window.XZ=window.XZ||{};(window.XZ.bank=window.XZ.bank||{})["内科学"]=[["1988-N1",27,"","",1988,1,"A","","下列哪一疾病的上腹痛可采取左侧卧位而缓解",[["A","消化性溃疡"],["B","钩虫病"],["C","慢性胃炎"],["D","胃黏膜脱垂症"],["E","十二指肠炎"]],"D","胃黏膜脱垂症（D对）是由于异常松弛的胃黏膜逆行突入食管或向前通过幽门管脱入十二指肠球部所致，临床上以后者多见，其上腹痛可采取左侧卧位而缓解。消化性溃疡（A错）、钩虫病（B错）、慢性胃炎（C错）及十二指肠炎（E错）均可以出现腹痛，但是与体位无关。","","N"],["1988-N2",35,"第一节 肝硬化","寄生虫感染",1988,2,"A","","下列哪一疾病的门脉高压最显著",[["A","血吸虫病性肝硬化"],["B","肝炎后肝硬化"],["C","酒精性肝硬化"],["D","原发性胆汁性肝硬化"],["E","原发性肝癌"]],"A","各种病因引起的肝硬化都会导致门脉高压，但是程度有所不同。血吸虫病时，由于虫卵直径过大，不能进入肝血窦，主要聚集在门静脉分支附近，成熟虫卵被肝内巨噬细胞吞噬后演变为成纤维细胞，纤维化常使门静脉灌注障碍，所导致的门脉高压最显著（A对）而肝细胞破坏较少，因此肝功能减退程度较轻。而肝炎后肝硬化（B错）、酒精性肝硬化（C错）、原发性胆汁性肝硬化（D错）、原发性肝癌（E错）均以肝细胞破坏更为显著，其导致门脉高压的主要原因为增生的纤维束及再生的肝细胞结节或癌细胞结节对肝血窦的挤压作用，因此肝功能减退与门静脉高压均较显著。","","N"],["1988-N3",35,"第一节 肝硬化","肝性脑病",1988,3,"A","","肝性脑昏迷病人治疗，为了取代脑部假性神经传导介质，应选用",[["A","多巴胺"],["B","谷氨酸钾"],["C","精氨酸盐"],["D","去甲肾上腺素"],["E","以上都不是"]],"E","多巴胺的前体左旋多巴可通过血脑屏障进入脑组织，经多巴胺脱羧酶产生多巴胺，纠正假性神经递质，但多巴胺（A错）和去甲肾上腺素（D错）不能通过血脑屏障，不能用于肝性脑昏迷病人治疗。谷氨酸钾（B错）、精氨酸盐（C错）为降低体内血氨的药物，并且其无法进入脑内形成正常神经递质而取代假性神经递质治疗肝性脑病。因此A、B、C、D都不能用于肝性脑昏迷的病人为取代脑部假性神经递质的治疗。支链氨基酸如亮氨酸、异亮氨酸、缬氨酸等氨基酸可用于肝性脑昏迷的病人为取代脑部假性神经递质的治疗。所以，应选“以上都不是”（E对）。","","N"],["1988-N4",30,"第一节 溃疡性结肠炎","溃疡性结肠炎病理",1988,4,"A","","溃疡性结肠炎病变多位于",[["A","回肠末段及升结肠"],["B","升结肠"],["C","降结肠"],["D","全结肠"],["E","直肠及乙状结肠"]],"E","溃疡性结肠炎病变多自直肠开始，逆行向近段发展，可累及全结肠甚至末端回肠，但主要位于直肠和乙状结肠（E对），极少数可扩展至全结肠（D错）。克罗恩病在整个胃肠道的任何部位均可发生，但好发于回肠末端及邻近结肠（十版内科学P392）（A错）。肠结核（十版内科学P383）病变主要位于回盲部，肠阿米巴疾病病变部位主要在盲肠、升结肠。","","N"],["1988-N5",16,"第三节 房性心律失常","非药物治疗",1988,5,"A","","心房扑动时，为转律首先选用",[["A","西地兰"],["B","电复律"],["C","奎尼丁"],["D","乙胺碘呋酮"],["E","心律平"]],"B","心房扑动简称房扑，是介于房速和房颤之间的快速性心律失常。健康者很少见，患者多伴有器质性心脏病。心脏电复律指在严重快速型心律失常时，用外加的高能量脉冲电流通过心脏，使全部或大部分心肌细胞在瞬间同时除极，造成心脏短暂的电活动停止，然后由最高自律性的起搏点（通常为窦房结）重新主导心脏节律的治疗过程。心房扑动时，通过直流电复律（B对）能迅速将房扑转复为窦性心律。西地兰（A错）属于洋地黄制剂，通过兴奋迷走神经，可以减慢房室传导、增加房室结中隐匿性传导、减慢心室率，是房颤合并心功能不全患者首选。奎尼丁（C错）属于ⅠA类抗心律失常药物，主要通过减慢动作电位0相上升速度，延长动作电位时程来抗心律失常，主要用于房性与室性期前收缩。乙胺碘呋酮（D错）即胺碘酮，属于Ⅲ类抗心律失常药物，主要通过阻断钾通道、延长复极，常用于各种室上性与室性快速性心律失常。心律平（E错）即普罗帕酮，属于ⅠC类抗心律失常药，通过减慢Vmax，减慢传导、轻微延长动作电位时程，用于各种室上性心动过速。","","N"],["1988-N6",18,"","",1988,6,"A","","哌唑嗪的降压的作用机理是",[["A","排钠增多，使血容量减少"],["B","同时阻滞α₁和α₂受体"],["C","使交感神经末梢去甲肾上腺素耗竭"],["D","阻滞α₁受体而不阻断α₂受体"],["E","干扰肾素-血管紧张素系统"]],"D","哌唑嗪为选择性突触后α₁受体阻滞药，能同时扩张阻力血管和容量血管。对突触前α₂受体无明显作用，故不引起反射性心动过速及肾素分泌增加等作用（D对）。排钠增多，使血容量减少是利尿剂的降压机制（A错）。同时阻滞α₁和α₂受体（B错）的是酚妥拉明。使交感神经末梢去甲肾上腺素耗竭是利舍平的降压机制（C错）。干扰肾素-血管紧张素系统是ACEI（E错）的降压机制。","","N"],["1988-N7",17,"","",1988,7,"A","","治疗自发性心绞痛最有效的药物是",[["A","硝苯地平"],["B","阿替洛尔"],["C","硝酸甘油酯含服"],["D","心得安"],["E","异搏定"]],"C","自发性心绞痛为心肌一过性缺血所致，其特点为疼痛发生与体力或脑力活动引起心肌需氧量增加无明显关系，与冠状动脉血流贮备量减少有关。药物治疗较重的发作，可使用作用快的硝酸酯制剂（C对），这类药物除扩张冠状动脉，降低其阻力，增加其血流量外，还通过对周围血管的扩张作用，减少静脉回心血量，降低心室容量、心腔内压、心排血量和血压，减低心脏前后负荷和心肌的需氧，从而缓解心绞痛。硝苯地平（A错）、阿替洛尔（B错）、心得安（普萘洛尔）（D错）、异搏定（维拉帕米）（E错）主要用于心绞痛缓解期的治疗。","","N"],["1988-N8",17,"第四节 急性冠状综合征","β受体拮抗剂",1988,8,"A","","下列哪种药物可能使变异型心绞痛加重",[["A","硝酸甘油"],["B","亚硝酸异戊酯"],["C","硝苯地平（心痛定）"],["D","心得安"],["E","异搏定"]],"D","心得安（即普萘洛尔）（D对）为非选择性β肾上腺素受体拮抗药，可阻滞能使冠状动脉扩张的β₂受体，或使α受体相对兴奋，诱发冠状动脉痉挛，使变异型心绞痛加重。变异型心绞痛也称血管痉挛性心绞痛，其发病机制为冠状动脉痉挛导致远端心肌缺血。硝酸甘油（A错）及亚硝酸异戊酯（B错）为硝酸酯类药物，在平滑肌细胞内经谷胱甘肽转移酶催化释放出NO，扩张痉挛的冠状动脉，减轻疼痛。硝苯地平（C错）为二氢吡啶类钙通道阻滞剂，异搏定（E错）为非二氢吡啶类钙通道阻滞剂维拉帕米，二者可降低平滑肌细胞内钙离子浓度，降低平滑肌张力，缓解血管痉挛。","","N"],["1988-N9",2,"第一节 支气管哮喘","重度至危重度(1)",1988,9,"A","","支气管哮喘持续状态很重要的治疗方法是",[["A","应用抗生素"],["B","应用祛痰药物"],["C","补液纠正失水"],["D","应用支气管扩张药物"],["E","应用肾上腺皮质激素"]],"C","支气管哮喘持续状态是指哮喘急性发作经合理使用支气管舒张剂和糖皮质激素等哮喘缓解药物治疗后，仍有严重或进行性呼吸困难者（九版儿科学P247），对其治疗，要注意因张口呼吸、出汗、进食减少等原因引起的脱水可导致痰液黏稠不易咳出、阻塞气道，所以补液纠正失水（C对）为支气管哮喘持续状态很重要的治疗方法。抗生素（A错）常在合并细菌感染时使用，不作为常规应用。祛痰药物（B错）是支气管哮喘持续状态的一般用药。支气管扩张药物（D错）和肾上腺皮质激素（E错）是该状态的基础用药，是最重要的一线用药。","","N"],["1988-N10",6,"第一节 肺结核","继发性肺结核",1988,10,"A","","浸润性肺结核主要是由于",[["A","原发病灶进展而来"],["B","血行播散扩散形成"],["C","隐性菌血症潜伏在肺内的结核菌重新繁殖"],["D","肺门淋巴结结核破溃形成"],["E","与病人接触引起的感染"]],"C","浸润性肺结核主要是由于隐性菌血症潜伏在肺内的结核杆菌（内源性感染）在人体免疫力降低时，重新繁殖所致（C对）。原发病灶进展（A错）主要形成原发综合征，原发病灶继续扩大和肺门淋巴结结核破溃（D错）可直接或经血流播散到邻近组织器官，发生结核病。血行播散扩散主要形成血行播散型肺结核（B错）。若接触者之前没有患过肺结核，与病人接触引起的感染为原发肺结核；若接触者之前患过肺结核，亦可因与病人接触而发生浸润型肺结核（外源性感染），但较少见（E错）。原发病灶进展（A错）、血行播散扩散（B错）、肺门淋巴结结核破溃（D错）也可形成浸润性肺结核，但均少见。","","N"],["1988-N11",10,"第三节 慢性肺源性心脏病","慢性肺源性心脏病诊断",1988,11,"A","","肺心病患者测血pH7.25，PaCO₂60mmHg，BE-10mEq/L，PaO₂50mmHg，诊断是",[["A","失代偿呼吸性酸中毒"],["B","代偿呼吸性酸中毒"],["C","代谢性碱中毒"],["D","呼酸合并代酸"],["E","正常"]],"D","患者pH7.25（正常值为7.35～7.45），低于正常值，为酸中毒（BE错）；PaCO₂60mmHg（正常值为35～45mmHg）高于正常值，说明有呼吸性酸中毒；BE（剩余碱）为-10mEq/L（正常值为-3～+3mmol/L）低于正常值，说明患者体内存在代谢性酸中毒（C错），所以患者为呼酸合并代酸（D对A错）。","","N"],["1988-N13",52,"第二节 急性白血病","ALL诱导缓解治疗",1988,13,"A","","对急性白血病进行缓解诱导治疗的目的是",[["A","完全杀灭白血病细胞"],["B","使体内白血病细胞减少到10¹²"],["C","使体内白血病细胞减少到10¹⁰"],["D","使体内白血病细胞减少到10⁹"],["E","以上都不是"]],"E","对急性白血病进行缓解诱导治疗的目的是使患者迅速获得完全缓解（CR），即白血病的症状和体征消失，外周血中性粒细胞绝对值≥1.0×10⁹/L，血小板≥100×10⁹/L，外周血中无白血病细胞；骨髓中原始粒Ⅰ型+Ⅱ型（原单+幼单或原淋+幼淋）≤5%，M₃型原粒+早幼粒≤5%，无Auer小体，故白血病细胞不需要完全被杀灭（E对A错），红细胞及巨核细胞系正常。","","N"],["1988-N15",59,"第一节 甲状腺功能亢进症","剂量与疗程",1988,15,"A","","甲状腺机能亢进症患者用硫脲类或咪唑类药物治疗后，症状好转，甲状腺较以前增大，下列哪项处理最适宜",[["A","加用心得安"],["B","停止用药"],["C","加用甲状腺片"],["D","加用碘剂"],["E","外科手术"]],"C","硫脲类是目前常用的抗甲状腺药物，通过抑制甲状腺过氧化物酶，进而抑制酪氨酸的碘化及耦联，减少甲状腺素的生物合成。使用硫脲类药物后患者出现甲状腺腺体增大是因为硫脲类使血清甲状腺素水平下降，反馈性增加促甲状腺激素分泌，进而引起腺体代偿性增加、腺体增大、充血等。此时应加用甲状腺片，负反馈抑制促甲状腺素的释放（C对）。患者目前病情稳定，无心率加快、心收缩力增强等交感神经激活症状，故无需加用心得安（A错）。硫脲类药物疗程中除非有较严重反应，一般不宜中断，并定期随访（B错）。碘剂仅用于术前准备与甲状腺危象治疗（D错）。患者目前病情稳定，无手术指征（E错）。","","N"],["1988-N16",33,"","",1988,16,"A","","能用以制备乙型肝炎疫苗的是",[["A","HbcAg"],["B","HbeAg"],["C","HbsAg"],["D","抗-HBe"],["E","抗-Hbe"]],"C","乙肝疫苗是利用重组DNA技术生产的。 含有乙肝表面抗原(HBsAg)基因的质粒被转染到普通的面包酵母菌，然后产生乙肝表面抗原（C对）。 然后收获和纯化HBsAg。 这种疫苗不能引起乙肝病毒感染，因为此过程不产生潜在的感染性病毒DNA或完整病毒颗粒。","","N"],["1988-N19",40,"第五节 肾病综合征","微小病变型肾病",1988,19,"A","","一个临床表现为“肾病综合征”的15岁病人，经4周足量强的松治疗后，症状明显改善，其肾脏病理表现最可能为",[["A","膜增生性肾小球肾炎"],["B","局灶性肾小球硬化"],["C","膜性肾病"],["D","肾小球囊壁层上皮增生新月体形成"],["E","光镜下所见肾小球基本正常"]],"E","15岁“肾病综合征”患者（青少年患者），4周足量强的松治疗症状明显改善（糖皮质激素敏感），考虑微小病变型肾病可能性大。微小病变型肾病是儿童最常见的一种肾小球疾病，多数病人对糖皮质激素治疗敏感，光镜下所见肾小球基本正常（E对），近曲小管上皮可见脂肪变性。膜增生性肾小球肾炎（A错）又称系膜毛细血管性肾小球肾炎，好发于青壮年，本病治疗困难，糖皮质激素及细胞毒药物治疗可能仅对部分儿童病例有效（十版内科学P482）。局灶性肾小球硬化（十版内科学P481）（B错）好发于青少年男性，约3/4患者伴有血尿，其五种亚型对激素反应不一，本病在我国仅占原发性肾病的5%～10%，所以不优先考虑。膜性肾病（C错）好发于中老年男性，约60%～70%早期患者经激素及细胞毒药物治疗后可达临床缓解。肾小球囊壁层上皮增生新月体形成（D错）为急进性肾小球肾炎的病理改变，多表现为肾炎综合征及早期少尿性急性肾衰竭，糖皮质激素主要对Ⅱ、Ⅲ型急进性肾小球肾炎有效，对Ⅰ型效果较差（十版内科学P478）。","","N"],["1988-N20",45,"第一节 慢性肾衰竭","营养治疗",1988,20,"A","","给尿毒症患者含必需氨基酸为主的低蛋白饮食，主要目的是",[["A","改善机体一般状况"],["B","辅助提高二氧化碳结合力，改善酸中毒"],["C","利用体内非蛋白氮合成蛋白质"],["D","改善肾小球的滤过功能，使尿毒症好转"],["E","以上都不是"]],"C","限制蛋白饮食是治疗的重要环节，能够减少含氮代谢产物生成，减轻症状及相关并发症，甚至可能延缓病情进展。必需氨基酸指人体不能合成或合成速度远不适应机体的需要，必需由食物蛋白供给；如有条件，在低蛋白饮食的基础上，以必需氨基酸为主，减少非必需氨基酸摄取量，而利用体内非蛋白氮合成蛋白质（C对），既可减少蛋白质摄取量，又可促进体内非蛋白氮的代谢，减少其在体内蓄积产生的危害。限制蛋白质饮食的主要目的是促进含氮代谢产物的代谢，减轻症状及相关并发症，而非改善机体一般状况（A错）。给予以必需氨基酸为主的低蛋白饮食并不能提高二氧化碳结合力也不能改善肾小球的滤过功能（BD错）。","","N"],["1988-N23",75,"","",1988,23,"A","","错觉对客观事物是",[["A","歪曲的知觉"],["B","错误的认识"],["C","判断的错误"],["D","虚幻的知觉"],["E","病态的信念"]],"A","知觉障碍包括错觉和幻觉。错觉是歪曲的知觉（A对），客观存在，是大脑在综合的时候出错了。幻觉是虚幻的知觉，客观不存在，是由大脑凭空产生的。","","N"],["1988-N24",75,"","",1988,24,"A","","神经衰弱与精神分裂症单纯最主要的鉴别点是",[["A","是否缓慢起病"],["B","有无头痛、头错、失眠工作率下降"],["C","起病有无因素"],["D","对疾病是否关心及积极要求治疗"],["E","有无家族精神病史"]],"E","略","","N"],["1988-N62",2,"第一节 支气管哮喘","动脉血气分析",1988,62,"A","","下列为患者动脉血样的血化分析结果，pH=7.46，PCO₂=27mmHg，PO₂=98mmHg，[HCO₃⁻]=23mmol/L，[Cl⁻]=110mEq/L，[Na⁺]=140mEq/L，[K⁺]=3.5mEq/L，最可能的情况是",[["A","呼吸性酸中毒"],["B","呼吸性碱中毒"],["C","代谢性（高氯性）酸中毒"],["D","代谢性（高乳酸性）酸中毒"],["E","代谢性（高酮性）酸中毒"]],"B","血气分析是临床上常用于判断机体是否存在酸碱平衡失调以及缺氧和缺氧程度等。根据患者血气分析：pH7.46（正常值为7.35～7.45），PCO₂27mmHg（正常值为35～45mmHg，大于50mmHg表示有抑制中枢危险），PO₂98mmHg（正常值为80～100mmHg，低于60mmHg表示有呼吸衰竭），[HCO₃⁻]23mmol/L（正常值为22～27mmol/L），[Cl⁻]110mmol/L（正常值为95～105mmol/L），[Na⁺]140mmol/L（正常值为137～147mmol/L），[K⁺]3.5mmol/L（正常值为3.5～5.3mmol/L）。患者pH 7.46大于正常值上限，为碱中毒，PCO₂ 27mmHg小于正常值下限，为呼吸性碱中毒，综合考虑为过度呼吸导致呼吸性碱中毒（B对）。","","N"],["1988-N63",36,"第一节 原发性肝癌","原发性肝癌诊断",1988,63,"A","","男，40岁，腹胀、纳差3个月，颈部有两个蜘蛛痣，肝肋下4cm，质硬，腹水中量。抽出淡红色腹水少许，比重1.013。诊断可能是",[["A","肝硬化"],["B","门静脉血栓形成"],["C","结核性腹膜炎"],["D","原发性肝癌"],["E","胰源性腹水"]],"D","患者中年男性，腹胀、纳差（消化吸收不良表现），颈部出现蜘蛛痣（肝功能减退表现），腹水中量（肝硬化失代偿期最突出的临床表现），以上均为肝硬化征象。又患者肝大，质硬（原发性肝癌肝脏呈进行性增大，质地坚硬），抽出血性腹水（肝癌侵犯肝包膜或向腹腔内破溃可引起血性腹水），故该患者可考虑为在失代偿期肝硬化基础上并发原发性肝癌（D对）。肝硬化（A错）出现肝功能减退及中量腹水时，多已进入失代偿期，肝脏缩小而不会肿大，且血性腹水少见。门静脉血栓形成（B错）为肝硬化失代偿期门静脉高压的较常见并发症，当其呈急性或亚急性发展时，可出现血性腹水，但其肝脏应该缩小，不会肿大。结核性腹膜炎（C错）可出现血性腹水，但不会出现蜘蛛痣及肝肿大。","","N"],["1988-N64",11,"第一节 胸腔积液","区别漏出液和渗出液",1988,64,"A","","胸腔积液患者，胸液检查：比重1.018，蛋白2.7g/dl，利凡他试验（+），红细胞200/mm³，白细胞300/mm³，淋巴细胞82%，细菌阴性，应首先考虑为",[["A","漏出性胸腔积液"],["B","血性胸腔积液"],["C","渗出性胸腔积液"],["D","乳糜性胸腔积液"],["E","化脓性胸腔积液"]],"C","渗出性胸腔积液常表现为比重＞1.018，蛋白含量＞30g/L，细胞总数＞500×10⁶/L，利凡他（Rivalta）试验（+）；漏出性胸腔积液常表现为比重＜1.015，蛋白含量＜25g/L，细胞总数＜100×10⁶/L，利凡他（Rivalta）试验（-）（参考九版诊断学P326-P327）。该患者胸水比重1.018，蛋白2.7g/dl（27g/L），利凡他试验阳性。根据患者的胸水检查结果，最可能的诊断为渗出性胸腔积液（C对A错）。血性胸腔积液（十版内科学P129）（B错）呈洗肉水样或静脉血样，红细胞超过5×10⁹/L，红细胞压积＞外周血压积50%以上；乳糜性胸水（十版内科学P129）（D错）呈乳状混浊，碱性，无臭味，苏丹Ⅲ染色呈红色，可见脂肪滴，镜检可见到少量淋巴细胞和红细胞，中性粒细胞罕见；化脓性胸水（十版内科学P131）（E错）时白细胞显著升高，以中性粒细胞为主，且细菌阳性。","","N"],["1988-N65",49,"第一节 再生障碍性贫血","AA诊断标准",1988,65,"A","","女，18岁，两个月来脸色苍白，月经过多，肝、脾未触及，血红蛋白70g/L，白细胞2.9×10⁹/L，血小板21×10⁹/L，分别在髂前及髂后上棘骨髓穿刺未取得骨髓，胸骨片显示骨髓增生尚活跃，粒、红二系成熟停滞于晚期，全片未见巨核细胞。诊断为",[["A","缺铁性贫血"],["B","原发性血小板减少性紫癜"],["C","急性白血病"],["D","再生障碍性贫血"],["E","脾功能亢进症"]],"D","该患者为青年女性，出现面色苍白（贫血表现），月经过多（出血表现）。查血常规：血红蛋白70g/L（成年女性正常值115～150g/L），白细胞2.9×10⁹/L（正常值3.5～9.5×10⁹/L），血小板21×10⁹/L（正常值125～350×10⁹/L）（外周血全血细胞减少）。查体：肝脾未大。骨髓穿刺：髂前上棘、髂后上棘穿刺未取得骨髓，胸骨片显示骨髓增生尚活跃，粒、红二系成熟停滞于晚期，全片未见巨核细胞（骨髓多部位增生减低）。符合再生障碍性贫血（D对）的诊断标准：1.骨髓多部位增生减低；2.外周血全血细胞减少；3.无肝脾肿大。缺铁性贫血（十版内科学P549）（A错）一般仅表现为外周血红细胞减少，不会出现全血细胞减少，骨髓增生活跃。原发性血小板减少性紫癜（十版内科学P622）（B错）骨髓巨核细胞数目增多或正常。急性白血病（十版内科学P577）（C错）表现为病态造血，异常白细胞显著增生，常有肝脾肿大。脾功能亢进（E错）患者常有脾肿大，与该患者不符。","","N"],["1988-N70",18,"第一节 原发性高血压","硝普钠",1988,70,"B","","直接作用于血管平滑肌降低前后负荷的药物是",[["A","硝普钠"],["B","苄胺唑啉"],["C","异丙基肾上腺素"],["D","多巴胺"],["E","间羟胺"]],"A","硝普钠（A对）对直接作用于血管平滑肌，同时扩张静脉和动脉，降低前、后负荷，迅速降低血压。苄胺唑啉（酚妥拉明）（B错）为α受体阻滞剂，可扩张皮肤和肌肉的小动脉，用于血管痉挛性疾病。异丙肾上腺素（C错）为β受体激动剂，对β₁和β₂受体均有较强大的激动作用，对α受体几无作用。主要作用于血管平滑肌β₂受体，使骨骼肌血管明显舒张，对肾、肠系膜血管舒张作用较弱，对冠状血管也有舒张作用，也有增加组织血流量的作用。多巴胺（D错）是β受体兴奋剂，小到中等剂量多巴胺可通过降低外周阻力，增加肾血流量。间羟胺（E错）主要作用是直接激动α受体，收缩血管，升压作用较去甲肾上腺素弱而持久。","","N"],["1988-N71",15,"第三节 急性心力衰竭","β受体兴奋剂",1988,71,"B","","收缩皮肤和肌肉的小动脉，扩张肾和内脏的小动脉的药物是",[["A","硝普钠"],["B","苄胺唑啉"],["C","异丙基肾上腺素"],["D","多巴胺"],["E","间羟胺"]],"D","多巴胺小剂量使用时，主要作用于多巴胺受体，使肾及肠系膜血管扩张，肾血流量及肾小球滤过率增加，尿量及钠排泄量增加；小到中等剂量，能直接激动β₁受体及间接促使去甲肾上腺素自储藏部位释放，对心肌产生正性肌力作用，使心肌收缩力及心搏量增加，冠脉血流及耗氧改善；大剂量时激动α受体，导致周围血管阻力增加，肾血管收缩，肾血流量及尿量反而减少。因此，多巴胺（D对）可收缩皮肤和肌肉的小动脉，扩张肾和内脏的小动脉。硝普钠（十版内科学P271）（A错）对动脉和静脉平滑肌均有直接扩张作用，血管扩张使心脏前、后负荷均减低，心排血量改善，故对心力衰竭有益。苄胺唑啉（酚妥拉明）（B错）为α受体阻滞剂，可扩张皮肤和肌肉的小动脉，用于血管痉挛性疾病。异丙肾上腺素（C错）为β受体激动剂，对β₁和β₂受体均有较强大的激动作用，对α受体几无作用。主要作用于血管平滑肌β₂受体，使骨骼肌血管明显舒张，对肾、肠系膜血管舒张作用较弱，对冠状血管也有舒张作用，也有增加组织血流量的作用。间羟胺（E错）主要作用是直接激动α受体，收缩血管，升压作用较去甲肾上腺素弱而持久。","","N"],["1988-N83",64,"","",1988,83,"B","","糖尿病",[["A","酸的酯化增强"],["B","血浆中与清蛋白结合的游离脂肪酸增多"],["C","禁食12小时后，血浆中有多量的乳糜徽粒"],["D","血浆高密度脂蛋白（HDL）减少"],["E","禁食12小时后，血浆胆固醇处于极高水平"]],"A","略","","N"],["1988-N88",37,"第一节 急性胰腺炎","急性胰腺炎临床表现",1988,88,"C","","可发生猝死",[["A","出血坏死型胰腺炎"],["B","隐性心肌梗死"],["C","两者都是"],["D","两者都不是"]],"C","出血坏死性胰腺炎（A对）临床表现为重症急性胰腺炎，重症急性胰腺炎由于炎症波及全身，可导致多器官损伤，当累及心脏时可引起猝死。隐性心肌梗死（B对）是心肌梗死的一种特殊类型，患者起病隐匿，平时健康状况和正常人一样，无任何症状，经尸检才明确其死因为心肌梗死。当出现心肌广泛坏死，心排血量急剧下降，或并发严重致死性心律失常，导致猝死。本题AB均对，正确答案为C。","","N"],["1988-N90",4,"第二节细菌性肺炎","肺炎链球菌肺炎临床表现",1988,90,"C","","肺炎球菌肺炎",[["A","起病急骤，寒战、高热"],["B","经治疗后肺部病变完全消退，肺组织恢复正常"],["C","两者都有"],["D","两者都无"]],"C","肺炎链球菌肺炎是由肺炎链球菌或称肺炎球菌所引起的肺炎，通常急骤起病，以高热、寒战、咳嗽、血痰及胸痛为特征（A对），肺炎球菌不产生毒素，不引起组织坏死或形成空洞，病变消散后肺泡内纤维蛋白完全吸收，肺组织多无结构破坏，不留纤维瘢痕（B对）。本题AB均对，正确答案为C。","","N"],["1988-N91",6,"第一节 肺结核","肺结核临床表现",1988,91,"C","","干酪性（结核性）肺炎",[["A","起病急骤，寒战、高热"],["B","经治疗后肺部病变完全消退，肺组织恢复正常"],["C","两者都有"],["D","两者都无"]],"A","干酪性肺炎又称结核性大叶性肺炎，属于继发性活动性肺结核，是一种急性严重的类型，多发生于虚弱而且受大量结核杆菌感染的人。病情发展快，症状十分严重，很快发生衰竭。大叶性干酪性肺炎多见于婴幼儿，小叶性者则多见于较大儿童。前者起病多较急，有高热和严重中毒症状（A对），后者可较缓，有长期低热和慢性中毒症状，多有咳嗽、咳痰甚至咯血。病程严重，预后不佳，如能及时积极进行抗结核药物治疗，多数病例可吸收好转，但肺部病变不能完全消退，肺组织最终钙化（B错）而治愈。","","N"],["1988-N98",28,"第一节 消化性溃疡","消化性溃疡药物治疗",1988,98,"X","","可用于十二指肠溃疡的药物是",[["A","西咪替丁"],["B","安定"],["C","前列腺素E₂"],["D","延缓释放型生胃酮"]],"AC","西咪替丁（A对）属于H₂受体拮抗剂，可抑制胃酸分泌，可用于治疗十二指肠溃疡。前列腺素E₂（C对）是黏膜保护剂，具有抑制胃酸分泌、增加胃十二指肠黏膜的黏液及碳酸氢盐分泌和增加黏膜血流等作用，同样可用于十二指肠溃疡的治疗。生胃酮（D错）能增加胃黏膜的黏液分泌，减少胃上皮细胞的脱落，能在胃黏膜细胞内抑制胃蛋白酶原，在胃内可与胃蛋白酶结合，抑制酶的活力约50%，从而保护溃疡面，促进组织再生和愈合，但是本药物副作用大，不可单独用于溃疡治疗，临床上已不常用。安定（B错）主要用于焦虑、镇静催眠，还可用于抗癫痫和抗惊厥，不用于治疗溃疡。","","N"],["1988-N99",29,"第二节 结核性腹膜炎","腹腔积液检查",1988,99,"A","","结核性腹膜炎腹水检查中，不正确的是",[["A","偶见乳糜样腹水"],["B","其比重一般超过1.016，蛋白含量在30g/L以上"],["C","合并肝硬化时其腹水性状接近漏出液"],["D","腹水浓缩多能找到结核杆菌"]],"D","结核性腹膜炎腹水是由于腹膜通透性增加所致，其性质为渗出液，多为草黄色，偶可见乳糜样腹水（A对）；比重＞1.018，蛋白定量＞30g/L（B对）；肝硬化时，肝脏蛋白质合成障碍导致低蛋白血症，且肝硬化一般腹水量很大，使腹水中蛋白含量减少，可接近于漏出液（C对）；腹水结核杆菌培养阳性率很低，腹水浓缩结核杆菌培养阳性率可增高，但腹水中多不能找到结核杆菌（D错，为本题正确答案）。","","N"],["1988-N101",16,"","",1988,101,"X","","无器质性心脏病的室上性心动过速发作时可以选用",[["A","升压药物"],["B","西地兰"],["C","心律平静注"],["D","美西律静注"]],"ABCD","无器质性心脏病的室上性心动过速发作时如果患者心功能与血压正常，可先尝试使用颈动脉窦按摩、Valsalva动作、将面部浸入冰水内等刺激迷走神经的方法使心动过速终止，如果未能达到满意效果应进行药物治疗。药物治疗首选腺苷，腺苷治疗无效的改用维拉帕米、地尔硫䓬等钙通道阻滞剂，疗效可达90%以上。西地兰（B对）等洋地黄药物与β受体拮抗剂可以有效终止心动过速。心律平（十版内科学P218）（C对）即普罗帕酮适用于各种类型室上性心动过速和室性心动过速，是一种广谱抗心律失常药物。美西律（十版内科学P218）（D对）适用于急、慢性室性快速性心律失常（特别是QT间期延长者）。升压药物（如去氧肾上腺素、甲氧明或间羟胺）（A对）用于室上性心动过速合并低血压者，在升高血压的同时可通过反射性兴奋迷走神经终止心动过速。","","N"],["1988-N102",21,"第四节 二尖瓣反流","二尖瓣反流临床表现",1988,102,"X","","风心病二尖瓣关闭不全时，可有",[["A","心尖区全收缩期杂音吸气时减弱"],["B","第三心音"],["C","心尖区第一心音减弱"],["D","肺动脉瓣第二心音分裂"]],"ABCD","吸气时胸腔内的负压增加，使得胸腔内大静脉扩张，返回右心的血流量增加，右心室充盈压增加，可将室间隔推向左心室，减少左室充盈。此外，吸气时肺血管床扩张，肺静脉血流量随之减少，左室充盈量进一步降低，导致收缩期反流减轻，故听诊心尖区收缩期杂音减弱（A对）。二尖瓣关闭不全出现严重反流者可在心尖区闻及第三心音（B对）和短暂的舒张期隆隆样杂音。心室舒张期过度充盈，使二尖瓣漂浮，以致在心室收缩期前二尖瓣位置较高，关闭时振幅较小，第一心音减弱（C对）。二尖瓣关闭不全时，左心室可前向及反向射血，因而射血时间变短，主动脉瓣关闭时间提前，出现S₂通常分裂（D对）。","","N"],["1988-N103",23,"第一节 感染性心内膜炎","择期手术",1988,103,"X","","亚急性感染性心内膜炎外科治疗的指征是",[["A","动脉导管未闭合并亚急性感染性心内膜炎抗生素治疗无效"],["B","主动脉瓣穿孔"],["C","真菌感染，药物不能控制"],["D","脓肿病灶，有待清除"]],"ABCD","亚急性感染性心内膜炎外科治疗主要适应证有：1.由瓣膜功能衰竭所致的心力衰竭；2.尽管积极抗生素治疗情况下，仍有持续败血症（A对）；3.再发栓塞。次要适应证：1.脓肿（D对）、假性动脉瘤以及1个（多个）瓣叶破裂或瘘（B对）引起异常交通的征象表明局部感染扩散（局部感染没有控制）时；2.不容易治愈（如真菌（C对）、布鲁菌和Q热病原体）或对心脏结构破坏力大的病原微生物感染时；3.抗生素治疗后仍病原不明；4.伴有心衰的左侧急性金黄色葡萄球菌性IE；5.血培养阴性，足够抗生素治疗，持续发热10天以上的再发。如果二尖瓣赘生物＞10mm或抗生素治疗下赘生物体积增大或赘生物位于二尖瓣闭合的边缘时应考虑尽早手术治疗。","","N"],["1988-N104",22,"第一节 急性心包炎","急性心包炎临床表现",1988,104,"X","","渗出性心包炎的表现有",[["A","超声心动图可见无回声区"],["B","伊瓦氏征（Ewart征）"],["C","心电图有电交替现象"],["D","交替脉"]],"ABC","超声心动图对诊断心包积液简单易行，迅速可靠。M型或二维超声心动图中均可见液性暗区（无回声区）以确定诊断（A对）。心包积液量大时可于左肩胛骨下出现叩浊音，听诊闻及支气管呼吸音，即心包积液征（Ewart征）（B对）。心包积液时可见肢体导联QRS低电压，大量渗液时可见P波、QRS波、T波电交替，常伴窦性心动过速（C对）。交替脉（D错）系节律规整而强弱交替的脉搏，一般认为系左室收缩力强弱交替所致，为左室心力衰竭的重要体征之一，常见于高血压性心脏病、急性心肌梗死和主动脉瓣关闭不全导致的心力衰竭等。","","N"],["1988-N105",19,"第六节 心肌炎","心肌炎病因",1988,105,"X","","引起病毒性心肌炎的病毒有",[["A","柯萨奇病毒"],["B","流感病毒"],["C","埃可病毒（ECHO）"],["D","腮腺炎病毒"]],"ABCD","病毒性心肌炎是指嗜心肌性病毒感染引起的心肌非特异性间质性炎症病变。引起心肌炎的常见病毒是柯萨奇病毒（A对），其次是埃可病毒（ECHO）（C对）和腺病毒，还有流感病毒（B对）、流行性腮腺炎病毒（D对）、风疹病毒、虫媒病毒、巨细胞病毒、肝炎病毒、HIV、脊髓灰质炎病毒和合胞病毒等30余种。","","N"],["1988-N106",4,"第二节细菌性肺炎","并发症的处理",1988,106,"X","","休克型肺炎的治疗原则",[["A","纠正休克、控制感染"],["B","糖皮质激素的应用"],["C","防止心、肺、肾功能不全"],["D","注意水、电解质平衡及纠正酸、碱紊乱"]],"ABCD","休克型肺炎是指伴有休克的一种重症肺炎，除有呼吸系统症状外，伴有低血压、外周循环衰竭、神志改变、尿闭等症状，查体有低血压和神志恍惚或淡漠、面色苍白、四肢厥冷、口唇或指端发绀、脉搏细速、冷汗等外周循环衰竭体征，肺部有肺炎相应的体征。治疗时应纠正休克、控制感染（A对），注意水、电解质平衡及纠正酸、碱紊乱（D对），应用糖皮质激素（B对）抗炎及增强机体应激能力，防止心、肺、肾功能不全（C对），注意防治并发症。","","N"],["1988-N107",13,"第三节 慢性呼吸衰竭","呼吸兴奋剂",1988,107,"X","","呼吸兴奋剂用于呼吸衰竭的作用有",[["A","降低机体耗氧量"],["B","提高肺泡通气量，促进CO₂排出"],["C","使氧离曲线左移"],["D","使病人暂时清醒有利于咳嗽排痰"]],"BD","呼吸兴奋剂通过刺激外周或中枢化学感受器兴奋呼吸中枢，使呼吸频率和潮气量增加，提高肺泡通气量，促进CO₂排出（B对）；呼吸兴奋剂通过增强呼吸运动、增加呼吸肌做功提高呼吸效率，增加肺泡通气量，故机体耗氧量增加（A错）；使氧解离曲线右移（C错），促进氧气释放，增加组织供氧，改善低氧血症；并使病人暂时清醒，有利于咳嗽排痰（D对）。","","N"],["1988-N108",1,"第一节 慢性支气管炎","慢性支气管炎急性加重期的治疗",1988,108,"X","","慢性支气管炎急性发作的治疗包括",[["A","控制感染"],["B","祛痰、止咳、平喘"],["C","气雾疗法"],["D","免疫治疗"]],"ABC","慢性支气管炎急性发作时会咳嗽咳痰，喘息或者气急，急性加重期的治疗主要是控制感染（A对），镇咳祛痰平喘（B对），气雾疗法通过吸入药物作用于气道或者全身可以很好地缓解急性发作的症状，应当使用（C对）。缓解期有反复呼吸道感染者可以使用免疫调节剂，而一般不适用于急性期控制症状（D错）。","","N"],["1988-N109",50,"第二节 遗传性球形红细胞增多症","遗传性球形红细胞增多症治疗",1988,109,"X","","溶血性贫血进行脾切除的适应证是",[["A","遗传性球形红细胞增多症"],["B","糖皮质激素治疗无效的原发性自身免疫性溶血性贫血"],["C","海洋性贫血溶血明显或脾肿大明显者"],["D","阵发性睡眠性血红蛋白尿"]],"ABC","血管外溶血性贫血，如遗传性球形红细胞增多症（A对）、温抗体型自身免疫性溶血性贫血（B对）、海洋性贫血（C对），红细胞在脾脏中被破坏，脾切除治疗有效，为脾切除的适应证。血管内溶血性贫血红细胞在血管内被破坏，脾切除无效，如阵发性睡眠性血红蛋白尿（十版内科学P567）（D错）。","","N"],["1988-N111",56,"第二节 原发免疫性血小板减少症","骨髓象",1988,111,"X","","无血小板生成的巨核细胞增多见于（单选）",[["A","再生障碍性贫血"],["B","慢性粒细胞白血病"],["C","急性单核细胞白血病"],["D","特发性血小板减少性紫癜"]],"D","特发性血小板减少性紫癜是多种机制共同参与的获得性自身免疫性疾病。其骨髓幼稚巨核细胞因免疫介导的作用而发育障碍，表现为巨核细胞体积变小，胞质颗粒减少，有血小板形成的成熟巨核细胞显著减少，而巨核细胞总数增多（D对）。再生障碍性贫血（十版内科学P555）（A错）是由不同病因和机制导致的骨髓造血功能衰竭症，巨核细胞减少。急性单核细胞白血病（C错）患者白血病细胞大量克隆性增殖，抑制巨核系的增生，导致巨核细胞减少。慢性粒细胞白血病（十版内科学P585）的慢性期巨核细胞正常或增多且无发育障碍，有血小板生成；急变期巨核细胞增生受抑制，巨核细胞减少（B错）。","","N"],["1988-N112",60,"第一节 库欣综合征","代谢障碍",1988,112,"X","","皮质醇增多症中的低血钾性碱中毒主要见于",[["A","肾上腺皮质癌"],["B","重症肾上腺皮质增生"],["C","异位ACTH综合征"],["D","肾上腺皮质腺瘤"]],"AC","皮质醇增多症中的低血钾性碱中毒主要见于肾上腺皮质癌（A对）和异位ACTH综合征（C对）。肾上腺皮质癌和异位ACTH综合征除了能自主分泌大量皮质醇，还分泌盐皮质激素，具有保水保钠排钾的作用，可引起明显的低钾血症，导致低钾性碱中毒。肾上腺皮质增生多由库欣病引起（也可由异位ACTH综合征引起），为ACTH依赖型库欣综合征，一般不会引起低血钾性碱中毒，重症肾上腺皮质增生（B错）可有低血钾性碱中毒，但也并不常见（P711表7-7-1中提到严重库欣病可有低血钾性碱中毒）。肾上腺皮质腺瘤（D错）自主分泌皮质醇的能力并没有肾上腺皮质癌强，很少引起重型库欣综合征，很少引起明显低血钾，一般不会引起低钾性碱中毒。注意：本题若问的是皮质醇增多症中的低血钾性碱中毒可见于，则答案为ABC。","","N"],["1988-N113",61,"第一节 糖尿病","微血管病变",1988,113,"X","","属于糖尿病微血管病变的是",[["A","肾小球硬化症"],["B","肾动脉硬化"],["C","视网膜微血管病"],["D","冠状动脉粥样硬化症"]],"AC","微血管病变是糖尿病的特异性并发症，其典型改变是微循环障碍和微血管基底膜增厚。糖尿病微血管病变主要表现在视网膜、肾、神经和心肌组织，其中以糖尿病肾病和视网膜微血管病变（C对）尤为重要。糖尿病肾病3种病理改变类型为结节性肾小球硬化型、弥漫性肾小球硬化型（A对）和渗出性病变。肾动脉硬化（B错）、冠状动脉粥样硬化症（D错）为动脉粥样硬化累及肾动脉、冠状动脉所致，均不属于糖尿病微血管病变。","","N"],["1988-N114",74,"","",1988,114,"X","","用普通显微镜检查涂片能确定诊断的病原体是",[["A","皮瘀点涂片查脑膜炎双球菌"],["B","粪便涂片查痢疾杆菌"],["C","粪便涂片查阿米巴原虫"],["D","咽拭子涂片查溶血性链球菌"]],"D","略","","N"],["1988-N120",14,"","",1988,120,"X","","处理抗精神病药物所致的持久性低血压宜选用",[["A","间羟胺"],["B","肾上腺素"],["C","去甲肾上腺素"],["D","麻黄素"]],"AB","略","","N"],["1988-N134",22,"第三节 缩窄性心包炎","缩窄性心包炎临床表现",1988,134,"X","","缩窄性心包炎的主要临床表现",[["A","肝脏肿大，腹水"],["B","心界不大或稍大"],["C","奇脉"],["D","多伴有心脏杂音或肺气肿"]],"ABC","缩窄性心包炎时心室舒张受限，导致腔静脉回流障碍，引起体循环淤血，导致肝脏肿大，腹水（A对）。缩窄性心包炎一般心界不大或稍大（B对），稍增大可能原因为心包增厚或合并少量心包积液。缩窄性心包炎时心室舒张受限，心室充盈降低。吸气时肺循环血容量增加，肺静脉回流进一步降低，左室射血量过低，产生奇脉（C对），但九版内科学P306认为奇脉不常见，故奇脉不是缩窄性心包炎的主要临床表现，C选项存在争议。缩窄性心包炎病变在心包，心脏结构大多无改变，一般不出现心脏杂音；缩窄性心包炎与肺气肿并无相关性（D错）。","","N"],["1989-N1",28,"第一节 消化性溃疡","幽门管溃疡",1989,1,"A","","关于幽门管溃疡的描述，正确的是",[["A","消化性溃疡的多见类型"],["B","有典型的节律性症状"],["C","不少为穿透性"],["D","甲氰咪胍治疗效果良好"],["E","病变发展较慢"]],"C","幽门管溃疡为特殊类型的消化性溃疡，并不多见（A错）；幽门管位于胃远端，与十二指肠交界，长约2cm，幽门管溃疡病理生理与十二指肠球部溃疡相近，胃酸一般增多，但常缺乏典型溃疡的周期性和节律性疼痛（B错），餐后上腹痛显著，对抑酸药（如西咪替丁又名甲氰咪胍）反应差（D错），容易出现呕吐或幽门梗阻，出血或穿孔等并发症（C对），且病变发展较快（E错）。","","N"],["1989-N2",29,"第一节 肠结核","肠结核影像学检查",1989,2,"A","","对肠结核的诊断有重要意义的检查方法是",[["A","大便及痰液皆找到抗酸杆菌"],["B","乙状结肠镜检查"],["C","X线钡餐检查"],["D","OT试验"],["E","血沉"]],"C","溃疡型肠结核在钡剂透视检查时，病变肠腔很难完全充盈，可呈激惹征象，即排空很快，充盈不佳，而病变上、下肠段钡剂充盈良好，又称为X线钡影跳跃征象，此为肠结核患者的特征X线征象，对肠结核的诊断有重要意义（C对）。大便及痰液中找到抗酸杆菌，可以诊断抗酸杆菌感染，但不能诊断肠结核（A错）。因回盲部具有丰富的淋巴组织，故为肠结核的好发部位，结肠镜检查及粘膜活检发现肉芽肿、干酪坏死或抗酸杆菌时，可以确诊。乙状结肠镜检查（B错）只能到达直肠和乙状结肠，不能到达回盲部，因此不能作为诊断肠结核的检查方法。溃疡型肠结核血沉多明显增快，可作为评估结核病活动程度的指标之一，但缺乏特异性，对肠结核的诊断意义不大（E错）。OT试验（结核菌素试验）有助于判断有无结核病感染，但是OT试验阳性仅表示已感染过结核杆菌或接种过卡介苗，不能诊断现阶段是否患病，对于阴性结果者，除表示未受结核感染外，尚应考虑以下几种情况：结核杆菌感染后未产生变态反应或是应用糖皮质激素等免疫抑制剂患者；百日咳、营养不良、麻疹等患者结核菌素反应可暂时消失；此外严重结核病对结核菌素无反应或仅有弱阳性（十版内科学P75）。因此OT试验对肠结核的诊断并无特异性（D错）。注意：虽X线钡餐检查对肠结核的诊断有重要意义，但诊断肠结核最有意义的检查是结肠镜检+活检。","","N"],["1989-N4",35,"第一节 肝硬化","腹腔积液",1989,4,"A","","在肝硬化腹水的治疗中下列哪项不宜采用",[["A","低盐饮食"],["B","滴注水解蛋白、血浆"],["C","联合应用利尿剂"],["D","自体腹水回输"],["E","反复大量放腹水"]],"E","肝硬化腹水的一般治疗有：1.限制钠和水的摄入（A对）；2.利尿剂：常联合使用保钾及排钾利尿剂（C对）；3.提高血浆胶体渗透压：对低蛋白血症患者，每周定期输注白蛋白或血浆（B对）。对于难治性腹水的治疗可选择下列方法：（1）大量放腹水加输注白蛋白；（2）自身腹水浓缩回输：将抽出腹水经浓缩处理后再经静脉输入，起到清除腹水，保留蛋白，增加有效血容量的作用（D对）；（3）经颈静脉肝内门腔分流术（TIPS）；（4）肝移植。肝硬化腹水的患者处于肝硬化失代偿期，如果反复大量放腹水容易导致有效循环血量进一步减少而诱发肝肾综合征；还易导致钾和血浆蛋白丢失过多，引起低钾性碱中毒和低蛋白血症而诱发肝性脑病。因此，肝硬化腹水患者不宜反复大量放腹水（E错，为本题正确答案）。","","N"],["1989-N5",35,"","",1989,5,"A","","肝性昏迷前驱期的主要临床表现是",[["A","定向力减退"],["B","计算力降低"],["C","精神错乱"],["D","腱反射亢进"],["E","轻度性格改变、行为失常"]],"E","肝性脑病的临床过程可分为5期：潜伏期、前驱期、昏迷前期、昏睡期、昏迷期。肝性昏迷前驱期临床表现不明显，主要表现为轻度性格改变和行为异常（E对）。计算力降低（B错）即智力测试有轻微异常，为肝性昏迷0期（潜伏期）的主要临床表现。定向力障碍（A错）、精神错乱（C错）和腱反射亢进（D错）于肝性昏迷2期才开始出现。","","N"],["1989-N6",15,"第二节 慢性心力衰竭","右心衰竭体征",1989,6,"A","","右心功能不全所致的心源性水肿主要由于",[["A","淋巴液回流受阻"],["B","血浆胶体渗透压降低"],["C","毛细血管静水压增高"],["D","毛细血管通透性增加"],["E","心源性肝硬化白蛋白合成减少"]],"C","右心衰竭可引起体循环静脉压增高，静脉回流受阻，使全身毛细血管后阻力增大，导致毛细血管有效流体静压（C对）增高，引起全身水肿（八版生理学P130）。淋巴液回流受阻（A错）引起的水肿可见于丝虫病。血浆胶体渗透压降低（B错）引起的水肿可见于肾病综合征。毛细血管通透性增加引起的水肿主要见于过敏时组织释放组胺引起（D错）。心源性肝硬化白蛋白合成减少（E错）也可引起血浆胶体渗透压降低而导致水肿，与右心功能不全无关。","","N"],["1989-N7",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄超声心动图",1989,7,"A","","以下哪项无创性检查能准确地反映主动脉瓣狭窄程度",[["A","心电图检查"],["B","心音图检查"],["C","心脏X线检查"],["D","二维超声心动图"],["E","心尖搏动图检查"]],"D","二维超声心动图是明确诊断和判定狭窄程度的重要方法。二维超声心动图（D对）有助于显示瓣叶数目、大小、增厚、钙化、活动度、瓣口大小和形状、瓣环大小等瓣膜结构，有助于确定狭窄的病因。心电图（A错）仅能反映心电活动的变化。心音图（B错）有助于确定心音或杂音发生的时间，区分易于混淆的声音，主要用于鉴别某些听诊杂音相似而病变迥异的心内疾病。心脏X线检查（C错）仅能反映心脏外形变化，对瓣膜病变有一定间接提示意义。心尖搏动图（E错）是在心尖部位记录心尖搏动引起的低频振动的曲线图形，可用于评判心脏的收缩及舒张功能。","","N"],["1989-N8",43,"","",1989,8,"A","","确诊先天性肾动脉狭窄最有价值的是",[["A","病人年轻"],["B","起病急骤、血压增高显著"],["C","患侧肾区血管杂音"],["D","肾动脉造影"],["E","放射性核素肾图"]],"D","肾动脉造影（D对）能准确显示肾动脉狭窄部位、范围、程度及侧支循环形成情况，是诊断肾动脉狭窄的“金标准”，为最有价值的检查手段。患侧肾区血管杂音（C错）可提示肾血管血流动力学异常，但并不能明确出现异常的部位、范围、程度及侧支循环形成情况。病人年轻（A错）、起病急骤、血压增高显著（B错）于疾病诊断无特异性。放射性核素肾图（E错）指静脉注射由肾小球滤过或肾小管上皮细胞分泌而不被再吸收的放射性示踪剂，在体外应用肾图仪连续记录双肾的时间-放射性活度曲线，可用于了解肾血流量、肾脏排泌功能、肾内有无尿流梗阻、肾脏的形态和位置及无功能区等，并不能确诊肾动脉狭窄。","","N"],["1989-N9",17,"第四节 急性冠状综合征","吗啡或哌替啶",1989,9,"A","","缓解急性心肌梗死剧烈疼痛效果最好的药物是",[["A","硝酸甘油"],["B","二硝酸异山梨醇"],["C","罂粟碱"],["D","吗啡"],["E","可待因"]],"D","吗啡通过模拟内源性抗痛物质脑啡肽的作用，激动中枢神经阿片受体而产生强大的镇痛作用，用于血压正常的心肌梗死患者，有镇静和减轻心脏负荷的作用，能够缓解恐惧情绪（D对）。罂粟碱（C错）及可待因（E错）为弱阿片类镇痛药，其效果较吗啡差。硝酸甘油（A错）及二硝酸异山梨醇（B错）为硝酸酯类药物，可扩张冠脉，增加冠脉血流缓解疼痛，但止痛效果仍不如吗啡。","","N"],["1989-N10",19,"第一节 肥厚型心肌病","β受体拮抗剂",1989,10,"A","","肥厚型梗阻性心肌病患者，活动后出现心前区痛、头晕、最适宜的治疗药物是",[["A","硝酸甘油"],["B","罂粟碱"],["C","安定"],["D","心得安"],["E","去痛片"]],"D","本病的治疗旨在改善症状、减少合并症和预防猝死，首选药物为β受体拮抗剂及钙通道阻滞剂。心得安（D对）即普萘洛尔，为β受体阻滞剂，可减慢心率并降低心肌收缩力，使舒张期充盈时间延长，室壁张力降低，改善胸痛及劳力性呼吸困难，并具有抗心律失常作用。使用硝酸甘油（A错）可使肥厚型梗阻性心肌病患者心输出量进一步减少，加剧临床症状。患者心前区疼痛由心肌缺血引起，头晕由心输出量不足引起的脑缺血所致。罂粟碱（B错）为阿片类镇痛药，安定（C错）为苯二氮䓬类镇静药物，去痛片（E错）主要成分为NSAIDs类抗炎药，三者均不能针对病因治疗，效果欠佳。","","N"],["1989-N11",22,"第一节 急性心包炎","急性心包炎诊断",1989,11,"A","","诊断急性纤维蛋白性心包炎最具特征性的是",[["A","心前区疼痛"],["B","心包摩擦音"],["C","心浊音界向两边扩大"],["D","心泵搏动减弱或消失"],["E","心音遥远"]],"B","急性心包炎为心包脏层和壁层的急性纤维蛋白性炎症，这两层心包膜因炎症而变得粗糙，在心脏活动时相互摩擦而产生一种抓刮样粗糙声音，称为心包摩擦音。其是诊断急性纤维蛋白性心包炎的特异性体征（B对）。急性纤维蛋白性心包炎可有心前区疼痛（A错），但无特异性。心浊音界向两边扩大（C错）、心泵搏动减弱或消失（D错）、心音遥远（E错）为大量心包积液时出现的体征。","","N"],["1989-N12",2,"第一节 支气管哮喘","神经调节机制",1989,12,"A","","能使支气管扩张的生物活性物质有",[["A","前列腺素F₂"],["B","前列腺素E₂"],["C","组织胺"],["D","缓激肽"],["E","慢反应物质"]],"B","细支气管平滑肌受副交感神经和交感神经双重支配。副交感神经兴奋时释放ACh。ACh作用于平滑肌细胞膜上的M受体，导致平滑肌收缩，使气管口径缩小、气流阻力增大。前列腺素E₂可使血管平滑肌和支气管平滑肌舒张，从而使血管和支气管扩张（B对）。细支气管交感神经支配较少，但交感神经兴奋导致肾上腺髓质释放肾上腺素，经血液循环作用于细支气管平滑肌β受体（以β₂受体为主），导致平滑肌舒张，使气管口径扩大、气流阻力减小。肺组织本身释放的某些物质，例如组织胺（C错）、慢反应物质、内皮素、前列腺素F₂（A错）等，可导致细支气管平滑肌强烈收缩。慢反应物质是速发型过敏反应时肺组织释放的化学介质，其作用主要是使气管和支气管平滑肌收缩（E错）。","","N"],["1989-N13",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病诊断",1989,13,"A","","对阻塞性肺气肿的诊断，最有价值的是",[["A","PaO₂＜正常"],["B","潮气量低于正常"],["C","肺活量降低"],["D","残气量/肺总量＞40%"],["E","PaCO₂＞正常"]],"D","阻塞性肺气肿的病理变化为肺部终末细支气管远端气腔出现异常持久的扩张，伴有肺泡壁和细支气管的破坏（十版内科学P26），肺组织弹性日益减退，肺泡持续扩大，回缩障碍，则残气量及残气量占肺总量的百分比增加，所以临床上把残气量/肺总量＞40%（D对）作为诊断肺气肿最有价值的指标。潮气量低于正常（B错）及肺活量降低（C错）也可见于支扩、支气管哮喘等多种疾病，对诊断阻塞性肺气肿的特异性不高，故其不是诊断阻塞性肺气肿最有价值的指标。PaO₂＜正常（A错）、PaCO₂＞正常（E错）可见于COPD、支气管哮喘及肺心病等多种疾病，对诊断阻塞性肺气肿的特异性不高，故其不是诊断阻塞性肺气肿最有价值的指标。","","N"],["1989-N14",7,"第一节 肺癌","肺癌的放射治疗",1989,14,"A","","肺癌的放射治疗正确的是",[["A","未分化癌不需放射"],["B","放射治疗不能缓解阻塞症状、骨转移的剧痛及脑转移的颅内高压症状"],["C","对有全身衰竭、严重脏器功能损害者均可适用放射治疗"],["D","近年来多采用放疗手术相结合的治疗方法"],["E","放射治疗不能改变肺癌的自然规律，对任何病人都不能根治"]],"D","未分化癌对于放疗敏感度很高，所以未分化癌患者首选放射治疗（A错）。放射疗法可使肿块减小，从而可缓解阻塞症状、骨转移的剧痛及脑转移的颅内高压症状（B错）。由于放射治疗对其他器官辐射较大，损伤较重，可加重病人病情，所以全身衰竭、严重脏器功能损害的患者应慎用（C错）。放射治疗可以改变肺癌的自然规律，对于早期非小细胞肺癌可以根治（E错）。近年来多采用放疗手术相结合的治疗方法（D对），因放疗可以杀灭手术后可能残留的癌细胞，以此提高治愈率和术后生存率，也可以使肿块缩小，增加手术切除的机会，提高患者治愈率。","","N"],["1989-N15",10,"第三节 慢性肺源性心脏病","酸碱失衡及电解质紊乱",1989,15,"A","","肺心病患者经综合治疗后，呼衰、心衰均好转，血气示：pH=7.52，PCO₂=55mmHg，BE=+20MeQ/L，K⁺=3.0MeQ/L，Cl⁻=68MeQ/L，治疗应采用",[["A","THAM"],["B","4%碳酸氢钠"],["C","醋氮磺胺"],["D","氯化钾"],["E","尼可刹米"]],"D","pH=7.52（正常值为7.35～7.45），PCO₂=55mmHg（正常值为33～46mmHg），BE=+20MeQ/L（正常值为-3～+3mmol/L），K⁺=3.0MeQ/L（正常值为3.5～5.3mmol/L），Cl⁻=68MeQ/L（96～106mmol/L），可以推断患者存在呼吸性酸中毒并低钾、低氯性碱中毒，治疗应采用氯化钾（D对），不可以用碳酸氢钠（B错）。THAM（三羟甲基氨基甲烷）（A错）主要用来限制钠的含量；醋氮磺胺主要用于心脏水肿（C错）；尼可刹米为呼吸兴奋剂，一般用于中枢性的、以通气障碍为主的呼吸障碍，用之前要确保气道通畅，慢性肺心病患者多合并慢阻肺，常存在阻塞性通气功能障碍，故不宜使用（E错）。","","N"],["1989-N16",10,"第三节 慢性肺源性心脏病","慢性肺源性心脏病诊断",1989,16,"A","","肺心病患者测血pH7.25，PaCO₂60mmHg，BE-10mEq/L，PaO₂50mmHg，诊断是",[["A","失代偿呼吸性酸中毒"],["B","代偿呼吸性酸中毒"],["C","代谢性碱中毒"],["D","呼酸合并代酸"],["E","正常"]],"D","患者pH7.25（正常值为7.35～7.45），低于正常值，为酸中毒（BE错）；PaCO₂60mmHg（正常值为33～46mmHg）高于正常值，说明有呼吸性酸中毒；BE（剩余碱）为-10mEq/L（正常值为-3～+3mmol/L）低于正常值，说明患者体内存在代谢性酸中毒（C错），所以患者为呼酸合并代酸（D对A错）。","","N"],["1989-N17",44,"第一节 急性肾损伤","肾脏替代治疗",1989,17,"A","","急进性肾炎持续少尿伴高钾血症时的首选治疗措施是",[["A","肾移植"],["B","大剂量维生素C静脉滴注"],["C","绝对卧床"],["D","血液透析"],["E","预防感染"]],"D","急进性肾炎少尿可导致代谢废物及尿毒症毒素淤积，高钾血症容易导致严重心律失常，可威胁患者生命，治疗首选血液透析（D对）。肾移植（A错）要在病情静止半年，特别是Ⅰ型患者血中抗GBM抗体须转阴后半年进行（P468），非首选。大剂量维生素C静脉滴注（B错）在治疗克山病，治疗精神性疾病方面有应用。卧床休息（C错）不能达到治疗目的，因高血钾会导致心脏骤停，要紧急处理。预防感染（E错）不是急进性肾炎的治疗方法。","","N"],["1989-N18",40,"第一节 肾小球疾病概述","蛋白尿",1989,18,"A","","选择性蛋白尿特点为",[["A","24小时尿蛋白少于150mg"],["B","运动后出现一过性蛋白尿"],["C","每日尿蛋白超过3.5g"],["D","多为白蛋白或更小分子的蛋白质"],["E","多为球蛋白"]],"D","肾小球病变较轻时，只有中、小分子量的蛋白质（如白蛋白或更小分子的蛋白质）（D对）从尿中排出，此种蛋白尿称为选择性蛋白尿。肾小球病变较重时，尿中可出现包括球蛋白在内的（E错）大分子蛋白质，称为非选择性蛋白尿。尿蛋白定性试验阳性或尿蛋白定量超过150mg/d，称为蛋白尿（十版内科学P468），24小时尿蛋白少于150mg（A错）不能诊断为蛋白尿。在剧烈运动（B错）、发热、精神紧张等各种综合因素影响下出现的一过性蛋白尿为功能性蛋白尿（八版内科学P460）。每日尿蛋白超过3.5g（C错）为肾病综合征的诊断标准（十版内科学P480），而不是选择性蛋白尿的特点（并且肾病综合征多呈现非选择性蛋白尿）。","","N"],["1989-N19",40,"第一节 肾小球疾病概述","肾小球临床表现",1989,19,"A","","肾小球肾病的主要临床特点是",[["A","肾功能减退"],["B","血尿"],["C","高血压"],["D","尿中纤维蛋白降解产物增高"],["E","以上都不是"]],"E","原题中肾小球肾病定义不明确。若为肾病综合征答案为E。若为肾炎综合征答案为C。肾病综合征四联征为：大量蛋白尿，低蛋白血症，明显水肿和（或）高脂血症。肾炎综合征四联征为：血尿、蛋白尿、水肿和高血压。","","N"],["1989-N20",41,"第一节 尿路感染","慢性肾盂肾炎",1989,20,"A","","关于慢性肾盂肾炎的临床表现，下列哪项是错误的",[["A","可无全身症状"],["B","尿路刺激征可不典型"],["C","长期肾小球滤过功能损害往往较肾小管功能损害为重"],["D","可有高血压"],["E","轻度水肿"]],"C","慢性肾盂肾炎早期病变在肾盂，可累及邻近肾髓质中的肾小管，早期以肾小管功能受损为主，可出现肾小管萎缩及肾间质淋巴-单核细胞浸润等慢性炎症表现（十版内科学P500），晚期可出现肾小球硬化，导致肾小球滤过功能受损，因此患者肾小管功能损害往往较肾小球滤过功能损害为重（C错，为本题正确答案）。慢性肾盂肾炎除急性发作期外，可无全身症状（A对），尿路刺激征亦不典型（B对）。慢性肾盂肾炎可使肾全积缩小，肾小管萎缩，晚期肾小球硬化，甚至发展为肾衰竭，从而引起肾性高血压（D对）。另外，慢性肾盂性肾炎损伤肾功能，受水钠潴留以及肾素-醛固酮系统的影响，肾脏损伤利尿的激素分泌减少，因此会出现轻度水肿（E对）。","","N"],["1989-N21",45,"第一节 慢性肾衰竭","CKD的发病机制",1989,21,"A","","尿毒症发病机制中，“健存”肾单位学说的内容是",[["A","全部肾小球受损害，仅肾小管健存"],["B","肾脏病时，全部肾单位同时普遍蒙受损害"],["C","一批肾单位受损害坏死后，又重新再生一批肾单位，以取得代偿"],["D","一批肾单位受损害坏死后，剩余的正常肾单位起代偿作用"],["E","以上都不是"]],"D","在慢性肾衰竭疾病的发病机制中，一批肾单位受损害坏死后，健存的肾单位起代偿作用（D对），出现高灌注、高滤过、高代谢状态，从而导致肾小球硬化和残余肾单位的进一步丢失，如此恶性循环。","","N"],["1989-N23",47,"第一节 缺铁性贫血","缺铁性贫血诊断",1989,23,"A","","缺铁性贫血诊断的最可靠依据是",[["A","小细胞性贫血"],["B","小细胞低色素性贫血"],["C","骨髓增生性贫血"],["D","血红蛋白及血清铁均减少"],["E","血红蛋白及骨髓贮存铁均减少"]],"E","缺铁性贫血病程发展的三个阶段：贮存铁耗尽→红细胞内铁缺乏→缺铁性贫血。1.贮存铁耗尽（ID）：①血清铁蛋白减少；②骨髓铁染色显示骨髓小粒可染铁消失，铁粒幼细胞减少；③血红蛋白及血清铁等指标尚正常。2.红细胞内缺铁（IDE）：①ID的①+②；②转铁蛋白饱和度降低；③游离原卟啉增多；④血红蛋白尚正常。3.缺铁性贫血（IDA）：①IDE的①+②+③；②小细胞低色素性贫血：血红蛋白降低；MCV＜80fl，MCH＜27pg，MCHC＜32%（十版内科学P551）。由此可知血红蛋白减少为贫血最可靠的依据；骨髓贮存铁减少为缺铁最可靠的依据，故血红蛋白及骨髓贮存铁均减少为缺铁性贫血诊断最可靠依据（E对）。血清铁减少见于红细胞内铁缺乏阶段，相对于以上组合不是最可靠的依据（D错）。小细胞低色素性贫血（十版内科学P544）（AB错）可见于缺铁性贫血、铁粒幼细胞性贫血，珠蛋白生成障碍性贫血等，不具有特异性。骨髓增生性贫血（十版内科学P572）（C错）是骨髓异常增生导致原位溶血引起的溶血性贫血，不是缺铁性贫血。","","N"],["1989-N24",52,"第二节 急性白血病","口腔和皮肤",1989,24,"A","","白血病发生齿龈肿胀以哪一类型为最多见",[["A","急性淋巴细胞型"],["B","急性粒细胞型"],["C","急性单核细胞型"],["D","急性红血病"],["E","慢性粒细胞型"]],"C","白血病分为急性白血病（AL）和慢性白血病（CL），根据主要受累的细胞系列可将AL分为急性淋巴细胞白血病（ALL）和急性髓系白血病（AML）。其中AML又分为M₀（急性髓细胞白血病微分化型）、M₁（急性粒细胞白血病未分化型）、M₂（急性粒细胞白血病部分分化型）、M₃（急性早幼粒细胞白血病）、M₄（急性粒-单核细胞白血病）、M₅（急性单核细胞白血病）、M₆（红白血病）和M₇（急性巨核细胞白血病）。CL则分为慢性髓系白血病（CML）、慢性淋巴细胞白血病（CLL）及少见类型的白血病。M₄（急性粒-单核细胞白血病）和M₅（急性单核细胞白血病）（C对）最易发生齿龈肿胀、皮肤蓝灰色斑丘疹等。急性淋巴细胞型（十版内科学P579）（A错）最常发生淋巴结肿大、中枢神经系统白血病和睾丸白血病。","","N"],["1989-N25",49,"第一节 再生障碍性贫血","AA骨髓象",1989,25,"A","","鉴别再生障碍性贫血与白细胞不增多性白血病最重要的检查是",[["A","血小板计数"],["B","周围血找幼稚白细胞"],["C","周围血找幼红细胞"],["D","网织红细胞计数"],["E","骨髓检查"]],"E","再生障碍性贫血通常指原发性骨髓造血功能衰竭症，骨髓象示多部位骨髓增生减低；白细胞不增多性白血病是一类造血干细胞的恶性克隆性疾病，骨髓象示有核细胞显著增生，以原始细胞为主。故骨髓检查（E对）为鉴别两者最重要的检查。两者血小板计数（A错）、网织红细胞计数（D错）均降低，不具有鉴别意义。再生障碍性贫血骨髓增生减低，血片一般无幼稚细胞；白血病血片分类检查可见数量不等的原始和幼稚细胞，但白细胞不增多型病例血片上很难找到幼稚细胞。故周围血找幼稚白细胞（B错）、幼红细胞（C错）不具有鉴别意义。","","N"],["1989-N27",59,"第一节 甲状腺功能亢进症","高代谢症群",1989,27,"A","","不易出现高脂血症的疾病是",[["A","糖尿病"],["B","肾病综合征"],["C","阻塞性黄疸"],["D","甲状腺功能亢进"],["E","甲状腺功能减退"]],"D","高脂血症是指各种原因导致的血浆中胆固醇和（或）甘油三酯水平升高的疾病。甲状腺功能亢进时，甲状腺素分泌增多，脂肪分解与氧化加速，胆固醇合成、转化及排出均加速，但胆固醇分解速度增加更明显，常导致血中总胆固醇降低（D对）。相反，甲状腺功能减退时，以上作用均减弱，血中总胆固醇升高（E错）。糖尿病致胰岛素缺乏时，可抑制脂蛋白酯酶的活性，使CM（乳糜微粒）在血浆中聚集，导致血浆内TG（甘油三脂）升高，引起高脂血症（A错）。肾病综合征患者，可以引起VLDL（极低密度脂蛋白）和LDL（低密度脂蛋白）合成增加，同时可伴有脂蛋白分解减慢，肾病综合征时胆固醇与TG（甘油三脂）均升高（B错）。阻塞性黄疸时，胆道梗阻，使胆酸、胆固醇排泄障碍，引起游离胆固醇和甘油三酯升高，磷酸降低（C错）。","","N"],["1989-N28",59,"第一节 甲状腺功能亢进症","甲亢¹³¹I治疗适应证和禁忌证",1989,28,"A","","¹³¹碘治疗甲亢，哪一项是不适宜的",[["A","抗甲状腺药物治疗无效者"],["B","甲亢手术后复发"],["C","甲亢合并妊娠"],["D","年龄30岁以上，病情中等度严重者"],["E","单个结节伴甲状腺功能亢进者"]],"C","甲亢合并妊娠是¹³¹I治疗的禁忌证（C对），因为¹³¹I治疗会影响胎儿的生长发育。¹³¹I治疗适应证：①对ATD过敏或ATD治疗后复发（A错）；②手术治疗后复发（B错）；③甲状腺肿大中度以上（D错）；④浸润性突眼。","","N"],["1989-N29",61,"第一节 糖尿病","糖尿病肾脏病",1989,29,"A","","糖尿病毛细血管间肾小球硬化症的临床上尿液变化的主要特点是",[["A","尿糖较前增多"],["B","大量血尿"],["C","尿中有大量白细胞和管型"],["D","持续性蛋白尿"],["E","出现酮尿"]],"D","糖尿病肾病可分为五期，各期尿液变化特点分别为：Ⅰ期（糖尿病初期）尿白蛋白阴性；Ⅱ期（临床前期）尿白蛋白排泄率多正常，可间歇性增高；Ⅲ期（早期糖尿病肾病期）出现持续微量白蛋白尿；Ⅳ期（临床糖尿病肾病期）为持续性白蛋白尿；Ⅴ期（尿毒症期）多数肾单位闭锁，尿白蛋白排泄率降低，尿白蛋白可呈阴性。毛细血管间肾小球硬化为糖尿病Ⅳ期的病理特点，此期尿液变化的主要特点为持续性白蛋白尿（D对）。糖尿病肾病的特征性改变为白蛋白尿，虽尿糖较前增多（A错）、出现酮尿（E错）也可出现，但不为主要特点。糖尿病肾病一般无大量血尿（B错）、无大量白细胞和管型尿（C错）。","","N"],["1989-N70",40,"第二节 急性肾小球肾炎","急性肾小球肾炎病理表现",1989,70,"A","","急性链球菌感染后肾小球肾炎属于",[["A","急性弥漫性增生性肾小球肾炎"],["B","新月体性肾小球肾炎"],["C","膜性肾小球肾炎"],["D","膜性增生性肾小球肾炎"],["E","轻微病变性肾小球肾炎"]],"A","链球菌感染后，其胞质成分（内链素）或分泌蛋白（外毒素B及其酶原前体）可诱发免疫反应通过循环免疫复合物沉积于肾小球致病，或种植于肾小球的抗原与循环中的特异抗体相结合形成原位免疫复合物，激活自身免疫反应及补体系统，导致肾小球毛细血管内皮细胞及系膜细胞增生，并可吸引中性粒细胞及单核细胞浸润，导致急性弥漫性增生性肾小球肾炎（A对）。新月体性肾小球肾炎（B错）见于急进型肾小球肾炎，少数可有链球菌感染前驱史，但感染与新月体性肾小球肾炎的关系尚未明确（十版内科学P477）。膜性肾小球肾炎（C错）、膜性增生性肾小球肾炎（D错）、轻微病变性肾小球肾炎（E错）为原发性肾病综合征的病理类型（十版内科学P481-P483），其发病机制未明确。","","N"],["1989-N71",35,"","",1989,71,"A","","男，66岁，昏迷患者，病历不详。巩膜轻度黄染。瞳孔等大，肌张力及腱反射亢进。无偏瘫，血糖100mg/dl，血尿素氮20mg/dl，血清白蛋白2.0g/dl，球蛋白3.0g/dl。最可能的是",[["A","肝性昏迷"],["B","糖尿病昏迷"],["C","尿毒症昏迷"],["D","安眠药中毒"],["E","脑血管意外"]],"A","本例患者巩膜轻度黄染，血清白蛋白降低（正常值：40～50g/L），白/球比降低（正常值：1.5～2.5）（九版诊断学P352），二者均提示肝功能减退，且有肌张力和腱反射亢进，故最可能的是肝性昏迷（A对）。糖尿病昏迷（B错）的血糖浓度在600mg/dl以上，且无巩膜黄染。尿毒症昏迷（C错）的血尿素氮浓度在60mg/dl以上，一般也无巩膜黄染。安眠药中毒（D错）一般无巩膜黄染及血清蛋白异常。脑血管意外（E错）的患者多为突发，会出现偏瘫，神经系统检查可出现阳性体征，血清白蛋白与球蛋白一般正常。","","N"],["1989-N72",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄诊断",1989,72,"A","","30岁，男性，常感疲乏无力，劳累后感胸骨后疼痛，主动脉瓣区喷射性粗糙的收缩杂音，主动脉瓣区第二心音减弱，脉搏细弱，X线检查有左心室肥厚及升主动脉扩张，可能的诊断是",[["A","冠心病心绞痛"],["B","肥厚型梗阻性原发性心肌病"],["C","主动脉瓣狭窄"],["D","主动脉瓣关闭不全"],["E","高血压性心脏病"]],"C","年轻男性患者，劳累后胸骨疼痛，主动脉瓣区收缩期喷射样粗糙杂音（主狭的典型心脏杂音），主动脉瓣区第二心音减弱，脉搏细弱（左室射血量减少），X线示左心室肥厚及升主动脉扩张（主动脉瓣狭窄常见X线表现），诊断考虑主动脉瓣狭窄（C对）。冠心病心绞痛（A错）发作时杂音多位于心尖部，且不会出现升主动脉扩张。肥厚型梗阻性原发性心肌病（B错）典型杂音为胸骨左缘3～4肋间粗糙的喷射样收缩期杂音。主动脉关闭不全的杂音为与第二心音同时开始的高调叹气样舒张早期杂音（D错）。高血压性心脏病（E错）主动脉瓣区第二心音增强，脉搏一般有力。","","N"],["1989-N73",11,"第一节 胸腔积液","区别漏出液和渗出液",1989,73,"A","","胸腔积液患者，胸液检查：比重1.018，蛋白2.7g/dl，利凡他试验（+），红细胞200/mm³，白细胞300/mm³，淋巴细胞82%，细菌阴性，应首先考虑为",[["A","漏出性胸腔积液"],["B","血性胸腔积液"],["C","渗出性胸腔积液"],["D","乳糜性胸腔积液"],["E","化脓性胸腔积液"]],"C","渗出性胸腔积液常表现为比重＞1.018，蛋白含量＞30g/L，白细胞＞500×10⁶/L，利凡他（Rivalta）试验（+）。该患者胸水比重1.018，蛋白2.7g/dl，利凡他试验阳性，根据患者的胸水检查结果，最可能的诊断为渗出性胸腔积液（C对A错）。血性胸腔积液（十版内科学P129）（B错）呈洗肉水样或静脉血样，红细胞超过5×10⁹/L，红细胞压积＞外周血压积50%以上；乳糜性胸水（十版内科学P129）（D错）呈乳状混浊，碱性，无臭味，苏丹Ⅲ染色呈红色，可见脂肪滴，镜检可见到少量淋巴细胞和红细胞，中性粒细胞罕见；化脓性胸水（十版内科学P131）（E错）时白细胞显著升高，以中性粒细胞为主，且细菌阳性。","","N"],["1989-N74",45,"第一节 慢性肾衰竭","防治感染",1989,74,"A","","女性，21岁，患“肾炎”四年，二天来发热咳嗽，查体T38℃，重症贫血貌，心界向左下扩大，心率130/分，右肺满布湿性啰音，肝在肋下1厘米，无明显水肿，肾功能严重损害，胸透右肺炎症，应选下列哪种抗生素",[["A","多粘菌素"],["B","卡那菌素"],["C","青霉素"],["D","庆大霉素"],["E","四环素"]],"C","慢性肾炎患者，出现心界扩大、重度贫血、肾功能严重损害。2天前出现发热咳嗽、右肺满布啰音、胸透右肺炎症，可拟诊为慢性肾衰竭并发肺部感染。慢性肾衰竭防治感染的原则是，在疗效相近的情况下，应该使用肾脏毒性最小的药物，青霉素（C对）在五个选项中肾毒性最小。多粘菌素（A错）主要用于治疗革兰阴性菌感染，对肾脏有毒性作用。卡那菌素（B错）、庆大霉素（D错）为氨基糖苷类药物，对革兰阴性需氧菌主要是肠杆菌菌属有效，有肾毒性。四环素（E错）为广谱抗生素，但对肝肾有毒性作用，已有肾损害者不应继续使用。","","N"],["1989-N75",52,"第二节 急性白血病","急性白血病诊断",1989,75,"A","","男性，20岁，头昏、乏力、全身痛、皮肤出现紫癜半月余，胸骨明显压痛，肝肋下1.5cm，脾肋下1cm。血红蛋白6g/dl，白细胞2×10⁹/L，血小板20×10⁹/L，诊断最可能是",[["A","再生障碍性贫血"],["B","溶血性贫血"],["C","巨幼红细胞性贫血"],["D","急性白血病"],["E","特发性血小板减少性紫癜"]],"D","该患者为青年男性，临床表现为头昏、乏力（贫血症状），全身痛（白血病细胞增殖浸润可有全身痛），皮肤紫癜（出血症状）。查体示：肝、脾大，胸骨明显压痛（白血病细胞增殖浸润常有淋巴结和肝脾肿大，骨骼和关节浸润等表现）。血常规示：血红蛋白6g/dl（6～9g/dl为中度贫血，3～6g/dl属于重度贫血），白细胞2×10⁹/L（正常范围是3.5～9.5×10⁹/L），血小板20×10⁹/L（正常范围125～350×10⁹/L）（急性白血病全血细胞减少）。据此该患者最可能的诊断为急性白血病（D对）。再生障碍性贫血（十版内科学P555）（A错）是由于造血干细胞受损导致的造血功能衰竭，虽患者三系减少，但无肝脾肿大。溶血性贫血（十版内科学P559）（B错）有腰痛、头痛、呕吐、血红蛋白尿、黄疸等表现，无胸骨压痛，无白细胞、血小板减少。巨幼红细胞性贫血（十版内科学P552）（C错）是由于缺乏维生素B₁₂或（和）叶酸所致，虽严重者可引起全血细胞减少，但患者常有引起巨幼贫血的病因，一般无全身痛、无胸骨压痛。特发性血小板减少性紫癜（十版内科学P622）（E错）只有血小板减少，无贫血，无白细胞减少。","","N"],["1989-N76",61,"第三节 高渗高血糖综合征","高渗高血糖综合征诊断",1989,76,"A","","男，60岁，进食后呕吐，腹泻、抽搐、昏迷入院。既往有肝肿大和谷丙转氨酶偏高病史。查体：心率90次/分，BP152/88mmHg，肝右肋下1厘米，质中度硬，表面平滑，脾未触及，血糖49.95mmol/L，血钠158mmol/L，血CO₂结合力容积46％，血尿素氮8.93mmol/L，尿糖（+++），尿酮体阴性，下列哪项诊断可能性最大",[["A","脑血管意外"],["B","糖尿病酮症酸中毒"],["C","高渗性非酮症糖尿病昏迷"],["D","肝性昏迷"],["E","尿毒症"]],"C","该中老年患者血糖49.95mmol/L（高渗高血糖综合征血糖≥33.3mmol/L），表现为呕吐、腹泻（高渗高血糖综合征常有严重脱水表现）、抽搐、昏迷（高渗高血糖综合征可有不同程度的意识障碍或昏迷），血钠增高（正常值范围135～145mmol/L），尿酮体阴性（高渗高血糖综合征血钠正常或升高，尿酮体阴性或弱阳性）。据此，该患者最可能的诊断为高渗高血糖昏迷（高渗性非酮症糖尿病昏迷）（C对）。患者无脑血管病及肾脏疾病病史相关表现（AE错）。糖尿病酮症酸中毒（B错）常表现为血糖16.7～33.3mmol/L，尿酮体阳性，Kussmaul呼吸（呼吸频率增快，呼吸深大），呼吸中可有烂苹果味。肝脏肿大不明显，表面尚光滑，脾脏未肿大，说明由肝病导致昏迷可能性不大（D错）。","","N"],["1989-N78",27,"","",1989,78,"A","","女性，30岁，无溃疡病史，因关节酸痛常服水杨酸制剂，6小时前突然大量呕血，血压100/70mmHg，心率120次/分，出血原因最可能是",[["A","胃、十二指肠溃疡"],["B","门脉高压症，食管曲张静脉破裂出血"],["C","急性胃炎"],["D","胃癌"],["E","应激性溃疡"]],"C","非甾体抗炎药（简称NSAIDs）是一类环氧合酶（简称COX）抑制剂。COX是花生四烯酸代谢的限速酶，有两种异构体：结构型COX-1和诱生型COX-2。COX-1在组织细胞中微量恒定表达，有助于上皮细胞的修复。COX-2主要受炎症诱导表达，促进炎症介质的产生。非特异性COX抑制剂旨在抑制COX-2，从而减轻炎症反应，但因特异性差，同时也抑制了COX-1，导致维持黏膜正常再生的前列腺素E不足，黏膜修复障碍，出现糜烂和出血。该患者在服用水杨酸制剂（非甾体抗炎药）6小时后出现消化道出血，出血原因最可能是急性胃炎（C对）。应激性溃疡（E错）泛指休克、创伤、手术后和严重全身性感染时发生的急性胃黏膜病变，多伴有出血症状，该患者无上述诱发因素，不考虑应激性溃疡。注意：非甾体类抗炎药短期大量使用可以导致急性胃炎，长期使用可以导致消化性溃疡。胃、十二指肠溃疡（A错）多有慢性反复发作病史，与本例不符。门脉高压症，食管曲张静脉破裂出血（B错）的患者多有肝病史本例未提及。胃癌（D错）中的溃疡型胃癌出血时可引起呕血，但是胃癌发病年龄大，多有长期上腹痛，纳差，厌食、乏力和体重减轻。","","N"],["1989-N83",59,"第一节 甲状腺功能亢进症","β受体拮抗剂",1989,83,"B","","甲亢伴严重哮喘者禁用",[["A","心得安"],["B","利血平"],["C","安定"],["D","甲状腺片"],["E","复方碘溶液"]],"A","甲亢指由于血液循环中甲状腺激素过多而引起的神经、循环、消化等系统兴奋性增高和代谢亢进为主要表现的一组临床综合征。β受体阻断药（如心得安，又名普萘洛尔）通过阻断β受体而改善甲亢所致的交感神经激活症状，使体内甲状腺激素作用减弱。但由于心得安对β₁和β₂受体无选择性，在用药过程中会阻断β₂受体激动而产生的支气管痉挛，引发哮喘发作，故甲亢伴严重哮喘者禁用心得安（A对）。","","N"],["1989-N84",59,"第一节 甲状腺功能亢进症","剂量与疗程",1989,84,"B","","抗甲状腺药物治疗后，甲亢症状缓解，甲状腺继续增大时可加用",[["A","心得安"],["B","利血平"],["C","安定"],["D","甲状腺片"],["E","复方碘溶液"]],"D","硫脲类是目前最常用的抗甲状腺药物，通过抑制甲状腺过氧化物酶，进而抑制酪氨酸的碘化及耦联，减少甲状腺素的生物合成。患者使用硫脲类药物后出现甲状腺腺体增大是因为硫脲类使血清甲状腺素水平下降，反馈性增加促甲状腺激素分泌，进而引起腺体代偿性增加、腺体增大、充血等。此时应服用甲状腺片，负反馈抑制TSH的释放（D对）。","","N"],["1989-N97",15,"第二节 慢性心力衰竭","利尿剂",1989,97,"C","","速尿",[["A","减轻心脏前负荷"],["B","减轻心脏后负荷"],["C","二者均减轻"],["D","二者均不减轻"]],"A","速尿（即呋塞米）为袢利尿剂，作用于髓袢升支粗段的Na⁺-K⁺-2Cl⁻共转运子，降低肾脏的浓缩及稀释功能，患者排出大量接近于等渗的尿液，液体潴留减轻，循环血量降低的同时回心血量减少，心脏容量负荷减轻，即前负荷减轻（A对）。心脏后负荷（B）是指心肌收缩之后所遇到的阻力或负荷，又称压力负荷，主要与外周血管阻力有关。考虑到本题目出题时间，原答案为A，但根据最新临床观点，应选择C。","","N"],["1989-N98",18,"","",1989,98,"C","","硝普钠",[["A","减轻心脏前负荷"],["B","减轻心脏后负荷"],["C","二者均减轻"],["D","二者均不减轻"]],"C","硝普钠对直接作用于血管平滑肌，使动、静脉血管均扩张，使心脏前、后负荷均减低（C对），为强效血管扩张剂。","","N"],["1989-N99",11,"第一节 胸腔积液","胸腔积液临床表现",1989,99,"C","","胸腔大量积液",[["A","叩诊浊音"],["B","气管与纵隔移位"],["C","两者均有"],["D","两者均无"]],"C","胸腔大量积液时，患侧胸廓饱满，触觉语颤减弱，局部叩诊浊音（A对），呼吸音减低或消失，可伴有气管与纵隔向健侧移位（B对）。本题AB均对，正确答案为C。","","N"],["1989-N100",4,"第二节细菌性肺炎","肺炎链球菌肺炎临床表现",1989,100,"C","","肺实变",[["A","叩诊浊音"],["B","气管与纵隔移位"],["C","两者均有"],["D","两者均无"]],"A","肺实变体征是指任何原因致肺泡腔内积聚浆液、纤维蛋白和细胞成分等，使肺泡含气量减少、肺质地致密化的一种临床体征。叩诊音介于清音跟实音之间为浊音（A对），无纵隔移位（B错）。气管与纵隔移位见于大量气胸和胸腔积液等。","","N"],["1989-N113",27,"","",1989,113,"X","","应激状态引起急性胃黏膜糜烂的机理，正确的是",[["A","胃酸分泌增多"],["B","黏膜细胞内DNA合成不足"],["C","肥大细胞释放5-羟色胺及组胺"],["D","黏液分泌增多"]],"ABC","正常情况下胃黏膜具有完善而有效的防御和修复机制，足以抵抗胃酸和胃蛋白酶的侵蚀，当机体处于应激状态下时，这一平衡机制被打破，胃酸分泌增多（A对）、肥大细胞释放5-羟色胺及组胺增多（C对），超出了修复范围或黏膜细胞增殖不足（B对）、黏液分泌减少（D错），而导致应激状态引起急性胃黏膜糜烂出血，消化性溃疡的发生。","","N"],["1989-N114",35,"第一节 肝硬化","感染",1989,114,"X","","肝硬化容易并发感染，多见的感染是",[["A","败血症"],["B","肺炎"],["C","自发性腹膜炎"],["D","胆囊、胆道炎"]],"ABCD","肝硬化患者免疫功能降低，容易发生感染，感染部位因患者基础疾病状况而异，主要有自发性细菌性腹膜炎（C对），胆道感染（D对），肺部（B对）、肠道及尿路感染等，严重者可并发败血症（A）。十版内科学中未明确指出败血症是肝硬化易并发的感染，故A存在争议，官方参考答案为ABCD。","","N"],["1989-N115",36,"第一节 原发性肝癌","肝癌标志物",1989,115,"X","","对原发性肝癌有协助诊断意义的辅助检查是",[["A","碱性磷酸酶"],["B","甲胎蛋白"],["C","γ-谷氨酰转肽酶"],["D","放射性核素肝扫描"]],"ABCD","原发性肝癌的实验室及辅助检查主要有肝癌标记物检查、影像学检查以及肝穿刺活体组织检查。肝癌标记物检查主要有甲胎蛋白（B对），是诊断肝细胞癌特异性最强的标记物，但应注意AFP升高还可见于急慢性肝炎、肝硬化以及生殖胚胎肿瘤，但是升高程度不如肝癌明显。γ-谷氨酰转肽酶（C对）和碱性磷酸酶（A对）可用于AFP阴性肝癌的诊断及鉴别诊断。放射性核素肝扫描（D对）也可用于肝癌的诊断，但是放射性核素扫描的敏感性不高，只能发现直径˃3cm的肝癌，目前不作为肝癌的首选诊断方法。","","N"],["1989-N116",75,"第二节 农药中毒","胆碱受体拮抗药",1989,116,"X","","有机磷中毒患者经大剂量阿托品治疗已达阿托品化后，阿托品的使用原则是",[["A","再加大剂量"],["B","维持原剂量"],["C","立即停用"],["D","减量后维持用药"]],"CD","阿托品化指征为口干、皮肤干燥、心率增快（90～100次/分）和肺湿啰音消失。有机磷中毒患者经大剂量阿托品治疗已达阿托品化后，应停用阿托品（C对）或减量后维持用药（D对）。若加大剂量（A错）或维持原剂量（B错）可能会出现瞳孔明显扩大、神志模糊、烦躁不安、抽搐、昏迷和尿潴留等阿托品中毒症状。注意：阿托品化与阿托品中毒的指征及鉴别应该熟练掌握，为常考点。","","N"],["1989-N117",16,"第六节 心脏传导阻滞","房室传导阻滞治疗",1989,117,"X","","二度Ⅱ型及三度房室传导阻滞，心室率慢时，可采用",[["A","阿托品"],["B","异丙肾上腺素"],["C","地塞米松"],["D","奎尼丁"]],"AB","房室传导阻滞的治疗原则是去除病因、维持一定水平的心室率、保持较理想的心排出量。阿托品（A对）可提高房室阻滞的心率，适用于阻滞位于房室结的患者。异丙肾上腺素（B对）适用于任何部位的房室传导阻滞。此外，根据房室传导阻滞室律减慢的程度不同，轻度或高度阻滞但心室率＞40次/min者，可用阿托品、异丙肾上腺素等药物，但如心室率显著缓慢出现了明显症状或血流动力学障碍甚至Adams-Strokes综合征（阿-斯综合征）者，应及早给予临时性或永久性心脏起搏治疗。地塞米松（C错）是糖皮质类激素，主要发挥抗炎、抗过敏作用，为危重疾病的急救用药和各类炎症的治疗药物。奎尼丁（D错）可显著延长心肌不应期，降低自律性、传导性及心肌收缩力，特别对非窦性的异位节律性作用较强，在心率减慢和细胞外低钾时易诱发早后除极，适用于心房纤颤、心房扑动、室上性和室性心动过速的转复和预防，还可用于频发室上性和室性期前收缩的治疗，此外，奎尼丁的不良反应有房室传导阻滞，故不选该选项。（八版药理学P194-P195）。","","N"],["1989-N118",18,"第一节 原发性高血压","高血压急症和亚急症临床表现",1989,118,"X","","急进型高血压的特点是",[["A","视力模糊或失明"],["B","短期内发生肾功能衰竭"],["C","病情发展迅速"],["D","舒张期血压持续＞130mmHg"]],"ABCD","急进型高血压（恶性高血压）的患者病情发展迅速（C对），舒张压持续≥130mmHg（D对），并有剧烈头痛、视力模糊、眼底出血、渗出和视盘水肿甚至失明（A对），肾脏损害突出，持续蛋白尿、血尿与管型尿，如不及时有效降压治疗，短期内可发生肾功能衰竭（B对）、脑卒中或心力衰竭。可同时伴有进行性心、脑、肾等重要靶器官功能不全的表现，血压水平的高低与急性靶器官损害的程度并非成正比。","","N"],["1989-N119",23,"第一节 感染性心内膜炎","链球菌",1989,119,"X","","女生，26岁，风湿性心脏病，病程10年，因近2周发热，口腔黏膜有瘀点，脾可扪及，尿中红细胞0～6/HP，疑合并亚急性感染性心内膜炎，青霉素皮试（+），可考虑改用的抗生素有",[["A","红霉素"],["B","万古霉素"],["C","氯霉素"],["D","先锋霉素"]],"BD","亚急性感染性心内膜炎最常见致病菌为链球菌（G⁺球菌），经验治疗一般以青霉素为主，但该患者青霉素皮试（+），考虑青霉素过敏，须更换其他抗菌谱类似的抗生素。万古霉素（B对）为糖肽类抗生素，对G⁺有强大的杀菌效力。先锋霉素（D对）为头孢菌素类抗生素，对G⁺有强大的杀菌效力。红霉素（A错）为大环内酯类药物，通常为抑菌作用，仅在高浓度时有一定杀菌作用，且红霉素的抗菌效力不及青霉素。氯霉素（C错）对G⁻细菌作用强于G⁺细菌，属于抑菌药，且对造血系统可能产生致命性毒性，因此，当能够使用其他抗生素或感染原因不明时，绝对不要使用氯霉素（八版药理学P393）。","","N"],["1989-N120",50,"第二节 遗传性球形红细胞增多症","遗传性球形红细胞增多症治疗",1989,120,"X","","溶血性贫血进行脾切除的适应证是",[["A","遗传性球形红细胞增多症"],["B","糖皮质激素治疗无效的原发性自身免疫性溶血性贫血"],["C","海洋性贫血溶血明显或脾肿大明显者"],["D","阵发性睡眠性血红蛋白尿"]],"ABC","血管外溶血性贫血，如遗传性球形红细胞增多症（A对）、温抗体型自身免疫性溶血性贫血（B对）、海洋性贫血（C对），红细胞在脾脏中被破坏，脾切除治疗有效，为脾切除的适应证。血管内溶血性贫血红细胞在血管内被破坏，脾切除无效，如阵发性睡眠性血红蛋白尿（十版内科学P567）（D错）。","","N"],["1989-N121",17,"第四节 急性冠状综合征","体征",1989,121,"X","","急性心肌梗塞时心室颤动的先兆是",[["A","室性早搏超过5次/分"],["B","多源性室性早搏"],["C","室性早搏落在前一心搏的易损期"],["D","多源性房性早搏"]],"ABC","各种心律失常中以室性心律失常最多，尤其是室性期前收缩，如室性期前收缩频发（每分钟5次以上）（A对），成对出现或呈短阵室性心动过速，多源性（B对）或落在前一心搏的易损期时（R在T波上）（C对），常为心室颤动的先兆。多源性房性期前收缩（D错）常见于患COPD（慢性阻塞性肺疾病）、CHF（充血性心力衰竭）的老年人、洋地黄中毒及低血钾者，易发展为心房颤动，不是心室颤动的先兆。","","N"],["1989-N122",5,"第一节 肺脓肿","肺脓肿抗感染治疗",1989,122,"X","","治疗肺脓肿厌氧菌感染的有效抗菌素有",[["A","青霉素"],["B","洁霉素"],["C","灭滴灵"],["D","氯林可霉素"]],"ABCD","吸入性肺脓肿多合并厌氧菌感染，一般均对青霉素敏感（A对），疗效较佳，故最常用。一般急性肺脓肿经青霉素治疗均可获痊愈。脆弱拟杆菌对青霉素不敏感，可用林可霉素（洁霉素）（B对）肌内注射；病情严重者可用静脉滴注，或氯林可霉素（克林霉素）（D对）口服，或甲硝唑（灭滴灵）（C对）口服。","","N"],["1989-N123",6,"第一节 肺结核","痰涂片检查",1989,123,"X","","肺结核患者有痰菌阳性，下列哪是错误的",[["A","肺内病灶具有活动性，需化疗"],["B","需补种卡介苗，提高机体免疫力"],["C","系结核病的传染源，痰液需无菌处理"],["D","需作结核菌素试验"]],"BD","肺结核患者痰菌阳性说明此时结核处于活动期，传染性强，可致他人感染，所以肺结核患者痰液应行无菌处理，患者必须及时给予化疗（AC对），控制患者病情，防止病情恶化。卡介苗是用于预防结核病的疫苗，患病前注射，刺激机体产生免疫应答，是一种预防措施，对结核的治疗意义不大，不作为结核的治疗措施（B错，为本题正确答案）。结核菌素试验是结核的一种诊断方法，而患者痰菌阳性说明此时结核处于活动期，无需作结核菌素试验（D错，为本题正确答案）。","","N"],["1989-N124",11,"第一节 胸腔积液","结核性胸膜炎",1989,124,"X","","以下不符合结核性渗出性胸膜炎特点的有",[["A","OT试验多属阴性"],["B","患侧胸廓运动受限"],["C","胸水中常可找到结核菌"],["D","胸水为渗出性"]],"AC","结核性渗出性胸膜炎是由于结核分枝杆菌感染引起的，OT试验为检测结核杆菌感染的特异的指标，多属阳性。故A错，为本题正确答案；结核分枝杆菌侵犯胸膜可导致胸膜通透性增加，引起出现渗出性胸腔积液（D对），胸腔积液较多时，患侧胸廓饱满，运动受限（B对）；但胸水中找结核分枝杆菌的阳性率较低，仅约20%（C错，为本题正确答案）。","","N"],["1989-N125",10,"第三节 慢性肺源性心脏病","慢性肺源性心脏病诊断",1989,125,"X","","早期慢性肺心病的临床诊断依据为",[["A","有慢支病史及肺气肿体征"],["B","剑突下有收缩期搏动P₂"],["C","三尖瓣区有收缩期杂音"],["D","左心室增大"]],"ABC","早期慢性肺心病的表现为肺、心功能代偿期症状和体征，如剑突下可有收缩期搏动，P₂亢进（B对），三尖瓣区可有收缩期杂音（C对），慢支及肺气肿（A对）是慢性肺心病重要的基础疾病因素，其临床表现可为慢性肺心病的早期表现，出现慢支或肺气肿时要警惕发展成为慢性肺心病；肺心病先有右心结构和功能改变，出现左心室增大说明心脏损害已累及全心，属于晚期病变（D错）。","","N"],["1989-N126",39,"第一节 总论","影像学检查",1989,126,"X","","放射性核素肾图检查可以了解",[["A","检测肾血流量"],["B","检测肾脏排泌功能"],["C","肾内有无尿流梗阻"],["D","肾脏的形态和位置及无功能区"]],"ABCD","肾图指静脉注射由肾小球滤过或肾小管上皮细胞分泌而不被再吸收的放射性示踪剂，在体外应用肾图仪连续记录双肾的时间-放射性活度曲线，可用于了解肾血流量（A对）、肾脏排泌功能（B对）、肾内有无尿流梗阻（C对）、肾脏的形态和位置及无功能区（D对）等。肾图具有无创伤性、简便、灵敏、定量等优点，常用于诊断上尿路梗阻如尿路结石、畸形、狭窄及肿瘤，测定肾功能，观察感染、损伤及血尿等与分肾的关系、移植肾监测等。","","N"],["1989-N127",40,"第五节 肾病综合征","细胞毒药物",1989,127,"X","","环磷酰胺的毒性反应有",[["A","恶心、呕吐及中毒性肝损害"],["B","抑制骨髓及性腺"],["C","出血性膀胱炎"],["D","脱发"]],"ABCD","环磷酰胺是各种免疫抑制剂中作用最强的药物之一，也是烷化剂中作为免疫抑制剂应用最多的药物。其免疫作用强而持久，机制是抑制细胞的增殖，非特异性地杀伤抗原敏感性小淋巴细胞，阻止其转化为免疫母细胞，在抗原刺激后给予最为有效。主要副作用：骨髓抑制（B对），主要为白细胞减少；泌尿道症状主要来自化学性膀胱炎，如尿频、尿急、膀胱尿感强烈、血尿（C对），甚至排尿困难。应多饮水，增加尿量以减轻症状；消化系统症状有恶心、呕吐及厌食，静注或口服均可发生，静注大量后3～4小时即可出现，肝功能不良者慎用（A对）；常见的皮肤症状有脱发（D对），但停药后可再生细小新发；长期应用，男性可致睾丸萎缩及精子缺乏；妇女可致闭经、卵巢纤维化或致畸胎，孕妇慎用；偶可影响肝功能，出现黄疸及凝血酶原减少。","","N"],["1989-N128",41,"第一节 尿路感染","尿路感染预后和预防",1989,128,"X","","预防慢性肾盂肾炎复发的措施有",[["A","长期、大剂量应用抗菌药物"],["B","多饮水、及时排尿"],["C","联合应用二种以上抗菌药物"],["D","低剂量药物抑菌疗法连续0.5～1年"]],"BD","预防慢性肾盂肾炎复发的措施有：多饮水、勤排尿（B对），通过尿液的反复冲刷使细菌难以定植；注意会阴部清洁；尽量避免尿路器械的使用，必需应用时，严格无菌操作；如必须留置导尿管，前3天给予抗生素可延迟尿感的发生；与性生活有关的尿感，应于性交后立即排尿，并口服一次常用量抗生素；膀胱-输尿管反流者，要“二次排尿”，即每次排尿后数分钟，再排尿一次。低剂量药物抑菌疗法连续0.5～1年（D对）也是比较有效的预防方法，维持尿液中一定的抗生素浓度以抑制细菌生长。长期、大剂量应用抗菌药物（A错）和联合应用两种以上抗菌药物（C错）为慢性肾盂肾炎急性发作的治疗措施，不是预防措施。","","N"],["1989-N129",45,"第一节 慢性肾衰竭","高血压的治疗",1989,129,"X","","尿毒症高血压时可选用的降压药是",[["A","甲基多巴"],["B","心得安"],["C","肼苯哒嗪"],["D","优降宁"]],"ABC","甲基多巴（A对）在体内产生代谢产物α-甲基去甲肾上腺素，激动中枢α受体，从而抑制对心、肾和周围血管的交感冲动输出，与此同时，周围血管阻力及血浆肾素活性也降低，血压因而下降。用于治疗中度高血压，特别是适用于肾功能不良的高血压患者（七版药理学P139-P140），由于不良反应较多，现在已很少应用；普萘洛尔（心得安）（B对）为β受体拮抗剂，作为治疗高血压第一线用药，单独或与其他药物合并应用；肼苯哒嗪（C对）能直接扩张周围血管，以扩张小动脉为主，降压作用强，降低外周总阻力而降压，可改善肾、子宫和脑的血流量，降低舒张压的作用较降低收缩压为强。用于肾型高血压及舒张压较高的病人。单独使用效果不甚好，且易引起副反应，故多与利血平、氢氯噻嗪、胍乙啶或心得安合用，以增加疗效；优降宁（D错）为单胺氧化酶抑制剂，临床上主要用于重度高血压，尤其是在其他降压药疗效不满意者，自觉症状较多，特别是精神及情绪均较差者以及对利血平有较严重不良反应者。轻度高血压不宜用本品，中度高血压可单用本品，或与口服利尿药合用，不适用于血容量增多的高血压患者，如尿毒症高血压，可导致肝肾功能障碍。","","N"],["1989-N130",46,"第一节 贫血概述","贫血分类",1989,130,"X","","小细胞低色素性贫血可见于",[["A","缺铁性贫血"],["B","海洋性贫血"],["C","铁粒幼红细胞性贫血"],["D","再生障碍性贫血"]],"ABC","小细胞低色素性贫血指红细胞平均体积减小（＜80fl），红细胞平均血红蛋白浓度降低（＜32%）的贫血，包括缺铁性贫血（A对）、珠蛋白生成障碍性贫血（海洋性贫血）（B对）以及铁粒幼细胞性贫血（C对）。缺铁性贫血（十版内科学P549）指原料铁缺乏所致的血红素、血红蛋白合成减少，表现为小细胞低色素性贫血。海洋性贫血又称地中海贫血（十版内科学P563），是由于基因异常而引起珠蛋白合成障碍的一种疾病，该病为慢性病程，以溶血、无效红细胞生成及不同程度的小细胞低色素性贫血为特征。铁粒幼细胞性贫血（十版内科学P551）是各种原因引起红细胞铁利用障碍所致的贫血，表现为小细胞低色素性贫血。再生障碍性贫血（十版内科学P555）（D错）是一种骨髓造血功能衰竭症，多为急性病程，生成的红细胞数量下降，质量多正常，表现为正常细胞性贫血。","","N"],["1989-N131",55,"第一节 出血性疾病概述","凝血异常",1989,131,"X","","下列疾病中，哪些会引起凝血功能障碍",[["A","严重肝病"],["B","原发性血小板减少性紫癜"],["C","维生素K缺乏症"],["D","过敏性紫癜"]],"AC","凝血功能障碍是由凝血因子缺乏或功能异常所引起，与血小板数量与质量、毛细血管脆性及通透性无关。多种凝血因子在肝内合成，所以严重肝病（A对）时会引起凝血因子缺乏、凝血功能障碍。凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的合成需维生素K参与，维生素K缺乏（C对）时会引起这些凝血因子合成障碍，导致凝血功能障碍。原发性血小板减少性紫癜（P614）（B错）会引起血小板减少，不会引起凝血功能障碍。过敏性紫癜（十版内科学P620）（D错）会引起毛细血管脆性及通透性增加，不会引起凝血功能障碍。","","N"],["1989-N133",59,"第一节 甲状腺功能亢进症","β受体拮抗剂",1989,133,"A","","可减轻甲状腺功能亢进症症状，但不能使甲状腺激素分泌释放减少的是",[["A","甲巯咪唑"],["B","¹³¹I治疗"],["C","复方碘液"],["D","心得安"]],"D","心得安（普萘洛尔）为β受体拮抗药，机制是阻断甲状腺激素对心脏的兴奋作用和阻断外周组织T₄向T₃的转化，并不能使甲状腺激素释放减少（D对）。甲巯咪唑（十版内科学P691）（他巴唑，MMI）为咪唑类抗甲状腺药物，抑制甲状腺合成甲状腺激素，从而使甲状腺激素释放减少（A错）。¹³¹I治疗破坏甲状腺组织细胞，从而使甲状腺激素释放减少（B错）。复方碘液可抑制甲状腺球蛋白的水解，从而抑制甲状腺素的释放；此外，大剂量碘剂还能拮抗TSH促进激素释放作用，亦可以抑制甲状腺过氧化物酶的活性，影响酪氨酸的碘化及酪氨酸的缩合，减少甲状腺素的合成（C错）。","","N"],["1989-N134",61,"第一节 糖尿病","T2DM病因、发病机制和自然史",1989,134,"X","","可引起糖耐量低下的疾病有",[["A","糖尿病"],["B","甲亢"],["C","库欣综合征"],["D","肢端肥大症"]],"ABCD","糖耐量减低，是胰岛素分泌不足或分泌延迟使机体对血糖浓度的调节能力减低，使餐后血糖不能正常降低。糖尿病胰岛素分泌不足，可引起糖耐量低下（A对）。甲亢时因甲状腺激素促进肠道糖吸收，加快糖代谢及肝糖原分解，导致血糖升高，糖耐量降低（B对）。Cushing综合征（库欣综合征）患者分泌大量皮质醇，促进肝糖原异生，并有拮抗胰岛素的作用，减少外周组织对葡萄糖的利用，肝葡萄糖输出增加，引起糖耐量减低（C对）。肢端肥大症因胰岛素拮抗激素（糖皮质激素、生长激素）分泌增多，对胰岛素产生拮抗作用，引起糖耐量降低（D对）。","","N"],["1989-N138",24,"第一节 心脏骤停与心脏性猝死","初级心肺复苏",1989,138,"X","","心跳、呼吸停止的急救中，理想的人工呼吸应是",[["A","能保证充分的通气量"],["B","能使动脉血氧分压接近正常"],["C","操作简单"],["D","无需特殊的器械或仪器"]],"ABCD","人工通气的目的就是为保证充分的通气量（A对），以纠正低氧血症，使动脉血氧分压接近正常（B对）。操作简单保证紧急情况下施救的有效性和可行性（C对）。心跳、呼吸停止的急救采取的是紧急处理措施，主要为了抢救生命，需要用简单的器械或仪器，便于操作，提高施救的效率，降低抢救的难度（D对）。","","N"],["1989-N140",36,"第一节 原发性肝癌","原发性肝癌并发症",1989,140,"X","","原发性肝癌可并发",[["A","肝性脑病"],["B","癌瘤破裂腹内大出血"],["C","上消化道出血"],["D","持续性低热"]],"ABCD","原发性肝癌的并发症可由肝癌本身或是并存的肝硬化引起，常见于病程晚期，是肝癌的主要致死原因。主要有（1）肝性脑病（A对）：常为终末期最严重并发症，约占本病死亡原因的1/3；（2）上消化道出血（C对）：约占肝癌死因15%，大量出血可诱发肝性脑病；（3）肝癌结节破裂出血（B对）：约发生于肝癌患者的10%；（4）继发感染：长期消耗、手术或放化疗，患者抵抗力减弱，容易并发肺炎、自发性腹膜炎、肠道感染和霉菌感染等。另外，肝癌患者本身可有发热症状，一般为低热，偶达39℃以上，呈持续性或午后低热或弛张型高热（D对）。","","N"],["1989-N141",37,"第二节 慢性胰腺炎","慢性胰腺炎病因和发病机制",1989,141,"X","","下列哪些因素与慢性胰腺炎的发病有关",[["A","胆道疾病"],["B","饮酒"],["C","胰管阻塞"],["D","胰腺外伤"]],"ABC","在其他致病因素存在的条件下，酒精（B对）及其代谢产物的细胞毒性作用可导致胰腺慢性进行性损伤和纤维化，胰液粘稠及蛋白沉淀可使胰管引流不畅和结石形成。胆道疾病（A对）是我国慢性胰腺疾病的常见原因之一，各种胆系疾病及胰管阻塞（C对）均可反复引起胰腺炎并逐渐发展为慢性胰腺炎。胰腺外伤（D错）与急性胰腺炎的发病有关，直接或间接的胰腺外伤可损伤胰腺组织与胰腺的血液供应引起急性胰腺炎，而与慢性胰腺炎的发病无关。","","N"],["1989-N142",37,"第一节 急性胰腺炎","急性胰腺炎病理",1989,142,"X","","急性胰腺炎所引起的严重病理生理改变",[["A","继发感染，全身中毒反应"],["B","急性肾功能衰竭"],["C","急性呼吸窘迫综合征"],["D","腹痛、失血和休克"]],"ABCD","急性胰腺炎表现为重症急性胰腺炎时，由于炎症波及全身，可有其他脏器如小肠、肺、肝、肾等脏器的炎症病理改变。当炎症波波及全身时，可有继发感染，全身中毒反应（A对）。当肾脏受累时，可有急性肾功能衰竭（B对）。当肺受累时，可有急性呼吸窘迫综合征（C对）。腹痛是急性胰腺炎的主要表现和首发症状；重症急性胰腺炎由于大量炎性渗出和严重严重炎症及感染，可引起休克；发生应激性溃疡时可引起消化道出血（D对）。","","N"],["1989-N153",13,"第二节 急性呼吸衰竭","急性呼吸衰竭临床表现",1989,153,"X","","在呼吸性酸中毒时，可见",[["A","血钾升高"],["B","血浆CO₂结合力下降"],["C","血浆CO₂结合力升高"],["D","呼吸加深加快"]],"ACD","呼吸性酸中毒（呼酸）血液中H⁺浓度升高，H⁺-K⁺交换增强，H⁺由细胞外液进入细胞内，K⁺由细胞内进入细胞外液，导致血钾升高（A对）。呼吸性酸中毒时动脉血中二氧化碳分压升高，刺激颈动脉体和主动脉体感受器，引起呼气加深加快（D对），促进二氧化碳的排出，应注意的是严重的呼吸性酸中毒则表现呼吸抑制。CO₂结合力反映血浆中HCO₃⁻的浓度。呼吸性酸中毒时，CO₂潴留导致PaCO₂升高，肾脏通过代偿性增加HCO₃⁻重吸收，使血浆HCO₃⁻浓度升高（C对B错）。","","N"],["1990-N1",27,"","",1990,1,"A","","急性胃黏膜损害的主要临床表现是",[["A","上腹痛"],["B","恶心、呕吐"],["C","伴有腹泻或发热"],["D","上消化道出血"],["E","以上都不是"]],"A","急性胃黏膜炎症是由多种病因引起的，临床上急性发病，常表现为上腹痛、胀满、恶心、呕吐和食欲不振等；重症可有呕血、黑粪、脱水、酸中毒或休克；轻者可无症状，仅在胃镜检查时发现（十版内科学P369），有症状者主要表现为轻微上腹部不适或隐痛（A对）。恶心、呕吐（B错）为伴随症状，不是主要症状。上消化道出血（D错）见于重症急性胃炎，病情较严重的状态。一般不伴有腹泻或发热（C错）。","","N"],["1990-N2",29,"第一节 肠结核","大便习惯改变",1990,2,"A","","增生性肠结核的常见症状是",[["A","腹泻"],["B","便秘"],["C","腹泻与便秘交替出现"],["D","盗汗"],["E","消瘦"]],"B","溃疡型肠结核常伴腹泻（A错），粪便呈糊状，多无脓血，不伴里急后重，有时腹泻与便秘交替出现。增生型肠结核肠壁大量肉芽肿及纤维组织增生，导致肠腔狭窄。因此增生型肠结核以便秘为主（B对），腹泻与便秘交替出现少见（C错）。盗汗和消瘦为结核毒血症状，主要见于溃疡型肠结核，增生型者全身情况一般较好，无明显结核毒血症状（十版内科学P383）（DE错）。","","N"],["1990-N4",35,"第一节 肝硬化","及早识别及去除HE发作的诱因",1990,4,"A","","关于肝性昏迷的处理，下列哪一项是错误的",[["A","终止蛋白质饮食"],["B","用肥皂水灌肠"],["C","新霉素保留灌肠"],["D","用冰帽降低颅内温度"],["E","谷氨酸钾静滴"]],"B","终止蛋白质饮食可以减少氨的生成（A对），有利于肝性脑病的治疗。新霉素保留灌肠可以抑制肠道产尿素酶的细菌，减少氨的生成（C对）。谷氨酸钾可与氨结合形成谷氨酰胺而降低血氨（E对）。冰帽降低颅内温度可减少能量消耗，保护脑细胞功能（D对）。氨以非离子型氨（NH₃）和离子型氨（NH₄⁺）两种形式存在，氨在肠道的吸收主要以NH₃弥散入肠黏膜，当结肠内pH˃6时，NH₄⁺转为NH₃，NH₃经肠道大量吸收，弥散入血；pH＜6时，则NH₃从血液转至肠腔，随粪排泄。肥皂水为碱性溶液，用肥皂水灌肠时（B错，为本题正确答案），NH₄⁺转为NH₃，NH₃经肠道大量吸收，弥散入血，加重肝性昏迷症状。","","N"],["1990-N5",75,"第二节 农药中毒","烟碱样症状",1990,5,"A","","有机磷农药中毒出现的烟碱样症状是",[["A","多汗"],["B","肌束颤动"],["C","瞳孔缩小"],["D","支气管痉挛"],["E","流涎"]],"B","正常情況下，体内的乙酰胆碱（ACh）在胆碱酯酶的水解下失活，有机磷农药中毒时胆碱酯酶活性被抑制，体内ACh大量蓄积，持续作用于M和N受体出现M样症状和N样症状。烟碱样症状又称N样症状，在横纹肌神经肌肉接头处ACh蓄积过多，出现肌纤维颤动（B对），甚至全身肌肉强直性痉挛，也可出现肌力减退或瘫痪，呼吸肌麻痹引起呼吸衰竭或停止。毒蕈碱样症状又称M样症状，主要是副交感神经末梢过度兴奋，产生类似毒蕈碱样作用（八版生理学P285）。平滑肌痉挛表现：瞳孔缩小（Ach作用于瞳孔括约肌M受体引起收缩所致）（C错），胸闷、气短、呼吸困难（Ach作用于支气管平滑肌M受体引起支气管痉挛所致）（D错），恶心、呕吐、腹痛、腹泻。括约肌松弛表现：大小便失禁。腺体分泌增加表现：多汗（交感节后神经纤维M胆碱能受体兴奋使皮肤小汗腺分泌汗液增加所致）（A错）、流泪和流涎（Ach作用于唾液腺上的M受体使唾液分泌增加所致）（E错）。","","N"],["1990-N7",37,"第一节 急性胰腺炎","减少胰液分泌",1990,7,"A","","治疗急性胰腺炎（水肿型）的主要措施是",[["A","手术"],["B","抑制或减少胰腺分泌"],["C","应用肾上腺皮质激素"],["D","应用抗生素"],["E","应用吗啡镇痛"]],"B","急性胰腺炎的主要发病机制为胰液对于胰腺及其周围组织的消化作用，抑制和减少胰液分泌可减少胰液的进一步损伤作用，是治疗急性胰腺炎（水肿型）的主要措施（B对）。急性胰腺炎全身炎症反应期经历大的手术创伤将加重炎症反应，增加死亡率，因此急性胰腺炎病人即使是重症急性胰腺炎（SAP），应尽量保守治疗，手术（A错）仅适用于某些出血坏死型胰腺炎，如因胆总管结石性梗阻、急性化脓性胆管炎等引起的胆源性胰腺炎可外科手术解除梗阻。急性水肿型胰腺炎继发感染可能小，可不使用抗生素，或仅作为预防继发感染时使用，并不是治疗的主要措施（D错）。当腹痛严重时，可予以哌替啶肌注镇痛。由于吗啡可增加Oddi括约肌压力，胆碱能受体拮抗剂如阿托品可诱发或加重肠麻痹，故均不宜使用（E错）。糖皮质激素一般不用于急性胰腺炎（水肿型）的治疗（C错）。","","N"],["1990-N8",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞鉴别诊断",1990,8,"A","","临床上鉴别肝性与心包疾患所引起的腹水，下列哪一项最有诊断价值",[["A","心动过速"],["B","肝肿大"],["C","下肢浮肿"],["D","颈静脉怒张"],["E","脾肿大"]],"D","心包疾病可导致体循环淤血，而肝脏病变主要引起门脉回流障碍，并不影响上腔静脉回流，不会出现颈静脉怒张，因此鉴别肝性与心包疾患所引起的腹水颈静脉怒张（D对）最有诊断价值。心动过速（A错）、肝肿大（B错）、下肢浮肿（C错）、脾肿大（E错）等症状在肝病变及心包疾患均有出现的可能，因此鉴别意义不大。","","N"],["1990-N9",17,"第四节 急性冠状综合征","心电图",1990,9,"A","","心电图对区别心肌梗死和心绞痛最有意义的改变是",[["A","T段上升"],["B","T波呈冠状“T”倒置"],["C","合并心律失常"],["D","T波异常高耸"],["E","病理Q波"]],"E","心肌梗死患者心肌发生缺血性坏死，为不可逆的病理性改变，心电图出现病理性Q波，而心绞痛一般为心肌缺血而导致的疼痛，心肌没有完全梗死，不会出现病理性Q波（E对）。心绞痛和心肌梗死患者心肌处于短暂性的失血状态，心电图会表现为ST段和T波的暂时性变化，可出现诸如T段上升（A错）、T波呈冠状“T”倒置（B错）、T波异常高耸（D错）等变化。心绞痛和心肌梗死时都可合并心律失常（C错）。","","N"],["1990-N10",19,"第一节 肥厚型心肌病","肥厚型心肌病超声心动图",1990,10,"A","","下列哪项检查对肥厚型梗阻性心肌病最有诊断价值",[["A","胸部X线检查"],["B","心电图"],["C","心音图"],["D","超声心动图"],["E","心功能检查"]],"D","肥厚型梗阻性心肌病的特征为心室肌肥厚，典型者在左心室，以室间隔为甚，偶尔可呈同心性肥厚，左心室腔容积正常或减小，偶尔病变发生于右心室。超声心动图对诊断该病有重要意义，典型超声心动图表现为：左心室壁显著增厚，心室间隔较心室后壁更为肥厚，左心室腔小，流出道狭窄和心脏收缩时二尖瓣前瓣叶向前移位（D对）。胸部X线检查（A错）可作为辅助诊断依据，典型病例可见心影增大，左心室增大，但无升主动脉扩大或瓣叶钙化征象。晚期病例则左心房、右心室亦可增大，肺野血管淤血。心电图（B错）检查可作为辅助诊断依据，可显示左心室肥大和劳损，有时前胸aVL和Ⅰ导联呈现异常Q波。有的病例呈现完全性右束支、左束支或左前半支传导阻滞和左心房肥大。心音图（C错）是将心脏活动过程中产生的声振动（心音及杂音）通过换能器、放大电路、检波等方法，以振动波的形式记录下来绘制成图。心音图有助于确定心音或杂音发生的时间，区分易于混淆的声音，主要用于鉴别某些听诊杂音相似而病变迥异的心内疾病。心功能检查（E错）的方法很多，通常分为有创性和无创性两大类。有创性检查主要指心导管检查；无创性检查方法较多，如超声心动图、放射性核素心血管造影、收缩时间间期、心阻抗图等等。但最主要的还是超声心动图。","","N"],["1990-N11",13,"第二节 急性呼吸衰竭","急性呼吸衰竭并发症的处理",1990,11,"A","","肺性脑病患者进入昏迷，一侧瞳孔缩小，对光反射迟钝，除积极处理呼吸衰竭外，急救先采用",[["A","加大抗生素用量"],["B","双氢克尿噻"],["C","安体舒通"],["D","20%甘露醇静脉快速滴注"],["E","5%碳酸氢钠静脉滴注"]],"D","肺性疾病患者昏迷后出现一侧瞳孔缩小，对光反射迟钝的表现，说明患者并发脑水肿，应该立即降低颅内压，急救先采用20%甘露醇静脉快速滴注（D对），其为高渗降压药，进入人体后能提高血浆渗透压，使脑组织脱水，减轻脑水肿。双氢克尿噻（B错）、安体舒通（C错）为利尿剂，主要通过抑制肾脏钠离子及水等的重吸收，增加尿量来发挥作用，急性应用主要是减少细胞外液量，并不能显著缓解脑水肿，若利尿过快可以导致脑疝的发生，不利于患者的治疗。加大抗生素用量（A错）可以控制肺部感染，减轻脑水肿，但不是急救先采用的药物。5%碳酸氢钠静脉滴注可以治疗患者的酸中毒，但也不是肺性疾病脑水肿的急救措施。","","N"],["1990-N12",10,"第三节 慢性肺源性心脏病","肺性脑病",1990,12,"A","","下列哪种情况禁忌使用吗啡或杜冷丁",[["A","肺心病合并肺性脑病"],["B","肺水肿"],["C","肺结核小量咯血"],["D","肺癌"],["E","干性胸膜炎"]],"A","吗啡或杜冷丁对呼吸中枢有抑制作用。肺性脑病是由于呼吸功能衰竭，二氧化碳潴留使脑脊液H⁺浓度增加，影响脑细胞代谢，降低脑细胞兴奋性的神经精神障碍综合征，治疗时必须增加呼吸中枢的兴奋性，加快二氧化碳的排出。所以，吗啡或杜冷丁是属禁忌使用的药物（A对）。吗啡或杜冷丁也有镇静、镇痛作用，肺水肿（B错）、肺结核小量咯血（C错）、肺癌（D错）、干性胸膜炎（E错）时可以应用。","","N"],["1990-N13",4,"第二节细菌性肺炎","并发症的处理",1990,13,"A","","肺炎球菌肺炎患者，在抗菌素治疗下热退又再发热，白细胞增高，应考虑是",[["A","抗菌素剂量不够"],["B","细菌产生耐药性"],["C","出现并发症"],["D","没有配用退热剂"],["E","机体反应性差"]],"C","患者在应用抗菌素治疗后先热退，说明抗生素发挥了作用，退热是有效的，故可以排除抗菌素剂量不够（A错），没有配用退热剂（D错）以及机体反应性差（E错）。治疗后又再发热，应考虑肺炎链球菌的肺外感染，出现并发症如脓胸、心包炎或关节炎等（C对）。一般细菌产生耐药性需要反复用药之后才会产生（B错）。","","N"],["1990-N14",2,"第一节 支气管哮喘","轻度",1990,14,"A","","急症哮喘患者，病因未明，为缓解症状，应立即选用",[["A","毒毛旋花子甙K"],["B","肾上腺素"],["C","异丙肾上腺素"],["D","氨茶碱"],["E","杜冷丁"]],"D","此题哮喘病因未明，可能是支气管哮喘也可能是心源性哮喘（左心衰竭引起的喘息样呼吸困难）。肾上腺素、异丙肾上腺素（BC错）可兴奋β₂受体，松弛支气管平滑肌，扩张支气管，解除支气管痉挛，故可用于支气管哮喘；而对心脏β₁受体也有兴奋作用，可使心肌收缩力增强，心率加快，心肌耗氧量增加，故禁用于心源性哮喘。吗啡、杜冷丁（E错）可以抑制呼吸中枢，引起支气管收缩，禁用于支气管哮喘的治疗。故病因一时难以鉴别时，可雾化吸入β₂受体激动剂或者静脉注射氨茶碱缓解症状后进一步检查（D对），以免造成危险。茶碱类药物通过抑制磷酸二酯酶，提高平滑肌细胞内的环腺苷酸（cAMP）浓度，拮抗腺苷受体，增强呼吸肌的力量以及增强气道纤毛清除功能等，从而起到舒张支气管和气道抗炎作用。毒毛旋花子甙K（A错）为洋地黄类的药物，主要用于急性心衰或慢性心衰加重期，对哮喘无改善作用。","","N"],["1990-N15",1,"第一节 慢性支气管炎","慢性支气管炎X线检查",1990,15,"A","","早期慢性支气管炎肺部X线表现是",[["A","无特殊征象"],["B","两肺纹理增粗、紊乱"],["C","肺野透亮度增加"],["D","膈肌下降"],["E","胸部扩张、肋间增宽"]],"A","早期慢性支气管炎肺部X线表现多无特殊征象（A对）。当病情反复发作时，可引起两肺纹理增粗、紊乱（十版内科学P24）（B错）。若病情进一步发展成慢性阻塞性肺气肿时，X线下可出现肺野透亮度增加（C错）和膈肌下降（D错）等表现。当病情继续发展至肺气肿晚期时，肺组织和毛细血管床破坏加重，X线下可出现肺野透亮度明显增加、胸廓前后径及横径均增大及肋间隙增宽（E错）等表现。","","N"],["1990-N16",6,"第一节 肺结核","肺结核鉴别诊断",1990,16,"A","","肺癌空洞、肺结核空洞、肺脓肿空洞最可靠的鉴别方法是",[["A","X线胸片+断层摄影"],["B","支气管碘油造影"],["C","痰脱落细胞学检查和细菌学检查"],["D","胸部超声波探查"],["E","以上都不是"]],"C","痰脱落细胞学检查和细菌学检查可直接发现痰液中的细胞类型、细菌种类，如肺癌患者痰液中可找到癌细胞、肺结核患者痰液中可发现抗酸杆菌、肺脓肿患者痰液中可找到致病菌，所以痰脱落细胞学检查和细菌学检查是肺癌空洞、肺结核空洞及肺脓肿空洞最可靠的鉴别方法（C对）。X线胸片+断层摄影（A错）及胸部超声波探查（D错）可以显示出不同的空洞大小，是否光滑，壁的厚度等，但对于肺癌空洞、肺结核空洞及肺脓肿空洞的鉴别不如痰脱落细胞学检查和细菌学检查的准确度高。支气管碘油造影（B错）为支气管扩张症的诊断方法，不用于三者的鉴别。","","N"],["1990-N17",44,"第一节 急性肾损伤","肾脏替代治疗",1990,17,"A","","急进性肾炎持续少尿伴高钾血症时的首选治疗措施是",[["A","肾移植"],["B","大剂量维生素C静脉滴注"],["C","绝对卧床"],["D","血液透析"],["E","预防感染"]],"D","急进性肾炎少尿可导致代谢废物及尿毒症毒素淤积，高钾血症容易导致心律失常，可威胁患者生命，治疗首选血液透析（D对）。肾移植（A错）要在病情静止半年，特别是Ⅰ型患者血中抗GBM抗体须转阴后半年进行（十版内科学P478），非首选。大剂量维生素C静脉滴注（B错）在治疗克山病，治疗精神性疾病方面有应用。卧床休息（C错）不能达到治疗目的，因高血钾会导致心脏骤停，要紧急处理。预防感染（D错）不是急进性肾炎的治疗方法。","","N"],["1990-N18",40,"第一节 肾小球疾病概述","蛋白尿",1990,18,"A","","尿蛋白在+++以上，应考虑为",[["A","肾小球疾病"],["B","肾小管疾病"],["C","肾间质疾病"],["D","肾血管疾病"],["E","肾脏感染"]],"A","肾小球性蛋白尿由肾小球滤过膜的机械屏障及电荷屏障受损，滤过膜通透性增加，血浆蛋白大量进入原尿，超过肾小管重吸收能力。尿蛋白以白蛋白等中、高分子蛋白为主，定量多大于2g/24小时，多在+++以上，常见于肾小球肾炎及肾病综合征等原发性肾小球疾病，亦可见于糖尿病肾病、狼疮性肾炎等继发性肾小球疾病（A对）。肾小管疾病（B错）、肾间质疾病（C错）、肾血管疾病（D错）、肾脏感染（E错）均可出现轻度蛋白尿，但其本身肾小球病变并不严重，因此较少出现大量蛋白尿的情况即尿蛋白（+++）以上。","","N"],["1990-N19",40,"第二节 急性肾小球肾炎","急性肾小球肾炎临床表现",1990,19,"A","","对急性肾小球肾炎诊断最有意义的是",[["A","蛋白尿和透明管型"],["B","蛋白尿和脓尿"],["C","血尿和闪光细胞"],["D","血尿和红细胞管型"],["E","尿成堆白细胞和白细胞管型"]],"D","血尿常为急性肾小球肾炎起病时最早出现的肾病症状，几乎全部患者均有血尿（十版内科学P476），通常尿中的红细胞为肾小球源性，尿中红细胞多严重变形呈现为毛刺状、半月状等。此外还可见红细胞管型，为急性肾小球肾炎的重要特征。故血尿和红细胞管型对诊断急性肾小球肾炎最有意义（D对）。急性肾小球肾炎患者有轻中度蛋白尿，少数患者有大量蛋白尿，透明管型健康人尿液中可见（A错）。脓尿（B错）指尿沉渣镜检WBC＞5个/HP，提示泌尿系感染性疾病。闪光细胞（C错）为炎症中发生脂肪变的中性粒细胞，在高倍镜视野下呈布朗运动，是肾盂肾炎的诊断指标。白细胞管型（E错）见于肾盂肾炎等肾实质感染性疾病，为上尿路感染的标志物。","","N"],["1990-N20",41,"第一节 尿路感染","治愈",1990,20,"A","","急性肾盂肾炎的临床治愈标准",[["A","膀胱刺激症状消失"],["B","体温正常"],["C","尿常规正常"],["D","腰痛消失"],["E","以上都不是"]],"E","急性肾盂肾炎只有细菌检查即停药后多次尿细菌培养阴性（E对）才能认为临床治愈。膀胱刺激症状消失（A错）、体温正常（B错）、腰痛消失（D错）及尿常规正常（C错）等相关症状及实验室检查只是辅助判断标准，而非治愈标准。急性肾盂肾炎治疗不彻底时，细菌生长虽暂时被抗生素抑制，上述临床症状可暂时消失，但仍残留少量细菌，停药后细菌恢复繁殖，可导致肾盂肾炎复发。","","N"],["1990-N21",45,"第一节 慢性肾衰竭","纠正酸中毒和水、电解质紊乱",1990,21,"A","","尿毒症高钾血症最有效的治疗方法是",[["A","输入碳酸氢钠"],["B","输入钙剂"],["C","输入高渗葡萄糖加胰岛素"],["D","进行血液透析"]],"D","尿毒症高钾血症病情严重，最有效地治疗方法是进行血液透析（D对），通过与透析液进行离子交换，可迅速降低血钾浓度。输入碳酸氢钠（A错）可稀释血清钾离子浓度，又能使钾离子转入细胞内或经尿排出；输入钙剂（B错）可对抗高钾对心肌的毒性作用；输入高渗葡萄糖加胰岛素（C错）可促进钾离子向细胞内转移；口服钠型阳离子交换树脂（E错）可促进钾离子经肠道排出，以上四种方法（P516）均可用于尿毒症高血钾的治疗，但起效较慢，并不是最有效的方法。","","N"],["1990-N22",46,"第一节 贫血概述","贫血分类",1990,22,"A","","小细胞低色素性贫血见于",[["A","维生素B₁₂缺乏所致贫血"],["B","特发性血小板减少性紫癜伴急性出血"],["C","再生障碍性贫血"],["D","慢性失血性贫血"],["E","急性白血病所致贫血"]],"D","小细胞低色素性贫血指红细胞平均体积减小（＜80fl），红细胞平均血红蛋白浓度降低（＜32%）的贫血，包括缺铁性贫血、铁粒幼细胞性贫血、珠蛋白生成障碍性贫血以及慢性失血性贫血等。慢性失血性贫血（十版内科学P549）（D对）时，原料铁随红细胞的丢失而丢失，往往合并缺铁性贫血，表现为小细胞低色素性贫血。维生素B₁₂缺乏所致贫血（A错）为巨幼细胞贫血（十版内科学P552），表现为大细胞性贫血。特发性血小板减少性紫癜伴急性出血（B错）属于急性失血性贫血，表现为正细胞性贫血。再生障碍性贫血（十版内科学P555）（C错）是一种骨髓造血功能衰竭症，生成的红细胞数量下降，质量多正常，表现为正常细胞性贫血。急性白血病（十版内科学P577）（E错）时，异常白血病细胞大量增殖，反馈性抑制红系和巨核系增生，红细胞数量降低，质量正常，表现为正常细胞性贫血。","","N"],["1990-N23",56,"第二节 原发免疫性血小板减少症","血清学检查",1990,23,"A","","以下哪项不符合特发性血小板减少性紫癜",[["A","血块回缩不良"],["B","脾脏轻度肿大"],["C","出血时间延长"],["D","巨核细胞增加"],["E","Coombs试验阳性"]],"E","Coombs试验（十版内科学P566）即抗人球蛋白试验，是检测血液中温反应性抗体的一种方法，也是诊断自身免疫性溶血性贫血的重要指标，而特发性血小板减少性紫癜（ITP）患者一般不会有Coombs试验阳性（E错，为本题正确答案），但伴自身免疫性贫血（Evans综合征）患者的Coombs试验可呈阳性。血小板参与血块回缩，ITP患者血小板减少，因此血块回缩不良（A对）。ITP患者体检脾脏一般不大，但病程超过半年者，由于自身致敏的血小板经脾被破坏，脾脏可轻度肿大（B对）。出血时间（BT）是指人为刺破皮肤毛细血管后，从血液自然流出到自然停止所需的时间。它受血小板的数量和质量、毛细血管结构和功能的影响，ITP患者血小板减少，故出血时间会延长（C对）。ITP患者由于血小板减少，骨髓巨核系可代偿性增生，巨核细胞数量正常或增加（D对）。","","N"],["1990-N24",47,"第一节 缺铁性贫血","补铁治疗",1990,24,"A","","治疗缺铁性贫血的最后目标是",[["A","血红蛋白及红细胞计数恢复正常"],["B","血红蛋白及血清铁恢复正常"],["C","血红蛋白正常及补足骨髓贮存铁"],["D","红细胞形态恢复正常"],["E","血清铁及血清铁总结合力恢复正常"]],"C","缺铁性贫血表现为缺铁引起的小细胞低色素性贫血及其他贫血相关临床表现。口服铁剂治疗缺铁性贫血时，首先外周血网织红细胞增多，2周后血红蛋白浓度上升，血红蛋白恢复正常后至少持续4～6个月，待贮存铁（血清铁蛋白和骨髓小粒含铁血黄素）正常后停药。故治疗缺铁性贫血的最后目标是血红蛋白正常及补足骨髓贮存铁（C对）。","","N"],["1990-N26",52,"第三节 慢性髓系白血病","临床表现",1990,26,"A","","下列哪种疾病最易引起明显脾大",[["A","特发性血小板减少性紫癜"],["B","自身免疫性溶血性贫血"],["C","过敏性紫癜"],["D","慢性粒细胞白血病"],["E","急性白血病"]],"D","特发性血小板减少性紫癜（A错）一般不会出现脾大。自身免疫性溶血性贫血（B错）多为慢性血管外溶血，红细胞在脾脏中被破坏，可引起脾亢进、肿大，但多为轻、中度脾大。过敏性紫癜（十版内科学P620）（C错）为一种常见的血管变态反应性疾病，机体对某些致敏物质产生变态反应，导致毛细血管脆性及通透性增加，血液外渗，患者出现紫癜、黏膜及某些器官出血，很少出现脾大。慢性粒细胞白血病（D对）病程发展缓慢，脾大是其最显著的特点，多数患者有明显脾大。急性白血病（E错）患者脾肿大多为轻至中度，除CML急性变外，巨脾罕见。","","N"],["1990-N27",61,"第一节 糖尿病","基本临床表现",1990,27,"A","","某患者一日尿量在4000ml以上，尿比重1.028，下列哪种情况的可能性最大",[["A","尿崩症"],["B","慢性肾小球肾炎"],["C","糖尿病"],["D","服利尿药的作用"],["E","大量饮水后"]],"C","糖尿病症状为多尿、烦渴多饮和难于解释的体重减轻；糖尿病患者血糖升高，超过肾糖阈，出现糖尿，尿比重增高。故糖尿病尿液特点为多尿且尿比重高。该患者一日尿量4000ml以上（增多，成人正常值为1000ml～2000ml），尿比重1.028（升高，正常值范围为成人1.015～1.025，新生儿1.002～1.004），与糖尿病尿液特点相符，故该患者为糖尿的可能性最大（C对）。尿崩症（十版内科学P680）（A错）是由于抗利尿激素（ADH）缺乏或肾脏对ADH不敏感，致肾小管重吸收水的功能障碍，从而引起多尿、烦渴、多饮和低比重尿为特征的一组综合征。慢性肾小球肾炎（十版内科学P487）（B错）病情迁延，病变缓慢进展，可有不同程度的肾功能衰退，肾功能减退时尿量减少，尿比重降低。利尿药（D错）作用于肾脏，可抑制肾小管对钠的重吸收，并进而减少对水的重吸收，导致尿比重降低（但袢利尿剂作用于髄袢升支粗段，抑制肾小管浓缩和稀释功能，排出的尿尿比重接近正常）。大量饮水后（E错）血液被稀释，血浆晶体渗透压降低，引起抗利尿激素分泌减少，肾远曲小管和集合管对水的重吸收减少，导致尿比重降低。","","N"],["1990-N28",59,"第一节 甲状腺功能亢进症","消化系统",1990,28,"A","","甲亢病人出现大便次数增多或腹泻主要是因为",[["A","胃酸缺乏"],["B","肠道炎症"],["C","肠蠕动增强"],["D","结肠过敏"],["E","小肠吸收不良"]],"C","甲亢是由多种原因引起的甲状腺激素分泌过多所致的一组常见内分泌疾病。由于甲状腺素增多，肠蠕动增强（C对），肠道来不及吸收各类营养物质，导致大便溏稀，次数增加，甚至呈顽固性腹泻。胃酸缺乏发病主要与慢性胃炎、长期服用刺激性食物和药物、十二指肠液的反流、免疫因素与感染相关（A错）。肠道炎症发病主要与病菌感染、过敏反应、急性肠炎、遗传、滥用抗生素相关（B错）。结肠过敏多与精神、饮食相关，每当情绪波动或吃了某种食物后，可突然出现腹痛、肠鸣、腹泻，泻后痛减，便中带有大量的黏液，或便秘腹泻交替（D错）。甲状腺素可以促进小肠吸收糖，加速糖的氧化利用和肝糖原分解等（E错）。","","N"],["1990-N29",59,"第一节 甲状腺功能亢进症","甲亢¹³¹I并发症",1990,29,"A","","用¹³¹I治疗甲状腺功能亢进症，最常见的并发症是",[["A","甲状腺癌变"],["B","血小板减少"],["C","甲状腺功能减退症"],["D","甲状腺功能亢进危象"],["E","白血病"]],"C","¹³¹I治疗甲亢是利用甲状腺高度摄取和浓集碘的能力及¹³¹I释放出β射线对甲状腺的生物效应，破坏滤泡上皮而减少TH（甲状腺素）分泌。经¹³¹I治疗后，近期内可出现一过性甲减（C对）、一过性甲亢或甲亢复发、个别可诱发甲状腺危象（D错）、放射性甲状腺炎、局部疼痛等，通常能自行恢复。¹³¹I治疗甲亢只作用于甲状腺，一般不影响白细胞、红细胞和血小板（B错）。十四版实用内科学P1219页观点认为，半个世纪的¹³¹I治疗经验已经否定了¹³¹I治疗可增加甲状腺肿瘤（A错）、白血病（E错）等恶性肿瘤发生率的观点。","","N"],["1990-N71",36,"第一节 原发性肝癌","原发性肝癌诊断",1990,71,"A","","男，40岁，腹胀、纳差3个月，颈部有两个蜘蛛痣，肝肋下4cm，质硬，腹水中量。抽出淡红色腹水少许，比重1.013。诊断可能是",[["A","肝硬化"],["B","门静脉血栓形成"],["C","结核性腹膜炎"],["D","原发性肝癌"],["E","胰源性腹水"]],"D","患者中年男性，腹胀、纳差（消化吸收不良表现），颈部出现蜘蛛痣（肝功能减退表现），腹水中量（肝硬化失代偿期最突出的临床表现），以上均为肝硬化征象。又患者肝大，质硬（原发性肝癌肝脏呈进行性增大，质地坚硬），抽出血性腹水（肝癌侵犯肝包膜或向腹腔内破溃可引起血性腹水），故该患者可考虑为在失代偿期肝硬化基础上并发原发性肝癌（D对）。肝硬化（A错）出现肝功能减退及中量腹水时，多已进入失代偿期，肝脏缩小而不会肿大，且血性腹水少见。门静脉血栓形成（B错）为肝硬化失代偿期门静脉高压的较常见并发症，当其呈急性或亚急性发展时，可出现血性腹水，但其肝脏应该缩小，不会肿大。结核性腹膜炎（C错）可出现血性腹水，但不会出现蜘蛛痣及肝肿大。","","N"],["1990-N72",21,"第三节 二尖瓣狭窄","直视分离术",1990,72,"A","","患者女性，25岁，心悸，气促。反复咯血10年。体检：梨形心影，心尖区有舒张期隆隆样杂音，肺动脉瓣第二音亢进，心尖区第一心音亢进，有开瓣音，宜采用",[["A","洋地黄"],["B","利尿剂"],["C","二尖瓣分离术"],["D","二尖瓣置换术"],["E","垂体后叶素止血"]],"C","患者梨形心影，心尖区有舒张期隆隆样杂音，初步诊断为风湿性心脏病伴二尖瓣狭窄。肺动脉瓣第二音亢进，提示肺动脉高压，应及早进行干预。心尖区可闻及开瓣音，提示瓣膜功能尚好，此时宜采用经皮二尖瓣分离术（C对），术后患者症状及血流动力学可迅速得到改善，严重并发症少见，手术死亡率小于0.5%。二尖瓣置换术（D错）适用于狭窄严重而不宜行瓣膜切开术和球囊扩张术的患者，其术后并发症及死亡率均高于分离术。正性肌力药洋地黄（A错）对改善心功能无益，甚至因加强右心收缩能力可加重肺水肿及呼吸困难。利尿剂（B错）可用于治疗二尖瓣狭窄引起的大咯血及肺水肿的救治，但无法根治。垂体后叶素收缩血管（E错）用于大咯血的救治，但无法根治。","","N"],["1990-N73",10,"第三节 慢性肺源性心脏病","慢性肺源性心脏病诊断",1990,73,"A","","女，60岁，患咳嗽、咳痰已8～9年。入院查体：可平卧，桶状胸，两肺少量湿啰音，剑突下可见收缩期搏动。三尖瓣区可听见收缩期杂音，肝脾不大，下肢无浮肿，其诊断可能为",[["A","慢性支气管炎"],["B","慢性支气管炎+肺气肿"],["C","慢性支气管炎+肺气肿+肺心病代偿期"],["D","慢性支气管炎+肺心病右心衰竭"],["E","以上都不是"]],"C","患者老年女性，慢性咳嗽、咳痰（咳嗽、咳痰每年发病持续3个月，连续2年或2年以上为慢性支气管炎的典型临床表现），两肺少量湿啰音，可以推断患者有慢性支气管炎。查体示桶状胸，为肺气肿特征性的体征。剑突下可见收缩期搏动，三尖瓣区可闻及收缩期杂音，提示为右心室肥厚的临床征象。慢性支气管炎肺气肿患者出现右心室肥厚，应考虑已合并肺心病。患者可平卧、肝脾不大、下肢无水肿，目前尚无右心功能衰竭的症状和体征，心功能属代偿期，所以诊断为慢性支气管炎+肺气肿+肺心病代偿期（C对）。","","N"],["1990-N74",40,"第七节 慢性肾小球肾炎","慢性肾小球肾炎实验室检查",1990,74,"A","","慢性肾炎患者，近10天来出现厌食、恶心、乏力，来急诊，首先宜查",[["A","内生肌酐清除率"],["B","HbsAg"],["C","钡餐检查"],["D","血尿素氮、肌酐，二氧化碳结合力"],["E","不需化验检查"]],"D","慢性肾炎患者，近10天来加重，应考虑肾病病情是否恶化，急诊宜先查肾功能，首选检查指标为血尿素氮、肌酐和二氧化碳结合力（D对），以明确有无肾衰竭和酸中毒，其他选项检查可以做，但不是主要的。内生肌酐清除率（A错）可用于慢性肾衰的分期，但不是肾功能检查的首选指标。乙肝表面抗原（HBsAg）（B错）是乙肝病毒的外壳蛋白，其出现常提示乙型病毒性肝炎活动期。钡餐检查（C错）主要用于消化道病变的检查。","","N"],["1990-N75",49,"第一节 再生障碍性贫血","AA骨髓象",1990,75,"A","","女性，22岁，贫血，鼻出血，发热，全血细胞减少，白细胞分类未见到幼稚细胞。为鉴别非白血性白血病与再生障碍性贫血，主要需要检查",[["A","肝、脾、淋巴结是否肿大"],["B","骨髓象中原始和幼稚细胞多少"],["C","网织红细胞多少"],["D","皮肤及齿龈是否浸润"],["E","反复检查血象"]],"B","再生障碍性贫血通常指原发性骨髓造血功能衰竭症，骨髓象示多部位骨髓增生减低，无原始细胞增生；非白血性白血病（白细胞不增多性白血病）是一类造血干细胞的恶性克隆性疾病，骨髓象示有核细胞显著增生，以原始细胞为主。故骨髓象中原始和幼稚细胞多少（B对）为鉴别两者最重要的检查。肝、脾、淋巴结肿大与皮肤、齿龈浸润属白血病细胞增殖浸润的表现（十版内科学P579），再生障碍性贫血无以上表现；非白血性白血病外周血白细胞不增多，一般也无以上表现，故肝、脾、淋巴结是否肿大（A错）和皮肤及齿龈是否浸润（D错）不具有鉴别意义。两者网织红细胞计数（C错）均降低，不具有鉴别意义。再生障碍性贫血外周血象表现为全血细胞减少，一般无原始细胞；非白血性白血病外周血象表现为全血细胞减少，很难找到原始细胞。两者血象无明显差异，故反复检查血象（E错）不具有鉴别意义。","","N"],["1990-N76",61,"第三节 高渗高血糖综合征","高渗高血糖综合征诊断",1990,76,"A","","男性，60岁，有高血压5年，1周来咳嗽发热，今日被家人发现神志不清，送来急诊。检查：意识不清，有癫痫伴抽搐，肺内湿啰音，心率110/分，BP130/60mmHg，左侧巴彬斯基征可疑，WBC计数：3.5×10⁹/L，尿糖（++++），酮体（-）。此例昏迷最可能的原因是",[["A","脑血管意外"],["B","高渗性非酮症性糖尿病昏迷"],["C","糖尿病酮症酸中毒昏迷"],["D","感染中毒性脑病"],["E","以上都不是"]],"B","该老年患者因咳嗽发热（诱因）出现神志不清伴癫痫和抽搐（高渗高血糖综合征可有不同程度的意识障碍或昏迷），左侧巴彬斯基征可疑（高渗高血糖综合征可有神经系统损害的定位体征）。尿糖（++++）为强阳性，酮体阴性（高渗高血糖综合征尿糖为强阳性，尿酮体阴性或弱阳性）。据此，此例昏迷最可能的原因是高渗性非酮症性糖尿病昏迷（B对）。脑血管意外（A错）虽可表现为昏迷，但常有偏瘫等表现，与本例不符。糖尿病酮症酸中毒昏迷（C错）尿糖强阳性、酮体阳性，常表现为酸中毒大呼吸（Kussmaul呼吸），呼吸频率增快，呼吸深大，呼吸中可有烂苹果味，与本例不符。感染中毒性脑病（D错）（急性中毒性脑病）多见于2～10岁儿童，常有高热的急性感染性史，并出现呕吐，脑脊液压力增高，与本例不符。","","N"],["1990-N81",18,"第一节 原发性高血压","高血压急症和亚急症概念",1990,81,"B","","急进型高血压病死因多为",[["A","脑血管意外"],["B","心肌梗死"],["C","心力衰竭"],["D","尿毒症"],["E","休克"]],"D","急进型高血压是指病情一开始即为急剧进展，或经数年的缓慢过程后突然迅速发展，导致细小动脉发生纤维素样坏死，以肾脏的改变最突出，病情进展迅速，如不及时有效降压治疗，预后很差。肾衰竭（引发尿毒症）是急进型高血压的主要死亡原因（D对）。","","N"],["1990-N82",18,"第一节 原发性高血压","脑血管病",1990,82,"B","","我国高血压死因多为",[["A","脑血管意外"],["B","心肌梗死"],["C","心力衰竭"],["D","尿毒症"],["E","休克"]],"A","高血压病的并发症主要发生在心、脑、肾（十版内科学P263），并可导致脑血管意外（A）、心肌梗死（B）、心力衰竭（C）、尿毒症（D）、休克（E）等而死亡。但目前在我国，高血压病所致的脑血管意外（A对）仍是引起患者死亡的最常见的原因。","","N"],["1990-N93",39,"第一节 总论","血清肌酐检测",1990,93,"B","","全血NPN（非蛋白氮）的正常值范围是",[["A","20～35mg/dl"],["B","65～80mg/dl"],["C","80～120mg/dl"],["D","110～200mg/dl"],["E","30～40mg/dl"]],"A","血液中除蛋白质外其他含氮化合物中的氮总量称为非蛋白氮（NPN），包括尿素、氨基酸、肌酸、尿酸和氨等物质中的氮含量。正常人血中NPN为20～35mg/dl（A对），其中尿素氮为10～15mg/dl。","","N"],["1990-N94",61,"第一节 糖尿病","血糖测定和口服葡萄糖耐量试验",1990,94,"B","","全血血糖的正常值范围是",[["A","20～35mg%"],["B","65～80mg%"],["C","80～120mg%"],["D","110～200mg%"],["E","30～40mg%"]],"C","血糖值单位mg%是指每一百毫升血液中血糖的含量，也就是mg/dl。正常人空腹时血浆血糖浓度在3.9～6.0mmol/L（70～108mg/dl）为正常，此为九版内科学最新数据，由于血浆血糖比全血血糖高15%，所以全血血糖=（70～108mg/dl）/115%=60.9～93.9mg/dl，此题无正确答案，但当年给的正确答案为C选项。","","N"],["1990-N97",15,"第二节 慢性心力衰竭","利尿剂",1990,97,"C","","速尿",[["A","减轻心脏前负荷"],["B","减轻心脏后负荷"],["C","二者均减轻"],["D","二者均不减轻"]],"A","速尿（即呋塞米）为袢利尿剂，作用于髓袢升支粗段的Na⁺-K⁺-2Cl⁻共转运子，降低肾脏的浓缩及稀释功能，患者排出大量接近于等渗的尿液，液体潴留减轻，循环血量降低的同时回心血量减少，心脏容量负荷减轻，即前负荷减轻（A对）。心脏后负荷（B对）是指心肌收缩之后所遇到的阻力或负荷，又称压力负荷，主要与外周血管阻力有关，最新版教材中指出利尿剂有降低外周血管阻力的效果。考虑到本题目出题时间，原答案为A，但根据最新教材观点AB均对，应选择C。","","N"],["1990-N98",18,"第一节 原发性高血压","硝普钠",1990,98,"C","","硝普钠",[["A","减轻心脏前负荷"],["B","减轻心脏后负荷"],["C","二者均减轻"],["D","二者均不减轻"]],"C","硝普钠对直接作用于血管平滑肌，使动、静脉血管均扩张，使心脏前、后负荷均减低（C对），为强效血管扩张剂。","","N"],["1990-N99",4,"第二节细菌性肺炎","肺炎链球菌肺炎临床表现",1990,99,"C","","肺炎球菌肺炎",[["A","起病急骤，寒战、高热"],["B","经治疗后肺部病变完全消退，肺组织恢复正常"],["C","两者都有"],["D","两者都无"]],"C","肺炎链球菌肺炎是由肺炎链球菌或称肺炎球菌所引起的肺炎，通常急骤起病，以高热、寒战、咳嗽、血痰及胸痛为特征（A对），肺炎球菌不产生毒素，不引起组织坏死或形成空洞，病变消散后肺泡内纤维蛋白完全吸收，肺组织多无结构破坏，不留纤维瘢痕（B对）。本题AB均对，正确答案为C。","","N"],["1990-N100",6,"第一节 肺结核","肺结核临床表现",1990,100,"C","","干酪性（结核性）肺炎",[["A","起病急骤，寒战、高热"],["B","经治疗后肺部病变完全消退，肺组织恢复正常"],["C","两者都有"],["D","两者都无"]],"A","干酪性肺炎又称结核性大叶性肺炎，属于继发性活动性肺结核，是一种急性严重的类型，多发生于虚弱而且受大量结核杆菌感染的人。病情发展快，症状十分严重，很快发生衰竭。大叶性干酪性肺炎多见于婴幼儿，小叶性者则多见于较大儿童。前者起病多较急，有高热和严重中毒症状（A对），后者可较缓，有长期低热和慢性中毒症状，多有咳嗽、咳痰甚至咯血。病程严重，预后不佳，如能及时积极进行抗结核药物治疗，多数病例可吸收好转，但肺部病变不能完全消退，肺组织最终钙化（B错）而治愈。","","N"],["1990-N101",40,"第七节 慢性肾小球肾炎","慢性肾小球肾炎实验室检查",1990,101,"C","","慢性肾小球肾炎（急性发作）",[["A","红细胞管型"],["B","PSP降低"],["C","二者皆有"],["D","二者皆无"]],"C","PSP是指尿酚红排泄试验，酚红经静脉注射到人体后，绝大部分会经肾小管分泌，排出体外。当肾小管出现病变时，酚红指示剂的排出量会减少。慢性肾小球肾炎在病变进展至晚期时，出现不同程度的肾小球硬化，相应肾单位的肾小管萎缩、肾间质纤维化，故PSP下降（B对）。慢性肾小球肾炎急性发作会出现血尿，可有红细胞管型（A对）。本题AB均对，正确答案为C。","","N"],["1990-N102",41,"第一节 尿路感染","尿常规检查",1990,102,"C","","慢性肾盂肾炎",[["A","红细胞管型"],["B","PSP降低"],["C","二者皆有"],["D","二者皆无"]],"B","PSP是指尿酚红排泄试验，酚红经静脉注射到人体后，绝大部分会经肾小管分泌，排出体外。当肾小管出现病变时，酚红指示剂的排出量会减少。慢性肾盂肾炎病变主要累及肾盂及肾小管，肾小管分泌排泄功能受损，故PSP下降（B对）。红细胞管型多发生于有血尿的弥漫性肾小球肾炎，慢性肾盂肾炎患者血尿较少见（A错）。","","N"],["1990-N113",28,"第一节 消化性溃疡","药物",1990,113,"X","","能造成消化溃疡的药物是",[["A","水杨酸盐"],["B","保泰松"],["C","消炎痛"],["D","甲苯磺脲"]],"ABC","水杨酸盐（A对）、保泰松（B对）和消炎痛（吲哚美辛）（C对）都属于NSAIDs，NSAIDs（非甾体抗炎药）是非特异性环氧合酶（COX）抑制剂，由于非特异性地抑制了结构型COX-1，导致维持黏膜正常再生的前列腺素E合成不足，黏膜修复障碍，出现糜烂出血，可致消化性溃疡（十版内科学P369）。除了NSAIDs之外，其他可导致消化性溃疡的药物还有糖皮质激素、氯吡格雷、化疗药物、双磷酸盐、西罗莫司等。甲苯磺脲（D错）为磺脲类口服降血糖药，不会导致消化性溃疡。","","N"],["1990-N114",35,"第一节 肝硬化","腹腔积液",1990,114,"X","","肝硬化腹水的治疗一般宜采用",[["A","强烈的利尿方法"],["B","保钾与排钾利尿剂可配合使用"],["C","放腹水，每周1～2次"],["D","卧床休息低钠饮食"]],"BD","肝硬化腹水的一般治疗措施有：1.限制钠和水的摄入：限钠饮食和卧床休息是腹水的基础治疗（D对）；2.利尿剂：临床上常联合使用保钾及排钾利尿剂（B对），强烈的利尿方法会导致水电解质紊乱，严重者诱发肝性脑病和肝肾综合征，故而不采取（A错）；3.提高血浆胶体渗透压。放腹水治疗肝硬化腹水，该方法缓解时间短，易于诱发肝肾综合征、肝性脑病等并发症，主要用于不具备TIPS技术、对TIPS禁忌及失去TIPS机会时顽固性腹水的姑息治疗，而不是肝硬化腹水的一般治疗措施（C错）。","","N"],["1990-N115",36,"第一节 原发性肝癌","甲胎蛋白",1990,115,"X","","可出现甲胎蛋白增高的是",[["A","肝炎"],["B","妊娠妇女"],["C","肝硬化"],["D","生殖腺胚胎肿瘤"]],"ABCD","甲胎蛋白（AFP）是在胎儿早期由肝脏和卵黄囊合成的一种血清糖蛋白，出生后，AFP的合成受抑制，当肝细胞或生殖腺胚胎组织发生恶性病变时，AFP的合成又重新开始，以致血中AFP含量明显升高。所以AFP的浓度监测对诊断肝细胞癌及滋养细胞恶性肿瘤有重要的临床价值。AFP升高可见于妊娠妇女（B对）、生殖腺胚胎瘤（D对）、病毒性肝炎（A对）、肝硬化（C对）、以及原发性肝细胞癌等（九版诊断学P417）。","","N"],["1990-N116",15,"第二节 慢性心力衰竭","左心衰竭症状",1990,116,"X","","左心功能不全的表现",[["A","呼吸困难"],["B","咳嗽咯血"],["C","乏力、紫绀"],["D","肝颈静脉反流征阳性"]],"ABC","左心功能不全以肺循环淤血及心排血量降低为主要表现。肺循环淤血可致呼吸困难（A对）、咳嗽咯血（B对）等。同时，因左心舒张-收缩功能障碍，心排血量降低可致乏力、发绀（C对）及代偿性心率加快等症状。肝颈静脉反流征阳性（D错）是指当右心衰竭引起肝淤血肿大时用手压迫肿大肝脏可使颈静脉怒张更明显。其发生机制是因压迫淤血的肝脏使回心血量增加，已充血右心房不能接受回心血液而使颈静脉压被迫上升所致，多见于右心衰竭。","","N"],["1990-N117",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞体征",1990,117,"X","","奇脉可见于",[["A","缩窄性心包炎"],["B","心包积液"],["C","限制型心肌病"],["D","左心衰竭"]],"AB","当存在大量心包积液（B对）或缩窄性心包炎（A对）时，吸气时右心舒张受限，回心血量减少而影响右心排血量，右心室排入肺循环的血量相应减少；另一方面肺循环受吸气时胸腔负压的影响，肺血管扩张，致使肺静脉回流至左心房血量减少，因而左心室排血减少。这些因素共同引起吸气时脉搏减弱，甚至不能触及，出现奇脉。限制型心肌病（C错）是以心室壁僵硬增加、舒张功能降低、充盈受限而产生临床右心衰症状为特征的一类心肌病。患者收缩功能多正常，故心排量无明显下降，一般不会出现奇脉。左心衰（D错）时可出现强弱交替的心室收缩，导致交替脉。","","N"],["1990-N118",23,"第一节 感染性心内膜炎","具体原则",1990,118,"X","","亚急性感染性心内膜炎时抗生素给药的一般原则是",[["A","选用杀菌抗生素"],["B","抗生素要早期、足量，疗程够长"],["C","肠道外给药"],["D","首选红霉素"]],"ABC","亚急性感染性心内膜炎须选用杀菌抗生素（A对），且药物应用宜早期、足量，疗程够长（B对），以完全消灭藏于赘生物内的致病菌，减少心脏损伤。感染性心内膜炎抗生素治疗应以静脉给药为主（C对），以维持高而稳定的血药浓度，充分发挥杀菌效力。亚急性感染性心内膜炎的常见致病菌为链球菌，治疗以青霉素为主或加庆大霉素（D错），对不能耐受β-内酰胺酶者可选万古霉素联合环丙沙星。红霉素为大环内酯类药物，通常为抑菌作用，仅在高浓度时有一定杀菌作用，且红霉素的抗菌效力不及青霉素。","","N"],["1990-N119",17,"第四节 急性冠状综合征","急性ST段抬高型心肌梗死诊断",1990,119,"X","","老年人突然发生以下哪种或哪几种情况须做心电图以排除急性心肌梗塞",[["A","休克"],["B","以前无心脏病史突然发生心力衰竭"],["C","严重心律失常"],["D","不明原因的上腹痛或恶心呕吐"]],"ABCD","对老年患者，突然发生休克（A对）、心力衰竭而原因未明（B对）、严重心律失常（C对），或突然发生较重而持久的胸闷或胸痛者，都应考虑急性心肌梗塞（AMI）的可能，需短期内进行心电图明确诊断。老年人急性心梗可在临床症状方面表现不典型，可无心前区痛、胸骨后疼痛或疼痛轻微而以胃肠道症状（不明原因的上腹痛或恶心呕吐）（D对）为主要表现，需进行心电图明确诊断。","","N"],["1990-N120",21,"第四节 二尖瓣反流","二尖瓣反流临床表现",1990,120,"X","","心尖区收缩期吹风样杂音可见于",[["A","高血压性心脏病"],["B","严重贫血"],["C","风湿性二尖瓣关闭不全"],["D","健康青少年"]],"ABCD","高血压性心脏病（A对）引起左心室肥大及二尖瓣环扩大，形成二尖瓣相对性关闭不全，心尖区可出现收缩期吹风样杂音。严重贫血（B对）可引起贫血性心脏病，心脏代偿性扩大，导致二尖瓣相对性关闭不全，出现心尖区收缩期吹风样杂音。风湿性二尖瓣关闭不全（C对）可引起心尖区收缩期杂音。健康青少年（D对）在运动、情绪激动或发热时，由于心输出量增加，左右心室将血液排入主或肺动脉时产生紊乱的血流亦可导致心尖区收缩期吹风样杂音。","","N"],["1990-N121",5,"第一节 肺脓肿","肺脓肿诊断",1990,121,"X","","肺脓肿的诊断依据是",[["A","突然起病，畏寒高热"],["B","咳嗽，大量脓痰，伴有咯血"],["C","白细胞总数及中性粒细胞增多"],["D","胸片有大片浓密阴影，中有空洞形成并有液平"]],"ABCD","急性吸入性肺脓肿起病急骤，患者畏寒、发热（A对），体温可高达39℃～40℃，伴咳嗽、咳黏液痰或黏液脓痰，约有1/3患者有不同程度的咯血（B对）。血液检查可有白细胞总数增高，中性粒细胞在90%以上，核左移明显（C对）。X线示胸片有大片浓密阴影，肺组织坏死、肺脓肿形成后，脓液经支气管排出形成空洞并有液平面（D对）。","","N"],["1990-N122",6,"第一节 肺结核","有无活动性",1990,122,"X","","活动性肺结核指的是",[["A","有结核毒性症状"],["B","痰菌阳性"],["C","X线病灶具有炎性成份或病灶正在进展"],["D","X线示病灶在好转阶段"]],"ABC","结核病活动时，临床表现为结核毒性症状，如低热、盗汗、乏力、体重减轻、食欲减退等（A对）；痰菌检查可呈阳性（B对）；X线胸片可出现浸润性改变，如云雾状、密度较淡、边缘模糊等炎性改变，或在胸片中可见病灶正在进展，如病灶中心溶解，出现空洞，或出现播散病灶（C对）。当X线显示病灶在好转阶段时（D错），一般结核病已处于相对静止期，而非活动期。","","N"],["1990-N123",11,"第一节 胸腔积液","恶性胸腔积液",1990,123,"X","","血性胸腔积液可发生于",[["A","肿瘤"],["B","肺梗塞"],["C","肺结核"],["D","右心衰竭"]],"ABC","血性胸液呈程度不同的洗肉水样或静脉血样，多见于肿瘤（A对）、结核（C对）和肺栓塞（B对）。右心衰竭（十版内科学P127）（D错）的胸腔积液为胸膜内毛细血管静水压升高引起，为漏出液。漏出液（十版内科学P130）透明清亮，静置不凝固，比重＜1.016～1.018。","","N"],["1990-N124",10,"第三节 慢性肺源性心脏病","右心衰竭",1990,124,"X","","慢性肺心病缓解期可有哪些表现",[["A","CO₂潴留，PaCO₂升高"],["B","肺动脉高压"],["C","pH值下降"],["D","右心室肥厚"]],"BD","慢性肺心病时，肺循环阻力增加导致肺动脉高压，右心发挥其代偿功能，以克服升高的肺动脉阻力而发生右心室肥厚（P110），此为慢性肺心病的基本病变。如病情进展，还可发生CO₂潴留，PaCO₂升高及pH值下降。当缓解期时，病情已被控制，CO₂潴留消失，PaCO₂恢复正常（A错），pH值正常（C错），但由于长期慢性疾病所造成的肺动脉高压及右心室肥厚不能恢复，故慢性肺心病缓解期可有肺动脉高压（B对）及右心室肥厚（D对）。","","N"],["1990-N125",40,"第二节 急性肾小球肾炎","急性肾小球肾炎临床表现",1990,125,"X","","急性肾炎的严重并发症有",[["A","心力衰竭"],["B","高血压脑病"],["C","肾功能衰竭"],["D","休克"]],"ABC","在急性肾小球肾炎时，由于水钠潴留、血容量增加及高血压，肺循环淤血，可出现急性充血性心力衰竭（A对）。严重高血压可导致高血压脑病（B对），常见症状是剧烈头痛及喷射状呕吐，继之出现视力障碍、意识模糊、嗜睡，并可发生阵发性惊厥或癫痫样发作如出现抽搐、神志不清等。急性肾小球肾炎急性期时，肾小球系膜细胞及内皮细胞大量增殖，肾脏血流量减少，肾小球滤过率降低，患者可出现少尿或无尿，蛋白质分解产物尿素氮等体内代谢产物大量滞留血中，可出现急性肾衰竭甚至尿毒症（C对）。患者虽可出现急性充血性心力衰竭，但由于血容量增多，血压多不会下降，故一般不会出现休克（D错）。","","N"],["1990-N126",41,"第一节 尿路感染","尿路感染并发症",1990,126,"X","","肾盂肾炎可并发",[["A","肾盂积脓与肾周围脓肿"],["B","败血症与休克"],["C","肾小管性酸中毒"],["D","肾功能衰竭"]],"ABCD","肾盂肾炎在局部迁延不愈可导致肾盂积脓，在伴有糖尿病及尿路结石的患者可向周围扩展，导致肾周围脓肿（A对）。肾盂肾炎的致病菌多是革兰阴性杆菌，尤以大肠杆菌常见，在部分抵抗力较低的患者，细菌可侵入血液，引起败血症与休克（B对）。肾盂肾炎可累及邻近肾髓质中的肾小管，出现肾小管萎缩及肾间质淋巴-单核细胞浸润等慢性炎症表现，导致肾小管功能受损，肾小管分泌氢离子和（或）重吸收碳酸氢根离子障碍而产生肾小管酸中毒（C对）。慢性肾盂肾炎晚期可出现肾小球硬化，导致肾小球滤过功能受损，出现肾功能衰竭（D对）。","","N"],["1990-N127",41,"第一节 尿路感染","肾盂肾炎",1990,127,"X","","急性肾盂肾炎治疗应该是",[["A","反复和轮替长期使用各种抗生素"],["B","用药48小时无效，应考虑换药"],["C","不宜选用庆大霉素"],["D","治疗应在尿常规和尿培养后立即开始"]],"D","首次发生的急性肾盂肾炎，在留取尿细菌检查标本后应立即开始治疗（D对）。若治疗停药6周内数次尿细菌培养阴性，就视为临床治愈，不需要反复轮替长期使用各种抗生素（A错）。治疗72小时无好转，应按药敏结果更换抗生素（B错）。首次发生的急性肾盂肾炎的致病菌80%为大肠埃希菌，属革兰阴性杆菌。庆大霉素为氨基糖苷类抗生素，对革兰阴性杆菌有强大的抗菌活性，24小时内有40%～65%以原形经尿液排出，在尿液中的药物浓度高，可用于治疗急性肾盂肾炎（C对），但该药肾毒性较大，需慎用。本题CD选项均正确，但当年给的参考答案为D选项。","","N"],["1990-N128",45,"第一节 慢性肾衰竭","水、电解质代谢紊乱",1990,128,"X","","慢性尿毒症时，常有以下改变",[["A","代谢性酸中毒"],["B","高钙血症"],["C","贫血"],["D","低磷血症"]],"AC","慢性肾衰竭时，肾小管泌氢障碍或碳酸氢根离子重吸收能力下降，可引起代谢性酸中毒（A对）；肾组织分泌的促红细胞生成素减少，从而导致肾性贫血（C对）。慢性肾衰竭患者尿磷排出减少，可致血磷升高（D错）；低钙血症（B错）与钙摄入不足、活性维生素D缺乏、高磷血症、代谢性酸中毒等因素有关。","","N"],["1990-N129",50,"第一节 溶血性贫血概述","溶血性贫血临床表现",1990,129,"X","","血管外溶血常表现为",[["A","起病较缓慢"],["B","脾脏常肿大"],["C","部分病人切脾可有效"],["D","多有血红蛋白尿"]],"ABC","血管外溶血指红细胞被脾脏等单核-巨噬细胞系统吞噬消化，释出的血红蛋白分解为珠蛋白和血红素，后者被分解为铁和卟啉，卟啉进一步分解为游离胆红素。血管外溶血一般呈慢性溶血过程，起病较缓慢（A对），脾脏中的单核-巨噬细胞系统的亢进以及髓外造血可致肝、脾大（B对），部分患者切脾可有效（C对）。血管外溶血一般无血红蛋白尿（D错），血红蛋白尿是血管内溶血的特点。","","N"],["1990-N130",47,"第一节 缺铁性贫血","补铁治疗",1990,130,"X","","应用铁注射剂时，应注意下列哪些事项",[["A","深部肌内注射"],["B","总剂量应精确计算"],["C","过敏性休克的可能性"],["D","首次用总量的1/2"]],"ABC","铁剂注射应深部肌内注射（A对），以减少过敏等反应。铁剂的总剂量应精确计算（B对），剂量少则疗效差，而过量会影响脏器功能，计算公式为：（需达到的血红蛋白浓度－患者的血红蛋白浓度）×0.33×患者体重（kg）。铁剂对机体来说是异物，不同人群的耐受力不同，有导致过敏性休克的可能性，应注意预防（C对）。在用铁剂进行治疗时，首次给药应该用0.5ml作为试验剂量，而不是首次用总量的1/2（D错），1小时后无过敏反应可给足量治疗。","","N"],["1990-N131",50,"第一节 溶血性贫血概述","溶血性贫血实验室检查",1990,131,"X","","证实有无血管内溶血的试验是",[["A","高铁血红蛋白测定"],["B","血浆游离血红蛋白测定"],["C","尿含铁血黄素试验（Rous试验）"],["D","尿液中尿胆原含量测定"]],"ABC","高铁血红蛋白测定可证实血管内溶血（A对）：血管内溶血时，破碎后的红细胞释放血红蛋白，当血红蛋白过多超过结合珠蛋白结合能力时，以游离状态存在，血浆中游离血红蛋白中的亚铁离子易被氧化成高铁离子；而血管外溶血时，血浆中血红蛋白以结合体状态存在，血红蛋白不易被氧化为高铁血红蛋白（十三版实用内科学P2442）。血浆游离血红蛋白可证实有血管内溶血（B对）：血管内溶血时红细胞在血液循环中被破坏，释放出血红蛋白，当血红蛋白过多超过结合珠蛋白结合能力时，以游离状态存在；而血管外溶血时红细胞是经过脾脏的单核-巨噬细胞系统被吞噬处理的，一般没有游离的血红蛋白。Rous试验（C对）即尿含铁血黄素试验，原理为血红蛋白通过肾滤过，部分铁离子以含铁血黄素的形式随尿液排出，在酸性环境下产生普鲁士蓝色的亚铁氰化铁沉淀（蓝色颗粒），可证实血管内溶血：血管内溶血时，血浆中有游离血红蛋白，Rous试验阳性；血管外溶血时，血浆中一般没有游离血红蛋白，Rous试验阴性。尿液中尿胆原含量测定（D错）证实血管外溶血（十版内科学P560）：血管外溶血中，红细胞通过单核巨噬细胞系统遭到破坏而生成的血红素，全部转化间接胆红素，再经过肝脏转化为直接胆红素，随胆汁排入肠道，继而在肠道菌作用下生成胆素原，经肠肝循环再次进入血液，经肾排出形成尿胆原，从而尿胆原增多，呈强阳性；而血管内溶血时，红细胞遭到破坏生成的血红蛋白，大部分经肾脏排出，小部分经肝脏代谢生成胆红素，虽尿胆原也可增加，但为少量增加，不会呈强阳性。","","N"],["1990-N133",59,"第一节 甲状腺功能亢进症","甲状腺危象",1990,133,"X","","诱发甲状腺危象的因素主要为",[["A","甲亢治疗不当"],["B","感染"],["C","手术"],["D","劳累，精神创伤"]],"ABCD","甲状腺危象，是甲状腺毒症急性加重的一个综合征，发生原因可能与循环内甲状腺激素水平增高有关。它是甲亢严重表现，可危及生命。多发生于未积极治疗或甲亢治疗不当的患者（A对），主要诱因为感染（B对）、精神创伤、劳累（D对）、高温、饥饿、心力衰竭、手术（C对））、不适当地停用碘剂及甲状腺手术前准备不充分等。","","N"],["1990-N134",59,"第一节 甲状腺功能亢进症","甲状腺危象的治疗",1990,134,"X","","治疗甲状腺危象时宜采用",[["A","大量抗甲状腺药物"],["B","复方碘液"],["C","β肾上腺素能受体阻滞剂"],["D","肾上腺皮质激素"]],"ABCD","甲状腺危象，是甲状腺毒症急性加重的一个综合征，为甲状腺素过量释放引起暴发性肾上腺素能兴奋现象。大剂量抗甲状腺药（PTU）可以减少甲状腺素的生物合成并能抑制外周组织T₄向T₃转换（A对）。大剂量碘（复方碘液）能抑制甲状腺激素的释放，还能抑制促甲状腺激素作用（B对）。β肾上腺素能受体阻滞剂通过阻断β受体而改善甲亢所致的交感神经激活症状，使体内甲状腺激素作用减弱，此外β受体拮抗剂可抑制T₄向T₃转化（C对）。甲亢患者糖皮质激素代谢加速，肾上腺存在潜在的储备功能不足。甲亢危象时糖皮质激素的需要量增加，对有高热或休克者应加用糖皮质激素（D对），可抑制甲状腺素的释放，并抑制外周组织T₄向T₃转换。","","N"],["1990-N142",24,"第一节 心脏骤停与心脏性猝死","初级心肺复苏",1990,142,"X","","心跳、呼吸停止的急救中，理想的人工呼吸应是",[["A","能保证充分的通气量"],["B","能使动脉血氧分压接近正常"],["C","操作简单"],["D","无需特殊的器械或仪器"]],"ABCD","人工通气的目的就是为保证充分的通气量（A对），以纠正低氧血症，使动脉血氧分压接近正常（B对）。操作简单保证紧急情况下施救的有效性和可行性（C对）。心跳、呼吸停止的急救采取的是紧急处理措施，主要为了抢救生命，需要用简单的器械或仪器，便于操作，提高施救的效率，降低抢救的难度（D对）。","","N"],["1991-N12",61,"第一节 糖尿病","尿糖测定",1991,12,"A","","下列关于尿糖的说明中，哪一项是正确的",[["A","尿糖阳性肯定有血糖升高"],["B","尿糖阳性是肾小管吸收功能不良的结果"],["C","尿糖阳性肯定有糖代谢异常"],["D","尿糖阳性可诊断糖尿病"],["E","Benedict（班氏）试剂只查尿中有无葡萄糖"]],"E","血糖经肾小球滤过到肾小管，再经肾小管重吸收，剩余的糖随尿排出称为尿糖。因此，尿糖的影响因素包括血糖浓度、肾小球滤过功能、肾小管重吸收功能以及肾糖阈（尿中开始出现葡萄糖时最低血糖浓度，一般为160～180mg/dl），其中任何一个因素受影响都可能出现尿糖阳性：当血糖值超过160～180mg/dl（正常血糖范围为80～120mg/dl）时，即使肾小管吸收功能正常，也会出现尿糖阳性（B错）；当肾糖阈降低时，即使糖代谢和血糖正常，尿糖也可能出现阳性（AC错）。糖尿病的诊断以血糖异常升高作为依据（十版内科学P732），尿糖阳性不可诊断糖尿病（D错）。Benedict（班氏）试剂是由硫酸铜、柠檬酸钠和无水碳酸钠配置成的蓝色溶液，可以与葡萄糖反应生成Cu₂O砖红色沉淀，因沉淀颜色无法与血液颜色区分，故只能用于查尿中有无葡萄糖，不能用于查血中有无葡萄糖（E对）。","","N"],["1991-N13",59,"第一节 甲状腺功能亢进症","血清总甲状腺激素",1991,13,"A","","一位疑有甲亢的病人，2个月前曾做胆囊造影，为确定有无甲亢，下列哪项试验最有价值",[["A","甲状腺摄¹³¹I率"],["B","血清蛋白结合碘"],["C","甲状腺激素结合试验"],["D","T₃、T₄"],["E","以上均无价值"]],"D","甲亢患者血清TT₄、FT₃、FT₄增高，T₃、T₄实验最具有诊断价值（D对）。¹³¹I摄取率为甲亢的传统诊断方法，目前已经被sTSH测定技术所代替（A错）。血清蛋白结合碘（B错）、甲状腺激素结合试验（C错）均会因曾用胆囊造影剂（碘剂）而受影响，故不选用。血清蛋白结合碘包括体内多种含碘物质所含的碘，其中大部分为甲状腺素（T₄）的碘，因此测定血清蛋白结合碘可反映甲状腺激素水平。甲状腺激素结合试验亦称¹²⁵I-三碘甲腺原氨酸吸收试验，其原理如下：血中绝大部分甲状腺激素都与TBG结合结合。T₃与TBG结合不及T₄牢固，易被后者所取代。T₃和TBG结合的量取决于TBG被T₄饱和的程度或未结合TBG的剩余结合容量。加入一定量的¹²⁵I-T₃于病人血清中，¹²⁵I-T₃即与血清中TBG剩余结合容量结合，未被结合的呈游离状态的¹²⁵I-T₃则可被红细胞、树脂或活性炭等吸附剂所吸附，测定血浆TBG结合¹²⁵I-T₃（结合试验），就能了解TBG剩余结合容量，从而间接反映血循环中T₄的浓度。但该患者2个月前曾做胆囊造影（常用造影剂为碘番酸和碘阿芬酸，为放射性碘标记物质），可干扰血清蛋白结合碘（B错）及甲状腺激素结合试验（C错）的准确性。","","N"],["1991-N14",47,"第一节 缺铁性贫血","缺铁性贫血诊断",1991,14,"A","","符合缺铁性贫血潜伏期的是",[["A","血清铁蛋白下降"],["B","血清铁下降"],["C","运铁蛋白饱和度下降"],["D","总铁结合力下降"],["E","小细胞低色素性贫血"]],"A","缺铁性贫血病程发展的三个阶段：贮存铁耗尽→红细胞内铁缺乏→缺铁性贫血。缺铁性贫血潜伏期指贮存铁耗尽（ID）阶段，此阶段血清铁蛋白下降（A对）；骨髓铁染色显示骨髓小粒可染铁消失，铁粒幼细胞减少；血红蛋白及血清铁（B错）等指标尚正常。血清铁下降、运铁蛋白（转铁蛋白）饱和度下降（C错）为红细胞内铁缺乏（IDE）阶段的特点。小细胞低色素性贫血（E错）为缺铁性贫血（IDA）阶段的特点。缺铁性贫血时总铁结合力增高（D错）→红细胞内铁缺乏→缺铁性贫血。","","N"],["1991-N15",56,"第二节 原发免疫性血小板减少症","出、凝血及血小板功能检查",1991,15,"A","","下列哪项不支持原发性血小板减少性紫癜",[["A","血小板减少"],["B","出血时间延长"],["C","束臂试验阳性"],["D","骨髓中巨核细胞增多"],["E","凝血时间延长"]],"E","特发性血小板减少性紫癜（ITP）是由于患者对自身血小板抗原的免疫失耐受，产生体液免疫和细胞免疫介导的血小板过度破坏和血小板生成受抑，出现血小板减少（A错）。出血时间（BT）是指人为刺破皮肤毛细血管后，从血液自然流出到自然停止所需的时间。它受血小板的数量和质量、毛细血管结构和功能的影响，ITP患者血小板减少，故出血时间会延长（B错）。束臂试验又称毛细血管抵抗力试验，当毛细血管管壁的结构和功能、血小板数量和质量存在缺陷时，毛细血管壁的脆性和通透性增加，新出血点增加，因而出现束臂试验阳性（C错）。ITP患者由于血小板减少，骨髓巨核系可代偿性增生，巨核细胞数量正常或增加（D错）。凝血时间（CT）是指血液离开血管，在体外发生凝固的时间，反映的是内源性凝血系统的功能，与血小板无关，故ITP患者CT正常（E对）。","","N"],["1991-N16",28,"第一节 消化性溃疡","消化性溃疡诊断",1991,16,"A","","患者男，32岁，经常周期性上腹痛三年，空腹发作，夜间更重，进食可缓解，服西咪替丁可止痛，最可能的诊断为",[["A","胃溃疡"],["B","十二指肠球部溃疡"],["C","慢性胃炎"],["D","胃黏膜脱垂症"],["E","十二指肠淤积症"]],"B","青壮年男性患者，慢性周期性上腹痛，空腹及夜间发作，进食可缓解，即有疼痛-进食-缓解规律，且服用抑酸药（西咪替丁）可缓解，为十二指肠球部溃疡的典型特点，因此本例患者最可能的诊断为十二指肠球部溃疡（B对）。胃溃疡（A错）好发于中老年人，其腹痛多为餐后痛，且胃溃疡胃酸分泌正常或减少，抑酸药治疗效果不明显。慢性胃炎（C错）大多数患者无明显症状，其上腹痛也没有节律性特点。胃黏膜脱垂（D错）是由于异常松弛的胃黏膜逆行突入食管或向前通过幽门管脱入十二指肠壶腹部，临床上以后者多见，腹痛是最常见的表现，无明显的周期性和节律性，且不能为抗酸剂所缓解。十二指肠淤积症（E错）是指各种原因引起的十二指肠阻塞，以致十二指肠阻塞部位的近端扩张、食糜淤积而产生的临床综合征，主要临床表现为上腹部疼痛和饱胀症状，症状可随体位改变而减轻，疼痛无节律性、周期性，且不能为抗酸剂所缓解。","","N"],["1991-N22",40,"第五节 肾病综合征","肾病综合征诊断",1991,22,"A","","我国诊断肾病综合征其尿蛋白标准是",[["A","＞2.0克/24小时"],["B","＞2.5克/24小时"],["C","＞3.0克/24小时"],["D","＞3.5克/24小时"],["E","＞4.0克/24小时"]],"D","肾病综合征诊断标准是：①尿蛋白大于3.5g/d（D对）；②血浆白蛋白低于30g/L；③水肿；④血脂升高。其中①②两项为诊断所必需。","","N"],["1991-N23",45,"第一节 慢性肾衰竭","心血管系统表现",1991,23,"A","","大部分慢性肾功能衰竭患者血压增高的主要原因是",[["A","血浆肾素活性增高"],["B","水、钠潴留，血容量扩张"],["C","前列腺素分泌减少"],["D","血管舒缓素分泌减少"],["E","儿茶酚胺分泌过多"]],"B","慢性肾衰竭患者血压增高多由于水、钠潴留、肾素-血管紧张素增高和（或）某些舒张血管的因子产生不足所致。由于慢性肾衰竭的突出表现为肾小球率过滤降低所致的水、钠潴留，故水、钠潴留所致的血容量扩张为慢性肾功能衰竭患者血压增高的主要原因（B对）。肾素活性增高（A错）、前列腺素分泌减少（C错）、血管舒缓素分泌减少（D错）也起到了促使血压增高的因素，但不是主要原因。儿茶酚胺分泌过多（E错）为原发性高血压的发病机制（十版内科学P261）。","","N"],["1991-N24",35,"","",1991,24,"A","","肝硬化患者发生原发性腹膜炎的原因是",[["A","抵抗力降低"],["B","脾功能亢进"],["C","肝脏合成白蛋白的能力降低"],["D","腹水形成"],["E","肠道屏障作用减弱，下消化道细菌经淋巴系统进入腹腔"]],"E","在腹腔内脏器无感染源的情况下，腹腔积液原发性感染导致自发性细菌性腹膜炎（SBP）和内毒素血症。肝硬化门静脉高压患者肠道淤血，屏障作用减弱，致使下消化道细菌移位进入腹腔，为肝硬化患者发生原发性腹膜炎的原因（E对），这一点从致病菌种类可以得到证实。由于腹水是细菌的良好培养基，肝硬化患者出现腹水后容易导致原发性腹膜炎，但腹水形成（D错）非主要原因。抵抗力降低（A错）、脾功能亢进（B错）、肝脏合成白蛋白的能力降低（C错）对原发性腹膜炎的发生有促进作用，均不是主要原因。","","N"],["1991-N25",30,"第一节 溃疡性结肠炎","腹痛",1991,25,"A","","溃疡性结肠炎腹痛的规律是",[["A","腹痛-便意-便后缓解"],["B","腹痛-进餐-缓解"],["C","腹痛-便意-便后加剧"],["D","腹痛多遍及全腹"],["E","以上都不是"]],"A","溃疡性结肠炎患者腹痛常为阵发性、痉挛性绞痛，局限于左下腹或下腹部（D错）。疼痛时可有便意，便后疼痛可暂时缓解，即呈腹痛-便意-便后缓解的规律（A对）。腹痛-进餐-缓解是十二指肠溃疡腹痛的特点（B错）。一般胃肠道疾病少有便后腹痛加剧，唯有肛裂时便后肛门疼痛加剧，肛裂肛门疼痛特点是便时剧痛，缓解数分钟，数分钟后括约肌痉挛致剧痛半小时至数小时。","","N"],["1991-N26",30,"第二节 克罗恩病","肠结核",1991,26,"A","","Crohn病与肠结核最主要的鉴别在于",[["A","病程的长短"],["B","有无肠外结核"],["C","OT试验是否阳性"],["D","肉芽肿有无干酪样坏死"],["E","有无发热，腹痛、腹泻，厌食、乏力"]],"D","病理检查为大部分疾病诊断的金标准之一，肠结核病理表现为可分为溃疡型、增生型与混合型。其中增生型表现为粘膜下层及浆膜层有大量结核肉芽肿和纤维组织增生（十版内科学P383）。而Crohn（克罗恩）病的病理组织学特点为：非干酪样肉芽肿、裂隙状溃疡及肠壁各层炎症（十版内科学P392）。二者病理表现截然不同，因此病理检查有无干酪坏死（D对）为克罗恩病与肠结核最主要的鉴别点。二者均为慢性发展过程，病程均较长（A错），均可有腹痛、腹泻、发热、厌食、乏力等全身中毒症状（E错）。OT试验（结核菌素试验）有助于判断有无结核病感染，但是OT试验阳性（C错）仅表示已感染过结核杆菌或接种过卡介苗，不能诊断现阶段是否患病，因此非肠结核确诊及鉴别诊断依据。有肠外结核倾向于诊断肠结核，但非确诊依据（B错）。","","N"],["1991-N41",29,"第一节 肠结核","克罗恩病",1991,41,"A","","Crohn病与肠结核最主要的鉴别点是",[["A","病程的长短"],["B","有无肠外结核"],["C","OT试验是否阳性"],["D","病理检查有无干酪坏死"],["E","有无发热、腹痛、腹泻、厌食、乏力"]],"D","病理检查为大部分疾病诊断的金标准之一，肠结核病理表现为可分为溃疡型、增生型与混合型。其中增生型表现为粘膜下层及浆膜层有大量结核肉芽肿和纤维组织增生（十版内科学P383）。而Crohn（克罗恩）病的病理组织学特点为：非干酪样肉芽肿、裂隙状溃疡及肠壁各层炎症（十版内科学P392）。二者病理表现截然不同，因此病理检查有无干酪坏死（D对）为克罗恩病与肠结核最主要的鉴别点。二者均为慢性发展过程，病程均较长（A错），均可有腹痛、腹泻、发热、厌食、乏力等全身中毒症状（E错）。OT试验（结核菌素试验）有助于判断有无结核病感染，但是OT试验阳性（C错）仅表示已感染过结核杆菌或接种过卡介苗，不能诊断现阶段是否患病，因此非肠结核确诊及鉴别诊断依据。有肠外结核倾向于诊断肠结核，但非确诊依据（B错）。","","N"],["1991-N42",16,"第四节 房室交界性心律失常","急性发作期",1991,42,"A","","下列哪项不宜首选洋地黄治疗",[["A","阵发性室上性心动过速伴完全性右束支传导阻滞"],["B","频发房性期前收缩伴短阵房性心动过速"],["C","快速心房纤颤"],["D","预激综合征伴阵发性室上性心动过速"],["E","心功能不全伴窦性心动过速"]],"D","洋地黄缩短旁路不应期，导致经旁路下行的冲动增加，可加快心室率，因此洋地黄不宜用于预激综合征伴阵发性室上性心动过速（D错，为本题正确答案）患者。洋地黄类药物可显著减轻中度心衰患者的临床症状，改善生活质量，提高运动耐量，减少住院率，主要发挥的作用有正性肌力作用、抑制心脏传导系统、兴奋迷走神经。伴有快速心房纤颤（C对）、频发房性期前收缩合并短阵房性心动过速（B对）的收缩性心力衰竭是应用洋地黄的最佳指征。阵发性室上性心动过速伴完全性右束支传导阻滞（A对）及心功能不全伴窦性心动过速（E对）也可以用洋地黄治疗。","","N"],["1991-N43",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病肺功能检查",1991,43,"A","","肺功能测定对于诊断肺气肿有决定性的意义常用的有以下几项，哪项最有价值",[["A","肺活量"],["B","残气量，残气量/肺总量（%）测定"],["C","弥散功能"],["D","潮气量"],["E","每分钟静息通气量"]],"B","阻塞性肺气肿的病理变化为终末细支气管出现异常持久的扩张，伴有肺泡壁和细支气管的破坏，肺组织弹性日益减退，肺泡持续扩大，回缩障碍，进而肺泡中的残气量及残气量占肺总量的百分比增加，所以临床上把残气量/肺总量＞40%（B对）作为诊断肺气肿最有价值的指标。肺活量（A错）、弥散功能（C错）、潮气量（D错）及每分钟静息通气量（E错）等指标虽然有助于肺气肿的诊断，但其可用于多种疾病的诊断，对诊断肺气肿的特异性不高，故其不是诊断肺气肿最有价值的指标。","","N"],["1991-N44",13,"第三节 慢性呼吸衰竭","氧疗",1991,44,"A","","呼吸衰竭患者，血气分析为PaO₂=50mmHg，PaCO₂=70mmHg，给予哪种吸氧浓度较合适",[["A","10%～20%"],["B","24%～28%"],["C","30%～40%"],["D","45%～50%"],["E","40%～60%"]],"B","患者PaO₂50mmHg＜60mmHg，同时伴有PaCO₂70mmHg＞50mmHg，诊断为Ⅱ型呼吸衰竭，对于低氧血症伴有明显CO₂潴留者，适宜采用低浓度（＜35%）给氧。慢性呼吸衰竭时，呼吸中枢的化学感受器对CO₂反应性差，呼吸主要靠低氧血症对颈动脉体、主动脉体化学感受器的刺激来维持。若吸入氧浓度过高，使血氧迅速上升，解除了低氧对外周化学感受器的刺激，造成通气状况进一步恶化，导致CO₂潴留，严重时陷入CO₂麻醉状态。低浓度给氧的浓度区间在实际临床工作中及教科书中有不同版本，包括24%～28%、25%～30%、28%～30%、24%～35%、25%～35%等等，24%～35%之间的取值均可认为是正确的，因此24%～28%（B对）为正确答案。","","N"],["1991-N45",10,"第三节 慢性肺源性心脏病","慢性肺源性心脏病诊断",1991,45,"A","","肺心病呼吸衰竭患者行气管切开辅助呼吸后，检查血气为PaO₂=75mmHg，血pH7.42，PaCO₂=28.5mmHg，BE=-5.2mEq/L，HCO₃⁻=18.3mEq/L，考虑是",[["A","正常"],["B","代谢性碱中毒"],["C","呼吸性碱中毒"],["D","呼吸性碱中毒（代偿）"],["E","代谢性酸中毒伴有呼吸性碱中毒（代偿）"]],"E","患者血气PaO₂=75mmHg（正常值80～100mmHg，小于60mmHg表明存在呼衰）；PaCO₂=28.5mmHg（正常值为33～46mmHg），小于正常值，为呼吸性碱中毒；BE（剩余碱）=-5.2mEq/L（正常值为-3～+3mmol/L），HCO₃⁻=18.3mEq/L（正常值为22～27mmol/L），小于正常值，为代谢性酸中毒；血pH7.42（正常值为7.35～7.45）尚在正常范围内，故该患者为代谢性酸中毒伴有呼吸性碱中毒（代偿）（E对）。","","N"],["1991-N50",37,"第一节 急性胰腺炎","诊断AP的重要血清学标志物",1991,50,"A","","急性胰腺炎，血清淀粉酶升高的规律为",[["A","发病后2小时升高，12～24小时达到高峰"],["B","发病后3～12小时开始升高，24～48小时达到高峰"],["C","发病后24小时开始升高，48小时达到高峰"],["D","发病后48小时开始升高，72小时后达高峰"],["E","以上均不对"]],"B","急性胰腺炎时，血清淀粉酶于起病后2～12小时开始升高，48小时开始下降，持续3～5天（B对）。急性胰腺炎尿淀粉酶升高较晚，在发病后12～14小时开始升高，下降缓慢，持续1～2周，但尿淀粉酶值受患者尿量的影响。血清脂肪酶常在起病后24～72小时开始升高，持续7～10天，对就诊较晚的急性胰腺炎患者有诊断价值，且特异性也较高。","","N"],["1991-N51",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄预后",1991,51,"A","","主动脉瓣狭窄患者出现用力后晕厥并发症，常说明",[["A","左心室已明显增大"],["B","预期平均寿命3～4年"],["C","预示近期发生心功能不全"],["D","预示要发生急性心肌梗死"],["E","已出现了最严重的并发症"]],"B","主动脉狭窄患者从出现症状起，平均生存期在心衰患者为2年、晕厥患者为3年（B对），心绞痛患者为5年，死亡原因为左心衰（70%）、猝死（15%）和感染性心内膜炎（5%）（二版八年制内科学P332）。","","N"],["1991-N52",23,"第一节 感染性心内膜炎","易患因素",1991,52,"A","","感染性心内膜炎最常见于",[["A","先天性心脏病室间隔缺损"],["B","法洛四联症"],["C","风湿性心脏病二尖瓣狭窄"],["D","风湿性心脏病二尖瓣关闭不全"],["E","心力衰竭患者"]],"D","感染性心内膜炎为心脏内膜表面的微生物感染，伴有赘生物形成，包括急性感染性心内膜炎和亚急性感染性心内膜炎，前者主要累及正常瓣膜，后者多发生在器质性心脏病，首先是心脏瓣膜，尤其是二尖瓣（CD）和主动脉瓣，其次为先天性心血管病，如室间隔缺损（A）、动脉导管未闭、法洛四联症（B）和主动脉缩窄等。其中感染性心内膜炎最常见于风湿性心脏病二尖瓣关闭不全（D对）。心力衰竭（E错）为感染性心内膜炎的最常见的并发症，不是其常见的病因。","","N"],["1991-N53",17,"第四节 急性冠状综合征","血清心肌坏死标志物",1991,53,"A","","急性心肌梗塞发病后，下列哪项指标最早出现异常",[["A","GOT"],["B","CK"],["C","LDH"],["D","HBD"],["E","Mb"]],"E","以往沿用多年的AMI心肌酶测定，包括肌酸激酶（CK）（B错）、天冬氨酸氨基转移酶（AST）（之前为GOT，又叫谷草转氨酶）（A错）以及乳酸脱氢酶（LDH）（C错），其特异性及敏感性较差，已不再用于诊断AMI。HBD（D错）为羟丁酸脱氢酶，与LDH关系十分密切，实际上它是LDH同工酶Ⅰ型，与LDH、AST、CK、Mb构成心肌酶谱，对诊断心肌梗死有意义，但上升时间晚于Mb。肌红蛋白（Mb）（E对）升高在急性心肌梗死起病后2小时内增高，12小时内达高峰，24～48小时内恢复正常。","","N"],["1991-N54",18,"第一节 原发性高血压","硝普钠",1991,54,"A","","直接作用于血管平滑肌，降低心脏前后负荷的药物是",[["A","硝普钠"],["B","多妥拉明"],["C","酚妥拉明"],["D","哌唑嗪"],["E","巯甲基丙脯酸"]],"A","硝普钠直接作用于血管平滑肌，同时扩张静脉和动脉，降低前、后负荷，迅速降低血压（A对）。多妥拉明（B错）、酚妥拉明（C错）和哌唑嗪（D错）都是α-肾上腺素能受体的阻断药，作用于外周动脉，仅降低后负荷。巯甲基丙脯酸即卡托普利，为竞争性血管紧张素转换酶抑制剂，能扩张外周动、静脉，降低心脏前后负荷，但不是直接作用于血管平滑肌（E错）。","","N"],["1991-N55",19,"第一节 肥厚型心肌病","肥厚型心肌病临床表现",1991,55,"A","","关于肥厚型心肌病，下列哪项是错误的",[["A","左心室腔明显增大，左心室壁心肌明显肥厚"],["B","胸骨左缘可闻收缩期杂音，做Valsalva试验时杂音增强"],["C","超声心动图可见SAM征"],["D","β-受体阻滞剂为首选药"],["E","常可发生猝死"]],"A","肥厚型心肌病是一种以心肌进行性肥厚、心室腔进行性缩小为特征（A错，为本题正确答案），以左心室血液充盈受阻、舒张期顺应性下降为基本病理特点的原因不明的心肌疾病。肥厚型心脏病因存在左心室流出道狭窄，可出现胸骨左缘中下段收缩期喷射样杂音，作Valsalva动作时，回心血量减少，左室流出道狭窄更明显，杂音随之增强（B对）。伴有流出道梗阻的病例可见室间隔流出道部分向左心室内突出、二尖瓣前叶在收缩期前移（SAM）（C对）。β受体拮抗剂是梗阻性HCM的一线治疗用药（D对），可减慢心率并降低心肌收缩力，使舒张期充盈时间延长，室壁张力降低，改善胸痛及劳力性呼吸困难，并具有抗心律失常作用。肥厚型心肌病是一种遗传性心肌病，以心室非对称性肥厚为解剖特点，是青少年运动猝死的最主要原因之一（E对）。根据左室流出道有无梗阻可将其分为梗阻型和非梗阻型两型。","","N"],["1991-N66",4,"第二节细菌性肺炎","肺炎链球菌肺炎诊断",1991,66,"A","","男性患者，40岁，突发寒战高热，伴咳嗽胸痛两天，两小时前口服APC0.5g，大汗后热退伴无力。体检：BP90/50mmHg，脉搏102次/分，神清，血白细胞总数21×10⁹/L，胸片示右上肺大片状阴影，以下哪项诊断正确",[["A","休克型肺炎"],["B","支原体肺炎"],["C","肺脓肿"],["D","肺炎球菌性肺炎"],["E","肺结核"]],"D","患者中年男性，急性起病，寒战高热，伴咳嗽胸痛，胸片上可见右上肺大片状阴影，应诊断为肺炎球菌性肺炎（D对）。肺炎球菌性肺炎起病急，寒战、高热、咳嗽、胸痛，有肺实变体征，血白细胞总数、中性粒细胞比例升高，X线大片炎症浸润阴影或实变影，重症感染时可伴休克；休克型肺炎（A错）患者低血压、神志恍惚、淡漠、面色苍白、四肢厥冷等休克表现明显，同时伴有肺部炎症等表现，但白细胞并不升高；支原体肺炎（十版内科学P61）（B错）的典型表现为干咳，痰液少见，并无休克表现；肺脓肿（十版内科学P68）（C错）多表现为畏寒、发热、咳嗽、咳黏液痰或黏液脓性痰，而无休克表现；肺结核（十版内科学P73）（E错）多表现为咳嗽、咳痰、低热、乏力等明显的全身结核中毒症状，而无休克表现。","","N"],["1991-N67",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病肺功能检查",1991,67,"A","","阻塞性肺气肿患者最早出现的变化是",[["A","X线示右下肺动脉干段增宽"],["B","心电图示顺钟向转位"],["C","叩诊心浊音界缩小"],["D","动脉血二氧化碳分压升高"],["E","最大通气量降低"]],"E","阻塞性肺气肿肺组织弹性日益减退，肺泡持续扩大，回缩障碍，则残气量及残气量占肺总量的百分比增加，最大通气量降低（E对）。若病情继续发展，可累及邻近肺小动脉，使肺血管阻力增高，导致肺动脉高压，引起肺心病，右心增大，X线示右下肺动脉干段增宽（十版内科学P123）（A错），心电图示顺钟向转位（十版内科学P123）（B错）。叩诊心浊音界缩小（十版内科学P134）（C错）主要出现在大量气胸时，而小量气胸及肺气肿时体征一般不明显。病情发展到最后会引起动脉血氧分压降低和二氧化碳分压升高（D错）。","","N"],["1991-N68",6,"第一节 肺结核","有无活动性",1991,68,"A","","下列哪种情况应视为新近感染的活动性结核病，需给予治疗",[["A","三岁以下，结核菌素反应阳性"],["B","城市成年居民，结核菌素反应阳性"],["C","60岁以上，结核菌素反应阳性"],["D","青壮年发热两周，结核菌素反应阳性"],["E","以上都不是"]],"A","结核菌素（PPD）试验阳性只表示曾感染结核分枝杆菌，并不表示一定患病。PPD阳性不能区分是结核分枝杆菌的自然感染还是卡介苗接种的免疫反应，只有未接种卡介苗的婴幼儿结核菌素反应阳性时，表明新近感染活动性结核病。由于我国婴儿出生后便接种卡介苗，成年后结核菌素反应可呈阳性，所以城市成年居民（B错）、60岁以上老人（C错）结核菌素反应阳性时，不能表明其感染活动性结核病。由于儿童免疫系统发育不完全，虽出生后便接种卡介苗，但儿童的结核菌素试验反应多为阴性，如果儿童尤其是三岁以下婴幼儿结核菌素反应阳性（A对），表明其感染活动性结核病，应给予治疗。青壮年发热两周（D错），PPD试验可能弱阳性，所以结核菌素反应阳性，也不能表明其感染活动性结核病。","","N"],["1991-N69",35,"第一节 肝硬化","及早识别及去除HE发作的诱因",1991,69,"A","","肝昏迷患者出现抽搐时最好选用",[["A","氯丙嗪"],["B","吗啡"],["C","副醛"],["D","安定"],["E","硫喷妥钠"]],"D","肝性脑病患者慎用镇静、催眠、镇痛药及麻醉剂。当患者发生肝性脑病出现烦躁、抽搐时禁用阿片类、巴比妥类、苯二氮䓬类镇静剂，可试用异丙嗪、氯苯那敏（扑尔敏）等抗组胺药。氯丙嗪（A错）属于镇静药，有中枢抑制的副作用，可加重肝性脑病。吗啡（B错）属于镇痛药，可抑制呼吸，不能用于肝性脑病。副醛（C错）即三聚乙醛是一种作用迅速的催眠药，其药理与水合氯醛相似，但作用比水合氯醛更快更强，用于治疗失眠、抗惊厥，属于镇静催眠药，也有中枢抑制的副作用，加重肝性脑病。安定（地西泮）（D错）属于苯二氮卓类镇静催眠药，可直接抑制大脑与呼吸中枢，引起缺氧，不适用于肝昏迷患者。硫喷妥钠（E错）为巴比妥类药物，静注后很快产生麻醉，故称静脉麻醉药，可抑制呼吸，不能用于肝性脑病。根据十版内科学观点，本题无正确答案，但参考答案为D。","","N"],["1991-N72",27,"第二节 慢性胃炎","慢性胃炎诊断",1991,72,"A","","诊断慢性胃炎最可靠的依据是",[["A","慢性上腹痛在餐后加重"],["B","X线胃肠钡餐检查"],["C","胃泌素胃液分析"],["D","胃脱落细胞检查"],["E","以上都不是"]],"E","诊断慢性胃炎最可靠的依据是胃镜及组织学检查（E对）。慢性上腹痛在餐后加重（A错）不但可以见于慢性胃炎，也可见于慢性胃溃疡；X线胃肠钡餐检查（B错）一般用于身体状态差，不愿做胃镜的患者，随着消化内镜技术的发展，目前胃炎诊断很少应用；胃泌素胃液分析（C错）为慢性胃炎诊断的辅助手段，只能判断胃酸是否增高，但并不能直接诊断慢性胃炎；胃脱落细胞检查（D错）最常用于胃癌的诊断，不用来确诊慢性胃炎。","","N"],["1991-N87",17,"第三节 慢性冠状动脉综合症","稳定型心绞痛病理生理",1991,87,"B","","冠心病劳力性心绞痛发作时",[["A","肺毛细血管楔压增高"],["B","肺动脉压增高"],["C","右房压增高"],["D","外周动脉压增高"],["E","以上四项都存在"]],"A","劳力性心绞痛也称稳定型心绞痛，是在冠状动脉固定性严重狭窄基础上，由于心肌负荷的增加引起急剧的、暂时的缺血缺氧的临床综合征。肺毛细血管楔压（也称肺动脉楔压）是反映左室充盈压及左心室前负荷的可靠指标。劳力性心绞痛发作时，左心室收缩力和收缩速度降低，射血功能障碍，射入主动脉的血液减少，导致外周动脉压降低（D错）；收缩末期残留于心室内血液增多，影响左心房及肺静脉血液回流，导致肺淤血，进而导致肺毛细血管楔压增高（A对）。由于外周循环血量不足，导致回心血量也不足，因而右房压降低（C错）、肺动脉压降低（B错）。","","N"],["1991-N88",17,"第四节 急性冠状综合征","急性ST段抬高型心肌梗死病理生理",1991,88,"B","","急性下壁心肌梗死伴右心室梗塞",[["A","肺毛楔压增高"],["B","肺动脉压增高"],["C","右房压增高"],["D","外周动脉压增高"],["E","以上四项都存在"]],"C","急性下壁心肌梗死伴右心室梗塞时，右心室收缩功能障碍，射血分数下降，收缩末期残留于心室的血液增多，影响右心房及腔静脉血液回流，导致右房压增高（C对）及中心静脉压增高。右心射血减少导致肺动脉压（B错）、肺毛细血管楔压（A错）均降低，左心回流减少，左心室排血量降低，导致外周动脉压下降（D错），可发生发生低血压和休克。","","N"],["1991-N89",49,"第一节 再生障碍性贫血","再生障碍性贫血病因和发病机制",1991,89,"B","","再生障碍性贫血",[["A","DNA合成障碍"],["B","珠蛋白合成障碍"],["C","血红素合成障碍"],["D","铁利用障碍"],["E","多能干细胞受损"]],"E","再障是不同病因导致的骨髓造血功能衰竭，可能通过三种机制发病：原发和继发性造血干祖细胞缺陷（E对）、造血微环境及免疫异常。主要表现为造血功能低下，骨髓增生减低，外周血三系减少。DNA合成障碍（A错）主要见于巨幼细胞贫血（十版内科学P552）。珠蛋白合成障碍（B错）主要见于地中海贫血（十版内科学P563）。血红素合成障碍（C错）多见于缺铁性贫血（十版内科学P549）。铁利用障碍（D错）常见于铁粒幼细胞性贫血（十版内科学P551）。","","N"],["1991-N90",47,"第一节 缺铁性贫血","缺铁性贫血发病机制",1991,90,"B","","缺铁性贫血",[["A","DNA合成障碍"],["B","珠蛋白合成障碍"],["C","血红素合成障碍"],["D","铁利用障碍"],["E","多能干细胞受损"]],"C","缺铁性贫血时，红细胞内缺铁，大量原卟啉不能与铁结合成为血红素，即血红素合成障碍（C对）。DNA合成障碍（A错）见于巨幼细胞性贫血（十版内科学P552）。珠蛋白合成障碍（B错）见于海洋性贫血（十版内科学P563）。铁利用障碍（D错）见于铁粒幼细胞性贫血（十版内科学P551）。多能干细胞受损（E错）见于再生障碍性贫血（十版内科学P555）。","","N"],["1991-N91",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎支原体肺炎临床表现",1991,91,"B","","儿童可伴发鼓膜炎和中耳炎的肺炎是",[["A","克雷伯杆菌肺炎"],["B","肺炎球菌肺炎"],["C","支原体肺炎"],["D","病毒性肺炎"],["E","肺曲菌病"]],"C","儿童可并发鼓膜炎或中耳炎的肺炎是肺炎支原体肺炎（C对）；肺炎支原体肺炎肺外表现更为常见，如皮炎（斑丘疹和多形性红斑）等，查体可见咽部充血，儿童偶可并发鼓膜炎或中耳炎，颈淋巴结肿大；克雷伯杆菌肺炎（十版内科学P49）（A错）的特征性病变为起病急、寒战、高热、全身衰竭、咳砖红色胶冻样痰；肺炎球菌肺炎（B错）肺外表现为胸膜炎、心包炎、脑膜炎、关节炎；病毒性肺炎（D错）肺外表现为发热、头痛、全身酸痛、倦怠等；肺曲菌病（E错）主要表现为发热干咳或棕黄色痰、胸痛、咯血、喘息。ABDE均不会并发鼓膜炎或中耳炎。","","N"],["1991-N92",4,"第二节细菌性肺炎","肺炎链球菌肺炎临床表现",1991,92,"B","","伴末梢循环衰竭（中毒型或休克型肺炎）",[["A","克雷伯杆菌肺炎"],["B","肺炎球菌肺炎"],["C","支原体肺炎"],["D","病毒性肺炎"],["E","肺曲菌病"]],"B","肺炎球菌肺炎（B对）患者伴严重脓毒症或毒血症时，易发生感染性休克，表现为末梢循环衰竭。克雷伯杆菌肺炎（A错）特征性病变为起病急、寒战、高热、咳砖红色胶冻样痰；支原体肺炎（十版内科学P61）（C错）起病较缓，乏力、咽痛、肌痛、头痛，肺外表现有皮炎，儿童偶可并发鼓膜炎或中耳炎；病毒性肺炎（D错）与支原体肺炎症状相似，但一般较轻；肺曲菌病（E错）主要表现为发热、干咳、或棕黄色痰、胸痛、咯血、喘息，以上几种疾病在病情严重时均可出现休克，但不及肺炎球菌肺炎常见。","","N"],["1991-N107",60,"第一节 库欣综合征","库欣综合征病因诊断",1991,107,"C","","大剂量地塞米松抑制试验不被抑制",[["A","双侧肾上腺皮质增生"],["B","肾上腺皮质癌肿"],["C","两者均可"],["D","两者均不可"]],"B","大剂量地塞米松抑制试验方法：口服地塞米松2mg，1次/6小时，共2天。结果分析：服药后，血、尿皮质醇值降至对照值的50%以下为抑制试验阳性。临床意义：用于鉴别Cushing综合征的病因。正常人糖皮质激素的分泌受下丘脑（CRH，促肾上腺激素释放激素）-垂体（ACTH，促肾上腺激素）-肾上腺皮质（GC，糖皮质激素）轴的调节，当给予外源性糖皮质激素时，垂体ACTH分泌受抑制，从而皮质醇分泌减少。在Cushing综合征病人中，肾上腺皮质癌肿为自主分泌皮质醇，引起的高皮质醇血症已在很大程度上抑制了垂体ACTH的分泌，再给予外源性糖皮质激素（地塞米松），也不会对垂体ACTH分泌有多大影响，血、尿皮质醇亦变化不大，因此不能被大剂量地塞米松抑制试验抑制（B对）。双侧肾上腺皮质增生由库欣病或异位ACTH综合征引起。库欣病是由垂体ACTH分泌过多所致，血皮质醇过高，给予小剂量地塞米松，对血皮质醇影响不大，故不能被小剂量地塞米松抑制试验抑制，但给予大剂量地塞米松能抑制垂体ACTH分泌，使血皮质醇减少，从而能被大剂量地塞米松抑制试验抑制；异位ACTH综合征是由于垂体以外的肿瘤自主性产生ACTH所致，而高皮质醇血症使垂体分泌ACTH受抑制，再给予外源性地塞米松，也不会对垂体ACTH分泌有多大影响，血、尿皮质醇亦变化不大，因此不能被大剂量地塞米松抑制试验抑制，只有少数异位CRH者，是由CRH作用于垂体，引起垂体分泌ACTH过多所致，因此能被大剂量地塞米松抑制试验抑制。综上所述，双侧肾上腺皮质增生多数能被大剂量地塞米松抑制试验抑制（A错）。","","N"],["1991-N108",60,"第一节 库欣综合征","库欣综合征病因诊断",1991,108,"C","","血中ACTH增高",[["A","双侧肾上腺皮质增生"],["B","肾上腺皮质癌肿"],["C","两者均可"],["D","两者均不可"]],"A","肾上腺皮质增生由库欣病或异位ACTH综合征引起，两者均会使血中ACTH升高（A对）。肾上腺皮质癌肿（B错）时，肾上腺皮质分泌过多皮质醇，负反馈使垂体分泌ACTH减少，严重者可使对侧肾上腺萎缩，检测不到ACTH。","","N"],["1991-N109",28,"第一节 消化性溃疡","消化性溃疡药物治疗",1991,109,"C","","治疗十二指肠溃疡并发幽门梗阻",[["A","前列腺素E"],["B","M胆碱受体阻断药"],["C","两者均可用"],["D","两者均不可"]],"A","前列腺素E属于黏膜细胞保护剂，并能减少胃酸分泌，故适用于治疗酸度增高的十二指肠溃疡并发幽门梗阻患者（A对），而M胆碱受体阻断药能松弛平滑肌，抑制幽门括约肌舒张，故使胃排空延缓，加重梗阻，所以不宜用于幽门梗阻的患者（B错）。","","N"],["1991-N110",27,"第二节 慢性胃炎","慢性胃炎治疗",1991,110,"C","","治疗慢性胃炎",[["A","前列腺素E"],["B","M胆碱受体阻断药"],["C","两者均可用"],["D","两者均不可"]],"C","前列腺素E属于黏膜细胞保护剂，并能减少胃酸分泌；M胆碱受体阻断药能松弛胃肠平滑肌，可缓解疼痛，两种药物都适于治疗慢性胃炎（C对）。","","N"],["1991-N119",61,"第一节 糖尿病","2型糖尿病",1991,119,"X","","引起糖耐量降低的疾病有",[["A","一切糖尿病"],["B","肝功能损害"],["C","肥胖病"],["D","胰腺β细胞功能衰竭"]],"BCD","糖耐量指人体对葡萄糖的耐受能力。糖耐量减低即胰岛素分泌不足或分泌延迟使机体对血糖浓度的调节能力减低，餐后血糖不能正常降低。大多糖尿病患者胰岛素分泌不足，糖耐量减低。当肾脏出现病变时，可导致肾小管对糖的重吸收降低，出现肾性糖尿，但血糖及糖耐量曲线均正常，故不是一切糖尿病均引起糖耐量减低（A错）。肝脏是糖异生和糖原合成分解的重要器官，肝功能损害时，可使糖原合成障碍，餐后血糖不能正常降低，引起糖耐量减低（B对）。肥胖病患者出现胰岛素抵抗（胰岛素促进葡萄糖摄取和利用的效率下降，机体代偿性分泌过多胰岛素产生高胰岛素血症，以维持血糖的稳定），早期可勉强把血糖控制在正常范围，后期便可出现糖耐量减低（C对）。胰腺β细胞功能衰竭，胰岛素分泌绝对缺乏，血糖升高不能刺激胰岛素分泌，导致糖耐量减低（D对）。由于教材版本的原因，A项存在争议，当年的参考教材将肾性糖尿归为糖尿病，九版教材已经未再采用此观点。","","N"],["1991-N121",16,"第三节 房性心律失常","心房颤动诊断",1991,121,"X","","听诊心尖部第一心音强弱不等可见于",[["A","心房纤颤"],["B","室性期前收缩三联律"],["C","一度房室传导阻滞"],["D","二度Ⅰ型房室传导阻滞"]],"ABD","房颤典型表现有三个：第一心音强弱不等（A对）、心律绝对不齐和脉搏短绌。三联律是每两个正常搏动后出现一个室性期前收缩。当发生室性期前收缩三联律（B对）时，心室在相对未完全舒张和和未被血液充分充盈的情况下，二尖瓣位置较低，急速的心室收缩使二尖瓣迅速和有力地关闭使第一心音增强。因此心尖部听诊可出现第一心音强弱不等。二度Ⅰ型房室传导阻滞（D对）有心搏脱漏，可出现第一心音强弱不等。一度房室传导阻滞（C错）时仅有延长的P-R间期固定不变而无心搏脱漏，无第一心音强弱不等表现。","","N"],["1991-N122",59,"第一节 甲状腺功能亢进症","血清总甲状腺激素",1991,122,"X","","T₃抑制试验，下列哪些情况是禁忌的",[["A","老年"],["B","冠状动脉粥样硬化性心脏病"],["C","甲亢性心脏病"],["D","单纯性甲状腺肿"]],"ABC","T₃抑制试验原理如下：正常人垂体-甲状腺轴呈反馈调节关系，故服用外源性T₃后，血液中T₃浓度升高，通过负反馈抑制内源性TSH合成与分泌，导致甲状腺¹³¹I摄取率明显降低；在弥漫性毒性甲状腺肿患者，由于存在病理性甲状腺刺激物（TRAb等），刺激甲状腺引起¹³¹I摄取率明显升高，不受T₃抑制。T₃（三碘甲状腺原氨酸）抑制试验可用于单纯性甲状腺肿与其他类型甲亢的鉴别（D错）。T₃（三碘甲状腺原氨酸）和甲状腺激素作用于心脏可引起心率加快，并能引起血容量增加，使心脏的负荷增加，诱发心脏血管疾病。故老年患者（A对）、冠状动脉粥样硬化性心脏病（B对）、甲亢性心脏病（C对）、严重甲亢者禁用本试验，以免诱发心律失常、心绞痛或甲亢危象。","","N"],["1991-N123",61,"第三节 高渗高血糖综合征","高渗高血糖综合征实验室检查",1991,123,"X","","糖尿病非酮症高渗昏迷的诊断依据是",[["A","血钠＞142mmol/L"],["B","血糖＞33.3mmol/L"],["C","血渗透压＞320mmol/L"],["D","血糖＞27.75mmol/L，血渗透压＞300mmol/L"]],"BC","糖尿病性非酮症高渗性昏迷（又称高渗高血糖综合征）的诊断依据是：1.中老年患者，血糖≥33.3mmol/L（B对D错）；2.有效血浆渗透压≥320mOsm/L（C对）。高渗高血糖昏迷血钠正常或增高，因此血钠>142mmol/L（正常值范围135～145mmol/L）并不能诊断糖尿病性非酮症高渗性昏迷（A错）。","","N"],["1991-N124",49,"第一节 再生障碍性贫血","AA血象",1991,124,"X","","下列哪些病可有全血细胞减少",[["A","缺铁性贫血"],["B","再生障碍性贫血"],["C","原发性血小板减少性紫癜"],["D","急性白血病"]],"BD","可导致全血细胞减少的疾病包括再生障碍性贫血（B对）、急性白血病（D对）、骨髓增生异常综合征、巨幼细胞性贫血、阵发性睡眠性血红蛋白尿、Fanconi贫血、Evans综合征、免疫相关性全血细胞减少（十版内科学P640）及恶性组织细胞病等。再生障碍性贫血是一种造血功能衰竭症，表现为骨髓增生减低，外周血全血细胞减少。急性白血病是一种造血干祖细胞的恶性克隆性疾病，发病时骨髓中异常的原始细胞及幼稚细胞（白血病细胞）大量增殖，抑制正常造血，导致外周全血细胞减少。缺铁性贫血（A错）表现为红细胞降低，白细胞和血小板计数可正常或减低，也有部分患者血小板计数升高。严重的缺铁性贫血可以出现全血细胞减少，该选项存在争议。原发性血小板减少性紫癜（十版内科学P624）（C错）患者血小板生成减少，破坏增加，出现血小板减少，而红系、粒系不受影响。","","N"],["1991-N125",52,"第二节 急性白血病","ALL诱导缓解治疗",1991,125,"X","","治疗急性淋巴细胞性白血病，可选用如下哪些药物",[["A","泼尼松"],["B","长春新碱"],["C","门冬酰胺酶"],["D","高三尖杉酯碱"]],"ABC","长春新碱（VCR）（B对）和泼尼松（P）（A对）组成的VP方案是急性淋巴细胞白血病（ALL）的基础用药。VP方案能使50%的成人ALL获CR（完全缓解），CR期3～8个月。VP加蒽环类药物（如柔红霉素，DNR）组成DVP方案，CR率可提高至70%以上，但需要警惕蒽环类药物的心脏毒性。DVP再加左旋门冬酰胺酶（L-ASP）（C对）即为DVLP方案，是目前ALL常采用的诱导方案。在DVLP基础上加用其他药物，包括环磷酰胺（CTX）或阿糖胞苷（Ara-C），可提高部分ALL的CR率和DFS。高三尖杉酯碱（十版内科学P584）（D错）属于AML的治疗用药。","","N"],["1991-N126",69,"第一节 系统性红斑狼疮","补体",1991,126,"X","","血中C3降低见于",[["A","尿酸肾病"],["B","系统性红斑狼疮活动期"],["C","糖尿病肾病"],["D","乙肝相关抗原肾炎"]],"BD","在形成免疫复合物的疾病中，免疫复合物可结合并消耗补体而使C3下降。系统性红斑狼疮（SLE）处于活动期时，补体C3、C4和总补体（CH50）活性水平常减低（B对），原因是免疫复合物的形成消耗补体，同时肝脏合成补体的能力下降。乙型肝炎病毒相关性肾炎是指乙肝病毒与机体产生的相应的抗体结合形成免疫复合物，在肾小球内沉积而引起的一系列肾脏疾病。乙型肝炎病毒相关性肾炎（D对）病人常有血清C3下降，循环免疫复合物增多等免疫学异常表现。高尿酸血症肾病（痛风性肾病）（十版内科学P851）（A错）是指原发性或继发性高尿酸血症伴有尿酸（或尿酸盐）沉积于肾，引起肾结石、梗阻、间质性肾炎、急性或慢性肾衰竭为表现的肾脏疾病，在疾病发生发展过程中，无免疫复合物形成，故C3不会下降。糖尿病肾病（十版内科学P729）（C错）多发生于糖尿病史10年以上的病人，常伴有高血压、肌酐清除率下降等，但无免疫复合物形成，故C3不会下降。","","N"],["1991-N137",19,"第二节 扩张型心肌病","扩张型心肌病临床表现",1991,137,"X","","扩张型心肌病的临床表现可有",[["A","心电图病理Q波"],["B","猝死"],["C","栓塞"],["D","肺毛细血管楔压上升"]],"ABCD","扩张型心肌病（DCM）是一种原因未明的原发性心肌疾病。本病的特征为左心室或双心室扩大，并伴有心室收缩功能减退，心肌广泛纤维化，伴或不伴充血性心力衰竭。在左心室严重纤维化的患者可出现病理性Q波（A对），需除外心肌梗死。疾病晚期，左心室泵血功能极度减退，收缩末期残留于左心室内的血液增多，舒张期心房及肺静脉血液回流受限，可引起肺毛细血管楔压上升（D对）。心肌收缩能力减弱，心腔内血流速度减慢，容易引起附壁血栓的形成，若血栓脱落，可引起远端栓塞（C对）。合并心律失常时，可出现心悸、头晕、黑蒙甚至猝死（B对）。","","N"],["1991-N138",13,"第三节 慢性呼吸衰竭","慢性呼吸衰竭病因",1991,138,"X","","呼吸性酸中毒合并代谢性碱中毒与下列哪些因素有关",[["A","多发生在呼吸衰竭早期"],["B","BE正值增大，PaCO₂升高"],["C","高钾血症"],["D","使用糖皮质激素及碱性药物和失钾性利尿剂"]],"BD","人体主要通过体液缓冲系统、肺、肾和离子交换调节等来维持及调节酸碱平衡，体液缓冲系统、离子交换是暂时的，过多的酸或碱性物质需最终依赖肺和肾的调节。肺的调节较快，主要以CO₂形式排出挥发性酸，肾的调节则较慢，以调节非挥发性酸和碱性物质的排出。呼吸衰竭早期主要表现为低氧血症，可伴或不伴CO₂潴留，缺氧导致体内酸性物质增多，由于呼吸衰竭，肺调节不能发挥作用，主要依靠肾减少HCO₃⁻的排出和增加H⁺排出，以维持酸碱平衡，HCO₃⁻的增加可引起代谢性碱中毒，由于肾的调节较慢，故呼吸性酸中毒合并代谢性碱中毒出现较晚（A错）；呼吸性酸中毒时PaCO₂升高，代谢性碱中毒时BE正值（剩余碱）增大（B对）；高钾血症引起代谢性酸中毒，不会引起呼吸性酸中毒合并代谢性碱中毒（C错）；使用糖皮质激素（具有轻微保钠排钾的作用）和碱性药物及失钾性利尿剂导致低钾血症，能引起代谢性碱中毒，合并PaCO₂增加则导致呼吸性酸中毒合并代谢性碱中毒（D对）。","","N"],["1991-N139",15,"第二节 慢性心力衰竭","洋地黄类药物",1991,139,"X","","下列哪些因素可诱发洋地黄中毒",[["A","静脉内注射钙剂"],["B","长期服用噻嗪类利尿剂"],["C","同时服用利血平"],["D","同时服用硝酸酯类药物"]],"ABC","洋地黄化时静脉用硫酸镁应十分谨慎，尤其是同时静注钙盐时，可发生心脏传导阻滞（A对）。长期服用噻嗪类利尿剂（B对）容易出现低血钾症，低血钾为最主要的诱发洋地黄毒性反应的因素。利血平可增加洋地黄对心脏的毒性反应，引起心律失常（C对）。同时服用硝酸酯类药物没有引发洋地黄中毒的明显证据（D错）。","","N"],["1991-N141",21,"第六节 风湿热","心脏炎",1991,141,"X","","关于急性风湿热，下列哪些是正确的",[["A","环形红斑多分布于肢体内侧，消退快"],["B","心脏可闻及可变化性杂音时，就考虑到有心内膜炎的可能"],["C","风湿性脑病患者常伴有心肌炎"],["D","皮质激素是急性风湿热治疗的首选药物"]],"AB","环形红斑多分布于肢体内侧，消退快（A对）。急性风湿热首发病例中40%～50%累及心脏，多于发病1～2周内即出现症状。常见听诊变化有心动过速，心音减弱，可闻及奔马律，心尖部收缩期吹风样杂音或全收缩期吹风样杂音与舒张期隆隆样杂音等。故心脏可闻及可变化性杂音时，就应考虑到有心内膜炎的可能（B对）。风湿性脑病主要病变为风湿性动脉炎和皮质下脑炎，后者主要累及大脑皮质、基底节、丘脑及小脑皮层，伴有心肌炎者较少见（C错）。急性风湿热首选药物为长效青霉素制剂（D错），如苄星青霉素，风湿性心脏炎患者宜早期应用糖皮质激素。","","N"],["1991-N145",44,"第一节 急性肾损伤","肾脏替代治疗",1991,145,"X","","急性肾衰竭时，采用透析疗法的适应证是",[["A","水中毒"],["B","血钾5.5mmol/L"],["C","血尿素氮＞100mg/d1"],["D","厌食、呕吐、肌肉抽搐"]],"ACD","肾透析治疗的指征：血肌酐每日升高＞176.8μmol/L（或血肌酐浓度＞442μmol/L）；血尿素氮每日升高＞8.9mmol/L（或血尿素氮浓度＞21.4mmol/L）（C对）；血钾每日升高＞1mmol/L（或血钾浓度＞6.5mmol/L）（B错）；严重酸中毒（CO₂CP＜13mmol/L、pH＜7.2）；利尿剂难以控制的水超负荷（A对）；药物治疗难以控制的高血压；出现尿毒症严重并发症。厌食、呕吐、肌肉抽搐（D对）为电解质失衡和神经肌肉系统兴奋性增加所致，为严重的尿毒症并发症，也应进行透析疗法。AKI的透析治疗可选择腹膜透析、间歇性血液透析、连续性肾脏替代治疗。","","N"],["1991-N146",4,"第一节 肺炎概述","肺炎治疗",1991,146,"X","","常用的抗生素中，下列哪些不正确",[["A","青霉素G是β内酰胺类抗生素，主要杀灭革兰氏阴性菌"],["B","庆大霉素是氨基糖苷类抗生素，主要抑制革兰氏阴性菌"],["C","第一代头孢菌素主要杀灭革兰氏阴性杆菌"],["D","氯霉素主要毒性反应是耳聋"]],"ACD","β-内酰胺类抗生素主要包括青霉素类和头孢菌素类。青霉素类包括窄谱青霉素类、耐酶青霉素类、广谱青霉素类、抗铜绿假单胞菌广谱青霉素类和抗革兰阴性菌青霉素类。青霉素G为窄谱青霉素类，主要作用于革兰阳性菌，对大多数革兰阴性菌作用较弱（A错，为本题正确答案）；头孢菌素类分为一、二、三、四代，第一代头孢菌素对革兰阳性菌作用较强，但是对革兰阴性菌的作用差（C错，为本题正确答案）；氨基糖苷类抗生素分为两大类，一类为天然来源，如链霉素、庆大霉素等，一类为半合成品，如阿米卡星等，氨基糖苷类对各种需氧革兰阴性杆菌具有强大的抗菌作用（B对）；氯霉素的主要不良反应为血液系统毒性（如骨髓抑制）和灰婴综合征（D错，为本题正确答案）。","","N"],["1991-N153",45,"第一节 慢性肾衰竭","心血管系统表现",1991,153,"X","","导致尿毒症性心肌病的原因有",[["A","高血压"],["B","贫血"],["C","尿毒症毒素"],["D","钙离子在心肌沉积"]],"ABCD","慢性肾衰竭时水、钠潴留致有效循环血量增多、肾素-血管紧张素分泌增加、血管扩张因子减少可导致高血压（八版内科学P527），高血压（A对）引起心肌后负荷增大、心肌细胞代偿性肥大，后期失代偿终致心脏扩大即尿毒症性心肌病。慢性肾衰竭可致肾性贫血，贫血（B对）引起循环高流量、高动力状态，心脏前负荷增大，心脏代偿性扩张，后期失代偿导致尿毒症性心肌病。尿毒症毒素（C对）在体内蓄积产生细胞毒性，使心肌细胞受损，导致尿毒症性心肌病。慢性肾衰竭时，细胞供氧不足、尿毒症毒素作用使线粒体损伤，细胞内钙超载（D对）导致心肌舒张收缩功能障碍导致尿毒症性心肌病。","","N"],["1991-N154",28,"第一节 消化性溃疡","消化性溃疡症状",1991,154,"X","","消化性溃疡引起腹痛的机理是",[["A","溃疡及其周围组织炎症"],["B","胃酸对溃疡面的刺激"],["C","局部肌张力增加"],["D","胃壁痉挛"]],"ABCD","消化性溃疡引起腹痛的机理有很多，包括胃酸或局部炎症刺激溃疡面的神经末梢（AB对），胃壁平滑肌痉挛（D对）、胃内压增高和肌纤维紧张度增强致局部肌张力增高（C对）使病变部位的神经感受器受到刺激。","","N"],["1991-N155",75,"第二节 农药中毒","胆碱酯酶复活药",1991,155,"X","","有机磷农药中毒首选的药物",[["A","解磷定"],["B","甲氧氯普胺"],["C","乙酰胆碱"],["D","抗胆碱能药物"]],"AD","有机磷农药发挥毒性的主要机制是对乙酰胆碱酯酶的抑制，引起乙酰胆碱蓄积，使胆碱能神经受到持续冲动，导致先兴奋后衰竭的一系列毒蕈碱样、烟碱样和中枢神经系统等症状。解磷定（A对）属于ChE复能药，能使被抑制的ChE恢复活性，复能作用强，毒性小，且其作用于外周N₂受体，可对抗外周N胆碱受体活性，能有效解除烟碱样毒性作用，是临床上有机磷中毒的首选药物。抗胆碱能药物（D对）可以对抗乙酰胆碱的作用，减轻M样症状及N样症状。乙酰胆碱（C错）的使用会加重乙酰胆碱蓄积，导致患者中毒症状加重或持续。甲氧氯普胺（B错）即胃复安，系镇吐药物，有强大的中枢性镇吐作用，用于治疗恶心、呕吐等症状，但大剂量或长期应用时，可因阻断多巴胺受体，使胆碱能受体相对亢进而导致锥体外系反应，主要表现为肌肉颤抖而加重症状，因此不宜使用。","","N"],["1992-N1",15,"第三节 急性心力衰竭","急性心力衰竭病因",1992,1,"A","","导致急性左心功能不全的原因是",[["A","左室舒张末压增高"],["B","肺静脉压增高"],["C","肺动脉压增高"],["D","肺毛细血管楔压增高"],["E","外周动脉压增高"]],"B","肺静脉压增高（B对）直接导致肺毛细血管压力升高，液体渗出到肺泡和肺间质，引发肺水肿，这是急性左心功能不全的直接病理生理机制。左室舒张末压增高（A错）通常反映左心室舒张功能受损，但它更多是左心功能不全的结果而非直接原因。肺动脉压增高（C错）通常与右心功能不全或肺血管疾病相关，而非直接由左心功能不全引起。肺毛细血管楔压增高（D错）是反映左心功能不全的一个指标，但它本身是肺静脉压增高的结果。外周动脉压增高（E错）与左心功能不全无直接关联，更多与高血压或外周血管阻力增加有关。","","N"],["1992-N2",6,"第一节 肺结核","复治肺结核病的治疗",1992,2,"A","","男性，30岁，右上肺结核，初治用异烟肼，乙胺丁醇和链霉素治疗半年，停药三个月后复发，复治药物宜选用",[["A","异烟肼+乙胺丁醇+链霉素"],["B","异烟肼+卡那霉素+吡嗪酰胺"],["C","利福平+乙胺丁醇+链霉素"],["D","吡嗪酰胺+链霉素+卡那霉素"],["E","异烟肼+对氨基水杨酸"]],"B","该患者停药后复发，所以应当按照复治的方案来进行治疗，首先要做药物敏感性试验，敏感患者按照复治涂阳的方案，若产生耐药，则按照耐药的方案治疗。复治药物强化期选用异烟肼、利福平、吡嗪酰胺、链霉素和乙胺丁醇。异烟肼是单一抗结核药物中杀菌力最强的药物，应该选用（CD错）；异烟肼+乙胺丁醇+链霉素用药为原来方案，复治时不宜再用，易形成耐药（A错）；结核病治疗时，应严格避免只选用一种新药加到原失败方案，且异烟肼+对氨基水杨酸（E错）对于结核病复发的治疗没有异烟肼+卡那霉素+吡嗪酰胺效果好（B对）。根据10版内科学教材P82：复治肺结核病人是指因结核病不合理或不规律抗结核治疗≥1个月，以及初治失败或复发的肺结核病人。WHO2017年指南以及《中国结核病预防控制工作技术规范（2020年版）》提出，不再规定标准复治方案，应对所有复治肺结核病病人进行药物敏感性试验，根据耐药结果制订个体化治疗方案。分为利福平敏感肺结核和利福平耐药肺结核两大类。对于利福平敏感或耐药性未知的复治肺结核病人，首选按照初治标准化治疗方案对病人进行治疗，耐药者纳入耐药方案治疗。本题无正确答案。","","N"],["1992-N3",5,"第一节 肺脓肿","肺脓肿抗感染治疗",1992,3,"A","","急性肺脓肿的感染菌中，50%～90%是厌氧菌，首选的抗生素是",[["A","磺胺药物"],["B","洁霉素"],["C","甲硝唑"],["D","青霉素"],["E","先锋霉素"]],"D","急性肺脓肿的50%～90%是由厌氧菌感染引起的，一般均对青霉素（D对）敏感，疗效较佳，为首选药物。对厌氧菌感染除应用青霉素外，尚可选用或联合应用其他抗厌氧菌感染治疗，如林可霉素（洁霉素）（B错）、甲硝唑（C错）。磺胺药物（A错）属于广谱抑菌药，但其不良反应成为突出问题，临床应用明显受限，但对流行性脑脊髓膜炎、鼠疫等感染性疾病疗效显著。先锋霉素（E错）为头孢菌素类抗生素，对厌氧菌感染疗效没有青霉素类显著。","","N"],["1992-N4",10,"第三节 慢性肺源性心脏病","酸碱失衡及电解质紊乱",1992,4,"A","","肺心病患者，在人工通气时，做血气分析，pH7.51，PaCO₂24mmHg，BE-8.0mmol/L，下一步应采用",[["A","精氨酸"],["B","减少呼吸机潮气量"],["C","5%NaHCO₃"],["D","加大呼吸机潮气量"],["E","立即停用呼吸机"]],"B","肺心病患者，在人工通气时，做血气分析，pH7.51（正常值为7.35～7.45），PaCO₂24mmHg（正常值为33～46mmHg），BE-8.0mmol/L（正常值为-3～+3mmol/L），可以推测患者是由于过度通气，导致急性失代偿性呼吸性碱中毒，所以应减少呼吸机的潮气量使患者得到纠正（B对D错）。一般调节呼吸机潮气量就可以有效改善症状，若体内HCO₃⁻增多，发展成代谢性碱中毒，可以加用精氨酸（A错）治疗；若立即停用呼吸机（E错），患者通气障碍不能纠正，很快又会使患者出现呼吸衰竭；患者已经是碱中毒，所以不可以采用5%碳酸氢钠（C错）。","","N"],["1992-N5",18,"第一节 原发性高血压","高血压急症和亚急症临床表现",1992,5,"A","","关于高血压脑病的特征，下列哪项是错误的",[["A","可发生于急性高血压"],["B","可发生于妊娠中毒症"],["C","临床表现主要为颅内压升高所致"],["D","发生时常伴有血压突然升高"],["E","大多有急性肺水肿表现"]],"E","高血压脑病一般不出现急性肺水肿（E错，为本题正确答案），仅见于少数症状严重患者。高血压脑病是指当血压突然升高（D对）超过脑血流自动调节的阈值（中心动脉压大于140mmHg）时，脑血流出现高灌注，毛细血管压力过高，渗透性增强，导致脑水肿和颅内压增高（C对），甚至脑疝的形成，引起的一系列暂时性脑循环功能障碍的临床表现。高血压脑病起病急，进展快，及时治疗其症状可完全消失，若治疗不及时或治疗不当则可导致不可逆脑损害及其他严重并发症，甚至可导致死亡。此类情况可见于急性高血压（A对）、妊娠中毒症（B对）（妊娠中毒症是指妊娠20周以后出现高血压、水肿及蛋白尿，严重时可出现抽搐与昏迷）、嗜铬细胞瘤等疾病。","","N"],["1992-N6",15,"第二节 慢性心力衰竭","洋地黄类药物",1992,6,"A","","洋地黄中毒的可能",[["A","心电图ST-T呈鱼钩形改变"],["B","心电图Q-T间期缩短"],["C","心电图出现高U波"],["D","频发房性期前收缩"],["E","频发室性期前收缩"]],"E","洋地黄毒性反应在心脏方面的表现最主要的为心律失常，常见为室性期前收缩，因此如若口服洋地黄后出现频发室性期前收缩（E对），可作为洋地黄中毒的诊断。洋地黄可引起心电图ST-T改变称为“鱼钩”形改变（A错），但不能据此诊断洋地黄中毒，仅提示患者曾服用洋地黄。Q-T间期长短与心率快慢相关，心电图Q-T间期缩短（B错）仅提示心率加快，而不能诊断为洋地黄中毒。心电图出现高U波（C错）最常见的原因是低血钾，亦可见于心动过缓、早搏代偿间歇后，或应用某些药物如洋地黄、奎尼丁、胺碘酮、钙剂、肾上腺素、普鲁卡因酰胺等，低温或用力呼吸、运动后均可出现U波增高，因此不具有特异性。出现频发房性期前收缩（D错）一般亦不考虑洋地黄中毒，多见于二尖瓣病变，甲状腺功能亢进或冠心病，尤其是多源性的，可能是心房颤动的前奏。","","N"],["1992-N7",16,"第三节 房性心律失常","心房颤动诊断",1992,7,"A","","下列哪项可作为确诊器质性心脏病的依据",[["A","室性期前收缩"],["B","二度Ⅰ型房室传导阻滞"],["C","右束支传导阻滞"],["D","阵发性心房颤动"],["E","以上都不是"]],"E","正常人可发生室性期前收缩，且机会随年龄的增长而增加（A错）。正常人或运动员可发生二度Ⅰ型房室传导阻滞（B错），与迷走神经张力增高有关，常发生于夜间。正常人也可以发生右束支传导阻滞（C错）。阵发性心房颤动（D错）亦可见于正常人，特别是在情绪紧张或在手术、运动、急性酒精中毒后。综上所述，以上症状都不是（E对）确诊器质性心脏病的依据。","","N"],["1992-N8",7,"第一节 肺癌","原发性肥大性骨关节病",1992,8,"A","","肺癌肺外表现中，以下哪项最常见",[["A","杵状指（趾）和肥大性骨关节病"],["B","重症肌无力"],["C","稀释性低钠血症"],["D","男性乳房发育"],["E","高血钙、低血磷"]],"A","肺癌的副癌综合征包括杵状指（趾）肥大性骨关节病（A）、分泌促肾上腺皮质激素样物、肌无力样综合征（B，注意与重症肌无力鉴别）、稀释性低钠血症（C）、男性乳房发育（D）、高钙血症（E）、类癌综合征，其中最常见的是杵状指（趾）和肥大性骨关节病（A对）。","","N"],["1992-N9",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎克雷伯杆菌肺炎诊断",1992,9,"A","","男性，68岁，高热三天伴咳嗽胸痛，多量黄绿色胶性痰。白细胞总数2万/μL，X线示右下肺实变，其间有不规则透亮区，叶间隙下坠，伴少量胸腔积液。最可能诊断为",[["A","肺炎球菌性肺炎"],["B","肺结核（干酪性肺炎）"],["C","克雷伯杆菌肺炎"],["D","肺曲菌病"],["E","绿脓杆菌性肺炎"]],"C","患者高热伴胸痛咳嗽、咳出大量黄绿色胶性痰（肺炎克雷伯杆菌的症状和体征），X线下可见右下肺实变，叶间隙下坠（肺炎克雷伯杆菌的X线征象），故最可能诊断为克雷伯杆菌肺炎（C对）。肺炎球菌性肺炎（十版内科学P51）（A错）起病急骤，痰液多呈铁锈色，X线表现为肺叶或肺段实变，不会出现叶间隙下坠；肺结核（十版内科学P73）（B错）多表现为咳嗽、咳痰及低热、乏力等全身中毒症状明显，影像特点为病变多位于上叶的尖后段、下叶的背段和后基底段，呈多态性；肺曲菌病（D错）常表现为反复发作性喘息、咳嗽、咳出棕黄色痰，X线表现为以胸膜为基底的楔形影、结节或团块影，内有空洞；绿脓杆菌性肺炎（E错）全身中毒症状明显，咳嗽、咳痰，痰液呈蓝绿色，X线表现为弥漫性支气管炎，早期肺脓肿。","","N"],["1992-N10",3,"第一节 支气管扩张症","支气管扩张诊断",1992,10,"A","","慢性支气管炎病人长期咳脓性痰合并以下哪种疾病较为多见",[["A","支气管哮喘"],["B","阻塞性肺气肿"],["C","鼻窦病变伴支气管扩张"],["D","活动性肺结核"],["E","肺囊肿"]],"C","支气管的慢性炎症长期刺激支气管，可使支气管平滑肌断裂，出现支气管扩张，支气管扩张（C对）的典型表现为持续或反复的咳嗽、咳痰且痰液多为脓性。支气管哮喘（十版内科学P32）（A错）的主要表现为发作性伴有哮鸣音的呼气性呼吸困难，可有咳嗽，如无继发感染痰液常为白色黏痰；阻塞性肺气肿（十版内科学P26）（B错）主要表现为咳嗽、咳痰、气短及呼吸困难，痰液一般为白色黏痰或浆液性泡沫痰，急性发作期可有脓痰；活动性肺结核（D错）多表现为咳嗽、咳痰，咳嗽较轻，干咳或少量黏液痰，合并细菌感染时可呈脓痰；肺囊肿（E错）可并发肺气肿，合并感染时可有脓痰。ABDE都不会出现长期咳脓性痰的表现。","","N"],["1992-N11",17,"第四节 急性冠状综合征","急性ST段抬高型心肌梗死诊断",1992,11,"A","","关于急性心肌梗塞的诊断，下列哪项是错误的",[["A","心电图上无病理性Q波者不能除外"],["B","右心室梗塞多伴发于下壁梗死"],["C","漂浮导管检查有助于急性心梗面积大小的判断"],["D","早期二维超声心动图检查对诊断有帮助"],["E","肺部啰音出现与否是判断有无左心功能不全的主要临床指标"]],"C","漂浮导管检测是经静脉插管直至肺动脉，测定各部位的压力及血液含氧量，计算心脏指数（CI）及肺毛细血管楔压（PCWP），直接反映左心功能，可以了解心功能情况，但不能直接判断急性心肌梗死的面积（C错，为本题正确答案）。非ST段抬高型心肌梗死心电图可不出现病理性Q波，因此没有出现病理性Q波不能除外急性心肌梗死（A对）。右心室梗塞多由右冠状动脉闭塞引起，而右冠状动脉及其分支主要供应右心室大部、左心室后壁、下壁，因此右心室梗塞多伴发于下壁梗死（B对）。早期二维超声心动图检查有助于了解心室壁的运动和左心室功能，并能发现室壁瘤、乳头肌功能失调、心包积液及室间隔穿孔等并发症，对诊断心梗有帮助（D对）。左心功能不全可致使肺淤血水肿，出现肺部啰音，因此肺部啰音是判断左室功能的主要临床指标之一（E对）。","","N"],["1992-N12",21,"第三节 二尖瓣狭窄","房颤",1992,12,"A","","二尖瓣狭窄最常见的心律失常是",[["A","房室传导阻滞"],["B","室性期前收缩"],["C","心房颤动"],["D","心室颤动"],["E","阵发性室上性心动过速"]],"C","二尖瓣狭窄血流动力学障碍的结果是左心房扩大，右心室肥厚扩大，左房压升高。心房结构改变可导致房性心律失常，常先有房性期前收缩，继而阵发性心房扑动和颤动，之后转变为慢性房颤。一般认为，房颤为二尖瓣狭窄最常见的心律失常（C对）。","","N"],["1992-N13",38,"第一节 消化道出血","出血程度的评估和周围循环状态的判断",1992,13,"A","","消化性溃疡活动期大便潜血阳性提示每天出血量不少于",[["A","＜1ml"],["B","1～2ml"],["C","2～3ml"],["D","3～4ml"],["E","5ml"]],"E","根据消化道出血的临床表现可大体作出出血程度及病因的判断。成人每日消化道出血＞5ml，粪便潜血试验即出现阳性（E对）；每日出血量超过50ml可出现黑粪；胃内积血量＞250ml可引起呕血；一次出血量＜400ml时，因轻度血容量减少可由组织液及脾脏贮血所补充，多不引起全身症状；出血量＞400ml，可出现头昏、心悸、乏力等症状；短时间内出血量＞1000ml，可出现休克表现。","","N"],["1992-N14",52,"第二节 急性白血病","ALL诱导缓解治疗",1992,14,"A","","下列哪种治疗白血病的药物不作用于S期",[["A","长春新碱"],["B","阿糖胞苷"],["C","甲氨蝶呤"],["D","羟基脲"],["E","6-硫代鸟嘌呤"]],"A","S期为DNA合成期。长春新碱作用靶点是微管，主要抑制微管蛋白的聚合而影响纺锤体微管的形成，作用于M期（A对），使有丝分裂停止。阿糖胞苷（B错）、甲氨蝶呤（C错）、羟基脲（D错）、6-硫代鸟嘌呤（E错）均为作用于S期的特异性DNA合成抑制药物。","","N"],["1992-N15",61,"第一节 糖尿病","糖尿病诊断标准",1992,15,"A","","患者身高170厘米，体重80kg，葡萄糖耐量试验结果为：空腹血糖125mg/dl，1小时185mg/dl，2小时160mg/dl，3小时132mg/dl，单凭此结果，哪种情况的可能性大",[["A","糖尿病"],["B","单纯性肥胖"],["C","脑垂体前叶功能亢进"],["D","肾上腺皮质功能亢进"],["E","以上均有可能"]],"E","本例患者空腹血糖为125mg/dl（6.9mmol/L，＜7.0mmol/L），糖耐量试验2小时为160mg/dl（8.9mmol/L，在7.8～11.0mmol/L之间），为IGT（糖耐量减低），虽未达到糖尿病诊断标准，但可能为糖尿病（A对）。患者体重指数BMI=27.7（80/1.7²）＞24，伴有糖耐量减低，可能为单纯性肥胖（肥胖症）（B对）。脑垂体前叶机能亢进包括巨人症或肢端肥大症，为生长激素分泌增多，生长激素有胰岛素抵抗的作用，从而导致糖耐量减低（十版内科学P672）（C对）。肾上腺皮质功能亢进时皮质醇分泌增多，而皮质醇有胰岛素抵抗的作用，即可导致糖耐量减低（十版内科学P710）（D对）。综上所述，糖尿病、单纯性肥胖、脑垂体前叶功能亢进和肾上腺皮质功能亢进均有可能。本题ABCD均对，正确答案为E。","","N"],["1992-N16",35,"第一节 肝硬化","肝硬化诊断",1992,16,"A","","对肝炎后肝硬化的诊断，下列哪项最有价值",[["A","脾大"],["B","蜘蛛痣"],["C","肝功能不正常"],["D","超声波显示肝回声不均质"],["E","食管钡餐检查下段有蚯蚓样充盈缺损"]],"E","肝硬化临床表现分为代偿期和失代偿期。失代偿期主要有肝功能减退和门静脉高压两类临床表现。脾大、食管静脉曲张为肝硬化门静脉高压所引起的临床表现，蜘蛛痣为肝功能减退所引起的临床表现。其中，食管静脉曲张（食管钡餐检查显示下段有蚯蚓样充盈缺损）由肝硬化门脉高压特异性引起，为诊断肝炎后肝硬化最有价值的体征（E对）。脾大（A错）虽可由肝硬化门脉高压引起，但也可由其他多种因素引起，如急性感染、血液系统疾病等，不具有特异性。蜘蛛痣（B错）由雌激素增多引起，不具有特异性。肝功能不正常（C错）、超声波显示肝回声不均质（D错）可有多种肝脏疾病引起，不具有特异性。","","N"],["1992-N17",59,"第一节 甲状腺功能亢进症","抗甲状腺药物",1992,17,"A","","硫脲类抗甲状腺药物的主要作用是",[["A","使体内甲状腺激素作用减弱"],["B","抑制碘的吸收"],["C","抑制甲状腺激素合成"],["D","抑制甲状腺激素的释放"],["E","抑制促甲状腺激素的作用"]],"C","硫脲类是常用的抗甲状腺药，主要作用是通过抑制甲状腺过氧化物酶，进而抑制酪氨酸的碘化及碘化酪氨酸缩合，从而抑制甲状腺激素合成（C对）。β受体阻断药可通过阻断β受体而改善甲亢所致的交感神经激活症状，使体内甲状腺激素作用减弱（A错）。大剂量碘剂可抑制甲状腺球蛋白的水解，从而抑制甲状腺激素的释放（D错），此外，大剂量碘剂还能拮抗TSH促进甲状腺素释放的作用（E错）。甲状腺功能低下患者，服用甲状腺素制剂，通过对腺垂体、下丘脑负反馈的作用，抑制TSH的分泌，从而抑制甲状腺激素的分泌，抑制碘的吸收（B错）。","","N"],["1992-N18",29,"第一节 肠结核","肠结核临床表现",1992,18,"A","","关于肠结核的临床表现，下列哪项不正确",[["A","腹泻是溃疡型肠结核的主要临床表现之一"],["B","腹部肿块主要见于增生型肠结核"],["C","多见于青少年与壮年"],["D","多数起病缓慢"],["E","多不伴有肺结核"]],"E","肠结核是结核分枝杆菌侵犯肠道引起的慢性特异性感染，多数起病缓慢，病程较长（D对）。本病多见于青少年与壮年（C对），女性多于男性。患有肠结核的病人多有开放性肺结核或喉结核（90%的肠结核、骨结核、肾结核都是由肺结核引起）（E错，为本题正确答案），肠结核也可由血型播散所致，或由腹腔内或盆腔内结核病灶直接蔓延所致。肠结核根据其病理特点分为溃疡型肠结核、增生型肠结核及混合型肠结核（十版内科学P388）。腹泻是溃疡型肠结核的主要临床表现之一（A对），系由于病变肠管炎症和溃疡使肠蠕动加速，肠排空过快所致，无黏液脓血，无里急后重。增生型肠结核粘膜下层及浆膜层有大量结核肉芽肿和纤维组织增生，因此腹部肿块主要见于增生型肠结核（B对）。","","N"],["1992-N19",52,"第二节 急性白血病","出血",1992,19,"A","","下列哪一型白血病最易发生播散性血管内凝血",[["A","急性单核细胞性白血病"],["B","急性粒-单核细胞白血病"],["C","急性红白血病"],["D","急性早幼粒细胞性白血病"],["E","急性原始粒细胞性白血病"]],"D","白血病分为急性白血病（AL）和慢性白血病（CL），根据主要受累的细胞系列可将AL分为急性淋巴细胞白血病（ALL）和急性髓系白血病（AML）。CL则分为慢性髓系白血病（CML）、慢性淋巴细胞白血病（CLL）及少见类型的白血病。其中AML的M₃型（急性早幼粒白血病，APL）最易发生DIC（弥漫性或播散性血管内凝血）（D对）。这可能与以下机制有关：1.在M₃型患者中血小板的黏附、聚集和释放功能比其他类型的更差；2.异常的早幼粒细胞内丰富的嗜苯氨蓝颗粒中含有大量的促凝物质，当此细胞被破坏即释放大量的促凝物质诱发DIC；3.APL的细胞染色体t（15；17）形成的PML/RARa融合基因导致了血浆组织因子（TF）的高表达与高凝状态。","","N"],["1992-N21",46,"第一节 贫血概述","贫血分类",1992,21,"A","","下列哪个肯定不是低色素小细胞性贫血",[["A","海洋性贫血"],["B","铁粒幼细胞性贫血"],["C","再生障碍性贫血"],["D","慢性疾病贫血"],["E","缺铁性贫血"]],"C","低色素小细胞性贫血（小细胞低色素性贫血）指红细胞平均体积减小（＜80fl），红细胞平均血红蛋白浓度降低（＜32%）的贫血，包括缺铁性贫血、珠蛋白生成障碍性贫血（海洋性贫血）以及铁粒幼细胞性贫血等。缺铁性贫血（十版内科学P549）指原料铁缺乏所致的血红素、血红蛋白合成减少，表现为小细胞低色素性贫血（E对）。海洋性贫血（十版内科学P563）是因基因异常导致珠蛋白合成障碍所致的溶血性贫血，以溶血、无效红细胞生成及不同程度的小细胞低色素性贫血为特征（A对）。铁粒幼细胞性贫血（十版内科学P551）是各种原因引起铁利用障碍所致的贫血，表现为小细胞低色素性贫血（B对）。慢性疾病贫血是由慢性炎症、感染或肿瘤等引起的铁代谢异常性贫血，表现为小细胞低色素性贫血（D对）。再生障碍性贫血（十版内科学P555）（C错，为本题正确答案）是一种骨髓造血功能衰竭症，生成的红细胞数量下降，质量多正常，表现为正常细胞性贫血。","","N"],["1992-N22",40,"第七节 慢性肾小球肾炎","慢性肾小球肾炎诊断",1992,22,"A","","患者男性，34岁，一周前曾感冒低热二天，近三天来发现下肢浮肿，血压20/12KPa（150/90mmHg），尿蛋白（+++），尿沉渣镜检红细胞20～40/高倍视野，颗粒管型偶见，血红蛋白9.8g/dl，A/G2.2/2.4，最可能的临床诊断为",[["A","急性肾炎"],["B","慢性肾炎急性发作"],["C","慢性肾盂肾炎急性发作"],["D","隐匿性肾炎"],["E","狼疮性肾炎"]],"B","青年男性患者，一周前感冒低热2天（慢性肾炎急性发作诱因），近3天来下肢浮肿、血压升高、尿检出现蛋白尿、血尿、A/G比例倒置（肾炎综合征），可拟诊为肾炎。其血红蛋白9.8g/dl（正常成年男性血红蛋白12g/dl～16g/dl）提示出现贫血（多提示慢性病程），因此其最可能的诊断为慢性肾炎急性发作（B对）。急性肾炎（A错）可表现为急性肾炎综合征，但一般无贫血。慢性肾盂肾炎急性发作（C错）多表现为发热、恶心呕吐等感染中毒症状以及腰痛、肾区叩痛及尿路刺激征（十版内科学P501），其肾小球受损较轻，因此较少出现大量蛋白尿，与本例尿蛋白（+++）及A/G比例倒置不符。隐匿性肾炎（D错）又称无症状性血尿或（和）蛋白尿，一般无高血压、水肿及肾功能损害。狼疮性肾炎（E错）多见于青年女性，且往往存在系统性红斑狼疮相关症状，与本例不符。","","N"],["1992-N23",30,"第一节 溃疡性结肠炎","溃疡性结肠炎诊断",1992,23,"A","","男50岁，半年来反复出现腹泻，粪便糊样，时有腹泻和便秘交替。检查轻度贫血貌，右下腹部可扪及肿块。胃肠X线检查示回盲部钡剂充盈缺损，考虑排除下列哪种疾病",[["A","结肠癌"],["B","Crohn病"],["C","血吸虫病性肉芽肿"],["D","肠结核"],["E","慢性溃疡性结肠炎"]],"E","中年男性患者，反复腹泻半年，粪便糊样，时有腹泻与便秘交替，贫血，右下腹部可扪及肿块，胃肠X线检查显示回盲部充盈缺损，首先可以排除溃疡性结肠炎，因溃疡性结肠炎病变多位于直肠和乙状结肠，较少累及回盲部，绝大多数患者有黏液脓血便，且一般无腹部肿块（E对）。右半结肠癌（A错）病变可位于回盲部，右下腹部可扪及肿块，可有腹泻和便秘交替，可有贫血貌，与患者症状和体征大致相符，不能排除。克罗恩病（B错）病变主要位于回肠末端及邻近结肠，右下腹肿块见于10%～20%的患者，也可伴有贫血，与患者症状和体征大致相符，不能排除。肠结核（D错）病变主要位于回盲部，增生型肠结核可有右下腹肿块，常有腹泻和便秘交替，与患者症状和体征基本相符，不能排除。血吸虫病性肉芽肿（C错）系肠道血吸虫病的一种晚期表现，血吸虫卵沉积部位除结肠外主要是回肠末端，右下腹部可扪及肿块，与患者症状和体征大致相符，不能排除。","","N"],["1992-N24",27,"","",1992,24,"A","","女25岁，昨晚吃剩饭一碗，当夜发生上腹痛，持续恶心、呕吐。体温36.5℃，上腹部压痛，肠鸣音活跃。白细胞总数、分类及粪常规正常，首先考虑",[["A","急性胃炎"],["B","急性胰腺炎"],["C","胃溃疡"],["D","胆囊炎"],["E","胃神经官能症"]],"A","青年女性患者，有明确吃剩饭史（食物刺激），急性起病，临床主要表现为上腹痛，持续恶心、呕吐，上腹部压痛，肠鸣音活跃，无发热（无感染），白细胞总数、分类及粪常规正常，所以首先考虑为急性胃炎（A对）。急性胰腺炎（B错）和胆囊炎（D错）均为急性起病，腹痛剧烈，常伴发热，白细胞数常增高，本例不支持；胃溃疡（C错）表现为餐后上腹痛，但为慢性过程，反复发作，常有溃疡病史，本病例未提及；胃神经官能症（E错）是一种功能性疾病，并没有器质性的病变，又称胃肠道功能紊乱，是神经性胃炎、神经性呕吐、神经性厌食的总称，常有相应病史，本例未提及，所以也不考虑。","","N"],["1992-N37",10,"第三节 慢性肺源性心脏病","心脏病变和心力衰竭",1992,37,"A","","下列哪项是慢性肺源性心脏病所不具备的",[["A","慢性阻塞性肺疾病"],["B","肺动脉高压"],["C","肺动脉硬化"],["D","右心室肥大"],["E","肺动脉主干栓塞"]],"E","肺源性心脏病（简称肺心病）主要是由于支气管-肺组织、胸廓或肺动脉血管病变所致肺血管阻力增加，产生肺动脉高压（B对），继而引起右心室肥大（D对）的心脏病。慢性肺心病的病因主要包括四类：①支气管、肺疾病，以慢支并发阻塞性肺气肿（A对）最为多见；②胸廓运动障碍性疾病；③肺血管疾病，肺动脉硬化（C对）可以使肺动脉压升高和右心负荷加重，发展成慢性肺心病；④其他，包括原发性肺泡通气不足及先天性口咽畸形、睡眠呼吸暂停低通气综合征等均可引起低氧血症，导致肺血管收缩，肺动脉高压，发展为慢性肺心病。肺动脉主干栓塞（E错，为本题正确答案）以肺循环和呼吸功能障碍为主要表现，严重时会发生猝死，不会引起慢性肺源性心脏病。","","N"],["1992-N70",44,"第一节 急性肾损伤","急性肾损伤病因和分类",1992,70,"A","","关于急性肾功能衰竭，下列哪项说法是错误的",[["A","急性肾功能衰竭是各种急腹症常见的并发症"],["B","肾前性肾功能衰竭，只要警惕到发生的可能，是可以预防的"],["C","肾后性肾功能衰竭，若能及时解除尿路梗阻，预后良好"],["D","尿量、比重及血尿素氮、肌酐等测定可用于急性肾功能衰竭的诊断"]],"A","部分急腹症可引起急性肾功能衰竭，但急性肾衰竭并非各种急腹症的常见并发症（A错，为本题正确答案）。肾前性肾功能衰竭多由于肾脏血液灌流不足导致（P511），患者多有可导致有效循环血量不足的某些基础疾病，只要警惕到发生的可能，及时纠正低灌注状态，肾前性肾功能衰竭是可以预防的（B对）。肾后性肾功能衰竭常见于急性尿路梗阻，早期肾脏病变轻微，及时解除梗阻可降低囊内压，GFR可恢复正常，预后通常良好（C对）。急性肾功能衰竭时，尿量降低、血尿素氮及肌酐升高，因此尿量、比重及血尿素氮、肌酐等测定可用于急性肾功能衰竭的诊断（D对）。","","N"],["1992-N81",15,"第二节 慢性心力衰竭","洋地黄类药物",1992,81,"B","","洋地黄中毒所致室性心动过速首选",[["A","利多卡因"],["B","苯妥英钠"],["C","异搏定"],["D","乙胺碘呋酮"],["E","溴苄胺"]],"B","利多卡因（A错）可用于治疗洋地黄中毒引起的室性心动过速和心室纤颤，而苯妥英钠（八版药理学P196）（B对）不仅可以对抗洋地黄引起的心律失常，还能与洋地黄竞争Na⁺-K⁺-ATP酶，恢复该酶的活性，有解毒效应，因而治疗效果较利多卡因更好。异搏定（C错）又称维拉帕米，用于治疗快速性室上性心律失常，使阵发性室上性心动过速转为窦性，或在心房扑动或心房颤动时减慢心室率，也可用于肥厚型心肌病。乙胺碘呋酮（又称盐酸胺碘酮）（D错）临床用于室性心动过速和室上性心动过速、期前收缩、阵发性心房扑动，并不作为洋地黄中毒致室性心动过速的首选药。溴苄胺（E错）适用于治疗及预防心室颤动，也适用于对常规第一线抗心律失常药物无效的致命性室性心律失常，如频发室性期前收缩、短阵室性心动过速、心室扑动、心室颤动等的治疗。","","N"],["1992-N82",16,"第四节 房室交界性心律失常","急性发作期",1992,82,"B","","预激综合征伴快速心房颤动首选",[["A","利多卡因"],["B","苯妥英钠"],["C","异搏定"],["D","乙胺碘呋酮"],["E","溴苄胺"]],"D","预激综合征伴快速心房颤动时，过快的心房率可经不应期较短的旁路下传，导致心室率极快，导致心输出量剧降，可出现晕厥及低血压，须紧急处理。应立即电复律，药物治疗首选普鲁卡因胺、普罗帕酮或胺碘酮（又名乙胺碘呋酮）（D对）等延长房室旁路不应期的药物。利多卡因（A错）或苯妥英钠（B错）可用于洋地黄中毒引起的室性心动过速（九版内科学P173）。异搏定（C错）又称维拉帕米，用于治疗快速性室上性心律失常，使阵发性室上性心动过速转为窦性，或在心房扑动或心房颤动时减慢心室率，也可用于肥厚型心肌病，但用于预激伴房颤患者可加快心室率，甚至诱发室颤。溴苄胺（E错）适用于治疗及预防心室颤动，也适用于对常规第一线抗心律失常药物无效的致命性室性心律失常，如频发室性期前收缩、短阵室性心动过速、心室扑动、心室颤动等的治疗。（10版内科学P208：预激伴房颤（房扑）的病人，终止心动过速首选电复律，或静脉注射伊布利特或普罗帕酮，不应使用β受体拮抗剂、维拉帕米、地尔硫䓬、洋地黄类药物和胺碘酮，因为这些抗心律失常药可能抑制房室结传导从而加剧旁道下传，有诱发室颤的风险。）","","N"],["1992-N83",52,"第二节 急性白血病","正常骨髓造血功能受抑制表现",1992,83,"B","","急性白血病的主要临床表现",[["A","发热、贫血、出血"],["B","出血"],["C","贫血"],["D","发热、贫血、出血、肝脾大"],["E","明显的脾大"]],"D","急性白血病的特征性临床表现为发热、贫血、出血和肝脾肿大（D对）。该病是造血干细胞的恶性克隆性疾病，白血病细胞大量增殖并抑制正常造血，外周血中红细胞、血小板和正常的白细胞数量均下降，表现为贫血、出血和感染（发热）。另外，由于该病是恶性克隆性疾病，会有白血病细胞增殖浸润的表现，如淋巴结肿大，肝、脾肿大，骨骼和关节疼痛，眼部的粒细胞瘤，口腔和皮肤的肿胀，中枢神经系统和睾丸的浸润等（D对）。","","N"],["1992-N84",49,"第一节 再生障碍性贫血","重型再生障碍性贫血",1992,84,"B","","再生障碍性贫血的主要临床表现",[["A","发热、贫血、出血"],["B","出血"],["C","贫血"],["D","发热、贫血、出血、肝脾大"],["E","明显的脾大"]],"A","再生障碍性贫血是由于不同病因和机制引起的骨髓造血功能衰竭症，主要表现为骨髓造血功能低下，全血细胞减少以及贫血、出血和感染（A对）。再障不是恶性克隆性疾病，无增殖浸润，故无肝脾肿大（DE错）。","","N"],["1992-N85",60,"第一节 库欣综合征","库欣综合征病因诊断",1992,85,"B","","鉴别诊断皮质醇增多症是因垂体肿瘤或肾上腺肿瘤引起的试验",[["A","小剂量地塞米松抑制试验"],["B","大剂量地塞米松抑制试验"],["C","VMA测定"],["D","尿17-OHCS、17-KS测定"],["E","酚苄明试验"]],"B","大剂量地塞米松抑制试验方法：口服地塞米松2mg，1次/6小时，共2天。结果分析：服药后，血、尿皮质醇值降至对照值的50%以下为抑制试验阳性。临床意义：用于鉴别皮质醇增多症的病因。正常人糖皮质激素的分泌受下丘脑（CRH，促肾上腺激素释放激素）-垂体（ACTH，促肾上腺激素）-肾上腺皮质（GC，糖皮质激素）轴的调节，当给予外源性糖皮质激素时，垂体ACTH分泌受抑制，从而皮质醇分泌减少。垂体肿瘤可致ACTH分泌增多，血皮质醇过高，给予小剂量地塞米松，对血皮质醇影响不大，故不能被小剂量地塞米松抑制试验抑制，但给予大剂量地塞米松能抑制垂体ACTH分泌，使血皮质醇减少，从而能被大剂量地塞米松抑制试验抑制；肾上腺肿瘤为自主分泌皮质醇，引起的高皮质醇血症已在很大程度上抑制了垂体ACTH的分泌，再给予外源性糖皮质激素，也不会对垂体ACTH分泌有多大影响，血、尿皮质醇亦变化不大，因此不能被大剂量地塞米松抑制试验抑制（B对）。皮质醇增多症均不能被小剂量地塞米松抑制试验抑制，小剂量地塞米松抑制试验（A错）对明确皮质醇增多症的病因无意义。VMA即尿内儿茶酚胺的代谢产物，VMA增高见于嗜铬细胞瘤，VMA测定（C错）主要用于嗜铬细胞瘤的诊断。尿17-羟皮质类固醇（17-OHCS）、17-酮类固醇（17-KS）均为肾上腺皮质激素的代谢产物，皮质醇增多症尿17-OHCS、17-KS均增高，尿17-OHCS、17-KS测定（D错）对明确皮质醇增多症的病因无意义。酚苄明为α₁、α₂受体阻断剂，作用与酚妥拉明相似，酚苄明试验（E错）主要用于诊断嗜铬细胞瘤。","","N"],["1992-N86",60,"第一节 库欣综合征","库欣综合征病因诊断",1992,86,"B","","鉴别单纯性肥胖及皮质醇增多症的试验",[["A","小剂量地塞米松抑制试验"],["B","大剂量地塞米松抑制试验"],["C","VMA测定"],["D","尿17-OHCS、17-KS测定"],["E","酚苄明试验"]],"A","小剂量地塞米松抑制试验方法是口服地塞米松0.5mg，6小时一次，连服两日，主要用于鉴别单纯性肥胖和皮质醇增多症。肥胖者小剂量地塞米松抑制试验为阳性（服药后第2日24小时尿17-羟皮质类固醇排出量较对照日减少50%以上），而皮质醇增多症患者小剂量地塞米松抑制试验为阴性（A对）。大剂量地塞米松抑制试验（B错）用于鉴别Cushing综合征的病因：垂体性Cushing病大剂量地塞米松抑制试验阳性，肾上腺皮质肿瘤及异位ACTH综合征大剂量地塞米松抑制试验为阴性。VMA即尿内儿茶酚胺的代谢产物，VMA增高见于嗜铬细胞瘤，VMA测定（C错）主要用于嗜铬细胞瘤的诊断。鉴别皮质醇增多症及单纯性肥胖者测定的是尿游离皮质醇而不是尿17-羟皮质类固醇（17-OHCS）、17-酮类固醇（17-KS）（D错）。酚苄明为α₁、α₂受体阻断剂，作用与酚妥拉明相似，酚苄明试验（E错）主要用于诊断嗜铬细胞瘤。","","N"],["1992-N95",27,"第二节 慢性胃炎","慢性胃炎胃镜及组织学病理",1992,95,"B","","重度胃体萎缩型胃炎",[["A","胃液酸度升高"],["B","胃液酸度正常或减少"],["C","胃液酸度常减少"],["D","胃液酸度明显升高"],["E","胃液酸度明显减少"]],"E","重度胃体萎缩型胃炎时，壁细胞分泌胃酸明显受到抑制（壁细胞位于胃体），所以胃液酸度明显减少（E对）。胃液酸度升高（A错）多见于十二指肠溃疡。胃酸分泌正常或偏低（B错）多见于多灶萎缩性胃炎和胃溃疡。胃酸分泌明显增加（D错）多见于胃泌素瘤。胃酸分泌减少（C错）见于B型胃炎。","","N"],["1992-N96",66,"","",1992,96,"B","","胃泌素瘤",[["A","胃液酸度升高"],["B","胃液酸度正常或减少"],["C","胃液酸度常减少"],["D","胃液酸度明显升高"],["E","胃液酸度明显减少"]],"D","胃泌素瘤分泌大量胃泌素，可刺激壁细胞增生，分泌大量胃酸，胃液酸度明显升高（D对）。胃液酸度升高（A错）见于十二指肠溃疡。胃液酸度正常或减少（B错）见于胃溃疡和多灶萎缩胃炎。胃液酸度明显减小（E错）见于重度胃体萎缩型胃炎：壁细胞位于胃体，胃体重度萎缩时壁细胞分泌胃酸明显受到抑制。","","N"],["1992-N97",37,"第一节 急性胰腺炎","急性胰腺炎发病机制",1992,97,"B","","引起胰腺坏死是因",[["A","激活弹力纤维酶"],["B","激活磷脂酶A"],["C","激活胰舒血管素"],["D","激活胰蛋白酶"],["E","激活血浆激肽"]],"D","急性胰腺炎的发病机制是胰酶自身消化导致胰腺及其周围组织损伤。急性胰腺炎时，首先激活胰蛋白酶原，形成胰蛋白酶，在胰蛋白酶作用下使各种胰消化酶原被激活为有生物活性的消化酶。一旦各种消化酶原激活后，其中起主要作用的活化酶有磷脂酶A₂、激肽释放酶或胰舒血管素、弹性蛋白酶和脂肪酶。弹力纤维酶（A错）可溶解血管弹性纤维引起出血和血栓形成；磷脂酶A（B错）的细胞毒作用引起胰实质凝固性坏死、脂肪组织坏死和溶血；激肽释放酶或胰舒血管素（C错）可使血浆中激肽酶原转变为激肽（E错），后者可使血管舒张和通透性增加，引起水肿和休克；脂肪酶参与胰腺及周围脂肪坏死和液化作用。上述消化酶共同作用，造成胰腺坏死。但引起上述酶激活的为胰蛋白酶，可见引起胰腺坏死是因激活胰蛋白酶（D对）。","","N"],["1992-N98",37,"第一节 急性胰腺炎","急性胰腺炎发病机制",1992,98,"B","","可损害其他脏器和引起休克是因",[["A","激活弹力纤维酶"],["B","激活磷脂酶A"],["C","激活胰舒血管素"],["D","激活胰蛋白酶"],["E","激活血浆激肽"]],"E","急性胰腺炎时，胰蛋白酶原首先激活，形成胰蛋白酶，胰蛋白酶（D错）使各种胰消化酶原被激活为有生物活性的消化酶。各种消化酶原激活后，其中起主要作用的活化酶有磷脂酶A₂、激肽释放酶或胰舒血管素、弹性蛋白酶和脂肪酶。激肽释放酶或胰舒血管素（C错）可使血浆中激肽酶原转变为激肽，激肽（E对）可使血管舒张和通透性增加，引起水肿和休克。弹力纤维酶（A错）可溶解血管弹性纤维引起出血和血栓形成。磷脂酶A₂（B错）的细胞毒作用引起胰实质凝固性坏死、脂肪组织坏死和溶血。脂肪酶参与胰腺及周围脂肪坏死和液化作用。","","N"],["1992-N113",39,"第一节 总论","尿常规检查",1992,113,"C","","肾小球肾炎",[["A","尿沉渣镜检有大量变形红细胞"],["B","尿沉渣镜检有多个嗜酸性粒细胞"],["C","两者皆有"],["D","两者皆无"]],"A","肾小球源性血尿产生的主要原因为GBM断裂，红细胞通过该裂缝时受血管内压力挤压受损，受损的红细胞后通过肾小管各段又受不同渗透压和pH作用呈现变形红细胞（A对）血尿，红细胞容积变小，甚至破裂。尿沉渣镜检有多个嗜酸性粒细胞（B错）见于过敏性疾病、皮肤病、寄生虫病、某些血液病等。","","N"],["1992-N114",39,"第一节 总论","尿常规检查",1992,114,"C","","糖尿病性肾病",[["A","尿沉渣镜检有大量变形红细胞"],["B","尿沉渣镜检有多个嗜酸性粒细胞"],["C","两者皆有"],["D","两者皆无"]],"A","糖尿病性肾病患者可出现微量甚至大量蛋白尿，若其滤过屏障严重受损也可出现肾小球源性血尿，即尿沉渣镜检有大量变形红细胞（A对）。尿沉渣镜检有多个嗜酸性粒细胞（B错）见于过敏性疾病、皮肤病、寄生虫病、某些血液病等。","","N"],["1992-N115",2,"第一节 支气管哮喘","抗胆碱药",1992,115,"C","","抗胆碱类药物",[["A","抑制肥大细胞释放介质"],["B","预防哮喘发作"],["C","两者皆有"],["D","两者皆无"]],"A","乙酰胆碱兴奋M胆碱受体，可增加鸟苷酸环化酶活性，促进三磷酸鸟苷（GTP）转化为环磷酸鸟苷（cGMP），可增加生物活性物质释放，使支气管收缩，发生哮喘（与1999N58AC选项知识点类似）。使用抗胆碱类药物，可抑制乙酰胆碱，使生物活性物质释放减少（A对）。抗胆碱药分为短效抗胆碱药（SAMA）和长效抗胆碱药（LAMA），SAMA主要用于哮喘急性发作的治疗，LAMA主要用于哮喘合并慢阻肺以及慢阻肺患者的长期治疗，不用于哮喘发作的预防（B错）。","","N"],["1992-N116",2,"第一节 支气管哮喘","药物分类和作用特点",1992,116,"C","","色苷酸二钠",[["A","抑制肥大细胞释放介质"],["B","预防哮喘发作"],["C","两者皆有"],["D","两者皆无"]],"C","色苷酸钠具有稳定肥大细胞膜作用，可以抑制肥大细胞释放介质（A对）。此药为预防哮喘发作的药物（八版药理学P297）（B对）。本题AB均对，正确答案为C。","","N"],["1992-N121",28,"第一节 消化性溃疡","出血",1992,121,"C","","多数十二指肠溃疡出血的临床表现是",[["A","柏油样黑便"],["B","呕大量鲜红血可伴休克"],["C","两者均有"],["D","两者均无"]],"A","十二指肠溃疡较胃溃疡易并发上消化道出血（十版内科学P375）。当消化性溃疡侵蚀周围或深处的血管，可产生不同程度的出血。轻者可表现为黑便（A对），重者出现呕血。黑便通常是由上消化道（屈式韧带以上）出血造成的，当血中的红细胞在肠道内分解时，血红蛋白铁在胃酸和肠道大肠杆菌等细菌的作用下，与粪便中的硫化物结合成为黑色的硫化铁，出现黑便，而且硫化铁刺激肠壁，使黏膜分泌大量黏液，大便因此呈现出像柏油似的油性光泽。十二指肠溃疡出血位于幽门以下，且其出血相对较缓、出血量不大，因此呕大量鲜红血可伴休克（B错）一般出现在肝硬化引起的胃食管胃底静脉曲张破裂出血，而十二指肠溃疡出血少见。","","N"],["1992-N122",35,"第一节 肝硬化","食管胃底静脉曲张出血",1992,122,"C","","食管静脉曲张出血的临床表现是",[["A","柏油样黑便"],["B","呕大量鲜红血可伴休克"],["C","两者均有"],["D","两者均无"]],"C","食管曲张静脉表面黏膜菲薄，且管内血压高，一旦发生破裂，则引起严重的出血，临床表现为呕大量鲜红血，来势很猛，一次出血量常达500～1000ml以上，可引起休克（B对）。此外，部分血液进入肠腔，引起柏油样黑便（A对）。本题AB均对，正确答案为C。","","N"],["1992-N127",35,"第一节 肝硬化","及早识别及去除HE发作的诱因",1992,127,"C","","肝昏迷病人",[["A","生理盐水灌肠"],["B","肥皂水灌肠"],["C","两者均可用"],["D","两者均不可用"]],"A","氨以非离子型氨（NH₃）和离子型氨（NH₄⁺）两种形式存在，氨在肠道的吸收主要以NH₃弥散入肠黏膜，当结肠内pH˃6时，NH₄⁺转为NH₃，大量弥散入血；pH＜6时，则NH₃从血液转至肠腔，随粪排泄（P408）。肥皂水为碱性，可促进肠道内的氨吸收入血使血氨升高。游离的NH₃有毒性，且能透过血脑屏障，加重肝性脑病。故肝性昏迷病人可用生理盐水（A对）或弱酸液（如稀醋酸溶液）灌肠而不可用肥皂水灌肠（B错）。","","N"],["1992-N128",61,"第二节 糖尿病酮症酸中毒","糖尿病酮症酸中毒治疗",1992,128,"C","","糖尿病昏迷病人",[["A","生理盐水灌肠"],["B","肥皂水灌肠"],["C","两者均可用"],["D","两者均不可用"]],"C","肥皂水为碱性，糖尿病昏迷病人是酮症酸中毒，故灌肠时用生理盐水（A对）和肥皂水（B对）都可。本题AB均对，正确答案为C。注意：氨以游离型氨（NH₃）和离子型氨（NH₄⁺）两种形式存在，游离的NH₃有毒性，且能透过血脑屏障。氨在肠道的吸收主要以NH₃弥散入肠黏膜，当pH＜6时，则NH₃从血液转至肠腔，随粪排泄；结肠内pH＞6时，NH₄⁺转为NH₃，大量弥散入血（十版内科学P420）。由于肥皂水为碱性，故肝性昏迷病人不可用肥皂水灌肠。","","N"],["1992-N130",39,"第一节 总论","尿液检查",1992,130,"X","","临床上肾髓质功能的检查法有",[["A","尿比重"],["B","尿浓缩稀释试验"],["C","尿渗透压"],["D","肌酐清除率"]],"ABC","肾髓质功能主要指肾小管的功能，主要包括浓缩、稀释功能、重吸收功能和酸化功能，尿浓缩和稀释试验（B对）最简单的方法是测定尿比重方法，即尿比重（A对）、尿渗透压（C对）用于临床上肾髓质功能的检查。肌酐清除率（D错）主要用于评估肾皮质（肾小球滤过）功能，无法评估肾髓质功能。","","N"],["1992-N131",61,"第一节 糖尿病","促胰岛素分泌剂",1992,131,"X","","口服降糖药达美康比优降糖有下列优点",[["A","对预防微血管病变有利"],["B","降血糖作用较强"],["C","Ⅰ型糖尿病有效"],["D","可预防冠心病"]],"AD","达美康（格列齐特）能降低血小板粘附力，减少血浆比粘度，降低ADP诱导的血小板聚集，改善微循环，对微血管病变有一定的预防作用（A对），还能降低胆固醇蓄积，减少主动脉三磷酸甘油酯和脂肪酸的血浆浓度，预防冠心病（D对）。优降糖（格列本脲）降糖作用较强（B错）。达美康和优降糖为磺酰脲类，属于促胰岛素分泌剂，Ⅰ型糖尿病为胰岛β细胞破坏，胰岛素绝对缺乏，故促胰岛素分泌剂均无效（C错）。","","N"],["1992-N132",19,"第一节 肥厚型心肌病","肥厚型心肌病诊断",1992,132,"X","","哪些病变可出现脑栓塞并发症",[["A","肥厚型心肌病"],["B","右房黏液瘤"],["C","急性心肌梗死"],["D","急性心肌炎"]],"AC","脑栓塞是指血液中的各种栓子（如心脏内的附壁血栓、动脉粥样硬化的斑块、脂肪等）随血流进入脑动脉而阻塞血管，引起该动脉供血区脑组织缺血性坏死，出现局灶性神经功能缺损。肥厚型心肌病（A对）主要以心室非对称性肥厚为解剖特点，心电图变化多端，患者同时可伴有室内传导阻滞和其他各类心律失常（如房颤）。房颤时，心房不能有效地泵出血液，血液滞留在心房内，容易形成附壁血栓，脱落后可引起栓塞并发症。急性心肌梗死（C对）累及心室壁的全层或大部分者，可导致心室腔内附壁血栓形成，脱落后可引起栓塞并发症。慢性心肌炎可形成附壁血栓，脱落后导致脑栓塞，但急性心肌炎（D错）一般不形成血栓，不引起脑栓塞。右房黏液瘤（B错）脱落血栓进入肺动脉，堵塞肺动脉或其分支引起肺循环障碍，与体循环无关。","","N"],["1992-N133",28,"第一节 消化性溃疡","球后溃疡",1992,133,"X","","背部疼痛可发生于",[["A","胰腺癌"],["B","球后溃疡"],["C","幽门梗阻"],["D","穿透性溃疡"]],"ABD","胰腺位于后腹部，当发生胰腺癌（A对）时，癌组织可浸润或压迫腹腔后部神经丛，因此引起背痛；球后溃疡（B对）多位于十二指肠降段的初始部及乳头附近，溃疡多在后内侧壁，可穿透入胰腺，引起后背部放射性痛；穿透性溃疡（D对）发生于后壁累及胰腺时亦同样引起背痛。幽门梗阻（C错）多由复合溃疡及幽门管溃疡引起，主要表现为明显上腹胀痛，餐后加重，呕吐后腹痛可稍缓解，一般不引起背部疼痛。","","N"],["1992-N134",51,"第一节 骨髓增生异常性肿瘤","骨髓增生异常性肿瘤实验室检查",1992,134,"X","","下列哪几个疾病可表现为全血细胞减少",[["A","阵发性睡眠性血红蛋白尿症"],["B","骨髓异常增生综合征"],["C","急性白血病"],["D","营养不良性巨幼细胞性贫血"]],"ABCD","可导致全血细胞减少的疾病包括再生障碍性贫血、骨髓增生异常综合征（B对）、急性白血病（C对）、阵发性睡眠性血红蛋白尿（A对）、巨幼细胞贫血（D对）、Fanconi贫血、Evans综合征、免疫相关性全血细胞减少及恶性组织细胞病等。阵发性睡眠性血红蛋白尿（十版内科学P567）是一种后天获得性造血干细胞基因突变所致的红细胞膜缺陷性溶血病，主要表现为慢性血管内溶血性贫血和血红蛋白尿，约半数患者可表现为全血细胞减少。骨髓增生异常综合征是起源于造血干细胞的克隆性疾病，异常克隆细胞在骨髓中分化、成熟障碍，出现病态造血，表现为持续性一系或多系血细胞减少，50%～70%的患者为全血细胞减少。急性白血病是一种造血干祖细胞的恶性克隆性疾病，发病时骨髓中异常的原始细胞及幼稚细胞（白血病细胞）大量增殖，抑制正常造血，导致外周全血细胞减少。巨幼细胞贫血是由于维生素B₁₂或（和）叶酸缺乏而导致的贫血，重者骨髓中红系、粒系和巨核系细胞均可发生巨幼变，因此可导致全血细胞减少。","","N"],["1992-N135",10,"第三节 慢性肺源性心脏病","血管扩张药",1992,135,"X","","苄胺唑啉和硝普钠用于慢性肺心病的原理为",[["A","缓解支气管平滑肌痉挛，改善通气功能"],["B","降低肺动脉压，改善心功能"],["C","降低肺静脉压，减轻肺淤血"],["D","扩张外周动脉血管，降低心脏后负荷"]],"AB","慢性肺心病患者由于各种病变导致肺血管阻力增加，产生肺动脉高压，继而导致右心室结构和功能改变。苄胺唑啉又称酚妥拉明，为α肾上腺素受体阻滞剂（十版内科学P187），可使血管平滑肌舒张，从而扩张血管，降低外周阻力，并降低肺毛细血管压，进而降低肺动脉压，减轻右心后负荷，改善慢性肺心病患者的右心功能（B对）；外周血管阻力下降，减轻左心后负荷，左心排血量增多，左心功能改善；经研究证实，支气管平滑肌上有α受体存在，酚妥拉明可舒张支气管平滑肌，解除支气管痉挛，改善通气功能（A对）。硝普钠（十版内科学P187）为动、静脉血管扩张剂，扩张静脉，可使静脉回心血量减少，减轻右心前负荷，改善右心功能，降低肺动脉压（B对）；扩张动脉，降低外周血管阻力，减轻左心后负荷，改善左心功能。虽然两者均可扩张动脉，降低外周血管阻力，降低心脏后负荷，但此作用是针对左心衰竭的治疗，不是针对肺心病的治疗原理（D错）。肺静脉压升高、肺淤血为左心衰竭的表现，慢性肺心病患者主要表现为右心功能不全（C错）。","","N"],["1992-N136",27,"第二节 慢性胃炎","慢性胃炎胃镜及组织学病理",1992,136,"X","","关于萎缩性胃窦胃炎，下列哪几项正确",[["A","可同时伴有胃体黏膜灶性萎缩"],["B","可伴有浅表性胃炎"],["C","可能与幽门螺杆菌无关"],["D","可能与胆汁反流有关"]],"ABCD","慢性萎缩性胃炎分为自身免疫性胃炎（A型胃炎、慢性胃体炎）和多灶萎缩性胃炎（B型胃炎、慢性胃窦炎）。萎缩性胃窦胃炎萎缩性改变在胃内呈多灶性分布，以胃窦部为主，可同时伴有胃体黏膜灶性萎缩（A对）。部分萎缩性胃窦胃炎由慢性浅表性胃炎迁延发展而来，可伴有浅表性胃炎（B对）。幽门螺杆菌感染只是萎缩性胃窦胃炎的主要病因，其他次要病因有十二指肠-胃反流、年龄因素和胃黏膜营养因子缺乏等，可与幽门螺杆菌无关（C对）。幽门括约肌功能不全时，含胆汁和胰液的十二指肠液反流入胃，长期的反流，可导致胃黏膜慢性炎症，为萎缩性胃窦胃炎的次要病因（D对）。","","N"],["1992-N137",19,"第二节 扩张型心肌病","扩张型心肌病临床表现",1992,137,"X","","扩张型心肌病的临床表现可有",[["A","心电图病理Q波"],["B","猝死"],["C","栓塞"],["D","肺毛细血管楔压上升"]],"ABCD","扩张型心肌病（DCM）是一种原因未明的原发性心肌疾病。本病的特征为左或右心室或双侧心室扩大，并伴有心室收缩功能减退，心肌广泛纤维化，伴或不伴充血性心力衰竭。在左心室严重纤维化的患者可出现病理性Q波（A对），需除外心肌梗死。疾病晚期，左心室泵血功能极度减退，收缩末期残留于左心室内的血液增多，舒张期心房及肺静脉血液回流受限，可引起肺毛细血管楔压上升（D对）。心肌收缩能力减弱，心腔内血流速度减慢，容易引起附壁血栓的形成，若血栓脱落，可引起远端栓塞（C对）。合并心律失常时，可出现心悸、头晕、黑蒙甚至猝死（B对）。","","N"],["1992-N138",13,"第三节 慢性呼吸衰竭","氧疗",1992,138,"X","","吸氧浓度至40%，可纠正以下哪种情况引起的低氧血症",[["A","房间隔缺损引起的肺动脉高压"],["B","严重的肺气肿"],["C","慢性肺心病急性加重期"],["D","ARDS"]],"BC","严重肺气肿（B对）、慢性肺心病急性加重期（C对）都存在肺通气下降的情况，肺通气下降导致动脉血氧分压下降，提高氧浓度可使患者低氧血症有所纠正或好转。房间隔缺损（十版内科学P288）（A错）后，由于左房压力高于右房，血液由左向右分流，肺血流量增加，持续肺血流量增加引起肺淤血，导致肺动脉高压，右心系统的压力随之持续增高甚至超过左心系统，此时逆转为右向左的分流，分流的静脉血不经过肺循环直接进入体循环而引起低氧血症，故吸氧浓度至40%不能纠正低氧血症。ARDS（十版内科学P143）（D错）可因休克、创伤等诱因使肺毛细血管内皮、肺泡细胞损伤，致使肺微血管血栓形成，肺泡表面活性物质减少，肺泡不张，致使通气与血流比例失调，肺内分流增加，导致严重的低氧血症，而提高吸氧浓度并不能改善通气与血流比例和肺内分流，故吸氧浓度至40%不能纠正低氧血症。","","N"],["1992-N139",40,"第三节 急进性肾小球肾炎","急进性肾小球肾炎临床表现",1992,139,"X","","急进性肾小球肾炎患者，主要的临床表现为",[["A","蛋白尿，血尿"],["B","少尿，无尿"],["C","尿急，尿频，尿痛"],["D","肾功能急骤减退"]],"ABD","急进性肾小球肾炎是一组表现为血尿、蛋白尿（A对）及进行性肾功能减退（D对）的临床综合征，是肾小球肾炎中最严重的类型，可见于任何年龄，但以青年和中、老年为多，该病可呈急性起病，多数病人在发热或上呼吸道感染后出现急性肾炎综合征，病情发展很快，起病数天内即出现少尿（B对）及进行性肾功能减退。尿频、尿急、尿痛（尿路刺激征）（C错）为泌尿系感染的常见症状。","","N"],["1992-N140",37,"第一节 急性胰腺炎","急性胰腺炎诊断",1992,140,"X","","诊断急性胰腺炎时，常依靠下列哪几项检查",[["A","发病3～4小时血清淀粉酶高于128温氏单位（或300索氏单位）"],["B","腹腔穿刺液中淀粉酶升高，外观是血性混浊"],["C","B超检查发现胰腺增大，网膜囊及腹腔有积液"],["D","既往有胆道疾患"]],"ABCD","血、尿淀粉酶测定是诊断急性胰腺炎的主要手段之一，其升高超过正常值的三倍以上时（即＞500U）才有诊断价值，且血清淀粉酶在发病数小时后开始升高，24小时达高峰，尿淀粉酶在12小时才开始升高，因此，12小时内采用血清淀粉酶检查比较准确，选项A中所给的数据是老版数据，现已弃用。腹腔穿刺液对于诊断急性胰腺炎也有帮助，通常在急性胰腺炎时，腹穿液的淀粉酶明显升高，且腹穿液呈血性浑浊（B对）。B超是急性胰腺炎的首选检查，常可显示胰腺弥漫肿大，同时可观察到网膜囊及腹腔有积液存在（C对）。如发现胆道结石、胆管扩张，则胆源性胰腺炎可能性较大。国内急性胰腺炎致病危险因素多以胆道疾病为主，当胆结石、胆道水肿等存在致胆汁引流不畅时，胆汁可经“共同通道”返流入胰管，致急性胰腺炎。故既往胆道疾患病史（D对）是诊断急性胰腺炎的一项重要因素。","","N"],["1993-N41",59,"第一节 甲状腺功能亢进症","剂量与疗程",1993,41,"A","","30岁女性Graves病患者，应用他巴唑治疗，一个月后症状缓解，但甲状腺肿及突眼加重，此时最适当的治疗措施是",[["A","加大他巴唑用量"],["B","改用丙硫氧嘧啶"],["C","应用¹³¹I治疗"],["D","改用心得安"],["E","加小剂量甲状腺激素"]],"E","患者使用他巴唑（抗甲状腺药物）后出现甲状腺腺体增大，是因为他巴唑使血清甲状腺素水平下降，反馈性增加促甲状腺激素分泌，引起腺体代偿性增生、肥大、充血等。此时应加用小剂量甲状腺激素（甲状腺片），负反馈抑制促甲状腺素的释放（E对）。若患者此时加大他巴唑剂量，甲状腺肿及突眼会更加严重（A错）。丙硫氧嘧啶与他巴唑同属抗甲状腺药物，也会出现此副作用（B错）。患者应用ATD治疗，效果较好且无明显不良反应，无需改用¹³¹I治疗（C错）。患者目前病情稳定，无心率加快、心收缩力增强等交感神经激活症状，故无需加用心得安（D错）。","","N"],["1993-N42",61,"第一节 糖尿病","T1DM的临床特点",1993,42,"A","","非胰岛素依赖型糖尿病与胰岛素依赖型糖尿病的最主要区别是",[["A","发病年龄不同"],["B","对胰岛素的敏感性不同"],["C","胰岛素基础值及释放曲线不同"],["D","发生酮中毒的倾向不同"],["E","血糖稳定性不同"]],"C","胰岛素依赖型糖尿病（1型糖尿病）（十版内科学P724）的胰岛β细胞破坏，常导致胰岛素绝对缺乏，葡萄糖负荷后血浆胰岛素浓度无明显升高，呈低平曲线；非胰岛素依赖型糖尿病（2型糖尿病）是胰岛素抵抗或胰岛素分泌不足所致，因此体内胰岛素水平正常甚至升高，空腹血浆胰岛素基础值正常、较低或偏高，葡萄糖负荷后血浆胰岛素分泌高峰延迟。可见非胰岛素依赖型糖尿病与胰岛素依赖型糖尿病的最主要区别是胰岛素基础值及释放曲线（C对）。多数1型糖尿病为青少年患者，起病初期需要胰岛素治疗，有自发酮症酸中毒倾向；2型糖尿病可见于任何年龄，多见于成年人，初期不需要胰岛素治疗，随着胰岛β细胞衰竭，需胰岛素治疗，在一定诱因下也可发生酮症酸中毒。可见发病年龄（A错）、对胰岛素的敏感性（B错）、发生酮中毒的倾向（D错）均可为两者的区别，但都不是最主要的区别。糖尿病患者糖耐量减低，都需要综合治疗来控制血糖使其稳定，因此血糖稳定性（E错）也不是其主要区别。","","N"],["1993-N43",35,"第一节 肝硬化","门静脉血栓或海绵样变",1993,43,"A","","肝硬化患者在很短时间里出现腹痛和大量血性腹水，不伴有发热，应首先考虑可能并发",[["A","原发性腹膜炎"],["B","继发性肝癌"],["C","结核性腹膜炎"],["D","肝肾综合征"],["E","门静脉血栓形成"]],"E","本例患者患有肝硬化且短时间突发腹痛和大量血性腹水，不伴有发热，应首先考虑可能并发急性或亚急性门脉血栓形成（E对）。原发性腹膜炎（A错）和结核性腹膜炎（十版内科学P385）（C错）常伴发热，血性腹水较少见。继发性肝癌（B错）的发生与肝硬化无关，且不会在很短时间里出现腹痛和大量血性腹水。肝肾综合征（D错）是由于严重门脉高压，内脏高动力循环使循环血流量减少导致的肾血流灌注不足而出现的肾功能衰竭，一般不会出现血性腹水。","","N"],["1993-N44",18,"第一节 原发性高血压","高血压急症和亚急症临床表现",1993,44,"A","","急进型高血压病病人，下列哪种器官的功能损害最为严重",[["A","肾脏"],["B","脑"],["C","心脏"],["D","眼底病变"],["E","肺"]],"A","急进型高血压亦称恶性高血压，是指少数高血压患者病情急骤发展，舒张压持续≥130mmHg，并有头痛、视力模糊、眼底出血、渗出和视盘水肿，肾脏损害突出，持续蛋白尿、血尿与管型尿，早期就可出现肾衰竭。由此定义可知急进型高血压病病人，功能损害最为严重的器官为肾脏（A对）。急进型高血压患者也可有脑（B错）、心脏（C错）和眼底病变（D错），但一般严重程度不及肾脏，而急进型高血压引起肺（E错）部病变较少见。","","N"],["1993-N45",17,"第四节 急性冠状综合征","硝酸酯类药物",1993,45,"A","","急性广泛前壁心肌梗塞患者，胸闷憋气明显，心率140次/分，双肺可闻弥漫性小水泡音，首选最佳处理应为",[["A","给予洋地黄制剂，以增加心肌收缩力"],["B","给予β受体阻滞剂，以降低心室率"],["C","给予血管扩张剂，以降低心脏前后负荷"],["D","给予钙拮抗剂，以缓解冠状动脉痉挛"],["E","给予补液，以补充循环血容量"]],"C","该患者双肺可闻弥漫性小水泡音且心率增快，初诊为急性心肌梗死伴左心功能不全，应给予血管扩张剂，减少心脏前后负荷（C对），以减少心肌耗氧量，防止梗死面积进一步扩大。AMI患者应用洋地黄可能引起室性心律失常，且AMI早期出现的心力衰竭主要是坏死心肌间质充血、水肿引起顺应性下降所致，而左心室舒张末期容量尚不增大（十版内科学P257），因此在心梗后24小时内尽量避免使用洋地黄制剂（A错）。患者此时左心衰症状明显，不宜应用β受体阻滞剂（B错）。AMI患者不推荐常规使用钙通道阻滞剂（D错）。给予钙拮抗剂，以缓解冠状动脉痉挛为变异型心绞痛的首选治疗方法。单纯补液增加心脏前负荷，心肌耗氧量增加，可导致梗死面积扩大（E错）。","","N"],["1993-N46",28,"第一节 消化性溃疡","抑制胃酸分泌",1993,46,"A","","治疗消化性溃疡时应用下列何种药物抑制胃酸和胃蛋白酶分泌最有效",[["A","酸泵抑制剂"],["B","H₂受体拮抗剂"],["C","M胆碱受体阻滞剂"],["D","胃泌素受体拮抗剂"],["E","胃酸中和剂"]],"A","酸泵抑制剂（质子泵抑制剂）直接作用于壁细胞膜上H⁺-K⁺-ATP酶，使其失去活性，泌酸活动消失，由于胃酸大幅度减少，胃液内pH上升，胃蛋白酶失活不能发挥作用（A对）；H₂受体拮抗剂（B错）（拮抗壁细胞上的2型组胺受体，阻断ECL细胞分泌的组胺对于胃酸分泌的刺激作用）、M胆碱能受体阻滞剂（C错）（拮抗壁细胞上的M胆碱能受体，阻断迷走神经末梢分泌的乙酰胆碱对于胃酸分泌的刺激作用）、胃泌素受体拮抗剂（D错）（拮抗壁细胞上的胃泌素受体，阻断G细胞分泌的胃泌素对于胃酸分泌的刺激作用）三者均未直接作用于壁细胞分泌胃酸的过程，因此作用效果不如质子泵抑制剂显著。胃酸中和剂（E错）可以中和胃酸，升高胃液pH，但并未抑制胃酸分泌。因此，抑制胃酸和胃蛋白酶分泌效果最强的为质子泵抑制剂。","","N"],["1993-N48",75,"第一节 中毒概述","洗胃",1993,48,"A","","误服下列哪种药物中毒应该洗胃",[["A","苯酚"],["B","醋酸"],["C","水杨酸类"],["D","硝酸"],["E","氧化汞"]],"C","洗胃适用于口服毒物1小时以内者，对于吸收缓慢的毒物、胃蠕动功能减退者，服毒4～6小时后仍应洗胃。而吞服强腐蚀性毒物、食管静脉曲张、惊厥或昏迷者，不宜进行洗胃。水杨酸类中毒会经胃大量吸收而加重毒性，应该用活性炭吸附剂洗胃（C对）。苯酚（即石炭酸）（A错）属于弱酸，具有强腐蚀性，硝酸（D错）属于强酸，禁忌洗胃。醋酸（B错）、和氧化汞（E错）对胃黏膜都有强腐蚀作用，插胃管洗胃有引起胃穿孔的危险，所以不宜洗胃。","","N"],["1993-N49",16,"第三节 房性心律失常","心房颤动诊断",1993,49,"A","","下列哪项表现临床听诊可有心律不整",[["A","一度房室传导阻滞"],["B","阵发性室上性心动过速"],["C","2：1心房扑动"],["D","心室率慢的心房纤颤"],["E","完全性右束支传导阻滞"]],"D","心室率慢的心房纤颤（D对）是由心房颤动速率过快引起许多小折返环而导致的房律紊乱以及下传心室的激动变少，主要特点有心音绝对不齐、心律不整和脉搏短绌。一度房室传导阻滞（A错）是指房室传导时间延长，超过正常范围，但每个心房激动仍能传入心室，心电图上每个P波后均有QRS波，因此患者心律规则。阵发性室上性心动过速（B错）是指起源于心房或房室交界区的心动过速，大多数是由于折返激动所致，少数由自律性增加和触发活动引起，患者心律绝对规则。心房扑动可以认为是在房性心动过速与心房颤动之间的中间型，典型房扑的频率常为250～350次/分，房室传导呈比例（如2：1）时，心室率规则（C错）；当房室传导不呈比例时，心室率不规则。完全性右束支传导阻滞（E错）一般心律整齐。","","N"],["1993-N50",17,"第三节 慢性冠状动脉综合症","稳定型心绞痛临床表现",1993,50,"A","","心绞痛发作时可出现",[["A","体温升高"],["B","血沉增快"],["C","血清心肌酶谱增高"],["D","动脉血压增高"],["E","以上都不正确"]],"D","心绞痛发作时由于疼痛刺激，交感神经兴奋，可见患者心率增快、血压升高（D对）、表情焦虑、皮肤冷或出汗，有时出现第四或第三心音奔马律。体温升高（A错），血沉增快（B错），血清心肌酶谱增高（C错）是急性心肌梗死的表现，而单纯的心绞痛不会出现上述表现。","","N"],["1993-N51",47,"第一节 缺铁性贫血","病因治疗",1993,51,"A","","含铁量最少的食物是",[["A","蛋黄"],["B","猪肝"],["C","牛乳"],["D","猪肉"],["E","牛肉"]],"C","肉类（DE错）、蛋类（A错）、动物内脏（B错）中均含有较多铁，而乳制品（C对）含铁量少，而且进食乳制品还会抑制铁的吸收。","","N"],["1993-N52",56,"第二节 原发免疫性血小板减少症","糖皮质激素",1993,52,"A","","用糖皮质激素治疗原发性血小板减少性紫癜，下列哪一项是正确的",[["A","血小板上升前出血症状即可改善"],["B","停药后不易复发"],["C","复发时再用无效"],["D","主要作用是抑制抗体生成"],["E","妊娠初期病人可以应用"]],"A","糖皮质激素可改善毛细血管通透性，所以血小板上升前出血症状就可通过毛细血管通透性降低而得到改善（A对）。糖皮质激素只能控制症状，而不能纠正病因，故停药后易复发（B错），复发时再用仍有效（C错）。糖皮质激素的主要作用是抑制单核-巨噬细胞系统对血小板的破坏（D错）。糖皮质激素影响胎儿生长发育，故妊娠期不宜应用（E错）。","","N"],["1993-N53",52,"第三节 慢性髓系白血病","临床表现",1993,53,"A","","慢性粒细胞性白血病确诊时最少见的体征是",[["A","脾脏肿大"],["B","胸骨压痛"],["C","苍白"],["D","肝脏肿大"],["E","淋巴结肿大"]],"E","慢性粒细胞性白血病（CML）患者多见脾脏肿大（A错），部分患者有胸骨压痛（B错），是白血病细胞侵犯胸骨的表现。CML患者通常有正细胞正色素性贫血，可见皮肤苍白（C错）。CML患者也会有肝脏肿大（D错），但是明显肿大者少见。淋巴结肿大常见于淋巴细胞性白血病，慢性粒细胞性白血病很少有淋巴结肿大（E对）。","","N"],["1993-N54",40,"第二节 急性肾小球肾炎","急性肾小球肾炎诊断",1993,54,"A","","女性16 岁，一周来尿少色红，眼睑下肢浮肿，血压20/14KPa，尿蛋白++，尿沉渣红细胞10~15/ 高倍视野，白细胞5~10/ 高倍视野，可见红细胞及颗粒管型，血红蛋白12g/dl，A/G40/22g/L，胆固醇5mmol/L，BUN6mmol/L，最可能的诊断是",[["A","急性肾小球肾炎"],["B","慢性肾炎急性发作"],["C","急性肾盂肾炎"],["D","急进性肾炎"],["E","肾病综合征Ⅱ型"]],"A","青年女性患者，尿少色红一周，眼睑下肢浮肿，血压20/14Kpa（154/107.8mmHg），尿蛋白++，尿沉渣提示有血尿（典型的肾炎综合征：血尿、蛋白尿、水肿、高血压），诊断考虑急性肾小球肾炎（A对）。慢性肾炎急性发作（B错）多存在贫血且病史较长，该患者无贫血且病程仅1周。急性肾盂肾炎（C错）多存在发热、恶心呕吐等感染中毒症状，出现腰部疼痛及叩击痛，部分患者可出现尿路刺激征，该患者仅存在尿白细胞稍高。急进性肾炎（D错）主要表现为急进性肾炎综合征，早期即可出现少尿及肾功能减退，该患者并无肾功能减退。肾病综合征Ⅱ型（E错）表现为大量蛋白尿（尿蛋白大于3.5g/L，定性试验应+++以上）、低蛋白血症、水肿及高脂血症，该患者血浆白蛋白40g/L、球蛋白22g/L、血浆A/G＞1.5（正常人血浆白蛋白40～55g/L，球蛋白20～30g/L，A/G1.5～2.5）处于正常范围，尿蛋白仅（++）未达到肾病综合征诊断标准。","","N"],["1993-N55",40,"第一节 肾小球疾病概述","细胞免疫",1993,55,"A","","目前认为微小病变性肾病最可能的发病机理是",[["A","感染引起"],["B","体液免疫功能失调为主"],["C","细胞免疫功能失调为主"],["D","与免疫功能无关"],["E","以上都不是"]],"C","本题考查微小病变型肾病发病机制。微小病变型肾病（十版内科学P481）既往称为类脂性肾病，是儿童最常见的一种肾小球疾病。病理特点有：光镜下肾小球基本正常，近曲小管上皮细胞可见脂肪变性；免疫病理检查阴性；电镜下有广泛的肾小球脏层上皮细胞足突消失，肾小球内无电子致密物沉积。T淋巴细胞功能紊乱（细胞免疫功能失调）（C对D错），循环中的淋巴因子破环肾小球电荷屏障。多数肾小球疾病为免疫介导的炎症疾病，并非感染性疾病（A错）。体液免疫功能失调（B错）主要指外来或自身抗原在肾内与相应抗体组成的免疫复合物异常沉积的机制，包括循环免疫复合物沉积、原位免疫复合物沉积、自身抗体等，微小病变型肾病并未检测到有异常免疫复合物的沉积。","","N"],["1993-N57",13,"第三节 慢性呼吸衰竭","纠正酸碱平衡失调",1993,57,"A","","患者血气分析结果为：pH7.16，PaO₂7.5KPa（56mmHg），PaCO₂12KPa（90mmHg），BE-18mmol/L（-18mEq/L），应采用哪种药物",[["A","3.64%THAM"],["B","5%NaHCO₃"],["C","11.2%乳酸钠"],["D","醋唑酰胺"],["E","2.5%NaHCO₃"]],"A","该患者血气分析PaO₂56mmHg＜60mmHg，PaCO₂90mmHg＞50mmHg，提示Ⅱ型呼吸衰竭。pH7.16＜7.35（正常值7.35～7.45），BE-18mmol/L＜-3mmol/L，提示是失代偿性呼吸性酸中毒合并代谢性酸中毒。5%NaHCO₃（B错）、2.5%NaHCO₃（E错）、11.2%乳酸钠（C错）及醋唑酰胺（D错）都会分解产生CO₂，加重CO₂潴留。3.64%THAM（三羟甲基氨基甲烷）（A对）为氨基缓冲剂，能摄取氢离子而纠正代谢性酸中毒，缓冲作用强，且能透过细胞膜，不会引起体内CO₂潴留，常用于治疗急性代谢性及呼吸性酸中毒。根据十版内科学（P125），该患者PH＜7.20，可以用5%NaHCO₃纠酸治疗，选择B选项更为合适，但原答案为A。","","N"],["1993-N58",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病病理生理",1993,58,"A","","慢性支气管炎并发阻塞性肺气肿时，下列哪种病理生理变化是正确的",[["A","只有当细支气管完全阻塞时，才会出现气道阻力增加，形成阻塞性通气功能障碍"],["B","残气量占肺总量百分比增加，但残气量绝对值不增加"],["C","无肺泡壁血流灌注异常，所以无生理无效腔增大"],["D","伴有换气障碍"],["E","可引起二氧化碳潴留，不引起低氧血症"]],"D","慢性支气管炎并发肺气肿时，炎症由支气管壁向周围组织扩散，黏膜下层平滑肌束可断裂萎缩，黏膜下和支气管壁周围纤维组织增生，支气管壁损伤修复过程反复发生，进而引起支气管结构重塑，瘢痕形成，气道狭窄，引起通气功能障碍。气道不完全阻塞时气道阻力也会升高，形成阻塞性通气障碍（A错）。慢阻肺加重导致肺组织弹性日益减退，肺泡持续扩大，回缩障碍，残气量及残气量占肺总量的百分比均增加（B错）。肺气肿加重导致肺泡周围肺毛细血管受挤压大量减少，肺泡间血流减少，此时肺泡虽有通气，但肺泡壁无血流灌流，导致无效腔样气量增大（C错）。同时，肺泡及毛细血管大量丧失，弥散面积减少，通气与血流比例失调与弥散障碍共同作用，导致换气功能发生障碍（D对），发展到最后会引起不同程度的低氧血症和高碳酸血症（E错）。","","N"],["1993-N59",10,"第三节 慢性肺源性心脏病","慢性肺源性心脏病诊断",1993,59,"A","","男性45岁，慢支15年，呼吸困难突然加重一天，伴右侧胸痛。查体：发绀，桶状胸，右肺呼吸音减低，左肺散在干啰音，心浊音界缩小，剑突下可触及收缩期搏动，考虑诊断为",[["A","慢支、肺气肿、肺部感染"],["B","慢支、肺气肿、早期肺心病、右侧气胸"],["C","慢支、肺气肿、右侧气胸"],["D","慢支、肺气肿、早期肺心病、右侧胸腔积液"],["E","慢支、肺气肿、右侧胸腔积液"]],"B","患者中年男性，慢支病史，查体桶状胸，心浊音界缩小，考虑慢支已发展至肺气肿。患者呼吸困难突然加重，伴右侧胸痛、右肺呼吸音减低考虑慢阻肺并发右侧自发性气胸。剑突下可触及收缩期搏动，提示右心室肥厚，已并发早期肺心病，故诊断为慢支、肺气肿、早期肺心病、右侧气胸（B对）。肺部感染（A错）患者多有发热等全身表现；右侧胸腔积液（DE错）时，不会出现心浊音界缩小。","","N"],["1993-N60",5,"第一节 肺脓肿","肺脓肿临床表现",1993,60,"A","","关于肺脓肿的特点，哪项是正确的",[["A","如无脓痰，可排除厌氧菌感染"],["B","感染菌，除厌氧菌外，都对青霉素敏感"],["C","食道贲门失弛缓不是急性肺脓肿的诱发因素"],["D","动脉血管瘤是慢性肺脓肿反复中、大量咯血的病理基础"],["E","早期呈现严重呼吸困难，咯大量臭脓痰"]],"D","肺脓肿发生后，脓肿周围炎症可刺激支气管血管，损伤血管内膜，形成动脉血管瘤。当动脉瘤破裂后，可出现反复中、大量咯血的表现，因此动脉血管瘤是慢性肺脓肿反复中、大量咯血的病理基础（D对）。链球菌等厌氧菌感染时，患者病变程度较轻，咳黏液痰，而不咳脓痰，所以当患者无脓痰时，不可排除厌氧菌感染（A错）。肺脓肿80%是由厌氧菌引起的，因厌氧菌对青霉素较敏感（B错），所以临床上将青霉素作为治疗肺脓肿的首选抗生素。食道贲门失弛缓时，可因胃内容物反流或呕吐而发生误吸，进而可致吸入性肺脓肿，因此食道贲门失弛缓也是急性肺脓肿的诱发因素（C错）。肺脓肿早期病变时，由于病变肺组织范围较小，病变对患者的呼吸功能影响较小，呼吸困难程度较轻，坏死较轻，无过多坏死组织排出，多无大量臭脓痰（E错）。","","N"],["1993-N61",6,"第一节 肺结核","结核病免疫和迟发性变态反应",1993,61,"A","","结核性胸膜炎和浸润性肺结核均为",[["A","速发型变态反应"],["B","细胞毒型变态反应和依赖抗体细胞毒型变态反应"],["C","免疫复合物型变态反应和细胞刺激型变态反应"],["D","迟发型变态反应"],["E","以上都不对"]],"D","结核性胸膜炎和浸润性肺结核均为结核病，其发病机制为机体初次接触抗原后，T细胞转化为致敏淋巴细胞，使机体处于过敏状态，出现分化、增殖，并释放许多淋巴因子，吸引、聚集并形成以单核细胞浸润为主的炎症反应，甚至引起组织坏死。此型反应局部炎症变化出现缓慢，接触抗原24～48小时后才出现高峰反应，故称迟发型变态反应（Ⅳ型变态反应）（D对）。速发型变态反应（A错）主要为呼吸道过敏反应、消化道过敏反应、皮肤过敏反应以及过敏性休克，由IgE介导，肥大细胞和嗜碱粒细胞等效应细胞以释放生物活性介质的方式参与反应，发生快，消退亦快，常表现为生理功能紊乱，无严重的组织损伤，不会引起继发型肺结核。细胞毒型变态反应和依赖抗体细胞毒型变态反应（B错）为Ⅱ型变态反应，是由抗体与靶细胞表面的抗原相结合而介导，细胞刺激型变态反应与细胞毒型变态反应相似，免疫复合物型变态反应（C错）由抗原抗体复合物引起的Ⅲ型变态反应，循环中的免疫复合物沉积于血管壁、肾小球基底膜或组织间隙，并进一步激活补体，引起炎性反应、组织损伤、激活凝血途径，常见于肾小球肾炎、系统性红斑狼疮等多种免疫复合物病，由于结核病主要的免疫保护机制是细胞免疫，体液免疫对控制结核分枝杆菌的作用不大，因此ABC可排除。","","N"],["1993-N62",10,"第三节 慢性肺源性心脏病","正性肌力药",1993,62,"A","","肺心病患者高度水肿PaCO₂7.98KPa（60mmHg），心率114次/分，下列哪种治疗较为合理",[["A","洋地黄化，并用少量镇静剂"],["B","毒毛花苷K静注，并用醋唑酰胺"],["C","西地兰静注，并用心得安"],["D","洋地黄化，并用氟美松"],["E","毒毛旋花子苷K静注，临时使用少量利尿剂"]],"E","肺心病患者高度水肿PCO₂=7.89KPa（60mmHg），心率114＞100次/分，可以使用正性肌力药，原则上选用作用快、排泄快的洋地黄药物，小剂量静脉给药。临床常用毒毛花苷K注射液或毛花苷丙；利尿剂应选择作用温和的，小剂量、短疗程的药物；镇静剂、醋唑酰胺有抑制呼吸作用（AB错）；氟美松为强效糖皮质激素（D错）；心得安会抑制β受体致气道收缩（C错），均不宜使用。故应选用毒毛旋花子苷K静注，临时使用少量利尿剂（E对）。","","N"],["1993-N63",26,"第一节 胃食管反流病","胃食管反流病发病机制",1993,63,"A","","以下哪种物质可使食管下括约肌张力增高",[["A","盐酸"],["B","内因子"],["C","胃蛋白酶"],["D","胃泌素"],["E","钙通道拮抗剂"]],"D","胃泌素（D对）对食管黏膜下括约肌内的套索纤维和钩状纤维均有收缩作用，使括约肌张力升高；钙通道阻滞剂（E错）通过阻断食管平滑肌细胞膜上的钙离子通道，阻止钙离子进入胞内，从而抑制了收缩，使食管下括约肌张力降低；而胃蛋白酶（C错）和盐酸（A错）是反流物中损害食管黏膜的主要成分，对食管下括约肌张力的影响不大。内因子（B错）是由胃体壁细胞分泌的一种黏蛋白，能与食物中的维生素B₁₂结合形成复合物，使之不被酶消化，到达回肠后，维生素B₁₂得以吸收，对食管下括约肌张力影响不大。","","N"],["1993-N64",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞病因",1993,64,"A","","下列哪项病因所致的心包炎一般不出现心包填塞征",[["A","结核性"],["B","病毒性"],["C","肿瘤性"],["D","风湿性"],["E","尿毒症性"]],"D","风湿性心包炎是一种纤维素性或浆液纤维素性炎症，积液量一般不多，不会引起心包填塞（D对）。结核性（A错）心包炎产生大量的纤维蛋白性或血性渗出，可发生心包填塞。病毒性（B错）心包炎可产生大量积液，发生心包填塞。肿瘤性（C错）心包积液多为血性，量较大，易导致心包压塞。肾功能不全晚期，尿毒症性（E错）心包炎，多为纤维素性心包炎，多数伴有血性心包积液，可导致心包压塞。","","N"],["1993-N93",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄诊断",1993,93,"B","","左心室后负荷增加",[["A","二尖瓣狭窄伴肺动脉高压"],["B","二尖瓣关闭不全"],["C","主动脉瓣狭窄"],["D","主动脉瓣关闭不全"],["E","三尖瓣关闭不全"]],"C","后负荷是指心肌收缩之后所遇到的阻力或负荷，又称压力负荷。前负荷是指在舒张末期，心室所承受的容量负荷或压力。左心室的后负荷指左心室排血阻力，主动脉瓣狭窄（C对）、高血压均增加左心室后负荷。前负荷是指在舒张末期，心室所承受的容量负荷或压力负荷，与静脉回心血量有关。二尖瓣狭窄伴肺动脉高压（A错）增加右心室后负荷，引起右心室肥厚扩张，终致右心室衰竭。二尖瓣关闭不全（B错），在心脏收缩时，一部分血液由左心室反流入左心房，使左心房的容量负荷增加，进而使左心室的容量负荷（前负荷）增加。主动脉瓣关闭不全（D错）时，心脏舒张时，一部分血液反流入左心室导致左心室的前负荷增加。三尖瓣关闭不全（E错）时，收缩期一部分血液由右心室反流入右心房，使右心房的容量负荷增加，进而使右心室的容量负荷（前负荷）增加。","","N"],["1993-N94",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄鉴别诊断",1993,94,"B","","右心室前负荷增加",[["A","二尖瓣狭窄伴肺动脉高压"],["B","二尖瓣关闭不全"],["C","主动脉瓣狭窄"],["D","主动脉瓣关闭不全"],["E","三尖瓣关闭不全"]],"E","后负荷是指心肌收缩之后所遇到的阻力或负荷，又称压力负荷。前负荷是指在舒张末期，心室所承受的容量负荷或压力。三尖瓣关闭不全（E对）时，收缩期一部分血液由右心室反流入右心房，使右心房的容量负荷增加，进而使右心室的容量负荷（前负荷）增加。左心室后负荷是指心肌收缩之后所遇到的阻力或负荷，又称压力负荷，二尖瓣狭窄伴肺动脉高压（A错）使右心室射血的阻力增加，右心室后负荷增加，引起右心室肥厚扩张，终致右心室衰竭。二尖瓣关闭不全（B错），在心脏收缩时，一部分血液由左心室反流入左心房，使左心房的容量负荷增加，导致使左心室的容量负荷（前负荷）增加。左心室的后负荷指左心室排血阻力，主动脉瓣狭窄（C错）、高血压均增加左心室后负荷。主动脉瓣关闭不全（D错）时，心脏舒张时，一部分血液反流入左心室导致左心室的前负荷增加。","","N"],["1993-N97",52,"第二节 急性白血病","ALL诱导缓解治疗",1993,97,"B","","只用于治疗急性淋巴细胞性白血病",[["A","6-巯基嘌呤（6-MP）"],["B","阿糖胞苷"],["C","左旋门冬酰胺酶"],["D","高三尖杉酯碱"],["E","柔红霉素"]],"C","急性淋巴细胞性白血病（ALL）常见的诱导方案（十版内科学P583）：DVLP方案（D柔红霉素、V长春新碱、L左旋门冬酰胺酶、P泼尼松）。在此基础上可加上环磷酰胺（CTX）或阿糖胞苷（Ara-C）等。左旋门冬酰胺酶一般只对ALL有效，而对急性髓系白血病（AML）无效（C对）。高三尖杉酯碱（十版内科学P584）（D错）一般只对AML有效，而对ALL无效。阿糖胞苷（B错）、柔红霉素（E错）、6-巯基嘌呤（6-MP）（A错）不仅对ALL有效，还可用于其他类型白血病治疗。","","N"],["1993-N98",52,"第二节 急性白血病","AML诱导缓解治疗",1993,98,"B","","只用于治疗急性非淋巴细胞性白血病",[["A","6-巯基嘌呤（6-MP）"],["B","阿糖胞苷"],["C","左旋门冬酰胺酶"],["D","高三尖杉酯碱"],["E","柔红霉素"]],"D","急性非淋巴细胞性白血病（ANLL）即急性髓系白血病（AML），AML（非APL）常见诱导方案（十版内科学P584）：IDA或HA（I去甲氧柔红霉素、D柔红霉素、A阿糖胞苷、H高三尖杉酯碱）。其中，高三尖杉酯碱一般只对AML有效（D对）。九版内科学认为，高三尖杉酯碱可用于CML治疗。左旋门冬酰胺酶（C错）一般只对ALL有效。阿糖胞苷（B错）、柔红霉素（E错）、6-巯嘌呤（6-MP）（A错）对AML有效，但对其他类型白血病也有效。","","N"],["1993-N109",60,"第一节 库欣综合征","库欣综合征病因诊断",1993,109,"C","","ACTH兴奋试验皮质醇分泌增加2～3倍",[["A","双侧肾上腺皮质增生"],["B","肾上腺皮质癌"],["C","两者均可"],["D","两者均不可"]],"A","双侧肾上腺皮质增生多由垂体肿瘤引起，为ACTH依赖型，受下丘脑-垂体-肾上腺皮质轴的调节，当体内ACTH增多时，皮质醇分泌增多，即ACTH兴奋试验阳性（A对）。而肾上腺皮质癌肿（B错）自主分泌皮质醇，是ACTH非依赖型，不受下丘脑-垂体-肾上腺皮质轴的调节，ACTH兴奋试验多无反应。","","N"],["1993-N110",60,"第一节 库欣综合征","库欣综合征病因诊断",1993,110,"C","","大剂量地塞米松不抑制",[["A","双侧肾上腺皮质增生"],["B","肾上腺皮质癌"],["C","两者均可"],["D","两者均不可"]],"B","大剂量地塞米松抑制试验方法：口服地塞米松2mg，1次/6小时，共2天。结果分析：服药后，血、尿皮质醇值降至对照值的50%以下为抑制试验阳性。临床意义：用于鉴别皮质醇增多症的病因。双侧肾上腺皮质增生多由垂体肿瘤引起，为ACTH依赖型，受下丘脑-垂体-肾上腺皮质轴的调节。当给予大剂量地塞米松时，通过负反馈调节，使ACTH分泌减少，从而使皮质醇分泌减少，故大剂量地塞米松抑制试验为阳性（A错）。但由于库欣病血皮质醇较高，给予小剂量地塞米松，对血皮质醇影响不大，故不能被小剂量地塞米松抑制试验抑制。肾上腺皮质腺瘤和肾上腺皮质癌能自主分泌皮质醇，不受ACTH的调节，故大剂量地塞米松抑制试验为阴性（B对）。","","N"],["1993-N119",17,"第四节 急性冠状综合征","不稳定型心绞痛和非ST段抬高型心肌梗死临床表现",1993,119,"C","","冠心病，急性肺水肿",[["A","高碳酸血症"],["B","低氧血症"],["C","两者均有"],["D","两者均无"]],"B","冠心病会导致心功能下降，肺淤血，呼吸膜变厚；急性肺水肿时也会导致呼吸膜变厚，呼吸膜变厚可以使肺的弥散功能降低，影响肺的换气功能。肺换气主要是氧气和二氧化碳的交换，因二氧化碳的弥散能力为氧的20倍，所以不会出现高碳酸血症（A错），可出现严重的低氧血症（B对）。","","N"],["1993-N120",2,"第一节 支气管哮喘","动脉血气分析",1993,120,"C","","支气管哮喘",[["A","高碳酸血症"],["B","低氧血症"],["C","两者均有"],["D","两者均无"]],"C","哮喘发作时表现为呼气性呼吸困难，引起缺氧（B对），低氧刺激外周化学感受器，引起呼吸加深加快，致过度通气可使PaCO₂下降，随病情发展，通气功能严重障碍时，也会导致二氧化碳潴留，引起高碳酸血症（A对），故两者均可出现。本题AB均对，正确答案为C。","","N"],["1993-N121",65,"","",1993,121,"C","","原发性高尿酸血症致痛风慢性肾功能不全期",[["A","血尿酸高于正常"],["B","尿尿酸240mg/24小时"],["C","二者均有"],["D","二者均无"]],"C","原发性高尿酸血症是嘌呤代谢障碍引起的代谢性疾病，表现为血尿酸增高（A对）。80%～90%的高尿酸血症具有尿酸排泄障碍，即尿尿酸低于正常（正常值为403.36～907.56mg/24小时）（B对）。本题AB均对，正确答案为C。","","N"],["1993-N122",40,"第七节 慢性肾小球肾炎","慢性肾小球肾炎实验室检查",1993,122,"C","","慢性肾小球肾炎致慢性肾功能不全时",[["A","血尿酸高于正常"],["B","尿尿酸240mg/24小时"],["C","二者均有"],["D","二者均无"]],"C","尿酸是体内核酸中嘌呤代谢的最终产物。其中大部分由内源性核酸降解产生（占80％），小部分来自于食物中的核酸代谢（占20％）。尿酸代谢去路30％由肠黏膜细胞分泌进入肠道，经细菌分解为氨排出体外，另60％～70％的尿酸主要由肾脏排泄，经肾小球滤过后在肾小管中重吸收和分泌。慢性肾小球肾炎导致的慢性肾功能不全时，即使体内尿酸生成没有增加（无尿酸生成过多因素），血尿酸值也会升高（A对），原因是肾排泄功能下降（持续血尿酸高的患者中90％有肾处理尿酸功能的异常），其实在慢性肾功能不全时不仅仅有血尿酸升高，代谢产物如磷酸、硫酸等酸性物因肾排泄障碍而潴留，即为“尿毒症性酸中毒”（十版内科学P527）。相反，此时尿液中尿酸含量（尿尿酸正常值为403.36～907.56mg/24小时）减少（B对）。尿酸增加仅见于肾功能正常而血清尿酸增加的情况。本题AB均对，正确答案为C。","","N"],["1993-N123",35,"第一节 肝硬化","门静脉高压",1993,123,"C","","脾大",[["A","与门脉高压有关"],["B","与肝功能减退有关"],["C","两者均有关"],["D","两者均无关"]],"A","门静脉高压（A对）时脾静脉回流阻力增加及门静脉压力逆传到脾，使脾脏被动淤血性肿大。而肝功能减退（B错）的临床表现主要为消化吸收不良、营养不良、黄疸、出血和贫血、内分泌失调、不规则低热、低白蛋白血症等，而与脾大无关。","","N"],["1993-N124",35,"","",1993,124,"C","","肝性脑病",[["A","与门脉高压有关"],["B","与肝功能减退有关"],["C","两者均有关"],["D","两者均无关"]],"C","大部分肝性脑病由肝硬化引起，肝硬化失代偿期症状较明显，主要有肝功能减退和门静脉高压两类临床表现。肝功能减退时（B对），肝脏对氨的代谢能力减退，门静脉高压时（A对），门静脉与体静脉之间形成大量交通支，肠道内产生的氨可不经肝脏解毒、代谢直接进入体循环。因此二者均可导致血氨升高，导致肝性脑病。本题AB均对，正确答案为C。","","N"],["1993-N136",35,"","",1993,136,"X","","肝性脑病时，患者血液生化指标升高的有",[["A","支链氨基酸"],["B","芳香族氨基酸"],["C","血NH₃"],["D","尿素"]],"BC","氨代谢紊乱引起氨中毒是肝性脑病、特别是门-体分流性肝性脑病的重要发病机制。健康的肝脏可将门静脉输入的氨转变为尿素和谷氨酰胺，使之极少进入体循环，肝功能不全时，肝脏对氨的代谢能力明显减退，或有门体分流存在时，肠道的氨不经肝脏代谢而直接进入体循环，血氨升高（C对），游离的NH₃透过血脑屏障通过多种作用机制引起神经系统功能障碍导致肝性脑病。血中芳香族氨基酸增多（B对），支链氨基酸减少（A错）可导致脑内假性递质增多，可竞争性抑制正常神经递质的作用，导致神经功能障碍。由于肝脏代谢障碍，ATP供给不足以及肝内酶系统受损害，导致鸟氨酸循环障碍，尿素合成能力降低，血中尿素含量下降（D错）。","","N"],["1993-N145",27,"第二节 慢性胃炎","慢性胃炎Hp检测",1993,145,"X","","胃内幽门螺杆菌阳性常见于",[["A","糜烂性胃炎"],["B","活动性胃炎"],["C","十二指肠球部溃疡"],["D","十二指肠球炎"]],"ABCD","糜烂性胃炎（A对）分为急性糜烂性胃炎和慢性糜烂性胃炎，前者的病因为应激、药物、酒精、创伤等因素，而后者常与幽门螺杆菌感染有关。活动性胃炎（B对）指慢性胃炎活动期，幽门螺杆菌感染是慢性胃炎最常见的病因，因此胃内幽门螺杆菌阳性常见于活动性胃炎。十二指肠球部溃疡（C对）患者的Hp感染率高达90％～100％。十二指肠炎（D对）多发生在球部，与胃酸分泌过高、HP感染、细胞凋亡等因素有关，长期大量饮酒、药物刺激、应激等因素可诱发此病。","","N"],["1993-N146",27,"第二节 慢性胃炎","慢性胃炎病因和发病机制",1993,146,"X","","胃酸缺乏常见于",[["A","胃癌"],["B","胃溃疡"],["C","慢性胃体胃炎"],["D","慢性胃窦胃炎"]],"AC","胃癌（A对）好发于胃窦部及胃体部，壁细胞位于胃体部，由于分泌胃酸的壁细胞遭到破坏，因此胃酸分泌减少，G细胞位于胃窦部，分泌胃泌素的G细胞遭到破坏，也会引起胃酸减少，最终导致胃酸缺乏。慢性胃体炎（C对）即自身免疫性胃炎，患者体内产生针对壁细胞或内因子的自身抗体，发生炎症反应导致壁细胞总数减少，胃酸分泌缺乏。胃溃疡（B错）多见于胃角和胃窦小弯，一般不会影响壁细胞的功能，胃酸常正常或稍减少。慢性胃窦胃炎（D错）的病变部位发生在胃窦部，也不会影响壁细胞的功能，胃酸常正常或稍减少。","","N"],["1993-N147",61,"第一节 糖尿病","胰岛素",1993,147,"X","","糖尿病治疗过程中，下列哪些注意事项是对的",[["A","遇感染、手术等情况胰岛素用量常需增加"],["B","合并妊娠者最好选用达美康治疗"],["C","合并肾功能不全时，胰岛素用量常需减少"],["D","合并Sheehan病时常需大大减少胰岛素用量"]],"ACD","遇感染、手术等情况，机体处于应激状态，胰岛素拮抗激素（如肾上腺素、促肾上腺皮质激素、肾上腺皮质激素和生长激素）分泌增加，故胰岛素用量常需增加（A对）。胰岛素主要在肾与肝中代谢，故肾功能不全时用量常减少（C对）。Sheehan综合征（希恩综合征）（十版内科学P674）是由于产后大出血，垂体前叶组织缺氧、变性坏死，继而纤维化，最终导致垂体前叶功能减退的综合征。合并Sheehan病时，垂体功能减退，体内拮抗胰岛素的激素（如肾上腺素、肾上腺皮质激素和生长激素等）分泌减少，故机体对胰岛素更加敏感，特别是伴生长激素不足者，严重病例有时有低血糖发作，因此糖尿病合并Sheehan病时胰岛素的用量应减少（D对）。糖尿病合并妊娠禁用降糖药物（达美康）以防止致畸（B错）。","","N"],["1993-N148",49,"第一节 再生障碍性贫血","重型再生障碍性贫血",1993,148,"X","","急性再生障碍性贫血早期表现是",[["A","起病急速，症状较重"],["B","感染"],["C","出血"],["D","明显贫血"]],"ABC","急性再生障碍性贫血常见于重型再生障碍性贫血，起病急速，症状较重（A对）；外周血三系减少，患者可出现贫血、感染、出血等临床表现。但由于白细胞和血小板的寿命均较短，所以骨髓造血障碍时，早期就会引起感染（白细胞减少）（B对）和出血（血小板减少）（C对）。而红细胞的寿命为120天，所以早期不会发生明显贫血（D错），患者贫血症状呈进行性加重。","","N"],["1993-N150",18,"第二节 继发性高血压","肾实质性高血压发病机制",1993,150,"X","","与肾性高血压有关的致血压升高的生理活性物质",[["A","血管紧张素Ⅱ"],["B","前列腺素"],["C","醛固酮"],["D","心钠素"]],"AC","肾实质性高血压的发生主要是由于肾单位大量丢失，导致水、钠潴留和细胞外容量增加，以及肾脏RAAS激活。RAAS激活可导致血管紧张素Ⅱ增多，血管紧张素Ⅱ（A对）可直接使小动脉平滑肌收缩，增加外周阻力，使交感神经兴奋，同时可刺激肾上腺皮质球状带，使醛固酮（C对）分泌增加，从而使肾小管钠重吸收加强，导致体内水钠潴留，使血压升高。前列腺素（B错）能使血管平滑肌松弛，从而减少血流的外周阻力，降低血压。心钠素（D错）具有抑制血管升压素和血管紧张素的作用，利尿排钠、扩张血管、降低血压。","","N"],["1993-N151",2,"第一节 支气管哮喘","支气管哮喘临床表现",1993,151,"X","","支气管哮喘的患者出现下面哪些情况提示病情严重有合并症发生",[["A","PaCO₂=4.6KPa（35mmHg），PaO₂=8.7KPa（65mmHg）"],["B","奇脉"],["C","两肺哮鸣音"],["D","呼吸困难加重，而哮鸣音减轻或消失"]],"BD","当支气管哮喘病变加重时，支气管痉挛加重，吸气时出现肺过度膨胀和肺内压增高，影响静脉血液回流，左室射血减少，脉搏明显减弱甚至消失，呼气时肺内压降低，又恢复正常，即出现奇脉（B对）。若病变继续发展，病人可由于供氧不足而出现嗜睡和意识模糊、胸腹矛盾运动、哮鸣音减弱甚至消失（D对）等表现，提示病情危重。当PaCO₂=4.6KPa（35mmHg）（正常值为35mmHg～45mmHg）及PaO₂=8.7kPa（65mmHg）（正常值＞60mmHg）时，机体氧分压虽下降但尚未出现高碳酸血症，不能提示病情严重（A错）。哮鸣音（C错）为支气管哮喘典型症状，只要气道存在狭窄，呼吸时便可闻及哮鸣音，不是判断病变严重程度的指标。","","N"],["1993-N152",16,"第八节 心律失常的介入治疗和手术治疗","禁忌证",1993,152,"X","","下列哪些情况不宜作心脏电复律",[["A","低血钾所致快速心律失常"],["B","非阵发性交界性心动过速"],["C","心房纤颤伴室内差异性传导"],["D","病态窦房结综合征伴快速室上性心动过速"]],"ABD","心脏电复律指在严重快速型心律失常时，用外加的高能量脉冲电流通过心脏，使全部或大部分心肌细胞在瞬间同时除极，造成心脏短暂的电活动停止，然后由最高自律性的起搏点（通常为窦房结）重新主导心脏节律的治疗过程。低钾血症（A对）可以诱发产生室性和房性早搏，低血钾抑制细胞膜上的多种钾通道使钾外流减小，相继引起其他跨膜离子流（如钙电流等）发生改变，使心室肌细胞的电生理特性异常。非阵发性交界性心动过速（B对）最常见的病因为洋地黄中毒，不能运用电转复。病态窦房结综合征伴快速室上性心动过速（D对）不宜做心脏电复律。心房纤颤伴室内差异性传导（C错）可以使用电转复。","","N"],["1993-N153",19,"第六节 心肌炎","心肌炎临床表现",1993,153,"X","","活动性风湿性心肌炎可出现",[["A","心尖部收缩期及/或舒张期杂音"],["B","左、右束支传导阻滞"],["C","血清CPK-MB增高"],["D","心脏扩大"]],"ABCD","风湿性心肌炎轻者可无症状，重者可伴不同程度的心衰（二版八年制内科学P320）。常见体征包括：心脏扩大（D对），心尖搏动弥散；心音低钝，可闻及奔马律；心尖部轻度收缩期吹风样杂音，75%初发患儿主动脉瓣区可闻及舒张中期杂音（A对）。心电图可见PR间期延长，伴有T波低平和ST段异常，可伴有心律失常。部分患者亦可出现左、右束支传导阻滞（B对）。风湿性心肌炎存在心肌细胞的损伤，可引起血清CPK-MB（CK-MB，即肌酸激酶同工酶）增高（C对）。","","N"],["1993-N154",3,"第一节 支气管扩张症","支气管扩张病理和病理生理",1993,154,"X","","以下哪些疾病不表现为阻塞性通气障碍",[["A","重症支气管扩张"],["B","类风湿关节炎引起的肺病变"],["C","慢性支气管炎"],["D","肺水肿"]],"BD","重症支气管扩张（A对）大多继发于急、慢性呼吸道感染和支气管阻塞后，反复发生支气管炎症，致使支气管壁结构破坏，引起支气管异常和持久性扩张，支扩可因感染加重而出现痰量增多或病变累及周围肺实质导致阻塞性通气障碍；慢性支气管炎（C对）由于支气管分泌大量黏性物质导致阻塞性通气障碍；类风湿关节炎（十版内科学P814）（B错，为本题正确答案）引起的肺病变主要表现为肺间质病变，影响肺换气功能，不表现为阻塞性通气障碍；肺水肿（D错，为本题正确答案）是指由于某种原因引起肺内组织液的生成和回流平衡失调，使大量组织液在很短时间内不能被肺淋巴和肺静脉系统吸收，从肺毛细血管内外渗，积聚在肺泡、肺间质和细小支气管内，从而造成肺通气与换气功能严重障碍，主要表现为肺换气和限制性通气障碍，不表现为阻塞性通气障碍。","","N"],["1994-N48",45,"第一节 慢性肾衰竭","心血管系统表现",1994,48,"A","","慢性肾功能衰竭时高血压的发生机制。下列哪项是正确的",[["A","肾素-血管紧张素水平增高"],["B","血容量扩张"],["C","血容量与肾素-血管紧张素平衡失调"],["D","激肽系统的作用"],["E","肾动脉狭窄"]],"C","慢性肾衰竭患者血压升高，多由于水、钠潴留及肾素-血管紧张素增高和（或）某些舒张血管的因子产生不足所致。水、钠潴留导致血容量扩张；肾素-血管紧张素增高导致小动脉平滑肌收缩，这些作用都可使血压增高。C选项兼顾了A、B选项的平衡关系，因此血容量与肾素-血管紧张素平衡失调（C对）为慢性肾功能衰竭时高血压的发生机制。肾脏可介导激肽释放酶-激肽系统的内分泌作用（八版内科学P460），激肽系统可作用于血管平滑肌，使其舒张致血压降低。慢性肾衰竭时，激肽系统的作用（D错）减弱可以导致血压升高，但非主要机制。肾动脉狭窄（E错）为肾血管性高血压发生病因。","","N"],["1994-N49",59,"第一节 甲状腺功能亢进症","妊娠期甲亢的治疗",1994,49,"A","","妊娠早期合并甲亢时的治疗应首选",[["A","甲巯咪唑"],["B","丙硫氧嘧啶"],["C","碳酸钾"],["D","心得安"],["E","碘剂"]],"B","抗甲状腺药（如：甲巯咪唑、丙硫氧嘧啶）能通过胎盘浓集于胎儿甲状腺，妊娠妇女慎用或不用。若必须使用时，应当按照妊娠的时期用药：妊娠T1期（1-3个月）使用丙硫氧嘧啶（B对），而在妊娠T2期（4-6个月）和T3期（7-9个月）使用甲巯咪唑（A对）。由于题干没有给出妊娠时期，因此，本题正确答案存在争议。碘剂能通过胎盘或进入乳汁，可能引起新生儿和婴儿甲状腺功能异常或甲状腺肿，严重者可因压迫气管而致命（E错）。心得安（普萘洛尔）可通过胎盘进入胎儿体内，患者用后可导致宫内胎儿发育迟缓，分娩时无力造成难产，在新生儿可产生低血压、低血糖、呼吸抑制及心率减慢等不良反应（D错）。碳酸钾主要用于食品中作膨松剂，属干扰选项（C错）。","","N"],["1994-N50",59,"第一节 甲状腺功能亢进症","剂量与疗程",1994,50,"A","","Graves病停用药物时，下列哪项检查对判断该病的预后关系最大",[["A","甲状腺缩小，杂音消失"],["B","T₃抑制试验可抑制"],["C","T₃、T₄及rT₃正常"],["D","TSH恢复正常"],["E","甲状腺刺激抗体阴性"]],"E","Graves病在使用抗甲状腺药物时，无论是否复发，抗甲状腺药物治疗1～2年后均需考虑停药。由于Graves病的主要特征是血清中存在针对甲状腺细胞TSH（促甲状腺激素）受体的特异性自身抗体TRAb（促甲状腺激素受体抗体），所以停药后对判断该病的预后关系最大的是TRAb（促甲状腺激素受体抗体）是否转阴（E对）。甲状腺缩小，杂音消失（A错）是甲状腺手术术前准备时，服用碘剂使甲状腺组织充血减少的结果。T₃（三碘甲状腺原氨酸）抑制试验用于单纯甲状腺肿与其他类型甲亢的鉴别（B错）。T₃（三碘甲状腺原氨酸）、T₄（甲状腺素）、rT₃（反三碘甲状腺原氨酸）（C错）及TSH（促甲状腺激素）（D错）测定一般用于诊断甲亢，与判断该病的预后并无直接关系。","","N"],["1994-N51",56,"第二节 原发免疫性血小板减少症","脾切除",1994,51,"A","","特发性血小板减少性紫癜患者，应用糖皮质激素治疗多长时间无效，才考虑切脾",[["A","1个月"],["B","2个月"],["C","3个月"],["D","4～6个月"],["E","＞6个月"]],"E","特发性血小板减少性紫癜患者首选糖皮质激素治疗，脾切除为二线治疗，其适应证包括：①正规糖皮质激素治疗无效，病程迁延6个月以上（E对）；②糖皮质激素维持量需大于30mg/d；③有糖皮质激素使用禁忌证。（10版内科学P623）“脾切除 用于糖皮质激素正规治疗无效、泼尼松安全剂量（5mg/d）不能维持疗效，以及使用糖皮质激素有禁忌且 ITP 确诊至少 12～24 个月以上者”","","N"],["1994-N52",56,"第二节 原发免疫性血小板减少症","出、凝血及血小板功能检查",1994,52,"A","","下列哪项在严重的特发性血小板减少性紫癜患者中最常见到",[["A","BT延长"],["B","CT延长"],["C","束臂试验阴性"],["D","血小板功能正常"],["E","骨髓巨核细胞数减少"]],"A","出血时间（BT）是指人为刺破皮肤毛细血管后，从血液自然流出到自然停止所需的时间。它受血小板的数量和质量、毛细血管结构和功能的影响，ITP患者血小板减少，故BT延长（A对）。凝血时间（CT）是指血液离开血管，在体外发生凝固的时间。它主要反映内源性凝血系统的功能，与血小板无关，故ITP患者CT正常（B错）。束臂试验又称毛细血管抵抗力试验。当毛细血管管壁的结构和功能、血小板数量和质量存在缺陷时，毛细血管壁脆性和通透性增加，新出血点增加，因而出现束臂试验阳性（C错）。ITP患者由于血小板减少，骨髓巨核系可代偿性增生，巨核细胞数量正常或增加（E错）。ITP患者血小板功能一般正常，但不如BT延长更常见（D错）。","","N"],["1994-N53",30,"第一节 溃疡性结肠炎","中毒性巨结肠",1994,53,"A","","溃疡性结肠炎患者腹痛、腹泻明显时，应用M胆碱能受体阻断药剂量过大，可能引起下列哪项并发症",[["A","机械性肠梗阻"],["B","肠穿孔"],["C","中毒性结肠扩张"],["D","结肠大出血"],["E","以上均不是"]],"C","重症溃疡性结肠炎患者结肠病变广泛而严重，累及肌层与肠肌神经丛，肠壁张力减退，此时若应用过量M胆碱能受体阻断药会抑制肠蠕动，使结肠蠕动消失，肠内容物与气体大量积聚，致急性结肠扩张，从而诱发中毒性巨结肠（P374）（C对）。低钾、钡剂灌肠或使用阿片类制剂等也会诱发。肠穿孔（B错）多与中毒性巨结肠有关，而与过量服用抗胆碱能药物无直接相关性。过量应用抗胆碱能药物可导致动力性肠梗阻，而机械性肠梗阻（A错）常由于肠壁粘膜大量纤维组织增生僵硬变细及炎性息肉阻塞肠道所致，与抗胆碱能药物的应用无关。结肠大出血（D错）的发生与肠壁粘膜糜烂、溃疡累及血管有关，而与过量服用抗胆碱能药物无关。","","N"],["1994-N54",36,"第一节 原发性肝癌","黄曲霉毒素",1994,54,"A","","原发性肝癌的发生与下列哪种因素最有关",[["A","肠道戊型肝炎病毒感染"],["B","肠道寄生虫感染"],["C","肠道细菌感染"],["D","黄曲霉素污染"],["E","酒精中毒"]],"D","黄曲霉毒素有极强的致癌性，长期摄入黄曲霉毒素会诱发肝癌，流行病学调查发现在一些肝癌高发地区，粮油、食品（如玉米、小麦、大豆、花生等）受黄曲霉素B₁污染的情况往往比较严重，而在低发区较少见。动物实验表明，黄曲霉素B₁是肝癌最强的致癌物，与肝癌的发生密切相关，它诱发肝癌的能力比二甲基亚硝胺大75倍，是目前公认的致癌性最强的物质之一（D对）。乙肝病毒、丙肝病毒与原发性肝癌有关，但未发现肠道戊型肝炎病毒感染与肝癌发生有关（A错）。寄生虫如血吸虫及华支睾吸虫感染均可导致肝癌，但并不是最相关因素（B错）。肠道细菌感染未见与原发性肝癌相关（C错）。长期大量饮酒导致酒精性肝病，在此基础上的肝纤维化及肝硬化过程都可能引发肝癌，但在几个选项中不是最相关因素（E错）。","","N"],["1994-N55",29,"第一节 肠结核","肠结核诊断",1994,55,"A","","女性28岁，右下腹痛、腹泻伴关节酸痛，低热半年。查体：心肺正常，腹软，右下腹触及可疑肿块，X线钡餐检查显示回盲部有钡影跳跃征象（stierlin’s sign），最可能的诊断是",[["A","Crohn病（克罗恩病）"],["B","肠结核"],["C","阿米巴痢疾"],["D","右半结肠癌"],["E","溃疡性结肠炎"]],"B","青年女性患者，低热（结核毒血症状）、右下腹痛、腹泻，右下腹部包块，X线钡餐：回盲部（肠结核的好发部位）有钡影“跳跃征”（溃疡性肠结核的典型征象），均支持肠结核的诊断（B对）。克罗恩病（十版内科学P392）（A错）病变呈节段性或跳跃式分布，钡剂造影见纵行性溃疡或裂沟以及鹅卵石征。阿米巴痢疾（十版内科学P390）（C错）有既往感染病史，粪便常规或孵化检查可发现有关病原体。右半结肠癌（十版内科学P396）（D错）发病年龄比肠结核晚，一般无结核毒血症表现。结肠镜检查及粘膜活检可明确诊断。溃疡性结肠炎（E错）病变多位于直肠，由直肠向近端发展，其腹痛多位于左下腹或下腹（而不是右下腹），其重要特点为黏液脓血便（十版内科学P388），其X线表现为：粘膜粗乱和颗粒样改变；多发性浅溃疡；肠管缩短，结肠袋消失，肠壁变硬，可呈铅管样（十版内科学P390）。","","N"],["1994-N56",28,"第一节 消化性溃疡","胃酸与胃蛋白酶",1994,56,"A","","消化性溃疡的命名主要是由于",[["A","溃疡发生于消化道"],["B","溃疡影响消化功能"],["C","溃疡形成与消化道功能障碍有关"],["D","溃疡形成与胃酸和胃蛋白酶消化作用有关"],["E","溃疡形成与消化道激素排泌紊乱有关"]],"D","消化性溃疡主要指发生在胃和十二指肠的慢性溃疡，因溃疡形成与胃酸/胃蛋白酶的消化作用有关而得名（D对）。","","N"],["1994-N58",27,"第二节 慢性胃炎","慢性胃炎诊断",1994,58,"A","","判断胃酸缺乏最可靠的指标是",[["A","呕吐物无酸"],["B","空腹胃液pH为7"],["C","BAO为0"],["D","MAO为0"],["E","空腹胃液中游离酸为0"]],"D","MAO（最大胃酸分泌）（D对）是指给予刺激后连续收集1小时胃液所测泌酸值，若无酸，即MAO为0，是胃酸缺乏最可靠的指标。BAO（基础胃酸分泌）（C错）是指抽取空腹胃液后，再连续收集1小时胃液所测泌酸值，未加刺激剂，若为0，刺激后还可能会有酸分泌，所以不如MAO可靠。呕吐物无酸（A错）、空腹胃液pH为7（B错）和空腹胃液中游离酸为0（E错）的可靠性更差。","","N"],["1994-N59",75,"第一节 中毒概述","洗胃",1994,59,"A","","误服下列哪种药物应禁忌洗胃",[["A","东莨菪碱"],["B","水杨酸盐"],["C","氢氧化钠"],["D","盐酸麻黄碱"],["E","亚硝酸盐类"]],"C","氢氧化钠为强碱，具有强腐蚀性，插胃管洗胃有引起食管、胃穿孔的危险，故不宜洗胃（C对），应给予药物及物理性对抗剂，如牛奶、蛋清、米汤、豆浆等保护胃黏膜。东莨菪碱（A错）、盐酸麻黄碱（D错）为生物碱，应采用1：5000高锰酸钾或10%活性炭悬浮液洗胃。水杨酸盐（B错）为弱酸，可采用10%活性炭悬浮液洗胃。亚硝酸盐（E错）为无机盐类，无腐蚀性，中毒后可用1：5000高锰酸钾液洗胃。ABDE选项均为非禁忌洗胃毒物，必要时予以洗胃处理。","","N"],["1994-N60",52,"第三节 慢性髓系白血病","细胞遗传学及分子生物学检查",1994,60,"A","","慢性粒细胞性白血病的Ph染色体是",[["A","t（8；21）"],["B","t（8；22）"],["C","t（9；21）"],["D","t（9；22）"],["E","t（9；23）"]],"D","Ph染色体是由Nowell及Hungerford于1960年在慢性粒细胞性白血病（CML）患者血中发现的，由于首先在美国费城发现，故也称为费城1号染色体。Ph染色体显带分析为t（9；22）（q34；q11）（D对），是9号染色体长臂上原癌基因C-ABL易位至22号染色体长臂的断裂点簇集区（BCR）形成BCR-ABL融合基因。Ph染色体多见于慢性粒细胞白血病（阳性率95%），也可见于急粒白血病（2%）、成人急淋白血病（25%）、儿童急淋白血病（5%）等，而慢淋白血病呈阴性。","","N"],["1994-N61",6,"第一节 肺结核","异烟肼",1994,61,"A","","常用于杀菌作用，并能透过血脑屏障，以及在胸水、干酪性病灶中浓度较高的抗结核药是",[["A","链霉素"],["B","对氨基水杨酸"],["C","利福平"],["D","异烟肼"],["E","氨硫脲"]],"D","异烟肼（D对）杀菌作用强，可渗入全身各组织中，容易通过血-脑脊液屏障，胸腔积液、干酪样病灶中药物浓度很高。链霉素对空洞内胞外结核菌作用强，不易通过血脑屏障和细胞膜（A错）。对氨基水杨酸（B错）和氨硫脲（E错）都是抑菌剂，无杀菌作用。利福平是杀菌剂（C错），主要在肝脏代谢，胆汁排泄，在胆汁中浓度高，也可穿透干酪样病灶和进入巨噬细胞，但在正常情况下不通过血-脑屏障、胸水中的浓度不高。","","N"],["1994-N62",2,"第一节 支气管哮喘","茶碱类药物",1994,62,"A","","氨茶碱治疗支气管哮喘的作用机理是",[["A","阻断迷走神经"],["B","抑制磷酸二酯酶"],["C","激活腺苷酸环化酶"],["D","保护肥大细胞溶酶体膜"],["E","使封闭抗体增加"]],"B","治疗哮喘的药物主要有糖皮质激素、β₂受体激动剂、白三烯调节剂、茶碱类药物、抗胆碱类药物等。氨茶碱治疗支气管哮喘的作用机理是抑制磷酸二酯酶（B对），提高平滑肌细胞内的环腺苷酸（cAMP）浓度，拮抗腺苷受体，增强呼吸肌的力量以及增强气道纤毛清除功能等，从而起到舒张支气管和气道抗炎作用。阻断迷走神经（十版内科学P36）（A错）为抗胆碱药物的作用机制；激活腺苷酸环化酶（C错）为β₂受体激动剂的作用机制；保护肥大细胞溶酶体膜为色苷酸钠和酮替芬的作用机制（D错）（九版病理学P294）。使封闭抗体增加为抗IgE抗体的作用机制（E错）。","","N"],["1994-N63",1,"第一节 慢性支气管炎","慢性支气管炎肺功能检查",1994,63,"A","","慢性支气管炎早期肺功能改变为",[["A","VC减少"],["B","一秒率减少"],["C","残气量增加"],["D","闭合气量减少"],["E","肺总量增加"]],"B","慢性支气管炎早期病变为支气管上皮细胞变性、坏死、脱落，支气管管壁多种炎性细胞浸润，杯状细胞和黏液腺肥大增生、分泌旺盛，大量黏液潴留在气道。呼吸功能检查一般无异常，如有小气道阻塞，最大呼气流速-容量曲线在75%和50%肺容量时流量明显减低，一秒率可减少（B对），闭合气量可增加（D错）。随着病情发展，肺组织弹性减退，肺泡腔扩大，回缩障碍，VC（肺活量）减少（A错），残气量增加（C错），肺总量增加（E错）。","","N"],["1994-N64",3,"第一节 支气管扩张症","支气管扩张诊断",1994,64,"A","","根据下列哪项条件可确诊支气管扩张",[["A","慢性咳嗽、咳痰"],["B","反复咯血"],["C","大量咳痰且分层"],["D","肺部湿啰音"],["E","支气管造影"]],"E","支气管碘脂质造影（E对）可以清楚的显示扩张的支气管，具有确诊作用，但因为此检查为创伤性检查，现已被高分辨率CT所取代。慢性咳嗽、咳痰（A错）、反复咯血（B错）、大量咳痰且分层（C错）、肺部湿啰音（D错）均为支气管扩张的临床表现，但不具有特异性，故不能用来诊断支气管扩张。","","N"],["1994-N65",2,"第一节 支气管哮喘","神经调节机制",1994,65,"A","","支气管哮喘的发病与下列哪种物质无关",[["A","环化一磷酸腺苷（cAMP）"],["B","环化一磷酸鸟苷（cGMP）"],["C","腺苷脱氨酶（ADA）"],["D","慢反应物质（SRS-A）"],["E","前列环素"]],"C","哮喘发作与cAMP/cGMP比值有关（AB对），比值增大时，支气管扩张，比值减小时，支气管痉挛，发生哮喘。慢反应物质（SRS-A）（D对）是发生速发型过敏反应时，肺组织释放的化学介质，可使气管和支气管平滑肌收缩，引发哮喘。前列环素（PGI₂）（E对）与血栓烷A₂（TXA₂）之间的失衡参与了哮喘的发病。腺苷脱氨酶ADA（C错，为本题正确答案）主要用于肝脏疾病、结核、SLE等疾病的诊断，与哮喘发病无关，故应排除。","","N"],["1994-N67",11,"第一节 胸腔积液","恶性胸腔积液",1994,67,"A","","癌性胸水具有下列哪项特点",[["A","比重小于1.018"],["B","蛋白含量低于3g/dl"],["C","细胞总数不超过100个/μl"],["D","胸水LDH含量高于血清"],["E","胸水蛋白/血清蛋白＜0.5"]],"D","癌肿侵及胸膜后，胸膜遭到破坏，胸膜内毛细血管通透性增高，可产生渗出性胸水，表现为颜色浑浊或血性，比重＞1.018（A错），蛋白定量＞3g/dL（B错），白细胞数＞500/μL（C错），胸水蛋白/血清蛋白＞0.5（E错）。恶性胸腔积液时LDH＞500U/L，正常血清LDH值＜500U/L，故胸水LDH含量高于血清（D对）。","","N"],["1994-N68",17,"第四节 急性冠状综合征","硝酸酯类药物",1994,68,"A","","急性心肌梗死24小时内伴发急性左心功能不全的处理，下列哪一项不适宜",[["A","应用吗啡"],["B","快速利尿剂"],["C","多巴酚丁胺静脉点滴"],["D","硝普钠静脉点滴"],["E","快速洋地黄化"]],"E","急性心肌梗死24小时内伴发急性左心功能不全的患者主要出现坏死心肌间质充血、水肿引起顺应性下降，左心室舒张末期容量尚未增大，洋地黄类药物可引起室性心律失常，故在梗死发生后24小时内宜尽量避免使用洋地黄制剂（E错，为本题正确答案）。应用吗啡（A对）可以解除疼痛，同时可减轻交感神经过度兴奋和濒死感，减少心肌耗氧量。快速利尿剂（B对）可降低心脏前负荷，减轻心衰所致水肿。多巴酚丁胺静脉点滴（C对）可以提高周围血管张力，升高血压，改善肾血流灌注，减少肾前性肾衰的发生。硝普钠（十版内科学P271）（D对）可降低心脏前后负荷，降低PCWP（肺毛细血管楔压），提高CI（心指数），同时可缓解因周围血管显著收缩引起的四肢厥冷和发绀症状。","","N"],["1994-N69",15,"第二节 慢性心力衰竭","洋地黄类药物",1994,69,"A","","洋地黄最适宜治疗下列哪项引起的急性肺水肿",[["A","急性心肌梗死"],["B","甲状腺功能亢进"],["C","快速心室率的阵发性心房纤颤"],["D","严重二尖瓣狭窄"],["E","梗阻性心肌病"]],"C","一般剂量下，洋地黄可抑制心脏传导系统，对房室交界区的抑制最为明显，还可作用于迷走神经传入纤维，增加心脏压力感受器的敏感性，在房颤时延缓房室传导，从而减慢房颤的心室率，且不增加心肌耗氧量，因此洋地黄最适宜治疗伴有快速心室率的阵发性心房颤动（C对）。急性心肌梗死（A错）24小时内应用洋地黄易发生洋地黄中毒，应慎用。甲亢性心肌病患者主要治疗甲亢，待甲亢症状缓解后，心脏病症状可以得到改善（B错）。严重二尖瓣狭窄（D错）应用洋地黄会增加右心室收缩功能，从而加重肺水肿。梗阻性心肌病（E错）应用洋地黄可导致流出道梗阻加重。","","N"],["1994-N70",17,"第四节 急性冠状综合征","血清心肌坏死标志物",1994,70,"A","","心肌酶中对诊断急性心肌梗塞特异性最高的是",[["A","CPK-MB及LDH₂"],["B","CPK-MM及LDH₁"],["C","CPK-MB及LDH₁"],["D","CPK-MB及LDH₃"],["E","CPK-BB及LDH₁"]],"C","CPK（肌酸磷酸激酶）与CK（肌酸激酶）为同一种物质，CK广泛存在于各种组织中，主要与三磷酸腺苷（ATP）的再生有关，此酶的功能是在生理水平上维持细胞内的三磷酸腺苷浓度。CK由M和B两个亚单位组成，组合成CK-BB（CK₁），CK-MB（CK₂），CK-MM（CK₃）三种同工酶，CK-BB大多存在于脑中，CK-MB则以心肌含量最多，CK-MM在骨骼肌中占90%，故CK-MB升高对诊断心肌梗死具有较好的特异性。乳酸脱氢酶（LDH）是体内能量代谢过程中的一个重要的酶。此酶几乎存在于所有组织中，其分布特点是心、肾以LDH₁为主，LDH₂次之；肺以LDH₃、LDH₄为主；骨骼肌以LDH₅为主；肝以LDH₅为主，LDH₄次之。这些组织中的LDH的活力比血清中高得多。所以当少量组织坏死时，该酶即释放血而使其他血液中的活力升高。测定此酶常用于对心梗、肝病和某些恶性肿瘤的辅助诊断。综上所述，选项中对诊断急性心肌梗塞特异性最高的是CPK-MB（CK-MB）及LDH₁（C对）。","","N"],["1994-N71",16,"第三节 房性心律失常","心房颤动临床表现",1994,71,"A","","关于心房纤颤的诊断，下列哪项不正确",[["A","心音强弱不等"],["B","心律绝对不齐"],["C","容易听到第四心音"],["D","心率大于脉率"],["E","心电图P波消失，代之f波"]],"C","第四心音的产生与心房收缩使房室瓣及其相关结构（瓣膜、瓣环、腱索和乳头肌）突然紧张、振动有关，也称心房音（九版诊断学P149）。房颤时心房失去了正常的收缩功能，不会出现第四心音（C错，为本题正确答案）。房颤心脏听诊典型表现有三个：心音强弱不等（A对）、心律绝对不齐（B对）和脉搏短绌（即心率大于脉率）（D对）。心电图典型表现为P波消失，代之以f波（E对）。","","N"],["1994-N72",16,"第七节 抗心律失常药物的合理应用","Ⅰ类",1994,72,"A","","下列哪种抗心律失常药物属ⅠA类",[["A","利多卡因"],["B","毗二丙胺（丙吡胺）"],["C","普罗帕酮（心律平）"],["D","美西律（慢心律）"],["E","胶磺达隆（乙胺碘呋酮）"]],"B","吡二丙胺（丙吡胺）（B对）可以减慢动作电位0相上升速度（Vmax），延长动作电位时限，属于ⅠA类抗心律失常药物。利多卡因（A错）及美西律（慢心律）（D错）不减慢Vmax，缩短动作电位时限，属于ⅠB类药物。普罗帕酮（心律平）（C错）减慢Vmax，减慢传导与轻微延长动作电位时限，属于ⅠC类药物。胶磺达隆（乙胺碘呋酮）（E错）即盐酸胺碘酮，可阻断钾通道与延长复极，属于Ⅲ类药物。","","N"],["1994-N73",15,"第二节 慢性心力衰竭","左心衰竭症状",1994,73,"A","","下列哪项不属于左心功能不全的临床表现",[["A","心尖部舒张期奔马律"],["B","交替脉"],["C","呼吸困难"],["D","颈静脉怒张"],["E","端坐呼吸"]],"D","颈静脉怒张（D错，为本题正确答案）与否可反映右心房压力变化及容量变化。正常人立位或坐位时，颈外静脉不显露，平卧位时稍见充盈，但仅限于锁骨上缘至下颌角距离的2/3处，若超过上述水平或半卧位45°时，颈静脉充盈、胀大、饱满则称颈静脉怒张，表明静脉压增高，提示右心功能不全，体循环淤血。奔马律系指一种额外心音发生在舒张期的三音心律，由于同时常存在的心率增快，额外心音与原有S₁、S₂组成类似马奔跑时的蹄声。奔马律是心肌严重损害的体征。舒张早期奔马律（A对）的出现，提示有严重器质性心脏病，常见于心力衰竭、急性心肌梗死、重症心肌炎与扩张性心肌病等。交替脉（B对）系节律规则而强弱交替的脉搏。一般认为是左室收缩力强弱交替所致，为左室心力衰竭的重要体征之一。常见于高血压性心脏病、急性心肌梗死和主动脉瓣关闭不全导致的心力衰竭。左心衰时可有不同程度的呼吸困难（C对），左心衰竭最早出现的症状是劳力性呼吸困难，严重时表现为端坐呼吸（E对）。","","N"],["1994-N74",23,"第一节 感染性心内膜炎","心脏杂音",1994,74,"A","","关于感染性心内膜炎，下列哪项正确",[["A","多见于老年患者"],["B","心内赘生物多附着于右心耳内"],["C","血培养阴性可排除该病"],["D","心脏杂音的性质和强度可发生突变"],["E","不侵犯脑膜"]],"D","急性者比亚急性者更容易出现心脏杂音的性质及强度改变（D对），多由赘生物破裂、瓣膜破裂及腱索断裂导致。亚急性感染性心内膜炎（九版内科学P308）常发生于风湿性心脏瓣膜病、室间隔缺损、动脉导管未闭等心脏病的基础上。该病好发于青壮年患者（A错）。心脏赘生物多附着于受累的瓣膜上（B错），常见于二尖瓣关闭不全的瓣膜心房面、主动脉瓣关闭不全的瓣膜心室面、室间隔缺损的右心室侧，右心耳处少见。血培养阴性率为2.5%～64%，因此血培养阴性并不能排除该病（C错）。含有细菌的赘生物脱落后可造成脑栓塞，可继发脑脓肿及化脓性脑膜炎（E错）。","","N"],["1994-N91",30,"第一节 溃疡性结肠炎","溃疡性结肠炎病理",1994,91,"A","","关于溃疡性结肠炎的叙述中，下列哪项不是此病的典型表现",[["A","本病的病理特点是结肠黏膜有广泛的溃疡形成"],["B","最常受累的部位是升结肠和回肠末端"],["C","主要症状是腹泻，带有脓血及黏液"],["D","钡剂灌肠和纤维结肠镜是最有价值的检查"],["E","症状反复发作，久治不愈者癌变率高"]],"B","溃疡性结肠炎是一种病因不明的直肠和结肠粘膜广泛溃疡形成及修复增生的炎症性疾病，病变主要限于大肠黏膜和黏膜下层，呈连续性弥漫性分布（A对）。病变多自直肠开始，逆行向近段发展，多累及直肠和乙状结肠（B错，为本题正确答案），可累及全结肠甚至末端回肠。主要症状有反复发作的腹泻、黏液脓血便、腹痛及里急后重（C对）。结肠镜和钡剂灌肠对本病的诊断有重要价值（D对），其中结肠镜最具诊断价值，结肠镜检查有困难时辅以钡剂灌肠检查，但是注意重型及暴发型患者不宜做钡剂灌肠检查，以免加重病情或诱发中毒性巨结肠。本病呈慢性过程，大部分患者反复发作，不容易彻底治愈，病程漫长者癌变危险性增加（E对）。","","N"],["1994-N105",28,"第一节 消化性溃疡","PPI",1994,105,"B","","质子泵抑制剂",[["A","丙谷胺"],["B","前列腺素E₂的衍生物"],["C","奥美拉唑"],["D","哌吡氮平"],["E","吗丁琳"]],"C","奥美拉唑（C对）是质子泵抑制剂，使H⁺-K⁺-ATP酶失去活性，抑酸作用很强，可使胃内达到无酸水平（十版内科学P377）。丙谷胺（A错）是胃泌素受体阻断药，与胃泌素竞争胃泌素受体，有抑制胃酸分泌作用，同时也促进胃黏膜黏液合成，增强胃黏膜的黏液-碳酸氢盐保护屏障，从而发挥抗溃疡病作用。前列腺素E₂的衍生物（B错）为胃黏膜保护剂，如米索前列醇具有抑制胃酸分泌、增加胃十二指肠黏膜的黏液及碳酸氢盐分泌和增加黏膜血流等作用，主要用于NSAID溃疡的预防。哌吡氮平（D错）为选择性抗M胆碱药，竞争性抑制乙酰胆碱，对胃黏膜（特别是壁细胞）的M₁受体有高度亲和力，一般剂量时，仅抑制胃酸分泌而对平滑肌、心肌和涎腺的M₂受体亲和力较低。吗丁啉（E错）是胃肠动力药，外周性多巴胺受体拮抗剂，可促进胃肠道的蠕动和张力恢复正常，促进胃排空，增加胃窦和十二指肠肠运动，协调幽门的收缩，同时也能增强食道的蠕动和食道下端括约肌的张力。","","N"],["1994-N106",28,"第一节 消化性溃疡","保护胃黏膜",1994,106,"B","","黏膜细胞保护剂",[["A","丙谷胺"],["B","前列腺素E₂的衍生物"],["C","奥美拉唑"],["D","哌吡氮平"],["E","吗丁琳"]],"B","前列腺素E₂的衍生物（B对）为胃黏膜保护剂，如米索前列醇具有抑制胃酸分泌、增加胃十二指肠黏膜的黏液及碳酸氢盐分泌和增加黏膜血流等作用，主要用于NSAID溃疡的预防。丙谷胺（A错）是胃泌素受体阻断药，与胃泌素竞争胃泌素受体，有抑制胃酸分泌作用，同时也促进胃黏膜黏液合成，增强胃黏膜的黏液-碳酸氢盐保护屏障，从而发挥抗溃疡病作用。奥美拉唑（C错）是质子泵抑制剂，使H⁺-K⁺-ATP酶失去活性，抑酸作用很强，可使胃内达到无酸水平。哌吡氮平（D错）为选择性抗M胆碱药，在M受体部位与乙酰胆碱竞争性抑制，对胃黏膜（特别是壁细胞）的M₁受体有高度亲和力，一般剂量时，仅抑制胃酸分泌而对平滑肌、心肌和涎腺的M₂受体亲和力较低。吗丁啉（E错）是胃肠动力药，外周性多巴胺受体拮抗剂，可促进上胃肠道的蠕动和张力恢复正常，促进胃排空，增加胃窦和十二指肠肠运动，协调幽门的收缩，同时也能增强食道的蠕动和食道下端括约肌的张力。","","N"],["1994-N107",61,"第一节 糖尿病","胰岛素",1994,107,"B","","一位妊娠5个月的妇女，空腹血糖为11mmol／L，除用饮食控制外，可选用下述哪种药物治疗",[["A","D860"],["B","氯磺丙脲"],["C","胰岛素"],["D","优降糖"],["E","降糖灵"]],"C","本题考察胰岛素治疗糖尿病的适应证。胰岛素的适应证为：①T1DM；②各种严重的糖尿病急性或慢性并发症；③手术、妊娠和分娩；④新发病且与T1DM鉴别困难的消瘦糖尿病患者；⑤新诊断的T2DM伴有明显高血糖；或在糖尿病病程中无明显诱因出现体重显著下降者；⑥T2DMβ细胞功能明显减退者；⑦某些特殊类型糖尿病。该妊娠妇女空腹血糖为11mmol/L（空腹血糖≥7.0mmol/L应考虑糖尿病），即妊娠合并糖尿病或糖尿病合并妊娠，均属胰岛素的适应证（C对）。妊娠合并糖尿病患者禁用口服降血糖药物（ABDE错），因其可通过胎盘，对胎儿有影响。","","N"],["1994-N108",61,"第一节 糖尿病","胰岛素",1994,108,"B","","一位糖尿病合并糖尿病肾病的患者，经饮食控制后，空腹血糖在10～12mmol／L，可先采用下述哪种药物治疗",[["A","D860"],["B","氯磺丙脲"],["C","胰岛素"],["D","优降糖"],["E","降糖灵"]],"C","胰岛素的适应证为：①T1DM；②各种严重的糖尿病急性或慢性并发症；③手术、妊娠和分娩；④新发病且与T1DM鉴别困难的消瘦糖尿病患者；⑤新诊断的T2DM伴有明显高血糖；或在糖尿病病程中无明显诱因出现体重显著下降者；⑥T2DMβ细胞功能明显减退者；⑦某些特殊类型糖尿病。该患者糖尿病合并糖尿病肾病（糖尿病慢性并发症），属胰岛素的适应证，应先采用胰岛素治疗（C对），其他均为辅助治疗（ABDE错）。","","N"],["1994-N109",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄临床表现",1994,109,"B","","风湿性心脏病主动脉瓣狭窄",[["A","心尖部抬举性搏动"],["B","心前区抬举性搏动"],["C","心底部抬举性搏动"],["D","胸骨上窝抬举性搏动"],["E","右颈部异常搏动"]],"A","主动脉瓣狭窄患者左心室射血阻力增加，心肌代偿性肥厚，左心室收缩力明显增强，因而可以在心尖部触及抬举性搏动（A对）。心前区抬举性搏动（B错）常见于室间隔缺损患者。室间隔缺损时，出现左向右分流，右心室压力负荷增加，右心室容量增加，右室肥大导致心脏出现顺钟向转位，心前区被占位，出现心前区抬举性搏动。心底部异常搏动（C错）在胸骨左缘者常见于肺动脉高压、肺动脉扩张、或者年轻人情绪激动时，在胸骨右缘者常见于升主动脉扩张及主动脉高压。胸骨上窝抬举性搏动（D错）可见于升主动脉瘤，系因瘤体压迫侵蚀胸骨，因而可在右前胸1、2肋间处有局部隆起并有明显搏动，也可在胸骨上窝触到搏动性肿块。右颈部异常搏动（E错）多为颈动脉异常搏动，见于脉压增大的疾病如主动脉瓣关闭不全、高血压、甲状腺功能亢进症及严重贫血，亦可见于颈动脉瘤。","","N"],["1994-N110",20,"成人常见先天性心血管病","室间隔缺损临床表现",1994,110,"B","","先天性心脏病室间隔缺损",[["A","心尖部抬举性搏动"],["B","心前区抬举性搏动"],["C","心底部抬举性搏动"],["D","胸骨上窝抬举性搏动"],["E","右颈部异常搏动"]],"B","室间隔缺损时，出现左向右分流，右心室压力负荷增加，右室肥大导致心脏出现顺钟向转位，出现心前区饱满及抬举性搏动（B对）。风湿性心脏病主动脉瓣狭窄时，增加左心室后负荷，代偿作用导致左心室肥厚，扩大的左心室触诊可在心尖区可触及收缩期抬举样搏动（A错）。梅毒性心血管病形成升主动脉瘤，升主动脉瘤可压迫侵蚀胸骨，在右前胸1、2肋间处有局部隆起并有明显搏动，也可在胸骨上窝触到搏动性肿块（D错）。在安静状态下，颈动脉出现明显的搏动（E错），见于主动脉瓣关闭不全、高血压、甲状腺功能亢进症及严重贫血病人，右颈部异常搏动与右心功能有关。心底部异常搏动（C错）：①胸骨左缘第2肋间搏动：肺动脉高压，肺动脉扩张，或者年轻人情绪激动时；②胸骨右缘第2肋间搏动：升主动脉扩张，主动脉高压。","","N"],["1994-N111",52,"第二节 急性白血病","ALL缓解后治疗",1994,111,"B","","甲氨蝶呤治疗急性白血病时的主要副作用是",[["A","口腔及其它黏膜溃疡"],["B","过敏反应"],["C","心脏损害"],["D","神经炎"],["E","脱发"]],"A","甲氨蝶呤治疗急性白血病时主要的副作用为黏膜炎（A对），肝肾功能损害。过敏反应（B错）为L-ASP（左旋门冬酰胺酶）的副作用，心脏损害（C错）为柔红霉素的副作用，神经炎（D错）为长春新碱的副作用，脱发（E错）为环磷酰胺的副作用。","","N"],["1994-N112",52,"第二节 急性白血病","ALL诱导缓解治疗",1994,112,"B","","左旋门冬酰胺酶治疗急性白血病时的主要副作用是",[["A","口腔及其它黏膜溃疡"],["B","过敏反应"],["C","心脏损害"],["D","神经炎"],["E","脱发"]],"B","L-ASP（左旋门冬酰胺酶）治疗急性白血病的主要副作用为肝功能损害、胰腺炎、凝血因子及清蛋白合成减少和过敏反应（B对）。口腔及其他黏膜溃疡（A错）为高剂量甲氨喋呤的副作用，心脏损害（C错）为柔红霉素的副作用，神经炎（D错）为长春新碱的副作用，脱发（E错）为环磷酰胺的副作用。","","N"],["1994-N129",42,"","",1994,129,"C","","Ⅰ型（远端）肾小管酸中毒",[["A","氯化铵负荷试验阳性"],["B","代谢性酸中毒伴有严重高血钾"],["C","两者均有"],["D","两者均无"]],"A","Ⅰ型（远端）肾小管酸中毒由远端肾小管酸化功能障碍引起。氯化铵负荷试验可人为地增加远端肾小管排泌H⁺的负荷，故Ⅰ型（远端）肾小管酸中毒时氯化铵负荷试验阳性（A对）。Ⅰ型（远端）肾小管酸中毒时，皮质集合管H⁺-K⁺泵功能减退导致低血钾（B错）。","","N"],["1994-N130",42,"","",1994,130,"C","","Ⅳ型肾小管酸中毒",[["A","氯化铵负荷试验阳性"],["B","代谢性酸中毒伴有严重高血钾"],["C","两者均有"],["D","两者均无"]],"B","Ⅳ型肾小管酸中毒即高血钾型远端肾小管酸中毒，肾小管Na⁺重吸收及H⁺、K⁺排泌受损，导致酸中毒及高钾血症（B对）。Ⅳ型肾小管酸中毒时，血清醛固酮水平降低，确诊方法为醛固酮浓度测定，而氯化铵负荷试验（A错）是Ⅰ型（远端）肾小管酸中毒的检查方法。","","N"],["1994-N131",35,"第一节 肝硬化","肝功能减退",1994,131,"C","","肝细胞性黄疸",[["A","血清总胆红素增高、非结合胆红素增高"],["B","血清总胆红素增高、结合胆红素增高"],["C","两者均有"],["D","两者均无"]],"C","肝细胞性黄疸是由于肝细胞损伤，对胆红素摄取和结合功能发生障碍，以致非结合胆红素（UCB）无法被肝细胞摄取、结合而转变为结合胆红素，因此大量非结合胆红素潴留于血中，导致血清非结合胆红素升高（A对）。而未受损的肝细胞仍能将部分非结合胆红素转变为结合胆红素，因肝细胞肿胀、炎性细胞浸润压迫毛细胆管及胆小管，加上胆栓阻塞致使结合胆红素（CB）排泄受阻而反流入血，因此血清结合胆红素增高（B对）。由于血清非结合胆红素和结合胆红素均升高，故血清总胆红素升高。本题AB均对，正确答案为C。","","N"],["1994-N132",25,"","",1994,132,"C","","Gilbert综合征",[["A","血清总胆红素增高、非结合胆红素增高"],["B","血清总胆红素增高、结合胆红素增高"],["C","两者均有"],["D","两者均无"]],"A","Gilbert综合征又称为体质性肝功能不良性黄疸，一种遗传性非结合胆红素血症，是肝细胞摄取游离胆红素障碍及微粒体内葡萄糖醛酸转移酶不足所致，故既有胆红素摄取障碍（肝细胞摄取游离胆红素障碍），又有胆红素结合障碍（葡萄糖醛酸转移酶不足），故结合胆红素降低（B错）。非结合胆红素转化为结合胆红素受阻，表现为血清总胆红素增高、非结合胆红素增高（A对）。","","N"],["1994-N133",13,"第二节 急性呼吸衰竭","急性呼吸衰竭动脉血气分析",1994,133,"C","","呼吸衰竭",[["A","pH值下降"],["B","PaO₂下降"],["C","两者均有"],["D","两者均无"]],"C","呼吸衰竭时，PaO₂下降（B对），引起低氧血症，缺氧导致酸性代谢产物增加，pH值下降（A对）。当伴有二氧化碳潴留时，pH值下降会更明显。因此呼吸衰竭时pH值下降、PaO₂下降均可出现。本题AB均对，正确答案为C。","","N"],["1994-N134",45,"第一节 慢性肾衰竭","水、电解质代谢紊乱",1994,134,"C","","肾功能衰竭",[["A","pH值下降"],["B","PaO₂下降"],["C","两者均有"],["D","两者均无"]],"A","肾衰竭时，肾小管排酸功能受损，各种酸性代谢产物体内蓄积（代酸）导致pH下降（A对），当肺通气和换气功能正常时，体内氧分压也正常，所以肾衰竭时不会出现PaO₂下降（B错）。","","N"],["1994-N151",60,"第一节 库欣综合征","库欣综合征鉴别诊断",1994,151,"X","","单纯性肥胖与皮质醇增多症的鉴别，下列哪些检查有意义",[["A","尿17-羟，17-酮"],["B","皮质醇昼夜节律"],["C","地塞米松抑制试验"],["D","血ACTH测定"]],"BC","单纯性肥胖患者血皮质醇昼夜变化节律正常；而皮质醇增多症患者皮质醇分泌增多，失去昼夜分泌节律。故皮质醇昼夜节律可作为二者鉴别的依据（B对）。单纯性肥胖（肥胖症）受下丘脑-垂体-肾上腺轴的负反馈调节，能被小剂量地塞米松抑制；而皮质醇增多症负反馈机制失灵，不能被小剂量地塞米松抑制。故地塞米松抑制试验可作为二者鉴别的依据（C对）。单纯性肥胖和皮质醇增多症尿17-羟与尿17-酮均增高，且易受其他因素影响，故尿17-羟与尿17-酮不能作为二者鉴别的依据（A错），用于鉴别皮质醇增多症及单纯性肥胖者测定的是尿游离皮质醇，原因是它能反映血中游离皮质醇水平，且少受其他色素干扰。单纯性肥胖患者因为体内皮质醇增多，引起ACTH降低；皮质醇增多症患者血ACTH增高或正常（ACTH依赖型），甚至降低（非ACTH依赖型）。故血ACTH测定不作为二者鉴别的依据（D错），血ACTH测定主要用于库欣综合征病因的鉴别和肿瘤的定位。","","N"],["1994-N152",40,"第五节 肾病综合征","肾病综合征病因",1994,152,"X","","引起原发性肾病综合征的常见肾小球疾病有",[["A","膜性肾炎"],["B","膜增殖性肾炎"],["C","IgA肾病"],["D","急进性肾炎"]],"AB","肾病综合征的主要病理类型包括微小病变型肾病、局灶节段性肾小球硬化、膜性肾病（A对）、系膜增生性肾小球肾炎、系膜毛细血管性肾小球肾炎（即膜增生型肾炎）（B对）等。多数IgA肾病（C错）的临床表现主要为血尿，伴或不伴轻度蛋白尿，无水肿、高血压和肾功能减退。虽然部分IgA肾病可出现肾病综合征，国内IgA肾病表现为肾病综合征者显著高于国外，但仅约10%～20%，加之IgA肾病仅占原发性肾小球疾病的20%～50%，是我国最常见的肾小球疾病（十版内科学P478），有些病人可表现为肾病综合征（十版内科学P479），因此一般不把IgA肾病作为引起原发性肾病综合征的常见肾小球疾病。本题若无“常见”二字，答案即为ABC。急进性肾炎（D错）主要表现为肾炎综合征及早期少尿性肾功能减退，无肾病综合征表现。","","N"],["1994-N153",47,"第一节 缺铁性贫血","补铁治疗",1994,153,"X","","在缺铁性贫血的防治中，下列哪些是错误的",[["A","维生素C能促进食物中铁的吸收"],["B","稀盐酸能促进亚铁的吸收"],["C","诊断性治疗时最好用注射铁剂"],["D","血红蛋白正常后应继续用铁剂1～2个月"]],"CD","维生素C是还原剂，可将食物中的三价铁还原为二价铁，以促进食物中铁的吸收（A对）。现在无论是九版内科学还是九版生理学P203均认为稀盐酸（胃酸）促进铁的吸收，因此B选项为正确说法。铁剂诊断性治疗首选口服铁剂，只有在口服铁剂不能耐受或胃肠道吸收障碍时，才使用注射铁剂（C错，为本题正确答案）。铁剂治疗应在血红蛋白恢复正常后持续4～6个月（D错，为本题正确答案），待铁蛋白正常后停药。","","N"],["1994-N154",29,"第二节 结核性腹膜炎","结核性腹膜炎诊断",1994,154,"X","","对发热、腹痛、血性腹水的患者应考虑",[["A","结核性腹膜炎"],["B","门静脉血栓形成"],["C","胰源性腹水"],["D","门脉性肝硬化"]],"ABC","结核性腹膜炎（A对）结核毒血症常见，主要是低热与中等热，早期腹痛不明显，以后可出现持续性隐痛或钝痛，腹水多为草黄色渗出液，少数为浑浊或淡血性。门静脉血栓形成（B对）表现为中、重度腹胀痛或突发剧烈腹痛，合并有肠坏死时，可有发热、血性腹水。胰源性腹水（C对）多由胰腺肿瘤、胰腺外伤或胰腺炎引起胰腺外伤或胰腺炎引起，为渗出性腹水，常合并有胰腺和胰周组织广泛充血、水肿甚至出血、坏死，可有发热、腹痛、血性腹水。门脉性肝硬化（D错）未合并感染时，腹水常呈漏出性，而非血性，无腹痛，因肝脏对致热因子等灭活降低，可出现不规则低热（十版内科学P418）。","","N"],["1994-N155",13,"第一节 呼吸衰竭概述","呼吸衰竭病因",1994,155,"X","","预期下列哪些病人的动脉血气检查报告为PaO₂40mmHg、PaCO₂70mmHg、pH7.20",[["A","重症肌无力"],["B","弥漫性肺间质纤维化"],["C","安眠药、麻醉药过量"],["D","急性左心功能不全"]],"AC","动脉血气检查结果为PaO₂40mmHg＜60mmHg、PaCO₂70mmHg＞50mmHg，应诊断为Ⅱ型呼吸衰竭，其为肺泡通气不足所致。pH＜7.35说明合并有失代偿性酸中毒。重症肌无力（A对）可导致呼吸肌无力，安眠药或麻醉药过量（C对）可抑制呼吸中枢，均可引起肺泡通气功能不足，导致PaO₂降低及CO₂潴留，由于CO₂潴留，大量酸性物质堆积体内，可引起代酸，加之通气不足所致的呼酸，使pH明显降低；弥漫性肺间质纤维化（十版内科学P100）（B错）以限制性通气功能障碍和气体交换障碍为特征，表现为肺容量减少和低氧血症，但由于气道阻力不大，很少发生通气功能不足及CO₂潴留；急性左心衰（十版内科学P186）（D错）呼吸频率通常每分钟高达30～40次，一般不引起CO₂潴留。","","N"],["1994-N156",21,"第二节 主动脉瓣反流","主动脉瓣反流临床表现",1994,156,"X","","下列哪些情况下可在心尖部听到舒张期杂音",[["A","缩窄性心包炎"],["B","二尖瓣狭窄"],["C","重度二尖瓣关闭不全"],["D","主动脉瓣关闭不全"]],"ABCD","缩窄性心包炎（A对）一般无杂音，但如缩窄部位发生在左侧房室间沟时，可导致二尖瓣环受压而使二尖瓣开放受阻，产生心尖部舒张期杂音。二尖瓣狭窄（B对）特征性的杂音为心尖区舒张中晚期低调的隆隆样杂音，呈递增型，局限，左侧卧位明显，运动或用力呼气可使其增强，常伴舒张期震颤。重度二尖瓣关闭不全时（C对），由于严重反流，舒张期大量血液通过二尖瓣口，导致相对性二尖瓣狭窄，故心尖区可闻及短促的舒张中期隆隆样杂音。主动脉瓣关闭不全（D对）的反流明显者，常在心尖区闻及柔和低调的隆隆样舒张期杂音（Austin-Flint杂音）。","","N"],["1995-N46",13,"第三节 慢性呼吸衰竭","氧疗",1995,46,"A","","慢性支气管炎、肺气肿患者，血气分析结果为：pH7.38，PaCO₂81mmHg，给予吸氧后，PaO₂维持多少较为合适",[["A","95mmHg"],["B","85mmHg"],["C","65mmHg"],["D","50mmHg"],["E","35mmHg"]],"C","慢性支气管炎、肺气肿患者，PaCO₂81mmHg＞50mmHg，伴有明显CO₂潴留，治疗时宜采用低浓度（＜35%）持续吸氧，控制PaO₂于60mmHg（C对）或SaO₂于90%或略高。慢性呼吸衰竭伴有明显CO₂潴留时，呼吸中枢的化学感受器对CO₂反应性差，呼吸主要依靠低氧对颈动脉体、主动脉体化学感受器的刺激来维持。PaO₂过高会解除低氧对外周化学感受器的刺激，便会抑制患者呼吸，造成通气状态进一步恶化。","","N"],["1995-N47",10,"第三节 慢性肺源性心脏病","肺动脉高压的形成",1995,47,"A","","慢性肺源性心脏病发病的主要因素，下列哪项不正确",[["A","肺血管阻力增加"],["B","气道梗阻"],["C","肺动脉高压"],["D","低氧血症及高碳酸血症"],["E","血黏度增加"]],"B","肺源性心脏病（简称肺心病）主要是由于支气管-肺组织、胸廓或肺动脉血管病变所致肺血管阻力增加（A对），产生肺动脉高压（C对），加重心脏负荷，引起右心室结构和功能改变的疾病。肺动脉高压是肺心病形成的重要环节，凡能引起持续性肺动脉高压的因素都可最终导致肺心病。肺动脉高压形成的因素有：（1）肺血管阻力增加的功能性因素：缺氧、高碳酸血症、呼吸性酸中毒。低氧血症及高碳酸血症（D对）可以使肺血管收缩、痉挛，其中缺氧是肺动脉高压形成最重要的因素，缺氧可使缩血管活性物质增多，还可使平滑肌细胞膜通透性增加，细胞内Ca²⁺增加，肺血管平滑肌收缩增强，肺血管阻力增加；高碳酸血症、呼吸性酸中毒时H⁺产生过多，使血管对缺氧的敏感性增强，致肺动脉高压。（2）肺血管阻力增加的解剖学因素：①长期反复发作的慢阻肺及支气管周围炎累及肺小动脉，导致肺血管阻力增加；②肺气肿导致肺泡腔内压增加，压迫肺泡周围毛细血管床，使肺循环阻力增加；③慢性缺氧导致肺血管重塑；④部分患者慢性肺心病急性发作期发生多发性肺微小动脉原位血栓形成。（3）血液黏稠度增加（E对）和血容量增多也可加重肺动脉高压。气道梗阻（B错，为本题正确答案）不是慢性肺源性心脏病发病的主要因素。","","N"],["1995-N48",41,"第一节 尿路感染","慢性肾盂肾炎的诊断",1995,48,"A","","诊断慢性肾盂肾炎时，下列哪项是不正确的",[["A","静脉肾盂造影中可见到肾盂肾盏变形缩窄"],["B","必有尿路刺激（尿急、尿频、尿痛）症状"],["C","无全身症状，只有尿培养反复多次阳性"],["D","肾小管功能可持续损害"],["E","可有高血压、水肿、肾功能减退"]],"B","慢性肾盂肾炎的诊断除反复发作尿路感染病史之外（超过半年），尚需结合影像学及肾脏功能检测：①肾外形凹凸不平，且双肾大小不等；②静脉肾盂造影可见肾盂、肾盏变形，缩窄（A对）；③持续性肾小管功能损害（D对）。具备上述第①、②条的任何一项再加第③条可诊断慢性肾盂肾炎。慢性肾盂肾炎临床表现较复杂，可无全身症状及泌尿系统局部症状，只有尿培养反复多次阳性（C对），即不一定出现尿路刺激（尿急、尿频、尿痛）症状（B错，为本题正确答案）。慢性肾盂肾炎反复迁延不愈，可损伤肾实质，引起肾功能减退，出现水肿及高血压（E对）。","","N"],["1995-N49",39,"","",1995,49,"A","","关于蛋白尿，下列哪一项是错误的",[["A","大、中、小分子均有的蛋白尿，见于肾小球肾炎"],["B","微量的蛋白尿，见于早期糖尿病肾病"],["C","凝溶蛋白尿，见于多发性骨髓瘤"],["D","肾组织性蛋白尿多为小分子蛋白尿"],["E","β₂-微球蛋白尿为微小病变型肾病的特征"]],"E","β₂-微球蛋白尿见于肾小管结构或功能受损时，肾小管对包括β₂-微球蛋白尿等正常滤过的小分子量蛋白质重吸收障碍，导致蛋白质从尿中排出，而微小病变型肾病的主要病理改变为肾小球脏层上皮细胞足突融合，其蛋白尿为以白蛋白为主的选择性蛋白尿。因此β₂-微球蛋白尿不是微小病变型肾病的特征（E错，为本题正确答案）。肾小球肾炎时，若滤过膜损害严重，其滤过屏障作用减退，可出现大、中、小分子均有的蛋白尿（A对）。糖尿病肾病早期，滤过膜损伤轻微，可出现持续微量白蛋白尿，持续在20～200μg/min（B对）。凝溶蛋白尿为溢出性蛋白尿，且多为小分子蛋白尿，见于多发性骨髓瘤（C对）。肾组织性蛋白尿多为小分子蛋白尿（D对），是由于肾组织被破坏或肾小管分泌蛋白增多所致的蛋白尿。","","N"],["1995-N50",61,"第二节 糖尿病酮症酸中毒","脑水肿",1995,50,"A","","25岁，男性，胰岛素依赖型糖尿病患者，2天前中断胰岛素后出现昏迷，血糖420mg／dl（23mmol／L），经抢救并静脉滴注碳酸氢钠后血糖下降，神志好转，酸中毒减轻，但不久又进入昏迷，其最可能的原因是",[["A","并发脑水肿"],["B","并发低血糖"],["C","并发脑血管意外"],["D","并发乳酸酸中毒"],["E","并发肾功能衰竭"]],"A","该患者为青年男性，属胰岛素依赖型糖尿病，中断胰岛素注射后出现昏迷，血糖23mmol/L（酮症酸中毒血糖一般为16.7～33.3mmol/L；高渗高血糖综合征血糖一般≥33.3mmol/L），提示该患者很有可能并发糖尿病酮症酸中毒（DKA）。DKA常见的并发症有休克、严重感染、心力衰竭、肾衰竭、脑水肿等。其中脑水肿常与脑缺氧、补碱或补液不当、血糖下降过快等有关。如经治疗后，血糖有所下降，酸中毒改善，但昏迷反而加重，应警惕脑水肿的可能。本例患者经抢救并静脉滴注碳酸氢钠后血糖下降，神志好转，酸中毒减轻，但不久又进入昏迷。故最可能的原因是并发脑水肿（A对）。并发低血糖（B错）、并发脑血管意外（C错）虽也可表现为昏迷，但DKA抢救过程中均很少见，且本例并无相关检查支持，暂不考虑。并发乳酸酸中毒（D错）虽也可表现为昏迷，但为口服双胍类降糖药的常见不良反应（十版内科学P736）。并发肾功能衰竭（E错）虽为DKA常见并发症，但是一般无昏迷表现，且本例无肾功能减退相关临床表现（如少尿）和实验室检查（如血肌酐升高）支持，暂不考虑。","","N"],["1995-N51",23,"第一节 感染性心内膜炎","周围体征",1995,51,"A","","感染性心内膜炎不出现下列哪项体征",[["A","杵状指"],["B","Osler结"],["C","Roth点"],["D","Janeways结"],["E","Duroziez征"]],"E","Duroziez征指用听诊器的钟型体件稍加压力于股动脉可闻及收缩期与舒张期双期吹风样杂音，常见于主动脉瓣关闭不全、甲状腺功能亢进症等引起脉压增大的疾病（E对）。杵状指发病机理尚不清楚，一般认为与动脉血氧量不足及血流增快等主要因素有关，亚急性心内膜炎患者约1/3有杵状指（A错）。Osler结（B错）主要源自体内免疫复合物的沉积，从而引发机体产生免疫反应，局部形成水肿、炎性红肿，并刺激末梢痛觉神经，产生一定的疼痛感。多存在于一些慢性（或亚急性）感染性心内膜炎中。Roth点（C错）是指亚急性感染性心内膜炎时，由于毒素和（或）免疫复合物的作用，微小血管壁受损，发生漏出性出血。Janeways结（D错）在亚急性感染性心内膜炎罕见，多见于急性感染性心内膜炎，约1～4mm，手掌和足底出现的红色或出血性的皮肤斑（损害），无压痛，为毛细血管出血或微栓塞的表现。","","N"],["1995-N52",15,"第二节 慢性心力衰竭","洋地黄类药物",1995,52,"A","","高血钾可使下列哪项洋地黄所致的心律失常加重",[["A","室性期前收缩、二联律"],["B","心室率快的心房纤颤"],["C","非阵发性交界性心动过速"],["D","完全性心脏传导阻滞"],["E","室性心动过速"]],"D","心律失常是洋地黄中毒的常见临床表现，凡洋地黄中毒所致的房性或室性心律失常，如阵发性房性心动过速或不伴有房室传导阻滞，多源性室性过早搏动或室性过早搏动形成二联律等，皆可应用钾盐进行治疗。故高血钾对洋地黄所致的室性期前收缩、二联律（A错）、心室率快的心房纤颤（B错）、非阵发性交界性心动过速（C错）、室性心动过速（E错）均无明显不良影响。但高血钾可导致心肌收缩力降低、心律失常、心率减慢、房室传导阻滞，加重洋地黄所致的心脏传导阻滞，因此洋地黄中毒伴完全性心脏传导阻滞（D对）者禁用钾盐。","","N"],["1995-N53",21,"第三节 二尖瓣狭窄","二尖瓣狭窄鉴别诊断",1995,53,"A","","下列哪项表现提示左房粘液瘤而非风湿性二尖瓣狭窄",[["A","肺动脉瓣第二心音亢进"],["B","心房纤颤"],["C","迟晚发生的开瓣音"],["D","左心房扩大"],["E","二尖瓣区舒张晚期杂音增强"]],"C","左心房黏液瘤瘤体下移可使二狭加重，开瓣音推迟（C对），发生在舒张中晚期。当二尖瓣严重狭窄、瓣膜钙化或伴有明显二尖瓣关闭不全，则开瓣音可消失。两者病情发展到晚期，均可出现左心房扩大（D错）后导致的肺动脉高压而引起肺动脉瓣第二心音亢进（A错）和二尖瓣区舒张晚期杂音增强（E错）。心房纤颤（B错）多见于风湿性二尖瓣狭窄。","","N"],["1995-N54",17,"第四节 急性冠状综合征","心脏破裂",1995,54,"A","","关于急性心肌梗塞并发心脏破裂，下列哪项不正确",[["A","多见于起病一周以内"],["B","可累及右心室"],["C","心内膜下心梗不易发生"],["D","心动过缓"],["E","多为室间隔破裂穿孔"]],"E","急性心梗并发心脏破裂少见，多为心室游离壁破裂，造成心包积血引起急性心脏压塞而猝死。偶为心室间隔破裂穿孔（E错，为本题正确答案），在胸骨左缘第3～4肋间出现响亮的收缩期杂音，常伴有震颤，可引起心力衰竭和休克而在数日内死亡。常在起病1周内出现（A对），可累及右心室（B对），心内膜下心梗不易发生心脏破裂（C对）。发生心脏破裂时，可出现心动过缓（D对）。心脏破裂也可为亚急性，患者可存活数月。","","N"],["1995-N55",15,"第二节 慢性心力衰竭","左心衰竭症状",1995,55,"A","","夜间阵发性呼吸困难发生的机理与下列哪项关系不大",[["A","静脉回流增加"],["B","膈肌上升"],["C","肺活量减少"],["D","迷走神经张力增高"],["E","外周小动脉扩张"]],"E","外周小动脉为毛细血管前阻力血管，外周小动脉扩张（E错，为本题正确答案）时，外周阻力下降，左心室后负荷降低，左心室泵血量增加，心室舒张末期压力降低，进而在一定程度上减轻肺淤血，可使呼吸困难症状得到缓解。夜间阵发性呼吸困难的发生机理包括：平卧时血液重新分配使静脉回流量增加（A对），加重肺淤血，夜间迷走神经张力增加（D对）、小支气管收缩、横膈抬高（B对）、肺活量减少（C对）。","","N"],["1995-N56",15,"第二节 慢性心力衰竭","左心衰竭症状",1995,56,"A","","下列哪项指标不符合心功能不全的表现",[["A","肺毛细血管楔压＞2.4KPa"],["B","中心静脉压＞1.8KPa"],["C","左心室舒张末压＜1.6KPa"],["D","左心室射血分数＜40%"],["E","心脏指数＜2.0L/（min•m²）"]],"C","肺毛细血管楔压，现称为肺小动脉楔压（PCWP）正常值6～12mmHg（0.8～1.6kPa），左心衰时PCWP增高大于2.0kPa以上（A对）。中心静脉压（CVP）正常值6～12cmH₂O（0.49～0.98kPa），右心衰时增高（B对）。左心室舒张末压（LVEDP）正常值6～12mmHg（0.8～1.6kPa），舒张性心衰时增高，大于1.6kPa（C错，为本题正确答案）。左心室射血分数（LVEF）正常值＞50%，收缩期心衰的诊断标准为LVEF≤40%（D对）。心脏指数（心排指数、CI）正常值＞2.5L/（min·m²），左心衰时降低（E对）。","","N"],["1995-N57",18,"第一节 原发性高血压","老年高血压",1995,57,"A","","关于老年人高血压脑病的特点，下列哪项不符合",[["A","血压波动小"],["B","容易发生心功能不全"],["C","容易出现体位性低血压"],["D","压力感受器调节血压敏感性减退"],["E","以收缩压增高为主"]],"A","一般认为，老年人高血压指年龄超过60岁的高血压。老年人常合并动脉硬化，血管弹性贮血作用降低，且压力感受器调节血压敏感性减退（D对），因此血压波动性大（A错，为本题正确答案），容易出现体位性低血压（C对）（体位性低血压又叫直立性脱虚，是由于体位的改变引起的低血压。通常认为，站立后收缩压较平卧位时下降20mmHg或舒张压下降10mmHg，即为体位性低血压）。老年人高血压常伴心脏、肾脏及脑等器官不同程度损害，较易发生心功能不全（B对）。老年人血管弹性下降，心室收缩期大动脉不能相应扩张，导致收缩压明显升高，而心室舒张期则因动脉弹性回缩能力下降，导致舒张压降低，因此老年人高血压以收缩压增高为主（E对）。","","N"],["1995-N58",2,"第一节 支气管哮喘","通气功能检查",1995,58,"A","","支气管哮喘的肺功能异常，主要表现在",[["A","肺活量减少"],["B","最大通气量增加"],["C","第一秒钟用力呼气容积减少"],["D","弥散量下降"],["E","功能残气减少"]],"C","哮喘发作时呈呼气性呼吸困难，属阻塞性通气功能障碍，其肺功能测定结果主要表现为流速降低，1秒用力呼气容积（FEV₁）、1秒率（FEV₁/FVC%）以及最高呼气流量（PEF）均下降，可有用力肺活量（FVC）正常或下降、残气量及残气量与肺总量的比值增加。其中FEV₁/FVC%＜70%或FEV₁低于正常预计值的80%为判断气流受限的最重要指标，所以肺功能异常主要表现在第一秒钟用力呼气容积减少（C对）。肺活量反映一次通气的最大能力，是肺功能测定的常用指标，由于测定肺活量不用限制呼气的时间，在某些肺组织弹性降低或呼吸道狭窄的病人，虽然通气功能损害，但延长通气时间时肺活量仍可以正常，所以测定肺活量不具有特异性（A错）。最大通气量是指单位时间内所能呼吸的最大气量，其生理意义与时间肺活量相同，哮喘发作时患者呈呼气性呼吸困难，所以功能残气量（余气量和补呼气量之和）会增加（E错），最大通气量会下降（B错）。弥散量是肺换气功能的指标，哮喘发作时呈阻塞性通气功能障碍（D错），弥散量正常。","","N"],["1995-N59",27,"第二节 慢性胃炎","慢性胃炎对症治疗",1995,59,"A","","患有幽门螺杆菌相关性胃炎的病人，给予哪种抗生素最为宜",[["A","四环素"],["B","红霉素"],["C","庆大霉素"],["D","先锋霉素Ⅳ"],["E","羟氨苄青霉素"]],"E","有幽门螺杆菌相关性胃炎的病人，根除Hp常用的联合方案有：1种PPI+2种抗生素和1种铋剂，常用的能根治幽门螺杆菌的抗生素包括阿莫西林（羟氨苄青霉素）（E对）、甲硝唑、呋喃唑酮、克拉霉素（甲红霉素）。四环素（A错）对幽门螺杆菌相关性胃炎的治疗也有较好的效果，在患者对青霉素过敏的时使用，但不是最好的；红霉素（B错）抗菌谱与青霉素相似，且对支原体，衣原体，立克次体等及军团菌有抗菌作用，但是幽门螺杆菌对红霉素类药物（新型红霉素类克拉霉素除外）不敏感；庆大霉素（C错）适用于绿脓杆菌、变形杆菌（吲哚阳性和阴性）、大肠杆菌、克雷伯菌属、肠杆菌属、沙雷菌属、枸橼酸杆菌属以及葡萄球菌，但其对幽门螺杆菌效果不好，且此类药物不良反应较多，目前应用较为局限；先锋霉素Ⅳ（D错）对金黄色葡萄球菌（包括耐青霉素G菌株）、溶血性链球菌、肺炎球菌、大肠杆菌、奇异变形杆菌、克雷伯杆菌（肺炎杆菌）、流感嗜血杆菌、卡他球菌等有抗菌作用，但不覆盖幽门螺杆菌。","","N"],["1995-N60",29,"第一节 肠结核","肠结核治疗",1995,60,"A","","在肠结核的治疗中，下列哪一项不正确",[["A","为使病人早日康复，防止耐药性的产生，目前多采用长程抗结核治疗"],["B","一般用异烟肼与利福平两种杀菌药联合"],["C","开始治疗1～2周即有症状改善"],["D","腹痛可用抗胆碱能药物"],["E","伴完全肠梗阻者应手术治疗"]],"A","肠结核治疗的目的是消除症状、改善全身情况、促进病灶愈合、防治并发症（十版内科学P384）。（1）抗结核化学药物治疗：结核病的化疗原则为早期、联合、适量、规律、全程使用敏感药物；为减少结核杆菌耐药的发生，现多采用短程化疗6～9个月，而不再采用长程抗结核治疗（A错，为本题正确答案）；异烟肼和利福平两种杀菌剂联合给药可提高疗效，减少耐药菌株的产生（B对）；使用抗结核药1～2周后，结核病症状开始改善（C对）。（2）对症治疗：腹痛者可给予抗胆碱能药物对症治疗，以缓解疼痛（D对）。（3）手术治疗：肠梗阻是肠结核的常见并发症之一，一般采用保守治疗，但是在出现不能控制的大出血、完全性梗阻时应考虑手术治疗（E对）。","","N"],["1995-N61",36,"第一节 原发性肝癌","原发性肝癌转移途径",1995,61,"A","","关于原发性肝癌的转移，下列哪项提法不正确",[["A","肝内血行转移发生最早，也最常见"],["B","容易侵犯门静脉分支形成癌栓"],["C","肝外血行转移中，转移至肺的几率达半数"],["D","经淋巴转移至肝门淋巴结的最多"],["E","种植转移常见"]],"E","原发性肝癌主要有两个转移途径：肝内转移和肝外转移。肝脏受门静脉和肝动脉双重供血，血流丰富，原发性肝癌最早发生同时也是最常见的转移方式为肝内血行转移（A对），原发性肝癌容易侵犯门静脉分支，形成癌栓（B对）。肝外转移又可分为：1、血行转移：肝外血行转移最常转移至肺（约50%）（C对）；2、淋巴转移：经淋巴转移至肝门淋巴结的最多（D对）；3、种植转移：种植转移比较少见（E错，为本题正确答案）。","","N"],["1995-N62",61,"第一节 糖尿病","糖尿病肾脏病",1995,62,"A","","糖尿病性肾脏病变的特点是",[["A","与病程长短无关，只与糖尿病类型有关"],["B","蛋白尿较轻微，而主要表现为肾功能衰竭"],["C","尿中最先出现M蛋白及β₂微球蛋白"],["D","常发生坏死性乳头炎"],["E","与糖尿病病程有关，可有大量蛋白尿、水肿、血浆蛋白下降，早期可为间歇性蛋白尿"]],"E","糖尿病肾病常见于病史超过10年的患者，与病程长短有关（A错）。早期表现为蛋白尿，从间歇性蛋白尿逐渐发展为持续性蛋白尿，晚期表现为大量蛋白尿、水肿、血浆蛋白下降、肾功能衰竭（E对B错）。糖尿病肾病早期有肾小管功能改变，尿β₂微球蛋白升高，而M蛋白多见于多发性骨髓瘤、巨球蛋白血症及恶性淋巴瘤（C错）。糖尿病肾病国内坏死性乳头炎少见（D错），坏死性乳头炎常见于肾内髓区缺血或严重感染。","","N"],["1995-N63",11,"第一节 胸腔积液","结核性胸膜炎",1995,63,"A","","关于结核性胸膜炎，下列哪项正确",[["A","是人体处于高敏状态时发生的渗出性病变"],["B","肺内无结核病灶"],["C","多见于中年人"],["D","胸腔活检无干酪灶"],["E","不能加用糖皮质激素"]],"A","结核性胸膜炎是肺部结核炎症累及胸膜时引起的胸膜炎症，肺内多存在结核病灶（B错），多见于青壮年（C错）。结核性胸膜炎和浸润性肺结核一样，均为迟发型变态反应，是人体处于高敏状态下发生的渗出性病变（A对）。结核性胸膜炎患者胸膜活检阳性率达60%～80%（D错）。糖皮质激素（E错）可以用于治疗结核性胸膜炎，但仅用于结核中毒症状严重者，且必须确保在有效抗结核药物治疗的情况下使用。","","N"],["1995-N64",4,"第二节细菌性肺炎","肺炎链球菌肺炎发病机制",1995,64,"A","","不易引起空洞的肺炎是",[["A","肺炎链球菌肺炎"],["B","金黄色葡萄球菌肺炎"],["C","克雷伯杆菌肺炎"],["D","大肠杆菌肺炎"],["E","梭形杆菌肺炎"]],"A","肺炎链球菌不产生毒素，不引起组织坏死或形成空洞，其致病力是由于高分子多糖体的荚膜对组织的侵袭作用，表现为肺泡水肿和细胞渗出（A对）。金黄色葡萄球菌肺炎（十版内科学P53）（B错）X线表现为肺叶或小叶浸润，早期空洞，脓胸，可见液气囊腔；克雷伯杆菌肺炎（十版内科学P49）（C错）X线表现为肺叶或肺段实变，蜂窝状脓肿，叶间隙下坠；大肠杆菌肺炎（十版内科学P49）（D错）表现为发热、脓痰、呼吸困难，可出现脓胸；梭形杆菌（E错）为革兰阴性无芽胞厌氧杆菌，其导致的肺炎表现为咳嗽、咳臭脓痰，可出现肺脓肿和脓胸等，可见BCDE都可引起肺组织的坏死性病变易形成空洞。","","N"],["1995-N65",4,"第二节细菌性肺炎","抗菌药物治疗",1995,65,"A","","男性，24岁，高热三天，咳嗽，咳铁锈色痰，血白细胞增高，胸片呈右上叶片状阴影，抗生素首选",[["A","青霉素"],["B","青霉素+链霉素"],["C","青霉素+庆大霉素"],["D","先锋V"],["E","先锋V+丁胺卡那霉素"]],"A","患者高热、咳嗽，咳铁锈色痰，胸片示右上叶片状阴影，应诊断为肺炎链球菌肺炎。对于肺炎链球菌肺炎的治疗，目前临床上首选青霉素（A对），对青霉素过敏者，或感染耐青霉素菌株者，用呼吸氟喹诺酮类、头孢噻肟或头孢曲松等药物，感染多重耐药菌（MDR）菌株者可用万古霉素、替考拉宁或利奈唑胺。先锋V又称头孢唑林，为第一代头孢菌，不是肺炎链球菌肺炎的抗生素首选药（D错）；链霉素（B错）、庆大霉素（C错）和丁胺卡那霉素（E错）均为氨基糖苷类抗菌药物，对各种需氧革兰阴性杆菌具有强大的抗菌作用，而肺炎链球菌属于革兰阳性球菌（BCE错）。","","N"],["1995-N66",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病病理",1995,66,"A","","关于阻塞性肺气肿，哪一项描述是正确的",[["A","经积极治疗可以痊愈"],["B","其病理改变是不可逆的"],["C","仅限于肺泡弹性减退与膨胀"],["D","α₁-抗胰蛋白酶增加易发生肺气肿"],["E","肺功能改变主要是肺活量减少"]],"B","阻塞性肺气肿主要是由于气道阻塞导致肺部终末细支气管远端气腔出现异常持久的扩张，并伴有肺泡壁和细支气管的破坏，病变并非仅限于肺泡弹性减退与膨胀（十版内科学P25）（C错），肺组织的变化多呈进行性发展，不可逆（十版内科学P25）（B对）。积极治疗可以减慢或者阻止肺组织的进一步破坏，但已损坏的肺组织无法恢复，疾病无法痊愈（A错）。蛋白酶增多或抗蛋白酶不足可导致组织结构破坏，产生肺气肿，α₁-抗胰蛋白酶增加不会发生肺气肿（D错）。阻塞性肺气肿的肺功能改变主要是流速降低、残气量增加，限制性通气障碍的肺功能改变主要是肺活量减少（E错）。","","N"],["1995-N68",52,"第二节 急性白血病","中枢神经系统",1995,68,"A","","下列各种类型急性白血病中，哪一种最常发生中枢神经系统白血病",[["A","急性粒细胞性白血病"],["B","急性单核细胞性白血病"],["C","急性淋巴细胞性白血病"],["D","急性粒单核细胞性白血病"],["E","红白血病"]],"C","急性白血病（AL）根据主要受累的细胞系列可分为急性淋巴细胞白血病（ALL）和急性髓系白血病（AML）。其中AML又分为M₀（急性髓细胞白血病微分化型）、M₁（急性粒细胞白血病未分化型）、M₂（急性粒细胞白血病部分分化型）、M₃（急性早幼粒细胞白血病）、M₄（急性粒-单核细胞白血病）、M₅（急性单核细胞白血病）、M₆（红白血病）和M₇（急性巨核细胞白血病）。其中ALL（C对）最易发生中枢神经系统白血病，可发生于疾病各时期，尤其是治疗后缓解期。一般来说，血脑屏障能阻挡病原生物和其他大分子物质由血循环进入脑组织和脑室。在ALL患者中，ALL细胞能表达的特定的细胞因子与人脑微血管内皮细胞相互作用，这可能与ALL最常发生中枢神经系统浸润有关。急性粒细胞性白血病（A错）易发生粒细胞肉瘤，急性单核细胞性白血病（M₅）（B错）、急性粒-单核细胞性白血病（M₄）（D错）最易发生齿龈肿胀、皮肤蓝灰色斑丘疹等（十版内科学P579）。","","N"],["1995-N69",56,"第二节 原发免疫性血小板减少症","糖皮质激素",1995,69,"A","","关于特发性血小板减少性紫癜的肾上腺皮质激素治疗，下列哪项是错误的",[["A","一般可用强的松1～1.5mg/kg·d"],["B","病情严重者可短期静脉滴注"],["C","妊娠期可以应用"],["D","复发时应用仍有效"],["E","治疗缓解后通常需小剂量维持3～6个月"]],"C","特发性血小板减少性紫癜的激素治疗一般可口服强的松1～1.5mg/kg·d（A对），病情严重者可给予等效地塞米松短期静滴，好转后再改为口服（B对）。待血小板正常或接近正常时逐步减量，维持治疗3～6个月（E对）。有关ITP 激素治疗的相关叙述，八、九版内科学及15版实用内科学均未提及糖皮质激素静脉滴注的用药方式，八、九版教材对使用泼尼松，症状缓解后小剂量维持也无明确说法（十五版实用内科学P1852有提及），同时十版内科学对泼尼松应用维持量的数据有更新（P623）。糖皮质激素只能控制症状，不能纠正病因，故停药后易复发，复发时治疗仍有效（D 对）。糖皮质激素影响胎儿生长发育，故妊娠期不宜应用（C 错，为本题正确答案）。","","N"],["1995-N70",47,"第一节 缺铁性贫血","铁代谢",1995,70,"A","","关于缺铁性贫血，下列哪一项是对的",[["A","血清总铁结合力减低"],["B","血清转铁蛋白饱和度减低"],["C","血清转铁蛋白减低"],["D","红细胞的游离原卟啉减低"],["E","网织红细胞减低"]],"B","转铁蛋白饱和度指与铁结合的转铁蛋白占转铁蛋白总量的百分比。缺铁性贫血时，原料铁减少，与铁结合的转铁蛋白减少，转铁蛋白饱和度降低（B对）。总铁结合力是指每升血清中的转铁蛋白所能结合的最大铁量，缺铁性贫血时，机体转铁蛋白合成增强（C错），血清总铁结合力增高（A错），以增加铁的利用率。在正常机体内，原卟啉与铁结合生成血红素，缺铁性贫血时，原料铁减少，原卟啉只能以游离方式积聚在红细胞内，所以红细胞的游离原卟啉增高（D错）。在缺铁性贫血中，外周血红细胞减少，刺激骨髓代偿性增生，网织红细胞计数多正常或轻度增高（E错）。","","N"],["1995-N71",59,"第一节 甲状腺功能亢进症","甲状腺危象的治疗",1995,71,"A","","甲亢危象的治疗，下列哪组最理想",[["A","丙基硫氧嘧啶+碘剂+普萘洛尔+强的松"],["B","丙基硫氧嘧啶+强的松"],["C","他巴唑+普萘洛尔+强的松"],["D","丙基硫氧嘧啶+普萘洛尔+他巴唑"],["E","碘剂+他巴唑"]],"A","甲状腺危象，是甲状腺毒症急性加重的一个综合征，为甲状腺素过量释放引起暴发性肾上腺素能兴奋现象。大剂量丙基硫氧嘧啶可以减少甲状腺素的生物合成并能抑制外周组织T₄向T₃转换。大剂量碘（复方碘液）能抑制甲状腺激素的释放，还能抑制促甲状腺激素作用。β肾上腺素能受体阻滞剂通过阻断β受体而改善甲亢所致的交感神经激活症状，使体内甲状腺激素作用减弱，此外β受体拮抗剂可抑制T₄向T₃转化。甲亢患者糖皮质激素代谢加速，肾上腺存在潜在的储备功能不足。甲亢危象时糖皮质激素的需要量增加，对有高热或休克者应加用糖皮质激素，可抑制甲状腺素的释放，并抑制外周组织T₄向T₃转换。综上所述，丙基硫氧嘧啶+碘剂+普萘洛尔+强的松（A对）为治疗甲亢危象的最理想组合。","","N"],["1995-N72",28,"第一节 消化性溃疡","胃泌素瘤",1995,72,"A","","下列哪项不符合由胃泌素瘤引起的消化性溃疡",[["A","多发生在球后十二指肠降段和横段，或空肠近端"],["B","常规胃手术后不易复发"],["C","易并发出血、穿孔和梗阻"],["D","基础胃酸分泌过度"],["E","常伴腹泻"]],"B","胃泌素（促胃液素）瘤是胰岛G细胞肿瘤，以高胃酸分泌，血促胃液素水平升高，多发、顽固及不典型部位消化性溃疡及腹泻为特征。肿瘤分泌的大量胃泌素可刺激胃壁细胞增生和大量胃酸分泌，使上消化道经常处于高酸环境下（D对）。本病溃疡易并发出血、穿孔、梗阻（C对），内科常规治疗常无显效。由于致病肿瘤位于胰腺，病变部位在胃，常规胃手术（B错，为本题正确答案）只是切除了病变部位，并没有去除病因，因此溃疡常复发。部分患者可伴有腹泻（E对），这是由于大量胃酸进入小肠，使脂肪酶失活，脂肪消化吸收障碍，导致腹泻。多数溃疡位于十二指肠球部和胃窦小弯侧，其余分布于非典型部位如食管下段、十二指肠球后及空肠等部位（A错）。本题答案应为AB，但参考答案为B。","","N"],["1995-N73",75,"第二节 农药中毒","毒蕈碱样症状",1995,73,"A","","下列哪个不是有机磷中毒时的毒蕈碱样表现",[["A","恶心、呕吐和腹痛、腹泻"],["B","多汗"],["C","肌肉颤动"],["D","瞳孔缩小"],["E","心率减慢"]],"C","正常情況下，体内的乙酰胆碱（ACh）在胆碱酯酶的水解下失活，有机磷农药中毒时胆碱酯酶活性被不可逆性抑制，体内ACh大量蓄积，持续作用于M和N受体出现M样症状和N样症状。毒蕈碱样症状（M样症状）主要为副交感神经过度兴奋的表现（九版生理学P309）：平滑肌痉挛表现有瞳孔缩小（瞳孔括约肌收缩所致）（D对）、恶心、呕吐、腹痛、腹泻（胃肠道平滑肌收缩所致）（A对）；腺体分泌增加表现有多汗（交感节后神经纤维M胆碱能受体兴奋使皮肤小汗腺分泌汗液增加所致）（B对）、流泪、流涎；心脏活动受抑制表现有心率减慢（心脏窦房结细胞膜上M胆碱能受体兴奋使心率减慢）（E对）等。烟碱样症状（N样症状）主要为横纹肌兴奋表现：肌肉颤动（C错，为本题正确答案）。","","N"],["1995-N74",25,"","",1995,74,"A","","下列哪一个是以结合胆红素增高为主的黄疸",[["A","溶血性黄疸"],["B","肝炎后高胆红素血症"],["C","Gilbert综合征"],["D","Crigler-Najjar综合征"],["E","Dubin-Johnson综合征"]],"E","Dubin-johnson综合征（E对）是临床少见的一种遗传性非溶血性高胆红素血症（又称家族性高胆红素血症），因肝细胞的先天性缺陷而对CB（结合型胆红素）排泄发生障碍，致血清结合型胆红素增高而出现黄疸。溶血性黄疸（A错）是由于大量红细胞破坏所形成的大量UCB（非结合胆红素），超过肝细胞摄取、结合与排泌的能力，致血清非结合胆红素增高而出现黄疸。肝炎后胆红素血症（B错）是由病毒性肝炎后胆红素代谢障碍所引起的黄疸，血清结合型胆红素与非结合胆红素均增高，当出现黄疸型肝炎时才出现血清结合型胆红素增高多于非结合胆红素。Gilbert综合征（C错）又称体质型肝功能不良性黄疸，是由于肝细胞摄取游离胆红素障碍及微粒体内葡糖醛酸转移酶不足，致血清中非结合胆红素增高而出现黄疸。Crigler-Najjar综合征（D错）又称先天性葡萄糖醛酸转移酶缺乏症，由于缺乏葡萄糖醛酸转移酶，肝细胞不能将非结合胆红素转变为结合胆红素，出现血清非结合胆红素增高的黄疸。","","N"],["1995-N79",44,"第一节 急性肾损伤","营养支持治疗",1995,79,"A","","急性肾功能衰竭多尿期每日补液量相当于",[["A","每日排出水分量的1/3～1/2"],["B","每日排出水分量的2/3"],["C","每日排出水分量的1/4"],["D","每日排出水分量的1/5"],["E","每日排出的水分量"]],"A","每日排出水量=尿量+经呼吸道失水量+胃肠道失水量+经皮肤失水量。后三者约1000ml，因此急性肾功能衰竭多尿期每日补液量相当于每日排出水分量的1/3～1/2（A对）。","","N"],["1995-N105",50,"第四节 血红蛋白病","珠蛋白生成障碍性贫血",1995,105,"B","","哪一种是溶血性贫血",[["A","再生障碍性贫血"],["B","海洋性贫血"],["C","铁粒幼细胞性贫血"],["D","缺铁性贫血"],["E","慢性疾病贫血"]],"B","红细胞破坏过多所引起的贫血即溶血性贫血。海洋性贫血（B对）是因珠蛋白基因异常而引起的珠蛋白链的合成下降，导致红细胞自身异常，表现为溶血性贫血。再生障碍性贫血（A错）是一种可能由不同病因和机制引起的骨髓造血功能衰竭症，患者的血细胞数量减少但是质量正常，所以红细胞不会遭到破坏，并不会发生溶血。铁粒幼细胞性贫血（十版内科学P551）（C错）是由各种原因导致的铁利用障碍，大量铁无法被红细胞利用而沉积在细胞内（形成环铁粒幼细胞）和细胞外（形成血色病），不会引起溶血。缺铁性贫血（D错）是原料铁缺乏使血红蛋白合成障碍而引起的一类小细胞低色素性贫血，不属于溶血性贫血。慢性疾病贫血（E错）是由于慢性炎症、感染或肿瘤等引起的铁代谢异常性贫血，不属于溶血性贫血。","","N"],["1995-N106",46,"第一节 贫血概述","贫血分类",1995,106,"B","","哪一种是正常红细胞性贫血",[["A","再生障碍性贫血"],["B","海洋性贫血"],["C","铁粒幼细胞性贫血"],["D","缺铁性贫血"],["E","慢性疾病贫血"]],"A","再生障碍性贫血（十版内科学P555）（A对）是不同病因导致的骨髓造血功能衰竭，主要表现为造血功能低下，生成的红细胞数量下降，质量多正常，因此为正常细胞性贫血。海洋性贫血（十版内科学P563）（B错）是因基因异常导致珠蛋白合成障碍所致的溶血性贫血，以溶血、无效红细胞生成及不同程度的小细胞低色素性贫血为特征。铁粒幼细胞性贫血（十版内科学P551）（C错）是各种原因导致的铁利用障碍而引起的贫血，是小细胞低色素性贫血。缺铁性贫血（十版内科学P549）（D错）指原料铁缺乏所致的血红素、血红蛋白合成减少，表现为小细胞低色素性贫血。慢性病性贫血（十版内科学P551）（E错）是由慢性炎症、感染或肿瘤等引起的铁代谢异常性贫血，表现为小细胞低色素性贫血。","","N"],["1995-N109",41,"第一节 尿路感染","尿细菌学检查",1995,109,"B","","粪链球菌引起的尿路感染，有临床诊断意义的最低菌落计数为",[["A","清洁中段尿培养，菌落计数为＜1000个/ml"],["B","清洁中段尿培养，菌落计数为1000个/ml"],["C","清洁中段尿培养，菌落计数为1万个/ml"],["D","清洁中段尿培养，菌落计数为5万个/ml"],["E","清洁中段尿培养，菌落计数为10万个/ml"]],"B","目前不再强调不同菌种的区别，只规定：清洁中段尿细菌定量培养≥10⁵/ml（10万个/ml），且为同一菌种，称为真性菌尿，可确诊尿路感染；尿细菌定量培养10⁴～10⁵/ml，为可疑阳性，需复查；如＜10⁴/ml则可能为污染。革兰阳性菌感染细菌定量培养≥10³/ml（B对），革兰阴性菌感染细菌定量培养≥10⁵/ml为细菌尿。","","N"],["1995-N110",41,"第一节 尿路感染","尿细菌学检查",1995,110,"B","","克雷伯杆菌引起的尿路感染，有临床诊断意义的最低菌落计数为",[["A","清洁中段尿培养，菌落计数为＜1000个/ml"],["B","清洁中段尿培养，菌落计数为1000个/ml"],["C","清洁中段尿培养，菌落计数为1万个/ml"],["D","清洁中段尿培养，菌落计数为5万个/ml"],["E","清洁中段尿培养，菌落计数为10万个/ml"]],"E","清洁中段尿细菌定量培养≥10⁵/ml，且为同一菌种，称为真性菌尿，可确诊尿路感染；尿细菌定量培养10⁴～10⁵/ml，为可疑阳性，需复查；如＜10⁴/ml则可能为污染。革兰阳性菌细菌定量培养≥10³/ml，革兰阴性菌细菌定量培养≥10⁵/ml（E对）为细菌尿。","","N"],["1995-N111",16,"第三节 房性心律失常","控制心室率",1995,111,"B","","风心病二十年，心房纤颤五年，心率152次/分，首选",[["A","起搏器植入"],["B","异丙基肾上腺素"],["C","直流电转复心律"],["D","药物控制心室率"],["E","临床观察心律变化"]],"D","根据房颤分类，该患者“风心病二十年、房颤五年”，为永久性房颤（持续时间＞1年，不能终止或终止后又复发，无转复愿望），心率快（152次/分），应用药物控制心室率即可（D对）。常用的控制心室率药物包括β受体拮抗剂、钙通道阻滞剂或地高辛等对心脏具有负性传导作用的药物。起搏器植入（A错）用于最长RR间歇＞5s或症状显著的心室率较慢的房颤患者。异丙基肾上腺素（B错）为β受体激动剂，用于支气管哮喘，各种原因引起的心脏骤停，房室传导阻滞，休克等。直流电转复心律（C错）包括直流电同步电复律和直流电非同步电除颤，前者用于除心室颤动以外的快速型心律失常，后者用于心室颤动的治疗。患者心率过快，心舒张期过短导致心室充盈受限，心输出量减少，需予以对症处理，不宜单纯临床观察心律变化（E错）。","","N"],["1995-N112",16,"第六节 心脏传导阻滞","房室传导阻滞治疗",1995,112,"B","","急性下壁心肌梗塞，二度Ⅰ型房室传导阻滞，心率56次/分，血压13/8kpa，首选",[["A","起搏器植入"],["B","异丙基肾上腺素"],["C","直流电转复心律"],["D","药物控制心室率"],["E","临床观察心律变化"]],"E","二度Ⅰ型房室传导阻滞，心率接近正常值下限（56次/分），血压13/8kpa（98/60mmHg），一般无临床症状者无需治疗（E对）。起搏器植入（A错）主要用于病态窦房结综合征和高度房室传导阻滞者。异丙基肾上腺素（B错）用于支气管哮喘，各种原因引起的心脏骤停，房室传导阻滞，休克等。直流电转复心律（C错）包括直流电同步电复律和直流电非同步电除颤，前者用于除心室颤动以外的快速型心律失常，后者用于心室颤动的治疗。药物控制心室率（D错）用于快速心室率的各型心律失常。","","N"],["1995-N129",30,"第二节 克罗恩病","腹痛",1995,129,"C","","克罗恩病（Crohn病）",[["A","右下腹痛"],["B","肉芽肿病变"],["C","两者均有"],["D","两者均无"]],"C","克罗恩病是一种原因不明的慢性炎性肉芽肿性疾病（B对）。克罗恩病在整个胃肠道的任何部位均可发生，但好发于末端回肠和右半结肠，所以腹痛多位于右下腹（A对）或脐周。本题AB均对，正确答案为C。","","N"],["1995-N130",29,"第一节 肠结核","肠结核诊断",1995,130,"C","","肠结核",[["A","右下腹痛"],["B","肉芽肿病变"],["C","两者均有"],["D","两者均无"]],"C","肠结核好发于回盲部，故腹痛多位于右下腹（A对）或脐周（十版内科学P383），而增生型肠结核的病理表现主要为肉芽肿性病变（B对）。本题AB均对，正确答案为C。","","N"],["1995-N131",61,"第二节 糖尿病酮症酸中毒","糖尿病酮症酸中毒实验室检查",1995,131,"C","","糖尿病酮中毒",[["A","血糖在17～28mmol／L（300～500mg／dl）"],["B","尿糖及尿酮体强阳性"],["C","两者均有"],["D","两者均无"]],"C","本题考察糖尿病酮症酸中毒的实验室检查。糖尿病酮症酸中毒（DKA）为最常见的糖尿病急症，以高血糖、酮症和酸中毒为主要表现，是胰岛素不足和拮抗胰岛素激素过多共同作用所致的严重代谢紊乱综合征（P745）。糖尿病酮症酸中毒时，血糖明显升高，一般为16.7～33.3mmo1/L（A对），尿糖及尿酮体强阳性（B对）。本题AB均对，正确答案为C。","","N"],["1995-N132",61,"第三节 高渗高血糖综合征","高渗高血糖综合征实验室检查",1995,132,"C","","糖尿病性非酮症高渗性昏迷",[["A","血糖在17～28mmol／L（300～500mg／dl）"],["B","尿糖及尿酮体强阳性"],["C","两者均有"],["D","两者均无"]],"D","糖尿病性非酮症高渗性昏迷（又称高渗高血糖综合征）是糖尿病急性代谢紊乱的一种临床类型，主要表现为严重高血糖、高血浆渗透压、无明显酮症。患者血糖水平多在33.3mmo1/L以上（一般为33.3～66.8mmol/L）（A错），无酮症表现，尿酮体阴性或弱阳性（B错）。本题AB均错，正确答案为D。","","N"],["1995-N133",2,"第一节 支气管哮喘","药物分类和作用特点",1995,133,"C","","色苷酸钠",[["A","抗炎作用"],["B","抑制肥大细胞释放介质"],["C","两者均有"],["D","两者均无"]],"C","色苷酸钠是非糖皮质激素抗炎药物（六版内科学P71）（A对），能稳定肥大细胞膜、抑制介质释放（B对）、降低气道高反应性，预防过敏性哮喘的发作。本题AB均对，正确答案为C。","","N"],["1995-N134",2,"第一节 支气管哮喘","β₂受体激动剂",1995,134,"C","","β₂受体兴奋剂",[["A","抗炎作用"],["B","抑制肥大细胞释放介质"],["C","两者均有"],["D","两者均无"]],"C","β₂受体激动剂治疗哮喘主要是两方面的机制：①激动气道平滑肌的β₂肾上腺素受体，舒张气道平滑肌，使支气管扩张；②激动肥大细胞等细胞膜表面的β₂肾上腺素受体，减少肥大细胞和嗜碱粒细胞脱颗粒和介质的释放，从而起到舒张支气管、缓解哮喘症状的作用（二版八年制内科学P57）。所以β₂受体激动剂具有抗炎作用和抑制肥大细胞释放介质的作用。本题AB均对，正确答案为C。","","N"],["1995-N151",35,"第一节 肝硬化","肝硬化治疗",1995,151,"X","","关于肝硬化的治疗有",[["A","代偿期用高热量、高蛋白及丰富维生素饮食"],["B","同时选用多种保肝药物治疗"],["C","肝硬化并发症治疗"],["D","伴有慢性活动性肝炎者，可试用肾上腺皮质激素治疗"]],"ACD","肝硬化患者，若碳水化合物供能不足，机体将消耗蛋白质供能，加重肝脏蛋白质合成代谢负担，所以代偿期需要高热量、高蛋白及丰富维生素饮食（A对），但是肝性脑病时应限制蛋白质的摄入。当出现并发症时，如上消化道出血、肝性脑病、腹水、自发性腹膜炎等，需要同时给予治疗（C对）。目前保肝药物对于肝硬化的治疗尚无肯定疗效，而且大部分的药物经过肝脏进行生物降解、解毒，因此治疗肝硬化时，选用多种保肝药物不仅起不到保肝的作用，反而加重肝脏负担，不利于肝功恢复（B错）。近年来，国内外学者采用激素的短程疗法，以利用激素停药后的免疫“反跳”作用，希望通过这种免疫的“反跳”作用，达到用其他抗病毒药物清除乙肝病毒的目的，即肾上腺皮质激素可作为免疫调节药物，用于慢性活动性肝炎者的抗病毒治疗（D对）。","","N"],["1995-N152",11,"第一节 胸腔积液","渗出性胸腔积液",1995,152,"X","","下列哪些病因的胸腔积液是渗出液",[["A","肿瘤转移"],["B","结缔组织病"],["C","气胸"],["D","结核性"]],"ABCD","胸腔积液是指胸腔内液体产生增多或吸收减少，超出正常范围的一种病理改变。渗出液产生的常见病因有：①胸膜通透性增加，如胸膜炎症（肺结核、肺炎）（D对）、风湿性疾病[系统性红斑狼疮（SLE）、类风湿关节炎（RA）等弥漫性结缔组织病（十版内科学P814）（B对）]、胸膜肿瘤（恶性肿瘤转移、间皮瘤）（A对）、肺梗塞、膈下炎症（膈下脓肿、肝脓肿、急性胰腺炎）等；②壁层胸膜淋巴引流障碍，如癌症淋巴管阻塞、发育性淋巴管引流异常等。可并发胸腔积液的气胸（C对）一般是由肺部炎症所致，故其胸腔积液的性质为渗出液。","","N"],["1995-N153",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄临床表现",1995,153,"X","","有关主动脉瓣狭窄所致的主动脉瓣区收缩期杂音的描述，下述哪些正确",[["A","响度可在三级以上"],["B","伴有主动脉瓣关闭不全时，则杂音减弱"],["C","杂音强度取决于瓣膜狭窄程度"],["D","老年人该杂音可在心尖部最响"]],"AD","器质性病变导致的心脏收缩期杂音多在3/6级以上，而功能性改变导致的心脏收缩期杂音（生理性杂音）多不超过2/6级（九版诊断学P156）。主动脉狭窄为心脏结构的器质性病变，因此杂音响度可在三级以上（A对）。伴有主动脉瓣关闭不全时，左心室前负荷增加，左室流出道又出现相对性狭窄，因而杂音增强（B错）。老年人因瓣膜钙化，可导致该杂音在心尖部最响（D对）。杂音的强度与瓣膜狭窄程度呈正相关，但并不完全一致，还取决于血流量、血流速度等，例如左心衰时，杂音会减弱或消失（C错）。","","N"],["1995-N154",60,"第一节 库欣综合征","库欣病",1995,154,"X","","库欣（Cushing）病时，下列哪几项是正确的",[["A","垂体常有微腺瘤"],["B","血中ACTH减低"],["C","双侧肾上腺皮质增生"],["D","双侧肾上腺皮质有腺瘤"]],"AC","库欣病属于依赖ACTH的库欣综合征，是指垂体ACTH分泌过多，伴肾上腺皮质增生。垂体多有微腺瘤（A对），少数为大腺瘤，也有未能发现肿瘤者。由于ACTH（促肾上腺皮质激素）分泌过多（B错），刺激双侧肾上腺皮质弥漫性增生（C对），而不是引起双侧肾上腺皮质腺瘤（D错）。双侧肾上腺皮质腺瘤引起的库欣综合征属于不依赖ACTH的综合征。","","N"],["1995-N155",40,"第三节 急进性肾小球肾炎","急进性肾小球肾炎治疗",1995,155,"X","","治疗Ⅰ型急进性肾炎最适当的疗法有",[["A","皮质激素和环磷酰胺"],["B","环孢素A"],["C","血浆置换疗法"],["D","透析和肾移植"]],"AC","Ⅰ型急进性肾炎属于抗肾小球基底膜型肾炎，抗肾小球基底膜抗体沉积于肾小球基底膜造成肾小球损伤，早期血浆置换（C对）可以较为彻底去除抗肾小球基底膜型抗体，但该法必须联合应用皮质激素和环磷酰胺冲击治疗（A对），为防止机体大量丢失免疫球蛋白后大量合成而造成反跳。但八版内科学认为甲泼尼龙冲击联合环磷酰胺治疗主要适用于Ⅱ、Ⅲ型，Ⅰ型疗效较差。因此，本题若作为单选，选C似乎更加合理，真题作为多选题目，可理解为将两者相结合用于治疗。急进性肾炎进展迅速，而环孢素A（B错）起效慢，因而不宜使用。凡因急性肾衰竭已达透析指征患者，应及时透析。肾移植应在病情停止半年，特别是Ⅰ型患者须在血中抗GBM抗体转阴后半年方可进行（D错）。","","N"],["1995-N156",52,"第三节 慢性髓系白血病","类白血病反应",1995,156,"X","","中性粒细胞碱性磷酸酶阳性率和积分增高可见于",[["A","阵发性睡眠性血红蛋白尿"],["B","慢性粒细胞性白血病"],["C","类白血病反应"],["D","再生障碍性贫血"]],"CD","NAP（中性粒细胞碱性磷酸酶）存在于成熟阶段的中性粒细胞中，NAP阳性率与患者中性粒细胞有无发育障碍直接相关，而与外周血粒细胞总数无关。类白血病反应（C对）常并发于严重感染、恶性肿瘤等基础疾病，外周血白细胞显著增高，中性粒细胞发育活跃，多为有功能的成熟中性粒细胞，因此NAP阳性率升高。再障（D对）骨髓造血衰竭，骨髓粒系增生障碍，幼稚粒细胞再生不足，中性粒细胞数量减少但发育无障碍，故NAP阳性率增高。NAP升高还见于急淋、急单、慢粒白血病急性变、严重化脓性感染、原发性血小板增多症、骨髓纤维化和真性红细胞增多症等。PNH（阵发性睡眠性血红蛋白尿）（十版内科学P567）（A错）是一种后天获得性造血干细胞基因突变所致的溶血病，病变不但累及红系，也可累及粒系，导致中性粒细胞发育障碍，故NAP阳性率降低。慢性粒细胞性白血病（B错）骨髓增生明显，以幼稚粒细胞为主，中性粒细胞发育障碍，故NAP阳性率降低。NAP阳性率降低还见于急粒、单纯性病毒性感染、系统性红斑狼疮。","","N"],["1996-N47",30,"第一节 溃疡性结肠炎","溃疡性结肠炎概述",1996,47,"A","","现在认为下列哪项最不可能引起溃疡性结肠炎",[["A","结肠的感染"],["B","变态反应"],["C","细胞免疫异常"],["D","遗传"],["E","过敏反应"]],"A","炎症性肠病（IBD）是一类多种病因引起的、异常免疫介导的肠道慢性及复发性炎症，溃疡性结肠炎和克罗恩病是其主要疾病类型，由环境、遗传（D对）、肠道微生态和免疫多因素相互作用所致。变态反应（超敏反应）（B对）、细胞免疫异常（C对）、过敏反应（E对）均属于免疫因素。结肠的感染（A错，为本题正确答案）最不可能引起溃疡性结肠炎。","","N"],["1996-N48",30,"第二节 克罗恩病","活动期",1996,48,"A","","关于肾上腺皮质激素治疗克罗恩病，下列哪项是不正确",[["A","用于本病活动期，对控制症状有效"],["B","长期应用可防止复发"],["C","一般开始口服泼尼松每日40～60mg"],["D","严重者可静脉给药"],["E","有瘘管形成者应慎用"]],"B","糖皮质激素对控制病情活动有较好疗效（A对），适用于各型中、重度患者以及对5-氨基水杨酸无效的中度患者，但有瘘管形成者应慎用（E对），因肠瘘通向的组织与器官因粪便污染可致继发性感染，糖皮质激素具有抗炎症及免疫抑制作用，可使感染不易控制，加重感染。糖皮质激素通过抑制免疫来控制症状，维持治疗可延长缓解期，但并不能减少复发（B错，为本题正确答案），且长期应用不良反应太大，因此不主张应用糖皮质激素长期维持治疗。方法一般予口服泼尼松0.75～1mg/kg，即开始口服泼尼松每日40～60mg（C对），重症患者先给予较大剂量静脉滴注（D对），7～10天后改为口服，病情缓解后逐渐减量至停药，减量期间加用5-氨基水杨酸逐渐接替激素治疗。","","N"],["1996-N49",35,"第一节 肝硬化","肝性脑病",1996,49,"A","","肝性脑病时中枢神经系统的多巴胺合成减少，故应给予",[["A","多巴胺"],["B","复方氨基酸溶液"],["C","乙酰谷氨酰胺"],["D","左旋多巴"],["E","乳果糖"]],"D","肾上腺素的代谢途径为：苯丙氨酸→酪氨酸→多巴→多巴胺→去甲肾上腺素→肾上腺素。故肝性昏迷时中枢神经系统的多巴胺合成减少，去甲肾上腺素合成随之减少，二者均为兴奋性神经递质，其合成减少可导致患者出现中枢抑制反应。由于多巴胺（A错）不能通过血脑屏障，因此不能用于肝性脑病的治疗。左旋多巴（D对）是多巴胺的前体，可通过血脑屏障进入脑组织，后转变为多巴胺，后者再转变为去甲肾上腺素，提高神经系统兴奋性，并可竞争性替换掉神经突触处的假性神经递质，故可用于肝性脑病的治疗。乙酰谷氨酰胺（C错）、乳果糖（E错）主要用于降低血氨（十版内科学P425），与多巴胺的补充无关。治疗肝性脑病时，使用的是支链氨基酸，并不是复方氨基酸（B错）。","","N"],["1996-N50",35,"","",1996,50,"A","","关于肝肾综合征，下列哪项不正确",[["A","多发生于有大量腹水的失代偿期肝硬化"],["B","表现为少尿或无尿"],["C","肾衰竭为不可逆性"],["D","低钠血症"],["E","低尿钠症"]],"C","肝肾综合征是指发生在严重肝病基础上的肾衰竭，多发生于有大量腹水的失代偿期肝硬化（A对）或急性肝功能衰竭的患者，由于全身血流动力学的改变，表现为内脏血管床扩张，心输出量相对不足和有效血容量不足，肾素-血管紧张素-醛固酮系统和交感神经系统被进一步激活，最终导致肾皮质血管强烈收缩、肾小球率过率下降，是一种功能性肾衰。由于肾脏本身并无器质性病变，肾功能衰竭具有可逆性（C错，为本题正确答案）。肝肾综合征临床表现为自发性少尿或无尿（B对），氮质血症和血肌酐升高，稀释性低钠血症（醛固酮灭活减少，水钠潴留；尿量减少，水相对潴留较多）（D对），低尿钠症（醛固酮灭活减少，尿钠重吸收增加，导致尿钠降低）（E对）。","","N"],["1996-N51",38,"第一节 消化道出血","积极补充血容量",1996,51,"A","","男，25岁，节律性间断上腹隐痛3年，加重2天，10天前开始自解黑便3次，量约1000g左右，血压9.16/6.0kPa，脉率120次/分，Hb90g/L，首选下列哪种治疗",[["A","大量输液"],["B","输右旋糖酐"],["C","外科手术"],["D","急诊内镜止血"],["E","输血、补液"]],"E","青年男性患者，节律性间断上腹隐痛3年，近期加重，出现大量黑便，并出现失血性休克和贫血表现，初步诊断为消化道大出血。患者血压9.16/6.0kPa（即68.7/45mmHg，休克指数=脉搏/收缩压=120/68.7=1.75＞1.5，提示严重休克，失血量为30％-50％）。因此，该患者目前最重要的措施为抗休克，又失血量＞30%（1500ml），应输全血与浓缩红细胞各半，再配合晶体液、胶体液及血浆（九版外科学P21），故输血、补液为首要治疗（E对AB错）。内科治疗无效才行外科手术治疗（C错）。急诊内镜止血（D错）应在休克纠正后执行。","","N"],["1996-N52",28,"第一节 消化性溃疡","球后溃疡",1996,52,"A","","关于球后溃疡的临床表现，下列哪项不符合",[["A","夜间痛常见"],["B","疼痛常向背部放射"],["C","症状较一般十二指肠溃疡严重而持续"],["D","不易出血"],["E","内科疗效差"]],"D","球后溃疡指发生于十二指肠降段、水平段的溃疡，多发生在十二指肠降段的初始部及乳头附近，溃疡多在后内侧壁，可穿透入胰腺（十版内科学P375）。球后溃疡多具有十二指肠球部溃疡的临床特点，但症状较一般十二指肠溃疡严重而持续（C对），且夜间疼痛和背部放射痛更为多见（AB对），对药物治疗反应较差（E对），较易并发出血（D错，为本题正确答案）。","","N"],["1996-N53",61,"第一节 糖尿病","糖化血红蛋白和糖化白蛋白测定",1996,53,"A","","关于糖尿病某些化验的意义，下列哪项是正确的",[["A","血清胆固醇（主要是HDL₂胆固醇）水平与大血管病变的危险性呈负相关"],["B","血清低密度脂蛋白水平与大血管病变的危险性呈负相关"],["C","血清极低密度脂蛋白水平与大血管病变的危险性呈负相关"],["D","外周血糖化血红蛋白的测定可反映近2～3周内血糖总的水平"],["E","外周血糖化血浆白蛋白测定可反映近2～3个月血糖总的水平"]],"A","高密度脂蛋白（HDL）（A对）为血管保护因子，与大血管病变危险性呈负相关。低密度脂蛋白（LDL）（B错）、极低密度脂蛋白（VLDL）（C错）为大血管病变的危害因子，与其危险性呈正相关（十版内科学P755）。外周血糖化血红蛋白是葡萄糖或其他糖与血红蛋白的氨基发生非酶催化反应，由于红细胞在血循环中的寿命约为120天，故外周血糖化血红蛋白可反映近8～12周内（D错）血糖平均水平。外周血糖化血浆白蛋白与葡萄糖发生非酶催化的糖化反应而形成果糖胺，由于白蛋白在血中半衰期为19天，故外周血糖化血浆白蛋白测定可反映2～3周内（E错）血糖平均水平","","N"],["1996-N54",59,"第一节 甲状腺功能亢进症","心血管系统",1996,54,"A","","Graves病的心血管系统体征，下列哪项是正确的",[["A","心动过速，休息或熟睡时可减慢"],["B","心律失常中以心房颤动最为常见"],["C","心尖部常可闻及舒张期杂音"],["D","心脏可肥大和扩大"],["E","收缩压上升，而舒张压不变或稍上升"]],"D","Graves病心血管系统以高动力循环为特征，几乎所有患者均伴有持续性窦性心动过速，心率多在90～120次/分（正常60～100次/分），在休息或熟睡时仍高于正常（A错）。Graves病所致心律失常以房性期前收缩最多见，其次为阵发性或持续性心房颤动（B错）。Graves病为高动力循环，左心室前负荷增加，心腔扩大，可致二尖瓣相对关闭不全，故常能听到是收缩期杂音而不是舒张期杂音（C错）。长期高动力循环在早期心肌可代偿性肥厚，心肌肥大，晚期心脏失代偿，心肌细胞出现坏死及纤维化，出现心脏扩大（D对）。Graves病患者心肌收缩力增强，心输出量增加，导致收缩压增高；Graves病患者体温可升高，外周血管代偿性舒张以促进散热，因此外周血管阻力下降，舒张压多降低（E错）。","","N"],["1996-N55",40,"第五节 肾病综合征","利尿消肿",1996,55,"A","","肾病综合征时的利尿治疗，下列哪项不正确",[["A","抑制醛固酮、抗利尿激素的分泌——肾上腺皮质激素"],["B","排钠潴钾利尿剂——安体舒通"],["C","袢利尿剂——丁尿胺"],["D","噻嗪类利尿剂——利尿酸钠"],["E","渗透性利尿剂——低分子右旋糖酐"]],"D","利尿消肿是肾病综合征常用的对症治疗，对肾病综合征患者的利尿治疗原则上不宜过快过猛，以免造成血容量不足，加重血液高粘度，诱发血栓。利尿消肿是肾病综合征常用的对症治疗，药物治疗一般包括5种类型：①噻嗪类利尿剂，常用的有氢氯噻嗪；②潴钾利尿剂，常用的有氨苯喋啶、螺内酯（安体舒通）（B对）；③袢利尿剂，常用的有呋塞米、布美他尼（丁尿胺）（C对）、依他尼酸（利尿酸钠）；④渗透性利尿剂，常用的有低分子右旋糖酐（E对）；⑤提高血浆胶体渗透压（当患者出现严重低蛋白血症伴水肿而又少尿时适用）。此外，肾上腺皮质激素可通过抑制醛固酮、抗利尿激素的分泌而发发挥其利尿作用（A对）。因此，依他尼酸（利尿酸钠）（D错，为本题正确答案）为袢利尿剂而不是噻嗪类利尿剂。","","N"],["1996-N56",41,"第一节 尿路感染","慢性肾盂肾炎的诊断",1996,56,"A","","对肾盂肾炎的描述，下列哪项不正确",[["A","肾盂肾炎病史超过一年即为慢性期"],["B","“无症状性菌尿”亦需及时系统治疗"],["C","容易再次复发"],["D","诊断慢性肾盂肾炎时，过去可无明确病史"],["E","判定急性期或者慢性期有困难时，可作短期治疗，以利鉴别"]],"A","慢性肾盂肾炎的诊断除反复发作尿路感染病史之外（超过半年），尚需结合影像学及肾脏功能检测：①肾外形凹凸不平，且双肾大小不等；②静脉肾盂造影可见肾盂、肾盏变形，缩窄；③持续性肾小管功能损害。具备上述第①、②条的任何一项再加第③条可诊断慢性肾盂肾炎（十版内科学P502）。因此单纯认为肾盂肾炎病史超过一年即为慢性期是错误的（A错，为本题正确答案）。慢性肾盂肾炎半数以上有急性发作病史，有的过去可无明确病史（D对）。肾盂肾炎合并无症状性菌尿，尿路有复杂情况，应及时给予相应治疗（B对）。肾盂肾炎为上尿路感染，治疗不及时或不彻底时容易再次复发（C对）。判定急性期或者慢性期有困难时，可作短期治疗，以利鉴别（E对）。急性者经短期治疗，症状改善明显；慢性肾盂肾炎常有尿路感染易感因素，短期治疗后症状可改善，但若不去除易感因素，常反复发作。","","N"],["1996-N57",40,"第一节 肾小球疾病概述","水肿",1996,57,"A","","下列哪一项不是肾病性水肿的机制",[["A","血浆胶体渗透压下降"],["B","激活肾素-血管紧张素-醛固酮系统"],["C","肾小管重吸收增加"],["D","肾小球滤过率下降"],["E","抗利尿激素分泌增加"]],"D","本题考查肾病性水肿的发生机制。肾病性水肿时肾小球受损较轻，滤过率多数仅轻度下降，肾小球滤过率下降（D错，为本题正确答案）属于肾炎性水肿的原因。肾病综合征时血浆蛋白大量流失，血浆胶体渗透压降低（A对），血液中水分漏出至组织间，导致组织水肿。血液中水分流失至组织间隙，血容量减少，使肾素-血管紧张素-醛固酮活性增加（B对），抗利尿激素增加（E对）加重水、钠潴留引起水肿。肾小管重吸收增加会使水钠潴留，导致肾病性水肿（C对）。","","N"],["1996-N58",51,"第一节 骨髓增生异常性肿瘤","骨髓增生异常性肿瘤实验室检查",1996,58,"A","","下列哪种情况骨髓红系增生情况与网织红细胞计数不一致",[["A","再生障碍性贫血"],["B","缺铁性贫血"],["C","急性白血病"],["D","骨髓增生异常综合征（MDS）"],["E","自身免疫性溶血性贫血"]],"D","再生障碍性贫血（十版内科学P555）（A错）是一种骨髓造血功能衰竭症，主要表现为骨髓造血功能低下、外周血网织红细胞减少和外周血三系减少，骨髓红系增生情况与网织红细胞计数一致，均为降低。缺铁性贫血（B错）时，原料铁缺乏，血红素及血红蛋白合成不足，骨髓中红系代偿性增生，网织红细胞（反映骨髓造血情况）计数多正常或轻度升高，骨髓红系增生情况与网织红细胞计数基本一致，均为升高。急性白血病（十版内科学P579）（C错）时，骨髓中白血病细胞大量增殖，骨髓红系增生受抑制而降低，外周血中网织红细胞计数也降低，骨髓红系增生情况与网织红细胞计数一致，均为降低。MDS（骨髓增生异常综合征）（十版内科学P572）（D对）是一组起源于造血干细胞的克隆性疾病，表现为骨髓红系增生活跃，外周血网织红细胞计数下降，骨髓红系增生情况与网织红细胞计数不一致。自身免疫性溶血性贫血（E错）是机体产生抗自身红细胞的抗体，致使红细胞破坏的一种疾病，表现为骨髓红系代偿性增生，网织红细胞计数升高，骨髓红系增生情况与网织红细胞计数基本一致，均为升高。","","N"],["1996-N59",49,"第一节 再生障碍性贫血","针对发病机制的治疗",1996,59,"A","","再生障碍性贫血治疗有效的一般病变中，下列哪项恢复最困难",[["A","血红蛋白"],["B","网织红细胞"],["C","中性粒细胞"],["D","单核细胞"],["E","血小板"]],"E","再生障碍性贫血的治疗分为支持治疗、免疫抑制治疗、促造血治疗和造血干细胞移植（十版内科学P557），一般于治疗开始2～3月出现网织红细胞（B错）计数上升，然后血红蛋白（A错）上升，白细胞（中性粒细胞、嗜酸性粒细胞、嗜碱性粒细胞及单核细胞等）（CD错）也较早恢复正常，但血小板（E对）几年仍处于低值，所以血小板的恢复最困难。","","N"],["1996-N60",47,"第一节 缺铁性贫血","缺铁性贫血铁代谢",1996,60,"A","","关于铁代谢，下列哪项是正确的",[["A","正常肠黏膜可吸收三价铁"],["B","血清铁一般是亚铁离子"],["C","维生素C能把食物中铁游离化"],["D","铁主要在空肠下段吸收"],["E","在肠黏膜细胞内铁离子与去铁铁蛋白结合"]],"E","正常肠黏膜可吸收二价铁（A错），而食物中的铁通常为三价铁，需要还原为二价铁后才容易被吸收。血清铁（三价铁离子与转铁蛋白结合）一般是三价铁离子（B错）。维生素C不能把食物中铁游离化（C错），而是把食物中的三价铁还原为二价铁，以促进铁的吸收。铁主要在十二指肠和空肠上段吸收（D错）。当机体原料铁充足时，多余的铁在肠黏膜细胞内与去铁铁蛋白结合（E对）而被吸收。","","N"],["1996-N61",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病发病机制",1996,61,"A","","目前认为关于肺气肿发生的机理，下列哪项不正确",[["A","弹性蛋白酶活性受抑制"],["B","α₁-抗胰蛋白酶缺乏"],["C","血清α₁-抗胰蛋白酶活力低下"],["D","中性粒细胞和巨噬细胞释放蛋白分解酶增多"],["E","肺泡壁毛细血管受压，肺组织营养障碍"]],"A","肺部的炎症可以使中性粒细胞和巨噬细胞活化和聚集，释放弹性蛋白酶增多（D对），破坏肺实质，产生肺气肿，所以弹性酶活性受抑制不是肺气肿发生的机理（A错，为本题的正确答案）。蛋白酶增多或抗蛋白酶不足均可导致肺组织结构破坏，产生肺气肿，所以α₁-抗胰蛋白酶缺乏（B对）和血清α₁-抗胰蛋白酶活力低下（C对）为肺气肿发生的机理。肺泡壁毛细血管受压，肺泡壁血液灌流减少，通气血流比例失调，产生肺组织营养障碍（E对），也为肺气肿发生的机理。","","N"],["1996-N62",1,"第一节 慢性支气管炎","慢性支气管炎缓解期治疗",1996,62,"A","","慢性支气管炎偶有轻微咳嗽，少量痰液，采取下列哪项措施最为合适",[["A","应用抗生素治疗"],["B","少量镇咳剂"],["C","应用支气管扩张剂以利排痰"],["D","提高机体抗病能力，避免上呼吸道感染"],["E","应用少量激素，减少气道非特异性炎症"]],"D","感染是慢性支气管炎加重的重要原因之一，故慢性支气管炎缓解期时的最合适治疗措施为提高机体抗病能力，避免上呼吸道感染（D对），同时也应该戒烟，避免吸入有害气体或有害颗粒。患者处于慢性支气管炎缓解期，偶有轻微咳嗽、少量痰液，症状较轻，多可自愈，无需应用少量镇咳剂（B错）及应用支气管扩张剂以利排痰（C错）等治疗措施。另外，患者未有明显感染及炎症的表现，故无需应用抗生素（A错）及少量激素（E错）。ABCE都是慢性支气管炎急性加重期的治疗措施。","","N"],["1996-N63",10,"第三节 慢性肺源性心脏病","正性肌力药",1996,63,"A","","肺心病患者心衰使用洋地黄，下述哪项不正确",[["A","避免选用作用快的制剂"],["B","用量为常规量的1/2～2/3"],["C","心率快与慢不能作为疗效指征"],["D","一般疗效较差"],["E","不作为首选治疗心功能不全的药物"]],"A","慢性肺心病患者由于慢性感染和缺氧对洋地黄类的耐受性低，疗效差（D对），易致中毒，出现心律失常，因此，不作为肺心病患者首选治疗心功能不全的药物（E对），应用应持慎重态度。用药时宜选用作用快、排泄快的制剂（A错，为本题正确答案），用量为常规量的1/2～2/3（B对）。肺心病患者低氧血症、感染等均可使心率增快，故不宜以心率快与慢作为衡量洋地黄类药物的应用和疗效考核指征（C对）。","","N"],["1996-N64",11,"第二节 气胸","排气疗法",1996,64,"A","","下列哪项积气量占该侧胸腔容量百分值的自发性气胸患者需进行治疗",[["A","15%以上"],["B","20%以上"],["C","25%以上"],["D","30%以上"],["E","40%以上"]],"B","对于肺被压缩面积＜20%，单纯性、首次发病、无明显症状的闭合性气胸，可采取保守治疗；肺被压缩＞20%的气胸，可给予胸腔穿刺抽气治疗（二版八年制内科学P150）（B对）。","","N"],["1996-N65",3,"第一节 支气管扩张症","清除气道分泌物",1996,65,"A","","支气管扩张患者施行体位引流排痰，下列哪项不正确",[["A","病变肺应处于高处"],["B","每日应引流2～4次，每次15～30分钟"],["C","可用生理盐水先作雾化吸入，便于排痰"],["D","痰量多的患者，应尽快把痰排出"],["E","排痰时，同时配合深呼吸，用力咳痰，可提高排痰效果"]],"D","支气管扩张患者施行体位引流排痰，应逐渐排出痰液，防止痰多发生气道堵塞，导致患者窒息（D错，为本题正确答案）。支气管扩张患者施行体位引流，一般要求病变部位较气管和喉部为高的体位，使病肺处于高位（A对），引流支气管开口向下。采用手拍或机械振动等方法，使振动从胸壁传导到支气管，松动分泌物，以利排出。每日应引流2～4次，每次15～30分钟（B对），排痰时，同时配合深呼吸，用力咳痰，可提高排痰效果（E对）。痰液黏稠者，可用生理盐水先作雾化吸入，使痰液稀释后便于排出（二版八年制内科学P100）（C对）。","","N"],["1996-N66",13,"第三节 慢性呼吸衰竭","正压机械通气",1996,66,"A","","呼吸衰竭患者治疗使用呼吸机辅助呼吸，下列哪项正确",[["A","呼吸衰竭伴低血压，应及时用呼吸机"],["B","严重呼吸性酸中毒和缺氧，应及时用呼吸机"],["C","气道阻力增加的重症病变，宜使用压力控制呼吸机"],["D","对肺顺应性降低的重症病变，宜使用压力控制呼吸机"],["E","对锻炼恢复自主呼吸病变，宜使用容量控制呼吸机"]],"B","判断是否需要行机械可参考以下条件：①意识障碍；②呼吸频率＞35～40次/分、呼吸节律异常或自主呼吸微弱或消失；③PaO₂＜50mmHg，尤其是吸氧后仍＜50mmHg；④PaCO₂进行性升高，pH进行性下降；⑤呼吸衰竭经常规治疗后效果不佳，有病情恶化趋势（二版八年制内科学P170）。呼吸衰竭伴低血压时，应先补充血容量，与呼吸机的使用无关（A错）。若呼衰急性发作，导致低氧和CO₂潴留甚至严重的呼吸性酸中毒时应及时使用呼吸机（B对）。呼吸机常用的通气的模式包括控制通气、辅助通气、辅助-控制通气、同步间歇指令通气、压力支持通气、呼吸膜正压通气等。控制通气包括容量控制通气和压力控制通气。容量控制通气能保证潮气量和分钟通气量的供给，压力控制通气吸气峰值压较低，可降低气压伤的发生，对气道阻力增加及肺顺应性降低的重症病变，宜使用容量控制型呼吸机（CD错）。同步间歇指令通气是指间歇指令的每一次送气在同步窗内由自主呼吸触发，若在同步触发窗内无触发，呼吸机按预置参数送气，间歇控制通气之外的时间允许自主呼吸的存在，适用于锻炼恢复自主呼吸的病变（E错）。","","N"],["1996-N67",11,"第一节 胸腔积液","恶性胸腔积液",1996,67,"A","","女性38岁，右侧中等量胸腔积液，胸水检查结果：淡红色，比重1.018，白细胞总数264×10⁶/L，Rivalta试验阳性，蛋白定量胸水/血清为1.0，LDH568U/L，葡萄糖定量3.4mmol/L，应首先考虑的诊断为",[["A","结核性"],["B","风湿性"],["C","肿瘤性"],["D","细菌性肺炎"],["E","肺梗塞"]],"C","该患者胸水淡红色，比重1.018，Rivalta试验（鉴别胸腔积液为渗出液还是漏出液的试验，阳性为渗出液，阴性为漏出液）阳性，胸水蛋白/血清蛋白＞0.5，LDH˃500U/L，可确定胸水性质为渗出液。肿瘤性胸水常呈血性，pH＞7.4，ADA25～45U/L，LDH˃500U/L，葡萄糖含量在3.3mmol/L左右或更低，所以该患者最可能的诊断为肿瘤性胸腔积液（C对）；结核性胸水（十版内科学P131）（A错）可呈血性，但以淋巴细胞增多为主，pH＜7.3，ADA＞45U/L，LDH＞200U/L，葡萄糖＜3.3mmol/L；风湿性胸水如类风湿关节炎（十版内科学P127）（B错）多呈黄绿色；细菌性肺炎（十版内科学P129）（D错）所致胸水一般草黄色或脓性，白细胞明显升高，以中性粒细胞增多为主；肺梗塞（E错）的胸腔积液虽可以产生淡红色胸腔积液，但一般LDH＞200U/L。","","N"],["1996-N68",16,"第一节 心律失常概述","心律失常的体格检查",1996,68,"A","","在心脏听诊方面，对分析诊断心律失常最有价值的心音是",[["A","第一心音和第二心音"],["B","第一心音和第三心音"],["C","第一心音和第四心音"],["D","第二心音和第三心音"],["E","第三心音和第四心音"]],"A","诊断心律失常时，心音检查有临床意义，尤其以第一心音及第二心音最有价值（A对）。第一心音主要由二尖瓣及三尖瓣关闭产生，第二心音主要由主动脉瓣及肺动脉瓣关闭产生。第一、第二心音在多种心律失常可出现典型变化，例如：房室传导阻滞或房室分离时，由于PR间期的变化可导致第一心音强度的改变；当存有完全左束支传导阻滞时可听到第二心音的反常分裂；房颤时可出现第一心音强弱不等。","","N"],["1996-N69",18,"第一节 原发性高血压","脑血管病",1996,69,"A","","有关高血压病的并发症，下列哪项不正确",[["A","心、脑、肾等器官是主要受累脏器"],["B","眼底病变与高血压的严重程度直接有关"],["C","恶性高血压以脑并发症最为突出"],["D","脑卒中的发病率比心肌梗塞高5倍左右"],["E","高血压脑病症状出现可能与脑水肿有关"]],"C","患者发生恶性高血压时舒张压持续≥130mmHg，肾脏损害突出，表现为持续蛋白尿、血尿与管型尿，故恶性高血压以肾脏并发症最为突出，而不是脑（C错，为本题正确答案）。高血压主要累及的脏器为心、脑、肾（A对）。眼底小动脉为唯一可以从体表观察的小动脉，根据对眼底血管病变的观察可了解高血压血管病变，帮助判断高血压的严重程度（B对）。长期高血压使脑血管发生缺血与变性，形成微动脉瘤，一旦破裂可发生脑出血。临床相关数据显示，脑卒中的发病率比心肌梗塞高5倍左右（D对）。高血压脑病发病机制之一为血压过高，使脑部血管灌注增多，毛细血管压力过高，渗透性增强，导致脑水肿（E对）。","","N"],["1996-N70",17,"第四节 急性冠状综合征","钙通道阻滞剂",1996,70,"A","","钙拮抗剂治疗心绞痛的主要机理，下列哪项不正确",[["A","抑制心肌收缩，减少心肌耗氧量"],["B","扩张外周动脉，降低血压，减轻后负荷"],["C","降低血液黏度，抗血小板聚集"],["D","解除冠状动脉痉挛，改善心肌供氧"],["E","减慢心率，减少心肌做功"]],"E","钙通道阻滞剂治疗心绞痛的主要机理包括：①阻滞心肌细胞膜上的L型钙通道，减少进入心肌细胞内钙离子数量，从而抑制心肌细胞兴奋-收缩偶联中钙离子的利用，抑制心肌收缩，减少心肌耗氧量（A对）；②扩张冠脉，解除冠状动脉痉挛，改善心肌供氧（D对）；③扩张外周动脉，降低血压，减轻后负荷（B对）；④还降低血液黏度，抗血小板聚集（C对），改善心肌的微循环。钙拮抗剂包括二氢吡啶类（硝苯地平、氨氯地平和尼卡地平等）和非二氢吡啶类（地尔硫䓬和维拉帕米等）两大类。非二氢吡啶类钙拮抗剂对心肌抑制作用较强，具有负性频率、负性肌力及负性传导作用，可减慢心率，减少心肌做功；而二氢吡啶类钙拮抗剂（如硝苯地平）扩张外周血管作用强，降压效果明显，可反射性兴奋交感神经，引起心率加快（E错，为本题正确答案）。","","N"],["1996-N71",21,"第四节 二尖瓣反流","二尖瓣反流临床表现",1996,71,"A","","二尖瓣关闭不全杂音的特征，下列哪项不正确",[["A","反流量大，杂音音调高"],["B","瓣膜增厚，杂音粗糙"],["C","前瓣损害为主，杂音向左腋下传导"],["D","由于左心室射血期延长，可导致第二心音逆分裂"],["E","风心病所致的杂音主要为收缩早、中期"]],"E","二尖瓣关闭不全时，瓣膜口反流量越大，杂音音调越高（A对）；瓣膜越厚，杂音越粗糙（B对）。二尖瓣关闭不全时前叶损害为主杂音向左腋下或左肩胛下传导（C对），后叶损害为主则杂音向心底部传导为主。二尖瓣关闭不全时由于左心室射血期缩短，主动脉瓣关闭提前，听诊可闻及S₂通常分裂（D错）。逆分裂指主动脉瓣关闭迟于肺动脉瓣，S₂反常分裂（逆分裂）是病理性体征，见于完全性左束支传导阻滞、主动脉瓣狭窄、重度高血压。二尖瓣关闭不全的典型杂音为心尖区全收缩期吹风样杂音（E错，为本题正确答案），杂音强度≥3/6级。本题答案应为DE，但参考答案为E。","","N"],["1996-N72",19,"第二节 扩张型心肌病","基因突变",1996,72,"A","","目前认为扩张型心肌病最主要的病因是",[["A","病毒性心肌炎"],["B","遗传因素"],["C","酒精中毒因素"],["D","内分泌疾患"],["E","代谢异常"]],"B","多数扩张型心肌病病因不清，常有家族性发病趋势，遗传方式多为常染色体显性、少数为常染色体隐性或X连锁遗传（B对）。病毒感染和自身免疫等获得性病因也参与致病。","","N"],["1996-N73",22,"第三节 缩窄性心包炎","缩窄性心包炎临床表现",1996,73,"A","","关于结核性心包炎的特征，下列哪项不符合",[["A","可有大量心包积液"],["B","可呈血性心包积液"],["C","心包摩擦音较多见"],["D","在肺内可无结核病灶"],["E","治疗不当可引起心包缩窄"]],"C","心包摩擦音由粗糙的心包壁层与脏层在心脏活动时相互摩擦产生，常见于纤维素性心包炎早期积液量较少时。结核性心包炎心包积液量一般较大（A对），此时脏壁层心包分离，心包摩擦音消失（C错，为本题正确答案）。结核性心包炎心包积液可呈浆液纤维素性或血性（B对）。结核性心包炎可由纵隔、肺、胸膜结核蔓延而来或经淋巴转移到心包，因此在肺内可无结核病灶（D对）。如治疗不当，可转为亚急性期或慢性期，此时积液逐渐吸收、纤维组织增生、心包增厚粘连，部分发展为心包缩窄（E对）。","","N"],["1996-N74",16,"第四节 房室交界性心律失常","房室交界性期前收缩临床表现",1996,74,"A","","关于房室交界性早搏，下列哪项正确",[["A","临床较常见"],["B","常发生在无器质性心脏病基础上"],["C","偶尔能呈隐匿性传导"],["D","其起源部位都在房室结本身"],["E","一般下传心室大多可伴有传导阻滞"]],"C","房室交界性早搏临床不常见（A错），室性早搏较常见。交界性早搏既可见于正常健康人，也可见于器质性心脏病患者（B错）。交界性早搏就是一种特殊的情况下出现的一次心脏提前的跳动，并且引起这种跳动的冲动起源于房室交界区（D错），房室交界区包括房室结和希氏束等。隐匿性房室交界区性早搏是指交界区性期前收缩，虽伴有双向性传导阻滞，但既不能前向传导激动心室，也不能逆向传导激动心房，但此隐匿性传导却因已激动了部分房室交界组织产生了一次新的不应期，而可影响下一次窦性搏动的传导，从而引起多种心律失常。因此房室交界性早搏偶尔能呈隐匿性传导（C对）。房室交界性早搏一般无传导阻滞（E错），QRS波形态正常，但早搏时相过早时，可出现室内差异性传导阻滞，QRS波呈宽大畸形。","","N"],["1996-N105",61,"第一节 糖尿病","双胍类",1996,105,"B","","降糖灵引起酮尿最常见",[["A","尿糖++++，酮体阴性"],["B","尿糖++++，酮体强阳性"],["C","尿糖阴性，酮体阳性"],["D","尿糖+，酮体阳性"],["E","尿糖+，酮体阴性"]],"D","降糖灵（盐酸苯乙双胍）降血糖的机理为促进肌肉等外周组织摄取葡萄糖、加速无氧糖酵解、抑制葡萄糖异生、抑制或延缓葡萄糖在胃肠道吸收，降低血糖，还能分解脂肪，脂肪酸经b氧化产生酮体。因此，服用此药后，血糖明显下降，尿糖+，酮体为阳性（D对）。尿糖++++，酮体阴性（A错）为高渗高血糖综合征的特点（十版内科学P746）。尿糖++++，尿酮体强阳性（B错）为糖尿病酮症酸中毒的特点（十版内科学P744）。尿糖阴性，酮体阳性（C错）为饥饿性酮症的特点。尿糖+，酮体阴性（E错）为糖尿病的特点。","","N"],["1996-N106",61,"第二节 糖尿病酮症酸中毒","糖尿病酮症酸中毒实验室检查",1996,106,"B","","糖尿病酮中毒",[["A","尿糖++++，酮体阴性"],["B","尿糖++++，酮体强阳性"],["C","尿糖阴性，酮体阳性"],["D","尿糖+，酮体阳性"],["E","尿糖+，酮体阴性"]],"B","糖尿病酮症酸中毒患者糖利用障碍，血糖明显升高使尿糖呈强阳性，同时动用脂肪，大量脂肪酸在肝内经β氧化产生大量酮体，使尿酮体亦呈强阳性（B对）（注意：八版内科学描述为“尿酮阳性”）。尿糖++++，酮体阴性（A错）为高渗高血糖综合征的表现（十版内科学P746）。尿糖阴性，酮体阳性（C错）为饥饿性酮症的表现。尿糖+，酮体阴性（E错）为糖尿病的表现。尿糖+，酮体为阳性（D错）为服用降糖灵（盐酸苯乙双胍）的表现。","","N"],["1996-N107",75,"第二节 农药中毒","胆碱酯酶复活药",1996,107,"B","","解除有机磷中毒时烟碱样毒性作用，首选",[["A","阿托品"],["B","解磷定"],["C","美解眠"],["D","尼可刹米"],["E","甘露醇"]],"B","烟碱样症状是由于AChE被抑制后，ACh过多蓄积，持续作用于神经肌肉接头处烟碱样受体（N样受体），出现肌纤维颤动、全身肌强直性痉挛。ChE复能药为肟类化合物能使被抑制的ChE恢复活性，其中解磷定复能作用强，毒性小，水溶性大，还能作用于外周N₂受体，对抗外周N胆碱受体活性，能有效解除烟碱样毒性作用，是临床上首选的解毒药（B对）。胆碱受体阻断药阿托品（A错）主要作用于外周M受体，能缓解M样症状，对N受体无明显作用，解除有机磷中毒时毒蕈碱样毒性作用，而对烟碱样症状无有效缓解作用。美解眠（贝美格）（C错）为中枢兴奋剂，可用于巴比妥类药物中毒的解毒。尼可刹米（D错）为呼吸兴奋剂，甘露醇（E错）为脱水剂，二者对烟碱样症状均无有效作用。","","N"],["1996-N108",75,"第二节 农药中毒","胆碱受体拮抗药",1996,108,"B","","解除有机磷中毒时毒蕈碱样毒性作用，首选",[["A","阿托品"],["B","解磷定"],["C","美解眠"],["D","尼可刹米"],["E","甘露醇"]],"A","毒蕈碱样症状又称M样症状，主要是副交感神经末梢过度兴奋所致。胆碱受体阻断药阿托品主要作用于外周M受体，能缓解M样症状，对N受体无明显作用，解除有机磷中毒时毒蕈碱样毒性作用（A对）。烟碱样症状是由于ACh过多蓄积所致，ChE复能药为肟类化合物能使被抑制的ChE恢复活性，其中解磷定（B错）复能作用强，毒性小，水溶性大，可作用于外周N₂受体，对抗外周N胆碱受体活性，有效缓解烟碱样症状，但对M样症状和中枢性呼吸抑制作用无明显影响。美解眠（贝美格）（C错）为中枢兴奋剂，可用于巴比妥类药物中毒的解毒。尼可刹米（D错）为呼吸兴奋剂，甘露醇（E错）为脱水剂，二者均对M受体无作用，故无法缓解毒蕈碱样症状。","","N"],["1996-N109",47,"第一节 缺铁性贫血","铁代谢",1996,109,"B","","缺铁性贫血",[["A","血清铁蛋白增高，血清铁增高，总铁结合力增高"],["B","血清铁蛋白增高，血清铁增高，总铁结合力降低"],["C","血清铁蛋白增高，血清铁降低，总铁结合力降低"],["D","血清铁蛋白降低，血清铁降低，总铁结合力降低"],["E","血清铁蛋白降低，血清铁降低，总铁结合力增高"]],"E","血清铁蛋白是铁的贮存形式，血清铁是与转铁蛋白结合的铁。缺铁性贫血的患者原料铁缺乏，导致血清铁蛋白降低，血清铁降低。总铁结合力是指每升血清中的转铁蛋白所能结合的最大铁量，实际反映转铁蛋白的水平。缺铁性贫血的患者，机体转铁蛋白合成增强，总铁结合力增高（E对），以增加铁的利用率。","","N"],["1996-N110",47,"第一节 缺铁性贫血","铁粒幼细胞贫血",1996,110,"B","","铁粒幼细胞性贫血",[["A","血清铁蛋白增高，血清铁增高，总铁结合力增高"],["B","血清铁蛋白增高，血清铁增高，总铁结合力降低"],["C","血清铁蛋白增高，血清铁降低，总铁结合力降低"],["D","血清铁蛋白降低，血清铁降低，总铁结合力降低"],["E","血清铁蛋白降低，血清铁降低，总铁结合力增高"]],"B","铁粒幼细胞贫血由于铁的利用障碍而导致血红素和血红蛋白合成障碍，铁无法被利用，血清铁和血清铁蛋白均增高。以前认为铁粒幼细胞性贫血的铁代谢指标与缺铁性贫血相反，缺铁性贫血总铁结合力升高，铁粒幼细胞性贫血总铁结合力下降，但七、八、九、十版内科学认为铁粒幼细胞贫血中总铁结合力不低（总铁结合力是指每升血清中的转铁蛋白所能结合的最大铁量，实际反映转铁蛋白的水平，铁粒幼细胞贫血时，转铁蛋白合成不会减少）。根据十版内科学观点，本题无正确答案，但参考答案为B。","","N"],["1996-N127",21,"第二节 主动脉瓣反流","主动脉瓣反流并发症",1996,127,"C","","主动脉瓣关闭不全",[["A","栓塞"],["B","猝死"],["C","二者均有"],["D","二者均无"]],"C","主动脉瓣关闭不全的最常见病因为风心病，其次为感染性心内膜炎。风心病发生栓塞的机率为20%，感染性心内膜炎发生动脉栓塞率为15%～35%（A对）。冠脉血供主要为舒张期血供，而主动脉瓣关闭不全时舒张压明显降低，冠脉供血因此减少并出现心绞痛，严重者甚至可以发生猝死（B对）。本题AB均对，正确答案为C。","","N"],["1996-N128",19,"第六节 心肌炎","心肌炎并发症",1996,128,"C","","病毒性心肌炎",[["A","栓塞"],["B","猝死"],["C","二者均有"],["D","二者均无"]],"B","病毒性心肌炎患者临床表现取决于病变的广泛程度和部位，轻者可无症状，暴发性心肌炎和重症心肌炎进展快、死亡率高，可随时出现心源性休克及猝死（B对）。临床上栓塞比较少见（A错）。","","N"],["1996-N129",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎支原体肺炎治疗",1996,129,"C","","支原体肺炎",[["A","咳砖红色痰"],["B","红霉素治疗有效"],["C","两者均是"],["D","两者均不是"]],"B","支原体肺炎咳嗽多为阵发性刺激性呛咳，咳少量黏液，治疗首选大环内酯类抗生素，如红霉素（B对）；咳砖红色痰（A错）常见于克雷伯杆菌肺炎，其治疗首选药物为氨基糖苷类+半合成青霉素。","","N"],["1996-N130",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎克雷伯杆菌肺炎临床表现",1996,130,"C","","克雷伯杆菌肺炎",[["A","咳砖红色痰"],["B","红霉素治疗有效"],["C","两者均是"],["D","两者均不是"]],"A","克雷伯杆菌肺炎痰液特点为砖红色胶冻状痰（A对），红霉素对支原体、衣原体、军团菌肺炎有效，而肺炎克雷伯杆菌治疗应首选氨基糖苷类抗生素+半合成青霉素（B错）。","","N"],["1996-N133",35,"第一节 肝硬化","肝功能减退",1996,133,"C","","重症肝细胞性黄疸",[["A","皮肤黄染"],["B","巩膜黄染"],["C","两者均有"],["D","两者均无"]],"C","肝细胞性黄疸是由于肝细胞病变，对胆红素摄取、结合和排泄功能发生障碍，以致血中胆红素含量升高。因巩膜含有较多的弹性硬蛋白，与胆红素有较强的亲和力，故黄疸患者巩膜黄染（A对）常先于黏膜、皮肤而首先被察觉。当血清总胆红素在17.1～34.2μmol/L，而肉眼看不出黄疸时，称隐性黄疸或亚临床黄疸；当血清总胆红素浓度超过34.2μmol/L时，临床上即可发现黄疸，即皮肤出现黄染（B对）。因此重症肝细胞性黄疸时，皮肤和巩膜均可出现黄染。本题AB均对，正确答案为C。","","N"],["1996-N134",25,"","",1996,134,"C","","胡萝卜素引起的假性黄疸",[["A","皮肤黄染"],["B","巩膜黄染"],["C","两者均有"],["D","两者均无"]],"A","假性黄疸的原因主要为一次大量或持续多次摄入含有大量胡萝卜素的食物，由此造成血清β-胡萝卜素显著增高，致色素在皮肤沉着，以皮肤黄染（A对）为主要特征的疾病，其与血清胆红素增加引起的皮肤、巩膜黄染（即真性黄疸）不同，一般不出现口腔黏膜和巩膜黄染（B错），故称为假性黄疸。","","N"],["1996-N151",2,"第一节 支气管哮喘","通气功能检查",1996,151,"X","","小气道通气功能减低可见于下列哪些疾病",[["A","冠心病"],["B","慢性肺源性心脏病"],["C","支气管哮喘"],["D","进行性系统性硬化症"]],"BC","慢性肺源性心脏病（B对）及支气管哮喘（C对）均可导致小气道痉挛、狭窄，使小气道通气功能减退。冠心病（A错）为冠状动脉粥样硬化性心脏病，与肺和小气道通气功能无关。进行性系统性硬化症（D错）是结缔组织异常增生的自身免疫性疾病，在肺部表现为肺间质纤维化和肺动脉高压，影响肺的换气功能，但不会影响小气道的通气功能（二版八年制内科学P1161）。","","N"],["1996-N152",17,"第四节 急性冠状综合征","溶栓疗法",1996,152,"X","","急性心肌梗塞溶栓治疗，常用的溶栓剂有",[["A","肝素"],["B","阿司匹林"],["C","尿激酶"],["D","链激酶"]],"CD","目前临床上使用的溶栓药物多为纤维蛋白溶酶原激活剂，可以激活血栓中的纤维蛋白溶酶原，将血栓溶解，实现冠状动脉的再通。常用的溶栓药物有尿激酶（C对）、链激酶（D对）、重组组织型纤维蛋白溶酶原激活剂（rt-PA）。肝素（A错）为抗凝血酶Ⅲ依赖的抗血栓形成药，可增强抗凝血酶Ⅲ的生物活性，增强其对部分凝血因子的抑制作用，用于防治血栓形成或栓塞性疾病等。阿司匹林（B错）通过抑制环氧化酶和血栓烷A₂的合成达到抗血小板聚集的作用。","","N"],["1996-N153",61,"第一节 糖尿病","T2DM病因、发病机制和自然史",1996,153,"X","","下列哪些情况糖耐量可减低",[["A","应激性糖尿"],["B","糖尿病"],["C","肾性糖尿"],["D","口服阿司匹林、消炎痛"]],"ABD","应激状态下，胰岛素拮抗激素（如肾上腺素、促肾上腺皮质激素、肾上腺皮质激素和生长激素）分泌增加，可使糖耐量减低（A对），出现一过性血糖升高，尿糖阳性，应激过后可恢复正常。糖尿病胰岛素分泌不足，可引起糖耐量低下（B对）。口服阿司匹林、吲哚美辛（消炎痛）可抑制胰岛素释放或有抗胰岛素的作用，导致糖耐量减低（D对）。肾性糖尿因肾糖阈降低所致，尿糖阳性，但血糖、OGTT正常及耐糖量正常（C错）。","","N"],["1996-N154",56,"第二节 原发免疫性血小板减少症","急症处理",1996,154,"X","","特发性血小板减少性紫癜病人出血严重，应选用如下哪些治疗",[["A","静脉给氢化可的松或地塞米松"],["B","输注浓缩血小板悬液"],["C","大剂量免疫球蛋白静脉输注"],["D","静脉给环磷酰胺"]],"ABC","特发性血小板减少性紫癜（ITP）患者出血严重属于ITP急症，处理可输注血小板预防颅内出血（B对），也可静脉输注丙种球蛋白（C对）以及静脉输注大剂量氢化可的松或地塞米松（A对）。环磷酰胺（D错）为细胞毒药物，为ITP的二线治疗，只有在糖皮质激素、静脉输注丙种球蛋白等一线治疗无效时才考虑使用。","","N"],["1996-N155",29,"第二节 结核性腹膜炎","腹腔积液检查",1996,155,"X","","结核性腹膜炎腹水性质可为",[["A","草黄色渗出液"],["B","淡血色"],["C","合并肝硬化的病人可接近漏出液"],["D","乳糜性"]],"ABCD","结核性腹膜炎腹水多为草黄色渗出液（A对），少数为浑浊或淡血性（B对），偶见乳糜性（D对）。结核性腹膜炎腹水一般为渗出液，但合并肝硬化时，由于肝硬化所致的大量漏出性腹水的稀释作用，可使腹水最终接近漏出液（C对）。","","N"],["1996-N156",40,"第五节 肾病综合征","低白蛋白血症",1996,156,"X","","肾病综合征时可伴哪些血浆蛋白成分下降",[["A","白蛋白"],["B","转铁蛋白"],["C","IgG"],["D","多种内分泌结合蛋白"]],"ABCD","在正常生理状况下，肾小球滤过膜具有机械屏障及电荷屏障作用。肾病综合征时屏障受损导致原尿中蛋白含量增多，大量蛋白质自尿液丢失，出现低蛋白血症。血浆蛋白减少以白蛋白（A对）为主，也包括免疫球蛋白（如IgG）（C对）、补体成分、抗凝及纤溶因子、金属结合蛋白如转铁蛋白（B对）及内分泌激素结合蛋白（D对）等。","","N"],["1997-N47",30,"第一节 溃疡性结肠炎","溃疡性结肠炎病理",1997,47,"A","","溃疡性结肠炎病变多位于",[["A","回肠末端及升结肠"],["B","升结肠"],["C","降结肠"],["D","全结肠"],["E","直肠及乙状结肠"]],"E","记住各种肠道疾病的好发部位对于其诊断与鉴别诊断很有帮助，因此考生应该熟练掌握。如溃疡性结肠炎病变多自直肠开始，逆行向近段发展，可累及全结肠甚至末端回肠，但主要位于直肠和乙状结肠（E对），极少数可扩展至全结肠（D错）。克罗恩病在整个胃肠道的任何部位均可发生，但好发于回肠末端及邻近结肠（十版内科学P392）（A错）。肠结核病变主要位于回盲部，肠阿米巴疾病病变部位主要在盲肠、升结肠。","","N"],["1997-N48",28,"第一节 消化性溃疡","消化性溃疡临床表现",1997,48,"A","","关于消化性溃疡的叙述，哪一项是不正确的",[["A","在临床上，十二指肠溃疡较胃溃疡多见"],["B","绝大多数病例病变位于胃和十二指肠"],["C","男性发病多于女性"],["D","全世界均多见"],["E","童年及老年均罕见"]],"E","消化性溃疡可发生于食管、胃、十二指肠、胃-空肠吻合口附近以及含有胃粘膜的Meckel憩室，胃、十二指肠球部溃疡最常见（B对）。消化性溃疡是全球性常见病（D对），可发生于任何年龄段，并非儿童及老年罕见（E错，为本题正确答案）。十二指肠球部溃疡多于胃溃疡（A对），十二指肠球部溃疡与胃溃疡发生率的比值大约为3：1。不论是胃溃疡还是十二指肠球部溃疡均好发于男性（C对）。","","N"],["1997-N50",75,"第一节 中毒概述","洗胃",1997,50,"A","","服毒后的洗胃处理，下列哪项不正确",[["A","一般在服毒后6小时内洗胃有效"],["B","超过6小时多数洗胃已无必要"],["C","吞服强腐蚀性毒物者，不宜洗胃"],["D","惊厥患者不宜插管洗胃"],["E","昏迷患者插胃管易致吸入性肺炎，洗胃应慎重"]],"B","洗胃在口服毒物1小时内效果最好，在6小时内仍有效（A对）。对于服用吸收缓慢的毒物、胃蠕动功能减弱或消失者，虽服毒超过6小时，但胃内还可能有没被吸收的毒物，只要符合洗胃条件的仍应积极洗胃治疗（B错，为本题正确答案），以免毒物继续被吸收。吞服强腐蚀性毒物患者，洗胃可能引起穿孔（C对）；食管静脉曲张患者洗胃可引起静脉破裂出血；惊厥患者洗胃插管时，可能诱发惊厥（D对）；昏迷患者洗胃插管时，易引起吸入性肺炎（E对）。以上均为洗胃的禁忌证。","","N"],["1997-N51",35,"第一节 肝硬化","利尿",1997,51,"A","","肝硬化腹水患者，应首选的利尿剂为",[["A","甘露醇"],["B","利尿酸钠"],["C","双氢氯噻嗪"],["D","安体舒通"],["E","速尿"]],"D","肝硬化患者腹水形成的原因之一是继发性醛固酮增多，使钠重吸收增加，导致水、钠潴留。安体舒通又称螺内酯，与醛固酮受体有很强的亲和力，但无内在活性，故具有竞争性拮抗醛固酮的作用，改善水钠潴留，增加尿量，减轻水肿。此外，肝硬化腹水患者多合并低钾，而螺内酯正是一种低效的保钾性利尿剂，可以纠正低钾，故肝硬化患者腹水的治疗首选安体舒通（D对）。甘露醇（A错）为渗透性脱水剂，临床主要用于脑水肿，降低颅内压，而肝硬化腹水血管内容量并无显著增多，强力脱水有引起肝性脑病的风险。利尿酸钠（B错）作用机制、作用特点与速尿（呋塞米）（E错）类似，都是强效排钾利尿剂，易加重肝硬化腹水的低钾，对肝硬化腹水治疗不利，常与保钾利尿剂螺内酯联合使用，而不作为首选。再者利尿酸钠和速尿可促进肾素的释放，使醛固酮分泌增多，对肝硬化腹水的治疗不利。双氢氯噻嗪（C错）为中效排钾利尿剂，效果不强且易加重肝硬化腹水的低钾，肝硬化腹水治疗较少使用。","","N"],["1997-N52",35,"第一节 肝硬化","肝硬化分期",1997,52,"A","","患者男，50岁，既往体健，查体时发现肝在右肋下2cm，质硬、压痛、脾可触及、锌浊度试验20单位、ALT正常范围、肝穿刺病理有假小叶形成，应诊断为",[["A","慢性活动性肝炎"],["B","慢性持续性肝炎"],["C","代偿期肝硬化"],["D","肝淤血"],["E","多囊肝"]],"C","中年男性患者，既往体健，肝大，触之质硬、有压痛，脾可触及，肝穿刺见假小叶（假小叶是肝硬化特征性病理变化），因此本例可以拟诊为肝硬化。锌浊度试验，即硫酸锌浊度试验，是测定血浆蛋白的水平和分析其成分的肝脏疾病重要试验之一，原理是血清中的γ球蛋白，在低浓度的硫酸锌溶液中发生沉淀而显浑浊，浑浊程度与γ球蛋白的含量成正比，其浑浊程度与沉淀的多少与肝病的严重程度有一定的关系，正常值2～12U。由于患者锌浊度试验20单位（正常值2～12U）、ALT正常范围，提示肝功能实验室检查轻度异常，因此可诊断为代偿期肝硬化（C对）。慢性活动性肝炎（A错）、慢性持续性肝炎（B错）、肝淤血（D错）及多囊肝（E错）肝穿刺病理无假小叶形成。","","N"],["1997-N53",40,"第五节 肾病综合征","糖皮质激素",1997,53,"A","","原发性肾病综合征患者，首次治疗，每日用强的松60mg，三周后尿蛋白仍为（++++），此时应",[["A","改用地塞米松"],["B","将泼尼松加量到80mg/日"],["C","改用环磷酰胺"],["D","用原量继续观察"],["E","减少泼尼松用量到40mg/日，加用免疫抑制剂"]],"D","原发性肾病综合征的激素治疗原则：即起始量要足，减剂量和撤药速度要慢，用药时间持续要久（十版内科学P484）。本例患者首次治疗刚3周，故应该原剂量继续服用至8周（D对E错），必要时可延长至12周。地塞米松（A错）半衰期长，副作用大，现在很少用。起始足量用量后一般不能再继续加量（B错）。环磷酰胺（C错）是细胞毒药物，仅用于激素依赖型或激素抵抗型患者，协同激素治疗，不单独应用。","","N"],["1997-N54",40,"第二节 急性肾小球肾炎","急性肾小球肾炎临床表现",1997,54,"A","","急性肾小球肾炎最常见的临床表现为",[["A","咽痛、蛋白尿、水肿、血浆白蛋白下降"],["B","蛋白尿、血尿、心功能不全"],["C","血尿、蛋白尿、水肿、高血压"],["D","血尿、肾区叩痛、发烧"],["E","血尿、蛋白尿、尿路刺激征"]],"C","急性肾小球肾炎常表现为急性肾炎综合征即血尿、蛋白尿、水肿、高血压（C对），并可有一过性肾功能不全。少数患者（＜20%患者）可呈肾病综合征范围的大量蛋白尿，但一般不出现血浆白蛋白下降（A错）。心功能不全（十版内科学P476）（B错）常发生于急性肾炎综合征期，继发于严重水、钠潴留和高血压，并非急性肾小球肾炎最常见的表现。肾区叩痛、发烧（D错）常见于肾盂肾炎（十版内科学P500），肾小球肾炎少见。尿路刺激征（E错）为下尿路感染的临床表现。","","N"],["1997-N55",41,"第一节 尿路感染","尿细菌学检查",1997,55,"A","","尿培养的球菌菌落计数不低于多少才有诊断意义",[["A","100/ml"],["B","300/ml"],["C","500/ml"],["D","1000/ml"],["E","10000/ml"]],"D","一般菌落计数大于10万个才有诊断意义，但由于球菌生长慢，故菌落计数大于1000/ml就有意义（D对）。杆菌大于100000/ml有意义。泌尿系统感染临床诊断基础上，符合下述四条之一即可诊断：1.清洁中段尿或导尿留取尿液（非留置导尿）培养革兰阳性球菌菌数≥10⁴cfu/ml、革兰阴性杆菌菌数≥10⁵cfu/ml；2.耻骨联合上膀胱穿刺留取尿液培养有细菌生长；3.新鲜尿液标本经离心应用相差显微镜检查（1×400），在30个视野中有半数视野见到细菌；4.无症状性菌尿症：患者虽然无症状，但在近期（通常为1周）有内镜检查或留置导尿史，尿液培养革兰阳性球菌浓度≥10⁴cfu/ml、革兰阴性杆菌浓度≥10⁵cfu/ml，应视为泌尿系统感染。","","N"],["1997-N56",47,"第一节 缺铁性贫血","铁代谢",1997,56,"A","","下列哪一项不符合缺铁性贫血",[["A","血清铁蛋白减低"],["B","血清铁减低"],["C","总铁结合力减低"],["D","运铁蛋白饱和度减低"],["E","骨髓有核红细胞内铁减低"]],"C","血清铁是指与转铁蛋白结合的铁，缺铁性贫血时，原料铁减少，血清铁减低（B对）。转铁蛋白饱和度指的是与铁结合的转铁蛋白占转铁蛋白总量的百分比，缺铁性贫血时，与铁结合的转铁蛋白减少，运铁蛋白（转铁蛋白）饱和度减低（D对）。总铁结合力是指每升血清中的转铁蛋白所能结合的最大铁量，反映转铁蛋白的水平，缺铁性贫血时，机体转铁蛋白合成增强，总铁结合力升高（C错，为本题正确答案），以增加铁的利用率。血清铁蛋白和骨髓有核红细胞内铁是贮存铁，当原料铁减少时，机体动员贮存铁以满足代谢需要，血清铁蛋白减低（A对），骨髓有核红细胞内铁减低（E对）。","","N"],["1997-N57",49,"第一节 再生障碍性贫血","AA诊断标准",1997,57,"A","","再生障碍性贫血的诊断，下列哪一项不正确",[["A","发热、出血、贫血"],["B","一般无肝脾和淋巴结肿大"],["C","中性粒细胞碱性磷酸酶阳性率和积分减低"],["D","骨髓可呈灶性增生，但巨核细胞减少"],["E","末梢血淋巴细胞比例数增高"]],"C","再生障碍性贫血是一种骨髓造血功能衰竭症，主要表现为发热、出血、贫血（A对）等，一般无肝、脾和淋巴结肿大（B对）。肝、脾和淋巴结肿大常见于白血病等恶性克隆性疾病。中性粒细胞碱性磷酸酶阳性率和积分值主要反映粒细胞的成熟程度和功能，再生障碍性贫血患者中性粒细胞成熟程度增高，所以中性粒细胞碱性磷酸酶阳性率和积分升高（C错，为本题正确答案）。再生障碍性贫血表现为多部位增生低下，但在某些病例可表现为骨髓呈灶性增生，但巨核细胞减少（D对）。再生障碍性贫血发病与T细胞功能亢进有关，因此淋巴细胞比例增高（E对）。","","N"],["1997-N58",47,"第一节 缺铁性贫血","铁粒幼细胞贫血",1997,58,"A","","哪一种贫血不是由于红细胞破坏过多引起的",[["A","海洋性贫血"],["B","蚕豆病"],["C","铁粒幼细胞性贫血"],["D","镰刀细胞性贫血"],["E","遗传性球形红细胞增多症"]],"C","红细胞破坏过多性贫血即溶血性贫血。海洋性贫血（A错）是由基因异常引起的珠蛋白合成减少，红细胞稳定性降低，属于溶血性贫血。蚕豆病（B错）是指缺乏红细胞葡萄糖-6-磷酸脱氢酶的儿童食用蚕豆等氧化剂后引起的急性血管内溶血。铁粒幼细胞性贫血（C对）是因为铁利用障碍，使血红蛋白合成减少而导致的贫血，并非红细胞破坏过多引起。镰刀形细胞性贫血（D错）是基因点突变（谷氨酸被缬氨酸替代）引起红细胞扭曲成镰状细胞而导致的贫血，属于溶血性贫血。遗传性球形红细胞增多症（E错）是红细胞膜异常引起的遗传性溶血性贫血。","","N"],["1997-N59",59,"第一节 甲状腺功能亢进症","甲状腺功能亢进症病因和发病机制",1997,59,"A","","弥漫性甲状腺肿伴甲亢的发病原理，哪项与目前观点不符",[["A","与遗传因素有关"],["B","由于甲状腺刺激抗体LATS及LATS-P的作用"],["C","由于细胞免疫异常"],["D","由于TSH分泌亢进"],["E","精神因素诱发"]],"D","弥漫性甲状腺肿伴甲亢又称Graves病（GD），是一种自身免疫性疾病，因多数患者同时有甲状腺毒症和甲状腺弥漫性肿大，故称为“毒性弥漫性甲状腺肿”。本病有显著的遗传倾向（A对），同时环境因素也参与了GD的发生，因此GD是在遗传易感性的基础上，在感染、应激、分娩、精神压力、辐射、药物等因素的作用下，引起体内免疫功能紊乱、甲状腺功能的异常（E对）。本病伴发甲亢的原因为患者B淋巴细胞产生抗体[促甲状腺激素受体抗体（TRAb），早期也被称为长效甲状腺刺激物（LATS）、LATS保护物（LATSP）等]（B对），可与甲状腺滤泡细胞上的促甲状腺激素（TSH）受体结合并使之活化，刺激甲状腺的增长并产生过多的甲状腺激素，此时是甲状腺滤泡细胞的TSH受体为抗体结合的位点，抗体与其结合后，能模拟TSH的功能，刺激甲状腺产生过多的甲状腺激素，故甲亢并非由于TSH本身的分泌亢进（D错，为本题正确答案）。目前产生TRAb的机制尚未完全阐明，目前认为有易感基因人群的甲状腺组织，在受到触发因素（环境因素）的刺激下，甲状腺细胞表面特异的HLA Ⅱ类分子呈递TSH受体片段给T淋巴细胞（C对），促使B淋巴细胞在免疫耐受缺陷时形成TRAb（15版本实用内科学P2267）。","","N"],["1997-N60",61,"第一节 糖尿病","T1DM的临床特点",1997,60,"A","","胰岛素依赖型糖尿病（Ⅰ型）与非胰岛素依赖型糖尿病（Ⅱ型）的最主要区别是",[["A","发病年龄不同"],["B","对胰岛素的敏感性不同"],["C","胰岛素基础水平与释放曲线不同"],["D","发生酮中毒的倾向不同"],["E","血糖稳定性不同"]],"C","胰岛素依赖型糖尿病（1型糖尿病）（十版内科学P724）的胰岛β细胞破坏，常导致胰岛素绝对缺乏，葡萄糖负荷后血浆胰岛素浓度无明显升高，呈低平曲线；非胰岛素依赖型糖尿病（2型糖尿病）是胰岛素抵抗或胰岛素分泌不足所致，因此体内胰岛素水平正常甚至升高，空腹血浆胰岛素基础值正常、较低或偏高，葡萄糖负荷后血浆胰岛素分泌高峰延迟。可见非胰岛素依赖型糖尿病与胰岛素依赖型糖尿病的最主要区别是胰岛素基础值及释放曲线（C对）。多数1型糖尿病为青少年患者，起病初期需要胰岛素治疗，有自发酮症酸中毒倾向；2型糖尿病可见于任何年龄，多见于成年人，初期不需要胰岛素治疗，随着胰岛β细胞衰竭，需胰岛素治疗，在一定诱因下也可发生酮症酸中毒。可见发病年龄（A错）、对胰岛素的敏感性（B错）、发生酮中毒的倾向（D错）均可为两者的区别，但都不是最主要的区别。糖尿病患者糖耐量减低，都需要综合治疗来控制血糖使其稳定，因此血糖稳定性（E错）也不是其主要区别。","","N"],["1997-N61",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病病理生理",1997,61,"A","","下列哪项关于阻塞性肺气肿出现的病理生理改变是错误的",[["A","最大通气量和时间肺活量减低"],["B","残气量占肺总量的百分比增加"],["C","动态及静态肺顺应性降低"],["D","生理无效腔气量增大"],["E","肺内动静脉分流"]],"C","顺应性指弹性体在外力作用下发生变形的难易程度，它包括静态顺应性和动态顺应性。静态顺应性反映肺组织的弹性，肺气肿时，肺组织的弹性减弱，在外力作用下更容易发生形变，故静态顺应性应当增加（C错，为本题正确答案）；动态顺应性反映肺呼吸运动的容易程度，慢性支气管炎并发肺气肿时肺呼吸运动困难，故动态顺应性下降。阻塞性肺气肿病变累及大气道时，肺通气功能障碍，最大通气量和时间肺活量减低（A对）；阻塞性肺气肿肺组织弹性减退，肺泡回缩障碍，残气量及残气量占肺总量的百分比增加（B对）；阻塞性肺气肿加重导致肺泡周围肺毛细血管受挤，肺泡壁血液灌流减少，导致无效腔样气量增大（D对），也有部分肺区虽有血流灌流，但通气不良，导致功能性分流增加（E对）。","","N"],["1997-N62",4,"第二节细菌性肺炎","肺炎链球菌肺炎发病机制",1997,62,"A","","哪种细菌性肺炎极少并发肺脓肿、空洞",[["A","金黄色葡萄球菌肺炎"],["B","链球菌肺炎"],["C","克雷伯杆菌肺炎"],["D","绿脓杆菌肺炎"],["E","肺炎链球菌肺炎"]],"E","肺炎链球菌不产生毒素，不引起组织坏死或形成空洞，其致病力是由于高分子多糖体的荚膜对组织的侵袭作用，表现为肺泡水肿和细胞渗出（E对）。金黄色葡萄球菌肺炎（十版内科学P53）（A错）X线表现为肺叶或小叶浸润，早期空洞，脓胸，可见液气囊腔；克雷伯杆菌肺炎（十版内科学P49）（C错）X线表现为肺叶或肺段实变，蜂窝状脓肿，叶间隙下坠；绿脓杆菌肺炎（十版内科学P49）（D错）又称铜绿假单胞菌肺炎，X线表现为弥漫性支气管炎，早期肺脓肿，可见ACD都会并发肺脓肿、空洞。肺炎链球菌肺炎是由肺炎链球菌或称肺炎球菌所引起的肺炎，链球菌肺炎为干扰选项（B错）。","","N"],["1997-N63",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎支原体肺炎临床表现",1997,63,"A","","有关肺炎支原体肺炎的临床表现，哪项是错误的",[["A","潜伏期约1～3周，起病缓慢"],["B","头痛显著"],["C","咳嗽不重，初为干咳，以后咳大量黏痰"],["D","发热退完后咳嗽可继续存在"],["E","胸膜累及时，可有胸膜摩擦音或胸水体征"]],"C","支原体肺炎潜伏期约2～3周，起病较缓慢（A对）。可有乏力、咽痛、头痛（B对）、咳嗽、发热、食欲不振、腹泻、肌痛、耳痛等。咳嗽多为阵发性刺激性呛咳，咳少量黏液（C错，为本题正确答案），体温恢复正常后可能仍有咳嗽（D对）。（九版病理学P190）支原体肺炎一般不累及胸膜（E），故E项存在争议。官方参考答案为C。","","N"],["1997-N64",11,"第二节 气胸","气胸治疗方法",1997,64,"A","","关于气胸的处理，哪项是错误的",[["A","气胸量＜20%，症状轻微，不需排气"],["B","如肺萎陷时间长，宜用高负压排气"],["C","交通性气胸应做胸腔插管引流"],["D","复发性气胸，可用四环素注入胸腔造成粘连"],["E","血气胸可做低位胸腔插管引流"]],"B","气胸量＜20%，症状轻微时，不需排气，可自行吸收（A对），积气量占该侧胸腔容量的20%时才需要进行抽气治疗；如肺萎陷时间长，肺压缩严重的患者，插管后应夹住引流管分次引流，不可以用高负压引流，避免复张后肺水肿或循环衰竭（B错，为本题正确答案）；不稳定型气胸，呼吸困难明显、肺压缩程度较重，交通性或张力性气胸，反复发生气胸的患者，应做胸腔插管引流（C对）；复发性气胸可向胸膜腔内注入硬化剂如四环素、灭菌滑石粉等产生无菌性胸膜炎症，使脏层和壁层胸膜粘连从而消灭胸膜腔间隙，减少复发（D对）；血气胸可做低位胸腔插管引流（E对），可迅速缓解症状，减轻对肺脏的压迫，促进肺复张。","","N"],["1997-N65",7,"第一节 肺癌","肺癌的放射治疗",1997,65,"A","","放射治疗不能控制或改善哪项支气管癌的合并症",[["A","支气管阻塞引起的呼吸困难"],["B","转移性骨痛"],["C","脑转移引起的颅内压增高"],["D","全血细胞减少"],["E","肥大性肺性骨关节病"]],"D","放射治疗会抑制骨髓造血，导致外周全血细胞减少，所以放射治疗不能控制或改善全血细胞减少的症状（D错，为本题正确答案），反而可能加重病情。放射治疗是肺癌局部治疗的手段之一，可使肿块缩小，控制肺癌的症状，如缓解支气管阻塞引起的呼吸困难（A对）、减轻转移性骨痛（B对）、减轻脑转移引起的颅内压增高（C对）及缓解肥大性肺性骨关节病（E对）。","","N"],["1997-N66",2,"第一节 支气管哮喘","药物分类和作用特点",1997,66,"A","","冠心病患者伴发支气管哮喘时应慎用哪种药物",[["A","氨茶碱"],["B","肾上腺皮质激素"],["C","酮替芬"],["D","肾上腺素"],["E","色苷酸钠"]],"D","伴有冠心病的支气管哮喘患者在哮喘发作时应选用不影响冠状动脉供血或影响小的药物，同时尽量减少血压的急剧波动，避免心肌应激性及心肌耗氧量增加，以免诱发心绞痛或心律失常等。肾上腺素对患者血压、耗氧量、应激性等影响较大，因此应慎用（D对）。治疗哮喘的药物主要有糖皮质激素（B错）、β₂受体激动剂、白三烯调节剂、茶碱类药物（A错）、抗胆碱类药物等。酮替芬（C错）属于致敏活性细胞（肥大细胞或嗜碱粒细胞）的过敏介质释放抑制剂，具有保护肥大细胞或嗜碱粒细胞的细胞膜，使之在变应原攻击下，减少膜变构，减少释放过敏活性介质的作用，故亦有肥大细胞膜保护剂之称，兼具变态反应病的预防及治疗双重功能，可以使用。色苷酸二钠（E错）是一种抗过敏药，用于治疗过敏性哮喘，可以使用。","","N"],["1997-N67",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病病理生理",1997,67,"A","","慢性支气管炎并发肺气肿时，最早出现的病理生理改变是",[["A","时间肺活量降低"],["B","生理无效腔气量增大"],["C","通气/血流比例失调"],["D","残气占肺总量百分比增加"],["E","低氧血症"]],"A","慢性支气管炎并发肺气肿主要导致肺的通气功能障碍，早期病变累及小气道，表现为小气道炎症、小气道纤维组织形成、小气道黏液栓等，使小气道阻力明显升高，肺功能检查以流速降低为主要改变，时间肺活量降低（A对）。以后病情发展，肺组织弹性日益减退，肺泡持续扩大，回缩障碍，则残气量及残气量占肺总量的百分比增加（D错）。肺气肿加重导致肺泡周围肺毛细血管受挤压大量减少，肺泡间血流减少，此时肺泡虽有通气，但肺泡壁无血流灌流，导致无效腔样气量增大（B错）；也有部分肺区虽有血流灌流，但通气不良，导致功能性分流增加，从而产生通气血流比例失调（C错）。发展到最后会引起缺氧和二氧化碳潴留，发生不同程度的低氧血症（E错）和高碳酸血症。","","N"],["1997-N68",17,"第四节 急性冠状综合征","右心室心肌梗死的处理",1997,68,"A","","有关急性右心室梗死的叙述，下列哪项是错误的",[["A","中心静脉压增高而肺毛细血管楔压正常"],["B","常与下壁及后壁心肌梗塞同时出现"],["C","增加右心室舒张末期容量可有利于维持左心功能"],["D","应慎用利尿剂治疗"],["E","应用冠脉内溶栓治疗的危险性比左心室梗死大"]],"E","冠脉内溶栓是使闭塞的冠状动脉再通，心肌得到再灌注，无论左室梗死，还是右室梗死，治疗时危险性无明显区别（E错，为本题正确答案）。右心室梗死后，右室搏出量减少，收缩末期残留于心室内的血液增多，导致右房及腔静脉血液回流不畅，引起中心静脉压增高；同时因右心室搏出量降低，肺循环血量减少，肺毛细血管楔压降低或正常（A对）。急性心肌梗死致右心衰的患者会因右心射血不足引起左心室相对充盈不足，如果使用利尿剂会减少右心室的充盈，进一步减少左心室的充盈量，故应慎用利尿剂（D对）。而相反，增加右心室舒张末期容量可有利于提高左心室排血量，维持左心功能（C对）。由于右室、下壁和后壁都是由右冠状动脉供血，因此右室梗死常与下壁、后壁心梗同时出现（B对）。","","N"],["1997-N69",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄临床表现",1997,69,"A","","下列哪项不是主动脉瓣狭窄的主要临床表现",[["A","栓塞"],["B","心绞痛"],["C","晕厥"],["D","左心功能不全"],["E","猝死"]],"A","主动脉瓣狭窄一般无血栓形成，因而鲜有栓塞（A错，为本题正确答案）并发症。主动脉瓣狭窄导致左心室收缩压明显升高，左心室代偿性肥厚，进而导致舒张期心室壁僵硬、顺应性降低，相继可发生左心房扩大、左心房压力增高，最终可引起左心功能不全（D对）。左心室肥厚造成心肌需氧量增多，左心室舒张压增高造成冠脉血流进一步减少，导致心肌缺血，出现心绞痛（B对）。狭窄的主动脉瓣口输出的血液不足以维持动脉血压，导致全身组织缺血，可引起晕厥（C对）甚至猝死（E对）。","","N"],["1997-N70",15,"第二节 慢性心力衰竭","左心衰竭体征",1997,70,"A","","下列哪项提示左心功能不全",[["A","交替脉"],["B","奇脉"],["C","水冲脉"],["D","脉短绌"],["E","脉细数"]],"A","交替脉（A对）指节律规则而强弱交替的脉搏，一般认为是左室收缩力强弱交替所致，为左室心力衰竭的重要体征之一。奇脉（B错）又称吸停脉，表现为吸气时脉搏明显减弱甚至消失，呼气时又出现或恢复原状的现象，可见于大量心包积液、缩窄性心包炎、肺气肿及支气管哮喘。水冲脉（C错）常见于脉压增大明显的疾病，是由于周围血管扩张、血流量增大，或存在血液分流所致，前者见于甲亢、严重贫血等，后者见于主动脉瓣关闭不全、先天性心脏病动脉导管未闭、动静脉瘘等。脉短绌（D错）即在同一单位时间内，脉率少于心率，其特点为心律完全不规则，心率快慢不一，心音强弱不等，见于心房颤动、频发早搏等。脉细数（E错）指病人的脉搏变窄变细而且速率加快，见于心力衰竭以及低血容量性休克。","","N"],["1997-N71",18,"第一节 原发性高血压","脑血管病",1997,71,"A","","高血压病死亡原因最常见的为",[["A","心肌梗死"],["B","脑血管意外"],["C","肾功能衰竭"],["D","心功能不全"],["E","心律失常"]],"B","高血压病的并发症主要发生在心、脑、肾（十版内科学P263），并可导致心肌梗死（A）、脑血管意外（B）、肾功能衰竭（C）、心功能不全（D）、心律失常（E）等而死亡。但目前在我国，高血压病所致的脑血管意外仍是引起死亡的最常见原因（B对）。","","N"],["1997-N72",17,"第四节 急性冠状综合征","血清心肌坏死标志物",1997,72,"A","","对心肌损害诊断最具有特异性的血清酶是",[["A","GOT（AST）"],["B","GPT（ALT）"],["C","LDH"],["D","CK"],["E","以上都不是"]],"E","目前认为CK-MB（肌酸激酶同工酶）（E对）为诊断急性心梗特异性最高的酶学指标，肌钙蛋白（cTn）为诊断急性心梗特异性最高的生化指标。GOT（AST）（A错）即谷草转氨酶和GPT（ALT）（B错）即谷丙转氨酶是反映肝功能的标志物，在肝细胞损伤时可升高，因此对诊断急性心梗的特异性不高。LDH（C错）即乳酸脱氢酶特异性不如CK-MB。CK（D错）即肌酸激酶，在各种病变包括肌肉萎缩和心肌梗塞发生时，人的血清中肌酸激酶水平迅速提高，故其对诊断急性心梗的特异性亦不高。","","N"],["1997-N73",15,"第三节 急性心力衰竭","急性心力衰竭病因",1997,73,"A","","最常伴发急性左心功能衰竭的疾病是",[["A","肺梗死"],["B","室间隔缺损"],["C","肺动脉瓣狭窄"],["D","急进性高血压"],["E","主动脉窦瘤破裂入右心室"]],"D","少数患者病情急骤发展，舒张压持续≥130mmHg，并有头痛，视力模糊，眼底出血、渗出和视盘水肿，肾脏损害突出，持续蛋白尿、血尿和管型尿，称为恶性高血压（急进型高血压）（十版内科学P270）。急进型高血压（D对）常伴发急性左心功能衰竭，系因左心室后负荷增加而心肌收缩力不能随之增加，导致左心射血量下降，不能满足机体组织代谢需要。肺梗死（A错）、肺动脉瓣狭窄（C错）导致右心室射血阻力增加，后负荷加重，导致右心衰。室间隔缺损（B错）、主动脉窦瘤破裂入右心室（E错）均导致肺循环血量增加，肺动脉压力增高，早期肺血管阻力功能性增加，晚期肺血管发生组织学改变，发展为严重肺动脉高压，最终发生右心衰竭。","","N"],["1997-N74",74,"","",1997,74,"A","","哪项急性风湿病变伴发心脏炎的机率最低",[["A","关节炎"],["B","皮下结节"],["C","舞蹈病"],["D","环形红斑"],["E","血管炎"]],"C","急性风湿病变多伴有链球菌感染，可表现为全身结缔组织炎症，主要累及关节、心脏、皮肤和皮下组织，偶可累及中枢神经系统、血管、浆膜及肺、肾等内脏。临床表现以关节炎和心脏炎为主，可伴有发热、皮疹、皮下结节、舞蹈病等。但由于关节炎（A错）、皮下结节（B错）、环形红斑（D错）、血管炎（E错）都是结缔组织病变的表现，和心脏有同源性，可经血液传播链球菌感染心脏，导致心肌炎，心包炎等，伴发心脏炎的机率较高。而舞蹈病是急性风湿病变的神经系统病变的症状，病变主要影响大脑皮层、基底节及小脑，故发生心脏炎几率较低（C对）。","","N"],["1997-N105",69,"第一节 系统性红斑狼疮","系统性红斑狼疮肾脏表现",1997,105,"B","","青年女性蛋白尿患者，诊断首先应注意除外",[["A","狼疮性肾炎"],["B","尿酸肾病"],["C","肾淀粉样变性"],["D","糖尿病性肾病"],["E","原发性肾小球肾炎"]],"A","青年女性系统性红斑狼疮发病率高，女性患者占90%，而狼疮性肾炎是系统性红斑狼疮最常见、严重的并发症，系统性红斑狼疮患者肾活检受累几乎为100%。因此，青年女性出现蛋白尿时应先除外狼疮性肾炎（A对）。尿酸性肾病（B错）（痛风肾病）即血液中尿酸盐浓度增高达到过饱和状态，尿酸盐结晶沉积于肾脏而引起病变。痛风（十版内科学P851）多见于肥胖、喜肉食及酗酒者，男性明显高于女性，且痛风肾病的发生多在患高尿酸血症10年以上的中年以上患者。肾淀粉样变性病（十版内科学P484）（C错）是一种全身性疾病，早年发现这种淀粉样物质对碘的反应类似于淀粉类而得名，实际上主要是非可溶性的纤维蛋白质，发病以中老年为主，男性多于女性，表现为肾病综合征。糖尿病肾病（D错）是糖尿病全身微血管病性合并症之一，多发生于糖尿病病史超过10年者。原发性肾小球肾炎（E错）以青中年发病为主，男性多见。","","N"],["1997-N106",40,"第二节 急性肾小球肾炎","急性肾小球肾炎诊断",1997,106,"B","","青年男性蛋白尿患者，诊断首先考虑",[["A","狼疮性肾炎"],["B","尿酸肾病"],["C","肾淀粉样变性"],["D","糖尿病性肾病"],["E","原发性肾小球肾炎"]],"E","青年男性蛋白尿患者最常见原因为原发性肾小球肾炎（E对）。狼疮性肾炎（A错）为系统性红斑狼疮最常见的并发症，为自身免疫性疾病，以青年女性患者多见（十版内科学P490）。尿酸性肾病（痛风肾病）（B错）即血液中尿酸盐浓度增高达到过饱和状态，尿酸盐结晶沉积于肾脏而引起病变。痛风（十版内科学P851）多见于肥胖、喜肉食及酗酒者，男性明显高于女性，而痛风肾病的发生多在患高尿酸血症10年以上。肾淀粉样变性病（C错）是一种全身性疾病，早年发现这种淀粉样物质对碘的反应类似于淀粉类而得名，实际上主要是非可溶性的纤维蛋白质，发病以中老年为主，男性多于女性（P474）。糖尿病肾病（D错）是糖尿病全身微血管病性合并症之一，多发生于糖尿病病史超过10年者。","","N"],["1997-N107",26,"第一节 胃食管反流病","促胃肠动力药",1997,107,"B","","吗丁啉",[["A","促进胃排空，增强胃窦和十二指肠运动"],["B","减少胃酸和胃蛋白酶分泌"],["C","促进胃黏膜血流，刺激胃黏液分泌"],["D","防止氢离子反渗，促进胃黏液分泌"],["E","减少胃酸分泌，延缓胃排空"]],"A","吗丁啉又称多潘立酮，为促胃肠动力药，可促进上消化道的蠕动和张力恢复正常，促进胃排空，增加胃窦和十二指肠运动（A对），协调幽门的收缩，同时也能增强食道的蠕动和食道下端括约肌的张力。减少胃酸和胃蛋白酶分泌（B错）、促进胃黏膜血流、刺激胃黏液分泌（C错）为前列腺素衍生物的作用机理。防止氢离子反渗，促进胃黏液分泌（D错）为生胃酮（甘珀酸）的作用机理。减少胃酸分泌、延缓胃排空（E错）为抗胆碱能药，如阿托品、山崀宕碱等的作用机理。","","N"],["1997-N108",27,"第二节 慢性胃炎","慢性胃炎对症治疗",1997,108,"B","","生胃酮",[["A","促进胃排空，增强胃窦和十二指肠运动"],["B","减少胃酸和胃蛋白酶分泌"],["C","促进胃黏膜血流，刺激胃黏液分泌"],["D","防止氢离子反渗，促进胃黏液分泌"],["E","减少胃酸分泌，延缓胃排空"]],"D","生胃酮（甘珀酸）用于治疗慢性胃溃疡，可防止氢离子反渗，促进胃黏液分泌（D对），还可预防胆汁反流，但生胃酮临床上已不常用。促进胃排空，增强胃窦和十二指肠运动（A错）的是外周性多巴胺受体拮抗剂，如吗丁啉（多潘立酮）。能减少胃酸分泌、延缓胃排空（B错）、促进胃黏膜血流，刺激胃黏液分泌（C错）的是前列腺素衍生物。减少胃酸分泌、延缓胃排空（E错）者为抗胆碱能药，如阿托品、山崀宕碱等。","","N"],["1997-N109",17,"第三节 慢性冠状动脉综合症","稳定型心绞痛CTA",1997,109,"B","","对诊断冠心病最有价值",[["A","超声心动图检查"],["B","X线心脏三位相片检查"],["C","心室及冠状动脉造影检查"],["D","漂浮导管检查"],["E","心电图运动负荷试验检查"]],"C","冠心病（十版内科学P232）是冠状动脉粥样硬化引起管腔狭窄或闭塞，导致心肌缺血缺氧或坏死而引起的心脏病，亦称缺血性心脏病。心室及冠状动脉造影检查（C对）可直接了解冠状动脉的形态、堵塞情况，是目前对冠心病诊断最有价值的检查。超声心动图（A错）包括M型超声、二维超声、脉冲多普勒、连续多普勒、彩色多普勒血流显像。是检查心脏和大血管的解剖结构及功能状态的一种首选无创性技术，对心脏肿物、冠心病、心包疾患、高血压性心脏病、肺心病、人工瓣膜随访、大血管疾患也有辅助诊断价值。X线心脏三位相片检查（B错）是指从心脏的胸部后前位片、右前斜位片及左前斜位片三个方位（部分病人必要时加照左侧位片）来观察心脏、大血管的大小与形态、肺血改变。漂浮导管检查（D错）可以测定心脏指数（CI）及肺小动脉楔压（PCWP），直接反映左心功能状况，因此对判断左心功能状况最有价值。心电图运动试验，亦有称心电图运动负荷试验（E错），是通过一定量的运动增加心脏负荷，观察心电图变化，对已知或怀疑患有心血管疾病，尤其是冠状动脉粥样硬化性心脏病（冠心病）进行临床评估的方法。","","N"],["1997-N110",15,"第二节 慢性心力衰竭","有创性血流动力学检查",1997,110,"B","","对左心功能判断最有价值",[["A","超声心动图检查"],["B","X线心脏三位相片检查"],["C","心室及冠状动脉造影检查"],["D","漂浮导管检查"],["E","心电图运动负荷试验检查"]],"D","对于左心功能不全的病人采用漂浮导管检查（D对），可以测定心脏指数（CI）及肺小动脉楔压（PCWP）直接反映左心功能状况，因此对判断左心功能状况最有价值。超声心动图（A错）是检查心脏和大血管的解剖结构及功能状态的一种首选无创性技术，对心脏肿物、冠心病、心包疾患、高血压性心脏病、肺心病、人工瓣膜随访、大血管疾患也有辅助诊断价值。X线心脏三位相片检查（B错）是指从心脏的胸部后前位片、右前斜位片及左前斜位片三个方位来观察心脏、大血管的大小与形态、肺血改变。冠状动脉造影（C错）仍然是诊断冠心病最有价值的检查，虽然为有创检查，但可直接了解冠状动脉的形态、堵塞情况。心电图运动负荷试验（E错）是通过一定量的运动增加心脏负荷，观察心电图变化，对已知或怀疑患有心血管疾病，尤其是冠状动脉粥样硬化性心脏病（冠心病）进行临床评估的方法。","","N"],["1997-N127",2,"第一节 支气管哮喘","通气功能检查",1997,127,"C","","支气管哮喘",[["A","弥散障碍"],["B","第一秒用力呼气率减低"],["C","两者均有"],["D","两者均无"]],"B","支气管哮喘是由多种细胞和细胞组分参与的气道慢性炎症性疾病，支气管哮喘发作时呈阻塞性通气功能障碍，无弥散功能障碍（A错）。由于支气管过度收缩，气道狭窄，表现为呼气性呼吸困难，因此第一秒用力呼气率显著减低（B对）。","","N"],["1997-N128",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病肺功能检查",1997,128,"C","","慢性阻塞性肺气肿",[["A","弥散障碍"],["B","第一秒用力呼气率减低"],["C","两者均有"],["D","两者均无"]],"C","慢性阻塞性肺气肿的病理生理变化是持续气流受限致肺通气功能障碍，使用支气管扩张剂后，FEV₁/FVC＜0.70可确定为持续气流受限，用力肺活量基本不变，第一秒用力呼气容积降低，因此慢性阻塞性肺疾病第一秒用力呼气率降低（B对），随着病情的发展，肺泡壁破裂和毛细血管受压，弥散面积减少，供血减少，通气与血流比例失调与弥散障碍（A对）共同作用，导致换气功能发生障碍。本题AB均对，正确答案为C。","","N"],["1997-N129",28,"第一节 消化性溃疡","H2RA",1997,129,"C","","治疗胃溃疡用",[["A","阿托品"],["B","H₂受体阻滞剂"],["C","两者均可"],["D","两者均不可"]],"C","治疗溃疡主要从抑制胃酸分泌、根除幽门螺旋杆菌和保护胃黏膜三个方面着手（十版内科学P376-P377）。常用的抑酸剂有H₂受体拮抗剂（H₂RA）（B对）和质子泵抑制剂（PPI）。抗胆碱能药物（阿托品）（A错）能抑制迷走神经而减少胃酸分泌、解除平滑肌和血管痉挛、改善局部营养和延缓胃排空，有利于延长制酸药、食物与胃酸中和时间，但抗胆碱能药物可引起胃潴留，增加胃泌素分泌，加重溃疡，因此严格来说，阿托品对胃溃疡也不适用。本题答案应为B，但参考答案为C。","","N"],["1997-N130",28,"第一节 消化性溃疡","H2RA",1997,130,"C","","治疗幽门梗阻用",[["A","阿托品"],["B","H₂受体阻滞剂"],["C","两者均可"],["D","两者均不可"]],"B","抗胆碱药物（阿托品）能松弛平滑肌，延缓胃排空，引起胃窦部潴留，因此对幽门梗阻者不适用（A错）。幽门梗阻的患者一般都有较长的溃疡病史，故抑酸药H₂受体拮抗剂（H₂RA）可用于幽门梗阻的治疗（B对）。","","N"],["1997-N131",52,"第一节 白血病概述","白血病病因和发病机制",1997,131,"C","","急性白血病",[["A","血细胞破坏过多"],["B","造血物质缺乏"],["C","两者均有"],["D","两者均无"]],"D","急性白血病会引起血细胞减少是因为骨髓中造血干细胞异常，白血病细胞恶性克隆性增生，使正常造血受抑制，而与血细胞破坏过多和造血物质的缺乏无关（D对）。血细胞破坏过多是溶血性贫血的表现（十版内科学P560）（A错），造血物质缺乏（B错）可致巨幼细胞贫血（叶酸或维生素B₁₂缺乏）或缺铁性贫血（铁原料缺乏）（十版内科学P549）。","","N"],["1997-N132",47,"第一节 缺铁性贫血","缺铁性贫血病因",1997,132,"C","","缺铁性贫血",[["A","血细胞破坏过多"],["B","造血物质缺乏"],["C","两者均有"],["D","两者均无"]],"B","缺铁性贫血是由于原料铁的缺乏而导致的贫血，主要表现为血红素和血红蛋白合成障碍，根据病因可分为铁摄入不足、供不应求、吸收不良、转运障碍、丢失过多及利用障碍等类型（B对）。红细胞破坏过多性贫血即溶血性贫血（十版内科学P560）（A错）。","","N"],["1997-N133",61,"第二节 糖尿病酮症酸中毒","纠正电解质及酸碱平衡失调",1997,133,"C","","糖尿病酮中毒早期补碱的主要缺点是",[["A","发生脑水肿的可能性大"],["B","发生低血钾、肾功能衰竭的可能性大"],["C","两者均是"],["D","两者均不是"]],"A","糖尿病酮症酸中毒患者经输液和胰岛素治疗后，酮体水平下降，酸中毒可自行纠正，一般不必补碱。早期补碱对机体的危害性：1.早期补碱后，HCO₃⁻会和血液中的氢离子结合生成CO₂，由于CO₂透过血脑屏障的弥散能力大于碳酸氢根，脑脊液pH呈反常性降低，引起脑细胞酸中毒，加重昏迷；2.血pH骤升使氧离曲线左移，血红蛋白和氧的亲和力上升，加重组织缺氧，可诱发或加重脑水肿（A对）；3.促进钾离子向细胞内转移，加重低钾血症和反跳性碱中毒。酮症酸中毒早期补碱一般不会导致肾功能衰竭（B错）。","","N"],["1997-N134",61,"第三节 高渗高血糖综合征","高渗高血糖综合征治疗",1997,134,"C","","糖尿病非酮症高渗昏迷应用小剂量胰岛素治疗",[["A","发生脑水肿的可能性大"],["B","发生低血钾、肾功能衰竭的可能性大"],["C","两者均是"],["D","两者均不是"]],"D","糖尿病非酮症高渗性昏迷患者对胰岛素较敏感，因而胰岛素用量较小，小剂量胰岛素治疗是安全的，一般不会引起脑水肿（A错）、低血钾、低血糖。大剂量胰岛素会使血糖快速降低，而高血糖是维护患者血容量的重要因素，血糖迅速降低而补液不足，将导致血压和血容量进一步下降，可能导致脑水肿、肾功能衰竭（B错）（本题AB均错，正确答案为D）。","","N"],["1997-N151",56,"第二节 原发免疫性血小板减少症","出、凝血及血小板功能检查",1997,151,"X","","下列哪些不支持特发性血小板减少性紫癜的诊断",[["A","出血时间延长"],["B","凝血时间延长"],["C","血小板减少"],["D","骨髓巨核细胞减少"]],"BD","特发性血小板减少性紫癜（ITP）是由于患者对自身血小板抗原的免疫失耐受，产生体液免疫和细胞免疫介导的血小板过度破坏和血小板生成受抑，出现血小板减少（C错）。ITP患者由于血小板减少，骨髓巨核系可代偿性增生，巨核细胞数量正常或增加（D对）。凝血时间（CT）是指血液离开血管，在体外发生凝固的时间。它反映内源性凝血系统的功能，与血小板无关，故ITP患者凝血时间正常（B对）。出血时间（BT）是指人为刺破皮肤毛细血管后，从血液自然流出到自然停止所需的时间。BT测定受血小板的数量和质量、毛细血管结构和功能的影响，ITP患者血小板减少，故出血时间会延长（A错）。","","N"],["1997-N152",44,"第一节 急性肾损伤","肾性AKI",1997,152,"X","","急性肾小管坏死的发病机理有",[["A","肾缺血"],["B","肾中毒"],["C","原尿外漏"],["D","肾小管阻塞"]],"ABCD","近端小管对缺血缺氧十分敏感，肾（小管）缺血（A对）可导致ATP耗竭、细胞骨架瓦解、细胞极性丧失、紧密连接完整性破坏，导致肾小管坏死。肾毒性物质导致的肾中毒（B对）可直接或间接损伤肾小管。肾小管受损伤后，管壁破裂，原尿外漏（C对），造成肾间质水肿，进一步加重肾小管及肾实质损伤。肾小管阻塞（D对）可导致小管内压力升高，压力向上传导，导致肾小球有效滤过压降低，肾小球滤过率进一步降低，加重肾小管坏死。","","N"],["1997-N153",61,"第二节 糖尿病酮症酸中毒","纠正电解质及酸碱平衡失调",1997,153,"X","","糖尿病酮症酸中毒治疗，补碱的指征是",[["A","CO₂结合力小于5mmol/L"],["B","血pH值小于7.1"],["C","血酮体阳性"],["D","血清HCO₃⁻浓度小于5mmol/L"]],"ABD","糖尿病酮症酸中毒（DKA）主要由酮体中酸性代谢产物引起，经输液和胰岛素治疗后，酮体水平下降，酸中毒可自行纠正，一般不必补碱。但严重酸中毒影响心血管、呼吸和神经系统功能，血pH≤6.9（B对）时应给予相应治疗，但补碱不宜过多、过快。糖尿病酮症酸中毒补碱指征为血pH7.1，HCO₃⁻＜5mmol／L（D对），CO₂结合力＜6.7mmol/L（A对）。虽DKA是由酮体中酸性代谢产物引起，但血酮体阳性并不一定有严重酮症酸中毒，因此血酮体阳性不是补碱指征（C错）。关于A选项CO₂结合力的指标九版教材中并未明确说明，廖二元第二版内分泌学P1438中指出，CO₂结合力＜6.7mmol/L时，才予以适当补碱；关于D选项十版教材已删除。故AD选项有争议。","","N"],["1997-N154",75,"第一节 中毒概述","中毒临床表现",1997,154,"X","","急性腐蚀性胃炎是由于吞服",[["A","硝酸"],["B","盐酸"],["C","水杨酸"],["D","亚硝酸盐"]],"AB","急性腐蚀性胃炎的毒物多是由于吞服强酸或强碱类物质而导致的胃黏膜发生变性、糜烂、溃疡或坏死性病变。硝酸（A对）、盐酸（B对）属于强酸类毒物，可直接损伤消化道粘膜，引起急性腐蚀性胃炎。亚硝酸盐（D错）为氧化剂，能使血液中正常携氧的低铁血红蛋白氧化成高铁血红蛋白，因而失去携氧能力而引起组织缺氧，吞服亚硝酸盐引起“肠源性发绀”，属窒息性毒物。水杨酸（C错）属于弱酸，口服后不能引起急性腐蚀性胃炎。注意：这里D选项是亚硝酸盐，而不是亚硝酸，亚硝酸盐属于氧化剂，并不属于强酸，对胃肠道粘膜刺激性较小；另外硫酸也属于强酸，此为本类考题的易错点。","","N"],["1997-N155",16,"第四节 房室交界性心律失常","急性发作期",1997,155,"X","","房室折返性心动过速的治疗，下列哪些是正确的",[["A","静脉注入异搏定"],["B","同步直流电复律"],["C","Valsalva法"],["D","静滴苯肾上腺素"]],"ABCD","房室折返性心动过速患者如果心功能与血压正常，可先尝试使用颈动脉窦按摩、Valsalva动作（C对）、将面部浸入冰水内等刺激迷走神经的方法使心动过速终止，如果未能达到满意效果应进行药物治疗。药物治疗首选腺苷，腺苷治疗无效的改用异搏定（维拉帕米）（A对）、地尔硫䓬等钙通道阻滞剂，疗效可达90%以上。合并低血压者可应用苯肾上腺素（去氧肾上腺素）（D对）等升压药物，在升高血压的同时可通过反射性兴奋迷走神经终止心动过速。当患者出现严重心绞痛、低血压、充血性心力衰竭表现，应立即应用同步直流电复律（B对）。","","N"],["1997-N156",6,"第一节 肺结核","有无活动性",1997,156,"X","","下列哪些病人需要进行抗结核化疗",[["A","男性，40岁，无自觉不适，查体发现慢性血行播散性肺结核，痰中未找到结核菌"],["B","女性，21岁，轻咳一周，右上肺结核球PPD2u（++）"],["C","女性，65岁，低热乏力二周，左上肺云雾状、密度较淡的片状阴影"],["D","男性，30岁，低热一个月，左侧反复气胸，左上肺可见少许密度高、边缘清晰的结节状阴影"]],"ACD","抗结核化疗的适应证是活动性肺结核。A项患者查体发现血行播散性肺结核，结核分枝杆菌可经过血行传播，有传染性，属于活动性肺结核，即使痰菌阴性也应及时治疗（A对）；C项患者出现低热乏力，X线示左上肺云雾状、密度较淡的片状阴影，结合临床表现和胸片，可以诊断为结核病活动期，需要进行抗结核化疗（C对）；D项患者出现低热、反复气胸，左上肺可见少许密度高、边缘清晰的结节状阴影，可怀疑由于结核病发展导致气胸，说明处于结核病活动期，应当及时治疗（D对）；PPD阳性只表明曾经受过结核菌感染，可见于活动性结核的病人及接种过卡介苗的病人，所以B选项患者PPD2u（++）可认为无明确临床意义，且单纯“右上肺结核球”无活动性，无需进行抗结核化疗（B错）。","","N"],["1998-N47",15,"第二节 慢性心力衰竭","左心衰竭症状",1998,47,"A","","左心衰竭最早出现的临床症状是",[["A","疲乏无力"],["B","劳力性呼吸困难"],["C","阵发性夜间呼吸困难"],["D","夜间卧床时咳嗽"],["E","失眠、尿少、头晕"]],"B","左心衰时，心室肌收缩-舒张功能失代偿，左心房内压升高，致使肺静脉及肺毛细血管淤血，表现为不同程度的呼吸困难和咳嗽咯血等症状。其中劳力性呼吸困难是左心衰竭最早出现的症状（B对），因运动使回心血量增加，左心房压力升高，加重肺淤血引起呼吸困难。肺淤血程度与心衰严重程度成正相关，故引起呼吸困难的运动量随心衰程度加重而减少。随心衰程度的加重，呼吸困难依次表现为劳力性呼吸困难，夜间阵发性呼吸困难（C错），端坐呼吸，和急性肺水肿。夜间卧床时咳嗽（D错）是肺泡和支气管黏膜淤血所致，晚于劳力性呼吸困难出现。根据心肌代偿机制，收缩功能障碍较舒张功能障碍出现晚（九版内科学P165），故疲乏无力（A错）、失眠、头晕（E错）等因组织、器官血流灌注不足及代偿性心率加快所致症状的出现，均晚于劳力性呼吸困难。严重的左心衰竭时全身血液重新分配，肾血流量减少，以满足重要器官血液供应，故尿少（E错）及肾功能损害出现较晚。","","N"],["1998-N48",16,"第五节 室性心律失常","室性心动过速心电图特征",1998,48,"A","","下列哪项心电图表现是确定室性心动过速诊断的最主要依据",[["A","QRS波群形态畸形"],["B","心室率100～200次/分"],["C","心室律可稍不规则"],["D","心室夺获与室性融合波"],["E","房室分离"]],"D","QRS波群形态畸形（A错），心室率100～200次/分（B错），心室律可稍不规则（C错）均符合室速的心电图表现，但并不具有特异性，不作为室性心动过速的诊断依据。心室夺获与室性融合波（D对）的存在是确定室性心动过速诊断的最主要依据。室性心动过速的心室夺获表现为P波后提前发生一次正常的QRS波群，当心室部分夺获时可产生室性融合波，表现为QRS波群形态介于正常和异位心室搏动之间。房室分离（即心房独立活动，与QRS波无固定关系）也作为室性心动过速诊断的依据之一，但非最主要依据（E错）。","","N"],["1998-N49",17,"第四节 急性冠状综合征","溶栓疗法",1998,49,"A","","关于急性心肌梗塞溶栓治疗，下列哪项不正确",[["A","心电图出现病理性Q波，不宜再溶栓"],["B","心肺复苏术后，不宜再溶栓"],["C","采用rt-PA溶栓后要随即应用肝素抗凝"],["D","再灌注心律失常出现与否不是溶栓成败的主要标准"],["E","用尿激酶作静脉溶栓，首次剂量宜150万单位"]],"A","急性心肌梗塞心电图的典型表现是出现病理性Q波，近期若无创伤史、外科大手术等禁忌证应立即（接诊患者30分钟内）行溶栓治疗（A错，为本题正确答案）。心肺复苏术后常常合并脑水肿，颅内高压，而溶栓治疗最严重的并发症是颅内出血，增加颅内出血，颅内高压的风险，故不宜再溶栓治疗（B对）。用rt-PA（重组组织型纤维蛋白溶酶原激活剂）前先用肝素5000IU静脉注射，用药后继续以肝素每小时700～1000IU持续静脉滴注共48小时（C对）。溶栓治疗效果判定主要标准是冠状动脉造影，2小时内再灌注心律失常可作为判断标准之一（D对），但不是主要标准。用尿激酶作静脉溶栓，首次剂量150万～200万单位（E对），30min内滴完。","","N"],["1998-N50",17,"第四节 急性冠状综合征","栓塞",1998,50,"A","","关于急性心肌梗塞并发症，下列哪项正确",[["A","乳头肌断裂多见于二尖瓣前乳头肌"],["B","心脏破裂多见于室间隔穿孔破裂"],["C","心室壁瘤多发于心梗后三个月"],["D","急性心梗早期即可伴发肺梗死"],["E","心梗后综合征发生率约为1%～2%"]],"D","急性心肌梗塞并发症包括：1.栓塞：发生率1%～6%，见于起病后1～2周，可因下肢静脉血栓形成部分脱落所致，产生肺动脉栓塞，而引起肺梗死（D对）；2.乳头肌功能失调或断裂：乳头肌整体断裂极少见，多发生在二尖瓣后乳头肌（A错），见于下壁MI，心力衰竭明显，可迅速发生肺水肿在数日内死亡；3.心脏破裂：多为心室游离壁破裂，造成心包积血引起急性心脏压塞而猝死。偶为心室间隔破裂造成穿孔（B错）；4.心室壁瘤：发生率5%～20%，主要见于左心室，多在起病数周后被发现，急性室壁瘤在MI后数日可形成（C错），可导致心功能不全、栓塞和室性心律失常；5.心肌梗死后综合征：发生率约1%～5%（E错）（10版内科学P253：心肌梗死后综合征发生率为1%-3%）。","","N"],["1998-N51",15,"第二节 慢性心力衰竭","扩血管药物",1998,51,"A","","血管扩张剂在心功能不全患者中的应用，下列哪项不正确",[["A","先天性心脏病室间隔缺损患者宜应用"],["B","二尖瓣狭窄患者宜应用"],["C","主动脉瓣关闭不全患者宜应用"],["D","严重冠状动脉狭窄患者应慎用"],["E","血容量不足者应禁用"]],"B","二尖瓣狭窄导致左心房需要更大压力才能使左心房内血液流向左心室，流入左室的血量减少，从左室射出的血流量锐减，如再应用扩张小动脉药物，极易引起有效循环血流量不足而引起低血压、休克等症状，故不宜应用（B错，为本题正确答案）。先天性心脏病室间隔缺损患者应用（A对）血管扩张剂，可降低外周阻力，左心室射血阻力下降，左向右分流减少，有利于改善心功能。主动脉瓣关闭不全时，在患者左心室射血结束开始舒张时，血液反流进入左心室，导致患者舒张末压迅速升高，射血速度及射血量加大导致心悸、心前区不适、头颈部剧烈动脉波动感等。给予扩血管药物后，会减少血液反流，增加外周血供，减轻患者症状，故宜应用（C对）。冠脉的供血主要来自舒张期血供，舒张压下降导致冠脉血供下降，严重冠状动脉狭窄患者应用血管扩张剂可能会加剧远端心肌的缺血，故选用血管扩张剂时需要选用扩张静脉与冠脉类药物，如硝酸甘油（十版内科学P271）。若同时选用扩张动脉药物，如硝普钠（十版内科学P271），会导致冠脉进一步缺血，故严重冠状动脉狭窄患者应慎用（D对）。血容量不足者禁用扩血管药（E对），因为此类药物会进一步导致血容量不足，须在补充血容量的基础上方可酌情应用。","","N"],["1998-N52",15,"第一节 心力衰竭总论","Frank-Starling机制",1998,52,"A","","有关舒张性心力衰竭，下列哪项不正确",[["A","可与收缩功能障碍同时出现"],["B","可早于收缩功能障碍出现"],["C","可晚于收缩功能障碍出现"],["D","心搏量降低，LVEF正常"],["E","与心肌肌浆网摄取钙离子能力减低有关"]],"C","心功能不全时心脏通过Frank-Starling机制、神经体液调节及心肌肥厚等代偿机制，保证泵出组织代谢所需的相应的血量，使收缩功能处于正常范围。在这过程中，由于细胞核和线粒体的增大、增多均落后于心肌的纤维化，导致心肌供能不足，心肌肌浆网摄取钙离子能力减低（E对），导致主动舒张功能障碍，与此同时，心肌肥厚导致心肌顺应性下降，舒张功能降低，心室充盈障碍，心搏量降低，而LVEF（为左室射血分数）值正常（D对），故表现为舒张性心力衰竭早于收缩功能障碍出现（B对），也可与收缩功能障碍同时出现（A对），但是舒张性心力衰竭的出现不可能晚于收缩功能障碍（C错，为本题正确答案）。","","N"],["1998-N53",18,"第一节 原发性高血压","血管紧张素转换酶抑制剂",1998,53,"A","","血管紧张素转换酶抑制剂治疗高血压病的机理，下列哪项不正确",[["A","使血管紧张素Ⅱ生成减少"],["B","抑制激肽酶Ⅱ的作用"],["C","间接使PGI₂合成增多"],["D","NO合成减少"],["E","抑制交感神经活性"]],"D","血管紧张素转换酶抑制剂（ACEI）降压机制如下：抑制ACE，使AngⅠ（血管紧张素Ⅰ）转变为AngⅡ（血管紧张素Ⅱ）减少（A对），从而产生血管舒张；同时减少醛固酮分泌，以利于排钠；特异性肾血管扩张亦加强排钠作用；抑制激肽酶Ⅱ（B对）从而抑制缓激肽的降解，使缓激肽增多；抑制交感神经系统活性（E对）（九版药理学 P231）。体内缓激肽增多后，可激活激肽B₂受体而使PGI₂（前列环素）（C对）和NO合成增加（D错，为本题正确答案），发挥其舒张血管作用而降低血压。","","N"],["1998-N54",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病肺功能检查",1998,54,"A","","下列哪项肺功能检查结果不符合阻塞性通气功能障碍",[["A","VC减低或正常"],["B","RV增加"],["C","TLC正常或增加"],["D","FEV₁/FVC减低"],["E","MMFR正常"]],"E","呼吸运动时，气道管径变化与肺组织的运动失去协调，使气道开放不足或提前关闭，气流通过气道时阻力增加，即阻塞性通气功能障碍。VC（肺活量）是指一次尽力吸气后，再尽力呼出的气体总量，反映肺一次通气的最大能力。阻塞性通气功能障碍对肺活量的影响较小，VC正常或减低（A对）。阻塞性通气功能障碍病变早期多不累及肺泡，TLC（肺总量）正常（C对）。随着病情程度的发展，肺组织弹性会逐渐减退，肺泡持续扩大，出现回缩障碍，气体排出减少，进而可导致RV（残气量）增加（B对）和TLC增加（C对）。阻塞性通气障碍时，FEV₁（第一秒用力呼气的容积）的降低比FVC（用力呼气的总容积）变化更明显，故FEV₁/FVC减低（D对）。MMFR（最大呼气中期流速）是指将气体用最快速度呼出的能力，由于阻塞性通气功能障碍导致气流通过气道的阻力增加，MMFR减低（E错，为本题正确答案）。","","N"],["1998-N55",10,"第三节 慢性肺源性心脏病","慢性肺源性心脏病心电图检查",1998,55,"A","","有关慢性肺源性心脏病的心电图诊断，下列哪项不正确",[["A","应有右心肥大的心电图改变"],["B","应有肺型P波"],["C","V₁至V₃导联可出现QS波"],["D","肢导低电压可有可无"],["E","可见间歇性右束支传导阻滞"]],"B","肺源性心脏病是指由支气管-肺组织、胸廓或肺血管病变致肺血管阻力增加，产生肺动脉高压，继而右心室结构和功能改变的疾病。由于肺循环压力增高，可致右心室重塑，右心室肥大心电图（A对）下可表现为：①额面平均电轴≥+90°；②V₁ R/S≥1；③重度顺钟向转位（V₅ R/S≤1）；④RV₁+SV₅≥1.05mV；⑤aVR R/S或R/Q≥1；⑥V₁～V₃呈QS、Qr或qr（酷似心肌梗死，应注意鉴别）（C对）；⑦可有肺型P波（B错，为本题正确答案），右心房肥大时可出现肺型P波，但不是应有肺型P波；⑧可见肢导低电压（D对）及右束支传导阻滞（E对）。","","N"],["1998-N56",2,"第一节 支气管哮喘","支气管哮喘临床表现",1998,56,"A","","危重症哮喘患者的临床表现，下列哪项不正确",[["A","呈现腹式呼吸"],["B","双肺哮鸣音响亮"],["C","血压下降"],["D","有奇脉"],["E","意识模糊"]],"B","支气管哮喘急性发作时根据严重程度可分为轻度、中度、重度和危重，在危重期，患者不能讲话，嗜睡或意识模糊（E对），胸腹矛盾运动（A）（本题A选项表述不当），哮鸣音较弱甚至消失，出现“沉默肺（Silence Chest）”（B错，为本题正确答案），脉率变慢或不规则，出现严重的低氧血症和高二氧化碳血症，出现酸中毒（pH降低）。危重期患者静脉回心血血量明显减少，心肌收缩力减低，血压下降（C对）（血压下降是病情严重程度的指标）。在重度哮喘时，因肺泡过度通气，用力呼气时，胸膜腔内压更高，右心回心血量减少，在强有力的负压吸气期，回心血量增加，右心充盈，室间隔移向左心室，致使舒张期左心室充盈不全，同时吸气期巨大负压不利于收缩期心室排空，相当于心室后负荷增加，使吸气期收缩压下降，出现奇脉，但是当哮喘极重度发作时（危重期），呼吸肌过度疲劳，患者呼吸变得浅快而不能使胸腔内压大幅度波动时，奇脉就会消失（D错）。需要注意的是，只要符合某一严重程度的某些指标，而不需满足全部指标，即可提示该级别的急性发作，故本题D选项有争议。","","N"],["1998-N57",2,"第一节 支气管哮喘","糖皮质激素",1998,57,"A","","关于用肾上腺糖皮质激素治疗迟发性哮喘的机制，下列哪项不正确",[["A","抑制磷酸脂酶A₂"],["B","抑制前列腺素、血小板活化因子合成"],["C","抑制组织胺脱羧酶，减少组织胺形成"],["D","抑制小血管收缩，减少渗出和炎症细胞浸润"],["E","增加β受体数量"]],"D","糖皮质激素是治疗哮喘最有效的药物。其主要作用机制为：①抑制炎症细胞的迁移和活化。②抑制细胞因子（如血小板活化因子）（B对）的生成。③抑制炎症介质的生成和释放：抑制磷脂酶A₂，从而影响花生四烯酸、前列腺素的生成（AB对）；抑制组织胺脱羧酶，减少组织胺形成（C对）。④促使小血管收缩，减少渗出和炎症细胞的浸润（D错，为本题正确答案）（八版药理学P335）；⑤糖皮质激素可以增强支气管平滑肌细胞β₂受体的反应性，但不能增加β受体数量（E错），本题答案应为DE，但参考答案为D。","","N"],["1998-N58",13,"第三节 慢性呼吸衰竭","呼吸兴奋剂",1998,58,"A","","呼吸衰竭时，CO₂潴留，应用呼吸兴奋剂治疗，下列哪项叙述不正确",[["A","病因以中枢抑制为主，疗效好"],["B","病因以呼吸肌疲劳为主，亦有效"],["C","病因以神经传导系统病变为主，疗效好"],["D","病因以呼吸肌病变为主，疗效差"],["E","病因以广泛间质纤维化为主，不宜使用"]],"C","呼吸兴奋剂通过刺激外周或中枢化学感受器兴奋呼吸中枢，使呼吸加深加快，通气量增加，改善呼吸衰竭，主要适用于以中枢抑制为主的呼吸衰竭（A对）；呼吸兴奋剂可增加呼吸肌做功，对病因以呼吸肌疲劳为主的疾病，亦有效（B对）；使用时须保证呼吸肌功能基本正常，故对病因以呼吸肌病变为主的疾病，疗效差（D对）；病因以广泛间质纤维化为主的疾病，主要表现为换气障碍，用呼吸兴奋剂不能改善症状，反而使呼吸肌过度做功，增加氧耗，故不宜使用（E对）；病因以神经传导系统病变为主的疾病，因呼吸兴奋剂对改善肌肉神经传导无效，所以疗效差（C错，为本题正确答案）。","","N"],["1998-N59",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎克雷伯杆菌肺炎诊断",1998,59,"A","","男性，50岁，一天来寒战高热（39.6℃），咳嗽伴左胸痛，咳痰呈砖红色胶冻状，量多，查体轻度紫绀，BP10.7/6.7KPa（80/50mmHg），左肺叩浊，呼吸音低，X线胸片左肺呈多发性蜂窝状阴影，最可能的诊断为",[["A","肺炎球菌肺炎，休克型"],["B","葡萄球菌肺炎"],["C","厌氧菌肺炎"],["D","军团菌肺炎"],["E","克雷伯杆菌肺炎"]],"E","患者寒战高热，咳嗽伴左胸痛，咳痰呈砖红色胶冻状，查体血压80/50mmHg左肺叩诊浊音，X线胸片左肺呈多发性蜂窝状阴影，应考虑克雷伯杆菌肺炎（E对）。克雷伯杆菌肺炎主要表现为寒战、高热、全身衰竭，典型的痰液为砖红色胶冻状，特征性的X线为蜂窝状阴影，叶间隙下坠；肺炎球菌肺炎（A错）主要表现为急性寒战、高热、胸痛，痰液呈铁锈色，特征性的X线为肺叶或肺段实变；葡萄球菌肺炎（B错）主要表现为急性寒战、高热、脓痰，痰中常有血丝，特征性的X线影像为单个或多发的液气囊腔及阴影的易变性；厌氧菌肺炎（C错）典型表现为突然畏寒高热，体温达39℃以上，伴咳嗽、咳黏液或黏液脓恶臭痰，特征性的X线为支气管肺炎、脓胸、脓气胸、多发性肺脓肿；军团菌肺炎（D错）患者常有疲乏、无力、肌痛、畏寒、发热等全身性表现，咳嗽咳痰，咳黏痰带少量血丝或血痰，量少，不呈脓性，特征性的X线为下叶斑片浸润影。","","N"],["1998-N60",6,"第一节 肺结核","结核病免疫和迟发性变态反应",1998,60,"A","","有关出现结核病变态反应，下列哪项是错误的",[["A","常发生于原发结核感染的病人"],["B","多发生于结核菌侵入人体后4～8周"],["C","局部可出现渗出性炎症，但不出现干酪样坏死"],["D","结核菌素试验呈阳性"],["E","可出现皮肤结节性红斑"]],"C","结核菌侵入人体后，体内免疫细胞对结核菌及其代谢产物所发生的敏感反应称为变态反应，属于迟发型（Ⅳ型）变态反应。结核分枝杆菌首次侵入人体开始繁殖时，人体发生变态反应，并通过特异性免疫阻止其播散繁殖，使机体产生免疫力，经过变态反应和免疫力之间的复杂作用，表现出不同的症状。变态反应在感染后需要4～8周才能建立（B对），表现为结核菌素试验阳性（D对），可出现皮肤结节性红斑（E对）。再次感染结核时，致敏的T淋巴细胞就释放出各种炎性因子和淋巴因子，使局部出现红肿和表浅溃疡，当结核分枝杆菌毒力强、感染菌量多、机体免疫力不足以抵抗时会出现干酪样坏死（C错，为本题正确答案）。迟发性超敏反应常见于成人的原发后感染（继发感染）（九版医学微生物学P160）（A），卡介苗接种为原发感染，也能出现迟发性超敏反应。A选项不严谨，参考答案为C。","","N"],["1998-N61",56,"第二节 原发免疫性血小板减少症","原发免疫性血小板减少症病因和发病机制",1998,61,"A","","引起ITP病人出血的机制中，下列哪项最不可能",[["A","血小板破坏过多"],["B","血小板生成减少"],["C","毛细血管壁通透性增加"],["D","血小板第3因子异常"],["E","血小板功能异常"]],"D","特发性血小板减少性紫癜（ITP）出血的机制是由于患者对自身血小板抗原的免疫失耐受，产生体液免疫和细胞免疫介导的血小板过度破坏（A错）和血小板生成受抑（B错），而导致血小板减少，但血小板的功能一般正常（E对）。ITP患者有毛细血管壁通透性增高，也可导致出血（C错）。血小板第3因子（PF3）活性降低见于血小板无力症，在ITP患者中PF3一般正常（D对）。根据十版内科学观点，本题答案应为DE，但参考答案为D。","","N"],["1998-N62",50,"第一节 溶血性贫血概述","溶血性贫血实验室检查",1998,62,"A","","下列哪项检查对鉴别血管内溶血和血管外溶血无帮助",[["A","血浆游离血红蛋白"],["B","血浆结合珠蛋白"],["C","血中破碎红细胞"],["D","尿隐血试验"],["E","尿Rous试验"]],"B","结合珠蛋白能与血浆中的血红蛋白结合形成稳定的复合物。血清结合珠蛋白为血管内溶血的实验室检查，但在血管外溶血时，其也可降低，因此无法用来鉴别血管内和血管外溶血（B对）。血浆游离血红蛋白（A错）、血中破碎红细胞（C错）可区分血管内溶血和血管外溶血：血管内溶血时，红细胞在血液循环中被破坏，释放出游离的血红蛋白，血液中可见破碎红细胞；而血管外溶血时，红细胞是经过脾脏的单核-巨噬细胞系统被吞噬处理的，一般没有游离的血红蛋白，血液中无破碎红细胞。尿隐血试验（D错）是检验尿中是否有红细胞或血红蛋白，可区分血管内溶血和血管外溶血：血管内溶血时会有血红蛋白尿，尿隐血试验阳性；血管外溶血尿隐血试验阴性。Rous试验（E错）即尿含铁血黄素试验，原理为血红蛋白通过肾滤过，部分铁离子以含铁血黄素的形式随尿液排出，在酸性环境下产生普鲁士蓝色的亚铁氰化铁沉淀（蓝色颗粒），可区分血管内溶血和血管外溶血：血管内溶血时，血浆中有游离血红蛋白，Rous试验阳性；血管外溶血时，血浆中一般没有游离血红蛋白，Rous试验阴性。","","N"],["1998-N63",52,"第二节 急性白血病","AML诱导缓解治疗",1998,63,"A","","急性早幼粒细胞性白血病的分化诱导剂治疗，通常首选下列哪一种",[["A","十三顺式维甲酸"],["B","全反式维甲酸"],["C","罗钙全"],["D","α-D₃"],["E","小剂量阿糖胞苷"]],"B","急性早幼粒细胞白血病（M₃型）首选全反式维甲酸（B对）诱导分化，其应用大大降低患者死亡率。但缓解后单用全反式维甲酸易复发，故常与蒽环类和砷剂联合或交替使用。其他各项虽都有效，但疗效均较差（ACDE错）。","","N"],["1998-N64",40,"第三节 急进性肾小球肾炎","急进性肾小球肾炎临床表现",1998,64,"A","","急进性肾炎临床最突出的表现是",[["A","水肿"],["B","高血压"],["C","少尿或无尿"],["D","肾病综合征"],["E","心包摩擦音"]],"C","急进性肾小球肾炎是以急性肾炎综合征、肾功能急剧恶化、多在早期出现少尿性急性肾衰竭为临床特征的肾小球疾病，其中少尿或无尿为其突出表现（C对），病理类型为新月体性肾小球肾炎。水肿（A错）、高血压（B错）可出现于急进性肾炎，但并非临床最突出表现。肾病综合征（D错）典型表现为大量蛋白尿、低蛋白血症、水肿及高脂血症，在儿童多见于微小病变型肾病，在成人多见于膜性肾病（十版内科学P481-P483）。心包摩擦音（E错）可见于尿毒症性心包炎，为慢性肾衰竭晚期并发症之一。","","N"],["1998-N65",40,"第五节 肾病综合征","利尿消肿",1998,65,"A","","肾病综合征常用如下利尿剂治疗，其中哪种利尿剂分类是错误的",[["A","呋噻米为噻嗪类利尿剂"],["B","氨苯喋啶为潴钾利尿剂"],["C","丁尿胺为袢利尿剂"],["D","不含钠的低分子右旋糖酐为渗透性利尿剂"],["E","螺内酯为潴钾利尿剂"]],"A","利尿消肿是肾病综合征常用的对症治疗，药物治疗一般包括5种类型：①噻嗪类利尿剂，常用的有氢氯噻嗪；②潴钾利尿剂，常用的有氨苯喋啶（B对）、螺内酯（E对）；③袢利尿剂，常用的有呋塞米（A错，为本题正确答案）、布美他尼（丁尿胺）（C对）；④渗透性利尿剂，常用的有不含钠的低分子右旋糖酐（D对）；⑤提高血浆胶体渗透压（当患者出现严重低蛋白血症伴水肿而又少尿时适用）。","","N"],["1998-N66",45,"第一节 慢性肾衰竭","心血管系统表现",1998,66,"A","","关于慢性肾衰伴发心脏扩大的原因，下列哪项是错误的",[["A","水钠潴留"],["B","高血压"],["C","尿毒症性心肌病变"],["D","心包积液"],["E","严重贫血"]],"D","慢性肾衰竭时，心包积液患者常见，心包积液患者的心影可以扩大，但心脏一般无实质性扩大（D错，为本题正确答案）。水钠潴留（A对）、高血压（B对）可引起左心室肥厚，晚期可导致心脏扩大；尿毒症性心肌病（C对）与代谢废物的潴留及贫血等因素有关，可导致心力衰竭，引起心脏扩大；贫血（E对）会引起心高搏出量状态，加重左心室负荷和左心室肥厚，导致心脏扩大。","","N"],["1998-N67",60,"第一节 库欣综合征","依赖ACTH的库欣综合征",1998,67,"A","","Cushing病是指下列哪种病因引起的皮质醇增多症",[["A","原发于肾上腺本身的肿瘤"],["B","垂体分泌ACTH过多"],["C","垂体外癌瘤产生ACTH"],["D","不依赖ACTH的双侧肾上腺结节性增生"],["E","大剂量应用糖皮质激素"]],"B","Cushing病（库欣病）属于依赖ACTH的库欣综合征，是指垂体分泌过多ACTH所引起的Cushing综合征（B对），伴肾上腺皮质增生。垂体外癌瘤产生ACTH（C错）引起的皮质醇增多症属于异位ACTH综合征。原发于肾上腺本身的肿瘤（A错）引起的皮质醇增多症属于不依赖ACTH的综合征。不依赖ACTH的双侧肾上腺结节性增生（D错）引起的皮质醇增多症属于不依赖ACTH的综合征。大剂量应用糖皮质激素（E错）引起的库欣综合征属于药源性库欣综合征。","","N"],["1998-N68",59,"第一节 甲状腺功能亢进症","淡漠型甲亢",1998,68,"A","","关于淡漠型甲亢，下列哪项是错误的",[["A","多见于老年人"],["B","病人乏力、明显消瘦"],["C","可仅表现为阵发性或持续性心房纤颤"],["D","不易发生甲状腺危象"],["E","眼征、甲状腺肿和高代谢症候群均不明显"]],"D","淡漠性甲亢是甲状腺功能亢进中的一个特殊类型，甲状腺毒症和甲亢体征不明显，是以消瘦、淡漠、嗜睡为特征的甲亢。其特点为：①多见于老年患者，起病隐匿，症状不典型（A对）；②全身症状较重，病人乏力、明显消瘦，抑郁淡漠，有时神志模糊，甚至昏迷，易被漏诊、误诊（B对）；③眼病和高代谢症群表现较少，甲状腺常不肿大（E对），但甲状腺结节的发生率较高（尤其是女性患者）；④临床表现不典型，常仅有某一系统的典型表现，尤其是循环系统及消化系统。甲状腺激素可增加心脏β受体对儿茶酚胺的敏感性，使心肌自律性提高，可出现心动过速；亦可因异位起搏点兴奋性提高导致窦性节律丧失，可仅表现为阵发性房颤或持续性心房纤颤（C对）。由于淡漠型甲亢常发生于老年患者，症状不明显，易被漏诊及误诊，患者对疾病警惕性亦较低，容易发生甲状腺危象（D错，为本题正确答案）。","","N"],["1998-N69",25,"","",1998,69,"A","","胆汁淤积性黄疸时，下列哪项正确",[["A","血清总胆固醇降低"],["B","血清结合胆红素降低"],["C","血清碱性磷酸酶降低"],["D","血清γ-谷氨酰转肽酶降低"],["E","尿胆原降低"]],"E","胆汁淤积性黄疸由于肝内、外胆汁淤积，胆汁排入肠道受阻，肠道中胆素原减少，尿胆原生成减少，由肠肝循环而进入门静脉血中的尿胆原也减少，故尿胆原和粪胆原减少或消失（E对）。胆汁淤积性黄疸时由于胆汁排出受阻而反流入血，因此胆汁中总胆固醇排出受阻而血清总胆固醇（A错）升高、胆汁中结合胆红素排出受阻因此血清结合胆红素（B错）升高、血清中大部分碱性磷酸酶来自肝脏与骨骼，胆道疾病致胆汁淤积时可能由于碱性磷酸酶产生过多而排泄减少，引起血清碱性磷酸酶（C错）升高、γ-谷氨酰转肽酶在肝脏中广泛分布于肝细胞的毛细胆管一侧和整个胆管系统，因此胆汁排出受阻时，血清中γ-谷氨酰转肽酶（D错）升高。","","N"],["1998-N70",30,"第一节 溃疡性结肠炎","疾病分期",1998,70,"A","","下列哪一项不符合重度溃疡性结肠炎",[["A","腹泻每日6次以上"],["B","体温达38℃以上"],["C","脉搏在90次/分以上"],["D","血沉大于30mm/第1小时"],["E","血红蛋白在105g/L以下"]],"B","溃疡型结肠炎按病情严重程度可分为三度：轻度，最常见，腹泻次数＜4次，粪便多成形，血、脓和黏液较少，腹痛程度较轻，全身症状和体征较少，血沉和白蛋白正常；重度：起病急骤，有显著腹泻，大便次数＞6次（A对），有明显黏液脓血便，体温＞37.8℃（B错，为本题正确答案）、脉搏＞90次/分（C对），血红蛋白＜105g/L（E对），血沉＞30mm/h（D对）；中度：介于轻、重度之间。","","N"],["1998-N71",35,"","",1998,71,"A","","下列哪种肝硬化引起肝性脑病最多见",[["A","酒精性肝硬化"],["B","原发性胆汁性肝硬化"],["C","淤血性肝硬化"],["D","肝炎后肝硬化"],["E","血吸虫病性肝硬化"]],"D","肝性脑病（十版内科学P420）又称肝性昏迷，大部分由肝硬化引起。肝硬化类型包括：酒精性肝硬化（A）、原发性胆汁性肝硬化（B）、淤血性肝硬化（C）、肝炎后肝硬化（D）、血吸虫病性肝硬化（E），其中最常见的是肝炎后肝硬化。故肝炎后肝硬化引起的肝性脑病最为常见（D对）。","","N"],["1998-N72",30,"第二节 克罗恩病","克罗恩病并发症",1998,72,"A","","克罗恩（Crohn）病最常见的并发症是",[["A","腹腔内脓肿"],["B","吸收不良综合征"],["C","肠梗阻"],["D","大量便血"],["E","发生癌变"]],"C","克罗恩病的病变可累及肠壁全层致肠腔狭窄（十版内科学P392），因此最常见的并发症为肠梗阻（C对）。其形成的溃疡深而呈裂隙状，可穿透肠壁形成腹腔内脓肿（A错），偶可发生急性穿孔和大量便血（D错）。克罗恩病多见于末端回肠和邻近结肠，直肠或结肠黏膜较少受累，直肠或粘膜受累者可发生癌变，发生癌变少见（E错）。吸收不良综合征是一种因小肠对营养物质消化、吸收功能障碍，造成营养物质不能正常吸收，而从粪便中排泄，引起营养物质缺乏的临床综合征。克罗恩病病变主要位于末端回肠和邻近结肠，累及小肠者少见，因此较少影响到小肠的消化吸收功能，吸收不良综合征少见（B错）。","","N"],["1998-N73",27,"","",1998,73,"A","","关于A型胃炎，下列哪项是正确的",[["A","较常见"],["B","大多数由幽门螺杆菌感染引起"],["C","病变主要累及胃体和胃底"],["D","发病与遗传素质无关"],["E","最终不易导致恶性贫血"]],"C","慢性萎缩性胃炎分为自身免疫性胃炎（A型胃炎、慢性胃体炎）和多灶萎缩性胃炎（B型胃炎、慢性胃窦炎）。A型胃炎少见（A错），属于自身免疫性疾病，其发病与遗传素质有关（D错），主要由自身免疫反应引起（B错），病变主要发生在胃体部或胃底部（C对）；B型胃炎多见，大多数由幽门螺杆菌感染引起，多累及胃窦部。由于壁细胞主要分布在胃底和胃体，其功能主要是分泌胃酸和内因子，内因子可促进维生素B₁₂的吸收，因此A型胃炎患者由于胃体受累，内因子分泌减少，维生素B₁₂吸收障碍，易导致巨幼细胞贫血（恶性贫血）（E错）。","","N"],["1998-N74",28,"第一节 消化性溃疡","癌变",1998,74,"A","","关于消化性溃疡的癌变，下列哪项是正确的",[["A","各种消化性溃疡均有癌变可能"],["B","癌变发生于溃疡边缘"],["C","癌变率可达1%以上"],["D","症状经严格的4周内科治疗无改善"],["E","癌变率与年龄无关"]],"B","有＜1%胃溃疡患者发生癌变（C错），而十二指肠溃疡一般不发生癌变（A错）。溃疡边缘（B对）细胞增生修复活跃，为胃溃疡癌变的好发部位。一般情况下，症状顽固而经8周以上内科治疗无效者应考虑癌变可能（D错），长期慢性GU病史、年龄在45岁以上的患者，癌变率增加（E错）。","","N"],["1998-N103",16,"第七节 抗心律失常药物的合理应用","Ⅰ类",1998,103,"B","","不减慢Vmax，稍减慢传导，缩短动作电位时间",[["A","普罗帕酮"],["B","奎尼丁"],["C","丙吡胺"],["D","利多卡因"],["E","胺碘酮"]],"D","利多卡因（D对）属ⅠB类药物，不减慢或轻度减慢Vmax，稍减慢传导，缩短动作电位时间。普罗帕酮（A错）属ⅠC类药，减慢Vmax，减慢传导与轻微延长动作电位时限。奎尼丁（B错）和丙吡胺（C错）等属ⅠA类药物，减慢动作电位0相上升速度（Vmax），延长动作电位时限。胺碘酮（E错）属Ⅲ类药，阻断钾通道与延长复极。","","N"],["1998-N104",16,"第七节 抗心律失常药物的合理应用","Ⅰ类",1998,104,"B","","明显减慢Vmax，显著减慢传导，轻微延长动作电位时间",[["A","普罗帕酮"],["B","奎尼丁"],["C","丙吡胺"],["D","利多卡因"],["E","胺碘酮"]],"A","普罗帕酮（A对）属ⅠC类药，明显减慢Vmax，显著减慢传导与轻微延长动作电位时限。奎尼丁（B错）和丙吡胺（C错）等属ⅠA类药物，减慢动作电位0相上升速度（Vmax），延长动作电位时限。利多卡因（D错）属ⅠB类药物，不减慢或轻度减慢Vmax，稍减慢传导，缩短动作电位时间。胺碘酮（E错）属Ⅲ类药，阻断钾通道与延长复极。","","N"],["1998-N105",52,"第三节 慢性髓系白血病","干扰素",1998,105,"B","","为使慢性粒细胞性白血病达细胞遗传学缓解，应首选",[["A","α-干扰素"],["B","羟基脲"],["C","马法仑"],["D","马利兰"],["E","甲基苄肼"]],"A","羟基脲、马利兰（白消安）和干扰素常用于治疗慢性粒细胞白血病。羟基脲（十版内科学P587）（B错）、马利兰（白消安）（D错）只能控制白细胞的数量，不能使慢性粒细胞白血病获得遗传学缓解，干扰素可以使之达到遗传学缓解，是分子靶向药物出现之前的首选药物（A错）。马法仑（美法仑）（十版内科学P603）（C错）用于治疗多发性骨髓瘤。甲基苄肼（丙卡巴肼）（十版内科学P593）（E错）用于治疗霍奇金病。近些年，由于分子靶向药物的开发与应用及其良好治疗效果，第一代酪氨酸激酶抑制剂（TKI）甲磺酸伊马替尼已作为治疗慢性粒细胞白血病的首选药物（十版内科学P586）。根据九版内科学观点，本题无正确答案，但参考答案为A。","","N"],["1998-N106",54,"第一节 多发性骨髓瘤","多发性骨髓瘤治疗",1998,106,"B","","多发性骨髓瘤治疗首选",[["A","α-干扰素"],["B","羟基脲"],["C","马法仑"],["D","马利兰"],["E","甲基苄肼"]],"C","MPT方案（美法仑/泼尼松/沙利度胺）（十版内科学P603）。MPT方案（马法仑＋泼尼松＋沙利度胺）（八版内科学P605）为治疗多发性骨髓瘤的首选方案（C对）。羟基脲（B错）、马利兰（白消安）（D错）和α-干扰素（A错）常用于治疗慢性粒细胞白血病（十版内科学P586-P587）。甲基苄肼（丙卡巴肼）（十版内科学P593）（E错）主要用于治疗霍奇金淋巴瘤。","","N"],["1998-N107",62,"","",1998,107,"B","","诊断胰岛素瘤有意义的试验是",[["A","高渗盐水试验"],["B","水利尿试验"],["C","螺内酯试验"],["D","饥饿试验"],["E","酚妥拉明试验"]],"D","胰岛素瘤主要表现为禁食后低血糖、发作时血糖＜2.8mmol/L、给予葡萄糖后缓解，可用持续饥饿试验诱发（D对），若禁食后24～36小时出现低血糖和胰岛素分泌增多，则诊断为胰岛素瘤。螺内酯试验（C错）可把原发性醛固酮增多症和失钾性肾病区分开。高渗盐水试验（A错）主要用于诊断尿崩症。水利尿试验（B错）主要用于测定肾脏对体液平衡调节的能力。酚妥拉明试验（E错）主要用于诊断嗜铬细胞瘤。","","N"],["1998-N108",60,"第二节 原发性醛固酮增多症","原发性醛固酮增多症鉴别诊断",1998,108,"B","","鉴别原发性醛固酮增多症与失钾性肾病的试验是",[["A","高渗盐水试验"],["B","水利尿试验"],["C","螺内酯试验"],["D","饥饿试验"],["E","酚妥拉明试验"]],"C","螺内酯试验：观察服药前后血钾、血钠、24h尿钾排泄量变化，以血钾为主要评定指标。原发性醛固酮增多症服药后血钾浓度比对照值显著升高，达到或接近正常，为试验阳性；而失钾性肾病服药后血钾浓度变化不大，为试验阴性。此试验可把原发性醛固酮增多症和失钾性肾病区分开（C对）。48～72小时饥饿试验（十版内科学P751）（D错）主要用于诊断胰岛素瘤。正常人静脉滴注高渗盐水后，血浆渗透压升高，兴奋下丘脑渗透感受器，促使垂体后叶抗利尿激素大量释放，随即尿量减少，尿崩症患者由于ADH缺乏，滴注高渗盐水后，尿量不减少，高渗盐水试验（A错）主要用于诊断尿崩症。一次大量饮水1000ml以上，会引起尿量增多的现象，称为水利尿，水利尿试验（B错）主要用于测定肾脏对体液平衡调节的能力。酚妥拉明为α受体阻滞剂，酚妥拉明试验（E错）主要用于诊断嗜铬细胞瘤。","","N"],["1998-N109",27,"第二节 慢性胃炎","慢性胃炎胃镜及组织学病理",1998,109,"B","","B型胃炎伴大量G细胞丧失",[["A","胃酸度升高"],["B","胃酸度正常或减少"],["C","胃酸度常减少"],["D","胃酸度明显升高"],["E","胃酸度明显减少"]],"C","B型胃炎表现为萎缩性改变，在胃内呈多灶性分布，以胃窦部为主，多由幽门螺杆菌感染引起，这种类型的胃炎由于胃窦部病变，导致大量G细胞丧失，使胃泌素分泌减少，从而引起胃酸分泌减少（C对）。胃酸分泌增加（A错）见于十二指肠溃疡。胃酸度正常或减少（B错）见于胃溃疡、多灶萎缩性胃炎。胃酸分泌明显增加（D错）见于胃泌素瘤。胃酸度明显减少（E错）见于A型胃炎。","","N"],["1998-N110",28,"第一节 消化性溃疡","消化性溃疡病理",1998,110,"B","","胃溃疡",[["A","胃酸度升高"],["B","胃酸度正常或减少"],["C","胃酸度常减少"],["D","胃酸度明显升高"],["E","胃酸度明显减少"]],"B","胃溃疡和B型胃炎（多灶萎缩型胃炎）的胃酸分泌可正常或减少（B对）。胃酸度升高（A错）常见于十二指肠溃疡。胃酸度常减少（C错）常见于胃癌。胃酸度明显升高（D错）常见于胃泌素瘤。胃酸度明显减少（E错）常见于A型胃炎（自身免疫型胃炎）（七版内科学P383-P384）。","","N"],["1998-N129",11,"第一节 胸腔积液","结核性胸膜炎",1998,129,"C","","结核性胸水检查结果",[["A","胸水LDH含量503U/L"],["B","胸水ADA含量96U/L"],["C","二者均可"],["D","二者均不可"]],"C","LDH是反映胸膜炎症程度的指标，渗出液乳酸脱氢酶（LDH）含量增高，大于200U/L，其值越高，表明炎症越明显，LDH＞500U/L常提示为恶性肿瘤或并发细菌感染。结核性胸膜炎时，乳酸脱氢酶（LDH）含量大于200U/L（A对）；因细胞免疫受刺激，淋巴细胞明显增多，故胸水中腺苷脱氨酶（ADA）多高于45U/L（B对）。A选项单位为IU/L（国际单位），一般单位为U/L。本题AB均对，正确答案为C。","","N"],["1998-N130",11,"第一节 胸腔积液","恶性胸腔积液",1998,130,"C","","恶性肿瘤胸水检查结果",[["A","胸水LDH含量503U/L"],["B","胸水ADA含量96U/L"],["C","二者均可"],["D","二者均不可"]],"A","LDH是反映胸膜炎症程度的指标，渗出液乳酸脱氢酶（LDH）含量增高，大于200U/L，其值越高，表明炎症越明显，LDH＞500U/L常提示为恶性肿瘤或并发细菌感染（A对）。结核性胸膜炎时，因细胞免疫受刺激，淋巴细胞明显增多，胸水中腺苷脱氨酶（ADA）多高于45U/L；恶性肿瘤胸水检查ADA＜45U/L（B错）。（十版内科学P129：ADA 升高也见于脓胸、类风湿关节炎、系统性红斑狼疮引起的胸腔积液、恶性胸腔积液等。本答案根据九版内科学教材编写）","","N"],["1998-N131",39,"","",1998,131,"C","","肾小球性蛋白尿主要是",[["A","溶菌酶尿"],["B","β₂微球蛋白尿"],["C","二者均有"],["D","二者均无"]],"D","肾小球性蛋白尿是由于肾小球滤过膜损伤或通透性增高，原尿中蛋白量超过肾小管重吸收的能力导致的蛋白尿。病变较轻时，仅以白蛋白为主的中小分子量蛋白质滤过增多，称为选择性蛋白尿，病变加重时，尿液中出现以IgG、补体C3等为主的大分子量蛋白质（十版内科学P475）。β₂微球蛋白（B错）、溶菌酶（A错）为小分子蛋白质，可通过肾小球滤过膜，存在于原尿中，当肾小管结构或功能受损时，其重吸收障碍，导致此类蛋白从尿中排出，属于肾小管性蛋白尿（本题AB均错，正确答案为D）。","","N"],["1998-N132",39,"","",1998,132,"C","","肾小管性蛋白尿主要是",[["A","溶菌酶尿"],["B","β₂微球蛋白尿"],["C","二者均有"],["D","二者均无"]],"C","肾小管性蛋白尿是指肾小管受到感染或中毒损伤后，近曲小管段对肾小球滤过液中的相对小分子量蛋白质重吸收能力减低，而出现以相对小分子量蛋白为主的蛋白尿。当肾小管结构或功能受损时，肾小管对正常滤过的小分子量蛋白质如β₂-微球蛋白（B对）、溶菌酶（A对）等重吸收障碍，导致蛋白质从尿中排出。本题AB均对，正确答案为C。","","N"],["1998-N133",75,"第一节 中毒概述","导泻",1998,133,"C","","脂溶性毒物中毒后导泻用",[["A","硫酸钠导泻"],["B","硫酸镁导泻"],["C","二者均可"],["D","二者均不可"]],"C","导泻一般不用油脂类泻药，以免促进脂溶性毒物吸收，硫酸钠（A对）和硫酸镁（B对）均非油脂类泻药，可用于脂溶性毒物中毒后导泻。本题AB均对，正确答案为C。","","N"],["1998-N134",75,"第一节 中毒概述","导泻",1998,134,"C","","昏迷患者导泻用",[["A","硫酸钠导泻"],["B","硫酸镁导泻"],["C","二者均可"],["D","二者均不可"]],"A","导泻一般不用油脂类泻药，以免促进脂溶性毒物吸收，硫酸钠（A对）和硫酸镁均非油脂类泻药，可用于脂溶性毒物中毒后导泻。硫酸镁含有镁离子，镁离子吸收过多对中枢神经系统有抑制作用。因此，肾或呼吸衰竭、昏迷和磷化锌、OPI中毒晚期者不宜使用硫酸镁导泻（B错）。","","N"],["1998-N151",21,"第四节 二尖瓣反流","二尖瓣反流并发症",1998,151,"X","","关于风湿性心脏病二尖瓣关闭不全，下列哪些叙述正确",[["A","心房纤颤较二尖瓣狭窄发生晚"],["B","感染性心内膜炎发生较二尖瓣狭窄多"],["C","出现充血性心力衰竭后，治疗预后较二尖瓣狭窄好"],["D","并发体循环梗死较二尖瓣狭窄少"]],"ABD","风湿性心脏病二尖瓣关闭不全的心房颤动见于3/4的慢性重度二尖瓣关闭不全患者，而二尖瓣狭窄相对早期就可发生心房颤动的并发症（A对）。二尖瓣关闭不全者，收缩期左心室内血液高速反流，冲击心房内膜，容易引起内膜损伤，创造细菌入侵的门户，因而风湿性二尖瓣关闭不全的感染性心内膜炎发生率较二尖瓣狭窄多（B对）。二尖瓣关闭不全出现充血性心力衰竭后，表明左心室在长期的容量负荷过度后极度扩张，左心室功能衰竭，治疗效果较二尖瓣狭窄差（C错）。二尖瓣关闭不全左房淤血发生较晚，形成血栓的概率较小，而二尖瓣狭窄并左房扩大、慢性房颤者常有附壁血栓形成，因此风湿性二尖瓣关闭不全并发体循环梗死较二尖瓣狭窄少（D对）。","","N"],["1998-N152",11,"第二节 气胸","气胸病因和发病机制",1998,152,"X","","自发性气胸的常见病因有",[["A","肺大疱"],["B","肺结核"],["C","肺癌"],["D","用力咳嗽、屏气、喷嚏"]],"ABC","气胸是指气体进入胸膜腔，造成积气的状态。气胸可以分为自发性气胸、外伤性气胸和医源性气胸。自发性气胸又可分为原发性气胸和继发性气胸。原发性气胸多见于肺部常规X线检查未能发现明显病变的青年人，特别是男性瘦高体型者。继发性气胸见于有基础肺部病变者，由于病变引起细支气管不完全阻塞，形成肺大疱（A对）破裂。如肺结核（B对）、慢阻肺、肺癌（C对）、肺脓肿、肺尘埃沉着症及淋巴管平滑肌瘤病等。用力咳嗽、屏气、喷嚏（D错）为气胸发生的诱因而非病因。","","N"],["1998-N153",50,"第一节 溶血性贫血概述","血管性HA",1998,153,"X","","下列哪几种疾病表现为微血管病性溶血性贫血",[["A","血栓性血小板减少性紫癜"],["B","弥散性血管内凝血"],["C","Evans综合征"],["D","冷凝集素综合征"]],"AB","微血管病性溶血性贫血是由于微血管内膜发生部分血栓形成、狭窄或坏死，当红细胞流过时发生摩擦，引起红细胞破碎而发生的机械性溶血性贫血。这种贫血见于多种伴有微小血管病变的疾病，如血栓性血小板减少性紫癜（A对）、弥散性血管内凝血（B对）、溶血性尿毒症综合征、败血症等，表现为进行性贫血，贫血程度与出血量不成比例，偶见皮肤、巩膜黄染。Evans综合征为温抗体型自身免疫性溶血性贫血合并免疫性血小板减少（P558）；冷凝集素综合征为冷抗体型自身免疫性溶血性贫血（十版内科学P565）。故Evans综合征（C错）和冷凝集素综合征（D错）均为自身免疫性溶血性贫血。","","N"],["1998-N154",41,"第一节 尿路感染","尿路感染并发症",1998,154,"X","","肾盂肾炎的并发症有",[["A","肾盂积脓"],["B","肾功能衰竭"],["C","肾周围脓肿"],["D","败血症"]],"ABCD","肾盂肾炎在局部迁延不愈可导致肾盂积脓（A对），在伴有糖尿病及尿路结石的患者可向周围扩展，导致肾周围脓肿（C对）。肾盂肾炎的致病菌多是革兰阴性杆菌，尤以大肠杆菌常见，在部分抵抗力较低的患者，细菌可侵入血液，引起败血症与休克（D对）。慢性肾盂肾炎晚期可出现肾小球硬化，导致肾小球滤过功能受损，出现肾功能衰竭（B对），但2021N157X并未将慢性肾衰竭作为肾病综合征的并发症，因此肾功能衰竭是否属于肾盂肾炎的并发症存在争议。","","N"],["1998-N155",60,"第一节 库欣综合征","库欣综合征鉴别诊断",1998,155,"X","","鉴别单纯性肥胖和皮质醇增多症的主要依据是",[["A","尿17-羟皮质类固醇测定"],["B","小剂量地塞米松抑制试验"],["C","血浆皮质醇昼夜节律变化"],["D","糖耐量试验"]],"BC","单纯性肥胖（肥胖症）受下丘脑-垂体-肾上腺轴的负反馈调节，能被小剂量地塞米松抑制；而皮质醇增多症负反馈机制失灵，不能被小剂量地塞米松抑制（B对）。单纯性肥胖患者血皮质醇昼夜变化节律正常；而皮质醇增多症患者皮质醇分泌增多，失去昼夜变化节律（C对）。尿17-羟皮质类固醇是游离皮质醇在肝脏的代谢产物，但影响其因素多，故不用于鉴别。而尿游离皮质醇较少受到其他色素干扰，诊断价值高，因此，鉴别单纯性肥胖和皮质醇增多症时选择尿游离皮质醇而不是直接测定尿17-羟皮质类固醇（A错）。单纯性肥胖和皮质醇增多症患者体内皮质醇都增高，拮抗胰岛素，使体内血糖升高，糖耐量均减低（D错）","","N"],["1998-N156",29,"第一节 肠结核","肠结核手术治疗",1998,156,"X","","下列哪几项是肠结核必须手术治疗的指征",[["A","肠梗阻"],["B","急性肠穿孔"],["C","慢性肠穿孔引起粪瘘经内科治疗不见好转"],["D","肠道大量出血经积极抢救不能满意止血"]],"BCD","肠结核必须手术治疗的指征：①完全性肠梗阻或部分性肠梗阻内科治疗无效者，而并非所有肠梗阻都需手术治疗（A错）；②急性肠穿孔（B对），或慢性肠穿孔瘘管形成经内科治疗而未能闭合者（C对）；③肠道大量出血经积极抢救不能有效止血者（D对）；④诊断困难需开腹探查者。肠结核一般采用保守治疗，因病变肠壁炎症水肿，手术治疗伤口不易愈合，且可引起结核扩散。因此除非发生严重并发症，一般均采用保守抗结核治疗，而不进行手术治疗。","","N"],["1999-N47",15,"第一节 心力衰竭总论","按左心室射血分数分类",1999,47,"A","","关于无症状性心力衰竭，下列哪项正确",[["A","左室已有功能下降，LVEF＜50%，有神经内分泌激活"],["B","左室已有功能下降，LVEF＞50%，有神经内分泌激活"],["C","左室已有功能下降，LVEF＜50%，无神经内分泌激活"],["D","左室已有功能下降，LVEF＞50%，无神经内分泌激活"],["E","此为一短暂的代偿过程"]],"A","心力衰竭按照阶段来分，可分为无症状心衰和充血性心衰。无症状性心力衰竭是指有存在左室心功能不全的病因及病程，且左室射血分数（LVEF）小于50%（BD错），但未表现出心力衰竭的临床症状的一种慢性心力衰竭（E错）。多伴有神经内分泌系统的激活（A对C错）。充血性心衰是指患者出现体循环或肺循环淤血症状的心力衰竭。","","N"],["1999-N48",15,"第一节 心力衰竭总论","心室重塑",1999,48,"A","","关于心室重构的概念，下列哪项不正确",[["A","心肌损害，心脏负荷过重，室壁应力增加，心室反应性肥大"],["B","肥厚心肌肌纤维缩短能力和心室排血能力下降"],["C","肥厚心肌收缩速度下降，松弛延缓"],["D","心肌适度肥厚足以克服室壁应力时，心功能可维持正常"],["E","早期心脏肥厚对维护心功能有益"]],"B","心室重塑是指在持续负荷过重及神经、体液过度激活的状态下，心肌组织在结构、功能、数量及基因表达等方面所发生的适应性变化。在心脏功能受损，心脏负荷（尤其是后负荷）过重，室壁应力增加时，常以心肌肥厚作为主要代偿机制（A对），可伴或不伴心室扩大。因细胞核和线粒体的增大、增多均落后于心肌的纤维化，致心肌供能不足，表现为肥厚心肌收缩速度下降，松弛延缓（C对），但是在早期心肌适度肥厚使心肌收缩力增强，足以克服室壁应力时，心输出量可满足机体需求、心功能可维持正常（DE对）。心室重构早期，由于心肌肥厚、交感神经兴奋性增强、肾素-血管紧张素-醛固酮系统激活，心肌收缩力增加，心室排血能力增加（B错，为本题正确答案）；心室重构晚期，心肌过度肥大，心肌细胞的血液供应相对缺乏，心肌细胞中产生的收缩蛋白也会因胚胎性基因的激活而转变为收缩效率较差的幼稚收缩蛋白，部分心肌纤维中的收缩成分甚至会溶解消失，最终导致心肌纤维的缩短能力和心室排血能力下降。","","N"],["1999-N49",15,"第一节 心力衰竭总论","交感-肾上腺髓质系统增强",1999,49,"A","","关于高动力循环状态的病理生理改变，下列哪项不正确",[["A","血压增高"],["B","心排血量增多"],["C","心率增快"],["D","肺毛细血管楔压增加"],["E","周围循环血液灌注增多"]],"D","高动力循环状态指安静状态下，心排血量及周围循环血液灌流量高于正常状态（E对），成人静息状态时心脏指数超过4L/（min·m²）[正常2.2～3.9L/（min·m²）]，常见于心脏高排出量心衰。由于心脏对刺激如儿茶酚胺、交感神经张力等的反应过度敏感，引起心肌收缩力增强、心脏传导加速及不应期缩短、外周血管扩张，导致静息时心排量增加（B对）、血压升高（收缩压明显升高）（A对）、外周阻力下降、心动过速（C对），血流动力学呈高动力循环状态。高动力循环时，心肌舒缩功能增强，心室舒张期对心房内血液的抽吸作用加强，左心房及肺静脉的血液回流顺利，不会出现肺循环淤血及肺毛细血管楔压增加（D错，为本题正确答案）。","","N"],["1999-N50",15,"第二节 慢性心力衰竭","β受体拮抗剂",1999,50,"A","","下列哪类药物对逆转左室肥厚、改善舒张功能无效",[["A","硝酸酯类"],["B","血管紧张素转换酶抑制剂类"],["C","钙拮抗剂类"],["D","β受体阻滞剂类"],["E","醛固酮拮抗剂类"]],"A","硝酸酯类（十版内科学P187）（A错，为本题正确答案）作用机制是扩张小静脉，减少有效血容量，降低回心血量，在慢性心力衰竭的治疗中用以缓解心绞痛或呼吸困难的症状，为有争议、正在研究或疗效不能肯定的药物（中国心力衰竭诊断和治疗指南2014）。血管紧张素转换酶抑制剂（ACEI）（B对）可减轻高血压时血管中层平滑肌细胞增殖，并使左心室肥厚减轻，除了降低血压和减少后负荷外，还能通过抑制血管紧张素依赖性心肌蛋白的合成和血管紧张素介导的肾上腺素的分泌而减轻心肌肥厚。钙拮抗剂（C对）可作用于心肌细胞的钙通道，降低心肌细胞胞浆中的钙离子浓度，心肌收缩力减弱，舒张功能得到改善。β受体阻滞剂（拮抗剂）类（D对）有逆转左心室肥厚、减轻左心室重构的作用，亦可能有减轻心肌间质纤维化的作用。醛固酮拮抗剂类（E对）可抑制心血管重塑，改善心衰远期预后。","","N"],["1999-N51",15,"第二节 慢性心力衰竭","利尿剂",1999,51,"A","","使用利尿剂治疗心力衰竭，下列哪项是错误的",[["A","保钾利尿剂宜持续应用"],["B","轻者宜选择噻嗪类或袢利尿剂间歇应用"],["C","有肾功能不全时应选用袢利尿剂"],["D","噻嗪类利尿剂剂量与效应呈线性关系"],["E","袢利尿剂的不良反应多由利尿作用所致"]],"D","噻嗪类尤其是氢氯噻嗪100mg/d已达最大效应（剂量-效应曲线已达平台期），再增加也无效（D错，为本题正确答案）。保钾利尿剂（A对）多与噻嗪类、袢利尿剂等排钾性利尿剂联合应用以加强利尿效果并预防低血钾，利尿作用弱，可以持续长期应用。轻度心力衰竭可首选噻嗪类利尿剂，但因可抑制尿酸排泄引起高尿酸血症，长期大剂量应用可影响糖、脂代谢，故轻者宜选择噻嗪类或袢利尿剂间歇应用（B对）。噻嗪类仅适用于有轻度液体潴留、伴高血压而肾功能正常的心衰患者。心力衰竭伴有肾功能不全时应选用袢利尿剂（C对），作用于髓袢升支粗段的Na⁺-K⁺-2Cl⁻共转运子，降低肾脏的浓缩及稀释功能，其利尿作用强大且不受体内酸碱平衡变化的影响。呋塞米的剂量与效应呈线性关系，剂量不受限制，但临床上不推荐很大剂量，用量过大，易致容量不足，增加低血压及肾功能不全风险（E对）。","","N"],["1999-N52",17,"第四节 急性冠状综合征","抗心律失常和传导障碍治疗",1999,52,"A","","急性心肌梗塞左心功能不全伴频发多源室性早搏，用利多卡因无效，应优选下列哪种药物治疗",[["A","普鲁卡因酰胺"],["B","普罗帕酮"],["C","胺碘酮"],["D","阿替洛尔"],["E","维拉帕米"]],"C","胺碘酮（C对）属于Ⅲ类抗心律失常药，主要作用于房室结，能阻断钾通道、延长动作电位时间（主要延长3相动作电位）、延长复极，对于房室结以下的传导系统可使其传导减慢，临床上主要用于各种室上性和室性快速心律失常，是急性心肌梗塞左心功能不全伴频发多源室性早搏，且利多卡因无效的优选药物。普鲁卡因酰胺（A错）、普罗帕酮（B错）、氨酰心安（阿替洛尔）（D错）具有明显的负性肌力作用，因而不适宜伴左心功能不全的治疗。维拉帕米（E错）为非二氢吡啶类钙通道拮抗剂，主要用于治疗房性心律失常。","","N"],["1999-N53",16,"第四节 房室交界性心律失常","房室结折返性心动过速心电图特征",1999,53,"A","","阵发性室上性心动过速的心电图诊断，下列哪项不正确",[["A","心室率150～250次/分"],["B","节律一般规则，但亦可有不规则"],["C","QRS波群形态可不正常"],["D","可见到逆行P波"],["E","起始及终止突然"]],"B","阵发性室上性心动过速心电图特点表现为：心室率150～250次/分（A对），节律规则（B错，为本题正确答案），QRS波形态与时限均正常，但发生室内差异性传导或原有束支传导阻滞时，QRS波形态异常（C对）。当发生交界性心动过速时，P波为逆行性（D对）。起始及终止突然（E对）为阵发性室上性心动过速的一个重要的特征性表现，通常由一个房性期前收缩触发，其下传的PR间期显著延长，随之引起心动过速发作。","","N"],["1999-N54",3,"第一节 支气管扩张症","支气管扩张临床表现",1999,54,"A","","关于支气管扩张的咳痰症状，下列哪项不正确",[["A","可大量咳痰，每天达几百毫升"],["B","可无咳痰"],["C","痰量可在夜间卧床时增多"],["D","可出现臭味痰"],["E","收集痰液可分三层"]],"E","支气管扩张的痰液静置后分为四层：上层为泡沫，下悬脓性成分，中层为浑浊黏液，最下层为坏死组织沉淀物（E错，为本题正确答案），肺脓肿的痰液静置后分为三层。支气管扩张患者非急性期发作时，可无咳痰（B对）。急性发作期，其咳嗽为多阵发性，每天痰量可达数百毫升（A对），咳嗽多在体位改变时，如起床及夜间卧床时增多（C对），痰液可呈黄色脓样，若有厌氧菌混合感染可出现臭味痰（二版八年制内科学P98）（D对）。","","N"],["1999-N55",2,"第一节 支气管哮喘","通气功能检查",1999,55,"A","","支气管哮喘发作时的呼吸功能检查，下列哪项不正确",[["A","FEV₁下降"],["B","FEV₁/FVC%下降"],["C","MMFR上升"],["D","MEF50%减少"],["E","PEFR减少"]],"C","支气管哮喘为阻塞性通气功能障碍，由于气管、支气管发生过度收缩、痉挛，导致气体通过气管、支气管时阻力增大，气体流速降低，与气体流速相关的指标如：FEV₁（A对）、FEV₁/FVC%（B对）、MMFR（最大中期呼气流速）（C错，为本题正确答案）、MEF50%（D对）（50%肺活量时最大呼气流速）及PEFR（E对）（呼气流速峰值）均减少。","","N"],["1999-N56",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病临床表现",1999,56,"A","","阻塞性肺气肿支气管炎型的临床表现，下列哪项是正确的",[["A","发病年龄较轻"],["B","多无紫绀"],["C","喘息明显，多呈持续性"],["D","X线胸片呈肺纹理减少"],["E","静息时PaO₂轻度降低"]],"A","阻塞肺气肿分为气肿型和支气管炎型。支气管炎型发病年龄较轻（A对），体型多肥胖，有发绀（B错），咳嗽较重，喘息较轻（C错）。X线胸片示肺气肿征不明显，肺纹理增粗（D错）、紊乱。血气检查静息时PaO₂显著降低（E错），在运动时则更低，但PaCO₂常明显升高。","","N"],["1999-N57",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病病理生理",1999,57,"A","","慢性支气管炎并发肺气肿早期病理生理改变，下列哪项错误",[["A","病变局限于细小气道"],["B","最大通气量降低"],["C","闭合容积增大"],["D","动态肺顺应性降低"],["E","静态肺顺应性增加"]],"B","慢支合并肺气肿呼吸功能检查早期可无异常表现，病变局限于细小气道（A对），若有小气道阻塞时，最大呼气流量-容积曲线显示流量明显减低（该指标比第一秒用力呼气量更敏感）闭合容量可增加（C对）、动态肺顺应性降低（D对）；然后随着病情发展，肺组织弹性日益减退，肺泡持续扩大，回缩障碍，则残气量及残气量占肺总量的百分比增加，可有最大通气量降低，可见最大通气量降低为晚期表现，并非早期病理生理改变（B错，为本题正确答案）。顺应性是指弹性体在外力作用下发生形变的难易程度。它包括静态顺应性和动态顺应性两者，前者反映了肺组织的弹性，肺气肿时，肺组织的弹性减弱，在外力作用下更容易发生形变，故静态顺应性应当增加（E对）；动态顺应性反应的是肺呼吸运动的容易程度，慢性支气管炎并发肺气肿时肺呼吸运动困难，故动态顺应性下降。","","N"],["1999-N58",2,"第一节 支气管哮喘","药物分类和作用特点",1999,58,"A","","常用控制支气管哮喘急性发作药物的作用，下列哪项不正确",[["A","β₂受体兴奋剂可提高细胞内cAMP的浓度"],["B","茶碱主要是通过抑制磷酸二酯酶、减少cAMP的水解起作用"],["C","抗胆碱能类药可减少cGMP的浓度"],["D","色苷酸二钠可稳定肥大细胞膜"],["E","酮替芬可抑制组胺和慢反应物质释放"]],"B","支气管哮喘是由于支气管平滑肌过度收缩引起的，而支气管平滑肌受多种生物活性物质影响，所以当支气管哮喘发作时，可通过影响这些物质来缓解患者症状。缓解哮喘急性发作的药物有：短效β₂受体激动剂、短效吸入型抗胆碱能药物、短效茶碱、全身用糖皮质激素。β₂肾上腺素受体激动剂主要通过激动呼吸道的β₂受体，激活腺苷酸环化酶，使细胞内的cAMP含量增加（A对），游离钙离子减少，从而松弛支气管平滑肌，是控制哮喘急性发作的首选药物；茶碱可抑制磷酸二酯酶，减少cAMP的水解（B对），提高支气管平滑肌细胞内的cAMP浓度，拮抗腺苷受体，增强呼吸肌的力量以及增强气道纤毛清除功能等，从而起到舒张支气管和气道抗炎作用；抗胆碱药可选择性得阻断M受体，抑制细胞内cGMP的转化，减少cGMP的浓度，使生物活性物质释放减少，从而松弛支气管平滑肌（C对）；色苷酸钠可以稳定肥大细胞膜，抑制肥大细胞释放介质（D对）；酮替芬可抑制组胺和慢反应物质释放（E对），主要用于防治轻、中度哮喘。本题ABCDE选项均正确，但参考答案为B。","","N"],["1999-N59",13,"第三节 慢性呼吸衰竭","氧疗",1999,59,"A","","慢性呼吸衰竭缺氧明显伴二氧化碳潴留时，采用氧疗的给氧浓度，下列哪项是正确的",[["A","＜25%"],["B","＜35%"],["C","＜45%"],["D","＜55%"],["E","＜65%"]],"B","慢性呼吸衰竭时，CO₂潴留和缺O₂分别可通过中枢化学感受器（为主）和外周化学感受器介导的化学感受性反射使呼吸运动加深加快，肺通气量增加，但是长时间CO₂潴留对中枢化学感受器的刺激存在明显的适应现象，而低O₂对外周化学感受器刺激的适应现象不明显，因此慢性呼吸衰竭患者主要依靠低O₂对外周化学感受器刺激进行代偿性呼吸调节。如果在给患者应用氧疗时吸入高浓度氧，可由于解除了低氧的刺激作用而引起呼吸抑制，因此宜采用持续低浓度（＜35%）（B对）持续给氧。","","N"],["1999-N60",4,"第二节细菌性肺炎","并发症的处理",1999,60,"A","","肺炎球菌肺炎伴休克患者，首选补充血容量的液体为",[["A","生理盐水"],["B","5%葡萄糖"],["C","10%葡萄糖"],["D","低分子右旋糖酐"],["E","林格氏液"]],"D","肺炎球菌肺炎出现感染性休克时，由于大量体液渗出，造成血容量不足，因此应首选扩容，临床上最常用于扩容的液体为低分子右旋糖酐（D对），既能维持血容量，又能降低血液黏度，防止DIC发生。生理盐水（A错）、5％葡萄糖（B错）及林格液（E错）均为等渗单纯晶体，对维持血容量效果较差。10％葡萄糖液（C错）为高渗液，扩容效果差。","","N"],["1999-N61",35,"第一节 肝硬化","肝功能减退",1999,61,"A","","肝硬化失代偿期病人的下列检验中，哪项不正确",[["A","凝血因子减少"],["B","血红蛋白减低"],["C","雄激素减少"],["D","雌激素减少"],["E","肾上腺糖皮质激素可减少"]],"D","肝脏作为机体重要器官，功能繁多：参与营养物质、胆红素及激素代谢，分泌、排泄、解毒功能，合成凝血因子及血小板生成素等。肝硬化失代偿期时，肝功能减退，可由于患者肝脏合成凝血因子减少（A对）、脾功能亢进和毛细血管脆性增加，易发生出血，从而引起贫血，血红蛋白减少（B对）；肝脏对雌激素灭活减少，病人体内雌激素增多（D错，为本题正确答案），升高的雌激素反馈抑制垂体促性腺激素释放，从而引起睾丸间质细胞分泌雄激素减少（C对）；肝硬化时，合成肾上腺激素重要的原料胆固醇酯减少，肾上腺皮质激素合成不足（E对）。","","N"],["1999-N62",28,"第一节 消化性溃疡","消化性溃疡药物治疗",1999,62,"A","","对幽门螺杆菌感染阳性的消化性溃疡治疗策略中，下列哪项不正确",[["A","给制酸剂同时加抗菌治疗"],["B","给黏膜防护剂同时加抗菌治疗"],["C","制酸剂可用H₂受体拮抗剂或质子泵阻滞剂"],["D","制酸剂应用疗程在DU应适当较GU时延长"],["E","抗菌素药首选一种，以2周为一疗程"]],"D","目前尚无单一药物可有效根除幽门螺杆菌，因此必须联合用药（十版内科学P372）。应选用幽门螺杆菌根除率高的治疗方案力求一次根除成功，（十版内科学P372）以PPI（制酸剂）（A对）或胶体铋剂（黏膜防护剂）（B对）为基础加上两种抗生素（E错）的三联治疗方案有较高根除率。制酸剂包括质子泵抑制剂和H₂受体拮抗剂，二者均可用于消化性溃疡的治疗（C对）。抗菌药常为克拉霉素、阿莫西林、甲硝唑等任选两种，目前国内多采用7天疗程（E错）。制酸剂应用疗程：DU（十二指肠溃疡）患者予PPI常规剂量、每日1次、总疗程4～6周；GU（胃溃疡）患者予PPI常规剂量、每日1次、总疗程6～8周。因此制酸剂应用疗程在GU应适当较DU时延长（D错，为本题正确答案）。本题答案应为DE，但参考答案为D。有关幽门螺杆菌的根治方案，九版之后的教材相关内容有更新，明确将三联方案更新为四联方案（十版内科学P372）。","","N"],["1999-N64",28,"第一节 消化性溃疡","黏膜防御与修复异常",1999,64,"A","","下列哪一项属于胃十二指肠黏膜防卫因子",[["A","胃酸/胃蛋白酶"],["B","前列腺素"],["C","胆盐"],["D","胰酶"],["E","药物（NSAID）"]],"B","前列腺素（B对）及其类似物米索前列醇具有抑制胃酸分泌、增加胃十二指肠黏膜的黏液及碳酸氢盐分泌和增加黏膜血流等作用，主要用于NSAID溃疡的预防。胃酸、胃蛋白酶（A错）对胃粘膜具有侵袭及消化作用，可导致消化性溃疡的发生。胃十二指肠反流液中的胆盐及胰酶（CD错）可导致胃黏膜损伤。药物（NSAIDs）（E错）是一类环氧合酶（COX）抑制剂，非特异性COX抑制剂抑制了COX-1，导致维持黏膜细胞正常再生的前列腺素E合成不足，黏膜修复障碍，出现糜烂和出血。","","N"],["1999-N65",29,"第二节 结核性腹膜炎","抗结核化学药物治疗",1999,65,"A","","结核性腹膜炎的抗结核治疗，下列哪项不正确",[["A","其疗效一般比溃疡型肠结核略好"],["B","粘连型合并渗出者，病变不易控制"],["C","一般用3至4种药物联合强化治疗"],["D","继发于体内其他结核病的病人，临床多选用以往未用或少用药物"],["E","有血行播散或严重结核毒性症状者，可短期加用肾上腺糖皮质激素"]],"A","结核性腹膜炎由于病变累及腹膜，大量纤维组织增生，药物不易进入病灶达到应有浓度，而溃疡性肠结核病变主要局限于回盲部，药物易进入病灶达到应有浓度，因此结核性腹膜炎抗结核药物的疗效一般比溃疡型肠结核略差（A错，为本题正确答案）。对于粘连型合并渗出者，由于纤维增生并有活动性病灶或干酪样坏死，病变不易控制（B对）。继发于体内其他结核病的病人，多数以前已接受抗结核治疗，容易产生抗药性，临床多选用以往未用或少用药物（D对）。对于血行播散或严重结核毒性症状者，在有效抗结核治疗的情况下，短期加用糖皮质激素可发挥其抗炎、减毒作用，可减轻中毒症状（E对）。在结核的标准治疗方案中，有2、3、4或5种药物联合使用，其中以3或4种药物联合应用为主（C对）。","","N"],["1999-N66",35,"","",1999,66,"A","","肝硬化病人引起肝肾综合征的因素中，下列哪项不正确",[["A","去甲肾上腺素分泌增加"],["B","肾素-血管紧张素Ⅱ系统活性增强"],["C","肾前列腺素合成增加"],["D","血栓素A₂增加"],["E","白三烯产生增加"]],"C","肝肾综合征患者肾脏无实质性病变，由于严重门静脉高压，内脏高动力循环使体循环血流量明显减少；多种扩血管物质如前列腺素、一氧化氮、胰高血糖素、心房利钠肽、内毒素和降钙素基因相关肽等不能被肝脏灭活，引起体循环血管床扩张；同时心输出量相对不足和有效血容量不足引起交感神经系统活性增强，去甲肾上腺素分泌增加（A对），肾素-血管紧张素-醛固酮系统激活（B对），缩血管因子如血栓素A₂（D对）、白三烯合成增加（E对），最终导致肾脏血流减少尤其是肾皮质灌注不足，出现肾衰竭。由于体内前列腺素灭活受阻，相对积累增多，对其自身合成有抑制作用，所以前列腺素合成并不增加（C错，为本题正确答案）。","","N"],["1999-N67",52,"第三节 慢性髓系白血病","急变期（BC）",1999,67,"A","","关于慢性粒细胞白血病急性变，下列哪项不正确",[["A","骨髓和血中原始细胞一般为30%～80%"],["B","不出现髓外原始细胞浸润"],["C","大多为急性粒细胞白血病变"],["D","20%～30%为急性淋巴细胞白血病变"],["E","为慢性粒细胞白血病的终末期"]],"B","慢性粒细胞白血病（慢性髓系白血病）（CML）分三期：慢性期、加速期和急变期。其中急变期为CML的终末期（E对），临床与AL类似，预后差。骨髓和血中原始细胞一般为30%～80%（A对），常有髓外原始细胞浸润（B错，为本题正确答案）。慢性粒细胞白血病急性变多为急性粒细胞白血病变（C对），少数为急性淋巴细胞白血病变（20%～30%）（D对）或急性单核细胞白血病变。","","N"],["1999-N68",49,"第一节 再生障碍性贫血","再生障碍性贫血病因和发病机制",1999,68,"A","","关于氯霉素引起再生障碍性贫血的说法，下列哪项不正确",[["A","用氯霉素引起的再生障碍性贫血发生率较对照组高6～20倍"],["B","与用药剂量和疗程无关"],["C","多数是不可逆的，即使停止用药，再生障碍性贫血仍继续发展"],["D","可影响骨髓细胞成熟和抑制幼稚细胞增殖"],["E","可能阻滞mRNA的功能"]],"C","氯霉素为常见的引起再生障碍性贫血的药物，它能阻滞mRNA的功能（E对），影响骨髓细胞成熟和抑制幼稚细胞增殖（D对）。有数据表明，氯霉素引起再障的发生率较对照组高6～20倍（A对）。在多数情况下，氯霉素能引起短期可逆性的骨髓抑制（C错，为本题正确答案），停止用药后，骨髓抑制可恢复。氯霉素引起的再障与剂量关系不大，而与个人的敏感性有关（B对）。","","N"],["1999-N69",47,"第一节 缺铁性贫血","缺铁性贫血铁代谢",1999,69,"A","","有关铁的描述，下列哪一项是错误的",[["A","食物中的铁以三价氧化高铁为主"],["B","肠黏膜吸收的铁为二价铁"],["C","体内铁蛋白中的铁是三价铁"],["D","转铁蛋白结合的铁是三价铁"],["E","血红蛋白中的铁是三价铁"]],"E","食物中的铁以三价氧化高铁（Fe³⁺）为主（A对），不易被吸收，需要还原成二价铁后才容易被肠黏膜吸收（B对），铁吸收部位主要在十二指肠及空肠上段。吸收入血的二价铁经铜蓝蛋白氧化成三价铁，与转铁蛋白结合（D对）后转运到组织，再与转铁蛋白分离并还原成二价铁，参与形成血红蛋白（E错，为本题正确答案）。多余的三价铁以铁蛋白（C对）和含铁血黄素形式贮存于肝、脾、骨髓等器官的单核巨噬细胞系统，待铁需要增加时动用。","","N"],["1999-N70",40,"第一节 肾小球疾病概述","炎症介质",1999,70,"A","","在下列与肾炎相关的炎症介质中，哪一个是近年来发现的更重要的炎症介质",[["A","补体"],["B","凝血因子"],["C","中性蛋白酶"],["D","血管活性肽"],["E","血管活性胺"]],"D","炎症介质（十版内科学P474）在肾小球疾病发病机制中起重要作用，与肾炎相关的炎性介质很多，如血管活性肽（内皮素、心房肽、加压素、缓激肽、血管紧张素Ⅱ）、血管活性胺（组胺、5-羟色胺）、生长因子、前列腺素（PGI₂、PGE₂、PAF）等，其中内皮素、心房肽即血管活性肽（D对）是近年来发现的重要炎症介质。","","N"],["1999-N71",39,"第一节 总论","尿常规检查",1999,71,"A","","下列描述中哪项不正确",[["A","每日尿量＜100ml为无尿"],["B","每日尿蛋白量持续＞150mg为蛋白尿"],["C","12小时尿红细胞计数＞50万为镜下血尿"],["D","12小时尿沉渣计数管型＞1万为管型尿"],["E","12小时尿白细胞计数＞100万为白细胞尿"]],"D","正常成人每日尿量为1000～2000ml，＞2500ml/d为多尿，＜400ml/d为少尿，＜100ml/d为无尿（A对）。24小时尿蛋白量持续＞150mg诊断为蛋白尿（B对），24小时尿蛋白量＞3.5g诊断为大量蛋白尿。肉眼血尿诊断标准为1L尿含1ml血，镜下血尿诊断标准为尿沉渣检查红细胞≥3个/高倍视野或1h尿红细胞计数＞10万或12h尿红细胞计数＞50万（C对）。正常人尿中偶见透明管型，12小时尿沉渣计数管型＞5000个或镜检时发现大量或其它类型管型时为管型尿（D错，为本题正确答案）。白细胞＞5个/高倍视野或1h新鲜尿液白细胞＞40万或12h尿中白细胞＞100万诊断为白细胞尿（E对），尿培养菌落计数＞10⁵个/ml时诊断为细菌尿。","","N"],["1999-N72",41,"第一节 尿路感染","尿道综合征",1999,72,"A","","下列哪项不符合尿道综合征",[["A","好发于中年女性"],["B","有尿频"],["C","有排尿不畅"],["D","尿白细胞均不增多"],["E","尿菌培养阴性"]],"D","尿道综合征好发于中年女性（A对），虽有尿频（B对）、尿急、尿痛及排尿不畅（C对）等尿路刺激症状，但多次检查均无真性细菌尿（E对）。尿道综合征患者有两种类型：①感染性尿道综合征：致病微生物为支原体、衣原体等，约占75%，患者可有白细胞尿（D错，为本题正确答案）；②非感染性尿道综合征：病因不明，占25%，无白细胞尿，可能因逼尿肌与膀胱括约肌功能不协调、妇科或肛周疾病及精神焦虑而引起。","","N"],["1999-N73",60,"第一节 库欣综合征","库欣综合征诊断与鉴别诊断",1999,73,"A","","皮质醇增多症时下列哪项不正确",[["A","抑制脂肪合成"],["B","抑制蛋白质合成"],["C","嗜酸粒细胞绝对值增高"],["D","血浆肾素增高"],["E","抑制垂体促性腺激素"]],"C","糖皮质激素（GC），主要是皮质醇可使血液中红细胞、血小板和中性粒细胞数量增加，而淋巴细胞和嗜酸性粒细胞数量减少（C错，为本题正确答案）。皮质醇对脂肪组织的主要作用是提高四肢部分的脂肪酶活性，促进脂肪分解，抑制脂肪合成（A对），但皮质醇引起的高血糖可继发引起胰岛素分泌增加，胰岛素增加可加强脂肪合成，增加脂肪沉积于躯干部，引起向心性肥胖、满月脸、水牛背。皮质醇可促进蛋白质分解代谢、抑制合成代谢（B对），使蛋白质呈负平衡。皮质醇增多可激活肾素-血管紧张素系统，导致血浆肾素增高（D对）。皮质醇增多可负反馈抑制垂体促性腺激素的分泌（E对），使性激素水平降低，引起女性月经减少、不规则或停经，男性性欲减退等。","","N"],["1999-N74",61,"第二节 糖尿病酮症酸中毒","纠正电解质及酸碱平衡失调",1999,74,"A","","糖尿病酮症酸中毒患者，过多过快补充碳酸氢钠产生的不良影响，下列哪项不正确",[["A","脑脊液pH反常升高"],["B","血pH骤升使血红蛋白和氧的亲和力上升"],["C","可诱发或加重脑水肿"],["D","促进钾离子向细胞内转移"],["E","反跳性碱中毒"]],"A","糖尿病酮症酸中毒患者经输液和胰岛素治疗后，酮体水平下降，酸中毒可自行纠正，一般不必补碱。但严重酸中毒影响心血管、呼吸和神经系统功能，应给予相应治疗，但补碱不宜过多、过快。过多、过快补充碳酸氢钠对机体的危害性：1.快速补碱后HCO₃⁻会和血液中的氢离子结合生成CO₂，由于CO₂透过血脑屏障的弥散能力大于碳酸氢根，脑脊液pH呈反常性降低，引起脑细胞酸中毒，加重昏迷（A错，为本题正确答案）；2.血pH骤升使氧离曲线左移，血红蛋白和氧的亲和力上升（B对），加重组织缺氧，可诱发或加重脑水肿（C对）；3.促进钾离子向细胞内转移（D对），加重低钾血症和反跳性碱中毒（E对）。","","N"],["1999-N88",28,"第一节 消化性溃疡","消化性溃疡病理",1999,88,"A","","关于胃、十二指肠溃疡病，下列哪项叙述不正确",[["A","胃溃疡好发年龄平均比十二指肠溃疡大"],["B","十二指肠溃疡的起病与精神神经因素有关"],["C","药物（阿司匹林、皮质类固醇）所引起的多为十二指肠溃疡"],["D","十二指肠溃疡不会恶变成癌"],["E","胃溃疡用抗酸剂止痛的效果不好"]],"C","胃溃疡和十二指肠溃疡同属于消化性溃疡，但二者病因、发病机制、好发年龄及临床表现等有诸多不同。十二指肠溃疡多由胃酸分泌过多所致，抑酸剂或抗酸剂治疗效果较好，而胃溃疡多是胃黏膜屏障功能降低所致（十版内科学P374），其胃酸分泌正常或减少，因此抗酸剂治疗效果不明显（E对）。十二指肠溃疡的起病与精神神经因素的关系更密切（B对）。溃疡由良性演变为恶性的几率很低，估计＜1%胃溃疡有可能癌变，十二指肠球部溃疡一般不发生癌变（D对）。药物（阿司匹林，皮质类固醇）所引起的溃疡多为胃溃疡，而非十二指肠溃疡（C错，为本题正确答案）。十二指肠溃疡（DU）多见于青壮年，而胃溃疡（GU）则多见于中老年，前者的发病高峰一般比后者早10年，因此胃溃疡的好发年龄比十二指肠溃疡大（A对）。","","N"],["1999-N103",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎克雷伯杆菌肺炎治疗",1999,103,"B","","克雷伯杆菌肺炎首选",[["A","庆大霉素"],["B","青霉素G"],["C","红霉素"],["D","氧氟沙星"],["E","甲硝唑"]],"A","克雷伯杆菌肺炎首选氨基糖苷类+半合成青霉素，庆大霉素属于氨基糖苷类抗生素（A对）；青霉素G（B错）属于β-内酰胺类抗生素，主要用于肺炎球菌肺炎；红霉素（C错）属于大环内酯类抗生素，首选用于军团菌肺炎、肺炎支原体肺炎；氧氟沙星（D错）属于喹诺酮类抗菌药，抗菌谱广，对革兰阳性菌及阴性菌均有强大的抗菌作用，对厌氧菌和肺炎支原体也有良好作用；甲硝唑（E错）是硝基咪唑类合成抗菌药，具广谱抗厌氧菌和抗原虫的作用，临床主要用于预防和治疗厌氧菌引起的感染。","","N"],["1999-N104",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺军团病治疗",1999,104,"B","","军团菌肺炎首选",[["A","庆大霉素"],["B","青霉素G"],["C","红霉素"],["D","氧氟沙星"],["E","甲硝唑"]],"C","军团菌肺炎、肺炎支原体肺炎均首选大环内酯类抗生素，如红霉素（C对）；庆大霉素（A错）属于氨基糖苷类抗生素，主要用于克雷伯杆菌肺炎、铜绿假单胞菌；青霉素G（B错）属于β-内酰胺类抗生素，主要用于肺炎球菌肺炎；氧氟沙星（D错）属于喹诺酮类抗菌药，抗菌谱广，对革兰阳性菌及阴性菌均有强大的抗菌作用，对肺炎支原体和军团菌也有良好作用，但不是首选；甲硝唑（E错）是硝基咪唑类合成抗菌药，具广谱抗厌氧菌和抗原虫的作用，临床主要用于预防和治疗厌氧菌引起的感染。","","N"],["1999-N105",37,"第一节 急性胰腺炎","急性胰腺炎发病机制",1999,105,"B","","引起胰腺细胞坏死的是",[["A","胰蛋白酶"],["B","糜蛋白酶"],["C","弹力蛋白酶"],["D","磷脂酶A"],["E","激肽酶"]],"D","磷脂酶A₂在小量胆酸参与下分解细胞膜的磷脂，引起胰腺细胞膜溶解，造成胰腺细胞坏死（D对），并产生溶血磷脂酰胆碱和溶血脑磷脂，其细胞毒作用引起胰实质凝固性坏死、脂肪组织坏死及溶血。激肽酶（E错）可使激肽酶原变为缓激肽和胰激肽，使血管舒张和通透性增加，引起水肿和休克。弹力蛋白酶（C错）可溶解血管弹性纤维引起出血和血栓形成。糜蛋白酶（B错）被胰蛋白酶激活后，可水解芳香族氨基酸，与急性胰腺炎发病关系不大。胰蛋白酶（A错）使各种胰消化酶原被激活为有生物活性的消化酶，各种消化酶原激活后，共同作用造成胰腺坏死。注意：胰腺坏死是指胰腺组织的坏死，包括胰腺细胞、脂肪组织和血管等；而胰腺细胞坏死是特指胰腺细胞的坏死。做题时应注意两者提问的区别，可结合1992N97B来深刻理解。","","N"],["1999-N106",37,"第一节 急性胰腺炎","急性胰腺炎发病机制",1999,106,"B","","引起胰腺血管坏死的是",[["A","胰蛋白酶"],["B","糜蛋白酶"],["C","弹力蛋白酶"],["D","磷脂酶A"],["E","激肽酶"]],"C","弹性蛋白酶可溶解血管弹性纤维引起出血和血栓形成，因此，引起胰腺血管坏死的是弹性蛋白酶（C对）。磷脂酶A（D错）在小量胆碱参与下分解细胞膜的磷脂，引起胰腺细胞膜溶解，造成胰腺细胞坏死，并产生溶血磷脂酰胆碱和溶血脑磷脂，其细胞毒作用引起胰实质凝固性坏死、脂肪组织坏死及溶血。激肽释放酶（E错）可使激肽酶原变为缓激肽和胰激肽，使血管舒张和通透性增加，引起水肿和休克。胰蛋白酶（A错）使各种胰消化酶原被激活为有生物活性的消化酶。糜蛋白酶（B错）被胰蛋白酶激活后，可水解芳香族氨基酸，与急性胰腺炎发病关系不大。","","N"],["1999-N107",47,"第一节 缺铁性贫血","慢性病贫血",1999,107,"B","","慢性炎症贫血",[["A","骨髓细胞外铁升高，铁粒幼细胞数增高，转铁蛋白饱和度升高"],["B","骨髓细胞外铁升高，铁粒幼细胞数增高，转铁蛋白饱和度降低"],["C","骨髓细胞外铁升高，铁粒幼细胞数降低，转铁蛋白饱和度正常"],["D","骨髓细胞外铁降低，铁粒幼细胞数降低，转铁蛋白饱和度降低"],["E","骨髓细胞外铁降低，铁粒幼细胞数降低，转铁蛋白饱和度升高"]],"C","慢性炎症贫血是由慢性炎症引起的铁代谢异常性贫血，表现为铁与转铁蛋白结合障碍和铁利用障碍。铁与转铁蛋白结合障碍时，血清铁、血清铁饱和度、总铁结合力减低。铁利用障碍时，铁粒幼细胞合成减少，贮存在血清铁蛋白和骨髓小粒含铁血黄素中的铁增多，骨髓细胞外铁（指骨髓细胞外的铁蛋白与含铁血黄素）升高。根据九版内科学观点，本题无正确答案，但参考答案为C。","","N"],["1999-N108",47,"第一节 缺铁性贫血","铁代谢",1999,108,"B","","缺铁性贫血",[["A","骨髓细胞外铁升高，铁粒幼细胞数增高，转铁蛋白饱和度升高"],["B","骨髓细胞外铁升高，铁粒幼细胞数增高，转铁蛋白饱和度降低"],["C","骨髓细胞外铁升高，铁粒幼细胞数降低，转铁蛋白饱和度正常"],["D","骨髓细胞外铁降低，铁粒幼细胞数降低，转铁蛋白饱和度降低"],["E","骨髓细胞外铁降低，铁粒幼细胞数降低，转铁蛋白饱和度升高"]],"D","缺铁性贫血患者原料铁缺乏，导致血清铁以及血清铁蛋白降低，转铁蛋白饱和度下降，而总铁结合力代偿性增高。骨髓细胞外铁指骨髓细胞外的铁蛋白与含铁血黄素，属贮存铁。缺铁性贫血时，贮存铁减少，故骨髓细胞外铁减少。骨髓细胞内铁指骨髓铁粒幼细胞内铁，缺铁性贫血时，铁粒幼细胞内铁小粒减少或消失，铁粒幼细胞少于15%（D对）。","","N"],["1999-N109",59,"第一节 甲状腺功能亢进症","甲亢¹³¹I治疗适应证和禁忌证",1999,109,"B","","女性40岁，中度弥漫性甲状腺肿伴甲亢合并迁延性肝炎，且对抗甲状腺药物过敏，首选何种治疗",[["A","硫脲类制剂"],["B","碘制剂"],["C","心得安"],["D","¹³¹I"],["E","手术"]],"D","考察¹³¹I治疗甲亢的适应证。根据¹³¹I治疗甲亢的适应证 ①甲状腺肿大Ⅱ度以上；②对ATD过敏；③ATD治疗或者手术治疗后复发；④甲亢合并心脏病；⑤甲亢伴白细胞减少、血小板减少或全血细胞减少；⑥甲亢合并肝、肾等脏器功能损害；⑦拒绝手术治疗或者有手术禁忌证；⑧浸润性突眼，患者应首选¹³¹I治疗（D对）。患者对抗甲状腺药物过敏，因此禁用抗甲状腺药（A错）。碘制剂仅用于甲状腺手术术前准备和甲状腺危象（十版内科学P692）（B错）。普萘洛尔为甲亢治疗的辅助用药（C错）。患者有迁延性肝炎，不宜手术（E错）。","","N"],["1999-N110",59,"第一节 甲状腺功能亢进症","甲亢手术适应证",1999,110,"B","","女性56岁，结节性甲状腺肿伴甲亢，首选何种治疗",[["A","硫脲类制剂"],["B","碘制剂"],["C","普萘洛尔"],["D","¹³¹I"],["E","手术"]],"E","结节性甲状腺肿为单纯性甲状腺肿结节期。单纯性甲状腺肿手术指征为：①因气管、食管或喉返神经受压引起临床症状者；②胸骨后甲状腺肿；③巨大甲状腺肿影响生活和工作者；④结节性甲状腺肿继发功能亢进者（E对）；⑤结节性甲状腺肿疑有恶变者。碘制剂仅用于甲状腺手术术前准备和甲状腺危象（十版内科学P692）救治（B错）。普萘洛尔为甲亢治疗的辅助用药（C错）。抗甲状腺药的适用于为甲状腺轻、中度肿大以及孕妇或严重疾病不适合手术者，并不作为结节性甲状腺肿伴甲亢的首选（十版内科学P691）（A错）。¹³¹I（D错）在下列情况才使用：①甲状腺二度肿大以上；②对ATD过敏；③ATD治疗或者手术治疗后复发；④甲亢合并心脏病；⑤甲亢伴白细胞减少、血小板减少或全血细胞减少；⑥甲亢合并肝、肾等脏器功能损害；⑦拒绝手术治疗或者有手术禁忌证；⑧浸润性突眼。","","N"],["1999-N127",27,"","",1999,127,"C","","A型萎缩性胃炎",[["A","胃黏膜萎缩"],["B","恶性贫血"],["C","两者皆有"],["D","两者皆无"]],"C","A型胃炎由自身免疫疾病引起，自身抗体攻击壁细胞，使壁细胞总数减少，进而导致壁细胞分泌的内因子丧失，引起维生素B₁₂吸收不良而导致恶性贫血（B对）；无论A型还是B型萎缩性胃炎均属于萎缩性胃炎，因此都有黏膜萎缩（A对）。本题AB均对，正确答案为C。","","N"],["1999-N128",27,"第二节 慢性胃炎","自身免疫",1999,128,"C","","B型萎缩性胃炎",[["A","胃黏膜萎缩"],["B","恶性贫血"],["C","两者皆有"],["D","两者皆无"]],"A","无论A型萎缩性还是B型萎缩性胃炎均有黏膜萎缩（A对），恶性贫血见于A型胃炎（由于自身抗体攻击壁细胞，使壁细胞分泌的内因子丧失，引起维生素B₁₂吸收不良所致），B型萎缩性胃炎主要为幽门螺杆菌感染引起的胃粘膜萎缩及慢性炎性细胞浸润，无自身免疫因素参与其发病（B错）。","","N"],["1999-N129",21,"第三节 二尖瓣狭窄","二尖瓣狭窄病理生理",1999,129,"C","","二尖瓣狭窄心功能失代偿期",[["A","肺动脉压增高"],["B","肺毛细血管楔压增高"],["C","两者均有"],["D","两者均无"]],"C","肺毛细血管楔压（PCWP）：可反映肺静脉、左心房和左心室的功能状态，PCWP的正常值为6～15mmHg（0.8～2kPa），与左心房内压接近，PCWP增高可反映左心房压力增高。二尖瓣狭窄失代偿期，血液从左房流入左室受阻，左心房内压力升高，肺血回流障碍导致肺淤血，肺毛细血管楔压增高（A对），长期肺淤血可使肺动脉压继发性升高（B对）（本题AB都对，故本题选C）。","","N"],["1999-N130",17,"第四节 急性冠状综合征","急性ST段抬高型心肌梗死病理生理",1999,130,"C","","单纯右心室梗死",[["A","肺动脉压增高"],["B","肺毛细血管楔压增高"],["C","两者均有"],["D","两者均无"]],"D","单纯右心室梗死在MI（心肌梗死）患者中少见，因右心室射血能力下降，血液从右房流入右室受阻，出现右房高压，导致回心血量减少，中心静脉压增高。肺动脉高压（A错）、肺毛细血管楔压增高（B错）是由左心衰导致肺淤血而引起（本题AB均错，正确答案为D）。","","N"],["1999-N131",25,"","",1999,131,"C","","Gilbert综合征",[["A","胆红素摄取障碍"],["B","胆红素结合障碍"],["C","两者均有"],["D","两者均无"]],"C","Gilbert综合征又称为体质性肝功能不良性黄疸，一种遗传性非结合胆红素血症，是肝细胞摄取游离胆红素障碍及微粒体内葡萄糖醛酸转移酶不足所致，非结合胆红素被肝细胞摄取后，在微粒体中经葡萄糖醛酸转移酶的催化作用与葡糖醛酸结合形成结合胆红素，完成非结合胆红素的结合。故既有胆红素摄取障碍（肝细胞摄取游离胆红素障碍）（A对），又有胆红素结合障碍（葡萄糖醛酸转移酶不足）（B对）。本题AB均对，正确答案为C。","","N"],["1999-N132",25,"","",1999,132,"C","","Crigler-Najjar综合征",[["A","胆红素摄取障碍"],["B","胆红素结合障碍"],["C","两者均有"],["D","两者均无"]],"B","Crigler-najjar综合征（CNS）又称为先天性葡萄糖醛酸转移酶缺乏症，病因为由于肝脏缺乏葡萄糖醛酸转移酶，而不能催化非结合胆红素与葡萄糖醛酸结合，形成结合胆红素（B对），但胆红素摄取正常（A错）。","","N"],["1999-N133",45,"第一节 慢性肾衰竭","慢性肾衰竭定义和分期",1999,133,"C","","肾功能不全代偿期",[["A","血肌酐＜178μmol/L"],["B","GFR25～50ml/min"],["C","两者均是"],["D","两者均不是"]],"A","随着临床和基础研究的不断进展，关于慢性肾衰竭的分期标准也在不断更新。美国肾脏病基金会专家组主要依据肾小球滤过率GFR（正常值90～110ml/min）将慢性肾脏病（CKD）分为5期：1期（≥90ml/min）；2期（60～89ml/min）；3期（30～59ml/min）；4期（15～29ml/min）；5期（＜15ml/min）（十版内科学P525）。我国主要依据血肌酐值Scr（正常值44～133μmol/L）将慢性肾功能不全分为4期：肾功能代偿期（133～177μmol/L）（A对）；肾功能失代偿期（186～442μmol/L）；肾功能衰竭期（451～707μmol/L）；尿毒症期（≥707μmol/L）。此4期分别对应CKD分期的2、3、4、5期。因此肾功能不全代偿期GFR为60～89ml/min（B错）。","","N"],["1999-N134",45,"第一节 慢性肾衰竭","慢性肾衰竭定义和分期",1999,134,"C","","肾功能衰竭期",[["A","血肌酐＜178μmol/L"],["B","GFR25～50ml/min"],["C","两者均是"],["D","两者均不是"]],"D","随着临床和基础研究的不断进展，关于慢性肾衰竭的分期标准也在不断更新。美国肾脏病基金会专家组主要依据肾小球滤过率GFR（正常值90～110ml/min）将慢性肾脏病（CKD）分为5期：1期（≥90ml/min）；2期（60～89ml/min）；3期（30～59ml/min）；4期（15～29ml/min）；5期（＜15ml/min）（十版内科学P525）。我国主要依据血肌酐值Scr（正常值44～133μmol/L）将慢性肾功能不全分为4期：肾功能代偿期（133～177μmol/L）；肾功能失代偿期（186～442μmol/L）；肾功能衰竭期（451～707μmol/L）（A错）；尿毒症期（≥707μmol/L）。此4期分别对应CKD分期的2、3、4、5期。因此肾功能衰竭期GFR为15～29ml/min（B错）。本题AB均错，正确答案为D。","","N"],["1999-N151",16,"第四节 房室交界性心律失常","急性发作期",1999,151,"X","","预激综合征并发快速心房纤颤患者治疗选择，下列哪些正确",[["A","电复律"],["B","普罗帕酮"],["C","胺碘酮"],["D","维拉帕米"]],"AB","预激综合征患者发作心房扑动与颤动时伴有晕厥或低血压，应立即电复律（A对），或静脉注射伊布利特或普罗帕酮（B对），不应使用β受体拮抗剂、维拉帕米（D错）、地尔硫䓬、洋地黄类药物和胺碘酮（C错），因为这些抗心律失常药可能抑制房室结传导从而加剧旁道下传，有诱发室颤的风险。","","N"],["1999-N152",10,"第三节 慢性肺源性心脏病","心脏病变和心力衰竭",1999,152,"X","","能促进肺心病发生心力衰竭的因素有",[["A","电解质紊乱所致的心律失常"],["B","乳酸积累"],["C","高能磷酸键合成降低"],["D","心肌缺氧"]],"ABCD","心力衰竭的解剖基础是心肌的不平衡生长，而心律失常（A对）、乳酸堆积（B对）、高能磷酸键合成降低（C对）、心肌缺氧（D对）均可加重心肌的能量生成和利用障碍以及兴奋-收缩耦联障碍，导致心肌收缩力下降而发生心力衰竭。","","N"],["1999-N153",75,"第一节 中毒概述","血液净化",1999,153,"X","","下列哪种物质中毒可采用血液透析",[["A","苯巴比妥"],["B","甲醇"],["C","导眠能"],["D","有机磷杀虫药"]],"AB","苯巴比妥（A对）、甲醇（B对）、水杨酸类、茶碱等非脂溶性毒物均可采用血液透析。导眠能（C错）具有脂溶性，一般不进行血液透析。有机磷杀虫药（D错）（十版内科学P889）除敌百虫外，一般难溶于水，为脂溶性的毒物，透析效果不好。","","N"],["1999-N154",52,"第四节 慢性淋巴细胞白血病","临床分期",1999,154,"X","","按照国际上对慢性淋巴细胞白血病的分期，A期病人可有",[["A","淋巴结肿大"],["B","脾肿大"],["C","贫血"],["D","血小板减少"]],"AB","Binet分期标准：A期 血和骨髓中淋巴细胞增多，＜3个区域的淋巴组织肿大；B期 血和骨髓中淋巴细胞增多，≥3个区域的淋巴组织肿大；C期 与B期相同外，尚有贫血（Hb：男性＜110g/L，女性＜100g/L）（C错）或血小板减少（＜100×10⁹/L）（D错）可知A期病人可有淋巴结肿大（A对）和脾肿大（B对）（一侧或双侧颈、腋下、腹股沟淋巴结各作为一个区域，肝、脾属于淋巴组织，也各作为一个区域，共五个区域。A期病人可有两个区域淋巴组织肿大，故可有淋巴结肿大和脾肿大）。贫血（C错）和血小板减少（D错）为C期表现。","","N"],["1999-N155",39,"第一节 总论","肾炎综合征",1999,155,"X","","慢性肾炎综合征的特点有",[["A","蛋白尿"],["B","血尿"],["C","高血压"],["D","水肿"]],"ABCD","肾炎综合征是以血尿、蛋白尿、水肿和高血压为特点的综合征，按起病急缓和转归分为急进性、急性、慢性肾炎综合征。慢性肾炎综合征多数起病缓慢，病程1年以上，临床表现呈多样性，主要表现为蛋白尿（A对）、血尿（B对）、高血压（C对）和水肿（D对），可有不同程度的肾功能减退。根据十版内科学观点，本题答案应为ABCD，但参考答案为ABC。","","N"],["1999-N156",61,"第一节 糖尿病","T2DM的临床特点",1999,156,"X","","在葡萄糖刺激时，非胰岛素依赖型糖尿病病人的胰岛素水平",[["A","可稍低"],["B","可基本正常"],["C","可高于正常"],["D","分泌高峰延迟"]],"ABCD","非胰岛素依赖型糖尿病（NIDDM）即2型糖尿病（T2DM），发病机制为从以胰岛素抵抗为主伴胰岛素进行性分泌不足到以胰岛素进行性分泌不足为主伴胰岛素抵抗，体内胰岛素水平正常甚至升高，空腹血浆胰岛素基础值正常、较低或偏高，葡萄糖负荷后血浆胰岛素分泌高峰延迟（D对）。2型糖尿病β细胞功能呈进行性减退，早期患者主要以胰岛素抵抗为主，胰岛β细胞功能尚正常，故在葡萄糖刺激时，血浆胰岛素水平可不适当地升高（C对）。中晚期患者由以胰岛素抵抗为主伴β细胞功能障碍，逐渐转变为以β细胞功能障碍为主伴胰岛素抵抗，故在葡萄糖刺激时，血浆胰岛素水平可基本正常或稍低（AB对）。","","N"],["2000-N47",18,"第二节 继发性高血压","肾血管性高血压诊断",2000,47,"A","","关于继发性高血压，下列哪项不正确",[["A","慢性肾小球肾炎所致的高血压主要与水钠潴留及血容量增加有关"],["B","肾血管性高血压在继发性高血压中属不常见的一种"],["C","原发性醛固酮增多症仅少数病例可发展为重度或恶性高血压"],["D","嗜铬细胞瘤在继发性高血压中是较少的一种"],["E","对40岁以下的高血压者应着重考虑继发性高血压的可能"]],"B","肾血管性高血压指单侧或双侧肾动脉主干或分支狭窄所致的高血压，属于较常见的继发性高血压之一（B错，为本题正确答案）。慢性肾小球肾炎简称慢性肾炎，基本临床表现为蛋白尿、血尿、高血压、水肿，其所致的高血压主要与水钠潴留及血容量增加有关（A对）。肾血管狭窄的常见病因包括多发性大动脉炎、动脉粥样硬化及肾动脉纤维肌性发育不良。原发性醛固酮增多症由肾上腺皮质肿瘤或增生引起，大多数表现为缓慢发展的良性血压升高，呈轻、中度高血压，少数可发展为重度或恶性高血压（C对）。嗜铬细胞瘤主要表现为阵发性或持续性高血压，肿瘤性质大多为良性，在继发性高血压中是较少见的一种，约9%（D对）。对40岁以下的高血压者应着重考虑继发性高血压的可能（E对）。","","N"],["2000-N48",17,"第四节 急性冠状综合征","环氧化酶抑制剂",2000,48,"A","","下列哪个不属于抗血小板聚集和黏附的药物",[["A","双嘧达莫（dipyridamole）"],["B","阿司匹林（aspirin）"],["C","噻氯匹定（ticlopidine）"],["D","双香豆素"],["E","芬氟咪唑"]],"D","双香豆素（D错，为本题正确答案）的抗凝血作用与肝素不同，主要与维生素K发生可逆性竞争，抑制维生素K依赖的凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ在肝细胞中合成，使凝血酶原含量降低，防止血栓形成，但对血小板的聚集和黏附无影响。其余四种药物分别通过以下机制对抗血小板聚集和黏附：双嘧达莫（潘生丁）（A对）作用机制是抑制血小板摄取腺苷，抑制磷酸二酯酶，使血小板内环磷酸腺苷（cAMP）增多，抑制血栓烷素A₂（TXA₂）形成；阿司匹林（B对）作用机制是通过抑制血小板的前列腺素环氧酶，从而防止血栓烷A₂的生成而起作用（TXA₂可促使血小板聚集）；噻氯匹定（C对）作用机制是抑制ADP诱导的血小板膜GPⅡb/Ⅲa受体复合物与纤维酶原结合位点的暴露，因而抑制血小板聚集。芬氟咪唑（E对）作用机制是抑制TXA₂合成酶。","","N"],["2000-N49",18,"第一节 原发性高血压","血管紧张素转换酶抑制剂",2000,49,"A","","高血压病合并糖尿病，BP180/100mmHg，心率65次/分，尿蛋白（+），血肌酐正常，选用下列哪类药物降压最合适",[["A","ACEI制剂"],["B","β-受体阻滞剂"],["C","钙离子拮抗剂"],["D","利尿剂"],["E","α-受体阻滞剂"]],"A","患者高血压病合并糖尿病，且尿蛋白（+）、血肌酐正常，提示轻度肾功能不全。ACEI（血管紧张素转换酶抑制剂）（A对）可增加高血压及糖尿病患者对胰岛素的敏感性，并能减少残存肾小球的高灌注、高滤过，减轻蛋白尿，可有效减轻或延缓糖尿病肾病的进展，但要注意在低血容量或病情晚期（肌酐清除率＜30ml/min或血肌酐超过265μmol/L，即3.0mg/dl）有可能反而使肾功能恶化。β-受体阻滞剂（B错）特别适用于心率较快的中、青年患者或合并心绞痛和慢性心力衰竭者。钙离子拮抗剂（十版内科学P268）（C 错）适用于合并糖尿病、冠心病或外周血管病患者。利尿剂（D 错）适用于轻中度高血压患者，对单纯收缩期高血压、合并心力衰竭和老年人高血压有较强的降压效应，但影响血脂、血糖、血尿酸代谢，不能改善糖尿、蛋白尿。α- 受体阻滞剂（E 错）用于治疗外周血管痉挛性疾病，也可用于治疗休克和嗜铬细胞瘤所致的高血压的治疗。","","N"],["2000-N50",21,"第五节 多瓣膜病","二尖瓣狭窄伴主动脉瓣反流",2000,50,"A","","关于二尖瓣狭窄伴主动脉瓣关闭不全，下列哪项不正确",[["A","是风湿性心脏病的常见组合形式"],["B","由于二尖瓣狭窄致心排血量减少，使左心室扩大延缓"],["C","约2/3患严重二尖瓣狭窄病人可伴有不同程度的主动脉瓣关闭不全"],["D","心排血量增加可使外周血管征缺如"],["E","心尖部第一心音可不亢进"]],"D","二尖瓣狭窄伴主动脉瓣关闭不全是风湿性心脏病的常见组合形式（A对）。二尖瓣狭窄导致舒张期心室充盈减少，虽合并主动脉血液反流，但早期左心室前负荷增加尚不严重，因而左心室扩大延缓（B对）。临床上，约2/3的严重二尖瓣狭窄病人可伴有不同程度的主动脉瓣关闭不全（C对）。主动脉反流及心室过度充盈使得二尖瓣所处位置较高，心室收缩期二尖瓣关闭振幅较小，因而心尖部第一心音可不亢进（E对）。周围血管征为脉压增大的表现。二尖瓣狭窄使左室舒张期充盈受限，收缩期每搏输出量降低，心排血量减少，收缩压明显降低。此时虽然存在主动脉反流，舒张压降低，但脉压变化不大，因而不可使外周血管征缺如（D错，为本题正确答案）。心排出量增大时，收缩压升高，此时外周血管征应十分典型。","","N"],["2000-N51",22,"第三节 缩窄性心包炎","缩窄性心包炎治疗",2000,51,"A","","下列哪类疾病目前不能采用介入治疗方法",[["A","冠心病心绞痛"],["B","二尖瓣狭窄"],["C","阵发性室性心动过速"],["D","肥厚型梗阻性心肌病"],["E","缩窄性心包炎"]],"E","心血管介入治疗是将治疗用的器械通过各种途径送入心脏或血管内实施的治疗，而缩窄性心包炎（E对）的病变在心脏和血管外，且心包因纤维素炎粘连致密、钙化导致心肌舒张受限，介入治疗不能改善症状，为禁忌证，应尽快用心包切除术。冠心病心绞痛（A错）可通过介入置入支架，可有效改善心肌供血。二尖瓣狭窄（B错）在瓣膜功能尚好时可行经皮球囊二尖瓣成形术或闭式二尖瓣分离术。阵发性室性心动过速（C错）可行旁路射频消融术。肥厚型梗阻性心肌病（D错）可行经皮室间隔心肌化学消融术，引发可控性室间隔上部心肌梗死，扩大左心室流出道。","","N"],["2000-N52",15,"第二节 慢性心力衰竭","洋地黄类药物",2000,52,"A","","洋地黄治疗心力衰竭的机制，下列哪项不正确",[["A","抑制心肌细胞钠-钾-ATP酶"],["B","促进Na⁺-Ca²⁺交换"],["C","降低SNS和RAS的活性"],["D","提高细胞内Ca²⁺水平"],["E","具有正性肌力作用及正性松弛作用"]],"E","洋地黄类药物治疗充血性心力衰竭的确切作用机制尚不完全清楚，目前认为洋地黄与心肌细胞膜上的Na⁺-K⁺-ATP酶（A对）结合并抑制其活性，导致钠泵失灵，使细胞内Na⁺增加，K⁺减少，细胞内Na⁺量增多后，又通过Na⁺-Ca²⁺（B对）双向交换机制，或使Na⁺内流减少，Ca²⁺外流减少，或使Na⁺外流增加，Ca²⁺内流增加（D对），最终导致心肌细胞内Ca²⁺增加，心肌的收缩加强（九版药理学P235），并非导致舒张加强（即正性松弛）（E错，为本题正确答案）。洋地黄还可兴奋迷走神经，降低SNS（交感神经系统）和RAS（肾素-血管紧张素系统）的活性（C对）。","","N"],["2000-N53",16,"第四节 房室交界性心律失常","急性发作期",2000,53,"A","","关于预激综合征患者的治疗选择，下列哪项不正确",[["A","伴发正向房室折返性心动过速，可首选维拉帕米静注"],["B","伴发心房纤颤，宜选用ⅠC类抗心律失常药物"],["C","心动过速发作频繁宜采用射频消融治疗"],["D","虽无心动过速或心房纤颤发生，亦应进行预防治疗"],["E","为有效预防心动过速的发作，应选用两种抗心律失常药物合用"]],"D","无心动过速或心房纤颤发生的预激综合征患者的治疗目前仍存在争议，需要通过危险分层来决定是否接受导管消融治疗（D错，为本题正确答案）。预激综合征患者伴发正向房室折返性心动过速，可首选维拉帕米静注（A对）或腺苷，也可选普罗帕酮，通过终止房室结内折返降低心室率。预激综合征患者伴发心房纤颤，宜选用延长房室旁路不应期的普鲁卡因胺（ⅠA类）或普罗帕酮（ⅠC类）等抗心律失常药物（B对）。心动过速发作频繁是采用射频消融治疗（C对）的适应证。预激综合征的病理基础是心房和心室之间存在房室旁路，心室预激、房室折返性心动过速、房扑和房颤是最常并发的快速性心律失常，预激综合征的预防主要是防止心动过速的复发，为了有效的防止反复发作的心动过速，应选用两种抗心律失常药物同时抑制折返回路的前向与逆向传导（E对），临床上奎尼丁与普萘洛尔、普鲁卡因与维拉帕米合用，可以取得比较良好的治疗效果。ⅠA、ⅠC类抗心律失常药胺碘酮等延长房室旁路与房室结的不定期，能有效预防心动过速的复发，药物选择可根据临床实际情况进行（电生理检查可确定最有效的药物，保证最佳的预防复发的效果）。","","N"],["2000-N54",11,"第二节 气胸","排气疗法",2000,54,"A","","闭合性气胸的排气治疗，下列哪项正确",[["A","积气量少于该侧胸腔容量的30%，不抽气"],["B","积气量多时，应立即将气抽尽，恢复肺功能"],["C","积气量多时，应立即行闭式水封瓶式引流"],["D","积气量多时，可一日多次抽气，每次1L直至抽尽"],["E","积气量多时，可每日或隔日抽气一次，每次小于1L"]],"E","对于肺被压缩面积＜20%，单纯性、首次发病、无明显症状的闭合性气胸，可采取保守治疗；肺被压缩＞20%的气胸，应抽气治疗（A错），一次抽气量不宜超过1000ml，每日或隔日抽气1次（E对BD错），过快、过多抽气可使胸腔压力骤降，发生复张后肺水肿或循环衰竭。闭式水封瓶式引流（C错）适用于不稳定型气胸，呼吸困难明显、肺压缩程度较重，交通性或张力性气胸，反复发生气胸的患者。","","N"],["2000-N55",6,"第一节 肺结核","化学治疗的原则",2000,55,"A","","关于结核病化疗原则，下列哪项不正确",[["A","应坚持早期、联合、大量、规律、全程用药"],["B","临床有结核中毒症状，X线病灶有炎性成分，需用化疗"],["C","对病灶部分硬结，痰菌阴性者，可先观察，暂不用化疗"],["D","利福平对杀灭被吞噬在细胞内的结核菌有效"],["E","初始病例如条件允许，尽量采用短程化疗（6个月）"]],"A","早期、规律、全程、适量（非大量）、联合（A错，为本题正确答案）是肺结核病人的化疗原则。结核中毒症状明显及X线病灶有炎性成分可以推断患者处于结核活动期，结核传染性强，应积极化疗（B对）。对病灶部分硬结，痰菌阴性者可诊断为无活动性肺结核患者，可先观察，暂不用化疗（C对）。利福平对巨噬细胞内外的结核分枝杆菌均有快速杀菌作用，特别是对C菌群有独特的杀菌作用（D对）。初始病例的治疗方案包括每日用药方案和间歇用药方案，均为六个月左右短程化疗，而复治的方案时间相对较长，不管用何种方案都要注意全程督导化疗管理（E对）。","","N"],["2000-N56",13,"第一节 呼吸衰竭概述","Ⅱ呼吸衰竭",2000,56,"A","","呼吸衰竭严重缺氧可导致机体内的变化，下列哪项错误",[["A","可抑制细胞能量代谢的氧化磷酸化作用"],["B","可产生乳酸和无机磷，引起代谢性酸中毒"],["C","氢离子进入细胞内引起细胞内酸中毒"],["D","组织二氧化碳分压增高"],["E","体内离子转运的钠泵损害，引起细胞内高钾"]],"E","呼吸衰竭导致严重低氧血症和高碳酸血症，使组织二氧化碳分压增高（D对）。在持续或严重缺氧的患者体内，组织细胞能量代谢的中间过程，如三羧酸循环、氧化磷酸化和有关酶的活性受到抑制（A对），使能量生成减少，体内乳酸和无机磷产生增多，导致代谢性酸中毒（B对）。由于能量不足，体内转运离子的钠泵功能障碍，使细胞内K⁺转移至血液，而Na⁺和H⁺进入细胞内，造成细胞内酸中毒（C对）、低钾（E错，为本题正确答案）和高钾血症。","","N"],["2000-N57",11,"第一节 胸腔积液","结核性胸膜炎",2000,57,"A","","胸水检查为：血性，比重1.020，蛋白定量39g/L，LDH503U/L，葡萄糖定量2.4mmol/L，ADA110U/L，最可能的诊断为",[["A","右心衰竭胸水"],["B","结核性胸水"],["C","癌性胸水"],["D","丝虫病性胸水"],["E","结缔组织病性胸水"]],"B","该患者胸水比重1.020、蛋白定量39g/L、LDH 503U/L（符合渗出液特征：比重＞1.018，总蛋白＞30g/L，LDH＞200U/L）；胸水为血性（血性胸水多见于肿瘤、结核和肺栓塞），葡萄糖定量2.4mmol/L（结核性和恶性胸腔积液葡萄糖含量可＜3.3mmol/L），ADA 110U/L（结核性胸膜炎时，因细胞免疫受刺激，淋巴细胞明显增多，胸水中腺苷脱氨酶（ADA）多高于45U/L），所以最可能的诊断为结核性胸腔水（B对）。右心衰竭胸水（十版内科学P126）（A错）为胸膜腔毛细血管内静水压增高所致，为漏出液。癌性胸水（C错）ADA＜45U/L。丝虫病性胸水（D错）为丝虫堵塞淋巴管引起的漏出液；结缔组织病性胸水（十版内科学P127）（E错）为渗出液，但非血性。","","N"],["2000-N58",10,"第三节 慢性肺源性心脏病","慢性肺源性心脏病X线检查",2000,58,"A","","X线胸片诊断慢性肺源性心脏病的主要依据，下列哪项不符合",[["A","可有明显肺气肿或慢性肺部感染疾患征象"],["B","右心室增大"],["C","肺动脉段突出，其高度大于等于5mm"],["D","右下肺动脉干横径大于等于15mm"],["E","右下肺动脉干横径与气管横径之比大于等于1.07"]],"C","X线胸片诊断慢性肺源性心脏病的依据：①肺、胸基础疾病及急性肺部感染的特征（A对）；②右下肺动脉干扩张，其横径≥15mm（D对）或右下肺动脉横径与气管横径比值≥1.07（E对），或动态观察右下肺动脉干增宽＞2mm；③肺动脉段明显突出或其高度≥3mm（C错，为本题正确答案）；④中心肺动脉扩张和外周分支纤细，形成“残根”征；⑤圆锥部显著凸出（右前斜位45°）或其高度≥7mm；⑥右心室增大（B对）。","","N"],["2000-N59",13,"第三节 慢性呼吸衰竭","慢性呼吸衰竭血气分析",2000,59,"A","","呼吸衰竭时下列检查中哪项不符合慢性呼吸性酸中毒表现",[["A","PaCO₂上升"],["B","pH可正常或降低"],["C","HCO₃⁻上升"],["D","SB＞AB"],["E","CO₂结合力上升"]],"D","呼吸衰竭发生慢性呼吸性酸中毒时，由于CO₂潴留，导致血PaCO₂上升（A对）、二氧化碳结合力（血中HCO₃⁻和H₂CO₃中CO₂含量的总和）上升（E对）、pH可正常（代偿性）或降低（失代偿性）（B对）；慢性呼吸性酸中毒时，因CO₂潴留发展缓慢，肾脏可通过减少HCO₃⁻的排出来维持pH恒定，导致HCO₃⁻上升（C对），引起AB（实际碳酸氢盐）＞SB（标准碳酸氢盐）（D错，为本题正确答案）；AB＜SB时表示呼出过多，见于呼吸性碱中毒。","","N"],["2000-N60",3,"第一节 支气管扩张症","支气管扩张诊断",2000,60,"A","","男性，44岁，一周前上感伴咳嗽，三小时前突然咯鲜血，量达300ml，无胸痛。既往有痰中带鲜血史。查体：体温37.3℃，血压正常，双肺叩清，右下肺可闻中小水泡音，心尖部可闻3/6级收缩期吹风样杂音。最可能的诊断为",[["A","肺结核病伴空洞"],["B","支气管扩张症"],["C","肺梗死"],["D","肺炎球菌性肺炎"],["E","风湿性心脏瓣膜病"]],"B","患者既往有痰中带鲜血史，一周前上感后出现咳嗽、咯血，量达300ml，体格检查发现右下肺中小水泡音，支气管扩张时可闻及下胸部、背部固定而持久的局限性粗湿啰音，故应怀疑支气管扩张症（B对）。肺结核病伴空洞（十版内科学P77）（A错）患者虽可有大量咯血表现，但空洞好发于肺尖，并且肺结核时有低热盗汗等明显的全身结核中毒症状；肺梗死（十版内科学P112）（C错）常表现为胸痛、咯血（常为小量咯血，大咯血少见）、呼吸困难、晕厥、烦躁不安等；肺炎球菌性肺炎（十版内科学P51）（D错）的典型表现为咳铁锈色痰，无大量咯血；风湿性心脏瓣膜病（十版内科学P305-P306）（E错）多累及二尖瓣，以二尖瓣狭窄最多见，多表现为舒张期杂音。","","N"],["2000-N61",35,"","",2000,61,"A","","肝硬化病人肝肾综合征的特点",[["A","血BUN↑、血钠↑、尿钠↑"],["B","血BUN↑、血钠↑、尿钠↓"],["C","血BUN↑、血钠↓、尿钠↓"],["D","血BUN↓、血钠↓、尿钠↓"],["E","血BUN↑、血钠↓、尿钠↑"]],"C","肝硬化患者出现严重的门脉高压时，内脏的高动力循环血流将使体循环血流量明显减少，又因为多种扩血管物质不能被肝脏灭活，引起体循环血管床扩张，心输出量相对不足和有效血容量不足，肾素-血管紧张素-醛固酮系统和交感神经系统被进一步激活，最终导致肾皮质血管强烈收缩、肾小球率过率下降，从而出现肾衰竭，即肝肾综合征。肝肾综合征的患者由于肾灌注不足，肾小球滤过率降低，肾小球滤过率降低时：①体内的含氮物质排不出去，出现氮质血症；②肾素-血管紧张素-醛固酮系统被激活，功能性肾衰，肾小管功能未受损，尿钠重吸收增加，尿钠含量降低；③由于尿量减少，体内的水排不出去，产生稀释性低钠血症。综上，血BUN（血尿素氮）升高、血钠降低、尿钠降低（C对）。","","N"],["2000-N63",36,"第一节 原发性肝癌","原发性肝癌临床表现",2000,63,"A","","有关肝癌的临床表现，下列哪项不正确",[["A","可完全不痛或仅有轻微钝痛"],["B","不会出现急腹症表现"],["C","有时表现为膈抬高"],["D","位于肋弓下的癌结节最易被触到"],["E","有时可在腹壁上听到吹风样血管杂音"]],"B","肝癌起病隐匿，早期缺乏典型症状。临床症状明显者，病情大多已进入中晚期，主要有肝区疼痛、肝大、黄疸、肝硬化征象、全身性表现、伴癌综合征等。肝区疼痛是肝癌最常见的症状，半数以上患者有肝区疼痛，多呈持续性钝痛或胀痛，如果病变侵犯膈，疼痛可牵涉至右肩或右背，如果癌肿生长缓慢，则可完全无痛或仅有轻微钝痛（A对）。当肝表面的癌结节破裂，可导致胆汁性腹膜炎和腹腔内出血，引起急腹症表现（B错，为本题正确答案）。位于膈面的癌肿，则主要表现为膈肌抬高（C对）而肝下缘不下移。位于肋弓下缘浅表部位较大的肝癌肿块最易被触到（D对）。由于肝癌动脉血管丰富而迂曲，粗动脉骤然变细，或因巨大的癌肿压迫肝动脉或腹主动脉，有时可在腹壁相应部位听到吹风样杂音（E对）。","","N"],["2000-N64",35,"","",2000,64,"A","","肝性脑病的脑性毒物中，下列哪项不正确",[["A","氨"],["B","芳香族氨基酸"],["C","γ-氨基丁酸"],["D","蛋氨酸的代谢产物-硫醇"],["E","中链脂肪酸"]],"E","关于肝性脑病发病机制的各种假说，主要有以下几种：1.氨中毒（A对）；2.神经递质假说，神经递质假说又分为γ-氨基丁酸/苯二氮䓬（GABA/BZ）神经递质（C对）、假性神经递质和色氨酸；3.锰离子。芳香族氨基酸（B对）是假性神经递质的合成前体，由其产生的假性神经递质可取代突触传递中的正常递质，抑制神经传导，故为肝性脑病的脑性毒物。蛋氨酸（甲硫氨酸）在肠道内被细菌分解为硫醇（D对），长链脂肪酸被细菌分解为短链脂肪酸，硫醇、短链脂肪酸（非中链脂肪酸）（E错，为本题正确答案）和体内的氨可相互作用，引发肝性脑病。硫醇类化合物可以抑制尿素合成而干扰氨的解毒，抑制线粒体呼吸过程等，短链脂肪酸对脑的损害机制并不十分清楚，可能与阻断脑细胞氧化磷酸过程及抑制神经冲动传递有关。","","N"],["2000-N65",37,"第一节 急性胰腺炎","急性胰腺炎辅助检查",2000,65,"A","","急性坏死性胰腺炎时，下列哪项检查结果正确",[["A","血清淀粉酶均升高"],["B","血清脂肪酶早期升高"],["C","血糖升高"],["D","血钙升高"],["E","血白蛋白升高"]],"C","急性胰腺炎时，胰腺细胞由于自身消化作用被破坏，大量淀粉酶释放入血，导致血、尿淀粉酶的升高，轻型急性胰腺炎的血清淀粉酶升高，但其升高幅度与病情严重程度无相关性。重症急性胰腺炎时，胰腺出血坏死广泛，胰腺细胞大量坏死，不再产生和释放淀粉酶，血尿淀粉酶可不升高甚至出现降低（A错）。血清脂肪酶一般在24～72小时才开始升高，持续7～10天恢复正常。脂肪组织被脂肪酶水解为脂肪酸，与钙离子结合，生成不溶性脂肪酸钙（钙皂），导致血钙降低（D错），常发生在发病的第2～3天后。急性坏死性胰腺炎时，由于大量炎性渗出、肝损伤，故白蛋白一般降低（E错）。急性坏死性胰腺炎胰腺实质坏死严重，胰岛功能严重受损，导致胰岛素分泌骤降，血糖升高（＞11.1mmol/L）（C对）。","","N"],["2000-N66",28,"第一节 消化性溃疡","消化性溃疡病理",2000,66,"A","","下列导致十二指肠溃疡胃酸分泌异常的因素中哪项不正确",[["A","壁细胞对胃泌素特别敏感"],["B","胃酸反馈性抑制机制失灵"],["C","对进餐刺激后胃酸分泌在溃疡活动期增强"],["D","晚间胃酸分泌明显增多"],["E","胃排空减慢"]],"E","消化性溃疡发病的机制是胃酸、胃蛋白酶的侵袭作用与黏膜的防御能力间失去平衡，胃酸对粘膜产生自我消化，其中十二指肠溃疡以高胃酸分泌为主要发病机制（十版内科学P374）。壁细胞为主要分泌胃酸细胞，G细胞分泌的胃泌素对其分泌活动有促进作用；当分泌的胃酸增加时会反馈性抑制G细胞使其分泌的胃泌素减少，当反馈抑制机制失灵后（B对），胃酸分泌增加引起十二指肠溃疡壁细胞对胃泌素特别敏感（A对），导致胃酸分泌过度，引起十二指肠溃疡；进餐刺激使胃酸分泌在溃疡活动期增强（C对），引起溃疡；夜间迷走神经张力增高，迷走神经释放Ach和GRP，分别有直接刺激壁细胞分泌盐酸和刺激G细胞分泌胃泌素作用，使胃酸分泌明显增多（D对）；此外，部分十二指肠溃疡患者存在胃排空加快和十二指肠蠕动减慢，胃排空加快特别表现为液体排空加快，致使十二指肠球部酸负荷加重，而十二指肠蠕动减慢又使其降段的碱性液体不能有效地中和近端肠腔内的酸性物质，十二指肠球部的pH低于正常，黏膜易遭受损伤（E错，为本题正确答案）。","","N"],["2000-N67",40,"第五节 肾病综合征","肾病综合征诊断",2000,67,"A","","下列哪一项是诊断肾病综合征的必需条件",[["A","尿蛋白＞3.5g/d"],["B","尿沉渣红细胞＞3个/高倍视野"],["C","高血压"],["D","水肿"],["E","血脂升高"]],"A","肾病综合征诊断标准是：①尿蛋白大于3.5g/d；②血浆白蛋白低于30g/L；③水肿；④血脂升高。其中①②两项为诊断所必需（A对DE错）。尿沉渣红细胞＞3个/高倍视野（B错）为镜下血尿诊断标准，血尿和高血压（C错）为肾炎综合征的临床表现，但肾病综合征中不一定出现。","","N"],["2000-N68",41,"第一节 尿路感染","尿路感染的分类",2000,68,"A","","判断肾盂肾炎病人是复发还是重新感染，通常以病人前次治疗停药后几周再发为依据",[["A","4周"],["B","5周"],["C","6周"],["D","7周"],["E","8周"]],"C","重新感染是在治疗后症状消失，尿菌阴性，但在停药6周后再次出现真性细菌尿，菌株与上次不同。复发是在治疗后症状消失，尿菌阴转后在6周内再出现菌尿，菌种与上次相同（菌种相同且为同一血清型）。因此，复发感染和重新感染的区别，以病人前次治疗停药后6周（C对）为界限。有关尿路感染的复发和重新感染，十版内科学提到“再感染是指由新的病原体致病，复发是因同一病原体持续存在导致的感染再次发作”（P499），八版内科学（P501-P502）及15 版实用内科学（P2074-P2975）都明确说明一般在停药6周后再发生的尿路感染为重新感染，停药后6 周内复发，致病菌与前次相同为复发。","","N"],["2000-N69",45,"第一节 慢性肾衰竭","骨骼病变",2000,69,"A","","导致肾性骨病的病因中，下列哪项不正确",[["A","缺乏活性维生素D₃"],["B","继发性甲状旁腺功能亢进"],["C","营养不良"],["D","铝中毒"],["E","铁负荷减少"]],"E","肾性骨营养不良是由慢性肾功能衰竭导致的骨代谢病，简称肾性骨病，包括纤维囊性骨炎（高转化骨病）、骨再生不良、骨软化症（低转化性骨病）及骨质疏松症。纤维囊性骨炎主要由PTH（甲状旁腺激素）过高引起（B对），其破骨细胞过度活跃，引起骨炎融化，骨质重吸收增加，骨的胶原基质破坏，而代以纤维组织，形成纤维囊性骨炎，易发生肋骨骨折。骨软化症主要由于骨化三醇（活性维生素D₃）不足（A对）或铝中毒（D对）引起骨组织钙化障碍，导致未钙化骨组织过分堆积，成人以脊柱和骨盆表现最早且突出，可有骨骼变形。慢性肾衰竭患者消化吸收功能障碍可出现营养不良，营养不良（C对）导致骨质合成及钙化不足，导致肾性骨病。导致肾性骨病的病因为铁负荷增加而非减少（E错，为本题正确答案）。","","N"],["2000-N70",60,"第一节 库欣综合征","库欣综合征病因诊断",2000,70,"A","","下列哪一项检查最有助于鉴别垂体性Cushing病和异位ACTH综合征",[["A","尿17-羟测定"],["B","尿17-酮测定"],["C","血浆ACTH测定"],["D","CRH兴奋试验"],["E","ACTH兴奋试验"]],"D","Cushing病（库欣病）是垂体分泌大量ACTH（促肾上腺皮质激素），导致肾上腺皮质分泌皮质醇过多所致，受下丘脑（CRH）-垂体（ACTH）-肾上腺皮质（皮质醇）轴的调节，CRH兴奋试验阳性；而异位ACTH综合征是指垂体以外的肿瘤产生大量ACTH，导致肾上腺皮质增生，不受下丘脑（CRH）-垂体（ACTH）-肾上腺皮质（皮质醇）轴的调节，CRH兴奋试验阴性。故CRH兴奋试验可作为二者鉴别的依据（D对）。垂体性Cushing病和异位ACTH综合征的尿17-羟、尿17-酮均升高，故尿17-羟（A错）、尿17-酮（B错）测定不作为二者鉴别的依据。垂体性Cushing病和异位ACTH综合征均可产生大量ACTH，血浆ACTH均增高，故血ACTH测定（C错）不作为二者的鉴别依据。垂体性Cushing病和异位ACTH综合征均为依赖ACTH的库欣综合征，ACTH兴奋试验均为有反应，故ACTH兴奋试验（E错）不作为二者的鉴别依据。ACTH兴奋试验有助于鉴别依赖ACTH的库欣综合征和不依赖ACTH的库欣综合征。","","N"],["2000-N71",59,"第一节 甲状腺功能亢进症","高代谢症群",2000,71,"A","","Graves病时的代谢，下列哪项不正确",[["A","肠道糖吸收增加"],["B","肝糖分解增加"],["C","尿肌酸排出增加"],["D","血总胆固醇增加"],["E","糖耐量异常"]],"D","Graves病主要指由于血液循环中甲状腺激素过多引起的神经、循环、消化等系统兴奋性增高和代谢亢进为主要表现的一组临床综合征（P680）。甲状腺功能亢进时，甲状腺素分泌增多，脂肪分解与氧化，胆固醇合成、转化及排出均加速，常导致血中总胆固醇降低（D错，为本题正确答案）。TH可加速肠黏膜吸收葡萄糖（A对）。TH亦可加强外周组织对葡萄糖的利用，导致血糖降低，肝糖分解增加（B对）以补充血糖。TH分泌过多，以骨骼肌为主的外周组织蛋白分解加速，引起负氮平衡，导致尿肌酸排出增加（C对）。TH水平升高还能对抗胰岛素，导致血糖升高，糖耐量异常（E对），甚至出现糖尿。","","N"],["2000-N72",53,"第一节 霍奇金淋巴瘤","霍奇金淋巴瘤病理和分型",2000,72,"A","","下列有关国内HD的描述，哪项不正确",[["A","HD仅占全部淋巴瘤的8%～11%"],["B","淋巴细胞耗竭型最常见"],["C","淋巴细胞为主型较为少见"],["D","淋巴细胞为主型较易向其他各型转化"],["E","结节硬化型不易转化"]],"B","HD（霍奇金病）为以前说法，现在已改为霍奇金淋巴瘤（HL）。我国HL的发病率明显低于欧美国家，约占淋巴瘤的8%～11%（A对）。HL分为五类：结节性淋巴细胞为主型、混合细胞型、结节硬化型、富于淋巴细胞型和淋巴细胞削减型。国内以混合细胞型最常见（B错，为本题正确答案），结节硬化型其次（但病理学观点认为结节硬化型发病率最高），其他各型均较少见（C对）。各型HL并非固定不变，淋巴细胞为主型的2/3可向其他各型转化（D对），仅结节硬化型较为固定（E对）。病理学观点认为结节硬化性发病率最高。","","N"],["2000-N73",47,"第一节 缺铁性贫血","铁代谢",2000,73,"A","","缺铁性贫血病人的下列哪一项检查结果不正确",[["A","TF升高"],["B","TFR升高"],["C","TS升高"],["D","FEP升高"],["E","锌卟啉升高"]],"C","缺铁性贫血时，原料铁减少，机体TF（转铁蛋白）合成增强（A对）。当红细胞内铁缺乏时，TFR（转铁蛋白受体）脱落进入血液成为血清可溶性转铁蛋白受体，血清中可以测得的TFR升高（B对）。TS（转铁蛋白饱和度）反映与铁结合的转铁蛋白占转铁蛋白总量的百分比，缺铁性贫血时，血清铁（铁与转铁蛋白结合）降低，TS降低（C错，为本题正确答案）。FEP（游离原卟啉）可与铁结合后成为血红素，缺铁性贫血时，原料铁减少，FEP升高（D对）。游离原卟啉还可与锌原子结合成锌卟啉（ZPP），缺铁性贫血时游离原卟啉升高，锌卟啉升高（E对）。","","N"],["2000-N74",46,"第一节 贫血概述","贫血临床表现",2000,74,"A","","下列有关贫血性心脏病的改变，哪一项不正确",[["A","心脏扩大"],["B","心尖部可闻及隆隆样杂音"],["C","心尖部可闻及较粗糙的吹风样杂音"],["D","心电图可呈现S-T段降低，T波低平或倒置"],["E","以上改变在贫血治愈后仍不能恢复正常"]],"E","贫血早期，机体通过增加循环血量以改善机体缺氧。循环血量增加，回心血量增多，心室前负荷增大而出现代偿性扩大（心脏扩大）（A对）。心室前负荷增大，左室舒张期容量负荷过高，使二尖瓣基本处于半关闭状态，呈现相对狭窄而产生杂音，即心尖部可闻及舒张期隆隆样杂音（B对）。当心脏扩大时，出现二尖瓣相对关闭不全，心尖部可闻及收缩期粗糙的吹风样杂音（C对）。长期贫血时，心肌缺血缺氧，因此心电图可呈现缺血时表现，如ST段降低，T波低平或倒置（D对）。贫血性心脏病患者无心血管系统原发疾病，若积极治愈贫血，循环系统的症状可以恢复正常（E错，为本题正确答案）。","","N"],["2000-N82",59,"","",2000,82,"A","","下列哪项是桥本甲状腺肿的表现特点",[["A","常继发于上呼吸道感染"],["B","常有基础代谢率增高和甲状腺摄取¹³¹I量降低的分离现象"],["C","组织学上，腺组织被大量淋巴细胞所浸润，并形成淋巴滤泡"],["D","强的松治疗可迅速缓解症状"],["E","无基础代谢率降低等甲状腺功能减退表现"]],"C","桥本氏甲状腺肿是一种自身免疫性甲状腺炎，又称慢性淋巴细胞性甲状腺炎，病理可见大量的淋巴细胞，并形成淋巴滤泡（C对）。它的病理与免疫变化与Graves病相似，是环境因素和遗传因素共同作用的结果，精神因素、过度劳累、感染与其他应激反应等是引发桥本氏甲状腺肿的诱因，亚急性甲状腺炎常继发于上呼吸道感染（十版内科学P697）（A错）。亚急性甲状腺炎血T₃、T₄增高，摄碘率可降至5％～10％以下，常有基础代谢率增高和甲状腺摄取¹³¹I量降低的分离现象（B错）。桥本氏甲状腺肿通常用小剂量抗甲状腺药物和适当剂量甲状腺激素治疗，甲状腺迅速肿大、伴局部疼痛或压迫症状时可予以糖皮质激素治疗。强的松治疗可迅速缓解症状（D错）为亚急性甲状腺炎的临床特点。桥本氏甲状腺炎甲状腺实质广泛破坏、萎缩，大量淋巴细胞及不等量的嗜酸性粒细胞浸润，纤维组织增生，因此本病晚期一般有甲状腺功能低下的表现（E错）。","","N"],["2000-N103",17,"第四节 急性冠状综合征","不稳定型心绞痛和非ST段抬高型心肌梗死治疗调脂治疗",2000,103,"B","","辛伐他汀",[["A","主要降低血甘油三酯，也降低血胆固醇的药物"],["B","主要降低血胆固醇，也降低血甘油三酯的药物"],["C","主要降低LDL-C的药物"],["D","仅降低血甘油三酯的药物"],["E","仅降低血总胆固醇的药物"]],"B","辛伐他汀为羟甲基戊二酸单酰辅酶A（HMG-COA）还原酶抑制剂，抑制内源性胆固醇的合成。此外，他汀类还通过负反馈调节导致肝细胞表面LDL受体代偿性增强或活性增强，使血浆LDL（低密度脂蛋白）降低，继而导致VLDL（极低密度脂蛋白）代谢加快，加上肝合成及释放VLDL减少，也导致VLDL及TG（甘油三酯）相应下降。辛伐他汀作为他汀类药物的一种，主要降低血胆固醇，也降低血甘油三酯（B对）。主要降低TG及VLDL药物为烟酸类及贝特类（A错）。九版药理学P243认为辛伐他汀的主要作用也包括降低LDL-C，因此，该题C选项存在争议。","","N"],["2000-N104",63,"","",2000,104,"B","","吉非贝特",[["A","主要降低血甘油三酯，也降低血胆固醇的药物"],["B","主要降低血胆固醇，也降低血甘油三酯的药物"],["C","主要降低LDL-C的药物"],["D","仅降低血甘油三酯的药物"],["E","仅降低血总胆固醇的药物"]],"A","吉非贝齐为苯氧芳酸类（贝特类）降血脂药物，它能促进VLDL（极低密度脂蛋白）和TG（甘油三酯）的分解以及胆固醇的逆向转运，因此吉非贝齐为主要降低甘油三酯，也降低血胆固醇的药物（A对）。他汀类主要降低血清TC（胆固醇），也在一定程度上降低血TG（甘油三酯）（十版内科学P759）（B错）。","","N"],["2000-N105",25,"","",2000,105,"B","","胆红素生成过多见于",[["A","Gilbert综合征"],["B","无效造血"],["C","Dubin-Johnson综合征"],["D","Crigler-Najjar综合征"],["E","Rotor综合征"]],"B","无效造血（B对）是在骨髓内红细胞分裂成熟的过程中，由于某种原因使其在成熟和进入外周循环之前就被破坏、死亡，导致红细胞破坏增加，胆红素生成过多。Gilbert综合征（A错）是肝细胞摄取游离胆红素障碍及微粒体内葡萄糖醛酸转移酶不足所致，而无胆红素生成过多。Dubin-Johnson综合征（C错）是临床上少见的一种遗传性非溶血性高胆红素血症，是由于肝细胞的先天缺陷对CB（结合型胆红素）及某些阴离子向毛细胆管排泄发生障碍，致血清中CB增加而出现黄疸，胆红素并无生成过多。Crigler-najjar综合征（D错）是先天性葡萄糖醛酸转移酶缺乏，导致非结合胆红素转化障碍，并无胆红素生成过多。Rotor综合征（E错）的病因是肝细胞摄取游离胆红和排泄结合胆红素均有先天性缺陷，致血中结合胆红素增高，无胆红素生成过多。","","N"],["2000-N106",25,"","",2000,106,"B","","肝细胞向毛细胆管排泄结合胆红素障碍，而胆红素的摄取和结合正常见于",[["A","Gilbert综合征"],["B","无效造血"],["C","Dubin-Johnson综合征"],["D","Crigler-Najjar综合征"],["E","Rotor综合征"]],"C","Dubin-Johnson综合征（C对）是临床上少见的一种遗传性非溶血性高胆红素血症（又称家族性高胆红素血症），是由于肝细胞的先天缺陷对CB（结合型胆红素）及某些阴离子向毛细胆管排泄发生障碍，致血清中CB增加而出现黄疸，而胆红素的摄取和结合正常。无效造血（B错）在骨髓内红细胞分裂成熟的过程中，由于某种原因使其在成熟和进入外周循环之前就被破坏、死亡，称之为无效造血，这种途径导致血红蛋白释放、破坏增加，随之胆红素生成增加，而与肝细胞排泄胆红素功能障碍无关。Gilbert综合征（A错）又称体质性肝功能不良性黄疸，一种遗传性非结合胆红素血症，是肝细胞摄取游离胆红素障碍及微粒体内葡萄糖醛酸转移酶不足所致。Crigler-najjar综合征（D错）病因为先天性葡萄糖醛酸转移酶缺乏，导致非结合胆红素转化障碍，而与结合胆红素排泄障碍无关。发生于新生儿和婴幼儿的遗传性高胆红素血症，又称先天性葡萄糖醛酰转移酶缺乏症、伴有胆红素脑病（核黄疸）的先天性非溶血性黄疸等。Rotor综合征（E错）的病因是肝细胞摄取游离胆红和排泄结合胆红素均有先天性缺陷，致血中结合胆红素增高为主。","","N"],["2000-N107",61,"第一节 糖尿病","促胰岛素分泌剂",2000,107,"B","","合并肾功能不全的糖尿病病人常首选",[["A","甲苯磺丁脲"],["B","氯磺丙脲"],["C","格列齐特"],["D","格列喹酮"],["E","格列本脲"]],"D","磺酰脲类口服降糖药：格列喹酮约95%在肝内代谢，其代谢产物由胆汁排入肠道，很少（5%）经肾脏排泄，因此格列喹酮为糖尿病合并肾功能不全的首选（D对）；甲苯磺丁脲（A错）、氯磺丙脲（B错）为第一代磺酰脲类现已很少应用；格列齐特（C错）、格列本脲（E错）经肾脏的排泄率分别为80%、50%，故不作为糖尿病合并肾功能不全的首选。","","N"],["2000-N108",61,"第一节 糖尿病","促胰岛素分泌剂",2000,108,"B","","为了减轻或延缓糖尿病血管并发症的发生常首选",[["A","甲苯磺丁脲"],["B","氯磺丙脲"],["C","格列齐特"],["D","格列喹酮"],["E","格列本脲"]],"C","格列齐特可降低血小板的黏附性和聚集性，刺激纤溶酶原合成，减少凝血和血管栓塞的发生，故为了减轻或延缓糖尿病血管并发症，磺酰脲类中首选格列齐特（C对）。甲苯磺丁脲（A错）、氯磺丙脲（B错）为第一代磺酰脲类，现已很少应用。格列喹酮（D错）可作为糖尿病合并肾功能不全的首选。","","N"],["2000-N109",52,"第二节 急性白血病","淋巴结和肝、脾大",2000,109,"B","","纵隔淋巴结肿大常见于",[["A","急性粒细胞白血病"],["B","急性单核细胞白血病"],["C","红白血病"],["D","B细胞急淋白血病"],["E","T细胞急淋白血病"]],"E","急性白血病（AL）根据主要受累的细胞系列可分为急性淋巴细胞白血病（ALL）和急性髓系白血病（AML）。淋巴结肿大以急淋白血病（急性淋巴细胞白血病）较多见，纵隔淋巴结肿大常见于T细胞急淋白血病（E对）。急性单核细胞白血病（M₅）（十版内科学P579）（B错）最易发生齿龈肿胀、皮肤蓝灰色斑丘疹等。","","N"],["2000-N110",52,"第二节 急性白血病","口腔和皮肤",2000,110,"B","","牙龈增生、肿胀多见于",[["A","急性粒细胞白血病"],["B","急性单核细胞白血病"],["C","红白血病"],["D","B细胞急淋白血病"],["E","T细胞急淋白血病"]],"B","急性白血病（AL）根据主要受累的细胞系列可分为急性淋巴细胞白血病（ALL）和急性髓系白血病（AML）。其中AML又分为M₀（急性髓细胞白血病微分化型）、M₁（急性粒细胞白血病未分化型）、M₂（急性粒细胞白血病部分分化型）、M₃（急性早幼粒细胞白血病）、M₄（急性粒-单核细胞白血病）、M₅（急性单核细胞白血病）、M₆（红白血病）和M₇（急性巨核细胞白血病）。牙龈增生、肿胀多见于急性单核细胞白血病（M₅）和急性粒-单核细胞白血病（M₄）（B对）。T细胞急淋白血病（十版内科学P579）（E错）常见纵隔淋巴结肿大。","","N"],["2000-N129",8,"第一节 间质性肺疾病的分类","间质性肺疾病肺功能",2000,129,"C","","间质性肺炎患者",[["A","限制性通气功能障碍"],["B","弥散功能降低"],["C","二者均可有"],["D","二者均可无"]],"C","间质性肺炎是一组主要累及肺间质和肺泡腔，导致肺泡-毛细血管功能单位丧失的弥散性肺疾病。临床上主要表现为进行性加重的呼吸困难、限制性通气功能障碍（A对）伴弥散功能降低（B对）、低氧血症以及影像学上的双肺弥漫性病变。本题AB均对，正确答案为C。","","N"],["2000-N130",12,"第一节 急性呼吸窘迫综合征","急性呼吸窘迫综合征临床表现",2000,130,"C","","ARDS患者",[["A","限制性通气功能障碍"],["B","弥散功能降低"],["C","二者均可有"],["D","二者均可无"]],"C","ARDS的主要病理特征是炎症导致的肺微血管通透性增高，肺泡腔渗出富含蛋白质的液体，进而导致肺水肿及透明膜形成使呼吸膜增厚，影响气体交换，导致弥散功能降低（B对），病变进一步发展导致肺间质纤维化，出现肺容积减少、肺顺应性降低等限制性通气功能障碍（A对）的表现。本题AB均对，正确答案为C。","","N"],["2000-N131",75,"第一节 中毒概述","血液净化",2000,131,"C","","苯巴比妥钠中毒",[["A","血液透析"],["B","应用强化利尿剂"],["C","二者均可用"],["D","二者均不用"]],"C","苯巴比妥钠为非脂溶性的毒物，中毒后可通过血液透析排出（A对）。苯巴比妥钠中毒后大部分由肾脏排出，有27%～50%以原形从肾脏排出，因此可应用利尿剂促进排泄（B对）。本题AB均对，正确答案为C。","","N"],["2000-N132",75,"第二节 农药中毒","急性有机磷杀虫药中毒治疗",2000,132,"C","","有机磷杀虫药中毒",[["A","血液透析"],["B","应用强化利尿剂"],["C","二者均可用"],["D","二者均不用"]],"D","有机磷杀虫药（OPI）为脂溶性，一般不进行血液透析（A错）。中毒后应洗胃迅速清除毒物，同时使用解毒药胆碱酯酶复活药和胆碱受体拮抗剂。有机磷杀虫药为脂溶性，不能以原形的形式经肾脏排泄，通过肾脏排泄多以代谢产物（如对硝基酚、三氯乙醇等）的形式，因此有机磷杀虫药中毒不宜应用强效利尿剂（B错）。本题AB均错，正确答案为D。","","N"],["2000-N133",40,"第二节 急性肾小球肾炎","急性肾小球肾炎实验室检查",2000,133,"C","","急性肾小球肾炎",[["A","血清抗肾小球基底膜抗体阳性"],["B","血清ANCA阳性"],["C","两者均有"],["D","两者均无"]],"D","急性肾小球肾炎发病机制：β-溶血性链球菌感染引发免疫反应，引起1.循环免疫复合物沉积于肾小球而致病；2.种植于肾小球的抗原与特异性抗体结合形成原位免疫复合物而致病（十版内科学474）。血清抗肾小球基底膜抗体阳性（A错）主要见于急进性肾小球肾炎Ⅰ型，血清ANCA阳性（B错）主要见于急进性肾小球肾炎Ⅲ型。二者均不会出现于急性肾小球肾炎中（本题AB均错，正确答案为D）。","","N"],["2000-N134",40,"第三节 急进性肾小球肾炎","急进性肾小球肾炎实验室检查",2000,134,"C","","急进性肾小球肾炎Ⅰ型",[["A","血清抗肾小球基底膜抗体阳性"],["B","血清ANCA阳性"],["C","两者均有"],["D","两者均无"]],"A","急进性肾小球肾炎Ⅰ型，又称抗肾小球基底膜型肾小球肾炎，发病机制为抗肾小球基底膜抗体与肾小球基底膜（GBM）抗原结合激活补体致病，故抗肾小球基底膜抗体阳性（A对）。血清中ANCA阳性（B错）见于原发性小血管炎引起的Ⅲ型急进性肾小球肾炎。","","N"],["2000-N151",17,"第四节 急性冠状综合征","心电图",2000,151,"X","","心电图Ⅱ、Ⅲ、AVF、V₆、V₇导运动后出现ST段水平下降，最可能涉及的冠状动脉",[["A","右冠状动脉"],["B","左前降支"],["C","左回旋支"],["D","左主干"]],"AC","右冠状动脉主要分布于右心室大部、左心室后壁、下壁，心电图对应导联为Ⅱ、Ⅲ、aVF。左前降支（B错）主要分布于左心室前壁、前乳头肌、心尖、室间隔等，心电图对应导联为V₁、V₂、V₃、V₄。左回旋支主要分布于左心室前侧壁、高侧壁，心电图对应导联为V₅、V₆、Ⅰ、aVL。左主干（D错）很短，约5～10mm，然后分为左前降支和左回旋支。该患者运动后出现心电图Ⅱ、Ⅲ、AVF、V₆、V₇导联出现ST段水平下降，提示下壁及前侧壁梗死，根据正常人冠脉供血范围推测，最可能涉及的冠状动脉为右冠状动脉（A对）及左回旋支（C对）。","","N"],["2000-N152",10,"第三节 慢性肺源性心脏病","肺性脑病",2000,152,"X","","关于肺源性心脏病呼吸衰竭的氧疗，下列哪些正确",[["A","提高肺泡内PaO₂，增加O₂弥散能力"],["B","提高动脉血氧饱和度，增加可利用氧"],["C","增加肺泡通气量，促进CO₂排出"],["D","降低肺循环阻力和肺动脉压，增强心肌收缩力"]],"ABD","氧疗的原则是在保证氧分压迅速提高到60mmHg或脉搏容积血氧饱和度达到90%以上的前提下，尽量降低吸氧浓度。氧疗可提高肺泡内氧分压，加大肺泡和毛细血管之间的氧分压差，增加O₂的弥散能力（A对），从而提高动脉血氧饱和度，增加可利用氧，提高患者的活动耐力和延长生存时间。（B对）。由于缺氧会导致肺血管收缩，肺动脉压力增高，故氧疗还可通过降低肺循环阻力和肺动脉压，降低后负荷，增加心肌收缩力（D对）。氧疗只能提高氧分压及血氧饱和度，但不能增加肺泡通气量及促进CO₂的排出（C错）。","","N"],["2000-N153",30,"第一节 溃疡性结肠炎","肠外表现",2000,153,"X","","下列哪些是炎症性肠病的肠外表现",[["A","杵状指"],["B","虹膜睫状体炎"],["C","口腔黏膜溃疡"],["D","结节性红斑"]],"ABCD","炎症性肠病的主要疾病类型包括溃疡性结肠炎和克罗恩病。由于炎症性肠病为一种免疫性疾病，虽主要累及肠道，但是全身其他系统器官亦可受累。溃疡性结肠炎肠外表现包括：外周关节炎、结节性红斑（D对）、坏疽性脓皮病、巩膜外层炎、前葡萄膜炎、口腔复发性溃疡（C对）等，这些肠外表现在结肠炎控制或结肠切除后可以缓解或恢复；骶髂关节炎、强直性脊柱炎、原发性硬化性胆管炎及少见的淀粉样变性、急性发热性嗜中性皮肤病等，可与溃疡性结肠炎共存，但与溃疡性结肠炎本身的病情变化无关。（八年制第3版内科学P494）克罗恩病肠外表现包括：杵状指（趾）（A对）、关节炎、结节性红斑、坏疽性脓皮病、口腔粘膜溃疡、虹膜睫状体炎（B对）、葡萄膜炎、小胆管周围炎、硬化性胆管炎、慢性活动性肝炎等，淀粉样变性或血栓栓塞性疾病亦偶有所见。","","N"],["2000-N154",45,"第一节 慢性肾衰竭","肾脏替代治疗",2000,154,"X","","下列哪些是慢性肾功能衰竭的透析指征",[["A","血BUN≥35.7mmol/L（100mg/dl）"],["B","血钾＞6.0mmol"],["C","二氧化碳结合力＜17.1mmol/L"],["D","血肌酐＞884μmol/L（10mg/dl）"]],"AD","肾透析治疗的指征包括：①血钾大于6.5mmol/L（B错）；②血尿素氮＞21.4mmol/L（A对），或血肌酐＞442μmol/L（D对）；③血肌酐每日升高＞176.8μmol/L，或血尿素氮每日升高＞8.9mmol/L；④急性肺水肿；⑤无明显高分解代谢，但无尿2天或少尿4天以上；⑥严重酸中毒：CO₂CP＜13mmol/L（C错）、pH＜7.25（九版内科学更新数据为pH ＜ 7.2）。本题选项的数据来源为旧版教材（五版内科学P567），有关急性肾损伤（肾衰竭）的肾脏代替治疗以十版内科学P523相关内容为准。","","N"],["2000-N155",53,"第二节 非霍奇金淋巴瘤","惰性淋巴瘤",2000,155,"X","","下列哪些NHL病人可考虑以放疗为主",[["A","低度恶性组临床分期Ⅰ期"],["B","中度恶性组病理分期Ⅰ期"],["C","高度恶性组病理分期Ⅰ期"],["D","低度恶性组临床分期Ⅱ期"]],"AD","NHL（非霍奇金淋巴瘤）多中心发生的倾向使其临床分期的价值和扩大照射的治疗作用不如霍奇金淋巴瘤，只有低度恶性组Ⅰ、Ⅱ期以放疗为主（AD对）。中度恶性组和高度恶性组Ⅰ、Ⅱ期均应以化疗为主，仅在必要时补充局部照射，采用化疗+放疗+化疗的方法治疗（BC错）。","","N"],["2000-N156",61,"第二节 糖尿病酮症酸中毒","糖尿病酮症酸中毒实验室检查",2000,156,"X","","下列哪些符合糖尿病酮症酸中毒的实验室检查结果",[["A","血糖多数为16.7～33.3mmol/L（300～600mg/dl）"],["B","血酮体多在4.8mmol/L（50mg/dl）以上"],["C","碱剩余负值增大"],["D","阴离子间隙增大，与碳酸氢盐降低大致相等"]],"ABCD","糖尿病酮症酸中毒血糖增高，一般为16.7～33.3mmo1/L（A对），有时可达55.5mmol/L以上。血酮体升高，＞1.0mmol/L为高血酮，＞3.0mmol/L提示可有酸中毒，血酮体多在4.8mmol/L（50mg/dl）以上（B对）。血实际HCO₃⁻和标准HCO₃⁻降低，CO₂结合力降低，酸中毒失代偿后血pH下降；剩余碱负值增大（C对），阴离子间隙增大，与碳酸氢盐降低大致相等（D对）。","","N"],["2001-N47",17,"第四节 急性冠状综合征","不稳定型心绞痛和非ST段抬高型心肌梗死诊断",2001,47,"A","","关于卧位型心绞痛，下列哪项不正确",[["A","属稳定型心绞痛范畴"],["B","可偶在午睡时发作"],["C","可能与冠心病患者左心室功能下降有关"],["D","硝酸甘油疗效较差"],["E","可出现心肌梗塞或猝死"]],"A","卧位型心绞痛是指平卧位时发生的心绞痛，常在休息或熟睡时发生，也可在午睡时发生（B对），发作时需立即坐起甚至站立，方能缓解，属自发性心绞痛，不属于稳定型心绞痛（A错，为本题正确答案），硝酸甘油疗效较差（D对），往往不能缓解此型心绞痛的症状。冠状动脉严重粥样硬化狭窄使冠状动脉循环储备能力明显下降是卧位型心绞痛的最主要的病理基础，也与冠心病患者左心室功能下降有关（C对）。平卧时静脉回心血量增加，心脏做功和需氧增加，患者可出现心肌梗塞或猝死（E对）。稳定型心绞痛也称劳力性心绞痛，是在冠状动脉固定性严重狭窄基础上，由于心肌负荷的增加引起心肌急剧的、暂时性的缺血缺氧临床综合征，通常由体力劳动或情绪激动所诱发，饱食、寒冷、吸烟、休克等因素亦可诱发。","","N"],["2001-N48",15,"第二节 慢性心力衰竭","RAAS抑制剂",2001,48,"A","","对降低慢性心力衰竭患者总死亡率较为肯定的药物是",[["A","利尿剂类"],["B","硝酸酯类"],["C","α受体兴奋剂类"],["D","钙离子拮抗剂类"],["E","血管紧张素转换酶抑制剂类"]],"E","临床研究证实ACEI早期足量应用除可缓解症状，还能延缓心衰进展，降低不同病因、不同程度心力衰竭患者及伴或不伴冠心病患者的死亡率（E对）。并且《中国心力衰竭诊断和治疗指南2014》中提出，血管紧张素转换酶抑制剂是被证实能降低心衰患者病死率的第一类药物，是公认的治疗心衰的基石和首选药物。利尿剂（A错）是心力衰竭治疗中改善症状的基石，是心衰治疗中唯一能够控制体液潴留的药物，但是降低患者死亡率的作用不肯定。硝酸酯类（B错）、α受体兴奋剂类（C错）均对降低慢性心力衰竭患者总死亡率无影响。大多数钙通道阻滞剂，尤其是短效的二氢吡啶类以及具有负性肌力作用的钙通道拮抗剂，不能改善慢性心力衰竭患者的症状或提高运动耐量，短期治疗可导致肺水肿和心源性休克，长期应用使心功能恶化，死亡危险增加。只有在慢性心力衰竭患者合并严重高血压或心绞痛，其他药物不能控制时使用氨氯地平或非洛地平，二者长期使用安全性较好，虽不能提高生存率，但对预后并无不利影响（D错）。","","N"],["2001-N49",15,"第二节 慢性心力衰竭","左心衰竭症状",2001,49,"A","","左心功能不全、肺循环淤血的主要临床表现，下列哪项不正确",[["A","咳嗽、咳痰，痰为浆液性，呈白色泡沫状"],["B","劳力性呼吸困难，休息即缓解"],["C","肺微小动脉压增高，血浆外渗，痰内带血丝"],["D","阵发性夜间呼吸困难"],["E","支气管痉挛，发作性哮喘"]],"C","左心功能不全时，左心房压力升高，致使肺静脉和毛细血管淤血、毛细血管内压力过度升高可使毛细血管破裂，出现痰内带血丝（C错，为本题正确答案）。肺微小动脉破裂出血时，出血量较大，可见于支气管扩张症。左心功能不全时最早出现的症状就是劳力性呼吸困难，休息即缓解（B对）。左心功能不全加重，会导致夜间阵发性呼吸困难（D对），重者可有哮鸣音，称为“心源性哮喘”，其发生机制除睡眠平卧血液重新分配使肺血量增加外，有夜间迷走神经张力增加、小支气管收缩、横膈抬高、肺活量减少等因素，表现为广泛的湿啰音和哮鸣音（E对），易与支气管哮喘混淆。","","N"],["2001-N50",19,"第六节 心肌炎","纠正心律失常",2001,50,"A","","某患者，女性，17岁，两周前感冒，一天来胸闷、气短、头晕，行走时出现眼前发黑。查体BP85/50mmHg，心律不整，心率36次/分，心电图为Ⅲ度房室传导阻滞、多源性室性心律，应选用的最佳治疗方案是",[["A","阿托品静注"],["B","异丙基肾上腺素静点"],["C","利多卡因静点"],["D","多巴胺静点"],["E","以上都不是"]],"E","年轻女性患者，两周前感冒（病毒感染的前驱症状），一天来胸闷、气短、头晕（病毒性心肌炎的常见症状），心电图为Ⅲ度房室传导阻滞、多源性室性心律，诊断最大可能为急性病毒性心肌炎并发重症心律失常。患者心律不齐，心率偏低（36次/分），心电图示Ⅲ度房室传导阻滞、多源性室性心律，最佳治疗方案应该是安装临时心脏起搏器（E对），以提高并稳定心室率，维持心输出量的稳定，缓解供血不足。","","N"],["2001-N51",16,"第七节 抗心律失常药物的合理应用","药物",2001,51,"A","","下列哪项不是胺碘酮的常见药物不良反应",[["A","低血糖"],["B","室性快速性心律失常"],["C","肺纤维化"],["D","角膜微粒沉着"],["E","光过敏"]],"A","低血糖（A错，为本题正确答案）为β受体拮抗剂的副作用（九版内科学P206）。胺碘酮不良反应可发生在各个系统，肺纤维化（C对）是最严重的心外毒性反应，还可见转氨酶升高，偶致肝硬化、光过敏（E对）、角膜微粒沉着（D对）。心脏方面可见心动过缓，致心律失常很少发生，偶尔发生尖端扭转型室性快速性心律失常（B对）。此外，其他系统还可见胃肠道反应、甲状腺功能亢进或甲状腺功能减退等。","","N"],["2001-N52",16,"第三节 房性心律失常","心房颤动临床表现",2001,52,"A","","心房颤动发生后至少可使心排血量下降",[["A","35%"],["B","30%"],["C","25%"],["D","20%"],["E","15%"]],"C","在全心舒张期内，回流入心室的血液量占心室总充盈量的约70%，全心舒张期之后是心房收缩期，由心房收缩推动进入心室的血液通常只占心室总充盈量的25%左右（九版生理学P87）。房颤时心房激动的频率达350～600次/分，心房失去有效收缩，心室充盈量减少，故可使心排血量降低至少25%（C对）。","","N"],["2001-N53",16,"第四节 房室交界性心律失常","心室预激",2001,53,"A","","下列哪项对诊断预激综合征最有价值",[["A","食管调搏检查"],["B","超声心动图检查"],["C","24小时动态心电图检查"],["D","心内电生理检查"],["E","冠状动脉及左心室造影"]],"D","预激综合征（十版内科学P206）是指心电图呈预激表现，临床上有心动过速发作。其解剖学基础是房室旁路（Kent束），其他还有房希氏束、结室纤维、分支室纤维。应用心内电生理检查（D对）可了解心律失常的类型、起源部位与发病机制，此外还可以进行治疗、判断预后，因此是诊断预激综合征最有价值的检查方法。食管调搏检查（A错）是将电极导管插入食管中段（左心房邻近处），通过间接有序地刺激左心房产生激动，从而达到了解电生理活动的目的。但该检查诊断价值不及心内电生理检查。超声心动图检查（B错）可反映心脏结构和功能状态，但对检查心脏电活动无意义。24h动态心电图检查（C错）只能粗略了解心肌电活动，可提高对一过性心律失常及短暂的心肌缺血发作的检出率。冠脉造影为诊断冠心病的金标准，左心室造影用于了解左心功能（E错）。","","N"],["2001-N54",2,"第一节 支气管哮喘","支气管哮喘临床表现",2001,54,"A","","关于支气管哮喘发作的临床表现，下列哪项不正确",[["A","强迫端坐位"],["B","出现严重呼气性呼吸困难"],["C","呼吸动度增大、呈吸气位"],["D","语音震颤减弱"],["E","大汗淋漓伴紫绀"]],"C","支气管哮喘是由多种细胞和细胞组分参与的气道慢性炎症性疾病。哮喘的典型表现为发作性呼气性呼吸困难（B对），呼吸动度变小，呈吸气位，可有三凹征（C错，为本题正确答案），病情严重患者常强迫端坐位（A对），大汗淋漓伴紫绀（E对），双肺可闻及广泛的哮鸣音，肺过度通气，语音震颤减弱（D对），呼吸音和语音共振减弱，叩诊过清音。","","N"],["2001-N55",11,"第一节 胸腔积液","胸腔积液临床表现",2001,55,"A","","关于胸腔积液，下列哪项不正确",[["A","积液量在300～500mL时可无临床症状"],["B","积液量大于300mL可出现X线表现"],["C","CT检查对提示积液性质无效"],["D","B超是敏感性最高的检查胸腔积液的无创性诊断方法"],["E","X线胸片可不表现为弧形向上的积液影"]],"C","少量胸腔积液可无明显症状或仅有胸痛，并随呼吸运动疼痛加剧；积液量在300～500mL时可无临床症状（A对）；胸腔积液300～500ml以上时，可感胸闷或者气急；随着胸腔积液增多，胸闷、气急逐渐加剧；大量胸腔积液时，可出现呼吸困难和心悸。较少量胸腔积液时胸部X线检查不易发现。当积液量达300～500ml时，胸部X线检查显示肋膈角变钝（BE对），随着胸腔积液增多，显示一凹面向上、外侧高内侧低的弧形积液影。B超探测胸腔积液的灵敏度高，定位准确，是敏感性最高的检查胸腔积液的无创性诊断方法（D对）。CT或PET/CT可显示胸腔积液及肺内病变、胸膜间皮瘤、胸内或胸膜转移性肿瘤、纵隔和气管旁淋巴结等病变，有助于病因诊断，对提示积液性质有重要作用（C错，为本题正确答案）。","","N"],["2001-N56",6,"第一节 肺结核","肺结核临床表现",2001,56,"A","","关于结核病的呼吸系统症状，下列哪项正确",[["A","约半数的病人有不同程度的咯血"],["B","痰中带血可因空洞中血管瘤破裂造成"],["C","炎症波及壁层胸膜时可出现剧烈胸痛"],["D","咯血后发热持续不退，提示有结核病播散"],["E","一般无急骤出现的呼吸困难"]],"D","结核病的呼吸系统症状常表现为咳嗽、咳痰，约有1/3的病人会出现不同程度的咯血（A错）。痰中带血为结核性炎症使毛细血管扩张，通透性增高所致（B错）；病变损伤小血管则血量增加；若空洞中小动脉瘤破裂则引起大咯血，出血可以源自肺动脉，亦可来自支气管动脉。咯血易引起结核播散，特别是中、大量咯血时，咯血后的持续高热常是有力提示（D对）。炎症波及壁层胸膜时，出现胸膜性胸痛，随呼吸和咳嗽加重，而非剧烈胸痛（C错）。当结核病病变引起干酪样肺炎或大量胸腔积液时，患者可出现急性、严重的呼吸困难（E错）。","","N"],["2001-N57",4,"第二节细菌性肺炎","葡萄球菌肺炎诊断",2001,57,"A","","某糖尿病患者，男性，68岁，突发高热、寒战、右胸痛，次日咳痰，为黄脓性带血丝，量多，X线显示右下肺叶实变，其中有多个液气囊腔，最可能的诊断是",[["A","干酪性肺炎"],["B","绿脓杆菌性肺炎"],["C","克雷伯杆菌肺炎"],["D","葡萄球菌性肺炎"],["E","军团菌性肺炎"]],"D","患者糖尿病病史（葡萄球菌肺炎常发生于有基础疾病如糖尿病、血液病等疾病者），突发高热、寒战、右胸痛等表现，并伴有咳嗽、咳痰，痰液黄脓性带血丝（葡萄球菌肺炎的痰液特点），量多，X线显示右下肺叶实变，并有多个液气囊腔（葡萄球菌肺炎的典型X线表现），故最可能的诊断是葡萄球菌性肺炎（D对）。干酪性肺炎（十版内科学P77）（A错）为继发性肺结核的一种，多表现低热、乏力、消瘦等明显的全身结核中毒症状，X线表现可见密度均匀磨玻璃状阴影，逐渐出现溶解区，呈虫蚀样空洞，可出现播散病灶；绿脓杆菌性肺炎（十版内科学P49）（B错）全身中毒症状明显，咳嗽、咳痰，痰液呈蓝绿色，X线表现为弥漫性支气管炎，早期肺脓肿；克雷伯杆菌肺炎（十版内科学P49）（C错）起病急、寒战、高热、全身衰竭等全身症状明显，咳砖红色胶冻样痰，X线表现蜂窝状脓肿，叶间隙下坠；军团菌性肺炎（十版内科学P49）（E错）患者常有疲乏、无力、肌痛、畏寒、发热等全身性表现，咳嗽、咳痰，咳黏痰带少量血丝或血痰，量少，有时可为脓性，X线表现斑片状浸润。","","N"],["2001-N58",13,"第三节 慢性呼吸衰竭","慢性呼吸衰竭血气分析",2001,58,"A","","下列哪项不符合呼吸性酸中毒合并代谢性酸中毒的血气检查结果",[["A","PaCO₂升高"],["B","HCO₃⁻减少"],["C","AB=SB≤正常值"],["D","BE负值减小"],["E","pH明显降低"]],"D","呼吸性酸中毒合并代谢性酸中毒时，在CO₂潴留的基础上酸性物质产生明显增多，使PaCO₂升高（A对），pH明显降低（E对），H⁺增高，和HCO₃⁻结合产生CO₂，使HCO₃⁻减少（B对）。SB（标准碳酸氢盐）为在标准状态下，动脉血测得的碳酸氢盐含量，AB（实际碳酸氢盐）为在隔绝空气的状态下，动脉血测得的实际碳酸氢盐含量。当AB与SB均低，而AB=SB，提示失代偿的代谢性酸中毒；当AB与SB均高，而AB=SB，提示失代偿的代谢性碱中毒。当呼吸性酸中毒时，AB＞SB。故呼吸性酸中毒合并代谢性酸中毒时，通常为AB（实际碳酸氢盐）＞SB（标准碳酸氢盐）且均小于正常值（C错，为本题正确答案）。BE（剩余碱）是反映代谢性酸碱平衡的指标，BE负值增大，代表代谢性酸中毒；BE正值增大，代表代谢性碱中毒。呼吸性酸中毒合并代谢性酸中毒时，酸性物质明显增多，剩余碱减少，BE负值增大（D错，为本题正确答案）。本题正确答案应为CD，官方给出的参考答案为D。","","N"],["2001-N59",5,"第一节 肺脓肿","肺脓肿临床表现",2001,59,"A","","关于肺脓肿的临床特点，下列哪项不正确",[["A","最常见的病原菌为金黄色葡萄球菌"],["B","病原体自口及鼻吸入是发病的主要原因"],["C","70%～90%的病例为急性起病"],["D","并非所有肺脓肿患者都能在肺部发现异常体征"],["E","多数肺脓肿的感染对青霉素治疗敏感"]],"A","吸入性肺脓肿是肺脓肿最常见的类型，约占60%，病原体经口、鼻、咽腔吸入致病（B对），其最常见的病原菌为厌氧菌（A错，为本题正确答案），一般对青霉素敏感，所以多数肺脓肿的感染对青霉素治疗敏感（E对）。其次为血源性肺脓肿，其以金黄色葡萄球菌感染最为多见。肺脓肿70%～90%的病例为急性起病（C对），肺部体征与肺脓肿的大小和部位有关，初起时肺部可无阳性体征，血源性肺脓肿大多也无阳性体征（D对）。","","N"],["2001-N60",13,"第三节 慢性呼吸衰竭","正压机械通气",2001,60,"A","","关于呼吸衰竭的治疗，下列哪项提法不正确",[["A","增加肺泡通气量才能纠正呼吸性酸中毒"],["B","采用PEEP方式有利于改善换气功能"],["C","呼吸兴奋剂可用于有呼吸肌病变及肺间质纤维化的患者"],["D","氧疗应使PaO₂在60mmHg以上，SaO₂为90%以上"],["E","在合并心衰时，如有血氧饱和度上升，则有使用利尿剂的指征"]],"C","Ⅱ型呼吸衰竭主要是由于肺泡通气不足，导致血氧降低和呼吸性酸中毒，所以保持呼吸道通畅，降低呼吸阻力，增加肺泡通气量才能纠正呼吸性酸中毒（A对）。PEEP（呼吸末正压）可使萎陷的小气道和肺泡再开放，防止肺泡随呼吸周期反复开闭，使呼气末肺容量增加，减轻肺损伤，改善肺泡换气功能（十版内科学P146）（B对）治疗呼吸衰竭。呼吸兴奋剂是在呼吸肌功能正常的前提下，通过刺激外周或中枢化学感受器，兴奋呼吸中枢，提高呼吸肌做功效率，增加肺通气量，治疗呼吸衰竭，主要适用于以中枢抑制为主、通气量不足引起的呼吸衰竭，不宜用于以肺换气功能障碍为主所致的呼吸衰竭。当呼吸肌病变时，治疗效果较差；间质纤维化主要表现为换气障碍，用呼吸兴奋剂不能改善症状，反而使呼吸肌过度做功，增加氧耗，故不宜使用（C错，为本题正确答案）。伴明显CO₂潴留的呼吸衰竭，宜采用持续低流量给氧（浓度＜35%，流量1～2L/min，每日10h以上，维持PaO₂≥60mmHg，SaO₂≥90%）（九版内科学P143）（D对）。在合并心衰时，一般在积极控制感染，通畅呼吸道，改善呼吸功能，纠正缺氧和二氧化碳的潴留之后，心力衰竭能得到改善，若患者仍有水肿、少尿等症状，可以在血氧饱和度升高的基础上，适当使用利尿剂以消除水肿，减少右心前负荷（E对）。","","N"],["2001-N61",35,"第一节 肝硬化","肝硬化代偿期",2001,61,"A","","下列哪一项不是肝硬化代偿期的表现",[["A","乏力、食欲减退"],["B","食管和胃底静脉曲张"],["C","肝脏质地结实或偏硬"],["D","脾脏中度肿大"],["E","肝功能轻度异常"]],"B","肝硬化起病隐匿，代偿期期可无特异性症状、体征，常出现乏力、食欲减退（A对）等非特异症状，肝脏质地结实或偏硬（C对），门脉高压致脾脏轻中度肿大（D对），肝功能可轻度异常（E对）；肝硬化失代偿期症状较明显，主要是分为肝功能减退症状和门静脉高压症状，门静脉高压常导致腹水，门-腔侧支循环开放，如食管胃底静脉曲张（B错，为本题正确答案），其破裂出血是肝硬化门静脉高压最常见的并发症。","","N"],["2001-N62",30,"第一节 溃疡性结肠炎","溃疡性结肠炎并发症",2001,62,"A","","下列哪一种并发症在溃疡性结肠炎最少见",[["A","中毒性巨结肠"],["B","直肠结肠癌变"],["C","直肠结肠大量出血"],["D","肠梗阻"],["E","瘘管形成"]],"E","溃疡性结肠炎的病变多为浅溃疡，一般局限于黏膜和黏膜下层，很少深入肌层，所以并发瘘管（E对）或周围脓肿罕见。约5%的重症溃疡性结肠炎患者可出现中毒性巨结肠（A错）致急性肠扩张，一般以横结肠为最严重，常因低钾、钡剂灌肠、使用抗胆碱能药物或阿片类制剂而诱发（十版内科学P388）。直肠结肠癌变（B错）常因长期粘膜细胞破坏与修复而发生，多见于广泛性结肠炎、幼年起病而病程漫长者，病程＞20年的患者发生结肠癌风险较正常增高10～15倍。直肠结肠大量出血（C错）发生率约3%，常由于肠壁粘膜糜烂、溃疡累及血管所致、肠梗阻（D错）可分为由于肠壁粘膜大量纤维组织增生僵硬变细及炎性息肉阻塞肠道所致的机械性肠梗阻及由于中毒性巨结肠所致的动力性肠梗阻，相对瘘管形成多见。","","N"],["2001-N63",28,"第一节 消化性溃疡","PPI",2001,63,"A","","下列哪一种药物兼有抑制幽门螺杆菌的作用",[["A","甲氰咪胍"],["B","雷尼替丁"],["C","奥美拉唑"],["D","碳酸钙"],["E","胶体铝镁合剂"]],"C","根除幽门螺杆菌通常使用四联方案，1种PPI+2种抗生素和1种铋剂的四联治疗方案有较高根除率（十版内科学P372）。其中PPI和铋剂还可抑制幽门螺旋杆菌，与抗生素联用有协同杀菌作用。本题各选项中，只有奥美拉唑属于PPI（C对）。甲氰咪胍（又称西咪替丁）（A错）和雷尼替丁（B错）均为H₂受体阻断剂，用于治疗消化性溃疡；碳酸钙（D错）为弱碱性物质，口服后在胃内直接中和胃酸，升高胃内pH值，降低胃蛋白酶活性，具有缓解溃疡病的疼痛作用；胶体铝镁合剂（氢氧化铝和镁乳合剂）（E错）为弱碱性抗酸剂，主要作用为中和胃酸，短暂缓解疼痛。","","N"],["2001-N64",28,"第一节 消化性溃疡","消化性溃疡病因和发病机制",2001,64,"A","","关于十二指肠溃疡（DU）的描述，下列哪项不正确",[["A","DU患者中，2/3有胃酸分泌过高现象"],["B","壁细胞总数小于10亿个不会发生DU"],["C","MAO小于10mmol/h不会发生DU"],["D","由幽门螺杆菌引起的DU均有胃窦炎存在"],["E","DU有导致胃酸分泌异常的多种因素"]],"A","十二指肠溃疡（DU）患者中约有20%～50%患者胃酸分泌高于正常（A错，为本题正确答案）。DU患者胃酸分泌增多，主要与壁细胞总数增多有关，正常人的胃黏膜内大约有10亿壁细胞，平均每小时分泌盐酸22mmol，而DU患者的壁细胞总数平均为19亿，每小时分泌盐酸约42mmol（十版内科学P374），胃酸分泌量与壁细胞总数相平行，壁细胞总数少于10亿个很少（试题选项为“不会”）发生DU（B错）。DU患者的平均基础酸排量（BAO）和最大酸排量（MAO）常大于正常，MAO小于10mmol/h很少（试题选项为“不会”）发生DU（C错）。由幽门螺杆菌引起的DU常（试题选项为“均有”）合并胃窦炎（D错）。导致十二指肠溃疡患者胃酸分泌增多的因素很多（E对），如壁细胞总数增多、壁细胞对刺激物的敏感性增强、胃酸分泌的正常反馈机制发生缺陷等。注意：本题为旧试题，十版内科学已经删除部分知识点，不必深究。","","N"],["2001-N65",27,"第二节 慢性胃炎","Hp感染",2001,65,"A","","B型胃炎主要是由下列哪个原因引起",[["A","幽门螺杆菌感染"],["B","胆汁反流"],["C","消炎药物"],["D","吸烟"],["E","酒癖"]],"A","B型胃炎病变主要位于胃窦部，90%由幽门螺杆菌感染引起（A对），胆汁反流（B错）、消炎药物（C错）如非甾体抗炎药、嗜烟酒（DE错）均为B型胃炎的病因，但不是主要病因。A型胃炎多由自身免疫性反应引起。","","N"],["2001-N66",37,"第一节 急性胰腺炎","胰腺局部并发症",2001,66,"A","","出血坏死型胰腺炎时的Cullen征是指",[["A","胁腹皮肤呈灰紫色斑"],["B","脐周皮肤呈灰紫色斑"],["C","胁腹皮肤青紫"],["D","脐周皮肤青紫"],["E","脐周皮肤红斑"]],"D","出血坏死型胰腺炎时，少数患者因胰酶、坏死组织及出血沿腹膜间隙与肌层渗入腹壁下，致两侧肋腹部皮肤呈暗灰蓝色，称Grey-Turner征；可致脐周围皮肤青紫，称Cullen征（D对）。","","N"],["2001-N67",53,"第二节 非霍奇金淋巴瘤","非霍奇金淋巴瘤临床表现",2001,67,"A","","NHL最常累及胃肠道的部位是",[["A","胃"],["B","十二指肠"],["C","回肠"],["D","结肠"],["E","直肠"]],"C","NHL（非霍奇金淋巴瘤）是一组具有不同的组织学特点和起病部位的淋巴瘤，易发生早期远处扩散（十版内科学P593）。对于NHL患者，当累及到胃肠道时，多发于回肠部位（C对），可能与该部位有大量的淋巴滤泡聚集有关。其次为胃，其他部位较少受累（ABDE错）。","","N"],["2001-N68",47,"第一节 缺铁性贫血","缺铁性贫血临床表现",2001,68,"A","","关于缺铁性贫血患者的表现，下列哪项不正确",[["A","感染发生率减低"],["B","口角炎、舌炎、舌乳头萎缩较常见"],["C","胃酸缺乏及胃肠功能障碍"],["D","毛发无泽、易断、易脱"],["E","指甲扁平，甚至“反甲”"]],"A","缺铁性贫血的临床表现可分为三类：缺铁原发病表现、贫血表现和组织缺铁表现。易感染（A错，为本题正确答案）；口角炎、舌炎、舌乳头萎缩（B对）；毛发无泽、易断、易脱（D对）；指甲扁平、甚至“反甲”（E对）等均为组织缺铁的表现。缺铁性贫血患者胃黏膜供氧减少，影响质子泵的功能，导致胃酸缺乏及胃肠功能障碍（C对）。","","N"],["2001-N69",46,"","",2001,69,"A","","急性失血性贫血患者，当丢失血容量至少达多少时即可有休克表现",[["A","10%"],["B","20%"],["C","25%"],["D","30%"],["E","35%"]],"B","人体通常在迅速失血超过全身总血量的20%时，即出现休克（B对）。根据休克的分度，失血小于20%属于休克代偿期（轻度休克），患者仅有口渴等临床表现，无贫血表现。失血20%～40%属于休克失代偿期（中度休克），患者出现皮肤黏膜苍白、发冷等贫血表现。失血大于40%属于休克失代偿期（重度休克），患者除贫血表现外，还会出现意识模糊甚至昏迷等。","","N"],["2001-N71",40,"第三节 急进性肾小球肾炎","急进性肾小球肾炎诊断",2001,71,"A","","下列哪一项不支持急进性肾小球肾炎的诊断",[["A","呈急性肾炎综合征"],["B","肾功能急剧恶化"],["C","早期出现少尿性急性肾功能衰竭"],["D","数周至半年进展至尿毒症"],["E","常无贫血表现"]],"E","急进性肾小球肾炎是一组表现为血尿、蛋白尿及进行性肾功能减退（B对）的临床综合征，是肾小球肾炎中最严重的类型，可见于任何年龄，但以青年和中、老年为多，该病可呈急性起病，多数病人在发热或上呼吸道感染后出现急性肾炎综合征（A对），病情发展很快，起病数天内即出现少尿及进行性肾功能衰竭（C对）并发展成尿毒症（D对）。急进性肾小球肾炎患者肾小管间质细胞损伤，分泌的促红细胞生成素减少；肾小球滤过膜损伤，血细胞还会随尿液排出，故急进性肾小球肾炎患者常伴有中度贫血（E错，为本题正确答案）。","","N"],["2001-N72",41,"第一节 尿路感染","急性肾盂肾炎",2001,72,"A","","有关肾区疼痛，下列哪项不正确",[["A","间质性肾炎有肾区压痛"],["B","IgA肾病有肾区压痛"],["C","肾盂积液有肾区叩痛"],["D","肾盂肾炎有肾区叩痛"],["E","肾动脉栓塞肾区有剧烈疼痛"]],"C","肾区叩痛是指竖脊肌外侧缘和第12肋的夹角处，叩击疼痛，常提示肾脏包括肾周围组织有炎症、肾结核、肾结石或肿瘤等。肾盂积液，只要不合并感染，在发作间隙期，病人可无任何症状，不会有肾区叩痛（C错，为本题正确答案）。间质性肾炎的发病与感染、自身免疫、药物及代谢等因素有关，其中药物引起的间质性肾炎常表现为少尿性或非少尿性急性肾损伤，部分可伴有肾区压痛（二版八年制内科学P627）（A对）。IgA肾病病人的典型临床表现为无症状性血尿，肾脏肿胀牵拉肾被膜及肾外小血管时可有肾区压痛（B对）。肾盂肾炎除发热、心动过速和全身肌肉压痛外，还可发现一侧或两侧肋脊角或输尿管点压痛和（或）肾区叩击痛（D对）。肾动脉栓塞（E对）可引起患侧剧烈腰痛、肋脊角（肾区）叩痛、蛋白尿及血尿。","","N"],["2001-N73",60,"第一节 库欣综合征","库欣综合征诊断依据",2001,73,"A","","某患者，女性，30岁，半年来肥胖，皮肤出现痤疮、紫纹，化验血皮质醇增高，血糖增高，小剂量地塞米松抑制试验血皮质醇较对照低38％，大剂量地塞米松抑制试验血皮质醇较对照低78％。该患者最可能的诊断是",[["A","肾上腺皮质腺瘤"],["B","肾上腺皮质腺癌"],["C","Cushing病"],["D","异位ACTH综合征"],["E","糖尿病"]],"C","该患者为青年女性，半年来肥胖，皮肤出现痤疮、紫纹（库欣综合征典型临床表现为向心性肥胖、满月脸、多血质、紫纹等），化验血皮质醇增高，血糖增高，小剂量地塞米松抑制试验为阴性（较对照日减少50%以上为阳性），大剂量地塞米松抑制试验为阳性。据此，该患者最可能的诊断为Cushing病（C对）：小剂量地塞米松抑制试验主要用于鉴别单纯性肥胖和皮质醇增多症，肥胖者为阳性，皮质醇增多症为阴性；大剂量地塞米松试验主要用于鉴别库欣综合征的病因，Cushing病多数为阳性，肾上腺皮质腺瘤（A错）、肾上腺皮质癌（B错）为阴性，异位ACTH综合征（D错）多数为阴性。糖尿病（十版内科学P728）（E错）患者一般会表现为多尿、多饮、多食、体重减轻等症状，与本例不符。","","N"],["2001-N74",59,"第一节 甲状腺功能亢进症","血清总甲状腺激素",2001,74,"A","","下列哪项对诊断妊娠甲亢无帮助",[["A","血总T₃、T₄升高"],["B","血FT₃、FT₄升高"],["C","体重不随妊娠月数而增加"],["D","休息时脉率100次／分"],["E","四肢近端肌肉消瘦"]],"A","妊娠时，胎盘分泌大量雌激素，可增强唾液酸的作用，延缓血浆中TBG的清除，导致血中TBG升高，血总T₃和T₄增高，属于正常生理表现，无法用于诊断妊娠甲亢（A对）。体重不随妊娠月数增加（C错）、四肢近端肌肉消瘦（E错）、休息时心率在100次/分以上（D错）均属于高代谢症候群的表现，须考虑甲亢可能。血FT₃（游离三碘甲腺原氨酸）、FT₄（游离甲状腺素）升高（B错），TSH（促甲状腺素）＜0.5μmol/L可诊断为妊娠期甲亢。","","N"],["2001-N103",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞体征",2001,103,"B","","渗出性心包炎可出现",[["A","Osler结"],["B","Ewart征"],["C","肝脏扩张性搏动"],["D","Duroziez氏血管杂音"],["E","Beck三联征"]],"B","渗出性心包炎时，渗出液使心脏叩诊浊音界向两侧增大，当有大量积液时可在左肩胛骨下出现叩诊浊音及左肺受压迫所引起的支气管呼吸音，称心包积液征（Ewart征）（B对）。Osler结节（A错）见于亚急性感染性心内膜炎，为指和趾垫出现的豌豆大的红或紫色痛性结节。肝脏扩张性搏动（C错）见于三尖瓣关闭不全，右心室的搏动可经右心房、下腔静脉传导至肝脏，使肝脏出现扩张性搏动。Duroziez氏血管杂音（D错）见于主动脉瓣关闭不全等脉压增大的疾病。将听诊器体件置于股动脉上，稍加压力，在收缩期与舒张期皆可听到吹风样杂音，为连续性。当渗出性心包炎液体迅速增多产生急性心脏压塞时，可出现Beck三联征（E错），表现为低血压、心音低弱、颈静脉怒张，E不是最佳选项。","","N"],["2001-N104",23,"第一节 感染性心内膜炎","周围体征",2001,104,"B","","亚急性感染性心内膜炎可出现",[["A","Osler结"],["B","Ewart征"],["C","肝脏扩张性搏动"],["D","Duroziez氏血管杂音"],["E","Beck三联征"]],"A","Osler结节为指和趾垫出现的豌豆大的红或紫色痛性结节，较常见于亚急性患者，因此亚急性感染性心内膜炎可出现Osler结节（A对）。心包积液征（Ewart征）（B错）为有大量积液时，可在左肩胛骨下出现浊音及左肺受压迫所引起的支气管呼吸音。肝脏扩张性搏动（C错）为三尖瓣关闭不全的特征，系因右心室收缩期搏动经右心房、下腔静脉传递至肝脏，使肝脏呈扩张性。Duroziez氏血管杂音（D错）见于主动脉瓣关闭不全等脉压增大的疾病，听诊器体件置于股动脉上，稍加压力，在收缩期与舒张期皆可听到吹风样杂音，为连续性。Beck三联征（E错）为低血压、心音低弱、颈静脉怒张。在心包积液、心包积血或缩窄性心包炎等限制心脏扩张疾病时出现。","","N"],["2001-N105",75,"第一节 中毒概述","中枢神经抑制剂解毒药",2001,105,"B","","阿片类麻醉药的解毒药是",[["A","依地酸二钠钙"],["B","亚甲蓝"],["C","二巯基丁二钠"],["D","氟马西尼"],["E","纳洛酮"]],"E","阿片类麻醉药的解毒药是纳洛酮（E对）。亚甲蓝（B错）是亚硝酸盐、苯胺或硝基苯等中毒引起的高铁血红蛋白血症的解毒药。依地酸二钠钙（A错）是金属离子铅、锰中毒的解毒药。二巯基丁二钠（C错）是金属离子砷、汞、锑中毒的解毒药。氟马西尼（D错）是苯二氮䓬类中毒的解毒药。","","N"],["2001-N106",75,"第一节 中毒概述","高铁血红蛋白血症解毒药",2001,106,"B","","亚硝酸盐中毒的解毒药是",[["A","依地酸二钠钙"],["B","亚甲蓝"],["C","二巯基丁二钠"],["D","氟马西尼"],["E","纳洛酮"]],"B","亚硝酸盐中毒可氧化红细胞中血红蛋白为高铁血红蛋白而失去携氧能力，可应用亚甲蓝（B对）将高铁血红蛋白还原为正常血红蛋白从而治疗亚硝酸盐中毒。依地酸二钠钙（A错）是金属离子铅、锰中毒的解毒药。二巯基丁二钠（C错）是金属离子砷、汞、锑中毒的解毒药。氟马西尼（D错）是苯二氮䓬类中毒的解毒药。纳洛酮（E错）是阿片类麻醉药的解毒药。","","N"],["2001-N107",52,"第二节 急性白血病","急性白血病免疫学检查",2001,107,"B","","CD19阳性见于",[["A","急性B淋巴细胞白血病"],["B","急性T淋巴细胞白血病"],["C","急性粒细胞白血病"],["D","急性红白血病"],["E","急性巨核细胞白血病"]],"A","CD（白细胞分化抗原）是白细胞分化成熟为不同谱系后以及处于不同分化阶段和活化过程中出现或消失的细胞表面标记，可以根据白血病细胞表达的系列相关抗原确定其来源。急性B淋巴细胞白血病通常表达CD19（A对）、CD20和CD10等。急性T淋巴细胞白血病通常表达CD2、CD5、CD8、CD10（B错）。急性非淋巴细胞白血病通常表达CD117、CD13、CD33、CD65（C错）。","","N"],["2001-N108",52,"第二节 急性白血病","急性白血病免疫学检查",2001,108,"B","","CD13阳性见于",[["A","急性B淋巴细胞白血病"],["B","急性T淋巴细胞白血病"],["C","急性粒细胞白血病"],["D","急性红白血病"],["E","急性巨核细胞白血病"]],"C","CD（白细胞分化抗原）是白细胞分化成熟为不同谱系后以及处于不同分化阶段和活化过程中出现或消失的细胞表面标记，可以根据白血病细胞表达的系列相关抗原确定其来源。急性非淋巴细胞白血病（急性粒细胞白血病、急性单核细胞白血病）通常表达CD117、CD13（C对）、CD33、CD65。急性B淋巴细胞白血病通常表达CD19、CD20和CD10等（A错）。急性T淋巴细胞白血病通常表达CD2、CD5、CD8、CD10（B错）。","","N"],["2001-N109",61,"第一节 糖尿病","胰岛素",2001,109,"B","","中效胰岛素是",[["A","锌结晶胰岛素、半慢胰岛素锌悬液"],["B","半慢胰岛素锌悬液、中性鱼精蛋白锌胰岛素"],["C","慢胰岛素锌悬液、鱼精蛋白锌胰岛素"],["D","慢胰岛素锌悬液、中性鱼精蛋白锌胰岛素"],["E","特慢胰岛素锌悬液，鱼精蛋白锌胰岛素"]],"D","考察胰岛素的分类。按作用起效快慢和维持时间，胰岛素可分为短效、中效、长效和预混胰岛素（P740）。短效胰岛素包括普通胰岛素、锌结晶胰岛素和半慢胰岛素锌混悬液（A错）。中效胰岛素包括低精蛋白锌胰岛素（中性精蛋白锌胰岛素，也可称为中性鱼精蛋白锌胰岛素）、慢胰岛素锌混悬液（D对）。长效胰岛素包括精蛋白锌胰岛素（鱼精蛋白锌胰岛素）（C错）和特慢胰岛素锌悬液（E错）。","","N"],["2001-N110",61,"第一节 糖尿病","胰岛素",2001,110,"B","","长效胰岛素是",[["A","锌结晶胰岛素、半慢胰岛素锌悬液"],["B","半慢胰岛素锌悬液、中性鱼精蛋白锌胰岛素"],["C","慢胰岛素锌悬液、鱼精蛋白锌胰岛素"],["D","慢胰岛素锌悬液、中性鱼精蛋白锌胰岛素"],["E","特慢胰岛素锌悬液，鱼精蛋白锌胰岛素"]],"E","考察胰岛素的分类。按作用起效快慢和维持时间，胰岛素可分为短效、中效、长效和预混胰岛素（十版内科学P738）。短效胰岛素包括普通胰岛素、锌结晶胰岛素和半慢胰岛素锌混悬液（AB错）。中效胰岛素包括低精蛋白锌胰岛素（中性精蛋白锌胰岛素，也可称为中性鱼精蛋白锌胰岛素）（B错）、慢胰岛素锌混悬液（CD错）。长效胰岛素包括精蛋白锌胰岛素（鱼精蛋白锌胰岛素）和特慢胰岛素锌悬液（E对）。","","N"],["2001-N129",39,"第一节 总论","肾炎综合征",2001,129,"C","","肾炎综合征表现有",[["A","血尿"],["B","高血压"],["C","二者都有"],["D","二者都无"]],"C","肾炎综合征是指血尿（A对）、蛋白尿、高血压（B对）、水肿为表现的一组综合征。本题AB均对，正确答案为C。","","N"],["2001-N130",40,"第六节 无症状性血尿和_或蛋白尿","无症状性血尿和_或蛋白尿临床表现",2001,130,"C","","隐匿性肾炎综合征表现有",[["A","血尿"],["B","高血压"],["C","二者都有"],["D","二者都无"]],"A","隐匿型肾小球肾炎又称无症状性血尿和（或）蛋白尿，无水肿、高血压（B错）及肾功能损害，而仅表现为血尿（A对）和（或）蛋白尿。","","N"],["2001-N131",37,"第一节 急性胰腺炎","诊断AP的重要血清学标志物",2001,131,"C","","水肿型急性胰腺炎可有",[["A","血清淀粉酶升高"],["B","血清淀粉酶正常或低于正常"],["C","二者都有"],["D","二者都无"]],"A","血清淀粉酶由胰腺的腺泡分泌。水肿型胰腺炎，胰腺的腺泡细胞充血、肿胀，细胞膜通透性升高，淀粉酶大量释放入血，导致血清淀粉酶升高（A对）。出血坏死性胰腺炎若胰腺广泛坏死，腺泡细胞数量减少，血清淀粉酶可正常、甚至低于正常，因此出血坏死性胰腺炎的淀粉酶可升高、正常或降低。所以，血清淀粉酶的高低与病情程度无确切关联，其高低不一定反映病情轻重。","","N"],["2001-N132",37,"第一节 急性胰腺炎","诊断AP的重要血清学标志物",2001,132,"C","","出血坏死型急性胰腺炎可有",[["A","血清淀粉酶升高"],["B","血清淀粉酶正常或低于正常"],["C","二者都有"],["D","二者都无"]],"C","血清淀粉酶由胰腺的腺泡分泌。出血坏死性胰腺炎若胰腺病变较轻，胰腺细胞仅充血，肿胀，细胞通透性升高，则血清淀粉酶轻度升高（A对）。若胰腺广泛坏死，腺泡细胞数量减少，血清淀粉酶可正常、甚至低于正常（B对）。所以，血清淀粉酶的高低与病情程度无确切关联，其高低不一定反映病情轻重。本题AB均对，正确答案为C。","","N"],["2001-N133",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺军团病治疗",2001,133,"C","","氨基糖苷类抗生素对",[["A","绿脓杆菌肺炎有效"],["B","军团菌肺炎有效"],["C","二者都有效"],["D","二者都无效"]],"A","氨基糖苷类药物的抗菌机制主要是抑制细菌蛋白质合成，还能破坏细菌胞质膜的完整性，对各种需氧革兰阴性菌有效，绿脓杆菌（A对）属于需氧革兰阴性菌，故对其有效。军团菌虽然也属于革兰阴性杆菌，但对其效果不好，其治疗首选大环内酯类抗生素，如红霉素等（B错）。","","N"],["2001-N134",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺军团病治疗",2001,134,"C","","头孢菌素类抗生素对",[["A","绿脓杆菌肺炎有效"],["B","军团菌肺炎有效"],["C","二者都有效"],["D","二者都无效"]],"A","头孢菌素类抗生素具有抗菌谱广、杀菌力强等特点，对G⁺和G⁻菌均有较强的杀菌作用，铜绿假单胞菌（又称绿脓杆菌）（A对）属于G⁻菌，故对其有效。氨基糖苷类及头孢菌素均对军团菌（B错）无效，其治疗首选大环内酯类，如红霉素等。","","N"],["2001-N151",11,"第一节 胸腔积液","胸膜通透性增加",2001,151,"X","","下列哪些疾病的胸腔积液是由于胸膜毛细血管壁通透性增加所致",[["A","结核性胸膜炎"],["B","缩窄性心包炎"],["C","胸膜肿瘤"],["D","肺梗塞"]],"ACD","胸腔积液是指胸膜腔内的液体产生增多或吸收减少，胸腔内的液体超出正常范围的一种病理改变。由胸膜毛细血管壁通透性增加引起的胸腔积液常见的病因有：胸膜炎症（肺结核、肺炎）（A对）、风湿性疾病[系统性红斑狼疮（SLE）、类风湿关节炎（RA）]、胸膜肿瘤（恶性肿瘤转移、间皮瘤）（C对）、肺梗塞（D对）、膈下炎症（膈下脓肿、肝脓肿、急性胰腺炎）等；缩窄性心包炎（B错）时，由于胸膜毛细血管内静水压增高，导致有效滤过压增大，组织液生成过多，引起漏出性胸腔积液。","","N"],["2001-N152",15,"第二节 慢性心力衰竭","慢性心力衰竭诊断",2001,152,"X","","下列哪些检查指标显示患者左心功能不全",[["A","LVEF=35%"],["B","PCWP=19mmHg"],["C","CI=2.46L/（min•m²）"],["D","CO=4.6L/min"]],"ABCD","左心室射血分数（LVEF）正常值＞50%，收缩期心衰的诊断标准为LVEF＜40%（A对）。肺毛细血管楔压，九版内科学称为肺小动脉楔压（PCWP）正常值6～12mmHg（0.8～1.6kPa），左心衰时PCWP增高（B对）。心脏指数（心排指数、CI）正常值＞2.5L/（min·m²），左心衰时降低（C对）。心排出量（CO）正常值＞5L／min，左心衰时降低（D对）。根据八版内科学观点，本题答案应为ABCD，但参考答案为AB。","","N"],["2001-N153",37,"第一节 急性胰腺炎","药物",2001,153,"X","","下列哪些药物被认为可能诱发急性胰腺炎",[["A","硫唑嘌呤"],["B","四环素"],["C","磺胺"],["D","肾上腺糖皮质激素"]],"ABCD","由药物引起的胰腺炎称为药物性胰腺炎，药物性胰腺炎患者缺少胰腺炎的特征性表现，多在服药2个月内发生，与剂量无关，易被误诊或漏诊，并因此导致不良后果，故应对此有所认识和警惕。常见的可引发胰腺炎的药物有硫唑嘌呤（A对）、四环素（B对）、磺胺（C对）、噻嗪类利尿剂及肾上腺糖皮质激素（D对）等。","","N"],["2001-N154",53,"第二节 非霍奇金淋巴瘤","弥漫大B细胞淋巴瘤",2001,154,"X","","下列NHL的病理类型中，哪些属于中度恶性",[["A","小无裂细胞性"],["B","弥漫性小裂细胞性"],["C","原始免疫细胞性"],["D","弥漫性大细胞性"]],"BD","根据非霍奇金淋巴瘤（NHL）的国际工作分型，属于低度恶性的NHL有小淋巴细胞型、滤泡性小裂细胞型和滤泡性小裂细胞与大细胞混合型。属于中度恶性的有滤泡性大细胞型、弥漫性小裂细胞型（B对）、弥漫性小细胞与大细胞混合型和弥漫性大细胞型（D对）。属于高度恶性的有免疫母细胞型（C错）、淋巴母细胞型和小无裂细胞型（A错）。","","N"],["2001-N155",45,"第一节 慢性肾衰竭","骨骼病变",2001,155,"X","","下列哪些属于肾性骨营养不良症",[["A","纤维性骨炎"],["B","尿毒症骨软化症"],["C","骨质疏松症"],["D","骨硬化症"]],"ABCD","肾性骨营养不良症由慢性肾功能衰竭导致的骨代谢病，简称肾性骨病，包括纤维囊性骨炎（高转化骨病）（A对）、骨生成不良、骨软化症（低转化性骨病）（B对）及骨质疏松症（C对）。六版内科学P546、五版内科学P573均明确指出肾性骨营养不良症包括骨硬化症（D），七、八、九、十版内科学均未明确说明肾性骨营养不良是否包括骨硬化症，所以D选项存在争议，参考答案为ABCD。","","N"],["2001-N156",61,"第一节 糖尿病","微血管病变",2001,156,"X","","糖尿病微血管病变的发生、发展可能与下列哪些因素有关",[["A","山梨醇旁路代谢增强"],["B","生长激素过多"],["C","血小板功能异常"],["D","糖化血红蛋白含量增高"]],"ABCD","糖尿病微血管病变典型改变是微循环障碍和微血管基底膜增厚（十版内科学P729）。其发病机理为：①多元醇代谢异常：山梨醇旁路代谢增强（A对）；②生长激素：生长激素的增多可引起基底膜增厚（B对），促进微血管病变的发生；③血小板功能异常（C对）：血小板处于高黏附状态，使血流缓慢及淤滞，导致管腔狭窄和微循环障碍，促进了微血管病变的发生；④糖化血红蛋白含量过高（D对）：可引起肾小球基底膜增厚，诱发糖尿病肾病；⑤血液流变学改变；⑥凝血机制异常。","","N"],["2002-N47",15,"第二节 慢性心力衰竭","利尿剂",2002,47,"A","","利尿剂治疗心功能不全的作用是通过",[["A","排钠排水"],["B","提高心肌收缩力"],["C","增加心排血量"],["D","减轻水肿"],["E","降低动脉压"]],"A","利尿剂治疗心功能不全的机制是排钠排水，降低心脏容量负荷，减少血容量，使心输出量降低（A对C错），减轻水肿是排钠排水的结果（D错）。利尿剂无明显提高心肌收缩力的作用（B错），提高心肌收缩能力、增加心排血量为强心苷类药物（洋地黄）的作用。利尿剂通过排水排钠，减少细胞外容量，降低外周血管阻力，从而降低动脉压（E错）来治疗高血压，与本题关系不大。","","N"],["2002-N48",22,"第二节 心包积液及心脏压塞","心脏压塞",2002,48,"A","","急性心包炎所致心脏压塞的临床表现，下列哪项不正确",[["A","奇脉"],["B","心率加快"],["C","心排血量降低"],["D","静脉压显著增高"],["E","外周动脉舒张压上升"]],"E","大量心包积液可引起急性心脏压塞，可表现为窦性心动过速（B对）、奇脉（A对）、血压下降、脉压变小、静脉压明显升高（D对）。如果心排血量显著下降，可造成急性循环衰竭和休克（C对）。心包积液导致心脏压塞时心室舒张受限，心搏出量下降，收缩压降低，血流速度减慢，因而舒张末期残留于大动脉的血液降低较少，舒张压可降低或不变（E错，为本题正确答案）。","","N"],["2002-N49",18,"第一节 原发性高血压","高血压病人心血管危险分层标准",2002,49,"A","","下列哪项符合原发性高血压高度危险组标准",[["A","高血压2级伴1个危险因素"],["B","高血压2级伴2个危险因素"],["C","高血压2级伴靶器官损害"],["D","高血压1～2级伴3个其他危险因素"],["E","高血压3级"]],"D","根据血压水平结合危险因素及并发的器官受损情况可对高血压危险度进行分级，一般分为低度、中度、高度、很高度危险组，高血压1～2级伴3个危险因素（D对）以及高血压1~2级伴靶器官损害（C对）均为原发性高血压高度危险组范畴。高血压2级伴1～2个危险因素（AB错）应为高血压中度危险组，高血压3级（E对）无其他危险因素、无靶器官损害等符合原发性高血压高度危险组标准。根据十版内科学观点，本题答案应为CDE，但参考答案为D。","","N"],["2002-N50",16,"第六节 心脏传导阻滞","二度房室传导阻滞",2002,50,"A","","下列哪项符合二度Ⅰ型房室传导阻滞的心电图表现",[["A","P-P间期及R-R间期均不等"],["B","相邻的P-P间期进行性缩短"],["C","包含受阻P波在内的R-R间期小于正常P-P间期的两倍"],["D","最常见的传导比例为4：2"],["E","受阻P波前的一个P-R间期延长"]],"C","二度Ⅰ型房室传导阻滞心电图特点为PR间期进行性延长（B错）、相邻RR间期进行性缩短直至一个P波不能下传心室，包含受阻P波在内的RR小于正常窦性PP间期的两倍（C对）。最常见的房室传导比例为3：2和5：4（D错）。由于二度Ⅰ型房室传导阻滞患者的窦房结发放冲动正常，因此P-P间期为窦性的均等（A错）表现。根据二度Ⅰ型房室传导阻滞的PR间期进行性延长直至一个P波受阻不能下传心室的基本心电图特点，可知受阻P波前的一个P-R间期应该是延长的（E对），本题答案应为CE，但参考答案为C。","","N"],["2002-N51",17,"第四节 急性冠状综合征","血清心肌坏死标志物",2002,51,"A","","下列哪项不是反映心肌梗死的指标",[["A","血清肌凝蛋白轻链降低"],["B","血清肌凝蛋白重链增高"],["C","肌钙蛋白I增高"],["D","肌红蛋白增高"],["E","肌酸激酶增高"]],"A","心肌凝蛋白轻链（CMLC）主要存在于骨骼肌和心肌的肌浆中，是肌原纤维收缩蛋白的结构成分。当心肌受损时，肌凝蛋白解离，心肌凝蛋白轻链分子量小容易向细胞外逸脱，并在血中稳定，故在心梗时，血清肌凝蛋白轻链升高（A错，为本题正确答案）。急性心肌梗死的指标：1.血清肌凝蛋白重链升高（B对）：肌凝蛋白重链（MHC）是肌节重丝的主要成分，骨骼肌、心肌的MHC（肌凝蛋白重链）成分决定它的收缩速度，与肌原纤维肌凝蛋白的ATP酶在不同pH水平的活性有关。当心肌受损时，肌凝蛋白重链（MHC）进入血中，故MHC升高；2.血清肌钙蛋白升高：肌钙蛋白I（cTnI）或T（cTnT）起病3～4小时后升高（C对），cTnI于11～24小时达髙峰，7～10天降至正常，cTnT于24～48小时达高峰，10～14天降至正常；3．血清肌红蛋白增高（D对）：起病后2小时内升高，12小时内达高峰；24～48小时内恢复正常；4．血清肌酸激酶同工酶CK-MB升高（E对）：在起病后4小时内增高，16～24小时达高峰，3～4天恢复正常，其增高的程度能较准确地反映梗死的范围。之前的真题认为CK并不等同于CK-MB，本题E选项存在争议。","","N"],["2002-N52",17,"第三节 慢性冠状动脉综合症","ECG负荷试验",2002,52,"A","","属于心电图负荷试验禁忌证的是",[["A","心电图ST段水平下降＞0.15mV"],["B","稳定型心绞痛行PTCA术后三天"],["C","无并发症的急性心肌梗死后一周"],["D","频发室性期前收缩"],["E","心房颤动患者"]],"A","心电图负荷试验的禁忌证包括：AMI；高危的UA；急性心肌、心包炎；严重高血压（收缩压≥200mmHg和（或）舒张压≥110mmHg）；心功能不全；严重主动脉瓣狭窄；肥厚梗阻性心肌病；静息状态下有严重心律失常；主动脉夹层（二版八年制内科学P286）。静息状态下ECG即有明显ST段改变的患者如完全性左束支或右束支传导阻滞，或心肌肥厚继发ST段压低等也不适合行心电图负荷试验。患者ST下移＞0.15mV（A对），说明心肌已明显缺血，是负荷试验的禁忌证。稳定型心绞痛行PTCA（经皮冠状动脉腔内血管成形术）术后三天（B错）及无并发症的急性心肌梗死后一周（C错），患者病情均稳定，可进行心电图负荷试验。频发室早（D错）及房颤（E错）不是负荷试验的绝对禁忌证。","","N"],["2002-N53",21,"第三节 二尖瓣狭窄","二尖瓣狭窄临床表现",2002,53,"A","","二尖瓣口面积为2.0cm²时，下列提法哪项正确",[["A","为二尖瓣中度狭窄"],["B","可无临床症状"],["C","可无心尖部舒张期隆隆样杂音"],["D","可无跨瓣压差存在"],["E","一般不引起左心房扩大"]],"B","本题瓣口面积2.0cm²，属轻度狭窄（A错），心脏处于代偿期，可无临床症状（B对），一般二尖瓣中度狭窄（瓣口面积＜1.5cm²）时方有临床症状。无论二尖瓣是否狭窄，心室舒张期，左心房、左心室之间均出现压力阶差，即跨瓣压差，为驱动血液由左心房流入左心室的直接动力。早期充盈后，左心房、左心室内压力趋于相等。二尖瓣狭窄时，左心室充盈受阻，压差持续整个心室舒张期，因而通过测量跨瓣压差可判断二尖瓣狭窄程度，即使是二尖瓣轻度狭窄，跨瓣压差也存在（D错）。二尖瓣狭窄后期左心房代偿性肥大扩张（E错），可发展为左心房衰竭。只要存在二尖瓣狭窄，血液流动即可受阻，出现湍流，就会出现心尖部舒张期隆隆样杂音（C错）。","","N"],["2002-N54",13,"第一节 呼吸衰竭概述","Ⅱ呼吸衰竭",2002,54,"A","","Ⅱ型呼吸衰竭最常见于下列哪一种疾病",[["A","大叶性肺炎"],["B","特发性肺间质纤维化"],["C","慢性阻塞性肺疾病"],["D","ARDS"],["E","浸润型肺结核"]],"C","大叶性肺炎（A错）主要表现为肺组织内炎性渗出、炎性细胞浸润、以及肺实质病变；特发性肺间质性纤维化（十版内科学P102）（B错）是一种慢性、进行性、纤维化性间质性肺炎，主要病变在肺间质；ARDS（十版内科学P143）（D错）是炎症导致的肺微血管通透性增加，肺泡腔渗出富含蛋白质的液体，进而导致肺水肿及透明膜形成，最终导致肺容积减少、肺顺应性降低和严重通气/血流比例失调；浸润性肺结核（十版内科学P77）（E错）表现为肺组织渗出、增生、干酪样坏死等病变，最终病变吸收或者肺组织纤维化。肺泡内渗出物、肺间质水肿或纤维化均可使呼吸膜增厚，影响气体弥散功能，导致低氧血症，由于CO₂弥散功能是O₂的20倍，较少有CO₂潴留，故大叶性肺炎、特发性肺间质性纤维化、ARDS、浸润性肺结核主要引起低氧血症，导致Ⅰ型呼吸衰竭，其中以ARDS引起Ⅰ型呼吸衰竭最常见。一些慢性疾病可使呼吸功能的损害逐渐加重，经过较长时间发展为Ⅱ型呼吸衰竭，其中以慢性阻塞性肺疾病（C对）最常见，慢阻肺以通气功能障碍为主，引起PaO₂降低及CO₂潴留，导致Ⅱ型呼吸衰竭。","","N"],["2002-N55",11,"第一节 胸腔积液","漏出性胸腔积液",2002,55,"A","","下列疾病中，不会引起漏出性胸水的是",[["A","心力衰竭"],["B","低蛋白血症"],["C","肝硬化"],["D","肾病综合征"],["E","系统性红斑狼疮"]],"E","胸腔积液是指胸腔内液体产生增多或吸收减少，超出正常范围的一种病理改变，可以分为渗出液和漏出液。漏出液产生的原因为：①胸膜毛细血管内静压升高，如充血性心力衰竭（A错）、缩窄性心包炎、血容量增加、上腔静脉或奇静脉受阻等；②胸膜毛细血管内胶体渗透压降低，如低蛋白血症（B错）、肝硬化（C错）、肾病综合征（D错）、急性肾小球肾炎、黏液性水肿等。渗出液一般常见于胸膜毛细血管通透性增加，如胸膜炎症（肺结核、肺炎）、风湿性疾病[系统性红斑狼疮（SLE）（E对）、类风湿关节炎（RA）]、胸膜肿瘤（恶性肿瘤转移、间皮瘤）、肺梗塞、膈下炎症（膈下脓肿、肝脓肿、急性胰腺炎）等；也可见于壁层胸膜淋巴引流障碍，如癌性淋巴管阻塞、发育性淋巴管引流异常等。","","N"],["2002-N56",10,"第三节 慢性肺源性心脏病","控制感染",2002,56,"A","","COPD并发肺心病急性加重时，采取的治疗措施中最重要的是",[["A","应用利尿剂"],["B","应用呼吸兴奋剂"],["C","控制肺部感染"],["D","应用血管扩张剂"],["E","应用强心剂"]],"C","COPD并肺心病急性加重期，常常是由于呼吸系统感染引起。所以应采取的治疗措施中最重要的是控制肺部感染（C对）。COPD并肺心病急性加重期患者一般在积极控制感染、改善呼吸功能、纠正缺氧和二氧化碳潴留后，心力衰竭便能得到改善，患者尿量增多，水肿消退，不需要使用利尿药（A错）和正性肌力药（E错）、血管扩张药（D错）。但对经上述治疗无效或者严重心力衰竭患者，可适当使用上述药物。呼吸兴奋剂（B错）主要适用于中枢抑制为主、通气不足引起的呼吸衰竭，使用时必须保持呼吸道通畅，否则会促发呼吸肌疲劳，COPD患者表现为阻塞性通气功能障碍，急性加重期常伴肺部感染，气道分泌物增加，加重气道阻塞，不宜使用呼吸兴奋剂。","","N"],["2002-N57",10,"第三节 慢性肺源性心脏病","利尿药",2002,57,"A","","慢性肺源性心脏病急性加重时，使用利尿剂可能引起",[["A","低钾低氯性碱中毒"],["B","代谢性酸中毒"],["C","呼吸性酸中毒合并代谢性酸中毒"],["D","呼吸性碱中毒合并代谢性酸中毒"],["E","稀释性低钠血症"]],"A","慢性肺心病急性加重期患者使用了利尿剂之后，钾离子排出增多，机体出现低钾、低氯。低钾时，H⁺-K⁺交换作用增强，K⁺进入细胞外，H⁺进入细胞内，产生碱中毒，同时由于利尿作用，H⁺排出增加，使碳酸氢根的重吸收增加，体内碳酸氢根水平增高，因血中主要阴离子碳酸氢根和氯离子之和相对恒定，故氯离子相应减少，所以使用利尿剂之后易发生低钾、低氯性碱中毒（A对）。慢性肺心病患者存在呼吸功能障碍，可出现CO₂潴留，产生呼吸性酸中毒，而不是呼吸性碱中毒（D错）。因CO₂潴留发展缓慢，肾脏可通过减少HCO₃⁻的排除来维持pH的恒定，但当体内CO₂长期升高时，HCO₃⁻也维持在较高的水平，导致呼吸性酸中毒合并代谢性碱中毒，而不是代谢性酸中毒（B错）。若是发生急性呼衰，则肾脏不能及时缓冲，于是体内酸性物质会增多，发生呼吸性酸中毒合并代谢性酸中毒（C错），而慢性肺源性心脏病急性加重时使用利尿剂不出现稀释性低钠血症（E错）。","","N"],["2002-N58",5,"第一节 肺脓肿","原发性肺脓肿",2002,58,"A","","吸入性肺脓肿的病原菌绝大多数是",[["A","金黄色葡萄球菌"],["B","厌氧菌"],["C","克雷伯杆菌"],["D","大肠杆菌"],["E","肺炎链球菌"]],"B","肺脓肿的病原体常为上呼吸道、口腔的定植菌，包括需氧、厌氧和兼性厌氧菌，90%的肺脓肿患者合并有厌氧菌感染。常见的其他病原体包括金黄色葡萄球菌、化脓性链球菌、肺炎克雷伯杆菌和铜绿假单胞菌等。大肠杆菌（D错）和流感嗜血杆菌也可引起坏死性肺炎。根据感染途径，肺脓肿可以分为吸入性肺脓肿、继发性肺脓肿、血源性肺脓肿。吸入性肺脓肿的病原菌绝大多数是厌氧菌（B对）。金黄色葡萄球菌一般多发于血源性肺脓肿和继发性肺脓肿（A错），肺炎克雷伯杆菌一般多发于继发性肺脓肿（C错）。肺炎链球菌则为除厌氧菌之外，需氧与兼性厌氧菌中最常见的致病菌之一（E错）。","","N"],["2002-N59",2,"第一节 支气管哮喘","动脉血气分析",2002,59,"A","","对支气管哮喘急性发作病人进行血气分析，其中PaCO₂增高提示",[["A","病情好转"],["B","出现呼吸性碱中毒"],["C","病情恶化"],["D","出现心力衰竭"],["E","无临床意义"]],"C","支气管哮喘是以气流受限为主要特征的阻塞性通气功能障碍。轻度病变时，由于气体通过气道的阻力增加，进入肺泡氧气减少，动脉血氧分压降低，刺激颈动脉化学感受器，反射性地促使呼吸加深加快，过度通气导致PaCO₂降低，出现呼吸性碱中毒。随着病情恶化（C对AE错），气管、支气管过度收缩，气道阻力进一步增加，呼气困难加重，血氧分压进一步降低、CO₂潴留，故PaCO₂增高可提示病情恶化。PaCO₂增高属于呼吸性酸中毒（B错）。PaCO₂增高不能提示患者出现心力衰竭（D错）。","","N"],["2002-N60",29,"第二节 结核性腹膜炎","抗结核化学药物治疗",2002,60,"A","","结核性腹膜炎治疗过程中应用乙胺丁醇，最易出现的不良反应是",[["A","皮疹"],["B","药物热"],["C","胃肠道刺激"],["D","肾功能损害"],["E","球后视神经炎"]],"E","各种抗结核药物的不良反应主要有：1、异烟肼：周围神经炎、肝损害等；2、利福平：消化道反应（C错）、肝损害及过敏反应（AB错）等；3、吡嗪酰胺：高尿酸血症、肝损害、食欲不振、关节痛和恶心；4、乙酰丁胺：视神经炎（E对）；5、链霉素：耳毒性、前庭功能损害和肾毒性（D错）等；6、对氨基水杨酸钠：胃肠不适、过敏反应及肝损害（十版内科学P80）。乙胺丁醇不良反应为视神经炎，应在治疗前测定视力与视野，治疗中密切观察，提醒患者发现视力异常应及时就医，鉴于儿童无症状判断能力，故不用。","","N"],["2002-N61",28,"第一节 消化性溃疡","H2RA",2002,61,"A","","下列H₂RA药物中，抑酸作用最强且持久而副作用少的是",[["A","西咪替丁"],["B","雷尼替丁"],["C","法莫替丁"],["D","尼扎替丁"],["E","罗沙替丁"]],"C","此五种药物均属于H₂受体阻断剂（H₂RA），其中常用的是西咪替丁、雷尼替丁、法莫替丁。作用基本相同，但各自对H₂受体拮抗作用的强弱不同，其抑制胃酸分泌的作用和持续时间：法莫替丁＞雷尼替丁=尼扎替丁＞西咪替丁（C对ABD错）。罗沙替丁九版内科学及九版药理学中未提及。","","N"],["2002-N62",35,"第一节 肝硬化","氨中毒",2002,62,"A","","关于肝性脑病的氨中毒学说，下列正确的是",[["A","NH₄⁺有毒性，能透过血脑屏障"],["B","肠内pH＞6时，NH₃不易被吸收"],["C","低钾碱中毒时增加氨毒性"],["D","腹泻时增加氨毒性"],["E","高血糖时增加氨毒性"]],"C","氨中毒是肝性脑病发病机制的主要假说之一。肠道是氨产生的主要部位，肠道内的氨以非离子型氨（NH₃）和离子型氨（NH₄⁺）两种形式存在，两者互相转化受pH梯度影响。当结肠内pH＞6时，NH₄⁺转化为NH₃，NH₃易被肠黏膜吸收（B错），NH₃能透过血脑屏障，产生对脑的毒性（A错）；pH＜6时，则NH₃从血液转至肠腔，随粪便排泄。低钾碱中毒时，NH₃不能形成NH₄⁺排出，大量弥散入血，增加氨毒性（C对）。高血糖时，葡萄糖供能增加，谷氨酰胺供能减少，后者供能时产生的氨也减少，故氨毒性下降（E错）。腹泻可减少氨的吸收，减轻氨毒性，但严重腹泻时可造成机体脱水，血容量减少，肾前性氮质血症，不利于氨的排泄，且腹泻容易导致低钾碱中毒，增加氨毒性（六版内科学P459）（D对）。本题答案应为CD，但参考答案为C。","","N"],["2002-N63",29,"第二节 结核性腹膜炎","全身症状",2002,63,"A","","结核性腹膜炎病人的发热特点错误的是",[["A","一半有弛张热"],["B","少数可呈稽留热"],["C","高热伴明显毒血症者见于渗出型"],["D","高热伴明显毒血症者见于干酪型"],["E","高热伴明显毒血症者见于伴有粟粒型结核者"]],"A","结核性腹膜炎是由结核分枝杆菌引起的慢性弥漫性腹膜感染，根据本病的病理特点分为渗出性、粘连型和干酪型，全身症状以结核毒血症常见，主要是发热与盗汗（十版内科学P385）。发热主要特点是低热与中等热，约1/3患者呈弛张热（A错，为本题正确答案），少数病人呈稽留热（B对）。高热伴有明显毒血症主要见于渗出型（C对）、干酪型（D对），或见于伴有粟粒型肺结核（E对）、干酪样肺炎等严重结核病的患者。","","N"],["2002-N64",32,"第二节 肠易激综合征","腹痛和腹部不适",2002,64,"A","","对于肠易激综合征病人，下列有关腹痛的描述，错误的是",[["A","部位不定"],["B","以下腹和右下腹多见"],["C","极少睡眠中痛醒"],["D","多于排便或排气后缓解"],["E","无明显体征"]],"B","肠易激综合征是一种功能性胃肠病，患者无实质性胃肠道病变，主要表现为腹痛或腹部不适伴排便习惯改变，疼痛部位不定（A对），以下腹和左下腹多见（B错，为本题正确答案），排便或排气后缓解（D对），极少有睡眠中痛醒者（C对）。因为本病是一种功能性胃肠病，无实质性胃肠道病变，所以一般无明显体征（E对）。","","N"],["2002-N65",26,"第一节 胃食管反流病","典型症状",2002,65,"A","","下列有关胃食管反流病烧心的描述，错误的是",[["A","烧心是指胸骨后或剑突下烧灼感"],["B","常在餐后半小时出现"],["C","腹压增高时可加重"],["D","弯腰时可加重"],["E","卧位可加重"]],"B","胃食管反流病（GERD）是指胃十二指肠内容物反流入食管引起烧心、反流等症状。烧心是指胸骨后或剑突下烧灼感（A对），常在餐后1小时出现（B错，为本题正确答案），腹压增高（C对）（可使胃所受外部压力增加）、卧位（E对）或弯腰（D对）（消除了重力因素），均可使胃反流增加，烧心症状加重。","","N"],["2002-N66",45,"第一节 慢性肾衰竭","尿毒症症状的发生机制",2002,66,"A","","下列引起尿毒症某些症状的毒素中，不属于小分子毒素的是",[["A","尿素"],["B","尿酸"],["C","溶菌酶"],["D","胍类"],["E","胺类"]],"C","根据尿毒症毒素分子量的大小可将尿毒症毒素分为小分子物质（分子量＜500道尔顿）：如尿素（量最多）（A对）、尿酸（B对）、胍类（D对）、各种胺类（E对）、酚类等；中分子物质（分子量500～5000道尔顿）：如甲状旁腺激素类；大分子物质（分子量＞5000道尔顿）：如核糖核酸酶、β₂微球蛋白、维生素A、溶菌酶（C错，为本题正确答案）等。","","N"],["2002-N67",40,"第二节 急性肾小球肾炎","急性肾小球肾炎鉴别诊断",2002,67,"A","","链球菌感染后急性肾小球肾炎与IgA肾病的根本不同是",[["A","链球菌感染史"],["B","病程长短"],["C","起病缓急"],["D","尿检异常"],["E","肾脏组织病变"]],"E","链球菌感染后急性肾小球肾炎与IgA肾病的根本不同是肾脏组织病变（E对），前者病理类型为毛细血管内增生性肾小球肾炎，后者病理类型主要为系膜增生性肾小球肾炎，通过肾组织活检可以得到确切的诊断。两种病变均可出现链球菌感染史（A错）、尿检异常（D错），病程长短（B错）、起病缓急（C错）也非根本区别。从解题技巧角度考虑，考察两种疾病的根本性不同往往是病理变化的不同。","","N"],["2002-N68",53,"第二节 非霍奇金淋巴瘤","蕈样肉芽肿病_塞扎里综合征",2002,68,"A","","淋巴瘤病人增生的细胞可以完全表达为成熟的辅助性T细胞的是",[["A","皮肤T细胞性"],["B","周围性T细胞性"],["C","血管免疫母细胞性T细胞性"],["D","小肠T细胞性"],["E","成人T细胞性"]],"A","皮肤T细胞淋巴瘤即蕈样肉芽肿，增生的细胞完全表达为成熟的辅助性T细胞（A对），呈CD3⁺、CD4⁺、CD8⁻。周围性T细胞性淋巴瘤（B错）已向辅助性T细胞或抑制性T细胞分化，但未分化完全；小肠T细胞性淋巴瘤（D错）和成人T细胞性淋巴瘤（E错）都是周围性T细胞性淋巴瘤的特殊类型；血管免疫母细胞性T细胞性淋巴瘤（C错）是一种侵袭性淋巴瘤。以上四种淋巴瘤增生的细胞都不能完全表达为成熟的辅助性T细胞，而表达为成熟的抑制性T细胞，呈CD3⁺、CD4⁻、CD8⁺。","","N"],["2002-N69",53,"第二节 非霍奇金淋巴瘤","非霍奇金淋巴瘤临床表现",2002,69,"A","","NHL累及胃肠道的最常见部位是",[["A","食管"],["B","胃"],["C","十二指肠"],["D","回肠"],["E","结肠"]],"D","NHL（非霍奇金淋巴瘤）是一组具有不同的组织学特点和起病部位的淋巴瘤，易发生早期远处扩散（十版内科学P593）。对于NHL患者，当累及到胃肠道时，多发于回肠部位（D对），可能与该部位有大量的淋巴滤泡聚集有关。其次为胃，其他部位较少受累（ABCE错）。","","N"],["2002-N70",51,"第一节 骨髓增生异常性肿瘤","难治性贫血伴原始细胞增多转变型",2002,70,"A","","骨髓增生异常综合征病人的骨髓幼稚细胞中有Auer小体，见于",[["A","RA型"],["B","RAS型"],["C","RAEB型"],["D","RAEB-T型"],["E","CMML型"]],"D","Auer小体（棒状小体）为白细胞胞质中出现的1条或数条染红色细杆状物质，见于急性髓细胞白血病（AML）、急性单核细胞白血病中，在骨髓增生异常综合征（MDS）的RAEB-t型（D对）也可检出Auer小体。另外，Auer小体有助于急性淋巴细胞白血病与急性非淋巴细胞白血病的鉴别诊断，急性淋巴细胞白血病患者无Auer小体，而在急性非淋巴细胞白血病中，Auer小体是一个具有诊断意义的形态学特征。","","N"],["2002-N71",60,"第五节 嗜铬细胞瘤","嗜铬细胞瘤治疗",2002,71,"A","","不宜单独用于治疗嗜铬细胞瘤的是",[["A","哌唑嗪"],["B","阿替洛尔"],["C","酚妥拉明"],["D","硝普钠"],["E","酚苄明"]],"B","嗜铬细胞瘤手术切除前需采用α受体拮抗药使血压下降，减轻心脏的负担，并使原来缩减的血管容量增大。哌唑嗪（A错）、酚妥拉明（C错）、酚卞明（E错）都为α受体阻滞剂，均可单独使用。硝普钠（D错）是外周小动、静脉的扩张剂，对血压骤增者可单独使用硝普钠静滴。术前β受体阻滞剂不必常规应用，如患者有心动过速或心律失常则需使用β受体阻滞剂。在用β受体阻滞剂之前，必须先用α受体阻滞剂使血压下降，如单独用β受体阻滞剂，则由于阻断β受体介导的舒血管效应而使血压升高，甚而发生肺水肿，故β受体阻滞剂如阿替洛尔不能单独使用（B对）。","","N"],["2002-N72",59,"第一节 甲状腺功能亢进症","血清总甲状腺激素",2002,72,"A","","下列能使TBG升高的是",[["A","雄激素"],["B","泼尼松"],["C","严重肝病"],["D","病毒性肝炎"],["E","肾病综合征"]],"D","TBG（甲状腺素结合球蛋白）由肝脏合成，是甲状腺激素在血液循环中的主要载体蛋白，对甲状腺激素的贮存、运输、代谢以及维持甲状腺激素的浓度和游离甲状腺激素的动态稳定，均具有重要的作用。病毒性肝炎时TBG合成和释放增多而出现血中TBG增高（D对）。雄激素（A错）、泼尼松（糖皮质激素）（B错）均使TBG分解加速导致TBG水平下降。严重肝病时，肝脏蛋白合成功能受损，TBG合成减少（C错）。肾病综合征患者出现大量蛋白尿，蛋白流失过多，TBG降低（E错）。","","N"],["2002-N73",68,"第一节 类风湿关节炎","关节畸形",2002,73,"A","","下列与类风湿关节炎活动无关的是",[["A","晨僵"],["B","关节畸形"],["C","类风湿结节"],["D","血沉增快"],["E","C反应蛋白增高"]],"B","晨僵（A错）出现在95%以上的类风湿关节炎患者，即患者晨起后在受累关节出现僵硬感，经活动或温暖后症状可减轻或消失，常被作为观察本病活动的指标之一。关节畸形（B对）为类风湿关节炎的晚期表现，属于后遗症，与急性期活动性无关。类风湿结节（C错）是类风湿关节炎的关节外表现，其存在提示有类风湿关节炎的活动。80%左右的类风湿关节炎患者，在活动期血沉增快。因此，血沉（D错）可作为类风湿关节炎活动的一项实验室指标。C反应蛋白（CRP）（E错）是指在机体受到感染或组织损伤时血浆中一些急剧上升的蛋白质（急性蛋白），类风湿关节炎活动时，C反应蛋白增高。","","N"],["2002-N74",69,"第一节 系统性红斑狼疮","抗dsDNA抗体",2002,74,"A","","对确诊SLE和判断其活动性参考价值最大的抗体是",[["A","抗核抗体"],["B","抗dsDNA抗体"],["C","抗Sm抗体"],["D","抗RNP抗体"],["E","抗Ro抗体"]],"B","系统性红斑狼疮（SLE）是一种多发于青年女性的累及多脏器的自身免疫性炎症性结缔组织病。ACR修订的SLE（系统性红斑狼疮）分类标准中，免疫学异常和自身抗体阳性包括：抗Sm抗体、抗dsDNA抗体、抗磷脂抗体和抗核抗体ANA。但对确诊SLE和判断其活动性参考价值最大的抗体是抗dsDNA抗体（B对）。抗核抗体（A错）见于几乎所有的SLE患者，为SLE的最佳筛选试验，但特异性低，其阳性不能作为SLE与其他结缔组织疾病的鉴别。抗Sm抗体（C错）特异性高，敏感性低，有助于早期和不典型患者的诊断和回顾性诊断，但与病情活动性无关。抗RNP抗体（抗核糖核蛋白抗体）（D错）可见于35%～45%的红斑狼疮病人和95%～100%的混合性结缔组织病病人，多作为辅助诊断，且与病情活动性无关。抗Ro（SSA）抗体（E错）在原发性干燥综合征患者体内阳性率可达到60%～80%（十版内科学P828），而在SLE中为24%～60%，诊断意义不大，且与病情活动性无关。","","N"],["2002-N103",12,"第一节 急性呼吸窘迫综合征","机械通气",2002,103,"B","","对成人呼吸窘迫综合征的治疗采用",[["A","高压氧疗"],["B","持续低流量给氧"],["C","无控制性给氧"],["D","鼻导管持续高浓度给氧"],["E","呼气末正压给氧"]],"E","成人呼吸窘迫综合征首选的措施是呼气末正压给氧（E对）。PEEP（呼气末正压通气）可使萎陷的小气道和肺泡开放，防止肺泡随呼吸周期反复开闭，使呼气末肺容量增加，并可以减轻肺损伤和肺泡水肿。呼气末正压给氧可以在此基础上缓解顽固性低氧血症；持续低流量给氧（十版内科学P30）（B错）主要用于慢性阻塞性肺疾病；无控制性给氧（C错）用于中、重度肺炎；高压给氧（A错）可用于气性坏疽、Buerger病（闭塞性血栓性脉管炎）、急性呼衰等；鼻导管持续高浓度给氧（D错）主要用于新生儿呼吸窘迫综合征（NRDS），早产儿呼吸暂停，预防拔管失败的支持治疗，是一种新型的无创呼吸支持模式。","","N"],["2002-N104",13,"第三节 慢性呼吸衰竭","氧疗",2002,104,"B","","对肺炎病人所致缺氧的治疗采用",[["A","高压氧疗"],["B","持续低流量给氧"],["C","无控制性给氧"],["D","鼻导管持续高浓度给氧"],["E","呼气末正压给氧"]],"C","成人肺炎所致缺氧是由于炎症累及终末气道、肺泡和肺间质等，使得肺组织的呼吸功能受损，产生缺氧，此时为了纠正缺氧症状，可给予无控制性给氧（C对）。呼气末正压给氧（E错）是成人呼吸窘迫综合征首选的措施；持续低流量给氧（十版内科学P30）（B错）可用于慢阻肺所致的呼衰；高压给氧（A错）可用于气性坏疽、Buerger病（闭塞性血栓性脉管炎）、急性呼衰等；鼻导管持续高流量给氧（D错）主要用于新生儿呼吸窘迫综合征（NRDS），早产儿呼吸暂停，预防拔管失败的支持治疗，是一种新型的无创呼吸支持模式。","","N"],["2002-N105",75,"第一节 中毒概述","血液净化",2002,105,"B","","血液灌流可清除",[["A","短效巴比妥类"],["B","苯巴比妥"],["C","水杨酸类"],["D","甲醇"],["E","锂"]],"A","血液灌流是指血液流过装有活性炭或树脂的灌流柱，毒物被吸附后，再将血液回输患者体内。此法能吸附脂溶性或与蛋白质结合的化学物，能清除血液中短效巴比妥类（A对）、长效巴比妥和百草枯等，是目前最常用的中毒抢救措施。巴比妥类依其催眠作用时间的长短分为：长效类，持续6～8小时，如巴比妥和苯巴比妥；中效类，4～6小时，如异戊巴比妥和戊巴比妥；短效类，2～3小时，如司可巴比妥。硫喷妥钠作用时间更短，可作静脉麻醉药，属超短效类。苯巴比妥属长效巴比妥，经血液灌流可清除（B对）。血液透析用于清除血液中分子量较小和非脂溶性的毒物，如苯巴比妥、水杨酸类（C错）、甲醇（D错）、茶碱、乙二醇和锂（E错）等。根据九版内科学观点，本题答案应为AB，但参考答案为A。","","N"],["2002-N106",75,"第一节 中毒概述","血液净化",2002,106,"B","","透析疗法不能很好清除",[["A","短效巴比妥类"],["B","苯巴比妥"],["C","水杨酸类"],["D","甲醇"],["E","锂"]],"A","血液透析用于清除血液中分子量较小和非脂溶性的毒物，如苯巴比妥（B错）、水杨酸类（C错）、甲醇（D错）、茶碱、乙二醇和锂（E错）等。短效巴比妥类（A对）因具有脂溶性，一般不进行血液透析，可进行血液灌流来清除。","","N"],["2002-N107",51,"第一节 骨髓增生异常性肿瘤","骨髓增生异常性肿瘤实验室检查",2002,107,"B","","符合MDS的是",[["A","血间接胆红素增高、贫血、网织红细胞增高"],["B","血间接胆红素增高、贫血、网织红细胞正常或减低"],["C","血间接胆红素增高、无贫血、网织红细胞正常"],["D","血间接胆红素正常、贫血、网织红细胞减低"],["E","血间接胆红素正常、贫血、网织红细胞正常"]],"B","MDS（骨髓增生异常综合征）是起源于造血干细胞的异质性疾病，异常克隆细胞在骨髓中分化、成熟障碍，出现病态造血，在骨髓原位或释放入血后不久被破坏，导致无效造血。发生原位溶血（属血管外溶血）时，异常红细胞在骨髓原位被单核-巨噬细胞系统吞噬消化，释放出的血红蛋白分解为珠蛋白和血红素，血红素被分解为铁和卟啉，卟啉进一步分解为游离胆红素后入血。当游离胆红素（间接胆红素）量增加，超过肝处理能力时，患者血中间接胆红素增高。虽然MDS患者骨髓增生活跃，但为病态造血，表现为持续性一系或多系血细胞减少，几乎所有的MDS患者都有红细胞减少（表现为贫血）；异常网织红细胞被破坏，网织红细胞计数常减少，少数患者网织红细胞分化正常，计数可正常（B对）。","","N"],["2002-N108",49,"第一节 再生障碍性贫血","AA血象",2002,108,"B","","符合再生障碍性贫血的是",[["A","血间接胆红素增高、贫血、网织红细胞增高"],["B","血间接胆红素增高、贫血、网织红细胞正常或减低"],["C","血间接胆红素增高、无贫血、网织红细胞正常"],["D","血间接胆红素正常、贫血、网织红细胞减低"],["E","血间接胆红素正常、贫血、网织红细胞正常"]],"D","再生障碍性贫血是不同病因导致的骨髓造血功能障碍或衰竭，表现为外周血三系减少、骨髓象增生减低，因此可见贫血、网织红细胞减低。血清间接胆红素升高与各种溶血疾病有关，再障患者骨髓增生减低，红细胞只是数量减少，而无质量异常，一般不伴溶血，因此间接胆红素正常（D对）。","","N"],["2002-N109",60,"第一节 库欣综合征","异位ACTH综合征",2002,109,"B","","血浆ACTH测定增高，见于",[["A","肾上腺皮质腺瘤"],["B","肾上腺皮质腺癌"],["C","Carney综合征"],["D","Meador综合征"],["E","异位ACTH综合征"]],"E","考察各种原因引起的Cushing综合征ACTH变化。异位ACTH综合征是指垂体以外的肿瘤（如肺小细胞癌、胸腺癌等）产生ACTH（E对），刺激肾上腺皮质增生，分泌过量的皮质醇。肾上腺皮质腺瘤（A错）、肾上腺皮质癌（B错）大量分泌皮质醇，可负反馈抑制垂体ACTH的分泌，故血液中ACTH浓度降低。Carney综合征（十版内科学P710）（C错）是一种罕见的遗传性疾病，通常包括黏液瘤、皮肤色素沉着、多发性内分泌腺瘤，其中内分泌肿瘤包括原发性色素结节性肾上腺增生（PPNAD）、生长激素瘤等，其ACTH值低于正常。Meador综合征（D错）又称原发性色素性结节性肾上腺病，为不依赖ACTH的双侧肾上腺小结节性增生，肾上腺皮质分泌大量皮质醇，可负反馈抑制垂体ACTH的分泌，故血液中ACTH浓度降低。Carney综合征（C错）指Meador综合征伴皮肤、乳房、心房黏液瘤、睾丸肿瘤、垂体生长激素瘤等，故血液中ACTH浓度也降低。","","N"],["2002-N110",60,"第一节 库欣综合征","库欣综合征病因诊断",2002,110,"B","","大剂量地塞米松抑制试验时少数可被抑制，见于",[["A","肾上腺皮质腺瘤"],["B","肾上腺皮质腺癌"],["C","Carney综合征"],["D","Meador综合征"],["E","异位ACTH综合征"]],"E","正常人糖皮质激素的分泌受下丘脑（CRH，促肾上腺激素释放激素）-垂体（ACTH，促肾上腺激素）-肾上腺皮质（GC，糖皮质激素）轴的调节，当给予外源性糖皮质激素时，垂体ACTH分泌受抑制，从而皮质醇分泌减少。异位ACTH综合征系垂体以外的组织分泌大量的ACTH或ACTH类似物，刺激肾上腺皮质增生，使之分泌过量皮质醇、盐皮质激素以及性激素引起一系列症状，引起异位ACTH综合征的肿瘤（最常见为肺癌，其次为胸腺瘤、胸腺类癌、胰岛肿瘤、支气管类癌等）一般都具有自主性，不受CRH兴奋，也不会被糖皮质激素抑制，即该综合征不涉及下丘脑-垂体-肾上腺皮质轴的调节，故不能被大剂量地塞米松抑制试验抑制；但需要注意的是，支气管类癌分泌ACTH比较特殊（即支气管类癌导致的异位ACTH综合征），多数可以被大剂量地塞米松抑制试验抑制，因此大剂量地塞米松抑制试验时少数可被抑制见于异位ACTH综合征（E对）。肾上腺皮质腺瘤（A错）、肾上腺皮质腺癌（B错）、Meador综合征（不依赖ACTH的双侧肾上腺小结节性增生）（D错）、Carney综合征（指Meador综合征伴皮肤、乳房、心房黏液瘤、睾丸肿瘤、垂体生长激素瘤等）（C错）为自主分泌皮质醇，引起的高皮质醇血症已在很大程度上抑制了垂体ACTH的分泌，不受下丘脑-垂体-肾上腺皮质轴的调节，因此不能被大剂量地塞米松抑制试验抑制。大剂量地塞米松抑制试验是鉴别库欣病与肾上腺腺瘤最经典的方法，通常血尿皮质醇不能被抑制者提示肾上腺腺瘤，反之为库欣病，此外低钾血症、低氯血症、代谢性碱中毒的存在，常提示异位ACTH的分泌。","","N"],["2002-N129",18,"","",2002,129,"C","","硝酸异山梨醇酯的作用是",[["A","扩张小静脉"],["B","扩张小动脉"],["C","二者均有"],["D","二者均无"]],"C","硝酸酯类在低剂量时就可扩张小静脉，降低回心血量，使LVEDP及肺血管压降低，常用药物包括硝酸甘油、双硝酸异山梨醇酯等。硝酸异山梨醇酯（即异舒吉）为双硝酸异山梨醇酯的代谢产物，1～3mg/h扩张小静脉，减轻心脏前负荷；3～7mg/h扩张动脉，改善冠状动脉血流；7～12mg/h扩张阻力血管（包括小动脉和微动脉等），降低心脏后负荷（C对）。","","N"],["2002-N130",17,"第四节 急性冠状综合征","钙通道阻滞剂",2002,130,"C","","硫氮䓬酮的作用是",[["A","扩张小静脉"],["B","扩张小动脉"],["C","二者均有"],["D","二者均无"]],"B","硫氮䓬酮（即地尔硫䓬）（十版内科学P267-P277）为非二氢吡啶类钙离子通道阻滞剂，主要通过阻滞电压依赖L型钙通道减少细胞外钙离子进入血管平滑肌细胞内，减少兴奋-收缩偶联，有效地扩张小动脉（B对）。","","N"],["2002-N131",26,"第一节 胃食管反流病","胃食管反流病病理",2002,131,"C","","Barrett食管是指",[["A","鳞状上皮被柱状上皮取代"],["B","发生消化道溃疡"],["C","两者均是"],["D","两者均非"]],"A","Barrett食管是指食管的鳞状上皮出现单层柱状上皮化生（A对），多发生于胃食管连接处的齿状线近端。","","N"],["2002-N132",26,"第一节 胃食管反流病","胃食管反流病病理",2002,132,"C","","Barrett溃疡是指",[["A","鳞状上皮被柱状上皮取代"],["B","发生消化道溃疡"],["C","两者均是"],["D","两者均非"]],"C","Barrett食管是指食管的鳞状上皮出现单层柱状上皮化生（A对），多发生于胃食管连接处的齿状线近端。Barrett溃疡是指在Barrett食管基础上发生的消化性溃疡（B对）。本题AB均对，正确答案为C。","","N"],["2002-N133",39,"","",2002,133,"C","","分泌性蛋白尿表现为",[["A","尿中IgA排泄增多"],["B","尿中核糖核酸酶排泄增多"],["C","二者均有"],["D","二者均无"]],"A","分泌性蛋白尿是由于尿液形成过程中，肾脏本身代谢产生的蛋白质渗入尿液中所致，如由髓袢升支分泌的Tamm-Horsfall蛋白、肾及尿路感染时的IgA（A对）、某些肾炎时尿中的纤维蛋白（原）及其降解产物、补体成分、肾小球基膜成分等可由尿中排出而致蛋白尿。尿中核糖核酸酶排泄增多（B错）为肾小管性蛋白尿的临床表现。","","N"],["2002-N134",39,"","",2002,134,"C","","肾小管性蛋白尿表现为",[["A","尿中IgA排泄增多"],["B","尿中核糖核酸酶排泄增多"],["C","二者均有"],["D","二者均无"]],"B","肾小管性蛋白尿是由于肾小管对滤出的小分子量蛋白的重吸收障碍所致。见于肾小管间质病变、肾盂肾炎、先天性肾小管病、低钾肾病等。此类蛋白尿的特点为尿蛋白总量通常较少，一般＜1g/d；且仅含少量白蛋白，并以低分子量的溶菌酶、核糖核酸酶（B对）、β₂微球蛋白、维生素A结合蛋白等为主。尿中IgA排泄增多（A错）为分泌性蛋白尿的临床表现。","","N"],["2002-N151",16,"第一节 心律失常概述","传导阻滞",2002,151,"X","","病理性冲动传导异常包括",[["A","房室分离"],["B","干扰脱节"],["C","左束支分支阻滞"],["D","窦房阻滞"]],"CD","病理性传导异常包括左、右束支及左束支分支阻滞（C对）或室内阻滞等束支或分支阻滞，窦房阻滞（D对），房内传导阻滞，房室传导阻滞（一度、二度和三度房室阻滞），阵发性心动过速（常见房室结折返、房室折返和心室内折返）等。冲动传导异常可分为生理性传导异常和病理性传导异常。生理性传导异常包括干扰脱节（B错）、干扰性房室分离（A）等。病理性房室分离包括三度房室传导阻滞和室性心动过速。A选项存在争议。","","N"],["2002-N152",2,"第一节 支气管哮喘","支气管哮喘病理",2002,152,"X","","支气管哮喘是以下列哪些细胞反应为主的气道炎性疾病",[["A","嗜酸性粒细胞"],["B","T淋巴细胞"],["C","B淋巴细胞"],["D","肥大细胞"]],"ABD","支气管哮喘是由多种刺激因素刺激炎症细胞而引起的高反应性气道慢性炎症。其中，细胞介导的炎症反应在支气管哮喘发病过程中起到了重要作用。进入机体的外源性变应原可激活T淋巴细胞，T细胞主要通过两种途径介导器官炎症反应。一方面，活化的T细胞可激活B淋巴细胞产生特异性IgE，后者结合肥大细胞的表面IgE受体。变应原再次进入体内后，可与结合在细胞表面的IgE交联，使该细胞释放多种导致气道收缩的炎症介质，发生哮喘。另一方面，活化的T细胞可直接激活肥大细胞、嗜酸粒细胞，使之聚集在气道，产生炎症介质，引发哮喘。由上可见，T淋巴细胞（B对）是介导支气管变态反应的始发环节，不可缺少，而B淋巴细胞（C对）可产生特异性抗体，介导炎症的发生，不可缺少。嗜酸粒细胞（A对）与肥大细胞（D对）是引发支气管变态反应的终末环节，不可缺少。故该题ABCD均正确，但原参考答案为ABD。有关气道慢性炎症的相关叙述，十版内科学有内容更新，参与气道慢性炎症的细胞新增了巨噬细胞（十版内科学P32）。","","N"],["2002-N153",26,"第一节 胃食管反流病","抗反流屏障结构与功能异常",2002,153,"X","","通过影响LES压力，能促进胃食管反流病发生的是",[["A","胆囊收缩素"],["B","胰升糖素"],["C","血管活性肠肽"],["D","地西泮"]],"ABCD","食管下端括约肌（LES）是食管末端约3～4cm长的环形肌束，其收缩产生的食管胃连接处的高压带，可防止胃内容物反流入食管。通过引起LES功能障碍或一过性LES松弛延长，而改变LES压促进胃食管反流病发生的因素有（十版内科学P363）：某些激素，如胆囊收缩素（A对）、胰高血糖素（B对）、血管活性肠肽（C对）等；某些药物，如地西泮（D对）、钙通道阻滞剂等。","","N"],["2002-N154",44,"第一节 急性肾损伤","进展期和维持期",2002,154,"X","","急性肾功能衰竭少尿期的表现是",[["A","高钾血症"],["B","高钠血症"],["C","高钙血症"],["D","高磷血症"]],"AD","急性肾衰竭少尿期，肾脏排泄钾减少，酸中毒（钾由细胞内向细胞外转移）、组织分解（细胞内钾释放）均可导致高钾血症（A对）；尿量减少导致磷排出减少，出现高磷血症（D对）；低钠血症（B错）是由于水钠潴留而发生的稀释性低钠；低钙血症（C错）多继发于高磷血症（磷酸钙盐为不溶物）。","","N"],["2002-N155",51,"第一节 骨髓增生异常性肿瘤","骨髓增生异常性肿瘤实验室检查",2002,155,"X","","MDS病人实验室检查可见的异常是",[["A","骨髓活检可见ALIP"],["B","骨髓网硬蛋白纤维增多"],["C","常见异常染色体-6"],["D","常见异常染色体5q⁻"]],"ABD","正常人原粒和早幼粒细胞沿骨小梁内膜分布，而MDS患者在骨小梁旁区和间区出现3～5个或更多的呈簇状分布的原粒和早幼粒细胞，称为不成熟前体细胞异常定位（ALIP）（A对）。临床上，约50%原发性骨髓增生异常综合征（MDS）患者骨髓切片内显示轻至中度网硬蛋白纤维增生（B对），10%～15%合并显著纤维化，不足10%的病例纤维组织内常伴胶原蛋白的沉积现象。40%～70%的MDS有克隆性染色体核型异常，多为缺失性改变，以+8、-5/5q⁻（D对）、-7/7q⁻、20q⁻最为常见，-6染色体异常少见（C错）。","","N"],["2002-N156",61,"第一节 糖尿病","糖尿病管理",2002,156,"X","","糖尿病治疗的目标是",[["A","使血糖达到或接近正常水平"],["B","消除糖尿病症状"],["C","防止或延缓并发症"],["D","彻底治愈"]],"ABC","糖尿病治疗的近期目标是控制高血糖，使血糖达到或接近正常水平（A对），消除糖尿病症状（B对）和防止出现急性严重代谢紊乱；远期目标是通过良好的代谢控制预防及（或）延缓糖尿病慢性并发症的发生和发展（C对），维持良好健康和学习、劳动能力，保障儿童生长发育，降低病死率和延长寿命。糖尿病属于慢性病变，病因和发病机制不甚明确，缺乏有效的针对病因的治疗措施，系终身性疾病，不能彻底治愈（D错），需终身服药或注射胰岛素。","","N"],["2003-N47",19,"第一节 肥厚型心肌病","肥厚型心肌病临床表现",2003,47,"A","","用硝酸甘油类药物使肥厚型梗阻性心肌病患者症状加重的原因是",[["A","扩张大动脉，降低了周围血压"],["B","扩张静脉，左室射血分数增加"],["C","扩张静脉，使回心血流量减少"],["D","冠状动脉收缩"],["E","心肌氧耗量增加"]],"C","硝酸甘油可扩张周围静脉，减少静脉回心血量（C对），舒张期心室充盈减少，心腔更趋狭窄，加重左心室流出道梗阻，使得患者心输出量进一步降低，症状加重。因此，在肥厚梗阻型心肌病患者，应避免使用降低心脏容量负荷的药物（硝酸酯类、利尿剂等）。","","N"],["2003-N48",18,"第一节 原发性高血压","降压药物应用基本原则",2003,48,"A","","下列关于高血压病降压治疗的原则，哪一项是错误的",[["A","发生高血压急症应迅速降压"],["B","血压控制满意后，可以立即停药"],["C","单个药物宜从小剂量开始"],["D","联合用药"],["E","尽可能用长效制剂，减少血压波动"]],"B","原发性高血压目前尚无根治方法，高血压与糖尿病等疾病一样，都需终身用药维持，不能在血压控制满意后立即停药（B错，为本题正确答案），否则可能导致血压反跳。高血压急症的治疗原则包括迅速降低血压（A对），预防进行性或不可逆靶器官损害，降低死亡率。降压药物治疗应用基本原则：（1）单个药物宜从小剂量开始（C对），根据需要可逐步增加药物剂量；（2）优先选择长效制剂（E对），可以减少降压过程中血压的波动并提高患者的依从性；（3）联合用药（D对），可以提高降压效果又不增加不良反应；（4）个体化。","","N"],["2003-N49",15,"第二节 慢性心力衰竭","慢性心力衰竭病因与诱因",2003,49,"A","","下列哪项不引起高排血量心力衰竭",[["A","严重贫血"],["B","甲状腺功能亢进"],["C","动静脉瘘"],["D","脚气病"],["E","二尖瓣关闭不全"]],"E","高输出量型心力衰竭由代谢需求增加如甲状腺功能亢进（B对）、妊娠等引起，或者由高动力循环状态如动静脉瘘（C对）、贫血（A对）和脚气病（D对）所引起（七版病理生理学P172）。严重贫血时，全身各组织氧供给不足，心肌收缩能力增强，心率代偿性加快，通过增加组织血液供应以满足组织代谢需要，心脏长期负荷过重最终导致心肌失代偿，出现高排血量心力衰竭。甲状腺功能亢进时，甲状腺激素分泌增加，致使心肌收缩加强，心率加快，外周血管扩张，阻力下降，导致心排血量明显增加。动静脉瘘时，由于大量动脉血经瘘口直接进入静脉，使静脉回心血量增加，左室充盈量增加，导致排血量增加。脚气病时，小血管扩张、周围血管阻力降低、血循环加速，使静脉回流量增多，心排血量增加。二尖瓣关闭不全时，心室收缩期血液经关闭不全的瓣膜反流，导致心排血量减少，属于低排出量心衰（E错，为本题正确答案）。","","N"],["2003-N50",15,"第二节 慢性心力衰竭","左心衰竭症状",2003,50,"A","","关于阵发性夜间呼吸困难发生的可能机制，下列哪一项是错误的",[["A","入睡时迷走神经兴奋性增高，小支气管收缩，影响肺泡通气"],["B","卧位时膈肌上抬，肺活量减少"],["C","卧床后，左室不能承受回流增多的血量，左室舒张末压升高"],["D","熟睡时呼吸中枢敏感性降低"],["E","由于夜间心动过缓引起"]],"E","夜间心动过缓（E错，为本题正确答案）（心率低于60次/分），心室舒张期延长，自心房进入心室的血液增加，心房容量负荷降低，有利于肺静脉血回流，可部分减轻肺循环淤血程度。阵发性夜间呼吸困难发生机制包括：入睡时迷走神经兴奋性增高，小支气管收缩，影响肺泡通气（A对）；卧位时横膈抬高，肺活量减少（B对）；平卧血液重新分配，回流入心脏的血液增多，左室不能承受回流增多的血量，左室舒张末压升高（C对）使肺循环阻力增加，肺静脉淤血加重；夜间呼吸中枢敏感性降低（D对），对肺淤血引起的轻度缺氧反应迟钝，缺氧明显时，才刺激呼吸中枢作出反应。","","N"],["2003-N51",17,"第四节 急性冠状综合征","急性ST段抬高型心肌梗死诊断",2003,51,"A","","下列哪种类型的急性心肌梗死危险性最大",[["A","前壁心肌梗死并发三度房室传导阻滞"],["B","下壁心肌梗死并发三度房室传导阻滞"],["C","下壁合并后壁心肌梗死"],["D","前壁合并高侧壁心肌梗死"],["E","高侧壁合并后侧壁心肌梗死"]],"A","急性心肌梗死预后与梗死面积、有无严重并发症有关。心肌梗死伴有三度房室传导阻滞等并发症的情况，会出现心室射血量严重不足，明显要比单纯心肌梗死要严重（CDE错）。前壁心梗一般是左前降支及其分支闭塞所致，下壁心梗一般是右冠状动脉闭塞所致。左前降支及其分支闭塞还可引起心尖、前间壁、前侧壁等部位的梗死，因此危险性要远大于下壁心梗（A对B错）。另外，根据心肌的特点，心肌前壁最薄，心肌下壁较厚、高侧壁和后侧壁均较厚，因而，当前壁心肌梗死时容易发生心脏破裂等可导致猝死的严重并发症，且前壁面积较大，当出现三度房室传导阻滞时说明梗死范围较大、心室功能严重下降，是急性心肌梗死最危险的情况。","","N"],["2003-N52",19,"第五节 限制型心肌病","限制型心肌病诊断",2003,52,"A","","下列哪种疾病的临床表现与缩窄性心包炎最相似",[["A","肥厚型梗阻性心肌病"],["B","风湿性心脏病"],["C","冠心病"],["D","限制型心肌病"],["E","肺心病"]],"D","缩窄性心包炎因心包增厚、粘连、钙化，导致心脏舒张功能受限；限制性心肌病因心内膜纤维化而导致心脏舒张功能受限，因此两者临床表现较为类似。与缩窄性心包炎相比，限制性心肌病（D对）的特点包括：①肺动脉（收缩期）压明显升高，常大于50mmHg；②舒张压变化较大；③右心室舒张压相对较低（缩窄性心包炎常达1/3收缩压峰值以上）。肥厚型梗阻性心肌病（A错）、风湿性心脏病（B错）、冠心病（C错）和肺心病（E错）的临床表现与缩窄性心包炎存在较大不同。","","N"],["2003-N53",17,"第四节 急性冠状综合征","心肌梗死后综合征",2003,53,"A","","男性，47岁，10天前患急性前壁心肌梗死入院，一天来胸痛再发，呈持续性，在吸气时及仰卧位时加重，坐位或前倾位时可减轻。查体：体温37.5℃，血压正常，右肺底叩浊，呼吸音减弱，可闻及心包摩擦音，胸部X线片示右侧胸腔少量积液。WBC11×10⁹/L，血沉28mm/h。最可能的诊断是",[["A","心肌梗死扩展"],["B","不稳定型心绞痛"],["C","变异型心绞痛"],["D","肺栓塞"],["E","心肌梗死后综合征"]],"E","患者10天前出现急性前壁心肌梗死，再发持续性胸痛1天伴发热，可闻及心包摩擦音（心包炎的典型临床表现），右侧胸腔少量积液，最可能的诊断是心肌梗死后综合征（E对）。心肌梗死的胸痛一般持续数小时至数天，且体位及呼吸运动与胸痛的关系不大，因此不考虑心肌梗死扩展（A错）。心绞痛患者常有胸骨后压榨痛，一般无白细胞升高、血沉加快及心包摩擦音等症状，因此诊断不考虑不稳定型心绞痛（B错）及变异型心绞痛（C错）。肺栓塞（D错）以不明原因的呼吸困难及气促为主要表现，出现胸痛伴咯血，本例虽有胸痛，但无呼吸困难及咯血症状，故不考虑。","","N"],["2003-N54",13,"第三节 慢性呼吸衰竭","慢性呼吸衰竭诊断",2003,54,"A","","女性，60岁，慢性咳喘18年，加重一周，血气分析结果如下：pH7.35，PaO₂55mmHg，PaCO₂74mmHg，AB42mmol/L，血钾2.8mmol/L，血氯80mmol/L，考虑诊断为",[["A","代谢性酸中毒失代偿"],["B","呼吸性酸中毒失代偿"],["C","呼吸性酸中毒伴代谢性酸中毒"],["D","呼吸性酸中毒伴代谢性碱中毒"],["E","呼吸性酸中毒代偿期"]],"D","患者老年女性，慢性咳喘病史，加重一周，血气分析PaO₂55mmHg＜（＜60mmHg），PaCO₂74mmHg＞（＞50mmHg），考虑患者系慢阻肺引起的慢性Ⅱ型呼衰，慢性Ⅱ型呼吸衰竭时体内CO₂长期增高，HCO₃⁻也持续维持在较高水平，易导致呼吸性酸中毒合并代谢性碱中毒。本例患者pH7.35（正常值为7.35～7.45）说明为代偿性酸碱平衡紊乱（AB错）；PaO₂＜60mmHg只能提示低氧血症，不能提示酸碱失衡类型；PaCO₂＞50mmHg，提示有呼吸性酸中毒。AB代表实际碳酸氢盐，反映机体实际的HCO₃⁻含量，患者AB42mmol/L（正常值22～26mmol/L）增高，当AB与SB均增高，AB=SB，提示失代偿的代谢性碱中毒；而AB＞SB则可能为代偿后的代谢性碱中毒或代偿后的呼吸性酸中毒，也可能为代谢性碱中毒合并呼吸性酸中毒（十版内科学P778）。患者血钾2.8mmol/L（正常值3.5～5.5mmol/L），血氯80mmol/L（正常值96～106mmol/L），提示有低钾低氯碱中毒，综上可诊断为代偿性呼吸性酸中毒合并代谢性碱中毒（D对）。","","N"],["2003-N55",13,"第三节 慢性呼吸衰竭","氧疗",2003,55,"A","","男性，62岁，咳嗽气喘40年，5年来间断加重。一周来咳喘、痰多，伴有嗜睡。血气结果显示：呼吸性酸中毒伴代谢性酸中毒。下列治疗方法中哪项不正确",[["A","静脉点滴5%碳酸氢钠，积极纠正酸中毒"],["B","补充血容量"],["C","提高通气量，给予氧疗"],["D","应用抗生素控制感染"],["E","纠正电解质紊乱"]],"A","患者慢性咳喘40年，诊断为慢阻肺。血气分析提示呼吸性酸中毒伴代谢性酸中毒，可见患者体内酸性物质产生增多，发生严重缺氧及CO₂潴留，慢阻肺合并CO₂潴留是由于肺泡通气不足所致，因此治疗上主要是提高通气量，给予氧疗（C对），加快排出CO₂，纠正CO₂潴留。呼吸性酸中毒时，在通气障碍纠正前尽量避免给予碳酸氢钠（A错，为本题正确答案）纠正酸中毒，以免增加体内CO₂的形成，加重中毒症状。电解质紊乱和酸碱平衡失调常同时存在，在治疗酸碱平衡紊乱时，同时要注意纠正水电解质紊乱（E对）。适当补充血容量（B对）以保证血细胞比容（Hct）在一定水平，这对于维持氧输送能力和防止肺水过多具有重要意义。呼吸道感染是患者出现酸碱平衡失调和呼吸衰竭的常见诱因，因此应用抗生素控制感染（D对）是重要的治疗方法。","","N"],["2003-N56",3,"第一节 支气管扩张症","支气管扩张临床表现",2003,56,"A","","杵状指（趾）一般不出现在下列哪种疾病",[["A","亚急性感染性心内膜炎"],["B","支气管扩张"],["C","慢性支气管炎"],["D","脓胸"],["E","肺癌"]],"C","杵状指（趾）为手指或足趾末端增生、肥厚、增宽、增厚，指甲从根部到末端拱形隆起呈杵状。其发生机制可能与肢体末端慢性缺氧、代谢障碍及中毒性损害有关，缺氧时末端肢体毛细血管增生扩张，因血流丰富，软组织增生，末端膨大。杵状指（趾）常见于：①呼吸系统疾病，如慢性肺脓肿、脓胸（D对）、支气管扩张（B对）和支气管肺癌（E对）；②某些心血管疾病，如发绀型先天性心脏病，亚急性感染性心内膜炎（A对）；③营养障碍性疾病，如肝硬化。但是慢性支气管炎（C错，为本题正确答案）患者较少有杵状指表现。","","N"],["2003-N57",7,"第一节 肺癌","原发肿瘤引起的症状和体征",2003,57,"A","","单侧肺局限性哮鸣音可见于",[["A","支气管哮喘"],["B","阻塞性肺气肿"],["C","肺炎"],["D","液气胸"],["E","支气管肺癌"]],"E","单侧局限性哮鸣音常见于：支气管肺癌、支气管异物、支气管内膜结核。支气管肺癌（E对）患者肿瘤向支气管内生长，或转移到肺门淋巴结致使肿大的淋巴结压迫主支气管或隆突或引起部分气道阻塞时，可有呼吸困难、气短、喘息及单侧局限性哮鸣音。支气管哮喘（十版内科学P32）（A错）发作时典型的体征是双肺可闻及广泛的哮鸣音。阻塞性肺气肿（B错）的特点是两肺呼吸音减弱，呼气相延长，严重者两肺闻及广泛哮鸣音。肺炎（C错）患者典型症状为发热、咳嗽、咳痰、胸痛，肺实变时有典型的体征，如叩诊浊音、语颤增强和支气管呼吸音等，但不会出现哮鸣音的表现。液气胸（D错），通常表现为突发胸痛，吸气加重，随之出现呼吸困难，一般无哮鸣音的表现。","","N"],["2003-N58",5,"第一节 肺脓肿","血源性肺脓肿",2003,58,"A","","血源性肺脓肿最常见的病原菌是",[["A","大肠杆菌"],["B","产气杆菌"],["C","金黄色葡萄球菌"],["D","肺炎球菌"],["E","草绿色链球菌"]],"C","血源性肺脓肿是因皮肤外伤感染、疖、痈、中耳炎或骨髓炎等所致的脓毒症，菌栓经血行播散到肺，引起小血管拴塞、炎症和坏死而形成肺脓肿，其最常见的病原菌是金黄色葡萄球菌（C对）。大肠杆菌（A错）也可引起坏死性肺炎，但不是常见的病原体；产气杆菌（B错）主要存在于肠道中，是气性坏疽的主要病原菌；肺炎球菌为需氧与兼性厌氧菌中常见的吸入性肺脓肿的致病菌（D错）；草绿色链球菌（十版内科学P321）（E错）是人体的重要正常菌群之一，分布于上呼吸道、胃肠道和女性生殖道，以口腔分布最多，是亚急性感染性心内膜炎的主要的致病菌。","","N"],["2003-N59",13,"第三节 慢性呼吸衰竭","慢性呼吸衰竭病因",2003,59,"A","","下列哪种疾病不是慢性呼吸衰竭的病因",[["A","重度肺结核"],["B","肺间质纤维化"],["C","尘肺"],["D","胸廓畸形"],["E","严重感染"]],"E","慢性呼吸衰竭多由支气管-肺疾病引起，如慢阻肺、严重肺结核（A对）、肺间质纤维化（B对）、肺尘埃沉着症（C对）等。胸廓和神经肌肉病变，如胸部手术、外伤、广泛胸膜增厚、胸廓畸形（D对）、脊髓侧索硬化症等，亦可导致慢性呼吸衰竭。感染（十版内科学P150）（E错，为本题正确答案）是急性呼吸衰竭常见的病因，而非慢性。","","N"],["2003-N60",1,"第一节 慢性支气管炎","慢性支气管炎肺功能检查",2003,60,"A","","下列哪项指标可提示有早期小气道病变存在",[["A","弥散功能"],["B","潮气量"],["C","流速容量曲线"],["D","最大通气量"],["E","肺泡通气量"]],"C","测定小气道功能的方法有闭合容积、最大呼气流速容量曲线、频率依赖性肺顺应性等。早期小气道病变发生后，小气道阻力增高，最大呼气流速明显降低，且最大呼气流速容量曲线降支下移，所以流速容量曲线（C对）可提示有早期小气道病变存在。弥散功能是反映气体分子通过肺泡膜进行交换的过程，为肺换气功能的指标（A错），而不能提示有早期小气道病变存在。潮气量（B错）、最大通气量（D错）、肺泡通气量（E错）等指标在早期小气道病变时大多无明显变化，故其不能提示有早期小气道病变存在。","","N"],["2003-N61",26,"第一节 胃食管反流病","PPI",2003,61,"A","","治疗重症胃食管反流病的首选药物是",[["A","雷尼替丁"],["B","西沙必利"],["C","奥美拉唑"],["D","氢氧化铝"],["E","丙谷胺"]],"C","治疗胃食管反流病的药物主要有促胃肠动力药、抑酸药和抗酸药（十版内科学P364-P365）。抑酸药包括PPI类和H₂RA类，其中以PPI类药物（如奥美拉唑）（C对）抑酸作用强，适用于症状重、有严重食管炎的患者；H₂RA类（如雷尼替丁）（A错）不能有效的抑制进食刺激引起的胃酸分泌，因此适用于轻、中症患者；促胃肠动力药（西沙必利）（B错）疗效有限且不确定，因此只适用于轻症患者；抗酸药（氢氧化铝、丙谷胺）（DE错）仅用于症状轻、间歇发作的患者作为临时缓解症状用。","","N"],["2003-N62",28,"第一节 消化性溃疡","消化性溃疡病因和发病机制",2003,62,"A","","十二指肠溃疡的发病主要是因为",[["A","胃酸、胃蛋白酶等侵蚀因素增强"],["B","黏膜屏障减弱"],["C","黏膜血流量减低"],["D","细胞更新能力减弱"],["E","表皮生长因子减少"]],"A","消化性溃疡发病的机制是胃酸、胃蛋白酶的侵袭作用与黏膜的防御能力间失去平衡（十版内科学P374）。十二指肠球部溃疡以胃酸、胃蛋白酶等侵蚀因素增强（A对）为主要发病机制，以黏膜屏障功能降低（B错）为主要机制的为胃溃疡。黏膜血流量减低（C错）、细胞更新能力减弱（D错）、表皮生长因子减少（E错）均可以引起胃黏膜的防御能力降低，但都不是十二指肠溃疡的主要发病机制。","","N"],["2003-N63",32,"第二节 肠易激综合征","腹泻",2003,63,"A","","下列不符合肠易激综合征腹泻特点的是",[["A","一般每日大便3～5次左右"],["B","大便多呈稀糊状"],["C","大便多带有黏液"],["D","排便常干扰睡眠"],["E","大便绝对无脓血"]],"D","肠易激综合征是一种功能性胃肠病，无实质性胃肠道病变，主要表现为腹痛或腹部不适伴排便习惯改变，其腹泻特点为：1、腹泻型IBS常排便较急，粪便呈稀糊状（B对）、水样便、有黏液（C对）、无脓血（E对）；2、一般每日3～5次左右（A对），少数严重发作期可达十余次；3、部分患者腹泻与便秘交替发生；4、可伴腹痛，以下腹和左下腹多见，排便或排气后缓解，仅有极少数患者可于睡眠中因腹泻致醒（D错，为本题正确答案）。","","N"],["2003-N64",35,"","",2003,64,"A","","隐性肝性脑病病人的临床特点是",[["A","轻度性格改变"],["B","轻度行为改变"],["C","应答尚准确，但吐字稍缓慢"],["D","可有扑翼样震颤"],["E","无任何临床表现"]],"E","肝性脑病的临床过程可分为5期：潜伏期、前驱期、昏迷前期、昏睡期、昏迷期。潜伏期即题中所提的“隐性肝性脑病”期，“隐性肝性脑病”这种说法已弃用，目前的说法为轻微肝性脑病，其临床特点是起病隐匿，无行为、性格异常（AB错），无神经系统病理征，无扑翼样震颤（D错），脑电图正常，即无任何临床表现（E对C错），只在心理测试或智力测试时有轻微异常。","","N"],["2003-N65",37,"第一节 急性胰腺炎","急性胰腺炎治疗",2003,65,"A","","急性胰腺炎治疗时，下列属抑制胰酶活性的药物是",[["A","抑肽酶"],["B","胰升糖素"],["C","降钙素"],["D","生长抑素"],["E","奥曲肽"]],"A","抑肽酶可以抑制胰蛋白酶及糜蛋白酶，阻止胰脏中其他活性蛋白酶原的激活及胰蛋白酶原的自身激活。急性胰腺炎时，可使用抑肽酶抑制胰酶活性（A对）。胰升糖素（B错）由胰岛A细胞分泌，主要作用是升高血糖，与抑制胰酶活性无关。降钙素（C错）由甲状腺滤泡旁细胞合成和分泌的肽类激素，可降低血浆中钙、磷浓度，抑制钙、磷的吸收。生长抑素（D错）及其生长抑素类似物奥曲肽（E错）可抑制胰泌素和缩胆囊素刺激的胰液基础分泌，但对其活性无影响。","","N"],["2003-N66",40,"第五节 肾病综合征","膜性肾病",2003,66,"A","","好发于中老年的原发性肾病综合征的病理类型是",[["A","微小病变型肾病"],["B","系膜增生性肾小球肾炎"],["C","系膜毛细血管性肾小球肾炎"],["D","膜性肾病"],["E","局灶性节段性肾小球硬化"]],"D","好发于中老年的原发性肾病综合征的病理类型是膜性肾病（D对）。微小病变型肾病（A错）为好发于儿童的原发性肾病综合征的病理类型。系膜增生性肾小球肾炎（B错）、局灶性节段性肾小球硬化（E错）、系膜毛细血管性肾小球肾炎（C错）为好发于青少年的原发性肾病综合征的病理类型。","","N"],["2003-N67",41,"第一节 尿路感染","尿道综合征",2003,67,"A","","鉴别尿路感染与尿道综合征的最根本点是",[["A","尿白细胞的多少"],["B","尿红细胞的多少"],["C","尿白细胞管型的有无"],["D","真性细菌尿的有无"],["E","尿路刺激症状的有无"]],"D","凡有真性细菌尿者，均可诊断为尿路感染。尿道综合征患者虽有尿频、尿急、尿痛及排尿不适等尿路刺激症状，但多次检查均无真性细菌尿。因此，尿路感染与尿道综合征鉴别的最根本点在于真性细菌尿的有无（D对）。白细胞尿（A错）、尿红细胞（B错）及尿白细胞管型（C错）既可见于尿路感染，也可见于非典型致病病原体如支原体、衣原体等感染导致的尿道综合征（十版内科学P502）。鉴别疾病的根本点一般为疾病的发病机制，尿路刺激征（E错）既可见于尿路感染，也可见于尿道综合征，不能作为区分标准。","","N"],["2003-N68",59,"第一节 甲状腺功能亢进症","甲状腺危象",2003,68,"A","","下列不符合甲状腺危象表现的是",[["A","高热达39℃以上"],["B","心率快＞140次/分"],["C","厌食"],["D","恶心、呕吐、腹泻"],["E","白细胞总数和中性粒细胞常减低"]],"E","甲状腺危象，是甲状腺毒症急性加重的一个综合征，为甲状腺素过量释放引起暴发性肾上腺素能兴奋现象。早期为患者原有的症状加剧，伴中等发热、体重锐减、恶心、呕吐、腹泻（D对）、厌食（C对）。典型的甲亢危象临床表现为高热达39℃以上（A对），大汗淋漓、皮肤潮红、窦性或异源性心动过速、心率快（常在140次/分以上）（B对）、极度烦躁不安甚至谵妄、昏迷、死亡。甲亢时，甲状腺功能亢进时，血液中淋巴细胞和单核细胞数增多，白细胞总数和血小板计数减低。但甲状腺危象时，白细胞总数和中性粒细胞数值均升高（E错，为本题正确答案）。有关甲状腺危象的临床表现，九版内、外科有数据差异。","","N"],["2003-N69",60,"第五节 嗜铬细胞瘤","嗜铬细胞瘤代谢紊乱",2003,69,"A","","下列关于嗜铬细胞瘤病人的代谢紊乱，错误的是",[["A","基础代谢率可增高"],["B","血糖增高"],["C","血游离脂肪酸增高"],["D","血钾可增高"],["E","血钙可增高"]],"D","嗜铬细胞瘤释放大量儿茶酚胺，产生以下代谢紊乱：1.低钾血症：儿茶酚胺促进钾离子进入细胞内及促进肾素、醛固酮（具有保钠保水排钾作用）分泌，导致血钾降低（D错，为本题正确答案）；2.基础代谢率增高（A对）：肾上腺素可作用于中枢神经及交感神经系统控制下的代谢过程，使患者耗氧量增加、基础代谢率增高；3.糖代谢紊乱：肝糖原分解加速及胰岛素分泌受抑制而肝糖异生加强，可引起血糖过度增高（B对），糖耐量减低；4.脂代谢紊乱：脂肪分解加速导致血游离脂肪酸增高（C对）；5.高钙血症（E对）：可能与肿瘤分泌甲状旁腺激素相关蛋白有关。","","N"],["2003-N70",47,"第一节 缺铁性贫血","缺铁性贫血临床表现",2003,70,"A","","缺铁性贫血病人发生Plummer-Vinson综合征时的临床特点是",[["A","儿童发育迟缓"],["B","智商低"],["C","烦躁、易怒"],["D","吞咽困难"],["E","异食癖"]],"D","Plummer-Vinson综合征又称缺铁性吞咽困难（D对），以缺铁性贫血、吞咽困难和舌炎为主要表现，好发于30～50岁的白种妇女，男性少见，中国人罕见。","","N"],["2003-N71",53,"第一节 霍奇金淋巴瘤","全身症状",2003,71,"A","","以原因不明发热为主要起病症状的霍奇金病的特征是",[["A","一般年龄较轻"],["B","女性较多"],["C","病变较弥漫"],["D","常不累及腹膜后淋巴结"],["E","多数都有局部或全身皮肤瘙痒"]],"C","霍奇金淋巴瘤（HL）全身症状主要表现为发热、盗汗、瘙痒及消瘦等。30%～40%的HL患者以原因不明的持续发热为起病症状，这类患者一般年龄稍大（A错），男性较多（B错），病变较弥漫（C对），常有腹膜后淋巴结累及（D错）。局部或全身皮肤瘙痒（E错）可见于周期性发热患者，多为年轻女性。","","N"],["2003-N72",56,"第二节 原发免疫性血小板减少症","ITP的三线治疗",2003,72,"A","","下列关于长春新碱治疗ITP的说法，错误的是",[["A","长春新碱是最常用的免疫抑制剂"],["B","可能有促进血小板生成的作用"],["C","可能促进血小板自贮存池释放"],["D","每周只用一次"],["E","静脉注射比静脉滴注效果更佳"]],"E","ITP（特发性血小板减少性紫癜）是一种复杂的多种机制共同参与的获得性自身免疫性疾病。治疗一般首选糖皮质激素，静脉输注丙种球蛋白也属于ITP的一线治疗。ITP的二线治疗包括脾切除、抗CD20单克隆抗体、血小板生成药物和免疫抑制剂等。其中最常用的免疫抑制剂是长春新碱（A对），它除具免疫抑制作用外，还可能有促进血小板生成及释放的作用（BC对）。长春新碱用法为每周一次（D对），每次1mg，4～6周为一疗程，静脉滴注比静脉注射效果更佳（E错，为本题正确答案）。","","N"],["2003-N73",68,"第一节 类风湿关节炎","免疫功能紊乱",2003,73,"A","","在类风湿关节炎发病中起主要作用的细胞是",[["A","CD3⁺细胞"],["B","CD4⁺细胞"],["C","CD8⁺细胞"],["D","B淋巴细胞"],["E","巨噬细胞"]],"B","T细胞是类风湿关节炎（RA）滑膜组织中的主要炎性细胞，在RA发病中扮演着非常重要的角色，这些T细胞大多数为CD4⁺T细胞（B对），而CD8⁺T细胞相对较少（C错），而B淋巴细胞（D错）和巨噬细胞（E错）是作为抗原递呈及自身抗体来源的细胞，但并不起主要作用。而CD3⁺T淋巴细胞（A错），临床常用作检验人体细胞免疫功能状态，增高可见于再生障碍性贫血、恶性胸腔积液、变应性鼻炎等，降低可见于病毒性感染、恶性肿瘤、心脑血管疾病、口腔溃疡等，与类风湿关节炎无关。","","N"],["2003-N74",69,"第一节 系统性红斑狼疮","病情活动度指标",2003,74,"A","","下列与SLE病情活动性无关的实验室检查是",[["A","血清C3、C4下降"],["B","白细胞减少和淋巴细胞绝对值减少"],["C","抗dsDNA抗体升高"],["D","抗Sm抗体升高"],["E","血沉加快"]],"D","系统性红斑狼疮（SLE）处于活动期时，补体C3、C4和总补体活性（CH50）水平常减低（A错），原因是免疫复合物的形成消耗补体，同时肝脏合成补体的能力下降。由于SLE患者常可存在多系统受累，在SLE活动期时常会导致血液系统异常和肾脏损伤等，血常规检查可有贫血、白细胞计数减少、淋巴细胞减少（B错）、血小板计数增加、红细胞沉降率（血沉）增快（E错）等。抗dsDNA抗体多出现在SLE的活动期，抗dsDNA抗体的滴度与疾病活动性密切相关（C错）。抗Sm抗体属于抗ENA抗体一种，对诊断系统性红斑狼疮（SLE）具有辅助诊断意义，但与疾病的活动无关（D对）。","","N"],["2003-N85",30,"第一节 溃疡性结肠炎","溃疡性结肠炎临床表现",2003,85,"A","","下列哪项不是溃疡性结肠炎的表现",[["A","最多见于直肠和乙状结肠"],["B","肠黏膜水肿呈卵石路面状，可有裂沟状深溃疡"],["C","溃疡间黏膜增生可形成增生性息肉"],["D","X线检查可见结肠袋消失、变形缩短"],["E","严重时可并发肠穿孔或癌变"]],"B","溃疡性结肠炎病变最多见于直肠和乙状结肠（A对），可延伸到降结肠，甚至整个结肠。结肠黏膜早期呈充血、水肿、出血、颗粒状改变，黏膜脆弱，触之易出血，此后黏膜形成椭圆形浅小溃疡，先沿结肠的纵轴发展，继而扩展成为广泛而不规则的大片溃疡，而克罗恩病的溃疡特点为深入肠壁的纵行溃疡形成较为典型的裂沟，且由于黏膜下层水肿和细胞浸润形成的小岛突起，加上溃疡愈合后纤维化和瘢痕收缩，使黏膜表现似鹅卵石状，故B选项是克罗恩病的病理特点（B错，为本题正确答案）。溃疡性结肠炎的X线检查主要表现为黏膜粗乱及（或）颗粒状改变，肠管缩短，结肠袋消失呈铅管样等（D对）。由于结肠病变一般局限于黏膜与黏膜下层，很少深入肌层，所以并发结肠穿孔少见，但是在严重病例，结肠全层可受累，甚至在并发中毒性巨结肠的基础上可导致急性肠穿孔，此外病情迁延不愈者癌变的风险较高（E对）。","","N"],["2003-N99",40,"第五节 肾病综合征","微小病变型肾病",2003,99,"B","","轻微病变性肾小球肾炎的临床表现是",[["A","急性肾炎综合征"],["B","急进性肾炎综合征"],["C","肾病综合征"],["D","慢性肾炎综合征"],["E","隐匿性肾炎综合征"]],"C","轻微病变性肾小球肾炎（P471）又称微小病变性肾病，其临床表现为肾病综合征（C对）。其特征性改变和本病的主要依据为电镜下有广泛的肾小球脏层上皮细胞足突融合。肾小球滤过屏障受损导致大量蛋白尿、低蛋白血症及继发的水肿、高脂血症。急性肾炎综合征（A错）主要表现为血尿、蛋白尿、水肿及高血压，多见于急性肾小球肾炎。急进性肾炎综合征（B错）表现为血尿、蛋白尿、水肿及高血压，早期出现少尿性急性肾衰竭，多见于急进性肾小球肾炎。慢性肾炎综合征（D错）表现为血尿、蛋白尿、水肿及高血压，并有不同程度的肾功能减退，多见于慢性肾小球肾炎。隐匿性肾炎综合征（E）指仅表现为肾小球源性血尿或（和）蛋白尿的一组肾小球疾病，多表现为无症状性血尿或（和）蛋白尿，而无水肿、高血压及肾功能损害，可见于轻微病变性肾小球肾炎、轻度系膜增生性肾小球肾炎及局灶节段性肾小球肾炎等病理类型，E选项存在争议。","","N"],["2003-N100",40,"第二节 急性肾小球肾炎","急性肾小球肾炎临床表现",2003,100,"B","","毛细血管内增生性肾小球肾炎的临床表现是",[["A","急性肾炎综合征"],["B","急进性肾炎综合征"],["C","肾病综合征"],["D","慢性肾炎综合征"],["E","隐匿性肾炎综合征"]],"A","毛细血管内增生性肾小球肾炎即急性肾小球肾炎，其临床表现主要为急性肾炎综合征（A对）：血尿、蛋白尿、水肿、高血压。急进性肾炎综合征（B错）表现为血尿、蛋白尿、水肿及高血压，早期出现少尿性急性肾衰竭，多见于急进性肾小球肾炎。肾病综合征（C错）的临床表现为大量蛋白尿、低蛋白血症、水肿及高脂血症，见于多种病理类型的肾小球疾病。慢性肾炎综合征（D错）表现为血尿、蛋白尿、水肿及高血压，并有不同程度的肾功能减退，见于慢性肾小球肾炎。隐匿性肾炎综合征（E错）指仅表现为肾小球源性血尿或（和）蛋白尿的一组肾小球疾病，多表现为无症状性血尿或（和）蛋白尿，而无水肿、高血压及肾功能损害。","","N"],["2003-N101",17,"第四节 急性冠状综合征","ACEI",2003,101,"B","","对提高急性心肌梗死患者生存率无影响的药物是",[["A","硝酸酯类"],["B","钙通道拮抗剂"],["C","血管紧张素转换酶抑制剂"],["D","β-受体阻滞剂"],["E","抗血小板制剂"]],"A","硝酸酯类（A对）主要作用为通过增加冠脉血流以及降低心室前负荷解除疼痛，对急性心肌梗死患者生存率无影响。钙通道阻滞剂（B错）与β受体拮抗剂联合应用或两者与硝酸酯类药物联合应用，可有效减轻胸痛，减轻近期死亡的危险，减少急性心肌梗死和急诊冠脉手术的需要。血管紧张素转换酶抑制剂（ACEI）（C错）有助于改善恢复期心肌的重构，减少MI的病死率和充血性心力衰竭的发生。β受体拮抗剂（D错）能减少心肌耗氧量和改善缺血区的氧供需失衡，缩小MI面积，减少复发性心肌缺血、再梗死、室颤及其他恶性心律失常的发生率，对降低急性期病死率有肯定的疗效，能降低发病率和死亡率。抗血小板制剂（E错）可预防血栓形成，减少复发性心肌缺血、再梗死事件发生，对降低急性期病死率有一定疗效。","","N"],["2003-N102",15,"第二节 慢性心力衰竭","RAAS抑制剂",2003,102,"B","","对提高慢性心力衰竭患者生存率无明显作用的药物是",[["A","硝酸酯类"],["B","钙通道拮抗剂"],["C","血管紧张素转换酶抑制剂"],["D","β-受体阻滞剂"],["E","抗血小板制剂"]],"B","大多数钙通道阻滞剂，尤其是短效的二氢吡啶类以及具有负性肌力作用的钙通道拮抗剂，不能改善慢性心力衰竭患者的症状或提高运动耐量，短期治疗可导致肺水肿和心源性休克，长期应用使心功能恶化，死亡危险增加。只有在慢性心力衰竭患者合并严重高血压或心绞痛，其他药物不能控制时使用氨氯地平或非洛地平，二者长期使用安全性较好，虽不能提高生存率，但对预后并无不利影响（B对）。血管紧张素转换酶抑制剂（十版内科学P183）（C错）是被证实能降低心衰患者病死率的第一类药物，是公认的治疗心衰的基石和首选药物。β受体拮抗剂（十版内科学P184）（D错）长期应用（＞3月）可改善心功能，提高LVEF，更长期使用还可使心肌重构延缓或逆转。硝酸酯类（A错）用以缓解心绞痛或呼吸困难的症状；抗血小板制剂（E错）主要在急性心肌梗死时使用，有预防血栓形成的作用，但此两种药物均被列入有争议、正在研究或疗效尚不能肯定的药物。","","N"],["2003-N103",75,"第二节 农药中毒","迅速清除毒物",2003,103,"B","","有机磷（对硫磷）农药中毒的洗胃液是",[["A","1：5000高锰酸钾"],["B","2%碳酸氢钠"],["C","0.3%H₂O₂"],["D","0.3％氧化镁"],["E","5%硫酸钠"]],"B","急性中毒时，口服中毒者排除禁忌证（吞服强腐蚀性毒物、食管静脉曲张、惊厥或昏迷者）后可采用洗胃的方法清除体内尚未吸收的毒物。有机磷农药中毒的洗胃液一般选用1：5000高锰酸钾溶液或2%碳酸氢钠溶液。但对硫磷（1605）中毒禁用1：5000高锰酸钾（会使其氧化为毒性更强的对氧磷）（A错），而应选用2%碳酸氢钠（B对）；敌百虫中毒禁用2%碳酸氢钠（碱性溶液能使敌百虫变为毒性更强的敌敌畏），而应选用1：5000高锰酸钾。0.3%H₂O₂（C错）主要用于阿片类，氰化物，高锰酸钾等中毒洗胃。0.3%氧化镁（D错）主要用于阿司匹林、草酸等中毒洗胃。5％硫酸钠（E错）主要用于氯化钡、碳酸钡等中毒洗胃。","","N"],["2003-N104",75,"第一节 中毒概述","洗胃",2003,104,"B","","镇静药物中毒的洗胃液是",[["A","1：5000高锰酸钾"],["B","2%碳酸氢钠"],["C","0.3%H₂O₂"],["D","0.3％氧化镁"],["E","5%硫酸钠"]],"A","镇静药物中毒的洗胃液一般选用1：5000高锰酸钾（A对）。2%碳酸氢钠（B错）溶液主要用于有机磷农药（OPI）、氨基甲酸酯类、拟菊酯类等中毒洗胃。0.3%H₂O₂（C错）主要用于阿片类，氰化物，高锰酸钾等中毒洗胃。0.3%氧化镁（D错）主要用于阿司匹林、草酸等中毒洗胃。5%硫酸钠（E错）主要用于氯化钡、碳酸钡等中毒洗胃。","","N"],["2003-N105",61,"第一节 糖尿病","糖化血红蛋白和糖化白蛋白测定",2003,105,"B","","糖化血红蛋白A1反映取血前血糖水平的时间是",[["A","瞬时"],["B","1～2周"],["C","2～3周"],["D","3～4周"],["E","4～12周"]],"E","血糖的测定值反映体内瞬时血糖状态（十版内科学P731）（A错）。糖化血红蛋白的形成与血红蛋白有关，由于红细胞在血循环中的寿命约为120天，糖化血红蛋白A1反映取血前8～12周（注意：此数据五版内科学为4～12周）的血糖水平（E对）。果糖胺反映患者近2～3周内平均血糖水平（C错）。","","N"],["2003-N106",61,"第一节 糖尿病","糖化血红蛋白和糖化白蛋白测定",2003,106,"B","","果糖胺反映提取血前血糖水平的时间是",[["A","瞬时"],["B","1～2周"],["C","2～3周"],["D","3～4周"],["E","4～12周"]],"C","血浆蛋白（主要为白蛋白）可与葡萄糖发生非酶催化的糖化反应而形成果糖胺（FA），其形成的量与血糖浓度和持续时间相关，由于白蛋白在血中半衰期为19天，故FA反应患者近2～3周内平均血糖水平（C对）。血糖的测定值反映体内血糖瞬时状态（A错）。糖化血红蛋白A1反映取血前8～12周（注意：此数据五版内科学为4～12周）的血糖水平（E错）。","","N"],["2003-N119",6,"第一节 肺结核","乙胺丁醇",2003,119,"C","","能杀灭结核菌的药物是",[["A","对氨基水杨酸钠"],["B","乙胺丁醇"],["C","二者均是"],["D","二者均非"]],"D","能杀灭结核菌的药物有：异烟肼、利福平、吡嗪酰胺、链霉素。对氨基水杨酸（A错）可竞争性抑制二氢蝶酸合酶，阻止二氢叶酸的合成，从而使蛋白质合成受阻，抑制结核杆菌的繁殖。乙胺丁醇（B错）可与二价金属离子络合，阻止菌体内亚精胺与镁离子结合，干扰细菌RNA的合成，从而抑制结核杆菌的生长繁殖。对氨基水杨酸和乙胺丁醇均属抑菌剂，不能杀灭结核杆菌（本题AB均错，正确答案为D）。","","N"],["2003-N120",6,"第一节 肺结核","乙胺丁醇",2003,120,"C","","对结核菌有抑菌作用的药物是",[["A","对氨基水杨酸钠"],["B","乙胺丁醇"],["C","二者均是"],["D","二者均非"]],"C","对氨基水杨酸（A对）可竞争性抑制二氢叶酸合酶，阻止二氢叶酸的合成，从而使蛋白质合成受阻，抑制结核杆菌的繁殖。乙胺丁醇（B对）可干扰细菌RNA的合成，从而抑制结核杆菌的生长繁殖，对氨基水杨酸和乙胺丁醇均属抑菌剂。本题AB均对，正确答案为C。","","N"],["2003-N121",35,"第一节 肝硬化","及早识别及去除HE发作的诱因",2003,121,"C","","治疗急性肝性脑病用",[["A","精氨酸"],["B","人工肝"],["C","二者均是"],["D","二者均非"]],"B","人工肝（B对）的原理是利用分子吸附剂再循环系统清除血氨和其他有毒物质，因此无论急性肝性脑病还是慢性肝性脑病都适用。尿素循环的三个重要中间产物（精氨酸、瓜氨酸和鸟氨酸）中，精氨酸可以促进尿素合成，但尿素合成必须在肝中进行，因此精氨酸对重症肝炎所致的急性肝性脑病因肝功能太差而无效。临床上精氨酸（A错）仅用于慢性肝性脑病的治疗，对急性肝性脑病无效，且疗效差，临床应用少。","","N"],["2003-N122",35,"第一节 肝硬化","促进体内氨的代谢",2003,122,"C","","治疗慢性肝性脑病用",[["A","精氨酸"],["B","人工肝"],["C","二者均是"],["D","二者均非"]],"C","人工肝（B对）的原理是利用血液透析清除血氨和其他有毒物质，因此无论急性肝性脑病还是慢性肝性脑病都适用。尿素循环的三个重要中间产物（精氨酸、瓜氨酸和鸟氨酸）中，精氨酸可以促进尿素合成，但尿素合成必须在肝中进行，因此精氨酸对重症肝炎所致的急性肝性脑病因肝功能太差而无效，临床上精氨酸（A对）仅用于慢性肝性脑病的治疗，对急性肝性脑病无效。本题AB均对，正确答案为C。","","N"],["2003-N123",40,"第五节 肾病综合征","肾病综合征免疫抑制治疗",2003,123,"C","","微小病变型肾病的治疗方法是",[["A","单用糖皮质激素"],["B","糖皮质激素并用细胞毒药物"],["C","二者均是"],["D","二者均非"]],"C","微小病变型肾病患者对糖皮质激素敏感，故初期可单用糖皮质激素治疗（A对），对于反复发作（复发率较高）或单用糖皮质激素效果不佳时，可以联合应用细胞毒药物（B对）。本题AB均对，正确答案为C。","","N"],["2003-N124",40,"第五节 肾病综合征","肾病综合征免疫抑制治疗",2003,124,"C","","膜性肾病的治疗方法是",[["A","单用糖皮质激素"],["B","糖皮质激素并用细胞毒药物"],["C","二者均是"],["D","二者均非"]],"B","膜性肾病约占我国原发性肾病综合征的20%。其中约有20%～35%患者的临床表现可自行缓解。膜性肾病单用糖皮质激素效果较差（A错），60%～70%的早期膜性肾病患者经糖皮质激素合并细胞毒药物治疗后可达临床缓解（B对）。","","N"],["2003-N141",15,"第二节 慢性心力衰竭","洋地黄类药物",2003,141,"X","","下列哪些情况宜应用洋地黄治疗",[["A","预激综合征合并房颤"],["B","冠心病合并房颤"],["C","风心病心衰合并房颤"],["D","扩张型心肌病合并房颤"]],"BCD","由于洋地黄可抑制心脏传导系统，对房室交界区的抑制最明显，可减慢房颤患者的心室率，因此洋地黄适用于房颤合并收缩性心衰的治疗。扩张型心肌病合并房颤（D对）应用洋地黄可增加心排出量，降低心室率，有效改善患者的临床症状。冠心病合并房颤（急性心肌梗死24h内除外）（B对）、风心病合并房颤时（C对），使用洋地黄类药物可以有效控制心室率。预激综合征合并房颤（A错）时，应用洋地黄可缩短旁路不应期导致更多的心电活动自旁路下传而加快心室率，因而不宜使用。","","N"],["2003-N142",11,"第一节 胸腔积液","结核性胸膜炎",2003,142,"X","","下列哪些指标支持结核性胸膜炎胸腔积液的诊断",[["A","pH＜7.3"],["B","ADA＜45U/L"],["C","胸水CEA/血清CEA＞1"],["D","胸水LDH/血清LDH＞0.6"]],"AD","结核性胸腔积液、肺炎并发胸腔积液、类风湿关节炎的胸液、血胸和脓胸时胸液pH＜7.30（A对）（二版八年制内科学P145）。结核性胸膜炎时，因细胞免疫受刺激，淋巴细胞明显增多，胸水中腺苷脱氨酶（ADA）多高于45U/L（B错）。胸水CEA升高或胸水/血清CEA＞1（C错），常提示为恶性胸水。结核性胸腔积液为胸膜通透性增加所致，胸水性质为渗出液，具有渗出液的一般特征：比重＞1.018，蛋白＞30g/L，白细胞数＞500×10⁶/L，胸水/血清LDH＞0.6（D对）。","","N"],["2003-N143",27,"第二节 慢性胃炎","慢性胃炎治疗",2003,143,"X","","可能逆转慢性胃炎病人胃黏膜之肠化和不典型增生的药物是",[["A","β-胡萝卜素"],["B","维生素C"],["C","维生素E"],["D","叶酸"]],"ABCD","近年来研究显示可能逆转慢性胃炎病人胃黏膜之肠化和不典型增生的药物有口服选择性COX-2抑制剂塞来昔布、适量复合维生素和含硒的食物，而β-胡萝卜素（A对）、维生素C（B对）、维生素E（C对）、叶酸（B族维生素的复合体）（D对）均为维生素，故均有逆转慢性胃炎病人胃黏膜之肠化和不典型增生的作用。","","N"],["2003-N144",44,"第一节 急性肾损伤","肾脏替代治疗",2003,144,"X","","急性肾衰少尿期进行透析治疗的指征是",[["A","血肌酐每日升高＞176.8μmol/L"],["B","血尿素氮每日升高＞8.9mmol/L"],["C","血钾每日升高＞0.8mmol/L"],["D","酸中毒，二氧化碳结合力＜13mmol/L，pH＜7.25"]],"ABD","肾透析治疗的指征（五版内科学P567）包括：①血钾大于6.5mmol/L；②血尿素氮＞21.4mmol/L，或血肌酐＞442μmol/L；③血肌酐每日升高＞176.8μmol/L（A对），或血尿素氮每日升高＞8.9mmol/L（B对），或血钾每日升高＞1mmol/L（C错）；④急性肺水肿；⑤无明显高分解代谢，但无尿2天或少尿4天以上；⑥严重酸中毒：CO₂CP＜13mmol/L、pH＜7.25（九版内科学更新数据为pH ＜7.2）（D对）。本题选项的数据来源为旧版教材，有关急性肾损伤（肾衰竭）的肾脏代替治疗以十版内科学P523相关内容为准。","","N"],["2003-N145",60,"第五节 嗜铬细胞瘤","高血压",2003,145,"X","","嗜铬细胞瘤病人的血压可表现为",[["A","阵发性高血压"],["B","持续性高血压"],["C","直立性低血压"],["D","高血压和低血压相交替"]],"ABCD","嗜铬细胞瘤起源于肾上腺髓质、交感神经节或其他部位的嗜铬组织，这种瘤持续或间断地释放大量儿茶酚胺，引起持续性（B对）或阵发性高血压（A对），可伴直立性低血压（C对）。其中，阵发性高血压是特征性病变。嗜铬细胞瘤还可发生低血压，或出现高血压和低血压相交替的表现（D对）。低血压及血压交替不稳的发生有下述原因：肿瘤骤然停止释放儿茶酚胺；大量儿茶酚胺引起严重心律失常或心力衰竭；由于肿瘤可分泌肾上腺素，兴奋肾上腺素能β受体，使周围血管扩张；肿瘤分泌多种扩血管物质，如舒血管肠肽、肾上腺髓质素等。","","N"],["2003-N146",50,"第二节 遗传性球形红细胞增多症","遗传性球形红细胞增多症治疗",2003,146,"X","","下列疾病中可以进行切脾治疗的是",[["A","遗传性球形红细胞增多症"],["B","自身免疫性溶血性贫血"],["C","丙酮酸激酶缺乏致贫血"],["D","海洋性贫血"]],"ABCD","血管外溶血性贫血如遗传性球形红细胞增多症（A对）、海洋性贫血（D对）、丙酮酸激酶缺乏致贫血（C对）等，红细胞在脾脏中被破坏，脾切除治疗有效，为脾切除的适应证。血管内溶血性贫血红细胞在血管内被破坏，脾切除无效，如阵发性睡眠性血红蛋白尿。自身免疫性溶血性贫血包括温抗体型自身免疫性溶血性贫血和冷抗体型自身免疫性溶血性贫血，温抗体型自身免疫性溶血性贫血为血管外溶血性贫血，而冷抗体型自身免疫性溶血性贫血为血管内溶血性贫血，故脾切除对部分自身免疫性溶血性贫血有效（B对）。","","N"],["2004-N47",15,"第一节 心力衰竭总论","收缩功能不全",2004,47,"A","","下列关于心力衰竭概念的叙述，错误的是",[["A","心排血量可维持正常"],["B","通常伴有肺循环的主动充血"],["C","是指伴有临床症状的心功能不全"],["D","有心功能不全不一定有心力衰竭"],["E","伴有体循环充血的心衰称为充血性心力衰竭"]],"B","充血是指局部组织或器官因动脉血输入过多致含血量主动增多的过程；淤血是指静脉血液回流受阻，血液被动淤积在小静脉和毛细血管中，使局部组织或器官的含血量增多。慢性左心衰时，左心室射血功能障碍，左心室舒张末期容积增加，左心室舒张末压升高，舒张期左心房内血液无法顺利流入左心室，引起左心房压力升高，左心房压升高使得肺静脉血液回流受阻，出现肺循环淤血，不是肺循环的主动充血（B错，为本题正确答案）。由于各种疾病引起心肌收缩能力减弱，使心输出量降低，难以满足机体需要，同时出现肺循环和（或）体循环淤血的表现，因此心力衰竭又称充血性心力衰竭（E对）。心力衰竭患者早期通过心肌代偿机制，心排出量可维持在正常范围内（A对），甲亢或贫血患者合并心衰时，心排出量可维持在正常水平甚至超过正常。心功能不全是指各种原因引起的心脏结构和功能异常及相关临床表现的一个广泛的概念，当心功能不全病情发展，出现相应的临床症状时称为心力衰竭（CD对）。","","N"],["2004-N48",15,"第一节 心力衰竭总论","其他体液因子的改变",2004,48,"A","","关于心力衰竭时各种体液因子的改变，下列哪项正确",[["A","心衰时，缓激肽生成增加"],["B","缓激肽有很强的利尿作用"],["C","心衰早期，心钠素分泌减少"],["D","内皮依赖性释放因子有强大的缩血管作用"],["E","由于心排血量降低，引起血管加压素分泌减少"]],"A","心衰时，由于心排量不足，交感神经系统及肾素-血管紧张素-醛固酮系统被激活，使去甲肾上腺素、血管加压素、醛固酮、心钠肽、缓激肽等分泌增多（A对）。具有很强的利尿作用的是由心房合成和分泌的心钠肽，而不是缓激肽（B错），缓激肽（bradykinin）是一种血管活性肽，由激肽原酶作用于血浆中激肽原而产生。缓激肽可以使细动脉扩张、血管通透性增加、支气管平滑肌收缩，并可引起疼痛（八版病理学P74）。心力衰竭时，BNP（脑钠肽）及ANP（心钠肽）分泌明显增加（C错），其增高的程度与心衰的严重程度呈正相关，可作为评定心衰进程和判断预后的指标。在缓激肽刺激下，血管内皮细胞合成内皮依赖性释放因子（即NO），有很强的扩血管作用，而不是缩血管作用（D错）。心力衰竭时心房牵张感受器敏感性下降，经迷走神经传至下丘脑的信号减少，对精氨酸加压素（精氨加压素、血管加压素、抗利尿激素为同一种物质）释放的抑制作用减弱，故血管加压素分泌增加（E错）。","","N"],["2004-N49",16,"第二节 窦性心律失常","窦性停搏心电图特点",2004,49,"A","","下列符合心电图诊断窦性停搏的是",[["A","心室率小于40次/分"],["B","可见单个逸搏或逸搏心律"],["C","长PP间期的时间大于1.5秒"],["D","长PP间期与基本的窦性PP间期无倍数关系"],["E","PP间期进行性缩短，直到出现一次长PP间期"]],"D","窦性停搏又称窦性静止、窦性间歇、窦性暂停等。窦性停搏是指窦房结在一个或多个心动周期中不产生冲动，以致不能激动心房或整个心脏。心电图表现为在较正常PP间期显著长的间期内无P波发生，或P波与QRS波均不出现，长的PP间期与基本的窦性PP间期无倍数关系（D对）。窦性停搏心室率不一定小于40次/分（A错），系因停搏后下位潜在起搏点如房室交界处可发出单个逸搏或逸搏性心律控制心室（B对）。PP间期长短变化大，不代表长PP间期的时间大于1.5秒（C错）。PP间期进行性缩短直至出现1次长的PP间期（E错）为二度Ⅰ型窦房传导阻滞的表现。根据十版内科学观点，本题答案应为BD，但参考答案为D。","","N"],["2004-N50",16,"第六节 心脏传导阻滞","三度房室传导阻滞",2004,50,"A","","男性，68岁，持续性心房颤动史10年，长期服用洋地黄、硫氮䓬酮，10天前腹泻伴恶心、食欲下降。两天来出现阵发性头晕、眼黑。查体：BP100/70mmHg，双肺（-），心律整，心率38次/分，左下腹轻压痛。导致患者就诊最直接的病因是",[["A","洋地黄效应"],["B","钙拮抗剂中毒"],["C","慢性腹泻"],["D","缓慢心室率的心房颤动"],["E","完全性房室传导阻滞"]],"E","患者长期服用洋地黄及非二氢吡啶类钙通道拮抗剂硫氮䓬酮，此两种药物均对心脏传导有抑制作用。患者有房颤病史，现心室律变得慢而规则，提示可能出现完全性房室传导阻滞（E对）。心室率过慢可引起供血不足，导致阵发性头晕、眼黑、血压降低。洋地黄效应（A错）主要指正性肌力作用，区别于洋地黄中毒。钙拮抗剂中毒（B错）主要表现为低血压、心搏量减少、出现窦缓、房室传导阻滞、早搏、交界性心律等心律失常，但消化系统症状少见，故患者来院就诊的直接病因最可能是由洋地黄中毒引起的完全性房室传导阻滞。单纯慢性腹泻（C错）并不足以解释患者所有症状，并非就诊的主要原因。缓慢心室率的房颤（D错）亦表现为心律绝对不齐、心音强弱不等、脉搏短绌。","","N"],["2004-N51",18,"第一节 原发性高血压","脑血管病",2004,51,"A","","下列关于高血压所致靶器官并发症的叙述，错误的是",[["A","血压急剧升高可形成脑部小动脉的微动脉瘤"],["B","高血压脑病的临床表现在血压降低后可逆转"],["C","高血压是促使冠状动脉粥样硬化的病因之一"],["D","长期持久高血压可致进行性肾硬化"],["E","严重高血压可并发主动脉夹层"]],"A","长期高血压可导致脑血管壁病变，血管弹性下降，当失去管壁外组织支撑时，容易引起微小动脉瘤；在血压急剧升高时，硬化变脆的细小动脉可发生破裂，导致脑出血（A错，为本题正确答案）。血压升高明显时，小动脉硬化痉挛，局部组织缺血水肿，加之毛细血管通透性增加，发生脑水肿，表现为高血压脑病，出现头痛、头晕眼花、呕吐、视力障碍等症状，血压降低后，部分临床症状可逆转（B对）。高血压可促使冠状动脉粥样硬化（C对）。长期持续高血压使肾小球内囊压力升高，肾小球纤维化、萎缩，肾动脉硬化，导致肾实质缺血和肾单位不断减少（D对）。高血压病人的血液渗入主动脉壁中层形成夹层血肿，即主动脉夹层，夹层突然破裂可导致病人死亡（E对）。","","N"],["2004-N52",17,"第四节 急性冠状综合征","急性ST段抬高型心肌梗死病因",2004,52,"A","","男性，64岁，在抗洪抢险一线，突获悉其母病故后当日发生急性下壁心肌梗死，既往有高血压病5年、糖尿病10年、吸烟40余年。该患者急性心肌梗死的病因是",[["A","劳累及情绪激动"],["B","高血压病"],["C","糖尿病"],["D","动脉硬化"],["E","吸烟过量"]],"D","急性心肌梗死的基本病因绝大数为冠状动脉粥样硬化，血管内斑块破裂，血栓形成，导致冠状动脉堵塞。劳累、情绪激动都是心梗的诱发因素。而高血压病（B错）、糖尿病（C错）、吸烟过量（E错）是冠心病的危险因素。本例患者老年男性，高血压病史5年、糖尿病史10年、吸烟40余年，这些都可以导致冠状动脉粥样硬化，患者在抗洪抢险一线，突获悉其母病故后当日发生急性下壁心肌梗死，劳累及情绪激动（A错）只是急性心肌梗死的诱因，真正的病因是动脉硬化（D对）。","","N"],["2004-N53",17,"第四节 急性冠状综合征","P₂Y₁₂受体拮抗剂",2004,53,"A","","下列关于非ST段抬高心肌梗死（NSTEMI）的叙述，正确的是",[["A","对血清肌钙蛋白增高者应尽早采用溶栓治疗"],["B","病情危险程度比ST段抬高心肌梗死低"],["C","可同时联合应用阿司匹林和氯吡格雷"],["D","血清肌钙蛋白可正常或轻度升高"],["E","早期抗凝治疗不利于降低死亡率"]],"C","非ST段抬高心肌梗死（NSTEMI）患者建议联合应用阿司匹林和氯吡格雷（C对），联合应用可以提高抗血小板疗效，维持12个月。非ST段抬高心肌梗死多为未完全闭塞的血管病变，血栓多为血小板聚集形成的白色血栓，用溶栓药物对于血小板为主的白色血栓是没有效果的，反而会激活凝血系统，使病情恶化，应避免使用（A错）。目前尚无循证医学证据表明，非ST段抬高心梗的危险程度较ST段心梗低（B错）。NSTEMI仍属于心肌梗死范畴，存在心肌的缺血损伤，因此包括肌钙蛋白在内的血清心肌坏死标记物应升高（D错）。NSTEMI应早期抗凝治疗，不仅可以有效减少心血管事件，而且大大降低出血风险，死亡率降低（E错）。","","N"],["2004-N54",21,"第四节 二尖瓣反流","二尖瓣反流临床表现",2004,54,"A","","下列关于二尖瓣关闭不全听诊特点的叙述，正确的是",[["A","第二心音出现延后"],["B","不出现第三心音"],["C","杂音可掩盖第一心音"],["D","杂音多呈递增型"],["E","杂音不向胸骨左缘及心底部传导"]],"C","由于左心室射血期缩短，主动脉瓣关闭提前，由主动脉瓣关闭引起的第二心音成分提前（A错）。二尖瓣关闭不全出现严重反流者可在心尖区闻及第三心音（B错）和短暂的舒张期隆隆样杂音。由于二尖瓣关闭不全，左心室收缩早期的等容收缩期不存在，血流可在心室除极及肌张力增高时向左心房反流，因此杂音可与第一心音同时出现，并可掩盖第一心音（C对）。二尖瓣关闭不全杂音为全收缩期吹风样高调一贯型杂音，而不呈递增型（D错）。二尖瓣关闭不全时前叶损害为主杂音向左腋下或左肩胛下传导，后叶损害为主则杂音向心底部传导为主（E错）。","","N"],["2004-N55",11,"第二节 气胸","排气疗法",2004,55,"A","","下列关于闭合性气胸采用排气疗法的叙述，正确的是",[["A","每次抽气量不宜超过1.5L"],["B","积气量多者可每日抽一次"],["C","胸腔闭式引流应为首选排气方式"],["D","肺复张能力差者，应尽快将气抽尽"],["E","积气量达到该侧胸腔容积的15%即可抽气"]],"B","对于肺被压缩面积＜20%，单纯性、首次发病、无明显症状的闭合性气胸，可采取保守治疗（E错）；肺被压缩＞20%的气胸，应抽气治疗；胸腔闭式引流适用于不稳定型气胸，呼吸困难明显、肺压缩程度较重，交通性或张力性气胸，反复发生气胸的患者（C错），只有出现上述适应证时才选用。闭合性气胸，一次抽气量不宜超过1000ml（A错），每日或隔日抽气1次，积气量多者可每日抽一次（B对）。肺复张能力较差者，应采用胸腔闭式引流，但不应尽快将气抽尽，避免胸腔压力骤降后产生肺复张后肺水肿或循环衰竭（D错）。","","N"],["2004-N56",11,"第一节 胸腔积液","渗出性胸腔积液",2004,56,"A","","下列哪项不是渗出性胸膜炎的病因",[["A","阻塞性肺炎累及胸膜"],["B","纵隔肿瘤侵袭胸膜"],["C","系统性红斑狼疮"],["D","气胸"],["E","药物过敏"]],"E","胸腔积液是指胸腔内液体产生增多或吸收减少，超出正常范围的一种病理改变。渗出液产生的常见病因有：①胸膜通透性增加，如胸膜炎症（肺结核、肺炎）（A错）、风湿性疾病[系统性红斑狼疮（SLE）（C错）、类风湿关节炎（RA）]、胸膜肿瘤（恶性肿瘤转移、间皮瘤）（B错）、肺梗塞、膈下炎症（膈下脓肿、肝脓肿、急性胰腺炎）等；②壁层胸膜淋巴引流障碍，如癌症淋巴管阻塞、发育性淋巴管引流异常等。可并发胸腔积液的气胸（D错）一般时由肺部炎症所致，故其胸腔积液的性质为渗出液；药物过敏（E对）时，也可使血管通透性增加，但其是作用于内皮细胞使细胞收缩而内皮细胞间隙变大所致，其胸腔积液产生没有炎症细胞的主动游出，所以为漏出液。","","N"],["2004-N57",6,"第一节 肺结核","肺结核临床表现",2004,57,"A","","下列关于肺结核患者咯血的叙述，正确的是",[["A","大量咯血时多伴有胸痛"],["B","约有1/2的患者有不同程度的咯血"],["C","大量咯血主要是由于肺小动脉破裂"],["D","痰中带血主要为病灶毛细血管扩张所致"],["E","咯血后常伴有低热的原因主要是并发感染"]],"D","结核病时约有1/3的病人会出现不同程度的咯血（B错）。痰中带血为结核性炎症使毛细血管扩张，通透性增高所致（D对）；病变损伤小血管则血量增加；若空洞中小动脉瘤破裂则引起大咯血，出血可以源自肺动脉，亦可来自支气管动脉（C错）。大量咯血时多不伴有胸痛（A错），而病变累及胸膜时，才表现为胸膜性胸痛，随呼吸和咳嗽加重。咯血后常伴有低热是小支气管内残留血块吸收所致（E错）。","","N"],["2004-N58",5,"第一节 肺脓肿","肺脓肿胸部影像学检查",2004,58,"A","","下列哪项不符合肺脓肿的X线检查表现",[["A","可见多房性脓腔"],["B","急性期的脓腔内壁可光整"],["C","早期为大片浓密模糊浸润阴影"],["D","可出现在数个肺段或分布在两侧肺野"],["E","治疗后，先脓腔缩小，后周围炎症消失"]],"E","肺脓肿早期的炎症X线检查表现为大片浓密模糊的浸润阴影（C对），分布在数个肺段或分布在两侧肺野（D对）。在肺脓肿急性期，肺组织坏死、肺脓肿形成后，脓液经支气管排出，脓腔出现圆形透亮区及液平面，其四周被浓密的炎症浸润所环绕。脓腔内壁光滑（B对）或者不规则。经脓液引流和抗生素治疗后，其周围炎症先吸收，逐渐缩小至脓腔消失（E错，为本题正确答案）。慢性肺脓肿脓腔壁增厚，内壁不规则，可见多房性脓腔（A对）。","","N"],["2004-N59",13,"第三节 慢性呼吸衰竭","正压机械通气",2004,59,"A","","男性，60岁，有慢性咳喘史35年，多次血气检查PaCO₂在55～60mmHg。近来因着凉后症状加重，入院时紫绀明显。血气分析PaCO₂86mmHg，PaO₂50mmHg，拟行机械通气。其治疗目标是",[["A","使PaCO₂降至完全正常"],["B","使PaCO₂降至55～60mmHg"],["C","使PaCO₂降至低于正常"],["D","使PaCO₂维持现状"],["E","使PaO₂恢复正常"]],"B","该患者有慢性咳喘史35年，多次血气检查PaCO₂为55～60mmHg，说明患者在这个状态下能够代偿。着凉后症状加重，紫绀明显，PaCO₂86mmHg＞50mmHg，PaO₂50mmHg＜60mmHg，患者PaCO₂明显升高，出现了明显的CO₂潴留，因此在加强抗感染的基础上可采用机械通气。对于慢性呼衰患者，呼吸中枢化学感受器对CO₂反应性差，呼吸的维持主要依靠低氧血症对颈动脉体、主动脉体化学感受器的兴奋作用，因此在使用机械通气时，应采取低浓度吸氧，使PaO₂大于60mmHg，PaCO₂恢复及维持在原有水平即可（55～60mmHg）（B对），慢性呼衰时因CO₂潴留发展缓慢，肾脏可通过减少HCO₃⁻的排出来维持pH恒定。但当体内CO₂长期增高时，HCO₃⁻也持续维持在较高水平，PaCO₂不宜在短时间内降至正常或低于正常，否则体内高水平的碳酸氢盐不能立刻下降，容易造成代谢性碱中毒，碱中毒时，血红蛋白与氧的亲和力增加，导致氧的释放减少，会加重组织缺氧。","","N"],["2004-N60",4,"第三节 病毒性肺炎","病毒性肺炎临床表现",2004,60,"A","","下列关于病毒性肺炎临床表现的叙述，正确的是",[["A","并发胸腔积液者较多见"],["B","起病较急，但临床症状较轻"],["C","肺部体征为较典型的肺炎体征"],["D","X线胸片可见散发性大片浸润阴影"],["E","感染可波及肺泡，但较少侵犯肺间质"]],"B","病毒性肺炎多为间质性肺炎（E错），肺炎可为局灶性或弥漫性，但大叶实变及胸腔积液者均不多见（A错）。病毒性肺炎好发于病毒疾病流行季节，症状通常较轻，但起病较急，发热、头痛、全身酸痛、倦怠等全身症状较突出（B对）。本病常无显著的胸部体征，病情严重者有呼吸浅速、心率增快、发绀、肺部干、湿性啰音（C错）。胸部X线检查可见肺纹理增多，磨玻璃状阴影，小片状浸润或广泛浸润、实变（D错），病情严重者显示双肺弥漫性结节状浸润。","","N"],["2004-N61",26,"第一节 胃食管反流病","胃食管反流病诊断",2004,61,"A","","诊断反流性食管炎最准确的方法是",[["A","食管吞钡X线检查"],["B","食管滴酸试验"],["C","食管内镜检查"],["D","食管24小时pH值监测"],["E","食管测压"]],"C","食管内镜检查（C对）是诊断反流性食管炎（RE）最准确、直观的方法，并能判断其严重程度和有无并发症，结合活检可与其他原因引起的食管炎和其他食管病变作鉴别。虽然食管吞钡X线检查（A错）、食管滴酸试验（B错）、24h食管pH监测（D错）和食管测压（E错）都对本病的诊断有帮助，但都不是最准确的检查方法。","","N"],["2004-N62",28,"第一节 消化性溃疡","出血",2004,62,"A","","下列关于消化性溃疡并发出血的叙述，正确的是",[["A","胃溃疡一般比十二指肠溃疡容易发生"],["B","一般出血50ml～100mL即可出现黑便"],["C","出血超过500mL时就可引起循环障碍"],["D","半小时内出血超过1000mL时均会发生休克"],["E","第一次出血后很少复发"]],"B","出血是消化性溃疡最常见并发症，其发生率约占本病患者的20%～25%，也是上消化道出血的最常见原因，并发于十二指肠溃疡者多见于胃溃疡（A错），而并发于球后溃疡者更为多见。并发出血者，其消化性溃疡病史大多在一年以内，但一次出血后，就易发生第二次或更多次出血（E错），尚有10%～15%的患者以大量出血为消化性溃疡的首见症状。消化性溃疡出血的临床表现取决于出血的部位、速度和出血量，一般出血50ml～100ml即可出现黑便（B对）；十二指肠溃疡出血，黑粪比呕血多见，而胃溃疡出血，两者发生机会相仿。出血量＞400ml（非500ml），可出现头昏、心悸、乏力等循环衰竭症状（C错）。短时间内出血超过1000ml时可（非均会）出现休克（D错）。","","N"],["2004-N63",29,"第一节 肠结核","大便习惯改变",2004,63,"A","","下列关于肠结核腹泻特点的叙述，错误的是",[["A","腹泻是溃疡型结核的主要临床表现之一"],["B","一般不含黏液和脓液"],["C","腹泻可与便秘交替"],["D","常伴里急后重"],["E","便血极少见"]],"D","腹泻是溃疡型肠结核的主要临床表现之一（A对），腹泻常与腹痛相伴随，系肠管炎症和溃疡病变，使肠蠕动加速，肠排空过快所致。腹泻可与便秘交替（C对）（腹泻与便秘交替可见于肠结核、结核性腹膜炎、肠易激综合征、大肠癌等），此与胃肠道功能紊乱有关，非肠结核特异症状。粪便多呈糊样，一般不含黏液脓血（BE对）。里急后重为累及下端结肠或直肠肛门的刺激症状，因肠结核好发于回盲部，占85%，因此肠结核一般无里急后重（D错，为本题正确答案）。","","N"],["2004-N64",35,"第一节 肝硬化","消化道出血",2004,64,"A","","肝硬化最常见的并发症是",[["A","肝性脑病"],["B","自发性腹膜炎"],["C","上消化道出血"],["D","肝肾综合征"],["E","原发性肝癌"]],"C","食管胃底静脉曲张破裂出血所致的上消化道出血是肝硬化最常见的并发症（C对），临床表现为突发呕血、柏油样大便，常为大量出血，引起出血性休克。肝性脑病（A错）是肝硬化最严重的并发症，也是最常见的死亡原因；自发性腹膜炎（B错）在住院腹水患者中发生率为10%～30%，常表现为短期内腹水迅速增加，对利尿剂无反应；肝肾综合征（D错）在顽固性腹水基础上出现少尿、无尿以及恶心等氮质血症的临床表现，较少见；原发性肝癌（E错）是肝硬化的进展阶段，是我国常见的恶性肿瘤之一。以上都不是肝硬化最常见的并发症。","","N"],["2004-N65",37,"第二节 慢性胰腺炎","胰腺内分泌功能不全的表现",2004,65,"A","","慢性胰腺炎后期，由于胰腺内分泌功能不全可引起",[["A","脂肪泻"],["B","夜盲症"],["C","维生素K缺乏症"],["D","维生素D缺乏症"],["E","糖尿病"]],"E","胰腺分为外分泌腺和内分泌腺两部分。外分泌腺分泌胰液，胰液中含有碳酸氢钠、胰蛋白酶原、脂肪酶、淀粉酶等。内分泌腺由大小不同的细胞团（胰岛）所组成。由于慢性胰腺炎引起胰岛β细胞破坏、胰岛素分泌不足，半数患者可发生糖尿病，为胰腺内分泌功能不全的表现（E对）。慢性胰腺炎后期，由于胰液分泌缺乏可引起食物中的脂肪和蛋白质不能完全被消化和吸收，常引起脂肪泻；同时也可使脂溶性维生素A、D、E、K等吸收受到影响。因此脂肪泻（A错）、夜盲症（夜盲症是由于维生素A缺乏所致）（B错）、维生素K缺乏症（C错）和维生素D缺乏症（D错）都是胰腺外分泌功能不全的临床表现。","","N"],["2004-N66",52,"第二节 急性白血病","急性白血病细胞遗传学和分子生物学检查",2004,66,"A","","急性非淋巴细胞白血病M₂型的基因改变是",[["A","PML/RARa"],["B","MLL/ENL"],["C","CBFB/MYH11"],["D","bcr/abl"],["E","AML1/ETO"]],"E","急性非淋巴细胞白血病M₂型（急性粒细胞白血病部分分化型）的基因改变是AML1-ETO（E对）。PML-RARa（A错）基因改变见于M₃型（急性早幼粒细胞白血病）。MLL-ENL（B错）基因改变见于M₅（急性单核细胞白血病）。CBFB-MYH11（C错）基因改变见于M₄EO。bcr-abl（D错）基因改变多见于慢粒（慢性髓系白血病），少数见于急性粒细胞白血病、急性淋巴细胞白血病等。","","N"],["2004-N67",52,"第二节 急性白血病","ALL造血干细胞移植",2004,67,"A","","下列关于急性白血病骨髓移植治疗的叙述，正确的是",[["A","自体骨髓移植应在第一次缓解期进行"],["B","异基因骨髓移植应在第二次缓解期进行"],["C","异基因骨髓移植患者的年龄应控制在40岁以内"],["D","从完全缓解到自体骨髓移植的时间间隔以6个月内为佳"],["E","自体外周血干细胞移植较自体骨髓移植的造血功能恢复慢"]],"A","骨髓移植是包括自体骨髓移植、自体外周血干细胞移植和异基因骨髓移植，都应在第一次缓解期进行（A对B错）。骨髓移植患者的年龄应控制在50岁以内（C错），从完全缓解到自体骨髓移植的时间以6个月以上为佳（D错）。自体外周血干细胞移植与自体骨髓移植相比具有植入几率高，造血、免疫功能重建快的特点（E错）。","","N"],["2004-N68",49,"第一节 再生障碍性贫血","促造血治疗",2004,68,"A","","用雄激素治疗再生障碍性贫血，下列选项中错误的是",[["A","雄激素可刺激骨髓造血"],["B","对慢性再障疗效较好"],["C","对重型再障无效"],["D","在用药1个月后生效"],["E","目前常用的是司坦唑醇（康力龙）"]],"D","雄激素可刺激骨髓造血（A对），临床上用这一原理来治疗再障。雄激素对慢性再障疗效较好（B对），使用2～3月后起效（D错，为本题正确答案）。五版内科学认为雄激素对重型再障无效，八、九、十版内科学认为雄激素适用于全部再障（C错）。目前常用的雄激素为：司坦唑醇（康力龙）（E对）、十一酸睾酮（安雄）、达那唑、丙酸睾酮。根据九版内科学观点，本题答案应为CD，但参考答案为D。","","N"],["2004-N69",59,"第一节 甲状腺功能亢进症","Graves眼病",2004,69,"A","","下列选项中，不属于Graves病患者单纯性突眼的表现是",[["A","眼球向前突出"],["B","瞬目减少"],["C","眼睑肿胀、肥厚、结膜充血、水肿"],["D","双眼上看时，前额皮肤不能皱起"],["E","双眼看近物时，眼球辐辏不良"]],"C","Graves病引起的眼部改变大致可分为单纯性突眼与浸润性突眼。单纯性突眼与甲状腺毒症所致的交感神经兴奋性增高有关，主要表现为：①轻度突眼：眼球向前突出超过正常值3mm以下，即19～20mm（正常眼突度男18.6mm，女16mm）（A错）。②Stellwag征：瞬目减少（B错），炯炯发亮。③Joffroy征：双眼上看时，前额皮肤不能皱起（D错）。④Mobius征：双眼看近物时，眼球辐辏不良（E错）。⑤上睑挛缩，睑裂增宽。⑥von Graefe征：双眼向下看时，由于上眼睑不能随眼球下落，显现白色巩膜。浸润性突眼即Graves眼病，与眶后组织炎症有关。浸润性突眼眼球明显突出，超过参考值上限3mm以上。查体见眼睑肿胀、肥厚、结膜充血、水肿（C对），严重浸润性突眼者眼球固定，眼睑闭合不全，角膜外露而形成角膜溃疡、全眼炎，甚至失明。","","N"],["2004-N70",60,"第五节 嗜铬细胞瘤","肿瘤部位及生化特征",2004,70,"A","","嗜铬细胞瘤可产生多种肽类激素，其中引起面部潮红的是",[["A","P物质"],["B","阿片肽"],["C","生长抑素"],["D","血清素"],["E","神经肽Y"]],"A","嗜铬细胞瘤可产生多种肽类激素，一部分可能引起一些不典型的症状，如Ｐ物质（A对）和舒血管肠肽可导致面部潮红，阿片肽（B错）和生长抑素（C错）可引起便秘，胃动素、血管活性肠肽和血清素（D错）可引起腹泻，神经肽Y（E错）可引起血管收缩和面色苍白，舒血管肠肽、肾上腺髓质素可引起低血压或休克。","","N"],["2004-N71",40,"第一节 肾小球疾病概述","高血压",2004,71,"A","","下列选项中，不属于肾小球病性高血压发生机制的是",[["A","钠、水潴留"],["B","血管内皮素分泌增多"],["C","肾素分泌增多"],["D","肾内激肽释放酶-激肽生成减少"],["E","前列腺素生成减少"]],"B","血管内皮素分泌增多（B错，为本题正确答案）为原发性高血压的发生机制之一，不属于肾小球病性高血压。钠、水潴留（A对）后引起容量依赖性高血压；肾实质缺血使肾素分泌增多（C对），激活肾素-血管紧张素-醛固酮系统，引起肾素依赖性高血压；肾实质损害后肾内降压物质分泌减少，如肾内激肽释放酶-激肽生成减少（D对），前列腺素生成减少（E对）等。以上均为肾小球疾病高血压的发生机制。","","N"],["2004-N72",40,"第五节 肾病综合征","细胞毒药物",2004,72,"A","","最常用于治疗肾病综合征的细胞毒药物是",[["A","长春新碱"],["B","氮芥"],["C","环磷酰胺"],["D","苯丁酸氮芥"],["E","硫唑嘌呤"]],"C","细胞毒药物是常用的抗肿瘤药物，并非治疗肾病综合征的首选药物，一般不单独使用。常常是在使用激素治疗无效或不能完全缓解症状时，加用细胞毒药物可提高治疗效果，使病情得到缓解。所以，细胞毒药物与激素合用的治疗方法，常用于治疗对激素抵抗型或激素依赖型肾病综合征。选项中五种药物均为细胞毒药物，但环磷酰胺（C对）为临床上最常用于治疗肾病综合征。氮芥（B错）为最早用于治疗肾病综合征的细胞毒药物，因可引起注射部位血管炎或局部组织坏死及严重的胃肠道反应及骨髓抑制，现已较少使用。苯丁酸氮芥（D错）疗效较差，但毒性较氮芥小。硫唑嘌呤（E错）治疗肾病综合征效果亦差。长春新碱（A错）为治疗ITP最常用的免疫抑制剂。","","N"],["2004-N73",69,"第一节 系统性红斑狼疮","系统性红斑狼疮一般检查",2004,73,"A","","SLE患者不会出现的血液学异常是",[["A","血红蛋白减少"],["B","网织红细胞减少"],["C","白细胞减少"],["D","淋巴细胞减少"],["E","血小板减少"]],"B","SLE即系统性红斑狼疮，是一种多发于青年女性的累及多脏器的自身免疫性炎症性结缔组织病。SLE患者贫血常见，血红蛋白减少（A错）；白细胞减少（C错），且通常与疾病活动性相关，约50%患者白细胞计数低于4500/μL，尤其见于那些处于SLE活动期患者；约20%的SLE患者发生淋巴细胞减少（淋巴细胞计数＜1500/μL）（D错）；25%～50%的SLE患者有轻度血小板减少（血小板计数100000～150000/μL），10%的患者血小板计数低于50000/μL（E错）。系统性红斑狼疮（SLE）患者由于红细胞减少，可刺激骨髓造血，因此网织红细胞计数反应性增高，而不是减少（B对）。","","N"],["2004-N74",68,"第一节 类风湿关节炎","类风湿因子",2004,74,"A","","在常规临床工作中测得的RF类型是",[["A","IgG"],["B","IgA"],["C","IgM"],["D","IgD"],["E","IgE"]],"C","在常规临床工作中测得的RF（类风湿因子）主要为IgM类自身抗体（C对），但在一些特殊患者临床检查工作中也可测到IgG（A错）类、IgA（B错）类和IgE（E错）类。IgD（D错）抗体主要出现在成熟的B淋巴细胞的表面上，可能与细胞识别有关，以便对相对的病原体进行免疫反应，也可能与B细胞的分化有关，但不属于RF类型，也不作为常规临床检测指标。","","N"],["2004-N78",44,"第一节 急性肾损伤","进展期和维持期",2004,78,"A","","下列关于急性肾衰竭的叙述，正确的是",[["A","肾性急性肾衰竭时通常尿液浓缩，尿比重和渗透压高"],["B","尿量是判断有无急性肾衰竭的唯一指标"],["C","20%的急性肾衰竭与创伤和手术相关"],["D","高血钾是少尿期最主要的死亡原因"],["E","多尿期时氮质血症恢复正常"]],"D","急性肾损伤少尿期肾排泄钾减少、酸中毒及组织分解过快共同导致血钾升高致高钾血症，高钾血症引起心脏电生理紊乱，甚至心跳骤停，导致猝死，高钾血症是少尿期最主要的死亡原因（D对）。肾性急性肾衰竭时，肾小管浓缩功能受损，常排出低渗尿（A错），尿比重固定在1.010～1.014之间。尿量明显减少是肾功能受损的最突出表现，但急性肾衰竭后期尿量增多，每日尿量可达3000～5000ml，因此尿量并不是判断有无急性肾衰竭的唯一指标（B错）。急性肾衰约60%与创伤和手术相关（C错），约40%为内科原因所致的血流动力学改变或由肾毒素造成。在多尿期早期时仍处于氮质血症（E错）和水、电解质失衡状态，肌酐和血钾水平仍高，随肾功能逐渐恢复才降至正常。","","N"],["2004-N84",28,"第一节 消化性溃疡","消化性溃疡病理",2004,84,"A","","下列关于胃溃疡的叙述，正确的是",[["A","95%的胃溃疡位于胃小弯"],["B","Ⅱ型胃溃疡癌变的可能性最大"],["C","胃溃疡不易引起胆汁反流"],["D","胃溃疡的幽门螺杆菌检出率不到50%"],["E","伴胃炎者少，抗酸药物治疗效果好"]],"A","胃溃疡（GU）好发于胃小弯，占95%（A对）。Ⅱ型胃溃疡靠近幽门，高胃酸，常合并十二指肠溃疡（DU）（七版外科学P426），比单纯胃溃疡癌变率低（B错）。GU患者幽门括约肌张力较低，常伴胆汁反流性胃炎（C错）。DU患者的Hp感染率高达90%～100%，GU为60%～90%（D错）。与DU多由胃酸分泌过多所致的发病机制不同，GU多是胃黏膜保护性因素减弱所致，其基础胃酸稍增高，也可正常，甚至低于正常，因此制酸剂治疗效果不明显，此外GU患者多伴多灶萎缩性胃炎（E错）。","","N"],["2004-N101",15,"第二节 慢性心力衰竭","β受体拮抗剂",2004,101,"B","","β受体阻滞剂应首选用于",[["A","扩张型心肌病并发心力衰竭"],["B","风湿性心脏病二尖瓣狭窄并发心力衰竭"],["C","急性病毒心肌炎并发心力衰竭"],["D","肺源性心脏病并发心力衰竭"],["E","冠心病心房颤动并发心力衰竭"]],"A","扩张性心肌病并发的心衰（A对）多为充血性心力衰竭，在使用洋地黄、利尿剂的同时，选用β受体阻滞剂，不但能控制心衰，而且还能延长患者存活时间，降低致残率、住院率，提高运动耐量。风心病二狭（B错）伴心力衰竭，风湿热是其主要病因，因此要进行病因治疗，二尖瓣狭窄也可并发感染性心内膜炎，因而要注意预防。病毒性心肌炎如出现心力衰竭（C错）多提示炎症范围广泛，病情严重，可酌情使用利尿剂、血管扩张剂、ACEI等。肺源性心脏病合并心衰（D错）一般是由呼吸系统感染等原因引起的，故首选治疗应该是控制感染，改善通气。伴有快速心房颤动（E错）、心房扑动的收缩性心力衰竭首选洋地黄。","","N"],["2004-N102",15,"第二节 慢性心力衰竭","洋地黄类药物",2004,102,"B","","洋地黄制剂应首选用于",[["A","扩张型心肌病并发心力衰竭"],["B","风湿性心脏病二尖瓣狭窄并发心力衰竭"],["C","急性病毒心肌炎并发心力衰竭"],["D","肺源性心脏病并发心力衰竭"],["E","冠心病心房颤动并发心力衰竭"]],"E","洋地黄属强心苷类药物，对各种原因导致的心力衰竭，凡有收缩功能障碍，均可使用强心苷治疗，但因缺乏心肌正性松弛作用，不能纠正舒张功能障碍，无法改善供养和代谢，因此对不同病因导致的心力衰竭疗效有差异。其中伴有房颤或心室率快的心力衰竭时强心苷的最佳适应症（E对），能产生良好的对症疗效，增加心排量，降低左室舒张末压与左室舒张末期容积，减轻水肿，缓解呼吸困难。对高血压、瓣膜病、先心病、风湿性心脏病（高度二尖瓣狭窄的病例除外）（B错）、冠状动脉粥样硬化性心脏病所致的低排量心力衰竭疗效良好，对贫血、甲亢、维生素B₁缺血所致能量产生障碍的心力衰竭疗效较差，对肺心病（D错）、心肌炎（C错）或风湿活动期的心力衰竭因心肌缺氧和能量产生障碍而疗效差，对心肌外机械因素所致的心力衰竭如严重二尖瓣狭窄、缩窄性心包炎患者无效；同时对扩张型心肌病（A错）、心肌肥厚、舒张性心力衰竭者不应选用强心苷而应首选β受体阻断药、ACEI。","","N"],["2004-N103",36,"第一节 原发性肝癌","病毒性肝炎",2004,103,"B","","最易并发原发性肝癌的是",[["A","病毒性肝炎后肝硬化"],["B","酒精性肝硬化"],["C","原发性胆汁性肝硬化"],["D","淤血性肝硬化"],["E","血吸虫病性肝硬化"]],"A","原发性肝癌是指由肝细胞或肝内胆管上皮细胞发生的恶性肿瘤。乙型肝炎病毒（HBV）为一种DNA病毒，其基因组内X基因可整合至宿主细胞基因组上，激活癌基因，促进细胞增殖，导致癌变。HBV感染→慢性肝炎→肝硬化（A对）→肝癌是最主要的发病机制（十版内科学P427）。酒精性肝硬化亦可并发原发性肝癌，但较为少见（B错）。胆汁性肝硬化（C错）、淤血性肝硬化（D错）及血吸虫病肝纤维化（E错）一般不导致原发性肝癌。","","N"],["2004-N104",34,"","",2004,104,"B","","血清抗线粒体抗体阳性率高且滴度高的是",[["A","病毒性肝炎后肝硬化"],["B","酒精性肝硬化"],["C","原发性胆汁性肝硬化"],["D","淤血性肝硬化"],["E","血吸虫病性肝硬化"]],"C","原发性胆汁性肝硬化一般认为是一种自身免疫反应介导的慢性进行性胆汁淤积性肝病。患者血清免疫球蛋白增加，特别是IgM，线粒体抗体在体液免疫中起关键作用，95%以上血清抗线粒体抗体阳性，且滴度常在1：128以上，因此血清抗线粒体抗体阳性率高且滴度高的是原发性胆汁性肝硬化（C对）。病毒性肝炎后肝硬化（A错）、酒精性肝硬化（B错）、淤血性肝硬化（D错）、血吸虫病性肝硬化（E错）均无自身免疫因素参与。","","N"],["2004-N105",61,"第一节 糖尿病","胰岛素",2004,105,"B","","速效胰岛素是",[["A","半慢胰岛素锌混悬液"],["B","慢胰岛素锌混悬液"],["C","中性精蛋白锌胰岛素"],["D","低精蛋白锌胰岛素"],["E","精蛋白锌胰岛素"]],"A","本题考察胰岛素的分类。胰岛素制剂按作用起效快慢和维持时间长短分为短效、中效、长效胰岛素（十版内科学P738）。短效胰岛素包括普通（正规）胰岛素、锌结晶胰岛素、半慢胰岛素锌混悬液（A对）；中效胰岛素包括低精蛋白锌胰岛素（中性精蛋白锌胰岛素，也可称为中性鱼精蛋白锌胰岛素）（CD错）和慢胰岛素锌混悬液（B错）；长效胰岛素包括精蛋白锌胰岛素注射液（鱼精蛋白锌胰岛素）（E错）和特慢胰岛素锌混悬液。","","N"],["2004-N106",61,"第一节 糖尿病","胰岛素",2004,106,"B","","长效胰岛素是",[["A","半慢胰岛素锌混悬液"],["B","慢胰岛素锌混悬液"],["C","中性精蛋白锌胰岛素"],["D","低精蛋白锌胰岛素"],["E","精蛋白锌胰岛素"]],"E","考察胰岛素的分类。胰岛素制剂按作用起效快慢和维持时间长短分为短效、中效、长效胰岛素。短效胰岛素包括普通（正规）胰岛素、半慢胰岛素锌混悬液（A错）；中效胰岛素包括低精蛋白锌胰岛素（中性精蛋白锌胰岛素，也可称为中性鱼精蛋白锌胰岛素）（CD错）和慢胰岛素锌混悬液（B错）；长效制剂有精蛋白锌胰岛素注射液（鱼精蛋白锌胰岛素）（E对）和特慢胰岛素锌混悬液。","","N"],["2004-N119",1,"第一节 慢性支气管炎","慢性支气管炎体征",2004,119,"C","","慢性支气管炎的体征可出现",[["A","水泡音"],["B","哮鸣音"],["C","二者均有"],["D","二者均无"]],"C","慢性支气管炎是指气管、支气管黏膜及周围组织的慢性非特异性炎症。早期多无异常体征。急性发作期可在背部或双肺底听到干、湿啰音（又称水泡音）（A对），咳嗽后减少或消失。如伴发哮喘可闻及广泛哮鸣音（B对）并伴呼气期延长。本题AB均对，正确答案为C。","","N"],["2004-N120",3,"第一节 支气管扩张症","支气管扩张临床表现",2004,120,"C","","干性支气管扩张的体征可出现",[["A","水泡音"],["B","哮鸣音"],["C","二者均有"],["D","二者均无"]],"D","干性支气管扩张的唯一症状就是咯血，平时无慢性咳嗽、大量脓痰，故没有水泡音（A错），也没有哮鸣音（B错）。本题AB均错，正确答案为D。","","N"],["2004-N121",30,"第一节 溃疡性结肠炎","中毒性巨结肠",2004,121,"C","","溃疡性结肠炎较常见的并发症是",[["A","中毒性结肠扩张"],["B","肠梗阻"],["C","二者均是"],["D","二者均非"]],"A","溃疡性结肠炎较常见的并发症是中毒性结肠扩张（A对），肠梗阻（B错）是克罗恩病最常见的并发症，而溃疡性结肠炎出现肠梗阻少见。","","N"],["2004-N122",30,"第二节 克罗恩病","克罗恩病并发症",2004,122,"C","","Crohn病较常见的并发症是",[["A","中毒性结肠扩张"],["B","肠梗阻"],["C","二者均是"],["D","二者均非"]],"B","克罗恩病的病变可累及肠壁全层致肠腔狭窄（十版内科学P392），因此最常见的并发症为肠梗阻（B对）。中毒性结肠扩张（A错）是溃疡性结肠炎常见的并发症，在克罗恩病患者中罕见发生。","","N"],["2004-N123",39,"第一节 总论","肾炎综合征",2004,123,"C","","急性肾炎综合征常表现为",[["A","血尿"],["B","肾功能减退"],["C","二者均是"],["D","二者均非"]],"C","急性肾炎综合征是以突出的血尿（A对）、蛋白尿、少尿、高血压和肾功能减退（B）为主要表现。考虑到本题目出题时间，原参考答案为C，但根据十版教材观点，肾功能不全不是其常见表现，故B选项错误，应选择A。","","N"],["2004-N124",39,"第一节 总论","无症状性血尿和_或蛋白尿",2004,124,"C","","无症状性尿异常常表现为",[["A","血尿"],["B","肾功能减退"],["C","二者均是"],["D","二者均非"]],"A","无症状尿检异常包括无症状性蛋白尿和（或）血尿（A对），是指轻、中度蛋白尿和（或）血尿，不伴有水肿、高血压、氮质血症等肾功能减退（B错）的症状。","","N"],["2004-N141",19,"第二节 扩张型心肌病","扩张型心肌病临床表现",2004,141,"X","","下列哪些临床表现可在扩张型心肌病出现",[["A","猝死"],["B","动脉栓塞"],["C","第四心音奔马律"],["D","心脏破裂"]],"ABC","心肌收缩能力减弱，心腔内血流速度减慢，容易引起附壁血栓的形成，若血栓脱落，可引起远端动脉栓塞（B对）。合并心律失常时，可出现心悸、头晕、黑蒙甚至猝死（A对）。心脏扩大，可闻及第三或第四心音，心率快时呈奔马律（C对）。扩张型心肌病心腔增大、心腔壁变薄，但一般不出现心脏破裂（D错），心脏破裂为急性心肌梗死的并发症之一。","","N"],["2004-N142",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病发病机制",2004,142,"X","","下列哪些因素与肺气肿的发病机制有关",[["A","肺部慢性炎症，损害肺组织和肺泡壁"],["B","支气管慢性炎症，使管腔狭窄，形成不完全阻塞"],["C","肺小动脉受压，血液供应减少，肺组织营养障碍"],["D","慢性炎症破坏肺泡间质，使其失去支架作用，促使肺泡膨胀"]],"AB","肺气肿的发病机制包括：1.肺内各级支气管、终末肺泡和肺血管的慢性炎症：各类炎症细胞活化、聚集破坏支气管壁和肺泡壁，并释放弹性蛋白酶等活性物质，引起慢性黏液高分泌状态，导致管腔狭窄、形成不完全阻塞（AB对）。2.蛋白酶-抗蛋白酶失衡机制：蛋白酶系统亢进，对肺组织进行损伤破坏。3.氧化应激机制：超氧阴离子、次氯酸、H₂O₂等氧化物直接破坏细胞及细胞外基质、促进蛋白酶-抗蛋白酶失衡、促进炎症反应。4.其他：自主神经功能失调、营养不良、气温变化等。肺气肿的发生最终导致：1.肺泡对小气道的正常拉力减小，小气道较易塌陷；2.肺泡弹性回缩力明显降低，肺泡持续膨胀（D错）；3.肺泡周围毛细血管受压退化（C错），通气/血流比值增大，导致生理无效腔气量增大。","","N"],["2004-N143",32,"第二节 肠易激综合征","肠易激综合征药物治疗",2004,143,"X","","治疗肠易激综合征可选用的药物有",[["A","胃肠解痉药"],["B","止泻药"],["C","泻药"],["D","抗抑郁药"]],"ABCD","肠易激综合征是一种功能性肠病，并无器质性病变，其药物治疗主要针对显著的症状进行对症治疗，药物只能解决患者的部分症状。解痉剂（A对）：腹痛多由肠道痉挛收缩所致，应用胃肠解痉药可缓解痉挛解除疼痛，常用药物有抗胆碱药和胃肠道平滑肌选择性钙离子通道阻滞药，如匹维溴铵；止泻药（B对）：对腹泻患者可使用止泻药，洛哌丁胺或地芬诺酯止泻效果好，适用于腹泻症状较重者，但不宜长期使用，轻症者宜使用吸附止泻药如蒙脱石、药用炭等；泻药（C对）：对便秘型患者酌情使用泻药；抗抑郁药（D对）：对腹痛症状重，治疗无效且精神症状明显者可试用抗抑郁药，临床研究表明这类药物甚至对不伴有明显精神症状者亦有一定疗效；肠道微生态制剂：如双歧杆菌、乳酸杆菌、酪酸菌等制剂，可纠正肠道菌失调，对腹泻、腹胀有一定疗效。","","N"],["2004-N144",39,"","",2004,144,"X","","溢出性蛋白尿中的蛋白是指",[["A","球蛋白"],["B","本周蛋白"],["C","血红蛋白"],["D","肌红蛋白"]],"BCD","溢出性蛋白尿是指肾小球滤过及肾小管重吸收均正常，但由于血中异常蛋白质增多，经肾小球滤出，超过肾小管重吸收能力，在尿中出现而产生的蛋白尿，如溶血性贫血时出现的血红蛋白尿（C对），横纹肌溶解时出现的肌红蛋白尿（D对），多发性骨髓瘤患者排出的轻链蛋白如本周蛋白（B对）等。球蛋白（A错）为大分子量蛋白质，当肾小球滤过屏障受损导致血浆蛋白滤出并超过了肾小管的重吸收能力，尿液中可出现球蛋白等大分子量蛋白，属于肾小球性蛋白尿。","","N"],["2004-N145",60,"第一节 库欣综合征","库欣病",2004,145,"X","","Cushing病的发生可由于",[["A","垂体微腺瘤"],["B","垂体大腺瘤"],["C","肾上腺皮质腺瘤"],["D","肾上腺皮质癌"]],"AB","库欣综合征（Cushing综合征）为各种病因造成肾上腺分泌过多糖皮质激素（主要是皮质醇）所致病症的总称，按病因分依赖ACTH和不依赖ACTH的库欣综合征。1.依赖ACTH的库欣综合征包括：①Cushing病（库欣病）：指垂体ACTH分泌过多，伴肾上腺皮质增生，垂体多有微腺瘤（A对），少数为大腺瘤（B对），也有未能发现肿瘤者；②异位ACTH综合征：小细胞肺癌、胸腺癌。２.不依赖ACTH的综合征包括：①肾上腺皮质腺瘤（C错）；②肾上腺皮质癌（D错）；③双侧肾上腺结节性增生。","","N"],["2004-N146",53,"第二节 非霍奇金淋巴瘤","套细胞淋巴瘤",2004,146,"X","","下列选项中，属于B细胞淋巴瘤的有",[["A","从淋巴结发生的边缘带淋巴瘤"],["B","黏膜相关性淋巴组织淋巴瘤"],["C","外套细胞淋巴瘤"],["D","Sezary综合征"]],"ABC","淋巴瘤分为B细胞淋巴瘤和T细胞淋巴瘤。约80%～85%的淋巴瘤是B细胞来源，包括边缘带淋巴瘤（A对）、滤泡性淋巴瘤、外套细胞淋巴瘤（C对）、Burkitt淋巴瘤、黏膜相关性淋巴组织淋巴瘤（B对）等。少数为T细胞来源，包括间变性大细胞淋巴瘤、原发性皮肤间变性大细胞淋巴瘤、蕈样肉芽肿/Sezary综合征（D错）、血管免疫母细胞性T细胞淋巴瘤等。","","N"],["2005-N51",17,"第三节 慢性冠状动脉综合症","稳定型心绞痛临床表现",2005,51,"A","","下列哪项不是稳定型心绞痛患者发作时的典型体征表现",[["A","血压下降"],["B","心率加快"],["C","第二心音逆分裂"],["D","出现第四心音奔马律"],["E","一过性心尖部收缩期杂音"]],"A","稳定型心绞痛也称劳力性心绞痛，是在冠状动脉固定性严重狭窄基础上，由于心肌负荷的增加引起心肌急剧的、暂时性的缺血缺氧临床综合征。发作时交感神经兴奋性增高，出现心率增快（B对）、血压升高（A错，为本题正确答案）、表情焦虑、皮肤冷或出汗，有时出现第四或第三心音奔马律（D对）。可有一过性心尖部收缩期杂音（E对），系因乳头肌缺血，其功能失调引起二尖瓣关闭不全。第二心音逆分裂又称反常分裂，指主动脉瓣关闭迟于肺动脉瓣，吸气时分裂变窄，呼气时变宽。心绞痛时，由于心肌缺血可导致左心收缩力降低，左心室排血时间延长，主动脉瓣关闭延迟，可出现第二心音逆分裂（C对）。","","N"],["2005-N52",17,"第四节 急性冠状综合征","血清心肌坏死标志物",2005,52,"A","","下列哪项是临床确定患者存在急性心肌损害最有价值的指标",[["A","乳酸脱氢酶增高"],["B","肌钙蛋白T增高"],["C","血清肌红蛋白增高"],["D","磷酸肌酸激酶增高"],["E","心电图出现ST段水平下移"]],"B","肌钙蛋白I（cTnI）或T（cTnT）起病3～4小时后升高，cTnI于11～24小时达髙峰，7～10天降至正常，cTnT于24～48小时达高峰，10～14天降至正常。肌钙蛋白测定对诊断心肌损害具有很高的敏感性和特异性，假阳性率低，急性心肌梗死1周左右，肌钙蛋白还未降至正常，因此肌钙蛋白测定是诊断心肌损害最有价值的指标（B对）。乳酸脱氢酶（A错）、肌红蛋白（C错）及磷酸肌酸激酶（D错）在急性心梗时可出现增高，但其特异性较差，因为在部分非心肌损害如肝损伤、骨骼肌受损、肺部疾病、颅脑受损等情况下这些指标也可出现升高。心电图ST段下移仅能反映心肌缺血（E错），不是特异性的变化。","","N"],["2005-N53",21,"第四节 二尖瓣反流","二尖瓣反流病理生理",2005,53,"A","","下列关于左房室瓣关闭不全患者早期病理生理改变的叙述，正确的是",[["A","左心房压力负荷增加"],["B","左心室压力负荷增加"],["C","左心室容量负荷增加"],["D","肺静脉压力负荷增加"],["E","肺静脉容量负荷增加"]],"C","左房室瓣关闭不全患者早期，左心室接受左心房血液及反流血，左心室容量负荷增加（C对），出现代偿性扩张，左心室舒张末期容量增大，因此左心室压力负荷并无明显增高（B错）。慢性二尖瓣关闭不全早期，左心房顺应性增加，左心房扩大，因而左心房压力负荷并无明显增加（A错），故肺血回流顺利，不会出现肺静脉压力负荷升高（D错）及容量负荷升高（E错）。随着病程的延长，持续严重的过度容量负荷终致左心房压和左心室舒张末压明显上升。晚期失代偿时，每搏量和射血分数下降，肺静脉和肺毛细血管楔压增高，继而发生肺淤血、左心衰竭，此时可有肺静脉压力和容量负荷的升高。","","N"],["2005-N54",23,"第一节 感染性心内膜炎","感染性心内膜炎诊断",2005,54,"A","","风湿性心脏瓣膜病患者出现下列哪种征象应首先考虑有感染性心内膜炎的可能",[["A","心律失常"],["B","心力衰竭"],["C","阵发性心前区疼痛"],["D","发热持续一周以上"],["E","尿频、尿急、尿痛"]],"D","风湿性心脏瓣膜病是指风湿性心脏炎遗留下来的以心瓣膜病变为主的心脏病。当心脏炎导致二尖瓣关闭不全或者主动脉关闭不全时，常可导致感染性心内膜炎发生。感染性心内膜炎是指由细菌、真菌和其他微生物直接感染而产生心瓣膜或心室壁内膜的炎症。患者在发病时几乎均有发热，但风湿性心脏瓣膜病非活动期一般无明显发热症状。因此对于风湿性心脏瓣膜病患者，如有不明原因发热达1周以上，应考虑是否合并感染性心内膜炎（D对）。风湿性心脏瓣膜病本身就可以出现心律失常（A错）、心力衰竭（B错）、阵发性心前区疼痛（C错）等症状，因此患者存在上述症状并不能提示合并感染性心内膜炎。尿频、尿急、尿痛为膀胱刺激征主要表现，提示患者存在尿路感染（E错）。","","N"],["2005-N55",16,"第三节 房性心律失常","心房颤动病因",2005,55,"A","","下列关于心房颤动发病原因的叙述，错误的是",[["A","心房颤动的自然发生率随年龄增长而增加"],["B","阵发性心房颤动可见于正常人"],["C","急性酒精中毒时可出现心房颤动"],["D","孤立性心房颤动是指短阵发作的、临床症状不明显的心房颤动"],["E","甲状腺功能亢进症是最常见的出现心房颤动的非心脏性疾病"]],"D","孤立性心房颤动（D错，为本题正确答案）的定义应为发生在无心脏病变的中青年的房颤。我国房颤总患病率为0.77%，一般认为，心房颤动的自然发生率随年龄增长而增加（A对），在50～59岁人群中仅为0.5%，在≥80岁人群中高达7.5%。正常人（B对）在情绪激动、术后、运动或大量饮酒时可发生心房颤动（C对）。非心脏性疾病患者也可发生，其中最常见的为甲状腺功能亢进症（E对）。","","N"],["2005-N56",15,"第二节 慢性心力衰竭","β受体拮抗剂",2005,56,"A","","下列哪项是影响β-受体阻滞剂治疗心力衰竭疗效的主要因素",[["A","年龄"],["B","性别"],["C","血脂水平"],["D","血糖水平"],["E","体重恒定"]],"E","β受体阻滞剂对心功能的影响是双向的，短期表现为对心脏的负性肌力作用，长期应用具有减慢心率，延长左室充盈时间，增加心肌灌注，减少心肌耗氧量等改善内源性心肌功能的“生物学效应”。使用β受体阻滞剂时可引起体液潴留，但是通常没有症状仅表现为体重增加，最后可能导致心力衰竭症状的明显恶化，因此体重恒定（E对）是影响其疗效的主要因素，起始治疗前应确认患者已达到干体重状态，在用药期间应测量体重以及时调整利尿剂的剂量。液体潴留时应用β受体阻滞剂，可使心衰恶化；液体不足时应用β受体阻滞剂可致低血压。年龄（A错）、性别（B错）、血脂水平（C错）等因素对β受体阻滞剂的疗效并无明显影响。过去认为β受体阻滞剂可以掩盖早期的低血糖症状而不用于糖尿病患者的治疗，但近年来临床研究证实，其所带来的效益远大于副作用，因此心衰伴糖尿病患者仍可使用（D错）。","","N"],["2005-N57",15,"第二节 慢性心力衰竭","洋地黄类药物",2005,57,"A","","女性，44岁，因风心病左房室瓣狭窄伴心房颤动，长期服用地高辛每天0.25mg，1周来腹泻，恶心呕吐，进食量少。1天来出现心悸，发作性头晕、黑朦，有短阵意识丧失来院。查体：平卧位，神清，淡漠，双肺（-），心率38次/分，律整，心尖部可闻及舒张期隆隆样杂音，下肢不肿。患者来院就诊的直接病因是",[["A","左房室瓣狭窄"],["B","腹泻"],["C","进食过少"],["D","血容量不足"],["E","洋地黄中毒"]],"E","中年女性患者，风心病左房室瓣狭窄伴心房颤动，长期服用地高辛，出现恶心、呕吐及腹泻（洋地黄中毒的常见胃肠道表现）、房颤率变为规则而缓慢（考虑洋地黄中毒引起的完全性房室传导阻滞）、发作性头晕、黑蒙（考虑缓慢心率导致的脑供血不足），诊断考虑洋地黄中毒（E对）。单纯左房室瓣狭窄（A错）表现为舒张期隆隆样杂音，但不会引起脉搏缓慢。腹泻（B错）与进食过少（C错）亦不引起脉搏缓慢。血容量不足（D错）应表现为脉搏细速。","","N"],["2005-N58",17,"第四节 急性冠状综合征","不稳定型心绞痛和非ST段抬高型心肌梗死诊断",2005,58,"A","","男性，52岁，1周来出现阵发性夜间心前区闷胀，伴出汗，每次持续约10分钟，能自行缓解，白天可正常工作。1小时前在熟睡中再发心前区胀痛，明显压抑感，自服速效救心丸无效，症状持续不缓解而来院。既往体健，无类似发作。入院查心电图呈心前区导联ST段抬高。该患者最可能的诊断是",[["A","劳力性心绞痛"],["B","初发型心绞痛"],["C","恶化型心绞痛"],["D","变异型心绞痛"],["E","梗死后心绞痛"]],"D","52岁男性（中老年男性），熟睡中发作心绞痛，速效救心丸无效，症状持续不缓解（变异型心绞痛为静息心绞痛，硝酸酯类药物一般无效），心电图呈心前区导联ST段抬高（变异型心绞痛可表现为一过性ST段抬高），诊断考虑变异型心绞痛（D对）。劳力性心绞痛（A错）多为活动相关的发作性胸痛，持续时间较短，很少超过半小时，口服硝酸酯类有效。初发型心绞痛（B错）指过去未发生过心绞痛或心梗，而现在发生由心肌缺血缺氧引起的心绞痛，时间尚在1～2个月内。恶化型心绞痛（C错）指原为稳定型心绞痛而在3个月疼痛的频率、程度、时限、诱因经常变动，进行性恶化者，常在原有斑块病变基础上附加有部分血栓形成和（或）动脉痉挛。梗死后心绞痛（E错）是指急性心梗发生1个月内又出现的心绞痛，属于不稳定型心绞痛的范畴，随时有再发心梗的可能。","","N"],["2005-N59",6,"第一节 肺结核","继发性肺结核",2005,59,"A","","下列关于继发性肺结核的叙述，正确的是",[["A","肺部病变好发于上叶尖后段、下叶背段"],["B","治疗后病变吸收快，短期内可有变化"],["C","继发性肺结核不包括慢性纤维空洞性肺结核"],["D","5个单位的PPD试验阴性可以排除继发性肺结核"],["E","多隐匿起病，不会出现急性发热和高热"]],"A","继发型肺结核包括浸润性肺结核、空洞型肺结核、结核球、干酪性肺炎及纤维空洞性肺结核（C错），好发于两肺上叶尖后段、下叶背段和后基底段（A对）。继发性肺结核如一些增生性病变或者干酪样病变治疗后病变吸收较慢，也可长期无改变（B错）。结核杆菌感染后需4～8周才建立充分的变态反应，在此之前结核菌素试验可呈阴性，另外营养不良、HIV感染、麻疹、水痘、癌症、严重的细菌感染包括重症结核病如粟粒性结核病和结核性脑膜炎等，结核菌素试验结果多为阴性和弱阳性，所以5个单位的PPD试验阴性不可以排除继发性肺结核（D错）。肺结核常表现为午后低热、盗汗、消瘦等全身结核中毒症状，若肺部病灶扩散、干酪性肺炎或血行播散型肺结核患者，常出现急性发热和高热（E错）。","","N"],["2005-N60",2,"第一节 支气管哮喘","β₂受体激动剂",2005,60,"A","","β₂-受体兴奋剂在应用两周后，常引起β₂-受体下调，使支气管舒张作用减弱。下列哪种药物可促进β₂-受体功能的恢复",[["A","氨茶碱"],["B","酮替酚"],["C","溴化己胺醇"],["D","白三烯受体拮抗剂"],["E","异丙托品"]],"B","目前，研究已证实酮替芬可逆转长期应用β₂-受体兴奋剂引起的β₂-受体下调，增加气道内β₂-受体的密度，增强β₂-受体兴奋剂的疗效（B对）。氨茶碱（A错）等茶碱类药物可以通过抑制磷酸二酯酶来舒张支气管；溴化己胺醇（C错）为β₂-受体激动剂；白三烯受体拮抗剂（D错）通过对气道平滑肌和其他细胞表面白三烯受体的拮抗，抑制肥大细胞和嗜酸性粒细胞的致喘和致炎作用，并可产生轻度支气管舒张；异丙托品（E错）等抗胆碱类药物，可抑制乙酰胆碱，舒张支气管平滑肌；但均无促进β₂-受体功能恢复的作用。","","N"],["2005-N61",2,"第一节 支气管哮喘","中度",2005,61,"A","","中度持续发作的支气管哮喘患者应用糖皮质激素的原则是",[["A","长期口服5～10mg强的松"],["B","长期吸入二丙酸倍氯米松＜400μg/d"],["C","长期吸入二丙酸倍氯米松200～1000μg/d"],["D","间断吸入激素加长期应用支气管扩张剂"],["E","一次性大剂量激素冲击治疗"]],"C","糖皮质激素，是目前控制哮喘最有效的药物。激素通过作用于气道炎症形成过程中的诸多环节，有效抑制气道炎症，可以分为吸入、口服和静脉用药。吸入型糖皮质激素局部作用强而全身副作用较小，所以目前临床上已将其作为长期治疗哮喘的首选方案，常用的药物有倍氯米松（BDP）、布地奈德、氟替卡松、环索奈德、莫米松等。根据哮喘病情，吸入剂量（BDP或等效量其他皮质激素）在轻度持续者一般200～500μg/d，中度持续者一般500～1000μg/d（C对B错），重度持续者一般＞1000μg/d（不宜超过2000μg/d）。长期口服强的松（A错）会有明显的副作用，多用于吸入激素无效或需要短期加强治疗的患者，而不提倡长期口服。吸入性糖皮质激素，通常需规律吸入1～2周以上方能起效，而非间断吸入，另外长期使用支气管扩张剂，容易造成支气管平滑肌对其敏感性下降，治疗效果降低，所以临床上多不采取长期应用支气管扩张剂的治疗方案（D错），支气管扩张剂多用于治疗哮喘的急性发作。一次性大剂量激素冲击治疗（E错）多用于治疗免疫性疾病，而支气管哮喘患者应用激素治疗时，多采用小剂量。慢性持续性哮喘根据病情严重程度可分为间歇性、轻度持续、中度持续和重度持续4级，但该分级方法目前已经较少采用，现采用哮喘控制水平评估。","","N"],["2005-N62",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病病理生理",2005,62,"A","","COPD病理生理改变的标志是",[["A","气体交换异常"],["B","黏液高分泌"],["C","肺动脉高压"],["D","肺过度充气"],["E","呼气气流受限"]],"E","慢阻肺的特征性的病理生理变化是持续气流受限致肺通气功能障碍（E对）。随着病情发展，肺组织弹性日益减退，肺泡持续扩大，回缩障碍，则残气量及残气量占肺总量的百分比增加，此时肺过度充气产生肺气肿（十版内科学P26）（D错）；肺气肿加重导致肺泡周围毛细血管受挤压大量减少，肺泡壁血液灌流减少，导致无效腔样气量增大，产生通气血流比例失调，与弥散障碍共同作用，导致换气功能发生障碍（十版内科学P26）（A错）；发展到最后会引起缺氧和二氧化碳潴留，缺氧、高碳酸血症、呼吸性酸中毒等可引起肺血管收缩、痉挛，肺气肿压迫肺泡毛细血管，使毛细血管床大量减少，最终肺循环阻力增加，肺动脉压力增高（十版内科学P122）（C错），此为慢性肺心病的特征；黏液高分泌是指炎症导致支气管上皮细胞变性、坏死、脱落，支气管管壁多种炎性细胞浸润，杯状细胞和黏液腺肥大增生、分泌旺盛，大量黏液潴留在气道，是一种常见的病理变化，不是COPD的病理生理改变的标志（B错）。","","N"],["2005-N63",4,"第二节细菌性肺炎","肺炎链球菌肺炎发病机制",2005,63,"A","","下列哪种细菌性肺炎一般不出现肺脓肿改变",[["A","流感嗜血杆菌"],["B","军团菌"],["C","肺炎克雷伯杆菌"],["D","肺炎链球菌"],["E","大肠杆菌"]],"D","肺炎链球菌不产生毒素，不引起组织坏死或形成空洞，其致病力是由于荚膜对组织的侵袭作用（D对）。而流感嗜血杆菌（A错）、军团菌（B错）、肺炎克雷伯杆菌（C错）、大肠杆菌（E错）均可以引起肺组织化脓性炎症、坏死，形成肺脓肿。","","N"],["2005-N64",4,"第二节细菌性肺炎","肺炎链球菌肺炎发病机制",2005,64,"A","","下列关于肺炎链球菌特点的叙述，正确的是",[["A","感染后可获得特异性免疫，同型菌的二次感染少见"],["B","感染后仅有非特异性免疫，在机体抵抗力下降时可以再发同型感染"],["C","不属于上呼吸道的正常菌群"],["D","与草绿色链球菌鉴别的重要特征是胆汁溶菌试验阴性"],["E","经上呼吸道进入肺泡后，可产生毒素，引起组织坏死"]],"A","肺炎链球菌是寄居在口腔及鼻咽部的一种正常菌群（C错）。机体免疫功能受损时，有毒力的肺炎链球菌入侵人体而致病。肺炎链球菌不产生毒素，不引起组织坏死或形成空洞（E错），其致病力是由于高分子多糖体的荚膜对组织的侵袭作用。肺炎链球菌感染后，根据其荚膜多糖的抗原特性，可诱发机体产生免疫应答，机体可建立较牢固的特异性免疫，由于免疫记忆使同型菌的二次感染少见（A对B错）。肺炎链球菌与草绿色链球菌鉴别常用的方法是胆汁溶菌试验，肺炎链球菌对胆盐敏感，胆汁溶菌试验常阳性，而草绿色链球菌对胆盐不敏感，胆汁溶菌试验常为阴性（D错）。","","N"],["2005-N65",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎克雷伯杆菌肺炎治疗",2005,65,"A","","患者，52岁，急性起病，寒战、高热，全身衰弱，痰稠呈砖红色胶冻状，胸部X线检查结果为右侧肺可见实变阴影及蜂窝状脓肿，叶间隙下坠。下列哪项诊断和治疗最适合",[["A","金黄色葡萄球菌肺炎，选用万古霉素治疗"],["B","军团菌肺炎，选用红霉素治疗"],["C","支原体肺炎，选用红霉素治疗"],["D","肺炎克雷伯杆菌肺炎，选用半合成广谱青霉素加氨基糖苷类"],["E","厌氧菌肺炎，选用青霉素G治疗"]],"D","患者寒战、高热、全身衰竭，痰液特点为砖红色胶冻状，X线胸片右肺呈多发性蜂窝状阴影，应怀疑克雷伯杆菌肺炎，选用半合成广谱青霉素加氨基糖苷类（D对）的治疗方案。金黄色葡萄球菌肺炎（A错）主要表现为急性寒战、高热、脓痰，痰中常有血丝，X线影像为单个或多发的液气囊腔及阴影的易变性；军团菌肺炎（B错）患者常有疲乏、无力、肌痛、畏寒、发热等全身性表现，咳嗽咳痰，咳黏痰带少量血丝或血痰，量少，不呈脓性，X线为下叶斑片浸润影；支原体肺炎（C错）多表现为干咳，痰液少见，X线为下叶间质性支气管炎；厌氧菌肺炎（E错）典型表现为突然畏寒高热，体温达39℃以上，伴咳嗽、咳黏液或黏液脓恶臭痰，X线为支气管肺炎、脓胸、脓气胸、多发性肺脓肿。","","N"],["2005-N66",11,"第二节 气胸","气胸诊断",2005,66,"A","","男性，40岁，慢性咳嗽咳痰史10年，突发左侧胸痛1天，呈针刺样疼痛，向左肩部放射，伴有胸闷及气短，干咳，无发热。吸烟约10年，1包/天。查体：消瘦，神志清楚，气管居中，无颈静脉怒张，左下肺叩诊鼓音，左下肺呼吸音明显降低，右肺散在少量干啰音，心界叩诊不清，心率92次/分，律齐，无病理性杂音，双下肢不肿。最可能的疾病是",[["A","左侧气胸"],["B","肺栓塞"],["C","急性心肌梗死"],["D","COPD"],["E","肺大疱"]],"A","患者男性，40岁，长期吸烟史，慢性咳嗽咳痰史，考虑有COPD（D错）基础疾病（继发性气胸常见于有基础肺部病变者），在此基础上，突发左侧胸痛1天，呈针刺样疼痛，向左肩部放射，伴有胸闷及气短，干咳（气胸常见的临床症状），无发热。左下肺叩诊鼓音，左下肺呼吸音明显降低，右肺散在少量干啰音，心界叩诊不清（气胸的临床体征），最可能的疾病为左侧气胸（A对）。肺栓塞（十版内科学P112）（B错）常有房颤、长期卧床、下肢血栓形成等病史，表现为突发胸痛、呼吸困难、咯血、晕厥、心动过速、颈静脉充盈或搏动，肺动脉瓣区第二心音亢进或分裂，三尖瓣区收缩期杂音；急性心肌梗死（十版内科学P248）（C错）常表现为心前区疼痛，有濒死感，可出现发热、心动过速、恶心呕吐，大汗淋漓，服用硝酸甘油不能缓解等症状；肺大疱（E错）一般没有症状和阳性体征。","","N"],["2005-N67",26,"第一节 胃食管反流病","PPI",2005,67,"A","","下列用于胃食管反流病维持治疗的药物中，效果最好的是",[["A","西沙必利"],["B","吗丁啉"],["C","氢氧化铝"],["D","西咪替丁"],["E","奥美拉唑"]],"E","治疗胃食管反流病的药物主要有促胃肠动力药、抑酸药和抗酸药（十版内科学P364-P365）。抑酸药奥美拉唑和西咪替丁均可用于胃食管反流病的维持治疗，但奥美拉唑效果更佳（E对D错）。促胃肠动力药西沙必利（A错）和吗丁啉（B错）疗效有限且不确定，只适用于轻症患者，或作为与抑酸药合用的辅助治疗，不用于维持治疗。抗酸药氢氧化铝（C错）是胃酸中和剂，临床上现已少用。","","N"],["2005-N68",27,"第二节 慢性胃炎","Hp感染",2005,68,"A","","在慢性胃炎的发病机制中，与幽门螺杆菌感染无关的因素是",[["A","产生胃壁细胞抗体"],["B","分泌空泡毒素A"],["C","释放尿素酶分解尿素产生NH₃"],["D","产生细胞毒素相关基因蛋白"],["E","菌体胞壁作为抗原诱导免疫反应"]],"A","慢性胃炎分自身免疫性胃炎（A型胃炎、慢性胃体炎）和多灶萎缩性胃炎（B型胃炎、慢性胃窦炎），A型胃炎多由自身免疫反应引起，患者血清中存在自身抗体，如壁细胞抗体、内因子抗体。B型胃炎绝大多数与幽门螺杆菌感染有关，幽门螺杆菌可通过释放尿素酶分解尿素产生NH₃（C对），分泌空泡毒素A（B对）等物质引起细胞损害；其细胞毒素相关基因（cagA）蛋白（D对）能引起强烈的炎症反应；其菌体细胞壁还可以作为抗原诱导免疫反应（E对）。而产生胃壁细胞抗体（A错，为本题正确答案）为A型胃炎的发病机制，与由幽门螺杆菌感染引起的B型胃炎无关。","","N"],["2005-N69",29,"第二节 结核性腹膜炎","全身症状",2005,69,"A","","下列关于结核性腹膜炎全身症状的叙述，错误的是",[["A","主要症状是发热和盗汗"],["B","热型以低热和中等热最多"],["C","约1/3患者呈弛张热"],["D","少数可呈稽留热"],["E","毒血症状明显者见于粘连型"]],"E","结核性腹膜炎是由结核分枝杆菌引起的慢性弥漫性腹膜感染，根据本病的病理特点分为渗出型、粘连型和干酪型，全身症状以结核毒血症常见，主要是发热与盗汗（十版内科学P385）（A对）。发热主要特点是低热与中等热（B对），约1/3患者呈弛张热（C对），少数病人呈稽留热（D对）。高热伴有明显毒血症主要见于渗出型、干酪型，或见于伴有粟粒型肺结核、干酪样肺炎等严重结核病的患者，粘连型腹膜炎病变相对较轻，全身症状不明显（E错，为本题正确答案）。","","N"],["2005-N70",30,"第一节 溃疡性结肠炎","临床类型",2005,70,"A","","溃疡性结肠炎最多见的临床类型是",[["A","初发型"],["B","慢性复发型"],["C","慢性持续型"],["D","急性暴发型"],["E","临床终末型"]],"B","溃疡性结肠炎的临床类型分为：①初发型，指无既往史的首次发作；②慢性复发型，临床上最多见（B对），指缓解后再次出现症状，常表现为发作期与缓解期交替。","","N"],["2005-N71",32,"第二节 肠易激综合征","肠易激综合征临床表现",2005,71,"A","","下列不支持肠易激综合征诊断的临床表现是",[["A","每天排便多于3次"],["B","每周排便少于3次"],["C","块状/硬粪便"],["D","稀水样便"],["E","粪便排出顺利，无不尽感"]],"E","肠易激综合征是一种功能性胃肠病，无实质性胃肠道病变，主要表现为腹痛或腹部不适伴排便习惯改变。诊断常采用罗马Ⅲ诊断标准，以下症状不是诊断所必备，但属常见症状，这些症状越多越支持IBS的诊断：①排便频率异常（每天排便＞3次或每周＜3次）（AB对）；②粪便性状异常（块状/硬便或稀水样便）（CD对）；③粪便排出过程异常（费力、急迫感、排便不尽感）（E错，为本题正确答案）；④黏液便；⑤胃肠胀气或腹部膨胀感（十版内科学P400）。","","N"],["2005-N72",29,"第一节 肠结核","肠结核诊断",2005,72,"A","","男性，25岁，右下腹痛3月余，还常伴有上腹或脐周腹痛，排便次数稍多，呈糊状，不含黏液和脓血，每日约2～4次，曾作过X线钡剂检查发现回盲部有跳跃征。最可能的诊断是",[["A","克罗恩病"],["B","溃疡型肠结核"],["C","右侧结肠癌"],["D","阿米巴病"],["E","肠恶性淋巴瘤"]],"B","青年男性患者，右下腹痛为主，伴脐周痛，大便习惯改变，呈糊状，无黏液脓血，且X线钡剂检查发现回盲部有跳跃征，以上均支持溃疡性肠结核的诊断（B对）。克罗恩病（十版内科学P392）（A错）病变呈节段性或跳跃式分布，钡剂造影见纵行性溃疡或裂沟以及鹅卵石征。右侧结肠癌（十版内科学P396）（C错）发病年龄比肠结核晚，一般无结核毒血症表现。结肠镜检查及粘膜活检可明确诊断。阿米巴病（十版内科学P390）（D错）有既往感染病史，粪便常规或孵化检查可发现有关病原体。肠恶性淋巴瘤（E错）以回肠部位为多，临床表现有腹痛、腹泻和腹部包块，结肠镜检查及粘膜活检可确诊。","","N"],["2005-N73",36,"第一节 原发性肝癌","原发性肝癌诊断",2005,73,"A","","男性，40岁，健康体检时化验血甲胎蛋白＞500μg/L，血ALT35U/L，查体未见异常。初步诊断最可能是",[["A","肝硬化代偿期"],["B","肝硬化失代偿期"],["C","慢性迁延性肝炎"],["D","慢性活动性肝炎"],["E","亚临床肝癌"]],"E","亚临床肝癌是指能检出AFP，但无任何症状和体征的肝癌，往往在体检或普查中被发现，患者仅表现为甲胎蛋白（AFP）升高和影像学上的肿块。该患者甲胎蛋白值明显升高，ALT（谷丙转氨酶）浓度正常（正常值为0～40U/L），首先应考虑原发性肝癌，但查体未见异常，符合亚临床肝癌的诊断标准（E对）。肝硬化（AB错）和肝炎（CD错）虽有AFP升高，但是多为低浓度（多在25～200μg/L），并且这些患者常有肝功能异常（ALT升高）。","","N"],["2005-N74",40,"第三节 急进性肾小球肾炎","急进性肾小球肾炎鉴别诊断",2005,74,"A","","下列不形成新月体的肾小球肾炎是",[["A","急进性肾小球肾炎"],["B","重症毛细血管内增生性肾小球肾炎"],["C","狼疮肾炎"],["D","肺出血-肾炎综合征"],["E","过敏性紫癜肾炎"]],"B","新月体主要由增生的壁层上皮细胞和渗出的单核细胞构成，新月体细胞成分间有较多纤维素，病理检查发现新月体对于鉴别肾小球肾炎亚类非常重要。急进性肾小球肾炎（A对）是典型的新月体性肾小球肾炎，此外，系统性红斑狼疮肾炎（C对）、肺出血-肾炎综合征（D对）、过敏性紫癜肾炎（E对）等均可引起继发性新月体性肾小球肾炎（P468）。重症毛细血管内增生性肾小球肾炎（B错，为本题正确答案）临床表现与新月体肾炎相似，但并没有新月体形成，其基本病理改变为弥漫性肾小球病变，以内皮细胞及系膜细胞增生为主，急性期可伴有中性粒细胞及单核细胞浸润。","","N"],["2005-N75",41,"第一节 尿路感染","无症状细菌尿",2005,75,"A","","下列无症状细菌尿患者中，不需要治疗的是",[["A","老年人"],["B","学龄前儿童"],["C","妊娠妇女"],["D","肾移植者"],["E","有尿路梗阻者"]],"A","无症状性菌尿又称隐匿型菌尿，是一种隐匿型尿路感染，即指病人有真性细菌尿而无任何尿路感染的症状，见于老年女性、女童及妊娠妇女。无症状性菌尿对于老年人不是急症，不影响寿命，可不予治疗（A对）。一般认为有下述情况者应予治疗：学龄前儿童（B错）、妊娠期无症状性菌尿（C错）、曾出现有症状感染者、肾移植（D错）、尿路梗阻（E错）及其他尿路有复杂情况者。","","N"],["2005-N76",45,"第一节 慢性肾衰竭","慢性肾衰竭定义和分期",2005,76,"A","","男性，55岁，患慢性肾炎10余年，经中西医结合治疗病情稳定，但近1年来逐渐加重，食欲下降，贫血，化验血肌酐已进入肾衰竭期，这时血肌酐的水平是",[["A","＜178μmol/L"],["B","178～278mμmol/L"],["C","278～450μmol/L"],["D","450～707μmol/L"],["E","＞707μmol/L"]],"D","十版内科学未明确说明肾衰竭期血肌酐水平，七版内科学明确了肾衰竭期的诊断标准：肾功能代偿期（血肌酐水平133～177μmol/L）；肾功能失代偿期（血肌酐水平186～442μmol/L）；肾衰竭期（血肌酐水平451～707μmol/L）（D对）；尿毒症期（血肌酐水平≥707μmol/L）。","","N"],["2005-N77",47,"第一节 缺铁性贫血","骨髓象",2005,77,"A","","下列疾病中，骨髓有核红细胞出现“核老浆幼”现象的是",[["A","巨幼细胞贫血"],["B","急性红血病"],["C","骨髓增生异常综合征"],["D","缺铁性贫血"],["E","再生障碍性贫血"]],"D","“核老浆幼”是指红细胞核浆发育不同步，胞浆发育滞后于胞核的现象，通常见于缺铁性贫血（D对）。缺铁性贫血（十版内科学P549）时，由于原料铁的缺乏导致血红蛋白合成障碍，而红细胞胞浆主要由血红蛋白组成，所以其胞浆发育滞后，表现为“核老浆幼”。巨幼细胞贫血（十版内科学P552）（A错）是由于叶酸或维生素B₁₂缺乏，使DNA合成障碍，而RNA合成所受影响不大，细胞内RNA/DNA比值增大，造成细胞体积增大，胞核发育滞后于胞质，形成巨幼变及“核幼浆老”的现象。急性红血病（B错）是一种骨髓内有核红细胞异常增生的恶性疾病，无“核老浆幼”现象。骨髓增生异常综合征（十版内科学P572）（C错）是一组起源于造血干细胞的克隆性疾病，骨髓象多见幼稚的有核红细胞，胞核和胞浆的发育并没有先后关系，不会出现“核老浆幼”现象。再生障碍性贫血（十版内科学P555）（E错）是一种骨髓造血功能衰竭症，主要表现为细胞数量减少而发育正常，不会出现“核老浆幼”现象。","","N"],["2005-N78",49,"第一节 再生障碍性贫血","急性造血功能停滞",2005,78,"A","","下列选项中，不符合急性造血停滞特点的是",[["A","均发生于无血液病的患者"],["B","突然全血细胞减少"],["C","网织红细胞可降至零"],["D","骨髓中可见巨大原红细胞"],["E","病程常呈自限性"]],"A","急性造血功能停滞常在溶血性贫血或感染发热的患者中发生（A错，为本题正确答案），全血细胞尤其是红细胞骤然下降（B对），网织红细胞可降至零（C对），骨髓三系减少，与SAA（重型再生障碍性贫血）相似。但骨髓涂片尾部可见巨大原始红细胞（D对），病程呈自限性（E对），约1月后可自行恢复。","","N"],["2005-N79",53,"第二节 非霍奇金淋巴瘤","弥漫大B细胞淋巴瘤",2005,79,"A","","应用染色体易位检测技术辅助NHL分型，下列选项中，错误的是",[["A","检出t（14；18）提示是滤泡性淋巴瘤"],["B","检出t（8；14）提示是Burkitt淋巴瘤"],["C","检出t（11；14）提示是套细胞淋巴瘤"],["D","检出t（2；5）提示是间变大细胞淋巴瘤"],["E","检出t（11；4）提示是弥漫性大B细胞淋巴瘤"]],"E","弥漫性大B细胞淋巴瘤是非霍奇金淋巴瘤中最常见的一种类型。弥漫性大B细胞淋巴瘤染色体异位特征为t（3；14）、t（14；18）（E错，为本题正确答案）。滤泡性淋巴瘤的染色体异位特征是t（14；18）（A对）。Burkitt淋巴瘤的染色体异位特征是t（8；14）（B对）、t（8；22）和t（2；8）。套细胞淋巴瘤的染色体异位特征是t（11；14）（C对）。间变大细胞淋巴瘤的染色体异位特征是t（2；5）（D对）。","","N"],["2005-N80",52,"第二节 急性白血病","CNSL防治和睾丸白血病治疗",2005,80,"A","","男性，17岁，患ALL，经化疗后已完全缓解3个月，但最近发现右侧睾丸无痛性肿大，骨髓检查正常，诊断为睾丸白血病。针对该病的治疗措施是",[["A","右侧睾丸放射治疗"],["B","右侧睾丸手术切除"],["C","双侧睾丸放射治疗"],["D","双侧睾丸手术切除"],["E","化学治疗"]],"C","该ALL（急性淋巴细胞白血病）患者经化疗后获得完全缓解，在缓解期又发现了髓外（单侧睾丸）白血病细胞浸润，无骨髓复发。对于睾丸白血病患者，虽然单侧睾丸出现无痛性肿大，但是对侧往往也有一定程度的浸润，所以要进行双侧照射（C对），只做单侧放疗患者易复发（A错）。睾丸白血病患者一般不考虑睾丸手术切除（BD错）。人体存在血-睾屏障，阻止了化疗药物进入睾丸，使睾丸内化疗药浓度降低；又因睾丸温度相对较低，早期白血病细胞可能存在于睾丸内并处于“休眠状态”，对全身化疗药物不敏感（E错）。一般采用双侧睾丸局部照射辅以放疗后全身化疗的方案。","","N"],["2005-N81",60,"第五节 嗜铬细胞瘤","消化系统",2005,81,"A","","下列选项中，不符合嗜铬细胞瘤消化系统表现的是",[["A","可引起腹泻"],["B","胆石症发生率高"],["C","可引起胆汁潴留"],["D","可引起肠出血"],["E","可引起肠扩张"]],"A","嗜铬细胞瘤分泌大量儿茶酚胺，消化系统有以下表现：1.胆石症发生率较高（B错）：与儿茶酚胺使胆囊收缩减弱，Oddi括约肌张力增强，引起胆汁潴留（C错）有关；2.肠坏死、出血（D错）、穿孔：儿茶酚胺可使胃肠壁内血管发生增殖性及闭塞性动脉炎，造成肠坏死、出血、穿孔。3.肠扩张（E错）：儿茶酚胺使肠蠕动及张力减弱，可引起便秘，甚至肠扩张。嗜铬细胞瘤可分泌多种肽类激素，其中，胃动素、血管活性肠肽和血清素可引起腹泻（十版内科学P721）（A错），阿片肽，生长抑素可引起便秘。根据十版内科学观点，本题无正确答案，但参考答案为A。","","N"],["2005-N82",59,"第一节 甲状腺功能亢进症","Graves眼病",2005,82,"A","","下列选项中，符合Graves病眼征分级标准4级的是",[["A","有症状和体征，软组织受累"],["B","突眼（＞18mm）"],["C","眼外肌受累"],["D","角膜受累"],["E","有视力丧失"]],"C","美国甲状腺病学会将突眼分为由0级至6级的7个级别。考虑到浸润性与单纯性眼突的动态变化和重叠交叉特点，不再分为两类。从0～6可简单记忆为NOSPECS。0级：无症状或体征；1级：仅有体征，无症状。体征仅有上睑挛缩、凝视、突眼度在22mm以内（正常眼突度男18.6mm，女16mm）（B错）；2级：软组织受累，有症状和体征（A错）；3级：突眼度大于22mm（正常眼突度男18.6mm，女16mm）；4级：眼外肌受累（C对）；5级：角膜受累（D错）；6级：视力下降，视神经受累（E错）。0～1级代表无眼病或眼病轻微；2～6级说明病变较重，达4级及以上者可以诊断为TAO（甲状腺相关性眼病）（二版廖二元主编内分泌学P569）。","","N"],["2005-N83",68,"第一节 类风湿关节炎","遗传易感性",2005,83,"A","","下列哪个基因被认为与类风湿关节炎的发病和发展无关",[["A","HLA-DR4"],["B","HLA-B27"],["C","TNF基因"],["D","性别基因"],["E","球蛋白基因"]],"B","HLA-DR4被认为是类风湿关节炎的易感基因（A对）。此外，其发病和发展与TNF-α、IL、球蛋白基因的表达等有关（CE对），发病有性别上的显著差异表明与性别基因有关（D对）。HLA-B27与强直性脊柱炎的发病有关（约90%以上患者阳性）（十版内科学P832）（B错，为本题正确答案）。","","N"],["2005-N84",69,"第一节 系统性红斑狼疮","糖皮质激素",2005,84,"A","","在SLE应用激素冲击疗法中，下列哪项一般不是适应证",[["A","急性肾衰竭"],["B","NP狼疮的癫痫发作"],["C","NP狼疮的明显精神症状"],["D","严重溶血性贫血"],["E","严重血小板减少性紫癜"]],"E","急性狼疮危象指SLE 导致的危及生命的急性或亚急性脏器功能障碍，如急进性狼疮肾炎、严重的中枢神经系统损害、严重的溶血性贫血、血小板减少性紫癜、粒细胞缺乏症、严重心脏损害、严重狼疮性肺炎、弥漫性肺泡出血、严重狼疮性肝炎和严重的血管炎。故根据九版内科学观点，ABCDE均为使用激素冲击治疗的指征，本题原答案选择E。","","N"],["2005-N119",16,"第一节 心律失常概述","持续心电监测",2005,119,"B","","患者发作性心悸伴头晕，为明确诊断，应选用的检查措施是",[["A","心电图运动试验"],["B","核素心肌灌注显像"],["C","动态心电图监测"],["D","血培养"],["E","心肌酶谱"]],"C","患者发作性心悸伴头晕，考虑阵发性心律失常，常规心电图只有在发作时方可能有阳性发现。动态心电图监测（C对）可连续监测心电活动，提高阳性率，便于了解心悸与晕厥等症状的发生是否与心律失常有关、明确心律失常或心肌缺血发作与日常生活的关系以及昼夜分布特征等，是常用的检查手段之一。心电图运动试验（A错）又称心电图运动负荷试验，是通过一定量的运动增加心脏负荷，观察心电图变化，对已知或怀疑患有心血管疾病尤其是冠状动脉粥样硬化性心脏病（冠心病）进行临床评估的方法，患者未出现典型的劳力性心绞痛症状，仅有“发作性心悸及头晕”，该项检查意义不大。放射性核素心肌灌注显像（B错）为明确心肌梗死后心肌存活状况的检查。血培养（D错）主要用于诊断感染性心内膜炎。心肌酶谱（E错）主要用于心肌梗死的定性诊断。","","N"],["2005-N120",17,"第四节 急性冠状综合征","放射性核素检查",2005,120,"B","","心肌梗死后，为明确存活心肌状况，应选用的检查措施是",[["A","心电图运动试验"],["B","核素心肌灌注显像"],["C","动态心电图监测"],["D","血培养"],["E","心肌酶谱"]],"B","心肌梗死后，为明确心肌存活状况，目前较为敏感的检查方法是放射性核素心肌灌注显像（B对）。心电图运动试验（A错）又称心电图运动负荷试验，是通过一定量的运动增加心脏负荷，观察心电图变化，对已知或怀疑患有心血管疾病尤其是冠状动脉粥样硬化性心脏病（冠心病）进行临床评估的方法。24小时动态心电图（C错）可连续监测心电活动，便于了解心悸与晕厥等症状的发生是否与心律失常有关的诊断方法。血培养（D错）主要用于感染性心内膜炎的诊断。心肌酶谱（E错）主要用于心肌梗死的定性诊断，并不能明确梗死部位及心肌存活情况。","","N"],["2005-N121",75,"第一节 中毒概述","血液净化",2005,121,"B","","血液透析治疗急性中毒的首选治疗指征是",[["A","生物毒类中毒"],["B","乙二醇中毒"],["C","氯酸盐中毒"],["D","导眠能中毒"],["E","短效巴比妥类中毒"]],"C","透析疗法多用于清除分子量较小或非脂溶性物质，氯酸盐（C对）或重铬酸盐为水溶性毒物，可引起急性肾衰竭，应首选血液透析治疗快速清除。乙二醇（B错）虽可用血液透析疗法治疗，但非血液透析治疗的最佳适应证。导眠能（D错）、短效巴比妥类（E错）药物为脂溶性，一般不进行血液透析，可用血液灌流清除。生物毒类中毒（A错）采用血浆置换效果更好。","","N"],["2005-N122",75,"第一节 中毒概述","血液净化",2005,122,"B","","最适于血浆置换治疗的中毒是",[["A","生物毒类中毒"],["B","乙二醇中毒"],["C","氯酸盐中毒"],["D","导眠能中毒"],["E","短效巴比妥类中毒"]],"A","生物毒（如蛇毒、蕈中毒）（A对）及砷化氢等溶血毒物中毒最适于血浆置换治疗。乙二醇（B错）及氯酸盐（C错）为非脂溶性毒物，应用血液透析治疗。导眠能（D错）、短效巴比妥类（E错）为脂溶性，应用血液灌流清除。","","N"],["2005-N123",61,"第一节 糖尿病","某些特殊类型糖尿病的临床特点",2005,123,"B","","MODY的发病是由于",[["A","B细胞胰岛素分泌不足"],["B","以胰岛素抵抗为主伴胰岛素分泌不足"],["C","常染色体显性遗传"],["D","胰岛素作用遗传性缺陷"],["E","线粒体基因突变"]],"C","MODY（青年人中的成年发病型糖尿病）是一组高度异质性的单基因遗传病，为常染色体显性遗传病（C对）。胰岛素抵抗为主伴胰岛素分泌不足（B错）见于2型糖尿病。线粒体基因突变（E错）见于线粒体基因突变糖尿病，属于特殊类型糖尿病。胰岛素作用遗传性缺陷（十版内科学P725）（D错）见于A型胰岛素抵抗、妖精貌综合征、脂肪萎缩型糖尿病等。","","N"],["2005-N124",61,"第一节 糖尿病","T2DM病因、发病机制和自然史",2005,124,"B","","2型糖尿病的发病是由于",[["A","B细胞胰岛素分泌不足"],["B","以胰岛素抵抗为主伴胰岛素分泌不足"],["C","常染色体显性遗传"],["D","胰岛素作用遗传性缺陷"],["E","线粒体基因突变"]],"B","2型糖尿病（T2DM）是因胰岛素抵抗为主伴胰岛素分泌不足引起（B对）：胰岛素抵抗是T2DM的特性，β细胞（亦称为B细胞）功能缺陷导致的胰岛素分泌不足在T2DM发病中起关键作用。MODY是一组高度异质性的单基因遗传病，是由于β细胞功能遗传性缺陷引起，为常染色体显性遗传病（C错）。线粒体基因突变（E错）见于线粒体基因突变糖尿病，属于特殊类型糖尿病。胰岛素作用遗传性缺陷（十版内科学P725）（D错）见于A型胰岛素抵抗、妖精貌综合征、脂肪萎缩型糖尿病等。","","N"],["2005-N141",18,"第一节 原发性高血压","利尿剂",2005,141,"X","","高血压患者长期应用噻嗪类药物可引起下列哪些临床表现",[["A","血胆固醇增加"],["B","血糖增高"],["C","血尿酸降低"],["D","血钾下降"]],"ABD","长期使用噻嗪类利尿剂可升高血浆胆固醇（A对）和甘油三酯水平，故血脂异常者需慎用。因其可能会抑制胰岛素释放并抑制外周组织对于葡萄糖的利用，导致糖耐量降低，血糖升高（B对），常发生于用药后2～3个月，停药后可缓解。其还可影响血尿酸代谢，导致高尿酸血症，甚至痛风（C错）。噻嗪类利尿剂作用于远曲小管近端的Na⁺-Cl⁻共转运子，抑制NaCl的重吸收，远曲小管中的Na⁺浓度增加，促进Na⁺-K⁺交换，K⁺排出增多，因此长期应用该药可导致血钾降低（D对）。","","N"],["2005-N142",10,"第三节 慢性肺源性心脏病","正性肌力药",2005,142,"X","","慢性肺源性心脏病洋地黄应用的指征是",[["A","合并急性左心功能衰竭"],["B","感染已控制，利尿剂治疗右心功能未能改善"],["C","合并室上性心动过速"],["D","心房颤动（心室率80～100次/分）"]],"ABC","洋地黄为正性肌力药，也可减慢房室传导、降低窦房结自律性、引起窦性心动过缓。慢性肺心病患者由于慢性感染和缺氧对洋地黄类的耐受性低，疗效差，易致中毒，出现心律失常。因此，是否应用应持慎重态度，应用指征有：①合并急性左心衰竭的患者（A对）；②感染已控制，呼吸功能已改善，利尿治疗后右心功能无改善者（B对）；③合并室上性快速心律失常，如室上性心动过速（C对）、心室率˃100次/分的心房颤动患者，而心室率80～100次/分的心房颤动（D错）患者不应使用洋地黄；④以右心衰竭为主要表现而无明显感染的患者。","","N"],["2005-N143",28,"第一节 消化性溃疡","胃癌",2005,143,"X","","下列关于胃的良性与恶性溃疡鉴别要点的叙述，正确的是",[["A","早期溃疡型胃癌单凭内镜所见不难与良性溃疡鉴别"],["B","活组织检查可以确定良性或恶性溃疡"],["C","即使内镜下诊断为良性溃疡且活检阴性，仍有漏诊恶性溃疡的可能"],["D","胃镜复查溃疡愈合不是鉴别良性与恶性溃疡的可靠依据"]],"BCD","胃镜发现溃疡时，应注意区分良性溃疡与恶性溃疡（十版内科学P376）。典型胃癌溃疡形态多不规则，常＞2cm，边缘呈结节状，底部凹凸不平，覆污秽状苔。早期溃疡型胃癌内镜下表现常不典型，与良性溃疡难以区分（A错）。因此，对胃溃疡应常规在溃疡边缘取活检来确定良性或恶性溃疡（B对），但活检结果阴性也有可能漏诊（C对），因可能没有取到癌变的组织。常规抗酸治疗一段时间后，有的癌性溃疡也可出现愈合，但溃疡常反复发生，因此胃镜复查溃疡愈合不是鉴别良、恶性溃疡的可靠依据（D对），必须重复活检加以证实。","","N"],["2005-N144",39,"第一节 总论","针对病因和发病机制的治疗",2005,144,"X","","下列肾脏病的免疫抑制治疗中，属于亲免素调节剂的是",[["A","环孢素"],["B","西罗莫司（雷帕霉素）"],["C","麦考酚吗乙酯（霉酚酸酯）"],["D","硫唑嘌呤"]],"ABC","亲免素是近年来发现的普遍存在于生物体内的免疫抑制剂的特异性受体，因大多是蛋白类的，故也叫亲免蛋白，也有叫做免疫嗜素或免疫亲和素等。肾脏疾病的免疫抑制治疗（十版内科学P471）包括糖皮质激素、细胞毒药物和亲免素调节剂，其中的亲免素调节剂为新型细胞免疫抑制剂，包括环孢素（A对）、他克莫司、西罗莫司（雷帕霉素）（B对）、麦考酚吗乙酯（霉酚酸酯）（C对）等。硫唑嘌呤属于细胞毒药物（D错），不属于亲免素调节剂。","","N"],["2005-N145",56,"第二节 原发免疫性血小板减少症","血清学检查",2005,145,"X","","下列支持ITP诊断的是",[["A","PAIg阳性"],["B","PAC₃阳性"],["C","APTT延长"],["D","CT延长"]],"AB","特发性血小板减少性紫癜（ITP）是由于患者对自身血小板抗原的免疫失耐受，产生体液免疫和细胞免疫介导的血小板过度破坏和血小板生成受抑。50%～70%的ITP患者血浆和血小板表面可检测到血小板膜糖蛋白特异性自身抗体，如血小板相关抗体（PAIg）和血小板相关补体（PAC₃）（AB对）。活化部分凝血酶时间（APTT）（C错）测定是内源凝血系统较敏感和最为常用的筛选试验，与血小板功能无关，故ITP患者APTT正常。凝血时间（CT）（D错）是指血液离开血管，在体外发生凝固的时间，主要反映的是内源性凝血系统的功能，与血小板功能无关，故ITP患者CT正常。[另外易考的是出血时间（BT），出血时间是指人为刺破皮肤毛细血管后，从血液自然流出到自然停止所需的时间。BT测定受血小板的数量和质量、毛细血管结构和功能的影响，故ITP患者BT延长。]","","N"],["2005-N146",59,"第一节 甲状腺功能亢进症","甲状腺功能亢进症临床表现",2005,146,"X","","Graves病的主要临床表现是",[["A","甲状腺毒症"],["B","结节性甲状腺肿"],["C","眼征"],["D","胫前黏液性水肿"]],"ACD","弥漫性毒性甲状腺肿（Graves）主要表现为甲状腺毒症（A对），即由血液循环中过多的甲状腺激素引起的神经、循环、消化等系统兴奋性增高和代谢亢进为主要表现的一组临床综合征。多数患者有程度不等的甲状腺肿大。甲状腺毒症可引起眼征（C对），分为单纯性突眼与浸润性突眼即Graves眼病，与眶后组织炎症有关。胫前黏液性水肿（D）多发生在胫骨前下1/3部位，为GD特异性的皮肤损害，属于皮肤的自身免疫性损害，约5%的GD患者伴发胫前黏液性水肿，白种人多见，因此D选项存在争议，原答案选择ACD。但根据十版内科学观点，胫前黏液性水肿见于少数GD患者，故其不是Graves病的主要临床表现，D选项存在争议。甲状腺肿为弥漫性（B错）、对称性，质地中等，无压痛。甲状腺上下极可触及震颤，闻及血管杂音。结节性甲状腺肿为非毒性甲状腺肿的结节期表现，甲状腺呈不对称结节状增大，结节大小不一，有的结节境界清楚，多无完整包膜，切面可有出血、坏死、囊性变、钙化及瘢痕形成。","","N"],["2005-N149",28,"第一节 消化性溃疡","消化性溃疡辅助检查",2005,149,"X","","男性，62岁，胃溃疡多年，2个月来上腹痛发作频繁，无规律，食欲下降。该患者需要进行的检查有",[["A","大便潜血检查"],["B","胃酸测定"],["C","胃镜检查并取活检"],["D","腹部平片"]],"ABC","老年男性患者，慢性胃溃疡多年病史，近期出现上腹痛发作频繁、无规律及食欲下降等异常症状，怀疑为胃溃疡并发癌变。故可行胃镜检查并取活检（最重要）（C对）、测胃酸（胃癌壁细胞遭到破坏，常伴低胃酸）（B对）、查大便潜血（胃溃疡常阴性，胃癌常阳性）（A对）等检查明确诊断。腹部平片（D错）多用于肠梗阻、腹部空腔脏器穿孔等的诊断，对于胃溃疡良恶性鉴别并无太大帮助。","","N"],["2006-N51",15,"第二节 慢性心力衰竭","慢性心力衰竭病因与诱因",2006,51,"A","","下列哪项是心力衰竭的基本病因",[["A","人口老龄化"],["B","急性心肌梗死急性期死亡率降低"],["C","随年龄增加心肌细胞数减少"],["D","原发性心肌舒缩功能障碍"],["E","应用负性肌力作用的抗心律失常药物过多"]],"D","心力衰竭的基本病因包括原发性心肌舒缩功能障碍（D对）（包括①缺血性心肌病：如冠心病心肌缺血和心肌梗死；②心肌炎和心肌病：如病毒性心肌炎和原发性扩张型心肌病；③心肌代谢障碍性疾病：以糖尿病心肌病最常见）和心脏负荷过重（包括前负荷过重和后负荷过重）。病因是疾病发生的原因，它是引起疾病的必不可少的、决定性的、特异性的因素；诱因是促进疾病发生的因素或条件，诱因不是致病的必要因素，但可促进或加速疾病的发生。人口老龄化（A错）、应用负性肌力作用的抗心律失常药物过多（E错）是导致心力衰竭的诱因。急性心肌梗死是心力衰竭的基本病因，但急性心肌梗死急性期死亡率降低是心力衰竭的诱因（B错）。随年龄增长，正常人心肌细胞的减少（C错），是单个或少数细胞生理性凋亡，不是心力衰竭的基本病因。","","N"],["2006-N52",16,"第五节 室性心律失常","尖端扭转型室性心动过速",2006,52,"A","","下列哪项不是尖端扭转型室性心动过速心电图的特点",[["A","发作时QRS波群的振幅与波峰呈周期性改变"],["B","是室性并行心律的一个特殊类型"],["C","频率一般为200～250次/分"],["D","QT间期通常延长"],["E","常并发高U波"]],"B","尖端扭转型室速是较为严重的一种室性心律失常，发作时呈室性心动过速特征。其发生机理与折返有关，因心肌细胞传导缓慢、心室复极不一致引起。常反复发作，易致昏厥。尖端扭转是多形性室速的特殊类型（B错，为本题正确答案），发作时QRS波群的振幅与波峰呈周期性改变（A对），宛如围绕等电位线连续扭转得名。频率一般为200～250次/分（C对）。其特征还包括QT间期通常延长（D对）、常并发高U波（E对）等。室性并行心律指心室的异位起搏点规律地自行发放冲动，并能防止窦房结冲动入侵。","","N"],["2006-N53",18,"第一节 原发性高血压","利尿剂",2006,53,"A","","关于高血压病药物治疗的选择，下列哪项不正确",[["A","无并发症高血压病患者——利尿剂"],["B","轻中度高血压病伴周围血管病者——β受体阻滞剂"],["C","伴糖尿病并有微量蛋白尿者——ACEI"],["D","伴有妊娠者——钙通道拮抗剂"],["E","伴有痛风者——ARB（血管紧张素Ⅱ受体拮抗剂）"]],"B","β受体拮抗剂由于其可诱发平滑肌痉挛，故对伴有哮喘、慢阻肺、周围血管病等患者禁用（B错，为本题正确答案）。利尿剂可降低血压，减少高血压患者并发症，是无并发症高血压患者的首选药物（A对）。ACEI可改善胰岛素抵抗，减少尿蛋白，因此尤其适用于糖尿病并有微量蛋白尿的高血压病患者（C对）。钙通道阻滞剂对胎儿无明显不良影响，因此高血压妊娠期妇女较为安全的降压药物为钙通道阻滞剂（D对）。ARB的作用与ACEI相似，已证实它还可降低血尿酸，故对伴痛风的患者适用（E对）。","","N"],["2006-N54",17,"第四节 急性冠状综合征","P₂Y₁₂受体拮抗剂",2006,54,"A","","下列哪项属于通过ADP受体抑制血小板聚集的药物",[["A","阿司匹林"],["B","双嘧达莫"],["C","氯吡格雷"],["D","水蛭素"],["E","阿昔单抗"]],"C","氯吡格雷（C对）是血小板ADP受体的抑制剂，通过阻断血小板的P₂Y₁₂受体抑制ADP诱导的血小板活化而发挥作用。阿司匹林（A错）作用机制是通过抑制血小板的前列腺素环氧酶，从而防止血栓烷A₂的生成而起作用（TXA₂可促使血小板聚集）。双嘧达莫（B错）作用机制是抑制血小板摄取腺苷，抑制磷酸二酯酶，使血小板内环磷酸腺苷（cAMP）增多，抑制血栓烷素A₂（TXA₂）形成。水蛭素（D错）是凝血酶特异抑制剂，具有很强的抗凝血作用，但对血小板作用弱。阿昔单抗（E错）可选择性阻断血小板糖蛋白（GP）Ⅱb/Ⅲa受体，而防止纤维蛋白原、血小板凝集因子（VWD）、玻璃体结合蛋白及纤维蛋白结合素与激活的血小板结合。","","N"],["2006-N55",17,"第四节 急性冠状综合征","其他",2006,55,"A","","急性心肌梗死应用主动脉内气囊反搏术的最佳适应证是",[["A","并发心源性休克"],["B","并发急性左心衰竭"],["C","并发恶性心律失常"],["D","并发右心室梗死"],["E","并发慢性肾功能不全"]],"A","主动脉内气囊反搏术为治疗低心排综合征的有效手段，是首选的心脏机械辅助方法之一。其作用原理是在心脏舒张期球囊充气、主动脉舒张压升高和冠状动脉压升高，使心肌供血供氧增加；心脏收缩前，气囊排气、主动脉压力下降、心脏后负荷下降、心脏射血阻力减小、心肌耗氧量下降。主动脉内气囊反搏术主要用于心脏疾患产生的心源性休克（A对）、难治性心绞痛、严重主动脉病变或严重血管病变须做急性介入治疗或外科手术时，主动脉内球囊反搏（IABP）是目前心源性休克最有效的支持性治疗措施之一。发左心衰竭（B错）、并发恶性心律失常（C错）、并发右心室梗死（D错）、并发慢性肾功能不全（E错）并非主动脉内气囊反搏术的适应证。","","N"],["2006-N56",21,"第三节 二尖瓣狭窄","右心衰",2006,56,"A","","下列哪项是二尖瓣狭窄伴心房颤动患者最常见的并发症",[["A","心绞痛"],["B","肺栓塞"],["C","心包填塞"],["D","心力衰竭"],["E","感染性心内膜炎"]],"D","二尖瓣狭窄伴心房颤动时，最常见的并发症是心力衰竭（D对）。二尖瓣狭窄时，心室充盈依赖于舒张期的时长，房颤时心率加快导致舒张期充盈时间缩短，左心室充盈减少，心排出量降低。房颤时，舒张晚期心房收缩功能丧失，使得左心室充盈进一步减少，心排出量更低。此两因素可导致心排出量降低20%～25%，导致心力衰竭。二尖瓣狭窄少有心绞痛（A错），心绞痛为主动脉瓣狭窄的常见症状。二尖瓣狭窄并房颤常形成附壁血栓，脱落后可引起体循环栓塞而非肺栓塞（B错）。二尖瓣狭窄伴房颤并不会引起快速性心包积液，因而一般不出现心包填塞（C错）。感染性心内膜炎（十版内科学P322）（E错）常见于二尖瓣及主动脉瓣关闭不全、室间隔缺损、动脉导管未闭、法洛四联症和主动脉缩窄。","","N"],["2006-N57",17,"第四节 急性冠状综合征","环氧化酶抑制剂",2006,57,"A","","男性，60岁，4小时持续性胸痛，阵发性加重，伴出汗，自服速效救心丸稍有缓解。既往有冠心病、高血压病史8年，发现糖尿病2年。入院查体：血压130/85mmHg，痛苦病容，双肺（-），心律整，心率60次/分，第一心音低钝，腹部（-）。ECG显示I、aVL、V₄～₆导ST段下移＞0.1mV，cTnT（+）。下列哪项治疗措施不合适",[["A","静脉应用硝酸甘油"],["B","皮下注射低分子肝素"],["C","口服小剂量β受体阻滞剂"],["D","口服阿司匹林或噻氯吡啶"],["E","口服二氢吡啶类钙拮抗剂"]],"E","老年男性患者，既往有冠心病、高血压病史（常见的基础疾病），持续性胸痛4小时，阵发性加重，伴出汗，自服速效救心丸稍有缓解（非ST段抬高心梗的典型临床表现），ECG显示I、aVL、V₄～₆导ST段下移＞0.1mV（非ST段抬高心梗的典型心电图表现），cTnT阳性（提示存在一定程度的心肌损伤），诊断考虑非ST段抬高心肌梗死。应用二氢吡啶类钙拮抗剂（硝苯地平）（E错，为本题正确答案）时由于其反射性兴奋交感神经引起心肌收缩增强和心率加快，可导致心肌耗氧量增加，因而不宜在心肌梗死患者中应用。硝酸酯类药物（A对）可扩张冠状动脉，缓解心肌缺血。低分子肝素（B对）是抗凝药，具有强烈的抗Ⅹa因子及Ⅱa因子活性的作用，可以降低心脏事件发生。β受体拮抗剂（C对）可以降低心肌耗氧量，减少心肌梗死发生。阿司匹林或噻氯吡啶（D对）是抗血小板药，可以预防血栓形成。","","N"],["2006-N58",19,"第六节 心肌炎","心肌炎诊断",2006,58,"A","","女性，22岁，3周前因上感发热5天。1天来胸闷，心悸，气短伴头晕，全身乏力。查体：体温37℃，脉搏70次/分，血压96/60mmHg，咽充血，双肺清，未闻及啰音，心脏不大，心律不整，心率76次/分，第一心音低钝，ECG示频发室性期前收缩，短阵室性心动过速。最可能的诊断是",[["A","急性心肌炎"],["B","急性心包炎"],["C","扩张型心肌病"],["D","感染性心内膜炎"],["E","冠心病"]],"A","年轻女性患者，近期有上呼吸道感染病史（病毒性心肌炎的常见前驱症状），胸痛、心悸、全身乏力（病毒性心肌炎常见症状），查体心脏不大，心律不整，心电图示：频发室早，阵发室速，诊断考虑急性心肌炎（A对）。急性心包炎（B错）常有胸痛及心包摩擦感，ECG可见ST段弓背向下抬高，与患者临床表现不符。扩张型心肌病（C错）多有心脏扩大及心力衰竭，与患者临床表现不符。感染性心内膜炎（D错）常有瓣膜病病史，且有发热，一般可闻及可变杂音，与患者临床表现不符。冠心病（E错）常见于有心血管高危因素的老年人，在年轻女性不作优先考虑。","","N"],["2006-N59",1,"第二节 慢性阻塞性肺疾病","肺功能评估",2006,59,"A","","COPD的严重程度分级是依据下列哪项肺功能指标进行的",[["A","第一秒用力呼气容积与用力肺活量比（FEV₁/FVC）"],["B","第一秒用力呼气容积与预计值比（FEV₁/预计值）"],["C","残气量与肺总量比（RV/TLC）"],["D","呼气相峰流速（PEF）"],["E","肺活量（VC）"]],"B","FEV₁/FVC（十版内科学P27）（A错）是评价气流受限的一项敏感指标，用于COPD的诊断；而FEV₁占预计值的百分比（B对）为慢性阻塞性肺疾病患者病情严重程度分级的指标，GOLD 1级（轻度）FEV₁≥80%预计值，GOLD 2级（中度）50%～80%预计值，GOLD 3级（重度）30%～50%预计值，GOLD 4级（极重度）＜30%预计值；RV/TLC（C错）升高主要出现在肺组织弹性日益减退，慢阻肺进一步发展时，不用于COPD患者的严重程度分级；PEF（D错）及其日间和周间变异率有助于哮喘的诊断和病情评估；VC（E错）是一次通气的最大能力，是肺功能测定的常用指标。","","N"],["2006-N60",3,"第一节 支气管扩张症","支气管扩张临床表现",2006,60,"A","","下列关于支气管扩张常见临床特点的叙述，错误的是",[["A","反复咯血"],["B","咳大量脓痰"],["C","病变部位固定湿啰音"],["D","胸部X线平片多无异常表现"],["E","胸部CT多表现为支气管壁增厚，管腔呈囊、柱状扩张"]],"D","支气管扩张胸部X线平片检查时，可见囊状支气管扩张的气道，表现为显著的囊腔，腔内可存在气液平面（D错，为本题正确答案）。胸部CT多表现为支气管壁增厚，管腔呈囊、柱状扩张（E对）。支气管扩张主要症状为持续或反复的咳嗽、咳痰或咳大量脓痰（B对）。50%～70%的病例可发生咯血（A对），大出血常为小动脉被侵蚀或增生的血管被破坏所致。部分患者以反复咯血为唯一的症状，称为干性支气管扩张。病变早期或干性支气管扩张可无异常肺部体征，病变重或继发感染时可闻及下胸部、背部固定而持久的局限性粗湿啰音（C对）。","","N"],["2006-N61",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病肺功能检查",2006,61,"A","","用于鉴别COPD和支气管哮喘的试验是",[["A","过敏原试验"],["B","支气管激发试验"],["C","低氧激发试验"],["D","运动试验"],["E","支气管舒张试验"]],"E","COPD和支气管哮喘都有气流受限，两者鉴别的关键为气流受限的可逆性。COPD的气流受限多呈进行性发展，不完全可逆，后者的气流受限具有显著的可逆性。临床上常用支气管舒张试验来测定气流受限的可逆性（E对）。当吸入支气管舒张剂20分钟后重复测定肺功能，FEV₁较用药前增加≥12%，且其绝对值增加≥200ml，判断结果为阳性，提示存在可逆的气道阻塞，此为支气管哮喘的特点。过敏原试验（A错）结合病史有助于哮喘的病因诊断，但对于鉴别COPD与支气管哮喘意义不大；支气管激发试验（B错）主要用于临床表现不典型哮喘患者的辅助诊断，用来测试气道反应性，对患者有一定的风险，临床上较少用其鉴别COPD和支气管哮喘；低氧激发试验（C错）、运动试验（D错）是支气管激发试验的一种，对于药物激发阴性的患者可以应用，同样有一定的危险。","","N"],["2006-N62",11,"第一节 胸腔积液","结核性胸膜炎",2006,62,"A","","下列关于结核性胸腔积液特点的叙述，错误的是",[["A","密度＞1.018"],["B","胸水蛋白定量＞30g/L"],["C","胸水腺苷脱氨酶＜40U/L"],["D","胸水细胞数＞500×10⁶/L"],["E","胸水乳酸脱氢酶水平大于血清水平的60%"]],"C","结核性胸腔积液为胸膜通透性增加所致，胸水性质为渗出液。渗出液一般有以下特点：比重＞1.018（A对），蛋白定量＞30g/L（B对），白细胞数＞500×10⁶/L（D对），胸水蛋白/血清蛋白＞0.5，胸水LDH/血清LDH＞0.6（E对）。腺苷脱氨酶（ADA）在淋巴细胞内含量较高，结核性胸膜炎引起的胸腔积液，因细胞免疫受刺激，淋巴细胞明显增多，故腺苷脱氨酶（ADA）多高于45U/L（C错，为本题正确答案）。","","N"],["2006-N63",5,"第一节 肺脓肿","原发性肺脓肿",2006,63,"A","","吸入性肺脓肿最常见的部位是",[["A","左上叶后段和舌叶"],["B","左下叶基底段"],["C","右上叶后段和下叶背段"],["D","右下叶基底段"],["E","右中叶"]],"C","吸入性肺脓肿的好发部位与支气管解剖和患者体位有关。由于右主支气管较陡直，且管径粗大，吸入物易进入右肺导致肺脓肿。仰卧位时，好发于上叶后段或下叶背段（C对）；坐位时好发于下叶后基底段；右侧卧位时，则好发于右上叶前段或后段。","","N"],["2006-N64",10,"第三节 慢性肺源性心脏病","利尿药",2006,64,"A","","慢性肺源性心脏病急性加重期应用利尿剂，可能引起",[["A","代谢性酸中毒"],["B","呼吸性酸中毒合并代谢性酸中毒"],["C","呼吸性碱中毒合并代谢性酸中毒"],["D","呼吸性酸中毒合并代谢性碱中毒"],["E","呼吸性碱中毒合并代谢性碱中毒"]],"D","慢性肺心病急性加重期患者使用了利尿剂之后，钾离子排出增多，机体出现低钾。低钾时，H⁺-K⁺泵作用增强，K⁺进入细胞外，H⁺进入细胞内，产生碱中毒，同时由于利尿作用，H⁺排出增加，使碳酸氢根的重吸收增加，体内碳酸氢根水平增高，因血中主要阴离子碳酸氢根和氯离子之和相对恒定，故氯离子相应减少，所以使用利尿剂之后易发生低钾、低氯性碱中毒（代谢性碱中毒）。慢性肺心病患者存在呼吸功能障碍，可出现CO₂潴留，产生呼吸性酸中毒，而不是呼吸性碱中毒（CE错）。因CO₂潴留发展缓慢，肾脏可通过减少HCO₃⁻的排除来维持pH的恒定，但当体内CO₂长期升高时，HCO₃⁻也维持在较高的水平，导致呼吸性酸中毒合并代谢性碱中毒（D对），而不是代谢性酸中毒（A错）。若是发生急性呼衰，则肾脏不能及时缓冲，于是体内酸性物质会增多，发生呼吸性酸中毒合并代谢性酸中毒（B错）。","","N"],["2006-N65",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺军团病诊断",2006,65,"A","","男性，34岁，2天前着凉后发热，体温38.9℃，伴呼吸困难，咳嗽，咳少量黄痰，腹泻两次。自服“先锋霉素”无效。入院查体：嗜睡，口唇轻度紫绀，脉搏100次/分，呼吸28次/分，双肺叩清音，双下肺可闻及湿啰音，心律整，腹（-），血WBC 12.3×10⁹/L，中性87%，血气分析：pH7.35，PaO₂57mmHg，PaCO₂31mmHg，胸片示：左上肺前段、左下肺及右上肺前段、右中肺见斑片状阴影。最可能的诊断是",[["A","军团菌肺炎"],["B","金黄色葡萄球菌肺炎"],["C","ARDS"],["D","肺栓塞"],["E","支原体肺炎"]],"A","患者着凉后发热，体温38.9℃（军团菌肺炎起病初感乏力、肌痛、头痛，24～48小时后体温上升至39～40℃，呈稽留热型，伴反复寒战），伴呼吸困难、咳嗽、咳少量黄痰、腹泻（军团菌肺炎咳嗽有少量黏痰，部分患者有胸痛、呼吸困难，或有恶心、呕吐、水样腹泻和消化道出血），入院查体：嗜睡，口唇轻度紫绀，脉搏100次/分，呼吸28次/分，双下肺可闻及湿啰音（军团菌肺炎呈急性病容、呼吸急促、发绀，肺部湿啰音），胸片可见左上肺前段、左下肺及右上肺前段、右中肺见斑片状阴影（军团菌肺炎的X线表现），自服“先锋霉素”无效（肺炎患者β-内酰类抗生素治疗无效，应警惕为军团菌肺炎），故最可能的诊断是军团菌肺炎（A对）。金黄色葡萄球菌肺炎（十版内科学P53）（B错）主要表现为急性寒战、高热、脓痰，痰中常有血丝，X线影像为单个或多发的液气囊腔，阴影的易变性，先锋霉素治疗效果较好；ARDS（十版内科学P144）（C错）患者表现为原发病起病后72小时内出现呼吸增快，进行性呼吸困难、发绀，X线呈磨玻璃或实变浸润影，血气分析的典型表现为PaO₂降低，PaCO₂降低，pH升高，患者虽有PaO₂（正常80～100mmHg）、PaCO₂（正常35～45mmHg）降低，但并无引起ARDS的原发病或高危因素；肺栓塞（十版内科学P112）（D错）主要表现为突发呼吸困难、胸痛、咯血、晕厥、烦躁不安、大汗淋漓、紫绀等，X线无斑片状阴影；支原体肺炎（十版内科学P61）（E错）的典型表现为干咳，咳少量黏液，X线显示肺部多种形态的浸润影。","","N"],["2006-N66",5,"第一节 肺脓肿","原发性肺脓肿",2006,66,"A","","男性，78岁，3天前着凉后发热，体温38.2℃，伴咳嗽，咳黄痰，痰不易咳出。既往病史：3年前患脑梗死，卧床，生活不能自理。偶有进食呛咳。体检：双下肺可闻及细小水泡音。胸片提示：右下肺背段片状影。血WBC10.8×10⁹/L，中性79%，应用头孢唑林体温控制不佳。该患者可能合并哪类病原体感染",[["A","耐甲氧西林金黄色葡萄球菌"],["B","军团菌"],["C","肺炎链球菌"],["D","真菌"],["E","厌氧菌"]],"E","患者老年男性，既往脑梗死病史，长期卧床，有进食呛咳，着凉后出现发热，伴咳嗽，咳黄痰，痰不易咳出。体检双下肺可闻及细小水泡音，胸片提示右下肺背段片状影，白细胞总数、中性粒细胞比例升高，根据吸入性肺脓肿诊断标准，可考虑为误吸导致的吸入性肺脓肿。吸入性肺脓肿病原体多为厌氧菌，头孢唑林属于第一代头孢菌素，对厌氧菌（E对）疗效差，仰卧位时，好发于上叶后段或下叶背段；耐甲氧西林金黄色葡萄球菌（A错）一般为长期使用抗生素患者感染时常见的病原体；军团菌（B错）感染时，一般有高热、肌痛，进展迅速的症状，且常经供水系统、空调和雾化吸入而被吸入导致感染；肺炎链球菌（C错）感染一般咳铁锈色痰，且对头孢唑林敏感；真菌性肺炎（D错）患者一般有长期使用广谱抗菌药物、免疫抑制剂、抗癌化疗或者放疗史。","","N"],["2006-N67",30,"第一节 溃疡性结肠炎","糖皮质激素",2006,67,"A","","在用糖皮质激素治疗溃疡性结肠炎时，宜选用主要作用于肠道局部而全身不良反应较小的药物。下列具有此种作用的糖皮质激素是",[["A","泼尼松"],["B","泼尼松龙"],["C","布地奈德"],["D","地塞米松"],["E","琥珀酸钠氢化可的松"]],"C","溃疡性结肠炎的治疗药物主要包括糖皮质激素和5-氨基水杨酸，其中糖皮质激素对本病急性发作期有较好的疗效，其治疗机制主要是非特异性的抗炎作用和抑制免疫反应，可用于对5-氨基水杨酸疗效不佳的轻、中度患者，特别适用于重度的患者。但泼尼松（A错）、泼尼松龙（B错）、地塞米松（D错）、琥珀酸钠氢化可的松（E错）可作用于全身，长期使用后都会出现严重的不良反应。布地奈德为以局部作用为主的糖皮质激素，全身不良反应较小（C对）。","","N"],["2006-N68",32,"第二节 肠易激综合征","肠易激综合征诊断与鉴别诊断",2006,68,"A","","目前，对肠易激综合征的诊断推荐采用国际认同的罗马Ⅱ标准，其中有关腹部不适或腹痛时间的规定是在过去12个月内至少累及达",[["A","6周"],["B","8周"],["C","10周"],["D","12周"],["E","16周"]],"D","肠易激综合征（IBS）的标准为最新的罗马Ⅳ标准（2016年），具体内容为：在诊断前至少6个月最近3个月内每周至少 1天反复发作腹痛，且伴有以下两条或两条以上：①与排便相关；②发作时伴排便次数的改变；③发作时伴排便性状的改变。罗马Ⅱ标准（1996年）的内容为：在过去的12个月内至少12周（D对）存在腹胀或腹痛，并伴有下列3个排便习惯改变中的两项：①排便后症状缓解；②症状发作伴排便次数改变；③症状发作伴粪便性状改变。本题根据题干选择D选项，但需要牢记最新教材诊断标准（罗马Ⅳ）。","","N"],["2006-N69",35,"第一节 肝硬化","肝硬化发病机制及病理",2006,69,"A","","在肝硬化的发病机制中，形成肝纤维化的主要细胞是",[["A","肝星状细胞"],["B","肝细胞"],["C","Kupffer细胞"],["D","上皮细胞"],["E","内皮细胞"]],"A","肝纤维化是肝硬化演变发展过程的一个重要阶段，正常肝组织细胞外基质生成和降解保持平衡，细胞外基质胶原纤维的过度沉积是肝纤维化的基础，而增多的胶原纤维可由肝星状细胞转变为成纤维样细胞产生胶原纤维（A对）。Kupffer细胞（C错）为肝血窦腔内的单核巨噬细胞，参与炎症反应，可产生少量胶原纤维，但非主要细胞。肝细胞（B错）的大量不规则再生可形成假小叶，此为肝硬化的基本病理特征，而与肝纤维化的形成关系不大。上皮细胞（D错）和内皮细胞（E错）均不能合成胶原，不参与纤维化。","","N"],["2006-N71",37,"第二节 慢性胰腺炎","胰腺内、外分泌功能测定",2006,71,"A","","下列选项中，属于胰腺外分泌功能的试验是",[["A","维生素B₁₂吸收试验"],["B","胰功肽试验"],["C","血清缩胆囊素测定"],["D","空腹血浆胰岛素测定"],["E","血浆胰多肽测定"]],"B","胰腺分为外分泌腺和内分泌腺两部分。外分泌腺由腺泡和腺管组成，分泌胰液。胰液中含有碳酸氢钠、胰蛋白酶原、糜蛋白酶原、弹力蛋白酶原、脂肪酶、淀粉酶等。内分泌腺由大小不同的细胞团（胰岛）所组成，分泌胰高血糖素、胰岛素、生长抑素和胰多肽等。胰功肽试验（粪弹力蛋白酶）（B对）：由于胰腺腺泡分泌的弹力蛋白酶在肠道中不被破坏，其粪便中的浓度高于其在胰液中的浓度，检测其粪便中的浓度可反映胰腺腺泡细胞的分泌情况，属于胰腺外分泌功能试验。维生素B₁₂吸收试验（A错）：应用⁵⁸Co维生素B₁₂吸收试验显示不正常时，口服碳酸氢钠和胰酶片后被纠正者，提示维生素B₁₂的吸收障碍与胰分泌不足有关，属于胰腺吸收功能试验。血清缩胆囊素测定（C错）：慢性胰腺炎时血清缩胆囊素升高，与胰外分泌减少，对血清缩胆囊素的反馈抑制作用减弱有关，属于胰腺内分泌功能测定。血浆胰多肽测定（E错）：胰多肽主要由胰岛PP细胞分泌，慢性胰腺炎患者血浆胰多肽明显下降，属于胰腺内分泌功能测定。空腹血浆胰岛素测定（D错）：胰岛素由胰岛B细胞分泌，慢性胰腺炎患者血浆胰岛素明显下降，属于胰腺内分泌功能测定。","","N"],["2006-N72",28,"第一节 消化性溃疡","保护胃黏膜",2006,72,"A","","男性，30岁，患消化性溃疡2年余，经常反复发作，曾用过多种药物治疗。下列用过的治疗药物中，属于保护胃黏膜的药物是",[["A","法莫替丁"],["B","奥美拉唑"],["C","氢氧化铝"],["D","西沙必利"],["E","米索前列醇"]],"CE","米索前列醇（E对）属于胃黏膜保护剂，具有抑制胃酸分泌、增加胃十二指肠黏膜的黏液及碳酸氢盐分泌和增加黏膜血流等作用，主要用于NSAID溃疡的预防。西沙必利（D错）属于胃肠动力药物，无保护胃黏膜作用。法莫替丁（H₂受体拮抗剂）（A错）和奥美拉唑（质子泵抑制剂）（B错）均属于抑酸剂。氢氧化铝（C对）为碱性抗酸剂，可中和胃酸，短暂缓解疼痛，由于其能促进前列腺素合成，增加黏膜血流量、刺激胃黏膜分泌HCO₃⁻和黏液，最新教材的观点将弱碱性抗酸剂视为胃黏膜保护剂范畴（十版内科学P377），故本题C选项也为正确答案。","","N"],["2006-N73",30,"第一节 溃疡性结肠炎","溃疡性结肠炎诊断",2006,73,"A","","男性，35岁，腹泻伴左下腹轻至中度疼痛2年，大便4～5次/天，间断便血，有疼痛-便意-便后缓解的规律，常有里急后重，最近结肠镜检查发现结肠黏膜粗糙呈细颗粒状，血管纹理模糊。目前最可能的诊断是",[["A","肠道功能紊乱"],["B","克罗恩病"],["C","溃疡性结肠炎"],["D","肠阿米巴病"],["E","肠结核"]],"C","青年男性患者，腹泻，间断便血，左下腹痛（溃疡性结肠炎腹痛多位于左下腹或下腹），里急后重（溃疡性结肠炎病变部位多位于直肠和乙状结肠，常有直肠刺激征），腹痛便后缓解，结肠镜检见结肠黏膜粗糙呈细颗粒状，血管纹理模糊等表现，可以得出患者最可能的诊断为溃疡性结肠炎（C对）。腹泻为克罗恩病（B错）患者常见症状，但一般无便血，其特征性内镜改变为纵行溃疡，伴周围黏膜正常或鹅卵石样改变（十版内科学P392）。肠结核（E错）好发于回盲部，因此腹痛位于右下腹，且一般无直肠刺激症状（如里急后重等）。肠道功能紊乱（A错）为功能性疾病，无器质性改变，因此结肠镜检时无阳性发现。肠阿米巴病变（D错）主要侵犯右半结肠，溃疡较深，边缘潜行，溃疡间黏膜多正常，可出现腹泻，其特征性表现为伴有腥臭味的暗红色果酱样大便。","","N"],["2006-N74",40,"第六节 无症状性血尿和_或蛋白尿","无症状性血尿和_或蛋白尿病理",2006,74,"A","","下列关于隐匿性肾小球肾炎的叙述，错误的是",[["A","可无蛋白尿"],["B","可无血尿"],["C","无高血压"],["D","无水肿"],["E","肾脏病理肾小球无异常"]],"E","隐匿性肾病是原发性肾小球疾病中常见的一种临床类型，又叫无症状性血尿和（或）蛋白尿，可仅有血尿（A对）或仅有蛋白尿（B对），无急慢性肾炎病史，肾功能检查结果正常。多无明显临床症状或体征，即无高血压（C对）、无水肿（D对）及肾功能损害。本病肾脏可由多种病理类型的原发性肾小球疾病所致，病理改变较轻微，但肾小球并非无异常（E错，为本题正确答案）。","","N"],["2006-N75",40,"第五节 肾病综合征","低白蛋白血症",2006,75,"A","","有多种原因可引起肾病综合征患者的血浆白蛋白降低。下列原因中，错误的是",[["A","白蛋白自尿中丢失"],["B","可能有蛋白质的摄入不足"],["C","可能有蛋白质的吸收不良或丢失"],["D","肝脏失去了代偿增加白蛋白合成的能力"],["E","原尿中部分白蛋白在近曲小管上皮细胞中分解"]],"D","肝脏失去代偿增加清蛋白合成能力（D错，为本题正确答案）为肝功能减退时血浆白蛋白降低的原因，而肾病综合征时，肝功能正常，低蛋白血症可促进肝脏代偿性合成白蛋白。肾病综合征时血浆蛋白降低的原因有：①肾小球滤过膜受损，对血浆蛋白的通透性增加，导致原尿中蛋白质含量增高，当超过近端肾小管重吸收能力时，形成大量蛋白尿，导致包括白蛋白在内的蛋白质从尿中丢失（A对）；②肾病综合征患者因胃肠道粘膜水肿导致食欲减退、蛋白质摄入不足（B对），以及蛋白质吸收不良或丢失（C对）；③肾病综合征时大量白蛋白从尿中丢失，近端肾小管摄取滤过蛋白增多，也使肾小管上皮细胞中分解蛋白增加（E对）。","","N"],["2006-N76",41,"第一节 尿路感染","定位诊断",2006,76,"A","","女性，40岁，5天来高热，腰痛伴尿频、尿痛、尿急，曾口服环丙沙星两天不见好转。既往无类似发作史，1个月前曾发现肾盂结石未积极治疗。查体：体温39℃，右肾区有叩击痛，尿蛋白（+），WBC20～30个/HP，偶见白细胞管型，尿比重1.025。最可能的诊断是",[["A","非复杂性膀胱炎"],["B","非复杂性急性肾盂肾炎"],["C","复杂性膀胱炎"],["D","复杂性急性肾盂肾炎"],["E","慢性肾盂肾炎"]],"D","40岁女性患者（育龄期妇女，属易感人群），高热、腰痛（感染中毒症状较明显，提示感染部位较高）、伴尿频、尿急、尿痛（尿路刺激征，提示泌尿系感染可能），曾口服环丙沙星两天不见好转（考虑革兰氏阴性耐药菌株和革兰氏阳性球菌感染可能），1个月前发现肾盂结石（存在基础性疾病肾盂结石，可能引起尿路梗阻，属易感因素），既往无类似发作史（考虑急性感染，慢性肾盂肾炎半数以上患者可有急性肾盂肾炎病史）诊断为复杂性急性肾盂肾炎（D对B错）。下尿路感染，一般少有高热、腰痛及肾区叩痛，且不会出现白细胞管型，故不选非复杂性膀胱炎（A错）及复杂性膀胱炎（C错）。慢性肾盂肾炎（E错）多有急性肾盂肾炎病史，患者病程5天，既往无类似发作史，故排除。","","N"],["2006-N77",51,"第一节 骨髓增生异常性肿瘤","骨髓增生异常性肿瘤实验室检查",2006,77,"A","","下列选项中，可引起间接胆红素升高的是",[["A","缺铁性贫血"],["B","铁粒幼细胞贫血"],["C","慢性病性贫血"],["D","再生障碍性贫血"],["E","骨髓增生异常综合征"]],"E","血清间接胆红素升高主要见于血管外溶血。发生血管外溶血时，异常红细胞在骨髓原位或脾脏中被单核-巨噬细胞系统吞噬消化，释放出的血红蛋白分解为珠蛋白和血红素，血红素被分解为铁和卟啉，卟啉进一步分解为游离胆红素后入血。当游离胆红素（间接胆红素）量增加，超过肝处理能力时，患者血中间接胆红素增高。骨髓增生异常综合征（MDS）属于血管外溶血，间接胆红素增高（E对）。缺铁性贫血（A错）是原料铁的缺乏导致血红蛋白和血红素合成障碍；铁粒幼细胞贫血（B错）是铁利用障碍导致血红蛋白和血红素不能合成；慢性病贫血（C错）是指继发于慢性感染、炎症和恶性肿瘤的一组贫血，表现为铁代谢障碍；再生障碍性贫血（D错）是造血功能低下或衰竭。以上四种类型贫血都不伴溶血，其间接胆红素正常。","","N"],["2006-N78",53,"第二节 非霍奇金淋巴瘤","蕈样肉芽肿病_塞扎里综合征",2006,78,"A","","完全表达为成熟的辅助性T细胞淋巴瘤的类型是",[["A","成人T细胞淋巴瘤"],["B","周围T细胞淋巴瘤"],["C","蕈样肉芽肿/赛塞里综合征"],["D","血管免疫母细胞性T细胞淋巴瘤"],["E","间变性大细胞淋巴瘤"]],"C","蕈样肉芽肿侵及末梢血液者称为Sezary综合征（赛塞里综合征），属惰性淋巴瘤类型，增生的细胞完全表达为成熟的辅助性T细胞（C对），呈CD3⁺、CD4⁺、CD8⁻。其余各项淋巴瘤均表达为成熟的抑制性T细胞，呈CD3⁺、CD4⁻、CD8⁺（ABDE错）。","","N"],["2006-N79",56,"第二节 原发免疫性血小板减少症","ITP的三线治疗",2006,79,"A","","在ITP的免疫抑制治疗中，最常用的免疫抑制剂是",[["A","长春新碱"],["B","环磷酰胺"],["C","硫唑嘌呤"],["D","环孢素"],["E","甲氨蝶呤"]],"A","ITP（特发性血小板减少性紫癜）是一种复杂的多种机制共同参与的获得性自身免疫性疾病，治疗一般首选糖皮质激素。ITP的二线治疗包括脾切除、抗CD20单克隆抗体、血小板生成药物和免疫抑制剂等。其中最常用的免疫抑制剂是长春新碱（A对），除具免疫抑制作用外，还可能有促进血小板生成及释放的作用。环孢素（D错）主要用于难治性ITP的治疗（十版内科学P623）。环磷酰胺（B错）为SLE（系统性红斑狼疮）患者首选的免疫抑制剂（十版内科学P825）。甲氨蝶呤（E错）为类风湿关节炎首选的改变病情风湿药（十版内科学P818）。长春新碱、环磷酰胺、甲氨蝶呤作为首选的免疫抑制剂分别对应的疾病需熟记。","","N"],["2006-N80",53,"第二节 非霍奇金淋巴瘤","套细胞淋巴瘤",2006,80,"A","","男性，65岁，无痛性双颈部淋巴结进行性肿大半个月，到医院行淋巴结活检病理，发现淋巴结结构破坏，弥漫性小淋巴细胞浸润，免疫染色CD20阳性，CD5阳性，有t（11；14），表达bcl-1。诊断为NHL，最可能的类型是",[["A","单核细胞样B细胞淋巴瘤"],["B","脾边缘区细胞淋巴瘤"],["C","黏膜相关性淋巴样组织淋巴瘤"],["D","滤泡性淋巴瘤"],["E","套细胞淋巴瘤"]],"E","该患者已诊断为NHL（非霍奇金淋巴瘤），考察NHL染色体异位特征。t（11；14）是套细胞淋巴瘤的标记（E对）。滤泡性淋巴瘤（D错）染色体异位特征为t（14；18）。黏膜相关性淋巴样组织淋巴瘤（C错）染色体异位特征为t（11；18）、t（14；18）和t（1；14）。边缘区淋巴瘤（B错）染色体异位特征为t（11；18）。","","N"],["2006-N81",61,"第一节 糖尿病","糖化血红蛋白和糖化白蛋白测定",2006,81,"A","","果糖胺的测定可反映多长时间内糖尿病患者血糖的总水平",[["A","7～14天"],["B","15～21天"],["C","22～28天"],["D","29～35天"],["E","36～42天"]],"B","果糖胺（FA）是血浆蛋白（主要为白蛋白）与葡萄糖发生非酶催化的糖化反应产物，其生成量与血糖浓度和持续时间相关。由于白蛋白在血中半衰期为19天，故果糖胺（FA）测定可反映患者2～3周内血糖水平（B对）。","","N"],["2006-N82",59,"第一节 甲状腺功能亢进症","Graves眼病",2006,82,"A","","下列关于Graves眼病的叙述，正确的是",[["A","多见于女性"],["B","全部为双眼受累"],["C","多数为甲亢与眼病同时发生"],["D","少数甲亢先于眼病发生"],["E","眼征达4级（ATA分级）和以上者可以诊断为GO"]],"E","最新美国甲状腺病学会将突眼分为由0级至6级的7个级别（ATA分级）。0～1级代表无眼病或眼病轻微；2～6级说明病变较重，达4级和以上者可以诊断为GO（Graves眼病）（E对）。Grave病与遗传关系密切，女性多见。而Graves眼病好发于女性（A对），但男性临床表现更重。发病时多双眼受累，但仍有10%～20%为单眼受累（B错）。眼病与甲亢发生顺序中，甲亢先于眼病发生与同时发生者占绝大多数，大量统计证明甲亢先于眼病发生率略高于同时发生者（CD错）。本题官方给出的参考答案为E，但根据10版教材，AE都是正确选项。","","N"],["2006-N83",68,"第一节 类风湿关节炎","类风湿关节炎X线检查",2006,83,"A","","类风湿关节炎的关节X线检查结果属Ⅲ期的特点是",[["A","关节周围软组织肿胀阴影"],["B","关节间隙狭窄"],["C","关节半脱位和骨性强直"],["D","关节面出现虫蚀样破坏性改变"],["E","关节端的骨质疏松"]],"D","类风湿关节炎的关节X线变化与其病理变化密切相关。早期病理变化是滑膜渗出炎症和间质水肿，X线表现为关节周围软组织肿胀阴影和关节端的骨质疏松（Ⅰ期）（AE错）。随着滑膜的肥厚，形成的绒毛样突起及纤维组织使得关节间隙变窄，X线表现为关节间隙狭窄（Ⅱ期）（B错）。绒毛对关节有很强的破坏性和血管炎的发生所致的类风湿结节中心纤维素样坏死，在X线上表现关节面虫蚀样破坏性改变（Ⅲ期）（D对）。最后晚期可见关节半脱位和关节破坏后的纤维性和骨性强直（Ⅳ期）（C错）。","","N"],["2006-N84",69,"第一节 系统性红斑狼疮","抗ENA抗体谱",2006,84,"A","","下列选项中，不属于抗ENA抗体的是",[["A","抗Sm抗体"],["B","抗RNP抗体"],["C","抗SSA抗体"],["D","抗rRNP抗体"],["E","抗dsDNA抗体"]],"E","抗ENA抗体主要有：抗Sm抗体（A错）、抗SSA抗体（C错）、抗SSB抗体、抗RNP抗体（B错）、抗rRNP抗体（D错）。对结缔组织疾病诊断和鉴别诊断有重要意义，与疾病严重程度和活动性无明显相关。抗双链DNA（dsDNA抗体）（E对）对诊断SLE有较高的特异性，且与SLE的活动相平行，并可作为治疗的评估，但其不属于抗ENA抗体。","","N"],["2006-N119",16,"第八节 心律失常的介入治疗和手术治疗","起搏方式的选择",2006,119,"B","","反复发作性室性心动过速伴短阵意识丧失者，应首选的起搏器型号是",[["A","DDD型"],["B","VVI型"],["C","AAI型"],["D","VOO型"],["E","ICD型"]],"E","起搏器型号的编码中，第一个字母均代表起搏心腔、第二个字母代表感知心腔、第三个字母代表感知后的反应，字母A代表心房、V代表心室、前两个字母D均代表双腔、最后一个字母D代表触发和抑制、I代表抑制、O代表无。DDD型（A错）起搏器代表的是：起搏的是心房及心室，感知的是自身心房及心室信号，心房和心室被感知后触发或抑制起搏器在不应期内发放一次脉冲，因此，此型起搏器适用于房室传导阻滞伴或不伴窦房结功能障碍的患者。VVI型（B错）起搏器代表的是：起搏的是心室，感知的是自身心室信号，自身心室信号被感知后抑制起搏器发放一次脉冲，因此此型适用于心室率缓慢、无器质性心脏病心功能正常的患者。AAI型（C错）起搏器代表的是：起搏的是心房，感知的是自身心房信号，自身心房信号被感知后抑制起搏器发放一次脉冲，因此此型适用于病位在心房的房室传导正常的病窦综合征患者，属于生理性起搏。VOO型（D错）起搏器代表的是：起搏的是心室，而无感知信号的部位、也无感知后的反应，因此此型属于比较机械的固定频率心室型起搏器，现已弃用。ICD型即植入式心律转复除颤器，它可以持续地监控患者的心律，当检测到患者的心室内出现心律不整时，就会对心脏释放出电流脉冲来恢复其正常的心跳，患者仍不能恢复正常的心律或者患者的心室开始出现颤动，ICD就会对心脏释放出高能量的电脉冲（电击）来达到除颤的目的。故ICD型（E对）应作为反复发作性室性心动过速伴短阵意识丧失者的首选。","","N"],["2006-N120",16,"第八节 心律失常的介入治疗和手术治疗","起搏方式的选择",2006,120,"B","","慢性心房颤动伴二度房室传导阻滞者，应首选的起搏器型号是",[["A","DDD型"],["B","VVI型"],["C","AAI型"],["D","VOO型"],["E","ICD型"]],"B","起搏器型号的编码中，第一个字母均代表起搏心腔、第二个字母代表感知心腔、第三个字母代表感知后的反应，字母A代表心房、V代表心室、前两个字母D均代表双腔、最后一个字母D代表触发和抑制、I代表抑制、O代表无。VVI型起搏器代表的是：起搏的是心室，感知的是自身心室信号，自身心室信号被感知后抑制起搏器发放一次脉冲，因此此型适用于慢性心房颤动伴二度房室传导阻滞者（B对）等心室率缓慢、无器质性心脏病心功能正常的患者。DDD型（A错）起搏器代表的是：起搏的是心房及心室，感知的是自身心房及心室信号，心房和心室被感知后触发或抑制起搏器在不应期内发放一次脉冲，因此，此型起搏器适用于房室传导阻滞伴或不伴窦房结功能障碍的患者。AAI型（C错）起搏器代表的是：起搏的是心房，感知的是自身心房信号，自身心房信号被感知后抑制起搏器发放一次脉冲，因此此型适用于病位在心房的房室传导正常的病窦综合征患者，属于生理性起搏。VOO型（D错）起搏器代表的是：起搏的是心室，而无感知信号的部位、也无感知后的反应，因此此型属于比较机械的固定频率心室型起搏器，现已弃用。ICD型即植入式心律转复除颤器，它可以持续地监控患者的心律，当检测到患者的心室内出现心律不整时，就会对心脏释放出电流脉冲来恢复其正常的心跳，患者仍不能恢复正常的心律或者患者的心室开始出现颤动，ICD就会对心脏释放出高能量的电脉冲（电击）来达到除颤的目的。故ICD型（E错）应作为反复发作性室性心动过速伴短阵意识丧失者的首选。","","N"],["2006-N121",27,"第二节 慢性胃炎","慢性胃炎Hp检测",2006,121,"B","","侵入性检查幽门螺杆菌的首选方法是",[["A","胃组织学检查"],["B","快速尿素酶试验"],["C","幽门螺杆菌培养"],["D","¹⁴C尿素呼气试验"],["E","血清学检查"]],"B","侵入性检查方法是指必须通过胃镜取胃黏膜活组织进行检测，包括快速尿素酶试验、胃组织学检查及幽门螺杆菌培养等（十版内科学P361）。其中快速尿素酶试验（B对）操作简便、费用低，是侵入性检查幽门螺杆菌（Hp）的首选方法；胃组织学检查（A错）可直接观察幽门螺杆菌，与快速尿素酶试验结合，可提高诊断准确率，但因操作繁琐，不作为首选；幽门螺杆菌培养（C错）技术要求高，主要用于科研。非侵入性检查不需要胃镜就能进行，包括¹³C或¹⁴C尿素呼气试验（D错）、粪便幽门螺杆菌抗原检测及血清学检查（E错）等。其中¹³C或¹⁴C尿素呼气试验检测幽门螺杆菌敏感性及特异性高而无需胃镜检查，患者依从性好，准确性较高，可作为根除治疗后复查的首选方法；血清学检查阳性仅提示近期是否感染过幽门螺杆菌。","","N"],["2006-N122",27,"第二节 慢性胃炎","慢性胃炎Hp检测",2006,122,"B","","作为幽门螺杆菌根除治疗后复查的首选方法是",[["A","胃组织学检查"],["B","快速尿素酶试验"],["C","幽门螺杆菌培养"],["D","¹⁴C尿素呼气试验"],["E","血清学检查"]],"D","非侵入性检查不需要胃镜就能进行，包括¹³C或¹⁴C尿素呼气试验、粪便幽门螺杆菌抗原检测及血清学检查等（P345）。其中¹³C或¹⁴C尿素呼气试验（D对）检测幽门螺杆菌敏感性及特异性高而无需胃镜检查，患者依从性好，准确性较高，可作为根除治疗后复查的首选方法；血清学检查（E错）虽也不需要胃镜就能进行，但仅提示近期是否感染过幽门螺杆菌，故不能作为根除治疗后复查的首选方法。侵入性检查方法（十版内科学P361）是指必须通过胃镜取胃黏膜活组织进行检测，为有创检查，故不作为根除治疗后复查的首选方法，包括快速尿素酶试验（B错）、胃组织学检查（A错）及幽门螺杆菌培养（C错）等。","","N"],["2006-N123",60,"第一节 库欣综合征","异位ACTH综合征",2006,123,"B","","引起异位性ACTH综合征的原因是",[["A","垂体ACTH微腺瘤"],["B","小细胞性肺癌"],["C","肾上腺皮质腺瘤"],["D","肾上腺皮质癌"],["E","肾上腺皮质结节状增生"]],"B","异位ACTH综合征（P723）是指垂体外的恶性肿瘤分泌ACTH刺激肾上腺皮质增生从而分泌过量皮质醇。异位ACTH综合征主要见于燕麦细胞支气管肺癌（约占半数）（B对）和不同部位的类癌。另外，胰岛癌、甲状腺髓样癌、嗜铬细胞瘤、神经母细胞瘤、黑色素瘤等，肺腺癌、鳞状细胞癌和肝癌也可引起。垂体ACTH微腺瘤（P699）（A错）约见于80%库欣病患者，是引起库欣病的主要原因。肾上腺皮质腺瘤（C错）、肾上腺皮质腺癌（D错）和肾上腺皮质结节状增生（E错）均属于不依赖ACTH的综合征（P699）。","","N"],["2006-N124",60,"第一节 库欣综合征","库欣病",2006,124,"B","","引起Cushing病的原因是",[["A","垂体ACTH微腺瘤"],["B","小细胞性肺癌"],["C","肾上腺皮质腺瘤"],["D","肾上腺皮质癌"],["E","肾上腺皮质结节状增生"]],"A","Cushing综合征是指各种病因造成肾上腺分泌过多皮质醇所致疾病的总称。其中Cushing病最多见，是指垂体分泌ACTH亢进引起的临床类型。在库欣病病因中垂体微腺瘤（A对）占80%，大腺瘤占10%，无腺瘤占10%（仅表现为ACTH增生）。异位ACTH综合征是指垂体外的恶性肿瘤（B错）分泌ACTH刺激肾上腺皮质增生从而分泌过量皮质醇。肾上腺皮质腺瘤（C错）、肾上腺皮质癌（D错）和肾上腺皮质结节状增生（E错）均属于不依赖ACTH的综合征，不是引起Cushing病的病因。","","N"],["2006-N125",31,"","",2006,125,"B","","氟尿嘧啶属于化疗药物的",[["A","细胞毒素类"],["B","抗代谢类"],["C","抗生素类"],["D","生物碱类"],["E","激素类"]],"B","5-氟尿嘧啶属于抗肿瘤药物中的抗代谢类（B对），可竞争性抑制脱氧胸苷酸合成酶，阻止脱氧尿苷酸甲基化为脱氧胸苷酸，从而影响DNA的合成。其他常用化疗药物有：（1）细胞毒素类：烷化剂（卡莫司汀、卡氮芥、洛莫司汀、环磷酰胺等）；（2）抗代谢类：去氧氟鸟苷、氟铁龙等；（3）抗生素类：放线菌素D、多柔比星、丝裂霉素等；（4）生物碱类：三尖杉酯碱、喜树碱、紫杉醇、长春新碱等；（5）激素类：氨鲁米特、甲他孕酮、他莫昔芬等。","","N"],["2006-N126",40,"第五节 肾病综合征","细胞毒药物",2006,126,"B","","环磷酰胺属于化疗药物的",[["A","细胞毒素类"],["B","抗代谢类"],["C","抗生素类"],["D","生物碱类"],["E","激素类"]],"A","环磷酰胺属于化疗药物的细胞毒素类（A对），通过氮芥基团作用于DNA和RNA、酶、蛋白质，可导致细胞死亡。临床常用化疗药物有：（1）细胞毒素类：烷化剂（卡莫司汀、卡氮芥、洛莫司汀、环磷酰胺等）（A对）；（2）抗代谢类：去氧氟鸟苷、氟铁龙、5-氟尿嘧啶等；（3）抗生素类：放线菌素D、多柔比星、丝裂霉素等；（4）生物碱类：三尖杉酯碱、喜树碱、紫杉醇、长春新碱等；（5）激素类：氨鲁米特、甲他孕酮、他莫昔芬等。环磷酰胺为烷化剂，通过氮芥基团作用于DNA和RNA、酶、蛋白质，可导致细胞死亡。","","N"],["2006-N141",23,"第一节 感染性心内膜炎","易患因素",2006,141,"X","","下列哪些是易患感染性心内膜炎的高危病变",[["A","主动脉瓣狭窄"],["B","单纯性房间隔缺损"],["C","动脉导管未闭"],["D","室间隔缺损"]],"CD","感染性心内膜炎是指由细菌、真菌和其他微生物直接感染而产生心瓣膜或心室壁内膜的炎症。瓣膜为最常受累部位。急性感染性心内膜炎目前发病原因不明，多由毒力较强的化脓菌引起，其中大多为金黄色葡萄球菌，其次为化脓链球菌。此型心内膜炎多发生在本来正常的心内膜上。亚急性感染性心内膜炎常发生在原有心瓣膜病变或其他心脏病的基础之上，如室间隔缺损（D对）、动脉导管未闭（C对）、法洛四联症和主动脉缩窄（注：不是主动脉瓣狭窄）。但是在压差较小或血流缓慢的地方发生较少，如房间隔缺损（B错）、巨大室间隔缺损、瓣膜狭窄（A错）等。","","N"],["2006-N142",4,"第二节细菌性肺炎","葡萄球菌肺炎临床表现",2006,142,"X","","下列选项中，属于血源性金黄色葡萄球菌肺炎特点的是",[["A","两肺多发性结节阴影，以两下肺为著"],["B","可有脓疡、空洞形成，且变化迅速"],["C","在形成大片渗出时，经常有支气管充气征"],["D","早期的肺部体征明显，可出现管状呼吸音"]],"AB","血源性金黄色葡萄球菌肺炎是指其他部位的葡萄球菌经血循环抵达肺部，引起肺部多发性病变，X线片可见多发性结节阴影，病变以两下肺为著（A对）。血源性金黄色葡萄球菌肺炎早期并无明显肺部体征（D错），常与严重的中毒症状和呼吸道症状不平行，然后可出现两肺散在性湿啰音。随着病情发展，胸片可见肺段或肺叶有空洞形成，并且变换迅速（B对）。X线片上出现大片渗出影，在实变阴影中可见支气管充气征（十版内科学P50）（C错）是肺炎链球菌肺炎的特征，而非血源性金黄色葡萄球菌肺炎特点。","","N"],["2006-N143",26,"第一节 胃食管反流病","胃食管反流病治疗",2006,143,"X","","胃食管反流病的治疗目的是",[["A","控制症状"],["B","减少复发"],["C","防止食管狭窄"],["D","避免食管穿孔"]],"ABC","胃食管反流病治疗目的在于控制症状（A对）、治愈食管炎、减少复发（B对）和防治并发症，其中主要防治食管狭窄（C对）和Barrett食管，本病并发食管穿孔较罕见（D错）。","","N"],["2006-N144",40,"第七节 慢性肾小球肾炎","积极控制高血压和减少尿蛋白",2006,144,"X","","下列具有肾保护作用，能延缓肾功能恶化的降压药物有",[["A","贝那普利"],["B","氯沙坦"],["C","氨氯地平"],["D","阿替洛尔"]],"AB","能够延缓肾功能恶化的降压药，主要为两类：ACEI类如贝那普利（A对）及ARB类如氯沙坦（B对）。二者除降低全身性高血压作用外，由于其扩张肾小球出球小动脉的作用强于入球小动脉，可直接降低肾小球内高压力，从而缓解肾小球内高压、高灌注、高滤过，有助于减少蛋白尿，保护肾功能，并可抑制肾组织细胞炎症反应及硬化（十版内科学P489）。氨氯地平（C错）是钙通道阻滞剂，阿替洛尔（D错）是β受体阻滞剂，两者无上述作用。","","N"],["2006-N145",52,"第二节 急性白血病","ALL诱导缓解治疗",2006,145,"X","","L-ASP治疗ALL时的主要不良反应有",[["A","肝功能损害"],["B","肾功能损害"],["C","胰腺炎"],["D","过敏反应"]],"ACD","L-ASP（左旋门冬氨酸）治疗ALL（急性淋巴细胞白血病）时的主要不良反应有肝功能损害（A对）、胰腺炎（C对）、凝血因子及清蛋白合成减少和过敏反应（D对），肾功能损害少见（B错）。肾功能损害为高剂量甲氨喋呤的不良反应。","","N"],["2006-N146",60,"第五节 嗜铬细胞瘤","血、尿儿茶酚胺及其代谢物测定",2006,146,"X","","可以干扰嗜铬细胞瘤患者血、尿儿茶酚胺测定结果的有",[["A","摄入咖啡"],["B","服用普萘洛尔"],["C","休克"],["D","低血糖"]],"ABCD","血、尿儿茶酚胺测定有助于诊断嗜铬细胞瘤，但实验结果受许多因素干扰：1.摄入咖啡（A对）、可乐类饮料及左旋多巴、拉贝洛尔（柳胺苄心定）、普萘洛尔（心得安）（B对）、四环素等药物可导致假阳性结果；2.休克（C对）、低血糖（D对）、高颅内压可使内源性儿茶酚胺增高。","","N"],["2007-N51",16,"第七节 抗心律失常药物的合理应用","药物",2007,51,"A","","下列选项中，不属于胺碘酮抗心律失常主要电生理效应的是",[["A","显著减慢Vmax"],["B","抑制电压依赖性钾通道"],["C","延长动作电位时限"],["D","延长有效不应期"]],"A","显著减慢Vmax（A错，为本题正确答案）的是ⅠA类、ⅠC类抗心律失常药的作用特点。胺碘酮是多通道阻滞剂，可表现出Ⅰ～Ⅳ类所有抗心律失常药物的药理作用。抑制电压依赖性钾通道，抑制慢、快成分的延迟整流钾电流，特别是开放状态的缓慢激活延迟整流钾通道（IKs）（B对），延长各部心肌组织的动作电位时限（C对）及延长有效不应期（D对），有利于消除折返激动。胺碘酮对Vmax影响作用较弱，主要作用于通道失活态，特点是心率快时阻滞作用强。","","N"],["2007-N52",21,"第四节 二尖瓣反流","二尖瓣反流病因",2007,52,"A","","下列选项中，不属于常见的急性二尖瓣关闭不全病因的是",[["A","感染性心内膜炎"],["B","急性心肌梗死"],["C","心脏瓣膜手术"],["D","扩张型心肌病"]],"D","扩张型心肌病因左心室逐渐扩大，可导致相对性二尖瓣关闭不全，为一缓慢进展性过程，不属于急性二尖瓣关闭不全（D错，为本题正确答案）。急性二尖瓣关闭不全主要是由各种原因导致的瓣膜本身或瓣周结构破坏所引起。急性感染性心内膜炎（A对）若累及二尖瓣，损伤二尖瓣或其附属结构，可造成急性二尖瓣关闭不全。急性心肌梗死（B对）累及乳头肌，导致其缺血坏死可使瓣膜收缩功能障碍，导致不同程度的二尖瓣脱垂伴关闭不全。心脏瓣膜手术（C对）若操作不当亦可损伤二尖瓣或其附属结构，造成急性二尖瓣关闭不全。","","N"],["2007-N53",19,"第二节 扩张型心肌病","扩张型心肌病临床表现",2007,53,"A","","下列关于扩张型心肌病临床表现的叙述，正确的是",[["A","起病可急也可缓"],["B","可在成年人任何年龄发病"],["C","一般不发生血栓栓塞"],["D","可早期发生全心扩大"]],"B","扩张型心肌病（DCM）是一类以左心室或双心室扩大伴收缩功能障碍为特征的心肌病，本病可在不同种族、不同性别、成年人任何年龄发病（B对），但以中年居多。本病起病缓慢（A错），早期可无症状，经过一段时间后症状逐步出现，这一过程有时可达10年以上。可有脑、心、肾、肺等处的栓塞，发生栓塞可以有受累相应脏器疼痛等表现（C错）。本病早期仅可表现为左心室轻度扩大，此时收缩功能尚未显示异常，后期各心腔均扩大，以左心室扩大为著（D错）。","","N"],["2007-N54",17,"第四节 急性冠状综合征","不稳定型心绞痛和非ST段抬高型心肌梗死诊断",2007,54,"A","","当患者发作剧烈胸痛时，下列哪项检查结果正常，可排除急性冠脉综合征的诊断",[["A","CK-MB"],["B","肌钙蛋白"],["C","超声心动图"],["D","18导联体表心电图"]],"D","急性冠脉综合征（ACS）是一组由急性心肌缺血引起的临床综合征，动脉粥样硬化不稳定斑块破裂或糜烂导致冠状动脉内血栓形成是主要病理基础。当患者发作剧烈胸痛，心肌缺血时，CK-MB（A错）、肌钙蛋白（B错）、超声心动图（C错）均可表现为正常；急性心肌梗死时，血清心肌坏死标记物异常也有一个过程，如肌钙蛋白I（cTnI）或T（cTnT）起病3～4小时后升高，CK-MB（肌酸激酶同工酶）在起病后4小时内增高。故以上几种检查结果正常并不能排除急性冠脉综合征（包含急性心肌梗死）的诊断。18导联心电图较12导联心电图增加了右胸导联及后胸壁导联，可比较全面反映心脏电生理活动，在心肌细胞缺血早期就会出现明显异常改变，因此当患者发作急性胸痛，18导联体表心电图（D对）正常时，可基本排除急性冠脉综合征。","","N"],["2007-N55",21,"第三节 二尖瓣狭窄","二尖瓣狭窄临床表现",2007,55,"A","","下列关于二尖瓣狭窄所致大量咯血机理的叙述，正确的是",[["A","左心房压力突然增高导致支气管静脉破裂"],["B","肺动脉压力持续增高导致肺小动脉破裂"],["C","肺静脉压力持续增高导致静脉破裂"],["D","肺泡毛细血管压力增高导致破裂"]],"C","二尖瓣狭窄引起咯血有两种情况，一种是急性左心衰导致肺泡毛细血管血液外渗，出现的粉红色泡沫痰；另一种是由于左心房压力突然增高，肺静脉压增高，导致支气管静脉破裂出血（A对），常表现为大咯血。大咯血与肺小动脉破裂（B错）和肺静脉破裂（C错）无关，而肺泡毛细血管破裂一般与痰中带血或血痰有关（D错）。本题答案应为A，但参考答案为C。","","N"],["2007-N56",16,"第八节 心律失常的介入治疗和手术治疗","适应证",2007,56,"A","","下列病症中，不能采用射频消融治疗的是",[["A","频发室性期前收缩"],["B","室性心动过速"],["C","心房颤动"],["D","非阵发性交界区心动过速"]],"D","非阵发性交界区心动过速（D错，为本题正确答案）的发生机制与房室交界区组织自律性增高或触发活动有关，心动过速发作开始与中止时心率逐渐变化，有别于阵发性心动过速，故被称为“非阵发性”，可有病理性的，亦有生理性的可能，若患者耐受性良好，仅需密切观察和治疗原发病，无需射频消融治疗。房室折返性心动过速、房室结折返性心动过速、房速和频发室性期前收缩（A对）、无器质性心脏病证据的室性心动过速（B对）呈反复发作性，或合并有心动过速心肌病，或者血流动力学不稳定者可用射频消融治疗。发作频繁、症状明显的心房颤动（C对）用射频消融治疗。","","N"],["2007-N57",9,"第一节 肺血栓栓塞症","肺血栓栓塞症诊断",2007,57,"A","","放射性核素主要用于诊断的病症是",[["A","肺泡炎"],["B","肺泡内出血"],["C","结节病"],["D","肺栓塞"]],"D","应用放射性核素肺作肺通气/血流灌注检查，主要用于诊断肺栓塞（D对）和血管病变，可以显示病变肺段血流灌注缺损，与通气显像不匹配。肺泡炎（A错）为肺泡内渗出性病变，主要通过影像学检查进行诊断；肺泡内出血（B错）的肺泡灌洗液内可发现大量充满含铁血黄素的巨噬细胞，故主要通过肺泡灌洗或肺活检诊断；结节病（C错）为肺间质性疾病，主要通过影像学检查和组织学活检进行确诊。","","N"],["2007-N58",13,"第三节 慢性呼吸衰竭","慢性呼吸衰竭病因",2007,58,"A","","血气分析结果显示：PaO₂下降，PaCO₂升高，pH下降或正常，HCO₃⁻升高。符合的疾病是",[["A","脊柱后侧突"],["B","吸入异物"],["C","支气管哮喘急性发作"],["D","脑干出血"]],"A","血气分析PaO₂下降，PaCO₂升高，HCO₃⁻升高，且pH下降或正常，诊断为呼吸性酸中毒合并代谢性碱中毒。呼吸性酸中毒合并代谢性碱中毒常发生于慢性呼吸衰竭，机体因长期气道阻塞，导致CO₂潴留，肾脏代偿性地减少HCO₃⁻的排出，导致体内的HCO₃⁻维持在一个较高的水平，以维持pH相对稳定，这种代偿性为慢性长期的过程。脊柱后侧突（A对）可引起胸廓畸形，导致气管扭曲，发生慢性气道阻塞，可出现该血气分析结果。吸入异物（B错）及支气管哮喘急性发作（C错）都是急性气道受阻，不会引起呼酸合并代碱。脑干出血（D错）为急性中枢病变，不会产生慢性代偿性病理生理变化。","","N"],["2007-N59",13,"第三节 慢性呼吸衰竭","慢性呼吸衰竭临床表现",2007,59,"A","","下列关于慢性缺氧表现的叙述，正确的是",[["A","抽搐、昏迷"],["B","继发性红细胞增多症"],["C","呼吸频数"],["D","肝脾肿大"]],"B","慢性缺氧时，组织氧分压降低可使肾脏促红细胞生成素合成增加，刺激骨髓造血，红细胞增生，引起继发性红细胞增多症（B对）。慢性缺氧多表现为注意力不集中或定向功能障碍（二版八年制内科学P167），抽搐、昏迷（A错）为急性缺氧的表现。低PaO₂（＜60mmHg）作用于颈动脉体和主动脉体的化学感受器，可反射性兴奋呼吸中枢，增强呼吸运动，使呼吸频率增快甚至出现呼吸窘迫，当缺氧程度缓慢加重时，这种反射性兴奋呼吸中枢的作用将变得迟钝，缺氧对呼吸中枢的直接作用是抑制作用，当PaO₂＜30mmHg时，此作用可大于反射性兴奋作用而使呼吸抑制，因此呼吸频数（C错）不是慢性缺氧的表现。缺氧可直接或间接损害肝细胞，使丙氨酸氨基转移酶增高，引起肝功能异常，但一般不引起肝脾肿大（D错）（二版八年制内科学P167）。","","N"],["2007-N60",12,"第一节 急性呼吸窘迫综合征","急性呼吸窘迫综合征病理生理",2007,60,"A","","ARDS时出现肺泡Ⅱ型细胞损伤，表面活性物质减少，可引起的病理改变是",[["A","肺不张、肺泡萎陷"],["B","肺水肿"],["C","肺内含铁血黄素沉着"],["D","肺小叶间隔增宽"]],"A","肺表面活性物质的主要作用是降低肺泡液-气界面的表面张力，减小肺泡的回缩力，降低吸气阻力，维持肺泡稳定性，防止肺水肿。ARDS时，出现肺泡Ⅱ型细胞损伤，肺泡表面活性物质减少，肺泡回缩力增加，导致肺不张、肺泡萎陷（A对）；肺泡表面活性物质减少，也可导致肺水肿（B错），但其为肺毛细血管内皮细胞和肺泡上皮细胞受损所致，不为最佳选项；肺小叶间隔增宽（D错）为肺水肿的继发性改变；肺内含铁血黄素沉着（C错）为慢性肺淤血的特征性表现。","","N"],["2007-N61",4,"第五节 肺真菌病","肺真菌病实验室和其他检查",2007,61,"A","","关于肺部真菌感染，下列选项中，对诊断最有意义的是",[["A","痰中培养出真菌"],["B","咽拭子涂片发现真菌"],["C","痰涂片找到真菌"],["D","胸水中培养出真菌"]],"D","肺部真菌感染后，X线影像表现无特征性，病理学诊断为肺真菌病的金标准，但其可操作性不强，故常选择真菌培养。由于真菌广泛存在于土壤、水、空气和有机物中，健康人咽喉部、痰中均可有真菌存在，因此痰中培养出真菌（A错）、痰涂片找到真菌（C错）与咽拭子涂片发现真菌（B错）均可能为取材时真菌污染所致，而对肺部真菌感染的诊断价值不大。正常人胸膜腔为无菌体腔，内无真菌，故胸水中培养出真菌最有诊断意义（D对）。","","N"],["2007-N62",10,"","",2007,62,"A","","慢性肺心病心功能代偿期除了有COPD的临床表现外，还可有的体征是",[["A","肝颈静脉反流征阳性"],["B","剑突下心脏收缩期搏动"],["C","舒张期奔马律"],["D","腹腔积液征"]],"B","慢性肺心病心功能代偿期主要是不同程度发绀和原发肺疾病的体征，包括肺气肿的体征，双肺呼吸音减弱，干、湿性啰音，以及肺动脉瓣区第二心音亢进（P₂＞A₂），三尖瓣区收缩期杂音或剑突下心脏搏动增强（B对）等肺动脉高压和右心室肥厚的体征，胸内压增高时阻碍腔静脉回流可有颈静脉充盈甚至怒张，但此时心功能尚可代偿，不会出现肝颈静脉反流征阳性。当慢性肺心病失代偿后，则会出现肝大且有压痛、肝颈静脉反流征阳性（A错）、舒张期奔马律（C错）、下肢水肿、腹腔积液征等右心衰竭的体征（D错）。","","N"],["2007-N63",25,"","",2007,63,"A","","下列选项中，属于内脏性腹痛特点的是",[["A","疼痛部位不确切，接近腹中线"],["B","疼痛程度剧烈而持续"],["C","可有局部腹肌强直"],["D","疼痛可因体位变化而加重"]],"A","腹痛的发生机制分3种，即内脏性腹痛、躯体性腹痛和牵涉痛。本题主要鉴别内脏性腹痛和躯体性腹痛的特点。内脏性腹痛是腹内某一器官的痛觉信号主要由交感神经传入脊髓，其疼痛特点为：疼痛部位不确切，接近腹中线（A对）；疼痛感觉模糊，多为痉挛、不适、钝痛、灼痛；常伴恶心、呕吐、出汗等自主神经兴奋症状。疼痛程度剧烈而持续（B错）、可有局部腹肌强直（C错）、疼痛可因体位变化而加重（D错）均为躯体性腹痛的特点。","","N"],["2007-N64",29,"第二节 结核性腹膜炎","腹痛",2007,64,"A","","结核性腹膜炎腹痛的特点是",[["A","早期腹痛明显"],["B","呈持续性绞痛"],["C","疼痛多位于脐周、下腹"],["D","呈转移性疼痛"]],"C","腹痛是结核性腹膜炎的常见症状之一，早期腹痛不明显（A错），以持续性隐痛或钝痛多见，当并发不完全肠梗阻时，常有阵发性绞痛。持续性绞痛（B错）多见于发生完全性绞窄性肠梗阻时，结核性腹膜炎少见。少数可始终没有腹痛，疼痛多位于脐周或下腹部（C对），有时有全腹痛。腹痛除由腹膜炎本身引起外，也常与伴有的活动性肠结核、肠系膜淋巴结结核或盆腔结核有关。转移性疼痛多见于阑尾炎（D错），本病一般无转移性疼痛。","","N"],["2007-N65",29,"第一节 肠结核","肠结核诊断",2007,65,"A","","对高度怀疑肠结核的病例中，下列最有利于临床诊断的是",[["A","抗结核治疗2～6周有效"],["B","PPD试验阳性"],["C","有肠外结核"],["D","有腹痛、腹泻、右下腹压痛"]],"A","肠结核与克罗恩病的诊断与鉴别有时相当困难，对于高度怀疑肠结核者可试行抗结核治疗。若抗结核治疗数周（2～6周）后（A对）症状明显改善，结肠镜检查病变明显改善或好转，可做出肠结核的临床诊断。对于成年患者来说，PPD试验（B错）阳性仅表示既往感染过结核杆菌或接种过卡介苗，不能诊断现阶段是否感染，对于阴性结果者，除表示未受结核感染外，尚应考虑以下几种情况：1、结核杆菌感染后未产生变态反应或是应用糖皮质激素等免疫抑制剂患者；2、百日咳、营养不良、麻疹等患者结核菌素反应可暂时消失；3、严重结核病对结核菌素无反应或仅有弱阳性（十版内科学P75）。所以PPD试验不能用于确诊肠结核。患者有肠外结核（C错）不能确诊肠结核，只能说明有结核分枝杆菌感染。肠结核缺乏特异性症状和体征，不能仅靠临床表现来确诊肠结核，腹痛、腹泻、右下腹压痛（D错）也可见于克罗恩病、右半结肠癌等其他疾病。综上，BCD项均有利于诊断肠结核，但不能确诊。","","N"],["2007-N66",28,"第一节 消化性溃疡","PPI",2007,66,"A","","非甾体抗炎药（NSAID）引起的消化性溃疡，当不能停用NSAID时，首选的治疗药物是",[["A","雷尼替丁"],["B","硫糖铝"],["C","西沙必利"],["D","奥美拉唑"]],"D","对服用NSAID后出现的溃疡，如情况允许应立即停用NSAID，如病情不允许可换用对黏膜损伤少的NSAID如特异性COX-2抑制剂（如塞来昔布）。对已停用NSAID者，可予常规剂量常规疗程的H₂RA或PPI治疗；对不能停用NSAID者，应首选PPI（如雷贝拉唑）治疗（D对），H₂RA（如雷尼替丁）疗效差，不作为首选（A错）。硫糖铝（B错）是弱碱性抗酸剂，能中和胃酸，短暂缓解疼痛，目前更多被视为黏膜保护剂，疗效较PPI差很多，一般不应用于NSAID相关性溃疡的预防。西沙必利（C错）是一种胃肠动力药，可作为GERD（胃食管反流病）的辅助治疗药物，对促进溃疡愈合作用不大，也不用于预防NSAID所致溃疡。","","N"],["2007-N67",26,"第一节 胃食管反流病","食管外症状",2007,67,"A","","下列胃食管反流病的临床表现中，不属于食管外刺激症状的是",[["A","咳嗽"],["B","哮喘"],["C","胸痛"],["D","声嘶"]],"C","本题主要鉴别胃食管反流病的食管症状和食管外症状。咳嗽（A对）、声嘶（D对）、哮喘（B对）为反流物刺激或损伤咽喉部及气管、支气管等食管外组织或器官引起的食管外症状。胸痛（C错，为本题正确答案）为反流物刺激食管引起的食管非典型症状。","","N"],["2007-N68",50,"第一节 溶血性贫血概述","溶血性贫血发病机制",2007,68,"A","","下列可以引起原位溶血的疾病是",[["A","遗传性球形细胞增多症"],["B","海洋性贫血"],["C","骨髓增生异常综合征"],["D","G6PD缺乏症"]],"C","根据红细胞破坏的部位不同，溶血可以分为血管内溶血和血管外溶血两种类型。血管内溶血的溶血部位在血管内，血管外溶血的溶血部位主要为脾脏，也见于骨髓内，骨髓为红细胞的生成部位，发生于骨髓内的溶血，称为原位溶血。骨髓增生异常综合征（MDS）因造血有缺陷，幼红细胞在成熟前已在骨髓内破坏，可引起原位溶血（C对）。遗传性球形细胞增多症（十版内科学P561）（A错）是红细胞膜缺陷引起的溶血性贫血，病理基础为红细胞膜蛋白基因异常，致膜骨架蛋白缺陷，细胞膜脂质丢失，细胞表面积减少，细胞球形变，球形红细胞的变形性和柔韧性降低，当通过脾脏时容易被破坏而出现溶血。海洋性贫血又称地中海贫血（十版内科学P563），是珠蛋白异常引起的溶血性贫血，其中ɑ珠蛋白生成障碍性贫血系因老化的红细胞在脾脏内被破坏，不属于原位溶血，而β珠蛋白生成障碍性贫血（十版内科学P564）时红系前体细胞在骨髓内破坏，属于原位溶血（B对）。葡萄糖-6-磷酸脱氢酶（G6PD）缺乏症（十版内科学P562）（D错）是遗传性红细胞酶缺乏性溶血性贫血，既有血管内溶血，也有血管外溶血（脾脏）。故本题的答案应为BC，原参考答案仅为C。","","N"],["2007-N69",52,"第二节 急性白血病","中枢神经系统",2007,69,"A","","中枢神经系统白血病最常发生于急性白血病的阶段是",[["A","起病时"],["B","缓解时"],["C","复发时"],["D","耐药时"]],"B","急性淋巴细胞白血病是最易发生中枢神经系统浸润的白血病类型，可发生于疾病各时期，尤其是治疗后缓解期（B对）。","","N"],["2007-N70",53,"第二节 非霍奇金淋巴瘤","套细胞淋巴瘤",2007,70,"A","","套细胞淋巴瘤细胞的表面标志，除CD5（+）外，还应有",[["A","CD3（+）"],["B","CD4（+）"],["C","CD20（+）"],["D","CD30（+）"]],"C","套细胞淋巴瘤起源于B淋巴细胞，细胞免疫表型为CD20（+）、CD5（+）和CyclinD1（+）（C对）。而CD3（+）（A错）和CD4（+）（B错）是T淋巴细胞的表面标记（十版内科学P596）。CD30（+）（D错）是间变性大细胞淋巴瘤的表面标志（十版内科学P596）。","","N"],["2007-N71",59,"第一节 甲状腺功能亢进症","ATD副作用",2007,71,"A","","抗甲状腺药物因白细胞减少而停药，因此在治疗时白细胞总数不能低于",[["A","2.0×10⁹/L"],["B","2.5×10⁹/L"],["C","3.0×10⁹/L"],["D","3.5×10⁹/L"]],"C","硫脲类是最常用抗甲状腺药，在使用硫脲类药物时，粒细胞缺乏症为最严重不良反应。10版教材观点认为外周血白细胞低于3×10⁹/L（C对）或中性粒细胞低于1.5×10⁹/L应考虑停药，并用升白细胞药物。","","N"],["2007-N72",60,"第一节 库欣综合征","不依赖ACTH的库欣综合征",2007,72,"A","","不依赖ACTH的Cushing综合征的病因是",[["A","垂体微腺瘤"],["B","肾上腺皮质癌"],["C","小细胞肺癌"],["D","胸腺癌"]],"B","库欣综合征（Cushing综合征）为各种病因造成肾上腺分泌过多糖皮质激素（主要是皮质醇）所致病症的总称，按病因分为依赖ACTH和不依赖ACTH的库欣综合征。1.不依赖性ACTH的综合征包括：①肾上腺皮质腺瘤；②肾上腺皮质癌（B对）；③不依赖ACTH的双侧肾上腺结节性增生。２.依赖性ACTH的库欣综合征：①Cushing病：垂体多有微腺瘤（A错），少数为大腺瘤，也有未能发现肿瘤者；②异位ACTH综合征：系垂体以外肿瘤（CD错）分泌大量ACTH，伴肾上腺皮质增生。","","N"],["2007-N73",40,"第一节 肾小球疾病概述","蛋白尿",2007,73,"A","","肾小球性蛋白尿的主要蛋白类型是",[["A","轻链蛋白"],["B","白蛋白"],["C","β₂微球蛋白"],["D","Tamm-Horsfall蛋白"]],"B","肾小球性蛋白尿为肾小球滤过膜受损（机械屏障及电荷屏障），滤过膜通透性增高，血浆蛋白质滤出并超过肾小管重吸收能力所致的蛋白尿。病变较轻时为选择性蛋白尿，尿中出现以白蛋白（B对）为主的中小分子量蛋白质。病变较重时为非选择性蛋白尿，尿中可出现包括IgG在内的大分子蛋白质。尿中出现多量轻链蛋白（A错）为溢出性蛋白尿，主要见于多发性骨髓瘤（十版内科学P601）。尿中出现多量β₂微球蛋白（C错）为肾小管性蛋白尿，主要见于各类肾间质疾病。尿中出现多量Tamm-Horsfall蛋白（D错）为组织性蛋白尿，主要见于肾组织炎症或肾实质损伤。","","N"],["2007-N74",41,"第一节 尿路感染","尿路感染的诊断",2007,74,"A","","尿路感染诊断的最重要依据是",[["A","有尿痛、尿频、尿急症状"],["B","腰痛和肾区叩击痛"],["C","有真性细菌尿"],["D","有白细胞尿"]],"C","尿路感染诊断的最重要依据是有真性细菌尿（C对），真性细菌尿标准包括：①正规清洁中段尿（要求尿停留在膀胱中4～6小时以上）菌定量培养细菌定量培养≥10⁵/ml；②耻骨上膀胱穿刺尿细菌定性培养两次都有细菌（同一菌种）；③如无临床症状，则要求两次细菌培养均为有意义的细菌尿。有些尿路感染可无尿痛、尿频、尿急（A错）等尿路刺激征，而仅有尿培养时出现真性细菌尿即无症状性细菌尿。腰痛和肾区叩击痛（B错）为肾盂肾炎的典型症状，但慢性肾盂肾炎（P493）缓解期可无症状，而仅有细菌尿。白细胞尿（D错）即脓尿对泌尿系感染的诊断有帮助，但不能确诊，因为除膀胱炎等尿路感染外，白带污染、肾结核、支原体及衣原体感染等均可出现白细胞尿。","","N"],["2007-N75",67,"第一节 风湿系统疾病总论","风湿性疾病范畴和分类",2007,75,"A","","下列属于退行性变的疾病是",[["A","强直性脊柱炎"],["B","骨性关节炎"],["C","Reiter综合征"],["D","银屑病关节炎"]],"B","骨关节炎的发生发展是一种长期、慢性、渐进的病理过程。一般认为是多种致病因素包括机械性和生物性因素的相互作用所致，是一种关节软骨退行性变（B对）。强直性脊柱炎（AS）（十版内科学P832）（A错）是脊椎的慢性进行性炎症，以骶髂关节和脊柱附着点炎症为主要病变的疾病，属脊柱关节病。Reiter综合征（C错）属脊柱关节病，为反应性关节炎中的经典，后者是一种发生于某些特定部位（如肠道和泌尿生殖道）感染之后而出现的关节炎，也属和感染相关的风湿病。银屑病关节炎（PSA）（D错）是一种与银屑病相关的炎性关节病，有银屑病皮疹并伴有关节和周围软组织疼痛、肿胀、压痛、僵硬和运动障碍，属脊柱关节病。","","N"],["2007-N76",67,"第一节 风湿系统疾病总论","抗磷脂抗体",2007,76,"A","","下列属于抗磷脂抗体的是",[["A","抗核抗体"],["B","类风湿因子"],["C","狼疮抗凝物"],["D","抗Sm抗体"]],"C","抗磷脂抗体包括抗心磷脂抗体、狼疮抗凝物（C对）、抗β₂-糖蛋白1抗体等。抗核抗体（ANA）（A错）属于抗核抗体谱，ANA检查是SLE的最佳筛选试验。类风湿因子（RF）（B错）对类风湿关节炎的诊断有意义，不属于抗磷脂抗体。抗Sm抗体（D错）属于抗ENA抗体，抗ENA抗体属抗核抗体谱。","","N"],["2007-N77",17,"第四节 急性冠状综合征","症状",2007,77,"A","","男性，70岁，因急性广泛前壁心肌梗死入院。查体：血压95/50mmHg，高枕卧位，双侧中下肺均可闻水泡音，心律整，心率108次/分，可闻S₃奔马律，四肢末梢皮温正常。胸片示：心脏不大，主动脉迂曲钙化，两肺门阴影增大、模糊。按Killip分级，该患者心功能应属于",[["A","Ⅰ级"],["B","Ⅱ级"],["C","Ⅲ级"],["D","Ⅳ级"]],"C","老年男性患者，急性广泛前壁心肌梗死入院。收缩压＞90mmHg，心率108次/分（正常值：60～100次/分）。患者高枕卧位，双侧中下肺均可闻水泡音（超过肺部50%以上），两肺门阴影增大、模糊。可闻S₃奔马律（舒张早期奔马律）考虑患者在心梗基础上伴有左心衰竭。四肢末梢皮温正常，提示患者末梢循环良好。休克的诊断不能光靠血压或者其他单一指标，需要综合进行考虑。临床观察中，对于有出汗、兴奋、心率加快、脉压小或尿少等症状者，应疑有休克。若病人出现神志淡漠、反应迟钝、皮肤苍白、呼吸浅快、收缩压降至90mmHg以下及尿少者，则标志病人已进入休克失代偿期（九版外科学P29）。由以上诊断标准可知患者并无心源性休克表现。综上所述：患者Killip分级为Ⅲ级（C对）。","","N"],["2007-N78",17,"第四节 急性冠状综合征","不稳定型心绞痛和非ST段抬高型心肌梗死诊断",2007,78,"A","","男性，58岁，2周来晨练行走300米左右出现胸部闷胀压抑感，放散到咽喉部，有紧缩感，持续5～10分钟，自行停止活动，休息约3～5分钟后缓解。近1周来自觉上一层楼即感上述症状，口含硝酸甘油有效。既往有高血压病25年，高脂血症8年，糖尿病6年。对该患者正确的诊断应是",[["A","劳力型心绞痛"],["B","变异型心绞痛"],["C","初发型心绞痛"],["D","恶化型心绞痛"]],"C","患者既往无心绞痛病史，为近2周来新发，并且在首发症状1～2个月内，很轻的体力活动可诱发（近1周来自觉上一层楼即感上述症状，口含硝酸甘油有效），故属于不稳定心绞痛中的初发型心绞痛（C对）。变异型心绞痛（B错）的发作与活动无关，好发于年轻人，此病主要由冠状动脉痉挛所致，故常用药物为钙通道阻滞剂和硝酸酯类。恶化型心绞痛（D错）指在相对稳定的劳力性心绞痛基础上心绞痛水平逐渐增强（疼痛更剧烈、时间更长或更频繁，按CCS分级至少增加Ⅰ级水平或程度至少CCSⅢ级）。劳力性心绞痛（十版内科学P233）（A错）属于稳定型心绞痛，疼痛发作的程度、频度、性质及诱发因素数周至数月不变。","","N"],["2007-N79",5,"第一节 肺脓肿","肺脓肿诊断",2007,79,"A","","男性，46岁，饮酒后出现发热，体温39.3℃，伴咳嗽、咳少量黄痰，自服“头孢菌素”3天无效，1天前咳出大量脓痰，自觉有臭味，体温降至37.5℃。最可能的诊断是",[["A","支气管扩张"],["B","金葡菌肺炎"],["C","吸入性肺炎"],["D","肺脓肿"]],"D","患者饮酒后出现高热、咳嗽、咳少量黄痰，口服头孢菌素无效，继而咳出大量脓臭痰（提示有厌氧菌感染）后体温下降，故初步诊断为肺脓肿（D对）。肺脓肿起病急，畏寒、高热，体温达39～40℃，伴咳嗽、咳脓性痰，如感染不能及时控制，可于发病的10～14天突然咳出大量脓臭痰及坏死组织后体温逐渐降低；支气管扩张（十版内科学P41）（A错）一般慢性起病，可反复咳嗽、咳大量脓痰、咯血，但痰液多无臭味；金葡菌肺炎（十版内科学P53）（B错）起病多急骤，寒战、高热、胸痛、咳嗽，咳脓性痰，量多，带血丝或呈脓血状；吸入性肺炎（C错）的临床表现与诱发因素和机体的状态有关，一般表现为剧烈咳嗽和呼吸困难，但不会出现大量脓臭痰。","","N"],["2007-N80",2,"第一节 支气管哮喘","动脉血气分析",2007,80,"A","","女性，60岁，慢性咳喘18年，加重1周，血气分析结果如下：pH7.35，PaO₂55mmHg，PaCO₂75mmHg，AB42mmo/L，K⁺2.8mmo/L，Cl⁻80mmo/L。考虑诊断为",[["A","代谢性酸中毒失代偿"],["B","呼吸性酸中毒失代偿"],["C","呼吸性酸中毒伴代谢性酸中毒"],["D","呼吸性酸中毒伴代谢性碱中毒"]],"D","pH正常值为7.35～7.45，题干pH=7.35可知本题患者为代偿性酸碱平衡失调（AB错）。PaCO₂正常值为35mmHg～45mmHg，当PaCO₂值大于45mmHg时为呼吸性酸中毒，当PaCO₂值小于35mmHg时为呼吸性碱中毒，该患者PaCO₂75mmHg，故为呼吸性酸中毒。患者AB（实际碳酸氢盐）=42mmol/L，与SB（标准碳酸氢盐）的正常值（22～27mmol/L）比较，AB＞SB，该情况见于呼吸性酸中毒或者代偿后的代谢性碱中毒。血钾正常值为3.5～5.3mmol/L，题干中K⁺2.8mmo/L，低于正常值，低钾血症时，细胞内K⁺向细胞外转移，同时细胞外的H⁺向细胞内转移，可发生代谢性碱中毒（C错）。故综合分析该患者为呼吸性酸中毒合并代谢性碱中毒（D对）。","","N"],["2007-N81",32,"第二节 肠易激综合征","肠易激综合征药物治疗",2007,81,"A","","男性，35岁，患肠易激综合征5年，近1个月来排便困难，粪便干结，伴失眠、焦虑。下列不宜选用的治疗药物是",[["A","甲基纤维素"],["B","聚乙二醇"],["C","洛哌丁胺"],["D","阿米替林"]],"C","肠易激综合征是一种功能性肠病，并无器质性病变，其药物治疗主要对显著的症状进行对症治疗。治疗药物包括解痉剂、止泻药、泻药、抗抑郁药及肠道微生态制剂等。本例患者属便秘型IBS，可酌情使用泻药如聚乙二醇（B对）、乳果糖、山梨醇及甲基纤维素（A对）等，而使用止泻药如洛哌丁胺（C错，为本题正确答案）会加重便秘。阿米替林（D对）为抗抑郁药，对伴或不伴有明显精神症状者均有一定疗效。","","N"],["2007-N82",30,"第二节 克罗恩病","克罗恩病诊断",2007,82,"A","","男性，30岁，腹痛、腹泻、间断低热3年，结肠镜见回肠末段病变呈跳跃性，见纵行溃疡，溃疡周围黏膜呈鹅卵石样。最可能的诊断是",[["A","溃疡性结肠炎"],["B","溃疡型肠结核"],["C","肠伤寒"],["D","克罗恩病"]],"D","青年男性患者，慢性腹痛、腹泻、间断低热，结肠镜见回肠末端病变呈跳跃性，见纵行溃疡，溃疡周围黏膜呈鹅卵石样，可以得出该患者最可能的诊断是克罗恩病（D对）。溃疡性结肠炎（A错）病变多位于直肠、乙状结肠，呈连续性弥漫性分布，其典型临床表现为黏液脓血便，结肠镜检为多发性浅溃疡，而非纵行溃疡。溃疡型肠结核（B错）好发于回盲部，溃疡沿淋巴管走行方向分布，因此溃疡呈横形而非纵行。肠伤寒（C错）虽然好发于回肠末端，但肠伤寒是由伤寒杆菌引起的急性传染病，其典型临床表现可概括为：伤寒肚子伤寒脸，梯形体温脉搏缓，三五千个白血球，周末脾大玫瑰现。典型伤寒自然病程约为4周，且溃疡呈圆形或椭圆形，与本例不符。需注意克罗恩病在结肠镜下观察病变呈跳跃性，节段性，而非跳跃征，肠结核钡剂灌肠X线呈跳跃征。","","N"],["2007-N83",49,"第一节 再生障碍性贫血","AA诊断标准",2007,83,"A","","男性，25岁，半年来乏力、面色苍白伴牙龈出血，3周来加重，既往体健。查体：皮肤有散在出血点，浅表淋巴结未触及，巩膜无黄染，肝脾未触及。化验血Hb68g/L，RBC2.3×10¹²/L，Ret0.9%，WBC2.1×10⁹/L，Plt28×10⁹/L，髂后骨髓穿刺检查示增生低下。为明确诊断，进一步的检查首选",[["A","白细胞分类计数"],["B","血清铁和铁蛋白测定"],["C","胸骨穿刺"],["D","骨髓活检"]],"C","该患者为青年男性，有乏力、面色苍白等贫血表现，并有牙龈出血表现。查体：皮肤有散在出血点（出血表现），无肝、脾和淋巴结肿大。查血常规示：Hb68g/L（成年男性正常值130～175g/L），RBC2.3×10¹²/L（正常值4.0～5.5×10¹²/L），WBC2.1×10⁹/L（正常为3.5～9.5×10⁹/L），Plt28×10⁹/L（正常为125～350×10⁹/L）（全血细胞减少）。髂后骨髓穿刺活检示增生低下。初步诊断为再生障碍性贫血，但要确诊，必须多部位骨髓穿刺检查提示增生低下。该病例已行髂后骨髓穿刺，因此进一步检查应首选胸骨穿刺（C对）。白细胞分类计数（A错）一般用于感染、白血病等疾病的诊断。血清铁和铁蛋白（B错）一般用于缺铁性贫血的诊断。骨髓活检（D错）是再生障碍性贫血诊断的必要检查手段，但患者已行髂后穿刺活检，应换部位行穿刺活检。","","N"],["2007-N84",40,"第五节 肾病综合征","血栓和栓塞",2007,84,"A","","男性，55 岁，因肾病综合征（病理为膜性肾病）入院治疗，在应用利尿剂和糖皮质激素的治疗过程中突然持续性腰痛，尿量减少，下肢浮肿加重，蛋白尿显著增多伴肉眼血尿，血肌酐较前增高，B超示双肾较前增大。最可能的原因是",[["A","原有肾病加重"],["B","肾静脉血栓形成"],["C","伴发泌尿系感染"],["D","伴发泌尿系肿瘤"]],"B","老年男性患者，病理检查为膜性肾病，应用利尿剂和糖皮质激素的治疗（可增加血液粘稠度）过程中突然持续性腰痛，尿量减少（提示可能肾血运障碍），下肢浮肿加重，蛋白尿、血尿较前加重，血肌酐较前增高，B超示双肾较前增大（提示肾脏可能淤血肿大），考虑肾静脉血栓形成（B对）。膜性肾病好发于中老年男性，极易发生血栓、栓塞并发症，肾静脉血栓发生率可高达40%～50%。血栓形成的原因包括：血液浓缩及高脂血症造成血液粘稠度增加；凝血、抗凝和纤溶系统失衡；血小板过度激活；应用利尿剂及糖皮质激素可进一步加重高凝状态。原有肾病加重（A错）多表现为肾病综合征的表现加重，一般不会出现腰痛及双肾肿大。伴发泌尿系感染（C错）常有发热及尿频、尿急、尿痛的尿路刺激征。若伴发泌尿系肿瘤（D错）常为无痛性肉眼血尿，起病较缓，且多单侧发病。","","N"],["2007-N89",35,"第一节 肝硬化","肝性脑病",2007,89,"A","","急性肝衰竭出现肝性脑病时，不宜选用的治疗是",[["A","应用硫喷妥钠"],["B","过度换气"],["C","降低体温至32℃～33℃"],["D","腹膜透析"]],"D","肝性脑病可由急性肝功能衰竭引起，多无明显诱因，起病数日内即进入昏迷直至死亡，且肝性脑病患者多半有脑水肿及继发于脑水肿的颅内高压，应加强脑细胞的保护并且防治脑水肿。应用硫喷妥钠（A对）可抑制脑代谢，减少氧耗及增加脑对缺氧的耐受力，减轻脑水肿，降低颅内压（巴比妥类可诱发肝性脑病，在肝硬化特别是有严重肝功能减退时应尽量避免使用，但硫喷妥钠属于超短效巴比妥类，对肝性脑病患者损伤较小）。过度换气（B对）目的是使体内CO₂排出，CO₂有扩张血管的作用，当动脉血的CO₂分压每下降1mmHg时，可使脑血流量递减2%，从而使颅内压相应下降。降低体温至32～33℃（C对），使病人维持于亚低温状态，有利于降低脑新陈代谢率，减少脑组织的氧耗量，防止脑水肿的发生与发展，对降低颅内压亦起到一定作用。腹膜透析对血液内代谢产物清除较快，但脑实质、脑脊髓液中代谢产物的清除受血脑屏障的限制，浓度下降较慢，血液和脑脊液之间形成一定的浓度差，血液中水分渗入脑脊液和脑细胞，诱发或加重肝性脑病，不宜应用（D错，为本题正确答案）。","","N"],["2007-N119",15,"第二节 慢性心力衰竭","慢性心力衰竭鉴别诊断",2007,119,"B","","心源性腹水与肝源性腹水的主要鉴别点是",[["A","颈静脉怒张"],["B","下肢水肿"],["C","贫血貌"],["D","腹部移动性浊音"]],"A","心源性腹水是右心衰竭的表现，常合并颈静脉怒张、肝肿大、下肢水肿、静脉压增高等。肝源性腹水也可伴下肢水肿（B错），但不会出现颈静脉怒张（A对）等上腔静脉回流障碍的体征，因颈静脉怒张是血液回流障碍引起的，与肝脏疾病无关。贫血貌（C错）在心源性腹水和肝源性腹水均可出现，对两者的鉴别不具有特征性。腹部移动性浊音（D错）只能提示腹腔积液量˃1000ml，不能提示腹水的原因。","","N"],["2007-N120",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞诊断",2007,120,"B","","尿毒症性心包积液与非特异性心包积液的主要鉴别点是",[["A","颈静脉怒张"],["B","下肢水肿"],["C","贫血貌"],["D","腹部移动性浊音"]],"C","尿毒症性心包积液与非特异性心包积液均可导致大量心包积液，引起心包压塞，出现颈静脉怒张（A错）、肝肿大、下肢水肿（B错）等体循环淤血的表现。非特异性心包炎一般不引起贫血，而尿毒症患者大多伴有不同程度的贫血（C对），其可能原因包括：①合并营养不良性贫血，以缺铁性贫血最常见；②消化道失血、血液透析失血等引起的失血性贫血；③EPO（促红细胞生成素）生成不足；④尿毒症毒素引起的骨髓微环境改变，产生造血障碍；⑤红细胞寿命变短。腹部移动性浊音（D错）只能提示腹腔积液量＞1000ml，不能提示腹水的原因。","","N"],["2007-N121",27,"第二节 慢性胃炎","慢性胃炎病因和发病机制",2007,121,"B","","自身免疫性胃炎的胃酸分泌",[["A","缺乏"],["B","正常或减少"],["C","少量增加"],["D","明显增加"]],"A","自身免疫性胃炎是指由自身免疫机制所致慢性萎缩性胃炎，又称A型胃炎、慢性胃体炎，患者体内产生针对壁细胞或内因子的自身抗体，发生炎症反应导致壁细胞总数减少，胃酸分泌缺乏（A对）。胃酸分泌正常或减少（B错）见于多灶萎缩性胃炎、胃溃疡。胃酸分泌少量增加（C错）见于十二指肠溃疡。胃酸分泌明显增加（D错）见于胃泌素瘤。","","N"],["2007-N122",27,"第二节 慢性胃炎","慢性胃炎病因和发病机制",2007,122,"B","","多灶萎缩性胃炎的胃酸分泌",[["A","缺乏"],["B","正常或减少"],["C","少量增加"],["D","明显增加"]],"B","多灶萎缩性胃炎属于慢性萎缩性胃炎的一种，常表现为胃内多灶性萎缩，病变主要位于胃窦，由于分泌胃泌素（促进壁细胞分泌胃酸）的G细胞（位于胃窦）受损，而分泌胃酸的壁细胞（位于胃体）未受累，因此胃酸分泌正常或减少（B对）。胃酸分泌缺乏（A错）见于自身免疫性胃炎。胃酸分泌少量增加（C错）见于十二指肠溃疡。胃酸分泌明显增加（D错）见于胃泌素瘤。","","N"],["2007-N123",61,"第一节 糖尿病","促胰岛素分泌剂",2007,123,"B","","口服降糖药格列喹酮的主要不良反应是",[["A","低血糖"],["B","乳酸酸中毒"],["C","胃肠反应"],["D","肝、肾损害"]],"A","本题考察口服降糖药的不良反应。格列喹酮属磺酰脲类降糖药，不良反应有低血糖、体重增加、皮肤过敏反应、消化系统和心血管系统症状等，其中低血糖反应为最常见、最重要的不良反应（A对）。乳酸酸中毒（B错）是双胍类降糖药最严重的副作用（十版内科学P736）。胃肠反应（C错）为α-葡萄糖苷酶抑制剂常见不良反应（十版内科学P738）。口服降糖药物一般无明显肝、肾损害（D错），但有些药物对肝肾功能不全者仍应慎用。","","N"],["2007-N124",61,"第一节 糖尿病","α-葡萄糖苷酶抑制剂（AGI）",2007,124,"B","","口服降糖药阿卡波糖的常见不良反应是",[["A","低血糖"],["B","乳酸酸中毒"],["C","胃肠反应"],["D","肝、肾损害"]],"C","本题考察口服降糖药的不良反应。阿卡波糖属于α-葡萄糖苷酶抑制剂，常见不良反应为胃肠反应（C对）。低血糖（A错）是磺脲类（如格列喹酮）和格列奈类最常见不良反应（P737）。乳酸酸中毒（B错）是双胍类降糖药最严重的副作用（十版内科学P736）。口服降糖药物一般无明显肝肾损害（D错），但有些药物对肝肾功能不全者仍应慎用。","","N"],["2007-N141",15,"第二节 慢性心力衰竭","RAAS抑制剂",2007,141,"X","","关于舒张性心力衰竭的治疗原则，下列提法中，正确的有",[["A","积极控制心动过速，增加心室充盈"],["B","尽量降低心脏后负荷，增加心排血量"],["C","应用ACEI、钙拮抗剂，逆转左室肥厚"],["D","合用适量地高辛可提高治疗效果"]],"AC","舒张性心力衰竭的治疗原则根据不同病因有所不同，高血压导致的舒张功能衰竭可适当降低后负荷，而肥厚型心肌病则不能降低后负荷（B错）。当发生舒张性心力衰竭（HFpEF）时，左心室舒张功能减弱，心室顺应性降低，充盈障碍，导致心室舒张末期容量减少，心室收缩末期容量无明显变化（心室收缩功能尚正常），每搏输出量减少，此时需要提高心室的充盈压以维持心室的充盈量，但是当左室舒张末期压力过高时，肺静脉压也随之上升，出现肺淤血肺水肿等左心衰竭临床表现，但此时心排量无明显降低。因此当有明显肺淤血情况时，适当应用利尿剂即适当降低前负荷可缓解肺淤血和外周水肿症状，但不宜过度，避免引起前负荷过度降低而导致低血压，因为有一定的心室压力和容量是舒张功能不全性心力衰竭患者保持相对正常心排量的基础。其他治疗要点包括：ACEI 、ARB 、β受体阻滞剂等治疗，可以逆转左室肥厚，改善心室舒张功能，钙通道拮抗剂可以松弛心肌，维拉帕米和地尔硫䓬虽有一定的负性肌力作用，但能通过减慢心率而改善舒张功能，C选项说法存在争议，因为ACEI能逆转左心室肥厚，但钙拮抗剂不能；积极控制血压，一般要求＜130/90mmHg；血运重建治疗（冠心病患者若有症状性或可证实的心肌缺血，应考虑冠脉血运重建）；对心率快者应控制心率，有房颤患者更应注意心率的控制（A对）；不宜应用正性肌力药物，当同时合并有收缩性心衰时，以治疗后者为主（D错）。","","N"],["2007-N142",4,"第一节 肺炎概述","医院获得性肺炎",2007,142,"X","","慢性呼吸衰竭患者发生院内获得性支气管-肺部感染的最多见的病原菌有",[["A","革兰阴性杆菌"],["B","耐甲氧西林金黄色葡萄球菌"],["C","厌氧菌"],["D","嗜肺军团菌"]],"ABC","医院内肺炎（HAP）是指病人住院期间没有接受有创机械通气，未处于病原感染潜伏期，且入院≥48小时后在医院内新发生的肺炎，呼吸机相关性肺炎（VAP）是指气管插管或气管切开病人，接受机械通气48小时后发生的肺炎及机械通气撤机、拔管后48小时内出现的肺炎。非免疫缺陷病人HAP/VAP通常由细菌感染引起，常见病原菌的分布及其耐药性特点随地区、医院等级、病人人群、暴露于抗菌药物情况不同而异，并且随时间改变。我国HAP/VAP常见的病原菌包括鲍曼不动杆菌、铜绿假单胞菌、肺炎克雷伯杆菌、大肠埃希菌、金黄色葡萄球菌。细菌所致的HAP/VAP中，约80%由6种病原菌引起，包括金黄色葡萄球菌、铜绿假单胞菌、不动杆菌、肺炎克雷伯杆菌、肠杆菌属细菌和大肠埃希菌，肺炎链球菌和流感嗜血杆菌的比例，已不足10%。综合以上信息，本例慢性呼吸衰竭患者发生HAP/VAP的最多见的病原菌有革兰阴性杆菌（A对）、耐甲氧西林金黄色葡萄球菌（B对）、厌氧菌（C对）。但也有相关资料表示，厌氧菌所致肺炎少见，可发生于误吸的非插管患者，如脑卒中、昏迷等，VAP少见。有关HAP的相关知识点，十版内科学有内容更新（P47）。","","N"],["2007-N143",75,"第二节 农药中毒","胆碱受体拮抗药",2007,143,"X","","治疗急性有机磷中毒时，出现“阿托品化”的表现有",[["A","瞳孔扩大"],["B","颜面潮红"],["C","心率减慢"],["D","肺部啰音消失"]],"ABD","阿托品为M胆碱受体拮抗剂，拮抗M胆碱能受体在外周产生的作用，用于治疗M样症状。使用时应特别注意区别阿托品化和阿托品中毒。阿托品化是抢救有机磷农药中毒时，使用阿托品剂量适量或轻微过量。其指征为瞳孔较前扩大（A对）、口干、皮肤干燥、面部潮红（B对）、心率增快（90～100次/分）（C错）和肺湿啰音消失（D对）等。为方便记忆概括为五大表现：一大（瞳孔扩大）；二干（口干、皮肤干燥）；三红（面部潮红）；四快（心率加快）；五消失（肺湿啰音消失）。阿托品中毒是抢救有机磷农药中毒时，使用阿托品过量，其指征为瞳孔明显扩大、神志模糊、烦躁不安、抽搐、昏迷和尿潴留等。注意：瞳孔扩大为阿托品化指征；而瞳孔明显扩大才是阿托品中毒指征。","","N"],["2007-N144",52,"第二节 急性白血病","急性白血病免疫学检查",2007,144,"X","","下列支持急性早幼粒细胞白血病的免疫表型有",[["A","CD13（+）"],["B","CD33（+）"],["C","CD56（+）"],["D","CD68（+）"]],"ABD","CD（白细胞分化抗原）是白细胞分化成熟为不同谱系后以及处于不同分化阶段和活化过程中出现或消失的细胞表面标记，可以根据白血病细胞表达的系列相关抗原确定其来源。急性早幼粒细胞白血病（APL）细胞通常表达CD13（A对）、CD33（B对）和CD117，CD68（D对）在APL患者中表达也较高，它主要参与细胞摄粒作用和溶酶体转运。CD56（C错）是NK细胞的特征标记。","","N"],["2007-N145",64,"","",2007,145,"X","","下列选项中，可引起肥胖的疾病有",[["A","原发性肾上腺皮质功能减退症"],["B","下丘脑综合征"],["C","胰岛素瘤"],["D","多囊卵巢综合征"]],"BCD","肥胖症指体内脂肪堆积过多和（或）分布异常、体重增加，是遗传因素、环境因素等多种因素相互作用所引起的慢性代谢性疾病。按病因分内源性肥胖和外源性肥胖。1.内源性肥胖：主要为某些内分泌疾病所致，如肾上腺皮质功能亢进（Cushing综合征）（十版内科学P709）、下丘脑综合征（B对）、甲状腺功能低下（十版内科学P706）、胰岛素瘤（C对）、多囊卵巢综合征（九版内科学P764）（D对）、单纯性肥胖等。2.外源性肥胖：为摄入过多热量所致，表现为全身脂肪分布均匀，身体各部位无异常改变，常有一定的遗传倾向。原发性肾上腺皮质功能减退症会引起消瘦、体重下降（十版内科学P715）（A错）。","","N"],["2007-N146",44,"第一节 急性肾损伤","血液检查",2007,146,"X","","肾前性急性肾衰竭的特点有",[["A","尿比重＞1.018"],["B","血尿素氮/肌酐＞20"],["C","肾衰指数＞1"],["D","滤过钠分数＞1"]],"AB","急性肾损伤（AKI）以往称为急性肾衰竭（ARF），急性肾损伤分为三类即肾前性、肾性和肾后性。肾前性急性肾衰竭又称为肾前性氮质血症，是指有效循环血量下降所致的功能性肾小球灌注压下降，早期肾实质的结构并无异常变化；在肾脏血供和肾小球灌注压恢复之后，肾小球滤过率（GFR）可恢复正常。主要特点包括：肾脏水钠重吸收增多，尿比重＞1.018（A 对）；血尿素氮/ 肌酐比值明显升高（＞20）（B 对）；早期肾小管对于原尿中钠的重吸收尚正常，因此肾衰指数＜1（C错），滤过钠分数＜1（D错）。","","N"],["2007-N151-L",60,"第五节 嗜铬细胞瘤","嗜铬细胞瘤治疗",2007,151,"A","C","男性，36岁，因持续性血压升高伴阵发性加剧1年，诊断为嗜铬细胞瘤，行手术治疗。嗜铬细胞瘤切除后第1周血压仍高。下列原因中，可能性最小的是",[["A","手术后的应激状态"],["B","原来体内储存的儿茶酚胺较多"],["C","合并原发性高血压"],["D","血容量的变化"]],"D","嗜铬细胞瘤切除后，血压多能恢复正常，但在手术后第1周，血压仍可偏高，其原因可能为：1.手术后患者出现应激状态（A错），导致血压仍然偏高；2.患者原来嗜铬细胞瘤切除前在体内已分泌较多儿茶酚胺，术后第1周，患者体内储存的儿茶酚胺较多（B错），仍可导致血压偏高；3.小部分患者可能合并原发性高血压（C错），或儿茶酚胺长期增多损伤血管；4.肿瘤未完全切除。而与血容量变化关系不大（D对）。","","N"],["2007-N152-L",69,"第一节 系统性红斑狼疮","抗核抗体谱",2007,152,"A","C","女性，20岁，间断低热伴关节痛半年，1周来高热，关节痛加重，轻度头晕查体：血压120/80 mmHg，皮肤无出血点，肝肋下1cm，脾侧位可触及，化验血Hb95 g/L，Ret6.5％，WBC4.2×10⁹/L，Plt76×10⁹/L，尿蛋白（+++），RBC3～8/HP，偶见颗粒管型。为明确诊断，下列血液学检查中最有意义的是",[["A","抗核抗体谱"],["B","抗中性粒细胞胞浆抗体"],["C","抗磷脂抗体"],["D","抗组织细胞抗体"]],"A","患者为青年女性，既往有间断低热（90%的SLE患者在病程中出现各种热型的发热，尤以低、中度热为常见）伴关节痛（关节痛是SLE常见的症状之一）病史半年，近一周来出现高热、关节痛加重，且出现轻度头晕。查体：肝、脾肿大。化验血：血小板减少（正常值125～350×10⁹/L），血红蛋白下降（成年女性正常值115～150g/L），网织红细胞增多（正常值0.5～1.5%）（活动性SLE中血红蛋白下降、白细胞和（或）血小板减少常见）。化验尿：尿蛋白（+++），血尿（RBC正常值0～3/HP），偶见颗粒管型（SLE肾脏受累常见，表现为蛋白尿、血尿、管型尿等）。综上所述，该患者可拟诊为系统性红斑狼疮（SLE）。SLE患者血清中可查到多种抗体，常见的自身抗体为抗核抗体谱、抗磷脂抗体和抗组织细胞抗体。其中抗核抗体谱是筛选结缔组织病的主要试验，抗核抗体谱可见于几乎所有的SLE患者，因此可作为SLE最佳筛选试验（A对）。抗中性粒细胞胞质抗体（ANCA）常用于血管炎的诊断（B错）。抗磷脂抗体主要用于结合SLE临床表现诊断患者是否合并有继发性抗磷脂抗体综合征（C错）。抗组织细胞抗体有助于诊断免疫性血细胞减少（D错）。","","N"],["2007-N166-L",8,"第二节 特发性肺纤维化","特发性肺纤维化诊断",2007,166,"A","C","男性，67岁，慢性咳嗽，咳少量白痰，活动后气短3年，近2月气短加重，痰量较多，为脓性痰。查体：口唇轻度发绀，双下肺可闻及Velcro啰音，有杵状指。根据以上病史、症状和体征特点，对该患者最可能的诊断是",[["A","淋巴样间质性肺炎"],["B","特发性肺纤维化"],["C","巨细胞型间质性肺炎"],["D","慢性阻塞性肺病"]],"B","患者老年男性，慢性病程，咳嗽、少量白痰，活动后气短，进行性加重，查体口唇轻度发绀，双下肺可闻及Velcro啰音，有杵状指，考虑特发性肺纤维化可能性大。特发性肺纤维化（B对）属间质性肺炎，主要表现为活动性呼吸困难，渐进性加重，约半数患者可见杵状指（趾），90%的患者可在双肺基底部闻及吸气末细小的Velcro啰音。Velcro啰音是特发性肺纤维化的特征性啰音，慢性阻塞性肺病（D错）、淋巴样间质性肺炎（A错）、巨细胞型间质性肺炎（C错）患者均无肺纤维化和Velcro啰音。","c1","N"],["2007-N167-L",8,"第二节 特发性肺纤维化","胸部HRCT",2007,167,"A","C","男性，67岁，慢性咳嗽，咳少量白痰，活动后气短3年，近2月气短加重，痰量较多，为脓性痰。查体：口唇轻度发绀，双下肺可闻及Velcro啰音，有杵状指。为了确诊，需做进一步检查，下列哪种检查方法最有利于确诊",[["A","肺功能测定"],["B","支气管肺泡灌洗液检查"],["C","肺通气灌注扫描"],["D","HRCT"]],"D","HRCT（D对）为确诊特发性肺纤维化的重要检查，其准确率高，可以替代外科肺活检。HRCT的典型表现为，病变以胸膜下和基底部分布为主，呈网格改变、蜂窝改变伴或不伴牵拉支气管扩张。肺功能测定（A错）虽然可以检测出限制性通气功能障碍伴弥散功能下降，但无特异性；支气管肺泡灌洗液检查（10版内科学P101）（B错）可进行细胞学、细菌学、生化和炎症介质等的检测，对于了解弥漫性肺部渗出性病变的性质，鉴别ILD具有一定的帮助，但对特发性肺纤维化无诊断意义；肺通气灌注扫描（十版内科学P113）（C错）主要用于确诊肺栓塞，不能确诊特发性肺纤维化。","c1","N"],["2007-N168-L",38,"第一节 消化道出血","消化道出血部位与病因",2007,168,"A","C","男性，47岁，腹胀、纳差半年，6小时前突然呕血约1000ml来急诊，既往HBsAg（+）。查体示P125次/分，BP70/50mmHg，巩膜轻度黄染，肝脾肋下未触及，移动性浊音（+），下肢有可凹性水肿。引起呕血的最可能病因是",[["A","胃癌"],["B","肝硬化"],["C","消化性溃疡"],["D","胆囊结石"]],"B","中年男性患者，腹胀、纳差，既往活动性乙型肝炎病史（乙型肝炎病毒感染为肝硬化最常见的病因），巩膜黄染，移动性浊音（+）（腹水为肝硬化失代偿期最突出的表现），下肢可凹性水肿。据此初步推断可能是由于病毒性肝炎所致失代偿期肝硬化，患者现突发呕血，出血量大，出现休克体征，提示肝硬化并发食管胃底静脉曲张破裂出血（B对）。胃癌（A错）无特异性症状，呈进展性，一般无肝硬化的相应临床表现。消化性溃疡（C错）应有周期性上腹疼痛病史，并发出血时，出血量不大，一般少于500ml，出血较缓慢，80%不经特殊处理便可自行止血。胆囊结石（D错）通常有胆绞痛病史，可出现巩膜黄染，但无腹水及下肢水肿，且其并发胆道出血时，出血量较小，与该患者表现不符。","c2","N"],["2007-N169-L",38,"第一节 消化道出血","积极补充血容量",2007,169,"A","C","男性，47岁，腹胀、纳差半年，6小时前突然呕血约1000ml来急诊，既往HBsAg（+）。查体示P125次/分，BP70/50mmHg，巩膜轻度黄染，肝脾肋下未触及，移动性浊音（+），下肢有可凹性水肿。应首选的处理措施是",[["A","急诊胃镜止血"],["B","剖腹探查"],["C","紧急输血和输液"],["D","三腔二囊管压迫"]],"C","本例肝硬化导致的食管静脉曲张破裂出血，出血量大，来势凶猛，已出现失血性休克状态，应首选的处理措施是紧急输血和输液（C对）。急诊胃镜止血（A错）是目前治疗食管胃底静脉曲张破裂出血的重要手段，一般在休克纠正，患者基本情况稳定后，再进行急诊内镜检查同时进行治疗。剖腹探查（B错）是在不明出血部位并且大量止血药物等其他方法难以有效的止血后才选择应用。三腔二囊管压迫（D错）止血效果肯定，但缺点是患者痛苦大、并发症多（如吸入性肺炎、窒息、食管炎、食管黏膜坏死、心律失常等），由于不能长期压迫，停用后早期再出血率高，目前已不推荐气囊压迫作为首选止血措施，而作为在药物治疗无效的大出血时暂时使用。","c2","N"],["2007-N170-L",40,"第七节 慢性肾小球肾炎","慢性肾小球肾炎诊断",2007,170,"A","C","女性，36岁，1年来乏力、易疲倦、腰部不适，有时下肢浮肿，未检查。2个月来加重，伴纳差，血压增高为160/100mmHg，下肢轻度浮肿。尿蛋白（+），沉渣RBC5～10/Hp，偶见颗粒管型，血化验Hb90g/L，血肌酐400μmol/L最可能的诊断是",[["A","慢性肾盂肾炎"],["B","慢性肾小球肾炎"],["C","肾病综合征"],["D","狼疮性肾炎"]],"B","青年女性患者，乏力、易疲倦、偶有下肢浮肿一年病史（病程较长），出现高血压、下肢浮肿、蛋白尿、血尿（典型的肾炎综合征），Hb90g/L（贫血，提示慢性病可能），血肌酐400μmol/L（在年轻女性正常值约41～73μmol/L），提示肾功能明显减退，诊断考虑慢性肾小球肾炎（B对）。慢性肾盂肾炎（A错）多有反复发作的泌尿系感染病史，且早期多表现为肾小管功能损伤（夜尿、低比重尿等），早期肾功能减退不明显。肾病综合征（C错）表现为大量蛋白尿、低蛋白血症、水肿及高脂血症，该患者尿蛋白仅（+），不支持其诊断。狼疮性肾炎（D错）需存在系统性红斑狼疮相关症状，但该患者仅有肾炎综合征及肾功能不全的表现，并无全身表现。","c3","N"],["2007-N171-L",40,"第七节 慢性肾小球肾炎","积极控制高血压和减少尿蛋白",2007,171,"A","C","女性，36岁，1年来乏力、易疲倦、腰部不适，有时下肢浮肿，未检查。2个月来加重，伴纳差，血压增高为160/100mmHg，下肢轻度浮肿。尿蛋白（+），沉渣RBC5～10/Hp，偶见颗粒管型，血化验Hb90g/L，血肌酐400μmol/L进行降压治疗时，下列药物不宜选用的是",[["A","贝那普利"],["B","氯沙坦"],["C","氢氯噻嗪"],["D","氨氯地平"]],"A","动脉血经入球小动脉进入肾小球进行滤过，再经出球小动脉流出肾小球。血液在肾小球滤过时，需要有一定的压力，才能将原尿滤过出去。ACEI、ARB类药有扩张肾小球动脉的作用，但扩张出球小动脉比扩张入球小动脉更强，导致肾小球有效滤过压降低，造成肾小球滤过率进一步下降，肾功能恶化。另外，肾功能不全病人血钾偏高，而ACEI、ARB类药有保钾作用，应用后会使血清钾进一步升高，严重的高钾血症易引起心脏电生理紊乱，发生室颤和心脏停搏。所以有慢性肾功能不全的病人，当血肌酐大于264μmol/L时，不能用ACEI类药物如贝那普利（A对）或ARB类药物如氯沙坦（B对）。氢氯噻嗪（C错）（十版内科学P183）GFR＜30ml/min时作用明显受限，患者血肌酐为400μmol/L，对应CKD3期，GFR大于30ml/min，故可以使用。氨氯地平（D错）禁忌证较少，可用于有肾损害的高血压患者降压。本题答案应为AB，但参考答案为A。","c3","N"],["2007-N172-L",47,"第一节 缺铁性贫血","缺铁性贫血病因",2007,172,"A","C","女性，25岁，未婚，半年来乏力，面色苍白，1周来加重，既往有十二指肠溃疡病5年。化验血Hb75g/L，RBC3.5×10¹²/L，WBC8.5×10⁹/L，Plt325×10⁹/L诊断为缺铁性贫血。下列致病原因中，最不可能的是",[["A","月经过多"],["B","消化道失血"],["C","偏食"],["D","需铁量增加"]],"D","患者为年轻女性，处于育龄期，有可能是月经过多（A错）引发缺铁性贫血。患者既往有十二指肠溃疡病史，可能是十二指肠溃疡导致消化道出血（B错）继而引发缺铁性贫血。偏食（C错）亦可导致缺铁性贫血。需铁量增加（D对）常见于婴幼儿、青少年、妊娠和哺乳，与该患者不符，是最不可能的致病原因。","c4","N"],["2007-N173-L",47,"第一节 缺铁性贫血","补铁治疗",2007,173,"A","C","女性，25岁，未婚，半年来乏力，面色苍白，1周来加重，既往有十二指肠溃疡病5年。化验血Hb75g/L，RBC3.5×10¹²/L，WBC8.5×10⁹/L，Plt325×10⁹/L诊断为缺铁性贫血。该患者最不适宜的处理是",[["A","口服琥珀酸亚铁"],["B","肌肉注射右旋糖酐铁"],["C","口服稀盐酸"],["D","浓缩红细胞输注"]],"C","缺铁性贫血的治疗包括去除病因和补充铁剂。治疗性铁剂分有机铁剂和无机铁剂两类，琥珀酸亚铁（A对）、右旋糖酐铁（B对）均为有机铁剂，可用于缺铁性贫血的治疗。该患者的Hb为75g/L，若Hb在70~100g/L，可以根据具体情况决定是否输血改善贫血症状（D对）。虽然胃酸（盐酸）可以增加非血红素铁的溶解度，但该患者有十二指肠溃疡病史，口服稀盐酸会加重溃疡，所以该患者最不适宜口服稀盐酸（C错，为本题正确答案）。口服铁剂需要注意的问题包括：较大剂量的维生素C或琥珀酸可以增加铁剂的吸收，但植物性食物中的磷酸盐、植酸盐、茶叶中的鞣酸及咖啡中的一些多酚类化合物等，会与铁形成难以溶解的盐类而抑制铁的吸收，蛋黄中的磷蛋白和卵黄高磷蛋白和铁结合后可溶性差而不易吸收。","c4","N"],["2007-N174-L",15,"第二节 慢性心力衰竭","慢性心力衰竭诊断",2007,174,"A","C","男性，60岁，因3年来渐进性加重的活动后心悸、气短，无心前区疼痛，半年来不能平卧，伴下肢浮肿、腹胀、尿少来诊，30年前曾有血压高，未治疗。无关节痛史，吸烟40年。查体：血压148/90mmHg，半卧位，颈静脉明显充盈，双肺底均可闻及水泡音，心界明显向左扩大，心尖部可闻3/6级收缩期吹风样杂音，心律整，心率103次/分，S₁减弱，肝肋下2.0cm，肝颈反流征（+），双下肢水肿（+）。根据上述临床资料分析，可基本排除的诊断是",[["A","风湿性心脏瓣膜病"],["B","冠心病"],["C","高血压病"],["D","扩张型心肌病"]],"A","患者颈静脉明显充盈，肝颈反流征（+），双下肢水肿（+）（为典型右心衰竭体循环淤血征象），双肺底均可闻及水泡音（为典型左心衰肺淤血水肿征象），可诊断为全心衰竭。冠心病、高血压可发展至全心衰竭，患者既往有血压高、吸烟等危险因素，因此冠心病、高血压不能排除（BC错）。患者为老年男性，起病缓慢、心脏扩大，因此扩张型心肌病也不能排除（D错）。风湿性心瓣膜病最常见的病理改变为二尖瓣狭窄，表现为心尖部舒张期隆隆样杂音；该患者心尖部并无舒张期杂音，仅可闻及3/6级收缩期吹风样杂音，考虑由相对性二尖瓣瓣膜关闭不全引起，因此风湿性心脏瓣膜病的可能性最小（A对）。","c5","N"],["2007-N175-L",15,"第二节 慢性心力衰竭","超声心动图",2007,175,"A","C","男性，60岁，因3年来渐进性加重的活动后心悸、气短，无心前区疼痛，半年来不能平卧，伴下肢浮肿、腹胀、尿少来诊，30年前曾有血压高，未治疗。无关节痛史，吸烟40年。查体：血压148/90mmHg，半卧位，颈静脉明显充盈，双肺底均可闻及水泡音，心界明显向左扩大，心尖部可闻3/6级收缩期吹风样杂音，心律整，心率103次/分，S₁减弱，肝肋下2.0cm，肝颈反流征（+），双下肢水肿（+）。为鉴别其他三种疾病，结合患者病情，下列哪项无创性检查意义最大",[["A","胸部X线平片"],["B","超声心动图"],["C","动态心电图"],["D","核素动静态心肌显像"]],"B","超声心动图可显示心脏的形态结构、功能，是鉴别高血压性心肌病、冠心病和扩张型心肌病最有意义的无创检查方法（B对）。动态心电图无法反映心脏结构变化，因此没有鉴别意义（C错）。由于患者已有心衰，故不能行核素动静态心肌显像（D错）。胸部X线平片仅从心脏形态学角度辅助诊断（A错），而无法显示心脏内部结构的变化，因此诊断价值远远小于超声心动图。","c5","N"],["2007-N176-L",11,"第一节 胸腔积液","结核性胸膜炎",2007,176,"A","C","男性，35岁，3个月来低热、盗汗、消瘦，1个月来劳累后气短。查体：T37.6℃，右下肺触觉语颤减弱，叩诊呈浊音，呼吸音消失。心尖搏动向左移位，心音正常，心率98次/分，律整，无杂音，超声示右侧胸腔中等量积液。对患者进行初步诊断，首先考虑为",[["A","结核性胸腔积液"],["B","病毒性胸腔积液"],["C","化脓性胸腔积液"],["D","肿瘤性胸腔积液"]],"A","患者青年男性，低热、盗汗、消瘦3个月（典型的结核中毒症状）；右下肺触觉语颤减弱、叩诊浊音、呼吸音消失（胸腔积液的典型体征），心尖搏动向左移位（右侧胸腔积液使纵隔向左移位压迫心脏所致），故首先考虑结核性胸腔积液（A对）。病毒性胸腔积液（B错）和化脓性胸腔积液（十版内科学P131）（C错）多急性起病，高热，积液量一般不多，一般不会出现低热、盗汗、体重减轻。肿瘤性胸腔积液（十版内科学P131）（D错）多见于中老年人，有胸部钝痛、咳血丝痰和消瘦等症状，但一般无发热、盗汗症状。","c6","N"],["2007-N177-L",11,"第一节 胸腔积液","胸腔积液实验室检查",2007,177,"A","C","男性，35岁，3个月来低热、盗汗、消瘦，1个月来劳累后气短。查体：T37.6℃，右下肺触觉语颤减弱，叩诊呈浊音，呼吸音消失。心尖搏动向左移位，心音正常，心率98次/分，律整，无杂音，超声示右侧胸腔中等量积液。入院后应采取的最主要诊断措施是",[["A","胸腔穿刺抽液检查"],["B","血培养"],["C","PPD试验"],["D","胸部CT检查"]],"A","在超声确定有胸腔积液之后，我们应当确定积液的性质，明确病因，故入院后应采取的最主要诊断措施是胸腔穿刺抽液检查（A对）；血培养（B错）只有在结核分枝杆菌侵及血液时才有阳性结果，对结核性胸腔积液的确诊意义不大。PPD试验（C错）只对3岁以内婴幼儿结核病的诊断有价值；胸部CT检查（D错）不是结核性胸腔积液主要诊断手段，但有助于排除肺部占位性病变。","c6","N"],["2007-N178-L",11,"第一节 胸腔积液","胸腔积液临床表现",2007,178,"A","C","男性，35岁，3个月来低热、盗汗、消瘦，1个月来劳累后气短。查体：T37.6℃，右下肺触觉语颤减弱，叩诊呈浊音，呼吸音消失。心尖搏动向左移位，心音正常，心率98次/分，律整，无杂音，超声示右侧胸腔中等量积液。该患者还可能出现的体征是",[["A","右侧肺底下移"],["B","气管向左移位"],["C","右上肺可闻管状呼吸音"],["D","双侧胸廓肋间隙变窄"]],"B","已知患者右侧中等量胸腔积液，胸腔积液由于重力作用沉积于下方，压迫肺组织，使右肺底上移（A错）；压迫肺组织，发生压迫性肺不张，因组织致密，有利于支气管音的传导，可于积液区上方有时可听到管状呼吸音（支气管呼吸音），并非右上肺（C错）；压迫气管，使气管向左侧移位（B对）；右侧胸腔体积增大，使右侧胸廓饱满，肋间隙增宽（D错）。","c6","N"],["2008-N58",35,"第一节 肝硬化","出血和贫血",2008,58,"A","","下列临床表现中，与肝硬化患者体内雌激素增加无关的是",[["A","蜘蛛痣"],["B","男性乳腺发育"],["C","毛细血管扩张"],["D","贫血貌"]],"D","肝硬化时，由于肝功能减退，雌激素的代谢灭活功能发生不同程度的障碍，雌激素在体内蓄积，雌激素作用于血管平滑肌具有毛细血管扩张（C错）作用，可导致肝掌和蜘蛛痣（又称蜘蛛状毛细血管扩张）。雌激素增加还可使肝硬化患者出现月经失调、睾丸萎缩或男性乳房发育（B错）。贫血（D对）与肝合成凝血因子减少和脾功能亢进有关，与雌激素增加无关，雌激素增加虽然会抑制造血，但一般很难造成贫血，红细胞的生成受多种因素调节。","","N"],["2008-N59",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄诊断",2008,59,"A","","下列疾患中，一般不会出现肺动脉瓣区第二心音反常分裂的是",[["A","先天性心脏病房间隔缺损"],["B","急性广泛前壁心肌梗死"],["C","完全性左束支传导阻滞"],["D","主动脉瓣狭窄"]],"A","心脏第二心音分裂分为正常第二心音分裂和病理性第二心音分裂两类。正常情况下左右心室舒张期不完全同步，吸气时右心血液回流较多，右室排空时间长，肺动脉瓣关闭进一步延迟，而左心回流未增加，可使第二心音的主动脉瓣成分与肺动脉瓣成分的距离加大，大于0.03以上听到第二心音分裂。呼气时可分裂消失，青少年和儿童在胸骨左缘第2、3肋间最宜听到。先天性心脏病房间隔缺损（A对）常出现S₂固定分裂（九版诊断学P151），即分裂不受吸气、呼气影响，S₂分裂的两个成分时距较固定，其原因如下：呼气时右心房回心血量有所减少，但由于存在左房向右房的血液分流，右心血量仍然增加，排血时间延长，肺动脉瓣关闭明显延迟；吸气时，回心血量增加，但右房压力暂时性升高同时造成左向右分流稍减少，基本抵消了吸气导致的右心血流增加的改变。反常分裂又称逆分裂（九版诊断学P151），指主动脉瓣关闭迟于肺动脉瓣，吸气时分裂变窄，呼气时分裂变宽。S₂反常分裂是病理性体征，见于完全性左束支传导阻滞（C错）、主动脉瓣狭窄（D错）、重度高血压。急性广泛前壁心肌梗死（B错）可导致左束支传导阻滞，引起S₂反常分裂。","","N"],["2008-N60",15,"第二节 慢性心力衰竭","左心衰竭症状",2008,60,"A","","下列呼吸困难类型中，最可能是由左心功能衰竭所致的是",[["A","劳力性呼吸困难"],["B","吸气性呼吸困难"],["C","呼气性呼吸困难"],["D","夜间阵发性呼吸困难"]],"D","夜间阵发性呼吸困难（D对）常见于左心功能衰竭患者或严重二尖瓣狭窄患者，为急性肺充血或慢性肺充血急性加剧的临床表现。其发生机制除睡眠平卧血液重新分配使肺血增加外，夜间迷走神经张力增加、小支气管收缩、横膈抬高、肺活量减少等也是促发因素，是左心衰较特异性的症状。劳力性呼吸困难（A错）无特异性，可见于左心功能衰竭、分流型先天性心脏病、肺部疾患（尤其是慢阻肺）。吸气性呼吸困难（B错）多见于上呼吸道梗阻，常见于肿瘤或异物堵塞引起的大气道狭窄、喉头水肿等。呼气性呼吸困难（C错）多见于下呼吸道梗阻，常见于支气管哮喘、慢阻肺等疾病。","","N"],["2008-N61",17,"第四节 急性冠状综合征","急性ST段抬高型心肌梗死诊断",2008,61,"A","","患者，男，50岁。2个月前，因急性前壁心肌梗死入院，经行左前降支内药物支架植入后，住院7天出院。此后患者无任何症状，服用药物1个月后自行停用。2小时前在睡眠中再次发生剧烈胸痛，ECG证实为急性前壁再发心肌梗死。该患者本次再梗的最可能原因是",[["A","冠状动脉内新病变形成"],["B","支架内再狭窄形成"],["C","支架内血栓形成"],["D","冠状动脉痉挛"]],"C","不管是传统的金属裸支架还是现在的药物洗脱支架，都存在支架内再狭窄和血栓形成等缺点，术后药物治疗仍然是冠心病治疗的基础，抗血小板治疗是核心。在长期口服阿司匹林的基础上，根据患者植入支架的种类来决定联合氯吡格雷的疗程。药物支架可能产生晚期血栓形成，因此一般药物支架PCI（经皮冠状动脉介入术）术后至少服用6～12个月的抗血小板药物。患者直接经皮冠状动脉介入治疗术后仅服药1个月，再发急性前壁心梗，考虑为支架内血栓形成（C对）。","","N"],["2008-N62",19,"第二节 扩张型心肌病","ACEI_ARB",2008,62,"A","","患者，男，52岁。患扩张型心肌病16年，呼吸困难、活动受限、下肢水肿4年，来院检查。查体：血压90/60mmHg，心率96次/分，心律整，双肺底多数湿啰音，左心室舒张末内径69mm，LVEF31%，尿蛋白微量，肾小球滤过率25ml/min。此时对患者进行治疗，最合适的药物是",[["A","卡托普利+呋塞米+美托洛尔"],["B","卡托普利+氢氯噻嗪+硝酸酯"],["C","氯沙坦钾+呋塞米+螺内酯"],["D","氯沙坦钾+美托洛尔+硝酸酯"]],"C","患者诊断扩张型心肌病16年，呼吸困难、活动受限、下肢水肿4年，双肺底多数湿啰音，左心室舒张末内径69mm，LVEF31%，血压90/60mmHg，心率96次/分，提示慢性心衰。患者肾小球滤过率25ml/min，提示慢性肾脏病CKD4期（GFR15～29ml/min·1.73m²），已进入慢性肾衰竭阶段。卡托普利等血管紧张素转换酶抑制剂（ACEI）和氯沙坦钾等血管紧张素受体阻滞剂（ARB）除具有降低血压作用外，还有减少尿蛋白、减缓肾功能恶化的肾脏保护作用。但是ACEI经肾代谢且有低血压、肾功能一过性恶化、高血钾、干咳和血管性水肿等副作用，而ARB相关不良反应少且其一部分经肝脏代谢，故患者首选ARB，慎用ACEI（AB错）。慢性心力衰竭的治疗并不推荐血管扩张药物的应用，仅在伴有心绞痛或高血压的患者可考虑联合治疗，此患者血压90/60mmHg，且无冠心病、心绞痛，故不应使用硝酸酯（D错）。患者双肺底多数湿啰音、下肢水肿，存在明显的水钠潴留，且患者肾功能衰竭，故应使用袢利尿剂，呋塞米等袢利尿剂易导致低血钾，应联合使用保钾型利尿剂，故适合患者的最佳方案是“氯沙坦钾+呋塞米+螺内酯”（C对）。此外β受体阻滞剂须在患者无明显液体潴留时方可使用，该患者双下肢水肿因此暂时不宜应用美托洛尔，须先利尿至干重后方可使用（二版八年制内科学P200）。","","N"],["2008-N63",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病病因",2008,63,"A","","下列选项中，不属于我国COPD发病的常见危险因素是",[["A","吸烟及大气污染"],["B","职业性粉尘暴露"],["C","儿童时期下呼吸道感染"],["D","先天性α₁-抗胰蛋白酶缺乏"]],"D","慢性阻塞性肺疾病（COPD）简称慢阻肺，以持续气流受限为特征并呈进行性发展，其病因与慢性支气管炎类似，与吸烟及大气污染（A对）、职业性粉尘暴露（B对）及儿童时期下呼吸道感染（十版内科学P23）（C对）等因素相关。COPD发病机制包括炎症机制、蛋白酶-抗蛋白酶失衡机制、氧化应激机制等，其中先天性α₁-抗胰蛋白酶缺乏导致的蛋白酶-抗蛋白酶失衡机制多见于外国人，我国尚无报道（D错，为本题正确答案）。","","N"],["2008-N64",2,"第一节 支气管哮喘","支气管哮喘诊断",2008,64,"A","","患者，男，45岁。吸烟20年，有喘息、咳嗽症状，普通胸片未发现明显异常，支气管舒张试验阳性。最可能的诊断是",[["A","心源性哮喘"],["B","支气管哮喘"],["C","嗜酸细胞性肺炎"],["D","COPD"]],"B","患者中年男性，长期吸烟史，有喘息、咳嗽症状，普通胸片未发现明显异常，支气管舒张试验阳性（提示存在可逆性的气道阻塞），根据哮喘诊断标准考虑为支气管哮喘（B对）。心源性哮喘（十版内科学P179）（A错）是指左心衰引起的喘息样呼吸困难，其症状与哮喘相似，但胸片可见心脏增大和肺淤血，与题中条件不符；嗜酸粒细胞性肺炎（十版内科学P108）（C错）X线胸片的典型表现有肺外带的致密肺泡渗出影，中心带清晰，称作“肺水肿反转形状”，与题干不相符；COPD（D错）患者存在不可逆的气流受限，支气管舒张试验为阴性，该试验为鉴别COPD和支气管哮喘的关键。","","N"],["2008-N65",4,"第二节细菌性肺炎","肺炎链球菌肺炎诊断",2008,65,"A","","患者，男，37岁。受凉后出现高热2天，体温达39～40℃，伴有头痛、寒战、咳嗽、咳血痰，恶心伴呕吐3次。查体：急性病容，神清，皮肤和黏膜可见散在出血点，口角可见单纯性疱疹，颈有抵抗，右下肺叩浊，可闻及支气管呼吸音和湿啰音。双侧病理反射未引出。该患者最可能的疾病是",[["A","干酪性肺炎"],["B","金葡菌肺炎"],["C","念珠菌肺炎"],["D","肺炎球菌肺炎"]],"D","患者受凉后高热，伴有头痛、寒战、咳嗽、咳血痰，恶心、呕吐，查体皮肤、黏膜可见散在出血点，口角可见单纯性疱疹，颈有抵抗，右下肺叩浊，并可闻及湿啰音，应怀疑肺炎链球菌肺炎（D对）。肺炎链球菌肺炎起病急，常有受凉、淋雨等诱因，痰呈铁锈色或带血，口角及鼻周有单纯疱疹为其特征性的表现，有脓毒症者，可出现皮肤、黏膜出血点，巩膜黄染，累及脑膜时可有颈抵抗；干酪性肺炎（十版内科学P77）（A错）为继发型肺结核的一种，起病急，病情重，病程短，表现为低热、盗汗、乏力、消瘦等结核中毒症状；金葡菌肺炎（十版内科学P53）（B错）主要表现为急性寒战、高热、脓痰，痰中常有血丝，但无口角及鼻周单纯疱疹；念珠菌肺炎（C错）主要表现为畏寒、发热、咳嗽、咳白色黏液胶冻样痰或脓痰，且无口角及鼻周单纯疱疹。","","N"],["2008-N66",38,"第一节 消化道出血","消化道出血临床表现",2008,66,"A","","下列选项中，不支持有活动性消化道出血的临床表现是",[["A","贫血"],["B","肠鸣音减弱"],["C","白细胞增高"],["D","血尿素氮增高"]],"B","活动性消化道大量出血后多有失血性贫血，一般出血3～4小时即可出现贫血（A错）。活动性消化道出血，肠道内容物增多，刺激肠道，导致肠鸣音活跃（B对）。活动性消化道大量出血2～5小时，白细胞计数轻至中度升高，血止后2~3天才恢复正常（C错）。活动性消化道大量出血后，由于大量血液蛋白质的消化产物在肠道被吸收，血中尿素氮浓度可暂时增高（D错），称为肠源性氮质血症。","","N"],["2008-N67",75,"第二节 农药中毒","中度中毒",2008,67,"A","","下列符合中度有机磷中毒时的胆碱酯酶活力是",[["A","35%"],["B","25%"],["C","15%"],["D","10%"]],"A","有机磷酸中毒的机制主要是有机磷农药对乙酰胆碱酯酶的不可逆性抑制，引起乙酰胆碱蓄积，使胆碱能神经受到持续冲动，导致先兴奋后衰竭。因此，血ChE活力的检测十分重要，也是诊断OPI（有机磷杀虫药）中毒的特异性实验指标，对判断中毒程度、疗效和预后极为重要。通常以正常人血ChE活力值作为100%，急性OPI中毒时，ChE活力值在70%～50%为轻度中毒；50%～30%为中度中毒（A对）；30%以下为重度中毒。","","N"],["2008-N68",37,"第一节 急性胰腺炎","急性胰腺炎辅助检查",2008,68,"A","","患者，男，40岁。6小时前大量饮酒后出现持续性上腹疼痛，阵发性加重，向腰背部放射，弯腰抱膝位可减轻。查体：上腹有压痛，轻度肌紧张。最不可能出现的实验室检查结果是",[["A","血清淀粉酶明显升高"],["B","腹水淀粉酶明显升高"],["C","血糖升高"],["D","血钙降低"]],"A","中年男性患者，6小时前大量饮酒，腹痛伴腰背部放射痛。查体：上腹有压痛，轻度肌紧张，考虑诊断为急性胰腺炎。又因患者持续性上腹疼痛，阵发性加重，可考虑诊断为急性重症胰腺炎。急性重症胰腺炎患者的血清淀粉酶常升高不明显，有时甚至是正常或低于正常（A错，为本题正确答案），腹水多呈血性，其淀粉酶明显升高（B对）。急性胰腺炎时，由于胰岛B细胞受损，使胰岛素分泌减少，可导致血糖升高（C对）。血清中钙离子与脂酸结合形成了脂酸钙（皂化斑），因此血钙降低（D对），且血钙降低程度与临床严重程度平行。","","N"],["2008-N69",39,"第一节 总论","肾脏的内分泌功能",2008,69,"A","","下列选项中，属于肾分泌的非血管活性激素是",[["A","促红细胞生成素"],["B","肾素"],["C","前列腺素"],["D","激肽类"]],"A","肾脏除具有排泄代谢产物及调节体内水盐、酸碱平衡的功能外，尚能分泌多种重要激素。肾脏分泌的激素主要分为两类，一类称为血管活性肽，主要作用于肾脏及全身血管平滑肌，参与调节肾脏本身的血流量及水盐代谢，包括肾素（B错）、前列腺素（C错）、激肽类（D错）、内皮素、血管紧张素、利钠肽以及类花生酸类等物质；另一类作用于全身，称为非血管活性激素，主要包括肾小管周围的间质细胞分泌的促红细胞生成素（EPO）（A对）和肾脏间质参与合成的1，25-（OH）₂D₃。","","N"],["2008-N70",44,"第一节 急性肾损伤","尿液检查",2008,70,"A","","下列选项中，支持肾缺血性急性肾衰竭的实验室检查指标是",[["A","尿渗透压＞500mmol/L"],["B","尿钠浓度＞20mmol/L"],["C","尿比重＞1.018"],["D","血尿素氮/血肌酐＞20"]],"B","急性肾损伤（AKI）以往称为急性肾衰竭（ARF），分为三类即肾前性、肾性和肾后性。肾缺血会损伤肾小管上皮细胞，可引起急性肾小管坏死（ATN），引起肾性AKI。由于肾小管坏死，其对于原尿的浓缩功能受损，尿渗透压＜250mOsm/kg H₂O（正常值为600～1000mOsm/kg H₂O）（A错），尿比重＜1.012（正常值为1.015～1.025）（C错）。由于肾小管的重吸收功能受损，尿钠浓度＞20mmol/L（B对），血尿素氮/血肌酐＜10～15（正常情况下，肾小管对尿素氮的重吸收率为30%～40%，有少量排泌；肾小管对肌酐基本不重吸收且排泌量较少）（D错）。","","N"],["2008-N71",50,"第一节 溶血性贫血概述","溶血性贫血实验室检查",2008,71,"A","","溶血性贫血患者进行外周血检查时，一般见不到的细胞是",[["A","靶形红细胞"],["B","晚幼红细胞"],["C","破碎红细胞"],["D","泪滴样红细胞"]],"D","溶血后可引起骨髓红系代偿性增生，此时外周血网织红细胞增多，也可见幼红细胞，主要是晚幼红细胞（B错），多染性红细胞，嗜碱性点彩红细胞。严重溶血时尚可见豪-胶小体和幼粒细胞。破裂红细胞（C错）常见于血管内溶血。靶形红细胞（A错）常见于各种低色素性贫血，在珠蛋白生成障碍性贫血（血管外溶血性贫血）时尤易见到，故溶血性贫血可见靶形红细胞。泪滴样红细胞最常见于骨髓纤维化症，也可见于珠蛋白生成障碍性贫血 、溶血性贫血（D）等。本题参考答案为D，略有争议。","","N"],["2008-N72",52,"第三节 慢性髓系白血病","中性粒细胞碱性磷酸酶（NAP）",2008,72,"A","","患者，男，41岁，因发热、咽痛10天来诊。化验WBC89×10⁹/L，疑诊为慢性粒细胞白血病（CML）。下列选项中，支持CML慢性期的化验结果是",[["A","血小板降低"],["B","NAP阳性率明显降低"],["C","外周血可见有核红细胞"],["D","骨髓中巨核细胞减少"]],"B","该患者疑诊为慢性粒细胞性白血病（CML）。CML慢性期患者血小板多在正常水平，部分患者增多（A错）；加速期会有血小板进行性减少或增加。NAP（中性粒细胞碱性磷酸酶）主要存在于成熟阶段的中性粒细胞中，NAP阳性率与患者中性粒细胞有无发育障碍直接相关。CML慢性期骨髓增生明显活跃，以幼稚粒细胞为主，中性粒细胞发育障碍，故NAP阳性率降低（B对）。另外NAP活性减低还见于急性粒细胞白血病、PNH（阵发性睡眠性血红蛋白尿）、单纯性病毒性感染、系统性红斑狼疮；NAP活性升高见于急性淋巴细胞白血病、急性单核细胞白血病、慢性粒细胞白血病急性变、再生障碍性贫血、类白血病反应、严重化脓性感染、原发性血小板增多症、骨髓纤维化和真性红细胞增多症等。CML慢性期红系增生受抑制，外周血一般无有核红细胞（C错）。CML慢性期骨髓中巨核细胞正常或增多（D错），晚期才减少。","","N"],["2008-N73",60,"第一节 库欣综合征","库欣综合征鉴别诊断",2008,73,"A","","患者，女，42岁，诊断为Cushing综合征，为与肥胖症鉴别，最有价值的表现是",[["A","高血压"],["B","月经少或闭经"],["C","糖耐量减低"],["D","血皮质醇失去昼夜规律"]],"D","Cushing综合征（皮质醇增多症）患者皮质醇分泌增多，失去昼夜分泌节律；单纯性肥胖（肥胖症）患者血皮质醇昼夜变化节律正常。故皮质醇昼夜节律可作为二者的鉴别依据（D对）。高血压（A错）、月经少或闭经（B错）、糖耐量减低（C错）均可见于Cushing综合征和肥胖症。","","N"],["2008-N74",60,"第五节 嗜铬细胞瘤","肿瘤部位及生化特征",2008,74,"A","","肾上腺外的嗜铬细胞瘤发生的主要部位是",[["A","腹主动脉旁"],["B","肾门区"],["C","肝门区"],["D","后纵隔或脊柱旁"]],"A","嗜铬细胞瘤位于肾上腺者约占80%～90%，肾上腺外的嗜铬细胞瘤主要位于腹部，多见于腹主动脉旁（A对），其他少见部位为肾门（B错）、肾上极、肝门区（C错）、肝及下腔静脉之间、近胰头部位、髂窝或近髂窝血管处如卵巢内、膀胱内、直肠后等。嗜铬细胞瘤位于腹外者甚少见，可位于胸内（主要在后纵隔或脊柱旁，也可在心脏内）（D错）、颈部、颅内。","","N"],["2008-N75",67,"第一节 风湿系统疾病总论","改善病情的抗风湿药",2008,75,"A","","下列选项中，不属于改变病情的抗风湿药物是",[["A","青霉胺"],["B","氯喹"],["C","萘普生"],["D","甲氨蝶呤"]],"C","抗风湿病药物主要包括非甾体抗炎药（NSAIDs）、糖皮质激素、改变病情抗风湿药（DMARDs）及生物制剂。萘普生属于非甾体抗炎药，通过抑制前列腺素的合成，发挥其解热、镇痛、消炎作用，是改善关节炎症状的常用药物，但不能改变患者病情（C对）。改变病情抗风湿药的共同特点是具有改善病情和延缓病情进展的作用，其特点是起效慢，常见的有柳氮磺吡啶、金制剂、抗疟药、青霉胺及一些免疫抑制剂等。青霉胺（A错）、氯喹（抗疟药）（B错）、甲氨蝶呤（D错）均属于改变病情的抗风湿药物。注意：改变病情抗风湿药常考，需熟记，特别要记住柳氮磺吡啶，柳氮磺吡啶分解后，起作用的5-氨基水杨酸能抑制前列腺素合成，虽和非甾体抗炎药作用机制相同，但是5-氨基水杨酸还能清除吞噬细胞释放的致炎性氧离子，5-氨基水杨酸不属于非甾体抗炎药，因柳氮磺吡啶能清除致炎性氧离子而能改善病情，故属于改变病情抗风湿药。","","N"],["2008-N76",67,"第一节 风湿系统疾病总论","抗角蛋白抗体谱",2008,76,"A","","抗角蛋白抗体谱的检查有助于类风湿关节炎的早期诊断。下列选项中，属于此类抗体的是",[["A","抗核周因子抗体"],["B","抗核抗体"],["C","抗RNP抗体"],["D","抗组织细胞抗体"]],"A","抗角蛋白抗体谱包括抗核周因子抗体（A对）、抗角蛋白抗体、抗聚角蛋白抗体及抗环瓜氨酸多肽（CCP）抗体。这些抗体有助于类风湿关节炎（尤其在类风湿因子阴性、临床症状不典型的类风湿关节炎患者）的早期诊断。抗核抗体（B错）属于抗核抗体谱，在多种自身免疫病中（如系统性红斑狼疮、类风湿关节炎、混合性结缔组织病、干燥综合征、全身性硬皮病等）均呈不同程度的阳性率。抗RNP抗体（抗核糖核蛋白抗体）（C错）属于抗核抗体谱中的抗ENA抗体谱，可见于系统性红斑狼疮（SLE）和混合性结缔组织病（MCTD）病人。抗组织细胞抗体（D错）包括抗红细胞膜抗体、抗血小板相关抗体、抗神经元抗体，并不属于抗角蛋白抗体谱。","","N"],["2008-N91",11,"第一节 胸腔积液","胸腔积液鉴别诊断",2008,91,"A","","患者，男，25岁。低热2周。查体：气管不偏，右侧胸部呼吸运动减弱，右下肺触觉语颤正常，叩诊呈浊音，肺泡呼吸音减低，未闻及湿啰音，左肺未见异常。根据患者的右侧胸部体征，可诊断为",[["A","胸腔积液"],["B","胸膜增厚伴粘连"],["C","肺实变"],["D","肺大疱"]],"B","胸腔积液（A错）量少时常无明显体征，而题目中患者叩诊及听诊均异常；大量胸腔积液时，气管向健侧移位，触觉语颤减弱或消失，与题目中患者的临床表现不相符。肺实变（C错）时，触觉语颤明显增强。肺大疱（D错）时，叩诊呈鼓音，一般无呼吸运动减弱，肺泡呼吸音减低等体征。胸膜增厚伴粘连（B对）时触觉语颤可正常，可不出现气管偏移，但可有呼吸运动减弱，叩诊呈浊音，肺泡呼吸音减弱，肺内无干湿啰音，故最可能的诊断为胸膜增厚伴粘连。","c8","N"],["2008-N92",11,"第一节 胸腔积液","胸腔积液鉴别诊断",2008,92,"A","","患者，男，25岁。低热2周。查体：气管不偏，右侧胸部呼吸运动减弱，右下肺触觉语颤正常，叩诊呈浊音，肺泡呼吸音减低，未闻及湿啰音，左肺未见异常。为明确诊断，应选用的最简便检查方法是",[["A","胸部X线片"],["B","胸部CT"],["C","胸部B超"],["D","胸腔镜"]],"C","胸部B超（C对）可以检测出胸膜增厚，为胸膜增厚伴粘连最简便的检查方法，能与胸腔积液相鉴别。胸部X线片（A错）只有在胸膜增厚粘连到一定程度时才可以检查出，表现为胸廓内缘和肺野之间有一层边缘清晰的锐利阴影。胸部CT（十版内科学P128）（B错）和胸腔镜（D错）可确诊，但因前者价格昂贵，后者有创，因此均不是最简单的检查方法。","c8","N"],["2008-N93",23,"第一节 感染性心内膜炎","感染性心内膜炎诊断",2008,93,"A","","患者，女，34岁。因1个月来发热、乏力、咳嗽，1天来左眼突然失明来院。既往有心脏杂音。查体：体温37.9℃，脉率96次/分，血压128/75mmHg，左眼视力消失，双肺（-），心界不大，心尖部3/6级收缩期吹风样杂音，肝未及，脾肋下可及。化验：Hb96g/L，WBC12.8×10⁹/L，尿蛋白（±），镜检RBC1～3个/HP。对该患者最可能的诊断是",[["A","肺结核"],["B","缺铁性贫血"],["C","急性肾小球肾炎"],["D","感染性心内膜炎"]],"D","患者中年女性，有发热、乏力1月（感染中毒症状），左眼突然失明1天（考虑赘生物脱落导致视网膜动脉栓塞）。查体：心尖部3/6级收缩期吹风样杂音（存在二尖瓣关闭不全，为感染性心内膜炎常见的基础疾病）。实验室检查，患者Hb96g/L，属轻度贫血（正常成年女性：115～150g/L），白细胞升高WBC12.8×10⁹/L（正常3.5～9.5×10⁹/L）（考虑存在感染）。尿蛋白弱阳性。结合患者临床表现与实验室检查，患者诊断考虑为感染性心内膜炎（D对）。肺结核（A错）起病可急可缓，多有低热（午后为著）、盗汗、乏力、纳差、消瘦等结核中毒症状，但不会引起心尖部杂音与单眼失明。缺铁性贫血（B错）主要表现为乏力、易倦、头晕、头痛等症状，但不会引起心尖部杂音与单眼失明。急性肾小球肾炎（C错）是以急性肾炎综合征为主要临床表现的一组原发性肾小球肾炎，其特点为急性起病，血尿、蛋白尿、水肿和高血压，可伴一过性氮质血症，具有自愈倾向（十版内科学P476），患者尿蛋白弱阳性，尿红细胞检查正常，可排除。","c9","N"],["2008-N94",23,"第一节 感染性心内膜炎","周围体征",2008,94,"A","","患者，女，34岁。因1个月来发热、乏力、咳嗽，1天来左眼突然失明来院。既往有心脏杂音。查体：体温37.9℃，脉率96次/分，血压128/75mmHg，左眼视力消失，双肺（-），心界不大，心尖部3/6级收缩期吹风样杂音，肝未及，脾肋下可及。化验：Hb96g/L，WBC12.8×10⁹/L，尿蛋白（±），镜检RBC1～3个/HP。该患者不可能出现的体征",[["A","Roth斑"],["B","杵状指"],["C","水冲脉"],["D","Osler斑"]],"C","患者诊断多考虑为感染性心内膜炎。水冲脉是由周围血管扩张或存在分流所致，多见于主动脉瓣关闭不全、先天性心脏病动脉导管未闭、动静脉瘘，与感染性心内膜炎并无关系（C对）。Roth斑（A错）是指亚急性感染性心内膜炎时，由于毒素和（或）免疫复合物的作用，微小血管壁受损，发生漏出性出血。杵状指发病机理尚不清楚，一般认为与动脉血氧量不足及血流增快等因素有关，亚急性心内膜炎患者约1/3有杵状指（B错）。Osler结节（D错）主要源自体内免疫复合物的沉积，从而引发机体产生免疫反应，局部形成水肿、炎性红肿，并刺激末梢痛觉神经，产生一定的疼痛感。多存在于一些慢性（或亚急性）感染性心内膜炎中。","c9","N"],["2008-N95",23,"第一节 感染性心内膜炎","感染性心内膜炎血培养",2008,95,"A","","患者，女，34岁。因1个月来发热、乏力、咳嗽，1天来左眼突然失明来院。既往有心脏杂音。查体：体温37.9℃，脉率96次/分，血压128/75mmHg，左眼视力消失，双肺（-），心界不大，心尖部3/6级收缩期吹风样杂音，肝未及，脾肋下可及。化验：Hb96g/L，WBC12.8×10⁹/L，尿蛋白（±），镜检RBC1～3个/HP。为确诊，最重要的临床检查是",[["A","胸部X线片"],["B","血培养加药敏"],["C","超声心动图"],["D","肾活检"]],"B","患者诊断多考虑为感染性心内膜炎。血培养阳性是确诊感染性心内膜炎的重要依据，凡原因未明的发热、体温持续在1周以上，且原有心脏病者，均应积极反复多次进行血培养，以提高阳性率，若血培养阳性，尚应做药物敏感试验以选择敏感抗生素治疗。故诊断感染性心内膜炎最重要的临床检查为血培养加药敏（B对）。感染性心内膜炎胸部X线片无特异性表现，部分病人可见脓毒性肺栓塞引起的肺多处小片状浸润影，仅用作辅助诊断（A错）。超声心动图（C错）如发现赘生物、瓣周并发症等支持心内膜炎的证据，可帮助明确IE（感染性心内膜炎）诊断。但超声心动图未发现赘生物时并不能除外感染性心内膜炎诊断，必须密切结合临床。感染治愈后，赘生物可持续存在。除非发现原有赘生物增大或新赘生物出现，否则难以诊断复发或再感染。肾活检（D错）多用于肾脏病变的检查，用以明确病变的病理类型及进展程度。","c9","N"],["2008-N96",8,"第二节 特发性肺纤维化","特发性肺纤维化诊断",2008,96,"A","","患者，男，66岁。活动后气短半年，逐渐加重，干咳，伴有明显乏力和消瘦。2个月来体重下降约4kg，无明显发热。吸烟40余年，1～2包/天，有高血压病史。查体：浅表淋巴结未及，双肺中下野可闻及Velcro啰音，肝脾肋下未及。杵状指（+）。对该患者最可能的诊断是",[["A","肺癌"],["B","肺结核病"],["C","间质性肺疾病"],["D","慢性支气管炎"]],"C","患者既往长期吸烟史及高血压病史，出现活动后气短，进行性加重，干咳伴有乏力和消瘦等表现（间质性肺疾病的典型临床表现），查体双肺中下野可闻及Velcro啰音（Velcro啰音是间质性肺疾病的特征性啰音），杵状指（+）［间质性肺疾病约半数患者可见杵状指（趾）］，该患者最可能的诊断是间质性肺疾病（C对）。肺癌（十版内科学P89）（A错）的典型临床表现为咳嗽、咳痰、咯血和气短等局部表现及发热、体重下降等全身明显表现；肺结核病（十版内科学P73）（B错）主要表现为咳嗽、咳痰、胸痛、咯血等局部表现及低热、盗汗、乏力及食欲减退等全身性结核中毒症状；慢性支气管炎（十版内科学P23）（D错）主要表现为咳嗽、咳痰及气喘等，而无明显乏力和消瘦等全身症状，多无杵状指。此外，ABD均不会出现Velcro啰音。","c10","N"],["2008-N97",8,"第二节 特发性肺纤维化","胸部HRCT",2008,97,"A","","患者，男，66岁。活动后气短半年，逐渐加重，干咳，伴有明显乏力和消瘦。2个月来体重下降约4kg，无明显发热。吸烟40余年，1～2包/天，有高血压病史。查体：浅表淋巴结未及，双肺中下野可闻及Velcro啰音，肝脾肋下未及。杵状指（+）。下列检查中，对该患者疾病诊断意义最大的是",[["A","肺功能检查"],["B","血气分析"],["C","胸部HRCT检查"],["D","血清结核抗体检查"]],"C","患者既往长期吸烟史及高血压病史，出现活动后气短，进行性加重，干咳伴有乏力和消瘦等表现（间质性肺疾病的典型临床表现），查体双肺中下野可闻及Velcro啰音（Velcro啰音是间质性肺疾病的特征性啰音），杵状指（+）［间质性肺疾病约半数患者可见杵状指（趾）］，该患者最可能的诊断是间质性肺疾病。为明确诊断应首选胸部HRCT检查（C对），目前HRCT为临床上诊断肺间质性疾病的重要方法，准确率90%以上，是诊断该疾病最有意义的检查。肺功能检查（A错）虽然可以检测出限制性通气功能障碍伴弥散功能下降，但无特异性。血气分析（B错）主要用于呼吸衰竭的诊断，判断机体是否存在酸碱平衡失调、缺氧及缺氧程度，对于诊断肺间质性疾病意义不大。血清结核抗体检查（D错）主要用于结核的诊断，对于诊断肺间质性疾病意义不大。","c10","N"],["2008-N98",8,"第二节 特发性肺纤维化","特发性肺纤维化治疗",2008,98,"A","","患者，男，66岁。活动后气短半年，逐渐加重，干咳，伴有明显乏力和消瘦。2个月来体重下降约4kg，无明显发热。吸烟40余年，1～2包/天，有高血压病史。查体：浅表淋巴结未及，双肺中下野可闻及Velcro啰音，肝脾肋下未及。杵状指（+）。下列治疗措施中，不正确的是",[["A","早期足量应用抗生素"],["B","应用糖皮质激素"],["C","加用免疫抑制剂"],["D","抗氧化剂治疗"]],"A","患者既往长期吸烟史及高血压病史，出现活动后气短，进行性加重，干咳伴有乏力和消瘦等表现（间质性肺疾病的典型临床表现），查体双肺中下野可闻及Velcro啰音（Velcro啰音是间质性肺疾病的特征性啰音），杵状指（+）［间质性肺疾病约半数患者可见杵状指（趾）］，该患者最可能的诊断是间质性肺疾病。目前间质性肺疾病最有效的治疗方法是肺移植，余尚无循证医学证据证明有效的药物，临床上常用糖皮质激素（B对）和免疫抑制剂（C对）等治疗。间质性肺疾病的发病机制主要是慢性炎症的损伤，应用抗氧化剂治疗（D对）有助于损伤组织的修复。间质性肺疾病没有细菌等微生物的感染，无需早期足量应用抗生素（A错，为本题正确答案）。","c10","N"],["2008-N99",26,"第一节 胃食管反流病","胃食管反流病诊断",2008,99,"A","","患者，男，45岁。2个月来反酸、反食和烧心，多于餐后明显，平卧或身体前倾时易出现，近1周来加重，有时伴胸骨后疼痛，ECG未见明显异常，内镜检查见食管黏膜破损有融合。对该患者的诊断是",[["A","胃食管反流病"],["B","心绞痛"],["C","Mallory-Weiss综合征"],["D","食管憩室炎"]],"A","中年男性患者，反酸、反食和烧心，且多于餐后明显，平卧或身体前倾时易出现，有时伴胸骨后疼痛，ECG未见明显异常，内镜检查提示食管黏膜破损且有融合，说明患者出现了反流性食管炎，这些症状及检查均符合胃食管反流病的表现（A对）。心绞痛（B错）发作时ECG会发生改变，与本题不符。食管贲门黏膜撕裂综合征（Mallory-Weiss综合征）（C错）指剧烈干呕、呕吐和致腹内压骤然增加等情况，造成胃的贲门、食管远端的黏膜和黏膜下层撕裂、并发大量出血与本病例不符。食管憩室是指食管壁的一层或全层局限性膨出，形成与食管腔相同的囊袋，内镜可看到憩室开口，与本题内镜下所见不相符，可排除食管憩室炎（D错）。","c11","N"],["2008-N100",26,"第一节 胃食管反流病","PPI",2008,100,"A","","患者，男，45岁。2个月来反酸、反食和烧心，多于餐后明显，平卧或身体前倾时易出现，近1周来加重，有时伴胸骨后疼痛，ECG未见明显异常，内镜检查见食管黏膜破损有融合。选用的最佳治疗药物是",[["A","多潘立酮"],["B","硝酸甘油"],["C","氢氧化铝"],["D","奥美拉唑"]],"D","胃食管反流病常用药物治疗主要有促胃肠动力药、抑酸药和抗酸药。抑酸是目前治疗本病的主要措施。抑酸药包括H₂RA和PPI（如奥美拉唑）。在所有抑酸药中PPI抑酸作用最强，特别适用于症状重，有严重食管炎的患者。该患者内镜检查见食管黏膜破损有融合，说明有严重的食管炎，故选用的最佳治疗药物是质子泵抑制剂奥美拉唑（D对）。多潘立酮（A错）为促胃肠动力药，这类药物疗效有限且不确定，因此只适用于轻症患者，或作为与抑酸药合用的辅助治疗。氢氧化铝（C错）为抗酸药，这类药物仅用于症状轻、间歇发作的患者作为临时缓解症状用。硝酸甘油为心绞痛患者常用药物，但用于食管反流病引起的胸痛无效并可加重反流症状（B错），应避免使用。","c11","N"],["2008-N101",26,"第一节 胃食管反流病","维持治疗",2008,101,"A","","患者，男，45岁。2个月来反酸、反食和烧心，多于餐后明显，平卧或身体前倾时易出现，近1周来加重，有时伴胸骨后疼痛，ECG未见明显异常，内镜检查见食管黏膜破损有融合。若需维持治疗，选用的最佳药物是",[["A","雷尼替丁"],["B","奥美拉唑"],["C","枸橼酸铋钾"],["D","莫沙必利"]],"B","抑酸药PPI类（如奥美拉唑）和H₂RA类（如雷尼替丁）均可用于胃食管反流病的维持治疗，但奥美拉唑效果更佳（B对A错）。莫沙必利（D错）为促胃肠动力药，这类药物疗效有限且不确定，因此只适用于轻症患者，或作为与抑酸药合用的辅助治疗，不用于维持治疗。枸橼酸铋钾（C错）为胃黏膜保护药，这类药物仅是保护胃黏膜覆盖溃疡面，不用于维持治疗。","c11","N"],["2008-N102",41,"第一节 尿路感染","定位诊断",2008,102,"A","","患者，女，30岁，1周来发热、尿频、尿急、尿痛伴腰痛，既往无类似病史。查体：体温38.3℃，心肺检查未见异常，腹软，肝脾肋下未触及，双肾区有叩击痛。化验：尿蛋白（+），白细胞30～50个/HP，可见白细胞管型。对该患者最可能的诊断是",[["A","急性肾小球肾炎"],["B","急性尿道炎"],["C","急性膀胱炎"],["D","急性肾盂肾炎"]],"D","30岁女性患者（育龄期女性，泌尿系感染易感人群），出现尿频、尿急、尿痛（典型的尿路刺激征，提示泌尿系感染），体查：体温38.3℃（下尿路感染少有发热，即使出现发热，体温也很少超过38.0℃，因此上尿路感染可能性大），双肾区叩击痛（提示肾盂肾炎可能），化验示：白细胞30～50个/HP，可见白细胞管型（提示上尿路感染），诊断考虑急性肾盂肾炎（D对）。急性肾小球肾炎（A错）主要表现为血尿、蛋白尿、水肿、高血压，一般无尿路刺激征和白细胞管型。急性尿道炎（B错）和急性膀胱炎（C错）为下尿路感染，可有明显的尿路刺激征，但感染中毒症状不明显（体温多低于38℃），一般无腰痛和双肾区叩击痛，亦不会有白细胞管型。","c12","N"],["2008-N103",41,"第一节 尿路感染","肾盂肾炎",2008,103,"A","","患者，女，30岁，1周来发热、尿频、尿急、尿痛伴腰痛，既往无类似病史。查体：体温38.3℃，心肺检查未见异常，腹软，肝脾肋下未触及，双肾区有叩击痛。化验：尿蛋白（+），白细胞30～50个/HP，可见白细胞管型。不宜作为首选的治疗药物是",[["A","喹诺酮类"],["B","头孢菌素类"],["C","红霉素"],["D","半合成广谱青霉素"]],"C","急性肾盂肾炎常见致病菌为革兰阴性杆菌，以大肠埃希菌最常见，约占全部尿路感染的85%。红霉素（C错，为本题正确答案）为大环内酯类抗生素，对革兰阳性菌如金葡菌、溶血性链球菌、肺炎球菌、白喉杆菌、炭疽杆菌及梭形芽胞杆菌等效果较好，对革兰阴性杆菌效果较差。喹诺酮类（A对）、头孢菌素类等（B对）、半合成青霉素类（D对）对革兰阴性杆菌效果较好，且在尿液中浓度较高，常作为肾盂肾炎的优选药物。","c12","N"],["2008-N104",41,"第一节 尿路感染","肾盂肾炎",2008,104,"A","","患者，女，30岁，1周来发热、尿频、尿急、尿痛伴腰痛，既往无类似病史。查体：体温38.3℃，心肺检查未见异常，腹软，肝脾肋下未触及，双肾区有叩击痛。化验：尿蛋白（+），白细胞30～50个/HP，可见白细胞管型。一般用药的疗程是",[["A","3天"],["B","7天"],["C","14天"],["D","20天"]],"C","急性肾盂肾炎病程较长，病情较重，除有膀胱刺激症状外，还有寒战、高热和肾区叩痛，抗生素疗程应在2周以上（C对）。3天（A错）疗程适用于育龄女性急性膀胱炎的治疗（十版内科学P503）。7天（B错）疗程适用于妊娠妇女、老年患者、糖尿病患者、免疫力低下患者及男性患者的急性膀胱炎的治疗。泌尿系感染治疗无20天（D错）疗程。","c12","N"],["2008-N105",49,"第一节 再生障碍性贫血","AA诊断标准",2008,105,"A","","患者，女，28岁，3个月来乏力，1周来发热伴皮肤紫癜和口腔颊黏膜血疱，浅表淋巴结及肝脾均不大，胸骨无压痛。化验：Hb65g/L，RBC2.2×10¹²/L，Ret0.2%，WBC2.4×10⁹/L，分类：N24%，L70%，M6%，Plt10×10⁹/L。胸部X线片检查示右下肺炎症。对该患者最可能的血液病学诊断是",[["A","骨髓增生异常综合征"],["B","再生障碍性贫血"],["C","急性淋巴细胞白血病"],["D","巨幼细胞贫血"]],"B","患者为青年女性，有乏力、Hb65g/L（成年女性正常值115～150g/L）（贫血症状），发热（感染症状），皮肤紫癜和口腔颊黏膜血疱（出血症状）等再生障碍性贫血的典型临床表现，查体：浅表淋巴结及肝脾均不大（再障一般无肝脾肿大），查血常规示：RBC2.2×10¹²/L（正常值3.5～5.0×10¹²/L），WBC2.4×10⁹/L（正常值3.5～9.5×10⁹/L），Plt10×10⁹/L（正常值125～350×10⁹/L）（全血细胞减少）。故患者最可能诊断为再生障碍性贫血（B对）。骨髓增生异常综合征（十版内科学P572）（A错）外周血一般可出现原始细胞，常有脾肿大，与该患者不符。急性淋巴细胞白血病（十版内科学P579）（C错）多有淋巴结肿大、肝脾肿大，且有胸骨下段局部压痛，大多数患者白细胞增多，超过10×10⁹/L，外周血可发现原始淋巴细胞明显增多，与该患者不符。巨幼细胞贫血（十版内科学P552）（D错）为维生素B₁₂和（或）叶酸缺乏所导致的贫血，主要表现为贫血症状，对粒系和单核系影响较小，虽重者可出现全血细胞减少，但较少见。","c13","N"],["2008-N106",49,"第一节 再生障碍性贫血","AA骨髓象",2008,106,"A","","患者，女，28岁，3个月来乏力，1周来发热伴皮肤紫癜和口腔颊黏膜血疱，浅表淋巴结及肝脾均不大，胸骨无压痛。化验：Hb65g/L，RBC2.2×10¹²/L，Ret0.2%，WBC2.4×10⁹/L，分类：N24%，L70%，M6%，Plt10×10⁹/L。胸部X线片检查示右下肺炎症。为确定诊断，首选的检查是",[["A","血清铁和铁蛋白"],["B","血清叶酸和维生素B₁₂"],["C","骨髓穿刺"],["D","骨髓活检"]],"C","根据患者临床表现及实验室检查，初步诊断为再生障碍性贫血，但患者骨髓增生情况还未知（再障最重要的诊断条件），因此为确定诊断，首选的检查是多部位骨髓穿刺（C对）（常提示增生低下）。血清铁和铁蛋白常用于缺铁性贫血的诊断（十版内科学P549）（A错）。血清叶酸和维生素B₁₂常用于巨幼细胞贫血的诊断（十版内科学P552）（B错）。骨髓活检（D错）也可用于再生障碍性贫血的诊断，但骨髓穿刺只需抽取骨髓液，而骨髓活检需要取骨髓组织，创伤较大，一般不作为首选。","c13","N"],["2008-N107",49,"第一节 再生障碍性贫血","对症治疗",2008,107,"A","","患者，女，28岁，3个月来乏力，1周来发热伴皮肤紫癜和口腔颊黏膜血疱，浅表淋巴结及肝脾均不大，胸骨无压痛。化验：Hb65g/L，RBC2.2×10¹²/L，Ret0.2%，WBC2.4×10⁹/L，分类：N24%，L70%，M6%，Plt10×10⁹/L。胸部X线片检查示右下肺炎症。根据病史，该患者最急需的治疗是",[["A","抗生素治疗"],["B","补充叶酸和维生素B₁₂"],["C","雄激素治疗"],["D","血小板成分输注"]],"D","患者目前诊断为再生障碍性贫血，已有皮肤、黏膜出血，且血小板仅10×10⁹/L（正常值为125～350×10⁹/L），发生严重出血，如内脏出血、颅内出血等可能性较大，因此最急需的治疗是血小板成分输注（D对），以预防严重出血（十版内科学P557）。抗生素治疗（A错）可控制患者肺部感染，但不是最急需的治疗。雄激素治疗（C错）可刺激造血，适用于全部再障（十版内科学P557），但不是最急需的治疗。补充叶酸和维生素B₁₂（B错）一般用于巨幼细胞性贫血的治疗（十版内科学P554）。","c13","N"],["2008-N108",59,"第一节 甲状腺功能亢进症","抗甲状腺药物",2008,108,"A","","患者，女，25岁，半个月来怕热、心悸、出汗多，体重下降5kg。查体：血压120／65mmHg，无突眼，甲状腺轻度弥漫性肿大，可闻及血管杂音，心率120次／分，心律整齐。对该患者首选的治疗方案是",[["A","口服抗甲状腺药物"],["B","口服β受体阻滞剂"],["C","放射性碘治疗"],["D","口服碘剂"]],"A","该患者为青年女性，有怕热、心悸、多汗、体重下降（甲亢的临床表现），且有甲状腺肿大、血管杂音（提示甲状腺血流量增大，存在甲亢可能）、心率120次/分（增快，正常为60～100次/分）等甲亢体征，诊断为甲亢。综合该患者病史及体查，诊断考虑Graves病。该患者病史短，症状轻，甲状腺轻度肿大应首选抗甲状腺药物治疗（A对）。β受体阻滞可阻断甲状腺激素对心脏的兴奋作用，并能阻断外周组织T₄向T₃的转化，主要在ATD治疗初期使用，可较快控制甲亢的临床症状。但β受体阻滞剂并不能减少甲状腺激素的合成，无法从根本上降低甲亢的高代谢状态，临床上仅作为辅助治疗（B错）。放射性碘治疗（¹³¹I治疗）作为美国GD（Graves病）患者的首选治疗，国内少用，适用于中度甲亢患者以及长期药物治疗无效者（C错）。口服碘剂仅用于治疗甲亢危象和甲状腺手术术前准备（D错）。","c14","N"],["2008-N109",59,"第一节 甲状腺功能亢进症","剂量与疗程",2008,109,"A","","患者，女，25岁，半个月来怕热、心悸、出汗多，体重下降5kg。查体：血压120／65mmHg，无突眼，甲状腺轻度弥漫性肿大，可闻及血管杂音，心率120次／分，心律整。若治疗8周后原症状消失，但甲状腺肿有加重，下一步的治疗方法是",[["A","继续原治疗"],["B","加服左甲状腺素（L-T₄）"],["C","加用另一种抗甲状腺药物"],["D","加大碘剂用量"]],"B","患者治疗8周后原症状消失，但甲状腺肿有加重的原因是抗甲状腺药物使血清甲状腺素水平下降，反馈性增加促甲状腺激素分泌，进而引起腺体代偿性增加、腺体增大、充血等。此时应服用甲状腺素片（左甲状腺素），负反馈抑制TSH的释放（B对）。同时应减少抗甲状腺药物（ATD）的剂量（AC错）。对于使用抗甲状腺药物期间，是否可以加用甲状腺素片，最新教材观点为不主张使用，九版药理学提到当发生甲状腺肿及甲状腺功能减退时，及时发现停药常可恢复（P340），而三版八年制内科学及实用内科学观点为可以适当酌情使用。口服碘剂仅用于治疗甲亢危象和甲状腺手术术前准备（D错）。","c14","N"],["2008-N110",59,"第一节 甲状腺功能亢进症","妊娠期甲亢的治疗",2008,110,"A","","患者，女，25岁，半个月来怕热、心悸、出汗多，体重下降5kg。查体：血压120／65mmHg，无突眼，甲状腺轻度弥漫性肿大，可闻及血管杂音，心率120次／分，心律整。若患者未愈而发生早孕，希望保胎，最佳的治疗方法是",[["A","立即行甲状腺手术"],["B","口服甲硫氧嘧啶"],["C","口服丙硫氧嘧啶"],["D","口服甲巯咪唑"]],"C","该甲亢患者合并妊娠，处于妊娠T1期（1～3个月），首选丙硫氧嘧啶（PTU）治疗（C对），因PTU不易通过胎盘，且其治疗剂量对于胎儿是安全的。应用甲硫氧嘧啶后，皮疹、粒细胞减少、粒细胞缺乏的发生率较丙硫氧嘧啶高，故目前已较少应用（B错）。妊娠T1期手术可以出现流产和麻醉剂致畸，为手术治疗的禁忌证（A错）。妊娠T1期甲巯咪唑（MMI）具有致畸作用，故不作首选（D错）。","c14","N"],["2008-N139",16,"第六节 心脏传导阻滞","房室传导阻滞临床表现",2008,139,"B","","听诊可闻大炮音见于",[["A","一度房室传导阻滞"],["B","二度Ⅰ型房室传导阻滞"],["C","二度Ⅱ型房室传导阻滞"],["D","三度房室传导阻滞"]],"D","大炮音（八版诊断学P154）是指心房心室几乎同时收缩时第一心音增强，其机制为心室收缩正好即刻出现在心房收缩之后，心室在相对未完全舒张和未被血液充盈的情况下，二尖瓣位置较低，急速的心室收缩使二尖瓣迅速和有力地关闭使第一心音增强，多见于完全性（三度）房室传导阻滞（D对）。一度房室阻滞（A错）听诊时，因PR间期延长，第一心音强度减弱。二度Ⅰ型房室阻滞（十版内科学P214）（B错）表现为PR间期进行性延长、直至一个P波受阻不能下传心室，包含受阻P波在内的RR间期小于正常窦性PP间期的两倍，且第一心音强度逐渐减弱并有心搏脱漏。二度Ⅱ型房室传导阻滞（十版内科学P214）（C错）表现为PR间期恒定不变部分P波后无QRS波群，亦有间歇性心搏脱漏，但第一心音强度恒定。","","N"],["2008-N140",16,"第六节 心脏传导阻滞","房室传导阻滞临床表现",2008,140,"B","","听诊第一心音由强变弱见于",[["A","一度房室传导阻滞"],["B","二度Ⅰ型房室传导阻滞"],["C","二度Ⅱ型房室传导阻滞"],["D","三度房室传导阻滞"]],"B","一度房室阻滞（A错）听诊时，因PR间期延长，第一心音强度减弱。二度Ⅰ型房室阻滞（十版内科学P214）（B对）表现为PR间期进行性延长、直至一个P波受阻不能下传心室，包含受阻P波在内的RR间期小于正常窦性PP间期的两倍，且第一心音强度逐渐减弱并有心搏脱漏。二度Ⅱ型房室传导阻滞（十版内科学P214）（C错）表现为PR间期恒定不变部分P波后无QRS波群，亦有间歇性心搏脱漏，但第一心音强度恒定。三度房室阻滞（十版内科学P215）（D错）表现为心房和心室活动各自独立、互不相关。心房率快于心室率等，第一心音强度经常变化，可听到响亮亢进的第一心音（即大炮音）。","","N"],["2008-N141",11,"第一节 胸腔积液","结核性胸膜炎",2008,141,"B","","胸腔积液化验结果为：pH7.40，WBC1700×10⁶/L，多核细胞30%，单核细胞70%，葡萄糖2.0mmol/L，ADA102U/L。应考虑诊断为",[["A","肺炎伴胸腔积液"],["B","心衰伴胸腔积液"],["C","肺癌伴胸腔积液"],["D","结核性胸膜炎"]],"D","胸水pH7.40，WBC1700×10⁶/L（渗出液的白细胞常超过500×10⁶/L），多核细胞30%，单核细胞70%，葡萄糖2.0mmol/L（SLE、结核和恶性胸腔积液中含量可＜3.3mmol/L），ADA 102U/L，腺苷脱氨酶（ADA）在淋巴细胞中含量较高。结核性胸膜炎时，淋巴细胞明显增多，故胸水中ADA多高于45U/L，其为结核性胸膜炎敏感性的指标，故为结核性胸膜炎的可能性最高（D对）。心衰所致胸腔积液（十版内科学P126）（B错）一般为漏出液；肺炎伴胸腔积液（十版内科学P130）（A错）胸水白细胞明显增高，但以中性粒细胞增高为主；肺癌伴胸腔积液（C错）指标一般为LDH＞500U/L、ADA多低于45U/L、胸水CEA升高或胸水/血清CEA＞1等。","","N"],["2008-N142",11,"第一节 胸腔积液","恶性胸腔积液",2008,142,"B","","胸腔积液化验结果为：pH7.28，WBC1200×10⁶/L，多核细胞56%，单核细胞44%，葡萄糖2.4mmol/L，ADA15U/L，胸液/血清CEA比值为2。应考虑诊断为",[["A","肺炎伴胸腔积液"],["B","心衰伴胸腔积液"],["C","肺癌伴胸腔积液"],["D","结核性胸膜炎"]],"C","胸腔积液化验结果为：pH7.28，WBC1200×10⁶/L（渗出液的白细胞常超过500×10⁶/L），多核细胞0.56，单核细胞0.44，葡萄糖2.4mmol/L（SLE、结核和恶性胸腔积液中含量可＜3.3mmol/L），ADA15U/L（肿瘤性胸水ADA＜45U/L），胸液/血清CEA比值为2（胸水CEA升高或胸水/血清CEA＞1，常提示为恶性胸水），应考虑诊断为肺癌伴胸腔积液（C对）。肺炎伴胸腔积液（十版内科学P131）（A错）胸水白细胞明显增高，但以中性粒细胞增高为主；心衰所致胸腔积液（十版内科学P130）（B错）一般为漏出液；腺苷脱氨酶（ADA）在淋巴细胞中含量较高，结核性胸膜炎（D错）时，淋巴细胞明显增多，胸水中ADA多高于45U/L，对诊断结核性胸膜炎较敏感。","","N"],["2008-N143",30,"第一节 溃疡性结肠炎","氨基水杨酸制剂",2008,143,"B","","治疗轻、中型溃疡性结肠炎的首选药物是",[["A","柳氮磺吡啶"],["B","美沙拉嗪"],["C","布地奈德"],["D","硫唑嘌呤"]],"A","柳氮磺吡啶（A对）口服后大部分达结肠，经肠菌分解为5-氨基水杨酸而发挥作用，该药物价格便宜，为治疗轻、中型溃疡性结肠炎的首选药。美沙拉嗪（B错）为5-ASA新型制剂，疗效与柳氮磺吡啶相仿，主要适用于轻、中度患者，虽可避免在小肠近段被吸收，降低了不良反应率，但缺点是价格昂贵，而不作为首选，适宜于对柳氮磺吡啶不能耐受者，但现在也有观点认为美沙拉嗪是炎症性肠病的首选药物。糖皮质激素（布地奈德）（C错）主要适用于氨基水杨酸制剂疗效不佳的轻、中度患者，特别适用于重度患者及急性暴发型患者。硫唑嘌呤（D错）可适用于对激素治疗效果不佳或对激素依赖的慢性持续型患者。","","N"],["2008-N144",30,"第二节 克罗恩病","控制炎症反应",2008,144,"B","","治疗轻、中型克罗恩病（病变累及回肠和结肠）的首选药物是",[["A","柳氮磺吡啶"],["B","美沙拉嗪"],["C","布地奈德"],["D","硫唑嘌呤"]],"B","美沙拉嗪（B对）能在回肠末端、结肠定位释放，为治疗轻、中型克罗恩病（病变累及回肠和结肠）的首选药物。柳氮磺吡啶（SASP）（A错）仅适用于病变局限在结肠的轻度患者。糖皮质激素（布地奈德）（C错）主要适用于氨基水杨酸制剂疗效不佳的轻、中度患者，特别适用于重度患者及急性暴发型患者。硫唑嘌呤（D错）可适用于对激素治疗效果不佳或对激素依赖的慢性持续型病例。","","N"],["2008-N169",21,"第四节 二尖瓣反流","二尖瓣反流X线检查",2008,169,"X","","下列检查结果中，可在重度二尖瓣脱垂心功能代偿期患者中出现的有",[["A","胸部X线片示肺血增加影像"],["B","超声心动图示左心室收缩加强"],["C","心电图示心房颤动"],["D","左心室肥厚"]],"ABC","二尖瓣脱垂是指二尖瓣叶（前叶、后叶或两叶）在心室收缩期脱入左心房（向左房侧膨出），影响二尖瓣关闭，主要表现为二尖瓣关闭不全。在心功能代偿期，左心室接受左心房血液及反流血，出现代偿性扩张，左心室舒张末期容量增大，根据Frank-Starling机制，左心室代偿性收缩增强（B对）以维持正常的前向心搏量。二尖瓣关闭不全时的心功能代偿期，收缩期部分血液经关闭不全的二尖瓣口反流至左心房，使左房负荷增加，影响肺静脉血液回流，导致肺淤血，甚至肺水肿，胸部X线片示肺血增加影像（A对）。重度二尖瓣关闭不全主要导致左心室容量负荷增加，一般不发生左心室肥厚（D错），但长期过度的压力负荷，可导致左心室扩张，最终导致左室功能衰竭。ECG常见心房颤动（C对）及左心房增大，部分有非特异性ST-T改变。","","N"],["2008-N170",13,"第三节 慢性呼吸衰竭","正压机械通气",2008,170,"X","","患者，男，65岁。慢性咳嗽、咳痰20年，伴喘息7年，加重1周。吸烟40年，1包/天。查体：两肺可闻及干、湿啰音，心律整。动脉血气分析示：pH7.28，PaO₂52mmHg，PaCO₂76mmHg。可采用的治疗方法有",[["A","无创机械通气治疗"],["B","5%碳酸氢钠40ml静注"],["C","低浓度吸氧，一般不超过33%"],["D","使用洛贝林或尼可刹米"]],"AC","患者老年男性，长期吸烟史，慢性咳嗽、咳痰20年，伴喘息7年，加重1周，查体两肺可闻及干、湿啰音，考虑该患者处于慢性阻塞性肺疾病急性加重期。血气分析：pH7.28（pH正常值为7.35～7.45）降低，PaO₂52mmHg＜60mmHg，PaCO₂76mmHg＞50mmHg，诊断为Ⅱ型呼衰。慢阻肺导致的Ⅱ型呼吸衰竭，氧疗时需注意保持低浓度吸氧，浓度＜35%，此题选项给的数据为33%（C对），防止血氧含量过高失去低氧对呼吸中枢的刺激。COPD因气道阻塞，肺泡通气不足，导致CO₂潴留，因此应无创机械通气治疗（A对），改善通气。酸中毒时使用碳酸氢钠可使H₂CO₃生成增加，后者分解，可加重CO₂潴留；慢性呼衰时CO₂潴留是一个慢性过程，机体常通过增加碱储备来代偿，使碳酸氢盐维持较高水平，以维持pH稳定，给予碳酸氢钠可增加HCO₃⁻含量，当改善通气迅速纠正呼吸性酸中毒后，碳酸氢盐水平不能立即下降，易发生代谢性碱中毒（B错）。该患者两肺闻及干、湿啰音，说明气道有分泌物阻塞气道，应用呼吸兴奋剂（尼可刹米和洛贝林）使用时，必须保持呼吸道通畅，否则会促发呼吸肌疲劳，加重组织缺氧和CO₂潴留（D错）。","","N"],["2008-N171",35,"第一节 肝硬化","肝硬化临床表现",2008,171,"X","","下列肝硬化的临床类型中，发现肝脏肿大的有",[["A","肝炎后肝硬化"],["B","淤血性肝硬化"],["C","酒精性肝硬化"],["D","原发性胆汁性肝硬化"]],"BCD","肝炎后肝硬化早期肝肿大，晚期肝萎缩变小（A），A选项存在争议。淤血性肝硬化（B对）由于肝淤血，引起肝脏肿大。酒精性肝硬化（C对）常伴黄疸，肝大并有触痛。原发性胆汁性肝硬化（D对）由于胆汁淤积，肝中度到重度肿大，常在肋下4～10cm，质硬，表面光滑，压痛不明显。","","N"],["2008-N172",40,"第一节 肾小球疾病概述","血尿",2008,172,"X","","下列选项中，支持肾小球源性血尿的有",[["A","伴较大量蛋白尿"],["B","出现红细胞管型"],["C","出现异形红细胞"],["D","红细胞容积分布呈对称曲线"]],"ABC","肾小球源性血尿产生的主要原因为肾小球基底膜（GBM）断裂，导致大量蛋白质漏出，产生蛋白尿（A对），红细胞通过该裂缝时受血管内压力挤压受损，呈现变形红细胞血尿（C对），随后在肾小管内形成红细胞管型（B对），尿红细胞容积分布曲线呈非对称曲线，红细胞容积分布呈对称性曲线（D错）表明红细胞未受到明显挤压，提示非肾小球源性血尿无红细胞损伤。","","N"],["2008-N173",56,"第二节 原发免疫性血小板减少症","原发免疫性血小板减少症临床表现",2008,173,"X","","下列选项中，符合成人ITP表现的有",[["A","紫癜四肢对称分布"],["B","多有中度脾大"],["C","可有口腔颊黏膜血疱"],["D","可有牙龈和鼻出血"]],"CD","成人ITP（特发性血小板减少性紫癜）的发病机制为体液免疫和细胞免疫介导的血小板过度破坏和血小板生成受抑，出现血小板减少。血小板减少可引起出血倾向，主要表现为皮肤、黏膜出血（C对），鼻出血、牙龈出血亦很常见（D对）。紫癜四肢对称分布为过敏性紫癜的临床特点（A错）。成人ITP体检脾脏一般不增大，但由于自身致敏的血小板经脾被破坏，病程较长者，脾脏可轻度肿大，极少见脾脏中度肿大（B错）。","","N"],["2008-N174",58,"第一节 内分泌学原理","激素的调节",2008,174,"X","","内分泌系统的反馈调节中，作为靶腺的有",[["A","甲状腺"],["B","胰腺"],["C","性腺"],["D","肾上腺"]],"ACD","下丘脑、垂体与靶腺之间存在着反馈调节。下丘脑分别与促甲状腺激素（TSH）、卵泡刺激素（FSH）和黄体生成素（LH）、促肾上腺皮质激素（ACTH）以及各自靶腺构成下丘脑-腺垂体-甲状腺轴、下丘脑-腺垂体-性腺轴、下丘脑-腺垂体-肾上腺皮质轴，其中的靶腺是指甲状腺（A对）、性腺（C对）和肾上腺（D对）。胰腺不与下丘脑和垂体构成下丘脑-垂体-靶腺轴，不属于靶腺（B错）。","","N"],["2009-N57",38,"第一节 消化道出血","上消化道出血",2009,57,"A","","剧烈呕吐后，患者呕出鲜血的最常见病因是",[["A","消化性溃疡"],["B","食管裂孔疝"],["C","急性胃炎"],["D","Mallory-Weiss综合征"]],"D","贲门黏膜撕裂综合征（Mallory-Weiss综合征）是指剧烈呕吐，食管内高压导致的贲门黏膜撕裂引起的出血，表现为出血凶猛，出血量大，剧烈呕吐为主要诱因之一。本题患者剧烈呕吐后，呕出鲜血，因此可以诊断为Mallory-Weiss综合征（D对）；而消化性溃疡（A错）一般不伴剧烈呕吐，常表现为恶心后呕吐出咖啡样物或鲜血；食管裂孔疝（B错）一般表现为腹痛，很少出现呕血；急性胃炎（C错）常无剧烈呕吐，出血量少，以黑便为主。","","N"],["2009-N58",8,"第二节 特发性肺纤维化","特发性肺纤维化诊断",2009,58,"A","","患者出现进行性呼吸困难，吸气时双肺中下野可闻及Velcro音，最可能是诊断是",[["A","肺癌"],["B","肺结核"],["C","特发性肺纤维化"],["D","肺大疱"]],"C","患者出现进行性呼吸困难（间质性肺疾病主要表现为活动性呼吸困难，进行性加重），查体发现双肺中下野可闻及Velcro啰音（Velcro啰音是间质性肺疾病的特征性啰音），该患者最可能的诊断是特发性肺纤维化（C对）。肺癌（A错）、肺结核（B错）、肺大疱（D错）均可出现进行性呼吸困难，但均不会产生Velcro啰音。","","N"],["2009-N59",15,"第二节 慢性心力衰竭","慢性心力衰竭一般治疗",2009,59,"A","","下列关于心力衰竭治疗的叙述正确的是",[["A","为保证休息，心衰患者应常规服用镇静剂"],["B","每日钠摄入量应控制在3～5g之间"],["C","在应用利尿剂时，不必控制钠的摄入"],["D","严格限制钠摄入时，可不必严格控制液体入量"]],"D","在肾功能正常的患者，严格控制钠盐摄入时，一般不必严格控制液体入量（D对），系因过剩的液体可经肾排出而不引起液体潴留。适当休息是减轻心脏负荷的一个重要措施。若患者休息状况欠佳，可依据病情给予适量镇静剂或安眠药，以免心衰加重，但不作为常规应用（A错）。心衰患者须严格控制钠盐摄入，否则可导致液体潴留，增加心脏前负荷，加重病情。钠盐摄入量一般控制在5g/d以下；病情严重者，应控制在1g/d以下（B错）。使用利尿剂易引起低钾血症，而低钠血症少见，因此应用利尿剂时，仍应控制钠盐摄入量（C错）。","","N"],["2009-N60",16,"第三节 房性心律失常","控制心室率",2009,60,"A","","慢性心房颤动应用洋地黄的主要目的是",[["A","控制心室率"],["B","转复房颤律"],["C","预防室性心律失常"],["D","为实施电转复做准备"]],"A","近年来的研究表明，持续性房颤选择减慢心室率同时注意血栓栓塞的预防，预后与经复律后维持窦性心律者并无显著差别，并且更简便易行。洋地黄可抑制心脏传导系统，对房室交界区的抑制最为明显。通过减慢房室结传导速度，延长其有效不应期，减低心室率，有利于改善心功能。故在慢性心房颤动治疗过程中，应用洋地黄的主要目的为控制心室率（A对）。洋地黄无转复房颤律功能（B错），亦无预防室性心律失常作用（C错）。转复房颤律分为药物转复与电转复，药物转复首选胺碘酮。如选用电转复，则应在电复律前几天开始用抗心律失常药物，如普罗帕酮和胺碘酮，从而提高电转复成功率，防止复律后房颤复发。但应注意，已用洋地黄者不应接受电复律治疗（D错）（P193），系因洋地黄可延缓房室传导。","","N"],["2009-N61",15,"第三节 急性心力衰竭","血管扩张剂",2009,61,"A","","患者，男，58岁，因疲劳后突发心悸，呼吸困难，咳嗽，咳泡沫血痰而来院就诊，既往高血压病，心肌梗死史，查体：BP90/60mmHg，端坐位，喘息状，口唇发绀，双肺布满中小水泡音，心率140次/分，心音听不清，下列急症处理不正确的是",[["A","高流量吸氧"],["B","选用中枢交感神经抑制剂"],["C","服用短效β受体抑制剂"],["D","应用外周动静脉血管扩张剂"]],"C","根据患者的临床表现突发心悸、呼吸困难，咳嗽，咳泡沫血痰，血压降低，满肺水泡音，心率增快，心音不清，初步诊断为急性左心衰竭。β受体抑制剂（C错，为本题正确答案）可用于慢性心力衰竭的治疗，且必须在心衰情况稳定、无体液潴留的情况下使用，不能用于急性心衰的治疗。高流量吸氧（A对）有助于提高血氧饱和度，缓解呼吸困难。选用中枢交感神经抑制剂（B对）可反射性降低外周静脉和小动脉张力，降低心脏前后负荷。应用外周动静脉血管扩张剂（D对）亦可以降低心脏前后负荷，改善心功能。","","N"],["2009-N62",18,"第二节 继发性高血压","原发性醛固酮增多症诊断",2009,62,"A","","患者，男，40岁，发现血压增高半年，最高达160/90mmHg，乏力，肌痛，口渴，吸烟20年。查体：血压170/90mmHg，肥胖，心脏不大，心律整，心率76次/分，双下肢不肿，尿蛋白（±），比重1.008，血钾3.1mmol/l，最可能的诊断是",[["A","原发性醛固酮增高症"],["B","原发性高血压"],["C","肾性高血压"],["D","肾血管性高血压"]],"A","中年男性患者，乏力、肌痛、口渴，长期高血压伴低血钾（正常值为3.5～5.5mmol/L），并有低比重尿，诊断考虑原发性醛固酮增高症（A对）。原发性醛固酮增多症是肾上腺皮质增生或肿瘤分泌过多醛固酮所致，临床上以长期高血压伴低血钾为特征，可伴有乏力、肌无力、肌痛等。原发性高血压（B错）一般无蛋白尿及低血钾。肾性高血压（C错）多见于各种终末期肾病，可出现蛋白尿和尿比重降低，常伴有水肿及血钾升高。肾血管性高血压（D错）指由一侧或双侧肾动脉主干或分支狭窄，导致肾脏或肾脏局部缺血，引起RAAS激活，引起水钠潴留导致高血压，但无乏力、肌痛、口渴、低钾血症等表现。","","N"],["2009-N63",2,"第一节 支气管哮喘","β₂受体激动剂",2009,63,"A","","下列药物中属于治疗支气管哮喘患者的β₂受体激动剂的是",[["A","氨茶碱"],["B","异丙托溴铵"],["C","色苷酸钠"],["D","沙丁胺醇"]],"D","治疗哮喘的药物主要有糖皮质激素、β₂受体激动剂、白三烯调节剂、茶碱类药物、抗胆碱类药物等。β₂受体激动剂分为短效β₂受体激动剂（SABA）和长效β₂受体激动剂（LABA）。SABA常用的药物为沙丁胺醇（D对）和特布他林，LABA常用的药物为沙美特罗和福莫特罗。氨茶碱属于茶碱类（A错），异丙托溴铵属于抗胆碱药（B错），色苷酸钠为非糖皮质激素抗炎药（C错）。","","N"],["2009-N64",6,"第一节 肺结核","结核菌素试验",2009,64,"A","","下列哪类人群中，PPD阳性对提示活动性结核病最有价值",[["A","肺内有结节样病灶伴纵隔淋巴结肿大的成年人"],["B","长期发热的患者"],["C","没有任何症状的健康查体者"],["D","未接种卡介苗的婴幼儿"]],"D","PPD阳性只表示曾感染结核分枝杆菌，并不表示一定患病。PPD阳性不能区分是结核分枝杆菌的自然感染还是卡介苗接种的免疫反应，只有未接种卡介苗的婴幼儿（D对）PPD阳性时，对提示活动性结核病有较大价值，而对肺内有结节样病灶伴纵隔淋巴结肿大的成年人（A错）及没有任何症状的健康查体者（C错）出现PPD阳性时诊断价值不大。长期发热的患者（B错）PPD试验可能弱阳性。","","N"],["2009-N65",11,"第二节 气胸","气胸诊断",2009,65,"A","","患者，男，58岁，三小时前在投掷铅球转身后，突感左侧胸痛，随即出现胸闷气短，呼吸急促，行走后症状加重，伴出汗、心悸，自行半坐位休息后症状稍有缓解而来院，既往有高血压、冠心病及肺结核病史，根据临床症状分析，应首先考虑下列哪种疾病的可能性最大",[["A","心绞痛"],["B","心肌梗死"],["C","急性肺栓塞"],["D","急性闭合性气胸"]],"D","患者，男，58岁，既往肺结核病史（继发性气胸常见肺部基础疾病），三小时前在投掷铅球转身后（气胸患者起病前可有持重物、屏气、剧烈体力活动等诱因），突感左侧胸痛，随即出现胸闷气短，呼吸急促，行走后症状加重，伴出汗、心悸（气胸的典型临床症状），既往有高血压、冠心病及肺结核病史（继发性气胸常见于有肺部基础病变者），故考虑急性闭合性气胸（D对）的可能性最大。患者虽有高血压、冠心病病史，但心绞痛（十版内科学P233）（A错）发作常由体力活动或情绪激动诱发，表现为心前区疼痛，呈压榨性、紧缩性，无呼吸困难或呼吸急促，停止原来诱发症状的活动后即可缓解；急性心肌梗死（十版内科学P248）（B错）常表现为心前区胸痛，可伴有出汗、恶心呕吐、呼吸困难，有发热、心动过速、白细胞升高的全身表现；急性肺栓塞（十版内科学P112）（C错）常有房颤、长期卧床、下肢血栓形成等病史，可表现为突发呼吸困难和胸痛，但常有咯血和晕厥，颈静脉充盈或搏动，肺动脉瓣区第二心音亢进或分裂，三尖瓣区收缩期杂音等症状和体征。","","N"],["2009-N66",32,"第二节 肠易激综合征","精神心理障碍",2009,66,"A","","引起肠易激综合征发病的最重要因素是",[["A","急性肠道感染"],["B","精神心理障碍"],["C","内脏感知异常"],["D","对某些食物不耐受"]],"B","肠易激综合征是一种以腹痛或腹部不适伴排便习惯改变为特征而无器质性病变的常见功能性肠病，患者以中青年居多，病因和发病机制尚不清楚，目前认为是多种因素和多种发病机制共同作用的结果，包括：胃肠动力学异常；内脏感觉异常；肠道感染治愈后；胃肠道激素；精神心理障碍等。之前认为精神心理障碍是最重要的因素（B对），大量调查表明，IBS 患者焦虑、抑郁积分显著高于正常人，应激事件发生频率亦高于正常人，对应激反应更敏感和强烈，但十版内科学（P399）认为内脏高敏感性是肠易激综合征的核心发病机制，因此按照最新观点C选项正确。","","N"],["2009-N67",30,"第一节 溃疡性结肠炎","肠外表现",2009,67,"A","","下列关于溃疡性结肠炎的肠外表现中，随肠炎控制或结肠切除后可以缓解或恢复的是",[["A","淀粉样变性"],["B","强直性脊柱炎"],["C","外周关节炎"],["D","骶髂关节炎"]],"C","溃疡性结肠炎（UC）有多种肠外表现，有些肠外表现在结肠炎控制或结肠切除后可以缓解或恢复，包括：外周关节炎（C对）、结节性红斑、坏疽性脓皮病、巩膜外层炎、前葡萄膜炎、口腔复发性溃疡等；有些肠外表现病情变化与UC本身的病情变化无关，包括：原发性硬化性胆管炎、淀粉样变性（A错）、强直性脊柱炎（B错）、骶髂关节炎（D错）等。","","N"],["2009-N68",35,"第一节 肝硬化","利尿",2009,68,"A","","患者，男，54岁。患肝炎后肝硬化10年，近一周来病情加重，腹水量增加，腹胀明显，并出现呼吸困难、睡眠障碍和意识错乱，为减少腹水，下列最佳的治疗药物是",[["A","阿米洛利"],["B","氢氯噻嗪"],["C","螺内酯"],["D","呋塞米"]],"C","本例为肝硬化患者并发肝性脑病，为减轻其腹水应选用螺内酯。肝性脑病患者利尿时应更谨慎，选用作用更为温和的利尿药，利尿药的剂量不宜过大，以免加重肝昏迷。肝硬化患者腹水形成的原因之一是继发性醛固酮增多，螺内酯与醛固酮受体有很强的亲和力，但无内在活性，故具有竞争性拮抗醛固酮的作用。此外，肝硬化腹水患者多合并低钾，而螺内酯正是一种低效的保钾性利尿剂，可以纠正低钾，故肝硬化患者腹水的治疗首选螺内酯（C对）。阿米洛利（A错）虽为强效保钾利尿药，但它作用于肾小管远端，阻断钠-钾交换机制，促使钠、氯排泄而减少钾、氢离子分泌，而无拮抗醛固酮的作用。呋塞米（D错）为强效排钾利尿剂，易加重肝硬化腹水的低钾，对肝硬化腹水治疗不利，常与保钾利尿剂螺内酯联合使用，而不作为首选。氢氯噻嗪（B错）为中效排钾利尿剂，效果不强且易加重肝硬化腹水的低钾，肝硬化腹水治疗较少使用。","","N"],["2009-N69",40,"第七节 慢性肾小球肾炎","积极控制高血压和减少尿蛋白",2009,69,"A","","下列关于慢性肾炎高血压的治疗方法中正确的是",[["A","顽固性高血压可联合应用降压药"],["B","尿蛋白定量大于等于1g/d，血压应控制在130/80mmHg以下"],["C","尿蛋白定量小于1g/d，血压应控制在125/75mmHg以下"],["D","血肌酐小于400μmol/L时，才能用ACEI"]],"A","慢性肾小球肾炎可引起肾实质性高血压，通常需要联合使用降压药物治疗（A对），将血压控制在130/80mmHg以下。慢性肾炎高血压的治疗目标：尿蛋白≥1g/d时，血压应控制在125/75mmHg以下（B错）；尿蛋白≤1g/d时，血压控制可放宽到130/80mmHg以下（C错）（根据十版内科学，高血压的治疗目标：大多数成年病人目标收缩压应＜120mmHg。尿蛋白的治疗目标：争取减少至＜1g/d）。ACEI类药有扩张肾小球动脉的作用，但扩张出球小动脉比扩张入球小动脉更强，导致肾小球有效滤过压降低，造成肾小球滤过率进一步下降，肾功能恶化。另外，肾功能不全病人血钾偏高，而ACEI类药有保钾作用，应用后会使血清钾进一步升高，严重的高钾血症易引起心脏电生理紊乱，发生室颤和心脏停搏。所以有慢性肾功能不全的病人，当血肌酐不高于264μmol/L时，才能用ACEI（D错）。","","N"],["2009-N70",45,"第一节 慢性肾衰竭","慢性肾衰竭诊断",2009,70,"A","","患者，男，35岁，反复水肿伴血压高5年，近半年夜尿增多，有时牙龈出血，口渴，气促，面色逐渐苍白。曾化验血红蛋白为65g/L，1天前稀便多次后逐渐神志不清。两年前患急性甲型肝炎已愈。为明确昏迷原因，除全面的查体外，首选的检查是",[["A","肝功能和血氨"],["B","血肌酐"],["C","血糖"],["D","骨髓穿刺"]],"B","青年男性患者，反复水肿伴血压高5年（提示有慢性肾脏病病史），近半年出现夜尿增多、牙龈出血、面色逐渐苍白，化验血红蛋白为65g/L（正常成年男性Hb为120g/L～160g/L）提示患者肾功能进一步恶化，几天前稀便多次后神志不清（尿毒症时常有反应淡漠、惊厥、幻觉、昏迷、精神异常等表现）提示进入尿毒症期。因此该患者最可能的诊断为慢性肾衰竭尿毒症期，血肌酐（B对）是慢性肾衰竭诊断和分期的最重要依据，故为明确昏迷原因的首选检查。肝功能和血氨（A错）主要用于肝性脑病（十版内科学P422）的诊断，患者虽有甲型肝炎病史，但已治愈，肝性脑病可能性不大。血糖监测（C错）主要用于糖尿病和低血糖昏迷，本例患者无相关临床表现，故不为首选检查。骨髓穿刺（D错）适用于血液系统疾病的诊断（十版内科学P547），血液系统疾病可出现贫血和牙龈出血等造血功能减退的临床表现，但早期一般不会出现肾衰竭及昏迷。","","N"],["2009-N71",52,"第三节 慢性髓系白血病","细胞遗传学及分子生物学检查",2009,71,"A","","下列白血病类型中不会出现Ph染色体的是",[["A","慢性粒细胞白血病"],["B","慢性淋巴细胞白血病"],["C","急性粒细胞白血病"],["D","儿童急性淋巴细胞白血病"]],"B","Ph染色体是由Nowell及Hungerford于1960年在慢性粒细胞性白血病（CML）患者血中发现的，由于首先在美国费城发现，故也称为费城染色体。Ph染色体为t（9；22）（q34；q11），是9号染色体长臂上原癌基因C-ABL易位至22号染色体长臂的断裂点簇集区（BCR）形成BCR-ABL融合基因。Ph染色体多见于慢性粒细胞白血病（阳性率95%）（A错），也可见于急性粒细胞白血病（1%）（C错）、成人急性淋巴细胞白血病（25%）、儿童急性淋巴细胞白血病（5%）（D错）等，慢性淋巴细胞白血病呈阴性（B对）。","","N"],["2009-N72",56,"第二节 原发免疫性血小板减少症","血清学检查",2009,72,"A","","患者，女，25岁，因皮肤瘀斑伴月经过多2个月来诊，化验血小板为20×10⁹/L，诊断为特发性血小板减少性紫癜，该患者化验血小板相关抗体的主要成分是",[["A","IgG"],["B","IgA"],["C","IgM"],["D","IgD"]],"A","特发性血小板减少性紫癜（ITP）患者化验血小板相关抗体成分有IgG、IgA、IgM，主要成分是IgG（A对）。","","N"],["2009-N73",68,"第一节 类风湿关节炎","类风湿关节炎病因和发病机制",2009,73,"A","","下列关于可能引起类风湿性关节炎的感染因子中，通过活化B淋巴细胞起作用的感染因子是",[["A","支原体"],["B","EB病毒"],["C","大肠杆菌"],["D","链球菌"]],"B","EB病毒仅能在B淋巴细胞中增殖，可使其转化，能长期传代。被病毒感染的细胞具有EBV的基因组，可刺激B细胞大量合成RF（类风湿因子）。RF（类风湿因子）是一种以变性IgG为靶抗原的自身抗体，未经治疗的类风湿性关节炎患者其阳性率为80%，故EB病毒通过活化B淋巴细胞起作用（B对）。支原体（A错）、大肠杆菌（C错）、链球菌（D错）均有可能是本病的直接感染因子，但未能得到证实。","","N"],["2009-N74",69,"第一节 系统性红斑狼疮","抗ENA抗体谱",2009,74,"A","","继发于SLE的干燥综合征患者中，出现的特异性抗体是",[["A","抗SSA抗体"],["B","抗磷脂抗体"],["C","抗RNP抗体"],["D","抗组蛋白抗体"]],"A","系统性红斑狼疮（SLE）患者血清中可查到多种自身抗体。继发于SLE的干燥综合征患者，出现的特异性抗体是抗SSA抗体（A对）和抗SSB抗体。抗磷脂抗体（B错）与SLE患者继发抗磷脂抗体综合征（表现为血栓形成、习惯性流产、血小板减少）有关。抗RNP抗体（抗核糖核蛋白抗体）（C错）与SLE的雷诺现象和肺动脉高压相关（十版内科学P822）。抗组蛋白抗体（D错）属于抗核抗体，可见于多种结缔组织病，缺乏诊断特异性，但对药物性狼疮的诊断及鉴别诊断有重要临床价值。","","N"],["2009-N75",59,"第一节 甲状腺功能亢进症","甲状腺肿",2009,75,"A","","下列关于弥散性Graves病的特点的叙述正确是",[["A","有程度不等的结节性甲状腺肿大"],["B","久病者甲状腺质软无压痛"],["C","肿大程度与甲亢病情轻重明显相关"],["D","极少数无甲状腺肿大"]],"D","Graves病患者甲状腺肿大多为弥漫性、对称性、均匀的肿大，无结节形成。有程度不等的结节性甲状腺肿大为结节性甲状腺肿（非毒性甲状腺肿的结节期）的临床特点，甲状腺呈不对称结节状增大，结节大小不一（A错）。患者一般无压痛，久病者甲状腺质地坚韧（B错）。患者主要临床表现为甲状腺毒症，病情严重程度与病史、激素和年龄相关，而与肿大程度关系不明显（C错）。极少数Graves病患者无甲状腺肿大，而仅表现出明显甲状腺毒症（D对）。","","N"],["2009-N76",61,"第一节 糖尿病","α-葡萄糖苷酶抑制剂（AGI）",2009,76,"A","","下列口服降糖药物中，必须与进食同时服用的是",[["A","甲苯磺丁脲"],["B","氯磺丙脲"],["C","格列本脲"],["D","阿卡波糖"]],"D","阿卡波糖是α-葡萄糖苷酶抑制剂（AGI），通过抑制小肠黏膜刷状缘的α-葡萄糖苷酶，从而延迟碳水化合物吸收，达到降低餐后高血糖的效果（十版内科学P738），故应与进食同时服用（D对）。甲苯磺丁脲（A错）、氯磺丙脲（B错）、格列本脲（C错）均属磺酰脲类降糖药，在餐前半小时服用（十版内科学P737）。","","N"],["2009-N91",35,"","",2009,91,"A","","患者，男，48岁，因患肝硬化5年，近1年来明显腹胀，尿少，食欲下降，下肢水肿来院。查体：一般情况差，腹膨隆，可见腹壁静脉曲张，移动性浊音阳性。该患者还可能出现的体征是",[["A","振水音阳性"],["B","剑突下可闻静脉“营营”音"],["C","肝浊音界消失"],["D","肠鸣音亢进"]],"B","中年男性患者，既往有肝硬化病史，近1年出现腹壁静脉曲张、下肢水肿及腹水征象，提示已进入肝硬化失代偿期。在肝硬化失代偿期，出生后闭合的脐静脉与脐旁静脉于门静脉压力过高时重新开放，位于脐周的腹壁浅表静脉血流增多而曲张，常在脐周、上腹部或剑突下，尤其是腹壁静脉曲张严重处，可闻及静脉连续性“营营”音（B对），无收缩期与舒张期性质。振水音指胃内有多量液体及气体存留时，以冲击触诊法振动胃部，可听到气液撞击音，振水音阳性（A错）常提示幽门梗阻、胃扩张，而肝硬化时由于腹水渗出在腹腔，因此不会出现振水音。肝浊音界消失（C错）常提示腹部空腔脏器穿孔，而肝硬化晚期由于肝脏纤维化，肝脏萎缩，一般肝浊音界缩小但不会消失。肠鸣音亢进（D错）常由肠梗阻、肠道出血、感染及炎性肠病等肠道内病变或刺激因素引起，而肝硬化患者消化吸收功能往往减退，且大量腹水也会使听诊肠鸣音减弱。","c19","N"],["2009-N92",35,"第一节 肝硬化","门腔侧支循环形成",2009,92,"A","","患者，男，48岁，因患肝硬化5年，近1年来明显腹胀，尿少，食欲下降，下肢水肿来院。查体：一般情况差，腹膨隆，可见腹壁静脉曲张，移动性浊音阳性。腹壁静脉曲张血流方向应为",[["A","脐以上静脉血流向上，脐以下血流向下"],["B","脐以上静脉血流向下，脐以下血流向上"],["C","脐以上静脉血流向上，脐以下血流向上"],["D","脐以上静脉血流向下，脐以下血流向下"]],"A","正常时脐水平线以上的腹壁静脉血流自下而上经胸壁静脉和腋静脉而进入上腔静脉，脐水平线以下的腹壁静脉自上向下经大隐静脉而流入下腔静脉。在肝硬化失代偿期，出生后闭合的脐静脉与脐旁静脉于门静脉压力过高时重新开放，位于脐周的腹壁浅表静脉血流增多而曲张，但血流方向较正常时并未改变，即脐以上静脉血流向上，脐以下血流向下（A对）。但当下腔静脉阻塞时，脐水平线以下的腹壁静脉自上向下经大隐静脉流入下腔静脉时受阻而逆流，因此脐部上、下的腹壁静脉血流方向均为自下而上（C错）。","c19","N"],["2009-N93",11,"第一节 胸腔积液","恶性胸腔积液",2009,93,"A","","患者，女，59岁，进行性呼吸困难一个月，无发热，体检示气管向右侧偏移，左侧胸廓饱满，左肺叩诊呈实音，呼吸音消失，诊断为胸腔积液，胸水检查示，外观呈淡黄色，比重1.024，有核细胞数1000×10⁶/L，单核细胞80%，胸水总蛋白36g/L。该患者出现胸水最可能的原因是",[["A","结核性胸膜炎"],["B","缩窄性心包炎"],["C","肺炎"],["D","肺癌"]],"D","该患者为老年女性（恶性胸腔积液常见于45岁以上中老年人），进行性呼吸困难一个月，无发热，胸水检查呈淡黄色，比重＞1.018，白细胞数＞500×10⁶/L，总蛋白＞30g/L（胸水性质为渗出液），出现胸水最可能的原因是肺癌（D对）。结核性胸膜炎（A错）常表现为低热、盗汗、乏力、消瘦、胸痛等结核中毒症状，胸水检查以淋巴细胞为主，蛋白质＞40g/L；缩窄性心包炎（B错）引起的胸腔积液是胸膜毛细血管内静压升高形成的，液体性质为漏出液（透明清亮，比重＜1.016～1.018，白细胞数＜500×10⁶/L，蛋白质＜30g/L）；肺炎性胸腔积液（C错）常表现为发热、咳嗽、咳痰、胸痛，胸水呈草黄色甚或脓性，白细胞明显增高，以中性粒细胞为主，葡萄糖和pH降低。","c20","N"],["2009-N94",11,"第一节 胸腔积液","恶性胸腔积液",2009,94,"A","","患者，女，59岁，进行性呼吸困难一个月，无发热，体检示气管向右侧偏移，左侧胸廓饱满，左肺叩诊呈实音，呼吸音消失，诊断为胸腔积液，胸水检查示，外观呈淡黄色，比重1.024，有核细胞数1000×10⁶/L，单核细胞80%，胸水总蛋白36g/L。对该患者的胸水做进一步检查，下列检查结果支持上述病因诊断的是",[["A","葡萄糖含量4.4mmol/L"],["B","LDH230U/L"],["C","ADA16U/L"],["D","pH7.35"]],"C","恶性胸腔积液，葡萄糖含量＜3.3mmol/L（A错），LDH˃500U/L（B错），ADA＜45U/L（C对），pH˃7.35（D错）（二版八年制内科学P145）。结核性胸腔积液葡萄糖含量＜3.3mmol/L，LDH＞200U/L，ADA˃45U/L，pH＜7.30。","c20","N"],["2009-N95",11,"第一节 胸腔积液","胸膜镜或开胸活检",2009,95,"A","","患者，女，59岁，进行性呼吸困难一个月，无发热，体检示气管向右侧偏移，左侧胸廓饱满，左肺叩诊呈实音，呼吸音消失，诊断为胸腔积液，胸水检查示，外观呈淡黄色，比重1.024，有核细胞数1000×10⁶/L，单核细胞80%，胸水总蛋白36g/L。为明确诊断，最佳的检查方法是",[["A","胸部X线"],["B","胸部B超"],["C","胸水培养"],["D","胸腔镜检查"]],"D","胸部X线片（A错）、胸部B超（B错）均是影像学检查方法，不能用于胸腔积液的定性诊断。胸水培养（C错）主要用于结核性胸腔积液的诊断。胸腔镜检查（D对）能全面检查胸膜，观察病变形态特征、分布范围及邻近器官受累情况，且可在直视下多处活检，对恶性胸腔积液的病因诊断率最高，对于明确肿瘤分期亦较准确，为最佳的确诊检查方法。","c20","N"],["2009-N96",19,"第一节 肥厚型心肌病","肥厚型心肌病诊断",2009,96,"A","","患者，男，36岁，三年来出现劳累后胸闷头晕，一小时前因胸闷自服硝酸甘油后感头晕加重，并出现短暂黑蒙而来院，既往无高血压，无烟酒史，其父有类似病史，查体：120/70mmHg，HR68次/分，双肺（-），心界不大，心律整，胸骨左缘第3～4肋间可闻3/6级收缩期吹风样杂音，A₂减弱。最可能的诊断是",[["A","肥厚型心肌病"],["B","扩张型心肌病"],["C","先天性心脏病"],["D","缺血性心脏病"]],"A","患者劳累后胸闷头晕3年，因胸闷自服硝酸甘油后感头晕加重，并出现短暂黑蒙，胸骨左缘第3～4肋间可闻3/6级收缩期吹风样杂音（肥厚型心肌病常见杂音），A₂减弱，心界不大，无心衰表现，其父有类似病史（肥厚型心肌病为常染色体显性遗传），提示肥厚型心肌病（A对）。肥厚型心肌病最常见的症状是劳力性呼吸困难和乏力，约1/3的患者可有劳力性胸痛，部分患者有晕厥，常于运动时出现，心尖部可听到收缩期杂音，这是因为二尖瓣前叶移向室间隔导致二尖瓣关闭不全，流出道梗阻的患者可于胸骨左缘第3～4肋间闻及较粗糙的喷射性收缩期杂音。扩张型心肌病（B错）以左心室或双心室扩大伴收缩功能障碍为特征，主要临床表现为活动时呼吸困难和活动耐量下降，主要体征为心界扩大，听诊心音减弱，常可及第三或第四心音，心率快时呈奔马律。虽然部分先天性心脏病（C错）如室间隔缺损也可于胸骨左缘第3～4肋间闻收缩期杂音，但发病年龄大多较早，常幼年起病，与本例不符。缺血性心脏病（D错）多有情绪激动、劳累时心前区疼痛，服硝酸甘油后症状应缓解。","c21","N"],["2009-N97",19,"第一节 肥厚型心肌病","肥厚型心肌病超声心动图",2009,97,"A","","患者，男，36岁，三年来出现劳累后胸闷头晕，一小时前因胸闷自服硝酸甘油后感头晕加重，并出现短暂黑蒙而来院，既往无高血压，无烟酒史，其父有类似病史，查体：120/70mmHg，HR68次/分，双肺（-），心界不大，心律整，胸骨左缘第3～4肋间可闻3/6级收缩期吹风样杂音，A₂减弱。应首选的检查是",[["A","心电图"],["B","超声心动图"],["C","心肌核素显像"],["D","冠状动脉造影"]],"B","超声心动图（B对）是诊断肥厚型心肌病临床最主要的检查方法，能观察到室间隔的厚度、心室流出道的情况。肥厚型心肌病无特异性心电图表现（A错），因此心电图无明显诊断意义。心肌核素显像（C错）主要用于心肌梗死的部位及范围的判断，肥厚型心肌病无明显大面积心肌细胞坏死的病理表现，故对其无效。肥厚型心肌病患者行冠状动脉造影（D错）多无异常。","c21","N"],["2009-N98",19,"第一节 肥厚型心肌病","β受体拮抗剂",2009,98,"A","","患者，男，36岁，三年来出现劳累后胸闷头晕，一小时前因胸闷自服硝酸甘油后感头晕加重，并出现短暂黑蒙而来院，既往无高血压，无烟酒史，其父有类似病史，查体：120/70mmHg，HR68次/分，双肺（-），心界不大，心律整，胸骨左缘第3～4肋间可闻3/6级收缩期吹风样杂音，A₂减弱。适宜该患者治疗的药物是",[["A","硝酸酯类"],["B","洋地黄"],["C","利尿剂"],["D","β受体阻滞剂"]],"D","肥厚型梗阻性心肌病首选药物为β受体拮抗剂及钙通道阻滞剂。β受体阻滞剂（D对）可减慢心率并降低心肌收缩力，使舒张期充盈时间延长，室壁张力降低，改善胸痛及劳力性呼吸困难，并具有抗心律失常作用。洋地黄（B错）可增强心肌收缩力，左室流出道两端压力差增大，血流速度加快，导致二尖瓣前叶收缩期前移更加明显（文丘里效应），加重流出道梗阻。硝酸酯类（A错）及利尿剂（C错）可降低心脏容量负荷使左心室舒张末期容积减小，加重左心室流出道梗阻。","c21","N"],["2009-N99",30,"第一节 溃疡性结肠炎","溃疡性结肠炎诊断",2009,99,"A","","患者，女，45岁。反复发作脓血便10余年，此期间有时伴有膝关节疼痛，多次大便细菌培养阴性，X线钡剂检查见乙状结肠袋消失，肠壁变硬，肠管变细。最可能的诊断是",[["A","溃疡性结肠炎"],["B","克罗恩病"],["C","肠结核"],["D","慢性细菌性痢疾"]],"A","中年女性患者，反复脓血便（绝大多数溃疡性结肠炎患者有黏液脓血便）10余年，伴有膝关节疼痛病史（溃疡性结肠炎常见的肠外表现），多次大便细菌培养阴性，X线钡剂检查见乙状结肠袋消失，肠壁变硬，肠管变细（溃疡性结肠炎X线钡剂灌肠典型表现），可以得出该患者最可能的诊断是溃疡性结肠炎（A对）。克罗恩病（十版内科学P392）（B错）多发生于回肠末端，脓血便少见。肠结核（十版内科学P383）（C错）好发于回盲部，常表现为腹泻与便秘交替，X线钡剂灌肠在溃疡型肠结核呈现激惹征象，在增生型肠结核表现为结节状改变。慢性细菌性痢疾（D错）无肠外症状，大便细菌培养常有阳性发现。","c22","N"],["2009-N100",30,"第二节 克罗恩病","腹痛",2009,100,"A","","患者，女，45岁。反复发作脓血便10余年，此期间有时伴有膝关节疼痛，多次大便细菌培养阴性，X线钡剂检查见乙状结肠袋消失，肠壁变硬，肠管变细。该病腹痛的特点是",[["A","腹痛-进食-缓解"],["B","腹痛-进食-加痛"],["C","腹痛-便意-便后缓解"],["D","腹痛-便意-便后无变化"]],"C","溃疡性结肠炎多有轻至中度腹痛，为左下腹或下腹阵痛，亦可累及全腹，腹痛与进食无关，常有里急后重，便后腹痛缓解，腹痛特点是“腹痛-便意-便后缓解”（C对）。克罗恩病常表现为右下腹或脐周阵发性疼痛，常于进餐后加重，排便或肛门排气后缓解，腹痛特点是“进食-加重-便后缓解”。肠结核常表现为脐周、下腹持续性隐痛或钝痛，餐后加重，排便或肛门排气后缓解，腹痛特点是“进食-加重-便后缓解”。“腹痛-进食-缓解”（A错）为十二指肠球部溃疡的腹痛规律，而“腹痛-进食-加痛”（B错）为胃溃疡的腹痛规律。","c22","N"],["2009-N101",30,"第二节 克罗恩病","克罗恩病并发症",2009,101,"A","","患者，女，45岁。反复发作脓血便10余年，此期间有时伴有膝关节疼痛，多次大便细菌培养阴性，X线钡剂检查见乙状结肠袋消失，肠壁变硬，肠管变细。该患者最不可能出现的并发症是",[["A","中毒性巨结肠"],["B","癌变"],["C","肠出血"],["D","肠梗阻"]],"A","中毒性巨结肠、癌变、肠出血、肠梗阻都是溃疡性结肠炎的并发症。中毒性巨结肠多发生在暴发型或重症患者，约5%的重症患者可出现中毒性巨结肠，其临床特征是严重的中毒症状及节段性或全结肠扩张；直肠结肠癌变多见于广泛性结肠炎、幼年起病而病程漫长者，病程越长癌变率越高。而本例患者病程10余年，X线检查提示肠壁变硬，肠管变细，说明肠管管壁因纤维化而增厚，发生中毒性巨结肠的几率很小，发生癌变的几率相对增大。故本例最不可能出现的并发症选择中毒性巨结肠更为合理（A对B错）。","c22","N"],["2009-N102",56,"第二节 原发免疫性血小板减少症","原发免疫性血小板减少症诊断要点",2009,102,"A","","患者，女，30岁，8个月来月经量增多，1周来皮肤瘀斑伴牙龈出血，不挑食，无光过敏和口腔溃疡。查体：脾侧位肋下刚触及。化验血Hb85g/L，RBC4.0×10¹²/L，WBC5.1×10⁹/L，Plt25×10⁹/L，尿常规（-）。骨髓检查：粒红比例正常，全片见巨核细胞138个，其中产板型4个。最可能的诊断是",[["A","再生障碍性贫血"],["B","ITP"],["C","脾功能亢进"],["D","MDS"]],"B","该患者出现月经增多、皮肤瘀斑和牙龈出血（出血症状），血红蛋白85g/L（＜90g/L，为中度贫血），白细胞正常（正常值3.5～9.5×10⁹/L），血小板减少（正常值为125～350×10⁹/L）；脾脏轻度肿大（ITP患者病程超过六个月会出现轻度脾大）；骨髓检查粒红比例正常，产板型巨核细胞显著减少（ITP产板型巨核细胞＜30%），可诊断为ITP（特发性血小板减少性紫癜）（B对）。再生障碍性贫血（十版内科学P555）（A错）是由于造血干细胞受损导致的造血功能衰竭，患者一般三系均减少。脾功能亢进（十版内科学P610）（C错）骨髓巨核细胞无发育障碍，骨髓中不会出现有血小板形成的巨核细胞显著减少。骨髓增生异常综合征（MDS）（十版内科学P572）（D错）表现为外周血三系减少，而骨髓增生活跃。","c23","N"],["2009-N103",56,"第二节 原发免疫性血小板减少症","血清学检查",2009,103,"A","","患者，女，30岁，8个月来月经量增多，1周来皮肤瘀斑伴牙龈出血，不挑食，无光过敏和口腔溃疡。查体：脾侧位肋下刚触及。化验血Hb85g/L，RBC4.0×10¹²/L，WBC5.1×10⁹/L，Plt25×10⁹/L，尿常规（-）。骨髓检查：粒红比例正常，全片见巨核细胞138个，其中产板型4个。最有助于诊断的进一步检查是",[["A","血小板抗体"],["B","腹部B超"],["C","骨髓活检"],["D","骨髓干细胞培养"]],"A","特发性血小板减少性紫癜（ITP）的发病机制是由于患者对自身血小板抗原的免疫失耐受，产生体液免疫和细胞免疫介导的血小板过度破坏和血小板生成受抑，50%～70%的ITP患者血浆和血小板表面可检测到血小板膜糖蛋白特异性自身抗体，如血小板相关抗体（PAIg）和血小板相关补体（PAC₃）。因此最有助于诊断的进一步检查是血小板抗体（A对）。腹部B超（B错）主要用于肝胆、妊娠检查，极少用于血液系统疾病诊断。骨髓活检（C错）为有创检查，本例已得出满意的骨髓检查结果，没必要再做骨髓活检。骨髓干细胞培养（D错）主要用于科研目的，且对本病帮助不大。","c23","N"],["2009-N104",47,"第一节 缺铁性贫血","铁代谢",2009,104,"A","","患者，女，30岁，8个月来月经量增多，1周来皮肤瘀斑伴牙龈出血，不挑食，无光过敏和口腔溃疡。查体：脾侧位肋下刚触及。化验血Hb85g/L，RBC4.0×10¹²/L，WBC5.1×10⁹/L，Plt25×10⁹/L，尿常规（-）。骨髓检查：粒红比例正常，全片见巨核细胞138个，其中产板型4个。若化验血清铁（SI）、铁蛋白（SF）和总铁结合力（TIBC），该患者的检查结果可能是",[["A","SI降低，SF降低，TIBC降低"],["B","SI降低，SF降低，TIBC增高"],["C","SI增高，SF增高，TIBC增高"],["D","SI增高，SF增高，TIBC降低"]],"B","患者长期月经量过多可能导致缺铁性贫血。血清铁蛋白是铁的贮存形式，血清铁是与转铁蛋白结合的铁。缺铁性贫血的患者原料铁缺乏，导致血清铁蛋白降低，血清铁降低。总铁结合力是指每升血清中的转铁蛋白所能结合的最大铁量，实际反映转铁蛋白的水平。缺铁性贫血的患者，机体转铁蛋白合成增强，总铁结合力增高（B对），以增加铁的利用率。","c23","N"],["2009-N105",45,"第一节 慢性肾衰竭","慢性肾衰竭定义和分期",2009,105,"A","","患者，男，50岁，一年来头晕乏力，半月来症状加重伴心悸、纳差、恶心，血压升高为165/105mmHg，化验尿蛋白（++），沉渣RBC4～8/HP，血Hb80g/L，血肌酐610μmol/L，BUN25mmol/L。根据国际公认的“肾脏病生存质量指导”（K/DOQI）的分级，属于哪期",[["A","1期"],["B","2期"],["C","3期"],["D","4期"]],"D","随着临床和基础研究的不断进展，关于慢性肾衰竭的分期标准也在不断更新。美国肾脏病基金会专家组主要依据肾小球滤过率GFR（正常值90～110ml/min）将慢性肾脏病（CKD）分为5期：1期（≥90ml/min）；2期（60～89ml/min）；3期（30～59ml/min）；4期（15～29ml/min）；5期（＜15ml/min）（十版内科学P525）。我国主要依据血肌酐值Scr（正常值44～133μmol/L）将慢性肾功能不全分为4期：肾功能代偿期（133～177μmol/L）；肾功能失代偿期（186～442μmol/L）；肾功能衰竭期（451～707μmol/L）；尿毒症期（≥707μmol/L）。此4期分别对应CKD分期的2、3、4、5期。因此GFR15～29ml/min或血肌酐451～707μmol/L为4期，该患者血肌酐610μmol/L，因此属于4期（D对）。","c24","N"],["2009-N106",45,"第一节 慢性肾衰竭","慢性肾衰竭诊断",2009,106,"A","","患者，男，50岁，一年来头晕乏力，半月来症状加重伴心悸、纳差、恶心，血压升高为165/105mmHg，化验尿蛋白（++），沉渣RBC4～8/HP，血Hb80g/L，血肌酐610μmol/L，BUN25mmol/L。根据肾功能损害程度，该患者符合",[["A","肾功能储备下降期"],["B","氮质血症期"],["C","肾衰竭期"],["D","尿毒症期"]],"C","根据肾脏损害程度（主要依据血肌酐值Scr）将慢性肾功能不全分为4期：肾功能代偿期（133～177μmol/L）；肾功能失代偿期（186～442μmol/L）；肾功能衰竭期（451～707μmol/L）；尿毒症期（≥707μmol/L）。该患者血肌酐610μmol/L，因此符合肾衰竭期（C对）。","c24","N"],["2009-N107",45,"第一节 慢性肾衰竭","水、电解质代谢紊乱",2009,107,"A","","患者，男，50岁，一年来头晕乏力，半月来症状加重伴心悸、纳差、恶心，血压升高为165/105mmHg，化验尿蛋白（++），沉渣RBC4～8/HP，血Hb80g/L，血肌酐610μmol/L，BUN25mmol/L。该患者最不可能出现的电解质紊乱是",[["A","低镁血症"],["B","低钠血症"],["C","低钙血症"],["D","高磷血症"]],"A","慢性肾衰竭时常出现各种电解质代谢紊乱和酸碱平衡失调，其中以代谢性酸中毒和水、钠平衡紊乱最为常见。水、钠代谢平衡紊乱：主要表现为水、钠潴留，少数患者由于长期低钠饮食、进食差、呕吐等，可出现低钠血症（B错）。钾代谢平衡紊乱：肾脏排钾能力下降，易出现高钾血症。钙磷代谢紊乱：主要表现为钙缺乏和磷增多，钙缺乏主要与钙摄入不足、活性维生素D缺乏、高磷血症、代谢性酸中毒等因素有关，明显钙缺乏时可出现低钙血症（C错），当肾小球滤过率下降、尿磷排出减少时，出现高磷血症（D错）。镁代谢紊乱：由于肾脏排镁减少，常有轻度高镁血症，虽镁摄入不足或过多应用利尿剂时可能会出现低镁血症，但很少见（A对）。","c24","N"],["2009-N108",61,"第一节 糖尿病","胰岛素",2009,108,"A","","患者，男，56岁，患糖尿病10年，一直采用饮食控制疗法，空腹血糖持续在10mmol/L，近5年来，口服降糖药格列本脲和阿卡波糖仍未获得良好控制，需采用胰岛素治疗。下列选项中属于长效胰岛素的是",[["A","普通胰岛素"],["B","慢胰岛素锌悬液"],["C","精蛋白锌胰岛素"],["D","低精蛋白胰岛素"]],"C","本题考察胰岛素的分类。胰岛素制剂按作用起效快慢和维持时间长短分为短效、中效、长效胰岛素。短效胰岛素包括普通（正规）胰岛素（A错）、半慢胰岛素锌混悬液；中效胰岛素包括低精蛋白锌胰岛素（中性精蛋白锌胰岛素）（D错）和慢胰岛素锌混悬液（B错）；长效制剂有精蛋白锌胰岛素注射液（鱼精蛋白锌胰岛素）（C对）和特慢胰岛素锌混悬液。","c25","N"],["2009-N109",61,"第一节 糖尿病","胰岛素",2009,109,"A","","患者，男，56岁，患糖尿病10年，一直采用饮食控制疗法，空腹血糖持续在10mmol/L，近5年来，口服降糖药格列本脲和阿卡波糖仍未获得良好控制，需采用胰岛素治疗。近一月来采用强化胰岛素治疗，但是空腹血糖一直过高，为查明原因，下列检查最有意义的是",[["A","夜间多次血糖测定"],["B","睡前胰岛素测定"],["C","血清胰岛素测定"],["D","血清C肽测定"]],"A","患者近一月来采用强化胰岛素治疗，但是空腹血糖一直过高，由于测血糖一般在早晨饭前测量，所以患者早晨空腹血糖较高，可能的原因为：①夜间胰岛素应用不足；②黎明现象：即夜间血糖控制良好，也无低血糖发生，仅于黎明短时间内出现高血糖，可能由于清晨皮质醇、生长激素等分泌增多所致；③Somogyi效应：即在夜间曾有低血糖，在睡眠中未被察觉，但导致体内胰岛素拮抗激素分泌增加，继而发生低血糖后的反跳性高血糖。夜间多次测定血糖，有助于鉴别早晨高血糖的原因（A对）。睡前胰岛素测定（B错）、血清胰岛素检测（C错）、血清C肽测定（D错）对鉴别空腹血糖过高的原因意义不大。","c25","N"],["2009-N110",61,"第一节 糖尿病","糖尿病肾脏病",2009,110,"A","","患者，男，56岁，患糖尿病10年，一直采用饮食控制疗法，空腹血糖持续在10mmol/L，近5年来，口服降糖药格列本脲和阿卡波糖仍未获得良好控制，需采用胰岛素治疗。该患者易发生并发症，下列选项中属于微血管病变并发症的是",[["A","糖尿病足"],["B","冠心病"],["C","糖尿病肾病"],["D","糖尿病酮症酸中毒"]],"C","糖尿病患者可并发各种急慢性并发症，微血管病变是糖尿病的特异性并发症，可累及全身各组织器官，主要表现在视网膜、肾、神经和心肌组织，其中以糖尿病肾病（C对）和视网膜病变尤为重要。糖尿病足（十版内科学P731）（A错）为糖尿病慢性并发症，是与下肢远端神经异常和不同程度周围血管病变相关的足部溃疡、感染和（或）深层组织破坏，不属于微血管病变，也不属于大血管病变，属于独立的分类。冠心病（B错）属于糖尿病大血管病变并发症。糖尿病酮症酸中毒（DKA）（十版内科学P743）（D错）是最常见的糖尿病急症，不属于微血管病变。","c25","N"],["2009-N139",19,"第二节 扩张型心肌病","扩张型心肌病鉴别诊断",2009,139,"B","","扩张型心肌病与心包积液的主要鉴别点是",[["A","奇脉"],["B","腹水"],["C","肝脏肿大"],["D","心界扩大"]],"A","扩张型心肌病心肌弥漫性病变，心腔扩大，心界扩大。心室泵血功能极度减退，收缩末期残留于心室内的血液增多，舒张期心房及静脉血液回流受限，可出现腹水、肝脏肿大、颈静脉怒张等表现，但一般无奇脉。心包积液患者出现心界扩大（D错），且心包内液体压迫心肌，导致心脏舒张功能受限，影响静脉血回流，可出现腹水（B错）、肝脏肿大（C错）、颈静脉怒张等表现。但大量心包积液出现心脏压塞时，可出现奇脉（A对）。","","N"],["2009-N140",22,"第一节 急性心包炎","急性心包炎诊断",2009,140,"B","","渗出性心包炎与缩窄性心包炎的主要鉴别点",[["A","奇脉"],["B","腹水"],["C","肝脏肿大"],["D","心界扩大"]],"D","渗出性心包炎体征为心界向两侧扩大，缩窄性心包炎心浊音界正常或稍增大，因此渗出性心包炎与缩窄性心包炎的主要鉴别为是否存在心界扩大（D对）。大量渗出性心包积液可压迫心脏导致心室舒张功能受限，而缩窄性心包炎心包被致密增厚的纤维化或钙化心包所包围，形成一个固定的心脏外鞘，限制心脏的舒张功能。两者的发病机制有一定的相似之处，都可影响静脉回流，因而均可以出现腹水（B错）、肝脏肿大（C错）等体循环淤血的表现。渗出性心包炎可导致心脏压塞，当有心脏压塞时，吸气时回心血量减少，舒张期充盈不足，心排血量降低，可出现奇脉，而缩窄性心包炎可有奇脉，但不常见（A错）（十版内科学P319），本题原答案选 D。","","N"],["2009-N141",28,"第一节 消化性溃疡","球后溃疡",2009,141,"B","","夜间痛多见且易发生出血的溃疡是",[["A","无症状性溃疡"],["B","幽门管溃疡"],["C","复合性溃疡"],["D","球后溃疡"]],"D","球后溃疡指发生于十二指肠球部以下的溃疡，具有十二指肠球部溃疡的临床特点，但症状较重且夜间疼痛和背部放射痛更为多见，对药物反应较差，较易并发出血（D对）。无症状溃疡（A错）患者无腹痛或消化不良症状，常以上消化道出血、穿孔等并发症为首发症状，可见于任何年龄。幽门管溃疡（B错）餐后很快发生疼痛，早期出现呕吐，易出现幽门梗阻、出血和穿孔等并发症。复合性溃疡（C错）指胃和十二指肠均有活动性溃疡，多见于男性，幽门梗阻的发生率较高。","","N"],["2009-N142",28,"第一节 消化性溃疡","H2RA",2009,142,"B","","用H₂RA维持治疗过程中，复发的溃疡半数以上的是",[["A","无症状性溃疡"],["B","幽门管溃疡"],["C","复合性溃疡"],["D","球后溃疡"]],"A","无症状溃疡患者可无任何症状，这部分患者多在发生出血、穿孔等并发症，或因其他疾病做检查时被发现，多见于老年人。由于NSAIDs（非甾体抗炎药）在老年人使用广泛，且H₂RA（H₂受体拮抗剂）抑酸能力较弱，因此，用H₂RA（H₂受体拮抗剂）维持治疗中复发的溃疡半数以上为无症状性溃疡（A对）。幽门管溃疡（B错）餐后很快发生疼痛，早期出现呕吐，易出现幽门梗阻、出血和穿孔等并发症。复合性溃疡（C错）指胃和十二指肠均有活动性溃疡，多见于男性，幽门梗阻的发生率较高。球后溃疡（D错）指发生于十二指肠球部以下的溃疡，具有十二指肠球部溃疡的临床特点，但症状较重且夜间疼痛和背部放射痛更为多见，对药物反应较差，较易并发出血。","","N"],["2009-N143",60,"第一节 库欣综合征","库欣病",2009,143,"B","","Cushing病的特点是",[["A","血皮质醇升高，ACTH降低，双侧肾上腺增生伴结节"],["B","血皮质醇升高，ACTH升高，双侧肾上腺皮质弥漫增生"],["C","血皮质醇升高，ACTH降低，血钾正常"],["D","血皮质醇升高，ACTH降低，伴明显低钾碱中毒"]],"B","Cushing病为垂体促肾上腺皮质激素（ACTH）分泌亢进所引起的临床类型。由于ACTH分泌过多，导致双侧肾上腺皮质弥漫增生，血皮质醇升高（B对）。血皮质醇升高，ACTH降低，双侧肾上腺增生伴结节（A错）为不依赖ACTH的双侧肾上腺结节性增生的特点。血皮质醇升高，ACTH降低，血钾正常（C错）为肾上腺皮质腺瘤或不依赖ACTH的双侧肾上腺结节性增生的特点。血皮质醇升高，ACTH降低，伴明显低钾碱中毒（D错）为肾上腺皮质癌的特点。","","N"],["2009-N144",60,"第一节 库欣综合征","肾上腺皮质癌",2009,144,"B","","肾上腺皮质腺癌的特点是",[["A","血皮质醇升高，ACTH降低，双侧肾上腺增生伴结节"],["B","血皮质醇升高，ACTH升高，双侧肾上腺皮质弥漫增生"],["C","血皮质醇升高，ACTH降低，血钾正常"],["D","血皮质醇升高，ACTH降低，伴明显低钾碱中毒"]],"D","肾上腺皮质腺癌是原发于肾上腺本身的恶性肿瘤，肿瘤的生长和分泌呈自主性，不受垂体ACTH的调节。由于肿瘤分泌大量的皮质醇，反馈抑制垂体ACTH的释放，导致ACTH降低，甚至不能检测到ACTH。皮质醇具有较弱的醛固酮效应，具有保钠排钾的作用。此外肾上腺皮质癌的癌肿还能分泌大量醛固酮，醛固酮具有保钠排钾的作用，分泌过多可引起水钠潴留和低钾性碱中毒。因此，肾上腺皮质癌可导致明显的低钾性碱中毒（D对）。血皮质醇升高，ACTH降低，双侧肾上腺增生伴结节（A错）为不依赖ACTH的双侧肾上腺结节性增生的特点。血皮质醇升高，ACTH升高，双侧肾上腺皮质弥漫增生（B错）为Cushing病的特点。血皮质醇升高，ACTH降低，血钾正常（C错）为肾上腺皮质腺瘤或不依赖ACTH的双侧肾上腺结节性增生的特点。","","N"],["2009-N169",23,"第一节 感染性心内膜炎","感染性心内膜炎治愈标准",2009,169,"X","","下列选项中，判断感染性心内膜炎治愈标准的有",[["A","脾脏缩小"],["B","应用抗生素后体温正常4～6周"],["C","血红蛋白上升"],["D","应用抗生素2周后血培养阴性"]],"ABC","治疗感染性心内膜炎时，抗生素的疗程至少4～6周，因此应用抗生素2周后血培养阴性说法错误（D错）。感染性心内膜炎的治愈标准包括：应用抗生素4～6周后体温（B对）和血沉恢复正常，自觉症状改善和消失，脾脏缩小（A对），红细胞、血细胞和血红蛋白上升（C对），尿常规转阴，且在停用抗生素后第1、2和6周作血培养均为阴性。","","N"],["2009-N170",13,"第三节 慢性呼吸衰竭","慢性呼吸衰竭病因",2009,170,"X","","导致肺心病Ⅱ型呼吸衰竭患者发生呼吸性酸中毒合并代谢性碱中毒的常见病因有",[["A","使用呼吸兴奋剂"],["B","补碱"],["C","过度机械通气"],["D","利尿"]],"BCD","对于Ⅱ型呼吸衰竭患者而言，合理使用呼吸兴奋剂（A错）能增加呼吸肌做功，增加通气量，能改善呼吸性酸中毒，不会发生代谢性碱中毒；在慢性Ⅱ型呼吸衰竭患者，CO₂潴留发展缓慢，肾脏通过减少HCO₃⁻的排出来维持pH的恒定，体内代偿性地会有较高水平的碳酸氢盐，补碱（B对）则使体内碳酸氢盐的含量过高，导致在呼酸的基础上发生代谢性碱中毒，且补碱不容易控制量，也易造成代谢性碱中毒；Ⅱ型呼吸衰竭时，过度机械通气（C对）可迅速改善呼吸性酸中毒（但仍为呼吸性酸中毒），而代偿性增加的碳酸氢盐却不能很快下降，使体内原有的碳酸氢盐维持在一个较高的水平，导致呼吸性酸中毒合并代谢性碱中毒；使用利尿剂（D对）可抑制Na⁺、Cl⁻重吸收，促进K⁺排出，细胞外液中K⁺减少，细胞H⁺-K⁺交换增加，H⁺进入细胞内导致细胞外液碱中毒，故使用利尿剂容易在原有的呼酸基础上发生低钾低氯性碱中毒。","","N"],["2009-N171",26,"第一节 胃食管反流病","食管外症状",2009,171,"X","","胃食管反流患者中，由反流物引起的临床表现有",[["A","癔球症"],["B","咽喉炎、声嘶"],["C","非季节性哮喘"],["D","反复发生肺炎"]],"ABCD","本题考察的是胃食管反流病的食管外症状。由反流物刺激或损伤食管以外的组织或器官引起的症状称食管外症状，如咽喉炎（B对）、慢性咳嗽和哮喘（C对），严重者可发生吸入性肺炎（D对），一些患者诉咽部不适，有异物感或堵塞感，但无吞咽困难，称为癔球症，目前也认为与GERD相关（A对）。","","N"],["2009-N172",39,"","",2009,172,"X","","下列选项中，属于生理性蛋白尿的有",[["A","直立性蛋白尿"],["B","发热引起的蛋白尿"],["C","分泌性蛋白尿"],["D","组织性蛋白尿"]],"AB","生理性蛋白尿是指在肾脏本身无病变的情况下发生的蛋白尿，多为暂时性出现，多见于青少年。生理性蛋白尿主要分为两类：一类称为功能性蛋白尿，如机体发热（B对）、剧烈运动等应激情况下出现的蛋白尿；另一类称为体位性蛋白尿，多数由于左肾静脉走行于腹主动脉与肠系膜上动脉之间的夹角内，当直立或者运动时，腹内压增加，使夹角过小，压迫左肾静脉，血流瘀滞导致尿蛋白增加，因此常于直立时出现蛋白尿（A对），卧位时消失。分泌性蛋白尿（C错）为肾小管分泌蛋白增多引起的蛋白尿，主要表现是尿中IgA排泄增多，为病理性蛋白尿。组织性蛋白尿（D错）是肾组织细胞代谢产生的、组织破坏分解的、以及肾脏组织炎症或受药物等刺激时泌尿道组织分泌的最终进入尿液中所形成的蛋白尿，其组成以T-H蛋白为主，为病理性蛋白尿。","","N"],["2009-N173",52,"第三节 慢性髓系白血病","中性粒细胞碱性磷酸酶（NAP）",2009,173,"X","","下列疾病中，可出现中性粒细胞碱性磷酸酶阳性率和积分减低的有",[["A","急性淋巴细胞白血病"],["B","急性粒细胞白血病"],["C","急性单核细胞白血病"],["D","慢性粒细胞白血病"]],"BD","NAP（中性粒细胞碱性磷酸酶）主要存在于成熟阶段的中性粒细胞中，其他血细胞均呈阴性反应，NAP阳性率与患者中性粒细胞有无发育障碍直接相关，而与外周血粒细胞总数无关。急性粒细胞白血病（B对）、慢性粒细胞白血病（D对）骨髓增生明显，以幼稚粒细胞为主，中性粒细胞发育障碍，故NAP阳性率降低。另外NAP阳性率降低还见于单纯病毒性感染、PNH（阵发性睡眠性血红蛋白尿）、SLE（系统性红斑狼疮）。急性淋巴细胞白血病（A错）和急性单核细胞性白血病（C错）骨髓增生明显，分别以幼稚淋巴细胞和幼稚单核细胞为主，骨髓粒系增生受抑制，虽然中性粒细胞数量减少，但是中性粒细胞发育无障碍，故NAP阳性率增高。另外NAP阳性率增高还见于再生障碍性贫血、严重化脓性感染、类白血病反应、慢性粒细胞白血病急性变。","","N"],["2009-N174",59,"第一节 甲状腺功能亢进症","甲状腺功能亢进症病因和发病机制",2009,174,"X","","Graves病是由自身抗体引起，这些自身抗体针对的抗原或抗原成分是",[["A","线粒体"],["B","TSH受体"],["C","甲状腺过氧化物酶（TPO）"],["D","甲状腺球蛋白"]],"BCD","抗原指能刺激免疫系统产生抗体或致敏淋巴细胞，并能与其相应抗体或致敏淋巴细胞在体内或体外发生特异性反应的物质。抗线粒体抗体（AMA）见于多种自身免疫病患者，如PBC（原发性胆汁性肝硬化）以及类风湿性关节炎，但甲状腺功能亢进的患者无抗线粒体抗体（A错）。TRAb（促甲状腺激素受体抗体）与TSH（促甲状腺激素）受体结合发挥作用（B对）。甲状腺过氧化物酶抗体（TPOAb）（C对）与甲状腺球蛋白抗体（TgAb）（D对）是自身免疫性甲状腺疾病的重要诊断指标，在Graves病患者血清中常可检测到。","","N"],["2010-N57",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄鉴别诊断",2010,57,"A","","因血管舒缩障碍所致晕厥的疾病是",[["A","颈动脉窦综合征"],["B","高通气综合征"],["C","低血糖综合征"],["D","阿-斯综合征"]],"A","晕厥是指一过性广泛脑供血不足所致短暂的意识丧失状态。晕厥可大致分为4类，包括：1.血管舒缩障碍，见于单纯性晕厥、体位性低血压、颈动脉窦综合征（A对）、排尿性晕厥、咳嗽性晕厥及疼痛性晕厥等；2.心源性晕厥，见于严重心律失常、心脏排血受阻、心肌缺血等，如阵发性心动过速、Q-T间期延长综合征、高度房室传导阻滞等，其中最严重的为阿-斯综合征（D错）；3.脑源性晕厥，见于短暂性脑缺血发作、无脉症、偏头痛等；4.血液成分异常，见于低血糖综合征（C错）、通气过度综合征（过度通气综合征）（B错）、哭泣性晕厥、重度贫血等。刺激颈动脉窦综合征患者的颈动脉窦，将导致迷走神经兴奋，反射性引起外周血管扩张、回心血量及心输出量减少，造成一过性脑供血不足，引起晕厥。正常状态下，大脑的能量供应均来自葡萄糖，在低血糖综合征患者，血糖降低，脑细胞出现代谢障碍，导致大脑功能障碍，引起晕厥。阿-斯综合征，是指突然发作的严重的、致命性缓慢性或快速性心律失常，使心排出量在短时间内锐减，产生严重脑缺血、神志丧失和晕厥等症状。高通气综合征为呼吸中枢调节异常，过度通气超过生理代谢所需而引起的一组症候群，常表现为呼吸困难、肢体麻木、头晕眼花，严重者可有晕厥、抽搐等症状。","","N"],["2010-N58",1,"","",2010,58,"A","","下列疾病中，叩诊检查可发现Kronig峡增宽的是",[["A","肺炎"],["B","肺气肿"],["C","肺结核"],["D","胸腔积液"]],"B","Kronig峡是指肺尖的宽度，正常值为4～6cm。当肺内含气量增大时，Kronig峡增宽，反之变狭窄。肺气肿（B对）、COPD患者肺内含气量增大，故Kronig峡增宽。肺结核（C错）出现肺尖浸润时，可使Kronig峡变狭窄；肺炎、胸腔积液均不会使Kronig峡增宽（AD错）。","","N"],["2010-N60",28,"第一节 消化性溃疡","保护胃黏膜",2010,60,"A","","预防非甾体抗炎药所致消化性溃疡的首选药物是",[["A","硫糖铝"],["B","胶体铋"],["C","米索前列醇"],["D","阿莫西林"]],"C","非甾体抗炎药（NSAID）主要通过抑制环氧合酶（COX）而起作用，COX是花生四烯酸合成前列腺素的关键限速酶，导致胃肠黏膜生理性保护剂前列腺素E合成不足，削弱黏膜的防御和修复功能而导致消化性溃疡发病（十版内科学P374）。米索前列醇（C对）是一种人工合成的前列腺素类似物，具有抑制胃酸分泌、增加胃十二指肠黏膜的黏液及碳酸氢盐分泌和增加黏膜血流等作用，是预防非甾体抗炎药所致消化性溃疡的首选药物。硫糖铝（A错）和胶体铋（B错）作为保护胃黏膜药物，目前临床上已少用；阿莫西林（D错）为消化性溃疡中根除Hp联合治疗方案中的常用抗生素。此三种药物均不用于预防NSAIDs所致消化性溃疡。","","N"],["2010-N61",35,"","",2010,61,"A","","下列关于肝肾综合征临床特点的叙述中，错误的是",[["A","自发性少尿或无尿"],["B","血肌酐升高"],["C","血钠升高"],["D","尿钠降低"]],"C","肝硬化患者出现严重的门脉高压时，内脏的高动力循环血流将使体循环血流量明显减少，又因为多种扩血管物质不能被肝脏灭活，引起体循环血管床扩张，心输出量相对不足和有效血容量不足，肾素-血管紧张素-醛固酮系统和交感神经系统被进一步激活，最终导致肾皮质血管强烈收缩、肾小球滤过率下降，从而出现肾衰竭，即肝肾综合征。肝肾综合征的患者由于肾灌注不足，肾小球滤过率降低，肾小球滤过率降低时：①自发性无尿少尿（A对）；②体内的肌酐排不出去，血肌酐升高（B对）；③体内的水排不出去，产生稀释性低钠血症（C错，为本题正确答案）；④肾素-血管紧张素-醛固酮系统被激活，尿钠重吸收增加，尿钠含量降低（D对）。","","N"],["2010-N62",32,"第二节 肠易激综合征","肠易激综合征诊断与鉴别诊断",2010,62,"A","","女性，32岁，反复发作腹泻3年，伴便前腹痛，便后缓解，体重无变化。近3个月来由于变换工作不顺利等原因，上述症状加重，每日大便5～6次，有黏液，无脓血，使用抗生素治疗效果欠佳。最可能的诊断是",[["A","肠易激综合征"],["B","感染性腹泻"],["C","炎症性肠病"],["D","抗生素相关性腹泻"]],"A","年轻女性患者，反复发作腹痛腹泻3年，便后缓解，粪便有黏液，无脓血，无体重改变，精神因素（工作不顺利）可加重症状，使用抗生素治疗效果欠佳（排除慢性感染），该患者最可能的诊断为肠易激综合征（A对）。感染性腹泻（B错）常有脓血，抗生素治疗有效。炎症性肠病（C错）病程较长者常有体重减轻。抗生素相关性腹泻（D错）一般先有长期抗生素治疗史，后有腹泻，与本例不符。","","N"],["2010-N63",15,"第二节 慢性心力衰竭","6分钟步行试验",2010,63,"A","","女性，48岁。患扩张型心肌病，6分钟步行测试行走320米。该患者的心功能评级应属于",[["A","心功能代偿正常"],["B","轻度心功能不全"],["C","中度心功能不全"],["D","重度心功能不全"]],"C","6分钟步行试验通过评定慢性心衰患者的运动耐力评价心衰严重程度和疗效。6分钟步行距离＜150m为重度心衰；150～450m为中度心衰；＞450m为轻度心衰。该患者患有扩张性心肌病，并且6分钟步行测试行走距离为320m，属于中度心功能不全（C对）。","","N"],["2010-N64",18,"第一节 原发性高血压","血管紧张素Ⅱ受体拮抗剂",2010,64,"A","","下列关于治疗高血压常用的血管紧张素Ⅱ受体拮抗剂作用特点的叙述，错误的是",[["A","降压作用持久、平稳"],["B","治疗剂量窗的范围较窄"],["C","最大降压作用在服药后6～8周出现"],["D","与药物直接相关的不良反应少"]],"B","血管紧张素Ⅱ受体拮抗剂（ARB）的降压作用主要通过拮抗血管紧张素受体亚型AT₁来发挥作用，临床药理基本特点为：多数ARB随剂量增大降压作用增强，治疗剂量窗较宽（B错，为本题正确答案）；降压作用起效缓慢，但持久而平稳（A对），一般在6～8 周时才达最大作用（C对）,作用持续时间能达到24h以上（需要注意区别的是血管紧张素转换酶抑制剂/ACEI的最大作用时间为3～4周）；ARB直接与药物有关的不良反应很少（D对），不会引起刺激性干咳（ACEI的典型常见不良反应），持续治疗的依从性高，但长期应用有升血钾的风险，使用药物期间需监测血钾水平，临床上尤其适用于预防左心室肥厚、心力衰竭、心房颤动，以及糖尿病肾病、冠心病、代谢综合征或糖尿病、微量白蛋白尿或蛋白尿患者，也用于不能耐受ACEI的患者。禁忌症为高血钾、双侧肾动脉狭窄患者及妊娠期妇女。","","N"],["2010-N65",23,"第一节 感染性心内膜炎","心脏",2010,65,"A","","感染性心内膜炎侵犯下列哪个瓣膜最容易并发心力衰竭",[["A","二尖瓣"],["B","三尖瓣"],["C","肺动脉瓣"],["D","主动脉瓣"]],"D","心力衰竭系心脏瓣膜严重受损的结果，最常见于主动脉瓣（D对）病变，发生率达75%，二尖瓣和三尖瓣病变时分别为50%和19%。急性主动脉瓣关闭不全时，左心室反流量突然加大，心搏量不能相应增加，左心室舒张末压急剧上升，可引起急性左心功能不全，甚至诱发心力衰竭。","","N"],["2010-N66",13,"第一节 呼吸衰竭概述","高碳酸血症性呼吸衰竭的发生机制",2010,66,"A","","男性，67岁，COPD患者，多次住院治疗。半年前出院时血气分析示：pH7.37，PaCO₂48mmHg，PaO₂65mmHg。3天前受凉后再次出现咳嗽、咳痰，呼吸困难加重。复查血气分析示：pH7.25，PaCO₂65mmHg，PaO₂52mmHg。该患者低氧血症加重的最重要机制是",[["A","通气血流比例失调"],["B","肺泡通气量下降"],["C","弥散功能障碍"],["D","肺内分流"]],"B","该患者复查血气PaO₂52mmHg＜60mmHg，PaCO₂65mmHg＞50mmHg，诊断为Ⅱ型呼吸衰竭，主要是由于通气功能障碍，肺泡通气量下降（B对），造成CO₂潴留，发生高碳酸血症。通气血流比例失调（A错）、弥散功能障碍（C错）及肺内分流（D错）引起低氧血症，表现换气功能障碍，导致Ⅰ型呼吸衰竭，不会引起PaCO₂升高。","","N"],["2010-N67",4,"第一节 肺炎概述","肺炎治疗",2010,67,"A","","单独使用大环内酯类抗生素不能很好地控制重症社区获得性肺炎的病原体是",[["A","肺炎球菌"],["B","肺炎支原体"],["C","军团菌"],["D","肺炎衣原体"]],"A","社区获得性肺炎是指在医院外罹患的感染性肺实质炎症，常见病原体为肺炎链球菌、支原体、衣原体、流感嗜血杆菌、呼吸道病毒等。肺炎支原体（B错）、军团菌（C错）、肺炎衣原体（D错）一般首选大环内酯类药物治疗。由于我国肺炎链球菌对大环内酯类耐药率高，故对该菌所致的肺炎不单独使用大环内酯类药物治疗（A对）。重症社区获得性肺炎常用内酰胺类联合大环内酯类或氟喹诺酮类药物；青霉素过敏者用呼吸氟喹诺酮类和氨曲南。","","N"],["2010-N68",9,"第一节 肺血栓栓塞症","肺血栓栓塞症溶栓治疗",2010,68,"A","","男性，45岁，突发胸痛、呼吸困难3小时，CTPA显示右下肺动脉干及左下肺动脉分支多处充盈缺损。查体：脉率105次/分，血压80/60mmHg，颈静脉怒张，双肺呼吸音清晰，P₂＞A₂，三尖瓣区可闻及2/6级收缩期杂音，左下肢轻度水肿。此时应采取的主要治疗措施是",[["A","静脉点滴rt-PA"],["B","静脉点滴多巴胺"],["C","皮下注射低分子肝素"],["D","手术治疗"]],"A","患者突发胸痛、呼吸困难3小时（急性肺栓塞的典型症状），CTPA（CT肺动脉造影）显示右下肺动脉干及左下肺动脉分支多处充盈缺损（急性肺栓塞的影像表现），脉率加快、血压降低、颈静脉怒张、肺动脉高压（P₂˃A₂）、左下肢轻度水肿（急性肺栓塞的典型体征），应怀疑急性肺栓塞。患者合并休克，血压降低（收缩压低于90mmHg），考虑高危（大面积）肺栓塞，此时治疗首选溶栓，溶栓的时间窗一般为14天以内，该患者应立即行溶栓治疗。溶栓治疗的药物包括尿激酶、链激酶和重组组织型纤溶酶原激活剂（rt-PA）（A对）。多巴胺（B错）为升压药，可缓解休克症状，但不是主要的治疗措施；低分子肝素（C错）为抗凝剂，多用于防止血栓再形成和复发，是肺栓塞基本的治疗方法，非主要治疗措施；手术治疗（D错）风险大，病死率高，只适用于内科治疗无效的紧急情况。","","N"],["2010-N69",41,"第一节 尿路感染","尿常规检查",2010,69,"A","","慢性肾盂肾炎早期肾功能减退的主要指标是",[["A","血尿素氮升高"],["B","血肌酐升高"],["C","尿浓缩功能减退"],["D","肌酐清除率下降"]],"C","慢性肾盂肾炎原发病灶在肾盂，早期可累及邻近肾髓质中的肾小管，出现肾小管萎缩及肾间质淋巴-单核细胞浸润等慢性炎症表现，导致肾小管功能受损：①尿浓缩功能减退（C对），出现夜尿及低比重尿；②肾小管分泌氢离子和（或）重吸收碳酸氢根离子障碍而产生肾小管酸中毒等。血尿素氮升高（A错）、肌酐清除率下降（D错）、血肌酐升高（B错）均于肾小球滤过功能减退时出现，慢性肾盂肾炎一般在晚期才累及肾小球。","","N"],["2010-N70",40,"第二节 急性肾小球肾炎","急性肾小球肾炎病理表现",2010,70,"A","","男性，16岁，水肿伴尿少1周，3周前有“感冒”史。查体：血压140/90mmHg，眼睑及双下肢水肿，其余未见明显异常。辅助检查：血Hb120g/L，尿蛋白（++++），红细胞15～20/HP，血肌酐180μmol/L，血C3下降，ASO1：800。该患者最可能的肾脏病理改变是",[["A","系膜增生性肾小球肾炎"],["B","毛细血管内增生性肾小球肾炎"],["C","新月体性肾小球肾炎"],["D","局灶节段性肾小球肾炎"]],"B","青少年男性患者，三周前有“感冒”史，ASO（血清抗链球菌溶血素）升高（提示前驱链球菌感染病史）和血清补体C3下降（免疫学异常）与急性肾小球肾炎的发病机制相符。出现血压升高、血尿、蛋白尿及水肿（典型的肾炎综合征），血肌酐180μmol/L（正常成年男性血Cr为53～106μmol/L）提示肾功能轻度减退，诊断考虑急性肾小球肾炎即毛细血管内增生性肾小球肾炎（B对）。系膜增生性肾小球肾炎（A错）及局灶节段性肾小球肾炎（D错）为肾病综合征常见的病理类型，临床上常表现为大量蛋白尿、低蛋白血症、水肿及高脂血症，也可出现血尿（特别是系膜增生性肾小球肾炎），但少有3周上感史和ASO的升高，与该患者表现不符。新月体性肾小球肾炎（C错）是急进性肾小球肾炎的病理类型，早期出现少尿、无尿，肾功能急剧恶化（十版内科学P477），与患者表现不符。","","N"],["2010-N71",47,"第一节 缺铁性贫血","组织缺铁表现",2010,71,"A","","下列缺铁性贫血的临床表现中，属于组织缺铁表现的是",[["A","头晕"],["B","皮肤苍白"],["C","心悸"],["D","异食癖"]],"D","缺铁性贫血的临床表现可分为三类：缺铁原发病表现、贫血表现和组织缺铁表现。异食癖（D对）为缺铁时下丘脑摄食中枢功能紊乱（细胞中含铁酶和铁依赖酶的活性降低）引起的摄食异常，属于组织缺铁表现。头晕（A错）、皮肤苍白（B错）、心悸（C错）均为红细胞数量减少引起的贫血表现。","","N"],["2010-N72",53,"第一节 霍奇金淋巴瘤","霍奇金淋巴瘤临床分期",2010,72,"A","","女性，32岁，右颈部无痛性淋巴结肿大半个月，发热1周，最高体温38.3℃。查体：右颈部和左腋下各触及1个3.0×2.0cm的淋巴结，其余部位淋巴结未见肿大，肝肋下刚触及，脾肋下1cm。颈部淋巴结活检为非霍奇金淋巴瘤。骨髓检查：淋巴瘤细胞占12%，按Ann Arbor提出的淋巴瘤临床分期方案，该患者的分期属于",[["A","ⅡA"],["B","ⅢB"],["C","ⅣA"],["D","ⅣB"]],"D","该患者诊断为非霍奇金淋巴瘤，肝肋下刚触及（已有肝受累），骨髓检查：淋巴瘤细胞占12%（已有骨髓受累），据Ann Arbor分期标准（Ⅳ期：弥漫性单个或多个结外器官受侵犯，伴或不伴相关淋巴结肿大，或孤立性结外器官受侵犯伴远处淋巴结肿大。如肝或骨髓受累，即使局限也属Ⅳ期）可知该患者属于Ⅳ期；该患者为青年女性，有发热症状，据Ann Arbor分期（凡无以下症状者为A组，有以下症状之一者为B组：不明原因发热大于38℃；盗汗；半年内体重下降10%以上）可知，该患者属于B组。综上，该患者的分期属于ⅣB（D对）。","","N"],["2010-N73",59,"第一节 甲状腺功能亢进症","妊娠期甲亢的治疗",2010,73,"A","","女性，32岁，妊娠30周出现心悸、多汗、手颤。辅助检查示：血FT₃、FT₄升高，TSH降低，诊断为Graves病。合理的治疗方法是",[["A","口服丙硫氧嘧啶"],["B","口服甲巯咪唑"],["C","¹³¹I治疗"],["D","手术治疗"]],"A","该患者为妊娠期30周（T3期，即7～9个月），诊断为Graves病，应首选ATD（抗甲状腺药物）治疗，妊娠期首选丙硫氧嘧啶（PTU）（A对），因为PTU和蛋白结合后不易通过胎盘。妊娠期和哺乳期女性禁用¹³¹I治疗（C错）。妊娠T3期（7～9个月）手术可出现流产和麻醉剂致畸，是手术治疗的禁忌证（D错）。","","N"],["2010-N74",62,"","",2010,74,"A","","女性，45岁，1周前查体发现空腹血糖9.2mmol/L，诊断为2型糖尿病，给予口服降糖药治疗。患者饮食欠规律。家属晨起时发现患者呼之不应即来急诊。查体：心率108次/分，呼吸21次/分，幅度较浅，血压140/70mmHg，皮肤潮湿。引起患者昏迷最可能的原因是",[["A","酮症酸中毒"],["B","乳酸酸中毒"],["C","非酮症高渗昏迷"],["D","低血糖"]],"D","该中年女性患者为2型糖尿病，给予口服降糖药（低血糖反应为常见不良反应）治疗。患者饮食不规律，突发昏迷、心率加快（正常为60～100次/分）、皮肤潮湿等交感神经过度兴奋表现，符合低血糖表现（D对）。酮症酸中毒常表现为酸中毒Kussmaul呼吸：呼吸频率增快，呼吸深大，呼吸中可有烂苹果味（A错）。乳酸酸中毒起病较急，有不明原因的深大呼吸、低血压，有时伴恶心、呕吐、腹痛（B错）。非酮症高渗昏迷（高渗性昏迷）起病缓慢，多见于老年T2DM患者，以严重高血糖（血糖一般为33.3～66.8mmol/L）、高血浆渗透压（有效血浆渗透压为320～430mOsm/L）、脱水为特点（C错）。","","N"],["2010-N75",69,"第一节 系统性红斑狼疮","系统性红斑狼疮诊断",2010,75,"A","","女性，32岁，因发热、关节痛2周入院。辅助检查示：血WBC 5.6×10⁹/L，Hb96g/L，Plt108×10⁹/L，网织红细胞3.0％，尿蛋白（+）、RBC5～7/HP。该患者确诊为系统性红斑狼疮，下列辅助检查结果与其病情相符合的是",[["A","Coombs试验（+）"],["B","外周血涂片可见破碎红细胞"],["C","血清抗肾小球基底膜抗体阳性"],["D","尿红细胞位相显示80％红细胞形态正常"]],"A","该患者现确诊为系统性红斑狼疮（SLE）。SLE是一种有多系统损害的慢性自身免疫性疾病，其血清具有以抗核抗体为代表的多种自身抗体，当抗红细胞膜抗体阳性时会有贫血表现。活动性SLE患者贫血常见，其中10%属于Coombs试验阳性的溶血性贫血，故Coombs试验（+）与其病情相符合（A对）。注：Coombs试验（抗人球蛋白试验）（十版内科学P566）是检测血液中温反应性抗体的一种方法，临床上常作为诊断自身免疫性溶血性贫血的重要指标。血清抗肾小球基底膜抗体阳性（C错）多见于Ⅰ型急进性肾小球肾炎（十版内科学P477）。尿红细胞位相显示80%红细胞形态正常（D错）提示非肾小球源性血尿，而狼疮性肾炎血尿主要见于肾小球出现毛细血管袢坏死、有较多新月体形成的患者，为肾小球源性血尿，尿红细胞位相应显示大部分红细胞形态异常。十版内科学P560表6-6-1中指出，外周血涂片出现破碎红细胞（B对）可同时见于血管内溶血和血管外溶血。本题正确答案应为AB，官方参考答案为A。","","N"],["2010-N76",67,"第一节 风湿系统疾病总论","自身抗体",2010,76,"A","","混合结缔组织病患者自身抗体阳性率最高的是",[["A","抗Jo-1抗体"],["B","抗RNP抗体"],["C","抗SS-A抗体"],["D","抗着丝点抗体"]],"B","混合性结缔组织病（MCTD）是一种以系统性红斑狼疮（SLE）、系统性硬化症（SSc）、多发性肌炎和皮肌炎（PM/DM）以及类风湿性关节炎（RA）样症状重叠为特征的风湿病综合征，有极高滴度的抗核糖核蛋白抗体（抗RNP抗体），故抗核糖核蛋白抗体（抗RNP抗体）阳性率最高（B对）。抗Jo-1抗体（A错）为皮肌炎（DM）和多发性肌炎（PM）患者自身抗体阳性率最高的抗体。抗SS-A抗体（C错）阳性主要见于原发性干燥综合征（pSS）和系统性红斑狼疮（SLE）。抗着丝点抗体（ACA）（D错）在硬皮病患者血清中阳性率达90%，在其他结缔组织病中很少见。","","N"],["2010-N91",21,"第三节 二尖瓣狭窄","二尖瓣狭窄诊断",2010,91,"A","","女性，35岁，因心悸1个月就诊。查体：脉率78次/分，血压130/85mmHg，心界向左扩大，心律不整，心率96次/分，心尖部可闻及3/6级收缩期吹风样杂音及舒张期隆隆样杂音，P₂亢进，胸骨左缘第二肋间可闻及柔和的舒张期杂音。该患者最可能的心脏器质性疾病诊断是",[["A","二尖瓣狭窄伴肺动脉瓣关闭不全"],["B","二尖瓣狭窄伴二尖瓣关闭不全"],["C","二尖瓣关闭不全伴肺动脉瓣关闭不全"],["D","二尖瓣狭窄及关闭不全，伴肺动脉瓣关闭不全"]],"B","患者心尖部可闻及3/6级收缩期吹风样杂音为二尖瓣关闭不全的典型体征。心尖部闻及舒张期隆隆样杂音，心界向左扩大，为二尖瓣狭窄的典型体征。当二尖瓣狭窄时，血流从左心房至左心室受阻，可造成左房压和肺静脉压增高，进而引起肺动脉高压，并导致肺动脉扩张，可引起相对性肺动脉瓣关闭不全，可在胸骨左缘第2～4肋间闻及递减型吹风样舒张早期杂音，称Graham-Steel杂音（B对D错）。二尖瓣狭窄伴肺动脉瓣关闭不全（A错）无心尖区全收缩期吹风样杂音。二尖瓣关闭不全伴肺动脉瓣关闭不全（C错）虽然也可出现心室部收缩期吹风样杂音及舒张期隆隆样杂音，但因为血容量增多导致的相对性二尖瓣狭窄引起的杂音强度一般在3级以下，而且其P₂亢进，胸骨左缘第二肋间闻及的杂音为器质性杂音，一般不柔和。","c29","N"],["2010-N92",21,"第三节 二尖瓣狭窄","二尖瓣狭窄临床表现",2010,92,"A","","女性，35岁，因心悸1个月就诊。查体：脉率78次/分，血压130/85mmHg，心界向左扩大，心律不整，心率96次/分，心尖部可闻及3/6级收缩期吹风样杂音及舒张期隆隆样杂音，P₂亢进，胸骨左缘第二肋间可闻及柔和的舒张期杂音。该患者听诊不可能出现的心音特点是",[["A","心尖部第一心音强弱不等"],["B","心尖部可闻舒张早期开瓣音"],["C","心尖部可闻及第四心音"],["D","P₂分裂"]],"C","患者具有心房颤动的表现：心律不齐、心率大于脉率即脉搏短绌，可见伴有心房颤动。第四心音是心房肌在心房收缩末期为克服心室舒张末期压力而用力收缩所产生的震动，也称心房音。房颤时，心房无法产生有效收缩。因而不可能闻及第四心音（C错，为本题正确答案）。心尖部第一心音强弱不等（A对）为房颤的典型表现之一。二尖瓣狭窄时，若前叶柔顺、活动度好，心尖部可闻及舒张早期开瓣音（B对）。二尖瓣狭窄出现肺动脉高压时，右心室射血时间延长，肺动脉瓣关闭形成的S₂成分延迟，与主动脉瓣关闭形成的S₂成分之间的时间差延长，出现P₂分裂（D对）。","c29","N"],["2010-N93",37,"第一节 急性胰腺炎","急性胰腺炎诊断",2010,93,"A","","男性，55岁，2天前酒后出现上腹痛，进行性加重，并向腰背部放散，曾呕吐1次，为胃内容物，呕吐后腹痛未减轻，稀便2次。既往有“胆石症”病史10年，无高血压、糖尿病史。查体：体温37.3℃，脉率80次/分，呼吸20次/分，血压120/80 mmHg，巩膜无黄染，心肺未见异常，腹平软，上腹部轻压痛，肝脾肋下未触及。对该患者最可能的诊断是",[["A","急性肠胃炎"],["B","急性胆囊炎"],["C","十二指肠球后溃疡"],["D","急性胰腺炎"]],"D","中年男性患者，既往有“胆石症”病史10年（胆石症是急性胰腺炎的主要病因），饮酒后上腹痛2天（酒精常与胆道疾病共同导致急性胰腺炎），进行性加重，向腰背部放射（急性胰腺炎腹痛多位于左上腹，向左肩及左腰背部放射），呕吐后腹痛不减轻（呕吐后腹痛不减轻为急性胰腺炎腹痛特点）。据此该患者最可能的诊断为急性胰腺炎（D对）。急性肠胃炎（A错）常有非甾体抗炎药服用、暴饮暴食史，呕吐后腹痛常减轻，一般不会伴腰背部放射痛。急性胆囊炎（B错）常表现为进食油腻食物后右上腹痛，常放射至右肩、肩胛和背部，右上腹压痛，与本例不符。十二指肠球后溃疡（C错）常为慢性病，多为午夜痛，与本例也不符。","c30","N"],["2010-N94",37,"第一节 急性胰腺炎","淀粉酶",2010,94,"A","","男性，55岁，2天前酒后出现上腹痛，进行性加重，并向腰背部放散，曾呕吐1次，为胃内容物，呕吐后腹痛未减轻，稀便2次。既往有“胆石症”病史10年，无高血压、糖尿病史。查体：体温37.3℃，脉率80次/分，呼吸20次/分，血压120/80 mmHg，巩膜无黄染，心肺未见异常，腹平软，上腹部轻压痛，肝脾肋下未触及。为明确诊断，应首先进行的检查是",[["A","血、尿淀粉酶"],["B","便常规和隐血"],["C","腹部CT"],["D","胃镜"]],"A","急性胰腺炎的诊断首选血淀粉酶测定（A对）。腹部CT（C错）虽有助于确定有无胰腺炎，但不作为首选，腹部增强CT可评估胰周炎性及胰腺坏死程度，对急性胰腺炎诊断价值较大，一般应在起病一周左右进行。便常规和隐血（B错）、胃镜（D错）为胃肠道疾病及消化道出血的常用检查方法，对急性胰腺炎的确诊意义不大。","c30","N"],["2010-N95",37,"第一节 急性胰腺炎","禁食",2010,95,"A","","男性，55岁，2天前酒后出现上腹痛，进行性加重，并向腰背部放散，曾呕吐1次，为胃内容物，呕吐后腹痛未减轻，稀便2次。既往有“胆石症”病史10年，无高血压、糖尿病史。查体：体温37.3℃，脉率80次/分，呼吸20次/分，血压120/80 mmHg，巩膜无黄染，心肺未见异常，腹平软，上腹部轻压痛，肝脾肋下未触及。对该患者最基本的治疗是",[["A","解痉止痛"],["B","禁食补液"],["C","抑制胃酸"],["D","静脉注射抗生素"]],"B","补液不充分是重症胰腺炎（SAP）常见的原因之一，对于急性胰腺炎患者，禁食补液，尤其是完全胃肠外营养支持，可减少胃酸分泌，使促胰液素分泌减少，从而减少胰液分泌，减轻胰腺自身消化，有利于胰腺的恢复，是急性胰腺炎最基本的治疗方法（B对）。解痉止痛（A错）、抑制胃酸（C错）、静脉注射抗生素（D错）均为胰腺炎患者一般治疗的措施。","c30","N"],["2010-N96",17,"第四节 急性冠状综合征","急性ST段抬高型心肌梗死诊断",2010,96,"A","","女性，74岁，1周前因股骨颈骨折卧床行保守牵引治疗。8小时前在睡眠中突发心前区疼痛，持续伴阵发加重，出汗，口含硝酸甘油不缓解。既往有高血压、糖尿病病史。入院查体：脉率62次/分，血压110/70mmHg，双肺（-），心脏不大，心律整，A₂＞P₂，双侧脉搏对称。心电图如下所示。对该患者最可能的诊断是",[["A","肺栓塞"],["B","主动脉夹层"],["C","不稳定型心绞痛"],["D","急性心肌梗死"]],"D","该老年患者突发心前区疼痛，持续伴阵发加重，出汗，口含硝酸甘油不缓解（急性心肌梗死的典型临床表现），既往有高血压、糖尿病病史（急性心肌梗死的常见基础疾病），心电图示V₁～V₅导联呈QS波（病理性Q波），ST段弓背向上抬高（急性心肌梗死的典型心电图表现），最可能的诊断考虑为急性心肌梗死（D对）。肺栓塞（A错）以不明原因的呼吸困难及气促为主要表现，可出现胸痛伴咯血，本例虽有胸痛，但无呼吸困难及咯血症状，故不考虑。主动脉夹层（B错）患者往往表现为突发的、剧烈的撕裂样疼痛，多数患者同时伴有难以控制的高血压，两上肢的血压和脉搏可有明显的差别，与本例不符。本例心电图表现有心肌梗死的证据，与不稳定型心绞痛（C错）的心电图特点（多数患者胸痛发作时，一过性ST段抬高或降低，T波低平或倒置）不符。","c31","N"],["2010-N97",17,"第四节 急性冠状综合征","血清心肌坏死标志物",2010,97,"A","","女性，74岁，1周前因股骨颈骨折卧床行保守牵引治疗。8小时前在睡眠中突发心前区疼痛，持续伴阵发加重，出汗，口含硝酸甘油不缓解。既往有高血压、糖尿病病史。入院查体：脉率62次/分，血压110/70mmHg，双肺（-），心脏不大，心律整，A₂＞P₂，双侧脉搏对称。心电图如下所示。为明确诊断，最有价值的检查是",[["A","肌酸激酶同工酶（CK-MB）"],["B","D-二聚体（D-dimer）"],["C","肌钙蛋白T（TnT）"],["D","脑钠肽（BNP）"]],"C","该老年患者突发心前区疼痛，持续伴阵发加重，出汗，口含硝酸甘油不缓解，既往有高血压、糖尿病病史，心电图示V₁～V₅导联呈QS波，ST段弓背向上抬高，可确诊为急性心肌梗死。肌钙蛋白I（cTnI）或T（cTnT）起病3～4小时后升高，cTnI于11～24小时达髙峰，7～10天降至正常，cTnT于24～48小时达高峰，10～14天降至正常。肌钙蛋白测定对诊断心肌损害具有很高的敏感性和特异性，假阳性率低，本例患者急性心肌梗死8小时左右，肌钙蛋白还未降至正常，因此肌钙蛋白（C对）测定是诊断心肌损害最有价值的指标。肌酸激酶同工酶（CK-MB）（A错）灵敏度和特异性不如肌钙蛋白I（cTnI）或T（cTnT）（A错）。D-二聚体（B错）主要用于诊断深静脉血栓（DVT），肺栓塞（PE），弥漫性血管内凝血（DIC）。脑钠肽（BNP）（D错）主要用于诊断心力衰竭，敏感性较高，但特异性不强。","c31","N"],["2010-N98",17,"第四节 急性冠状综合征","抗血小板治疗",2010,98,"A","","女性，74岁，1周前因股骨颈骨折卧床行保守牵引治疗。8小时前在睡眠中突发心前区疼痛，持续伴阵发加重，出汗，口含硝酸甘油不缓解。既往有高血压、糖尿病病史。入院查体：脉率62次/分，血压110/70mmHg，双肺（-），心脏不大，心律整，A₂＞P₂，双侧脉搏对称。心电图如下所示。下列关于该患者的急诊处理措施中，错误的是",[["A","溶栓治疗"],["B","抗凝治疗"],["C","抗血小板治疗"],["D","急诊介入治疗"]],"A","患者1周前发生股骨颈骨折（创伤史），为溶栓治疗的禁忌（A错，为本题正确答案）。凝血酶使纤维蛋白原转变为纤维蛋白是最终血栓形成的关键环节，因此急性心肌梗死需要行抗凝治疗（B对）。各种类型的ACS均需要联合应用包括阿司匹林和ADP受体拮抗剂在内的口服抗血小板药物（十版内科学P246）（C对），负荷剂量后给予维持剂量。本例患者于8小时前（起病3～6小时内，最多12小时以内进行）突发心前区疼痛，且持续伴阵发加重，为急诊介入治疗（PCI）的适应证（D对）。","c31","N"],["2010-N99",12,"第一节 急性呼吸窘迫综合征","急性呼吸窘迫综合征诊断",2010,99,"A","","女性，42岁，因“急性重症胰腺炎”入院。2天来经保守治疗，发热及腹痛略好转，但逐渐出现呼吸困难，予面罩吸氧（氧流量6升/分）后血气分析显示：pH7.52，PaO₂63mmHg，PaCO₂24mmHg。查体：体温38.5℃，呼吸30次/分，血压130/80mmHg，双肺呼吸音清晰，心率105次/分，律整，A₂＞P₂，中上腹压痛（+），肝脾肋下未触及，双下肢无水肿。胸片示双肺外带少许渗出性病变。该患者出现呼吸困难最可能的原因是",[["A","ARDS"],["B","吸入性肺炎"],["C","心力衰竭"],["D","肺栓塞"]],"A","患者急性重症胰腺炎保守治疗2天（72小时内）出现呼吸困难（胰腺炎为ARDS的常见危险因素），面罩吸氧后血气结果为pH7.52，PaO₂63mmHg，PaCO₂24mmHg（pH正常值为7.35～7.45，PaO₂正常值为95～100mmHg，PaCO₂正常值为35～45mmHg），仍然处于低氧血症，呼吸性碱中毒状态，通常吸氧疗法不能改善（ARDS血气特点）。临床上PaO₂/FiO₂≤300mmHg（PaO₂/FiO₂正常值为400～500mmHg）是诊断ARDS的必要条件，本例吸入氧气浓度（%）=21+4×氧流量（L/min）=21+4×6=45%，PaO₂/FiO₂=63/0.45=140mmHg，且胸片示双肺外带渗出性病变（ARDS的影像学表现），符合ARDS诊断，因此该患者出现呼吸困难最可能的原因是ARDS（A对）；吸入性肺炎（B错）通常有误吸史，表现为剧烈咳嗽，晚期才会出现呼吸困难；左心衰竭（P168）常为端坐呼吸，伴粉红色咳痰，胸片显示肺淤血、心脏扩大影，右心衰竭（P167）常表现为颈静脉怒张、肝脾肿大、双下肢水肿等（C错）；肺栓塞（P100）（D错）主要表现为突发呼吸困难，常伴有胸痛、烦躁不安，甚至晕厥，且肺动脉区第二心音亢进（P₂＞A₂）。","c32","N"],["2010-N100",12,"第一节 急性呼吸窘迫综合征","急性呼吸窘迫综合征病理生理",2010,100,"A","","女性，42岁，因“急性重症胰腺炎”入院。2天来经保守治疗，发热及腹痛略好转，但逐渐出现呼吸困难，予面罩吸氧（氧流量6升/分）后血气分析显示：pH7.52，PaO₂63mmHg，PaCO₂24mmHg。查体：体温38.5℃，呼吸30次/分，血压130/80mmHg，双肺呼吸音清晰，心率105次/分，律整，A₂＞P₂，中上腹压痛（+），肝脾肋下未触及，双下肢无水肿。胸片示双肺外带少许渗出性病变。该患者出现低氧血症最主要的机制是",[["A","通气血流比例失衡"],["B","肺泡通气量下降"],["C","弥散功能障碍"],["D","肺内分流"]],"D","ARDS患者出现低氧血症的原因主要为肺毛细血管内皮细胞和肺泡上皮细胞损伤，引起肺间质和肺泡水肿，透明膜形成；肺表面活性物质减少，导致肺萎陷、不张。肺水肿和透明膜形成使呼吸膜增厚，影响气体交换，导致弥散功能障碍；肺萎陷和不张导致流经该区域的血液不能进行有效的气体交换，出现肺内分流。其中肺萎陷和不张导致的肺内分流（D对）为主要机制。通气/血流比例失调（A错）和弥散功能障碍（C错）均可引起低氧血症，但不是引起ARDS顽固性低氧血症最主要的机制。肺泡通气量下降（B错）引起低氧血症和CO₂潴留。","c32","N"],["2010-N101",12,"第一节 急性呼吸窘迫综合征","机械通气",2010,101,"A","","女性，42岁，因“急性重症胰腺炎”入院。2天来经保守治疗，发热及腹痛略好转，但逐渐出现呼吸困难，予面罩吸氧（氧流量6升/分）后血气分析显示：pH7.52，PaO₂63mmHg，PaCO₂24mmHg。查体：体温38.5℃，呼吸30次/分，血压130/80mmHg，双肺呼吸音清晰，心率105次/分，律整，A₂＞P₂，中上腹压痛（+），肝脾肋下未触及，双下肢无水肿。胸片示双肺外带少许渗出性病变。针对该患者呼吸困难的原因，应首选的治疗措施是",[["A","加强抗厌氧菌治疗"],["B","皮下注射低分子肝素"],["C","无创通气"],["D","控制入量，防治心衰发生"]],"C","患者呼吸困难是由于并发了ARDS，给予面罩吸氧，缺氧状态无法纠正。应给予机械通气改善呼吸功能。机械通气是ARDS最重要的支持治疗措施，可改善气体交换，纠正低氧血症，满足机体氧合需要，因此首选的治疗措施为无创通气（C对）；抗感染治疗（加强抗厌氧菌治疗）（A错）适用于ARDS合并感染，单纯ARDS引起的呼吸困难，加强抗厌氧菌治疗无效；皮下注射低分子肝素（B错）能抗凝血，一般在合并DIC时使用，单纯ARDS时使用会加重肺泡出血，加重呼吸困难；控制入量、防止心衰的发生（D错）可以减轻肺水肿，缓解呼吸困难，但不是首选的治疗措施。","c32","N"],["2010-N102",40,"第五节 肾病综合征","肾病综合征诊断",2010,102,"A","","女性，60岁，间断水肿3年，加重1个月，气短、尿少2天。既往有糖尿病病史2年。查体：血压150/90mmHg，腹水征阳性，下肢明显水肿，其余未见异常。辅助检查：尿蛋白（++++），红细胞0～2/HP，血浆白蛋白20g/L。对该患者最可能的诊断是",[["A","慢性肾炎急性发作"],["B","高血压肾损害"],["C","糖尿病肾病"],["D","肾病综合征"]],"D","老年女性患者，尿蛋白（++++）（提示尿蛋白＞3.5g/d），血浆白蛋白20g/L（提示低蛋白血症），腹水征阳性，下肢明显水肿，诊断考虑肾病综合征（D对）。慢性肾炎（A错）病程应至少超过3个月，典型表现为血尿、蛋白尿、水肿及高血压的肾炎综合征，通常尿检可见管型，一般无低蛋白血症。高血压肾损害（B错）肾功能减退首先从肾小管浓缩功能开始，肾小球滤过功能仍可长期保持正常或增强（P250），尿改变轻微，很少出现蛋白尿，血尿不明显，血浆白蛋白一般正常，常有高血压的其他靶器官并发症。糖尿病肾病（C错）所引起的肾病综合征常见于病程10年以上的糖尿病患者。","c33","N"],["2010-N103",40,"第五节 肾病综合征","肾病综合征诊断",2010,103,"A","","女性，60岁，间断水肿3年，加重1个月，气短、尿少2天。既往有糖尿病病史2年。查体：血压150/90mmHg，腹水征阳性，下肢明显水肿，其余未见异常。辅助检查：尿蛋白（++++），红细胞0～2/HP，血浆白蛋白20g/L。对该患者确诊和治疗最有意义的检查是",[["A","尿白蛋白排泄率"],["B","肾功能"],["C","肾活检"],["D","肾脏B超"]],"C","患者诊断为肾病综合征，对该患者确诊和治疗最有意义的检查是肾活检（C对），可以明确病理类型（注：对于肾脏疾病只要需要确诊，首选病理活检），可用于确定治疗方案，评估预后。尿白蛋白排泄率（A错）和肾功能（B错）检测为功能诊断，主要用于急性肾损伤和慢性肾损伤肾功能的分期诊断。肾脏B超（D错）可反映肾脏形态学变化，并不能用于确诊病理类型。","c33","N"],["2010-N104",40,"第五节 肾病综合征","糖皮质激素",2010,104,"A","","女性，60岁，间断水肿3年，加重1个月，气短、尿少2天。既往有糖尿病病史2年。查体：血压150/90mmHg，腹水征阳性，下肢明显水肿，其余未见异常。辅助检查：尿蛋白（++++），红细胞0～2/HP，血浆白蛋白20g/L。对该患者最主要的治疗用药是",[["A","利尿剂"],["B","糖皮质激素"],["C","胰岛素"],["D","血管紧张素转换酶抑制剂"]],"B","肾病综合征的发病机制主要为异常免疫反应激活肾小球内炎症细胞及实质细胞导致滤过膜受损产生蛋白尿及低蛋白血症，继发引起水肿及高脂血症。因此针对其发病机制治疗最重要的为抑制免疫与炎症反应，而糖皮质激素（B对）可通过抑制免疫与炎症反应，抑制醛固酮和抗利尿激素分泌，影响肾小球基底膜通透性等综合作用发挥利尿、消除蛋白尿的疗效。对严重低蛋白血症、高度水肿而又少尿（尿量＜400ml/d）的NS患者，在必需利尿的情况下方可考虑使用利尿剂（A错），但也要避免过频过多。胰岛素（C错）可用于治疗糖尿病及糖尿病肾病，本例患者仅有2年糖尿病史，一般无使用胰岛素必要，对于其肾病综合征治疗意义不大。血管紧张素转换酶抑制剂（D错）除有降低血压作用外，尚有不依赖于降低全身血压而减少尿蛋白的作用，属于对症治疗措施。","c33","N"],["2010-N105",56,"第二节 原发免疫性血小板减少症","原发免疫性血小板减少症诊断要点",2010,105,"A","","女性，26岁，1周来无明显原因出现皮肤散在出血点，伴牙龈出血。1天来出血加重。急诊化验：Plt8×10⁹/L。临床诊断为特发性血小板减少性紫癜（ITP）。支持该患者诊断的临床表现是",[["A","口腔溃疡"],["B","面部蝶形红斑"],["C","脾脏不大"],["D","肌肉血肿"]],"C","特发性血小板减少性紫癜（ITP）患者脾脏一般不大（C对），病程在半年以上者，可有轻度脾大。ITP患者出血为血小板减少所致，主要表现为皮肤、黏膜出血，鼻出血、牙龈出血亦很常见，而关节出血、肌肉血肿（D错）少见（关节出血、肌肉血肿多与凝血功能障碍有关）。口腔溃疡（A错）是发生于口腔黏膜的溃疡性损伤病症，应该注意与口腔黏膜出血区分。面部蝶形红斑（十版内科学P821）（B错）是系统性红斑狼疮的特异性表现，与ITP无关。","c34","N"],["2010-N106",56,"第二节 原发免疫性血小板减少症","出、凝血及血小板功能检查",2010,106,"A","","女性，26岁，1周来无明显原因出现皮肤散在出血点，伴牙龈出血。1天来出血加重。急诊化验：Plt8×10⁹/L。临床诊断为特发性血小板减少性紫癜（ITP）。该患者可能出现的实验室检查结果是",[["A","凝血时间延长，血块收缩良好"],["B","出血时间可延长，血小板平均体积偏大"],["C","抗核抗体阳性，抗磷脂抗体阳性"],["D","骨髓巨核细胞减少，产板型增多"]],"B","凝血时间（CT）是指血液离开血管，在体外发生凝固的时间，反映的是内源性凝血系统的功能，与血小板无关，故ITP患者CT正常；血小板参与血块收缩，ITP患者血小板减少，因此血块收缩不良（A错）。出血时间（BT）是指人为刺破皮肤毛细血管后，从血液自然流出到自然停止所需的时间，受血小板的数量和质量、毛细血管结构和功能的影响，ITP患者血小板减少，故出血时间会延长；ITP患者血小板平均体积偏大（B对）。约70%的病人抗血小板自身抗体阳性，部分病人可检测到抗心磷脂抗体、抗核抗体（C对）。ITP 患者由于血小板减少，骨髓巨核系可代偿性增生，巨核细胞数量正常或增加，产板型巨核细胞数量减少（D 错）。故本题BC均对，原参考答案为B。","c34","N"],["2010-N107",56,"第二节 原发免疫性血小板减少症","急症处理",2010,107,"A","","女性，26岁，1周来无明显原因出现皮肤散在出血点，伴牙龈出血。1天来出血加重。急诊化验：Plt8×10⁹/L。临床诊断为特发性血小板减少性紫癜（ITP）。对该患者应首选的治疗措施是",[["A","血小板成分输注"],["B","静脉点滴长春新碱"],["C","静脉点滴糖皮质激素"],["D","急诊脾切除"]],"A","该患者1天来出血量加重，血小板低于10×10⁹/L，有颅内致命性出血的风险，属ITP急症，需紧急处理。血小板成分输注可迅速提高血小板数量，应作为首选（A对）。此外急症的处理还包括静脉输注丙种球蛋白和大剂量甲泼尼龙，虽然此两种方法作用持久，但没有血小板成分输注起效快，故不作为急症处理的首选（C错）。长春新碱（B错）为ITP二线治疗，糖皮质激素治疗无效时可考虑，不用于急症的处理。脾切除（D错）也为ITP二线治疗，适应证为：1.糖皮质激素治疗无效，病程迁延6个月以上；2.糖皮质激素维持量需大于30mg/d；3.有糖皮质激素使用禁忌证。脾切除不用于急症的处理。有关ITP急症和急症处理的叙述，十版内科学相关内容有更新（P623）。","c34","N"],["2010-N108",61,"第一节 糖尿病","糖尿病并发症检查",2010,108,"A","","男性，65岁，患糖尿病15年，高血压10年。查体：双下肢轻度水肿。尿蛋白（++），血肌酐160μmol/L，眼底检查示视网膜出现棉絮状软性渗出。为明确该患者是否出现糖尿病肾病，应进行的检查是",[["A","尿渗透压"],["B","尿白蛋白排泄率"],["C","糖化血红蛋白"],["D","血、尿β₂微球蛋白"]],"B","糖尿病肾病主要累及肾小球，早期肾小球毛细血管基底膜（GBM）增厚，尿白蛋白排泄率（UAER）增高，晚期肾小球病变更重，部分肾小球硬化，灶状肾小管萎缩及间质纤维化，尿蛋白逐渐增多，UAER显著增高，因此为明确该患者是否出现糖尿病肾病，可行尿白蛋白排泄率（UAER）测定（十版内科学P729）（B对）。尿渗透压测定（A错）是评价肾脏浓缩与稀释功能的指标之一，常与血浆渗量共同使用。糖化血红蛋白（GHbA1）（十版内科学P731）（C错）测定反映患者近8～12周平均血糖水平，为糖尿病控制情况的主要监测目标之一。当肾小管结构或功能受损时，肾小管对正常滤过的小分子量蛋白质（如β₂微球蛋白、溶菌酶等）重吸收障碍。因此血、尿β₂微球蛋白测定（D错）主要用于监测肾小管重吸收功能。","c35","N"],["2010-N109",61,"第一节 糖尿病","口服降糖药物",2010,109,"A","","男性，65岁，患糖尿病15年，高血压10年。查体：双下肢轻度水肿。尿蛋白（++），血肌酐160μmol/L，眼底检查示视网膜出现棉絮状软性渗出。该患者不宜选用的降糖药物是",[["A","胰岛素"],["B","阿卡波糖"],["C","格列喹酮"],["D","二甲双胍"]],"D","该患者患糖尿病15年（超过10年），双下肢水肿，尿蛋白（++），血肌酐160μmol／L（>133μmol/L为肾功能不全），视网膜出现棉絮状软性渗出，可见患者已合并糖尿病肾病和视网膜病变，应首选胰岛素治疗（A错）。阿卡波糖（B错）主要抑制α淀粉酶，T1DM患者在胰岛素治疗基础上加用阿卡波糖有助于降低餐后高血糖，可用于中度肾功能损害。格列喹酮（磺酰脲类）（C错）为促胰岛素分泌剂，可与胰岛素联合应用，经肾脏排泄少，可用于中度肾功能损害。二甲双胍（双胍类药物）（D ）禁用于肾功能不全、肝功不全、缺氧及高热患者，有关肾功能不全的指征，最新教材认为二甲双胍不能用于肾小球滤过率＜30ml/min的患者，本例患者血肌酐160uml/L，属于肾功能代偿期，其肾小球滤过率＞45ml/min，故本题题干与选项设置不够严谨，原答案选D。","c35","N"],["2010-N110",61,"第一节 糖尿病","糖尿病慢性并发症的防治原则",2010,110,"A","","男性，65岁，患糖尿病15年，高血压10年。查体：双下肢轻度水肿。尿蛋白（++），血肌酐160μmol/L，眼底检查示视网膜出现棉絮状软性渗出。为延缓该患者糖尿病肾病的进展，不宜采用的措施是",[["A","使用糖皮质激素"],["B","控制血压"],["C","低蛋白饮食"],["D","控制血糖"]],"A","糖尿病容易并发各种感染（十版内科学P729），糖尿病肾病患者长期使用糖皮质激素可增加感染几率，促进病情恶化（A错，为本题正确答案）。高血压可加速糖尿病肾病的进展和恶化，应选用降压药物（血管紧张素转换酶抑制剂）控制血压（一般应控制在130/80mmHg以下）（B对）。目前主张在糖尿病肾病的早期即应限制蛋白质的摄入，对于肾功能不全的病人，摄入蛋白质宜采用少而精的原则（C对）。控制血糖为治疗糖尿病的基本措施，糖尿病肾病患者应尽早使用胰岛素治疗控制血糖，以延缓糖尿病肾病的进展（D对）。","c35","N"],["2010-N139",35,"第一节 肝硬化","调节神经递质",2010,139,"B","","治疗肝性脑病时，可减少假神经递质形成的药物是",[["A","精氨酸"],["B","谷氨酸钾"],["C","支链氨基酸"],["D","乳果糖"]],"C","支链氨基酸制剂是一种以亮氨酸、异亮氨酸、缬氨酸等为主的复合氨基酸。可竞争性抑制芳香族氨基酸进入大脑，减少假性神经递质的形成，因此治疗肝性脑病时，可减少假神经递质形成的药物是支链氨基酸（C对）。谷氨酸钠或钾（B错）、精氨酸（A错）等药物理论上具有降低血氨的作用，以往曾在临床上广泛应用，但至今尚无证据肯定其疗效。乳果糖（D错）口服后在小肠不会被分解，达到结肠后可被乳酸杆菌、粪肠球菌等细菌分解为乳酸、乙酸而降低肠道的pH。可使肠道细菌产氨减少，减少氨的吸收，并促进血液中的氨渗入肠道排出体外。","","N"],["2010-N140",35,"第一节 肝硬化","及早识别及去除HE发作的诱因",2010,140,"B","","治疗肝性脑病时，可减少氨生成与吸收的药物是",[["A","精氨酸"],["B","谷氨酸钾"],["C","支链氨基酸"],["D","乳果糖"]],"D","乳果糖口服后在小肠不会被分解，达到结肠后可被乳酸杆菌、粪肠球菌等细菌分解为乳酸、乙酸等降低肠道pH值。肠道酸化后对产尿素酶的细菌生长不利，但有利于不产尿素酶的乳酸杆菌的生长，使肠道细菌产氨减少。此外，酸性肠道环境可减少氨的吸收，并促进氨的排出。因此治疗肝性脑病时，可减少氨生成与吸收的药物是乳果糖（D对）。支链氨基酸（C错）可竞争性抑制芳香族氨基酸进入大脑，减少假性神经递质的形成。谷氨酸钠或钾（B错）、精氨酸（A错）等药物理论上具有降低血氨的作用。","","N"],["2010-N141",16,"第三节 房性心律失常","心房颤动诊断",2010,141,"B","","女性，45岁，患风湿性心脏病二尖瓣狭窄20年。近1个月来多次突发心悸，心电图证实为心房颤动，持续几分钟至几小时不等，可自行恢复，应诊断为",[["A","急性心房颤动"],["B","阵发性心房颤动"],["C","持续性心房颤动"],["D","永久性心房颤动"]],"B","房颤分为急性和慢性两类，慢性房颤分为阵发性、持续性、长期持续性和永久性房颤。值得注意的是：慢性房颤的分类只需看最近一次发作持续时间的长短以及是否有自限性，而与以往的发作无关。阵发性心房颤动临床特点为持续时间≤7天（常≤48小时），能自行终止。本例患者中年女性，心电图证实为心房颤动，持续几分钟至几小时不等，可自行恢复，符合阵发性心房颤动（B对）的诊断。急性心房颤动（A错）是指初次发作房颤且在24～48小时以内，短时间内可自行终止。持续性心房颤动（C错）临床特点为房颤持续时间＞7天，非自限性。永久性心房颤动（D错）临床特点为持续时间＞1年，不能终止或终止后又复发，无转复愿望。","","N"],["2010-N142",16,"第三节 房性心律失常","心房颤动诊断",2010,142,"B","","男性，47岁，心悸3年，动态心电图检查示：快心室率心房颤动。曾服用胺碘酮转复为窦性心律并维持。1个月前心房颤动再发。改用电复律成功。应诊断为",[["A","急性心房颤动"],["B","阵发性心房颤动"],["C","持续性心房颤动"],["D","永久性心房颤动"]],"C","房颤分为急性和慢性两类，慢性房颤分为阵发性、持续性、长期持续性和永久性房颤。值得注意的是：慢性房颤的分类只需看最近一次发作持续时间的长短以及是否有自限性，而与以往的发作无关。本例患者中年男性，心悸3年，动态心电图示快心室率心房颤动，曾服用胺碘酮转复为窦性心律并维持，最近一次心房颤动再发为1个月前，为非自限性，但可用电复律转复，患者临床特点符合房颤持续时间＞7天，非自限性的特点，诊断为持续性心房颤动（C对）。急性心房颤动（A错）是指初次发作的房颤且在24～48小时以内，短时间内可自行终止。阵发性心房颤动（B错）临床特点为持续时间≤7天（常≤48小时），能自行终止。永久性心房颤动（D错）临床特点为持续时间＞1年，不能终止或终止后又复发，无转复愿望。","","N"],["2010-N143",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎克雷伯杆菌肺炎治疗",2010,143,"B","","对β内酰胺类抗生素耐药的病原中，主要机制为产生超广谱β内酰胺酶的是",[["A","肺炎链球菌"],["B","军团菌"],["C","铜绿假单胞菌"],["D","肺炎克雷伯杆菌"]],"D","β-内酰胺类抗生素是指化学结构中含有β-内酰胺环的一类抗生素。细菌对β-内酰胺类抗生素产生耐药的机制有：①产生水解酶：β-内酰胺酶是耐β-内酰胺类抗生素细菌产生的一类能使药物结构中的β-内酰胺环水解裂开，失去抗菌活性的酶。能产生超广谱β-内酰胺酶而对β-内酰胺类抗生素产生耐药性的是肺炎杆菌，如肺炎克雷伯杆菌（D对）；能产生羧苄青霉素酶而对β-内酰胺类抗生素产生耐药性的是铜绿假单胞菌（C错）和肠杆菌科；②与药物结合：β-内酰胺酶可与某些耐酶β-内酰胺类抗生素迅速结合，使药物停留在胞质膜外间隙中，不能到达作用靶位；③改变青霉素结合蛋白（PBPs）：PBPs可发生结构改变或合成量增加或产生新的PBPs，使与β-内酰胺类抗生素的结合减少，失去抗菌作用如肺炎链球菌（A错）；④改变菌膜的通透性；⑤增强药物外排；⑥缺乏自溶酶（九版药理学P370-P371）。","","N"],["2010-N144",4,"第二节细菌性肺炎","抗菌药物治疗",2010,144,"B","","对β内酰胺类抗生素耐药的病原中，主要机制为青霉素结合蛋白结构改变的是",[["A","肺炎链球菌"],["B","军团菌"],["C","铜绿假单胞菌"],["D","肺炎克雷伯杆菌"]],"A","细菌对β-内酰胺类抗生素产生耐药的机制有：①产生水解酶：β-内酰胺酶是耐β-内酰胺类抗生素细菌产生的一类能使药物结构中的β-内酰胺环水解裂开，失去抗菌活性的酶。能产生超广谱β-内酰胺酶而对β-内酰胺类抗生素产生耐药性的是肺炎杆菌，如肺炎克雷伯杆菌（D错）；能产生羧苄青霉素酶而对β-内酰胺类抗生素产生耐药性的是铜绿假单胞菌（C错）和肠杆菌科；②与药物结合：β-内酰胺酶可与某些耐酶β-内酰胺类抗生素迅速结合，使药物停留在胞质膜外间隙中，不能到达作用靶位；③改变青霉素结合蛋白（PBPs）：PBPs可发生结构改变或合成量增加或产生新的PBPs，使与β-内酰胺类抗生素的结合减少，失去抗菌作用如肺炎链球菌（A对）；④改变菌膜的通透性；⑤增强药物外排；⑥缺乏自溶酶（九版药理学P370-P371）。","","N"],["2010-N169",75,"第一节 中毒概述","金属中毒解毒药",2010,169,"X","","下列关于急性中毒特殊解毒药的应用，正确的有",[["A","依地酸钙钠治疗铅中毒"],["B","二巯丙醇治疗砷中毒"],["C","去铁胺治疗镁中毒"],["D","亚甲蓝治疗亚硝酸盐中毒"]],"ABD","依地酸钙钠为最常用的氨羧螯合剂，可与多种金属形成稳定而可溶的金属螯合物排出体外，用于治疗铅、锰中毒（A对）。二巯丙醇含有活性巯基，巯基解毒药可进入体内与某些金属形成无毒、难解离但可溶的螯合物由尿排出，用于砷、汞的解毒（B对）。小剂量亚甲蓝可使高铁血红蛋白还原为正常血红蛋白，用于治疗亚硝酸盐、苯胺或硝基苯等中毒引起的高铁血红蛋白血症（D对）。镁中毒用钙剂治疗，去铁胺用于治疗铁、镍中毒（C错）。","","N"],["2010-N170",17,"第三节 慢性冠状动脉综合症","稳定型心绞痛发病机制",2010,170,"X","","稳定型心绞痛的发病机制有",[["A","冠状动脉内斑块形成"],["B","冠状动脉内血栓形成"],["C","冠状动脉痉挛"],["D","冠状循环小动脉病变"]],"ACD","稳定型心绞痛发病机制主要是冠状动脉存在固定狭窄或部分闭塞的基础上发生需氧量的增加。在劳力、情绪激动、饱食、受寒等情况下，一旦心脏负荷突然增加，使心率增快、心肌张力和心肌收缩力增加等而致心肌耗氧量增加，而冠状动脉的供血却不能相应的增加以满足心肌对血液的需求时，即可引起心绞痛。冠状动脉内斑块形成（A对）、冠状动脉痉挛（C对）、冠状循环小动脉病变（D对）都可导致冠脉供血减少，而引起稳定型心绞痛。冠状动脉内血栓形成（B错）可导致急性或亚急性心肌供氧的减少和缺血加重，清除代谢物发生障碍，多引起不稳定型心绞痛。","","N"],["2010-N171",8,"第一节 间质性肺疾病的分类","间质性肺疾病肺功能",2010,171,"X","","间质性肺病的典型肺功能检查结果有",[["A","FEV₁/FVC下降"],["B","CO弥散量下降"],["C","VC下降"],["D","TLC下降"]],"BCD","间质性肺疾病是一组主要累及肺间质和肺泡腔，导致肺泡-毛细血管功能单位丧失的弥漫性肺疾病。临床上主要表现为进行性加重的呼吸困难、限制性通气功能障碍伴弥散功能降低、低氧血症以及影像学上的双肺弥漫性病变。限制性通气功能障碍表现为肺容量包括肺总量（TLC）、肺活量（VC）减少（CD对），一秒钟用力呼气容积/用力肺活量（FEV₁/FVC）正常或增加（A错）；气体交换障碍表现为一氧化碳弥散量（DLCO）减少（B对）、肺泡-动脉氧分压差［P（A-a）O₂］增加和低氧血症。FEV₁/FVC下降主要见于阻塞性通气功能障碍。","","N"],["2010-N172",40,"第三节 急进性肾小球肾炎","急进性肾小球肾炎临床表现",2010,172,"X","","下列关于急进性肾小球肾炎临床特点的叙述中，正确的有",[["A","以急性肾炎综合征起病"],["B","早期出现少尿或无尿"],["C","进行性肾功能恶化"],["D","常伴有中度贫血"]],"ABCD","急进性肾小球肾炎是一组表现为血尿、蛋白尿及进行性肾功能减退（C对）的临床综合征，是肾小球肾炎中最严重的类型，可见于任何年龄，但以青年和中、老年为多，该病可呈急性起病，多数病人在发热或上呼吸道感染后出现急性肾炎综合征（A对），病情发展很快，起病数天内即出现少尿（B对）及进行性肾功能恶化（C对），患者常伴有中度贫血（D对）。","","N"],["2010-N173",50,"第三节 红细胞葡萄糖-6-磷酸脱氢酶缺乏症","G-6-PD发病机制",2010,173,"X","","可出现血管内溶血的疾病有",[["A","遗传性球形细胞增多症"],["B","G6PD缺乏症"],["C","地中海贫血"],["D","阵发性睡眠性血红蛋白尿"]],"BD","阵发性睡眠性血红蛋白尿（PNH）（D对）是一种后天获得性造血干细胞基因突变所致的红细胞膜缺陷性溶血病，临床主要表现为与睡眠有关、间歇发作的慢性血管内溶血和血红蛋白尿。G-6-PD缺乏症（B对）时，红细胞易于被脾脏巨噬细胞吞噬发生血管外溶血，也可发生血管内溶血。遗传性球形细胞增多症（A错）是由红细胞膜缺陷引起的血管外溶血，地中海贫血（C错）属于珠蛋白异常引起的血管外溶血。","","N"],["2010-N174",60,"第二节 原发性醛固酮增多症","血、尿生化检查",2010,174,"X","","下列选项中，符合原发性醛固酮增多症的诊断指标有",[["A","高肾素"],["B","高血钠"],["C","高尿钾"],["D","血中HCO₃⁻浓度升高"]],"BCD","原发性醛固酮增多症（原醛症）是由于肾上腺皮质病变致醛固酮分泌增多，醛固酮具有保钠保水排钾作用。保钠保水可致水、钠潴留，引起高血钠（B对）。排钾增多致低血钾、高尿钾（C对）、碱血症（血中HCO₃⁻浓度升高）（D对）。由于分泌大量的醛固酮，反馈抑制肾素-血管紧张素-醛固酮调节轴，导致肾素降低（A错）。注意：慢性肾衰时，肾小球滤过率降低，也有水、钠潴留，但水潴留比钠潴留更多，最终引起稀释性低钠血症；而原醛症引起水、钠潴留，为醛固酮增多引起，机体其他机制通过肾脏排水正常，钠潴留比水潴留多，最终引起高钠血症。","","N"],["2011-N57",16,"第一节 心律失常概述","持续心电监测",2011,57,"A","","动态心电图检查对评价心律失常临床价值最小的是",[["A","心率变异性"],["B","心律失常类型"],["C","心律失常性质"],["D","心律失常病因"]],"D","动态心电图：又称Holter检测，可连续记录24～72小时心电信号。这样可以提高对非持续性心律失常，尤其是对一过性心律失常及短暂的心肌缺血发作的检出率，对于诊断各种心率变异性（A对）、心律失常类型（B对）、心律失常性质（C对）及了解起搏器工作情况和采取措施预防猝死有重要意义，但无法明确心律失常病因（D错，为本题正确答案）。心脏电生理检查可主动诱发心律失常，以协助诊断并能明确其发病机制及起源部位。","","N"],["2011-N58",37,"","",2011,58,"A","","正常人腹部触诊时，下列结构不能触及的是",[["A","腰椎椎体"],["B","横结肠"],["C","胰腺"],["D","带粪块的乙状结肠"]],"C","胰腺（C对）位于腹膜后部，位置深而质软，正常情况下不能触及，当胰腺病变时，则可在上腹部出现体征。正常腹部可触到的结构有腹直肌肌腹及腱划、腰椎椎体（A错）及骶骨岬、乙状结肠粪块（D错）、横结肠（B错）和盲肠等。形体消瘦及腹壁薄软者，在脐附近中线位常可触到骨样硬度的肿块，自腹后壁向前突出，此即腰椎椎体（A错）或骶骨岬。正常较瘦的人，于上腹部可触及一中间下垂的横行条索，腊肠样粗细，光滑柔软，滑行触诊时可推动，即为横结肠（B错）。正常乙状结肠用滑行触诊法常可触及，内存粪便时更加明显（D错）。","","N"],["2011-N59",15,"第二节 慢性心力衰竭","左心衰竭症状",2011,59,"A","","下列关于高排量型心力衰竭临床表现的叙述，正确的是",[["A","可出现脉压增大"],["B","以全心衰竭为主"],["C","多表现为舒张性心衰"],["D","常见于心动过速的心衰患者"]],"A","高排量型心力衰竭常见于严重贫血、妊娠、甲状腺功能亢进、体循环动静脉瘘、脚气病（维生素B₁缺乏）等疾病（记忆口诀“动脚评价人”），此时外周血管阻力降低、血容量扩大或循环速度加快，静脉回流增加，心脏过度充盈，使机体处于高动力循环状态，患者通常舒张压明显降低，故脉压（收缩压和舒张压之差）明显增大（A对）。严重贫血、甲状腺功能亢进等伴有全身循环血量增多的疾病，心脏的容量负荷增加，早期心室腔代偿性扩大，心肌收缩功能代偿，但心脏结构和功能发生改变超过一定限度后即出现充血性心力衰竭，全心衰竭较少见（B错）。高排量型心力衰竭容量负荷增加、心室扩大时，心室顺应性增加，即使有心室肥厚也不至于出现单纯的舒张性心衰（C错）。单纯的舒张性心衰多见于冠心病和高血压心脏病心功能不全早期。心动过速时，心室舒张期缩短，心室舒张期静脉回心血量减少，多为低排量型心衰的表现（D错）。","","N"],["2011-N60",60,"第二节 原发性醛固酮增多症","原发性醛固酮增多症诊断与病因诊断",2011,60,"A","","患者，男，32岁，发现血压高1年，最高达到170/100mmHg，口服硝苯地平治疗，近半年来出现头晕，发作性全身乏力，手足发麻，口渴，夜尿增多，查尿糖（-），尿蛋白（±），尿比重1.010，钾3.01mmol/L，最可能的诊断是",[["A","原发性高血压"],["B","原发性醛固酮增多症"],["C","肾血管性高血压"],["D","肾实质性高血压"]],"B","原发性醛固酮增多症（原醛症）是由于肾上腺皮质病变致醛固酮分泌增多，醛固酮具有保钠保水排钾作用。保钠保水可致水、钠潴留，引起高血压。排钾增多致低血钾、高尿钾、低钾性碱中毒。因此原醛症的特点为低血钾+高血压。本例患者发现高血压1年，血钾低（正常值3.5～5.3mmol/L），另外还有低血钾所致神经肌肉功能障碍表现（如全身乏力、手足发麻等表现）。据此，该患者最可能的诊断是原发性醛固酮增多症（B对）。原发性高血压（A错）多见于中老年人，高血压病史长达十多年或数十年，一般无低血钾，与本例不符。肾血管性高血压（十版内科学P273）（C错）是由单侧或双侧肾动脉主干或分支狭窄引起的高血压，高血压进展迅速，一般无低血钾，与本例不符。肾实质性高血压（十版内科学272～273）（D错）多见于青少年，既往有肾病史，多表现为顽固性高血压，以舒张压较高、脉压差小为特点，一般无低血钾，与本例不符。","","N"],["2011-N61",9,"第一节 肺血栓栓塞症","肺血栓栓塞症诊断",2011,61,"A","","患者，男，72岁，患有高血压、心绞痛2年，20小时前经股动脉途径行冠状动脉造影显示：升主动脉明显扩张，左前降支95%阻塞，半小时前患者起床后突感胸闷、胸痛、呼吸困难、口唇发绀。血压70/50mmHg，颈静脉明显充盈，血气PaO₂45mmHg，PaCO₂35mmHg，最可能的诊断是",[["A","急性心肌梗死"],["B","主动脉夹层"],["C","急性肺栓塞"],["D","心脏压塞"]],"C","患者老年男性，股动脉插管史，术后卧床20小时（急性肺栓塞的危险因素：术后血管内皮损伤，血液处于高凝状态，静脉血液淤滞），起床时（突然脱落，导致急性肺栓塞）突然出现胸闷、胸痛、呼吸困难（急性肺栓塞的典型临床症状），血压下降（70/50mmHg）、颈静脉明显充盈（急性肺栓塞的典型临床体征）、血气分析示血氧分压降低，故最可能的诊断为急性肺栓塞（C对）。急性心肌梗死（十版内科学P248）（A错）主要表现为胸骨后压榨性疼痛，当右心室心梗或心梗致右心衰时可出现颈静脉怒张和呼吸困难，但不会有过度通气的血气分析结果；主动脉夹层（B错）主要表现为前胸或背部持续性、撕裂样或刀割样剧痛，高血压，两上肢血压相差较大，不会出现颈静脉怒张及低氧血症等表现；题干描述中无心脏压塞（D错）的病因和诱因，故不是最可能的诊断。","","N"],["2011-N62",23,"第一节 感染性心内膜炎","感染性心内膜炎免疫学检查",2011,62,"A","","下列关于感染性心内膜炎诊断检查的叙述，错误的是",[["A","50%的患者的血培养阳性结果获自第一天的血标本"],["B","25%的患者有高丙种球蛋白血症"],["C","可见镜下血尿"],["D","经食管超声心动图可发现直径≤5mm的生物赘生物"]],"A","超声心动图和血培养是诊断感染性心内膜炎的两大基石。在近期未接受过抗生素治疗的患者血培养阳性率可高达95%以上，其中90%以上患者的阳性结果获自入院后第一日采取的标本（A错，为本题正确答案）。经食管超声心动图可检查出≤5mm的赘生物（D对）为九版内科学说法，十版内科学中经食管超声心动图可检查出＜3mm的赘生物。25%的患者有高丙种球蛋白血症（B对），80%患者出现循环中免疫复合物。尿液检查常见镜下血尿（C对）及蛋白尿，少数患者可出现肉眼血尿，提示肾梗死。","","N"],["2011-N63",2,"第一节 支气管哮喘","重度至危重度(1)",2011,63,"A","","患者，男，30岁。哮喘发作已2天，自服氨茶碱、吸入丙酸倍氯松气雾剂无效而来诊，体检：患者神志恍惚，紫绀，有奇脉，两肺满布哮鸣音，HR120次/分，对该患者的紧急处理方法是",[["A","静脉推注氨茶碱并检测血药浓度"],["B","静脉注射地塞米松和β₂受体激动剂"],["C","大量补液、气管插管和机械通气"],["D","静脉滴注抗生素和支气管舒张剂"]],"C","该患者神志恍惚，紫绀，有奇脉，两肺满布哮鸣音，HR120次/分，可知为重度。支气管哮喘发作持续2天，且经氨茶碱、糖皮质激素治疗无效，已出现意识障碍，说明病情恶化，应及时给予气管插管、机械通气同时大量补液维持水、电解质平衡，纠正酸碱失衡（C对）。应用支气管扩张剂，静脉滴注糖皮质激素、氨茶碱和抗生素（ABD错）均为对该患者的辅助治疗手段，不为紧急处理手段。若该患者不出现意识改变，可不进行有创机械通气，可选择应用支气管扩张剂、静脉滴注糖皮质激素、氨茶碱等。若未并发感染不主张早期使用抗生素。","","N"],["2011-N64",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎支原体肺炎诊断",2011,64,"A","","患者，女，16岁，外出郊游后出现头痛、咽痛，伴低热和肌肉酸痛，3天后出现咳嗽和少量黏痰，X胸片检查结果：双肺下叶边缘模糊的斑片状阴影，1周后查体发现鼓膜充血，最可能的诊断是",[["A","军团菌肺炎"],["B","支原体肺炎"],["C","浸润型肺结核"],["D","厌氧菌肺炎"]],"B","患者青年女性，郊游后出现头痛、咽痛，伴低热和肌肉酸痛，咳嗽伴少量黏痰，查体发现鼓膜充血，X线胸片可见双肺下叶边缘模糊的斑片状阴影，该患者最有可能的诊断是支原体肺炎（B对）。支原体肺炎好发于儿童及青年人，主要症状为乏力、咽痛、头痛、咳嗽、发热、腹泻、肌痛、耳痛等，咳嗽多为阵发性呛咳，咳少量黏液，查体可见咽部充血，胸部体检与肺部病变程度常不相称，可无明显体征；军团菌肺炎（A错）患者常表现为疲乏、无力、肌痛、畏寒、高热、咳嗽、咳黏痰带少量血丝或血痰；浸润性肺结核（十版内科学P77）（C错）患者低热、盗汗、乏力及消瘦等全身中毒症状明显；厌氧菌肺炎（十版内科学P49）（D错）多表现为高热、咳臭脓痰，毒血症症状明显。","","N"],["2011-N65",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病发病机制",2011,65,"A","","下列关于阻塞性肺气肿发病机制的阐述，错误的是",[["A","肺纤维化"],["B","呼吸性细支气管狭窄"],["C","气腔过度膨胀"],["D","气腔壁破坏"]],"A","肺气肿的发病机制包括：1.肺内各级支气管、终末肺泡和肺血管的慢性炎症：各类炎症细胞活化、聚集破坏支气管壁和肺泡壁，并释放弹性蛋白酶等活性物质，引起慢性黏液高分泌状态，导致管腔狭窄、形成不完全阻塞，肺泡进一步膨胀（BCD对）。2.蛋白酶-抗蛋白酶失衡机制：蛋白酶系统亢进，对肺组织进行损伤破坏。3.氧化应激机制：超氧阴离子、次氯酸、H₂O₂等氧化物直接破坏细胞及细胞外基质、促进蛋白酶-抗蛋白酶失衡、促进炎症反应。4.其他：自主神经功能失调、营养不良、气温变化等。肺纤维化为间质性肺疾病的病理表现（A错，为本题正确答案）。","","N"],["2011-N66",26,"第一节 胃食管反流病","非典型症状",2011,66,"A","","下列关于胃食管反流病胸痛的叙述，错误的是",[["A","反流物刺激食管痉挛所致"],["B","疼痛可发生在胸骨后"],["C","疼痛不向他处放射"],["D","疼痛可为剧烈刺痛"]],"C","胃食管反流病（GERD）是指胃十二指肠内容物反流入食管引起烧心、反流等症状的疾病，其典型症状为烧心和反流。此外还有一些非典型症状，如胸痛，胸痛由反流物刺激食管痉挛所致（A对），发生在胸骨后（B对），严重时可为剧烈刺痛（D对），可放射到后背、胸部、肩部、颈部、耳后（C错，为本题正确答案）。","","N"],["2011-N67",35,"第一节 肝硬化","肝肾综合征",2011,67,"A","","下列属于肝硬化肝肾综合征诊断标准的是",[["A","肝硬化不合并腹水"],["B","有休克"],["C","近期未使用肾毒性药物"],["D","血肌酐123μmol/L"]],"C","肝肾综合征是指发生在严重肝病基础上的肾衰竭，但肾脏本身并无器质性损害，故进行肝肾综合征的诊断标准之一是近期未使用肾毒性药物（肾毒性药物可造成肾脏本身器质性损害）（C对）。其他诊断标准还有：①肝硬化合并腹水（A错）；②急进型血清肌酐浓度在2周内升至2倍基线值，或＞226μmol/L（25mg/L），缓进型血清肌酐＞133μmol/L（15mg/L）（D错）；③停利尿剂至少2天以上并经白蛋白扩容后，血肌酐值没有改善。④排除休克（B错）；⑤排除肾实质性疾病。","","N"],["2011-N68",37,"第一节 急性胰腺炎","急性胰腺炎辅助检查",2011,68,"A","","患者，男，40岁。8小时前开始上腹剧烈疼痛。查体：上腹部有压痛。此时对确诊价值不大的检查是",[["A","血淀粉酶"],["B","尿淀粉酶"],["C","心电图"],["D","X线腹部平片"]],"B","中年男性患者，8小时前开始上腹剧烈疼痛，上腹部压痛，应考虑可能诊断的为急性胰腺炎、消化性溃疡穿孔、急性心肌梗死等。急查血淀粉酶可排除或肯定急性胰腺炎的诊断（A错）。可作心电图检查用以排除急性心肌梗死（C错）。作X线腹部平片检查用以排除消化性溃疡穿孔（D错）。尿淀粉酶升高较晚，在发病后12～14小时开始升高，该患者发病仅8小时，尿淀粉酶仍未增高，不能用于鉴别诊断（B对）。","","N"],["2011-N69",40,"第二节 急性肾小球肾炎","急性肾小球肾炎病因和发病机制",2011,69,"A","","下列关于急性肾小球肾炎发病机制的叙述，错误的是",[["A","常由β-溶血性链球菌感染所致"],["B","感染严重程度与病变轻重一致"],["C","可通过循环免疫复合物而致病"],["D","可通过原位免疫复合物形成而致病"]],"B","急性肾小球肾炎简称急性肾炎，以急性肾炎综合征为主要临床表现，起病急骤，患者可出现水肿、高血压、血尿及蛋白尿。常因β-溶血性链球菌“致肾炎菌株”（常见为A组12型和49型等）感染所致（A对），感染的严重程度与急性肾炎的发生和病变轻重并不完全一致（B错，为本题正确答案）。本病主要由感染所诱发的免疫反应引起，目前认为链球菌的致病抗原系胞质成分或分泌蛋白，诱发免疫反应后可通过循环免疫复合物沉积于肾小球致病（C对），或种植于肾小球的抗原与循环中的特异抗体相结合形成原位免疫复合物而致病（D对）。","","N"],["2011-N70",40,"第六节 无症状性血尿和_或蛋白尿","无症状性血尿和_或蛋白尿实验室检查",2011,70,"A","","患者，男，40岁，常规体检时发现镜下血尿，尿红细胞5～8/HP，尿蛋白（-），肾功能正常，血压120/80mmHg，B超示双肾未见明显异常，在诊断时，首选的检查是",[["A","肾脏CT检查"],["B","肾穿刺活检"],["C","相差显微镜尿红细胞形态"],["D","静脉肾盂造影检查"]],"C","该患者在常规体检时肾脏功能正常，血压正常，亦无蛋白尿，唯一异常是镜下血尿，因此可怀疑为无症状性血尿。对该患者首先应确定尿中红细胞的来源，新鲜尿沉渣相差显微镜检查可以区别血尿来源（C对）。肾小球源性血尿为变形红细胞（肾小球基底膜破坏，红细胞通过时受血管内压力挤压受损），非肾小球源性血尿为均一形态正常红细胞尿，可除外由于下尿路疾病所致的血尿（十版内科学P475）。肾脏CT检查（A错）为影像学检查，主要用于肾实质损伤、病变的检查，B超显示双肾无明显异常，因此不选择CT检查。肾穿刺活检（B错）主要为明确诊断、指导治疗和判断预后，对组织病理学诊断很有帮助，为有创检查，用于在确诊为肾小球性血尿后确定肾小球疾病的病理类型。静脉肾盂造影检查（D错），属于影像学检查，主要用于慢性肾盂肾炎的诊断。","","N"],["2011-N71",47,"第一节 缺铁性贫血","补铁治疗",2011,71,"A","","下列治疗缺铁性贫血的铁剂中，不良反应最明显的是",[["A","琥珀酸亚铁"],["B","富马酸亚铁"],["C","硫酸亚铁"],["D","葡萄糖酸亚铁"]],"C","缺铁性贫血的治疗包括病因治疗和补充铁剂，铁剂分为无机铁和有机铁：硫酸亚铁为无机铁；琥珀酸亚铁（A错）、富马酸亚铁（B错）、葡萄糖酸亚铁（D错）均属于有机铁。无机铁剂的不良反应较有机铁剂明显，故不良反应最明显的是硫酸亚铁（C对）。","","N"],["2011-N72",52,"第二节 急性白血病","中枢神经系统",2011,72,"A","","急性淋巴细胞白血病引起的中枢神经系统白血病常发生的时间是",[["A","起病时"],["B","化疗时"],["C","缓解时"],["D","耐药时"]],"C","急性淋巴细胞白血病是最易发生中枢神经系统浸润的白血病类型，可发生于疾病各时期，尤其是治疗后缓解期（C对）。","","N"],["2011-N73",59,"第一节 甲状腺功能亢进症","肌肉骨骼系统",2011,73,"A","","下列有关Graves病引起的甲亢性周期性瘫痪的叙述，正确的是",[["A","多见于20～40岁成年女性"],["B","激烈运动可诱发"],["C","病变主要累及上肢"],["D","有低钠血症"]],"B","甲亢性周期性瘫痪多见于20～40岁亚洲男性（A错）。发病前多无明显前驱症状，常在一定诱因如饱餐、疲劳、精神紧张、激烈运动等情况下发作（B对）。临床主要表现为双侧对称性肌无力，双下肢最易受累（C错）。发作时常伴有低钾血症，而非低钠血症（D错）。","","N"],["2011-N74",60,"第一节 库欣综合征","心血管表现",2011,74,"A","","早期Cushing综合征主要的临床表现是",[["A","高血压"],["B","向心性肥胖"],["C","满月脸"],["D","多血质"]],"A","库欣综合征的早期表现：以高血压为主（A对），向心性肥胖（B错）、满月脸（C错）、多血质（D错）、紫纹等典型表现不明显。","","N"],["2011-N75",68,"第一节 类风湿关节炎","类风湿关节炎关节表现",2011,75,"A","","下列关于类风湿关节炎关节表现的叙述，错误的是",[["A","可有明显而持久的晨僵"],["B","关节结构破坏有一定的可逆性"],["C","受累关节多具对称性、持续性"],["D","凡受累关节均可肿胀"]],"B","类风湿关节炎是以侵蚀性、对称性多关节炎为主要临床表现的慢性、全身性自身免疫性疾病。受累关节可出现晨僵、疼痛、压痛、肿胀及活动受限，多具对称性、持续性（C对）。关节肿多因关节腔内积液或关节周围软组织炎症引起，凡受累关节均可肿胀（D对）。由于炎症的加剧和缓解反复交替进行，引起关节软骨和关节囊的破坏，最终导致关节强直畸形且不可逆（B错，为本题正确答案）。晨僵是类风湿关节炎患者常见的体征，也是类风湿关节炎的重要诊断依据之一。其临床表现为患者早晨起床后关节及其周围僵硬感，持续时间常超过1小时，故类风湿关节炎患者可有明显而持久的晨僵（A对）。","","N"],["2011-N76",69,"第一节 系统性红斑狼疮","系统性红斑狼疮抗磷脂综合征",2011,76,"A","","下列关于系统性红斑狼疮（SLE）继发性抗磷脂抗体综合征（APS）的概述，正确的是",[["A","不出现在SLE的活跃期"],["B","可表现为血小板正常"],["C","只表现为静脉血栓形成"],["D","可表现为习惯性自发性流产"]],"D","抗磷脂抗体综合征（APS）是指由抗磷脂抗体（APL抗体）引起的一组临床征象的总称，常发生在系统性红斑狼疮的活跃期（A错）。临床主要表现为动静脉血栓形成（C错）、习惯性自发性流产（D对）、血小板减少（B错）和神经精神症状等。","","N"],["2011-N91",17,"第四节 急性冠状综合征","乳头肌功能失调或断裂",2011,91,"A","","患者，男，46岁。5天前因压榨性胸痛伴大汗3小时来院，诊断急性前壁心肌梗死。因拒绝介入及溶栓治疗而按常规行保守处理，1天后症状缓解，此后病情平稳，4小时前，患者再次发作胸痛，持续50分钟，心尖部可闻3/6级收缩晚期吹风样杂音。该患者出现杂音最可能的病因是",[["A","心力衰竭"],["B","腱索断裂"],["C","乳头肌功能不全"],["D","室间隔穿孔"]],"C","该患者5天前出现急性前壁心肌梗死，4小时前再次发作胸痛，持续50分钟，心尖部可闻及3/6级收缩中晚期吹风样杂音，考虑由乳头肌功能不全（C对）导致。产生杂音的机制：二尖瓣乳头肌因缺血、坏死等使收缩功能发生障碍，造成不同程度的二尖瓣脱垂并关闭不全，心尖区出现收缩中晚期喀喇音和吹风样收缩期杂音。心力衰竭一般不会出现心尖部的杂音（A错）。乳头肌功能不全占急性心肌梗死的发生率高达50%，亦可导致乳头肌断裂，但腱索断裂极少见（B错）。急性心肌梗死并发症偶为室间隔破裂造成穿孔，典型表现为胸骨左缘第3～4肋间出现响亮的收缩期杂音，常伴有震颤（D 错）。","c40","N"],["2011-N92",17,"第四节 急性冠状综合征","血清心肌坏死标志物",2011,92,"A","","患者，男，46岁。5天前因压榨性胸痛伴大汗3小时来院，诊断急性前壁心肌梗死。因拒绝介入及溶栓治疗而按常规行保守处理，1天后症状缓解，此后病情平稳，4小时前，患者再次发作胸痛，持续50分钟，心尖部可闻3/6级收缩晚期吹风样杂音。下列检查指标升高对诊断再梗死意义最大的是",[["A","cTnT"],["B","CK-MB"],["C","LDH"],["D","AST"]],"B","该患者5天前出现急性前壁心肌梗死，4小时前再次发作胸痛，持续50分钟，心尖部可闻及3/6级收缩中晚期吹风样杂音，诊断为乳头肌功能不全。肌酸激酶同工酶CK-MB升高：在起病后4小时内增高，16～24小时达高峰，3～4天恢复正常，其增高的程度能较准确地反映梗死的范围。CK-MB不如cTnT、cTnI敏感，但在心肌梗死后3～4天即可恢复正常，若出现CK-MB再次升高，提示再次发生心肌梗死（B对），故其诊断意义最大。肌钙蛋白T（cTnT）：肌钙蛋白I（cTnI）或T（cTnT）起病3～4小时后升高，cTnI于11～24小时达高峰，7～10天降至正常，cTnT于24～48小时达高峰，10～14天降至正常，本例5天前发生急性心肌梗死，cTnT（A错）仍未恢复正常，故不能用于诊断再发心肌梗死。乳酸脱氢酶（LDH）（C错）和天门冬氨酸氨基转移酶（AST）（D错）测定的特异性及敏感性均远不如心肌坏死标记物，临床上少用。","c40","N"],["2011-N93",11,"","",2011,93,"A","","患者，男，74岁，因发热，咳嗽，呼吸困难1周来院。查体：体温38.8℃，脉率：80次/分，血压140/80mmHg，未见颈静脉充盈，右中下肺叩浊，语音震颤减弱，呼吸音消失，左肺可闻及散在干性啰音，心界向左扩大，心律不整，心率100次/分，未闻杂音，腹（-）。该患者的主要疾病是",[["A","肺炎"],["B","气胸"],["C","胸腔积液"],["D","心力衰竭"]],"C","患者发热，咳嗽，呼吸困难1周，右中下肺叩浊，语音震颤减弱，呼吸音消失，心界向左扩大，考虑该患者的主要疾病是右侧胸腔积液（C对）。肺炎（十版内科学P51）（A错）时，肺部叩诊为浊音，语音震颤增强并可闻及支气管呼吸音；气胸（十版内科学P132）（B错）时，起病急骤，突感一侧胸痛，针刺样或刀割样，肺部叩诊为过清音或鼓音，心或肝浊音界缩小或消失。左心衰竭（十版内科学P179）常表现为肺淤血，咳粉红色泡沫痰，不同程度的呼吸困难，肺部可闻及从局限于肺底直至全肺的湿啰音；右心衰（十版内科学P179）常表现为体循环淤血，肝大，颈静脉充盈，双下肢水肿等（D错）。","c41","N"],["2011-N94",11,"第一节 胸腔积液","胸腔积液临床表现",2011,94,"A","","患者，男，74岁，因发热，咳嗽，呼吸困难1周来院。查体：体温38.8℃，脉率：80次/分，血压140/80mmHg，未见颈静脉充盈，右中下肺叩浊，语音震颤减弱，呼吸音消失，左肺可闻及散在干性啰音，心界向左扩大，心律不整，心率100次/分，未闻杂音，腹（-）。该患者还可能出现的体征有",[["A","气管向左移位"],["B","可闻胸膜摩擦音"],["C","双侧肋间隙变窄"],["D","左上肺支气管呼吸音"]],"A","患者发热，咳嗽，呼吸困难1周，右中下肺叩浊，语音震颤减弱，呼吸音消失，心界向左扩大，考虑为右侧胸腔积液。右侧中等量以上胸腔积液时，使气管、纵隔向左移位（A对），右侧胸廓饱满，肋间隙（非双侧）增宽（C错）。该患者右中下肺叩浊，表明积液量较多，此时脏壁层胸膜分离，不能闻及胸膜摩擦音（B错）。右侧胸腔积液可挤压肺组织，使右侧积液区上方的肺部气体含量减少，密度增大，类似于实变，因此在右侧积液区上方的肺部（非左上肺）可闻及支气管呼吸音（D错）。","c41","N"],["2011-N95",11,"第一节 胸腔积液","胸腔积液实验室检查",2011,95,"A","","患者，男，74岁，因发热，咳嗽，呼吸困难1周来院。查体：体温38.8℃，脉率：80次/分，血压140/80mmHg，未见颈静脉充盈，右中下肺叩浊，语音震颤减弱，呼吸音消失，左肺可闻及散在干性啰音，心界向左扩大，心律不整，心率100次/分，未闻杂音，腹（-）。为明确病因，应采取的最佳检查方法是",[["A","胸部CT"],["B","胸部B超"],["C","胸部X线片"],["D","胸腔穿刺"]],"D","患者发热，咳嗽，呼吸困难1周，右中下肺叩浊，语音震颤减弱，呼吸音消失，心界向左扩大，考虑为右侧胸腔积液。胸腔穿刺对明确积液性质及病因诊断具有重要意义，大多数积液的原因通过胸水分析可确定。该患者发热、咳嗽、呼吸困难，提示有肺部炎症，疑为渗出液，因此为明确胸腔积液的原因，应行胸腔穿刺（D对）。胸部B超（B错）、胸部X线片（C错）均可以确诊胸腔积液，但均不能用于病因诊断；胸部CT（A错）对于胸腔积液病因的诊断具有重要作用，但不是最佳的检查方法。","c41","N"],["2011-N96",23,"第一节 感染性心内膜炎","感染性心内膜炎诊断",2011,96,"A","","患者，女，22岁，5年前发现心脏杂音，2个月来乏力、头晕、食欲下降，四肢关节疼痛。1周来活动后气短，夜间反复憋醒而来院就诊，查体：体温37．8℃，脉率96次/分，血压120/60mmHg，消瘦，睑结膜苍白，可见小出血点，右肺底少许小水泡音，心界不大，心律整，心尖部S₁减弱，胸骨左缘第三肋间可闻舒张期叹气样杂音，肝脾肋下均可及，下肢不肿。血红蛋白84g/L，白细胞12.1×10⁹/L，红细胞沉降率（血沉）38mm/第1小时末，尿常规红细胞2～4/HP。该患者最主要的疾病是",[["A","风湿热"],["B","肺炎"],["C","缺铁性贫血"],["D","感染性心内膜炎"]],"D","青年女性患者，5年前发现心脏杂音（提示存在基础性心脏器质性病变），出现活动后气短、夜间反复憋醒1周，低热（正常体温36.4～37.3℃）（提示存在炎症感染），睑结膜苍白，可见小出血点，右肺底少许小水泡音，心尖部S₁减弱，胸骨左缘第3肋间可闻舒张期叹气样杂音（提示主动脉瓣关闭不全，为感染性心内膜炎的常见并发症），肝脾肋下均可及，下肢不肿，诊断考虑（亚急性）感染性心内膜炎（D对），系因中毒症状较轻，病程较长。风湿热（A错）患者多有心脏炎、关节炎、环形红斑、皮下结节及舞蹈病等特异性症状，与本例不符。本例患者为多系统损害表现，且伴有明显的主动脉瓣关闭不全杂音，不能单纯的用肺炎（B错）和缺铁性贫血（C错）来解释。","c42","N"],["2011-N97",23,"第一节 感染性心内膜炎","感染性心内膜炎血培养",2011,97,"A","","患者，女，22岁，5年前发现心脏杂音，2个月来乏力、头晕、食欲下降，四肢关节疼痛。1周来活动后气短，夜间反复憋醒而来院就诊，查体：体温37．8℃，脉率96次/分，血压120/60mmHg，消瘦，睑结膜苍白，可见小出血点，右肺底少许小水泡音，心界不大，心律整，心尖部S₁减弱，胸骨左缘第三肋间可闻舒张期叹气样杂音，肝脾肋下均可及，下肢不肿。血红蛋白84g/L，白细胞12.1×10⁹/L，红细胞沉降率（血沉）38mm/第1小时末，尿常规红细胞2～4/HP。对确诊意义最大的检查是",[["A","CRP"],["B","胸部X线片"],["C","血培养"],["D","血清铁蛋白"]],"C","患者可初步诊断为感染性心内膜炎。确诊感染性心内膜炎，最有意义的检查是血细菌培养（C对）。CRP（C反应蛋白）（A错）提示急性期感染，不具有诊断特异性。感染性心内膜炎胸部X线片（B错）无特异性表现，部分病人可见脓毒性肺栓塞引起的肺多处小片状浸润影，仅用作辅助诊断。血清铁蛋白含量测定（D错）用于辅助诊断缺铁性贫血。","c42","N"],["2011-N98",23,"第一节 感染性心内膜炎","心脏杂音",2011,98,"A","","患者，女，22岁，5年前发现心脏杂音，2个月来乏力、头晕、食欲下降，四肢关节疼痛。1周来活动后气短，夜间反复憋醒而来院就诊，查体：体温37．8℃，脉率96次/分，血压120/60mmHg，消瘦，睑结膜苍白，可见小出血点，右肺底少许小水泡音，心界不大，心律整，心尖部S₁减弱，胸骨左缘第三肋间可闻舒张期叹气样杂音，肝脾肋下均可及，下肢不肿。血红蛋白84g/L，白细胞12.1×10⁹/L，红细胞沉降率（血沉）38mm/第1小时末，尿常规红细胞2～4/HP。该患者心脏杂音最可能的瓣膜异常是",[["A","主动脉瓣关闭不全"],["B","肺动脉瓣关闭不全"],["C","二尖瓣关闭不全"],["D","三尖瓣关闭不全"]],"A","患者可初步诊断为感染性心内膜炎。胸骨左缘第3肋间闻及舒张期叹气样杂音，为主动脉瓣关闭不全的典型杂音（A对），且脉压增大（60mmHg）及心尖部S₁减弱均支持该诊断。肺动脉瓣关闭不全（B错）听诊为胸骨左缘第2肋间听到舒张期杂音，其性质与主动脉瓣关闭不全相似，但音调较后者为低。二尖瓣关闭不全（C错）的典型杂音为心尖区全收缩期吹风样杂音，可伴有收缩期震颤。三尖瓣关闭不全（D错）听诊为胸骨左缘第4～5肋间全收缩期杂音，偶可在剑突区最响，当右心室明显增大致心脏转位时此杂音可位于心尖区。","c42","N"],["2011-N99",28,"第一节 消化性溃疡","消化性溃疡诊断",2011,99,"A","","患者，男，35岁。3个月来间断上腹痛，有时夜间痛醒，反酸。1天前黑便1次，无呕血，但腹痛减轻，化验大便隐血强阳性。最可能的诊断是",[["A","慢性胃炎"],["B","胃溃疡"],["C","十二指肠溃疡"],["D","胃癌"]],"C","青年男性患者，慢性间断上腹痛3月病史，偶伴夜间痛及反酸，可初步考虑为十二指肠球部溃疡。出现黑便且腹痛减轻（出血后血液可中和胃酸从而减轻腹痛）（十版内科学P375），大便隐血试验强阳性说明出现了消化道出血的并发症。十二指肠溃疡较胃溃疡更易发生消化道出血，因此本例患者最可能的诊断为十二指肠溃疡（C对）。胃溃疡（B错）多表现为餐后痛，少有夜间痛，且多发于中老年人，与本例不符。慢性胃炎（A错）多无典型症状，腹痛无节律性，出血较少发生，与本例不符。胃癌（D错）好发于老年人，腹痛无节律性。","c43","N"],["2011-N100",28,"第一节 消化性溃疡","上消化道内镜检查及活检",2011,100,"A","","患者，男，35岁。3个月来间断上腹痛，有时夜间痛醒，反酸。1天前黑便1次，无呕血，但腹痛减轻，化验大便隐血强阳性。为了确定诊断，首选的检查是",[["A","胃镜检查"],["B","钡餐透视"],["C","腹部CT"],["D","腹部B超"]],"A","十二指肠溃疡并发出血首选检查方法为胃镜检查（A对），钡餐透视（B错）的检查效果不如胃镜检查直观、准确，仅用于对胃镜检查有禁忌或不愿接受胃镜检查者，故不作为首选检查。腹部CT（C错）、腹部B超（D错）不能用于消化性溃疡的诊断。","c43","N"],["2011-N101",28,"第一节 消化性溃疡","出血",2011,101,"A","","患者，男，35岁。3个月来间断上腹痛，有时夜间痛醒，反酸。1天前黑便1次，无呕血，但腹痛减轻，化验大便隐血强阳性。若患者出现黑便，每日出血量最少应超过",[["A","30mL"],["B","50mL"],["C","150mL"],["D","300mL"]],"B","出血为消化性溃疡的常见并发症，出现黑粪提示出血量至少超过50ml（B对）。","c43","N"],["2011-N102",51,"第一节 骨髓增生异常性肿瘤","难治性贫血",2011,102,"A","","患者，男，52岁，3个月来乏力，面色苍白。化验血Hb62g/L，WBC3.2×10⁹/L，分类N66%，L30%，M4%，Plt68×10⁹/L，骨髓增生明显活跃，原始粒细胞4%，成熟粒细胞分叶过多，胞浆内颗粒少，红系有巨幼样变，全片见巨核细胞54个，易见小巨核细胞。骨髓铁染色见环状铁粒幼细胞11%，染色体检查见-7，诊断为MDS。按照FAB分型，该例MDS最可能的类型是",[["A","RA"],["B","RAS"],["C","RAEB"],["D","CMML"]],"A","FAB协作组主要根据MDS患者外周血、骨髓中的原始细胞比例、形态学改变及单核细胞数量，将MDS分为5型：难治性贫血（RA）、环形铁粒幼细胞性难治性贫血（RAS）、难治性贫血伴原始细胞增多（RAEB）、难治性贫血伴原始细胞增多转变型（RAEB-t）、慢性粒-单核细胞性白血病（CMML）。RA：外周血原始细胞＜1%；骨髓原始细胞＜5%。RAS：外周血原始细胞＜1%；骨髓原始细胞＜5%，环形铁幼粒细胞˃有核红细胞15%。RAEB：外周血原始细胞＜5%；骨髓原始细胞5%～20%。RAEB-t：外周血原始细胞≥5%；骨髓原始细胞＞20%而＜30%，或幼粒细胞出现Auer小体。CMML：外周血原始细胞＜5%，单核细胞绝对值＞1×10⁹/L；骨髓原始细胞5%～20%。该患者骨髓原始粒细胞4%，环形铁幼粒细胞11%，按FAB诊断标准诊断为RA（A对）。","c44","N"],["2011-N103",51,"第一节 骨髓增生异常性肿瘤","WHO分型",2011,103,"A","","患者，男，52岁，3个月来乏力，面色苍白。化验血Hb62g/L，WBC3.2×10⁹/L，分类N66%，L30%，M4%，Plt68×10⁹/L，骨髓增生明显活跃，原始粒细胞4%，成熟粒细胞分叶过多，胞浆内颗粒少，红系有巨幼样变，全片见巨核细胞54个，易见小巨核细胞。骨髓铁染色见环状铁粒幼细胞11%，染色体检查见-7，诊断为MDS。按照WHO新的分型，该例MDS最可能的类型是",[["A","RA"],["B","RAS"],["C","RCMD"],["D","RAEB"]],"C","2008年WHO对MDS的分型（八版教材）进行了修订，保留了FAB分型的RA、RAS/RARS、RAEB；增加了难治性血细胞减少伴单系病态造血（RCUD）；将RA或RARS中伴有2系或3系增生异常者单独列为难治性血细胞减少伴多系病态造血（RCMD），将仅有5号染色体长臂缺失的RA独立为5q⁻综合征；还新增加了MDS未能分类（u-MDS）。该患者骨髓中红系有巨幼样变，粒系成熟粒细胞分叶过多，巨核系易见小巨核细胞，表明红系、粒系、巨核系3系病态造血，按2008版的WHO分型应为RCMD（C对）。2016年WHO再次对MDS的分型进行修订（九版教材），根据最新2016版WHO分型，该例应为MDS-MLD。","c44","N"],["2011-N104",51,"第一节 骨髓增生异常性肿瘤","骨髓增生异常性肿瘤治疗",2011,104,"A","","患者，男，52岁，3个月来乏力，面色苍白。化验血Hb62g/L，WBC3.2×10⁹/L，分类N66%，L30%，M4%，Plt68×10⁹/L，骨髓增生明显活跃，原始粒细胞4%，成熟粒细胞分叶过多，胞浆内颗粒少，红系有巨幼样变，全片见巨核细胞54个，易见小巨核细胞。骨髓铁染色见环状铁粒幼细胞11%，染色体检查见-7，诊断为MDS。下列治疗方法中，目前该例尚不宜选用的是",[["A","司坦唑醇"],["B","联合化疗"],["C","全反式维甲酸"],["D","促红细胞生成素"]],"B","该患者为MDS中的难治性血细胞减少伴多系病态造血（RCMD），以贫血为主，恶变率极低，无需化疗（B对）；难治性贫血伴原始细胞增多（RAEB）和难治性贫血伴原始细胞增多转变型（RAEB-t）有向白血病转化的倾向，恶变率为40%～60%，应行联合化疗。司坦唑醇（A错）和红细胞生成素（D错）均属于促造血剂，能改善造血，无论哪种MDS均能适用。全反式维甲酸（C错）可诱导分化，少部分患者可改善血象，也可应用于RCMD。","c44","N"],["2011-N105",40,"第五节 肾病综合征","微小病变型肾病",2011,105,"A","","患者，男，20岁，因大量蛋白尿1个月入院，病前无上呼吸道感染史。查体：血压120/80mmHg，双下肢有明显可凹性水肿。入院后诊断为肾病综合征，为明确病理类型，行肾穿刺活检，电镜下见有广泛的肾小球脏层上皮细胞足突消失。该患者最可能的病理类型是",[["A","膜性肾病"],["B","微小病变型肾病"],["C","系膜增生性肾小球肾炎"],["D","局灶性节段性肾小球硬化"]],"B","光镜下肾小球基本正常，电镜下有广泛的肾小球脏层上皮细胞足突消失，为微小病变型肾病（B对）的典型病理特点。膜性肾病（十版内科学P482）（A错）的病理特点为光镜下可见钉突形成，广泛足突融合，上皮下沉积物，基底膜增厚。系膜增生性肾小球肾炎（十版内科学P482）（C错）电镜下特点为系膜细胞增生，在系膜区可见到电子致密物。局灶性节段性肾小球硬化（十版内科学P481）（D错）电镜下可见肾小球上皮细胞足突广泛融合、基底膜塌陷，系膜基质增多，电子致密物沉积。","c45","N"],["2011-N106",40,"第五节 肾病综合征","微小病变型肾病",2011,106,"A","","患者，男，20岁，因大量蛋白尿1个月入院，病前无上呼吸道感染史。查体：血压120/80mmHg，双下肢有明显可凹性水肿。入院后诊断为肾病综合征，为明确病理类型，行肾穿刺活检，电镜下见有广泛的肾小球脏层上皮细胞足突消失。下列选项中，该病理类型的临床特点是",[["A","多见于成年女性"],["B","多伴有镜下血尿"],["C","表现为典型的肾病综合征"],["D","有明显的肾功能减退"]],"C","微小病变型肾病典型的临床表现为肾病综合征（C对），男性多于女性（A错），儿童高发，成人发病率降低。微小病变型肾病一般无持续性高血压及明显的肾功能减退（D错），仅15%左右的患者可有镜下血尿（B错）。","c45","N"],["2011-N107",40,"第五节 肾病综合征","糖皮质激素",2011,107,"A","","患者，男，20岁，因大量蛋白尿1个月入院，病前无上呼吸道感染史。查体：血压120/80mmHg，双下肢有明显可凹性水肿。入院后诊断为肾病综合征，为明确病理类型，行肾穿刺活检，电镜下见有广泛的肾小球脏层上皮细胞足突消失。首选的治疗方法是",[["A","单用糖皮质激素"],["B","单用细胞毒药物"],["C","糖皮质激素联合用细胞毒药物"],["D","单用环孢素A"]],"A","微小病变型肾病患者对糖皮质激素敏感，故初期可单用糖皮质激素治疗（A对），仅在疾病反复发作（复发率较高）或单用糖皮质激素效果不佳时，可以联合应用细胞毒药物（BC错）。环孢素A（D错）仅用于治疗激素及细胞毒性药物无效的难治性肾病综合征。","c45","N"],["2011-N108",59,"第一节 甲状腺功能亢进症","心血管系统",2011,108,"A","","患者，男，55岁。因心悸伴消瘦1周来诊。查体：脉率84次/分，血压148/60mmHg，甲状腺弥漫性Ⅱ度肿大，可闻及血管杂音，肺（-）；心率112次/分。心律绝对不整，心音强弱不等，腹（-）。该患者的心律失常类型是",[["A","心房颤动"],["B","心房扑动"],["C","频发早搏"],["D","二度Ⅱ型房室传导阻滞"]],"A","该患者脉搏短绌（脉率＜心率），心律绝对不整，心音强弱不等（为房颤的典型三大体征）。因此该患者的心律失常类型是心房颤动（A对）。心房扑动（十版内科学P200）（B错）心室率规则或不规则，与本例不符。频发早搏（C错）、二度Ⅱ型房室传导阻滞（D错）第一心音强度恒定，与本例不符。","c46","N"],["2011-N109",59,"第一节 甲状腺功能亢进症","心血管系统",2011,109,"A","","患者，男，55岁。因心悸伴消瘦1周来诊。查体：脉率84次/分，血压148/60mmHg，甲状腺弥漫性Ⅱ度肿大，可闻及血管杂音，肺（-）；心率112次/分。心律绝对不整，心音强弱不等，腹（-）。产生心律失常的最可能原因是",[["A","冠心病"],["B","甲亢性心脏病"],["C","心肌病"],["D","高血压病"]],"B","患者为中老年男性，表现为心悸伴消瘦（甲亢高代谢症状主要表现为易激动、心悸、乏力、怕热、多汗、消瘦、食欲亢进等），甲状腺弥漫性Ⅱ度肿大，可闻及血管杂音（甲亢患者常有程度不等的弥漫性甲状腺肿大，甲状腺上、下级可以触及震颤，闻及血管杂音）。综上所述，该患者可诊断为甲亢。又甲亢是最常见的出现房颤的非心脏病性疾病，因此该患者产生心律失常的最可能原因是甲亢性心脏病（B对）。冠心病（A错）患者常表现为胸骨压榨性疼痛，有明显劳累诱因，有高血压、高血脂、糖尿病等易患因素，与本例不符。心肌病（十版内科学P278）早期表现为活动后气促、乏力，无典型甲亢症状，与本例不符。高血压病（D错）既往有高血压病史，与本例不符。","c46","N"],["2011-N110",59,"第一节 甲状腺功能亢进症","甲状腺毒症和甲亢的诊断",2011,110,"A","","患者，男，55岁。因心悸伴消瘦1周来诊。查体：脉率84次/分，血压148/60mmHg，甲状腺弥漫性Ⅱ度肿大，可闻及血管杂音，肺（-）；心率112次/分。心律绝对不整，心音强弱不等，腹（-）。为明确诊断，首选的检查是",[["A","超声心动图"],["B","心肌酶谱"],["C","血T₃、T₄测定"],["D","冠状动脉造影"]],"C","甲亢的诊断标准为：①高代谢症状和体征；②甲状腺肿大；③血清TT₄、FT₄增高，TSH减低。该患者已有高代谢症状（心悸伴消瘦）和甲状腺肿大，为进一步确诊为甲亢，首选检查为血T₃、T₄测定（C对）。超声心动图（A错）主要用于确诊或排除多种器质性心脏病。心肌酶谱（B错）主要用于确诊心肌缺血坏死。冠状动脉造影（D错）主要用于确诊或排除冠心病。","c46","N"],["2011-N139",22,"第一节 急性心包炎","急性心包炎诊断",2011,139,"B","","常胸痛剧烈，持续发热，多数患者可闻及心包摩擦音，见于",[["A","急性非特异性心包炎"],["B","结核性心包炎"],["C","肿瘤性心包炎"],["D","化脓性心包炎"]],"A","急性非特异性心包炎临床特征常为剧烈胸痛、持续发热，约70%病例可闻及心包摩擦音，本例患者的临床表现符合急性非特异性心包炎的表现（A对）。结核性心包炎（B错）多慢性起病，常有轻度低热、盗汗等结核中毒症状及轻度胸痛。肿瘤性心包炎（C错）心包积液量大，一般无发热及胸痛，心包摩擦音少见。化脓性心包炎（D错）多急性起病，常见高热、胸痛及心包摩擦音。","","N"],["2011-N140",22,"第一节 急性心包炎","急性心包炎诊断",2011,140,"B","","多数起病缓，常见发热及胸痛，可闻及心包摩擦音，见于",[["A","急性非特异性心包炎"],["B","结核性心包炎"],["C","肿瘤性心包炎"],["D","化脓性心包炎"]],"B","结核性心包炎（B对）患者起病缓慢，常有发热和轻度胸痛。当心包积液量少时，有心包摩擦音，当心包积液量多时，心包摩擦音消失，出现心脏压塞征（十版内科学在表3-9-1中明确提到结核性心包炎常无发热和胸痛，十五版实用内科学P1109亦提到有的心包炎轻微或完全无胸痛，如结核性心包炎，故本题考点已更新，原答案选B）。急性非特异性心包炎（A错）起病较急，常有剧烈的胸痛、持续发热，有心包摩擦音。肿瘤性心包炎（C错）心包积液量大，一般无发热及胸痛，心包摩擦音少见。化脓性心包炎（D错）多急性起病，常见高热、胸痛及心包摩擦音。","","N"],["2011-N141",35,"","",2011,141,"B","","肝性脑病二期的表现是",[["A","扑翼样震颤无法引出"],["B","轻度性格改变和行为失常"],["C","昏睡和精神错乱"],["D","意识错乱和睡眠倒错"]],"D","（十版内科学P421）肝性脑病2期（昏迷前期）的表现是意识错乱（D对）、言语不清、腱反射亢进、肌张力增高、踝阵挛及Babinski征阳性等神经体征。扑翼样震颤无法引出（A错）是4期（昏迷期）肝性脑病患者的临床表现，此期患者昏迷，不能被唤醒，患者不能合作而无法引出扑翼样震颤。轻度性格改变（B错）属于1期（前驱期）的临床表现，此期临床表现不明显，易被忽略；行为异常属于2期（昏迷前期）的临床表现。昏睡和精神错乱（C错）是3期（昏睡期）肝性脑病患者的临床表现。D选项中睡眠倒错为肝性脑病1期（前驱期）表现，故本题出题不严谨，官方参考答案为D。","","N"],["2011-N142",35,"","",2011,142,"B","","肝性脑病四期的表现是",[["A","扑翼样震颤无法引出"],["B","轻度性格改变和行为失常"],["C","昏睡和精神错乱"],["D","意识错乱和睡眠倒错"]],"A","肝性脑病4期的表现是昏迷，不能唤醒，患者不能合作而无法引出扑翼样震颤（A对）。轻度性格改变和行为异常（B错）属于1期（前驱期）的临床表现。昏睡和精神错乱（C错）是3期（昏睡期）肝性脑病患者的临床表现。意识错乱是肝性脑病2期（昏迷前期）的表现，睡眠倒错是肝性脑病1期（前驱期）的表现（D错）。","","N"],["2011-N143",59,"第一节 甲状腺功能亢进症","促甲状腺激素（TSH）",2011,143,"B","","对诊断亚临床甲状腺功能异常，最有意义的激素测定是",[["A","TSH"],["B","rT₃"],["C","TT₃"],["D","FT₃"]],"A","亚临床甲状腺功能异常包括亚临床甲亢与亚临床甲减，均无典型临床表现，主要依赖实验室检查结果诊断。亚临床甲亢特点是血FT₃（游离三碘甲腺原氨酸）、FT₄（游离甲状腺素）正常，但TSH（促甲状腺素）低于正常。亚临床甲减特点是TSH（促甲状腺素）升高，TT₄（血清总甲状腺素）和FT₄（游离甲状腺素）正常。故TSH（促甲状腺素）的诊断对亚临床甲状腺功能异常最有意义（A对）。","","N"],["2011-N144",59,"第二节 甲状腺功能减退症","低T3综合征",2011,144,"B","","对诊断低T₃综合征，最有意义的激素测定是",[["A","TSH"],["B","rT₃"],["C","TT₃"],["D","FT₃"]],"B","低T₃（三碘甲状腺原氨酸）综合征也称为甲状腺功能正常的病态综合征，指非甲状腺疾病原因引起的血中T₃降低的综合征，主要表现在血清TT₃、FT₃水平减低，血清rT₃（反三碘甲状腺原氨酸）增高，血清T₄（甲状腺素）、TSH（促甲状腺素）水平正常（A错）。低T₃综合征为甲减的鉴别诊断。因甲减时血清TT₃、FT₃水平也减低，故TT₃、FT₃不是诊断低T₃综合征最有意义的激素测定（CD错）。甲减时血清rT₃减低，故对诊断低T₃综合征最有意义的激素测定是rT₃（B对）。","","N"],["2011-N169",18,"第一节 原发性高血压","利尿剂",2011,169,"X","","利尿剂作为治疗高血压病的药物，下列说法不正确的有",[["A","过度肥胖患者禁用"],["B","不适用于老年患者"],["C","伴发心力衰竭者可选用"],["D","主要适用于高血压病3级患者"]],"ABD","利尿剂适用于轻、中度高血压（D错，为本题正确答案），对单纯收缩期高血压、盐敏感性高血压、合并肥胖（A错，为本题正确答案）或糖尿病、更年期女性、合并心力衰竭和老年人高血压（B错，为本题正确答案）有较强的降压效应，通过排钠排水减轻心脏容量负荷，减轻水肿。主要通过排钠排水降低血容量及心输出量发挥降压作用，长期应用可降低血管阻力（九版药理学P220）。高血压伴发心力衰竭时可应用利尿剂控制体内体液潴留，减轻水肿，也可起到降压效果（C对）。","","N"],["2011-N170",11,"第一节 胸腔积液","恶性胸腔积液",2011,170,"X","","恶性胸腔积液的特点有",[["A","积液性质可为不典型的渗出液或漏出液"],["B","CEA大于20μg/L"],["C","糖含量降低"],["D","ADA增高，多大于45U/L"]],"ABC","恶性胸腔积液的性质，根据其导致胸腔积液的不同方式，可为不典型的渗出液或漏出液（A对）。CEA常大于20μg/L（B对），ADA大于45U/L为结核性胸腔积液的特征（D错），恶性胸腔积液由于不断增殖的肿瘤细胞会消耗葡萄糖，故糖含量常降低小于3.3mmol/L（C对）。","","N"],["2011-N171",30,"第一节 溃疡性结肠炎","氨基水杨酸制剂",2011,171,"X","","在治疗溃疡性结肠炎的常用药物中，可避免在小肠近段被吸收的氨基水杨酸制剂有",[["A","柳氮磺吡啶"],["B","巴柳氮"],["C","美沙拉嗪"],["D","奥沙拉嗪"]],"BCD","氨基水杨酸类制剂是治疗溃疡型结肠炎的常用药物，柳氮磺吡啶部分在小肠被吸收（A错），到达结肠后，经肠菌分解为5-氨基水杨酸和磺胺吡啶，前者是主要的有效成分，为了避免该药物的不良反应，近年来开发出了许多氨基水杨酸新型制剂，可避免在小肠近端被吸收，这类制剂有美沙拉嗪（C对）、奥沙拉嗪（D对）、巴柳氮（B对）等。","","N"],["2011-N172",40,"第三节 急进性肾小球肾炎","急进性肾小球肾炎鉴别诊断",2011,172,"X","","下列选项中，能引起急进性肾炎综合征的疾病有",[["A","系统性红斑狼疮肾炎"],["B","过敏性紫癜肾炎"],["C","重症毛细血管内增生性肾小球肾炎"],["D","重症系膜毛细血管性肾小球肾炎"]],"ABCD","引起急进性肾炎综合征的原因可分为两类。一是继发性急进性肾炎如Goodpasture病（即肺出血-肾炎综合征）、系统性红斑狼疮肾炎（A对）、过敏性紫癜肾炎（B对）均可引起新月体性肾小球肾炎；二是原发性肾小球疾病，虽然病理改变无新月体形成，但若病变较重和（或）持续，临床上可呈现急进性肾炎综合征，如重症毛细血管内增生性肾小球肾炎（C对）或重症系膜毛细血管性肾小球肾炎（D对）等。","","N"],["2011-N173",50,"第一节 溶血性贫血概述","红细胞膜异常",2011,173,"X","","下列选项中，属于遗传性红细胞膜缺陷引起的溶血性贫血的疾病有",[["A","遗传性球形细胞增多症"],["B","阵发性睡眠性血红蛋白尿"],["C","遗传性椭圆形细胞增多症"],["D","遗传性血红蛋白病"]],"AC","溶血性贫血按病因可分为红细胞自身异常和红细胞外部异常所致的溶血性贫血。遗传性红细胞膜缺陷引起的溶血性贫血属于红细胞自身异常所致的溶血性贫血，如遗传性球形细胞增多症（A对）、遗传性椭圆形细胞增多症（C对）、遗传性棘形细胞增多症、遗传性口形细胞增多症等。遗传性球形红细胞增多症是红细胞先天性膜缺陷引起的溶血性贫血中最常见的一种类型，血片见球形红细胞增多，临床表现有贫血、溶血性黄疸、脾大，常伴胆石症。遗传性椭圆形红细胞增多症是一种较少见的红细胞膜缺陷溶血性贫血，周围血象中可见椭圆形、卵圆形甚至雪茄形红细胞，临床症状轻重不一。阵发性睡眠性血红蛋白尿（PNH）（B错）是一种后天获得性造血干细胞基因突变所致的红细胞膜缺陷性溶血病（十版内科学P567），不是遗传性疾病。遗传性血红蛋白病（十版内科学P563）（D错）是一组遗传性珠蛋白生成障碍所致的溶血性贫血，分为珠蛋白肽链合成数量异常（地中海贫血）和异常血红蛋白病（珠蛋白链结构异常）两类，不是红细胞膜缺陷引起的溶血性贫血。","","N"],["2011-N174",61,"第一节 糖尿病","糖尿病足",2011,174,"X","","WHO将糖尿病足定义为与下肢远端神经异常和不同程度的周围血管病变相关的足部病变，这些病变包括",[["A","感染"],["B","溃疡"],["C","深层组织破坏"],["D","畸形"]],"ABC","WHO将糖尿病足定义为与下肢远端神经异常和不同程度周围血管病变相关的足部溃疡（B对）、感染（A对）和（或）深层组织破坏（C对）。定义包括的足部病变为重者表现。轻者表现为足部畸形（D错）、皮肤干燥和发凉、胼胝（高危足），不属于糖尿病足定义范畴。","","N"],["2012-N57",36,"","",2012,57,"A","","下列疾病中，发热可伴明显肌肉疼痛的是",[["A","钩端螺旋体病"],["B","急性细菌性痢疾"],["C","急性白血病"],["D","急性病毒性肝炎"]],"A","钩端螺旋体病是一种急性流行性全身感染性疾病，其主要临床表现为骤起寒战、发热、黄疸、出血、肝脾肿大及肾功能衰竭等，可出现以腓肠肌疼痛为代表的肌肉疼痛（A对）。急性细菌性痢疾（B错）主要临床表现为腹痛、腹泻和里急后重。急性白血病（十版内科学P579）（C错）主要表现为发热、出血、贫血及淋巴结、肝脾肿大。急性病毒性肝炎（D错）主要临床症状为发热、畏寒、厌食、纳差、肝脏肿大，部分患者可出现黄疸。","","N"],["2012-N58",0,"","",2012,58,"A","","下列呼吸类型与疾病的关系，正确的是",[["A","精神紧张——深大呼吸"],["B","糖尿病酮症——潮式呼吸"],["C","尿毒症——叹息样呼吸"],["D","脑出血——间停呼吸"]],"D","脑出血（D对）后颅内压增高，可压迫呼吸中枢导致呼吸变慢变深，并常伴有呼吸节律的改变，可表现为间停呼吸；精神性呼吸困难，主要表现为呼吸快而浅，其发生机制多为过度通气发生呼吸性碱中毒，过度紧张也会发生呼吸深快（十版诊断学P128）。糖尿病酮症（B）和尿毒症（C错）时体内大量酸性物质潴留，机体为保持内环境稳态，多通过深快呼吸（Kussmaul呼吸）增加的排出以维持体内酸碱平衡。叹息样呼吸多为功能性改变，表现为一段正常呼吸节律中插入一次深大呼吸（A对），常伴有叹息声，见于神经衰弱、精神紧张或抑郁症。当糖尿病酮症中毒引起呼吸中枢的兴奋性降低时也可出现潮式呼吸，但十版内科学中糖尿病酮症酸中毒的表现是呼吸深快，并非快慢交替的周期性呼吸。因此B选项存在争议，本题正确答案应为AD，但参考答案为D。","","N"],["2012-N59",15,"第二节 慢性心力衰竭","慢性心力衰竭病因与诱因",2012,59,"A","","临床上出现舒张性心力衰竭最常见的疾病是",[["A","急性心肌梗死"],["B","扩张型心肌病"],["C","高血压病"],["D","缩窄性心包炎"]],"C","舒张性心力衰竭是指在心肌收缩功能正常的情况下，由于心室顺应性减低，使其舒张和充盈能力减弱， 患者出现循环淤血的临床综合征，此时患者LVEF≥50%，通常存在左室肥厚或左房增大，现在称为射血分数保留性心衰（HFpEF） 。常见于高血压伴左室肥大肥厚型心肌病（C对）、主动脉瓣狭窄和缩窄性心包炎等。长期高血压引起的心脏改变主要是左心室肥厚和扩大，但需要注意的是，高血压心脏病早期只有心室充盈量减少，但随着心肌的代谢、功能和结构改变，最终会发展成收缩和舒张功能障碍。急性心肌梗死（A错）及扩张型心肌病（B错）均可导致心脏收缩功能障碍，心排血量下降并出现循环淤血表现，一般引起收缩性心力衰竭。缩窄性心包炎（D错）患者心包纤维化或钙化使心室舒张期充盈受限，部分心包缩窄严重患者可导致舒张性心力衰竭，但临床上高血压病较缩窄性心包炎更常见，故结合本题，临床上出现舒张性心衰最常见的疾病应选高血压病。","","N"],["2012-N60",16,"第三节 房性心律失常","房性期前收缩治疗",2012,60,"A","","男性，48岁，因偶发心悸，24小时动态心电图检查发现，平均心率62次/分，房性期前收缩58次/24小时，ST段无异常，应采取的最佳处理是",[["A","美托洛尔口服"],["B","普罗帕酮口服"],["C","钾镁盐类口服"],["D","临床观察"]],"D","房性期前收缩的临床表现主要为心悸，一些患者有胸闷、乏力症状，自觉有停跳感。结合患者青壮年男性，偶发心悸，24小时平均心率正常，每小时约发生房早2次，心肌无缺血（ST段正常），无需治疗，可临床观察（D对），避免吸烟、饮酒、饮咖啡等可诱发房性期前收缩的因素。美托洛尔（A错）、普罗帕酮（B错）、钾镁盐类（C错）为治疗药物，仅用于症状严重者。","","N"],["2012-N61",18,"第一节 原发性高血压","降压药物应用基本原则",2012,61,"A","","关于高血压病患者的降压治疗，下列提法正确的是",[["A","血压控制越低越好，减少靶器官损害"],["B","尽量应用单种药物，降低药物副反应"],["C","血压控制达标后，药物需及时调整减量"],["D","有并发症患者，药物及治疗方案应个体化"]],"D","应将血压降到患者能最大耐受的水平，一般为＜140/90mmHg，并不是越低越好（A错），血压过低则引起各器官供血不足，甚至引起休克。联合用药可以提高降压效果并减少单种药物的用量，降低副作用（B错）。血压控制达标后，应坚持长期用药，避免频繁换药、减药（C错），否则容易引起血压波动或反跳。不仅是有并发症患者，实际上所有病人基本情况均不相同，药物及治疗方案均应个体化（D对）。","","N"],["2012-N62",19,"第六节 心肌炎","心肌炎诊断",2012,62,"A","","女性，22岁，3天来感心悸伴胸闷，活动后明显，时有阵发性胸痛。呈针刺样，体力下降。3周前有上感发热、咽痛史，既往体健。查体：T37.2℃，P120次/分，R18次/分。BP100/70mmHg，平卧位，颈静脉无怒张，甲状腺Ⅰ度肿大，双肺底可闻及散在湿啰音，心率120次/分，心律整，S₁低钝，可闻及奔马律，P₂＞A₂，肝未及，下肢不肿。该患者最可能的诊断是",[["A","甲状腺功能亢进症"],["B","急性心肌炎"],["C","急性心包炎"],["D","急性冠脉综合征"]],"B","患者发病3周前有“上感”病史（病毒性心肌炎的常见前驱症状），心动过速（120次/分）与发热程度（37.2℃）不相称，有心悸、胸痛症状，有奔马律、肺部啰音（病毒性心肌炎常见心律失常及心功能减退），可诊断为急性病毒性心肌炎（B对）。甲状腺功能亢进性心脏病常先有甲亢，而后可出现心脏病，病史较长，常伴有高代谢症候群，但早期无心肌缺血缺氧表现，一般不会出现“上感”病史（A错）。急性心包炎（C错）心前区疼痛一般为持续性，查体常有心包摩擦音，端坐呼吸，颈静脉怒张。急性冠脉综合征（D错）典型表现为发作性胸骨后闷痛，紧缩压榨感或压迫感、烧灼感，可放射至附近或新的部位，发作时常伴有出汗、恶心、呕吐、心悸或呼吸困难，一般不会有“上感”病史，主要为心肌缺血缺氧症状。","","N"],["2012-N63",1,"第二节 慢性阻塞性肺疾病","肺功能评估",2012,63,"A","","评估慢性阻塞性肺疾病严重程度的肺功能指标是",[["A","FEV₁/FVC"],["B","FEV₁/预计值"],["C","FEV₁绝对值"],["D","DLco"]],"B","FEV₁/FVC（十版内科学P27）（A错）是评价气流受限的一项敏感指标，用于COPD的诊断，而FEV₁占预计值的百分比（B对）为慢性阻塞性肺疾病患者病情严重程度分级的指标，根据其值可把肺功能分为4级，GOLD 1级（轻度）FEV₁≥80%预计值，GOLD 2级（中度）50%～80%预计值，GOLD 3级（重度）30%～50%预计值，GOLD 4级（极重度）＜30%预计值。FEV₁为一秒用力肺活量，其绝对值一般不用来作为慢性阻塞性肺疾病患者病情严重程度分级的指标，因为无法排除不同的个体肺容积不同的差异（C错）。DLco（D错）指一氧化碳弥散量，为间质性肺疾病的监测指标。","","N"],["2012-N64",11,"第一节 胸腔积液","肺炎旁胸腔积液",2012,64,"A","","女性，26岁，近1周出现右侧胸痛，呼吸困难伴发热。查体：T38.5℃，右下肺叩诊浊音，呼吸音减低。行抽液治疗时，患者感到呼吸困难有减轻，但抽液1200ml时患者气促加重，伴剧烈咳嗽，咳大量泡沫状痰，最可能的原因是",[["A","胸膜反应"],["B","并发气胸"],["C","并发肺水肿"],["D","纵隔摆动"]],"C","患者右侧胸痛，呼吸困难伴发热1周，查体：右下肺叩诊浊音，呼吸音减低，考虑右侧胸腔积液，行抽液治疗时，患者呼吸困难减轻，可确诊。抽液1200ml时出现气促加重，伴剧烈咳嗽，咳大量泡沫状痰（抽液过多出现肺水肿的典型临床表现），最可能的原因是并发复张后肺水肿（C对）。抽液治疗首次抽液不要超过800ml，以后每次抽液量不应超过1000ml，过快、过多抽液可使胸腔压力骤降，发生复张后肺水肿或循环衰竭。表现为剧咳、气促、咳大量泡沫状痰，双肺满布湿啰音，PaO₂下降，X线显示肺水肿征。胸膜反应（十版内科学P132）（A错）是指行胸膜腔穿刺抽液时，出现头晕、冷汗、心悸、面色苍白、脉细等表现；气胸（十版内科学P134）（B错）常为突发胸痛，尖锐持续性刺痛或刀割痛，吸气加重，继之出现胸闷和呼吸困难；纵隔摆动（D错）常见于开放性气胸、多根多处肋骨骨折。","","N"],["2012-N65",3,"第一节 支气管扩张症","支气管扩张病因和发病机制",2012,65,"A","","支气管扩张症合并感染的常见病原体不包括",[["A","肺炎链球菌"],["B","流感嗜血杆菌"],["C","铜绿假单胞菌"],["D","肺炎支原体"]],"D","支气管扩张症引起感染的常见病原体为铜绿假单胞菌（C对）、金黄色葡萄球菌、流感嗜血杆菌（B对）、肺炎链球菌（A对）和卡他莫拉菌。肺炎支原体不侵入肺实质，常引起肺间质性炎症，不是引起支扩感染常见的病原体（D错，为本题正确答案）。但在第九版《内科学》中，删除了肺炎链球菌，故肺炎链球菌（A）存在争议。","","N"],["2012-N66",28,"第一节 消化性溃疡","消化性溃疡实验室检查",2012,66,"A","","正在用PPI治疗的溃疡病患者，用下列方法检查幽门螺杆菌（Hp）感染时，最不易出现假阴性的是",[["A","¹³C尿素呼气试验"],["B","快速尿素酶试验"],["C","血清学Hp抗体检查"],["D","Hp培养"]],"C","血清学抗体检测，检测的抗体是IgG，反映一段时间内Hp感染情况。Hp根除后血清抗体可以维持很久（数月至数年），因此本题对于应用PPI治疗（PPI可抑制幽门螺杆菌）的患者应用血清学Hp抗体检测最不易出现假阴性（C对）。¹³C尿素呼气试验（A错）用于幽门螺杆菌根除治疗后复查，PPI可以暂时抑制幽门螺杆菌，可出现假阴性。快速尿素酶试验（B错）是侵入性幽门螺杆菌检查的首选方法，但也会出现假阴性。Hp培养（D错）常会由于各种因素出现假阴性结果，一般需多次培养。","","N"],["2012-N67",75,"第二节 农药中毒","中度中毒",2012,67,"A","","急性有机磷中毒的下列临床表现中，能提示中度中毒的是",[["A","出汗、流涎"],["B","呕吐、腹泻"],["C","胸背部肌肉颤动"],["D","瞳孔缩小"]],"C","急性有机磷的轻度中毒仅有M样症状。中度中毒症状表现为M样症状加重，并出现N样症状。重度中毒具有M、N样症状，并伴有肺水肿、抽搐、昏迷，呼吸肌麻痹和脑水肿。出汗、流涎（A错）、呕吐、腹泻（B错）、瞳孔缩小（D错）均是副交感神经末梢过度兴奋产生的M样症状，提示轻度中毒。胸背部肌肉颤动（C对）属于N样症状，提示中度中毒。伴有肺水肿、抽搐、昏迷，呼吸肌麻痹和脑水肿，提示重度中毒。","","N"],["2012-N68",38,"第一节 消化道出血","内镜治疗",2012,68,"A","","男性，58岁。黑便3天，呕血1天伴头晕、心悸被送入急诊室。既往有“慢性胃病史”，无肝病史。查体：T36.6℃，P96次/分，BP108/70mmHg，意识清楚，面色苍白，巩膜无黄染，心肺检查未见异常，腹软，未见腹壁静脉曲张，肝脾肋下未触及，移动性浊音阴性，肠鸣音活跃。化验：Hb85g/L，WBC4.0×10⁹/L，Plt122×10⁹/L，此时最重要的处理原则是",[["A","补充血容量"],["B","急诊内镜"],["C","肌注止血药"],["D","急症手术治疗"]],"B","中年男性患者，呕血、黑便伴周围循环血容量减少征象，有慢性胃病史，肠鸣音活跃。据此该患者最可能的诊断为消化性溃疡并发出血。由于患者生命体征稳定，意识清楚，无休克表现。因此该患者应首选急诊内镜检查，以尽快明确诊断且可以直接镜下止血治疗（B对），而补充血容量（A错）不是此时最重要的处理原则。肌注止血药（C错）对消化性溃疡出血效果不好，且止血药并不能消除出血的病因，仅作为一般对症治疗。手术治疗（D错）一般在药物、内镜及介入治疗仍不能止血、持续出血将危及患者生命时进行。注意：对于上消化道出血疾病，当生命体征不稳定（收缩压＜90mmHg）时，应“先救命再治病”，而首选补充血容量；当生命体征稳定时应该首选胃镜治疗。","","N"],["2012-N69",40,"第四节 IgA肾病","IgA肾病临床表现",2012,69,"A","","IgA肾病最常见的临床表现是",[["A","水肿"],["B","高血压"],["C","血尿"],["D","蛋白尿"]],"C","几乎所有的IgA肾病患者均有血尿（C对）。60%～70%的IgA肾病患者可表现为伴或不伴轻度蛋白尿，无水肿、高血压和肾功能减退，临床称之为无症状性血尿和（或）蛋白尿，约10%～20%患者表现为大量蛋白尿和水肿。","","N"],["2012-N70",41,"第一节 尿路感染","定位诊断",2012,70,"A","","女性，35岁，发热伴尿频、尿急、尿痛2天来急诊，测体温最高38.8℃，既往体健，化验血WBC14.5×10⁹/L，尿蛋白（+），尿沉渣镜检RBC20～30/HP，WBC满视野/HP。该患者最可能的诊断是",[["A","急性膀胱炎"],["B","急性肾盂肾炎"],["C","慢性肾盂肾炎急性发作"],["D","尿道综合征"]],"B","35岁女性患者（育龄期女性，尿路感染的易感人群），发热（感染中毒症状，提示上尿路感染可能性大），伴尿频、尿急、尿痛（尿路刺激征，提示泌尿系感染可能），血常规示白细胞升高，尿沉渣示WBC满视野/HP（脓尿，提示泌尿系感染），患者既往体健，诊断考虑急性肾盂肾炎（B对）。急性膀胱炎（A错）一般仅表现为尿路刺激征，一般无全身感染中毒症状，少数患者可有发热，但体温不超过38℃（注：在病例分析题中，临床表现符合尿道感染时，体温超过38℃，一般考虑为肾盂肾炎，而低于38℃考虑诊断为膀胱炎）。慢性肾盂肾炎急性发作（C错）患者应有相关病史，本例患者既往体健，可基本排除。尿道综合征（十版内科学P502）（D错）常见于女性，患者可有尿路刺激征及排尿不适等尿路刺激症状，但多次检查均无真性细菌尿。该患者虽未作尿液细菌检查，但实验室检查均提示泌尿系真性感染可能，故不考虑尿道综合征。","","N"],["2012-N71",55,"第一节 出血性疾病概述","止血药物",2012,71,"A","","下列属于抗纤溶药物的是",[["A","氨基己酸"],["B","曲克芦丁"],["C","维生素K"],["D","去氨加压素"]],"A","目前广泛应用于临床的止血药物分为：收缩血管、增加毛细血管致密度、改善其通透性的药物；合成凝血相关成分所需的药物；抗纤溶药物；促进止血因子释放的药物；重组活化因子Ⅶ和局部止血药物等。抗纤溶药物包括氨基己酸（EACA）（A对）、氨甲苯酸（PAMBA）。曲克芦丁（B错）属于收缩血管、增加毛细血管致密度、改善其通透性的药物。维生素K（C错）属于合成凝血相关成分所需的药物。去氨加压素（D错）属于促进止血因子释放的药物。","","N"],["2012-N72",47,"第一节 缺铁性贫血","补铁治疗",2012,72,"A","","女性，25岁，头晕、乏力半年门诊就诊，诊断为“缺铁性贫血”，当时化验Hb78g/L，RBC3.5×10¹²/L，网织红细胞1.5%，门诊给予口服琥珀酸亚铁0.1g，3次/日，1周后门诊复查Hb和RBC未上升，网织红细胞4%，该患者Hb和RBC未上升的最可能原因是",[["A","未按时服药"],["B","药物吸收不良"],["C","诊断错误"],["D","服药时间短"]],"D","缺铁性贫血患者口服铁剂治疗后，外周血网织红细胞计数首先增高，5～10天达到高峰，2周后血红蛋白开始升高，2月左右恢复正常。该患者服药仅一周，Hb（血红蛋白）和RBC（红细胞）未上升的最可能原因是服药时间短（D对），暂不考虑未按时服药（A错）、诊断错误（C错）等，若患者服药2周后血红蛋白仍不升高再考虑这些因素。患者服用的铁剂为有机铁（琥珀酸亚铁），胃肠道反应小且易耐受，所以药物吸收不良可能性小（B错）。","","N"],["2012-N73",59,"第一节 甲状腺功能亢进症","甲状腺危象的治疗",2012,73,"A","","甲亢危象的处理中，不恰当的是",[["A","首选丙硫氧嘧啶"],["B","碘剂应在服用抗甲状腺药物后使用"],["C","使用糖皮质激素有助于增强应激能力"],["D","高热时应选用乙酰水杨酸类解热药"]],"D","水杨酸制剂可抑制甲状腺结合球蛋白与甲状腺素的结合，使得FT₃及FT₄增加；此外，水杨酸制剂可降低体温调定点，导致患者大量出汗，可导致患者脱水甚至休克，因此甲状腺危象患者高热时避免用乙酰水杨酸类解热药（D错，为本题正确答案）。甲状腺危象治疗时应首选大剂量丙硫氧嘧啶（PTU）（A对），原理是PTU可抑制甲状腺激素合成，抑制外周组织T₄向T₃的转化，对控制甲亢症状见效快。碘剂应在服用PTU（丙硫氧嘧啶）1小时后使用（B对），能抑制甲状腺激素的释放，还能抑制促甲状腺激素作用。甲亢危象时糖皮质激素的需要量增加，对有高热或休克者应加用糖皮质激素，可抑制甲状腺素的释放，并抑制外周组织T₄向T₃转换（C对）。","","N"],["2012-N74",61,"第二节 糖尿病酮症酸中毒","补液",2012,74,"A","","在糖尿病酮症酸中毒的治疗中，最关键的措施是",[["A","补充液体"],["B","小剂量胰岛素治疗"],["C","纠正酸中毒"],["D","补钾"]],"A","糖尿病酮症酸中毒（DKA）患者由于高血糖、高血酮和各种酸性代谢产物引起渗透性利尿，酮体从肺排出又带走大量水，从而引起严重失水（十版内科学P743），因此补液是治疗最关键的措施（A对），只有充分补液，才能保证微循环有效灌注，胰岛素才能充分发挥生物学效应。DKA患者应用小剂量胰岛素治疗的主要目的是抑制脂肪分解和酮体生成，降低血糖效应（十版内科学P745），但不是最关键措施（B错）。DKA患者经补液和胰岛素治疗后，酮体水平降低，酸中毒可自行纠正，一般不必补碱（C错），若血pH＜7.1，HCO₃⁻＜5mmol/L可补碱。DKA患者有不同程度失钾，应根据血钾和尿量适当补钾，但不是最关键措施（D错）。","","N"],["2012-N75",67,"第一节 风湿系统疾病总论","风湿性疾病范畴和分类",2012,75,"A","","下列与感染相关的风湿病是",[["A","风湿热"],["B","类风湿关节炎"],["C","多肌炎"],["D","Reiter综合征"]],"A","风湿热是一种与A组乙型溶血性链球菌感染有关的全身性结缔组织的非化脓性疾病，属于感染相关的风湿病（A对）。类风湿关节炎（RA）（十版内科学P814）（B错）是以侵蚀性、对称性多关节炎为主要临床表现的慢性、全身性自身免疫性疾病，属弥漫性结缔组织病。多肌炎（C错）为系统性结缔组织疾病，病因不明，细胞介导的免疫反应对肌肉起着重要作用，但与感染是否相关没有明确依据，属弥漫性结缔组织病。Reiter综合征（D对）为消化道或泌尿道感染3～30天后出现关节炎、非淋球菌性尿道炎及结膜炎（完全型莱特综合征），如只有初始感染和随后发生关节炎，未发生无菌性尿道炎、结膜炎则为不完全型莱特综合征，Reiter综合征属于脊柱关节病，也是经典的反应性关节炎（十六版实用内科学P2221），即也属于感染相关风湿病，但本题标准答案为A。","","N"],["2012-N76",68,"第一节 类风湿关节炎","传统DMARDs",2012,76,"A","","应用改变病情抗风湿药治疗类风湿关节炎时，一般首选的药物是",[["A","羟氯喹"],["B","来氟米特"],["C","甲氨蝶呤"],["D","柳氮磺吡啶"]],"C","甲氨蝶呤抑制细胞内二氢叶酸还原酶，使嘌呤合成受抑，同时具抗炎作用，常作为RA的首选药物（C对）。羟氯喹（A错）对眼和心脏相关的不良反应（如传导阻滞）比甲氨蝶呤常见，目前较少应用。来氟米特（B错）不良反应较多且有致畸作用，孕妇禁用。柳氮磺吡啶（D错）用药后起效慢于甲氨蝶呤，价格又较高，对于磺胺类药物过敏者不能用。","","N"],["2012-N91",26,"第一节 胃食管反流病","胃食管反流病诊断",2012,91,"A","","女性，55岁。2个月来反复发作夜间入睡时胸骨下段疼痛，性质呈刺痛、烧灼样，向后背、胸部、颈部放射，持续30分钟以上，坐起后症状可有减轻，偶在饱餐后1小时左右发生，口含硝酸甘油无效。既往有高血压、胃病史，否认糖尿病史。父有冠心病史。该患者发作性胸痛最可能的病因是",[["A","心绞痛"],["B","胆囊炎"],["C","主动脉夹层"],["D","胃食管反流病"]],"D","胃食管反流病（GERD）是指胃十二指肠内容物反流入食管引起烧心、反流等症状的疾病，常反复发生，其典型症状为烧心和反流。也可产生一些非典型症状如胸骨后胸痛，严重时可为剧烈刺痛，可放射到后背、胸部、肩部、颈部、耳后，有时酷似心绞痛，但口含硝酸甘油无效，可伴有或不伴有烧心和反流，症状常于餐后1小时出现，坐起后可有减轻，卧位、弯腰或腹压增高时可加重，部分患者可在夜间入睡时发生。结合患者病史和临床表现，该患者发作性胸痛最可能的病因是胃食管反流病（D对）。心绞痛（十版内科学P233）（A错）常呈压榨性、紧缩性、烧灼性胸骨后疼痛，但不像针刺或刀扎样锐性痛，持续时间一般不超过30分钟，口含硝酸甘油可缓解，与本例不符合。胆囊炎（B错）一般于进油腻晚餐后发病，但主要表现为右上腹持续性疼痛或阵发性加剧，常伴发热、恶心呕吐，黄疸，与本例不符合。主动脉夹层（十版内科学P335）（C错）常有高血压病史，为急性起病，撕裂样胸痛一开始即达到高峰，不可能自行缓解，两上肢血压和脉搏可有明显差别，也与本例不符。","c51","N"],["2012-N92",26,"第一节 胃食管反流病","非典型症状",2012,92,"A","","女性，55岁。2个月来反复发作夜间入睡时胸骨下段疼痛，性质呈刺痛、烧灼样，向后背、胸部、颈部放射，持续30分钟以上，坐起后症状可有减轻，偶在饱餐后1小时左右发生，口含硝酸甘油无效。既往有高血压、胃病史，否认糖尿病史。父有冠心病史。该患者胸痛的类型属于",[["A","胸膜性胸痛"],["B","纵隔性胸痛"],["C","胸壁性胸痛"],["D","心因性胸痛"]],"B","引起胸痛的原因包括胸壁疾病、心血管疾病、呼吸系统疾病、纵隔疾病及其他。1.胸壁疾病，如急性皮炎、皮下蜂窝织炎、肋间神经炎、肋软骨炎、流行性肌炎等（C错）；2.心血管疾病，如心绞痛、心肌梗死、心肌病等（D错）；3.呼吸系统疾病，如胸膜炎、胸膜肿瘤、自发性气胸、血胸、支气管炎等（A错）；4.纵隔疾病，如纵隔炎、纵隔气肿、纵隔肿瘤等；5.其他，如食管炎、食管癌、食管裂孔疝等。胃食管反流病属于“其他”类胸痛的原因。胸痛按照其部位分类可分为胸壁性胸痛、胸膜性胸痛、心因性胸痛及纵隔性胸痛。依据解剖学中知识，食管应属于后纵隔的一部分，因此由胃食管反流病引起的胸痛应属于纵隔性胸痛（B对）。","c51","N"],["2012-N93",19,"第二节 扩张型心肌病","扩张型心肌病诊断",2012,93,"A","","男性，56岁。3年来进行性加重劳累后心悸、气短，多次出现夜间睡眠中呼吸困难，需坐起后缓解。半年来感腹胀、食欲下降、尿少、下肢水肿。既往无高血压、糖尿病、高血脂症。查体：P88次/分，BP130/70mmHg，半卧位，颈静脉怒张，双肺底可闻及湿啰音，心前区搏动弥散，心界向两侧扩大，心率110次/分，心律不整，心音强弱不等，P₂＞A₂，心尖部可闻及3/6级收缩期吹风样杂音，肝肋下2.0cm，肝颈静脉反流征（+），下肢水肿（++）。该患者最可能的诊断是",[["A","扩张型心肌病"],["B","心瓣膜病"],["C","心包积液"],["D","冠状动脉性心脏病"]],"A","患者中年男性，进行性加重劳累后心悸、气短，多次出现夜间睡眠中呼吸困难，需坐起后缓解，查体发现双肺底可闻及湿啰音（扩心病左心衰的常见表现）。下肢水肿，颈静脉怒张，肝肋下2.0cm，肝颈静脉反流征（+），下肢水肿（++）（扩心病右心衰的常见表现）。P₂＞A₂，提示肺动脉高压。心律不整，心音强弱不等，脉搏短绌（P88次/分，心率110次/分），考虑为房颤。心界向两侧扩大，患者心脏增大，心尖部可闻及3/6级收缩期吹风样杂音（考虑扩心病心腔明显扩大，导致相对性二尖瓣关闭不全）。综上所述，患者病史长，出现全心衰，心脏体积增大，伴有二尖瓣关闭不全症状，诊断考虑为扩张型心肌病加全心衰竭伴房颤（A对）。患者心尖部可闻及3/6级收缩期吹风样杂音，若考虑为二尖瓣关闭不全，患者心尖搏动应为抬举性，且心界向左下扩大，故不考虑为心瓣膜病（B错）。心包积液（C错）可有颈静脉怒张、肝大、肝颈静脉回流征（＋）、下肢水肿等体循环淤血的体征，心界向两侧扩大，但一般无心脏杂音，且心音低钝而遥远。当短期内出现大量心包积液时可引起心脏压塞，典型表现为Beck三联征：低血压、心音低弱、颈静脉怒张。冠状动脉性心脏病（D错）常表现为劳力性心绞痛，心界扩大少见，一般无心脏杂音。","c52","N"],["2012-N94",19,"第二节 扩张型心肌病","扩张型心肌病超声心动图",2012,94,"A","","男性，56岁。3年来进行性加重劳累后心悸、气短，多次出现夜间睡眠中呼吸困难，需坐起后缓解。半年来感腹胀、食欲下降、尿少、下肢水肿。既往无高血压、糖尿病、高血脂症。查体：P88次/分，BP130/70mmHg，半卧位，颈静脉怒张，双肺底可闻及湿啰音，心前区搏动弥散，心界向两侧扩大，心率110次/分，心律不整，心音强弱不等，P₂＞A₂，心尖部可闻及3/6级收缩期吹风样杂音，肝肋下2.0cm，肝颈静脉反流征（+），下肢水肿（++）。为明确诊断，最有价值的检查是",[["A","动态心电图"],["B","超声心动图"],["C","胸部X线片"],["D","冠状动脉CT"]],"B","超声心动图（B对）是诊断及评估扩张型心肌病最常用的重要检查手段，可见左心室明显扩大，左心室流出道扩张，室间隔及左室后壁搏动幅度减弱。胸部X线片（C错）可作为辅诊依据，表现为：心脏扩大，以左心室扩大主，伴右心室扩大，也可有左心房及右心房扩大。动态心电图（A错）可作为辅诊依据，可表现为：不同程度的房室传导阻滞，右束支传导阻滞常见。广泛ST-T改变，左心室高电压，左房肥大，由于心肌纤维化可出现病理性Q波，各导联低电压。冠状动脉CT（D错）主要用于与冠心病相鉴别。","c52","N"],["2012-N95",16,"第三节 房性心律失常","心房颤动诊断",2012,95,"A","","男性，56岁。3年来进行性加重劳累后心悸、气短，多次出现夜间睡眠中呼吸困难，需坐起后缓解。半年来感腹胀、食欲下降、尿少、下肢水肿。既往无高血压、糖尿病、高血脂症。查体：P88次/分，BP130/70mmHg，半卧位，颈静脉怒张，双肺底可闻及湿啰音，心前区搏动弥散，心界向两侧扩大，心率110次/分，心律不整，心音强弱不等，P₂＞A₂，心尖部可闻及3/6级收缩期吹风样杂音，肝肋下2.0cm，肝颈静脉反流征（+），下肢水肿（++）。该患者心律不齐最可能的类型是",[["A","心房颤动"],["B","窦性心律不齐"],["C","阵发性心动过速"],["D","频发期前收缩"]],"A","典型心房颤动的三大体征（A对）为：①脉搏短绌（心率>脉率）；②心律不整；③心音强弱不等。窦性心律不齐（B错）指窦性心律的起源未变，但节律不整，在同一导联上PP间期差异＞0.12秒。阵发性心动过速（C错）是一种阵发性过速而整齐的心律，其特征是突然发作和突然停止。频发期前收缩（曾称早搏）（D错）是指异位起搏点发出的过早冲动引起的心脏搏动，为最常见的心律失常，可发生在窦性或异位性心律的基础上，可偶发或频发，可以不规则或规则地在每一个或每数个正常搏动后发生，形成二联律或联律性过早搏动。","c52","N"],["2012-N96",2,"第一节 支气管哮喘","动脉血气分析",2012,96,"A","","男性，35岁。支气管哮喘30年，再发咳嗽伴喘息3天，吸入沙丁胺醇症状稍改善，1天来喘息加重。查体：R32次/分，端坐呼吸，大汗，语不成句，口唇发绀，双肺呼吸音低，可闻及散在哮鸣音，未闻及湿啰音，心率126次/分，有奇脉。应首选的辅助检查是",[["A","胸部X线"],["B","肺功能"],["C","动脉血气分析"],["D","心电图"]],"C","该患者查体R32次/分，端坐呼吸，大汗，语不成句，口唇发绀，双肺呼吸音低，可闻及散在哮鸣音，未闻及湿啰音，心率126次/分，有奇脉，诊断为支气管哮喘重度急性发作期。支气管哮喘是气道的一种慢性变态反应性炎症性疾病，这种慢性炎症导致可逆性气流受限。肺功能检查中1秒率（FEV₁/FVC%）＜70%或FEV₁低于正常预计值的80%是判断气流受限的最重要指标，所以支气管哮喘诊断一般首选肺功能检查。但该患者处于支气管哮喘重度急性发作期，无法配合完成肺功能检查（B错），所以应首选的辅助检查为动脉血气分析，以判断酸碱、离子平衡和PaO₂、PaCO₂状态来帮助确定疾病的严重程度（C对）。胸部X线和心电图一般不作为首选（AD错）。","c53","N"],["2012-N97",2,"第一节 支气管哮喘","重度至危重度(1)",2012,97,"A","","男性，35岁。支气管哮喘30年，再发咳嗽伴喘息3天，吸入沙丁胺醇症状稍改善，1天来喘息加重。查体：R32次/分，端坐呼吸，大汗，语不成句，口唇发绀，双肺呼吸音低，可闻及散在哮鸣音，未闻及湿啰音，心率126次/分，有奇脉。下列处理措施中，不恰当的是",[["A","鼻导管吸氧"],["B","静脉滴注糖皮质激素"],["C","持续雾化吸入β₂受体激动剂"],["D","限制液体入量（＜2000ml/d）"]],"D","重度至危重度哮喘患者应立即鼻导管吸氧（A对）、静脉滴注糖皮质激素（B对）、持续雾化吸入β₂受体激动剂（C对），使用氨茶碱和抗胆碱药物等。同时注意维持水、电解质平衡，纠正酸碱失衡。重度哮喘发作时因张口呼吸、出汗、进食少等原因引起脱水，应及时进行静脉补充液体，以纠正脱水，此外还可以避免痰液粘稠导致气道阻塞。每天的补液量一般为2500ml～3000ml，应遵循补液的一般原则，即先快后慢、先盐后糖、见尿补钾（二版八年制内科学P61）（D错，为本题正确答案）。","c53","N"],["2012-N98",2,"第一节 支气管哮喘","重度至危重度(1)",2012,98,"A","","男性，35岁。支气管哮喘30年，再发咳嗽伴喘息3天，吸入沙丁胺醇症状稍改善，1天来喘息加重。查体：R32次/分，端坐呼吸，大汗，语不成句，口唇发绀，双肺呼吸音低，可闻及散在哮鸣音，未闻及湿啰音，心率126次/分，有奇脉。经治疗病情不缓解，病人出现嗜睡，意识模糊，不能言语，查体：哮鸣音消失，应采取的最主要的措施是",[["A","面罩吸氧"],["B","静脉注射肾上腺素"],["C","机械通气"],["D","静脉滴注呼吸兴奋剂"]],"C","重度至危重度哮喘患者经治疗病情不能缓解，出现意识改变，应进行有创机械通气（C对），此时面罩吸氧（A错）对于纠正缺氧的效果不大。肾上腺素（B错）为强心剂，一般用于心脏骤停和过敏性休克的抢救，不作为重症哮喘病人的主要治疗措施。呼吸兴奋剂（九版内科学P141）（D错）主要适用于中枢抑制为主、通气不足引起的呼吸衰竭，其使用时必须保持气道通畅，否则会触发呼吸肌疲劳，加重CO₂潴留和组织缺氧，重症哮喘发作时不宜使用。","c53","N"],["2012-N99",37,"第一节 急性胰腺炎","急性胰腺炎诊断",2012,99,"A","","男性，46岁。饮酒后出现中上腹部持续性疼痛24小时，呕吐两次，呕吐物为胃内容物，呕吐后腹痛不缓解，急诊入院。查体：T37.8℃，P106次/分，BP90/60mmHg，心肺检查未见异常，上腹中偏左有压痛、局部反跳痛和肌紧张，肝脾触诊不满意，移动性浊音阳性，肠鸣音1～2次/分，下肢无水肿。最可能的诊断是",[["A","急性胆囊炎"],["B","轻症急性胰腺炎"],["C","重症急性胰腺炎"],["D","消化性溃疡穿孔"]],"C","中年男性患者，饮酒后持续性中上腹痛（饮酒可导致急性胰腺炎），呕吐2次，呕吐后腹痛不减轻（呕吐后腹痛不减轻为急性胰腺炎的腹痛特点），提示急性胰腺炎。又患者有左上腹压痛、反跳痛及肌紧张（腹膜刺激征），肠鸣音减弱（正常4～5次/分）（九版诊断学P173），移动性浊音阳性，血压下降，因此该患者最可能的诊断为重症急性胰腺炎（C对）。轻症急性胰腺炎（B错）腹部体征不明显，且血压下降不显著。消化性溃疡穿孔（D错）有较典型的溃疡病史，腹痛突然加剧，板状腹，肝浊音界消失，X线透视可见膈下有游离气体等，与本例不符。急性胆囊炎（A错）常有胆绞痛史，疼痛位于右上腹，常放射到右肩部，Murphy征阳性，血及尿淀粉酶轻度升高，B超及X线胆道造影可明确诊断，与本例不符。","c54","N"],["2012-N100",37,"第一节 急性胰腺炎","淀粉酶",2012,100,"A","","男性，46岁。饮酒后出现中上腹部持续性疼痛24小时，呕吐两次，呕吐物为胃内容物，呕吐后腹痛不缓解，急诊入院。查体：T37.8℃，P106次/分，BP90/60mmHg，心肺检查未见异常，上腹中偏左有压痛、局部反跳痛和肌紧张，肝脾触诊不满意，移动性浊音阳性，肠鸣音1～2次/分，下肢无水肿。明确诊断，最有价值的检查是",[["A","血淀粉酶测定"],["B","腹水淀粉酶测定"],["C","腹部B型超声检查"],["D","立位腹平片"]],"B","由于重症胰腺炎患者血清淀粉酶可升高、正常或降低，而腹水淀粉酶一定升高，本例移动性浊音阳性说明有腹水，可行诊断性穿刺抽取腹水进行淀粉酶检测，若升高程度大可确诊急性胰腺炎，因此该患者最有价值的检查为腹水淀粉酶测定（B对），而血清淀粉酶测定（A错）数值可高、可低、可正常，对急性重症胰腺炎的确诊易受干扰。腹部B超（C错）可见胰腺肿大，胰内及胰周围回声异常，可作为常规初筛检查，但因常受胃肠道积气的干扰，对胰腺形态观察常不满意，而不能作为最有价值的检查。立位腹平片（D错）常常用于消化道穿孔的确诊，对于胰腺炎的确诊意义不大。","c54","N"],["2012-N101",37,"第一节 急性胰腺炎","急性胰腺炎治疗",2012,101,"A","","男性，46岁。饮酒后出现中上腹部持续性疼痛24小时，呕吐两次，呕吐物为胃内容物，呕吐后腹痛不缓解，急诊入院。查体：T37.8℃，P106次/分，BP90/60mmHg，心肺检查未见异常，上腹中偏左有压痛、局部反跳痛和肌紧张，肝脾触诊不满意，移动性浊音阳性，肠鸣音1～2次/分，下肢无水肿。患者入院时最不宜选用的治疗是",[["A","禁食、补液"],["B","静脉给予抑制胃酸分泌药"],["C","静脉给予抗生素"],["D","皮下注射吗啡类止痛药"]],"D","治疗胰腺炎时，不能使用吗啡止痛，因为吗啡会使Oddi括约肌痉挛，阻塞胰胆管共同通道，加重胰腺炎病情（D对），但九版外科学P460提到吗啡虽然可以引起Oddi括约肌张力增高，却对预后并无不良影响，这里内外科略微存在争议。且对于腹痛病人当诊断不明确时，禁止给予止痛药，以免掩盖症状，延误诊断。禁食、补液（A错）、静脉给予抑制胃酸分泌药（B错）、静脉给予抗生素（C错）均为急性胰腺炎的一般性对症治疗。","c54","N"],["2012-N102",18,"第一节 原发性高血压","高血压急症和亚急症治疗原则",2012,102,"A","","男性，45岁。间断全身轻度水肿5年，加重伴视物模糊1天入院。测血压180/135mmHg，化验尿蛋白（++），尿沉渣镜检RBC8～10个/HP，24小时尿蛋白定量1.3g，血Cr337μmol/L。该患者首选的治疗措施是",[["A","血液透析"],["B","限盐、低蛋白饮食"],["C","利尿治疗"],["D","降压药物治疗"]],"D","患者间断全身轻度水肿5年，加重伴视物模糊1天，入院血压180/135mmHg合并明显的肾功能异常（尿蛋白阳性、尿沉渣镜检RBC8～10个/HP，24小时尿蛋白定量1.3g，血Cr337μmol/L），提示恶性高血压，需要迅速应用降压药物治疗（D对），采用静脉途径给药，同时应监测血压。患者肾功能损害的根本原因是血压迅速、明显升高，及时正确降压，可在短时间内使病情缓解，预防进行性或不可逆性靶器官损害，降低死亡率。血液透析的指征为Cr＞442μmol/L，因此该患者暂不需要血液透析（A错）。限盐、低蛋白饮食（B错），利尿治疗（C错）均不能迅速有效降压，缓解病情。","c55","N"],["2012-N103",18,"第一节 原发性高血压","其他",2012,103,"A","","男性，45岁。间断全身轻度水肿5年，加重伴视物模糊1天入院。测血压180/135mmHg，化验尿蛋白（++），尿沉渣镜检RBC8～10个/HP，24小时尿蛋白定量1.3g，血Cr337μmol/L。该患者目前不适宜选用的治疗药物是",[["A","卡托普利"],["B","硝苯地平"],["C","氢氯噻嗪"],["D","呋塞米"]],"A","患者间断全身轻度水肿5年，加重伴视物模糊1天，入院血压180/135mmHg合并明显的肾功能异常（尿蛋白阳性、尿沉渣镜检RBC8～10个/HP，24小时尿蛋白定量1.3g，血Cr337μmol/L），提示恶性高血压，需要迅速降低血压，采用静脉途径给药，同时应监测血压。卡托普利（为ACEI类）（A错，为本题正确答案）起效慢，且在低血容量和病情晚期（肌酐清除率＜30ml/min或血肌酐超过265μmol/L，即3.0mg/dL）有可能反而使肾功能恶化，故此病例中不应使用ACEI类。患者全身轻度水肿，故需要使用利尿剂，但是由于多数高血压急症时交感神经系统和RAAS激活，外周血管阻力明显升高，体内循环血容量减少，强力利尿存在风险，故不应使用呋塞米（D错），可使用氢氯噻嗪（C对）。硝苯地平（B对）起效迅速，短时间内达到最大作用，作用持续时间短，停药后作用消失快，不良反应小，适合用于恶性高血压的治疗。本题答案应为AD，但参考答案为A。","c55","N"],["2012-N104",18,"第二节 继发性高血压","肾实质性高血压辅助检查",2012,104,"A","","男性，45岁。间断全身轻度水肿5年，加重伴视物模糊1天入院。测血压180/135mmHg，化验尿蛋白（++），尿沉渣镜检RBC8～10个/HP，24小时尿蛋白定量1.3g，血Cr337μmol/L。病情稳定后，为明确诊断，最重要的检查是",[["A","眼底检查"],["B","肾动态显像"],["C","肾穿刺活检"],["D","双肾B型超声"]],"C","患者间断全身轻度水肿5年，加重伴视物模糊1天，入院血压180/135mmHg合并明显的肾功能异常（尿蛋白阳性、尿沉渣镜检RBC8～10个/HP，24小时尿蛋白定量1.3g，血Cr337μmol/L），提示恶性高血压。患者肾功能损害突出，需在病情稳定后，需行肾穿刺活检（C对），以明确肾小球病理改变类型及其病变程度。眼底检查（A错）主要是了解高血压导致的眼底病变情况；肾动态显像（B错）主要了解肾脏形态、功能和尿路通畅情况；双肾B型超声（D错）只能从形态学上了解肾脏改变。","c55","N"],["2012-N105",53,"第二节 非霍奇金淋巴瘤","非霍奇金淋巴瘤诊断",2012,105,"A","","女性，45岁。两侧颈部淋巴结无痛性肿大1个月，无原因发热3天入院，既往体健。查体：T38.5℃，双颈部各触及2个肿大淋巴结，最大者为2.5×1.5cm大小，左腹股沟可触及1个1.5×1cm大小淋巴结，均活动无压痛，巩膜无黄染，心肺检查未见异常，肝肋下0.5cm，脾肋下1cm。化验Hb115g/L，WBC8.2×10⁹/L，PLt149×10⁹/L，颈部淋巴结活检病理弥漫性小～中等大小细胞浸润，细胞免疫表型：CD5（+），CD20（+），CyclinD1（+）。该患者的诊断是",[["A","滤泡性淋巴瘤"],["B","套细胞淋巴瘤"],["C","Burkitt淋巴瘤"],["D","脾边缘区细胞淋巴瘤"]],"B","该患者为中年女性，有发热、颈部及左腹股沟淋巴结无痛性肿大、肝脾肿大的症状，诊断为淋巴瘤。根据其细胞免疫表型CD20（+）、CD5（+）和CyclinD1（+）可知该患者为套细胞淋巴瘤（B对）。滤泡性淋巴瘤（A错）的细胞免疫表型为CD20（+）、CD10（+）、bcl-6（+）和bcl-2（+）。Burkitt淋巴瘤（C错）的细胞免疫表型为CD20（+）、CD22（+）、CD10（+）、CD5（-）和TdT（-）。边缘区细胞淋巴瘤（D错）的细胞免疫表型为CD20（+）、CD5（-）和CyclinD1（-）。","c56","N"],["2012-N106",53,"第二节 非霍奇金淋巴瘤","套细胞淋巴瘤",2012,106,"A","","女性，45岁。两侧颈部淋巴结无痛性肿大1个月，无原因发热3天入院，既往体健。查体：T38.5℃，双颈部各触及2个肿大淋巴结，最大者为2.5×1.5cm大小，左腹股沟可触及1个1.5×1cm大小淋巴结，均活动无压痛，巩膜无黄染，心肺检查未见异常，肝肋下0.5cm，脾肋下1cm。化验Hb115g/L，WBC8.2×10⁹/L，PLt149×10⁹/L，颈部淋巴结活检病理弥漫性小～中等大小细胞浸润，细胞免疫表型：CD5（+），CD20（+），CyclinD1（+）。其可能的染色体异常是",[["A","t（8；14）"],["B","t（11；14）"],["C","t（11；18）"],["D","t（14；18）"]],"B","该患者诊断为套细胞淋巴瘤。套细胞淋巴瘤染色体异常为t（11；14）（B对）。t（8；14）（A错）是Burkitt淋巴瘤的标记。t（11；18）（C错）是边缘区淋巴瘤的标记。t（14；18）（D错）是滤泡性淋巴瘤和弥漫性大B细胞淋巴瘤的标记。","c56","N"],["2012-N107",53,"第二节 非霍奇金淋巴瘤","侵袭性淋巴瘤",2012,107,"A","","女性，45岁。两侧颈部淋巴结无痛性肿大1个月，无原因发热3天入院，既往体健。查体：T38.5℃，双颈部各触及2个肿大淋巴结，最大者为2.5×1.5cm大小，左腹股沟可触及1个1.5×1cm大小淋巴结，均活动无压痛，巩膜无黄染，心肺检查未见异常，肝肋下0.5cm，脾肋下1cm。化验Hb115g/L，WBC8.2×10⁹/L，PLt149×10⁹/L，颈部淋巴结活检病理弥漫性小～中等大小细胞浸润，细胞免疫表型：CD5（+），CD20（+），CyclinD1（+）。该患者治疗的最佳方案是",[["A","CHOP"],["B","ABVD"],["C","MOPP"],["D","CHOP+利妥昔单抗"]],"D","套细胞淋巴瘤发展迅速，中位存活期2～3年，属侵袭性非霍奇金淋巴瘤（NHL）。CHOP方案为侵袭性NHL的标准治疗方案，但该患者CD20（+），适用利妥昔单抗，且随着靶向治疗的发展和利妥昔单抗的应用，使得R-CHOP方案（化疗前加用利妥昔单抗）更加广泛的应用于临床，特别在CD20（+）的患者中，获得了很好的疗效（D对A错）。ABVD（B错）方案、MOPP（C错）方案均用于霍奇金淋巴瘤的治疗（十版内科学P593）。","c56","N"],["2012-N108",60,"第二节 原发性醛固酮增多症","原发性醛固酮增多症诊断与病因诊断",2012,108,"A","","男性，30岁，2个月来自觉乏力、口渴、夜尿增多，1周前因劳累感乏力症状明显加重，伴下肢无力，行走困难，来院检查发现血压增高。既往体健，无烟酒嗜好，无高血压病家族史。查体：BP160/90mmHg，心肺腹均未见阳性体征，尿常规：比重1.011，蛋白（±）。心电图可见高U波。该患者最可能的诊断是",[["A","原发性高血压"],["B","肾性高血压"],["C","糖尿病并发高血压"],["D","原发性醛固酮增多症"]],"D","原发性醛固酮增多症（原醛症）是由于肾上腺皮质病变致醛固酮分泌增多，醛固酮具有保钠保水排钾作用。保钠保水可致水、钠潴留，引起高血压。排钾增多致低血钾、高尿钾、低钾性碱中毒。因此原醛症的特点为低血钾+高血压。本例患者血压高（高血压：收缩压≥140mmHg和或舒张压≥90mmHg），心电图有低血钾表现（低钾为U波出现；高钾为T波高尖），另外还有低血钾所致的神经肌肉功能障碍表现（如自觉乏力伴下肢无力、行走困难等表现）。据此，该患者最可能的诊断是原发性醛固酮增多症（D对）。原发性高血压（A错）多见于中老年人，高血压病史长达十多年或数十年，一般无低血钾，与本例不符。肾性高血压（十版内科学P273）（B错）既往有肾病史，长期高血压突然加剧或高血压突然出现，病程短，进展快，舒张期血压增高尤为明显，一般无低血钾，与本例不符。本例未提及血糖值检查，故不考虑糖尿病并发高血压（C错）。","c57","N"],["2012-N109",60,"第二节 原发性醛固酮增多症","血、尿生化检查",2012,109,"A","","男性，30岁，2个月来自觉乏力、口渴、夜尿增多，1周前因劳累感乏力症状明显加重，伴下肢无力，行走困难，来院检查发现血压增高。既往体健，无烟酒嗜好，无高血压病家族史。查体：BP160/90mmHg，心肺腹均未见阳性体征，尿常规：比重1.011，蛋白（±）。心电图可见高U波。为进一步明确病情，首选的检查是",[["A","肾功能检查"],["B","超声心动图检查"],["C","血、尿电解质检查"],["D","糖化血红蛋白检查"]],"C","原醛症的特点为高血压+低血钾。本题血压已测，虽然有低血钾表现，但血钾值仍未知。所以为明确诊断，应首选血、尿电解质检查，以了解有无低血钾、高血钠、碱血症、高尿钾（C对）。原醛症大多肾功能正常，肾功能检查（A错）对确诊原醛症价值不大。超声心动图检查（B错）主要用于确诊或排除多种器质性心脏病，如风湿性心脏病、心肌病。糖化血红蛋白（D错）通常反映糖尿病患者近8～12周的血糖控制情况，也是监测糖尿病发展的指标。","c57","N"],["2012-N110",60,"第二节 原发性醛固酮增多症","药物治疗",2012,110,"A","","男性，30岁，2个月来自觉乏力、口渴、夜尿增多，1周前因劳累感乏力症状明显加重，伴下肢无力，行走困难，来院检查发现血压增高。既往体健，无烟酒嗜好，无高血压病家族史。查体：BP160/90mmHg，心肺腹均未见阳性体征，尿常规：比重1.011，蛋白（±）。心电图可见高U波。下列对该患者治疗不恰当的药物是",[["A","氨苯蝶啶"],["B","氨氯地平"],["C","螺内酯"],["D","呋塞米"]],"D","原发性醛固酮增多症（原醛症）是由于肾上腺皮质病变所致醛固酮分泌增多，醛固酮具有保钠保水排钾作用，保钠保水引起水、钠潴留，排钾增多致低钾血症，故不能使用呋塞米（排钾性利尿剂）（D对）。氨苯喋啶（A错）为保钾利尿药，可以帮助排钠保钾，原醛症患者可选用。氨氯地平（钙拮抗剂）（B错）可使一部分原醛症患者醛固酮产生量减少，血钾和血压恢复正常，因为醛固酮的合成需要钙的参与。螺内酯（保钾利尿药）（C错）能与肾小管醛固酮受体结合，对醛固酮起竞争性抑制作用，具有潴钾排钠作用，作为原醛症首选。","c57","N"],["2012-N139",16,"第一节 心律失常概述","异位心律",2012,139,"B","","心电图示：P波及QRS波时限、形态正常，P-P及R-R各自成规律，P波与QRS波无关，P波频率54次/分，QRS波频率62次/分，应诊断为",[["A","房室分离"],["B","房室传导阻滞"],["C","窦房传导阻滞"],["D","室性逸搏心律"]],"A","正常人心脏冲动由窦房结发出，先激动心房，再向下激动心室。房室分离就是房室分离的病人出现两个激动产生点，心房的激动点控制心房，心室的激动点控制心室，因此，房率和室率往往不一致。房室分离包括病理性的三度房室传导阻滞（B错）和生理性的干扰性房室分离（十版内科学P191）（A对）。前者心室率较慢，常小于60次/分，P波个数多于QRS波。后者是指房室分离连续3次或3次以上的窦性或房性激动，与交界性或室性激动在房室交界区发生绝对干扰所形成的分离，表现为心室率较快，常大于60次/分，P波个数少于QRS波。窦房传导阻滞（C错）时，窦房结产生的冲动不能使心房除极或使心房除极延迟，最常见的二度窦房传导阻滞分为两型：莫氏Ⅰ型即文氏阻滞，表现为PP间期进行性缩短，直至出现一次长PP间期，该长PP间期短于基本PP间期的两倍；莫氏Ⅱ型阻滞时，长PP间期为基本PP间期的整数倍。与本例心电图均不符。室性逸搏心律（D错）是指当窦房结或心房内以及房室交接区的激动均由于某些原因不能按时下传，则下一级的心室作为起搏点发出激动来控制心室，形成室性逸搏，连续3个或3个以上的室性逸搏构成室性逸搏心律。","","N"],["2012-N140",16,"第二节 窦性心律失常","窦房传导阻滞诊断",2012,140,"B","","心电图示：P波形态、时限正常，下传的P-R间期正常。部分P波后无QRS波，出现一长间隙，长间隙时间与窦性P-P间距成整倍数关系，应诊断为",[["A","房室分离"],["B","房室传导阻滞"],["C","窦房传导阻滞"],["D","室性逸搏心律"]],"C","（二度Ⅱ型）窦房传导阻滞（C）时，窦房结产生的冲动不能使心房除极或使心房除极延迟，表现为PP间期显著延长，其长度为窦性PP间期的整数倍，但P波之后一般都存在QRS波。房室分离（A错）的病人，心房去极化产生的P波与心室去极化产生的QRS波无关。房室传导阻滞（B）分为一、二、三度，一度房室传导阻滞P波和QRS波按顺序发生，仅PR间期延长，无QRS波脱落。二度Ⅰ型和Ⅱ型阻滞均可有QRS波的脱落，但二度Ⅰ型表现为PR间期进行性延长，二度Ⅱ型表现为PR间期恒定，部分P波后无QRS波群。三度阻滞表现为P波和QRS波互不相关。室性逸搏心律（D错）是指当窦房结或心房内以及房室交接区的激动均由于某些原因不能按时下传，则下一级的心室作为起搏点发出激动来控制心室，形成室性逸搏，连续3个或3个以上的室性逸搏构成室性逸搏心律。本题选B选项更为恰当，但原答案为C选项。","","N"],["2012-N141",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎克雷伯杆菌肺炎临床表现",2012,141,"B","","肺炎克雷伯杆菌肺炎典型痰液表现是",[["A","少量铁锈色痰"],["B","砖红色胶冻样痰"],["C","脓痰带血丝或脓血状"],["D","黄绿色脓痰"]],"B","肺炎克雷伯杆菌肺炎典型痰液表现是咳砖红色胶冻样痰（B对）。少量铁锈色痰（A错）是肺炎链球菌肺炎的典型痰液表现；脓痰带血丝或脓血痰（C错）是金黄色葡萄球菌肺炎的典型痰液表现；黄绿色脓痰（D错）是铜绿假单胞菌感染的典型痰液表现。","","N"],["2012-N142",4,"第二节细菌性肺炎","葡萄球菌肺炎临床表现",2012,142,"B","","金黄色葡萄球菌肺炎典型痰液表现是",[["A","少量铁锈色痰"],["B","砖红色胶冻样痰"],["C","脓痰带血丝或脓血状"],["D","黄绿色脓痰"]],"C","金黄色葡萄球菌肺炎的典型痰液表现是脓痰带血丝或脓血痰（C对）；少量铁锈色痰（A错）是肺炎链球菌肺炎的典型痰液表现；咳砖红色胶冻样痰（B错）是肺炎克雷伯杆菌肺炎的典型痰液表现；黄绿色脓痰（D错）是铜绿假单胞菌感染的典型痰液表现。","","N"],["2012-N143",35,"第一节 肝硬化","肝硬化代偿期",2012,143,"B","","肝硬化代偿期的体征是",[["A","黄疸"],["B","肝大"],["C","腹壁静脉曲张"],["D","皮肤紫癜"]],"B","临床上肝硬化大致分为肝功能代偿期和失代偿期。代偿期大部分患者无症状或症状较轻，肝硬化代偿期的体征可有肝脾肿大（B对），肝脏质地偏硬。黄疸（A错）是由于肝脏对胆红素的摄取、结合、排泄功能障碍导致，皮肤紫癜（D错）是由于肝脏合成凝血因子及血小板生成素减少、脾功能亢进导致的皮肤出血，二者均为肝硬化失代偿期中肝功能减退的表现。腹壁静脉曲张（C错）为肝硬化失代偿期中门静脉高压的表现。","","N"],["2012-N144",35,"第一节 肝硬化","门静脉高压",2012,144,"B","","肝硬化失代偿期门静脉高压的体征是",[["A","黄疸"],["B","肝大"],["C","腹壁静脉曲张"],["D","皮肤紫癜"]],"C","临床上肝硬化大致分为肝功能代偿期和失代偿期。失代偿期主要有肝功能减退和门静脉高压两类临床表现。肝硬化失代偿期中门静脉高压的主要表现为腹水、门-腔侧支循环开放、脾功能亢进及脾大等。其中门-腔侧支循环常有：①食管胃底静脉曲张；②腹壁静脉曲张（C对）；③痔静脉扩张；④腹膜后吻合支曲张；⑤脾肾分流。肝大（B错）为肝硬化代偿期的体征，肝硬化失代偿期为肝脏体积缩小。黄疸（A错）、皮肤紫癜（D错）为肝硬化失代偿期中肝功能减退的表现。","","N"],["2012-N169",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞体征",2012,169,"X","","临床可出现奇脉的疾病有",[["A","支气管哮喘急性发作"],["B","自发性气胸"],["C","限制型心肌病"],["D","心包积液"]],"AD","奇脉亦称吸停脉，指吸气时脉搏明显减弱甚至消失，呼气时又出现或恢复原状的现象。奇脉常见于渗出性心包炎、大量心包积液（D对）、心脏压塞、严重的支气管哮喘（A对）、缩窄性心包炎、肺气肿等疾病。自发性气胸（B错）可出现脉搏增快，但不出现奇脉。限制型心肌病（C错）是以心室壁僵硬增加、舒张功能降低、充盈受限而产生临床右心衰症状为特征的一类心肌病。患者收缩功能多正常，故心排量无明显下降，一般不会出现奇脉。","","N"],["2012-N170",6,"第一节 肺结核","继发性肺结核",2012,170,"X","","继发性肺结核的好发部位有",[["A","上叶尖后段"],["B","下叶后基底段"],["C","右中叶或左舌叶"],["D","下叶背段"]],"ABD","继发型肺结核的好发部位为上叶的尖后段（A对）、下叶的背段（D对）。需要注意的是，继发性肺结核的好发部位和肺结核病的好发部位不完全相同，后者的好发部位还包括后基底段（B错）（十版内科学P74），但按十版教材观点，B选项正确。","","N"],["2012-N171",27,"第二节 慢性胃炎","慢性胃炎病因和发病机制",2012,171,"X","","下列属于慢性胃炎发病原因的有",[["A","Hp感染"],["B","自身免疫"],["C","精神刺激"],["D","十二指肠液反流入胃"]],"ABD","慢性胃炎的发病原因有Hp感染（A对）、自身免疫（B对）、十二指肠-胃反流（D对）、年龄因素和胃黏膜营养因子缺乏等。精神刺激与许多胃肠疾病有关，例如急性胃炎、功能性消化不良、肠易激综合征、消化性溃疡等，但是慢性胃炎一般与精神刺激无关（C错）。","","N"],["2012-N172",44,"第一节 急性肾损伤","尿液检查",2012,172,"X","","下列支持急性肾小管坏死的尿液检查结果有",[["A","尿比重＜1.010"],["B","尿渗透压＜300mOsm/Kg·H₂O"],["C","尿钠浓度＜20mmol/L"],["D","肾衰指数＜1"]],"AB","急性肾损伤（AKI）以往称为急性肾衰竭（ARF），急性肾损伤分为三类即肾前性、肾性和肾后性。急性肾小管坏死（ATN）时，肾小管浓缩及稀释功能受损功能，出现低渗及低比重尿、尿钠浓度增高。急性肾小管坏死的尿液诊断标准为：尿比重＜1.010（A对），尿渗透压＜300mOsm/kg H₂O（B对）（但十版P522表5-9-2中已更新至尿渗透压＜250mOsm/kg H₂O），尿钠浓度＞20mmol/L（C错），肾衰指数＞1（D错）。","","N"],["2012-N173",49,"第一节 再生障碍性贫血","AA血象",2012,173,"X","","外周血中全血细胞减少可见于",[["A","再生障碍性贫血"],["B","巨幼细胞贫血"],["C","阵发性睡眠性血红蛋白尿"],["D","自身免疫性溶血性贫血"]],"ABC","可导致全血细胞减少的血液病包括再生障碍性贫血（A对）、急性白血病、骨髓增生异常综合征、巨幼细胞贫血（B对）、阵发性睡眠性血红蛋白尿（C对）、Fanconi贫血、Evans综合征、免疫相关性全血细胞减少及恶性组织细胞病等。再生障碍性贫血是一种造血功能衰竭症，表现为骨髓增生减低，外周血全血细胞减少。巨幼细胞贫血是由于维生素B₁₂或（和）叶酸缺乏而导致的贫血，骨髓中红系、粒系和巨核系细胞均可发生巨幼变，因此可导致全血细胞减少。阵发性睡眠性血红蛋白尿约半数患者可表现为全血细胞减少。自身免疫性溶血性贫血系因免疫调节功能发生异常，产生抗自身红细胞抗体致使红细胞破坏的一种溶血性贫血，一般表现为红细胞减少，但白细胞及血小板多正常（D错），10% -20% 的病人可合并免疫性血小板减少，表现为全血细胞减少，称为 Evans 综合征，D选项略有争议。","","N"],["2012-N174",59,"第一节 甲状腺功能亢进症","Graves眼病",2012,174,"X","","符合浸润性突眼体征的有",[["A","上眼睑挛缩，眼裂增宽"],["B","眼球活动受限"],["C","眼睑肿胀，结膜充血水肿"],["D","双眼迅速向下看时，出现白色巩膜"]],"BC","Graves病引起的眼部改变大致可分为单纯性突眼与浸润性突眼。浸润性突眼即Graves眼病，与眶后组织炎症有关。患者有明显的自觉症状，常有畏光、流泪、复视、视力减退、眼部肿痛、刺痛、异物感等。检查可发现视野缩小，斜视，眼球活动受限甚至固定（B对）。眼球明显突出，突出度一般在超过正常值3mm以上（正常眼突度男18.6mm，女16mm），两侧多不对称。由于眼球明显突出，眼睑不能闭合，可导致眼睑肿胀、结膜充血水肿、角膜溃疡等（C对）。单纯性突眼与甲状腺毒症所致的交感神经兴奋性增高有关，主要表现为：①上眼睑挛缩，眼裂增宽（A错）。②von Graefe征：双眼迅速向下看时，出现白色巩膜（D错）。③Joffroy征：眼球向上看时，前额皮肤不能皱起。④Mobius征：双眼看近物时，眼球辐辏不良。⑤Stellwag征：瞬目减少，炯炯发亮。⑥轻度突眼：突眼度超过正常值3mm以下，即19～20mm（正常眼突度男18.6mm，女16mm）。","","N"],["2013-N57",35,"第一节 肝硬化","肝硬化失代偿期",2013,57,"A","","肝硬化失代偿期患者发生大呕血后出现的体征变化，正确的是",[["A","肝脏缩小"],["B","脾脏缩小"],["C","腹水量明显减少"],["D","腹壁静脉曲张加重"]],"B","肝硬化早期肝脏增生、假小叶形成等会使肝脏体积增大，但到晚期肝脏会发生萎缩坏死导致体积缩小，和呕血无关（A错）。肝硬化失代偿期，门静脉高压使脾静脉回流阻力增加及门静脉压力逆传到脾，使脾脏被动淤血性肿大，当大呕血后门静脉压力下降，可使脾脏暂时缩小（B对）。肝硬化腹水形成是门静脉高压和肝功能减退共同作用的结果，为肝硬化肝功能失代偿时最突出的临床表现，呕血后门静脉压力有所下降，但是肝功能没有改善，因此腹水量不会明显减少（C错）。肝硬化门静脉高压时侧支循环建立开放，表现为腹壁静脉曲张，大量出血后门静脉压力下降，腹壁静脉曲张会减轻（D错）。","","N"],["2013-N58",21,"第三节 二尖瓣狭窄","二尖瓣狭窄临床表现",2013,58,"A","","关于二尖瓣狭窄心尖部舒张期杂音听诊特点的叙述，正确的是",[["A","多为递增递减型"],["B","为全舒张期"],["C","向剑突方向传导"],["D","强度不受呼吸影响"]],"D","由于二尖瓣狭窄的存在，舒张期血流由左心房通过狭窄的二尖瓣到左心室，形成血流漩涡而产生低音调的雷鸣样（隆隆样或滚筒样）杂音。二尖瓣狭窄舒张期杂音听诊特点为舒张中晚期（B错）隆隆样杂音，呈递增型（A错），音调较低，局限于心尖部（C错），左侧卧位较清楚，常伴有舒张期震颤及第一心音亢进或开瓣音，运动或用力呼气可使其杂音强度增强（D错）。根据十版内科学观点，本题无正确答案，但参考答案为D。","","N"],["2013-N59",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄诊断",2013,59,"A","","下列临床上常见出现脉压减少的病变，不正确的是",[["A","心包积液"],["B","心力衰竭"],["C","主动脉瓣狭窄"],["D","重度二尖瓣关闭不全"]],"D","心包积液、心力衰竭（非容量负荷过重引起的心衰）、主动脉瓣狭窄时，心脏每搏输出量降低，收缩压明显降低。由于动脉压明显降低，血流速度减慢，在心室舒张期末存留于大动脉中的血液减少不多，因而舒张压降低相对较小，因而脉压降低。重度二尖瓣关闭不全时，虽然也表现为心脏每搏输出量降低，收缩压明显降低，但收缩期重度反流使收缩期大大缩短，反流所致的左心房容量负荷增加则使舒张期延长，舒张期主动脉流向外周的血液增加，舒张压下降比收缩压更明显，因此出现脉压增大（D错，为本题正确答案）。","","N"],["2013-N60",16,"第三节 房性心律失常","抗凝治疗",2013,60,"A","","女性，62岁。患高血压病10年，2个月来发作性心悸，心电图诊断为心房颤动，持续5～24小时左右自行恢复。4天前再次发作后持续不缓解来院。查体：BP125/70mmHg，心率90次/分，对该患者正确的治疗措施是",[["A","立即采取电转复"],["B","立即静脉输注胺碘酮转复"],["C","华法林抗凝3周后转复"],["D","经胸UCG检查心房内无血栓即可转复"]],"C","房颤持续不超过24小时，复律前无需做抗凝治疗。否则应在复律前接受三周华法林治疗，待心律转复后继续治疗3～4周。该患者4天前再次发作后持续不缓解，可见房颤持续时间超过24小时，所以应华法林抗凝3周后转复（C对），而不应立即复律（AB错）。也可行食道超声心动图除外心房血栓后再行复律，而不是经胸UCG（超声心动图）（D错）。","","N"],["2013-N61",17,"第四节 急性冠状综合征","环氧化酶抑制剂",2013,61,"A","","急性非ST段抬高心肌梗死治疗时不宜采用溶栓疗法的主要原因是",[["A","冠脉内主要是白血栓"],["B","冠脉阻塞不完全"],["C","冠脉痉挛是发病的主要原因"],["D","病情危急程度较轻"]],"A","急性非ST段抬高的心梗多为未完全闭塞的血管病变，冠脉内血栓多为血小板聚集形成的白血栓（A对），在溶栓治疗中，溶栓药针对的是纤维蛋白而不是血小板，若应用会导致纤溶系统功能增强，由于凝血系统与纤溶系统一直处于动态平衡状态，间接激活凝血系统，使病情恶化。ST段抬高心梗多为冠脉内存在纤维蛋白交联形成的红色血栓，早期溶栓效果好，须与非ST段抬高心梗相鉴别。冠脉痉挛（C错）是变异型心绞痛的发病的主要原因。冠脉阻塞不完全（B错）及病情危急程度较轻（D错）不是急性非ST段抬高心肌梗死治疗时不宜采用溶栓疗法的主要原因。","","N"],["2013-N62",19,"第四节 致心律失常性右心室心肌病","致心律失常性右心室心肌病诊断",2013,62,"A","","下列疾病中，属于原发性心肌病范畴的是",[["A","致心律失常型右室心肌病"],["B","围产期心肌病"],["C","酒精性心肌病"],["D","自身免疫性心肌病"]],"A","心肌病是指除CHD、高血压性心脏病、心脏瓣膜病、先天性心脏病和肺源性心脏病以外的心肌结构和功能异常为主要表现的一组疾病，可分为原发性心肌病及继发性心肌病（特异性心肌病）。原发性心肌病是一组原因未明的心肌病，包括扩张型心肌病、肥厚型心肌病、限制型心肌病、致心律失常型右室心肌病（A对）和未定型的心肌病。继发性心肌病包括克山病、酒精性心肌病（C错）、围产期心肌病（B错）、糖尿病心肌病、药物性心肌病、自身免疫性心肌病（D错）等。","","N"],["2013-N63",8,"第二节 特发性肺纤维化","胸部HRCT",2013,63,"A","","特发性肺纤维化的HRCT典型表现是",[["A","双肺斑片状磨玻璃影"],["B","双下肺和胸膜下分布为主的网状改变"],["C","病灶与周围正常组织形成鲜明对照的“地图状”改变"],["D","双肺结节状阴影"]],"B","HRCT已成为临床上诊断特发性肺纤维化的首选检查，其诊断准确性大于90%，甚至可以替代外科肺活检。双下肺和胸膜下分布为主的网状改变（B对）、蜂窝改变伴或不伴牵拉支气管扩张是特发性肺纤维化的HRCT典型表现。双肺斑片状磨玻璃影（A错）主要发生于炎症、结核等病变；病灶与周围正常组织形成鲜明对照的“地图状”改变（C错）是肺泡蛋白沉积症的表现；双肺结节状阴影（D错）多为转移性肺癌的表现。","","N"],["2013-N64",1,"第二节 慢性阻塞性肺疾病","自发性气胸",2013,64,"A","","男性，68岁。3年前诊断为COPD，未规律治疗。2小时前无明显诱因突感左胸剧痛，继之呼吸困难，发绀，大汗，烦躁。查体：BP90/60mmHg，气管右移，左肺呼吸音减弱，未闻及干湿性啰音。最可能的诊断是",[["A","肺炎并发胸膜炎"],["B","肺栓塞"],["C","自发性气胸"],["D","急性心肌梗死"]],"C","患者有COPD病史，突发左胸剧痛、呼吸困难、发绀、大汗、烦躁、血压降低、气管右移、左肺呼吸音减弱，故首先怀疑是COPD病情发展并发自发性气胸（C对）。肺炎并发胸膜炎（A错）患者多可闻及双肺湿啰音，无气管移位；肺栓塞（十版内科学P112）（B错）多表现为突发的胸痛、不明原因的呼吸困难及气促（尤以活动后明显）、咯血、晕厥、烦躁不安，但不会出现气管右移；急性心肌梗死（十版内科学P248）（D错）多有心脏病史，多表现为突发的胸痛、大汗、发绀及呼吸困难等，但不会出现气管右移的表现。","","N"],["2013-N65",9,"第一节 肺血栓栓塞症","肺血栓栓塞症溶栓治疗",2013,65,"A","","伴有血液动力学紊乱的大面积肺栓塞的溶栓治疗时间窗是",[["A","≤3天"],["B","≤7天"],["C","≤14天"],["D","≤30天"]],"C","溶栓治疗的时间窗一般规定为14天以内（C对），但鉴于可能存在血栓的动态形成过程，这一时间窗的规定并不是绝对的，若近期有新发PTE（肺栓塞）征象可适当延长。","","N"],["2013-N66",26,"第一节 胃食管反流病","胃食管反流病发病机制",2013,66,"A","","与幽门螺杆菌感染无关的疾病是",[["A","胃炎"],["B","胃溃疡"],["C","十二指肠溃疡"],["D","胃食管反流病"]],"D","幽门螺杆菌感染是慢性胃炎（A错）和消化性溃疡（BC错）的主要病因，慢性胃炎患者Hp感染率高达80%～95%，十二指肠球部溃疡患者Hp感染率高达90%～100%，胃溃疡为80%～90%。胃食管反流病的病因有抗反流屏障结构与功能异常、食管清除作用降低、食管黏膜屏障功能降低，与幽门螺杆菌感染无关（D对）。","","N"],["2013-N67",35,"第一节 肝硬化","门腔侧支循环形成",2013,67,"A","","下列对诊断肝硬化门脉高压症最有价值的体征是",[["A","蜘蛛痣"],["B","脾脏肿大"],["C","肝脏质地坚硬"],["D","腹壁静脉曲张"]],"D","肝硬化门脉高压症的临床表现主要包括：腹水、门-腔侧支循环开放、脾功能亢进及脾大等。其中，门-腔侧支循环开放由持续性门静脉高压引起，为诊断肝硬化门脉高压症最有价值的体征，常见的侧支循环有食管胃底静脉曲张、腹壁静脉曲张（D对）、痔静脉扩张、腹膜后吻合支曲张以及脾肾分流等。蜘蛛痣（A错）为肝功能减退的表现，而非门脉高压引起。脾脏肿大（B错）为肝硬化门静脉高压较早出现的体征，但非特异性体征，也可由其他多种因素引起，如急性感染、恶性肿瘤、血液系统疾病等，不具有特异性，不是诊断门脉高压最有价值的体征。肝脏质地坚硬（C错）也可见于肝硬化代偿期，对诊断肝硬化门脉高压症价值不大。","","N"],["2013-N68",38,"第一节 消化道出血","内镜治疗",2013,68,"A","","男性，23岁。间断上腹痛2年，2天来柏油样便6次，今晨呕咖啡样物200ml。无肝病史。静脉输液后下一步诊治措施首选",[["A","急诊胃镜及镜下止血"],["B","急诊上消化道造影"],["C","腹部B型超声检查"],["D","外科手术"]],"A","青年男性患者，有间断上腹痛病史，现出现柏油样大便及今呕吐咖啡样物200ml，初步诊断为消化性溃疡并发出血。因此应当在补足血容量、血压稳定后，行急诊胃镜下止血治疗（A对），既可明确诊断又能直接进行治疗。急诊上消化道造影（B错）、腹部B型超声（C错）对上消化道出血的诊断价值不大。外科手术（D错）一般在药物、内镜及介入治疗仍不能止血、持续出血将危及患者生命时进行。","","N"],["2013-N69",40,"第四节 IgA肾病","IgA肾病诊断",2013,69,"A","","肾小球源性血尿最常见的病因是",[["A","急性肾小球肾炎"],["B","慢性肾小球肾炎"],["C","急性肾盂肾炎"],["D","IgA肾病"]],"D","IgA肾病（D对）是肾小球源性血尿最常见的病因，为目前世界范围内最常见的原发性肾小球疾病，约占原发性肾小球疾病的20%～50%，也是我国最常见的肾小球疾病。几乎所有IgA肾病患者均有血尿，典型病例常在上呼吸道感染后数小时至2天内出现肉眼血尿。急性肾炎（A错）几乎全部患者均有肾小球源性血尿，约30%患者可有肉眼血尿，但发病率较IgA肾病低。慢性肾小球肾炎（B错）常由多种不同病因、不同病理类型的原发性肾小球疾病发展而来，虽有肾小球源性血尿，但发病率较IgA肾病低。急性肾盂肾炎（C错）肾小球较少受累，故很少出现肾小球源性血尿，可出现由于肾盂及肾小管炎症破坏导致的非肾小球源性血尿。","","N"],["2013-N70",40,"第五节 肾病综合征","肾病综合征并发症",2013,70,"A","","男性，35岁，因蛋白尿原因待查入院，24小时尿蛋白定量3.8g，血白蛋白30g/L，肾活检示：轻度系膜增生性肾炎。该患者最不常见的并发症是",[["A","水、电解质紊乱"],["B","肾静脉血栓形成"],["C","急性肾衰竭"],["D","营养不良"]],"A","患者尿蛋白3.8g/d（＞3.5g/L），血浆白蛋白低于30g/L（患者30g/L），肾活检显示患者为预后良好的轻度系膜增生性肾小球肾炎，因此该患者可诊断为肾病综合征。肾病综合征常见的并发症包括：①感染，与蛋白质营养不良、免疫功能紊乱及应用糖皮质激素有关；②血栓栓塞并发症，系因血液浓缩及高脂血症造成血液粘稠度增加以及凝血、抗凝和纤溶系统失衡，以肾静脉血栓最常见（B对）；③急性肾衰竭（C对），发生率相对较低，可能与肾间质高度水肿压迫肾小管及大量管型堵塞肾小管有关；④营养不良（D对），与蛋白质经尿液长期大量丢失有关。肾病综合征患者可因有效循环血容量不足而致肾血流量下降，可能会出现肾前性氮质血症，经扩容及利尿治疗容易恢复。由于其肾小管受损较轻，肾小管的浓缩稀释及排泄功能一般正常，较少发生水、电解质紊乱（A错，为本题正确答案）。","","N"],["2013-N71",47,"第一节 缺铁性贫血","缺铁性贫血铁代谢",2013,71,"A","","正常人体铁在消化道吸收的主要部位是",[["A","胃"],["B","十二指肠"],["C","空肠下段"],["D","回肠"]],"B","铁吸收的主要形式是二价铁，吸收部位主要在十二指肠（B对）及空肠上段。胃（A错）不是吸收的主要部位，仅有乙醇、少量水分及某些药物（如阿司匹林）可在胃内被吸收。空肠下段（C错）是各种营养物质吸收的主要部位。回肠（D错）是维生素B₁₂吸收的主要部位。","","N"],["2013-N72",55,"第一节 出血性疾病概述","出血性疾病病史",2013,72,"A","","男性，18岁，因头痛针刺合谷穴后，次日局部形成血肿。半年前曾因右膝关节轻度外伤而出血。该患者出血最可能的机制是",[["A","血管壁功能异常"],["B","凝血功能异常"],["C","血小板数减少"],["D","血小板功能缺陷"]],"B","该患者针刺后出现血肿，有关节轻度外伤而出血（深部血肿、关节出血等提示可能与凝血障碍等有关）的病史，说明该患者出血最可能的机制是凝血功能异常（B对）。一般认为，皮肤、黏膜出血点、紫癜等多为血管（A错）、血小板异常（CD错）所致。","","N"],["2013-N73",61,"第一节 糖尿病","促胰岛素分泌剂",2013,73,"A","","男性，82岁。体型较消瘦，3个月前口服葡萄糖耐量试验诊为糖尿病，平时空腹血糖6.5～7.2mmol/L，餐后2小时血糖12～14mmol/L，有冠心病心衰病史10年，结肠癌术后5年。为控制血糖，应首选的药物是",[["A","二甲双胍"],["B","阿卡波糖"],["C","胰岛素"],["D","那格列奈"]],"D","本例为老年糖尿病患者，体型较消瘦，空腹血糖轻度升高（空腹血糖正常值为3.9～6.0mmol/L，≥7.0mmol/L才考虑糖尿病），而餐后血糖较高（餐后血糖≥11.1mmol/L即可考虑糖尿病）。那格列奈（格列奈类药物）为促胰岛素分泌剂，主要通过刺激胰岛素的早时相分泌而降低餐后血糖，不良反应是低血糖和体重增加，主要用于非肥胖型餐后高血糖患者（D对）。二甲双胍（十版内科学P736）（A错）主要用于治疗肥胖型T2DM糖尿病，可使体重减轻，有关高龄是否为二甲双胍禁忌症，九版内科学相关内容有更新，明确提到高龄不是二甲双胍的禁忌，需根据肾功能调整用量，说法较八版内科学更加清楚。阿卡波糖（十版内科学P738）（B错）是α-葡萄糖苷酶抑制剂（AGI），主要用于肥胖型餐后高血糖患者。本病例为老年患者，是非胰岛素依赖性糖尿病（T2DM）可能性偏大，未出现并发症之前，不考虑胰岛素治疗（C错）。","","N"],["2013-N74",60,"第二节 原发性醛固酮增多症","药物治疗",2013,74,"A","","原发性醛固酮增多症首选的治疗方法是",[["A","手术治疗"],["B","螺内酯"],["C","氨苯蝶啶"],["D","血管紧张素转换酶抑制剂"]],"B","原发性醛固酮增多症是由肾上腺皮质病变致醛固酮分泌增多所致。按病因分类为醛固酮瘤、特发性醛固酮增多症（又称为原发性肾上腺增生所致原醛症）和糖皮质激素可治性醛固酮增多症等。醛固酮瘤的根治方法为手术切除，应作为其首选治疗方法。特发性增生者手术效果差，应采用药物治疗。有时难以确定为腺瘤或特发性增生时，可先用药物治疗，又螺内酯结构与醛固酮相似，为醛固酮的竞争性抑制剂，应作为首选的药物治疗方法。本题问的是原发性醛固酮增多症首选的治疗方法，由于病因未明，应首选螺内酯治疗（B对）。手术治疗（A错）为醛固酮瘤的首选治疗方法。氨苯蝶啶（C错）为保钾利尿剂，适用于螺内酯治疗无效者，不作首选。血管紧张素转换酶抑制剂（D错）可减少醛固酮分泌，改善钾的平衡并降低血压至正常，可用于治疗特发性醛固酮增多症的患者，但不作首选。注意：原发性醛固酮增多症首选的治疗方法是螺内酯；而醛固酮瘤首选的治疗方法是手术治疗。","","N"],["2013-N75",67,"第一节 风湿系统疾病总论","非甾体类抗炎药",2013,75,"A","","下列治疗风湿病的非甾体抗炎药物中，胃肠道不良反应最小的是",[["A","萘普生"],["B","炎痛喜康"],["C","塞来昔布"],["D","双氯芬酸"]],"C","非甾体抗炎药的作用机制是通过抑制环氧化酶（COX），从而抑制花生四烯酸转化为前列腺素，起到抗炎、解热、镇痛的效果。传统的非甾体抗炎药如布洛芬、双氯芬酸（D错）、萘普生（A错）、炎痛喜康（吡罗昔康）（B错）、吲哚美辛等，能非选择性抑制COX-1（主要表达于胃粘膜）和COX-2（主要参与炎症反应），故胃肠道反应较大。选择性COX-2抑制剂如塞来昔布（C对）、罗非昔布等，能选择性抑制COX-2达到抗炎镇痛效果，胃肠道反应也较少。","","N"],["2013-N76",69,"第一节 系统性红斑狼疮","系统性红斑狼疮病因",2013,76,"A","","与系统性红斑狼疮的发病无关的原因是",[["A","遗传"],["B","紫外线照射"],["C","化学试剂"],["D","雄激素"]],"D","系统性红斑狼疮（SLE）病因至今尚未肯定，大量研究显示遗传、内分泌、感染、免疫异常和一些环境因素与本病的发病有关。在遗传因素（A错）、环境因素（如紫外线、药物、化学试剂、微生物病原体等）（BC错）、雌激素水平（而非雄激素）（D对）等各种因素相互作用下，引起急慢性炎症及组织坏死（如狼疮肾炎），从而导致机体的多系统损害。","","N"],["2013-N91",11,"第一节 胸腔积液","胸腔积液临床表现",2013,91,"A","","男性，48岁。1个月来气短、呼吸困难，1周来发热、咳嗽，B超发现“右侧大量胸腔积液”。近半年日渐消瘦。查体：T37.5℃，R21次/分，轻度贫血貌，高枕右侧卧位。该患者胸部叩诊不可能出现的体征是",[["A","右肺叩诊呈实音"],["B","右肺肝界下移"],["C","右侧肺底移动度消失"],["D","心界叩诊向左侧移位"]],"B","患者B超发现右侧大量胸腔积液，右侧大量胸腔积液时，纵隔向左移位压迫心脏，故心界叩诊向左侧移位（D对）；向上压迫肺组织，影响患侧呼吸，使右侧肺底移动度消失（C对）；肺组织受压，使其变致密，右肺叩诊浊音或实音（A对）；叩诊右肺肝界时，右侧胸腔积液属浊音，肝属实音，浊音与实音难以鉴别，故右肺肝界很难叩出，不能判断右肺肝界下移（B错，为本题正确答案），右肺肝界下移见于肺气肿、右侧张力性气胸等。","c62","N"],["2013-N92",11,"第一节 胸腔积液","胸腔积液临床表现",2013,92,"A","","男性，48岁。1个月来气短、呼吸困难，1周来发热、咳嗽，B超发现“右侧大量胸腔积液”。近半年日渐消瘦。查体：T37.5℃，R21次/分，轻度贫血貌，高枕右侧卧位。该患者胸部听诊不可能出现的体征是",[["A","左上肺可闻及支气管肺泡呼吸音"],["B","右上肺可闻及支气管呼吸音"],["C","右下腋前线部可闻及胸膜摩擦音"],["D","右中下肺语音共振消失"]],"C","该患者为右侧大量胸腔积液，胸膜摩擦音为少量胸腔积液时产生的体征，当大量胸腔积液时，脏壁层胸膜分开，摩擦音消失，所以不可能出现的体征是右下腋前线部可闻及胸膜摩擦音（C错，为本题正确答案）；正常人于胸骨两侧第一、二肋间，肩胛间区第三、四胸椎水平以及肺尖前后部可听到支气管肺泡呼吸音，故患者左上肺可闻及支气管肺泡呼吸音（A对），当其他部位听到支气管肺泡呼吸音时，均属异常情况，其产生机制为肺实变区域较小且与正常含气肺组织混合存在，或肺实变部位较深并被正常肺组织所覆盖之故，常见于支气管肺炎、肺结核、大叶性肺炎初期或在胸腔积液上方肺膨胀不全区域听及；正常人于喉部，胸骨上窝，背部第六、七颈椎及一、二胸椎附近可听到支气管呼吸音，胸腔积液时，压迫肺脏，发生压迫性肺不张，因组织致密，有利于支气管音的传导，故于积液区上方有时可听到支气管呼吸音（B对）；语音共振产生的机制为：喉部发声产生的振动经气管、支气管、肺泡传至胸壁，由听诊器听及。右侧大量胸腔积液时，肺组织压迫上移，使中下肺语音共振消失（D对）。","c62","N"],["2013-N93",21,"第三节 二尖瓣狭窄","二尖瓣狭窄诊断",2013,93,"A","","女性，48岁。5年来渐进性劳累后心悸、气短，1年来加重，曾有夜间憋醒，需坐起后缓解，既往有关节痛史。检查后发现心脏扩大，可闻及杂音，胸片显示如下，该患者最可能的心脏病变是",[["A","扩张型心肌病"],["B","风湿性心脏病"],["C","冠状动脉性心脏病"],["D","先天性心脏病"]],"B","中年女性患者，渐进性劳累后心悸、气短，夜间憋醒（提示肺血回流障碍）。胸部X线正位片示：左心房增大，左心缘变直，呈“梨形心”改变；右前斜位片示：增大的左心房向后压迫食管，食管后移，此为典型的二尖瓣狭窄的心脏X线平片改变。患者有关节痛病史（提示风湿性关节炎），综合病史及典型X线表现，诊断考虑风湿性心脏病（B对）。扩张型心肌病（A错）X线常表现为心影明显增大，尤以左心室明显，心胸比高于50%，不符合该患者X线表现。冠状动脉性心脏病（C错）心脏外形并无明显改变，因而心脏X线片多正常。先天性心脏病（D错）常幼年发病，中年起病者少见。","c63","N"],["2013-N94",21,"第三节 二尖瓣狭窄","二尖瓣狭窄临床表现",2013,94,"A","","女性，48岁。5年来渐进性劳累后心悸、气短，1年来加重，曾有夜间憋醒，需坐起后缓解，既往有关节痛史。检查后发现心脏扩大，可闻及杂音，胸片显示如下，该患者可能闻及的心脏杂音是",[["A","心尖部舒张期隆隆样杂音"],["B","胸骨左缘第三肋间舒张期叹气样杂音"],["C","胸骨右缘第二肋间收缩期喷射样杂音"],["D","胸骨左缘第二肋间机器样连续性杂音"]],"A","二尖瓣狭窄特征性的杂音为心尖区舒张中晚期低调的隆隆样杂音（A对），呈递增型，局限，左侧卧位明显，运动或用力呼气可使其增强，常伴舒张期震颤。胸骨左缘第三肋间舒张期叹气样杂音（B错）为主动脉瓣关闭不全的典型心脏杂音。胸骨右缘第二肋间收缩期喷射样杂音（C错）为主动脉瓣狭窄的典型心脏杂音。胸骨左缘第二肋间机器样连续性杂音（D错）为动脉导管未闭的典型心脏杂音。","c63","N"],["2013-N95",15,"第二节 慢性心力衰竭","心力衰竭分级",2013,95,"A","","女性，48岁。5年来渐进性劳累后心悸、气短，1年来加重，曾有夜间憋醒，需坐起后缓解，既往有关节痛史。检查后发现心脏扩大，可闻及杂音，胸片显示如下，按NYHA分级，该患者目前的心功能应是",[["A","Ⅰ级"],["B","Ⅱ级"],["C","Ⅲ级"],["D","Ⅳ级"]],"C","患者劳累后心悸、气短（体力活动轻度受限），近来加重，夜间阵发性呼吸困难，坐起后可缓解（体力活动明显受限）。根据NYHA分级，患者符合心功能Ⅲ级（C对）的表现。（注意：NYHA分级是按诱发心力衰竭症状的活动程度将心功能的受损状况分为四级）。","c63","N"],["2013-N96",1,"第二节 慢性阻塞性肺疾病","急性加重期治疗",2013,96,"A","","男性，60岁。反复咳喘40余年，活动后气短10余年，间断双下肢水肿5年，加重1天入院，吸烟史40年。查体：嗜睡，口唇发绀，颈静脉怒张，桶状胸，双肺可闻及干湿啰音，心率110次/分，心律整，肝肋下3.0cm，双下肢水肿。血气分析示pH7.26，PaO₂45mmHg，PaCO₂75mmHg。下列治疗措施错误的是",[["A","积极控制感染"],["B","应用无创呼吸机改善通气"],["C","应用5%碳酸氢钠纠正酸中毒"],["D","应用支气管舒张剂"]],"C","患者老年男性，长期吸烟史，反复咳喘40余年，桶状胸，故有COPD的基础疾病。现该患者双下肢水肿，颈静脉怒张，肝肋下3.0cm，应考虑存在右心衰；嗜睡，口唇发绀，血气分析示pH7.26，PaO₂45mmHg，PaCO₂75mmHg，存在Ⅱ型呼吸衰竭（PaO₂＜60mmHg，PaCO₂＞50mmHg），合并呼吸性酸中毒。该患者现处于COPD急性加重期。急性加重期的治疗措施主要为积极控制感染（A对）、应用无创呼吸机改善通气（B对）、应用支气管舒张剂（D对）。该患者存在酸中毒是通气障碍所致，所以应该改善肺部通气来治疗酸中毒（C错，为本题正确答案），补碱一般应用于重症代谢性酸中毒且不易控制量，容易导致碱中毒，使氧解离曲线左移，减少血红蛋白氧的释放，加重组织缺氧。","c64","N"],["2013-N97",1,"第二节 慢性阻塞性肺疾病","慢性呼吸衰竭",2013,97,"A","","男性，60岁。反复咳喘40余年，活动后气短10余年，间断双下肢水肿5年，加重1天入院，吸烟史40年。查体：嗜睡，口唇发绀，颈静脉怒张，桶状胸，双肺可闻及干湿啰音，心率110次/分，心律整，肝肋下3.0cm，双下肢水肿。血气分析示pH7.26，PaO₂45mmHg，PaCO₂75mmHg。经治疗后病情有好转，神志清醒。数日后出现烦躁，有时抽搐，血气分析pH7.49，PaO₂66mmHg，PaCO₂55mmHg，BE+15mmol/L，上述情况最可能是",[["A","失代偿性代谢性碱中毒"],["B","呼吸性酸中毒合并代谢性碱中毒"],["C","呼吸性碱中毒合并代谢性碱中毒"],["D","失代偿性呼吸性酸中毒"]],"B","老年男患，40年吸烟病史，长期咳嗽、喘息伴活动后气短（慢阻肺的典型症状）。间断双下肢水肿5年，加重1天入院（提示并发右心衰竭，1天前急性加重）。查体可见：桶状胸、双肺可闻及干湿啰音（慢阻肺的典型体征），嗜睡、口唇发绀、心率加快（提示并发呼吸衰竭），口唇发绀、心率加快、颈静脉怒张、肝脏肿大、双下肢水肿（右心衰的典型表现）。血气分析示pH7.26，PaO₂45mmHg，PaCO₂75mmHg（低氧血症、高碳酸血症，确诊并发Ⅱ型呼吸衰竭）。根据该患者的病史、临床表现、血气分析，诊断为慢阻肺并发慢性肺心病，1天前急性加重，处于心、肺功能失代偿期，故可见急性呼吸衰竭、右心衰加重表现。经氧疗、机械通气等治疗后，病情有好转，神志清醒（急性呼吸衰竭得到控制）。数日后出现烦躁，有时抽搐（碱中毒的典型临床表现），血气分析pH7.49（pH正常值7.35～7.45，提示碱中毒），PaO₂66mmHg，PaCO₂55mmHg（PaCO₂正常值35～45mmHg，提示呼吸性酸中毒），BE+15mmol/L（BE正常值-3～+3mmol/L，提示代谢性碱中毒）。根据上述临床表现、血气分析可知，患者经治疗后由急性呼吸衰竭转变为慢性呼吸衰竭，此时肾脏酸碱代偿功能被启动，排酸保碱，机体碱储备增加，导致呼吸性酸中毒合并代谢性碱中毒（B对）。","c64","N"],["2013-N98",1,"第二节 慢性阻塞性肺疾病","稳定期的治疗",2013,98,"A","","男性，60岁。反复咳喘40余年，活动后气短10余年，间断双下肢水肿5年，加重1天入院，吸烟史40年。查体：嗜睡，口唇发绀，颈静脉怒张，桶状胸，双肺可闻及干湿啰音，心率110次/分，心率整，肝肋下3.0cm，双下肢水肿。血气分析示pH7.26，PaO₂45mmHg，PaCO₂75mmHg。经治疗后症状好转出院，出院后应采取的措施不包括",[["A","长期口服小剂量糖皮质激素"],["B","戒烟"],["C","长期使用长效支气管舒张剂"],["D","长期家庭氧疗"]],"A","经治疗后，症状好转，本患病情稳定于慢性肺心病肺、心功能代偿期。预后采取常规综合治疗，例如，戒烟（B对）、长期使用长效支气管舒张剂（C对）、长期吸入小剂量糖皮质激素（A错，为本题正确答案）、长期家庭氧疗（D对）等。","c64","N"],["2013-N99",28,"第一节 消化性溃疡","癌变",2013,99,"A","","男性，50岁。胃溃疡病史10年，近2个月患者腹痛加重，失去规律，经多种药物治疗无效，体重下降。查体：浅表淋巴结无肿大，腹平软，上腹部有压痛。就目前资料考虑，最可能的诊断是",[["A","胃溃疡复发"],["B","胃溃疡癌变"],["C","合并胃泌素瘤"],["D","复合性溃疡"]],"B","中年男性患者，既往胃溃疡病史10年，近期腹痛失去规律，药物治疗无效，且体重下降，应首先考虑胃溃疡癌变（B对）。复合性溃疡（D错）指胃和十二指肠均有活动性溃疡，多见于男性，一般先有十二指肠溃疡后有胃溃疡，且常发生幽门梗阻（十版内科学P375）。胃溃疡复发（A错）腹痛规律不会改变，药物治疗有效，体重不会下降。胃泌素瘤（C错）虽药物治疗无效，但是以多发、顽固及不典型部位消化性溃疡及腹泻为特征。","c65","N"],["2013-N100",28,"第一节 消化性溃疡","上消化道内镜检查及活检",2013,100,"A","","男性，50岁。胃溃疡病史10年，近2个月患者腹痛加重，失去规律，经多种药物治疗无效，体重下降。查体：浅表淋巴结无肿大，腹平软，上腹部有压痛。为明确诊断，最有意义的检查是",[["A","粪隐血试验"],["B","血清胃泌素测定"],["C","钡餐造影"],["D","胃镜检查"]],"D","胃溃疡癌变确诊首选胃镜检查加粘膜活检（D对），即病理检查（为大部分疾病确诊的金标准）。粪隐血试验（A错）阳性只能提示有消化道出血，很多原因都可引起消化道出血，并不能确定是不是胃癌。血清胃泌素测定（B错）用于胃泌素瘤的诊断，对于胃癌诊断意义不大。钡餐造影（C错）可以用于胃癌的辅助诊断，仅用于有胃镜检查禁忌证时，不作为首选检查。","c65","N"],["2013-N101",28,"第一节 消化性溃疡","消化性溃疡外科治疗",2013,101,"A","","男性，50岁。胃溃疡病史10年，近2个月患者腹痛加重，失去规律，经多种药物治疗无效，体重下降。查体：浅表淋巴结无肿大，腹平软，上腹部有压痛。根据诊断，最佳的处理方法是",[["A","胃黏膜保护剂治疗"],["B","质子泵抑制剂治疗"],["C","根除幽门螺杆菌"],["D","手术治疗"]],"D","对于胃癌的治疗，大量国内的研究资料表明，目前能够治愈胃癌的唯一手段是手术切除（D对）。胃黏膜保护剂治疗（A错）、质子泵抑制剂治疗（B错）、根除幽门螺杆菌（C错）均为消化性溃疡的治疗药物，对胃癌治疗无效。","c65","N"],["2013-N102",45,"第一节 慢性肾衰竭","患病率与病因",2013,102,"A","","男性，45岁，间断双下肢水肿伴蛋白尿10年，乏力，纳差，恶心1周，刷牙时牙龈出血伴皮肤碰后发青3天入院。入院时测血压150/90mmHg，化验血Hb80g/L，WBC6.4×10⁹/L，Plt192×10⁹/L。蛋白尿（++），尿比重1.010，尿糖（±），偶见颗粒管型。血Cr707μmol/L。该患者血肌酐升高的最可能病因是",[["A","慢性肾小球肾炎"],["B","肾病综合征"],["C","高血压病肾损害"],["D","糖尿病肾病"]],"A","中青年男性患者（慢性肾小球肾炎主要好发人群），间断双下肢水肿伴蛋白尿10年（慢性进程），出现乏力、纳差、恶心及出血症状（提示肾功能减退），血压150/90mmHg，血Hb80g/L（正常成年男性Hb120g/L～160g/L，出现贫血多提示慢性病程），蛋白尿（++）。以上均提示该患者最可能的诊断为慢性肾小球肾炎肾功能衰竭，化验血肌酐为707μmmol/L，达到了慢性肾衰尿毒症期的标准（血肌酐≥707μmol/L），因此该患者血肌酐升高的最可能病因是慢性肾小球肾炎（A对）。肾病综合征（B错）两个必需诊断标准为：①蛋白尿大于3.5g/d（定性试验应+++～++++）；②血浆白蛋白低于30g/L（十版内科学P480）。本例患者尿蛋白（++）未达肾病综合征尿蛋白标准且未提及低蛋白血症，因此排除肾病综合征。高血压病肾损害（C错）需有较长的高血压病史，很少出现蛋白尿，肾功能减退首先从肾小管浓缩功能减退开始（十版内科学P263）。本例患者并无高血压病史，入院时血压仅150/90mmHg，蛋白尿（++），故排除高血压肾损害。糖尿病肾病（D错）需有较长的糖尿病病史，且血糖升高，尿糖阳性，故排除糖尿病肾病。","c66","N"],["2013-N103",45,"第一节 慢性肾衰竭","血液系统表现",2013,103,"A","","男性，45岁，间断双下肢水肿伴蛋白尿10年，乏力，纳差，恶心1周，刷牙时牙龈出血伴皮肤碰后发青3天入院。入院时测血压150/90mmHg，化验血Hb80g/L，WBC6.4×10⁹/L，Plt192×10⁹/L。蛋白尿（++），尿比重1.010，尿糖（±），偶见颗粒管型。血Cr707μmol/L。该患者贫血最可能的原因是",[["A","失血因素"],["B","慢性溶血"],["C","促红细胞生成素减少"],["D","营养性造血原料不足"]],"C","EPO（促红细胞生成素）由肾间质产生，因此慢性肾衰时，肾组织分泌EPO减少，可导致肾性贫血（C对）。本例无明显失血病史及表现（A错），也无黄疸、肝脾大等慢性溶血表现（B错）。营养性造血原料不足常见于缺铁性贫血，题干并未述及（D错）。","c66","N"],["2013-N104",45,"第一节 慢性肾衰竭","血液系统表现",2013,104,"A","","男性，45岁，间断双下肢水肿伴蛋白尿10年，乏力，纳差，恶心1周，刷牙时牙龈出血伴皮肤碰后发青3天入院。入院时测血压150/90mmHg，化验血Hb80g/L，WBC6.4×10⁹/L，Plt192×10⁹/L。蛋白尿（++），尿比重1.010，尿糖（±），偶见颗粒管型。血Cr707μmol/L。该患者出血倾向最可能的原因是",[["A","血管脆性增加"],["B","血小板功能减低"],["C","凝血因子缺乏"],["D","纤溶亢进"]],"B","晚期肾衰患者有出血倾向，其原因多与体内尿毒症毒素蓄积抑制血小板功能，导致血小板功能减低有关（B对），部分患者也可有凝血因子Ⅷ缺乏。凝血因子缺乏（C错）为肝病导致出血倾向的主要原因（十版内科学P418）。血管脆性增加（A错）和纤溶亢进（D错）均不是慢性肾衰竭患者出血的病因。","c66","N"],["2013-N105",52,"第二节 急性白血病","急性白血病诊断",2013,105,"A","","男性，23岁，因乏力10天、牙龈出血伴皮肤瘀斑4天入院，既往体健。化验血Hb76g/L，WBC25×10⁹/L，Plt29×10⁹/L，骨髓增生明显活跃，原始细胞占60%，POX染色（-），PAS染色（+）成块，NSE染色（-）。该患者的诊断是",[["A","急性淋巴细胞白血病"],["B","急性粒细胞白血病"],["C","急性单核细胞白血病"],["D","急性红白血病"]],"A","患者为青年男性，有乏力（贫血症状），牙龈出血伴皮肤瘀斑（出血症状）。血象：Hb76g/L（正常男性为130～175g/L），WBC25×10⁹/L（正常为3.5～9.5×10⁹/L），Plt29×10⁹/L（正常为125～350×10⁹/L）（红细胞、血小板明显减少，白细胞增多）。骨髓细胞增生活跃，原始细胞占60%（原始细胞≥骨髓有核细胞的30%定义为急性白血病的诊断标准）（十版内科学P577），可诊断为急性白血病。不同类型的AL单用临床表现和血象难以鉴别，常用细胞化学的方法鉴别，如过氧化物酶（MPO或POX）阴性见于急淋白血病，强阳性见于急粒白血病；糖原（PAS）染色成块见于急淋白血病；非特异性酯酶（NEC/NSE）阳性、能被NaF抑制≥50%见于急单白血病。该患者POX染色阴性，PAS染色成块，NSE染色阴性，故该患者最可能的诊断为急性淋巴细胞白血病（A对）。急性粒细胞白血病（B错）POX染色呈强阳性。急性单核细胞白血病（C错）NSE染色阳性。急性红白血病（D错）表现为红、白两系的恶性增生，幼稚红细胞和幼稚白细胞数目均增加。","c67","N"],["2013-N106",52,"第二节 急性白血病","急性白血病细胞遗传学和分子生物学检查",2013,106,"A","","男性，23岁，因乏力10天、牙龈出血伴皮肤瘀斑4天入院，既往体健。化验血Hb76g/L，WBC25×10⁹/L，Plt29×10⁹/L，骨髓增生明显活跃，原始细胞占60%，POX染色（-），PAS染色（+）成块，NSE染色（-）。提示该患者预后差的染色体异常是",[["A","t（8；21）"],["B","t（9；22）"],["C","t（15；17）"],["D","t（16；16）"]],"B","ALL（淋巴母细胞性淋巴瘤/白血病）对治疗反应很敏感，进行强力化疗，90%以上的患者可以获得完全缓解。影响ALL预后的因素有遗传学异常的类型、年龄以及外周白细胞的数量等。前者如存在t（9；22）（q34；q11.2）、t（v；11q23）以及有MLL基因重排患者的预后较差（B对）；而有t（12；21）（p13；q22），TEL-AML-易位患者的预后则较好。同时外周血白细胞>10×10⁹/L的患者预后不良。","c67","N"],["2013-N107",52,"第二节 急性白血病","ALL诱导缓解治疗",2013,107,"A","","男性，23岁，因乏力10天、牙龈出血伴皮肤瘀斑4天入院，既往体健。化验血Hb76g/L，WBC25×10⁹/L，Plt29×10⁹/L，骨髓增生明显活跃，原始细胞占60%，POX染色（-），PAS染色（+）成块，NSE染色（-）。该患者首选的治疗方案是",[["A","DA"],["B","COP"],["C","DVLP"],["D","ABVD"]],"C","DVLP（D为柔红霉素，V为长春新碱，L为左旋门冬酰胺酶，P为泼尼松）（C对）是ALL常用的诱导方案。DA（D为柔红霉素，A为阿糖胞苷）（十版内科学P584）（A错）为AML诱导缓解方案。COP（C为环磷酰胺，O为长春新碱，P为泼尼松）（十版内科学P598）（B错）为非霍奇金淋巴瘤化疗方案。ABVD（A为阿霉素，B为博莱霉素，V为长春花碱，D为甲氮咪胺）（十版内科学P593）（D错）为霍奇金淋巴瘤化疗方案。有关白血病一般治疗中白细胞淤滞症的描述，十版内科学有数据更新（P582）。","c67","N"],["2013-N108",59,"第一节 甲状腺功能亢进症","甲状腺毒症和甲亢的诊断",2013,108,"A","","女性，35岁，乏力，心悸一年余，近2个月症状加重，伴厌食、消瘦、手颤。查体：甲状腺弥漫性肿大，心率126次/分，心律整。实验室检查提示FT₃、FT₄显著增高，TSH降低。该患者最可能的诊断是",[["A","Graves病"],["B","自身免疫甲状腺炎"],["C","多结节性病毒性甲状腺肿"],["D","亚急性甲状腺炎"]],"A","该患者为中青年女性，出现乏力、心悸伴厌食、消瘦、手颤（甲亢的高代谢症状主要有易激动、心悸、乏力、怕热、多汗、消瘦等）。实验室检查提示：FT₃、FT₄显著增高，TSH降低。据此，该患者可诊断为甲亢。结合查体：甲状腺弥漫性肿大。故该患者最可能的诊断为Graves病（弥漫性毒性甲状腺肿，简称GD）（A对）。自身免疫性甲状腺炎（十版内科学P697）（B错）以甲状腺的炎症破坏为主，表现为甲状腺功能正常或减退，与本例不符。多结节性病毒性甲状腺肿（十版内科学P699）（C错）表现为甲状腺结节性肿大，FT₃、FT₄、TSH均正常，与本例不符。亚急性甲状腺炎（十版内科学P697）（D错）发作前常有上呼吸道感染史或腮腺炎史，表现为发热，甲状腺肿大伴单个或多个结节，与本例不符。","c68","N"],["2013-N109",59,"第一节 甲状腺功能亢进症","TRAb",2013,109,"A","","女性，35岁，乏力，心悸一年余，近2个月症状加重，伴厌食、消瘦、手颤。查体：甲状腺弥漫性肿大，心率126次/分，心律整。实验室检查提示FT₃、FT₄显著增高，TSH降低。为进一步确诊，下列检查项目中意义重大的是",[["A","促甲状腺激素受体抗体"],["B","¹³¹I摄取率"],["C","甲状腺B超"],["D","甲状腺核素显像"]],"A","Graves病的患者血清中存在针对甲状腺细胞TSH受体的特异性自身抗体，75%～96%的患者TRAb阳性，促甲状腺激素受体抗体（TRAb）是诊断Graves病的重要指标（A对）。¹³¹I摄取率（B错）对甲亢具有辅助诊断价值，目前已经被sTSH测定技术所代替。甲状腺B超（C错）对于诊断甲状腺肿块有意义，但该患者查体已触及甲状腺肿大，无需再查。甲状腺核素显像（D错）对于诊断甲状腺自主高功能腺瘤有意义，对诊断Graves病意义不大。","c68","N"],["2013-N110",59,"第一节 甲状腺功能亢进症","抗甲状腺药物",2013,110,"A","","女性，35岁，乏力，心悸一年余，近2个月症状加重，伴厌食、消瘦、手颤。查体：甲状腺弥漫性肿大，心率126次/分，心律整。实验室检查提示FT₃、FT₄显著增高，TSH降低。对该患者治疗，首选的方法是",[["A","手术治疗"],["B","咪唑类药物"],["C","碘制剂"],["D","¹³¹I治疗"]],"B","本例为中青年女性甲亢患者，病史较短，病情轻，应首选抗甲状腺药物，如咪唑类（B对）或硫脲类药物。手术治疗（A错）适应证为：甲状腺肿大显著，有压迫症状；中、重度甲亢，长期服药无效或停药复发；胸骨后甲状腺肿；细针穿刺细胞学检查怀疑恶变；ATD治疗无效或者过敏的妊娠患者。碘制剂（Ｃ错）仅用于甲亢危象和手术治疗前准备。¹³¹I治疗（D错）适应证为：甲状腺Ⅱ度肿大以上；对ATD过敏；ATD治疗或者手术治疗后复发；甲亢合并心脏病；甲亢伴白细胞减少、血小板减少或全血细胞减少；甲亢合并肝、肾等脏器功能损害；拒绝手术治疗或者有手术禁忌证；浸润性突眼。","c68","N"],["2013-N139",18,"第一节 原发性高血压","血管紧张素转换酶抑制剂",2013,139,"B","","高血压病并发2型糖尿病患者首选的药物是",[["A","血管紧张素转换酶抑制剂"],["B","钙通道阻滞剂"],["C","β受体阻滞剂"],["D","噻嗪类利尿剂"]],"A","血管紧张素转换酶抑制剂（ACEI）（A对）可增加高血压及糖尿病患者对胰岛素的敏感性，并能减少残存肾小球的高灌注、高滤过，减轻蛋白尿，可有效减轻或延缓糖尿病肾病的进展，因此高血压合并2型糖尿病首选血管紧张素转换酶抑制剂。钙通道阻滞剂（B错）为变异型心绞痛的首选药物。β受体阻滞剂（C错），可增加胰岛素抵抗，还可能掩盖和延长低血糖反应，因此不能作为高血压合并2型糖尿病首选。噻嗪类利尿剂（D错）适用于轻、中度高血压患者，对单纯收缩期高血压，盐敏感性高血压治疗效果好。","","N"],["2013-N140",17,"第四节 急性冠状综合征","钙通道阻滞剂",2013,140,"B","","变异型心绞痛并发高血压患者禁用的药物是",[["A","血管紧张素转换酶抑制剂"],["B","钙通道阻滞剂"],["C","β受体阻滞剂"],["D","噻嗪类利尿剂"]],"C","β受体阻滞剂（拮抗剂）（C对）可阻滞能使冠状动脉扩张的β₂受体，使α受体相对兴奋，诱发冠状动脉痉挛而禁用于变异型心绞痛。钙通道阻滞剂可降低血管平滑肌细胞内钙离子浓度，降低平滑肌张力，舒张血管，降低血压；此外，钙通道阻滞剂可解除冠脉痉挛，减轻冠脉狭窄，因此钙通道阻滞剂（B错）可作为变异型心绞痛并发高血压患者首选药物。血管紧张素转换酶抑制剂（A错）对变异型心绞痛无不良影响，且具有改善胰岛素抵抗和减少蛋白尿的作用，特别适用于糖耐量减退或糖尿病肾病的高血压患者。噻嗪类利尿剂（D错）对变异型心绞痛亦无不良影响，且适用于轻、中度高血压，单纯收缩期高血压，盐敏感性高血压等。","","N"],["2013-N141",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病肺功能检查",2013,141,"B","","慢性阻塞性肺疾病的典型肺容量和通气功能的特征性变化是",[["A","FEV₁/FVC减低"],["B","TLC减低"],["C","RV/TLC升高"],["D","FEV₁占预计值百分比减低"]],"A","慢性阻塞性肺疾病的特征是存在持续的呼吸系统症状和气流受限，肺功能检查对确定气流受限有重要意义，吸入支气管扩张剂后，FEV₁/FVC小于70%为确定存在持续气流受限的界限，是慢阻肺的特征性变化（A对）。FEV₁占预计值的百分比（D错）为慢性阻塞性肺疾病患者病情严重程度分级的指标；RV/TLC升高（C错）主要出现在肺组织弹性日益减退，慢阻肺进一步发展后；TLC减低（B错）见于间质性肺疾病，如特发性肺纤维化。","","N"],["2013-N142",8,"第二节 特发性肺纤维化","肺功能",2013,142,"B","","特发性肺纤维化的典型肺容量和通气功能的特征性变化是",[["A","FEV₁/FVC减低"],["B","TLC减低"],["C","RV/TLC升高"],["D","FEV₁占预计值百分比减低"]],"B","特发性肺纤维化为典型的间质性肺疾病，以限制性通气功能障碍和气体交换障碍为特征，主要表现为肺容积减少和弥散功能障碍，即肺总量（TLC）降低（B对）、肺活量（VC）减低、FEV₁/FVC正常或轻度增加（A错）；RV/TLC升高（C错）主要出现在慢性阻塞性肺疾病等通气功能障碍性疾病患者；FEV₁占预计值百分比（十版内科学P28）（D错）为慢性阻塞性肺疾病患者病情严重程度分级的指标。","","N"],["2013-N143",30,"第二节 克罗恩病","克罗恩病并发症",2013,143,"B","","克罗恩病患者最常见的并发症是",[["A","肠穿孔"],["B","肠出血"],["C","肠梗阻"],["D","中毒性巨结肠"]],"C","克罗恩病是一种慢性炎性肉芽肿性疾病，多见于末段回肠和邻近结肠，但从口腔至肛门各段消化道均可受累，呈节段性或跳跃式分布，其病变可累及肠壁全层致肠腔狭窄（十版内科学P392），因此并发症中肠梗阻（C对）最常见，其次是腹腔内脓肿，偶可并发急性穿孔（A错）或大量便血（B错）。中毒性巨结肠（D错）多发生在暴发型或重型溃疡性结肠炎患者，发生率约为5%，在克罗恩病患者中罕见发生。","","N"],["2013-N144",30,"第一节 溃疡性结肠炎","中毒性巨结肠",2013,144,"B","","暴发型或重型溃疡性结肠炎患者最易发生的并发症是",[["A","肠穿孔"],["B","肠出血"],["C","肠梗阻"],["D","中毒性巨结肠"]],"D","重症溃疡性结肠炎患者结肠病变广泛而严重，累及肌层与肠肌神经丛，肠壁张力减退，易引起结肠蠕动消失、肠内容物与气体大量积聚，致急性结肠扩张，从而发生中毒性巨结肠（D对），约5%的重症溃疡性结肠炎可出现中毒性巨结肠。","","N"],["2013-N169",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄病理生理",2013,169,"X","","严重主动脉瓣狭窄引起心肌缺血的机制包括",[["A","冠状动脉灌注压降低"],["B","左心室舒张末容积减小"],["C","左心室壁毛细血管密度相对减少"],["D","左心室射血时间延长，心肌耗氧增加"]],"ACD","主动脉瓣狭窄导致心肌缺血，引起心绞痛的机制包括：①左心室壁肥厚、心室收缩压增高和射血时间延长，增加了心肌耗氧量（D对）；②左心室肥厚，导致心肌毛细血管密度相对减少（C对）；③舒张期心腔内压力增高，压迫心内膜下冠状动脉，导致心肌灌注不足；④左心室舒张末压升高导致舒张期主动脉-左心室压差降低，减少冠状动脉灌注压（A对）。严重主动脉狭窄患者，收缩期末残留于心室内血液增多，此外，肥厚左心房在舒张期的有力收缩可使左心室充盈进一步增加，导致左心室舒张末容积增加（B错）。","","N"],["2013-N170",4,"第一节 肺炎概述","社区获得性肺炎",2013,170,"X","","青壮年社区获得性肺炎常见病原体包括",[["A","肺炎支原体"],["B","肺炎克雷伯杆菌"],["C","流感嗜血杆菌"],["D","铜绿假单胞菌"]],"AC","社区获得性肺炎常见病原体为肺炎链球菌、支原体（A对）、衣原体、流感嗜血杆菌（C对）和呼吸道病毒，而肺炎克雷伯杆菌（B错）、铜绿假单胞菌（D错）主要是医院获得性肺炎常见病原体，而非社区获得性肺炎常见病原体。","","N"],["2013-N171",36,"第一节 原发性肝癌","伴癌综合征",2013,171,"X","","原发性肝癌发生的伴癌综合征的主要表现有",[["A","自发性低血糖症"],["B","高钙血症"],["C","高脂血症"],["D","红细胞增多症"]],"AD","肝癌的伴癌综合征是指肝癌患者由于癌肿本身代谢异常或癌组织对机体影响而引起内分泌或代谢异常的一组症候群。可与肝癌典型临床表现同时存在，也可先于肝癌典型临床表现出现，常见的症状有自发性低血糖（系因肝癌细胞的异位分泌胰岛素或胰岛素样物质或肿瘤抑制胰岛素酶，亦可因肝癌组织影响糖异生所致）（A对）；红细胞增多症（可能与循环中促红细胞生成素增多有关）（D对）。高钙血症（B错）和高脂血症（C错）、类癌综合征等也是原发性肝癌伴癌综合征的表现，但比较罕见。","","N"],["2013-N172",41,"第一节 尿路感染","尿路感染的分类",2013,172,"X","","下列情况发生的尿路感染属于复杂性尿感的有",[["A","尿路结石"],["B","尿路畸形"],["C","膀胱输尿管反流"],["D","慢性肾实质性疾病"]],"ABCD","尿路感染根据有无尿路结构或功能的异常，可分为复杂性尿路感染和非复杂性尿路感染。复杂性尿感是指在尿路引流不畅、结石（A对）、畸形（B对）、膀胱-输尿管反流（C对）等结构或功能的异常，或在慢性肾实质性疾病（D对）基础上发生的尿路感染。","","N"],["2013-N173",50,"第一节 溶血性贫血概述","溶血性贫血实验室检查",2013,173,"X","","溶血性贫血时，能提示骨髓代偿性增生的实验室检查结果有",[["A","血涂片见有核红细胞"],["B","血网织红细胞增高"],["C","血清胆红素增高"],["D","骨髓增生活跃，粒红比例倒置"]],"ABD","溶血性贫血时，红细胞破坏过多，外周血红细胞减少，骨髓会代偿性增生。血涂片见有核红细胞，说明幼稚的红细胞还没来得及发育成熟，就被释放到外周血中，提示骨髓代偿性增生（A对）。网织红细胞是红细胞的前体细胞，同理，它的增高也能提示骨髓的代偿性增生（B对）。骨髓中正常粒红比为（3～5）：1，当代偿性增生时，红系比例增高，导致粒红比例倒置（D对）。血清胆红素增高只能提示红细胞破坏增多，不能提示骨髓增生的情况（C错）。","","N"],["2013-N174",60,"第二节 原发性醛固酮增多症","原发性醛固酮增多症临床表现",2013,174,"X","","有双侧肾上腺皮质增生，并可引发高血压、低血钾疾病包括",[["A","原发性醛固酮增多症"],["B","Liddle综合征"],["C","Cushing病"],["D","嗜铬细胞瘤"]],"AC","原发性醛固酮增多症（A对）双侧肾上腺皮质增生，醛固酮分泌增多，导致水、钠潴留及体液容量扩增引起高血压，排钾增多导致低血钾症。Cushing病（十版内科学P710）（C对）双侧肾上腺皮质增生，皮质醇分泌增多，皮质醇也有弱的保钠排水排钾作用，所以重度Cushing病患者会出现高血压、低血钾。Liddle综合征（十版内科学P715）（B错）为常染色体显性遗传病，主要表现为高血压、低血钾，是由上皮细胞钠通道异常，钠重吸收过多及排钾过多所致，但无肾上腺皮质增生。嗜铬细胞瘤（十版内科学P720）（D错）是由肾上腺髓质嗜铬细胞持续或间断地分泌大量儿茶酚胺引起，以高血压为主要症状，少数可出现低钾血症，但病变在肾上腺髓质，无肾上腺皮质增生。","","N"],["2014-N57",17,"第四节 急性冠状综合征","急性ST段抬高型心肌梗死鉴别诊断",2014,57,"A","","男性，72岁，2天来上腹疼痛，1天来发热，最高达38℃，在下列疾病中可排除的是",[["A","胆囊炎"],["B","十二指肠溃疡穿孔"],["C","急性心肌梗死"],["D","右下大叶性肺炎"]],"D","右下大叶性肺炎（D对）多有咳嗽、血痰、胸痛，寒战、高热等全身中毒症状明显，体温高于38.5℃，而患者为腹痛，体温最高达38℃，与其表现不符，且内科疾病一般为先出现发热，后出现疼痛；外科疾病一般为先出现疼痛，后出现发热，该患者先出现腹痛，后出现发热，故可排除右下大叶性肺炎，应考虑为腹部外科疾病，如胆囊炎（A错）、十二指肠溃疡穿孔（B错）。急性心肌梗死（十版内科学P248）（C错）常表现为中下段胸骨后疼痛，部分患者疼痛位于上腹部易被误认为急腹症，心肌梗死后可因坏死物质吸收而出现发热，一般在疼痛发生后24～48小时出现，程度与梗死范围常呈正相关，体温一般在38℃左右，故不能排除。","","N"],["2014-N58",18,"第一节 原发性高血压","推荐项目",2014,58,"A","","测量血压方法的注意事项，下列说法正确的是",[["A","被检者测前安静休息并停止吸烟5～10分钟"],["B","仰卧位时，被测的右上肢平放于腋中线水平"],["C","袖带下缘位于肘窝横纹处"],["D","袖带内充气应至肱动脉搏动音消失为止"]],"B","被测量者至少安静休息5分钟，在测量前30分钟内禁止吸烟，排空膀胱（A错）。不论被测者体位如何，血压计应放在心脏水平。故仰卧位时，被测的右上肢平放于腋中线水平正确（B对）。将袖带紧贴缚在被测者上臂，其下缘应在肘窝以上约2.5cm处（C错）。检查者触及肱动脉搏动后，将听诊器体件置于搏动上准备听诊。测量时快速充气，气囊内压力应达到肱动脉搏动消失并再升高30mmHg（D错），缓慢放气，双眼平视汞柱表面，根据听诊结果读出血压值。首先听到响亮的拍击声时的数值代表收缩压，声音消失时的数值代表舒张压。血压应至少测量2次，间隔1～2分钟；若收缩压或舒张压2次差值大于5mmHg，应再次测量，取三次读数的平均值作为测量结果。","","N"],["2014-N59",19,"第二节 扩张型心肌病","针对心律失常的药物治疗",2014,59,"A","","男性，60岁。因扩张型心肌病、心脏扩大、心功能Ⅳ级、心电监测呈现频发室性期前收缩伴短阵阵发性室性心动过速而来院。对该患者治疗应首选的方法是",[["A","静脉输注胺碘酮"],["B","静脉推注利多卡因"],["C","静脉推注美托洛尔"],["D","静脉推注普罗帕酮"]],"A","老年男性患者，既往扩张型心肌病、心功能Ⅳ级，心电图提示：频发室性期前收缩伴短阵阵发性室速，该患者目前的情况为频发的室性期前收缩（室早）触发了室性心动过速（室速），因器质性心脏病并发的室性心动过速常是心脏性猝死的高危因素，故需要尽快进行干预，对于有器质性心脏病的室速患者，研究发现Ⅰ类药物虽然能有效的抑制心律失常的发生，但是增加了心律失常的相关性死亡和总体死亡率，故推荐Ⅲ类抗心律失常药物，特别是冠心病和心力衰竭的患者，首选胺碘酮（A对）。β受体阻滞剂（C错）属于Ⅱ类抗心律失常药物，可用于症状明显的无器质性心脏病的室速患者，对于有器质性心脏病患者，可作为联合用药，改善预后。利多卡因（B错）属于Ⅰ类抗心律失常药物，适用于缺血或心肌梗死相关室速的急性期的治疗。普罗帕酮（D错）属于Ⅰ类抗心律失常药物，可用于症状明显的无器质性心脏病的室速患者，伴有心力衰竭和心肌梗死的患者禁用。","","N"],["2014-N60",17,"第四节 急性冠状综合征","血清心肌坏死标志物",2014,60,"A","","欲判断患者是否在1周前左右发生急性心肌梗死，最有价值的检查是",[["A","超声心动图"],["B","冠状动脉造影"],["C","肌钙蛋白测定"],["D","心肌核素显像"]],"C","肌钙蛋白诊断心肌损害具有很高的敏感性和特异性，假阳性率低。患者发病一周，肌钙蛋白还未降至正常，因此肌钙蛋白测定是诊断心肌损害最有价值的指标（C对）。超声心动图是利用超声的特殊物理学特性检查心脏和大血管的解剖结构及功能状态的一种无创性技术，对心梗检测价值不大（A错），但可以发现心梗的并发症如室壁瘤、乳头肌功能失调、心包积液、室间隔穿孔等。冠状动脉造影（B错）是诊断冠状动脉粥样硬化性心脏病（冠心病）的一种常用而且有效的方法。心肌核素显像（D错）主要用于了解心肌梗死后心肌存活状况。","","N"],["2014-N61",19,"第一节 肥厚型心肌病","肥厚型心肌病诊断",2014,61,"A","","女性，19岁。平素体质差，曾有一次运动后晕厥史，查体发现胸骨左缘3～4肋间可闻及3/6级收缩期杂音，下蹲位时杂音减弱，应首先考虑的疾病是",[["A","先天性心脏病室间隔缺损"],["B","风湿性心脏病二尖瓣关闭不全"],["C","肥厚型梗阻性心肌病"],["D","扩张型心肌病伴心功能不全"]],"C","本例患者有晕厥史，胸骨左缘3～4肋间可闻及3/6级收缩期杂音，下蹲位时杂音减弱，考虑为肥厚型梗阻性心肌病（C对）。先天性心脏病室间隔缺损（十版内科学P288）（A错）可在胸骨左缘3～4肋间闻及响亮粗糙的全收缩期杂音，杂音性质类似于肥厚梗阻性心脏病，但下蹲时左向右分流增加，杂音一般不减弱甚至会出现杂音增强。风湿性心脏病二尖瓣关闭不全（十版内科学P310）（B错）时可在心尖部闻及收缩期吹风样杂音，而在收缩血管和下蹲或者是躺下的情况下静脉血液回流到心脏的血液增多，二尖瓣关闭不全相对来说要更严重，所以杂音更加明显。扩张型心肌病伴心功能不全（D错）时听诊心音减弱，常可及第三或第四心音，心率快时呈奔马律，因心腔扩张可致相对性二尖瓣关闭不全，有时可于心尖部闻及收缩期杂音（十版内科学P278）。","","N"],["2014-N62",15,"第二节 慢性心力衰竭","左心衰竭体征",2014,62,"A","","下列选项中，对诊断左心室衰竭最有价值的体征是",[["A","第一心音减弱"],["B","肺部湿啰音"],["C","收缩中期喀喇音"],["D","舒张期奔马律"]],"D","左心衰竭时，由于心脏负荷增加和（或）心室壁张力减退，出现舒张期奔马律（D对）。奔马律是一种额外心音发生在舒张期的三音心律，是心肌严重损害的体征。第一心音强弱改变主要取决于心室内压增加的速率，心室内压增加慢，则S₁越弱，常见于二尖瓣关闭不全、主动脉瓣关闭不全等，左心衰竭虽可导致第一心音减弱，但多见于严重的收缩功能减退，如心肌炎、心肌病、心肌梗死等，且早期左心衰并无心音减弱（A错），故S₁缺乏特异性。肺部湿啰音虽可见于左心衰竭，但也可见于肺炎、肺结核或支气管扩张等肺部疾病，缺乏特异性（B错）。收缩中期喀喇音常见于二尖瓣脱垂（C错）。","","N"],["2014-N63",12,"第一节 急性呼吸窘迫综合征","急性呼吸窘迫综合征诊断",2014,63,"A","","下列选项中，符合ARDS诊断标准的是",[["A","PaO₂/FiO₂≤200mmHg，PCWP≤18mmHg"],["B","PaO₂/FiO₂≤300mmHg，PCWP≤18mmHg"],["C","PaO₂/FiO₂≤200mmHg，PCWP≥18mmHg"],["D","PaO₂/FiO₂≤300mmHg，PCWP≥18mmHg"]],"B","急性呼吸窘迫综合征（ARDS）是指短时间内由于各种肺内外致病因素（严重感染、创伤、休克等）导致的以肺泡毛细血管损伤为主要表现的急性的、进行性临床综合征（缺氧性急性呼吸衰竭），在较早阶段（1994年美欧共识会议），为了强调ARDS是一动态发病过程，提出了急性肺损伤（ALI）的概念，ALI代表早期和病情相对较轻的阶段，ARDS代表后期病情较为严重的阶段，但目前（2012年ARDS柏林定义）已经取消了ALI的命名，即原ALI相当于现在的轻症ARDS。根据ARDS（ALI）的命名和定义的发展情况，结合十版教材和14版实用内科学相关数据，ARDS的诊断标准中血气指标为 PaO₂/FiO₂≤300mmHg，PCWP≤18mmHg（B对）。原参考答案选择A的数据来源为旧版教材（七版内科学P153中提到ARDS 诊断标准包括PaO₂/FiO₂≤200mmHg，PCWP≤18mmHg）。需注意PCWP（肺毛细血管分压）和PAWP（肺动脉楔压）在临床上两者意义一般相同。","","N"],["2014-N64",10,"第三节 慢性肺源性心脏病","控制感染",2014,64,"A","","慢性肺源性心脏病心力衰竭最重要的治疗是",[["A","利尿药"],["B","血管扩张药"],["C","控制感染，改善呼吸功能"],["D","正性肌力药"]],"C","慢性肺源性心脏病心力衰竭，常常是由于呼吸系统感染引起。所以应采取的治疗措施中最重要的是控制感染，改善呼吸功能（C对）。慢性肺源性心脏病心力衰竭患者一般在积极控制感染、改善呼吸功能、纠正缺氧和二氧化碳潴留后，心力衰竭便能得到改善，患者尿量增多，水肿消退，不需要使用利尿药（A错）和正性肌力药（E错）、血管扩张药（D错）。但对经上述治疗无效或者严重心力衰竭患者，可适当使用上述药物。","","N"],["2014-N65",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎克雷伯杆菌肺炎诊断",2014,65,"A","","男性，72岁。一周前感冒后咳嗽、咳痰，量多，初为黄色脓性、黏稠带血，后变为红棕色胶冻状。查体：R24次/分，口唇发绀，右肺叩浊，呼吸音低，散在湿啰音，心率120次/分，心律整。血常规WBC10.5×10⁹/L。最可能的诊断是",[["A","金黄色葡萄球菌肺炎"],["B","干酪性肺炎"],["C","肺炎链球菌肺炎"],["D","肺炎克雷伯杆菌肺炎"]],"D","患者感冒后出现咳嗽、咳痰、量多等表现，呈红棕色胶冻状，该患者最可能的诊断是肺炎克雷伯杆菌肺炎（D对）。金黄色葡萄球菌肺炎（A错）主要表现为急性寒战、高热、脓痰，痰中常有血丝或脓血痰；干酪性肺炎（B错）多有低热乏力等结核全身中毒症状；肺炎链球菌肺炎（C错）痰液呈铁锈色。","","N"],["2014-N66",35,"","",2014,66,"A","","对早期肝性脑病诊断价值最大的检查结果是",[["A","定向力障碍"],["B","心理智能检查异常"],["C","病理征阳性"],["D","扑翼样震颤"]],"B","肝性脑病的临床过程可分为5期：潜伏期、前驱期、昏迷前期、昏睡期、昏迷期。早期（0期）肝性脑病一般无任何临床表现，只在心理测试或智力测试时有轻微异常（B对）。定向力障碍（A错）、病理征阳性（C错）于2期（昏迷前期）才开始出现。扑翼样震颤（D错）于肝性脑病1期（前驱期）才开始出现。","","N"],["2014-N67",35,"","",2014,67,"A","","肝硬化患者发生肝肾综合征的特点是",[["A","血BUN升高、血钠升高、尿钠降低"],["B","血BUN升高、血钠降低、尿钠升高"],["C","血BUN降低、血钠降低、尿钠升高"],["D","血BUN升高、血钠降低、尿钠降低"]],"D","肝硬化患者出现严重的门脉高压时，内脏的高动力循环血流将使体循环血流量明显减少，又因为多种扩血管物质不能被肝脏灭活，引起体循环血管床扩张，心输出量相对不足和有效血容量不足，肾素-血管紧张素-醛固酮系统和交感神经系统被进一步激活，最终导致肾皮质血管强烈收缩、肾小球滤过率下降，从而出现肾衰竭，即肝肾综合征。肝肾综合征的患者由于肾功能损坏，肾小球滤过率降低，肾小球滤过率降低时：①体内的含氮物质排不出去，出现氮质血症；②肾素-血管紧张素-醛固酮系统被激活，功能性肾衰，肾小管功能未受损，尿钠重吸收增加，尿钠含量降低；③由于尿量减少，体内的水排不出去，产生稀释性低钠血症。综上，血BUN（血尿素氮）升高、血钠降低、尿钠降低（D对）。","","N"],["2014-N68",29,"第一节 肠结核","肠结核诊断",2014,68,"A","","男性，32岁。3个多月来低热、乏力、大便稀、右下腹痛、体重减轻。查体：T37.6℃，P84次/分，BP110/70mmHg，心肺检查未见异常，腹软，右下腹轻压痛，肝脾肋下未触及，肠鸣音活跃。化验血Hb125g/L，WBC5.4×10⁹/L，Plt252×10⁹/L，粪常规偶见WBC。结肠镜检查示回盲部肠黏膜充血水肿，横行溃疡形成，肠腔狭窄，大小及形态各异的炎性息肉。最可能的诊断是",[["A","克罗恩病"],["B","肠结核"],["C","结肠癌"],["D","阿米巴肉芽肿"]],"B","青年男性患者，右下腹痛3个多月，稀便、右下腹压痛、肠鸣音活跃等消化道表现，伴长期低热、乏力、消瘦等结核中毒症状，实验室检查粪便中可见白细胞，结肠镜下检查回盲部肠黏膜充血水肿，横行溃疡形成，有大小及形态各异的炎性息肉，符合肠结核临床表现（B对）。克罗恩病（A错）病变呈节段性、非对称性分布，结肠镜下可见溃疡为纵行裂隙状（十版内科学P392）。结肠癌（C错）比肠结核发病年龄大，一般无结核毒血症状，常表现为结肠肿块，或火山口状溃疡，结肠镜检查加粘膜活检可确诊。阿米巴肉芽肿（D错）患者既往有相应感染史，脓血便常见，粪便常规或孵化检查可发现有关病原体（十版内科学P390），结肠镜下可见其溃疡较深，溃疡间黏膜多正常。","","N"],["2014-N69",40,"第五节 肾病综合征","血栓和栓塞",2014,69,"A","","肾病综合征患者发生血栓并发症，最常见的部位是",[["A","肾静脉"],["B","脾静脉"],["C","下肢静脉"],["D","肺静脉"]],"A","肾病综合征患者容易发生血栓，其中以肾静脉（A对）血栓最为常见，特别是膜性肾病发生率可达40%～50%。其他静脉也可有血栓、栓塞并发症，但相对少见。血栓形成的原因包括：血液浓缩及高脂血症造成血液粘稠度增加，凝血、抗凝和纤溶系统失衡，血小板过度激活，应用利尿剂及糖皮质激素进一步加重高凝状态。","","N"],["2014-N70",40,"第二节 急性肾小球肾炎","急性肾小球肾炎诊断",2014,70,"A","","男性，16岁，少尿、水肿1周，气促不能平卧伴咳粉红色泡沫痰1天入院，既往体健。查体T37.5℃，P120次/分，R24次/分，BP165/105mmHg，端坐呼吸，全身水肿明显，双肺底可闻及湿啰音，心律整，无杂音。化验血Hb120g/L，尿蛋白（++），尿比重1.025，尿沉渣镜检RBC30～40/HP，颗粒管型0～1/HP，血Cr178μmol/L。该患者发生急性心力衰竭最可能的病因是",[["A","急性肾小球肾炎"],["B","急进性肾小球肾炎"],["C","肾病综合征"],["D","高血压病"]],"A","青少年男性患者，尿沉渣镜检RBC30～40/HP（提示血尿）、尿蛋白（++）、全身水肿明显、BP165/105mmHg（典型的肾炎综合征表现），血Cr178μmol/L（正常值约53～106μmol/L），少尿（提示肾功能减退）。气促不能平卧伴咳粉红色泡沫痰，双肺底可闻及湿啰音（提示充血性心力衰竭），诊断考虑急性肾小球肾炎（A对），急性肾炎综合征期水、钠潴留及高血压引起的充血性心力衰竭。急进性肾小球肾炎（B错）多表现为肾炎综合征，且早期出现少尿性急性肾功能衰竭症状，常伴有中度贫血，而本例患者肾功能仅轻度下降且无贫血，因此不考虑急进性肾小球肾炎。肾病综合征（C错）多表现为大量蛋白尿、低蛋白血症、水肿及高脂血症（十版内科学P480），该患者尿蛋白仅++，且无法判断是否存在低蛋白血症。高血压病（D错）导致肾损伤为一慢性过程，肾小球受损较轻，主要影响尿的浓缩稀释功能（十版内科学P272），该患者病程仅1周。","","N"],["2014-N71",52,"第二节 急性白血病","白血病细胞增殖浸润的表现",2014,71,"A","","下列不属于白血病细胞浸润表现的是",[["A","皮肤瘀斑"],["B","淋巴结肿大"],["C","牙龈增生"],["D","关节痛"]],"A","白血病的临床表现分为正常骨髓造血功能受抑制表现和白血病细胞增殖浸润的表现。白血病细胞增殖浸润的主要表现为淋巴结和肝脾肿大（B错）、骨骼和关节疼痛（D错）、眼部的粒细胞肉瘤（绿色瘤）、皮肤蓝灰色斑丘疹、牙龈增生（C错）、中枢神经系统和睾丸的浸润等。皮肤瘀斑（A对）是由于白血病患者外周血血小板减少而引起的皮肤黏膜出血性病变，属于正常骨髓造血功能受抑制表现。白血病细胞浸润皮肤表现为蓝灰色斑丘疹，局部皮肤隆起、变硬，呈紫蓝色结节，应注意区分。","","N"],["2014-N72",57,"第一节 血友病","血友病病因与遗传规律",2014,72,"A","","男性，18岁，2天来右膝关节肿胀。自幼外伤后易出血不止。查体：皮肤黏膜未见出血点和紫癜，右膝关节肿胀，局部有压痛。化验示APTT延长，PT正常，该患者出血最可能的原因是",[["A","凝血酶生成障碍"],["B","纤维蛋白溶解亢进"],["C","凝血活酶生成障碍"],["D","纤维蛋白生成障碍"]],"C","该患者为青年男性，自幼外伤后出血不止（与生俱来），皮肤、黏膜未见出血点和紫癜（皮肤、黏膜出血点和紫癜等多为血管、血小板异常所致），右膝关节肿胀有压痛，提示为关节内出血（深部血肿、关节出血多与凝血功能障碍有关），说明为凝血功能障碍所致。患者化验示APTT（活化部分凝血活酶时间）延长（APTT反映的是内源性凝血系统功能），PT（凝血酶原时间）正常（PT反映外源性凝血系统功能），说明患者内源性凝血功能异常，而外源性凝血功能正常。符合血友病的诊断。血友病是一组因遗传性凝血活酶生成障碍引起的出血性疾病（C对）。凝血过程分为三个过程：凝血活酶的形成、凝血酶原的激活和纤维蛋白的生成。其中凝血酶原的激活和纤维蛋白的生成为内、外凝血途径的共同过程。由于外源性凝血功能正常，说明共同过程无障碍（AD错）。血友病主要由凝血活酶生成障碍引起，而与纤维蛋白溶解亢进无关（B错）。","","N"],["2014-N73",60,"第二节 原发性醛固酮增多症","原发性醛固酮增多症临床表现",2014,73,"A","","原发性醛固酮增多症最常见和最早出现的临床表现是",[["A","心律失常"],["B","高血压"],["C","低血钾症"],["D","周期性麻痹"]],"B","原发性醛固酮增多症（原醛症）是由于肾上腺皮质病变所致醛固酮分泌增多，醛固酮具有保钠保水排钾作用，还能增强血管平滑肌对儿茶酚胺的敏感性，可引起高血压和低钾血症，其中高血压是原发性醛固酮增多症最常见和最早出现的临床表现（B对）。早期仅有高血压，无低血钾症（C错）。心律失常（A错）和周期性麻痹（D错）均可由低钾血症所致，为原发性醛固酮增多症的临床表现，但都不是最常见和最早出现的临床表现。","","N"],["2014-N74",61,"第一节 糖尿病","胰岛素",2014,74,"A","","女性，35岁，1个月前与人争吵后出现口渴、多饮，体重下降3公斤，既往无糖尿病史，体重指数21，空腹血糖15.9mmol/L，尿酮体（++），最适合的治疗是",[["A","使用双胍类药物"],["B","使用磺脲类药物"],["C","使用胰岛素"],["D","使用磺脲类加双胍类药物"]],"C","该患者为青年女性，1个月前出现口渴、多饮、体重下降（糖尿病症状），空腹血糖15.9mmol/L（≥7.0mmol/L应考虑糖尿病），故诊断为糖尿病。又患者尿酮体（++）、血糖＞11mmol/L，说明合并有糖尿病酮症酸中毒。根据胰岛素适应证：①T1DM；②各种严重的糖尿病急性或慢性并发症；③手术、妊娠和分娩；④新发病且与T1DM鉴别困难的消瘦糖尿病患者；⑤新诊断的T2DM伴有明显高血糖；或在糖尿病病程中无明显诱因出现体重显著下降者；⑥T2DMβ细胞功能明显减退者；⑦某些特殊类型糖尿病。糖尿病患者合并有急性并发症如糖尿病酮症酸中毒，应用胰岛素来降低血糖（C对），而不是使用降糖药物控制血糖（ABD错）。","","N"],["2014-N75",68,"第一节 类风湿关节炎","强直性脊柱炎",2014,75,"A","","下列导致关节痛的疾病中，休息后症状加重的是",[["A","强直性脊柱炎"],["B","系统性红斑狼疮"],["C","痛风"],["D","骨关节炎"]],"A","强直性脊柱炎（AS）是以骶髂关节和脊柱附着点炎症为主要症状的疾病，其症状在夜间休息或久坐时加重，活动后疼痛可以减轻（A对）。系统性红斑狼疮（十版内科学P820）（B错）是一种多发于青年女性的累及多脏器的自身免疫性炎症性结缔组织病，骨关节主要表现有关节痛、关节炎，关节痛发病与休息和运动无关。痛风（十版内科学P851）（C错）患者多数发作前无明显征兆，或仅有疲乏、全身不适和关节刺痛等，典型发作常于深夜因关节痛而惊醒，疼痛进行性加剧，与休息和运动无关。骨关节炎（十版内科学P855）（D错）为一种退行性病变，关节疼痛多发生于活动以后，休息可以缓解。","","N"],["2014-N76",69,"第一节 系统性红斑狼疮","抗ENA抗体谱",2014,76,"A","","代表系统性红斑狼疮疾病活动性的自身抗体是",[["A","抗SSA（Ro）"],["B","抗rRNP抗体"],["C","抗Sm抗体"],["D","抗核抗体"]],"B","对判断系统性红斑狼疮（SLE）活动性最有价值的自身抗体是抗dsDNA抗体。另外代表系统性红斑狼疮疾病活动性的自身抗体还有抗rRNP抗体（B对）。抗SSA（Ro）（A错）与SLE患者出现光过敏、血管炎、皮损、白细胞降低、新生儿狼疮有关，与SLE活动性无关。抗Sm抗体（C错）有助于早期和不典型患者的诊断，特异性99%，敏感性25%，与疾病活动无相关性。抗核抗体（D错）在多种自身免疫病中均呈不同程度的阳性率，如系统性红斑狼疮（SLE）、类风湿性关节炎（RA）、混合性结缔组织病（MCTD）等，特异性差，与SLE活动无相关性。","","N"],["2014-N93",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞诊断",2014,93,"A","","男性，60岁。3个月来自觉乏力，1个月来出现渐进性呼吸困难、气短、腹胀、尿少、下肢水肿，体重无明显变化，无胸痛、发热等。既往有慢性支气管炎病史30年，饮酒史20年。查体：T36.5℃，P102次/分，BP90/80mmHg，轻度贫血貌，颈静脉怒张，双肺（-），心界明显向两侧扩大，心音低，肝肋下3.0cm，双下肢水肿（++），深吸气时脉搏消失。根据患者病史及体检，导致目前临床表现的最可能原因是",[["A","心脏压塞"],["B","呼吸衰竭"],["C","肝脏衰竭"],["D","全心衰竭"]],"A","老年男性患者，既往慢支病史，短期内（1个月）出现渐进性呼吸困难及腹胀、尿少、下肢水肿等一系列体循环淤血症状。查体可见：体温、脉搏正常，血压降低（收缩压降低明显，舒张压变化不大）且脉压变小；心脏向两侧明显扩大、心音低，奇脉，以及颈静脉怒张、肝大、双下肢水肿等体循环淤血体征。综合该患者的病史、症状、体征，导致目前临床表现的最可能原因是心脏压塞（A对）。呼吸衰竭（B错）主要表现为低氧血症所致的呼吸困难及多器官功能障碍，但其临床表现缺乏特异性，诊断常依赖于动脉血气分析，可见低氧、高碳酸血症。肝脏衰竭（C错）时肝功严重受损，进而表现为代谢和解毒功能丧失，严重的凝血系统障碍、消化系统症状及肝性脑病等多器官功能衰竭。全心衰竭（D错）与心脏压塞的鉴别较难，但心力衰竭常伴有高血压、冠心病、心肌病等病史，查体闻及肺部啰音、心脏杂音等特异性体征。","c73","N"],["2014-N94",22,"第一节 急性心包炎","急性心包炎诊断",2014,94,"A","","男性，60岁。3个月来自觉乏力，1个月来出现渐进性呼吸困难、气短、腹胀、尿少、下肢水肿，体重无明显变化，无胸痛、发热等。既往有慢性支气管炎病史30年，饮酒史20年。查体：T36.5℃，P102次/分，BP90/80mmHg，轻度贫血貌，颈静脉怒张，双肺（-），心界明显向两侧扩大，心音低，肝肋下3.0cm，双下肢水肿（++），深吸气时脉搏消失。应首先考虑的疾病诊断是",[["A","渗出性心包炎"],["B","酒精性心肌病"],["C","扩张型心肌病"],["D","COPD"]],"A","心包疾患或其他病因累及心包可以造成心包渗出和心包积液，当积液迅速或积液量达到一定程度时，可造成心脏输出量和回心血量明显下降而产生临床症状，即心脏压塞（A对）。酒精性心肌病（B错）、扩张型心肌病（C错）、COPD（慢性阻塞性肺疾病）（D错）不会引起心脏压塞。","c73","N"],["2014-N95",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞超声心动图",2014,95,"A","","男性，60岁。3个月来自觉乏力，1个月来出现渐进性呼吸困难、气短、腹胀、尿少、下肢水肿，体重无明显变化，无胸痛、发热等。既往有慢性支气管炎病史30年，饮酒史20年。查体：T36.5℃，P102次/分，BP90/80mmHg，轻度贫血貌，颈静脉怒张，双肺（-），心界明显向两侧扩大，心音低，肝肋下3.0cm，双下肢水肿（++），深吸气时脉搏消失。为明确诊断，应选用最简便而又有价值的检查是",[["A","动态心电图"],["B","胸部CT检查"],["C","胸部X线片"],["D","超声心动图"]],"D","渗出性心包炎的首选检查是超声心动图，对诊断心包积液简单易行，迅速可靠（D对）。动态心电图用于阵发性心律失常的诊断（A错）。胸部CT检查价格较贵且操作较繁琐，不作为首选（B错）。渗出性心包炎立位胸部X线片（C错）可见烧瓶样变，有一定的诊断意义，但一般不作首选检查。","c73","N"],["2014-N96",9,"第一节 肺血栓栓塞症","肺血栓栓塞症诊断",2014,96,"A","","男性，75岁。下肢骨折术后1周突发呼吸困难，晕厥1次，查体：BP85/55mmHg，口唇发绀，颈静脉充盈，肺动脉瓣区第二心音亢进。该患者最可能的诊断为",[["A","急性心肌梗死"],["B","心律失常"],["C","主动脉夹层"],["D","肺栓塞"]],"D","老年男性患者，下肢骨折术后（术后须制动，静脉回流不畅，存在血栓形成的高危因素），突发呼吸困难；口唇发绀（提示低氧血症）；肺动脉瓣区第二心音亢进（提示肺动脉高压），诊断考虑下肢深静脉血栓脱落造成肺栓塞（D对）。急性心肌梗死（A错）可导致血压降低、颈静脉充盈，但不会出现肺动脉瓣区第二心音亢进。单纯的心律失常（B错）并不足以解释患者的所有症状。主动脉夹层（十版内科学P336）（C错）的典型表现为突发前胸或胸背部持续性、撕裂样或刀割样剧痛，两上肢或上下肢血压相差较大，与本例不符。","c74","N"],["2014-N97",9,"第一节 肺血栓栓塞症","肺动脉造影",2014,97,"A","","男性，75岁。下肢骨折术后1周突发呼吸困难，晕厥1次，查体：BP85/55mmHg，口唇发绀，颈静脉充盈，肺动脉瓣区第二心音亢进。下列检查中，对该患者疾病诊断意义最大的是",[["A","心电图"],["B","血气分析"],["C","超声心动图"],["D","CT肺动脉造影"]],"D","CT是肺动脉栓塞的一线确诊手段，采用特殊操作技术进行CT肺动脉造影（D对），能够准确发现段以上肺动脉栓塞。心电图用于心律失常的诊断（A错），但多数肺栓塞病例呈现非特异性心电图异常。血气分析可用于呼吸衰竭及呼衰类型的诊断（B错），肺栓塞常表现为低氧血症及低碳酸血症，可作为辅助诊断依据。超声心动图（C错）可发现右室功能障碍的一些表现，对肺栓塞的诊断有一定间接提示意义。","c74","N"],["2014-N98",9,"第一节 肺血栓栓塞症","肺血栓栓塞症溶栓治疗",2014,98,"A","","男性，75岁。下肢骨折术后1周突发呼吸困难，晕厥1次，查体：BP85/55mmHg，口唇发绀，颈静脉充盈，肺动脉瓣区第二心音亢进。该患者首选的治疗是",[["A","介入治疗"],["B","外科手术"],["C","起搏器置入"],["D","溶栓治疗"]],"D","溶栓治疗主要适用于高危（大面积）肺动脉栓塞的病例（有明显呼吸困难、胸痛、低氧血症等），溶栓时间窗一般定为14天以内。患者存在呼吸困难，晕厥，考虑栓塞面积较大，尽管存在2周内大手术的相对禁忌症，但此时如不及时溶栓，可能会产生严重后果，因此首选溶栓治疗（D对）。介入治疗（A错）在肺动脉栓塞仅用于肺动脉主干或主要分支的高危肺栓塞患者。外科手术（B错）在肺动脉栓塞仅适用于经积极的内科治疗或导管介入治疗无效的紧急情况、有溶栓禁忌证、或在溶栓起效前很可能会发生致死性休克的患者。起搏器置入（C错）适用于心脏停搏或心率缓慢性心律失常的患者。","c74","N"],["2014-N99",38,"第一节 消化道出血","消化道出血诊断",2014,99,"A","","男性，26岁。排柏油便2天，加重伴头晕、心慌半天急诊入院。既往无肝病史，近期无服药史。查体：BP70/40mmHg，心率120次/分，腹平软，无压痛，肝、脾肋下未触及，四肢末梢发凉。该患者最可能的诊断是",[["A","胃癌"],["B","十二指肠溃疡"],["C","肝硬化食管静脉曲张破裂出血"],["D","急性胃炎"]],"B","26岁青年男性患者，排柏油便2天，查体：BP70/40mmHg（血压下降），心率120次/分（心率加快），PU（消化性溃疡）（十版内科学P375）是上消化道出血中最常见的病因，且DU（十二指肠溃疡）较GU（胃溃疡）多见，综合该患者的年龄、病史、查体，考虑该患者为十二指肠溃疡（B对）。胃癌（A错）多见于老年人，早期无明显症状体征，进展期最常见症状为体重减轻和上腹痛，查体上腹部可扪及肿块，有压痛。溃疡型胃癌出血时可引起呕血或黑粪，继之出现贫血；肝硬化食管静脉曲张破裂出血（C错）多有肝病病史，出现食管静脉破裂出血多提示已进入失代偿期，出现肝功能减退及门静脉高压的一系列临床表现；急性胃炎（D错）多有近期服药史，临床表现常有上腹痛、恶心和食欲不振等，重症可有呕血、黑粪。","c75","N"],["2014-N100",38,"第一节 消化道出血","积极补充血容量",2014,100,"A","","男性，26岁。排柏油便2天，加重伴头晕、心慌半天急诊入院。既往无肝病史，近期无服药史。查体：BP70/40mmHg，心率120次/分，腹平软，无压痛，肝、脾肋下未触及，四肢末梢发凉。首选的处理",[["A","三腔二囊管压迫止血"],["B","补充血容量"],["C","急诊手术治疗"],["D","胃镜止血"]],"B","本例消化性溃疡并发出血，心率加快，血压明显降低，四肢末梢发凉，提示已经出现失血性周围循环衰竭，首选的治疗是抗休克、补充血容量（B对）。三腔二囊管治疗（A错）为食管囊、胃囊注气以压迫止血，多用于肝硬化门静脉高压导致的食管胃底静脉曲张破裂出血，一般不用于消化性溃疡出血；胃镜止血（D错）一般在抗休克治疗后进行；急诊手术治疗（C错）仅用于保守治疗无效时，不作为首选的治疗方法。","c75","N"],["2014-N101",38,"第一节 消化道出血","胃镜和结肠镜",2014,101,"A","","男性，26岁。排柏油便2天，加重伴头晕、心慌半天急诊入院。既往无肝病史，近期无服药史。查体：BP70/40mmHg，心率120次/分，腹平软，无压痛，肝、脾肋下未触及，四肢末梢发凉。为明确诊断，最重要的检查方法是",[["A","血清CEA测定"],["B","稳定后胃镜检查"],["C","稳定后X线钡餐检查"],["D","腹部B型超声检查"]],"B","上消化道出血后，为明确诊断，应在抗休克治疗患者病情稳定后行胃镜检查（B对）。血清CEA（癌胚抗原）（A错）对大肠癌、乳腺癌和肺癌的疗效判断、病情发展、监测和预后估计是一个较好的肿瘤标志物，但其特异性不强，灵敏度不高，对肿瘤早期诊断作用不明显；X线钡餐检查（C错）目前已多为胃镜检查所替代，故主要适用于有胃镜检查禁忌证或不愿进行胃镜检查者，且一般在出血停止后数天进行；腹部B型超声（D错）常用于腹腔实质脏器病变诊断，对消化道溃疡诊断价值不大。","c75","N"],["2014-N102",40,"第四节 IgA肾病","IgA肾病诊断",2014,102,"A","","男性，25岁，咽痛、发热1天后出现肉眼血尿，无尿频、尿痛、尿急。化验尿蛋白阴性，尿沉渣镜检RBC满视野/HP。该患者最可能的诊断是",[["A","急性肾小球肾炎"],["B","过敏性紫癜肾炎"],["C","IgA肾病"],["D","急进性肾小球肾炎"]],"C","青少年男性患者（IgA肾病好发人群），咽痛、发热一天（上呼吸道感染前驱症状）后出现肉眼血尿（几乎所有IgA肾病患者均有血尿），尿蛋白阴性，无尿频、尿急、尿痛（无尿路刺激征，泌尿系感染可能性较低），诊断考虑IgA肾病（C对）。急性肾小球肾炎（A错）常表现为上呼吸道感染1～3周后，出现血尿、蛋白尿、水肿、高血压、肾功能一过性减退，而该患者上呼吸道感染1天后即出现肉眼血尿、无蛋白尿、水肿及高血压。过敏性紫癜性肾炎（B错）除血尿症状以外，尚有双下肢对称性小出血点、腹痛等紫癜的其他表现。急进性肾小球肾炎（D错）常表现为血尿、蛋白尿、水肿、高血压的肾炎综合征，肾功能急剧恶化，早期出现少尿性急性肾衰竭。","c76","N"],["2014-N103",40,"第四节 IgA肾病","IgA肾病病理",2014,103,"A","","男性，25岁，咽痛、发热1天后出现肉眼血尿，无尿频、尿痛、尿急。化验尿蛋白阴性，尿沉渣镜检RBC满视野/HP。该患者活检最可能的类型是",[["A","新月体性肾小球肾炎"],["B","系膜增生性肾小球肾炎"],["C","毛细血管内增生性肾小球肾炎"],["D","系膜毛细血管性肾小球肾炎"]],"B","IgA肾病病理变化多种多样，可涉及增生性肾小球肾炎几乎所有的病理类型，病变程度可轻重不一，主要病理类型为系膜增生性肾小球肾炎（B对）。新月体性肾小球肾炎（A错）为急进性肾小球肾炎常见的病理类型。毛细血管内增生性肾小球肾炎（C错）为急性肾炎的常见病理类型。系膜毛细血管性肾小球肾炎（D错）为肾病综合征的常见病理类型。","c76","N"],["2014-N104",40,"第四节 IgA肾病","IgA肾病治疗",2014,104,"A","","男性，25岁，咽痛、发热1天后出现肉眼血尿，无尿频、尿痛、尿急。化验尿蛋白阴性，尿沉渣镜检RBC满视野/HP。若诊断确定，处理方案是",[["A","血浆置换治疗"],["B","给予糖皮质激素"],["C","给予免疫抑制剂"],["D","对症支持治疗"]],"D","本例IgA肾病患者，仅有血尿，无蛋白尿、水肿、高血压等其他临床表现，对IgA肾病单纯性镜下血尿患者，一般无特殊治疗，避免劳累、预防感冒和避免使用肾毒性药物，对症支持治疗即可（D对）。此类患者一般预后较好，肾功能可较长期地维持在正常范围。血浆置换治疗（A错）可用于治疗各型急进性肾炎，但主要适用于Ⅰ型和就诊时急性肾衰竭已经需要透析的Ⅲ型。糖皮质激素（B错）、免疫抑制剂（C错）主要用于治疗肾病综合征。","c76","N"],["2014-N105",47,"第一节 缺铁性贫血","缺铁性贫血诊断",2014,105,"A","","男性，45岁。逐渐乏力、心慌2个月来诊，病后偶有上腹部不适，进食正常，体重略有下降，大小便正常，既往体健。查体：贫血貌，皮肤未见出血点，浅表淋巴结不大，巩膜无黄染，心肺腹检查未见明显异常。化验Hb78g/L，MCV75fl，MCHC29%，WBC7.2×10⁹/L，分类中见中性粒细胞70%，淋巴细胞30%，Plt260×10⁹/L。粪便隐血阳性。该患者最可能的诊断是",[["A","肾性贫血"],["B","铁粒幼细胞性贫血"],["C","慢性病性贫血"],["D","缺铁性贫血"]],"D","患者为中年男性，出现心慌、乏力等贫血症状，Hb78g/L（男性正常值为130～175g/L），可诊断为中度贫血（60～90g/L为中度贫血）。MCV75fl（＜80fl），MCHC29%（＜32%），可诊断为小细胞低色素性贫血。患者粪便隐血阳性，说明有消化道出血，临床上小细胞低色素性贫血以缺铁性贫血最常见，故目前最可能的诊断是慢性消化道出血导致的缺铁性贫血（D对）。肾性贫血（A错）患者常有慢性肾脏疾病，除贫血相关表现外，还应有血尿、蛋白尿、水肿、高血压等原发病的表现，与该患者不符。铁粒幼细胞性贫血（十版内科学P551）（B错）常由遗传或不明原因的红细胞铁利用障碍引起，临床上少见，虽也可出现小细胞低色素性贫血，但考虑到该患者有明显的慢性出血史，缺铁性贫血的可能性更大。慢性病性贫血（十版内科学P551）（C错）一般继发于慢性炎症、感染、肿瘤等疾病，该患者既往体健，无相关疾病病史。","c77","N"],["2014-N106",47,"第一节 缺铁性贫血","缺铁性贫血实验室检查",2014,106,"A","","男性，45岁。逐渐乏力、心慌2个月来诊，病后偶有上腹部不适，进食正常，体重略有下降，大小便正常，既往体健。查体：贫血貌，皮肤未见出血点，浅表淋巴结不大，巩膜无黄染，心肺腹检查未见明显异常。化验Hb78g/L，MCV75fl，MCHC29%，WBC7.2×10⁹/L，分类中见中性粒细胞70%，淋巴细胞30%，Plt260×10⁹/L。粪便隐血阳性。下列检查中，对诊断意义最小的是",[["A","尿常规"],["B","血清铁和铁蛋白测定"],["C","消化道内镜"],["D","骨髓细胞学"]],"A","患者目前诊断为缺铁性贫血。缺铁性贫血时，血清铁和铁蛋白降低，故测定血清铁和铁蛋白（B错）有利于本病的诊断。患者粪便隐血阳性，消化道内镜检查（C错）有助于查明消化道出血原因，以明确缺铁性贫血的病因，并尽可能地进行病因治疗。缺铁性贫血时，骨髓红系增生活跃或明显活跃，骨髓铁染色显示骨髓小粒可染铁消失，铁粒幼细胞减少，故骨髓细胞学检查（D错）有利于本病的诊断。缺铁性贫血时，尿常规一般无异常，故尿常规检查（A对）对缺铁性贫血的诊断价值不大，一般用于肾脏疾病的检查。","c77","N"],["2014-N107",47,"第一节 缺铁性贫血","铁代谢",2014,107,"A","","男性，45岁。逐渐乏力、心慌2个月来诊，病后偶有上腹部不适，进食正常，体重略有下降，大小便正常，既往体健。查体：贫血貌，皮肤未见出血点，浅表淋巴结不大，巩膜无黄染，心肺腹检查未见明显异常。化验Hb78g/L，MCV75fl，MCHC29%，WBC7.2×10⁹/L，分类中见中性粒细胞70%，淋巴细胞30%，Plt260×10⁹/L。粪便隐血阳性。下列符合该患者铁代谢异常的结果是",[["A","骨髓细胞内铁减低、外铁增高"],["B","骨髓细胞内、外铁均增高"],["C","骨髓细胞内铁增高、外铁减低"],["D","骨髓细胞内、外铁均减低"]],"D","患者目前诊断为缺铁性贫血，对于缺铁性贫血的患者，由于原料铁不足，骨髓小粒中含铁血黄素颗粒减少或消失；幼红细胞内铁小粒减少或消失，铁粒幼细胞减少。细胞外铁为骨髓小粒中贮存在单核-巨噬细胞系统内的铁（在幼红细胞之外的铁），细胞内铁为幼红细胞内的铁（含有铁颗粒的幼红细胞称为铁粒幼红细胞）（九版诊断学P267）。故骨髓细胞内、外铁均减低（D对）。","c77","N"],["2014-N108",60,"第一节 库欣综合征","库欣综合征诊断与鉴别诊断",2014,108,"A","","男性，46岁，有乏力、腰背痛2年，常有便秘，既往高血压病史5年。查体：腹部稍膨隆，四肢近端较细，胸椎X线提示有骨质疏松，B超显示左侧肾上腺可见一直径约3.5cm肿物，临床拟诊为“皮质醇增多症”。上述描述中，对提示“皮质醇增多症”诊断意义不大的是",[["A","腹部膨隆"],["B","高血压"],["C","骨质疏松"],["D","便秘"]],"D","皮质醇增多症又称库欣综合征，是由多种病因引起的以高皮质醇血症为特征的临床综合征。皮质醇增多引起身体脂肪重新分布，四肢脂肪组织分解增强，躯干部脂肪沉积，表现为满月脸、水牛背、腹部膨隆（A错）、四肢近端肥胖粗大而远端细弱等，称为向心性肥胖。皮质醇能保钠排钾，还能增强血管平滑肌对儿茶酚胺的敏感性，故早期病例以高血压为主（B错）。病程较久者可出现骨质疏松（C错），脊柱可发生压缩畸形，身材变矮。便秘（D对）表现甚少，故对于皮质醇增多症诊断意义不大。","c78","N"],["2014-N109",60,"第一节 库欣综合征","库欣综合征诊断依据",2014,109,"A","","男性，46岁，有乏力、腰背痛2年，常有便秘，既往高血压病史5年。查体：腹部稍膨隆，四肢近端较细，胸椎X线提示有骨质疏松，B超显示左侧肾上腺可见一直径约3.5cm肿物，临床拟诊为“皮质醇增多症”。为进一步确定“皮质醇增多症”诊断，最有价值的检查是",[["A","血ACTH"],["B","小剂量地塞米松抑制试验"],["C","大剂量地塞米松抑制试验"],["D","肾上腺CT"]],"B","肥胖者小剂量地塞米松抑制试验为阳性，而皮质醇增多症患者小剂量地塞米松抑制试验为阴性，故小剂量地塞米松抑制试验主要用于鉴别单纯性肥胖和皮质醇增多症（B对）。血ACTH测定（A错）主要用于库欣综合征病因的鉴别和肿瘤的定位。大剂量地塞米松抑制试验（C错）主要用于鉴别库欣综合征的病因，如库欣病和非垂体性库欣综合征。肾上腺CT（D错）主要用于了解肾上腺肿瘤的情况（进一步明确肿瘤的部位、性质），是针对病因的检查。","c78","N"],["2014-N110",60,"第一节 库欣综合征","肾上腺皮质腺瘤",2014,110,"A","","男性，46岁，有乏力、腰背痛2年，常有便秘，既往高血压病史5年。查体：腹部稍膨隆，四肢近端较细，胸椎X线提示有骨质疏松，B超显示左侧肾上腺可见一直径约3.5cm肿物，临床拟诊为“皮质醇增多症”。患者确诊为“肾上腺腺瘤”，对该患者的治疗原则，正确的是",[["A","手术切除+终身激素替代治疗"],["B","单纯手术切除腺瘤"],["C","手术切除+短期激素替代治疗"],["D","手术切除+较长期激素替代治疗"]],"D","肾上腺腺瘤首选手术治疗，手术切除可获根治。因为长时期高皮质醇血症抑制垂体及健侧肾上腺的功能，术后可能出现肾上腺皮质功能减退，需较长期使用激素作替代治疗（D对B错）。短期内该患者垂体及健侧肾上腺的功能尚未恢复，而不采取（C错）。较长期激素替代治疗后，该患者垂体及健侧肾上腺的功能逐渐恢复，而不需采取终身激素替代治疗（A错）。","c78","N"],["2014-N139",23,"第一节 感染性心内膜炎","易患因素",2014,139,"B","","最容易并发感染性心内膜炎的瓣膜损害是",[["A","二尖瓣狭窄"],["B","二尖瓣关闭不全"],["C","主动脉瓣狭窄"],["D","肺动脉瓣狭窄"]],"B","亚急性感染性心内膜炎主要发生于器质性心脏瓣膜病，尤其是二尖瓣和主动脉瓣。赘生物常位于血流从高压腔经病变瓣膜口至低压腔产生高速射流和湍流的下游，如二尖瓣关闭不全（B对）的瓣叶心房面、主动脉关闭不全的瓣叶心室面，可能与这些部位的侧压下降和内膜灌注减少，有利于微生物沉积和生长有关。瓣膜狭窄如二尖瓣狭窄（A错）、主动脉瓣狭窄（C错）、肺动脉瓣狭窄（D错）引起的感染性心内膜炎较瓣膜关闭不全少见。","","N"],["2014-N140",21,"第三节 二尖瓣狭窄","房颤",2014,140,"B","","最容易并发心房颤动的瓣膜损害是",[["A","二尖瓣狭窄"],["B","二尖瓣关闭不全"],["C","主动脉瓣狭窄"],["D","肺动脉瓣狭窄"]],"A","二尖瓣狭窄时，左心房压力增高致使左心房扩大及房壁纤维化，极易发生房颤（A对）。慢性二尖瓣关闭不全导致房颤见于重度患者（十版内科学P310）（B错）；主动脉瓣狭窄10%的患者可发生房颤（十版内科学P301）（C错）。肺动脉瓣狭窄（D错）与心房颤动的发生一般无关。","","N"],["2014-N141",5,"第一节 肺脓肿","肺脓肿诊断",2014,141,"B","","男性，45岁。醉酒后出现发热、咳嗽，1周后咳黏液脓性痰伴胸痛，胸部CT提示下叶背段大片模糊阴影，密度不均匀，最可能的诊断是",[["A","肺炎"],["B","肺脓肿"],["C","支气管扩张症"],["D","肺结核"]],"B","患者有醉酒史，后出现发热、咳嗽、咳黏液脓性痰。胸部CT显示下叶背段（吸入性肺脓肿仰卧位好发部位）大片模糊阴影，密度不均匀，故该患者最可能的诊断是吸入性肺脓肿（B对）。吸入性肺脓肿多有手术、醉酒、劳累、受凉和脑血管病等病史，起病急，畏寒、高热，伴有咳嗽、咳黏液痰或黏液脓性痰，可伴胸痛，仰卧位时好发于上叶后段或下叶背段，CT影像表现为大片模糊阴影；肺炎（十版内科学P51）（A错）患者的临床表现为青壮年受凉后出现寒战、高热、咳嗽，咳铁锈色痰，X线表现为大片炎症浸润阴影或实变影；支气管扩张症（十版内科学P41）（C错）患者表现为病史长达数年至数十年，持续或反复的咳嗽、咳痰或咳脓痰和（或）咯血，CT纵切面为“双轨征”横切面示“环形阴影”；肺结核（十版内科学P73）（D错）患者多有全身中毒症状，如午后低热、盗汗、乏力、体重减轻等，X线胸片见病变多在肺尖或锁骨上下，密度不均，可形成空洞或肺内播散。","","N"],["2014-N142",4,"第二节细菌性肺炎","肺炎链球菌肺炎诊断",2014,142,"B","","男性，38岁。受凉后出现发热、咳嗽、痰少3天，查体：口周疱疹，右下肺叩浊，可闻及支气管呼吸音，最可能的诊断是",[["A","肺炎"],["B","肺脓肿"],["C","支气管扩张症"],["D","肺结核"]],"A","患者为青壮年男性，受凉后发热、咳嗽、痰少、口唇疱疹、肺部叩诊浊音及闻及支气管呼吸音，典型的肺炎链球菌肺炎的症状，故本例最可能的诊断是肺炎球菌肺炎（A对）。肺脓肿（十版内科学P68）（B错）急性起病，表现为高热、咳嗽、咳大量脓臭痰；支气管扩张症（十版内科学P41）（C错）患者病史长达数年至数十年，表现为持续或反复的咳嗽、咳痰或咳脓痰和（或）咯血；肺结核（十版内科学P73）（D错）患者起病缓慢，病情迁延，多有全身中毒症状，如午后低热、盗汗、乏力、体重减轻等。","","N"],["2014-N143",27,"第二节 慢性胃炎","慢性胃炎Hp检测",2014,143,"B","","侵入性检查幽门螺杆菌的首选方法是",[["A","血清学检查"],["B","¹³C尿素呼气试验"],["C","快速尿素酶试验"],["D","胃组织学检查"]],"C","侵入性检查方法（十版内科学P361）是指必须通过胃镜取胃黏膜活组织进行检测，包括快速尿素酶试验、胃粘膜组织切片染色镜检及细菌培养等。其中快速尿素酶试验（C对）是侵入性检查幽门螺杆菌（Hp）的首选方法，操作简便、费用低廉。虽然胃组织学检查（D错）是Hp检测的“金标准”之一，但由于操作繁琐，一般不作为首选。¹³C或¹⁴C尿素呼气试验（B错）、粪便幽门螺杆菌抗原检测及血清学检查（A错）均为非侵入性检查方法。其中¹³C尿素呼气试验检测幽门螺杆菌敏感性及特异性高而无需胃镜检查，患者依从性好，准确性较高，为Hp检测的“金标准”之一，临床上常作为Hp根除治疗后复查的首选方法。血清学检查仅提示近期是否感染过幽门螺杆菌。","","N"],["2014-N144",27,"第二节 慢性胃炎","慢性胃炎Hp检测",2014,144,"B","","当幽门螺杆菌根除治疗后复查疗效时，首选的检查方法是",[["A","血清学检查"],["B","¹³C尿素呼气试验"],["C","快速尿素酶试验"],["D","胃组织学检查"]],"B","非侵入性检查（十版内科学P361）不需要胃镜就能进行，包括¹³C或¹⁴C尿素呼气试验、粪便幽门螺杆菌抗原检测及血清学检查等。其中¹³C或¹⁴C尿素呼气试验（B对）检测幽门螺杆菌敏感性及特异性高而无需胃镜检查，患者依从性好，准确性较高，可作为根除治疗后复查的首选方法；血清学检查（A错）虽也不需要胃镜就能进行，但仅提示近期是否感染过幽门螺杆菌，故不能作为根除治疗后复查的首选方法。快速尿素酶试验（C错）、胃组织学检查（D错）及幽门螺杆菌培养等为侵入性检查方法。侵入性检查方法（十版内科学P361）是指必须通过胃镜取胃黏膜活组织进行检测，为有创检查，故不作为根除治疗后复查的首选方法。其中快速尿素酶试验操作简便、费用低，是侵入性检查幽门螺杆菌（Hp）的首选方法；胃组织学检查可直接观察幽门螺杆菌，与快速尿素酶试验结合，可提高诊断准确率，但因操作繁琐，不作为侵入性检查的首选方法。","","N"],["2014-N169",17,"第四节 急性冠状综合征","右心室心肌梗死的处理",2014,169,"X","","男性，50岁。4小时来急性胸痛，心电图诊断为“急性下壁、右心室心肌梗死”。患者胸痛持续不缓解，查体：BP85/60mmHg，颈静脉充盈，下肢水肿（+）。下列治疗措施中，正确的有",[["A","适当利尿消除水肿"],["B","积极补液适当应用多巴胺升血压"],["C","即刻进行PCI术血运重建"],["D","静点硝酸甘油缓解心绞痛"]],"BC","患者系右心室梗死，在无左心衰竭表现时，宜扩张血容量。在血流动力学检测下静脉滴注输液，直到低血压得到纠正或PCWP达15～18mmHg。如输液1～2L低血压仍未能纠正者可用正性肌力药，如多巴酚丁胺及多巴胺（B对）以升高血压。患者心梗4小时，未超过12小时，应即刻进行PCI术以重建血运（C对），尽可能挽救心肌组织。患者出现休克血压（收缩压＜90mmHg），提示血容量不足，此时不宜利尿（A错）。静点硝酸甘油（D错）可降低心脏前负荷，减少心输出量，进一步加重休克。","","N"],["2014-N170",6,"第一节 肺结核","治疗方案",2014,170,"X","","耐多药结核病的治疗原则包括",[["A","三联抗结核治疗"],["B","有广泛病变的应延长治疗至24个月"],["C","通常含强化期和继续期2个阶段"],["D","痰涂片和培养阴转后至少治疗12个月"]],"BC","三联抗结核治疗（A错）多用于首次感染结核的患者，并不是耐多药结核病的治疗原则。目前，临床上对于耐多药结核病的治疗多采用4种敏感药物联合使用的方案，并且治疗通常含有强化期和继续期2个阶段（C对）。经过治疗后，痰涂片和培养阴转后仍需至少治疗18个月，而非12个月（D错），有广泛病变的应延长至24个月（B对）。","","N"],["2014-N171",36,"第一节 原发性肝癌","原发性肝癌实验室和其他辅助检查",2014,171,"X","","对原发性肝癌高危人群进行普查的主要方法有",[["A","血清AFP测定"],["B","腹部CT检查"],["C","腹部B超检查"],["D","肝MRI检查"]],"AC","AFP现已广泛应用于原发性肝癌的普查（A对）、诊断、判断治疗效果及预测复发。在排除生殖腺胚胎瘤、少数转移性肿瘤以及妊娠、活动性肝炎、肝硬化炎症活动期的基础上，血清AFP检查诊断肝细胞癌的标准为：1.大于400ng/ml持续4周或AFP在200ng/ml以上的中等水平持续8周以上；2.AFP由低浓度逐渐升高不降。实时B型超声显像是目前肝癌筛查的首选检查方法（C对），它具有简便易行、价格低廉、准确及无创伤等优点，能确定肝内有无占位性病变。CT（B错）、MRI（D错）虽敏感性较B超高，能更客观地显示肝癌，1cm左右肝癌的检出率可＞80%，是诊断及确定治疗策略的重要手段，但由于价格昂贵，不能用于普查工作。","","N"],["2014-N172",41,"第一节 尿路感染","慢性肾盂肾炎的诊断",2014,172,"X","","下列支持慢性肾盂肾炎诊断的有",[["A","可无急性肾盂肾炎病史"],["B","肾外形凹凸不平，双肾大小不等"],["C","持续性肾小管功能损害"],["D","静脉肾盂造影常见肾盂肾盏正常"]],"ABC","慢性肾盂肾炎的诊断除反复发作尿路感染病史之外（超过半年），尚需结合影像学及肾脏功能检测：①肾外形凹凸不平，且双肾大小不等（B对）；②静脉肾盂造影可见肾盂、肾盏变形，缩窄（D错）；③持续性肾小管功能损害（C对）。具备上述第①、②条的任何一项再加第③条可诊断慢性肾盂肾炎。部分慢性肾盂肾炎患者可无急性肾盂肾炎病史（A对）。","","N"],["2014-N173",53,"第一节 霍奇金淋巴瘤","霍奇金淋巴瘤临床分期",2014,173,"X","","下列支持淋巴瘤分期为B组的临床表现有",[["A","盗汗"],["B","3个月内体重减轻≥10%"],["C","瘙痒"],["D","发热38℃以上连续三天"]],"AD","霍奇金淋巴瘤按全身症状可分两组，凡无以下症状者为A组，有以下症状之一者为B组：1.不明原因发热大于38℃（D对）。2.盗汗（A对）。3.半年内体重下降10%以上（B错）。","","N"],["2014-N174",61,"第一节 糖尿病","糖化血红蛋白和糖化白蛋白测定",2014,174,"X","","关于糖尿病的检查，下列提法正确的有",[["A","全血血糖高于血浆血糖"],["B","GHbA1c主要反映近2～3个月血糖总水平"],["C","胰岛素和C肽测定有助于糖尿病诊断"],["D","注射胰岛素的患者可通过测定C肽水平反映胰岛功能状况"]],"BD","全血化验指的是直接抽取血液进行化验，血浆是指去除血细胞后的液体进行化验，相当于浓缩了血糖，所以全血血糖低于血浆血糖（A错）。GHbA1（糖化血红蛋白）测定是利用红细胞血红蛋白Ｎ端的缬氨酸与葡萄糖结合形成GHbA1的原理，由于红细胞在血循环中的寿命约为120天，因此反映患者近8～12周（B对）平均血糖水平。胰岛B细胞分泌胰岛素原，胰岛素原分裂成C肽与胰岛素，故C肽水平能反映胰岛B细胞功能，且C肽测定不受血清中的胰岛素抗体和外源性胰岛素影响，因此注射胰岛素的患者可通过测定C肽水平反映胰岛功能状况（D对）。诊断糖尿病的依据是血糖值，胰岛素和C肽测定主要反映基础和葡萄糖介导的胰岛素释放功能，对糖尿病的诊断价值意义不大（C错）。","","N"],["2015-N57",19,"第二节 扩张型心肌病","扩张型心肌病超声心动图",2015,57,"A","","下列超声心动图结果描述中，不支持扩张性心肌病诊断的是",[["A","左心房扩大"],["B","左心室可见节段性运动减弱"],["C","左心室舒张末内径增大"],["D","左心室后壁厚度变薄"]],"B","扩张型心肌病（DCM）是一类以左心室或双心室扩大伴收缩功能障碍为特征的心肌病，后期各心腔均扩大（A对）。从解剖上看，扩张型心肌病心脏改变以心腔增大，心室壁变薄为主（D对）（此为内科学的观点，但九版病理学认为扩张性心肌病心室壁略厚或正常）。心腔扩大，舒张期能容纳的血液增加，表现为左心室舒张末内径增大（C对）。扩张型心肌病室壁运动普遍减弱，而不是左心室节段性运动减弱（B错，为本题正确答案），左心室节段性运动减弱见于缺血性心脏病。","","N"],["2015-N58",2,"","",2015,58,"A","","下列疾病中，可出现抑制性呼吸现象的病因是",[["A","急性胸膜炎"],["B","糖尿病酮症"],["C","充血性心力衰竭"],["D","支气管哮喘"]],"A","抑制性呼吸是指胸部发生剧烈疼痛所致的吸气相突然中断，呼吸运动短暂地突然受到抑制的一种呼吸，常见于急性胸膜炎（A对）、胸膜恶性肿瘤、肋骨骨折及胸部外伤等。糖尿病酮症（B错）、充血性心力衰竭（C错）及支气管哮喘（D错）均不会出现因胸部发生剧烈疼痛导致吸气相突然中断，因此三者均不属于抑制性呼吸。糖尿病酮症常表现为深大呼吸（Kussmaul呼吸）。充血性心力衰竭常表现为潮式呼吸（Cheyne-Stokes呼吸）。支气管哮喘（十版内科学P32）常表现为伴有哮鸣音的呼气性呼吸困难。","","N"],["2015-N59",17,"第四节 急性冠状综合征","不稳定型心绞痛和非ST段抬高型心肌梗死冠脉造影和其他侵入性检查",2015,59,"A","","男性，56岁，近1个月来反复出现发作性胸部压抑感，自咽喉部放射，持续10分钟左右自行缓解，既往高血压、糖尿病病史，吸烟35年。为明确诊断，不宜进行的检查是",[["A","24小时动态心电图"],["B","冠状动脉CT"],["C","冠状动脉造影"],["D","心电图活动平板负荷试验"]],"D","患者中老年男性，1月来反复发作性胸痛，自咽喉部放射，持续10分钟左右自行缓解，既往高血压、糖尿病病史，考虑诊断为初发型心绞痛，属于不稳定型心绞痛患者，禁作心电图负荷试验（D错，为本题正确答案）。24小时动态心电图（A对）可以连续监测患者不同时间心电图变化情况，可反映心绞痛发作时的ST段改变。冠状动脉CT（B对）为无创性检查方法，可用于判断冠脉狭窄程度以及管壁是否存在钙化及钙化程度。冠状动脉造影（C对）可以判断冠状动脉的管腔狭窄程度，是诊断冠心病较准确的检查方法。","","N"],["2015-N60",16,"第三节 房性心律失常","转复并维持窦性心律",2015,60,"A","","男性，47岁，因健康查体发现心房颤动而入院，平日无心悸感，既往体健，无高血压、糖尿病、甲亢病史。超声心动图检查心脏结构正常，化验血脂正常，对该患者的最佳处理方案是",[["A","临床观察"],["B","口服β受体拮抗剂"],["C","射频消融术"],["D","口服阿司匹林"]],"C","射频消融术已作为年龄小于75岁、无明显器质性心肌病、左房直径小于50mm的阵发房颤的一线治疗手段（三版八年制内科学P425）。本例患者中青年男性，查体发现房颤，平日无心悸感，既往体健，无高血压、糖尿病、甲亢病史，超声心动图检查心脏结构正常，化验血脂正常。根据患者为无心脏病变的中青年，可以诊断为孤立性房颤（九版内科学P188），应首选射频消融术（C对A错）早期根除房颤，防治血栓形成以及对心脏功能的损害。β受体拮抗剂主要用于特发性房颤或心功能正常的房颤患者控制心室率（B错）。阿司匹林属于抗血小板药物，不能显著减少房颤的血栓栓塞事件，一般不用于房颤治疗（D错）。","","N"],["2015-N61",15,"第二节 慢性心力衰竭","慢性心力衰竭诊断",2015,61,"A","","男性，53岁，1个月来活动后气短、心悸，自觉体力明显下降。偶有夜间憋醒，坐起休息后可缓解有高血压病史1年，最高血压达150/90mmHg，吸烟25年，查体：P88次/分，BP130/80mmHg，平卧位，颈静脉充盈，双肺间可闻及湿啰音，心界向两侧扩大，心率108次/分，心律不整，心音强弱不等，心尖部可闻及2/6级收缩期吹风样杂音，肝肋下可及，下肢水肿（±），首先可排除的疾病是",[["A","风湿性心瓣膜病"],["B","扩张型心肌病"],["C","冠心病"],["D","心包积液"]],"A","患者中年男性，活动后气短、心悸，体力下降1月。偶有夜间阵发性呼吸困难，双肺间可闻及湿啰音。考虑为左心衰竭症状。有高血压病史1年，最高血压150/90mmHg，可诊断为高血压1级。吸烟25年，为冠心病危险因素。颈静脉充盈，肝肋下可及、下肢水肿（±），考虑右心衰表现。患者目前全心衰诊断明确，需考虑冠心病（C错）导致的全心衰。查体：P88次/分，心率108次/分，心律不整，心音强弱不等，考虑为房颤。心界向两侧扩大，为全心扩大表现，需考虑扩张型心肌病可能（B错）。心尖部可闻及2/6级收缩期吹风样杂音属于心脏功能性改变，且患者伴有全心扩大表现，可考虑为全心扩大引起的二尖瓣相对性关闭不全。患者心包积液时，由于上、下腔静脉回流均受阻，可以引起颈静脉充盈、肝肋下可及，故需考虑心包积液的可能（D错）。风湿性心瓣膜病以二尖瓣狭窄伴二尖瓣关闭不全与单纯二尖瓣狭窄多见，二尖瓣狭窄主要表现为心尖区舒张中晚期低调的隆隆样杂音，杂音强度3/6级以上，该患者杂音仅2/6级，因此可首先排除风湿性心瓣膜病（A对）。","","N"],["2015-N62",18,"第一节 原发性高血压","原发性高血压流行病学",2015,62,"A","","我国高血压人群个体特点是",[["A","盐敏感"],["B","高血糖"],["C","高血脂"],["D","高肾素"]],"A","高血压的发病主要与遗传、饮食、精神应激、吸烟、体重及药物等有关。我国不同地区的人群高血压患病率与当地钠盐平均摄入量存在显著正相关，并且在我国高血压人群中，盐敏感（A对）者大约占25%～42%。高血糖（B错）、高血脂（C错）是我国高血压患者的心血管高危因素，而高肾素（D错）是我国高血压患者的发病机制之一。","","N"],["2015-N63",11,"第一节 胸腔积液","恶性胸腔积液",2015,63,"A","","女性，45岁，呼吸困难、胸痛1个月。胸部B超发现右侧中等量胸腔积液。化验：血性胸水，比重1.020，蛋白定量35g/L，WBC680×10⁶/L，ADA25U/L，最可能的诊断是",[["A","结核性胸腔积液"],["B","癌性胸腔积液"],["C","肺栓塞所致胸腔积液"],["D","肺炎伴胸腔积液"]],"B","女性患者，45岁（癌性胸腔积液常见于45岁以上中老年人），呼吸困难、胸痛（胸腔积液常见临床表现），胸水检查呈血性胸水（癌性胸腔积液典型胸水特征），比重1.020、蛋白定量35g/L、WBC 680×10⁶/L（符合渗出液特征：比重＞1.018，白细胞数＞500×10⁶/L，总蛋白＞30g/L），ADA25U/L（癌性胸腔积液ADA＜45U/L，结核性胸腔积液ADA（十版内科学P129）＞45U/L），所以该患者最可能的诊断为肿瘤性胸腔积液（B对）。结核性胸腔积液（A错）可呈血性，但ADA＞45U/L，且有全身结核中毒症状；肺栓塞所致胸腔积液（C错）虽可以产生血性胸水，但一般少见，且临床症状为突发胸痛、呼吸困难；肺炎伴胸腔积液（D错）所致胸水一般为草黄色或脓性，多有发热、咳嗽、咳痰等表现。","","N"],["2015-N64",2,"第一节 支气管哮喘","药物分类和作用特点",2015,64,"A","","治疗支气管哮喘的缓解药物不包括",[["A","速效吸入的β₂受体激动剂"],["B","短效茶碱"],["C","白三烯调节剂"],["D","全身用糖皮质激素"]],"C","哮喘治疗药物分为控制性药物和缓解性药物。控制性药物指需要长期使用的药物，主要用于治疗气道慢性炎症，使哮喘维持临床控制，亦称抗炎药；缓解性药物指按需使用的药物，主要通过迅速解除支气管痉挛缓解哮喘症状，亦称支气管扩张药。速效吸入的β₂受体激动剂（A对）、短效茶碱（B对）、全身用糖皮质激素（D对）为缓解性药物。白三烯调节剂为控制性药物，通过调节白三烯的生物活性而发挥抗炎作用，同时可以舒张支气管平滑肌，不用于缓解药（C错，为本题正确答案）。","","N"],["2015-N65",4,"第二节细菌性肺炎","肺炎链球菌肺炎发病机制",2015,65,"A","","在整个病理过程中没有肺泡壁和其他结构破坏的肺炎是",[["A","肺炎链球菌肺炎"],["B","肺炎克雷伯杆菌肺炎"],["C","铜绿假单胞菌肺炎"],["D","金黄色葡萄球菌肺炎"]],"A","肺炎链球菌不产生毒素，肺炎链球菌肺炎不引起组织坏死或形成空洞，在整个病理过程中没有肺泡壁和其他结构破坏（A对）。肺炎链球菌致病力是由于高分子多糖体的荚膜对组织的侵袭作用，首先引起肺泡壁水肿，出现白细胞与红细胞渗出，之后向肺的中央部分扩展，甚至累及几个肺段或整个肺叶。金黄色葡萄球菌、铜绿假单胞菌、肺炎克雷伯杆菌引起的肺炎均可引起肺组织的坏死性病变易形成空洞，破坏肺的结构（BCD错）。","","N"],["2015-N66",38,"第一节 消化道出血","出血程度的评估和周围循环状态的判断",2015,66,"A","","上消化道出血患者粪隐血试验阳性，最少出血量是",[["A","5ml"],["B","20ml"],["C","50ml"],["D","100ml"]],"A","关于上消化道出血严重程度的估计和周围循环状态的判断，据研究成人每日消化道出血＞5～10ml，粪便隐血试验出现阳性（A对）。每日出血量50～100ml，可出现黑粪。胃内储积血量在250～300ml可引起呕血。一次出血量不超过400ml时，因轻度血容量减少可由组织液及脾脏贮血所补充，一般不引起全身症状。出血量超过400～500ml，可出现全身症状，如头昏、心慌、乏力等。短时间内出血量超过1000ml，可出现周围循环衰竭休克表现。","","N"],["2015-N67",37,"第一节 急性胰腺炎","急性胰腺炎发病机制",2015,67,"A","","在急性胰腺炎发病过程中起关键作用的酶是",[["A","淀粉酶"],["B","弹力纤维酶"],["C","胰蛋白酶"],["D","激肽酶"]],"C","急性胰腺炎是多种病因导致胰蛋白酶在胰腺内被激活后引起胰腺组织自身消化、水肿、出血甚至坏死的炎症反应。首先激活胰蛋白酶原，形成胰蛋白酶，在胰蛋白酶作用下使各种胰消化酶原激活为有生物活性的消化酶。一旦各种消化酶原激活后，其中起主要作用的活化酶有磷脂酶A₂、激肽释放酶或胰舒血管素、弹性蛋白酶和脂肪酶，上述消化酶共同作用，造成胰腺实质及邻近组织的病变。因此胰蛋白酶是胰腺损害最关键的酶类（C对BD错）。胰淀粉酶（A错）是由胰腺以活性状态排入消化道，主要水解碳水化合物，并不能引起严重自体消化。","","N"],["2015-N68",75,"第二节 农药中毒","重度中毒",2015,68,"A","","女性，20岁，误服有机磷农药半小时家人送来急诊。查体：神志不清，皮肤潮湿多汗，面部肌肉束颤动，瞳孔缩小，双肺布满湿啰音。该患者最可能的中毒程度是",[["A","轻度"],["B","中度"],["C","重度"],["D","不能确定"]],"C","急性有机磷的轻度中毒仅有M样症状。中度中毒症状表现为M样症状加重，并出现N样症状。重度中毒具有M、N样症状，并伴有肺水肿、抽搐、昏迷，呼吸肌麻痹和脑水肿。患者有机磷农药中毒半小时，皮肤潮湿多汗，瞳孔缩小（M样症状），面部肌肉束颤动（N样症状），双肺布满湿啰音（提示肺水肿）。患者具有明显的M样症状、N样症状，并伴有肺水肿，符合重度中毒的诊断标准，因此该患者最可能的中毒程度是重度中毒（C对）。","","N"],["2015-N69",41,"第一节 尿路感染","无症状细菌尿",2015,69,"A","","下列患无症状细菌尿的病人中，不需要治疗的是",[["A","学龄前儿童"],["B","老年人"],["C","妊娠妇女"],["D","肾移植后"]],"B","无症状性菌尿又称隐匿型菌尿，是一种隐匿型尿路感染，即指病人有真性细菌尿而无任何尿路感染的症状，常见于老年女性、妊娠妇女、女童。无症状细菌尿是否治疗目前存在争议，我国指南认为绝经前和非妊娠期女性、老年人（B对）、糖尿病、脊髓损伤和留置导尿管的病人、儿童（A对）无症状细菌尿无需主动筛查和治疗。有下述情况者建议常规筛查和治疗：①妊娠期女性（C错）；②即将接受可能损伤黏膜的泌尿系统外科手术病人（D错）。本题官方给出的参考答案为B，但根据10版教材，可选择AB。","","N"],["2015-N70",40,"第四节 IgA肾病","IgA肾病诊断",2015,70,"A","","男性，30岁，上呼吸道感染后3天出现颜面水肿。测血压145/95mmHg。化验尿蛋白（++），沉渣镜检RBC满视野/HP，偶见颗粒管型；化验Hb100g/L，血Cr250μmol/L。此时对诊断最有帮助的检查是",[["A","血清IgA测定"],["B","血清补体测定"],["C","肾活检病理检查"],["D","肾脏B超检查"]],"C","30岁青年男性，于上呼吸道感染后3天（前驱感染时间短）出现颜面水肿、尿蛋白（++）、沉渣镜检RBC满视野/HP，偶见颗粒管型（提示血尿）、血压145/95mmHg（肾炎综合征表现），血Cr250μmol/L（正常值约44～132μmol/L，提示肾功能减退），诊断考虑IgA肾病。因为IgA肾病以 20～30 岁男性为多见，临床表现多样，可表现为无症状性血尿、蛋白尿，急进性肾炎综合症，肾炎综合征和肾病综合症。为明确诊断最有价值的检查为肾活检病理检查（C对）。IgA肾病血清补体水平多数正常，血清补体测定（B错）对诊断意义不大。血清IgA测定（A错）可用于辅助诊断IgA肾病，但只有30%-50%的病人伴有血IgA增高。肾脏B超检查（D错）仅能反映肾脏形态变化，但并不能明确病理改变类型。","","N"],["2015-N71",52,"第二节 急性白血病","急性白血病诊断",2015,71,"A","","下列急性白血病患者的白血病细胞镜检时，无Auer小体的类型是",[["A","急性淋巴细胞白血病"],["B","急性粒细胞白血病部分分化型"],["C","急性早幼粒细胞白血病"],["D","急性单核细胞白血病"]],"A","Auer小体（棒状小体）为白细胞胞质中出现的1条或数条染红色细杆状物质，长1～6mm，常出现在急性粒细胞白血病和急性单核细胞白血病（M₅）（D错）中，急性粒细胞白血病部分分化型（M₂）（B错）、急性早幼粒细胞白血病（M₃）（C错）均为急性粒细胞白血病。在骨髓增生异常综合征（MDS）的RAEB-t型也可检出Auer小体。急性淋巴细胞白血病无Auer小体（A对）。","","N"],["2015-N72",50,"第一节 溶血性贫血概述","溶血性贫血诊断",2015,72,"A","","女性，23岁。头晕、乏力、低热、腰痛、恶心5天来诊，有肝炎病史1年。查体：T37.5℃，浅表淋巴结不大，巩膜轻度黄染，脾肋下3cm。化验尿色深，镜下未见红细胞，尿胆原（+），尿胆红素（-），血TBil44.2μmol/L，DBil5.2μmol/L。最可能的诊断是",[["A","慢性肝炎急性发作"],["B","胆囊炎"],["C","急性胰腺炎"],["D","溶血性贫血"]],"D","该患者为青年女性，有头晕、乏力、低热、腰痛、恶心、轻度黄疸，脾肿大等溶血性贫血的症状，尿胆原（+），尿胆红素（-）（血管外溶血尿胆原增多，而胆红素阴性），血TBil（总胆红素）增高（TBil正常值3.4～17.1μmol/L），血DBil（结合胆红素）正常（DBil正常值0～6.8μmol/L），DBil/TBil=0.11（溶血性黄疸以血清游离胆红素增高为主，DBil/TBil＜0.15）。据此该患者最可能的诊断是溶血性贫血（D对）。慢性肝炎急性发作（A错）虽可有肝细胞性黄疸，但常表现为DBil中度升高，IBil（未结合胆红素）中度增高，DBil/TBil为0.2～0.5，尿胆红素常阳性，与本例不符。胆囊炎（九版外科学P443-P444）（B错）主要表现为右上腹持续性疼痛、阵发性加剧，可向右肩背放射，很少出现黄疸、脾肿大，与本例不符。急性胰腺炎（九版外科学P458）（C错）多表现为高热、剧烈上腹痛，并多向肩背部放射，与本例不符。","","N"],["2015-N73",61,"第一节 糖尿病","糖尿病性视网膜病变",2015,73,"A","","关于糖尿病视网膜病变，下列叙述不正确的是",[["A","当出现增殖性视网膜病变时常合并有糖尿病肾病"],["B","严格控制血糖有助于延缓视网膜病变的发生和发展"],["C","严格控制血压有助于延缓视网膜病变的发生和发展"],["D","当出现视网膜病变时，应尽早行激光治疗"]],"D","重度NPDR（非增殖期视网膜病变）时才应尽早接受视网膜激光光凝治疗，并非患者出现视网膜病变就尽早行激光治疗（D错，为本题正确答案）。PDR（增殖期视网膜病变）患者存在威胁视力时应尽早行玻璃体切割手术。糖尿病视网膜病变分为六期，Ⅳ～Ⅵ期为增殖期视网膜病变（PDR），当出现PDR时，常伴有糖尿病肾病及神经病变（A对）。严格控制血糖是防治糖尿病慢性并发症的基础，可延缓视网膜病变的发生发展（B对）。对于病程长的患者，仅严格控制血糖对预防和延缓T2DM患者慢性并发症发生发展的作用有限，应早期和积极全面控制危险因素，如严格控制血压，使其控制在130/80mmHg以下，有助于延缓视网膜病变的发生和发展（C对）。","","N"],["2015-N74",61,"第一节 糖尿病","促胰岛素分泌剂",2015,74,"A","","经肾脏排泄最少，可在轻中度肾功能不全情况下使用的磺脲类药物是",[["A","格列本脲"],["B","格列喹酮"],["C","格列吡嗪"],["D","格列美脲"]],"B","格列喹酮主要在肝脏代谢，95%代谢产物通过胆汁进入肠道由粪便排泄，经肾脏排泄量不足5%，因此可在轻中度肾功能不全情况下使用（B对）。磺酰脲类药物经肾脏排泄量为格列吡嗪（89%）（C错）＞格列齐特（80%）＞格列美脲（60%）（D错）＞格列本脲（50%）（A错）＞格列喹酮（5%）。","","N"],["2015-N75",67,"第一节 风湿系统疾病总论","风湿系统疾病临床表现",2015,75,"A","","在下列表现中，符合皮肌炎特异性临床表现的是",[["A","腮腺肿大"],["B","上眼睑红肿"],["C","口、眼干"],["D","雷诺现象"]],"B","皮肌炎是一种主要累及横纹肌，以淋巴细胞浸润为主的非化脓性炎症病变，可伴有或不伴有多种皮肤损害。眼部特异性临床表现为上睑暗紫红色皮疹，可为一侧或两侧，常伴眶周水肿和近睑缘处毛细血管扩张，故上眼睑红肿为其特异性临床表现（B对）。干燥综合征（SS）（十版内科学P827）是一个主要累及外分泌腺体的慢性炎症性自身免疫病，主要表现为唾液腺和泪腺受损。腮腺肿大（A错），口、眼干（C错）为原发性干燥综合征（pSS）的特异性临床表现。雷诺现象（十版内科学P849）（D错）是指因受寒冷或紧张的刺激后，肢端细动脉痉挛，使手指皮肤突然出现苍白，相继出现皮肤青紫而后潮红为特征的临床现象，为系统性硬化症（SSc）的特异性临床表现。","","N"],["2015-N76",68,"第一节 类风湿关节炎","类风湿关节炎诊断",2015,76,"A","","下列不属于类风湿关节炎诊断标准的是",[["A","晨僵"],["B","关节肿"],["C","关节畸形"],["D","类风湿结节"]],"C","美国风湿病学会1987年修订的RA（类风湿性关节炎）分类标准如下：①关节内或周围晨僵持续至少1小时（A错）；②至少同时有3个关节区软组织肿或积液；③腕、掌指、近端指间关节区中，至少1个关节区肿（B错）；④对称性关节炎；⑤有类风湿结节（D错）；⑥血清RF阳性（所用方法正常人群中不超过5%阳性）；⑦X线片改变（至少有骨质疏松和关节间隙狭窄）。符合以上4项者可以诊断RA。而关节畸形（C对）可见于类风湿关节炎、银屑病关节炎、强直性脊柱炎、创伤等，并无特异性，故不作为类风湿关节炎诊断标准。","","N"],["2015-N91",17,"第四节 急性冠状综合征","乳头肌功能失调或断裂",2015,91,"A","","男，72岁，因胸痛24h，诊断前壁心梗入院，常规接受药物治疗，入院后第4天，患者再次感心前区疼痛，持续约30min，查体心尖部内侧可闻及收缩中晚期高调短促附加音伴收缩晚期杂音，与呼吸运动无关，患者新出现的附加音最可能是",[["A","心包摩擦音"],["B","开瓣音"],["C","喀喇音"],["D","第四心音"]],"C","本例老年男性患者4天前出现急性前壁心肌梗死，经药物治疗后，再次出现心前区疼痛，心尖部内侧可闻及收缩中晚期高调、短促附加音伴收缩晚期杂音，考虑乳头肌功能不全。乳头肌功能失调或断裂是急性心梗最常见的并发症，心尖区出现收缩中晚期喀喇音（C对）和吹风样收缩期杂音，其机制：因二尖瓣乳头肌缺血、坏死等使收缩功能发生障碍，造成不同程度的二尖瓣脱垂并关闭不全。心包摩擦音（A错）在心前区或胸骨左缘第3～4肋间出现响亮的收缩期杂音，深吸气时杂音可出现增强，可见于心肌梗死后综合征。开瓣音（B错）见于二尖瓣狭窄而瓣膜尚柔软时，又称二尖瓣开放拍击声，听诊特点为音调高、历时短促而响亮、清脆，呈拍击样，在心尖内侧较清楚。第四心音出现在心室舒张末期、收缩期前（D错），一般认为其产生与心房收缩使房室瓣及其相关结构（瓣膜、瓣环、腱索和乳头肌）突然紧张、振动有关，听诊在心尖部及其内侧较明显，低调、沉浊而弱，为病理性。","c80","N"],["2015-N92",17,"第四节 急性冠状综合征","乳头肌功能失调或断裂",2015,92,"A","","男，72岁，因胸痛24h，诊断前壁心梗入院，常规接受药物治疗，入院后第4天，患者再次感心前区疼痛，持续约30min，查体心尖部内侧可闻及收缩中晚期高调短促附加音伴收缩晚期杂音，与呼吸运动无关，出现该附加音最可能的原因是",[["A","心力衰竭"],["B","渗出性心包炎"],["C","二尖瓣脱垂"],["D","心室壁瘤"]],"C","本例老年男性患者4天前出现急性前壁心肌梗死，经药物治疗后，再次出现心前区疼痛，心尖部内侧可闻及收缩中晚期高调、短促附加音伴收缩晚期杂音，考虑乳头肌功能不全。乳头肌功能失调或断裂是急性心梗最常见的并发症，因二尖瓣乳头肌缺血、坏死等使收缩功能发生障碍，造成不同程度的二尖瓣脱垂并关闭不全（C对），心尖区出现收缩中晚期喀喇音和吹风样收缩期杂音。第一心音可不减弱，可引起心力衰竭。急性心肌梗死可出现心力衰竭，但一般无特异性心脏杂音（A错）。渗出性心包炎（B错）可为心肌梗死后综合征，常见于急性心梗后数周至数月，与本例不符。心室壁瘤可见左侧心界扩大，心脏搏动范围较广，可有收缩期杂音，与本例不符（D错）。","c80","N"],["2015-N93",15,"第二节 慢性心力衰竭","洋地黄类药物",2015,93,"A","","女性，75岁，半年来稍活动心悸、气短，1个月来夜间不能平卧，双下肢水肿来院。5年前患前壁心梗，有高血压16年，糖尿病12年，查体：T37.3℃，P88次/分，BP135/60mmHg，半卧位，颈静脉怒张，双肺底可闻及湿啰音，心界向左下扩大，心率120次/分，心律不整，A₂=P₂，脉短绌，腹壁厚，肝触诊不满意，双下肢凹陷性水肿（++）。目前选用的治疗药物，不恰当的是",[["A","洋地黄"],["B","噻嗪类"],["C","β受体拮抗剂"],["D","硝酸酯类"]],"C","患者活动后心悸、气短，夜间不能平卧、双肺底湿啰音，心界向左下扩大（为左心衰的典型征象），患者颈静脉怒张、双下肢凹陷性水肿（为右心衰的典型征象）。并且，患者心率快（正常60～100次/分），心律不整，P88次/分，脉短绌（为房颤的典型征象）。故初步诊断患者为慢性全心衰竭伴快速型房颤。患者稍活动心悸、气短半年，夜间不能平卧1个月，根据NYHA心力衰竭分级，为Ⅳ级，属于重度心衰，不宜使用β受体拮抗剂（C错，为本题正确答案），须待患者情况好转后，在严密监护下方可使用。伴有快速心房颤动/扑动的收缩性心力衰竭是应用洋地黄（A对）的最佳指征，在增强心肌收缩力的同时降低心率，改善心功能。患者夜间不能平卧、双下肢水肿且颈静脉怒张，提示体液潴留，可使用噻嗪类利尿剂（B对）。患者有高血压16年，可使用硝酸酯类扩血管药物进行联合治疗，防止缺血事件的发生（D对）。","c81","N"],["2015-N94",15,"第二节 慢性心力衰竭","洋地黄类药物",2015,94,"A","","女性，75岁，半年来稍活动心悸、气短，1个月来夜间不能平卧，双下肢水肿来院。5年前患前壁心梗，有高血压16年，糖尿病12年，查体：T37.3℃，P88次/分，BP135/60mmHg，半卧位，颈静脉怒张，双肺底可闻及湿啰音，心界向左下扩大，心率120次/分，心律不整，A₂=P₂，脉短绌，腹壁厚，肝触诊不满意，双下肢凹陷性水肿（++）。针对患者心律不整应选用的药物是",[["A","地高辛"],["B","普罗帕酮"],["C","胺碘酮"],["D","维拉帕米"]],"A","患者活动后心悸、气短，夜间不能平卧、双肺底湿啰音，心界向左下扩大，提示左心衰竭。与此同时，患者颈静脉怒张、双下肢凹陷性水肿，提示右心衰竭。并且，患者心率增快（正常60～100次/分），心律不整，P88次/分，脉短绌，提示房颤。故初步诊断患者为慢性全心衰竭伴快速型房颤。房颤时控制心室率的药物包括β受体拮抗剂、钙通道阻滞剂或地高辛。伴有快速心房颤动/扑动的收缩性心力衰竭是应用洋地黄的最佳指征，且患者无房室传导阻滞等洋地黄禁忌证，故可使用洋地黄（A对）。普罗帕酮（B错）与胺碘酮（C错）均为房颤复律药物，但是患者目前心律失常已超过24小时，应在复律前进行3周抗凝治疗，不宜直接复律。维拉帕米（D错）为非二氢吡啶类钙通道阻滞剂，对心脏具有负性肌力、负性传导以及负性频率作用。房颤患者心功能正常时应用维拉帕米有助于复律，但心功能不全时应用可加重心衰。","c81","N"],["2015-N95",15,"第二节 慢性心力衰竭","利尿剂",2015,95,"A","","女性，75岁，半年来稍活动后心悸、气短，1个月来夜间不能平卧、双下肢水肿来院。5年前患前壁心梗，有高血压16年，糖尿病12年，查体：T37.3℃，P88次／分，BP135/60mmHg，半卧位，颈静脉怒张，双肺底可闻及湿啰音，心界向左下扩大，心率120次／分，心律不整，A2=P2，脉短绌，腹壁厚，肝触诊不满意，双下肢凹陷性水肿（++）。患者检验结果：血WBC12.4×10⁹/L，中性粒细胞82%，ALT42U/L，血Cr264μmol/L，TC4.21mmol/L，LDL-C2.96mmol/L，血K⁺4.98mmol/L，Na⁺138mmol/L，血糖6.5mmol/L。根据检验结果，该患者应调整的治疗药物中，不恰当的是",[["A","增加ACEI"],["B","改用袢利尿剂"],["C","加用抗生素"],["D","增加他汀类制剂"]],"A","患者活动后心悸、气短，夜间不能平卧、双肺底湿啰音，心界向左下扩大（为左心衰的典型征象），患者颈静脉怒张、双下肢凹陷性水肿（右心衰的典型征象）。并且，患者心率增快（正常60～100次/分），心律不整，P88次/分，脉短绌（房颤的典型表现）。故初步诊断患者为慢性全心衰竭伴快速型房颤。患者血Cr264μmol/L（正常值：女性41～81μmol/L），提示肾小球滤过功能减退，血管紧张素转换酶抑制剂ACEI（A错，为本题正确答案）可减少血管紧张素Ⅱ的合成，使肾灌注压降低，导致肾小球滤过率降低，故本例患者应慎用ACEI。患者夜间不能平卧、双下肢水肿且颈静脉怒张，提示体液潴留，可改用袢利尿剂（B对）。患者WBC升高（正常值3.5～9.5×10⁹/L），中性粒细胞比例升高（NEUT%，正常成人40%～75%），提示患者合并感染，应加用抗生素治疗（C对）。患者血清总胆固醇（TC）4.21mmol/L（升高标准：＞6.2mmol/L）、低密度脂蛋白胆固醇（LDL-C）2.96mmol/L（升高标准：＞4.1mmol/L），患者虽未达到血脂异常诊断标准，但根据心衰竭、心律失常、糖尿病病史，属于根据动脉粥样硬化性心血管疾病（ASCVD）危险程度分类极高危人群，要进行调脂干预，LDL-C 需要降至＜1.8mmol/L（十版内科学P757），首选药物为他汀类（D对）。","","N"],["2015-N96",8,"第三节 结节病","结节病诊断",2015,96,"A","","女性，45岁。干咳、活动后气短、乏力2个月。2年前曾发现双侧肺门淋巴结肿大，因无症状未予诊治。查体：双下肢可见散在分布的红色丘疹，双下肺可闻及少许湿啰音。胸部CT提示双肺弥漫性网状、小结节状阴影，双下肺呈蜂窝肺改变，肺门纵隔淋巴结无肿大。患者最可能的诊断是",[["A","肺结核"],["B","特发性肺纤维化"],["C","结节病"],["D","结缔组织病相关肺间质病"]],"C","患者出现干咳、气短、乏力等表现，既往双侧肺门淋巴结肿大病史，因无症状未予诊治（处于结节病Ⅰ期）。查体可见双下肢散在红色丘疹（结节病典型皮肤表现），双下肺可闻及少许湿啰音，胸部CT提示双肺弥漫性网状、小结节状阴影，双下肺呈蜂窝肺改变（结节病典型影像学表现，且可判断处于结节病Ⅳ期），该患者最可能的诊断是结节病（C对）。肺结核（十版内科学P73）（A错）主要表现为低热、盗汗、消瘦等全身结核中毒症状，影像学表现呈多态性，即浸润、增殖、干酪、纤维钙化病变可同时存在，密度不均匀、边缘较清楚和病变变化较慢，易形成空洞和播散病灶，CT不会出现蜂窝肺的表现；特发性肺纤维化（十版内科学P102）（B错）和结缔组织病相关肺间质病（D错）主要表现为呼吸困难并常伴干咳，虽然CT也可有弥漫性网状、小结节状阴影、蜂窝状改变，但不会出现双下肢红色丘疹等皮肤表现，且结缔组织病相关肺间质病较少见。","c82","N"],["2015-N97",8,"第三节 结节病","纤维支气管镜与支气管肺泡灌洗",2015,97,"A","","女性，45岁。干咳、活动后气短、乏力2个月。2年前曾发现双侧肺门淋巴结肿大，因无症状未予诊治。查体：双下肢可见散在分布的红色丘疹，双下肺可闻及少许湿啰音。胸部CT提示双肺弥漫性网状、小结节状阴影，双下肺呈蜂窝肺改变，肺门纵隔淋巴结无肿大。对明确诊断意义最大的检查是",[["A","肺功能检查"],["B","结核菌素试验"],["C","自身抗体检查"],["D","支气管镜检查"]],"D","患者出现干咳、气短、乏力等表现，既往双侧肺门淋巴结肿大病史，因无症状未予诊治（处于结节病Ⅰ期），查体可见双下肢散在红色丘疹（结节病典型皮肤表现），双下肺可闻及少许湿啰音，胸部CT提示双肺弥漫性网状、小结节状阴影，双下肺呈蜂窝肺改变（结节病典型影像学表现，且可判断处于结节病Ⅳ期），该患者最可能的诊断是结节病。为明确诊断，应首选支气管镜检查（D对），因其可以取活检，进行病理学检查，是诊断的金标准。肺功能检查（A错）虽然可以检测出限制性通气功能障碍伴弥散功能下降，但无特异性；结核菌素试验（B错）主要用于结核的诊断；自身抗体检查（C错）主要用于自身免疫性疾病的诊断。","c82","N"],["2015-N98",8,"第三节 结节病","结节病治疗",2015,98,"A","","女性，45岁。干咳、活动后气短、乏力2个月。2年前曾发现双侧肺门淋巴结肿大，因无症状未予诊治。查体：双下肢可见散在分布的红色丘疹，双下肺可闻及少许湿啰音。胸部CT提示双肺弥漫性网状、小结节状阴影，双下肺呈蜂窝肺改变，肺门纵隔淋巴结无肿大。药物治疗总疗程一般不少于",[["A","1个月"],["B","2个月"],["C","3个月"],["D","6个月"]],"D","患者出现干咳、气短、乏力等表现，既往双侧肺门淋巴结肿大病史，因无症状未予诊治（处于结节病Ⅰ期），查体可见双下肢散在红色丘疹（结节病典型皮肤表现），双下肺可闻及少许湿啰音，胸部CT提示双肺弥漫性网状、小结节状阴影，双下肺呈蜂窝肺改变（结节病典型影像学表现，且可判断处于结节病Ⅳ期），该患者最可能的诊断是结节病。该期患者处于结节病Ⅳ期，出现明显的肺内肺外症状，需要使用全身糖皮质激素治疗，常用泼尼松连续4周，病情好转减量至维持量，药物治疗总疗程一般为6～24个月（D对）。","c82","N"],["2015-N99",35,"","",2015,99,"A","","男性，56岁。2年来消瘦、乏力，近5天来发热、嗜睡，1天来意识障碍急诊入院，既往患乙型肝炎多年，吸烟史20年。查体：T37.5℃，P86次/分，R20次/分，BP120/80mmHg，神志不清，巩膜轻度黄染，颈软，心肺检查未见异常，腹平软，肝肋下未及，脾肋下4cm，移动性浊音阳性。尿常规无异常，化验血Hb110g/L，WBC3.4×10⁹/L，Plt92×10⁹/L。该患者最可能的诊断是",[["A","肺性脑病"],["B","肝性脑病"],["C","尿毒症昏迷"],["D","脑血管意外"]],"B","中年男性患者，既往乙肝病史（乙肝为肝硬化最常见的病因），有营养不良表现，现出现发热（肝硬化患者容易发生感染）。查体：巩膜轻度黄染（肝硬化肝功能减退可有营养不良和黄疸表现），脾肿大（肝硬化门脉高压可有脾肿大），移动性浊音阳性（腹水是肝硬化失代偿期最突出的临床表现）。化验血：Hb、WBC、Plt均降低（肝硬化门脉高压引起脾功能亢进时可有全血细胞减少）。据此该患者可诊断为肝硬化失代偿期，又因该患者嗜睡、意识障碍，故该患者最可能的诊断是肝硬化失代偿期合并肝性脑病（B对）。肺性脑病（A错）多见于由慢阻肺引起的呼吸衰竭，应有呼吸系统相关病史，肺部听诊可闻及干湿啰音，一般无脾大及移动性浊音，球结膜可有水肿，巩膜无黄染，血液系统检查无异常或血红蛋白有所升高，动脉血气分析可有氧分压降低或二氧化碳分压升高，与本例不符。尿毒症昏迷（C错）一般会有慢性肾病史，血肌酐和尿素氮会升高，一般为低比重或等比重尿，尿常规会有异常，而无脾大和巩膜黄染，与本例不符。脑血管意外（D错）者多为突然发生，神经系统查体会有阳性体征，如颈抵抗、病理征阳性，不会出现脾大和巩膜黄染，与本例不符。","c83","N"],["2015-N100",35,"","",2015,100,"A","","男性，56岁。2年来消瘦、乏力，近5天来发热、嗜睡，1天来意识障碍急诊入院，既往患乙型肝炎多年，吸烟史20年。查体：T37.5℃，P86次/分，R20次/分，BP120/80mmHg，神志不清，巩膜轻度黄染，颈软，心肺检查未见异常，腹平软，肝肋下未及，脾肋下4cm，移动性浊音阳性。尿常规无异常，化验血Hb110g/L，WBC3.4×10⁹/L，Plt92×10⁹/L。为明确诊断，首选的检查是",[["A","肝肾功能"],["B","血气分析"],["C","头颅CT"],["D","血氨"]],"D","氨代谢紊乱是肝性脑病的主要发病机制，肝性脑病患者多血氨升高，因此为明确诊断，首选的检查是血氨检测（D对）。肝硬化失代偿期合并肝肾综合征时，可有肾功能减退，肾功能检查（A错）有助于诊断肝肾综合征，对于肝性脑病的诊断无意义。肝硬化失代偿期合并肝肺综合征时，可有血气异常，血气分析（B错）有助于诊断肝肺综合征，对于肝性脑病的诊断无意义。肝性脑病虽有神经系统症状，但为氨中毒及神经递质等变化引起，脑部常无明显的解剖异常，头颅CT（C错）为脑血管疾病及颅内肿瘤的重要检查手段，对于肝性脑病的确诊意义不大。","c83","N"],["2015-N101",35,"第一节 肝硬化","肝性脑病",2015,101,"A","","男性，56岁。2年来消瘦、乏力，近5天来发热、嗜睡，1天来意识障碍急诊入院，既往患乙型肝炎多年，吸烟史20年。查体：T37.5℃，P86次/分，R20次/分，BP120/80mmHg，神志不清，巩膜轻度黄染，颈软，心肺检查未见异常，腹平软，肝肋下未及，脾肋下4cm，移动性浊音阳性。尿常规无异常，化验血Hb110g/L，WBC3.4×10⁹/L，Plt92×10⁹/L。针对该患者的发病机制，应选择的治疗措施是",[["A","降血氨药物如谷氨酸钾"],["B","纠正水、电解质紊乱"],["C","机械通气"],["D","降颅压治疗"]],"A","目前治疗肝性脑病（HE）的主要措施是去除HE发作的诱因、保护肝脏功能免受进一步损伤、治疗氨中毒及调节神经递质，而肝性脑病的发生主要是由于体内血氨的升高引发一系列神经系统症状，即氨中毒学说，所以降低血氨至关重要（A对）。纠正水、电解质紊乱（B错）是一般对症治疗措施，非针对发病机制的治疗。机械通气（C错）通常用于治疗急、慢性呼吸衰竭；降颅压（D错）为颅内高压的对症治疗措施。二者均对肝性脑病的治疗帮助不大。","c83","N"],["2015-N102",40,"第五节 肾病综合征","肾病综合征诊断",2015,102,"A","","男性，55岁，间断水肿1年，加重半个月，伴气短、纳差2天入院。查体：BP150/90mmHg，心肺检查未见异常，腹软，肝脾肋下未触及，双下肢凹陷性水肿（++）。化验尿：蛋白（++++），尿糖（±），尿沉渣镜检RBC0～2/HP。B超双肾静脉主干有血栓。最可能的诊断是",[["A","糖尿病肾病"],["B","慢性肾小球肾炎急性发作"],["C","高血压肾损害"],["D","肾病综合征"]],"D","55岁男性患者（中老年男性），间断水肿1年，出现尿蛋白（++++），双下肢凹陷性水肿（++），B超示双肾静脉血栓（肾病综合征的常见并发症，系因血液浓缩及高脂血症造成血液粘稠，且机体凝血、抗凝和纤溶系统失衡），诊断考虑肾病综合征（D对）。糖尿病肾病（A错）为糖尿病的常见微血管病变，常表现为血糖升高、尿糖升高、尿微量白蛋白增多，常有糖尿病多年慢性病史。慢性肾小球肾炎急性发作（B错）常表现为血尿、蛋白尿、高血压、水肿，多伴有肾功能减退表现如贫血，多无肾静脉血栓形成（十版内科学P487）。高血压肾损害（C错）常有多年高血压病史，一般肾小球滤过功能受累较轻，肾小管浓缩稀释功能受累较早出现，如夜尿增多、尿比重降低，而蛋白尿出现较晚，一般无肾静脉血栓形成（十版内科学P272）。","c84","N"],["2015-N103",40,"第五节 肾病综合征","膜性肾病",2015,103,"A","","男性，55岁，间断水肿1年，加重半个月，伴气短、纳差2天入院。查体：BP150/90mmHg，心肺检查未见异常，腹软，肝脾肋下未触及，双下肢凹陷性水肿（++）。化验尿：蛋白（++++），尿糖（±），尿沉渣镜检RBCO～2/HP。B超双肾静脉主干有血栓。肾穿刺检查，最可能的病理结果是",[["A","系膜毛细血管性肾炎"],["B","结节性肾小球硬化"],["C","入球动脉玻璃样变性"],["D","膜性肾病"]],"D","膜性肾病好发于中老年男性，极易发生血栓、栓塞并发症，本例为中老年男性，有肾静脉血栓，故最可能的病理诊断为膜性肾病（D对）。系膜毛细血管性肾炎（A错）好发于青壮年，几乎所有患者均有血尿。结节性肾小球硬化（B错）是糖尿病肾病的特征性病变，在肾病综合征中少见。入球动脉玻璃样变性（C错）为原发性高血压肾损害的常见病变。","c84","N"],["2015-N104",40,"第五节 肾病综合征","糖皮质激素",2015,104,"A","","男性，55岁，间断水肿1年，加重半个月，伴气短、纳差2天入院。查体：BP150/90mmHg，心肺检查未见异常，腹软，肝脾肋下未触及，双下肢凹陷性水肿（++）。化验尿：蛋白（++++），尿糖（±），尿沉渣镜检RBC0～2/HP。B超双肾静脉主干有血栓。最主要的治疗用药是",[["A","利尿剂"],["B","糖皮质激素"],["C","ACEI"],["D","胰岛素"]],"B","糖皮质激素（B对）通过抑制免疫与炎症反应，抑制醛固酮和抗利尿激素分泌，影响肾小球基底膜通透性等综合作用发挥利尿、消除蛋白尿的疗效，约60%～70%的膜性肾病经糖皮质激素和细胞毒药物治疗后可达临床缓解。对严重低蛋白血症、高度水肿而又少尿（尿量＜400ml/d）的NS患者，在必需利尿的情况下方可考虑使用利尿剂（A错），但也要避免过频过多。ACEI有不依赖于降低全身血压而减少尿蛋白作用，属于对症治疗措施（C错）。胰岛素（D错）可用于治疗糖尿病肾病，该患者并无糖尿病相关表现。","c84","N"],["2015-N105",56,"第二节 原发免疫性血小板减少症","原发免疫性血小板减少症临床表现",2015,105,"A","","女性，25岁。无明显诱因月经量增多2个月，出现牙龈出血2天入院，既往体健。查体：胸腹部及四肢皮肤散在出血点和少量瘀斑，浅表淋巴结不大，牙龈少量渗血，心肺腹检查未见明显异常。化验血：Hb100g/L，RBC3.3×10¹²/L，WBC8.2×10⁹/L，Plt9×10⁹/L，网织红细胞1%。为警惕颅内出血的危险，查体中还应特别注意的检查是",[["A","关节肿胀"],["B","血肿"],["C","鼻出血"],["D","口腔血疱"]],"D","患者为年轻女性，月经量增多、牙龈出血（出血症状）。查体：全身出血点和少量瘀斑，浅表淋巴结不大。化验血：Hb轻度减少（成年女性正常值115～150g/L），RBC轻度减少（成年女性正常值3.5～5.0×10¹²/L），WBC正常（正常值3.5～9.5×10⁹/L），Plt显著减少（正常值125～350×10⁹/L）。据此该患者最可能的诊断为特发性血小板减少性紫癜（ITP）。ITP患者出血为血小板减少所致，主要表现为皮肤、黏膜出血。口腔血疱（D对）属黏膜出血，查体中应特别注意检查。鼻出血（C错）、牙龈出血亦很常见，但是较皮肤、黏膜出血少见。而关节出血（A错）、深部血肿（B错）多与凝血功能障碍有关，ITP患者少见。","c85","N"],["2015-N106",56,"第二节 原发免疫性血小板减少症","原发免疫性血小板减少症诊断要点",2015,106,"A","","女性，25岁。无明显诱因月经量增多2个月，出现牙龈出血2天入院，既往体健。查体：胸腹部及四肢皮肤散在出血点和少量瘀斑，浅表淋巴结不大，牙龈少量渗血，心肺腹检查未见明显异常。化验血：Hb100g/L，RBC3.3×10¹²/L，WBC8.2×10⁹/L，Plt9×10⁹/L，网织红细胞1%。该患者最可能的诊断是",[["A","再生障碍性贫血"],["B","Evans综合征"],["C","特发性血小板减少性紫癜"],["D","弥散性血管内凝血"]],"C","患者为年轻女性，月经量增多、牙龈出血（出血症状）。查体：全身出血点和少量瘀斑，浅表淋巴结不大。化验血：Hb轻度减少（成年女性正常值115～150g/L），RBC轻度减少（成年女性正常值3.5～5.0×10¹²/L），WBC正常（正常值3.5～9.5×10⁹/L），Plt显著减少（正常值125～350×10⁹/L）。据此该患者最可能的诊断为特发性血小板减少性紫癜（ITP）（C对）。再生障碍性贫血（十版内科学P555）（A错）是由于造血干细胞受损导致的造血功能衰竭，患者一般三系均减少。Evans综合征（十版内科学P566）（B错）是自身免疫性溶血性贫血同时伴有血小板减少的一种疾病，主要表现为中、重度贫血，而血小板减少为次要表现。弥散性血管内凝血（D错）血小板进行性下降，病情危重，进展迅速，3P试验常阳性。","c85","N"],["2015-N107",56,"第二节 原发免疫性血小板减少症","骨髓象",2015,107,"A","","女性，25岁。无明显诱因月经量增多2个月，出现牙龈出血2天入院，既往体健。查体：胸腹部及四肢皮肤散在出血点和少量瘀斑，浅表淋巴结不大，牙龈少量渗血，心肺腹检查未见明显异常。化验血：Hb100g/L，RBC3.3×10¹²/L，WBC8.2×10⁹/L，Plt9×10⁹/L，网织红细胞1%。为确定诊断，首选的检查是",[["A","白细胞分类"],["B","骨髓检查"],["C","抗人球蛋白试验"],["D","凝血功能"]],"B","ITP诊断要点为：①至少2次化验血小板计数减少，血细胞形态无异常；②体检脾脏一般不增大；③骨髓检查巨核细胞增多或正常，有成熟障碍；④排除其他继发性血小板减少症。故本例患者要确诊还需要做骨髓检查（B对），明确骨髓巨核细胞数量和成熟情况及红系、粒系和单核系是否正常。白细胞分类（A错）为细菌感染性疾病的检查方法。抗人球蛋白试验（Coombs试验）（十版内科学P566）（C错）是诊断温抗体型自身免疫性溶血性贫血的重要依据。凝血功能检测（D错）为凝血障碍性疾病的常用检查。","c85","N"],["2015-N108",61,"第三节 高渗高血糖综合征","高渗高血糖综合征诊断",2015,108,"A","","女性，72岁。6天前进食后出现腹泻，呈稀水样，每日7～8次，伴恶心、呕吐，当地医院给予输注葡萄糖等治疗后，感口干加重、尿量增多。1天来反应迟钝，淡漠，既往有脑梗塞病史，曾有血糖增高史。查体：BP90/50mmHg，嗜睡状，呼吸正常，即刻查血糖35.3mmol/L。该患者最可能的诊断是",[["A","糖尿病酮症酸中毒"],["B","高血糖高渗状态"],["C","急性胃肠炎合并脱水"],["D","水电解质紊乱"]],"B","本例老年患者出现重度腹泻伴恶心呕吐（高渗高血糖综合征常有严重脱水表现），反应迟钝、淡漠、嗜睡（高渗高血糖综合征可有不同程度的意识障碍或昏迷），随机血糖35.3mmol/L（高渗高血糖综合征血糖一般为33.3～66.8mmol/L）。据此，该患者最可能的诊断为高血糖高渗状态（高渗高血糖综合征）（B对）。糖尿病酮症酸中毒（A错）血糖一般为16.7～33.3mmol/L，常表现为酸中毒大呼吸（又称Kussmaul呼吸），表现为呼吸频率增快，呼吸深大，呼吸中可有烂苹果味。急性胃肠炎合并脱水（C错）患者起病急，多有暴饮暴食或不洁饮食史，常表现恶心、呕吐、腹泻和剧烈腹痛，无高血糖表现。高渗高血糖综合征可合并有血钠增高，水电解质紊乱（D错）可为该患者的次要表现，但不能作为主要诊断。","c86","N"],["2015-N109",61,"第三节 高渗高血糖综合征","高渗高血糖综合征实验室检查",2015,109,"A","","女性，72岁。6天前进食后出现腹泻，呈稀水样，每日7～8次，伴恶心、呕吐，当地医院给予输注葡萄糖等治疗后，感口干加重、尿量增多。1天来反应迟钝，淡漠，既往有脑梗塞病史，曾有血糖增高史。查体：BP90/50mmHg，嗜睡状，呼吸正常，即刻查血糖35.3mmol/L。为明确该诊断作进一步检查，最有价值的项目是",[["A","血浆有效渗透压"],["B","尿酮体"],["C","血气分析"],["D","血电解质"]],"A","高渗高血糖综合征血糖≥33.3mmo1/L，有效血浆渗透压≥320mOsm/L可诊断本病。本例已急查患者血糖，为明确诊断，最有价值的检查项目固然为血浆有效渗透压（A对）。高血糖高渗状态患者尿酮体阴性或弱阳性，对诊断高血糖高渗状态意义不大（B错）。高渗高血糖综合征血钠正常或增高，血电解质紊乱为次要表现，对诊断高血糖高渗状态意义不大（D错）。血气分析（C错）主要监测病人通气与换气功能及机体的酸碱平衡状态，对诊断高血糖高渗状态意义不大。","c86","N"],["2015-N110",61,"第三节 高渗高血糖综合征","高渗高血糖综合征治疗",2015,110,"A","","女性，72岁。6天前进食后出现腹泻，呈稀水样，每日7～8次，伴恶心、呕吐，当地医院给予输注葡萄糖等治疗后，感口干加重、尿量增多。1天来反应迟钝，淡漠，既往有脑梗塞病史，曾有血糖增高史。查体：BP90/50mmHg，嗜睡状，呼吸正常，即刻查血糖35.3mmol/L。下列的治疗措施中不恰当的是",[["A","开始24小时补液量可达6000～10000ml"],["B","静脉胰岛素输注速度一般为每公斤体重每小时0.1单位"],["C","开始可先大量输入低渗盐水"],["D","血压偏低，可先给予输血浆"]],"C","高血糖高渗状态患者的治疗：开始用等渗溶液如0.9%氯化钠（C错，为本题正确答案），因大量输入等渗液不会引起溶血，有利于恢复血容量，纠正休克，改善肾血流量，恢复肾脏调节功能。休克患者另予血浆或全血（D对）。如无休克或休克已纠正，在输入生理盐水后血浆渗透压高于350mOsm/L，血钠高于155mmol/L，可考虑输入适量低渗溶液如0.45%氯化钠。本症失水比DKA（糖尿病酮症酸中毒）更为严重，可达体重10%～15%，24小时补液量可达6000～10000ml（A对）。本症常用小剂量胰岛素疗法，以每小时给予每公斤体重0.1U的速率静脉滴注胰岛素（B对）。","c86","N"],["2015-N139",23,"第一节 感染性心内膜炎","心脏杂音",2015,139,"B","","亚急性感染性心内膜炎一般不出现的临床表现是",[["A","贫血"],["B","心瓣膜区杂音"],["C","脾肿大"],["D","环形红斑"]],"D","亚急性感染性心内膜炎多发生于器质性心脏病，首先为心脏瓣膜病，尤其是二尖瓣和主动脉瓣；其次为先天性心血管病，如室间隔缺损、动脉导管未闭、法洛四联症和主动脉缩窄。患者可有轻、中度贫血（A对），80%～85%患者可闻及心脏杂音（B对），15%～50%患者可出现脾肿大（C对），但一般不会出现环形红斑（D错，为本题正确答案），环形红斑是急性风湿热具有诊断意义的病变。","","N"],["2015-N140",21,"第六节 风湿热","心脏炎",2015,140,"B","","急性风湿热一般不出现的临床表现是",[["A","贫血"],["B","心瓣膜区杂音"],["C","脾肿大"],["D","环形红斑"]],"C","急性风湿热常有轻度红细胞计数和血红蛋白含量降低，呈正细胞正色素性贫血（A对），而无脾肿大（C错，为本题正确答案）（十三版实用内科学P2695）。风湿热是A组乙型溶血性链球菌感染后反复发作的全身结缔组织炎症，若累及心脏导致心脏炎出现心脏杂音（B对），如若为二尖瓣炎时可有心尖区高调、收缩期吹风样杂音或短促低调舒张中期杂音（Carey coombs杂音），主动脉瓣炎时在心底部可听到舒张中期柔和吹风样杂音出现。环形红斑（D对）是急性风湿热具有诊断意义的病变。","","N"],["2015-N141",6,"第一节 肺结核","异烟肼",2015,141,"B","","对结核分枝杆菌A菌群作用最强的药物是",[["A","异烟肼"],["B","利福平"],["C","吡嗪酰胺"],["D","乙胺丁醇"]],"A","结核分枝杆菌根据其代谢状态分为A、B、C、D4个菌群。抗结核药物对不同菌群的作用各异。对A菌群作用强弱依次为异烟肼（A对）＞链霉素＞利福平（B错）＞乙胺丁醇（D错）；对B菌群依次为吡嗪酰胺（C错）＞利福平＞异烟肼；对C菌群依次为利福平＞异烟肼；抗结核药物对D菌群无作用。","","N"],["2015-N142",6,"第一节 肺结核","吡嗪酰胺",2015,142,"B","","对结核分枝杆菌B群作用最强的药物是",[["A","异烟肼"],["B","利福平"],["C","吡嗪酰胺"],["D","乙胺丁醇"]],"C","结核分枝杆菌根据其代谢状态分为A、B、C、D4个菌群。抗结核药物对不同菌群的作用各异。A菌群作用强弱依次为异烟肼＞链霉素＞利福平＞乙胺丁醇（D错）；B菌群依次为吡嗪酰胺（C对）＞利福平（B错）＞异烟肼（A错）；C菌群依次为利福平＞异烟肼；抗结核药物对D菌群无作用。","","N"],["2015-N143",28,"第一节 消化性溃疡","出血",2015,143,"B","","消化性溃疡患者最常见的并发症是",[["A","穿孔"],["B","出血"],["C","幽门梗阻"],["D","癌变"]],"B","消化性溃疡指胃肠道黏膜被自身消化而形成的溃疡，可发生于食管、胃、十二指肠、胃-空肠吻合口附近以及含有胃黏膜的Meckel憩室（十版内科学P374）。其并发症主要包括穿孔（A）、出血（B）、幽门梗阻（C）及癌变（D），其中出血（B对）是最常见的并发症，癌变（D错）是最少见的并发症（胃溃疡癌变率＜1%，十二指肠溃疡一般不癌变）。","","N"],["2015-N144",28,"第一节 消化性溃疡","癌变",2015,144,"B","","十二指肠溃疡患者不易发生的并发症是",[["A","穿孔"],["B","出血"],["C","幽门梗阻"],["D","癌变"]],"D","十二指肠溃疡并发症主要包括穿孔（A错）、出血（B错）及幽门梗阻（C错），其中出血是最常见的并发症。胃溃疡有可能发生癌变，但十二指肠溃疡一般不发生癌变（D对）。","","N"],["2015-N169",17,"第四节 急性冠状综合征","急性ST段抬高型心肌梗死鉴别诊断",2015,169,"X","","对急性胸痛患者，鉴别急性心肌梗死与主动脉夹层有意义的临床表现有",[["A","疼痛持续时间"],["B","合并消化道症状"],["C","心肌坏死标记物"],["D","主动脉瓣区杂音"]],"CD","急性心肌梗死与主动脉夹层均可以出现持续性胸痛，故疼痛持续时间（A错）不能作为两者的鉴别依据。急性心肌梗死有心肌坏死标记物（如肌钙蛋白、肌酸激酶同工酶等）（C对）的变化而后者没有。主动脉夹层可因主动脉瓣关闭不全而出现主动脉瓣区杂音（D对），急性心肌梗死多可在心尖区闻及粗糙的收缩期杂音或伴收缩晚期喀喇音，为二尖瓣乳头肌功能失调或断裂所致。急性心肌梗死时，心输出量降低，胃肠道缺血，可出现频繁的恶心、呕吐和上腹胀痛等消化道症状；主动脉夹层撕裂累及腹主动脉时，亦可导致肠道缺血，出现腹痛、恶心、呕吐及黑便等消化道症状，因此合并消化道症状（B错）不能鉴别急性心肌梗死和主动脉夹层。","","N"],["2015-N170",6,"第一节 肺结核","结核菌素试验",2015,170,"X","","结核菌素试验阴性可见于",[["A","结核性脑膜炎"],["B","儿童结核"],["C","癌症合并结核"],["D","营养不良合并结核"]],"ACD","结核菌素试验广泛运用于检出结核菌分枝杆菌感染，而不用于结核病的诊断。结核菌素试验阳性不能区分是结核分枝杆菌的自然感染还是卡介苗接种的免疫反应。儿童结核分枝杆菌自然感染率较低，若儿童感染结核（B错），其结核菌素试验常表现为强阳性。结核性脑膜炎（A对）、癌症（C对）及营养不良（D对）患者机体免疫力低下，机体免疫应答能力较弱，感染结核分枝杆菌后，不能建立充分的变态反应，结核菌素试验常阴性。","","N"],["2015-N171",27,"第二节 慢性胃炎","慢性胃炎对症治疗",2015,171,"X","","根除胃幽门螺杆菌治疗时常用的药物包括",[["A","雷尼替丁"],["B","奥美拉唑"],["C","硫糖铝"],["D","克拉霉素"]],"BD","根治幽门螺杆菌的药物主要包括三类：质子泵抑制剂、铋剂及抗生素。根除Hp需要联合用药，目前倡导的联合方案为含有铋剂的四联疗法，即1种PPI（奥美拉唑）（B对）+2种抗生素和1种铋剂，疗程10～14天，常用的能根治幽门螺杆菌的抗生素包括阿莫西林（羟氨苄青霉素），甲硝唑（或呋喃唑酮）、克拉霉素（甲红霉素）（D对）。雷尼替丁（A错）属于H₂受体拮抗剂，硫糖铝（C错）属于胃黏膜保护剂，均不用于Hp的根除治疗。有关幽门螺杆菌的根治方案，最新版内科学教材明确为四联方案（372）。","","N"],["2015-N172",45,"第一节 慢性肾衰竭","骨骼病变",2015,172,"X","","下列属于尿毒症肾性骨营养不良的疾病有",[["A","纤维囊性骨炎"],["B","骨生成不良"],["C","骨软化症"],["D","骨硬化症"]],"ABC","慢性肾脏病患者存在钙、磷等矿物质代谢及内分泌功能紊乱，导致矿物质异常、骨病、血管钙化等临床综合征，即肾性骨营养不良，包括高转化性骨病（纤维囊性骨炎）（A对）、低转化性骨病（包括骨软化症、骨再生不良）（BC对）及骨质疏松症。六版内科学P546、五版内科学P573均明确指出肾性骨营养不良症包括骨硬化症（D），且真题2001N155X肾性骨营养不良症也包括了骨硬化症，七、八、九、十版内科学均未明确说明肾性骨营养不良是否包括骨硬化症，所以D选项存在争议，参考答案为ABC，故默认D选项不属于肾性骨营养不良。","","N"],["2015-N173",55,"","",2015,173,"X","","下列凝血因子中，如缺陷可引起APTT延长的有",[["A","纤维蛋白原"],["B","凝血酶原"],["C","凝血因子Ⅶ"],["D","凝血因子Ⅹ"]],"ABD","APTT（活化部分凝血活酶时间）反映的是内源性凝血系统功能，所有参与内源性凝血途径的因子缺乏，如因子Ⅻ、Ⅺ、Ⅸ、Ⅷ、Ⅹ（D对）、Ⅴ、Ⅱ（凝血酶原）（B对）、PK（激肽释放酶原）、HMWK（高分子量激肽原）和纤维蛋白原（A对）缺乏，均可使APTT延长。凝血因子Ⅶ（C错）是外源性通路中的关键因子，其缺陷对APTT延长没有影响。","","N"],["2015-N174",60,"第五节 嗜铬细胞瘤","嗜铬细胞瘤心血管系统表现",2015,174,"X","","嗜铬细胞瘤的心血管系统临床表现有",[["A","间歇性高血压"],["B","持续性高血压"],["C","直立性低血压"],["D","休克"]],"ABCD","嗜铬细胞瘤起源于肾上腺髓质、交感神经节或其他部位的嗜铬组织，这种瘤持续或间断地释放大量儿茶酚胺，引起间歇性（A对）或持续性高血压（B对），可伴直立性低血压（C对）。其中，阵发性高血压是特征性病变。嗜铬细胞瘤还可发生低血压，甚至休克（D对），或出现高血压和低血压交替的表现。低血压及血压交替不稳的发生有下述原因：肿瘤骤然停止释放儿茶酚胺；大量儿茶酚胺引起严重心律失常或心力衰竭；由于肿瘤可分泌肾上腺素，兴奋肾上腺素能β受体，使周围血管扩张；肿瘤分泌多种扩血管物质，如舒血管肠肽、肾上腺髓质素等。","","N"],["2016-N57",15,"第二节 慢性心力衰竭","左心衰竭体征",2016,57,"A","","下列疾病中，出现混合性发绀的是",[["A","肺栓塞"],["B","阻塞性肺气肿"],["C","心力衰竭"],["D","亚硝酸盐中毒"]],"C","发绀可由血液中还原血红蛋白增加（真性发绀）及血液中存在异常血红蛋白衍生物引起。其中，真性发绀可分为中心性发绀、周围性发绀和混合性发绀。中心性发绀可分为：①肺性发绀，常见于各种严重的呼吸系统疾病，如肺栓塞（A错）、阻塞性肺气肿（B错）、肺淤血、肺水肿、急性呼吸窘迫综合征等；②心性混合性发绀，常见于发绀型先天性心脏病。周围性发绀常见于体循环淤血及引起心排血量减少的疾病。混合性发绀常见于心力衰竭（C对）。亚硝酸盐中毒引起发绀是由于血液中存在异常血红蛋白衍生物所致（D错）。","","N"],["2016-N58",35,"第一节 肝硬化","肝硬化临床表现",2016,58,"A","","下列疾病中，可出现杵状指的是",[["A","肝硬化"],["B","慢性支气管炎"],["C","肢端肥大"],["D","缺铁性贫血"]],"A","杵状指（趾）为手指或足趾末端增生、肥厚、增宽、增厚，指甲从根部到末端拱形隆起呈杵状。其发生机制可能与肢体末端慢性缺氧、代谢障碍及中毒性损害有关。缺氧时末端肢体毛细血管增生扩张，因血流丰富，软组织增生，末端膨大。杵状指（趾）常见于：①呼吸系统疾病，如慢性肺脓肿、支气管扩张和支气管肺癌；②某些心血管疾病，如发绀型先天性心脏病，亚急性感染性心内膜炎；③营养障碍性疾病，如肝硬化（A对）。杵状指不常见于慢性阻塞性肺疾病（B错）或慢性肺结核的病人，如果这类病人出现杵状指，应怀疑肿瘤；肢端肥大症（C错）是由于GH过度分泌而导致的一种疾病，临床呈慢性进展，主要表现为软弱乏力，手足粗大；缺铁性贫血（十版内科学P550）（D错）患者指（趾）甲缺乏光泽、脆薄易裂，重者指（趾）甲变平，甚至凹下呈勺状（匙状甲）。","","N"],["2016-N59",10,"第二节 特发性肺动脉高压","特发性肺动脉高压体征",2016,59,"A","","女性，32岁，患特发性肺动脉高压，可能出现的体征是",[["A","心尖搏动呈抬举样"],["B","心尖搏动向左侧移位"],["C","心尖部可闻及收缩期杂音"],["D","心底部第二心音逆分裂"]],"B","特发性肺动脉高压可使右心室增大肥厚，心尖搏动向左移位（B对）；心尖搏动呈抬举样（A错）为左心室肥厚的体征。特发性肺动脉高压使右心室增大后，相对性三尖瓣关闭不全，可在三尖瓣区闻及收缩期杂音；心尖部闻及收缩期杂音为二尖瓣关闭不全的体征（C错）。特发性肺动脉高压使右心室射血时间延长，肺动脉瓣关闭延迟，出现S₂通常分裂；心底部第二心音逆分裂（D错）为病理性体征，是指主动脉瓣关闭迟于肺动脉瓣，常见于完全性左束支传导阻滞、主动脉瓣狭窄或重度高血压。","","N"],["2016-N60",15,"第三节 急性心力衰竭","洋地黄类药物",2016,60,"A","","男，60岁，因一年反复夜间阵发性呼吸困难，2个月心悸、气短、不能平卧、尿少、下肢水肿来院，三年前患广泛前壁心肌梗死。入院查体：T36.7℃，P67次/分，BP120/65mmHg，半卧位、颈静脉充盈、双肺底闻及湿啰音，心界扩大，心律不整，心率98次/分，心音强弱不等，肝肋下2cm，双下肢凹陷性水肿（++），该治疗不宜选用的药物",[["A","洋地黄"],["B","华法林"],["C","β受体拮抗剂"],["D","血管紧张素转化酶抑制剂"]],"C","患者现心力衰竭急性期，伴有体液潴留，不可使用β受体阻滞剂（拮抗剂）（C错，为本题正确答案），心脏负性作用会加重心衰。应用洋地黄（A对）可增加心肌收缩力，并降低心室率，从而提高心功能。老年男性患者，广泛前壁心肌梗死病史（提示心功能有减退），出现夜间阵发性呼吸困难、双肺底湿啰音（为左心衰的典型征象）、颈静脉充盈、肝脏肿大、下肢凹陷性水肿（为右心衰体循环淤血征象），且脉率＜心率，心音强弱不等（为心房颤动的典型征象）。该患者房颤，目前CHA₂DS₂-VASc2分，应使用华法林抗凝药物（十版内科学P202）（B对）。早期大量应用血管紧张素转化酶抑制剂（D对）可延缓甚至逆转心室重塑，提高患者的远期预后。","","N"],["2016-N61",18,"第一节 原发性高血压","高血压急症和亚急症治疗原则",2016,61,"A","","有关高血压急症治疗原则，不正确的是",[["A","使用静脉制剂快速降压"],["B","60分钟内降压幅度不超过25%"],["C","2～6小时内将血压降至正常水平"],["D","无临床症状及靶器官损害证据者，可采取口服降压治疗"]],"C","高血压急症时应及时正确处理过高的血压，尽快缓解病情，预防进行性或不可逆性靶器官损害，降低死亡率。其治疗原则包括以下几点：①及时降低血压：选用适宜有效的降压药静脉滴注给药（A对），同时监测血压。②控制性降压：初始阶段（数分钟到1小时内）血压控制目标为平均动脉压降低幅度不超过治疗前水平的25％（B对），在随后2～6小时内将血压控制至较安全的水平，一般为160/100mmHg左右（C错，为本题正确答案）；如果可耐受，临床情况稳定，在随后24～48小时逐步降至正常水平；③合理选择降压药物。尽量选择起效迅速、作用时间短、不良反应小，且降压过程中不明显影响心率、心输出量和脑血流量的药物；④注意避免选用部分不适宜的降压药如利血平，治疗早期亦不适宜使用强利尿药。高血压急症不伴严重临床症状及进行性靶器官损害时称为高血压亚急症，可采取口服降压治疗（D对），在24～48小时内降低血压即可。","","N"],["2016-N62",16,"第三节 房性心律失常","房性期前收缩治疗",2016,62,"A","","女性，36岁。因偶发心悸3天来诊。既往有“预激综合征”，无心动过速史。查体：P80次/分，BP110/70mmHg，双肺（-），心界不大，偶发早搏0～3次/分，心音正常。24小时动态心电图示单发房性期前收缩98次。该患者应首选的治疗方案是",[["A","观察病情，暂不用药"],["B","应用IC类抗心律失常药"],["C","选用钙通道阻滞剂"],["D","立即行射频消融术"]],"A","青年女性患者，偶发心悸三天，查体脉率正常，偶发早搏。24小时动态心电图示早发房性期前收缩98次，约4次/小时，症状轻微，首选观察病情，暂不用药（A对），但需避免诱发房早的因素如吸烟、饮酒等。药物治疗仅用于部分症状严重患者，常用药物包括IC类抗心律失常药（如普罗帕酮、莫雷西嗪）（B错）或β受体拮抗剂。钙通道阻滞剂（C错）可用于各种折返性室上性心动过速及房扑房颤时减慢心室率。偶发房性期前收缩不是射频消融术的适应证（D错）。","","N"],["2016-N63",5,"第一节 肺脓肿","肺脓肿抗感染治疗",2016,63,"A","","急性肺脓肿停用抗菌药物治疗的指征是",[["A","体温正常"],["B","痰恶臭味消失"],["C","血白细胞正常"],["D","胸片显示脓腔消失"]],"D","肺脓肿应用抗生素疗程6～8周，或直至X线胸片示脓腔和炎症消失（D对），仅有少量的残留纤维化时停用抗菌药物。体温正常（A错）、血白细胞正常（C错）、痰恶臭味消失（B错）不是肺脓肿停药指征。","","N"],["2016-N64",8,"第二节 特发性肺纤维化","肺功能",2016,64,"A","","男性，66岁。进行性呼吸困难伴干咳1年，无吸烟史。查体：双下肺可闻及爆裂音，可见杵状指。胸部HRCT提示：双下肺蜂窝状改变。最可能的肺功能指标改变是",[["A","FEV₁/FVC减低"],["B","TLC减低"],["C","RV增高"],["D","DLCO增高"]],"B","患者，男，66岁（特发性肺纤维化多于50岁以后发病），进行性呼吸困难伴干咳1年，双下肺可闻及爆裂音，可见杵状指［爆裂音或Velcro啰音，是特发性肺纤维化的常见体征，90％可出现，约半数患者可见杵状指（趾）］，胸部HRCT提示双下肺蜂窝状改变（特发性肺纤维化HRCT典型表现），考虑诊断为特发性肺纤维化。特发性肺纤维化，属于间质性肺疾病，主要表现为限制性通气功能障碍、弥散量降低伴低氧血症或Ⅰ型呼吸衰竭。限制性通气功能障碍表现为肺容量包括肺总量（TLC）、肺活量（VC）和残气量（RV）均减少（B对C错），肺顺应性降低，一秒钟用力呼气容积/用力肺活量（FEV₁/FVC）正常或增加（A错）；弥散量降低表现为一氧化碳弥散量（DLCO）减少（D错）。FEV₁/FVC减低、RV增高见于阻塞性通气功能障碍性疾病如COPD。","","N"],["2016-N65",2,"第一节 支气管哮喘","轻度",2016,65,"A","","支气管哮喘急性发作首选治疗方法是",[["A","静脉注射氨茶碱"],["B","雾化吸入异丙托溴铵"],["C","雾化吸入沙丁胺醇"],["D","静脉使用糖皮质激素"]],"C","SABA（短效β₂受体激动剂）为治疗急性哮喘发作的首选药物，首选吸入给药。常用药物有沙丁胺醇和特布他林（C对）。氨茶碱静脉给药主要用于重症和危重症哮喘（十版内科学P36）（A错）。常用的SAMA异丙托溴铵主要用于哮喘急性发作的治疗，多与β₂受体激动剂联合应用（十版内科学P36）（B错）。静脉给予激素主要用于重度或严重哮喘发作时（十版内科学P36）（D错）。","","N"],["2016-N66",26,"第一节 胃食管反流病","胃食管反流病诊断",2016,66,"A","","诊断胃食管反流病最准确的是",[["A","食管吞钡X线检查"],["B","食管测压"],["C","24h食管pH监测"],["D","胃镜"]],"D","胃镜（D对）是诊断RE（反流性食管炎）最准确的方法，并能判断其严重程度和有无并发症，结合活检可与其他原因引起的食管炎和其他食管病变作鉴别。虽然食管吞钡X线检查（A错）、食管测压（B错）、24h食管pH监测（C错）都对本病的诊断有帮助，但都不是最准确的检查方法。（根据10版内科学P364： 食管反流监测：包括食管 pH 监测和食管阻抗 -pH 监测，可用于评估症状与反流的相关性，提供反流的客观证据，是诊断GERD的金标准。原答案依据9版内科学教材编写）","","N"],["2016-N67",28,"第一节 消化性溃疡","保护胃黏膜",2016,67,"A","","临床上服用下列药物时，不影响对幽门螺杆菌病原检测的是",[["A","奥美拉唑"],["B","枸橼酸铋钾"],["C","米索前列醇"],["D","呋喃唑酮"]],"C","PPI类如奥美拉唑（A错）可增强抗Hp抗生素的杀菌作用；铋剂如枸橼酸铋钾（B错）还可通过包裹Hp菌体，干扰Hp代谢，发挥杀菌作用；呋喃唑酮（D错）为硝基呋喃类抗生素，是一种广谱抗菌药，可用于Hp（幽门螺杆菌）所致的胃窦炎，可用来根除幽门螺杆菌；米索前列醇（C对）抑制胃酸分泌，增加胃黏膜血流量，增加胃十二指肠黏膜黏液和碳酸氢盐的分泌，对Hp无杀伤或抑制作用，因此不会干扰幽门螺杆菌病原检测。","","N"],["2016-N68",32,"第二节 肠易激综合征","肠易激综合征诊断与鉴别诊断",2016,68,"A","","男，40岁，5年来反复腹痛，腹泻，排便2～4次/日，加重一周，排黏液便，无脓血，便后缓解。查体：腹软，左下腹压痛。便常规RBC（-），WBC（-）。该患者最可能的诊断是",[["A","克罗恩"],["B","溃疡性结肠炎"],["C","细菌性痢疾"],["D","肠易激综合征"]],"D","中年男性患者，慢性腹痛、腹泻，排黏液便，无脓血（肠易激综合征的粪便特点），便后缓解，左下腹压痛（肠易激综合征腹痛部位以下腹和左下腹多见），便常规无红细胞、白细胞（肠易激综合征为功能性肠病，无器质性病变），可以得出该患者最可能的诊断是肠易激综合征（D对）。克罗恩病（A错）病变主要位于末端回肠和邻近结肠，常见右下腹痛及压痛。溃疡性结肠炎（B错）主要临床症状为腹痛、腹泻及黏液脓血便，大便常规镜检可见红细胞及脓细胞。细菌性痢疾（C错）常有不洁饮食史，阵发性腹痛、腹泻，每日排便十几次至几十次，典型者为黏液脓血便伴里急后重，便常规镜检可见大量脓细胞及红细胞。","","N"],["2016-N69",44,"第一节 急性肾损伤","血液检查",2016,69,"A","","急性肾小管坏死维持期出现的实验室异常是",[["A","血尿素氮与肌酐的比值减低"],["B","血红蛋白中度以上减低"],["C","血钾浓度减低"],["D","尿钠浓度减低"]],"A","急性肾小管坏死（以下简称ATN）维持期血尿素氮及肌酐均升高，但肌酐升高幅度相对更高，因此血尿素氮与肌酐的比值降低（A对），常＜10～15。ATN维持期可出现轻度贫血，可能与毒素蓄积有关。因红细胞寿命达120天，而ATN病理进程相对较短，红细胞减少相对少，因此贫血（血红蛋白降低）一般为轻度（B错）。ATN维持期多有少尿，此时肾脏排泌H⁺、K⁺减少，导致血钾浓度升高，此外酸中毒可促进K⁺向细胞外转移，进一步升高血钾浓度（C错）。ATN时，肾小管重吸收功能降低，导致尿钠浓度升高（＞20mmol/L）（D错），钠排泄分数大于1％。","","N"],["2016-N70",40,"第五节 肾病综合征","肾病综合征诊断",2016,70,"A","","男性，32岁，5天来眼睑及下肢水肿入院。6年前患病毒性乙型肝炎。查体：BP140/82mmHg，双眼睑水肿，巩膜无黄染，心肺检查未见异常，腹软，肝脾触诊不满意，腹部移动性浊音阳性，双下肢凹陷性水肿（++）。化验尿常规：蛋白（++++），沉渣镜检RBC2～5/HP。血清白蛋白20g/L。对诊断和治疗最有意义的检查是",[["A","24小时尿蛋白定量"],["B","肝功能和HBsAg检查"],["C","血胆固醇测定"],["D","肾穿刺病理学检查"]],"D","中年男性患者，双下肢凹陷性水肿（++），腹部移动性浊音阳性，尿蛋白（++++），血清白蛋白20g/L（低于30g/L），诊断考虑肾病综合征。临床上对于肾病综合征的诊断包括三个方面：明确是否为肾病综合征；确认病因及病理分型，最好能进行肾活检（D对）；判定有无并发症。24小时尿蛋白定量（A错）、血胆固醇测定（C错）可以协助诊断和评估病情，但并非诊断和治疗最有意义的检查。肝功能和HBsAg检查（B错）可用于辅助诊断乙型肝炎病毒相关性肾炎（继发性肾病综合征），但诊断需要肾活检切片中找到乙型肝炎病毒抗原。","","N"],["2016-N71",46,"第一节 贫血概述","贫血实验室检查",2016,71,"A","","下列外周血化验检查最有助于判断骨髓增生程度的是",[["A","血红蛋白测定"],["B","红细胞计数"],["C","网织红细胞计数"],["D","红细胞比容测定"]],"C","红细胞在骨髓发育成熟后转移到外周血被利用，其发育过程为：祖细胞→原始红细胞→早幼红细胞→中幼红细胞→晚幼红细胞→网织红细胞→成熟红细胞。骨髓中的晚幼红细胞脱核之后成为网织红细胞进入外周血，在外周血进一步发育成为成熟的红细胞。骨髓红系增生活跃时，网织红细胞计数增高，因此网织红细胞计数有助于判断骨髓增生程度（C对）。血红蛋白测定（A错）、红细胞计数（B错）是确定贫血的可靠指标，血红蛋白测定还可判断贫血的严重程度。红细胞比容（D错）指红细胞在全血中所占的容积百分比，反映红细胞和血浆的比例。","","N"],["2016-N72",57,"第一节 血友病","血友病实验室检查",2016,72,"A","","男性，15岁，左膝外伤后关节肿胀、疼痛2天。自幼外伤后易出血不止。查体：左膝关节处皮肤见一瘀斑，左膝关节肿胀，局部有压痛。该患者下列实验室检查中最有可能出现的异常是",[["A","凝血酶原时间（PT）"],["B","活化部分凝血酶时间（APTT）"],["C","凝血酶时间（TT）"],["D","血纤维蛋白原测定"]],"B","患者自幼外伤后易出血不止（与生俱来），左膝外伤后关节肿胀（血肿形成），局部有压痛，提示为关节内出血，符合血友病的诊断。血友病为FⅧ或FⅨ缺乏所致的出血性疾病，主要影响内源性凝血途径。故反映内源性凝血途径的指标如APTT（活化部分凝血活酶时间）和CT（凝血时间）延长（B对）。反映外源性凝血途径的指标如PT（凝血酶原时间）正常（A错）。反映血小板功能的指标如出血时间、血小板计数和血小板聚集功能正常。反映FⅠ（纤维蛋白原）功能的指标如凝血酶时间（TT）和血纤维蛋白原测定正常（CD错）。","","N"],["2016-N73",61,"第二节 糖尿病酮症酸中毒","糖尿病酮症酸中毒实验室检查",2016,73,"A","","对鉴别糖尿病酮症酸中毒与高渗高血糖综合征意义最小的检查是",[["A","血糖测定"],["B","尿酮体检查"],["C","血气分析检查"],["D","血电解质检查"]],"D","糖尿病酮症酸中毒（DKA）血糖一般为11.1～33.3mmol/L，血钠可表现正常、低于或者高于正常，尿酮体呈阳性，常伴有酮症酸中毒；高渗高血糖综合症（HHS）血糖一般为33.3～66.8mmol/L，血钠正常或者增高，尿酮体阴性或弱阳性，一般无明显酸中毒，血糖测定（Ａ对）、尿酮体测定（B对）、血气分析检查（C对）对二者均有一定的鉴别意义，血电解质检查（D错，为本题正确答案）的鉴别意义不大。","","N"],["2016-N74",59,"第一节 甲状腺功能亢进症","甲状腺毒症和甲亢的诊断",2016,74,"A","","男性，31岁，3个月来感全身乏力、手颤，体重下降7kg，4小时前起床时感双下肢不能活动，既往体健，查体：心率120次/分。血K⁺ 2.7mmol/L，Na⁺ 140.6mmol/L，Cl⁻105.1mmol/L，HCO₃⁻25.3mmol/L，患者最可能的诊断是",[["A","家族性周期麻痹"],["B","甲状腺毒症性周期性瘫痪"],["C","肾小管酸中毒"],["D","原发性醛固酮增多症"]],"B","中青年男性患者，既往体健，近3个月出现乏力、手颤、体重下降、心率120次/分（增快，正常为60～100次/分）等甲状腺功能亢进的典型表现，患者血清K⁺为2.7mmol/L（减低，正常为3.5～5.3mmol/L），4小时前出现双下肢不能活动（双侧对称性肌无力，双下肢最易受累，发作时血钾下降为周期性瘫痪的表现），考虑符合甲状腺毒症性周期性瘫痪（B对）。家族性周期性麻痹是以反复发作的骨骼肌弛缓性瘫痪为特征的疾病，有家族遗传倾向，故患者暂不考虑家族性周期性麻痹（A错）。肾小管酸中毒（十版内科学P506）主要表现为高氯性代谢性酸中毒，临床表现为烦渴、多饮、多尿，伴低钾、钠、钙血症。该患者血清Na⁺为140.6mmol/L（正常，范围为137～147mmol/L），血清Cl⁻为105.1mmol/L（正常，范围为96～106mmol/L），故暂不考虑此病（C错）。原发性醛固酮增多症（十版内科学P713）表现为高血压而低血钾，高血钠、高尿钾。该患者无肾上腺占位，无高血压病史，血钠正常，故暂不考虑此病（D错）。","","N"],["2016-N75",68,"第一节 类风湿关节炎","关节肿胀",2016,75,"A","","首发累及近端指间关节，掌指关节和腕关节的风湿性疾病是",[["A","类风湿关节炎"],["B","骨关节炎"],["C","强直性脊柱炎"],["D","系统性红斑狼疮"]],"A","类风湿关节炎（RA）首发关节为PIP（近端指间关节）、MCP（掌指关节）、腕关节（A对）。骨关节炎（B错）首发关节为膝、腰椎、远端指间关节。强直性脊柱炎（C错）首发关节为膝、髋、踝关节。系统性红斑狼疮（D错）首发关节为手关节或其他部位。","","N"],["2016-N76",69,"第一节 系统性红斑狼疮","抗ENA抗体谱",2016,76,"A","","抗ENA抗体谱中不包括的抗体是",[["A","抗RNP抗体"],["B","抗SSB（La）抗体"],["C","抗dsDNA抗体"],["D","抗Sm抗体"]],"C","抗ENA抗体主要有：抗Sm抗体（D错）、抗SSA抗体、抗SSB抗体（B错）、抗RNP抗体（A错）、抗rRNP抗体。对结缔组织疾病诊断和鉴别诊断有重要意义，与疾病严重程度和活动性无明显相关。抗双链DNA（dsDNA抗体）（C对）对诊断SLE有较高的特异性，且与SLE的活动相平行，并可作为治疗的评估，但其不属于抗ENA抗体。","","N"],["2016-N91",40,"","",2016,91,"A","","女性，24岁，3周前上感发热、咽痛，1周以来乏力，头晕，晨起颜面部肿胀，继而出现下肢肿胀，食欲减退，尿少。自幼房间隔缺损。查体：T37.2℃，P88次/分，BP150/90mmHg，发育差，自主体位，双侧眼睑水肿，颈静脉无怒张，双肺（-），心界不大，心律整齐，心音正常，P₂＞A₂，腹软，肝脾肋下未及，下肢凹陷性水肿（+）。该患者最有可能的水肿类型是什么",[["A","心源性"],["B","肾源性"],["C","肝源性"],["D","营养不良性"]],"B","青年女性患者，3周前上感发热、咽痛（急性肾炎的常见前驱感染），相继出现颜面部肿胀及下肢肿胀，血压升高，尿少（考虑肾功减退），诊断考虑急性肾小球肾炎。因此该患者最有可能的水肿原因为肾源性（B对）水肿，其特点是水肿从眼睑、颜面开始而延及全身。心源性（A错）水肿多见于右心衰及部分心包疾患（如缩窄性心包炎、心包压塞），其特点是水肿多先出现于踝部，逐渐向上蔓延。本例患者心界不大，脉率正常，心音正常，水肿自颜面部开始。肝源性（C错）水肿多见于肝硬化患者，水肿多先出现于踝部，逐渐向上蔓延，但头面部和上肢常无水肿，常同时伴有脾大及肝功能减退的临床表现。营养不良性（D错）水肿见于长期慢性消耗性疾病、蛋白质丢失性胃肠病和重度烧伤患者，水肿常先从足部开始，逐渐蔓延全身，常伴消瘦、体重减轻等症状。","c91","N"],["2016-N92",40,"第一节 肾小球疾病概述","水肿",2016,92,"A","","女性，24岁，3周前上感发热、咽痛，1周以来乏力，头晕，晨起颜面部肿胀，继而出现下肢肿胀，食欲减退，尿少。自幼房间隔缺损。查体：T37.2℃，P88次/分，BP150/90mmHg，发育差，自主体位，双侧眼睑水肿，颈静脉无怒张，双肺（-），心界不大，心律整齐，心音正常，P2＞A2，腹软，肝脾肋下未及，下肢凹陷性水肿（+）。导致该患者水肿最可能的机制是",[["A","水钠潴留"],["B","血管通透性增加"],["C","低蛋白血症"],["D","静脉压增大"]],"A","根据该患者的临床表现考虑为肾炎性水肿。肾炎性水肿的主要机制为：肾小球滤过率下降，而肾小管重吸收功能基本正常造成“球-管失衡”和肾小球滤过分数（肾小球滤过率/肾血浆流量）下降，导致水钠潴留（A对）。血管通透性增加（B错）为炎症性水肿的发生机制。低蛋白血症（C错）为肝源性水肿的发生机制。静脉压增大（D错）为心源性水肿的发生机制。","c91","N"],["2016-N93",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄诊断",2016,93,"A","","患者男，70岁，3个月前出现活动后胸闷头晕，晕厥，近1周上一层楼即感心前区疼痛，2小时前因再感胸痛伴短暂晕厥来院，既往有糖尿病12年，吸烟35年，查体：P82次/分，Bp100/85mmHg，神志清，颈静脉无怒张，双肺（-），心尖搏动抬举样，心界向左下移位，心律整，S₁低钝，胸骨右缘第二肋间可闻及3/6收缩期吹风样杂音，粗糙，喷射状，向颈部放散，A₂＜P₂，下肢不肿。本例最可能的诊断是",[["A","肥厚型梗阻性心肌病"],["B","主动脉瓣狭窄"],["C","不稳定性心绞痛"],["D","病态窦房结综合征"]],"B","患者老年男性，根据活动后胸闷、胸痛、头晕、晕厥等症状（主动脉狭窄导致心肌缺血及外周供血不足），查体：心尖抬举样搏动，心界向左下扩大，胸骨右缘第2肋间可闻及3/6收缩期吹风样杂音，粗糙，喷射状，向颈部扩散等典型体征（主动脉瓣狭窄的典型心脏杂音），诊断考虑主动脉瓣狭窄（B对）。患者无胸骨左缘第3～4肋间收缩期杂音，无心尖部收缩期杂音，故肥厚型梗阻性心肌病可能性不大（A错）。患者胸痛症状均出现在活动后，而不稳定型心绞痛在休息时亦可发作，发作时可发现一过性第三及第四心音，心尖部可闻及一过性收缩期杂音，因此不稳定型心绞痛可能性不大（C错）。病态窦房结综合征常有与心动过缓相关的心、脑等脏器供血不足的症状，而该患者并无心律失常（最典型为心动过缓与房性快速性心律失常交替发作）的表现，故病态窦房结综合征可能性不大（D错）。","c92","N"],["2016-N94",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄超声心动图",2016,94,"A","","患者男，70岁，3个月前出现活动后胸闷头晕，晕厥，近1周上一层楼即感心前区疼痛，2小时前因再感胸痛伴短暂晕厥来院，既往有糖尿病12年，吸烟35年，查体：P82次/分，Bp100/85mmHg，神志清，颈静脉无怒张，双肺（-），心尖搏动抬举样，心界向左下移位，心律整，S₁低钝，胸骨右缘第二肋间可闻及3/6收缩期吹风样杂音，粗糙，喷射状，向颈部放散，A₂＜P₂，下肢不肿。对明确诊断意义最大的无创性检查是",[["A","常规体表心电图"],["B","24小时动态心电图"],["C","冠状动脉CT"],["D","超声心动图"]],"D","超声心动图（D对）有助于显示心脏结构和功能，如二叶瓣、瓣叶变形、僵硬、瓣叶开放幅度或瓣口面积减小等，可以明确部分狭窄的原因，常作为主动脉瓣狭窄诊断的首选无创性检查。常规体表心电图（A错）及24小时动态心电图（B错）仅能反映心电活动的变化，主要用于诊断心律失常等相关疾病。冠状动脉CT用于诊断冠心病（C错）。","c92","N"],["2016-N95",21,"第一节 主动脉瓣狭窄","外科人工瓣膜置换术",2016,95,"A","","患者男，70岁，3个月前出现活动后胸闷头晕，晕厥，近1周上一层楼即感心前区疼痛，2小时前因再感胸痛伴短暂晕厥来院，既往有糖尿病12年，吸烟35年，查体：P82次/分，Bp100/85mmHg，神志清，颈静脉无怒张，双肺（-），心尖搏动抬举样，心界向左下移位，心律整，S₁低钝，胸骨右缘第二肋间可闻及3/6收缩期吹风样杂音，粗糙，喷射状，向颈部放散，A₂＜P₂，下肢不肿。为缓解胸痛、头晕，最适宜的治疗是",[["A","静脉注射硝酸酯制剂"],["B","应用β受体阻滞剂"],["C","介入治疗"],["D","心脏瓣膜置换术"]],"D","患者目前存在因主动脉瓣狭窄引起的活动后胸闷、胸痛、头晕、晕厥等不适，有外科手术主动脉瓣置换的指征（D对）。本患者出现的心绞痛症状与冠脉收缩或狭窄无关，应用硝酸酯类不仅不能从根本上缓解症状，还会引起直立性低血压等副作用（A错）。除非伴有房颤，否则主动脉狭窄患者应尽量避免应用β受体阻滞剂（B错）。介入治疗主要用于冠心病（C错）。","c92","N"],["2016-N96",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病诊断",2016,96,"A","","男性，75岁，反复咳嗽，咳痰，喘息30年，活动后气短2年，加重1周。既往高血压病史25年，吸烟史30年，平均1包/日，已戒烟2年，查体：R22次/分，双肺呼吸音低，偶闻及干鸣音。双下肺可闻及少许湿性啰音。该患者最可能的诊断",[["A","慢性阻塞性肺疾病"],["B","支气管扩张症"],["C","支气管哮喘"],["D","慢性心衰"]],"A","患者老年男性，既往有长期吸烟史，30年来反复咳嗽、咳痰、喘息，2年来活动后气短（慢阻肺的标志性症状），近1周来上述症状加重，查体双肺呼吸音减低，伴干、湿性啰音，根据症状、体征考虑慢性阻塞性肺疾病急性加重期可能性大（A对）。患者无反复咳脓痰、咯血病史，支气管扩张可能性不大（十版内科学P41）（B错）。患者无夜间及凌晨发作性伴有哮鸣音的呼气性呼吸困难，考虑支气管哮喘可能性不大（十版内科学P32）（C错）。虽然患者既往有高血压病史且双下肺有少许湿性啰音，但无夜间阵发性呼吸困难、端坐呼吸等左心衰症状和体征，且无双下肢水肿、肝脾大等右心衰表现，故不考虑慢性心衰（十版内科学P179）（D错）。","c93","N"],["2016-N97",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病肺功能检查",2016,97,"A","","男性，75岁，反复咳嗽，咳痰，喘息30年，活动后气短2年，加重1周。既往高血压病史25年，吸烟史30年，平均1包/日，已戒烟2年，查体：R22次/分，双肺呼吸音低，偶闻及干鸣音。双下肺可闻及少许湿性啰音。下列检查对诊断意义最大",[["A","胸部HRCT"],["B","肺功能"],["C","血气分析"],["D","超声心动图"]],"B","患者考虑为慢性阻塞性肺疾病可能性大。慢性阻塞性肺疾病的确诊依据是肺功能检查，持续性气流受限是慢阻肺诊断的必备条件（B对）。当病人处于昏迷状态无法进行肺功能检查时选用血气分析，血气分析主要用于诊断呼吸衰竭（十版内科学P148）（C错）；胸部HRCT主要用于诊断支气管扩张和肺纤维化（A错）；超声心动图主要用于检查心功能（D错）。","c93","N"],["2016-N98",1,"第二节 慢性阻塞性肺疾病","支气管扩张剂",2016,98,"A","","男性，75岁，反复咳嗽，咳痰，喘息30年，活动后气短2年，加重1周。既往高血压病史25年，吸烟史30年，平均1包/日，已戒烟2年，查体：R22次/分，双肺呼吸音低，偶闻及干鸣音。双下肺可闻及少许湿性啰音。应采取的措施",[["A","口服利尿剂"],["B","静脉应用糖皮质激素"],["C","吸入支气管舒张剂"],["D","口服祛痰药"]],"C","患者为老年男性，既往有长期吸烟史，30年来反复咳嗽、咳痰、喘息，近2年来活动后气促，近1周来上述症状加重，同时伴干、湿性啰音，根据症状、体征考虑慢性阻塞性肺疾病急性加重期可能性大，可予支气管舒张剂、祛痰等治疗，通畅呼吸道，改善通气功能，吸入支气管舒张剂起效快，副作用小，是控制症状的主要措施（C对）。口服祛痰剂可用于咳痰较多、痰浓不易咳出者，该患者可以应用此药物，但不是最佳答案（D错）。对需住院治疗的急性加重期患者可考虑静脉给予糖皮质激素，但不能常规长期使用，故也不是最佳选项（B错）。患者目前无右心功能不全症状，暂不予利尿剂（A错）。慢性阻塞性肺疾病患者即使出现心力衰竭，一般在积极控制感染、改善呼吸功能、纠正缺氧和二氧化碳潴留后，心力衰竭便能得到改善，不需常规使用利尿药，经过上述治疗无效者可以适当选用，但应注意会使痰液粘稠，不易排出。","c93","N"],["2016-N99",29,"第二节 结核性腹膜炎","结核性腹膜炎诊断",2016,99,"A","","女性，26岁，腹胀、腹痛伴低热、盗汗3个月。查体：腹部移动性浊音（+），化验血HBsAg（+），腹水常规：比重＞1.023，蛋白38g/L，WBC610×10⁶/L，单核细胞百分比80%。该患者最可能的诊断是",[["A","肝硬化合并自发性腹膜炎"],["B","结核性腹膜炎"],["C","肝炎后肝硬化失代偿期"],["D","肝癌腹膜转移"]],"B","年轻女性患者，腹胀、腹痛伴低热、盗汗，腹水检查结果提示为渗出液，以单核细胞为主，提示结核性腹膜炎（B对）。肝硬化合并自发性腹膜炎（A错）也可有腹痛、渗出性腹水、血HBsAg（+），但体检可发现轻重不等的全腹压痛和腹膜刺激征，渗出性腹水以中性粒细胞为主，腹水可培养出致病菌，且常有肝硬化典型临床表现，如肝功能减退，门脉高压等。肝炎后肝硬化失代偿期（C错）虽血HBsAg（+），但常有肝硬化典型临床表现，如肝功能减退，门脉高压等，无发热、盗汗等结核中毒症状，腹水检查通常为漏出液。肝癌腹膜转移（D错）发病年龄较晚，多有肝癌典型临床表现，腹水多呈血性。","c94","N"],["2016-N100",29,"第二节 结核性腹膜炎","腹腔积液检查",2016,100,"A","","女性，26岁，腹胀、腹痛伴低热、盗汗3个月。查体：腹部移动性浊音（+），化验血HBsAg（+），腹水常规：比重＞1.023，蛋白38g/L，WBC610×10⁶/L，单核细胞百分比80%。下列检查结果支持上述诊断的是",[["A","腹水腺苷脱氨酶（ADA）79.5U/L"],["B","血清-腹水白蛋白梯度（SAAG）12g/L"],["C","腹水病理检查见到癌细胞"],["D","腹水培养见到来自肠道的革兰阴性菌"]],"A","腺苷脱氨酶（ADA）在淋巴细胞内含量较高，结核性腹膜炎时，因细胞免疫受刺激，淋巴细胞明显增多，故结核性腹膜炎的腹水中腺苷脱氨酶（ADA）活性常增高（P116），多高于45U/L（A对）。血清-腹水白蛋白梯度（SAAG）是血清白蛋白含量和腹水白蛋白含量的差值，是判断肝腹水病因的常用指标，能够较真实地反映门静脉压力，提高诊断腹水的准确性。当SAAG≥11g/L时为高梯度腹水，提示存在门静脉高压，腹水为漏出液，如SAAG＜11g/L，则为低梯度腹水，提示为非门静脉高压腹水，腹水为渗出液。结核性腹膜炎腹水为渗出液，SAAG应＜11g/L（B错）。腹水病理检查见到癌细胞是癌性腹水的表现（C错）。腹水培养见到来自肠道的革兰阴性菌支持自发性腹膜炎（D错）的诊断。","c94","N"],["2016-N101",29,"第二节 结核性腹膜炎","抗结核化学药物治疗",2016,101,"A","","女性，26岁，腹胀、腹痛伴低热、盗汗3个月。查体：腹部移动性浊音（+），化验血HBsAg（+），腹水常规：比重＞1.023，蛋白38g/L，WBC610×10⁶/L，单核细胞百分比80%。该患者最宜选用的治疗是",[["A","对症治疗"],["B","广谱抗生素"],["C","抗结核"],["D","抗癌"]],"C","本例患者为年轻女性，有腹胀、腹痛伴低热、盗汗病史，腹水检查结果为渗出液，以单核细胞为主，提示结核性腹膜炎，因此首先应该进行抗结核治疗（C对）。对症治疗应作为抗结核治疗的辅助治疗手段（A错）。结核性腹膜炎为结核感染性疾病，一般抗生素治疗无效（B错）。该患者最可能的诊断是结核性腹膜炎，并非癌症病变，无需进行抗癌治疗（D错）。","c94","N"],["2016-N102",40,"第二节 急性肾小球肾炎","急性肾小球肾炎诊断",2016,102,"A","","男，21岁，肉眼血尿伴少尿6天入院。2周前有咽痛、发热。既往体健。查体：BP156/95mmHg，皮肤黏膜未见出血和紫癜，双眼睑水肿，双下肢凹陷性水肿（++）。化验尿常规，蛋白（++），沉渣RBC50～60/HP，血肌酐156μmol/L，尿素氮11mmol/L。该患者最可能诊断",[["A","急性肾小球肾炎"],["B","急进性肾小球肾炎"],["C","IgA肾病"],["D","肾病综合征"]],"A","年轻男性患者，2周前有咽痛、发热（前驱症状），出现肉眼血尿伴少尿，查体：BP156/95mmHg，双眼睑水肿，蛋白（++），沉渣RBC50～60/HP（典型的肾炎综合征表现），血肌酐156μmol/L（正常成年男性血Cr为53～106μmol/L，提示肾功能损伤），尿素氮11mmol/L（正常值为1.8～7.1mmol/L），提示肾功能减退，最可能的诊断考虑为急性肾小球肾炎（A对）。急进性肾小球肾炎（B错）病情进展迅速，患者无肾功能急剧恶化、进行性肾功能恶化等表现，考虑急进性肾小球肾炎可能性不大。IgA肾病（十版内科学P478）（C错）常表现为上呼吸道感染24～72小时后出现突发性肉眼血尿，持续数小时至数日。肾病综合征（D错）诊断必需标准为尿蛋白大于3.5g/d，至少为（+++），且血浆白蛋白低于30g/L（十版内科学P480）。本患者尿蛋白（++），无低蛋白血症、高脂血症等临床特征，考虑肾病综合征可能性不大。","c95","N"],["2016-N103",40,"第二节 急性肾小球肾炎","急性肾小球肾炎病理表现",2016,103,"A","","男，21岁，肉眼血尿伴少尿6天入院。2周前有咽痛、发热。既往体健。查体：BP156/95mmHg，皮肤黏膜未见出血和紫癜，双眼睑水肿，双下肢凹陷性水肿（++）。化验尿常规，蛋白（++），沉渣RBC50～60/HP，血肌酐156μmol/L，尿素氮11mmol/L。行肾穿刺病理学检查，最可能的病理类型是",[["A","系膜增生性肾小球肾炎"],["B","微小病变性肾小球肾炎"],["C","毛细血管内增生性肾小球肾炎"],["D","新月体性肾小球肾炎"]],"C","急性肾小球肾炎最常见的病理类型为毛细血管内增生型肾小球肾炎（C对），光镜下通常为弥漫性肾小球病变，以内皮细胞及系膜细胞增生为主，急性期可伴有中性粒细胞及单核细胞浸润。系膜增生性肾小球肾炎（A错）、微小病变性肾小球肾炎（B错）多为肾病综合征的病理类型。新月体性肾小球肾炎（D错）多为急进性肾小球肾炎的病理类型。","c95","N"],["2016-N104",40,"第二节 急性肾小球肾炎","急性肾小球肾炎治疗",2016,104,"A","","男，21岁，肉眼血尿伴少尿6天入院。2周前有咽痛、发热。既往体健。查体：BP156/95mmHg，皮肤黏膜未见出血和紫癜，双眼睑水肿，双下肢凹陷性水肿（++）。化验尿常规，蛋白（++），沉渣RBC50～60/HP，血肌酐156μmol/L，尿素氮11mmol/L。该患者目前不宜选用的治疗是",[["A","限制盐的摄入"],["B","利尿治疗"],["C","降压治疗"],["D","糖皮质激素与细胞毒药物治疗"]],"D","该患者诊断为急性肾小球肾炎，该病为自限性疾病，大部分患者仅需治疗原发感染灶及对症治疗，包括利尿消肿（B对）、降血压、预防心脑并发症的发生。若休息、低盐（A对）和利尿后高血压控制仍不满意时，可加用降压药物（C对）。急性肾衰竭患者可以予以透析，待其自然恢复。本病为自限性疾病，大部分患者预后好，一般不宜使用糖皮质激素及细胞毒药物治疗（D错，为本题正确答案）。","c95","N"],["2016-N105",52,"第二节 急性白血病","急性白血病诊断",2016,105,"A","","男性，35岁，牙龈出血，皮肤瘀斑及间断流鼻血10天入院。既往体健。化验血常规：Hb64g/L，WBC10.5×10⁹/L，PLT26×10⁹/L。骨髓增生明显活跃，可见胞浆中有较多颗粒POX染色强阳性的细胞，部分可见成堆Auer小体，计数此种细胞占65%。此患者最可能的诊断是",[["A","急性淋巴性白血病"],["B","急性早幼粒性白血病"],["C","急性单核细胞性白血病"],["D","急性巨核细胞性白血病"]],"B","患者为青年男性，有出血症状。血常规示：Hb64g/L（男性正常范围130～175 g/L），WBC10.5×10⁹/L（正常值为3.5～9.5×10⁹/L），PLT26×10⁹/L（正常值为125～350×10⁹/L）。骨髓象示：骨髓增生明显活跃。据此可初步诊断为白血病。该患者胞浆可见棒状小体（Auer小体），POX（过氧化物酶）染色强阳性，可诊断为急性粒细胞性白血病：棒状小体（Auer小体）在急性淋巴细胞白血病不可见（A错），在急性粒细胞白血病和急性单核细胞白血病时可见到；POX（过氧化物酶）染色在急性粒细胞白血病时多呈强阳性反应，急性单核细胞白血病时呈弱阳性或阴性反应（C错），急性淋巴细胞白血病则呈阴性反应。急性早幼粒细胞胞浆内含有较多粗大颗粒，故本例最可能的诊断是急性早幼粒细胞白血病（B对）。","c96","N"],["2016-N106",52,"第二节 急性白血病","急性白血病免疫学检查",2016,106,"A","","男性，35岁，牙龈出血，皮肤瘀斑及间断流鼻血10天入院。既往体健。化验血常规：Hb64g/L，WBC10.5×10⁹/L，PLT26×10⁹/L。骨髓增生明显活跃，可见胞浆中有较多颗粒POX染色强阳性的细胞，部分可见成堆Auer小体，计数此种细胞占65%。支持上述诊断的细胞免疫学表型是",[["A","CD10阳性，CD19阳性"],["B","CD13阳性，HLA-DR阳性"],["C","CD13阳性，HLA-DR阴性"],["D","CD41阳性，CD61阳性"]],"C","该患者最可能的诊断是急性早幼粒细胞白血病（APL）。APL细胞通常表达CD13、CD33和CD117，不表达HLA-DR（C对B错）和CD34，还可表达CD9。B淋巴细胞通常表达CD10、CD19和CD20（A错）。M₇（急性巨核细胞白血病）通常表达CD41（D错）。","c96","N"],["2016-N107",52,"第二节 急性白血病","出血",2016,107,"A","","男性，35岁，牙龈出血，皮肤瘀斑及间断流鼻血10天入院。既往体健。化验血常规：Hb64g/L，WBC10.5×10⁹/L，PLT26×10⁹/L。骨髓增生明显活跃，可见胞浆中有较多颗粒POX染色强阳性的细胞，部分可见成堆Auer小体，计数此种细胞占65%。此患者最易得的并发症",[["A","高尿酸性肾病"],["B","弥散性血管内凝血"],["C","严重感染"],["D","中枢神经系统性白血病"]],"B","APL（急性早幼粒细胞白血病）细胞颗粒中含有促凝物质，故此患者最易得的并发症为弥散性血管内凝血（B对）。高尿酸性肾病（A错）是急性白血病化疗时常见的并发症（十版内科学P582）。严重感染（C错）是急性白血病的常见临床表现。中枢神经系统白血病（十版内科学P583）（D错）多见于急性淋巴细胞白血病。","c96","N"],["2016-N108",61,"第二节 糖尿病酮症酸中毒","糖尿病酮症酸中毒诊断",2016,108,"A","","男性，34岁，口渴，多尿，乏力2个月，1天前外出饮酒，饱餐后，上述症状加重伴恶心，频繁呕吐，继而神志恍惚，急诊入院。既往有乙型肝炎病史。入院查体：BP85/50mmHg，神志恍惚，皮肤黏膜干燥，心率104次/分，四肢发凉。该患者应首先考虑的诊断是",[["A","急性重症胰腺炎"],["B","急性食物中毒"],["C","糖尿病酮症酸中毒"],["D","肝性脑病"]],"C","该患者为青年男性，口渴、多尿、乏力（糖尿病症状指多尿、烦渴多饮和难于解释的体重减轻）2月，1天前外出饮酒、饱餐（DKA最常见的诱因是感染，其他诱因包括胰岛素治疗中断、各种应激以及酗酒等）后，上述症状加重伴恶心、呕吐，继而神志恍惚（DKA可导致脑细胞失水或水肿、中枢神经功能障碍）。入院查体：皮肤黏膜干燥（DKA引起渗透性利尿，导致严重失水），血压下降（正常不低于90/60mmHg）、心率增快（正常为60～100次/分）、四肢发凉（DKA严重失水可导致低血容量休克）。据此，该患者应首先考虑的诊断是糖尿病酮症酸中毒（DKA）（C对）。急性重症胰腺炎（A错）患者伴有剧烈腹痛、腹部压痛、反跳痛等特征性表现及体征。急性食物中毒（B错）发病潜伏期短，来势凶猛急剧，短时间内可能出现多人发病，以胃肠道症状为主。肝性脑病（D错）多由肝硬化引起，常见诱因为消化道出血、大量排钾利尿等。","c97","N"],["2016-N109",61,"第二节 糖尿病酮症酸中毒","糖尿病酮症酸中毒实验室检查",2016,109,"A","","男性，34岁，口渴，多尿，乏力2个月，1天前外出饮酒，饱餐后，上述症状加重伴恶心，频繁呕吐，继而神志恍惚，急诊入院。既往有乙型肝炎病史。入院查体：BP85/50mmHg，神志恍惚，皮肤黏膜干燥，心率104次/分，四肢发凉。为明确诊断，最主要的检查是",[["A","血淀粉酶"],["B","血糖及尿酮体"],["C","血氨"],["D","血渗透压"]],"B","糖尿病酮症酸中毒患者血糖升高，一般为11.1～33.3mmol/L，尿糖强阳性、尿酮阳性，故此患者为明确诊断，最主要的检查应为血糖及尿酮体（B对）。血淀粉酶（A错）为诊断急性胰腺炎首选检查方法。血氨（C错）为肝性脑病患者常规检查。血渗透压（D错）为诊断高渗高血糖综合征所需检查之一。","c97","N"],["2016-N110",61,"第二节 糖尿病酮症酸中毒","补液",2016,110,"A","","男性，34岁，口渴，多尿，乏力2个月，1天前外出饮酒，饱餐后，上述症状加重伴恶心，频繁呕吐，继而神志恍惚，急诊入院。既往有乙型肝炎病史。入院查体：BP85/50mmHg，神志恍惚，皮肤黏膜干燥，心率104次/分，四肢发凉。该患者急诊应急处理正确的是",[["A","快速静脉输入生理盐水"],["B","即刻使用去甲肾上腺素"],["C","静脉输入葡萄糖"],["D","静脉输入支链氨基酸"]],"A","补液是治疗糖尿病酮症酸中毒的关键环节，基本原则是“先快后慢，先盐后糖”，应先快速输入生理盐水（A对），当血糖下降至13.9mmol/L时，根据血钠情况以决定改为5％葡萄糖液或葡萄糖生理盐水（C错）。经快速输液仍不能有效升血压，应输入胶体溶液并采取其他抗休克措施，如使用去甲肾上腺素（B错）。静脉输入支链氨基酸为肝性脑病治疗方法（十版内科学P420）（D错）。","c97","N"],["2016-N139",15,"第二节 慢性心力衰竭","6分钟步行试验",2016,139,"B","","女，70岁，冠心病患者，行6分钟步行实验结果为425米，该患者心功能为",[["A","重度心功能不全"],["B","中度心功能不全"],["C","轻度心功能不全"],["D","心功能正常"]],"B","患者老年女性，冠心病诊断明确，行6分钟步行试验评价心功能情况。因6分钟步行试验结果示步行距离为425米，根据6分钟步行试验分级标准，6分钟步行距离＜150m为重度心衰；150～450m和＞450m分别为中度和轻度心衰，考虑为中度心功能不全（B对）。","","N"],["2016-N140",15,"第二节 慢性心力衰竭","6分钟步行试验",2016,140,"B","","男性，45岁，扩张性心肌病患者，行6分钟步行试验结果为145米，该患者的心功能为",[["A","重度心功能不全"],["B","中度心功能不全"],["C","轻度心功能不全"],["D","心功能正常"]],"A","患者中年男性，扩张性心肌病诊断明确，行6分钟步行试验评价心功能情况。因6分钟步行试验结果示步行距离为145米，根据6分钟步行试验分级标准，6分钟步行距离＜150m为重度心衰；150～450m和＞450m分别为中度和轻度心衰，考虑为重度心功能不全（A对）。","","N"],["2016-N141",9,"第一节 肺血栓栓塞症","呼吸功能不全",2016,141,"B","","肺栓塞患者出现低氧血症最主要的机制",[["A","肺泡通气量下降"],["B","弥散障碍"],["C","通气/血流比例失调"],["D","肺内分流"]],"C","通气血流比值是指每分钟肺泡通气量和每分钟肺血流量的比值，是影响肺换气的重要因素。无论比值增大或者减小，都表明两者匹配不佳，气体的交换效率均将降低，导致机体缺氧（九版生理学P160-P161）。肺栓塞时，栓塞部位肺血流减少，肺泡无效腔量增大；肺内血流重新分布，通气/血流比例增大，导致呼吸功能不全，出现低氧血症（C对）。低氧血症刺激外周化学感受器引起代偿性的过度通气。栓塞部位肺泡表面活性物质减少，顺应性下降，肺泡萎缩、不张，肺体积变小导致相对性肺泡通气不足，肺血流相对过多，通气/血流比例减小，部分血液流经通气不良的肺泡时会出现肺内分流。肺栓塞导致肺体积减小，呼吸膜的面积减小可引起弥散障碍。通气/血流比例失调、相对性肺泡通气不足（A错）、弥散障碍（B错）、肺内分流（D错）均参与肺栓塞低氧血症的形成，但最主要的机制是通气/血流比例失调。","","N"],["2016-N142",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病病理生理",2016,142,"B","","COPD患者出现低氧血症最主要的机制是",[["A","肺泡通气量下降"],["B","弥散障碍"],["C","通气/血流比例失调"],["D","肺内分流"]],"A","慢阻肺的特征性病理生理变化是持续气流受限导致肺通气功能障碍，肺泡通气量下降（A对）。其为COPD患者出现低氧血症最主要的机制，随着病情发展，会出现通气/血流比例失调（肺内分流为其类型之一）和弥散障碍（BCD错）。弥散障碍为间质性肺疾病患者出现低氧血症的主要机制。","","N"],["2016-N143",36,"第一节 原发性肝癌","病毒性肝炎",2016,143,"B","","在我国最易引起原发性肝癌的肝硬化类型是",[["A","病毒性肝炎后肝硬化"],["B","酒精性肝硬化"],["C","淤血性肝硬化"],["D","原发性胆汁性肝硬化"]],"A","在我国最易引起原发性肝癌的肝硬化类型是病毒性肝炎后肝硬化，肝癌患者中约90%有乙型肝炎病毒感染的背景。乙型肝炎病毒为一种DNA病毒，其基因组内X基因可整合至宿主细胞基因组上，激活癌基因，促进细胞增殖，导致癌变。HBV感染→慢性肝炎→肝硬化→肝癌是最主要的发病机制（A对BCD错）。","","N"],["2016-N144",35,"第一节 肝硬化","肝硬化代偿期",2016,144,"B","","肝脏明显缩小的肝硬化类型是",[["A","病毒性肝炎后肝硬化"],["B","酒精性肝硬化"],["C","淤血性肝硬化"],["D","原发性胆汁性肝硬化"]],"A","病毒性肝炎后肝硬化肝脏早期肿大，晚期明显缩小（A对）。酒精性肝硬化（B错）常伴黄疸，肝大并有触痛。淤血性肝硬化（C错）由于肝淤血，晚期仍有肝肿大。原发性胆汁性肝硬化（D错）由于胆汁淤积，肝中度～重度肿大，常在肋下4～10cm，质硬，表面光滑，压痛不明显。","","N"],["2016-N169",23,"第一节 感染性心内膜炎","择期手术",2016,169,"X","","感染性心内膜炎接受人工瓣膜适应证有",[["A","伴急性心肌梗死"],["B","严重瓣膜反流致左心衰竭"],["C","真菌性心内膜炎"],["D","赘生物直径大于10mm"]],"BCD","感染性心内膜炎指由细菌、真菌和其他微生物（如病毒、立克次体、衣原体、螺旋体等）直接感染而产生心瓣膜或心室壁内膜的炎症。人工心脏瓣膜是可植入心脏内代替心脏瓣膜（主动脉瓣、三尖瓣、二尖瓣），能使血液单向流动，具有天然心脏瓣膜功能的人工器官。感染性心内膜炎的手术适应征主要与心力衰竭、感染无法控制和栓塞事件有关。心力衰竭相关适应证主要包括（B对）：瓣膜急性反流或梗阻导致顽固性肺水肿或心源性休克、瘘入心腔或心包导致顽固性肺水肿或休克、瓣膜急性重度反流或梗阻，持续心力衰竭或心脏超声血流动力学恶化、瓣膜重度反流，无心力衰竭。不易控制的感染相关适应证包括：局灶型不易控制的感染（脓肿、假性动脉瘤、瘘管、赘生物增大）、持续发热或血培养阳性＞7～10天、真菌或多重耐药菌感染（C对）。预防栓塞事件相关适应证包括：抗感染治疗后赘生物仍增大，1次或以上栓塞事件、赘生物＞10mm 伴其他高危因素（D）、孤立性赘生物＞15mm。本题D选项单独的“赘生物直径＞10mm”不作为手术适应证，需要合并相关高危因素，故D选项有争议。但感染性心内膜炎伴有心肌梗死可先进行心梗的治疗，根据治疗后心功能评价结果确定是否需要瓣膜置换治疗（A错）。","","N"],["2016-N170",6,"第一节 肺结核","HIV_AIDS",2016,170,"X","","HIV/AIDS并发肺结核的特点",[["A","结核菌素试验常阴性"],["B","肺下叶病变多见"],["C","容易出现空洞"],["D","出现药物不良反应多见"]],"ABD","结核病是HIV/AIDS最常见的机会感染性疾病，HIV/AIDS加速了潜伏结核的发展和感染，两者相互产生不利影响（八版内科学P73）。HIV与结核分枝杆菌双重感染病例的临床表现是症状和体征多，如体重减轻、长期发热和持续性咳嗽等，全身淋巴结肿大，可有触痛，肺部X线影像经常出现肿大的肺门纵隔淋巴结团块，下叶病变多见（B对），胸膜和心包有渗出等，结核菌素试验常为阴性（A对），应多次查痰。治疗过程中常出现药物不良反应（D对）。HIV/AIDS并发肺结核病因严重的免疫缺陷，肺部炎症多轻而不典型，很少形成典型的肉芽肿性变，更少出现空洞（C 错），但病灶中的结核杆菌却甚多。","","N"],["2016-N171",75,"第一节 中毒概述","血液净化",2016,171,"X","","下列药物中毒中血液透析有效的是",[["A","苯巴比妥"],["B","茶碱"],["C","水杨酸"],["D","有机磷中毒"]],"ABC","血液透析用于清除血液中分子量较小和非脂溶性的毒物，如苯巴比妥（A对）、水杨酸类（C对）、甲醇、茶碱（B对）、乙二醇和锂等。有机磷（D错）因具有脂溶性，一般不进行血液透析，而选用血液灌流。","","N"],["2016-N172",40,"第五节 肾病综合征","肾病综合征病因",2016,172,"X","","下列属于中老年人继发性肾病综合征常见病因的有",[["A","糖尿病肾病"],["B","肾淀粉样变性"],["C","过敏性紫癜肾炎"],["D","系统性红斑狼疮肾炎"]],"AB","继发性肾病在老年人常见病因为糖尿病肾病（A对）、肾淀粉样变性（B对）、骨髓瘤性肾病、淋巴瘤或实体肿瘤性肾病。过敏性紫癜肾炎（C错）和系统性红斑狼疮肾炎（D错）在中老年人中并不常见，多见于儿童及青少年继发性肾病。继发性肾病在青少年常见病因为系统性红斑狼疮性肾炎、过敏性紫癜肾炎、乙型肝炎病毒相关性肾炎。继发性肾病在儿童常见病因为过敏性紫癜肾炎、乙型肝炎病毒相关性肾炎、系统性红斑狼疮肾炎。","","N"],["2016-N173",49,"第一节 再生障碍性贫血","AA分型诊断标准",2016,173,"X","","符合重型再生障碍性贫血血象诊断标准的有",[["A","Hb＜90g/L"],["B","网织红细胞＜15×10⁹/L"],["C","中性粒细胞＜0.5×10⁹/L"],["D","血小板＜20×10⁹/L"]],"BCD","再生障碍性贫血（AA）分为非重型再生障碍性贫血（NSAA）、重型再生障碍性贫血（SAA）和极重型再生障碍性贫血（VSAA）。其中重型再生障碍性贫血血象应具备下述三项中两项：网织红细胞绝对值＜15×10⁹/L（B对），中性粒细胞＜0.5×10⁹/L（C对）和血小板＜20×10⁹/L（D对）。Hb＜90g/L（A错）为中度贫血的划分标准（十版内科学P544），并不是诊断重型再障的指标。","","N"],["2016-N174",59,"第一节 甲状腺功能亢进症","Graves眼病",2016,174,"X","","Graves眼病活动期的指标是",[["A","眼球活动性疼痛"],["B","突眼度"],["C","复视"],["D","结膜充血"]],"ACD","Graves眼病活动期的指标包括：①球后疼痛超过4周；②眼运动时疼痛超过4周（A对）；③眼睑充血；④结膜充血（D对）；⑤眼睑肿胀；⑥球结膜水肿（C对）；⑦泪阜肿胀；⑧突眼度增加＞2mm（B）；⑨任一方向眼球运动减少5°以上；⑩视力下降≥1行。以上每项指标各计1分，总积分≥3分即为GO活动。需要注意的是，该标准在九版及十版教材中有所不同，九版球结膜水肿一项中添加了复视，故根据九版教材，本题答案应为 ACD，但根据八版及十版教材，选AD，原答案参照八版内科学选的AD（B选项描述的是突眼度，Graves眼病活动期相关指标为突眼度增加，故B选项一定程度上有争议）。","","N"],["2017-N41",35,"第一节 肝硬化","肝硬化临床表现",2017,41,"A","","可见于肝源性水肿的临床表现是",[["A","自颜面部开始向全身发展"],["B","可表现为踝部水肿"],["C","常伴发颈静脉充盈"],["D","常为非凹陷性水肿"]],"B","肝源性水肿多见于肝硬化患者，水肿多先出现于踝部（B对），逐渐向上蔓延，但头面部和上肢常无水肿（A错），常同时伴有脾大及肝功能减退的临床表现。颈静脉充盈（C错）为心源性水肿常见表现。非凹陷性水肿（D错）为甲状腺功能减退症所致水肿的特点。","","N"],["2017-N42",14,"","",2017,42,"A","","患者剑突下可见搏动，深吸气后明显，可能的临床意义是",[["A","腹主动脉瘤"],["B","肝血管瘤"],["C","右心室扩大"],["D","左心室室壁瘤"]],"C","剑突下搏动可能是右心室收缩期搏动，也可由腹主动脉搏动产生，吸气后，胸腔负压，促进右心室血液向肺灌注，使搏动增强。本题中患者剑突下可见搏动，深吸气后明显，可以判断搏动来自右心室（C对A错）。肝血管瘤（B错）小的病变多无症状，较大的病变可造成上腹不适或触及包块，巨大血管瘤可使肝脏显著增大，伴腹部不适，肝肿大，食欲不振，消化不良等症状，不引起剑突下搏动。室壁瘤（D错）是冠心病患者大面积心肌梗死后梗死区域出现室壁扩张、变薄、心肌全层坏死，坏死的心肌逐渐被纤维疤痕组织所替代，病变区薄层的心室壁向外膨出，心脏收缩时丧失活动能力或呈现反常运动，形成室壁瘤，常见于左心室，不引起剑突下搏动。","","N"],["2017-N43",4,"第一节 肺炎概述","医院获得性肺炎",2017,43,"A","","医院获得性肺炎最常见的致病菌是",[["A","革兰阳性杆菌"],["B","革兰阴性杆菌"],["C","革兰阳性球菌"],["D","革兰阴性球菌"]],"B","医院获得性肺炎最常见的致病菌是革兰阴性杆菌（B对）。医院获得性肺炎中，细菌是最常见的病原体，约占90%，其中1/3是复数菌感染，根据地区、病情、入院时间有所不同，常见病菌有革兰阴性杆菌（铜绿、肠杆菌科、流感嗜血杆菌）（构成比可达60%-90%）、金黄色葡萄球菌、厌氧菌、肺炎链球菌。","","N"],["2017-N44",11,"","",2017,44,"A","","男性，46岁，发热伴咳嗽、咳痰3天，右侧胸痛2天，既往“关节炎”病史，查体：T38.7℃，右下肺呼吸音减低，可闻及少许湿啰音，胸片提示右侧胸腔积液，胸水示：白细胞15，000×10⁶/L，单核10％，PH6.9，LDH986U/L，ADA90U/L。胸腔积液最可能是",[["A","结核性胸膜炎"],["B","肺癌"],["C","类风湿关节炎"],["D","脓胸"]],"D","患者中年男性，发热伴咳嗽、咳痰3天，右侧胸痛2天（胸膜感染表现），既往“关节炎”病史，查体：T38.7℃，右下肺呼吸音减低，可闻及少许湿啰音，胸片提示右侧胸腔积液（影像学表现），胸水示：白细胞15，000×10⁶/L（胸水白细胞升高提示胸膜感染），单核10％，pH6.9（提示脓胸），LDH986U/L（提示渗出液，炎症明显），ADA90U/L，ADA过高可高度怀疑结核性胸膜炎。在结核病高发的发展中国家中，ADA是一种简单、迅速、特异的方法，但以淋巴细胞为主的胸液（如类风湿关节炎、淋巴瘤、肺泡细胞癌、间皮瘤、支原体衣原体肺炎、军团菌感染、肺吸虫、隐球菌肺炎）中，ADA也可增高（实用内科学P1821）。根据患者的临床表现、实验室检查和影像学表现，胸腔积液最可能是脓胸（D对）。结核性胸膜炎（A错）多见于青壮年，一般有低热、消瘦、盗汗、干咳等全身中毒症状，胸水检查以淋巴细胞为主。肺癌（B错）患者胸部影像学表现多可见癌肿病灶及淋巴肿大征象。类风湿性关节炎（C错）的肺部影像学改变常表现为肺间质改变及类风湿结节。","","N"],["2017-N45",13,"第一节 呼吸衰竭概述","高碳酸血症性呼吸衰竭的发生机制",2017,45,"A","","男性患者，72岁，慢性咳嗽、咳痰20年。活动后呼吸困难3年，加重1周。既往吸烟史50年。血气分析提示PO₂50mmHg，PCO₂68mmHg。患者出现呼吸衰竭最主要的机制是",[["A","通气/血流比例失调"],["B","肺泡通气量下降"],["C","弥散功能障碍"],["D","肺内分流"]],"B","老年男性，慢性咳嗽咳痰20年（高度怀疑慢阻肺病史）。活动后呼吸困难3年，加重1周（慢阻肺急性加重期）。既往吸烟史50年（慢阻肺诱因）。血气分析提示PaO₂50mmHg（PaO₂＜60mmHg），PaCO₂68mmHg（PaCO₂＞50mmHg）（血气结果提示患者发生Ⅱ型呼吸衰竭），诊断为：①慢阻肺急性加重期；②Ⅱ型呼吸衰竭。慢阻肺是引起Ⅱ型呼吸衰竭的常见原因，其导致Ⅱ型呼吸衰竭最主要的机制是通气功能障碍，肺泡通气量下降（B对），造成CO₂潴留，发生高碳酸血症。通气血流比例失调（A错）、弥散功能障碍（C错）及肺内分流（D错）引起低氧血症，均表现为换气功能障碍，是导致Ⅰ型呼吸衰竭的因素。","","N"],["2017-N46",8,"第三节 结节病","纤维支气管镜与支气管肺泡灌洗",2017,46,"A","","女，48岁，胸闷，咳嗽4个月，无发热。胸部CT提示双侧肺门、纵隔淋巴结肿大，伴双肺网格影及小结节影，双下肺少许蜂窝状改变。支气管镜检查提示支气管黏膜呈铺路石样改变，支气管肺泡灌洗液检查最可能的结果是",[["A","中性粒细胞比例升高"],["B","淋巴细胞比例升高且CD4⁺/CD8⁺比值增高"],["C","淋巴细胞比例升高且CD4⁺/CD8⁺比值降低"],["D","嗜酸性粒细胞比例升高"]],"B","患者中年女性，咳嗽、胸闷、无发热（初步排除感染性病灶），CT显示双侧肺门纵隔淋巴结肿大伴双侧网格状小结节（结节病Ⅱ期常见X线改变），肺底有蜂窝状改变（结节病常见CT影像学改变）该患者初步诊断为：结节病，其支气管肺泡液多存在淋巴细胞增多且CD4⁺/CD8⁺增加（B对）。嗜酸性粒细胞（D错）可见于支气管哮喘。中性粒细胞细胞（A错）浸润多见于细菌感染性肺疾病。淋巴细胞增多且CD4⁺/CD8⁺降低则为过敏性肺炎肺泡灌洗液的检查结果（C错）。","","N"],["2017-N47",15,"第一节 心力衰竭总论","钠尿肽系统增强",2017,47,"A","","下列关于血浆脑钠肽（BNP）叙述正确的是",[["A","主要来源左心房"],["B","左心室功能不全可明显增高"],["C","增高可提示存在心肌损伤"],["D","快速心房颤动时明显增高"]],"B","BNP主要来源于心室（A错），ANP主要来源于心房。左心室功能不全时，左室收缩期射血分数减少，收缩末期残留于心腔内的血容量增加，导致心室容量负荷增加，心室壁张力增加，BNP分泌增加（B对）。血清BNP增高提示心衰，血清肌钙蛋白增高可提示存在心肌损伤（C错），BNP的分泌与心室功能密切相关，而与心房无关，快速心房颤动时BNP并不会明显增高（D错）。","","N"],["2017-N48",17,"第四节 急性冠状综合征","钙通道阻滞剂",2017,48,"A","","男，56岁，一个月3次夜间睡觉中因突发心前区疼痛而惊醒，伴出汗，咽部发紧，呼吸不畅，持续10分钟自行缓解，白天活动正常，既往发现血压升高1年，未治，吸烟20年。查体：P60/分，BP160/80，双肺正常，心率整，心音正常，双下肢不肿，首选降压治疗药物",[["A","血管紧张素转换酶抑制剂"],["B","血管紧张素Ⅱ受体拮抗剂"],["C","钙通道阻滞剂"],["D","β受体拮抗剂"]],"C","56岁男性患者一个月3次夜间睡觉中突发心前区疼痛，伴出汗、呼吸不畅，持续10分钟后自行缓解（不稳定型心绞痛临床表现），既往发现血压升高1年，未治，吸烟20年（冠状动脉粥样硬化性心脏病常见病因）。查体：P60/分，BP160/80mmHg（提示高血压）可初步诊断为：①不稳定型心绞痛；②高血压。钙通道阻滞剂（C对）降压疗效和幅度较强，疗效个体差异性小，对老年患者有较好的降压效果，长期治疗有抗动脉粥样硬化作用，为血管痉挛性心绞痛的首选药物。血管紧张素转换酶抑制剂（A错）和血管紧张素Ⅱ受体拮抗剂（B错）为高血压合并心力衰竭、心肌梗死、左心室肥厚、糖尿病肾病的首选治疗（三版八年制内科学P292）。β受体拮抗剂（D错）对心律较快的中、青年或合并心绞痛和慢性心力衰竭的患者疗效较好，对心肌的远期改善效果好，对老年高血压疗效相对较差，且会诱发冠脉痉挛而禁用于变异性心绞痛。","","N"],["2017-N49",15,"第二节 慢性心力衰竭","心脏再同步治疗",2017,49,"A","","男性，65岁。因心力衰竭2年来院。查体：口唇稍发绀，颈静脉充盈，双肺底均可闻及湿啰音，心界向两侧扩大，心律整，心率76次/分，双下肢凹陷性水肿（＋）。心电图示窦性心律，完全性左束支传导阻滞，超声心动图示左心室扩大，室壁弥漫性运动减弱伴运动不协调，LVEF32%。该患者治疗的最佳方案是",[["A","长期应用醛固酮受体拮抗剂"],["B","联合应用正性肌力药及血管扩张药"],["C","联合应用β受体拮抗剂和利尿剂"],["D","心脏再同步化治疗（CRT）"]],"D","老年男性患者，心力衰竭2年（慢性心衰），查体：口唇稍发绀，颈静脉充盈（右心衰表现），双肺底均可闻及湿啰音（左心衰表现），心界向两侧扩大，心律整，心率76次/分，双下肢凹陷性水肿（＋）。心电图示窦性心律，完全性左束支传导阻滞，超声心动图示左心室扩大，室壁弥漫性运动减弱伴运动不协调，LVEF32%。患者诊断为慢性心衰，左室收缩不同步，射血分数过低（LVEF32%），应首先增加患者心排量，改善缺氧症状。CRT可改善室内收缩同步性增加心排量，改善心衰症状，且完全性左束支传导阻滞对CRT反应良好（D对）。醛固酮受体拮抗剂可改善患者水肿，但不能增加心排量（A错）。正性肌力药物可抑制心脏传导，患者有完全性左束支传导阻滞，不宜作为首选（B错）。患者为全心衰，射血分数过低，症状严重，为β受体拮抗剂的禁忌证，不宜应用（C错）。","","N"],["2017-N50",27,"","",2017,50,"A","","阿司匹林引起NSAID溃疡的最主要致溃疡机制是",[["A","抑制COX-1"],["B","抑制COX-2"],["C","同时抑制COX-1和COX-2"],["D","局部作用"]],"A","阿司匹林引起NSAIDs溃疡的最主要致溃疡机制是通过小肠吸收后，抑制COX-1（A对），导致维持黏膜正常再生的前列腺素E不足，黏膜修复障碍，出现糜烂和出血。抑制COX-2的作用是减轻炎症反应（BC错）。局部作用为根据药物作用部位，无需药物吸收而在用药部位发挥的直接作用，NSAIDs溃疡是药物经小肠吸收后导致胃黏膜损伤，不属于局部作用（D错）。","","N"],["2017-N51",36,"第一节 原发性肝癌","肝内转移",2017,51,"A","","原发性肝癌早期的转移方式主要是",[["A","肝外血行转移"],["B","淋巴转移"],["C","种植转移"],["D","肝内转移"]],"D","原发性肝癌转移包括了肝内转移和肝外转移。肝脏受门静脉和肝动脉双重供血，血流丰富，原发性肝癌发生转移最早、最常见的转移方式是经门静脉在肝内转移（D对）。肝外转移又可分为：血行转移（A错），最常转移至肺；淋巴转移（B错），常见肝门淋巴结转移；种植转移（C错），比较少见。","","N"],["2017-N52",35,"第一节 肝硬化","门静脉血栓或海绵样变",2017,52,"A","","男性，53岁，肝硬化病史8年。5天来无明显原因出现腹胀，腹水迅速增加，脾脏进一步增大，体温正常。最可能发生的并发症是",[["A","原发性肝细胞癌"],["B","原发性腹膜炎"],["C","门静脉血栓形成"],["D","肝肾综合征"]],"C","中老年男性患者，肝硬化病史8年。5天来无明显原因出现腹胀，腹水迅速增加，脾脏进一步增大（门静脉血栓形成的临床表现），体温正常（排除感染）。结合病史及临床表现，该患者最可能发生的并发症是门静脉血栓形成（C对）。原发性肝细胞癌（A错）起病隐匿，早期缺乏典型症状，中晚期多表现为肝区疼痛、肝大，黄疸等。原发性腹膜炎（B错）是指腹腔内无原发病灶时引起的腹膜炎，临床症状与感染轻重有关，病情进展快者腹痛明显，伴有发热、恶心呕吐，有腹膜刺激征；起病缓慢者低热，症状较轻。肝肾综合征（D错）主因严重门静脉高压，内脏高动力循环导致体循环血量减少，患者肾脏本身无实质性病变，临床主要表现为少尿、无尿及氮质血症。","","N"],["2017-N53",40,"第四节 IgA肾病","IgA肾病诊断",2017,53,"A","","男性，25岁，因肉眼血尿2天就诊，三天前有上呼吸道感染。既往体健。查体，血压BP125/85mmHg。皮肤黏膜未见出血点和紫癜，心肺腹检查未见异常。化验尿常规蛋白++.沉渣镜检RBC满视野/HP，WBC0-3/HP，血常规Hb105g/L，WBC6.0×10⁹/L，PLT210×10⁹/L，血肌酐120umol/L。该患者可能诊断为",[["A","急性肾小球肾炎"],["B","急进性肾小球肾炎"],["C","IgA肾病"],["D","肾病综合征"]],"C","患者为青年男性，既往体健，三天（24～72小时）前有上呼吸道感染（感染史），之后出现肉眼血尿（沉渣镜检RBC满视野/HP、WBC0～3/HP）、尿常规示蛋白++（正常尿蛋白为阴性，++指尿蛋白1.0～2.0g/L、+++指尿蛋白为2.0～4.0g/L、++++指尿蛋白＞4.0g/L），血常规Hb105g/L，WBC6.0×10⁹/L（成人正常值3.5～9.5×10⁹/L），血肌酐120umol/L（男性正常值54～106umol/L，血肌酐水平略高提示患者肾损害不严重），血压BP125/85mmHg尚正常，根据其临床表现及发展过程该患者可能诊断为IgA肾病（C对）。急性肾小球肾炎（A错）多于链球菌感染后1～3周发生血尿、蛋白尿、水肿和高血压，甚至少尿及肾功能不全等急性肾炎综合征表现。急进性肾小球肾炎（B错）（十版内科学P477）临床特征为有急性肾炎综合症、肾功能急剧恶化、多在早期出现少尿性急性肾衰竭。肾病综合征（D错）（十版内科学P480）以蛋白尿（尿蛋白大于3.5g/d）、低蛋白血症（血浆白蛋白低于30g/L）、水肿及高脂血症为主要症状，蛋白尿与低蛋白血症为诊断所必需。","","N"],["2017-N54",50,"第一节 溶血性贫血概述","溶血性贫血实验室检查",2017,54,"A","","下列检查结果支持溶血性贫血的是",[["A","尿中尿胆原排泄减少"],["B","血清非结合胆红素减少"],["C","血清结合珠蛋白减少"],["D","血网织红细胞减少"]],"C","溶血性贫血时，尿中尿胆原排泄增加（A错），血清非结合胆红素升高（B错），血网织红细胞升高（D错）；各种溶血时，血清结合珠蛋白均有减低，血管内溶血时显著减低，当发生严重血管内溶血时，可监测不出血清结合珠蛋白（C对）。","","N"],["2017-N55",61,"第一节 糖尿病","T1DM的临床特点",2017,55,"A","","临床诊断Ⅰ型糖尿病的主要依据是",[["A","年轻人表现典型的三多一少症状"],["B","反复出现酮症"],["C","胰岛素分泌曲线低平"],["D","早期使用胰岛素"]],"C","Ⅰ型糖尿病胰岛β 细胞破坏，常导致胰岛素分泌不足，葡萄糖刺激后胰岛素分泌无明显升高，呈低平曲线。Ⅱ型糖尿病胰岛β 细胞胰岛素分泌不足伴胰岛素抵抗，葡萄糖刺激后胰岛素可代偿增多，呈升高曲线，即临床诊断Ⅰ型糖尿病的主要依据是胰岛素分泌曲线低平（C对）。Ⅰ型糖尿病多见于青少年患者，可以是轻度非特异性症状、典型三多一少症状或者昏迷，有自发酮症倾向，多数患者早期需要胰岛素治疗；Ⅱ型糖尿病可发生任何年龄，多见成人患者，多数患者起病隐匿，初期不需要胰岛素治疗，随着病情发展也可出现典型三多一少症状，在应激、严重感染等情况下，也可有自发酮症现象，部分患者早期也需应用胰岛素治疗控制病情。故年轻人表现典型的三多一少症状（A错）、反复出现酮症（B错）、早期使用胰岛素（D错）不能作为临床诊断Ⅰ型糖尿病和Ⅱ型糖尿病的主要鉴别依据。","","N"],["2017-N56",68,"第一节 类风湿关节炎","传统DMARDs",2017,56,"A","","下列药物属于治疗风湿病情的药物是",[["A","阿司匹林"],["B","环孢素"],["C","醋酸泼尼松"],["D","塞来昔布"]],"B","治疗类风湿关节炎（RA）的常用药物分为五大类，即非甾体抗炎药（NSAIDs）、改变病情抗风湿（DMARDs）、糖皮质激素（GC）、植物药和生物制剂等。改善病情抗风湿药包括甲氨蝶呤（MTX）、来氟米特、柳氮磺吡啶、氯喹、硫唑嘌呤、环孢素（B对）等。阿司匹林（A错）和塞来昔布（D错）属于非甾体抗炎药，可以改善关节炎症状，但不能控制病情。醋酸泼尼松（C错）为糖皮质激素，具有强大的抗炎作用，必须与DMARDs联合应用。","","N"],["2017-N68",15,"第二节 慢性心力衰竭","左心衰竭症状",2017,68,"A","","男，66岁。2个月来稍事活动即出现心悸，气短，呼吸困难，1周以来反复发生夜间憋醒，需坐起方可缓解。既往有两次急性心肌梗死病史，慢性支气管炎病史30年，吸烟40年，查体呼吸18次/分，血压140/80mmHg，高枕位，无发绀，轻度桶状胸，双肺底可闻及湿啰音，心律整，心率108次/分，第一心音低钝，A2=P2，下肢无水肿，该患者呼吸困难的类型是",[["A","肺源性"],["B","心源性"],["C","神经精神性"],["D","血源性"]],"B","66岁老年男性，2个月来稍事活动即出现心悸，气短，呼吸困难（劳力性呼吸困难），1周以来反复发生夜间憋醒，需坐起方可缓解（夜间阵发性呼吸困难），有心肌梗死病史（有基础心脏疾病），慢性支气管炎病史30年，吸烟40年，查体呼吸18次/分，血压140/80mmHg，高枕位，无发绀，轻度桶状胸，双肺底可闻及湿啰音（肺淤血），心律整，心率108次/分，第一心音低钝，A₂=P₂，根据患者的病史、临床表现、体征，该患者可诊断为心功能Ⅲ级，慢性左心衰，该患者呼吸困难的类型是心源性（B对）。心源性呼吸困难（九版诊断学P21-P22）主要是由于左心和（或）右心衰引起，尤其是左心衰竭时呼吸困难更为严重。肺源性呼吸困难（九版诊断学P21）（A错）主要是呼吸系统疾病引起的通气、换气功能障碍导致缺氧和（或）二氧化碳潴留导致。神经性呼吸困难（九版诊断学P22）（C错）是由呼吸中枢受到增高的颅内压和供血减少的刺激导致，常见于重症颅脑疾病；精神性呼吸困难（C错）是由过度通气发生呼吸性碱中毒导致，严重时可出现意识障碍，常见于焦虑症、癔症发作，是精神心理病变。血源性呼吸困难（九版诊断学P22）（D错）多由红细胞携氧减少，血氧含量降低导致，常见于重症贫血、高铁血红蛋白血症、硫化血红蛋白血症等，此外大出血或休克时，由于血容量不足血压下降、组织缺氧也会刺激呼吸中枢，出现呼吸困难。","c102","N"],["2017-N69",15,"第二节 慢性心力衰竭","左心衰竭症状",2017,69,"A","","男，66岁。2个月来稍事活动即出现心悸，气短，呼吸困难，1周以来反复发生夜间憋醒，需坐起方可缓解。既往有两次急性心肌梗死病史，慢性支气管炎病史30年，吸烟40年，查体呼吸18次/分，血压140/80mmHg，高枕位，无发绀，轻度桶状胸，双肺底可闻及湿啰音，心律整，心率108/分，第一心音低钝，A2=P2，双下肢无水肿，该患者发生呼吸困难最可能的病理生理机制是",[["A","血氧分压降低"],["B","肺泡张力增高"],["C","小支气管痉挛"],["D","肺淤血"]],"D","66岁老年男性，2个月来稍事活动即出现心悸，气短，呼吸困难（劳力性呼吸困难），1周以来反复发生夜间憋醒，需坐起方可缓解（夜间阵发性呼吸困难），有心肌梗死病史（有基础心脏疾病），慢性支气管炎病史30年，吸烟40年，查体呼吸18次/分，血压140/80mmHg，高枕位，无发绀，轻度桶状胸，双肺底可闻及湿啰音（肺淤血），心律整，心率108/分，第一心音低钝，A₂=P₂，根据患者的病史、临床表现、体征，该患者可诊断为心功能Ⅲ级，慢性左心衰。左心衰导致的呼吸困难是由于肺淤血（D对）导致肺循环毛细血管压升高，组织液聚集在肺泡和肺组织间隙中，形成肺水肿，继而导致肺泡壁毛细血管的气体交换障碍，阻碍肺的扩张和收缩，引起肺换气和肺通气功能障碍。","c102","N"],["2017-N70",48,"第一节 巨幼细胞贫血","巨幼细胞贫血诊断",2017,70,"A","","女性，42岁。2个月以来进行性乏力，头晕，心悸，纳差。查体：面色苍白，心率110次/分。血常规：Hb72g/L，MCV124fl，MCH40pg，MCHC330g/L，Ret1.0%，WBC3.4×10⁹/L，Plt85×10⁹/L。该患者可能的诊断是",[["A","缺铁性贫血"],["B","巨幼细胞性贫血"],["C","再生障碍性贫血"],["D","溶血性贫血"]],"B","中年女性，乏力，头晕，心悸，纳差2个月（巨幼细胞性贫血常见临床症状），血常规示Hb72g/L（正常女性115～150g/L），MCV124fl（正常值80-100fl），MCH40pg（正常值27-34pg），MCHC330g/L（正常值320-360g/L），Ret1.0%（正常值0.005-0.015），WBC3.4×10⁹/L，Plt85×10⁹/L（大红细胞性贫血，MCV、MCH均增高，MCHC正常，符合巨幼细胞性贫血）。结合上述临床表现和实验室检查结果，该患者可能的诊断是巨幼细胞性贫血（B对）。缺铁性贫血（A错）指原料铁缺乏所致的血红素、血红蛋白合成减少，表现为小细胞低色素性贫血。再生障碍性贫血（C错）表现为：1.骨髓多部位增生减低；2.外周血全血细胞减少；3.无肝脾肿大。溶血性贫血（D错）可分为血管内溶血和血管外溶血，多有黄疸表现。","c103","N"],["2017-N71",48,"第一节 巨幼细胞贫血","巨幼细胞贫血临床表现",2017,71,"A","","女性，42岁。2个月以来进行性乏力，头晕，心悸，纳差。查体：面色苍白，心率110次/分。血常规：Hb72g/L，MCV124fl，MCH40pg，MCHC330g/L，Ret1.0%，WBC3.4×10⁹/L，Plt85×10⁹/L。该患者还有可能出现的症状有",[["A","牛肉样舌"],["B","匙状甲"],["C","皮肤瘀斑"],["D","肝脾肿大"]],"A","中年女性，乏力，头晕，心悸，纳差2个月（贫血的常见临床表现），血常规示Hb72g/L（正常成年女性115～150g/L），MCV124fl（正常值80～100fl），MCH40pg（正常值27～34pg），MCHC330g/L（正常值320～360g/L）（MCV、MCH均增高，MCHC正常，符合巨幼细胞性贫血实验室检查），Ret1.0%（正常值百分数0.005～0.015），WBC3.4×10⁹/L（正常值3.5～9.5×10⁹/L），Plt85×10⁹/L（正常值125～350×10⁹/L）。根据该患者的临床表现和实验室检查结果，可能的诊断是巨幼细胞性贫血，巨幼细胞性贫血患者可因口腔黏膜、舌乳头萎缩而出现牛肉样舌（A对）。匙状甲（B错）多见于缺铁性贫血，表现为小细胞低色素性贫血。皮肤瘀斑（C错）多见于再生障碍性贫血，该患者血小板计数稍低，一般不会出现皮肤粘膜出血。肝脾肿大（D错）多见于慢性溶血性贫血。","c103","N"],["2017-N72",48,"第一节 巨幼细胞贫血","巨幼细胞贫血骨髓象",2017,72,"A","","女性，42岁，2个月来进行性乏力、头晕、心悸、纳差。查体：面色苍白，心率110次/分，化验血常规：Hb72g/L，MCV124fl，MCH40pg，MCHC330g/L，Ret1.0%，WBC3.4×10⁹/L，Plt85×10⁹/L。最可能支持该患者诊断的骨髓象是：",[["A","浆细胞增多"],["B","粒红倒置"],["C","核老浆幼"],["D","核幼浆老"]],"D","中年女性，乏力，头晕，心悸，纳差2个月（巨幼细胞性贫血常见临床症状），血常规示Hb72g/L（正常女性110～150g/L），MCV124fl（正常值80～100fl），MCH40pg（正常值27～34pg），MCHC330g/L（正常值320～360g/L），Ret1.0%（正常值0.005～0.015），WBC3.4×10⁹/L，Plt85×10⁹/L（大红细胞性贫血，MCV、MCH均增高，MCHC正常，符合巨幼细胞性贫血）。结合上述临床表现和实验室检查结果，该患者可能的诊断是巨幼细胞性贫血。最可能支持该患者诊断的骨髓象是核幼浆老（D对）。浆细胞增多（A错）可见于多发性骨髓瘤等。粒红倒置（B错）可见于溶血性贫血的骨髓象；核老浆幼（C错）可见于缺铁性贫血的骨髓象。","","N"],["2017-N73",9,"第一节 肺血栓栓塞症","肺血栓栓塞症动脉血气分析",2017,73,"A","","女性，45岁，术后卧床3天，突发呼吸困难、胸痛，CTPA诊断为肺栓塞。查体：R24次/分，口唇发绀，双肺呼吸音清，P₂＞A₂，左下肢肿胀。该患者最可能的血气分析结果",[["A","PaO₂降低，PaCO₂降低"],["B","PaO₂降低，PaCO₂升高"],["C","PaO₂正常，PaCO₂降低"],["D","PaO₂正常，PaCO₂升高"]],"A","患者术后卧床3天，突发呼吸困难、胸痛，CTPA诊断为肺栓塞。查体：R24次/分（呼吸急促），口唇发绀（低氧血症），双肺呼吸音清，P₂＞A₂（肺动脉瓣区第二心音亢进），左下肢肿胀。患者栓塞部位肺血流量减少，肺泡无效腔增大，肺内血流重新分布，通气/血流比例失调，可导致呼吸功能不全，产生低氧血症，而患者过度通气可导致大量CO₂弥散出血，导致低碳酸血症，因此该患者最可能的血气分析结果为PaO₂降低，PaCO₂降低（A对BCD错）。","c104","N"],["2017-N74",9,"第一节 肺血栓栓塞症","肺血栓栓塞症溶栓治疗",2017,74,"A","","女性，45岁，术后卧床3天，突发呼吸困难、胸痛，CTPA诊断为肺栓塞。查体：R24次/分，口唇发绀，双肺呼吸音清，P₂＞A₂，左下肢肿胀。下列情况，对决定患者是否采取溶栓治疗意义最大的是",[["A","低氧血症程度"],["B","血压与右心功能情况"],["C","呼吸困难程度"],["D","发病时间长短"]],"B","肺栓塞溶栓指征为中危（次大面积）PTE以上且无禁忌证患者，低危（非大面积）PTE患者不宜溶栓。患者是否为中危（次大面积）PTE主要取决于其血压和右心功能情况。因此决定该患者是否采取溶栓治疗意义最大的是血压和右心功能情况（B对）。","c104","N"],["2017-N75",9,"第一节 肺血栓栓塞症","抗凝疗程",2017,75,"A","","女性，45岁。术后卧床3天，突发呼吸困难、胸痛，CTPA诊断为肺栓塞。查体：R24次/分，口唇发绀，双肺呼吸音清，P₂＞A₂，左下肢肿胀。该患者抗凝治疗的疗程是",[["A","3～6月"],["B","大于6个月，少于12个月"],["C","12～24个月"],["D","终身接受抗凝治疗"]],"A","中年女性，术后卧床3天后出现下肢静脉血栓及肺栓塞，既往无栓塞病史，且危险因素短期可消除（临时制动），不存在长期危险因素，因此抗凝治疗的疗程约3～6个月（A对BCD错）。","c104","N"],["2017-N76",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞诊断",2017,76,"A","","男性，46岁。两个月来渐进性乏力，活动后呼吸困难。2周来上感后不能平卧，下肢水肿。既往有肺结核病史，吸烟25年。查体:T37.8、P104、R18、血压95/85mmHg，半卧位，口唇轻度发绀，颈静脉怒张，双肺未闻及干湿啰音，心界向两侧扩大，心率齐，脉搏随呼吸强弱不等，肝肋下2（cm），下肢凹陷性水肿（＋＋）。最有可能的诊断：",[["A","扩张型心肌病"],["B","急性心肌炎"],["C","心包积液"],["D","心力衰竭"]],"C","患者两个月前开始渐进乏力，活动后呼吸困难（心包积液突出临床表现），两周来上感后不能平卧，双下肢水肿，既往有结核病史（心包积液可能病因），患者心率增快、血压偏低、口唇发绀、颈静脉怒张、两侧心界扩大、脉搏随呼吸强弱不等（奇脉）、肝肋下2cm（肝大）、双下肢水肿均为心包积液症状（C对）。扩张型心肌病（A错）肺部听诊可闻及湿罗音。急性心肌炎（B错）常以心律失常为主诉或首见症状。心力衰竭（D错）为全心衰竭时，心界可向两侧扩大，但双肺应闻及湿啰音。","c105","N"],["2017-N77",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞超声心动图",2017,77,"A","","男性，46岁。两个月来渐进性乏力，活动后呼吸困难。2周来上感后不能平卧，下肢水肿。既往有肺结核病史，吸烟25年。查体：T37.8℃、H104次/分、R18次/分、血压95/85mmHg，半卧位，口唇轻度发绀，颈静脉怒张，双肺未闻及干湿啰音，心界向两侧扩大，心率齐，脉搏随呼吸强弱不等，肝肋下2（cm），下肢凹陷性水肿（＋＋）。为明确诊断，最有意义的检查是",[["A","X线胸片"],["B","心电图"],["C","超声心动图"],["D","心肌损伤标志物检测"]],"C","患者两个月前开始渐进乏力，活动后呼吸困难，两周来上感后不能平卧，双下肢水肿，既往有结核病史，患者心率增快、血压偏低、口唇发绀、颈静脉怒张、两侧心界扩大、脉搏随呼吸强弱不等（奇脉）、肝肋下2cm（肝大），结合上述病史和临床表现，患者诊断最可能为心包积液。为明确诊断，最有意义的检查是超声心动图（C对）。X线胸片（A错）可见心影增大，有助于鉴别心力衰竭。心电图（B错）可见肢体导联QRS低电压，可作为辅助诊断。心肌损伤标志物检测（D错）有助于了解患者有无心肌损伤，无法诊断心包积液。","c105","N"],["2017-N78",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞治疗",2017,78,"A","","男性，46岁。两个月来渐进性乏力，活动后呼吸困难。2周来上感后不能平卧，下肢水肿。既往有肺结核病史，吸烟25年。查体:T37.8、H104、R18、血压95/85mmHg，半卧位，口唇轻度发绀，颈静脉怒张，双肺未闻及干湿啰音，心界向两侧扩大，心率齐，脉搏随呼吸强弱不等，肝肋下2（cm），下肢凹陷性水肿（＋＋）。对该患者采取最关键的治疗措施是",[["A","应用正性肌力药物"],["B","应用静脉血管舒张剂"],["C","应用静脉心肌营养药物"],["D","心包穿刺术"]],"D","患者两个月前开始渐进乏力，活动后呼吸困难，两周来上感后不能平卧，双下肢水肿，既往有结核病史，患者心率增快、血压偏低、口唇发绀、颈静脉怒张、两侧心界扩大、脉搏随呼吸强弱不等（奇脉）、肝肋下2cm（肝大），结合上述病史和临床表现，患者诊断最可能为心包积液。对该患者采取最关键的治疗措施是心包穿刺术（D对），可迅速解除心脏压塞，且最为简单有效。应用正性肌力药物（A错）、应用静脉血管舒张剂（B错）和应用静脉心肌营养药物（C错）都不是该患者最佳治疗措施。","c105","N"],["2017-N79",26,"第一节 胃食管反流病","胃食管反流病诊断",2017,79,"A","","男性，54岁，近两个月来反酸、烧心，多于餐后出现，平卧位时明显，近5天来情况严重，有时伴有胸骨后疼痛，ECG检查未见明显异常，胃镜检查可见食管黏膜破损融合。该患者最可能的诊断是",[["A","胃食管反流病"],["B","心绞痛"],["C","食管憩室炎"],["D","食管癌"]],"A","中年男性患者，近两个月来反酸、烧心，多于餐后出现，平卧位时明显（胃食管反流病典型症状），有时伴胸骨后疼痛（胃食管反流病非典型症状），ECG检查未见明显异常（排除心源性胸痛），胃镜检查提示食管黏膜破损且有融合（胃食管反流病镜下表现），结合该患者典型临床表现和实验室检查，最可能的诊断是胃食管反流病（A对）。心绞痛（B错）发作时ECG检查常见ST段压低。食管憩室（C错）为食管壁局部膨出内壁覆盖有完整上皮的盲袋，初期可无症状，憩室增大后可出现高位咽下困难和憩室内容物反流（反流物为新鲜的、未经消化的、无苦味酸味的食物），内镜检查可见憩室开口。食管癌（D错）主要表现为进行性吞咽困难，胃镜下可发现病灶。","c106","N"],["2017-N80",26,"第一节 胃食管反流病","PPI",2017,80,"A","","男性，54岁，近两个月来反酸、烧心，多于餐后出现，平卧位时明显，近5天来情况严重，有时伴有胸骨后疼痛，ECG检查未见明显异常，胃镜检查可见食管黏膜破损融合。选用的最佳治疗是：",[["A","氢氧化铝"],["B","硝酸甘油"],["C","奥美拉唑"],["D","手术"]],"C","胃食管反流病常用药物治疗主要有促胃肠动力药、抑酸药和抗酸药。抑酸是目前治疗本病的主要措施。抑酸药包括HRA和PPI（如奥美拉唑）。在所有抑酸药中PPI抑酸作用最强，特别适用于症状重，有严重食管炎的患者。该患者内镜检查见食管黏膜破损有融合，说明有严重的食管炎，故选用的最佳治疗药物是质子泵抑制剂奥美拉唑（C对）。氢氧化铝（A错）为抗酸药，这类药物仅用于症状轻、间歇发作的患者作为临时缓解症状用。硝酸甘油（B错）为心绞痛患者常用药物，但用于食管反流病引起的胸痛无效并可加重反流症状，应避免使用。手术（D错）一般不作为首选治疗，而用于需要长期大剂量PPI维持治疗的患者，或用于由反流引起的严重呼吸道疾病的患者。","c106","N"],["2017-N81",26,"第一节 胃食管反流病","维持治疗",2017,81,"A","","男性，54岁，近两个月来反酸、烧心，多于餐后出现，平卧位时明显，近5天来情况严重，有时伴有胸骨后疼痛，ECG检查未见明显异常，胃镜检查可见食管黏膜破损融合。若持续维持治疗，选用的最佳药物是",[["A","雷尼替丁"],["B","奥美拉唑"],["C","硝酸异山梨酯"],["D","顺铂和5-氟尿嘧啶"]],"B","患者近两个月来反酸、烧心，多于餐后出现，平卧位时明显，5天来情况严重，有时伴有胸骨后疼痛，ECG检查未见明显异常，胃镜检查可见食管粘膜破损融合，可诊断为胃食管反流症。而胃食管返流症维持治疗首选的药物为PPI，选项中只有奥美拉唑（B对）为PPI制剂。雷尼替丁（A错）为抑酸制剂，也可用于胃食管反流病，但效果较质子泵抑制剂差。硝酸异山梨酯（C错）为心绞痛患者常用药物。顺铂和5-氟尿嘧啶（D错）为化疗用药。","c106","N"],["2017-N82",41,"第一节 尿路感染","定位诊断",2017,82,"A","","女性，26岁，妊娠30周，3天来腰痛伴尿频、尿痛，两天来发热，体温最高达38.6℃，既往体健，化验尿常规：蛋白（+），RBC5～10/HP，WBC20～25/HP偶见白细胞管型。患者最可能诊断是",[["A","尿道综合征"],["B","急性膀胱炎"],["C","急性肾盂肾炎"],["D","肾结核"]],"C","青年妊娠女性患者，既往体健，3天来腰痛伴尿频、尿痛（膀胱刺激征伴腰痛怀疑肾盂肾炎），2天来发热，最高体温达38.6℃（提示全身感染症状），沉渣尿检：RBC5～10/HP（提示镜下血尿），WBC20～25/HP（提示尿路感染），偶见白细胞管型（提示肾脏病变），结合患者的临床表现和实验室检查，最可能的诊断是急性肾盂肾炎（C对）。尿道综合征（A错）表现为尿频、尿痛等尿路刺激症状，但是多次检查均无真性细菌尿。急性膀胱炎（B错）表现为尿频、尿急、尿痛等膀胱刺激症状伴下腹疼痛，无发热等全身症状。肾结核（D错）表现为明显的膀胱刺激征，伴有食欲减退、消瘦、乏力、贫血等慢性消耗症状。","c107","N"],["2017-N83",41,"第一节 尿路感染","尿路感染致病菌",2017,83,"A","","女性，26岁，妊娠30周，3天来腰痛伴尿频、尿痛，两天来发热，体温最高达38.6℃，既往体健，化验尿常规：蛋白（+），RBC5～10/HP，WBC20～25/HP偶见白细胞管型。若做清洁后中段尿细菌培养，最可能的结果",[["A","未见细菌生长"],["B","大肠埃希菌"],["C","粪链球菌"],["D","结核杆菌"]],"B","青年妊娠女性，既往体健，3天来腰痛伴尿频、尿痛（膀胱刺激征），2天来发热，最高体温达38.6℃（全身症状明显），沉渣尿检：RBC5～10/HP，WBC20～25/HP（脓尿），偶见白细胞管型，根据患者的临床表现和实验室诊断，最可能的诊断是急性肾盂肾炎。而革兰阴性杆菌为尿路感染最常见致病菌，其中以大肠埃希菌最为常见，约占全部尿路感染的85%（B对ACD错）。","c107","N"],["2017-N84",41,"第一节 尿路感染","肾盂肾炎",2017,84,"A","","女性，26岁，妊娠30周，3天来腰痛伴尿频、尿痛，两天来发热，体温最高达38.6℃，既往体健，化验尿常规：蛋白（+），RBC5～10/HP，WBC20～25/HP偶见白细胞管型。最首选用的治疗",[["A","多饮水及对症治疗"],["B","静脉给予大环内酯类抗生素"],["C","抗结核治疗"],["D","静脉给予第三代头孢菌素类抗生素"]],"D","急性尿路感染包括上尿路感染和下尿路感染，上尿路感染最典型的症状包括尿路刺激征、感染中毒症状和腰部不适。下尿路感染体温一般不会超过 38℃，上尿路感染体温可以超过38℃，还可以出现少量蛋白尿，偶可见白细胞管型。治疗包括一般治疗和抗感染治疗。妊娠期尿路感染宜选用毒性小的抗菌药物，孕妇急性肾盂肾炎可静脉滴注第三代头孢菌素。本例患者为青年女性，既往体健，此次为急性起病，出现尿频、尿急的尿路刺激征，发热最高达 38.6℃（超过38℃），故诊断为妊娠期上尿路感染，最首选用静脉给予第三代头孢菌素类抗生素（D对B错）。多饮水及对症治疗（A错）为一般治疗，不是最首选的治疗。患者没有发现感染结核的症状和体征，不使用抗结核治疗（C错）。","c107","N"],["2017-N85",53,"第一节 霍奇金淋巴瘤","霍奇金淋巴瘤诊断",2017,85,"A","","女，28岁。发热伴皮肤瘙痒1周，查体：T38.2℃，轻度贫血貌，右侧颈部及右侧锁骨上各触及数个肿大淋巴结，最大者为3cm×1.5cm大小，活动，无压痛，其余浅表淋巴结均未触及肿大。化验血常规Hb90g/L，WBC9.5×10⁹/L，中性粒细胞55%，淋巴细胞35%，Plt110×10⁹/L，网织红细胞15%。骨髓涂片偶见R-S细胞。该患者最可能的诊断是",[["A","慢性淋巴细胞白血病"],["B","结核性淋巴结炎"],["C","淋巴结转移肿瘤"],["D","淋巴瘤"]],"D","青年女性患者，发热伴皮肤瘙痒（HL全身症状多见于年轻女性）1周。查体：T38.2℃，轻度贫血貌，右侧颈部及右侧锁骨上各触及数个肿大淋巴结，最大者为3cm×1.5cm大小，活动，无压痛（无痛性颈部及锁骨上淋巴结肿大常为HL首发症状），其余浅表淋巴结均未触及肿大。化验血常规Hb90g/L（成年女性正常值115～150g/L，提示轻度贫血），WBC9.5×10⁹/L，中性粒细胞55%，淋巴细胞35%，Plt110×10⁹/L，网织红细胞15%。骨髓涂片偶见R-S细胞（HL典型病理特征，提示有骨髓浸润）。综合该患者的病史、体征及实验室检查，该患者最可能的诊断是霍奇金淋巴瘤（HL）（D对）。慢性淋巴细胞白血病（A错）多见于50岁以上患者，表现为无痛性头颈部、锁骨上、腋窝及腹股沟淋巴结肿大，伴有乏力、消瘦、低热等全身症状，血常规检查白细胞多高于10×10⁹/L，淋巴细胞比例≥50%。结核性淋巴结炎（B错）早期多局限于颈的两侧，可彼此融合，与周围组织粘连，一般无全身症状，晚期由于软化、破溃而形成窦道。淋巴结转移肿瘤（C错）多来源鼻咽癌和甲状腺癌的转移，表现为颈部及锁骨上窝坚硬如石的淋巴结肿大，无发热及皮肤瘙痒等全身症状。","c108","N"],["2017-N86",53,"第一节 霍奇金淋巴瘤","霍奇金淋巴瘤病理学检查",2017,86,"A","","女，28岁。发热伴皮肤瘙痒1周，查体:T38.2℃，轻度贫血貌，右侧颈部及右侧锁骨上各触及数个肿大淋巴结，最大者为3cm×1.5cm大小，活动，无压痛，其余浅表淋巴结均未触及肿大。化验血常规Hb90g/L，WBC9.5×10⁹/L，中性粒细胞55%，淋巴细胞35%，Plt110×10⁹/L，网织红细胞15%。骨髓涂片偶见R-S细胞。对明确诊断，最具有意义的检查",[["A","PPD试验"],["B","淋巴结B超"],["C","淋巴结活检"],["D","骨髓活检"]],"C","青年女性患者，发热伴皮肤瘙痒（HL全身症状多见于年轻女性）1周。查体：T38.2℃，轻度贫血貌，右侧颈部及右侧锁骨上各触及数个肿大淋巴结，最大者为3cm×1.5cm大小，活动，无压痛（无痛性颈部及锁骨上淋巴结肿大常为HL首发症状），其余浅表淋巴结均未触及肿大。化验血常规Hb90g/L（成年女性正常值115～150g/L，提示中度贫血），WBC9.5×10⁹/L，中性粒细胞55%，淋巴细胞35%，Plt110×10⁹/L，网织红细胞15%。骨髓涂片偶见R-S细胞（HL典型病理特征，提示有骨髓浸润）。综合该患者的病史、体征及实验室检查，该患者最可能的诊断是霍奇金淋巴瘤。对明确诊断最有意义的检查为淋巴结活检（C对），切片可见典型R-S细胞，是确诊HL的主要依据。PPD（A错）用于检出结核分枝杆菌感染，而非检出结核病。淋巴结B超（B错）为形态学检查，帮助发现体检时遗漏的肿块，不能明确肿块性质。骨髓活检（D错）用于确定是否有骨髓浸润，阳性率为9%～22%。","c108","N"],["2017-N87",50,"第五节 自身免疫性溶血性贫血","温抗体型AIHA病因与发病机制",2017,87,"A","","女，28岁。发热伴皮肤瘙痒1周，查体:T38.2℃，轻度贫血貌，右侧颈部及右侧锁骨上各触及数个肿大淋巴结，最大者为3cm×1.5cm大小，活动，无压痛，其余浅表淋巴结均未触及肿大。化验血常规Hb90g/L，WBC9.5×10⁹/L，中性粒细胞55%，淋巴细胞35%，Plt110×10⁹/L，网织红细胞15%。骨髓涂片偶见R-S细胞。引起该患者贫血最可能的原因是",[["A","慢性疾病致铁代谢障碍"],["B","骨髓内肿瘤细胞浸润"],["C","营养不良"],["D","自身免疫异常"]],"D","青年女性患者，发热伴皮肤瘙痒（HL全身症状多见于年轻女性）1周。查体：T38.2℃，轻度贫血貌，右侧颈部及右侧锁骨上各触及数个肿大淋巴结，最大者为3cm×1.5cm大小，活动，无压痛（无痛性颈部及锁骨上淋巴结肿大常为HL首发症状），其余浅表淋巴结均未触及肿大。化验血常规Hb90g/L（成年女性正常值115～150g/L，提示轻度贫血），WBC9.5×10⁹/L，中性粒细胞55%，淋巴细胞35%，Plt110×10⁹/L，网织红细胞15%。骨髓涂片偶见R-S细胞（HL典型病理特征，提示有骨髓浸润）。综合该患者的病史、体征及实验室检查，该患者最可能的诊断是霍奇金淋巴瘤。该患者白细胞以中性粒细胞为主，中性粒细胞在骨髓成熟，中性粒细胞没有明显减少，且骨髓涂片偶见R-S细胞，说明患者骨髓浸润不严重（B错），同时患者网织红细胞15%，表明骨髓增生活跃，高网织红细胞也表明患者溶血，故贫血最可能的原因是自身免疫异常引起的溶血性贫血（D对）。","c108","N"],["2017-N88",59,"第一节 甲状腺功能亢进症","甲状腺毒症和甲亢的诊断",2017,88,"A","","女性，25岁，低热，乏力，心悸2周余。检查甲状腺弥漫肿大Ⅰ度，无触痛，心率110次/分钟。血液检查FT₃、FT₄明显升高，TSH明显降低。该患者最可能的诊断是",[["A","Graves病"],["B","亚急性甲状腺炎"],["C","结节性甲状腺肿"],["D","自身免疫性甲状腺炎"]],"A","青年女性患者，低热、乏力、心悸（甲亢高代谢症状）2周余。检查甲状腺弥漫肿大Ⅰ度（Graves病诊断必备条件），无触痛，心率110次/分钟。血液检查FT₃、FT₄明显升高，TSH明显降低（甲亢实验室检查指标）。综合该患者的病史、体查及实验室检查，该患者最可能的诊断是Graves病（A对）。亚急性甲状腺炎（B错）是一种与病毒感染有关的自限性甲状腺炎，起病前多有病毒感染症状，甲状腺轻度或中度肿大，触痛显著。结节性甲状腺肿（C错）血清甲状腺激素水平多正常，在甲状腺一侧或双侧可触及大小不等的结节。自身免疫性甲状腺炎（D错）早期表现为甲状腺肿，长时期表现为甲状腺功能减退，血清TT₄、FT₄降低，TSH升高。","c109","N"],["2017-N89",59,"第一节 甲状腺功能亢进症","抗甲状腺药物",2017,89,"A","","女性，25岁，低热，乏力，心悸2周余。检查甲状腺弥漫肿大Ⅰ度，无触痛，心率110次/分钟。血液检查FT₃、FT₄明显升高，TSH明显降低。该患者最恰当的治疗是",[["A","¹³¹I治疗"],["B","糖皮质激素治疗"],["C","甲巯咪唑"],["D","口服非甾体类抗炎药"]],"C","青年女性患者，低热、乏力、心悸（甲亢高代谢症状）2周余。检查甲状腺弥漫肿大Ⅰ度（Graves病诊断必备条件），无触痛，心率110次/分钟。血液检查FT₃、FT₄明显升高，TSH明显降低（甲亢实验室检查指标）。综合该患者的病史、体查及实验室检查，该患者最可能的诊断是Graves病。该患者甲状腺轻度肿大，首选抗甲状腺药物甲巯咪唑（C对）治疗，肝脏毒性较丙硫氧嘧啶小。¹³¹I（A错）多用于甲状腺肿大Ⅱ度以上或对ATD（抗甲状腺药物）过敏患者。糖皮质激素（B错）用于在治疗甲亢危象时防止肾上腺皮质低功。口服非甾体类抗炎药（D错）多用于轻型亚急性甲状腺炎的治疗，该患者甲状腺无触痛，不符合亚急性甲状腺炎的临床表现。","c109","N"],["2017-N90",59,"第一节 甲状腺功能亢进症","甲亢¹³¹I治疗适应证和禁忌证",2017,90,"A","","女性，25岁，低热，乏力，心悸2周余。检查甲状腺弥漫肿大Ⅰ度，无触痛，心率110次/分钟。血液检查FT₃、FT₄明显升高，TSH明显降低。患者经治疗后，甲状腺激素水平仍较高，症状不缓解，下一步最恰当的处理是",[["A","¹³¹I治疗"],["B","糖皮质激素加量"],["C","改服碘剂治疗"],["D","加服β受体拮抗剂"]],"A","青年女性患者，低热、乏力、心悸（甲亢高代谢症状）2周余。检查甲状腺弥漫肿大Ⅰ度（Graves病诊断必备条件），无触痛，心率110次/分钟。血液检查FT₃、FT₄明显升高，TSH明显降低（甲亢实验室检查指标）。综合该患者的病史、体查及实验室检查，该患者最可能的诊断是Graves病。国内Graves病首选抗甲状腺药物（ATD）治疗，该患者经过治疗以后，症状不改善，甲状腺激素水平仍然很高，说明ATD治疗效果不佳，需要使用¹³¹I治疗（A对），¹³¹I作用于甲状腺滤泡，减少甲状腺激素的分泌，¹³¹I治疗治愈率85%，复发率1%，适用于ATD治疗失败或不良反应严重等患者。加服 β 受体拮抗剂（D错）在 ATD 治疗初期可缓解儿茶酚胺效应，改善患者的心悸、烦躁等交感神经系统兴奋症状，减少外周组织 T₄转化为 T₃，可用于辅助治疗以及术前治疗。糖皮质激素（B错）、碘剂治疗（C错）用于甲状腺危象的治疗。","c109","N"],["2017-N91",70,"第一节 干燥综合征","干燥综合征眼科检查",2017,91,"A","","男性，52岁，近三年来口干，眼干，近一月来加重伴双膝关节疼痛，哭时无泪。查体：舌干，牙齿多个脱落，双膝关节无肿胀。化验血Hb:105g/L，WBC：3.4×10⁹/L，Plt110×10⁹/L，ANA1：320，ESR34mm/h，尿常规无异常。下列检查无帮助于该病诊断的是",[["A","Schirmer试验"],["B","腮腺造影"],["C","涎腺放射性核素扫描"],["D","双膝关节X线片"]],"D","52岁男性（干燥综合征好发年龄），近三年来口干，眼干（干燥综合征局部表现），近一月来加重伴双膝关节疼痛（骨骼表现），哭时无泪，查体：舌干（口干燥症），牙齿多个脱落（猖獗性龋齿），双膝关节无肿胀（关节无破坏），实验室检查Hb105g/L（成年男性Hb正常值130～175g/L，轻度贫血），WBC3.4×10⁹/L（成人WBC正常值3.5～9.5×10⁹/L，白细胞降低），Plt110×10⁹/L（血小板正常值125～350×10⁹/L），ANA1：320（滴度升高），ESR34mm/h（男性0～20mm/h，血沉加快），尿常规无异常，根据患者的临床表现和实验室检查，诊断为干燥综合征。干燥综合征是一种以侵犯泪腺、唾液腺等外分泌腺体，具有淋巴细胞浸润和特异性自身抗体为特征的弥漫性结缔组织病。Schirmer试验（A对）属于泪腺功能检测，腮腺造影（B对）和涎腺放射性核素扫描（C对）属于涎腺功能检查，均有助于该病的诊断，干燥综合征会有骨骼肌肉症状，但关节破坏非本病的特点，双膝关节X线片（D错，为本题正确答案）对本病的诊断无帮助。","c110","N"],["2017-N92",70,"第一节 干燥综合征","干燥综合征的腺外表现",2017,92,"A","","男性，52岁，近三年来口干，眼干，近一月来加重伴双膝关节疼痛，哭时无泪。查体：舌干，牙齿多个脱落，双膝关节无肿胀。化验血Hb：105g/L，WBC：3.4×10⁹/L，Plt110×10⁹/L，ANA1：320，ESR34mm/h，尿常规无异常。该病在皮肤的特征性表现是",[["A","紫癜样皮疹"],["B","荨麻疹样皮疹"],["C","结节样红斑"],["D","环形红斑"]],"A","52岁男性（干燥综合征好发年龄），近三年来口干，眼干（干燥综合征局部表现），近一月来加重伴双膝关节疼痛（骨骼表现），哭时无泪，查体：舌干（口干燥症），牙齿多个脱落（猖獗性龋齿），双膝关节无肿胀（关节无破坏），实验室检查Hb105g/L（成年男性Hb正常值130～175g/L，轻度贫血），WBC3.4×10⁹/L（成人WBC正常值3.5～9.5×10⁹/L，白细胞降低），Plt110×10⁹/L（血小板正常值125～350×10⁹/L），ANA1：320（滴度升高），ESR34mm/h（男性0～15mm/h，血沉加快），尿常规无异常，根据患者的临床表现和实验室检查，诊断为干燥综合征。干燥综合征是一种以侵犯泪腺、唾液腺等外分泌腺体，具有淋巴细胞浸润和特异性自身抗体为特征的弥漫性结缔组织病。该病在皮肤的特征性表现是紫癜样皮疹（A对）。荨麻疹样皮疹（B错）多见于皮肤过敏反应。结节样红斑（C错）多见于感染及贝赫切特病。环形红斑（D错）多见于风湿性疾病。","c110","N"],["2017-N128",16,"第三节 房性心律失常","抗凝治疗",2017,128,"B","","男，66岁，高血压4年，半年前房颤，超声心动图示左房大，选用的治疗",[["A","溶栓治疗"],["B","介入取栓治疗"],["C","抗凝治疗"],["D","抗血小板治疗"]],"C","房颤患者的栓塞发生率较高，抗凝治疗是其重要的治疗内容，本例房颤患者66岁老年男性（CHA₂DS₂-VASc评分1分），高血压病史（CHA₂DS₂-VASc评分1分），左房增大（左心室功能障碍，CHA₂DS₂-VASc评分1分），CHA₂DS₂-VASc评分3分（≥2分），选用的治疗为抗凝治疗（C对）。CHA₂DS₂-VASc评分≥2分者，需抗凝治疗，评分为1分者，权衡疗效和风险，优选抗凝治疗，0分不需抗凝治疗。有关该评分系统，十版内科学有内容更新（P202），以前使用CHADS₂评分简单易行，但对脑卒中低危病人的评估不够准确，目前临床上多采用CHA₂DS₂-VASc评分系统。溶栓治疗（A错）介入取栓治疗（B错）多用于栓塞后的治疗，该患者尚未发生栓塞事件，不需以上治疗。抗血小板治疗（D错）可防止血栓形成，可能有助于血管栓塞性疾病，抗凝作用较小。","","N"],["2017-N129",17,"第四节 急性冠状综合征","抗血小板治疗",2017,129,"B","","男，72岁，一周前急性前壁心梗，PCI治疗，左房前降支植入药物洗脱支架，选用治疗",[["A","溶栓治疗"],["B","介入取栓治疗"],["C","抗凝治疗"],["D","抗血小板治疗"]],"D","老年男性患者，前壁心梗1周，并植入药物洗脱支架，应选用双联抗血小板治疗（D对）。溶栓治疗（A错）介入取栓治疗（B错）多用于栓塞后的治疗，该患者已行动脉支架治疗，以上二者均不必重复使用。抗凝治疗（C错）不用于急性心梗支架术后。","","N"],["2017-N130",75,"第一节 中毒概述","金属中毒解毒药",2017,130,"B","","铅中毒时的解毒药物",[["A","依地酸钙钠"],["B","二巯丙醇"],["C","纳洛酮"],["D","亚甲蓝"]],"A","铅中毒时的解毒药物是依地酸钙钠（A对）。二巯丙醇（B错）是金属离子砷、汞、锑中毒的解毒药。纳洛酮（C错）是阿片类麻醉药的解毒药。亚甲蓝（D错）是亚硝酸盐、苯胺或硝基苯等中毒引起的高铁血红蛋白血症的解毒药。","","N"],["2017-N131",75,"第一节 中毒概述","中枢神经抑制剂解毒药",2017,131,"B","","阿片类中毒的解毒药物",[["A","依地酸那钙"],["B","二巯丙醇"],["C","纳洛酮"],["D","亚甲蓝"]],"C","阿片类中毒的解毒药物是纳洛酮（C对）。依地酸那钙（A错）是铅中毒时的解毒药物。二巯丙醇（B错）是金属离子砷、汞、锑中毒的解毒药。亚甲蓝（D错）是亚硝酸盐、苯胺或硝基苯等中毒引起的高铁血红蛋白血症的解毒药。","","N"],["2017-N154",10,"第三节 慢性肺源性心脏病","控制感染",2017,154,"X","","下列属于慢性肺源性心脏病急性加重期的治疗原则有",[["A","积极控制感染"],["B","积极利尿"],["C","积极应用正性肌力药"],["D","积极处理并发症"]],"AD","慢性肺心病是由于肺部疾病引起肺动脉高压，最终导致的心脏的结构和功能的改变。慢性肺心病急性加重常由呼吸系统感染引起，需积极控制感染（A对）。慢性肺心病患者一般在积极控制感染及改善呼吸功能后，心衰症状便能得到改善，不需要常规应用利尿药（B 错）及正性肌力药（C错）。慢性肺心病可伴发肺性脑病、电解质紊乱、心律失常等并发症，需积极处理并发症（D对）。","","N"],["2017-N155",19,"第二节 扩张型心肌病","扩张型心肌病心电图",2017,155,"X","","扩张型心肌病患者辅助检查可出现的异常结果有",[["A","心电图可见病理Q波"],["B","超声心动图可呈现二尖瓣反流"],["C","核素检查心肌可有灶性放射性减低"],["D","心室造影可出现室壁矛盾运动"]],"ABC","扩张型心肌病（DCM）是由各种病因引起的一组非均质的心肌病变。表现为心室不适当的肥厚或扩张。心电图检查缺乏诊断特异性，改变以心脏肥大、心肌损害和心律失常为主，少数可有病理性Q波（A对）。超声心动图早期可见到心腔轻度扩大，尤其是左心室，后期各心室均扩大，室壁运动普遍减弱，二尖瓣、三尖瓣收缩期不能退至瓣环水平，彩色血流多普勒显示二尖瓣反流（B对）。DCM核素心肌扫描可见室壁运动弥漫性减弱，可见散在灶性放射性减低（C对），三版八年制内科学（P373）说法为，运动或药物负荷心肌显像可 用于除外冠状动脉疾病引起的缺血性疾病，核素血池扫描可见舒张末期和收缩末期左心室容积增大，左心室射血分数降低，但一般不用于心功能评价。心室造影可出现室壁矛盾运动（D错）是室壁瘤的典型特征。","","N"],["2017-N156",30,"第一节 溃疡性结肠炎","溃疡性结肠炎并发症",2017,156,"X","","溃疡性结肠炎的并发症可有",[["A","中毒性巨结肠"],["B","癌变"],["C","肠出血"],["D","肠穿孔"]],"ABCD","溃疡性结肠炎的并发症最常见的为中毒性巨结肠（A对）（5%）和直肠结肠癌变（B对）（多见于病程漫长者），此外还有结肠出血（C对）（3%）和肠穿孔（D对）（并发于中毒性巨结肠）。","","N"],["2017-N157",44,"第一节 急性肾损伤","肾脏替代治疗",2017,157,"X","","重症急性肾衰竭透析治疗的方法有",[["A","间歇性血液透析"],["B","连续性动-静脉血液滤过"],["C","连续性静-静脉血液滤过"],["D","腹膜透析"]],"ABC","急性肾衰竭患者出现了严重高血钾症（＞6.5mmol/L）、代谢性酸中毒（pH＜7.2）、容量负荷过重对利尿剂治疗无效、心包炎和严重脑病等都是透析治疗指征，属于重症急性肾衰竭。采用透析治疗方法可选择腹膜透析、间歇性血液透析（A对）或连续性肾脏替代治疗。其中连续性肾脏替代治疗包括连续性静-静脉血液滤过（C对）、连续性静-静脉血液透析、连续性静-静脉血液透析滤过、连续性动静脉血液滤过（B对）、连续动静脉血液透析滤过等一系列方法。腹膜透析重症急性肾衰竭治疗中已少采用（D错），因其透析效率较差且有发生腹膜炎的风险，但在经济欠发达地区以及灾难性事件导致大量患者需要治疗时，仍可采用腹膜透析治疗。","","N"],["2017-N158",55,"","",2017,158,"X","","可引起PT延长而TT正常的凝血因子缺陷有",[["A","纤维蛋白原"],["B","凝血酶原"],["C","凝血因子Ⅶ"],["D","凝血因子Ⅷ"]],"BC","PT指在被检血浆中加入Ca²⁺和组织因子或组织凝血活酶，观测到血浆的凝固时间。PT延长见于先天性I（纤维蛋白原）、Ⅱ（B对）、Ⅴ、Ⅶ（C对）、Ⅹ缺乏。凝血酶时间（TT）是测定在受检血浆中加入标准化凝血酶溶液，到开始出现纤维蛋白丝所需要的时间。纤维蛋白原（A错）缺乏，TT和PT均会延长。凝血因子Ⅷ（D错）为内源性凝血途径的因子，不参与外源性凝血途径，因此，若缺乏凝血因子Ⅷ，则PT和TT均正常。","","N"],["2017-N159",61,"第二节 糖尿病酮症酸中毒","补液",2017,159,"X","","下列治疗措施中，易引起低钾血症的有：",[["A","糖尿病酮症酸中毒大量补碱"],["B","糖尿病酸中毒使用大剂量胰岛素"],["C","Graves眼病采用大剂量糖皮质激素冲击治疗"],["D","糖尿病高血糖使用大剂量双胍类药物"]],"ABC","引起低钾血症的原因有很多，大致可分为摄入不足、丢失过多、分布异常。糖尿病酮症酸中毒大量补碱（A对）易引起低钾血症属于钾分布异常，机制为大量补碱导致碱中毒，H⁺从细胞内溢出细胞外，细胞外K⁺进入细胞内，同时肾小管上皮也发生此种离子转移，H⁺-Na⁺交换减弱，K⁺-Na⁺交换增强，尿钾排出增多。糖尿病酸中毒使用大剂量胰岛素（B对）易引起低钾血症，属于钾分布异常，机制为胰岛素可直接激活细胞膜上Na⁺-K⁺-ATP酶的活性，使细胞外钾转入细胞内，另一方面可促使细胞糖原合成，使细胞外钾随葡萄糖转入细胞内。以上两种方式导致的低血钾均为细胞外钾转入细胞内，但机体的总钾量并不减少。Graves眼病采用大剂量糖皮质激素冲击治疗（C对）引起低钾血症属于钾丢失过多，由于糖皮质激素（GC）能促进肾远曲小管和集合管保Na⁺排K⁺，采用大剂量糖皮质激素冲击治疗，经肾脏排出的钾增多，导致低钾血症。糖尿病高血糖使用大剂量双胍类药物（D错）引起乳酸性酸中毒，血钾常升高或正常。","","N"],["2018-N41",48,"第一节 巨幼细胞贫血","巨幼细胞贫血血象",2018,41,"A","","巨幼细胞贫血患者外周血红细胞的形态特征是",[["A","大椭圆形"],["B","球形"],["C","靶形"],["D","镰刀形"]],"A","巨幼红细胞贫血是DNA合成障碍所致的贫血，主要原因是叶酸或维生素B₁₂缺乏、某些影响核苷酸代谢药物、遗传因素等导致DNA合成障碍，本病呈大红细胞性贫血，细胞体积增大，胞核发育滞后于胞质，形成巨幼变，患者外周血红细胞形态特征呈大椭圆形（A对），且中央苍白区缩小，中性粒细胞核分叶过多。球形（B错）红细胞见于遗传性球形红细胞增多症（十版内科学P561）。靶形（C错）红细胞见于α地中海贫血（十版内科学P563）。镰刀形（D错）红细胞可见于镰刀形红细胞贫血症、恶性肿瘤所致贫血等（十版内科学P564）。","","N"],["2018-N42",21,"第二节 主动脉瓣反流","主动脉瓣反流临床表现",2018,42,"A","","可能在心尖部听到舒张期隆隆样杂音的病变是",[["A","动脉导管未闭"],["B","室间隔缺损"],["C","主动脉瓣关闭不全"],["D","肺动脉瓣关闭不全"]],"C","可能在心尖部出现舒张期隆隆样杂音的病变是主动脉瓣关闭不全（C对），系主动脉关闭不全严重时，反流束冲击二尖瓣前侧叶，将二尖瓣前侧叶推起处于较高位置，影响其开放，引起相对性二尖瓣狭窄，在心尖部出现舒张期隆隆样杂音（P299）。该杂音属于二尖瓣功能性杂音（非器质性二尖瓣狭窄杂音），主要见于中、重度主动脉瓣关闭不全。动脉导管未闭（A）最突出的体征是胸骨左缘第2肋间有响亮的连续性机器声样杂音，几乎占据整个收缩期与舒张期，在收缩期末最响亮并伴有震颤，分流较大患者可闻及心尖区舒张期杂音（相对性二尖瓣狭窄）等（九版外科学P285、实用外科学P1444），但较主动脉关闭不全，后者更易闻及心尖部出现舒张期隆隆样杂音。室间隔缺损（B）产生的杂音为胸骨左缘第2～4肋间粗糙、响亮的全收缩期杂音（九版外科学P289），在分流量大时，也可出现相对性二尖瓣狭窄，心尖部可闻及舒张期隆隆样杂音。单纯肺动脉瓣关闭不全（D错）少见，多由于肺动脉总干扩张导致相对性关闭不全导致的功能性杂音，为肺动脉瓣区舒张早期递减型哈气样杂音，伴有肺动脉高压时，肺动脉瓣听诊区第二心音亢进、分裂，反流量较大时，三尖瓣区可闻及收缩前期低调杂音（实用内科学P1531）。该题AB选项也正确，但参考答案为C选项。","","N"],["2018-N43",2,"第一节 支气管哮喘","支气管哮喘临床表现",2018,43,"A","","支气管哮喘有别于心源性哮喘的临床表现是",[["A","咳嗽、咳痰"],["B","多于夜间发作"],["C","呼气性呼吸困难，可自行缓解"],["D","双肺可闻及哮鸣音"]],"C","支气管哮喘由多种刺激因素刺激炎症细胞引起，多见于青少年有过敏史者。心源性哮喘系由左心衰竭引起的呼吸困难（夜间阵发性呼吸困难），多见于器质性心脏病患者（为避免混淆，目前已经不再使用“心源性哮喘”一词）。支气管哮喘与心源性哮喘都可出现咳嗽（A错）、常于夜间发作（B错）及双肺哮鸣音（D错）等临床表现，但支气管哮喘病人咳黏液痰，心源性哮喘病人则常咳粉红色泡沫痰。支气管哮喘发作时典型症状为伴有哮鸣音的呼气性呼吸困难，可经平喘药物治疗后缓解或自行缓解，心源性哮喘（夜间阵发性呼吸困难）系患者入睡后突然因憋气而惊醒，被迫取坐位，重者可有哮鸣音，多于端坐休息后缓解，故支气管哮喘有别于心源性哮喘的临床表现是呼气性呼吸困难，可自行缓解（C对）。二者临床表现相似，测定血浆BNP水平对鉴别心源性和支气管性哮喘有较大的参考价值。","","N"],["2018-N44",9,"第一节 肺血栓栓塞症","肺血栓栓塞症溶栓治疗",2018,44,"A","","肺栓塞患者应考虑溶栓治疗的指征是",[["A","低血压或晕厥"],["B","剧烈胸痛"],["C","低氧血症"],["D","咯血"]],"A","肺栓塞溶栓治疗最主要的目的是缓解循环障碍，肺栓塞患者应考虑溶栓治疗的指征是低血压或晕厥、休克等循环障碍症状（A对），出现循环障碍时除溶栓外没有其他治疗方式可以缓解患者症状，溶栓治疗可以迅速融解部分或全部血栓，恢复肺组织再灌注，减小肺动脉阻力，降低肺动脉压，改善右心室功能，减少严重肺栓塞患者的病死率和复发率。咯血（D错）属于溶栓治疗的绝对禁忌证（致命性大面积肺栓塞时为相对禁忌证）。剧烈胸痛和低氧血症不伴有血压和右心功能障碍时，不宜溶栓，单纯剧烈胸痛（B错）和低氧血症（C错）不能作为溶栓治疗的指征，对于低氧血症，可以通过机械通气解决。","","N"],["2018-N45",8,"第四节 其他间质性肺疾病","过敏性肺炎诊断",2018,45,"A","","支气管肺泡灌洗液检查为以淋巴细胞增高为主，且以CD8⁺淋巴细胞为主的疾病是",[["A","结节病"],["B","特发性肺纤维化"],["C","肺泡蛋白沉积症"],["D","过敏性肺炎"]],"D","支气管肺泡灌洗液检查时淋巴细胞增高为主的疾病应考虑过敏性肺炎、结节病，过敏性肺炎（D对）主要以CD8⁺淋巴细胞增高为主，CD4⁺/CD8⁺＜1或正常，结节病以CD4⁺淋巴细胞增高为主（A错），CD4⁺/CD8⁺的比值增加（＞3.5）。特发性肺纤维化（B错）主要以中性粒细胞及嗜酸性细胞增高为主，淋巴细胞增高不明显。肺泡蛋白沉积症（C错）以肺泡腔内积聚大量的表面活性物质为特征，支气管肺泡灌洗液呈典型乳白色或浓稠浅黄色液体，可有PAS（过碘酸希夫）染色阳性物质，淋巴细胞和浆细胞比例增高。","","N"],["2018-N46",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺军团病治疗",2018,46,"A","","男性，48岁。外出旅行后出现发热、咳嗽、咳痰伴乏力、腹泻5天。查体：血压120/76mmHg，神志清楚，双下肺可闻及湿性啰音。化验血白细胞12.0×10⁹/L，中性87%。血钠126mmol/L。胸片提示双下肺斑片状影。外院予“头孢呋辛”静脉治疗3天，自觉症状无好转，复查胸片显示双肺阴影较前增多。应首选的治疗药物是",[["A","青霉素"],["B","头孢曲松"],["C","亚胺培南/西司他丁"],["D","阿奇霉素"]],"D","48岁男性（符合军团菌肺炎的发病年龄），外出旅游后出现发热、咳嗽、咳痰，乏力，腹泻5天（符合军团菌肺炎的外出旅游史和早期症状）。查体：血压 126/70mmHg，神志清楚，双下肺可闻及湿啰音（符合军团菌肺炎的典型体征）。血常规：白细胞12×10⁹/L（正常值为3.5～9.5×10⁹/L），中性粒 87%，血钠 126mmol/L（正常值为137～147mmol/L，血钠偏低），胸片：双下肺斑片状阴影（符合军团菌肺炎的典型影像学表现），外院头孢呋辛静脉治疗3天后，自觉症状无好转（β内酰胺类药物作用无效，提示该致病菌细胞无细胞壁），复查胸片肺部阴影较前增多。综合该患者的病史、临床表现、实验室检查和影像学检查，考虑诊断为军团菌肺炎，首选大环内酯类抗生素如红霉素、阿奇霉素（D对）等。青霉素（A错）、头孢曲松（B 错）均为β-内酰胺类抗生素，作用于细菌体内的青霉素结合蛋白（PBPs），抑制细胞壁的合成，而军团菌属于胞内寄生菌，β-内酰胺类及氨基糖苷类药物无法穿透细胞膜，对军团菌肺炎治疗效果很差，故对此两种抗生素不敏感。亚胺培南/西司他丁（泰能）（C错）为β-内酰胺类抗生素的复方制剂，抗菌谱广、抗菌作用强，主要用于G⁺和G⁻需氧菌和厌氧菌所致的各种严重感染，不可口服，仅供注射用，一般不作首选用药。","","N"],["2018-N47",16,"第四节 房室交界性心律失常","急性发作期",2018,47,"A","","男性，62岁。1周前患广泛前壁心肌梗死、左心功能不全，未接受冠脉介入治疗。4小时前突发心动过速，心电图示A型预激综合征伴心房颤动，心室率156次/分，应首选的治疗药物是",[["A","毛花苷C"],["B","美托洛尔"],["C","普罗帕酮"],["D","胺碘酮"]],"D","62岁老年男性心梗后心功能不全突发a型预激综合症伴心房颤动，电传导通路为房室结前向传导，旁路逆向传导，故应选择延长旁路不应期的药物，该患者房颤合并器质性心脏病和心衰，胺碘酮为首选（D），但房颤合并预激综合征，更合理的首选治疗为对房室旁路行射频消融。普罗帕酮（C）属于ⅠC类抗心律失常药，通过减慢Vmax，减慢传导、轻微延长动作电位时程，用于各种室上性心动过速，但对心脏抑制作用较强，加重心衰，对合并器质性心脏病患者慎用，不作为首选。毛花苷c（A错）属于洋地黄制剂，减慢房室结传导，缩短旁路不应期使心室率加快，易诱发室颤，不宜单独用于曾经发作心房颤动或扑动的患者。美托洛尔（B错）属于β受体拮抗剂，有心脏负性作用，急性心衰时禁用，不作为首选。（根据10版内科学P208：预激伴房颤（房扑）的病人，终止心动过速首选电复律，或静脉注射伊布利特或普罗帕酮，不应使用β受体拮抗剂、维拉帕米、地尔硫䓬、洋地黄类药物和胺碘酮，因为这些抗心律失常药可能抑制房室结传导从而加剧旁道下传，有诱发室颤的风险，但该患者有器质性心脏病，普罗帕酮仅禁用于器质性心脏病患者，故本题无正确答案）。","","N"],["2018-N48",18,"第一节 原发性高血压","原发性高血压诊断",2018,48,"A","","女性，48岁。发现高血压8年，最高达180/100mmHg，坚持口服吲达帕胺，血压基本正常。1周前患急性胃肠炎，后感发作性心悸、胸闷，明显乏力，查BP 140/85mmHg。心电图检查示：心率82次/分，频发室性期前收缩，二联律。该患者1周来病情变化最可能的原因是",[["A","并发急性心肌炎"],["B","并发低钾血症"],["C","冠状动脉缺血"],["D","血压控制不满意"]],"B","48岁中年女性，高血压8年，最高达180/140mmHg，坚持口服吲达帕胺控制血压（吲达帕胺为利尿药，长期使用不良反应是低血钾），一周前急性肠胃炎（低血钾加重诱因），后感心悸发作，胸闷，明显乏力（室性期前收缩临床表现），查血压140/85mmHg（血压控制情况尚可）（D错），心电图：心率82次/分，频发室性期前收缩，二联律，一周前引起病情变化的主要原因是并发低血钾（B对）。室性期前收缩常见于高血压、冠心病、心肌病、风湿性心脏病等心脏疾病，低血钾易诱发室性期前收缩。心肌炎是心肌的炎症性疾病，最常见的原因是病毒感染，急性心肌炎（A错）发病前1～3周有病毒感染前驱症状，如发热、全身倦怠感和肌肉酸痛等，心率可增快，且和体温不相称，重症患者可出现心源性休克症状。冠状动脉血供不足（C错）最常见的病因是冠状动脉狭窄，急剧短暂的缺血缺氧引起心绞痛，持续严重的心肌缺血可引起心肌梗死。","","N"],["2018-N49",16,"第三节 房性心律失常","抗凝治疗",2018,49,"A","","下列关于持续性心房颤动患者应用华法林抗凝治疗的方法，正确的是",[["A","80岁以上患者禁用"],["B","心房内径正常者可暂时不用"],["C","一旦并发心力衰竭应及时减量"],["D","需长期持续应用"]],"D","心房颤动最大的并发症就是血栓栓塞，是房颤主要的致残和致死原因，无论是在房颤时或在药物或电复律前均需要进行抗凝治疗。心房持续性颤动患者用华法林进行抗凝治疗，需长期持续使用（D对），使凝血酶原时间国际标准比值（INR）维持在2.0～3.0，能安全而有效预防脑卒中发生。80岁以上患者CHADS₂评分=2（根据新指南推荐的CHA₂DS₂VASc积分，年龄≥75岁为2分），老年房颤患者并发血栓栓塞的年发病率达5%，为非房颤患者的6倍，主张应用华法林抗凝治疗（A错）。根据CHADS₂评分（或CHA₂DS₂VASc积分）心房内径不作为积分项，不能单纯根据心房内径大小来判断是否应用抗凝治疗（B错）。并发心力衰竭患者CHADS₂评分=1，应根据实际情况考虑接受华法林抗凝治疗，而不是减量（C错）。有关该评分系统，十版内科学有内容更新（P202），以前使用 CHADS₂评分简单易行，但对脑卒中低危病人的评估不够准确，目前临床上多采用CHA₂DS₂-VASc评分系统。","","N"],["2018-N50",27,"第二节 慢性胃炎","Hp感染",2018,50,"A","","多灶萎缩性胃窦炎最主要的病因是",[["A","胆汁反流"],["B","口服非甾体抗炎药"],["C","幽门螺杆菌感染"],["D","自身免疫性抗体"]],"C","多灶萎缩性胃窦炎（B型胃炎），病变主要位于胃窦部，主要病因是幽门螺杆菌感染（C对），胆汁反流（A错）、口服非甾体抗炎药（B错）是化学性胃病（C型胃炎）的病因（三版8年制病理学P257）。自身免疫性抗体（D错）是自身免疫性胃炎（A型胃炎）的病因（三版8年制病理学P257）。","","N"],["2018-N51",28,"第一节 消化性溃疡","球后溃疡",2018,51,"A","","球后溃疡的临床特点是",[["A","上腹痛常无典型的节律性"],["B","午夜痛和背部放射痛多见"],["C","对药物治疗反应较好"],["D","不易并发出血"]],"B","球后溃疡一般指发生于十二指肠降段、水平段的溃疡，多发生在十二指肠降段的初始部及乳头附近，溃疡多在后内侧壁，约占消化性溃疡5%，常为慢性，可穿透入胰腺（十版内科学P375）。球后溃疡多具有十二指肠球部溃疡的临床特点，但症状较一般十二指肠溃疡严重而持续，且夜间疼痛和背部放射痛更为多见（B对A错），内科治疗效果较差，对药物治疗反应较差（C错），较易并发出血（D错）。","","N"],["2018-N52",35,"第一节 肝硬化","及早识别及去除HE发作的诱因",2018,52,"A","","男性，51岁。肝硬化病史4年，发生呕血、黑便2天，半天来出现意识模糊和躁动入院。为清除该患者的肠道内积血，最宜选用的灌肠液是",[["A","弱酸性液"],["B","弱碱性液"],["C","肥皂水"],["D","温开水"]],"A","51岁男性患者，肝硬化病史4年（肝性脑病病因），发生上消化道出血（肝性脑病诱因），半天来出现意识模糊和躁动入院（肝性脑病2期症状），根据该患者的既往史、临床表现可诊断为肝性脑病，为清除该患者的肠道内积血，最宜选用的肠道灌洗液是弱酸性液（A对B错）。上消化道出血是肝性脑病的重要诱因之一，需要积极止血，可采取以下措施：乳果糖、乳梨醇或25%硫酸镁口服或鼻饲导泻，生理盐水或弱酸液清洁灌肠。肠道酸化后可使肠道细菌产氨减少，酸性的肠道环境可减少氨的吸收，并促进血液中的氨渗入肠道排除体外。肥皂水（C错）用于中毒（腐蚀性毒物除外）时清除体内毒物的灌肠，或功能性便秘的灌肠治疗。温开水（D错）多用于洗胃。","","N"],["2018-N53",45,"第一节 慢性肾衰竭","水、电解质代谢紊乱",2018,53,"A","","尿毒症患者以碳酸氢钠静脉滴入纠正代谢性酸中毒时，发生手足搐搦的机制是",[["A","血钠增高继发脑水肿"],["B","血钙总量降低"],["C","血中游离钙降低"],["D","血中结合钙降低"]],"C","游离钙有维持神经系统稳定性的作用，尿毒症患者以碳酸氢钠静脉注射滴入纠正代谢性酸中毒时，游离钙转变为结合钙的形式存在，血中游离钙降低（C对）。游离钙的下降导致膜功能下降，钠离子进入细胞增多，阈电位绝对值增大，更容易达到阈电位，兴奋性增高，发生手足抽搐。故在临床上用碳酸氢钠或乳酸钠纠正酸中毒时，要注意防止低钾和低钙。","","N"],["2018-N54",52,"第二节 急性白血病","急性白血病细胞遗传学和分子生物学检查",2018,54,"A","","女性，26岁。因乏力、皮下瘀斑2周诊断急性髓细胞白血病入院。化验血：白细胞15×10⁹/L，血红蛋白83g/L，血小板15×10⁹/L；骨髓检查见原始粒细胞占65%，早幼粒细胞占2%，其他各阶段粒细胞占18%，单核细胞占12%。该白血病患者已行染色体检查，最可能出现的染色体异常是",[["A","t（8；21）（q22；q22）"],["B","t（9；22）（q34；q11）"],["C","t（15；17）（q22；q21）"],["D","t（16；16）（p13；q22）"]],"A","26岁女性患者，因乏力、皮下瘀斑2周诊断急性髓系白血病入院。化验：白细胞15×10⁹/L（正常成人白细胞3.5～9.5×10⁹/L），血红蛋白83g/L（正常成年女性血红蛋白115～150g/L），血小板15×10⁹/L（正常成人血小板125～350×10⁹/L）。骨髓：原始粒65%（30%～89%），早幼粒2%，其他18%（≥10%），单核12%（＜20%），根据患者的实验室检查，可诊断为急性髓系白血病M₂型，M₂型异常染色体表现为t（8；21）（q22；q22）（A对）。t（9；22）（q34；q11）（B错）为急性淋巴细胞白血病的异常染色体表现。t（15；17）（q22；q21）（C错）为M₃（急性早幼粒细胞白血病）的异常染色体表现。t（16；16）（p13；q22）（D错）为M₄Eo的表现。","","N"],["2018-N55",59,"第一节 甲状腺功能亢进症","肌肉骨骼系统",2018,55,"A","","甲状腺毒症性周期性瘫痪的临床特点，正确的是",[["A","多见于亚洲青年女性"],["B","与甲亢疾病的严重程度相平行"],["C","高碳水化合物饮食可诱发"],["D","为不对称性肢体软瘫"]],"C","甲状腺毒症周期性瘫痪主要见于亚洲青年男性患者（A错），发病诱因包括饱餐、高糖饮食（C对）、运动等，病变主要为双上肢、双下肢及躯干发作性软瘫（D错），以双下肢瘫痪更为常见，严重时可有呼吸肌麻痹，伴有腱反射消失，发作可持续数小时至数日，常伴有低血钾，呈自限性，甲亢控制后可以自愈，发作频数个体差异很大，目前麻痹的发生机制不明，可能与过多甲状腺激素促进钠钾泵的活性，引起钾离子向细胞内转移有关。根据现有临床证据，周期性麻痹的发病与甲亢的病程和严重程度无明显关系，但与甲亢的控制与否有关（B错）。","","N"],["2018-N56",68,"第一节 类风湿关节炎","类风湿关节炎血液学改变",2018,56,"A","","与类风湿关节炎病情活动性无关的实验室检查结果是",[["A","血红蛋白降低"],["B","血小板减少"],["C","血沉增快"],["D","RF滴度增高"]],"B","类风湿关节炎（RA）是以侵蚀性、对称性关节炎为主要临床表现的慢性、全身性自身免疫疾病，实验室检查有助于RA的诊断、评价疾病活动性及预后，血常规常有轻至中度贫血（A对），白细胞及分类多正常，活动期患者血小板可增高（B错，为本题正确答案），血沉（ESR）是最常用的检测炎症或病情活动的指标，血沉（ESR）（C对）和C反应蛋白（CRP）常升高，类风湿因子（RF）（D对）见于约70%的患者血清，其滴度一般与RA的活动性和严重性成比例。","","N"],["2018-N68",35,"第一节 肝硬化","食管胃底静脉曲张出血",2018,68,"A","","男性，48岁。2小时前参加婚宴后感上腹不适、恶心，随即呕吐大量混有残食的鲜血约500ml，伴头晕、心悸。近年来常感上腹不适、乏力。查体：体型消瘦，面色晦暗，蜘蛛痣（+），巩膜轻度黄染，肝肋下未及，移动性浊音阳性，肠鸣音活跃。患者最可能的出血病因是",[["A","食管贲门黏膜撕裂出血"],["B","胃溃疡伴出血"],["C","上消化道肿瘤伴出血"],["D","食管静脉曲张破裂出血"]],"D","中年男性，近年来常感上腹不适、乏力（肝功能减退临床表现），查体可见体型消瘦，面色晦暗（营养不良），蜘蛛痣（+）（内分泌失调体征），巩膜轻度黄染，肝肋下未及，移动性浊音阳性（肝硬化失代偿期典型体征），两小时前参加婚宴后感上腹不适、恶心（消化道出血诱因），随即呕吐混有残食的鲜血约500ml（呕血），伴头晕、心悸，肠鸣音活跃（上消化道出血的典型表现），根据患者临床表现和体征，最可能的诊断为肝硬化门静脉高压并发的食管胃底静脉破裂出血（D对）。食管贲门上黏膜撕裂出血（A错）多有剧烈呕吐的诱因，且发病前无肝硬化失代偿的一系列临床表现。胃溃疡伴出血（B错）的上腹部不适为慢性过程、周期性发作、季节性、与进餐相关的节律性上腹痛，腹痛可被抑酸或抗酸剂缓解，不会出现肝硬化失代偿期表现，且并发出血时出血量及速度不及食管胃底静脉破裂出血剧烈。上消化道肿瘤伴出血（C错）多有肿瘤相关性症状，不会出现蜘蛛痣、肝病面容等肝硬化失代偿期的表现。","c114","N"],["2018-N69",35,"第一节 肝硬化","EGVB及门静脉高压性胃肠病",2018,69,"A","","男性，48岁。2小时前参加婚宴后感上腹不适、恶心，随即呕吐大量混有残食的鲜血约500ml，伴头晕、心悸。近年来常感上腹不适、乏力。查体：体型消瘦，面色晦暗，蜘蛛痣（+），巩膜轻度黄染，肝肋下未及，移动性浊音阳性，肠鸣音活跃。对判断该患者是否继续存在活动性出血最有价值的体征是",[["A","面色晦暗"],["B","巩膜轻度黄染"],["C","移动性浊音阳性"],["D","肠鸣音活跃"]],"D","中年男性，近年来常感上腹不适、乏力（肝功能减退临床表现），查体可见体型消瘦，面色晦暗（营养不良），蜘蛛痣（+）（内分泌失调体征），巩膜轻度黄染，肝肋下未及，移动性浊音阳性（肝硬化失代偿期典型体征），两小时前参加婚宴后感上腹不适、恶心（消化道出血诱因），随即呕吐混有残食的鲜血约500ml（呕血），伴头晕、心悸，肠鸣音活跃（上消化道出血的典型表现），根据患者临床表现和体征，最可能的诊断为肝硬化门静脉高压并发的食管胃底静脉破裂出血。判断消化道活动性出血的指标有：①反复呕血或黑粪次数增多、粪质稀薄，肠鸣音活跃（D对）；②周围循环状态经充分补液及输血后未见明显改善，或虽暂时好转而又继续恶化；③血红蛋白浓度、红细胞计数与血细胞比容继续下降，网织红细胞计数持续增高；④补液与尿量足够的情况下，血尿素氮持续或再次增高（十版内科学P461）。面色晦暗（A错）为肝硬化失代偿期病人的肝病面容，不能说明有活动性出血。巩膜轻度黄染（B错）为肝硬化失代偿期黄疸的表现，不能说明有活动性出血。移动性浊音阳性（C错）为肝硬化失代偿期腹水的表现，亦不能说明有活动性出血。","c114","N"],["2018-N70",11,"第二节 气胸","气胸诊断",2018,70,"A","","男性，21岁。2小时前进行举重训练，在用力举起杠铃时突发左胸痛，随即出现进行性呼吸困难、出汗、心悸，急送校医院。查体：脉搏微弱，频率120次/分，呼吸浅而快，频率24～30次/分，BP 90/60mmHg，神清，烦躁不安，高枕右侧卧，口唇轻绀，颈静脉怒张。患者应考虑的主要疾病是",[["A","肺气肿"],["B","气胸"],["C","肺栓塞"],["D","急性胸膜炎"]],"B","青年男性，持重物（自发性气胸诱因）后突发左胸痛，随即出现进行性呼吸困难，出汗，心悸（自发性气胸典型症状）。脉搏微弱，心率快，呼吸浅快，血压90/60mmHg，神清，烦躁不安，高枕右侧卧，口唇发绀，颈静脉怒张（自发性气胸体征），由此判断患者最可能的诊断为气胸（B对）。肺气肿（A错）多见于并发慢性支气管炎慢阻肺的老年人，一般无胸痛，且呼吸困难多为长期缓慢进行性加重。肺栓塞（C错）患者除有胸痛、呼吸困难的表现，还有咯血、低热、晕厥等症状，多有下肢或盆腔血栓性静脉炎、骨折、手术等促进血栓形成的基础性疾病。急性胸膜炎（D错）起病相对较缓，不会出现突发胸痛及进行性呼吸困难。","c115","N"],["2018-N71",11,"第二节 气胸","气胸体征",2018,71,"A","","男性，21岁。2小时前进行举重训练，在用力举起杠铃时突发左胸痛，随即出现进行性呼吸困难、出汗、心悸，急送校医院。查体：脉搏微弱，频率120次/分，呼吸浅而快，频率24～30次/分，BP 90/60mmHg，神清，烦躁不安，高枕右侧卧，口唇轻绀，颈静脉怒张。下列最能支持患者主要疾病的体征是",[["A","气管左偏"],["B","左肺叩浊、呼吸音减弱"],["C","左肺呼吸音消失"],["D","双肺叩诊过清音"]],"C","青年男性，持重物（自发性气胸诱因）后突发左胸痛，随即出现进行性呼吸困难，出汗，心悸（自发性气胸典型症状）。脉搏微弱，心率快，呼吸浅快，血压90/60mmHg，神清，烦躁不安，高枕右侧卧，口唇发绀，颈静脉怒张（自发性气胸体征），由此判断患者最可能的诊断为气胸。为了减轻呼吸困难，患者一般都会呈气胸侧向上的卧位，故考虑左侧为患侧，右侧为健侧。自发性气胸的典型表现为突发的一侧剧烈胸痛，查体气管向健侧移位（A错），患侧肺受压导致呼吸运动减弱，听诊呼吸音减弱或消失（C对），患侧叩诊过清音或鼓音（BD错）。患者血压较低，不能平卧，考虑积气量较大，肺压缩程度较重，呼吸音应当消失而非减弱（B错）。","c115","N"],["2018-N72",11,"第二节 气胸","气胸X线胸片检查",2018,72,"A","","男性，21岁。2小时前进行举重训练，在用力举起杠铃时突发左胸痛，随即出现进行性呼吸困难、出汗、心悸，急送校医院。查体：脉搏微弱，频率120次/分，呼吸浅而快，频率24～30次/分，BP 90/60mmHg，神清，烦躁不安，高枕右侧卧，口唇轻绀，颈静脉怒张。为确诊应首先选用的辅助检查是",[["A","胸部B超"],["B","胸部X线片"],["C","胸部CT"],["D","肺动脉造影"]],"B","青年男性，持重物（自发性气胸诱因）后突发左胸痛，随即出现进行性呼吸困难，出汗，心悸（自发性气胸典型症状）。脉搏微弱，心率快，呼吸浅快，血压90/60mmHg，神清，烦躁不安，高枕右侧卧，口唇发绀，颈静脉怒张（自发性气胸体征），由此判断患者最可能的诊断为气胸，首选检查为X线，可显示肺受压程度，肺内病变情况以及有无胸膜粘连、胸腔积液及纵隔移位等（B对）；胸部CT（C错）表现为胸膜腔内出现极低密度的气体影，伴有肺组织不同程度的萎缩改变，但一般不作为首选；胸部B超（A错）检查可用于胸腔积液的诊断与穿刺定位以及紧贴胸膜病变的引导穿刺等，由于易受气体干扰，不用于气胸的诊断。肺动脉造影（D错）用于肺血栓栓塞症的诊断。","c115","N"],["2018-N73",3,"第一节 支气管扩张症","支气管扩张诊断",2018,73,"A","","男性，36岁。间断咳嗽、咳黄脓痰20余年，3天前出现发热，痰中少量带血。幼年时曾患百日咳。患者最可能的诊断是",[["A","慢性阻塞性肺疾病"],["B","支气管扩张症"],["C","肺结核"],["D","肺脓肿"]],"B","患者青年男性（支气管扩张常见人群），长期慢性咳嗽、咳脓痰病史（支气管扩张的典型症状），既往百日咳病史（支气管扩张的诱因），根据患者既往史、临床表现，可能的诊断是支气管扩张（B对）。慢性阻塞性肺疾病（A错）多发生于中老年患者，主要表现为持续气流受限，病情呈进行性发展，与慢性支气管炎和肺气肿关系密切，气短或者呼吸困难为慢阻肺的标志性症状。肺结核（C错）患者常有低热、盗汗、乏力、消瘦等结核毒性症状。肺脓肿（D错）多有误吸等诱因，急性起病，表现为高热、寒战、咳大量脓痰、胸痛。有关支气管扩张症的诱发因素，十版内科学有内容更新（P41）。","","N"],["2018-N74",3,"第一节 支气管扩张症","胸部高分辨率CT扫描",2018,74,"A","","男性，36岁。间断咳嗽、咳黄脓痰20余年，3天前出现发热，痰中少量带血。幼年时曾患百日咳。为明确诊断，最有意义的检查是",[["A","肺功能"],["B","胸部X线片"],["C","胸部HRCT"],["D","支气管镜"]],"C","患者青年男性（支气管扩张常见人群），长期慢性咳嗽、咳脓痰病史（支气管扩张的典型症状），既往百日咳病史（支气管扩张的诱因），根据患者既往史、临床表现，可能的诊断是支气管扩张，最有意义的检查是胸部HRCT（C对），HRCT为无创检查，可在横断面上清楚显示扩张的支气管，表现为“戒指征”或“指套征”，且重复性良好，是目前支气管扩张的首选影像学检查。肺功能（A错）可反映肺的通气及弥散功能，但并不能明确病变性质。胸部X线（B错）平片检查时，在部分病变显著患者可表现为显著的囊腔，腔内可存在气液平，但囊腔内无气液平面时，很难与大疱性肺气肿或严重肺间质病变的蜂窝肺鉴别。支气管镜（D错）在部分支气管局灶性扩张的患者可发现弹坑样变，作为有创侵入性检查，一般不作首选。","","N"],["2018-N75",3,"第一节 支气管扩张症","控制感染",2018,75,"A","","男性，36岁。间断咳嗽、咳黄脓痰20余年，3天前出现发热，痰中少量带血。幼年时曾患百日咳。根据诊断，目前最佳的处理方法是",[["A","吸氧"],["B","抗感染"],["C","止血"],["D","体位引流"]],"B","患者青年男性（支气管扩张常见人群），长期慢性咳嗽、咳脓痰病史（支气管扩张的典型症状），既往百日咳病史（支气管扩张的诱因），根据患者既往史、临床表现，可能的诊断是支气管扩张，慢性病程急性发作，表现为发热、咳痰（感染征象），需积极抗感染治疗（B对）。患者目前无呼吸困难、憋喘等乏氧表现，暂时不需要吸氧（A错）。患者痰中少量带血，出血量较少，暂不需止血治疗（C错）。患者痰中少量带血，且能够咳出，体位引流（D错）可作为抗生素治疗的辅助治疗。有关支气管扩张症抗感染治疗的有关叙述，十版内科学有内容更新。","","N"],["2018-N76",19,"第二节 扩张型心肌病","扩张型心肌病诊断",2018,76,"A","","男性，55岁。外院诊断心力衰竭3年来院。既往有吸烟史。查体：BP 110/70mmHg，口唇稍绀，颈静脉充盈，双肺底均可闻及湿啰音，心界向两侧扩大，心率96次/分，心律整，心前区可闻及3/6级收缩期吹风样杂音，双下肢水肿（++）。心电图示窦性心律、完全性左束支传导阻滞；超声心动图示左房、左室、右室扩大，左室壁变薄伴弥漫性运动减弱及运动不协调，LVEF 32%；NTpro-BNP 7109pg/ml（正常值＜190 pg/ml）。患者心力衰竭最可能的病因是",[["A","扩张型心肌病"],["B","冠状动脉性心脏病"],["C","肺源性心脏病"],["D","风湿性心瓣膜病"]],"A","患者男性，55岁，既往心力衰竭3年。口唇稍绀，颈静脉充盈，双肺底均闻及湿啰音（提示左心衰导致的肺淤血），心脏向两侧扩大（扩张性心肌病的典型特征），心前区可闻及3/6级收缩期吹风样杂音（心腔扩大导致的瓣膜在收缩期不能退至瓣环水平而关闭不全），超声心动图示左心室、左心房、右心室扩大，心室壁变薄，室壁运动弥漫性减弱（扩张性心肌病超声心动图表现，心脏扩大导致的心肌缺血），LEVF32％（正常值＞50%），NTpro-BNP 7109pg/ml（正常值＜190pg/ml），N末端脑钠肽（NT-proBNP）升高有助于鉴别扩张性心肌病与其他原因导致的呼吸困难，根据患者既往史、临床表现、影像学检查和实验室检查结果，最可能的诊断是扩张性心肌病（A对）。冠状动脉性心脏病（B错）是冠状动脉发生粥样硬化引起管腔狭窄或闭塞，导致心肌缺血缺氧或坏死，短暂的缺血缺氧表现为心绞痛，严重持续的心肌缺血可导致心肌梗死，冠心病患者多有高血压、高血脂和糖尿病等易感因素。肺源性心脏病（C错）是慢阻肺的并发症，是肺血管床减少及缺氧致肺动脉收缩、血管重塑，导致肺动脉高压，右心室肥厚扩大，最终发生右心功能不全。风湿性心脏病（D错）有溶血性链球菌感染史，在典型症状出现前1～6周常有咽喉炎或扁桃体炎等，有心脏炎表现，早期有窦性心动过速（入睡后心率＞100次/分），超声心动图可见心包积液，严重时可有充血性心力衰竭，心脏超声有助于诊断。","c116","N"],["2018-N77",19,"第二节 扩张型心肌病","扩张型心肌病超声心动图",2018,77,"A","","男性，55岁。外院诊断心力衰竭3年来院。既往有吸烟史。查体：BP 110/70mmHg，口唇稍绀，颈静脉充盈，双肺底均可闻及湿啰音，心界向两侧扩大，心率96次/分，心律整，心前区可闻及3/6级收缩期吹风样杂音，双下肢水肿（++）。心电图示窦性心律、完全性左束支传导阻滞；超声心动图示左房、左室、右室扩大，左室壁变薄伴弥漫性运动减弱及运动不协调，LVEF 32%；NTpro-BNP 7109pg/ml（正常值＜190 pg/ml）。上述病情资料中，对判断病因诊断最有价值的检查结果是",[["A","ECG示窦性心律、完全性左束支传导阻滞"],["B","LVEF 32%"],["C","超声心动图示心腔扩大、室壁薄、弥漫性运动减弱"],["D","NT-proBNP 7109pg/ml"]],"C","患者男性，55岁，既往心力衰竭3年。口唇稍绀，颈静脉充盈，双肺底均闻及湿啰音（提示左心衰导致的肺淤血），心脏向两侧扩大（扩张性心肌病的典型特征），心前区可闻及3/6级收缩期吹风样杂音（心腔扩大导致的瓣膜在收缩期不能退至瓣环水平而关闭不全），超声心动图示左心室、左心房、右心室扩大，心室壁变薄，室壁运动弥漫性减弱（扩张性心肌病超声心动图表现，心脏扩大导致的心肌缺血），LEVF32％（正常值＞50%），NTpro-BNP 7109pg/ml（正常值＜190pg/ml），N末端脑钠肽（NT-proBNP）升高有助于鉴别扩张性心肌病与其他原因导致的呼吸困难，根据患者既往史、临床表现、影像学检查和实验室检查结果，最可能的诊断是扩张性心肌病，超声心动图是诊断及评估DCM最常用的重要检查手段，超声心动图示左室薄弥漫运动减弱（C对）最有助于DCM的诊断。完全左束支传导阻滞（A错）可见于充血性心衰、急性心肌梗死、急性感染、奎尼丁和普鲁卡因中毒、高血压性心脏病、风心病、冠心病与梅毒性心脏病。射血分数降低（B错）常见于大面积严重心肌病变，如心梗等，各种原因引起的心肌收缩功能降低、心肌舒张功能障碍、心脏各部分舒缩互动不协调，都会导致心脏射血分数降低（泵血功能下降）。NT-proBNP（N末端脑钠肽）（D错）与心衰严重程度相关，是DCM心衰诊断的重要依据，有助于鉴别扩张性心肌病与其他原因导致的呼吸困难。","c116","N"],["2018-N78",19,"第二节 扩张型心肌病","利尿剂",2018,78,"A","","男性，55岁。外院诊断心力衰竭3年来院。既往有吸烟史。查体：BP 110/70mmHg，口唇稍绀，颈静脉充盈，双肺底均可闻及湿啰音，心界向两侧扩大，心率96次/分，心律整，心前区可闻及3/6级收缩期吹风样杂音，双下肢水肿（++）。心电图示窦性心律、完全性左束支传导阻滞；超声心动图示左房、左室、右室扩大，左室壁变薄伴弥漫性运动减弱及运动不协调，LVEF 32%；NT-proBNP 7109pg/ml（正常值＜190 pg/ml）。在患者目前的治疗中，不宜选用的药物是",[["A","比索洛尔"],["B","托拉塞米"],["C","螺内酯"],["D","单硝酸异山梨酯"]],"A","患者男性，55岁，既往心力衰竭3年。口唇稍绀，颈静脉充盈，双肺底均闻及湿啰音（提示左心衰导致的肺淤血），心脏向两侧扩大（扩张性心肌病的典型特征），心前区可闻及3/6级收缩期吹风样杂音（心腔扩大导致的瓣膜在收缩期不能退至瓣环水平而关闭不全），超声心动图示左心室、左心房、右心室扩大，心室壁变薄，室壁运动弥漫性减弱（心脏扩大导致的心肌缺血），LEVF32％（正常值>50%）降低，N末端脑钠肽（NTpro-BNP）7109pg/ml（正常值＜190pg/ml）明显升高。综上各指标可知患者为扩张性心肌病，心电图示窦性心律，左束支完全性传导阻滞，β受体阻滞剂为负性肌力药，使用会使心衰加重，故如今这名患者最不适宜的治疗是应用比索洛尔（A错，为本题正确答案）。托拉塞米（B对）为利尿剂，螺内酯（C对）为醛固酮受体拮抗剂，单硝酸异山梨酯（D对）为扩血管药，均有助于扩张性心肌病及慢性心衰的治疗。","c116","N"],["2018-N79",32,"第二节 肠易激综合征","肠易激综合征诊断与鉴别诊断",2018,79,"A","","男性，32岁。间断发作下腹痛、腹胀伴腹泻或便秘3年余，下腹痛不重，多于排便后缓解，粪便常有黏液，无脓血。3周来再次发作下腹痛伴腹泻，大便2～4次/天，粪便性状同前。体格检查除下腹部有轻度压痛外，其余未见异常。粪便常规、隐血及培养均未发现明显异常。患者最可能的诊断是",[["A","肠结核"],["B","克罗恩病"],["C","肠易激综合征"],["D","溃疡性结肠炎"]],"C","患者男性，32岁（中青年），间歇发作下腹痛、腹胀伴腹泻或便秘3年余（症状反复发作，病程慢性迁延），粪便常有粘液，无脓血（腹泻型IBS粪便特点），体格检查除下腹部有轻度压痛外，其余未见异常，粪便常规、隐血及培养均未见明显异常（排除感染等病因），根据患者既往史、临床表现和实验室检查，最可能的诊断是肠易激综合征（C对），肠易激综合征（IBS）是一种以腹痛或腹部不适伴有排便习惯改变为特征而无器质性病变的常见功能性肠病。肠结核（A错）也多见于中青年，但肠结核常并发肠梗阻，有结核病史，常伴有低热、盗汗、乏力等结核中毒症状（十版内科学P383）。克罗恩病（B错）常为痉挛性阵痛伴肠鸣音增加，且常伴有肠梗阻、肛周病变与瘘管形成（十版内科学P392）。溃疡性结肠炎（D错）患者多有粘液脓血便，有时可触及痉挛的降结肠或乙状结肠（十版内科学P388）。","c117","N"],["2018-N80",32,"第二节 肠易激综合征","肠易激综合征诊断与鉴别诊断",2018,80,"A","","男性，32岁。间断发作下腹痛、腹胀伴腹泻或便秘3年余，下腹痛不重，多于排便后缓解，粪便常有黏液，无脓血。3周来再次发作下腹痛伴腹泻，大便2～4次/天，粪便性状同前。体格检查除下腹部有轻度压痛外，其余未见异常。粪便常规、隐血及培养均未发现明显异常。为确定诊断，最有意义的检查是",[["A","PPD试验"],["B","腹部B超"],["C","钡剂灌肠"],["D","结肠镜"]],"D","患者男性，32岁（中青年），间歇发作下腹痛、腹胀伴腹泻或便秘3年余（症状反复发作，病程慢性迁延），粪便常有粘液，无脓血（腹泻型IBS粪便特点），体格检查除下腹部有轻度压痛外，其余未见异常，粪便常规、隐血及培养均未见明显异常（排除感染等病因），根据患者既往史、临床表现和实验室检查，最可能的诊断是肠易激综合征，肠易激综合征（IBS）是一种以腹痛或腹部不适伴有排便习惯改变为特征而无器质性病变的常见功能性肠病，检查应重在排除器质性病变，一般而言，在仔细体格检查的基础上，应常规进行全血细胞计数、大便潜血和镜检、肝功能检查、红细胞沉降率和乙状结肠镜活检（D对）。PPD试验（A错）即结核菌素试验，常用于结核分枝杆菌检查。B超检查（B错）对空腔脏器的检查效果较差，空腔脏器内气体对回声影响大，肠道系统含气量较多不宜应用。钡剂灌肠（C错）常用于肠梗阻、肠瘘。","c117","N"],["2018-N81",32,"第二节 肠易激综合征","解痉剂",2018,81,"A","","男性，32岁。间断发作下腹痛、腹胀伴腹泻或便秘3年余，下腹痛不重，多于排便后缓解，粪便常有黏液，无脓血。3周来再次发作下腹痛伴腹泻，大便2～4次/天，粪便性状同前。体格检查除下腹部有轻度压痛外，其余未见异常。粪便常规、隐血及培养均未发现明显异常。可选择的治疗是",[["A","口服抗结核药"],["B","口服柳氮磺胺吡啶"],["C","口服匹维溴铵"],["D","口服布地奈德"]],"C","患者男性，32岁（中青年），间歇发作下腹痛、腹胀伴腹泻或便秘3年余（症状反复发作，病程慢性迁延），粪便常有粘液，无脓血（腹泻型IBS粪便特点），体格检查除下腹部有轻度压痛外，其余未见异常，粪便常规、隐血及培养均未见明显异常（排除感染等病因），根据患者既往史、临床表现和实验室检查，最可能的诊断是肠易激综合征，肠易激综合征（IBS）是一种以腹痛或腹部不适伴有排便习惯改变为特征而无器质性病变的常见功能性肠病，肠易激综合征主要是对症治疗，常用解痉药、止泻药、泻药、抗抑郁药、肠道微生态制剂。匹维溴铵（C对）为能选择性作用于胃肠道平滑肌的钙通道阻滞剂，能舒张胃肠道平滑肌，解除痉挛。抗结核药物用于结核的治疗（A错）。柳氮磺胺吡啶（B错）通过偶氮键连接于磺胺吡啶，使之能通过胃，进入肠道，在肠道发挥抗炎作用，而肠易激综合征是一种功能性肠病，不需要抗炎。布地奈德（D错）是糖皮质激素，溃疡性结肠炎病变局限于直肠者灌肠使用（十版内科学P394），另外吸入型布地奈德可用于支气管哮喘的长期治疗（十版内科学P35）。","c117","N"],["2018-N82",41,"第一节 尿路感染","定位诊断",2018,82,"A","","女性，26岁。尿频、尿急、尿痛伴腰痛3天。既往体健。查体：T 36.8℃，心肺未见异常，腹软，肝脾肋下未触及，双肾区无叩击痛。化验：尿蛋白（±），亚硝酸盐还原试验阳性，沉渣镜检白细胞 20～30/HP，红细胞5～10/HP。患者最可能的诊断是",[["A","急性膀胱炎"],["B","急性肾盂肾炎"],["C","慢性肾盂肾炎"],["D","尿道综合征"]],"A","26岁女性患者（育龄期女性，尿路感染的易感人群，无感染中毒症状，提示下尿路感染可能性大），伴尿频、尿急、尿痛（尿路刺激征，提示泌尿系感染可能），硝酸盐还原实验阳性，白细胞20～30/HP、红细胞5～10/HP（脓尿，提示泌尿系感染），根据患者既往史、临床表现、实验室检查，诊断考虑急性膀胱炎（A对）。急性膀胱炎（A对）一般仅表现为尿路刺激征，一般无全身感染中毒症状，少数患者可有发热，但体温不超过38.0℃（注：在病例分析题中，临床表现符合尿道感染时，体温超过38.0℃，一般考虑为肾盂肾炎，而低于38℃考虑诊断为膀胱炎）（B错）。慢性肾盂肾炎（C错）（十版内科学P501）临床表现较复杂，全身及泌尿系统局部症状可不典型，可仅表现为无症状性菌尿，需结合病史，半数以上的患者可有急性肾盂肾炎病史，后出现不同程度的低热、间歇性尿频、排尿不适、腰部酸痛和肾小管功能受损表现（夜尿增多、低比重尿等），急性发作症状明显与急性肾盂肾炎类似，持续发展严重时可发展为慢性肾衰竭。尿道综合征（十版内科学P502）（D错）常见于女性，患者可有尿路刺激征及排尿不适等尿路刺激症状，但多次检查均无真性细菌尿，其亚硝酸盐还原试验阴性。","c118","N"],["2018-N83",41,"第一节 尿路感染","尿细菌学检查",2018,83,"A","","女性，26岁。尿频、尿急、尿痛伴腰痛3天。既往体健。查体：T 36.8℃，心肺未见异常，腹软，肝脾肋下未触及，双肾区无叩击痛。化验：尿蛋白（±），亚硝酸盐还原试验阳性，沉渣镜检白细胞 20～30/HP，红细胞5～10/HP。下列尿检查结果支持该诊断的是",[["A","可见白细胞管型"],["B","尿乙酰-β-D-氨基葡萄糖苷酶（NAG）升高"],["C","清洁中段尿培养有大肠埃希菌"],["D","尿比重和渗透压下降"]],"C","26岁女性患者（育龄期女性，尿路感染的易感人群，无感染中毒症状，提示下尿路感染可能性大），伴尿频、尿急、尿痛（尿路刺激征，提示泌尿系感染可能），硝酸盐还原实验阳性，白细胞10～20/HP、红细胞5～10/HP（脓尿，提示泌尿系感染），根据患者既往史、临床表现、实验室检查，诊断考虑急性膀胱炎，急性膀胱炎属于下尿路感染，清洁中段尿培养大肠埃希菌阳性多提示膀胱炎（C对）。尿检有白细胞管型（A错）、NAG阳性（B错）、尿比重和渗透压下降（D错）都提示是上尿路感染。","c118","N"],["2018-N84",41,"第一节 尿路感染","急性膀胱炎",2018,84,"A","","女性，26岁。尿频、尿急、尿痛伴腰痛3天。既往体健。查体：T 36.8℃，心肺未见异常，腹软，肝脾肋下未触及，双肾区无叩击痛。化验：尿蛋白（±），亚硝酸盐还原试验阳性，沉渣镜检白细胞 20～30/HP，红细胞5～10/HP。此时最主要的处理是",[["A","对症治疗及多饮水"],["B","单剂量抗生素疗法"],["C","短疗程抗生素疗法"],["D","10～14天抗生素疗法"]],"C","26岁女性患者（育龄期女性，尿路感染的易感人群，无感染中毒症状，提示下尿路感染可能性大），伴尿频、尿急、尿痛（尿路刺激征，提示泌尿系感染可能），硝酸盐还原实验阳性，白细胞10～20/HP、红细胞5～10/HP（脓尿，提示泌尿系感染），根据患者既往史、临床表现、实验室检查，诊断考虑急性膀胱炎，目前最主要的处理抗感染治疗——短疗程抗生素疗法（C对），有良好的依从性、花费低和副作用发生率低的优势，与单剂量疗法相比，短疗程疗法更有效；耐药性并无增高；可减少复发，增加治愈率（B错）。对症治疗多饮水属于一般治疗（A错）。10～14天抗生素疗法（D错）为肾盂肾炎病情较轻者的治疗措施。","c118","N"],["2018-N85",56,"第二节 原发免疫性血小板减少症","急症处理",2018,85,"A","","女性，31岁。5天来无明显原因发现四肢皮肤出血点伴牙龈出血，1天来间断鼻出血。查体见口腔颊黏膜血疱。急诊化验血Plt 8×10⁹/L，临床诊断为特发性血小板减少性紫癜（ITP）。该患者应首选的紧急治疗不包括",[["A","静滴地塞米松"],["B","静滴免疫球蛋白"],["C","静滴长春新碱"],["D","血小板成分输注"]],"C","31岁女性患者（ITP高发人群），患者近1天，间断性鼻出血，查体见口腔黏膜出血疱，出血量加重，PLT8×10⁹/L（＜9.5×10⁹/L，属于重症ITP），有颅内致命性出血的风险，属ITP急症，需紧急处理。血小板成分输注可迅速提高血小板数量防止颅内出血，应作为首选（D对）。此外急症的处理还包括静脉输注丙种球蛋白（B对）和大剂量甲泼尼龙。ITP的一线治疗首选糖皮质激素（A），但地塞米松起效较慢，A选项不够严谨。长春新碱（C错，为本题正确答案）为ITP二线治疗，糖皮质激素治疗无效时可考虑，不用于急症的处理。","c119","N"],["2018-N86",56,"第二节 原发免疫性血小板减少症","原发免疫性血小板减少症临床表现",2018,86,"A","","女性，31岁。5天来无明显原因发现四肢皮肤出血点伴牙龈出血，1天来间断鼻出血。查体见口腔颊黏膜血疱。急诊化验血Plt 8×10⁹/L，临床诊断为特发性血小板减少性紫癜（ITP）。目前的临床症状中，提示该患者颅内出血风险最大的表现是",[["A","间断鼻出血"],["B","牙龈出血"],["C","四肢皮肤出血点"],["D","口腔颊黏膜血疱"]],"D","31岁女性患者（ITP高发人群），患者近1天，间断性鼻出血，查体见口腔黏膜出血疱，出血量加重，PLT8×10⁹/L（＜9.5×10⁹/L，属于重症ITP），临床诊断为ITP（特发性血小板减少性紫癜），ITP患者出血为血小板减少所致，一定程度上与血小板计数有关，血小板数在（20～50）×10⁹/L之间轻度外伤即可引起出血，少数为自发性出血，如瘀斑瘀点等，血小板数小于20×10⁹/L有严重出血危险。皮肤紫癜、瘀斑、瘀点多见，多为全身性，下肢为多，分布均匀（C错），静脉穿刺点周围可见瘀斑，一般无关节或皮下血肿，可有鼻（A错）、牙龈（B错）及口腔黏膜出血，口腔血疱（D对）见于严重血小板减少，应警惕颅内出血（十四版实用内科学P2484）。","c119","N"],["2018-N87",56,"第二节 原发免疫性血小板减少症","骨髓象",2018,87,"A","","女性，31岁。5天来无明显原因发现四肢皮肤出血点伴牙龈出血，1天来间断鼻出血。查体见口腔颊黏膜血疱。急诊化验血Plt 8×10⁹/L，临床诊断为特发性血小板减少性紫癜（ITP）。下列实验室检查结果支持该诊断的是",[["A","血白细胞减少，血红蛋白正常"],["B","抗核抗体阳性，抗磷脂抗体阳性"],["C","凝血时间延长，血块收缩良好"],["D","骨髓巨核细胞增多，产板型减少"]],"D","31岁女性患者（ITP高发人群），患者近1天，间断性鼻出血，查体见口腔黏膜出血疱，出血量加重，PLT8×10⁹/L（＜9.5×10⁹/L，属于重症ITP），临床诊断为ITP（特发性血小板减少性紫癜），ITP患者血小板减少，骨髓呈增生象，巨核细胞数可正常或增多，有成熟障碍，产板型巨核细胞数目明显减少（D对）。ITP可有程度不等的正常细胞或小细胞低色素性贫血（A错）。抗核抗体阳性，抗磷脂抗体阳性（B错）多见于系统性红斑狼疮患者（SLE），部分ITP 患者可检测到心磷脂抗体，但无诊断特异性。凝血时间（CT）反映的是内源性凝血系统的功能，与血小板无关，ITP患者CT正常；血小板参与血块收缩，ITP患者血小板减少，因此血块收缩不良（C错）。","c119","N"],["2018-N88",60,"第五节 嗜铬细胞瘤","嗜铬细胞瘤诊断",2018,88,"A","","女性，32岁。发现持续性高血压3年，血压为150～160/90～100mmHg，常因情绪激动、体位改变时诱发血压增高，最高可达210/110mmHg，伴头痛、心悸、出汗。口服多种降压药物疗效不佳。查体：T 36.7℃，P 90次/分，BP 158/95mmHg，甲状腺（-），双肺（-），心界不大，心律不整，可闻期前收缩5～6次/分，心尖部S1增强，腹部未闻及血管杂音，下肢不肿。患者最可能的诊断是",[["A","原发性高血压"],["B","原发性醛固酮增多症"],["C","嗜铬细胞瘤"],["D","肾动脉狭窄"]],"C","青年女性患者（嗜铬细胞瘤多发人群），持续高血压三年，血压为150～160/90～100mmHg（正常成年人高值血压120～139/80～89mmHg），常因情绪激动，体位变动（常见诱因）诱发高血压，血压最高为210/110mmHg（发作时血压骤升），伴头痛、心悸、出汗（交感神经过度兴奋表现），口服多种降压药疗效不明显（持续性高血压阵发性加剧临床表现）。查体：P95次/分，血压158/95mmHg，心律不整，可闻及期前收缩5～6次/分，心前区S₁亢进（嗜铬细胞瘤心脏表现），根据患者既往史、临床表现、查体结果，最可能的诊断为嗜铬细胞瘤（C对）。原发性高血压（A错）通常不会有明显的交感神经过度兴奋表现，口服降压药通常可控制。原发性醛固酮增多症（B错）亦不会出现交感神经过度兴奋表现，且常有神经肌肉障碍及肾脏病变表现如多尿、口渴等。肾动脉狭窄（D错）除了出现难以控制的高血压，常在体检时于上腹部或背部肋脊角处闻及血管杂音。","c120","N"],["2018-N89",60,"第五节 嗜铬细胞瘤","嗜铬细胞瘤影像学检查",2018,89,"A","","女性，32岁。发现持续性高血压3年，血压为150～160/90～100mmHg，常因情绪激动、体位改变时诱发血压增高，最高可达210/110mmHg，伴头痛、心悸、出汗。口服多种降压药物疗效不佳。查体：T 36.7℃，P 90次/分，BP 158/95mmHg，甲状腺（-），双肺（-），心界不大，心律不整，可闻期前收缩5～6次/分，心尖部S1增强，腹部未闻及血管杂音，下肢不肿。对患者确诊最有价值的检查是",[["A","超声心动图"],["B","肾及肾上腺CT"],["C","肾动脉B超"],["D","腹部X线片"]],"B","青年女性患者（嗜铬细胞瘤多发人群），持续高血压三年，血压为150～160/90～100mmHg（正常成年人高值血压120～139/80～89mmHg），常因情绪激动，体位变动（常见诱因）诱发高血压，血压最高为210/110mmHg（发作时血压骤升），伴头痛、心悸、出汗（交感神经过度兴奋表现），口服多种降压药疗效不明显（持续性高血压阵发性加剧临床表现）。查体：P95次/分，血压158/95mmHg，心律不整，可闻及期前收缩5～6次/分，心前区S₁亢进（嗜铬细胞瘤心脏表现），根据患者既往史、临床表现、查体结果，最可能的诊断为嗜铬细胞瘤，嗜铬细胞瘤位于肾上腺者约占80%～90%，肾及肾上腺CT扫描（B对）可将90%以上的肿瘤准确定位。超声心动图（A错）对于嗜铬细胞瘤引起的心脏改变有一定的辅助诊断价值，不用于确诊疾病。肾动脉B超（C错）用于诊断肾动脉狭窄，对于嗜铬细胞瘤无确诊价值。腹部X线（D错）很难发现嗜铬细胞瘤。","c120","N"],["2018-N90",60,"第五节 嗜铬细胞瘤","嗜铬细胞瘤治疗",2018,90,"A","","女性，32岁。发现持续性高血压3年，血压为150～160/90～100mmHg，常因情绪激动、体位改变时诱发血压增高，最高可达210/110mmHg，伴头痛、心悸、出汗。口服多种降压药物疗效不佳。查体：T 36.7℃，P 90次/分，BP 158/95mmHg，甲状腺（-），双肺（-），心界不大，心律不整，可闻期前收缩5～6次/分，心尖部S1增强，腹部未闻及血管杂音，下肢不肿患者因疾病而明显焦虑，烦躁，测血压200/108mmHg，心率108次/分。应首选的治疗药物是",[["A","β受体拮抗剂"],["B","α受体拮抗剂"],["C","醛固酮受体拮抗剂"],["D","血管紧张素转换酶抑制剂"]],"B","青年女性患者（嗜铬细胞瘤多发人群），持续高血压三年，血压为150～160/90～100mmHg（正常成年人高值血压120～139/80～89mmHg），常因情绪激动，体位变动（常见诱因）诱发高血压，血压最高为210/110mmHg（发作时血压骤升），伴头痛、心悸、出汗（交感神经过度兴奋表现），口服多种降压药疗效不明显（持续性高血压阵发性加剧临床表现）。查体：P95次/分，血压158/95mmHg，心律不整，可闻及期前收缩5～6次/分，心前区S₁亢进（嗜铬细胞瘤心脏表现），根据患者既往史、临床表现、查体结果，最可能的诊断为嗜铬细胞瘤，应用药物长期控制嗜铬细胞瘤的高血压是困难的，且其中恶性约占10%，手术治疗是首选，嗜铬细胞瘤手术切除前采用α受体拮抗药（B对）使血压下降，减轻心脏的负担，并使原来缩减的血管容量扩大，能减少心脑血管并发症。单用β受体拮抗剂（A错）会阻断β受体介导的舒血管效应导致血压更高。醛固酮受体拮抗剂（C错）主要用于原发性醛固酮增多症导致的高血压。血管紧张素转化酶抑制剂（D错）主要用于原发性高血压，其降压作用较温和，起效慢，非首选药物，不能很快控制血压。","c120","N"],["2018-N91",69,"第一节 系统性红斑狼疮","系统性红斑狼疮诊断",2018,91,"A","","女性，25岁。1周来无明显诱因发热、双膝关节疼痛伴皮肤出血点，自测体温最高38.8℃，无寒战。既往体健。查体：T 38.1℃，四肢皮肤可见出血点，口腔颊黏膜见两处溃疡，心、肺、腹检查未见明显异常。化验血Hb 102g/L，WBC 5.2×10⁹/L，Plt 24×10⁹/L，网织红细胞4.9%，尿蛋白（++）。该患者最可能的诊断是",[["A","再生障碍性贫血"],["B","贝赫切特（Behcet）病"],["C","系统性红斑狼疮"],["D","急性肾小球肾炎"]],"C","患者青年女性（系统性红斑狼疮好发于育龄女性），1周前无明显诱因出现发热，双膝关节疼痛伴皮肤出血点，无寒战，既往体健。查体：T38.1℃（正常腋温36.0～37.0℃），四肢皮肤可见出血点，口腔颊黏膜可见两个溃疡（非狼疮特异性皮损），心肺腹检查无明显异常（患者病变累及多个系统，综合考虑为风湿免疫系统疾病）。化验血：Hb102g/L（女性正常值＞115g/L），WBC5.2×10⁹/L（正常值3.5～9.5×10⁹/L），plt24×10⁹/L（正常值125～350×10⁹/L），网织红细胞4.9%（正常值0.5%～2.0%），尿蛋白（++）（正常尿蛋白阴性），根据美国风湿病学会（ACR）1997年修订的SLE分类标准（符合4项或4项以上者，支持诊断为SLE），在11项诊断标准中，该患者符合口腔溃疡、关节炎、肾脏病变、血液学疾病4项诊断要点，结合患者临床表现及实验室检查，考虑诊断为系统性红斑狼疮（C对）。本例需与贝赫切特病鉴别，口腔溃疡可出现于系统性红斑狼疮和贝赫切特病，亦可出现在其他自身免疫性疾病，贝赫切特病（B错）基本表现为口腔溃疡每年发作至少3次（诊断贝赫切特病必须具有复发性口腔溃疡），伴有外阴溃疡、结节性红斑、假性毛囊炎及眼炎，肾脏累及极少见，目前无特异性实验室检查指标，根据1990年国际贝赫切特病研究组提出诊断标准（十版内科学P843），本例不符合贝赫切特病的诊断标准。再生障碍性贫血（A错）主要表现为贫血、感染、出血等症状，呈重度全血细胞减少，网织红细胞百分数多在0.5%以下（十版内科学P555）。急性肾小球肾炎（D错）多见于儿童，男性多于女性，通常于前驱感染后1～3周（平均10天左右）起病，临床表现为血尿、蛋白尿、水肿、高血压（十版内科学P476）。","c121","N"],["2018-N92",69,"第一节 系统性红斑狼疮","系统性红斑狼疮皮肤与黏膜表现",2018,92,"A","","女性，25岁。1周来无明显诱因发热、双膝关节疼痛伴皮肤出血点，自测体温最高38.8℃，无寒战。既往体健。查体：T 38.1℃，四肢皮肤可见出血点，口腔颊黏膜见两处溃疡，心、肺、腹检查未见明显异常。化验血Hb 102g/L，WBC 5.2×10⁹/L，Plt 24×10⁹/L，网织红细胞4.9%，尿蛋白（++）。为明确诊断，查体中还应特别注意检查的是",[["A","颜面部水肿"],["B","盘状红斑"],["C","结节性红斑"],["D","牙龈渗血"]],"B","患者青年女性（系统性红斑狼疮好发于育龄女性），1周前无明显诱因出现发热，双膝关节疼痛伴皮肤出血点，无寒战，既往体健。查体：T38.1℃（正常腋温36.0～37.0℃），四肢皮肤可见出血点，口腔颊黏膜可见两个溃疡（非狼疮特异性皮损），心肺腹检查无明显异常（患者病变累及多个系统，综合考虑为风湿免疫系统疾病）。化验血：Hb102g/L（女性正常值＞115g/L），WBC5.2×10⁹/L（正常值3.5～9.5×10⁹/L），plt24×10⁹/L（正常值125～350×10⁹/L），网织红细胞4.9%（正常值0.5%～2.0%），尿蛋白（++）（正常尿蛋白阴性），根据美国风湿病学会（ACR）1997年修订的SLE分类标准（符合4项或4项以上者，支持诊断为SLE），在11项诊断标准中，该患者符合口腔溃疡、关节炎、肾脏病变、血液学疾病4项诊断要点，结合患者临床表现及实验室检查，考虑诊断为系统性红斑狼疮，要明确诊断，查体还需注意盘状红斑（B对），SLE典型皮肤与黏膜表现为面部蝶形红斑及盘状红斑（B对）。SLE可出现颜面水肿（A错），但颜面水肿可见于诸多疾病，为非特异性表现。结节状红斑（C错）是贝赫切特病的典型表现。牙龈渗血（D错）主要见于血液系统出血性或三系减少疾病，如再生障碍性贫血。","c121","N"],["2018-N128",16,"第三节 房性心律失常","心房扑动心电图特征",2018,128,"B","","请判读下列心电图并作出诊断",[["A","窦性心动过速"],["B","阵发性室上性心动过速"],["C","心房扑动"],["D","心房颤动"]],"C","心房扑动的心电图特点：①窦性P波消失，出现F波。②QRS波形态正常。③房室传导比例不固定者心室率可不规则。④F波频率和形态有时可不绝对规则，称不纯性心房扑动或心房扑动-颤动。","","N"],["2018-N129",16,"第四节 房室交界性心律失常","房室结折返性心动过速心电图特征",2018,129,"B","","请判读下列心电图并作出诊断",[["A","窦性心动过速"],["B","阵发性室上性心动过速"],["C","心房扑动"],["D","心房颤动"]],"B","快速性室上性心动过速（阵发性室上性心动过速）心电图特点为室上性的QRS波群，心率150～250次/分，律均齐，可能由房性或室性期前收缩诱发，P波为逆行性（Ⅱ、Ⅲ、aVF导联倒置），常埋藏于QRS波内或位于其终末部分，P波与QRS波保持固定关系（B对）。","","N"],["2018-N130",75,"第一节 中毒概述","呼吸系统表现",2018,130,"B","","有机磷中毒时，患者的呼吸气味常是",[["A","烂苹果味"],["B","苦杏仁味"],["C","蒜臭味"],["D","腥臭味"]],"C","有机磷中毒时，气道分泌物增多表现为咳嗽、气促、呼吸困难、双肺干性或湿性啰音，呼出蒜臭味气体（C对）。烂苹果味（A错）为酮症酸中毒的呼吸气味。苦杏仁味（B错）为氰化物中毒时的呼吸气味。腥臭味（D错）可见于牙周炎等口腔疾病、支气管扩张等。","","N"],["2018-N131",75,"第一节 中毒概述","呼吸系统表现",2018,131,"B","","氰化物中毒时，患者的呼吸气味常是",[["A","烂苹果味"],["B","苦杏仁味"],["C","蒜臭味"],["D","腥臭味"]],"B","氰化物中毒时，有头昏、头痛、嗜睡、呼吸困难、心率加快、血压低、皮肤潮红、昏迷、惊厥、严重时呼吸心跳停止，呼出苦杏仁味气体（B对）。烂苹果味（A错）为酮症酸中毒的呼吸气味。蒜臭味（C错）为有机磷中毒的呼吸气味。腥臭味（D错）可见于牙周炎等口腔疾病、支气管扩张等。","","N"],["2018-N154",6,"第一节 肺结核","异烟肼",2018,154,"X","","下列抗结核药中，属于杀菌药的有",[["A","异烟肼"],["B","利福平"],["C","吡嗪酰胺"],["D","对氨基水杨酸"]],"ABC","抗结核药中，属于杀菌药的有异烟肼（A对）、利福平（B对）、吡嗪酰胺（C对）、链霉素等。对氨基水杨酸（D错）对结核菌抑菌作用较弱，仅作为辅助抗结核治疗药物，可竞争性抑制二氢叶酸合酶，阻止二氢叶酸的合成，从而使蛋白质合成受阻，抑制结核杆菌的繁殖，属二线口服抑菌药。","","N"],["2018-N155",22,"第二节 心包积液及心脏压塞","心脏压塞",2018,155,"X","","心脏压塞的主要体征有",[["A","奇脉"],["B","心界扩大"],["C","血压下降，脉压增大"],["D","心率加快，心音减弱"]],"ABD","迅速或大量心包积液可引起心脏压塞。心脏压塞时心尖搏动减弱，心音减弱（D对）。心脏叩诊浊音界向两侧增大（B对），皆为绝对浊音区。心脏压塞导致心室舒张受限，心搏出量下降，收缩压降低，血流速度减慢，因而舒张末期残留于大动脉的血液降低较少，舒张压可降低或不变。收缩压降低，而舒张压变化不大，故脉压减小（C错）。急性心脏压塞可表现为窦性心动过速、奇脉（A对）、血压下降、脉压减小（C错）和静脉压明显升高。","","N"],["2018-N156",75,"第二节 农药中毒","毒蕈碱样症状",2018,156,"X","","有机磷中毒时的毒蕈碱样症状有",[["A","腹痛、腹泻"],["B","大汗、流涎"],["C","肌纤维颤动"],["D","瞳孔缩小"]],"ABD","正常情況下，体内的乙酰胆碱（ACh）在胆碱酯酶的水解下失活，有机磷农药中毒时胆碱酯酶活性被不可逆性抑制，体内ACh大量蓄积，持续作用于M和N受体出现M样症状和N样症状。毒蕈碱样症状（M样症状）主要为副交感神经过度兴奋的表现（九版生理学P309），平滑肌痉挛表现有瞳孔缩小（瞳孔括约肌收缩所致）（D对）、恶心、呕吐、腹痛、腹泻（胃肠道平滑肌收缩所致）（A对），腺体分泌增加表现有多汗（交感节后神经纤维M胆碱能受体兴奋使皮肤小汗腺分泌汗液增加所致）（B对）、流泪、流涎等。烟碱样症状（N样症状）主要为横纹肌兴奋表现如肌束纤维颤动等（C错）。","","N"],["2018-N157",40,"第二节 急性肾小球肾炎","急性肾小球肾炎临床表现",2018,157,"X","","急性肾炎综合征应具有的临床特点包括",[["A","高血压"],["B","血尿"],["C","蛋白尿"],["D","肾功能不全"]],"ABC","根据九版内科学及三版八年制内科学观点，急性肾炎综合征是以血尿（B对）、蛋白尿（C对）、水肿、高血压（A对）为主要临床表现的肾脏综合征，可伴有一过性肾功能损害。十五版实用内科学（P1981）原发性肾小球疾病常见的临床综合征表格中所述，急性肾炎综合症的临床特点为：起病急骤，以血尿、蛋白尿为主要表现，常伴有水肿和高血压。综合各教材观点，肾功能不全（D错）不作为急性肾炎综合症的临床特点，属于急性肾炎综合征可能出现的伴随临床表现，且为一过性。","","N"],["2018-N158",53,"第二节 非霍奇金淋巴瘤","Burkitt淋巴瘤",2018,158,"X","","Burkitt淋巴瘤的免疫表型有",[["A","CD3阳性"],["B","CD5阳性"],["C","CD20阳性"],["D","CD22阳性"]],"CD","Burkitt淋巴瘤起源于滤泡生发中心或生发中心后B细胞，免疫表型为CD20⁺（C对），CD22⁺（D对），CD5ˉ（B错）。CD3⁺（A错）是T淋巴细胞的免疫表型。CD5⁺（B错）常见于套细胞淋巴瘤。","","N"],["2018-N159",61,"第一节 糖尿病","1型糖尿病",2018,159,"X","","在内分泌系统疾病中，属于由内分泌腺破坏而导致功能减低的疾病有",[["A","1型糖尿病"],["B","桥本甲状腺炎"],["C","Addison病"],["D","原发性垂体性侏儒症"]],"ABC","Ⅰ型糖尿病（A对）时，胰岛β细胞破坏，常导致胰岛素绝对缺乏。桥本甲状腺炎（B对）为甲状腺自身免疫性疾病，甲状腺腺体内淋巴细胞大量浸润，导致甲状腺滤泡大量破坏，腺体功能降低。Addison病（C对）指原发性慢性肾上腺皮质功能减退症，系因双侧肾上腺绝大部分被毁，导致肾上腺皮质激素分泌不足。原发性垂体性侏儒症（D错）病因不明，部分患者可能因下丘脑-垂体及其IGF轴功能异常，导致生长激素分泌不足，而腺垂体本身并无破坏。","","N"],["2019-N41",46,"第一节 贫血概述","贫血实验室检查",2019,41,"A","","外周血网织红细胞检测的意义",[["A","可反映骨髓整体造血功能"],["B","可反映骨髓造血原料利用程度"],["C","可反映早期红细胞生成过程"],["D","可反映某些贫血患者的治疗效果"]],"D","外周血网织红细胞检测包括网织红细胞计数、网织红细胞绝对数、网织红细胞生成指数和网织红细胞血红蛋白含量，其意义是反映骨髓红细胞造血功能（非骨髓整体的造血功能）（A错），增多表示红细胞系增生旺盛，在贫血的诊断和鉴别诊断中起重要作用，同时还可用于反映某些贫血患者的治疗效果（D对）、骨髓移植的恢复和放化疗骨髓抑制的情况等。在红细胞生成过程中，需要有足够的蛋白质、铁、叶酸和维生素B₁₂的供应，叶酸和维生素B₁₂是DNA合成的辅酶，缺乏会引起细胞核发育异常，造成幼红细胞分裂减慢，导致巨幼细胞性贫血，而铁是生成血红蛋白的原料，网织红细胞是晚幼红细胞（此时细胞内血红蛋白已达到正常含量）脱去细胞核形成（B错）。网织红细胞进入血液后通过自噬细胞器发育成成熟红细胞，此过程约需1天，故网织红细胞属于红细胞发育后期（C错）。","","N"],["2019-N42",22,"","",2019,42,"A","","胸膜摩擦音与心包摩擦音最重要的鉴别点是",[["A","听诊的部位不同"],["B","与呼吸运动的关系"],["C","与体位的关系"],["D","摩擦音的性质不同"]],"B","胸膜摩擦音是由于胸膜发生炎症而变得粗糙时，随着呼吸出现的声音，可在极短的时间内出现、消失或再出现，也可持续数日或更久，呼气与吸气时均可听到，一般在吸气末与呼气开始时较为明显，屏住呼吸则声音消失。心包摩擦音是心脏脏层与壁层由于生物或理化因素导致纤维蛋白沉积而粗糙，使心脏搏动时产生摩擦而出现的声音，故其与心搏一致，屏气时摩擦音仍然存在。因此胸膜摩擦音与心包摩擦音最重要的鉴别点是与呼吸运动的关系（B对）。胸膜摩擦音最常听到的部位是前下侧胸壁，心包摩擦音在心前区或胸骨左缘第三、四肋间最响亮，无法根据听诊部位将其鉴别（A错）。胸膜摩擦音可随体位的变动消失或复现，坐位或卧位明显，心包摩擦音在坐位前倾明显，故无法根据与体位的关系将二者鉴别（C错）。胸膜摩擦音声音性质差别很大，有的声音柔软细微，如丝织物的摩擦声，有的声音粗糙，如搔抓声、沙沙声、踏雪或握雪的声音，心包摩擦音声音类似纸张摩擦，故无法根据摩擦音性质的不同将二者鉴别（D错）。心包摩擦音见于各种感染性心包炎，也可见于急性心肌梗死、尿毒症、心脏损伤后综合征和SLE等非感染性情况导致的心包炎。胸膜摩擦音常见于纤维素性胸膜炎、肺梗死、胸膜肿瘤及尿毒症等病人。","","N"],["2019-N43",1,"第二节 慢性阻塞性肺疾病","抗胆碱药",2019,43,"A","","男性，58岁。反复咳嗽、咳痰16年，活动后气短3年。平地行走因呼吸困难需停止，近一年无急性加重。既往吸烟史40年。肺功能结果提示：吸入支气管扩张剂后FEV₁/FVC62%，FEV₁%pred65%，首选的吸入治疗药物是",[["A","短效抗胆碱能药物"],["B","长效抗胆碱能药物"],["C","短效β₂受体激动剂"],["D","糖皮质激素"]],"B","老年男患，40年吸烟病史，常年咳嗽、咳痰，近3年并发气短。平地行走因呼吸困难需停止（符合mMRC分级2级），近一年无急性加重（提示急性加重风险低）。肺功能结果提示：吸入支气管扩张剂后FEV₁/FVC62%，FEV₁%pred65%（确诊持续气流受限，GOLD2级/中度）。综合该患者的病史、临床表现、辅助检查，该病人最可能诊断的是慢性阻塞性肺疾病，病人综合评估分组为B组，首选的吸入治疗药物是长效抗胆碱能药物（B对）。短效抗胆碱能药物（A错）和（或）短效β2受体激动剂（C错）为稳定期A组患者的首选治疗药物。糖皮质激素（D错）用于急性加重风险高的病人（C组和D组）和急性加重期病人的治疗。注：根据10版内科学P28“表2-3-3稳定期慢阻肺病病人病情严重程度的综合性评估及其主要治疗药物”可知，B组低风险患者首选治疗药物为LABA+LAMA。","","N"],["2019-N44",9,"第一节 肺血栓栓塞症","抗凝药物",2019,44,"A","","男性，50岁。呼吸困难、胸痛3天。查体：P 96次/分，BP125/75mmHg，双肺呼吸音清，心率96次/分，心律整。右下肢肿胀。超声心动图提示右室功能障碍，cTnT 0.2ng/ml。CT肺动脉造影提示“右下、左上多发肺动脉内充盈缺损”。治疗应首选的药物是",[["A","重组组织型纤溶酶原激活剂"],["B","低分子肝素"],["C","氯吡格雷"],["D","阿司匹林"]],"B","中年男性患者，呼吸困难、胸痛3天（PTE常见临床症状），查体P96次/分（正常人心率范围60～100次/分），BP125/75mmHg（90mmHg≤正常收缩压＜139mmHg，60mmHg≤正常舒张压＜89mmHg），双肺呼吸音清，心律整（以上提示血流动力学稳定），右下肢肿胀（DVT症状），超声提示右心室功能障碍（存在右心功能不全），cTnT0.2ng/ml（＞cTnT0.1ng/ml，中危PTE心肌损伤诊断标准），CT肺动脉造影示“右下，左上肺多发肺动脉充盈缺损”（PTE影像学表现），根据患者的临床表现、体征、实验室检查结果和影像学结果，诊断为肺血栓栓塞（PTE），其血栓来自于深静脉血栓形成（DVT），临床分型为中危（十版内科学P114）。抗凝治疗是PTE和DVT的基本治疗方法，可以显著提高患者的生存率、降低血栓栓塞的复发率，该患者属血压正常和右心室功能不全的中危患者，不论是否溶栓，首选均为抗凝治疗，低分子肝素使用较普通肝素方便，疗效不低于普通肝素，为本例首选（B对）。重组组织纤溶酶原激活物（A错）的应用属于溶栓治疗，主要适用于高危（大面积）PTE病例（有明显呼吸困难、胸痛、低氧血症等），对部分中危患者，若无禁忌症可考虑，非首选治疗。氯吡格雷（C错）和阿司匹林（D错）为抗血小板药，其抗凝作用不能满足PTE或DVT的抗凝要求，不用于肺血栓栓塞的治疗，多应用于动脉粥样硬化的药物治疗。","","N"],["2019-N45",7,"第一节 肺癌","肺癌临床分期",2019,45,"A","","女性，72岁。刺激性干咳1个月。胸部CT提示右下肺团块状高密度影，边缘分叶状，最大径约4cm，纵隔、肺门未见肿大淋巴结，右侧胸腔积液。胸水中可见腺癌细胞。患者肺癌的临床分期是",[["A","IB期"],["B","ⅡB期"],["C","Ⅲ期"],["D","Ⅳ期"]],"D","老年女性，刺激性干咳一个月（原发肿瘤引起的症状），影像学提示右下肺部团状高密度影，边缘分叶状，最大直径约4cm（肿瘤最大直径＞3～4cm，肺癌TNM分期为T₂ₐ），纵隔、肺门淋巴结未见肿大（无区域淋巴结转移，肺癌TNM分期为N₀），右侧胸部胸腔积液，胸水检查有腺癌细胞（有远处转移，局限于胸腔内，M₁ₐ），该患者肺癌的TNM分期为T₂ₐN₀M₁ₐ，根据TNM与临床分期的关系，应为ⅣA期（D对）。ⅠB期对应T₂ₐN₀M₀（A错）。ⅡB期（B错）对应的是T₃N₀M₀及T₁ₐ₋₂bN₁M₀。Ⅲ期对应的TNM分期皆无远处转移。","","N"],["2019-N46",8,"第四节 其他间质性肺疾病","过敏性肺炎诊断",2019,46,"A","","男性，38岁。咳嗽、胸闷1个月。胸部CT提示双肺散在磨玻璃影及小结节影。支气管肺泡灌洗液显示淋巴细胞增高为主，且以CD8⁺淋巴细胞为主，追问病史患者饲养鸽子3个月。最可能的诊断是",[["A","特发性肺纤维化"],["B","隐源性机化性肺炎"],["C","结节病"],["D","过敏性肺炎"]],"D","38岁男性患者，饲养鸽子三个月（明确的抗原接触史），咳嗽、胸闷1个月（过敏性肺炎慢性形式可有临床表现），胸部CT显示双肺散在磨玻璃影和小结节影（过敏性肺炎影像学表现），支气管肺泡灌洗液显示淋巴细胞增高为主，且以CD8⁺淋巴细胞为主（过敏性肺炎BALF检查典型结果），根据患者的个人史、临床表现、影像学诊断和实验室检查结果，最可能的诊断是过敏性肺炎（D对），本病也称为外源性过敏性肺泡炎，是易感个体反复吸入外界有机粉尘抗原所引起的过敏性肺泡炎。特发性肺纤维化（A错）为慢性、进行性、纤维化性间质性肺炎，特征性病理改变为UIP（普通型间质性肺炎），即呈斑片状分布，表现纤维化、蜂窝状改变、间质性炎症和正常肺组织并存，致密的纤维瘢痕区伴散在的成纤维细胞灶，好发于老年人，多于50岁以后发病（十版内科学P102）。隐源性机化性肺炎（B错）多于50～60岁发病，临床表现多为亚急性过程，为流感样症状，BALF检查特征表现为细胞数增多，呈“混合性增高”，CD4⁺/CD8⁺下降，影像学常见双肺多发斑片状（肺泡）浸润影、孤立局灶性致密阴影，弥漫性双肺浸润性、小结节状或网织状改变，需要注意的是其临床特征和影像学特点具有一些特点，但并非特异，故诊断需慎重。结节病（C错）为多系统累及的肉芽肿性疾病，病因不明，常见的影像学表现为X线检查双侧肺门淋巴结肿大，胸部CT/HRCT的典型表现为沿着支气管血管束分布的微小结节，可融合成球，BALF检查显示淋巴细胞增加，CD4⁺/CD8⁺比值增加（＞3.5），活检称为确诊的重要手段（十版内科学P105）。","","N"],["2019-N47",18,"第一节 原发性高血压","原发性高血压诊断",2019,47,"A","","男性，58岁。因活动后心悸、胸闷、气短半年来院，15年前发现血压高，从未诊治。吸烟30年。父亲40岁死于心肌梗死。查体：P 82次/分，BP 150/70mmHg，双肺（-），心界向左下扩大，心尖部可闻及3/6级收缩期吹风样杂音。超声心动图示左心房增大、左室壁增厚，二尖瓣瓣尖稍增厚，室壁运动正常。该患者应首先考虑的诊断是",[["A","扩张型心肌病"],["B","风湿性心瓣膜病"],["C","高血压心脏病"],["D","冠状动脉性心脏病"]],"C","58岁男性患者，父亲40岁时死于心肌梗死（遗传因素），活动后心悸，胸闷，气短半年（心功能代偿失调可有靶器官损害症状），高血压15年，未经系统治疗（高血压病史），查体P82次/分（正常人心率范围60～100次/分），BP150/70mmHg（90mmHg≤正常收缩压<139mmHg，60mmHg≤正常舒张压<89mmHg，单纯收缩期高血压），肺部（—），心界向左下扩大，可闻及3/6级收缩期吹风样杂音，超声心动见左心房扩大，左室壁增厚，二尖瓣稍厚，室壁运动正常（高血压心脏病心肺表现），根据患者个人史、临床表现和体征、影像学表现，该患者首先考虑高血压心脏病（C对），患者早期可无明显临床症状，在高血压起病数年至十余年之后，会出现临床心功能不全症状，在心功能代偿期，除偶感心悸，其他心脏方面症状可不明显，代偿功能失调时，则可出现左心衰症状，如阵发性夜间呼吸困难，劳累后气喘、心悸、咳嗽等，心脏增大后，查体可见心界向左、向下扩大，心尖抬举样搏动，心尖区可闻及Ⅱ～Ⅲ级收缩期吹风样杂音，是左心室扩大导致相对性二尖瓣关闭不全或二尖瓣乳头功能失调导致，可有第四心音。扩张型心肌病（A错）是一类以左心室或双心室扩大伴收缩功能障碍为特征的心肌病，临床表现为心脏扩大、心力衰竭、心律失常、血栓栓塞及猝死，疾病终末期可表现为持续顽固性低血压，主要体征为心界扩大，听诊心音减弱，常可闻及第三或第四心音，超声心动示室壁活动普遍减弱，心肌收缩功能下降，可见二、三尖瓣反流（十版内科学P278）。风湿性心脏病（RHD）在典型症状出现前1～6周常有咽喉炎或扁桃体炎等A组β溶血性链球菌感染表现，风湿性心瓣膜病（B错）病变主要累及二尖瓣，有时心尖区可闻及高调、收缩期吹风样杂音后短促低调舒张中期杂音，可伴有发热、皮疹、皮下小结、舞蹈病等（十版内科学P869）。冠状动脉性心脏病（D错）是冠状动脉粥样硬化所致，根据冠状动脉的病变部位、供血范围、血管堵塞程度以及心肌供血不足的发展速度不同，可有不同的临床特点，分为慢性稳定性心绞痛和急性冠状动脉综合征两大类。","","N"],["2019-N48",23,"第一节 感染性心内膜炎","感染性心内膜炎诊断",2019,48,"A","","女性，36岁。4周来发热、乏力、关节痛、食欲下降、腰背酸痛。既往有二尖瓣脱垂史。查体：T 38.1℃，轻度贫血貌，眼球结膜下有出血点，心率105次/分，心律整，心尖部可闻及3/6级收缩期吹风样杂音，肝脾肋下均可及。化验血Hb 88g/L，WBC 13.2×10⁹/L；尿蛋白（+），沉渣镜检RBC 5～8个/HP，该患者最可能的诊断是",[["A","急性肾小球肾炎"],["B","风湿热"],["C","亚急性感染性心内膜炎"],["D","系统性红斑狼疮"]],"C","女性患者，有二尖瓣脱垂病史（心瓣膜病病史），发热，乏力，关节痛，食欲下降，腰背酸痛四周（亚急性心内膜炎可有临床表现），查体：T38.1℃（发热），轻度贫血貌，眼球结膜下有出血点（亚急性心内膜炎周围体征），心率105次/分（正常人心率为60～100次/分），心律整，心尖部可闻及3/6级收缩期吹风样杂音（亚急性心内膜炎可闻及心脏杂音），肝脾肋下均可及（肝脾肿大）。化验血Hb88g/L（正常成年女性血红蛋白115～150g/L，中度贫血），WBC13.2×10⁹/L（正常成年人3.5～9.5×10⁹/L，轻度升高），尿蛋白（+）（蛋白尿），沉渣镜检RBC5～8个/HP（＞3个/HP，镜下血尿），根据患者的病史、临床表现和体征、实验室检查，最可能的诊断是亚急性感染性心内膜炎（C对），感染性心内膜炎是指因细菌、真菌和其他病原微生物直接感染产生的心瓣膜或心室壁内膜的炎症，需要注意的是2009年欧洲心脏病学会（ESC）公布了新版IE（感染性心内膜炎）预防、诊断与治疗指南，摒弃了急性、亚急性和慢性心内膜炎的分类方法。急性肾小球肾炎（A错）是以急性肾炎综合症为主要临床表现的一组疾病，临床表现为血尿、蛋白尿、水肿和高血压，可伴有一过性肾功能不全（十版内科学P476）。风湿热（B错）是一种因A组链球菌感染咽部引起的迟发型、非化脓性后遗症，临床表现为关节炎、心脏炎、舞蹈病、皮下结节及边缘性红斑，典型症状出现前1～6周会有前驱症状（咽喉炎或扁桃体炎等上呼吸道感染表现），一般不会出现周围体征瘀点瘀斑等，且较少累及肾脏（十版内科学P869）。系统性红斑狼疮（D错）是一种致病性自身抗体和免疫复合物形成并介导器官、组织损伤的自身免疫疾病，表现为多系统受累，其WBC多不升高，可出现疣状心内膜炎，其病理表现与感染性心内膜炎不同，且通常不会引起心脏杂音改变（十版内科学P848）。","","N"],["2019-N49",24,"第一节 心脏骤停与心脏性猝死","初级心肺复苏",2019,49,"A","","正确的心肺复苏程序是",[["A","A-B-C"],["B","C-B-A"],["C","B-A-C"],["D","C-A-B"]],"D","正确的心肺复苏程序为C-A-B（D对），其中C代表人工胸外按压（circulation），A代表开放气道（airway），B代表人工呼吸（breathing），以上属于初级心肺复苏的内容，其中胸外按压最为重要，按压频率应为100～120/分，成人按压胸骨的幅度至少为5cm，但是不超过6cm，行30次胸外按压之后，再开通气道，开放气道后，首先进行2次人工呼吸，持续吹气1秒以上，保证足够的潮气量使胸廓起伏，无论单人或双人进行心肺复苏，按压和通气的比例为30：2。十版内科学强调心肺复苏的程序为C-A-B。","","N"],["2019-N50",26,"第一节 胃食管反流病","抗反流屏障结构与功能异常",2019,50,"A","","下列引起胃食管反流病的病因中，不属于抗反流屏障结构与功能异常的是",[["A","贲门失弛缓症手术后"],["B","大量腹水"],["C","胃扩张"],["D","干燥综合征"]],"D","胃食管反流病是指胃十二指肠内容物反流至食管、口咽或呼吸道引起的不适症状和（或）并发症，多种病理生理改变导致食管防御能力下降、损害因素增加，反流至食管的胃十二指肠内容物均会损伤食管黏膜，主要病因为①抗反流屏障结构与功能异常，②食管清除作用降低，③食管黏膜屏障功能降低，贲门失弛缓症手术后（A对）、大量腹水（B对）、胃扩张（C对）均属于抗反流屏障结构和功能异常，干燥综合征（D错，为本题正确答案）属于食管清除作用降低。干燥综合征主要累及外分泌腺体，表现为腺体导管扩张、狭窄及腺体间质大量淋巴细胞浸润、小唾液腺上皮细胞破坏和萎缩，类似病变还可出现在其他外分泌腺体，其中消化系统为黏膜层外分泌腺体破坏出现食管黏膜萎缩、萎缩性胃炎、慢性腹泻等非特异性症状。应仔细区分干燥综合征在消化系统的临床表现和胃食管反流病发病机制中干燥综合征导致的食管清除作用降低。","","N"],["2019-N51",28,"第一节 消化性溃疡","幽门管溃疡",2019,51,"A","","幽门管溃疡的临床特点是",[["A","空腹疼痛"],["B","易发生幽门梗阻"],["C","不易有出血并发症"],["D","不易有穿孔并发症"]],"B","幽门管位于胃的远端，与十二指肠交接，长度约为2cm，幽门管溃疡的病理生理与十二指肠溃疡（DU）相似，胃酸一般会增多，常缺乏典型溃疡的节律性疼痛，餐后上腹痛多见（A错），对抗酸药物反应较差，容易出现呕吐等胃出口梗阻症状（B对），穿孔或出血等并发症也较多见（CD错）。","","N"],["2019-N52",35,"","",2019,52,"A","","男性，65岁。呕血、黑便3天，半天来出现躁动不安和意识模糊入院。既往有肝炎病史15年，治疗不详；患糖尿病10年，一直服用降糖药物；有高血压病史6年，一直服用降压药物。查体：T 36.8℃，P 95次/分，R 22次/分，BP130/80mmHg，神志不清，前胸部可见蜘蛛痣，心肺（-），腹软，肝脾触诊不满意。该患者意识障碍应首先考虑的病因是",[["A","肝性脑病"],["B","糖尿病酮症酸中毒"],["C","急性肾损伤"],["D","急性脑血管病"]],"A","老年男性患者，有呕血、黑便（消化道出血症状，肝性脑病诱因），因出现躁动不安和意识模糊入院（肝性脑病2期临床表现），既往有肝炎病史15年（肝硬化病因），糖尿病10年，一直服用降糖药物；有高血压病史6年，一直服用降压药物（长期服药导致可能导致肝功能损伤）。查体：T 36.8℃（正常人体温36～37℃），P 95次/分（正常人心率为60～100次/分），R 22次/分（正常成年人呼吸频率12～20次/分，超过20次为属于呼吸过速），BP130/80mmHg（90mmHg≤正常收缩压<139mmHg，60mmHg≤正常舒张压<89mmHg），神志不清（肝性脑病症状），前胸部可见蜘蛛痣（肝硬化体征），心肺（-），腹软，肝脾触诊不满意（门脉高压导致肝脾大），根据患者的既往病史、临床表现、查体体征，该患者应诊断为肝硬化，其意识障碍首先要考虑的病因是肝性脑病（A对），处于昏迷前期（2期）。糖尿病酮症酸中毒（B错）属于糖尿病急症，以高血糖、酮症和酸中毒为主要表现，常见诱因是感染，呼吸有典型的酮味（烂苹果味），血压一般降低，该患者服用降糖药物控制血糖，酮症酸中毒可能性不高（十版内科学P744）。急性肾损伤（AKI）是各种病因导致短时间内肾功能快速减退的临床综合征，临床表现差异大，与病因和所处的临床分期有关，常见症状包括乏力、恶心、呕吐、尿量减少和尿色加深，容量过多时刻出现急性左心衰症状，AKI的首次诊断常基于实验室检查（特别是血清肌酐），而不是临床症状和与体征（十版内科学P520）。急性脑血管病是一组疾病的总称，为起病急骤的脑部血管循环障碍疾病，可分为出血性和缺血性脑血管病两大类，高血压是重要的病因及诱因，该患者有高血压病史，规律服用降压药物，控制良好且无异常表现，故暂排出急性脑血管病。","","N"],["2019-N53",41,"第一节 尿路感染","尿路感染的分类",2019,53,"A","","女性，29岁。曾患尿路感染，尿培养为大肠埃希菌，经治疗后尿菌转阴。随访尿培养再次出现真性细菌尿。下面确定该患者尿路感染为复发的依据是",[["A","停药6周内，菌株仍为大肠埃希菌"],["B","停药6周内，菌株为变形杆菌"],["C","停药6周后，菌株仍为大肠埃希菌"],["D","停药6周后，菌株为变形杆菌"]],"A","29岁患者，尿路感染病原菌为大肠埃希菌（大肠杆菌），治疗后尿培养转阴，随诊时发现真性菌尿，尿路感染复发，依据为停药6周内，尿培养仍然为大肠杆菌（A对C错）。尿路感染复发是指治疗后症状消失，尿菌阴转后在6周内再次出现菌尿，菌种与上次相同（菌种相同且为同一血清型）（BD错）。有关尿路感染的复发，十版内科学提到“再感染是指由新的病原体致病，复发是因同一病原体持续存在导致的感染再次发作”（P499），八版内科学（P501-P502）及15版实用内科学（P2074-P2975）都明确说明一般在停药6周后再发生的尿路感染为重新感染，停药后6周内复发，致病菌与前次相同为复发。","","N"],["2019-N54",50,"第二节 遗传性球形红细胞增多症","遗传性球形红细胞增多症治疗",2019,54,"A","","首选脾切除治疗且疗效最佳的溶血性贫血是",[["A","地中海贫血"],["B","阵发性睡眠性血红蛋白尿"],["C","遗传性球形红细胞增多症"],["D","温抗体型自身免疫性溶血性贫血"]],"C","首选脾切除治疗且疗效最佳的溶血性贫血是遗传性球形红细胞增多症（C对），除个别常染色体隐性遗传和某些重度病例外，脾切除对大多数遗传性球形红细胞增多症有显著疗效，术后球形红细胞虽然依然存在，但红细胞寿命延长，数天后即可见黄疸减轻和血红蛋白浓度上升，还可以防止胆结石和再障危象等并发症的发生。地中海贫血（A错），现称珠蛋白生成障碍性贫血，主要治疗方式是对症治疗，重症患者需要长期输血，脾切除适用于输血量不断增加，伴脾功能亢进及明显压迫症状者，唯一的根治措施是进行异基因造血干细胞移植（十版内科学P564）。阵发性睡眠性血红蛋白尿（B错）的主要对策是支持和对症治疗，包括缓解或终止溶血、刺激造血和抗血栓治疗，脾切除对大部分患者无效，且手术并发症严重，尤其是血栓形成风险高（三版八年制内科学P807）。温抗体型自身免疫性溶血性贫血（D错）的首选治疗为使用糖皮质激素，脾切除为二线治疗，需按照治疗指征进行手术（十版内科学P565）。","","N"],["2019-N55",61,"第二节 糖尿病酮症酸中毒","糖尿病酮症酸中毒诊断",2019,55,"A","","男性，20岁。近半年来乏力日渐明显，体重下降约15公斤，食欲尚可，尿量多。2天前外出就餐后感恶心、腹痛伴腹泻6次，粪便为不消化食物，1天来精神恍惚来院。既往曾查血糖高。查体：T 36.8℃，P 118次/分，R 28次/分，BP 88/58mmHg，嗜睡状，消瘦，呼吸深快，皮肤干燥，双肺（-），心律整，心音正常，腹软，肠鸣音活跃，四肢发凉。最可能的诊断是",[["A","甲状腺危象"],["B","食物中毒"],["C","感染中毒性休克"],["D","糖尿病酮症酸中毒"]],"D","青年男性患者，近半年来乏力日渐明显，体重下降约15公斤，食欲尚可，尿量多（有三多一少症状，且加重），既往有血糖升高史（考虑可能存在1型糖尿病，有自发DKA倾向），2天前外出就餐后感恶心、腹痛伴腹泻6次（饮食不当是1型糖尿病患者DKA反复发作的重要诱因，电解质平衡紊乱），粪便为不消化食物，1天来精神恍惚来院（出现中枢神经系统功能障碍），查体：T 36.8℃（正常人体温36～37℃），P 118次/分（正常人心率为60～100次/分，心率加快），R 28次/分（正常成年人呼吸频率12～20次/分，呼吸过速），BP 88/58mmHg（90mmHg≤正常收缩压<139mmHg，60mmHg≤正常舒张压＜89mmHg，血压下降），嗜睡状，消瘦，呼吸深快，皮肤干燥，双肺（-），心律整，心音正常，腹软，肠鸣音活跃，四肢发凉（DKA可有临床表现），根据患者既往病史、临床表现和体征，最可能的诊断是糖尿病酮症酸中毒（DKA）（D对），DKA是高血糖危象之一，也是糖尿病急性并发症之一，临床以高血糖、高血酮和代谢性酸中毒为主要表现。甲状腺危象（A错），过去亦称甲亢危象，是甲状腺毒症急性加重的表现，主要诱因为感染、应激（包括急性创伤、分娩等）、¹³¹I治疗及甲状腺手术前准备不充分等，临床表现为原有甲亢症状加重，高热（体温可达40℃或更高）、大汗、心悸、心率过速（常>140次/分），恶心呕吐、腹痛腹泻、烦躁甚至谵妄，严重者可有心衰、休克及昏迷（十版内科学P688）。食物中毒（B错）时，常为集体发病，散发病例，应调查同餐者有无类似情况发病者，该患者没有明确的食物中毒确诊依据，餐后呕吐、腹痛、腹泻是酸中毒相关症状。感染中毒性休克（C错）是各种感染导致脓毒血症以及其诱发的组织灌注不足、细胞代谢紊乱和功能障碍的病理过程，以下三种情况同时存在：SIRS（全身炎症反应综合征）、细菌学感染的证据、休克的表现（九版外科学P34）。","","N"],["2019-N56",68,"第一节 类风湿关节炎","抗瓜氨酸化蛋白抗体",2019,56,"A","","下列关于类风湿关节炎（RA）患者实验室检查临床意义的叙述，正确的是",[["A","RF阴性可排除RA诊断"],["B","RF对诊断RA的特异性明显高于抗CCP抗体"],["C","抗CCP抗体有助于RA的早期诊断"],["D","抗CCP抗体对RA诊断的敏感性高，特异性低"]],"C","类风湿关节炎（RA）是一种以慢性、侵蚀性、对称性多关节炎为主要临床表现的全身性自身免疫性疾病，类风湿关节炎相关的自身抗体如类风湿性因子（RF）以及环瓜酸多肽抗体（CCP）在本病诊断中有重要意义，其中抗CCP抗体敏感性和特异性均很高（D错），且可在疾病早期出现，有助于RA的早期诊断，与疾病预后相关（C对）。RF阳性率为75%～80%，除了RA外，RF阳性还可见于干燥综合征、系统性红斑狼疮、病毒性肝炎、结核等疾病，另有1%～5%的健康人群也可出现RF阳性，RF阴性不能排除RA的诊断（A错）。RF对诊断RA的特异性为86%，抗CCP抗体为96%，抗CCP抗体对诊断RA的特异性明显高于RF（B错）。","","N"],["2019-N68",16,"第三节 房性心律失常","心房颤动心电图特征",2019,68,"A","","男性，72岁。有高血压病史10年，长期服用降压药物，平日血压控制在130～145/70～80mmHg。日常活动正常。2个月来无诱因出现发作性心悸，持续3～8小时左右可自行缓解。1小时前症状再次发作，心电图提示心房颤动。该患者心电图的特征不正确的是",[["A","P波消失"],["B","QRS时限正常"],["C","R-R间期不等"],["D","可见规律f波"]],"D","老年男性患者，既往高血压病史10年（疑高血压性心脏病），血压控制达标，2月前突发心悸，持续数小时可自行缓解，1小时前再次发作，心电图提示心房颤动，房颤是一种心房激动频率达350～600次/分的快速性心律失常，本例属于阵发性房颤，房颤心电图特征为P波消失（A对），可见快速而不规则的f波（D错，为本题正确答案），也称为房颤波，有些f波较为粗大，甚至表现为不纯性扑动或颤动，QRS波群节律不规则，致R-R间期不等（C对），QRS波群形态多正常（B对）。","c127","N"],["2019-N69",16,"第三节 房性心律失常","心房颤动临床表现",2019,69,"A","","男性，72岁。有高血压病史10年，长期服用降压药物，平日血压控制在130～145/70～80mmHg。日常活动正常。2个月来无诱因出现发作性心悸，持续3～8小时左右可自行缓解。2小时前症状再次发作，心电图提示心房颤动。该患者心脏检查可能出现的体征是",[["A","心律完全不整"],["B","心界向两侧扩大"],["C","心尖部第一心音亢进"],["D","心尖部闻及第四心音"]],"A","老年男性患者，既往高血压病史10年（疑高血压性心脏病），血压控制达标，2月前突发心悸，持续数小时可自行缓解，1小时前再次发作，心电图提示心房颤动，房颤是一种心房激动频率达350～600次/分的快速性心律失常，本例属于阵发性房颤，行心脏检查，可能出现的体征有听诊心率快慢不一，第一心音强弱不等（C错），节律绝对不规整（A对），心率快于脉率（脉搏短绌）。第四心音属病理性心音，为心房肌在收缩末期为克服心室舒张末期压力而用力收缩所产生的震动，也称心房音，一般认为它的产生与心房收缩使房室瓣及其相关结构（瓣膜、瓣环、腱索和乳头肌）突然紧张、振动有关，房颤时，心房很少能做到有效的收缩，故不能闻及第四心音（D错）。心界向两侧扩大（B错）常见于扩张型心肌病、全心衰、心肌炎等，本例患者无明确心界扩大相关临床表现。","c127","N"],["2019-N70",16,"第三节 房性心律失常","心房颤动临床表现",2019,70,"A","","男性，72岁。有高血压病史10年，长期服用降压药物，平日血压控制在130～145/70～80mmHg。日常活动正常。2个月来无诱因出现发作性心悸，持续3～8小时左右可自行缓解。3小时前症状再次发作，心电图提示心房颤动。目前该患者最容易出现的并发症是",[["A","心力衰竭"],["B","肺栓塞"],["C","脑栓塞"],["D","猝死"]],"C","老年男性患者，既往高血压病史10年（疑高血压性心脏病），血压控制达标，2月前突发心悸，持续数小时可自行缓解，1小时前再次发作，心电图提示心房颤动，房颤是一种心房激动频率达350～600次/分的快速性心律失常，本例属于阵发性房颤。房颤有较高的发生体循环栓塞的危险（B错），其易形成左房附壁血栓，血栓栓塞，尤其是脑栓塞，是最重要的致残和致死的原因，且结合本例患者10年高血压病史，目前该患者最容易出现的并发症是脑栓塞（C对），且随着年龄的增长，心力衰竭、冠心病、高血压等危险因素对脑卒中发生率的影响越来越弱，房颤成为脑卒中发病率的唯一的独立危险因素，20%～25%的缺血性脑卒中是心源性栓子所致。心力衰竭（A错）也属于房颤的并发症。心脏骤停是心源性猝死的直接原因，其病理生理机制最常见的是快速型室性心律失常（室颤和室速）（D错）。","c127","N"],["2019-N73",2,"第一节 支气管哮喘","支气管哮喘诊断",2019,73,"A","","男性，45岁。发作性咳嗽、喘息10年，再发2天。高血压病史3年，无吸烟史。查体：双肺可闻及散在哮鸣音，未闻及湿啰音。心率98次/分，心律整。胸片检查可见双肺透亮度增加。该患者最可能的诊断是",[["A","慢性阻塞性肺疾病"],["B","支气管扩张症"],["C","支气管哮喘"],["D","左心衰竭"]],"C","中年男性患者发作性咳嗽、喘息10年，2天前再发，查体双肺闻及散在哮鸣音（支气管哮喘发作时典型体征），胸片显示双肺透亮度增加（支气管哮喘发作时过度通气状态），心率98次/分，心律整（心血管系统暂无明显体征）。综合该患者病史、临床变现及体征，诊断考虑为支气管哮喘（C对）。慢性阻塞性肺疾病（A错）多见于中老年人，多有长期吸烟或接触有害气体的病史和慢性咳嗽史，喘息长年存在，体检双肺呼吸音明显下降，可有肺气肿体征，两肺可闻及湿啰音。支气管扩张（B错）主要表现为持续或反复的咳嗽、咳痰或咳脓痰，胸片可见特征性的“双轨征”或“环形阴影”。左心衰竭（D错）引起的呼吸困难病人常突发气急，端坐呼吸，阵发性咳嗽，常咳粉红色泡沫痰，两肺可闻及广泛的湿啰音和哮鸣音，左心界扩大，心率增快，心尖部可闻及奔马律，胸片检查可见心脏增大，肺淤血征。","c129","N"],["2019-N74",2,"第一节 支气管哮喘","通气功能检查",2019,74,"A","","男性，45岁。发作性咳嗽、喘息10年，再发2天。高血压病史3年，无吸烟史。查体：双肺可闻及散在哮鸣音，未闻及湿啰音。心率99次/分，心律整。胸片检查可见双肺透亮度增加。下列检查中，对该患者疾病诊断意义最大的是",[["A","肺功能及支气管舒张试验"],["B","胸部CT"],["C","血清总IgE测定"],["D","超声心动图"]],"A","中年男性患者发作性咳嗽、喘息10年，2天前再发，查体双肺闻及散在哮鸣音（支气管哮喘发作时典型体征），胸片显示双肺透亮度增加（支气管哮喘发作时过度通气状态），心率98次/分，心律整（心血管系统暂无明显体征），综合该患者病史、临床表现及体征，诊断考虑为支气管哮喘，对患者疾病诊断意义最大的是肺功能及支气管舒张试验（A对），通过肺功能检查可确定是否存在气流受限，支气管舒张试验用于测定气道的可逆性改变。一般X线胸片或胸部CT缓解期无明显异常，胸部CT在部分病人可见支气管壁增厚、黏液阻塞，并不能作为支气管哮喘确诊的依据（B错）。支气管哮喘时血清总IgE测定（C错）可增高，同时肝脏病、结节病、类风湿关节炎、特异性皮炎、过敏性鼻炎、间质性肺炎、荨麻疹等疾病也可见其增高，可作为辅助诊断。超声心动图（D错）用于检查心脏和大血管的解剖结构及功能状态，主要用于心血管相关疾病的辅助诊断。","c129","N"],["2019-N75",2,"第一节 支气管哮喘","慢性持续期的治疗",2019,75,"A","","男性，45岁。发作性咳嗽、喘息10年，再发2天。高血压病史3年，无吸烟史。查体：双肺可闻及散在哮鸣音，未闻及湿啰音。心率100次/分，心律整。胸片检查可见双肺透亮度增加。该患者长期治疗首选的方案是",[["A","吸入长效抗胆碱能药物"],["B","出现感染征象应用抗生素"],["C","吸入糖皮质激素"],["D","扩血管、利尿"]],"C","中年男性患者发作性咳嗽、喘息10年，2天前再发，查体双肺闻及散在哮鸣音（支气管哮喘发作时典型体征），胸片显示双肺透亮度增加（支气管哮喘发作时过度通气状态），心率98次/分，心律整（心血管系统暂无明显体征），综合该患者病史、临床表现及体征，诊断考虑为支气管哮喘。该患者长期治疗首选的方案是吸入糖皮质激素（C对），其局部抗炎作用强、全身不良反应少，是哮喘长期治疗的首选药物，机制为作用于气道炎症形成过程中的诸多环节，如抑制嗜酸性粒细胞等炎症细胞在气道的聚集、抑制炎症因子的生成和介质释放、增强平滑肌β₂受体的反应性等，能有效抑制气道炎症。长效抗胆碱能药物（LAMA）主要用于哮喘合并慢阻肺以及慢阻肺病人的长期治疗（A错）。出现感染征象应用抗生素（B错）属于对症治疗。扩血管、利尿（D错）不属于支气管哮喘的治疗方案。","c129","N"],["2019-N76",17,"第四节 急性冠状综合征","不稳定型心绞痛和非ST段抬高型心肌梗死诊断",2019,76,"A","","女性，49岁。2个月来无诱因出现心前区憋闷、气促，持续10分钟至半小时不等，发作时伴乏力、四肢麻木、手心出汗，活动不受限。1小时来症状再发并持续不缓解，步行来院。既往有高血脂，无其他病史。其父患心脏病猝死。查体：P 80次/分，R 16次/分，BP 130/70mmHg。肥胖体型，双肺（-），心界不大，心律整，心尖部可闻及2/6级收缩期杂音，A₂= P₂，腹部（-），左下肢水肿（±）。心电图示：Ⅲ、aVF、V5导T波低平。根据目前资料，患者最不可能的疾病是",[["A","心脏神经官能症"],["B","急性心肌梗死"],["C","不稳定型心绞痛"],["D","肺栓塞"]],"B","心脏神经官能症（A对）是以心脏不适为主要表现的神经症，本症多见于女性，尤其是更年期女性，精神与心理因素与本症的发病密切相关，其中“心理暗示”的作用尤为突出，常见心悸、心前区疼痛、气短或过度换气，也可有焦虑、抑郁，甚至紧张、头晕、手掌汗多、乏力、双手颤抖等神经系统症状，心血管体格检查大多正常，听诊可闻及心音增强或轻度心前区收缩期杂音，少数患者心电图可有窦性心动过速或ST段改变，后者大多表现为非特异性ST段J点压低或水平样下移，和（或）T波低平、双向或倒置。ST-T改变主要局限于Ⅱ、Ⅲ、aVF 或V₄～V₆导联（十五版本实用内科学P1119-P1120）。不稳定型心绞痛（C对）属于急性冠状动脉综合征，是一组由心肌缺血引起的临床综合征。不稳定型心绞痛可有典型的心绞痛症状，以及发作时有新的相关症状如出汗、恶心、心悸或呼吸困难，有典型的缺血性心电图改变（新发或一过性ST段压低≥0.1mV，或T波低平或倒置）以及心肌损伤标志物，体征可有一过性收缩期杂音。肺栓塞（D对）是以各种栓子阻塞肺动脉或其分支为其发病原因的一组疾病或临床综合征的总称，最常见的是肺血栓栓塞，症状多样，缺乏特异性，可以从无症状、隐匿到血流动力学不稳定，甚或发生猝死，典型的肺栓塞“三联症”为呼吸困难、胸痛和咯血，但临床上只有不到30%患者出现，同时肺栓塞一般有高危因素，如长期卧床、术后等，临床表现呼吸困难最常见，程度和栓塞的范围有关，其次为胸痛，多为胸膜性胸痛，本例患者的症状、体征、心电图检查等不能完全排除肺栓塞。根据患者的个人史、既往病史、临床表现、体征、心电图结果，不能排除以上疾病，需进行详细鉴别和诊断。急性心肌梗死发病先兆有乏力、胸部不适、活动时心悸、气急、烦躁等，发作时有心绞痛症状（性质更加剧烈、持续时间长、硝酸甘油效果差）常伴有烦躁不安、出汗、恐惧或濒死感，亦有胃肠道症状、心律失常、低血压和休克等，严重时可出现心力衰竭（左心衰竭为主），体征心尖区可出现粗糙的收缩期杂音，特征性心电图改变为ST段弓背样抬高、病理性Q波、T波倒置（十版内科学P242），该患者在出现症状后可自行步行到医院就医，临床表现和体征不能完全用急性心肌梗死解释，故根据目前资料，患者最不可能的疾病是急性心肌梗死（B错，为本题正确答案）。","c130","N"],["2019-N77",17,"第四节 急性冠状综合征","不稳定型心绞痛和非ST段抬高型心肌梗死一般治疗",2019,77,"A","","女性，49岁。2个月来无诱因出现心前区憋闷、气促，持续10分钟至半小时不等，发作时伴乏力、四肢麻木、手心出汗，活动不受限。1小时来症状再发并持续不缓解，步行来院。既往有高血脂，无其他病史。其父患心脏病猝死。查体：P 80次/分，R 16次/分，BP 130/70mmHg。肥胖体型，双肺（-），心界不大，心律整，心尖部可闻及2/6级收缩期杂音，A₂= P₂，腹部（-），左下肢水肿（±）。心电图示：Ⅲ、aVF、V5导T波低平。此时给予患者最正确的处理是",[["A","对症处理，临床观察"],["B","保证O₂供，急诊溶栓"],["C","积极抗凝，抗血小板"],["D","血运重建，急诊介入"]],"A","根据本例患者的个人史、既往病史、临床表现、体征、心电图结果，不能确定引发症状的具体病因，此时给与患者最正确的处理应为对症处理、临床观察（A对），再根据临床观察结果给与进一步的诊疗方案。提高氧供，积极溶栓（B错）属于肺栓塞的治疗。积极抗凝，抗血小板（C错）属于急性冠脉综合征（ACS）的治疗，血供重建，急诊介入（D错）适用于有更加切实证据的患者，如心电图动态演变、心肌酶学变化，亦或经上述治疗，效果欠佳者。心脏神经官能症的治疗原则与神经症相同，以心理治疗为主，药物治疗为辅，必要时邀请心理治疗专科医生参与诊治，原则上也先应对症处理临床观察。","c130","N"],["2019-N78",17,"第四节 急性冠状综合征","心电图活动平板负荷试验",2019,78,"A","","女性，49岁。2个月来无诱因出现心前区憋闷、气促，持续10分钟至半小时不等，发作时伴乏力、四肢麻木、手心出汗，活动不受限。1小时来症状再发并持续不缓解，步行来院。既往有高血脂，无其他病史。其父患心脏病猝死。查体：P 80次/分，R 16次/分，BP 130/70mmHg。肥胖体型，双肺（-），心界不大，心律整，心尖部可闻及2/6级收缩期杂音，A₂= P₂，腹部（-），左下肢水肿（±）。心电图示：Ⅲ、aVF、V5导T波低平。患者症状缓解后2周再次来院，为明确诊断，此时应首选的检查是",[["A","超声心动图"],["B","冠状动脉造影"],["C","运动负荷心电图"],["D","肺通气灌注检查"]],"C","根据本例患者的个人史、既往病史、临床表现、体征、心电图结果，应考虑的疾病为冠脉相关疾病（冠心病），考虑到患者的基本情况，为明确诊断，此时应首选的检查为运动负荷心电图，运动试验目前常用平板和脚车运动试验（C对），受检者接受适量运动，观察其症状、心率、血压、心电图及其他指标变化情况，并据此辅助诊断心脏疾病或对预后做出判断，在运动过程中，心电图出现ST段水平或斜向下下移，或发生典型心绞痛，对冠心病的诊断有较大的价值。超声心动图（A错）有助于了解心室壁的运动和左心室的功能，诊断室壁瘤和乳头肌功能失调，检测心包积液以及室间隔穿孔等并发症，有助于发现其他需与冠状动脉狭窄导致的心绞痛相鉴别的疾病，如梗阻性肥厚型心肌病、主动脉瓣狭窄等。冠状动脉造影（B错）为有创性检查手段，虽然是诊断冠心病的金标准，但不作为首选检查。肺通气灌注检查（D错）是诊断肺栓塞的重要诊断方法，对远端肺栓塞诊断价值更高，且可用于肾功能不全和碘造影剂过敏患者。","c130","N"],["2019-N79",30,"第二节 克罗恩病","克罗恩病诊断",2019,79,"A","","男性，24岁。间断下腹痛、腹胀、腹泻1年余，腹痛常于进食后加重，排便后缓解，粪便呈糊状，一般无黏液和脓血，未进行系统检查和治疗，3天来再次发作。查体：T36.5℃，浅表淋巴结不大，心肺（-），腹平软，右下腹压痛（+），无肌紧张和反跳痛，肝脾未及。钡剂灌肠检查见回盲部纵行性溃疡和鹅卵石征。该患者最可能的诊断是",[["A","肠结核"],["B","克罗恩病"],["C","结肠癌"],["D","肠淋巴瘤"]],"B","青年男性患者（CD高发人群），间断腹痛、腹胀、腹泻1年（慢性病程，迁延不愈，CD可有临床表现），腹痛常于进食后加重，排便后缓解，粪便呈糊状，一般无黏液脓血（CD腹泻特点），体查：T36.5℃（无发热），浅表淋巴结不大，心肺（-），腹平软，右下腹压痛（+）（CD可有腹痛表现）。钡剂灌肠检查见：回盲部纵行溃疡和鹅卵石征（鹅卵石征，克罗恩病的特征性病理改变），根据该患者的病史、查体及钡剂检查，该患者最可能的诊断是克罗恩病（B对），克罗恩病（CD）是一种病因不明的胃肠道慢性肉芽肿性疾病。肠结核（A错）是结核分枝杆菌引起的肠道慢性特异性感染，多有低热、盗汗、消瘦等结核毒血症状，结肠镜可发现回盲部黏膜充血、水肿、溃疡形成（十版内科学P383）。结肠癌（C错）多见于老年患者，排便习惯和粪便性状改变，多表现为血便或粪便隐血阳性，也可表现为腹泻，或腹泻与便秘交替，粪质无明显黏液脓血，结肠镜检可确诊（十版内科学P396）。肠淋巴结瘤（D错）一般进展较快，活检确诊，临床表现为非特异性的胃肠道症状，X线检见一肠段内广泛侵蚀，呈较大的指压痕或充盈缺损，超声、CT有利于诊断（十版内科学P393）。","c131","N"],["2019-N80",30,"第二节 克罗恩病","克罗恩病内镜检查",2019,80,"A","","男性，24岁。间断下腹痛、腹胀、腹泻1年余，腹痛常于进食后加重，排便后缓解，粪便呈糊状，一般无黏液和脓血，未进行系统检查和治疗，3天来再次发作。查体：T36.6℃，浅表淋巴结不大，心肺（-），腹平软，右下腹压痛（+），无肌紧张和反跳痛，肝脾未及。钡剂灌肠检查见回盲部纵行性溃疡和鹅卵石征。为确定诊断，最有意义的检查是",[["A","PPD试验"],["B","腹部B超"],["C","腹部CT"],["D","结肠镜检查及活检"]],"D","青年男性患者（CD高发人群），间断腹痛、腹胀、腹泻1年（慢性病程，迁延不愈，CD可有临床表现），腹痛常于进食后加重，排便后缓解，粪便呈糊状，一般无黏液脓血（CD腹泻特点），体查：T36.5℃（无发热），浅表淋巴结不大，心肺（-），腹平软，右下腹压痛（+）（CD可有腹痛表现）。钡剂灌肠检查见：回盲部纵行溃疡和鹅卵石征（鹅卵石征，克罗恩病的特征性病理改变），根据该患者的病史、查体及钡剂检查，该患者最可能的诊断是克罗恩病，克罗恩病（CD）是一种病因不明的胃肠道慢性肉芽肿性疾病，为明确诊断，首选结肠镜检查及活检（D对），若结肠镜发现肠道炎性病变主要在回肠末段与邻近结肠且呈阶段性分布，见纵行溃疡和裂隙溃疡、鹅卵石征，病变间的黏膜外观正常，活检肠壁全层炎，全层淋巴滤泡增生，非干酪性肉芽肿等则可确诊。PPD试验广泛应用于检出结核分枝杆菌的感染，本例可用于与肠结核的鉴别，及肠结核患者结肠镜可发现主要位于回盲部的炎症、溃疡、炎性息肉或肠腔狭窄。腹部CT（C错）和腹部B超对腹腔脓肿诊断有重要价值，CT检查对了解病变分布、肠腔狭窄程度以及通过肠壁增厚和强化等改变利于CD的诊断和鉴别诊断，B超可用于指导腹腔脓肿的穿刺引流。","c131","N"],["2019-N81",30,"第二节 克罗恩病","克罗恩病并发症",2019,81,"A","","男性，24岁。间断下腹痛、腹胀、腹泻1年余，腹痛常于进食后加重，排便后缓解，粪便呈糊状，一般无黏液和脓血，未进行系统检查和治疗，3天来再次发作。查体：T36.7℃，浅表淋巴结不大，心肺（-），腹平软，右下腹压痛（+），无肌紧张和反跳痛，肝脾未及。钡剂灌肠检查见回盲部纵行性溃疡和鹅卵石征。最常见的并发症是",[["A","肠穿孔"],["B","肠出血"],["C","肠梗阻"],["D","腹腔内脓肿"]],"C","青年男性患者（CD高发人群），间断腹痛、腹胀、腹泻1年（慢性病程，迁延不愈，CD可有临床表现），腹痛常于进食后加重，排便后缓解，粪便呈糊状，一般无黏液脓血（CD腹泻特点），体查：T36.5℃（无发热），浅表淋巴结不大，心肺（-），腹平软，右下腹压痛（+）（CD可有腹痛表现）。钡剂灌肠检查见：回盲部纵行溃疡和鹅卵石征（鹅卵石征，克罗恩病的特征性病理改变），根据该患者的病史、查体及钡剂检查，该患者最可能的诊断是克罗恩病，其最常见的并发症是肠梗阻（C对），其次为腹腔内脓肿（D错），偶可发生急性肠穿孔（A错）或大量便血（肠出血）（B错），直肠或结肠黏膜受累者可发生癌变。","c131","N"],["2019-N82",40,"第四节 IgA肾病","IgA肾病临床表现",2019,82,"A","","男性，19岁。尿呈洗肉水样1周，每日尿量约1000ml。临床拟诊为IgA肾病。对该患者诊断最有价值的病史是",[["A","有无上呼吸道感染后迅速发病"],["B","有无血压增高"],["C","有无水肿表现"],["D","有无肾功能减退"]],"A","患者青年男性，突发肉眼血尿一周，拟诊断为IgA肾病，最具有诊断价值的病史是上呼吸道感染后紧接出现血尿（A对）。IgA肾病好发于儿童和青少年，男性多见，多数患者起病前数小时或数日内有上呼吸道感染或消化道感染等前驱症状，主要表现为发作性的肉眼血尿或镜下血尿，可持续数小时或数日，肉眼血尿多为无痛性，部分患者表现为肾病综合征、严重高血压和肾功能损害（BCD错）。","","N"],["2019-N83",40,"第四节 IgA肾病","IgA肾病诊断",2019,83,"A","","男性，19岁。尿呈洗肉水样1周，每日尿量约1000ml。临床拟诊为IgA肾病。对确诊最有意义的检查是",[["A","尿沉渣红细胞相差显微镜检查"],["B","24小时尿蛋白定量"],["C","血清lgA检查"],["D","肾活检病理学检查"]],"D","患者青年男性，突发肉眼血尿一周，拟诊断为IgA肾病，IgA肾病的确诊有赖于肾活检免疫病理检查（D对）。尿液检查可表现为镜下血尿或肉眼血尿，以畸形红细胞为主，约60%的患者伴有少量蛋白尿（尿蛋白常＜1.0g/24h），部分患者可表现为肾病综合征，同时，30%～50%的患者伴有血清lgA增高，但这种现象对lgA肾病的诊断没有特异性（ABC错）。","","N"],["2019-N84",40,"第四节 IgA肾病","IgA肾病鉴别诊断",2019,84,"A","","男性，19岁。尿呈洗肉水样1周，每日尿量约1000ml。临床拟诊为IgA肾病。最需要鉴别的继发性IgA沉积的肾小球疾病是",[["A","过敏性紫癜肾炎"],["B","狼疮性肾炎"],["C","肾淀粉样变性"],["D","糖尿病肾病"]],"A","患者青年男性，突发肉眼血尿一周，拟诊断为IgA肾病，年轻病人出现镜下血尿和（或）蛋白尿，尤其是与上呼吸道感染有关的血尿，临床上应该考虑IgA肾病。最需要鉴别的继发性lgA沉积的肾小球肾病为过敏性紫癜性肾病（A对）。狼疮性肾炎（B错）是系统性红斑狼疮常见且严重的并发症，肾损害的临床表现主要有血尿和（或）蛋白尿，免疫复合物沉积以IgG为主，常伴IgM、IgA、C3、C4和C1q沉积，形成“满亮堂”现象，为其特征性表现。肾淀粉样变性（C错）是一种全身性疾病，由淀粉样物质沉积于肾脏所致，临床主要表现为蛋白尿、肾病综合征，后期肾功能可迅速恶化，最终导致肾衰竭。糖尿病肾病（D错）属于糖尿病的慢性并发症，好发于中老年人，肾小球系膜区的嗜伊红结节是诊断的可靠指标，免疫荧光检查可见IgG沉积，还可伴有IgM、C3等沉积。","","N"],["2019-N85",53,"第一节 霍奇金淋巴瘤","霍奇金淋巴瘤临床分期",2019,85,"A","","男性，36岁。左侧颈部淋巴结肿大1个月，在外院诊断为颈淋巴结结核，抗结核治疗半个月，效果不明显，自觉低热、盗汗。查体：T 38.1℃，双侧颈部和右侧腹股沟淋巴结肿大，最大者2×3cm大小，均活动，无压痛，心肺（-），腹平软，肝脾肋下未及。化验血Hb 126g/L，WBC 5.5×10⁹/L，Plt 175×10⁹/L。左侧颈部淋巴结活检发现R-S细胞，诊断为淋巴瘤。根据目前的临床资料，该患者最可能的临床分期是",[["A","Ⅰ期"],["B","Ⅱ期"],["C","Ⅲ期"],["D","Ⅳ期"]],"C","中年男性患者，左侧颈部淋巴结肿大1个月（淋巴瘤常见首发症状），自觉低热、盗汗（淋巴瘤可有全身症状）。查体：T 38.1℃（发热），双侧颈部和右侧腹股沟淋巴结肿大，最大者2×3cm大小，均活动，无压痛（无痛淋巴结肿大），心肺（-），腹平软，肝脾肋下未及（肝未受侵犯）。化验血Hb 126g/L，WBC 5.5×10⁹/L，Plt 175×10⁹/L。左侧颈部淋巴结活检发现R-S细胞，诊断为淋巴瘤，根据目前的临床资料，该患者横膈上下淋巴结区域同时受侵犯，肝未受侵犯，该患者最可能的临床分期是Ⅲ期（C对），该分期参考依据为Ann Arbor分期标准（1966年）。","c132","N"],["2019-N86",53,"第一节 霍奇金淋巴瘤","霍奇金淋巴瘤临床分期",2019,86,"A","","男性，36岁。左侧颈部淋巴结肿大1个月，在外院诊断为颈淋巴结结核，抗结核治疗半个月，效果不明显，自觉低热、盗汗。查体：T 38.1℃，双侧颈部和右侧腹股沟淋巴结肿大，最大者2×3cm大小，均活动，无压痛，心肺（-），腹平软，肝脾肋下未及。化验血Hb 126g/L，WBC 5.5×10⁹/L，Plt 175×10⁹/L。左侧颈部淋巴结活检发现R-S细胞，诊断为淋巴瘤。根据目前的全身症状，确定为B组，还应询问的病史是",[["A","有无皮肤瘙痒"],["B","有无食欲减退"],["C","有无体重减轻"],["D","有无腹痛、腹泻"]],"C","中年男性患者，左侧颈部淋巴结肿大1个月（淋巴瘤常见首发症状），自觉低热、盗汗（淋巴瘤可有全身症状，B组症状）。查体：T 38.1℃（发热，B组症状），双侧颈部和右侧腹股沟淋巴结肿大，最大者2×3cm大小，均活动，无压痛（无痛淋巴结肿大），心肺（-），腹平软，肝脾肋下未及（肝未受侵犯）。化验血Hb 126g/L，WBC 5.5×10⁹/L，Plt 175×10⁹/L。左侧颈部淋巴结活检发现R-S细胞提示淋巴瘤，诊断为淋巴瘤，根据病理结果，患者为霍奇金淋巴瘤（HL）。根据目前的全身症状，该患者确定为B组，根据病史，已知患者有不明原因发热（大于38℃）和盗汗症状，故还应询问的病史是有无体重减轻（C对）。","c132","N"],["2019-N87",53,"第一节 霍奇金淋巴瘤","霍奇金淋巴瘤治疗",2019,87,"A","","男性，36岁。左侧颈部淋巴结肿大1个月，在外院诊断为颈淋巴结结核，抗结核治疗半个月，效果不明显，自觉低热、盗汗。查体：T 38.1℃，双侧颈部和右侧腹股沟淋巴结肿大，最大者2×3cm大小，均活动，无压痛，心肺（-），腹平软，肝脾肋下未及。化验血Hb 126g/L，WBC 5.5×10⁹/L，Plt 175×10⁹/L。左侧颈部淋巴结活检发现R-S细胞，诊断为淋巴瘤。对该患者首选的治疗是",[["A","放射治疗"],["B","CHOP方案化疗"],["C","MOPP方案化疗"],["D","ABVD方案化疗"]],"D","中年男性患者，左侧颈部淋巴结肿大1个月（淋巴瘤常见首发症状），自觉低热、盗汗（淋巴瘤可有全身症状）。查体：T 38.1℃（发热），双侧颈部和右侧腹股沟淋巴结肿大，最大者2×3cm大小，均活动，无压痛（无痛淋巴结肿大），心肺（-），腹平软，肝脾肋下未及（肝未受侵犯）。化验血Hb 126g/L，WBC 5.5×10⁹/L，Plt 175×10⁹/L。左侧颈部淋巴结活检发现R-S细胞（骨髓浸润依据），诊断为淋巴瘤，根据病理结果，患者为霍奇金淋巴瘤（HL），最可能的临床分期是Ⅲ期，进展期（Ⅲ、Ⅳ期）病例主张以ABVD方案为金标准治疗，为该例首选。以及临床分期Ⅰ～Ⅱ期的HL，目前认为最佳治疗方案也是ABVD（D对）。","c132","N"],["2019-N88",59,"第二节 甲状腺功能减退症","甲状腺功能减退症诊断",2019,88,"A","","男性，68岁。5个月来渐进性乏力，食欲下降，1个月来嗜睡，活动后感心悸、气短，下肢水肿，便秘。无体重下降。既往无冠心病、糖尿病病史。查体：T 36℃，P 52次/分，BP 100/85mmHg，神情淡漠，高枕位，颜面水肿，皮肤干燥，颈静脉充盈，甲状腺不大，双肺（-），心界向两侧扩大，心律整，心音低，肝肋下1.5cm，双下肢胫前非凹陷性水肿（+），跟腱反射减弱。患者最可能的诊断是",[["A","渗出性心包炎"],["B","甲状腺功能减退症"],["C","慢性心力衰竭"],["D","慢性肾衰竭"]],"B","患者老年男性，近五个月出现无力，食欲下降（代谢率减低表现），1个月来嗜睡，活动后感心悸、气短，下肢水肿，便秘（甲减可有临床表现），查体：T 36℃（正常人体温36～37℃），P 52次/分（正常人心率为60～100次/分，心动过缓），BP 100/85mmHg（正常血压），神情淡漠，高枕位，颜面水肿，皮肤干燥，颈静脉充盈（甲减体征），甲状腺不大，双肺（-），心界向两侧扩大，心律整，心音低，肝肋下1.5cm（肝大），双下肢胫前非凹陷性水肿（+）（双下肢胫前粘液性水肿），跟腱反射减弱（甲减可有体征），根据患者的病史、临床表现、体征，患者最可能的诊断是甲状腺功能减退症（B对），甲状腺功能减退只是功能诊断，需要明确其发病原因和发病部位。渗出性心包炎（A错）主要表现为心脏压塞的表现，如动脉压下降、静脉压升高，心音遥远，奇脉等特点，结合该病例，患者无心包炎病史及诱因，其低代谢表现、下肢非凹陷性水肿无法用渗出型心包炎解释。慢性心力衰竭（C错）多存在心衰病因，可有心界扩大，颈静脉充盈，肝大等特点，一般存在下肢凹陷性水肿特点，与该病人的低代谢表现亦不符合。慢性肾功能衰竭（D错）有明显少尿，无尿，高氮质血症等肾衰特点。","c133","N"],["2019-N89",59,"第二节 甲状腺功能减退症","血清TSH、TT4和FT4",2019,89,"A","","男性，68岁。5个月来渐进性乏力，食欲下降，1个月来嗜睡，活动后感心悸、气短，下肢水肿，便秘。无体重下降。既往无冠心病、糖尿病病史。查体：T 36℃，P 52次/分，BP 100/85mmHg，神情淡漠，高枕位，颜面水肿，皮肤干燥，颈静脉充盈，甲状腺不大，双肺（-），心界向两侧扩大，心律整，心音低，肝肋下1.5cm，双下肢胫前非凹陷性水肿（+），跟腱反射减弱。对明确诊断最有价值的血液检查项目是",[["A","NT-proBNP"],["B","T₃、T₄、TSH"],["C","Cr、BUN"],["D","K⁺、Na⁺、Cl⁻"]],"B","患者老年男性，近五个月出现无力，食欲下降（代谢率减低表现），1个月来嗜睡，活动后感心悸、气短，下肢水肿，便秘（甲减可有临床表现），查体：T 36℃（正常人体温36～37℃），P 52次/分（正常人心率为60～100次/分，心动过缓），BP 100/85mmHg（正常血压），神情淡漠，高枕位，颜面水肿，皮肤干燥，颈静脉充盈（甲减体征），甲状腺不大，双肺（-），心界向两侧扩大，心律整，心音低，肝肋下1.5cm（肝大），双下肢胫前非凹陷性水肿（+）（双下肢胫前粘液性水肿），跟腱反射减弱（甲减可有体征），根据患者的病史、临床表现、体征，患者最可能的诊断是甲状腺功能减退症，对明确诊断最有价值的血液检查项目是甲状腺功能检查，即血清T₃、T₄、TSH（B对），甲状腺激素TT₄、FT₄降低是诊断甲减的必备指标，血清TSH是评估原发性甲状腺功能异常最敏感和最早期的一线指标，甲减时血清T₃减低。NT-proBNP（A错）用于明确心衰的程度及预后。Cr、BUN（C错）用于肾功能衰竭的分级及严重程度评估。K⁺、Na⁺、Cl⁻等电解质检查只是辅助了解疾病血生化变化，对于诊断疾病无帮助。","c133","N"],["2019-N90",59,"第二节 甲状腺功能减退症","甲状腺激素替代治疗",2019,90,"A","","男性，68岁。5个月来渐进性乏力，食欲下降，1个月来嗜睡，活动后感心悸、气短，下肢水肿，便秘。无体重下降。既往无冠心病、糖尿病病史。查体：T 36℃，P 52次/分，BP 100/85mmHg，神情淡漠，高枕位，颜面水肿，皮肤干燥，颈静脉充盈，甲状腺不大，双肺（-），心界向两侧扩大，心律整，心音低，肝肋下1.5cm，双下肢胫前非凹陷性水肿（+），跟腱反射减弱。该患者应选择的治疗原则是",[["A","替代治疗"],["B","手术治疗"],["C","免疫抑制剂治疗"],["D","放射治疗"]],"A","患者老年男性，近五个月出现无力，食欲下降（代谢率减低表现），1个月来嗜睡，活动后感心悸、气短，下肢水肿，便秘（甲减可有临床表现），查体：T 36℃（正常人体温36～37℃），P 52次/分（正常人心率为60～100次/分，心动过缓），BP 100/85mmHg（正常血压），神情淡漠，高枕位，颜面水肿，皮肤干燥，颈静脉充盈（甲减体征），甲状腺不大，双肺（-），心界向两侧扩大，心律整，心音低，肝肋下1.5cm（肝大），双下肢胫前非凹陷性水肿（+）（双下肢胫前粘液性水肿），跟腱反射减弱（甲减可有体征），根据患者的病史、临床表现、体征，患者最可能的诊断是甲状腺功能减退症，该患者应选择的治疗原则是替代治疗（A对），服用药物首选左甲状腺素（L-T₄）单药治疗，剂量取决于甲减的程度、病因、年龄、性别和个体差异。甲状腺功能减退症的治疗不涉及手术治疗（B错）、免疫抑制剂治疗（C错）、放射治疗（D错）。","c133","N"],["2019-N91",71,"第六节 贝赫切特病","贝赫切特病诊断",2019,91,"A","","女性，31岁。反复口腔溃疡伴间断双膝关节游走性肿痛1年，近1周自觉左眼视物不清，并出现间断下腹痛。该患者最可能的诊断是",[["A","系统性红斑狼疮"],["B","风湿热"],["C","类风湿关节炎"],["D","贝赫切特（Behcet）病"]],"D","青年女性患者，反复口腔溃疡（贝赫切特病最重要症状和必须诊断标准）伴间断双膝关节游走性肿痛1年（关节受累），近一周自觉左眼视物不清（眼受累，出现眼炎，诊断标准之一），伴间断下腹痛（消化道受累），根据患者的病史、临床表现和体征，该患者最可能的诊断是贝赫切特（Behcet）病（D对），又称白塞病，是一种病因未明、以口腔溃疡、外阴溃疡、眼炎及皮肤损害为临床特征的自身免疫性疾病。系统性红斑狼疮（A错）是一种以致病性自身抗体和免疫复合物形成并介导器官、组织损伤的自身免疫病，主要表现为发热、皮疹（蝶形红斑、盘状红斑）、对称性多关节（指、腕、膝关节）疼痛肿胀及视网膜出血水肿（十版内科学P820）。风湿热（B错）是一种因A组链球菌感染咽部引起的迟发性、非化脓性后遗症，有前驱感染症状（咽喉炎或扁桃体炎），主要表现环形红斑、皮下结节、舞蹈病、关节炎多为游走性、多发性，疼痛通常在2周内消退（十版内科学P869）。类风湿关节炎（C错）是一种以侵蚀性、对称性多关节炎为主要临床表现的慢性、全身性自身免疫性疾病，主要表现为对称性双手、腕关、足等多关节肿痛，常伴有晨僵，可伴有乏力、低热、肌肉酸痛、体重下降等全身症状（十版内科学P814）。","","N"],["2019-N92",71,"第六节 贝赫切特病","皮肤病变",2019,92,"A","","女性，31岁。反复口腔溃疡伴间断双膝关节游走性肿痛1年，近2周自觉左眼视物不清，并出现间断下腹痛。该病特异性的皮肤表现是",[["A","结节性红斑"],["B","盘状红斑"],["C","类风湿结节"],["D","环形红斑"]],"A","青年女性患者，反复口腔溃疡（贝赫切特病最重要症状和必须诊断标准）伴间断双膝关节游走性肿痛1年（关节受累），近一周自觉左眼视物不清（眼受累，出现眼炎，诊断标准之一），伴间断下腹痛（消化道受累），根据患者的病史、临床表现和体征，该患者最可能的诊断是贝赫切特（Behcet）病，又称白塞病，是一种病因未明、以口腔溃疡、外阴溃疡、眼炎及皮肤损害为临床特征的自身免疫性疾病，该病特异性的皮肤表现是结节性红斑（A对）最为常见，见于70％的病人，为对称性，多见于下肢膝盖以下部位。盘状红斑（B错）见于系统性红斑狼疮。类风湿结节（C错）见于类风湿关节炎。环形红斑（D错）见于风湿热。","","N"],["2019-N128",21,"第三节 二尖瓣狭窄","二尖瓣狭窄诊断",2019,128,"B","","最易发生左心功能不全临床表现的心脏瓣膜病是",[["A","主动脉瓣狭窄"],["B","主动脉瓣关闭不全"],["C","二尖瓣狭窄"],["D","二尖瓣关闭不全"]],"C","心功能不全是由不同病因导致的心脏舒缩功能异常，包括心脏泵血功能受损尚处于完全代偿至失代偿阶段的全过程，心力衰竭属于心功能的失代偿状态，两者在发病学上本质相同，只是程度上有所区别。左心功能不全以肺淤血及心排血量降低表现为主，如不同程度的呼吸困难：劳力性呼吸困难、端坐呼吸、夜间阵发性呼吸困难、最严重可有急性肺水肿，也有咳嗽、咳痰、咯血，全身症状可有乏力、疲倦、头晕、心慌等，为心排血量不足，器官、组织灌注不足及代偿性心率加快所致的主要症状。最易发生左心功能不全临床表现的心脏瓣膜病是二尖瓣狭窄（C对），其最早出现的血流动力学改变是左心房压力升高，这种压力增高是一个渐进的过程，最终可传导到肺静脉造成肺淤血，慢性肺静脉压力增高，可导致肺动脉压力增加。单纯性二尖瓣关闭不全（D错）的病程往往较漫长，其无症状期可达数十年，一旦出现症状，则左心功能急转直下，会发生明显的症状。主动脉瓣狭窄（A错）可经历相当长的无症状期，一旦出现则进展迅速，典型的症状为劳力性呼吸困难（病变晚期）、心绞痛和晕厥三联征，早期症状多不典型，易被忽视。慢性主动脉瓣关闭不全因左心室代偿性改变可在很长一段时间内没有症状，严重时可有左心衰症状，急性主动脉瓣关闭不全患者症状主要与反流的严重程度有关，轻者无症状，重者出现左心衰或肺水肿、心源性休克、心肌缺血表现，甚至猝死（B错）。","","N"],["2019-N129",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄诊断",2019,129,"B","","最易引发左心室肥厚临床表现的心脏瓣膜病是",[["A","主动脉瓣狭窄"],["B","主动脉瓣关闭不全"],["C","二尖瓣狭窄"],["D","二尖瓣关闭不全"]],"A","最易引发左心室肥厚临床表现的心脏瓣膜病是主动脉瓣狭窄（A对），其病理学典型特点为左心室增厚（三版八年制临床诊断学P227），因主动脉瓣狭窄使左心室排血明显受阻，收缩压明显升高，跨瓣压差显著，逐渐产生左心室肥厚。主动脉瓣关闭不全（B错）、二尖瓣关闭不全（D错）在病程后期也会逐渐发展为心室肥厚。二尖瓣狭窄（C错）主要引起左心房肥大。","","N"],["2019-N130",75,"第一节 中毒概述","眼部表现",2019,130,"B","","引起瞳孔明显缩小的中毒是",[["A","阿托品中毒"],["B","有机磷中毒"],["C","甲醇中毒"],["D","乙醇中毒"]],"B","引起瞳孔明显缩小的中毒是有机磷中毒（B对），有机磷（OPI）进入人体后，抑制乙酰胆碱酯酶活性，会引起机体内生理效应部位乙酰胆碱大量蓄积，过度兴奋胆碱能神经，出现一系列毒蕈碱样、烟碱样和中枢神经系统症状。如平滑肌痉挛表现有瞳孔缩小（B对）、恶心、呕吐、腹痛等和肌纤维颤动、全身肌强直性痉挛等。阿托品中毒（A错）会出现瞳孔明显扩大、神志模糊、烦躁不安、抽搐、昏迷和尿潴留等。甲醇中毒（C错）以代谢性酸中毒为主要特征，眼部损害会导致视乳头水肿、视神经髓鞘破坏等。乙醇中毒（D错）即酒精中毒，急性中毒以行为异常和意识障碍为主要表现，严重者损害器官功能，导致呼吸循环衰竭。","","N"],["2019-N131",75,"第一节 中毒概述","眼部表现",2019,131,"B","","引起瞳孔明显扩大的中毒是",[["A","阿托品中毒"],["B","有机磷中毒"],["C","甲醇中毒"],["D","乙醇中毒"]],"A","引起瞳孔明显扩大的中毒是阿托品中毒（A对），同时还会出现神志模糊、烦躁不安、抽搐、昏迷和尿潴留等症状。阿托品可用于缓解M样症状，临床停药指征为病人M样症状消失或出现“阿托品化”，阿托品化指征为口干、皮肤干燥、心率增快（90～100次/分）和肺湿啰音消失，此时，应减少阿托品剂量或停用，如未及时处理，易出现阿托品中毒症状，需要立即停药。有机磷中毒（B错）时机体会出现一系列毒蕈碱样、烟碱样和中枢神经系统症状，如平滑肌痉挛表现有瞳孔缩小、恶心、呕吐、腹痛等和肌纤维颤动、全身肌强直性痉挛等。甲醇中毒（C错）以代谢性酸中毒为主要特征，眼部损害会导致视乳头水肿、视神经髓鞘破坏等。乙醇中毒（D错）即酒精中毒，急性中毒以行为异常和意识障碍为主要表现，严重者损害器官功能，导致呼吸循环衰竭。","","N"],["2019-N132",35,"第一节 肝硬化","促进体内氨的代谢",2019,132,"B","","对肠黏膜细胞有营养作用的药物是",[["A","支链氨基酸"],["B","谷氨酰胺"],["C","精氨酸"],["D","核苷酸"]],"B","对肠黏膜细胞有营养作用的药物是谷氨酰胺（B对），它是肠道黏膜细胞代谢的必需物质，能起到保护胃肠黏膜的作用，增强肠道细胞活性，改善肠道免疫功能。支链氨基酸（A错）是一种以亮氨酸异亮氨酸、缬氨酸等为主的氨基酸，在机体内其机制为竞争性抑制芳香族氨基酸进入大脑，减少假性神经递质的形成，其疗效尚有争议，但对于不能耐受蛋白质的营养不良者，补充支链氨基酸有助于改善其氮平衡，可用于肝功能受损患者的营养支持治疗。精氨酸（C错）、核苷酸（D错）对于营养肠黏膜无特殊意义。","","N"],["2019-N133",35,"第一节 肝硬化","调节神经递质",2019,133,"B","","肝功能不全病人肠外营养时应选用的药物是",[["A","支链氨基酸"],["B","谷氨酰胺"],["C","精氨酸"],["D","核苷酸"]],"A","芳香族氨基酸（酪氨酸、苯丙氨酸）体内代谢可产生假性神经递质，肝功能不全病人对假性神经递质处理能力下降，易导致肝性脑病，故肝功能不全病人肠外营养时应选用的药物是静脉或口服支链氨基酸（A对），可改善支链氨基酸/芳香族氨基酸比例。谷氨酰胺（B错）可用于营养肠黏膜，维持正常肠道的机械屏障作用，促进脑、肾利用和消耗氨，降低血氨，减轻脑水肿。精氨酸（C错）、核苷酸（D错）对于肝功能异常患者无特殊治疗意义。","","N"],["2019-N154",12,"第一节 急性呼吸窘迫综合征","机械通气",2019,154,"X","","急性呼吸窘迫综合征机械通气的治疗原则",[["A","保持尽量大的潮气量，维持PaCO₂在正常范围内"],["B","给予一定量的PEEP，使萎陷的肺泡开放"],["C","初始上机给予高水平的PEEP，保证PaO₂尽快达到60mmHg以上"],["D","吸气平台压控制在30～35cmH₂O以下，防止肺泡过度扩张"]],"BD","急性呼吸窘迫综合征的肺部病变具有“不均一性”和“小肺”的特点，故其进行机械通气的关键在于，复张萎陷的肺泡并使其维持开放状态，以增加肺容积和改善氧合，同时避免肺泡过度扩张和反复开闭造成的损伤，其治疗原则推荐保护性通气策略，及合适水平的PEEP和小潮气量（A错）。适当水平的PEEP可使萎陷的肺泡扩张（B对），措施主要包括从低水平开始，从5cmH₂O逐渐增加至合适水平（C错），争取维持PaO₂＞60mmHg而FiO₂＜0.6。小潮气量（即4～8ml/kg）旨在将吸气平台压控制在30cmH₂O以下，防止肺泡过度扩张（D对），同时为保证小潮气量，可允许一定程度的CO₂潴留和呼吸性酸中毒（pH7.25～7.30）","","N"],["2019-N155",24,"第一节 心脏骤停与心脏性猝死","心脏骤停与心脏性猝死病因",2019,155,"X","","在冠心病好发年龄前（＜35岁），心源性猝死的原因",[["A","Brugada综合征"],["B","肥厚型梗阻性心肌病"],["C","长QT间期综合征"],["D","X综合征"]],"ABC","心脏性猝死（SCD）是指急性症状发作后1小时内发生的以意识突然丧失为特征的、由心脏原因引起的自然死亡，绝大多数心源性猝死发生在有器质性心脏病的病人，在冠心病好发年龄前，各种心肌疾病引起心脏性猝死的主要原因，如梗阻性肥厚型心肌病（B对）、致心律失常型右心室心肌病，此外还有离子通道病，如长QT间期综合征（C对）、Brugada综合征等（A对）。X综合征（D错）以绝经期前女性多见，病人具有心绞痛或类似于心绞痛的症状，运动平板试验出现ST段下移而冠状动脉造影无异常表现，预后通常良好。","","N"],["2019-N156",27,"第二节 慢性胃炎","慢性胃炎诊断",2019,156,"X","","有助于诊断自身免疫性胃炎的实验室检查有",[["A","血清维生素B₁₂水平"],["B","幽门螺旋杆菌检测"],["C","血清抗壁细胞抗体"],["D","血清内因子抗体"]],"ACD","自身免疫性胃炎（A型萎缩性胃炎）是在自身免疫基础上以胃体萎缩为主的慢性胃炎，患者血液中存在自身抗体即壁细胞抗体和内因子抗体，前者使壁细胞总数减少，导致胃酸分泌减少或缺乏，后者使内因子缺乏，引起维生素B₁₂吸收不良，导致恶性贫血，故有助于诊断自身免疫性胃炎的实验室检查有血清抗壁细胞抗体（C对）、内因子抗体（D对）及维生素B₁₂水平测定（A对）。幽门螺旋杆菌检测（B错）常用于Hp（幽门螺旋杆菌）感染相关性胃炎。","","N"],["2019-N157",39,"第一节 总论","肾炎综合征",2019,157,"X","","以血尿、蛋白尿、水肿和高血压为特点的综合征有",[["A","急性肾炎综合征"],["B","肾病综合征"],["C","慢性肾炎综合征"],["D","慢性肾功能衰竭综合征"]],"AC","以血尿，蛋白尿，水肿，高血压为特点的综合征是肾炎综合征。根据病程长短又可分为三种类型：①急性肾炎综合征（A对），最典型的为链球菌感染后急性肾小球肾炎；②急进型肾炎综合症，除血尿和蛋白尿外，主要特征是短时间内出现高血压和（或）肾功能损害；③慢性肾炎综合征（C对），即慢性肾炎，病程缓慢，以蛋白尿、血尿、高血压和水肿为基本临床表现，随着病情进展可出现肾功能损害。肾病综合征（B错）（十版内科学P480）是以大量蛋白尿（＞3.5g/d）和低白蛋白血症（＜30g/L），常伴有水肿和（或）高脂血症为特征的一组疾病。慢性肾衰竭（D错）（十版内科学P525）是各种慢性肾脏病持续进展至后期的共同结局，它是以代谢产物潴留，水、电解质及酸碱平衡失调和全身各系统症状为表现的一种临床综合征。","","N"],["2019-N158",55,"第一节 出血性疾病概述","纤溶异常",2019,158,"X","","提示纤溶异常的实验室检查有",[["A","3P实验"],["B","D-二聚体测定"],["C","PC、PS测定"],["D","FDP测定"]],"ABD","纤溶系统实验室检查的项目分为筛检试验和诊断试验两大类。其中筛检试验包括：血浆D-二聚体测定（B对）、血浆纤维蛋白（原）降解产物（FDP）测定（D对）及优球蛋白溶解时间测定。诊断试验包括：血浆组织型纤溶酶原激活物测定、血浆纤溶酶原活性测定、血浆纤溶酶原激活抑制物-1活性测定、血浆鱼精蛋白副凝固试验（3P实验）（A对）及血浆纤溶酶-抗纤溶酶复合物测定。PC（proteinC）（十版内科学P635）、PS（proteinS）测定（十版内科学P617）（C错）是抗凝系统而非纤溶系统的实验室检查项目。","","N"],["2019-N159",61,"第一节 糖尿病","T1DM的临床特点",2019,159,"X","","关于免疫介导性T1糖尿病（1A型）的临床特点，正确的有",[["A","多数青少年患者起病隐匿"],["B","诊断时临床表现变化大"],["C","多数患者起病初期都需要胰岛素治疗"],["D","多数患者血浆基础胰岛素水平低于正常"]],"BCD","免疫介导1型糖尿病（A1型）是某些外界因素（如病毒感染、化学毒物和饮食等）作用于有遗传易感性的个体，激活T淋巴细胞介导一系列自身免疫反应，选择性引起胰岛β细胞破坏和功能衰竭，从而导致的糖尿病。患者大多在25岁前起病，多数青少年病人起病较急，症状较明显（A错）。多数人临床表现变化很大（B对），不同年龄以及不同起病速度的临床表现存在年龄差异，可以是轻度非特异性症状、典型三多一少症状或昏迷。多数患者起病初期都需要胰岛素治疗（C对），使代谢恢复正常，但此后可能有持续数周至数个月不等的时间需要的胰岛素剂量很小，即所谓“蜜月期”，这是由于β细胞功能得到了部分恢复。多数患者血浆基础胰岛素水平低于正常（D对），葡萄糖刺激后胰岛素分泌曲线低平。","","N"],["2020-N42",15,"第二节 慢性心力衰竭","X线检查",2020,42,"A","","下列符合慢性心力衰竭胸部X线片影像学特点的是",[["A","双下肺野纹理增多"],["B","双上肺野片絮状影"],["C","肺门呈蝴蝶状"],["D","呈现KerleyB线"]],"D","不同部位的肺泡隔水肿增厚会形成小叶间隔线（Kerley A、B、C线），此时胸膜下和（或）胸腔少量积液，Kerley B 线位于肋膈角区，水平横行，长2～3cm，宽1～3mm，是慢性肺淤血的特征性表现，常见于二尖瓣狭窄及慢性左侧心力衰竭（D对）。肺泡性肺水肿的典型特征是两肺门为中心形成“蝴蝶”状阴影，短期内变化迅速，常见于急性左侧心力衰竭和尿毒症（C错）。慢性心力衰竭早期肺静脉压增高时，主要表现为肺门血管影增强，上肺血管影增多与下肺纹理密度相仿甚至多于下肺（A错）。肺上部有云絮状阴影（B错）可见于结核病、高原病。","","N"],["2020-N43",10,"第三节 慢性肺源性心脏病","肺血管阻力增加的功能性因素",2020,43,"A","","慢性阻塞性肺疾病患者发生肺动脉高压的最重要机制是",[["A","肺微小动脉广泛血栓形成"],["B","红细胞增多，血液黏稠度增加"],["C","肺小静脉管壁增厚"],["D","缺氧致肺小动脉收缩，肺血管重构"]],"D","慢性肺源性心脏病肺动脉高压最主要的机制是慢性缺氧引起的肺血管收缩，同时还可以引起以管壁增厚、管腔狭窄为特征的肺血管的结构改建，最终导致持续的肺动脉高压，其中血管结构改建的主要表现为小动脉中层平滑肌增厚（C错），肺血管壁中成纤维细胞肥大、增生，血管壁中胶原和弹性纤维沉积，与血管平滑肌细胞增殖肥大共同作用导致血管壁增厚、管腔狭窄、血管硬化、反应性降低（D对）。持久的肺动脉高压可增加右心室后负荷而导致右心室肥大以致衰竭，是高原心脏病和肺源性心脏病的主要发病环节。部分慢性肺心病急性发作期患者存在多发性肺微小动脉原位血栓形成，引起血管阻力增加，加重肺动脉高压（A错）；长期的慢性缺氧，导致促红细胞生成素分泌增加，继发性红细胞生成增多，血液黏滞度增高，肺血流阻力增高（B错），以上均与肺动脉高压形成有关，但不是其发生的主要机制。","","N"],["2020-N44",2,"第一节 支气管哮喘","支气管舒张试验",2020,44,"A","","男性，21岁。自幼对花粉过敏，多次接触花粉后出现荨麻疹及喘息。此次再次接触花粉后喘息6小时。查体：双肺可闻及散在哮鸣音，此时不宜进行的检查是",[["A","血嗜酸粒细胞计数"],["B","支气管激发试验"],["C","支气管舒张试验"],["D","胸部X线片"]],"B","青年男性患者，花粉过敏史，6小时前再次接触花粉后喘息发作（典型支气管哮喘发作），查体：双肺可闻及散在哮鸣音（支气管哮喘发作典型体征），根据患者病史、临床表现和体征，初步诊断为支气管哮喘，此时不宜进行的检查支气管激发试验（B错，为本题正确答案），因患者处于明显的支气管哮喘发作期，而支气管激发试验（BPT）主要用于协助支气管哮喘的诊断，但其检查对象为无症状、体征，或有可以哮喘病史，或在症状缓解期，肺功能正常者，或者仅以咳嗽为主要表现的变异型哮喘患者。支气管舒张试验（C对）用于测定气道可逆性，支气管舒张药可以使哮喘发作时气道痉挛得到缓解和改善，肺功能指标好转。过敏性哮喘患者可有血嗜酸性粒细胞计数升高，有助于确诊（A对）。胸部X片（D对）在哮喘发作早期可见两肺透亮度增加。","","N"],["2020-N45",6,"第一节 肺结核","肺结核诊断",2020,45,"A","","女性，42岁。低热、咳嗽、少量痰中带血3周。胸片显示右上肺斑点状阴影。该患者最可能的诊断是",[["A","肺炎"],["B","肺结核"],["C","肺脓肿"],["D","肺癌"]],"B","中年女性患者，低热，咳嗽，少量痰中带血3周（结核杆菌感染症状），胸片显示右上肺斑点状阴影（肺结核活动性病变影像学表现），根据患者临床表现和影像学检查结果，最可能的诊断是肺结核（B对）。肺炎（A错）的临床表现、体征、X线征象与感染的病原体有关，多表现为发热，咳嗽、咳痰明显，血白细胞计数增高，抗生素治疗有效；胸片可根据不同细菌感染有不同表现如肺实变、肺叶弧形下坠、下叶斑片浸润等。肺脓肿（C错）临床特征为高热、咳嗽、咳大量脓臭痰，胸片表现为带有液平面的空洞伴周围浓密的炎性阴影，血白细胞计数增高。肺癌（D错）临床表现与肿瘤大小、类型、发展阶段、所在部位、有无并发症或转移有密切关系，患者多有长期吸烟史，表现为刺激性咳嗽、痰中带血、胸痛和消瘦等症状，胸部X线或CT常表现肺癌肿块常呈分叶状，有毛刺、切迹；癌组织坏死液化后，可形成偏心厚壁空洞。","","N"],["2020-N46",4,"第二节细菌性肺炎","葡萄球菌肺炎诊断",2020,46,"A","","男性，35岁。高热、寒战5天，伴胸痛，咳脓性痰带少量血丝。查体：双肺散在湿啰音。胸片检查显示双肺多发实变影伴部分空洞病变形成。血化验：WBC23.0×10⁹/L，N91%。该患者最可能的诊断是",[["A","肺炎支原体肺炎"],["B","军团菌肺炎"],["C","肺炎链球菌肺炎"],["D","金黄色葡萄球菌肺炎"]],"D","中年男性患者，高热，寒战5天，伴胸痛，咳脓性痰带少量血丝（葡萄球菌肺炎可有症状）。查体：双肺散在湿啰音（葡萄球菌肺炎可有体征）。胸片检查显示双肺多发实变阴影伴部分空洞病变形成（葡萄球菌肺炎典型X线表现）。血化验：WBC23×10⁹/L（成年人正常白细胞计数3.5～9.5×10⁹/L，白细胞计数明显升高），N91%（中性粒细胞正常比例50～75%，中性粒细胞比例增加），根据患者临床表现、体征，实验室检查结果和影像学表现，该患者最可能的诊断是金黄色葡萄球菌肺炎（D对），肺浸润、肺脓肿、肺气囊肿和脓（气）胸是葡萄球菌尤其是金葡菌肺炎的四大X线特征，在不同类型和病期以不同的组合出现，有助于诊断。肺炎支原体肺炎（A错）临床起病较缓慢，发热一般在38℃，干咳为最突出症状，呈阵发性剧咳嗽，痰液常为白色，或带有血丝，胸片早期为间质性改变，后期可见肺门向肺野外周伸展的扇形阴影。军团菌肺炎（B错）肺外症状明显，相对缓脉、低钠血症、低磷血症以及β-内酰类抗生素治疗无效提示本病，X线胸片表现为斑片状影或肺段实变，偶有空洞形成和胸腔积液。肺炎链球菌（C错）发病前常有淋雨受凉、过度疲劳等诱因，典型临床表现为急性起病，高热、寒战、咳嗽、咳痰、呼吸急促和胸痛，咳嗽始为干咳，之后出现脓痰，部分患者有痰中带血或咳铁锈色痰，X线胸片呈叶段实变，累及胸膜时可有胸膜摩擦音。","","N"],["2020-N47",17,"第四节 急性冠状综合征","其他",2020,47,"A","","男性，60岁。突发左胸持续压榨性疼痛伴大汗3小时，自含速效救心丸无效，急送来院。查体：P85次/分，BP80/50mmHg，神清，四肢皮肤发凉，双肺未闻及啰音，心律不整，心尖部S₁低钝。心电图示：窦性心律，偶发房性早搏，Ⅰ、aVL、V₂～V₆导联ST段抬高，T波倒置。下列急诊处理正确的是",[["A","积极静脉输液扩容"],["B","静脉注入利多卡因"],["C","静脉滴注硝酸甘油"],["D","置入主动脉内球囊反搏"]],"D","60岁老年男性患者（STEMI高发人群），左胸部压榨性疼痛伴大汗3小时，自含速效救心丸无效（STEMI典型胸痛临床表现），查体：P85次/分，BP80/50mmHg，四肢皮肤发凉，双肺未闻及啰音，心律不整，S₁低钝（心源性休克临床表现），心电图示：窦性心律，偶有房性早搏，I，aVL，V₂～V₆导联ST段抬高，T波倒置（急性广泛前壁心肌梗死心电图表现），根据患者临床表现、体征及影像学检查结果，最可能的诊断是急性广泛前壁心肌梗死（心电图提示左前降支病变，考虑急性左心梗死）。此时患者已经心源性休克，病因治疗是治疗心源性休克的关键，急性心肌梗死的首要治疗就是再灌注治疗，主动脉球囊反搏是急性心肌梗死合并心源性休克经常使用的辅助治疗方法，提倡在休克发生的早期及时使用，故该患者急救措施恰当的是放置主动脉球囊反搏装置（D对），主动脉球囊反搏装置（IABP）以增高舒张动脉压而不增加左心室收缩期负荷，并有助于增加冠状动脉灌流，为STEMI合并心源性休克患者接受冠状动脉造影和机械性再灌注（PCI或CABG）提供重要的过渡和机会，此时患者的Ⅰ类推介，对大面积STEMI或高危患者应考虑预防性使用IABP。患者为心源性休克（左心梗死），补液治疗会增加左心前负荷，增加做功及耗氧量（A错）。利多卡因（B错）主要用于室性心律失常，如心脏手术、心导管术、心肌梗死或强心苷中毒导致的室性心动过速或心室纤颤。硝酸甘油（C错）因其血管舒张作用可降低血压，引起心脑等重要器官灌注压过低，不适用于本例患者。","","N"],["2020-N48",18,"第一节 原发性高血压","血压控制目标值",2020,48,"A","","男性，72岁。患高血压病20年，糖尿病15年。近2年来活动能力明显下降，上两层楼即感气短。查体：双肺底可闻及湿啰音，心率78次/分，下肢无水肿。HbA1c7.8%，NT-proBNP865pg/ml，eGFR48ml/min﹒1.73m²。该患者血压控制目标值应是",[["A","＜150/90mmHg"],["B","＜140/90mmHg"],["C","＜130/90mmHg"],["D","＜130/80mmHg"]],"D","72岁老年男性患者，高血压糖尿病病史，日常活动能力下降，上两层楼气喘，双肺底可闻及湿啰音，下肢无水肿（心功能NYHAⅢ级，慢性左心衰），糖化血红蛋白（正常值3%～6%升高），NT-proBNP865pg/ml（＞500pg/ml，升高，提示心衰），eGFR 48ml/min·1.73㎡（＜60ml/min·1.73㎡，提示肾功能不全），根据患者病史，该患者为糖尿病、肾功能不全、心力衰竭的高血压患者，此时血压控制目标为＜130/80mmHg（D对）。小于140/90mmHg（B错）为一般高血压病人的控制目标值。","","N"],["2020-N49",21,"第三节 二尖瓣狭窄","房颤",2020,49,"A","","在慢性心脏瓣膜病中，最容易引起心房颤动的瓣膜损害是",[["A","二尖瓣关闭不全"],["B","二尖瓣狭窄"],["C","主动脉瓣关闭不全"],["D","主动脉瓣狭窄"]],"B","二尖瓣狭窄时，心舒张期左心房充盈、左心室受限，导致左心房压力增高，左心房压力增高和左心房扩大，容易导致心房颤动（B对）。二尖瓣关闭不全（A错）的并发症与二尖瓣狭窄相似，但出现较晚，感染性心内膜炎较多见，栓塞少见。10%主动脉狭窄（D错）病人可发生房颤。主动脉关闭不全（C错）常并发室性心律失常。","","N"],["2020-N50",26,"第一节 胃食管反流病","食管外症状",2020,50,"A","","胃食管反流病的食管外症状是",[["A","胸痛"],["B","咳嗽"],["C","吞咽困难"],["D","烧心"]],"B","胃食管反流病的食管外症状包括无季节性发作性夜间哮喘、咳嗽（B对）、睡醒后声音嘶哑、咽炎、中耳炎、牙龈炎、癔球症、牙釉质腐蚀等。反流液侵蚀咽部、声带和气管而引起慢性咽炎、慢性声带炎和气管炎，被称为Delahunty综合征，胃反流液和胃内容物进入呼吸道尚可导致吸入性肺炎。胸痛（A错）、吞咽困难（C错）、烧心（D错）均为食管症状，反流和烧心是最典型的症状。","","N"],["2020-N51",38,"第一节 消化道出血","胶囊内镜及小肠镜",2020,51,"A","","目前判断小肠出血部位和病因的最佳辅助检查是",[["A","消化道X线钡剂造影"],["B","胃镜和结肠镜"],["C","胶囊内镜"],["D","腹部B超"]],"C","小肠出血属于中消化道出血，内镜检查是消化道出血定位、定性诊断的首选方法，诊断正确率高，可解决大部分消化道出血的病因诊断，胶囊内镜和小肠镜是诊断小肠出血部位和病因最有效的辅助检查（C对），胶囊内镜具有安全、创伤小的优点，对怀疑小肠出血检出率约为38%～83%，小肠镜具有可活检、可提供治疗（病灶标记、止血、息肉切除）等优点。消化道X线钡剂造影（A错）在急性消化道出血期间不宜选择，仅适用于出血已停止和病情稳定的患者，对急性消化道出血病因诊断的阳性率不高，特别对小肠出血的诊断率低，目前不推荐使用。胃镜检查可以在直视下观察食管、胃、十二指肠球部至降部，从而判断出血的病因、部位，结肠镜是诊断大肠及回肠末端病变的首选检查方法（B错）。腹部B超（D错）对胃肠道的显示较差，多用于诊断胆道出血。","","N"],["2020-N52",30,"第一节 溃疡性结肠炎","溃疡性结肠炎诊断",2020,52,"A","","男性，30岁。反复腹泻、黏液脓血便1年余，加重3天。既往体健。查体：T36.7℃，轻度贫血貌，心肺检查未见异常，腹软，左下腹明显压痛，无肌紧张、反跳痛，肝脾肋下未触及，肠鸣音6～8次/分。粪便培养未见病原菌，广谱抗菌药物治疗1周无效。该患者最可能的诊断是",[["A","肠易激综合征"],["B","溃疡性结肠炎"],["C","慢性细菌性痢疾"],["D","克罗恩病"]],"B","中年男性患者，反复腹泻、黏液脓血便（UC典型症状），体温不高，伴有轻度贫血貌（UC全身表现）、左下腹疼痛，无肌紧张，反跳痛（UC可有体征），粪便细菌培养阴性，广谱抗生素治疗无效（排除细菌感染），根据患者的病史、临床表现、既往史最可能的诊断为溃疡性结肠炎（UC）（B对），UC是一种病因尚不明确的直肠和结肠慢性非特异性炎症性疾病，临床表现为腹泻、黏液脓血便、腹痛，病情轻重不等，多呈反复发作的慢性病程。肠易激综合征（A错）粪便可有黏液但无脓血，显微镜检查正常，结肠镜检查无器质性病变。克罗恩病（D错）脓血便无或少见，腹痛多位于右下腹或脐周，内镜检查和活检有助于鉴别。慢性细菌性痢疾（C错）属于感染性肠炎，粪便致病菌培养可分离出致病菌，抗生素治疗有效。","","N"],["2020-N53",40,"第二节 急性肾小球肾炎","急性肾小球肾炎治疗",2020,53,"A","","男性，18岁。发热、咽痛2周后出现颜面水肿、血压升高（160/90mmHg）2天来诊。既往体健。化验尿蛋白（++），沉渣镜检红细胞20～25个/HP，抗链“O”1∶800，血清C3降低。治疗该患者高血压的首选药物是",[["A","利尿剂"],["B","β受体拮抗剂"],["C","钙通道阻滞剂"],["D","血管紧张素转换酶抑制剂"]],"A","青年男性患者，于感染后2周起病，血压升高，颜面水肿，伴尿蛋白（++）、沉渣镜检红细胞20～25个/HP（正常值＜3个/Hp），血清抗链球菌溶血素“O”滴度升高（参考值：阴性），血清C3降低，综合该患者的病史、查体、实验室检查，该患者最可能的疾病是急性肾小球肾炎。对于急性肾小球肾炎引起的一过性轻中重高血压，常与水钠潴留有关，因此治疗该患者高血压的首选药物是利尿剂（A对），经利尿后，血压仍高的患者可选用ACEI/ARB（D错），此类药物除降压以外，还具有保护肾脏，降低蛋白尿的作用。β受体拮抗剂（B错）、钙通道阻滞剂（C错）均是临床上常用的降压药，但都不是急性肾小球肾炎所引起的高血压的首选药。","","N"],["2020-N54",52,"第二节 急性白血病","AML的FAB分型",2020,54,"A","","女性，26岁。乏力、皮下瘀斑1周诊断急性髓系白血病入院。化验血常规：Hb85g/L，WBC25.4×10⁹/L，Plt25×10⁹/L，骨髓检查见原始粒细胞71%，早幼粒细胞2%，其他各阶段粒细胞12%，单核细胞8%。该患者急性白血病的FAB分类属于",[["A","M₁型"],["B","M₂型"],["C","M₃型"],["D","M₄型"]],"B","青年女性患者，诊断为急性髓系白血病，实验室检查Hb 85g/L（＜115g/L，贫血），WBC 25.4×10⁹/L（＞9.5×10⁹/L，白细胞升高），PLT 25×10⁹/L（正常值125～350×10⁹/L，血小板降低）。骨髓象见原始粒细胞71%（M₂为30%～89%），早幼粒细胞2%，其他各阶段粒细胞12%（M₂为≥10%），单核细胞8%（M₂＜20%），根据患者骨髓象，FAB分型为M₂（急性粒细胞白血病部分分化型）（B对）。FAB将急粒白血病分为M₀～M₇8型，其他各分型要点见内科学P578。","","N"],["2020-N55",61,"第一节 糖尿病","胰岛素",2020,55,"A","","男性，55岁。患2型糖尿病10年，用二甲双胍0.5g每日三次口服，以及睡前中效胰岛素20U皮下注射治疗。血糖监测显示：凌晨两点血糖2.9mmol/L，空腹血糖12.0mmol/L。该患者空腹血糖升高的原因是",[["A","黎明现象"],["B","Somogyi效应"],["C","睡前胰岛素剂量不足"],["D","二甲双胍药物不良反应"]],"B","中年男性患者，患2型糖尿病，口服二甲双胍，睡前使用中效胰岛素，夜间血糖监测:凌晨两点血糖2.9mmol/L（低血糖），空腹血糖12mmol/L（空腹血糖升高），即该患者表现为夜间低血糖，空腹高血糖，典型的Somogyi效应（B对），该患者引发Somogyi效应的原因可能为睡前中效胰岛素剂量过多（C错），中效胰岛素使用剂量估计，肥胖者为10～15U，非肥胖者5～10U。需要注意的是，Somogyi效应与黎明现象均表现为清晨空腹血糖升高，但黎明现象（A错）是午夜无低血糖，不存在低血糖后高血糖反应，其基本特点是清晨血糖升高，血糖波动性增大（正常人和糖尿病患者均有黎明现象，糖尿病患者的更为明显，提示血糖控制不良）。二甲双胍常见的不良反应是胃肠道症状，表现为口干、口苦、金属味、厌食、恶心、呕吐、腹泻等，偶可见过敏反应，表现为皮肤红斑、荨麻疹等，严重时可导致诱发乳酸性酸中毒（D错）。","","N"],["2020-N56",67,"第一节 风湿系统疾病总论","风湿性疾病范畴和分类",2020,56,"A","","病理和临床特点为退行性变的风湿性疾病是",[["A","银屑病关节炎"],["B","强直性脊柱炎"],["C","骨关节炎"],["D","类风湿关节炎"]],"C","呈退行性变的风湿性疾病是骨关节炎（继发性、原发性）（C对），银屑病关节炎（A错）、强直性脊柱炎（B错）属于脊柱关节炎，类风湿性关节炎（D错）属于弥漫性结缔组织病。","","N"],["2020-N57",38,"第一节 消化道出血","上消化道出血",2020,57,"A","","上消化道大出血的病因中，肝硬化食管胃底曲张静脉破裂所占的比例是",[["A","20%～25%"],["B","26%～30%"],["C","31%～35%"],["D","36%～40%"]],"A","上消化道大出血的病因中，肝硬化食管胃底静脉曲张破裂大出血所占的比例为20%～25%。","","N"],["2020-N68",2,"第一节 支气管哮喘","重度",2020,68,"A","","男性，35岁。反复发作性喘息伴流涕5年，均在每年春季发作。1天前因去花鸟商店后再次发作喘息，较前严重，不能平卧伴大汗，呼吸困难，意识模糊，来院急诊。诊断支气管哮喘急性发作期，重度。该患者喘息急性发作时的呼吸困难类型是",[["A","吸气性呼吸困难"],["B","呼气性呼吸困难"],["C","混合性呼吸困难"],["D","心源性呼吸困难"]],"B","中年男患，春季反复发作性喘息伴流涕5年（提示哮喘病史）。1天前因去花鸟商店后再次发作（接触变应原病史），喘息等症状加重（提示哮喘急性发作），端坐呼吸伴大汗、呼吸困难、意识模糊（符合哮喘重度急性发作表现）。哮喘发作典型的呼吸困难类型为呼气性呼吸困难（B对），但临床重度哮喘发作患者常伴有响亮、弥漫的哮鸣音、常有辅助呼吸肌运动及“三凹征”，此时吸气、呼气都费力，极度呼吸困难，呼吸频率加快、变浅，为混合型呼吸困难（C）。本题中患者出现了意识模糊，应属于支气管哮喘急性发作期，危重度，但题干将其程度判断为重度，根据题干给出的信息选择B，对呼吸困难的类型不能单纯从原发病角度考虑，要根据临床表现综合判断。","c138","N"],["2020-N69",2,"第一节 支气管哮喘","重度",2020,69,"A","","男性，35岁。反复发作性喘息伴流涕5年，均在每年春季发作。1天前因去花鸟商店后再次发作喘息，较前严重，不能平卧伴大汗，呼吸困难，意识模糊，来院急诊。诊断支气管哮喘急性发作期，重度。该患者此时的动脉血气分析检查结果最可能的是",[["A","PaO₂正常，PaCO₂升高"],["B","PaO₂正常，PaCO₂下降"],["C","PaO₂下降，PaCO₂下降"],["D","PaO₂下降，PaCO₂升高"]],"D","中年男患，春季反复发作性喘息伴流涕5年（提示哮喘病史）。1天前因去花鸟商店后再次发作（接触变应原病史），喘息等症状加重（提示哮喘急性发作），端坐呼吸伴大汗、呼吸困难、意识模糊（符合哮喘重度急性发作表现）。来院诊断为哮喘急性发作期，重度。此期患者小气道闭塞严重，发生混合型呼吸困难，导致缺氧、二氧化碳潴留，故患者此时的动脉血气分析检查结果最可能的是PaO₂降低，PaCO₂升高（D对）。PaO₂正常，PaCO₂降低（B错）见于轻度急性发作病人，此期患者小气道闭塞程度轻，PaO₂不受影响，但呼吸频率增加，过度通气导致PaCO₂下降。","c138","N"],["2020-N70",21,"第三节 二尖瓣狭窄","二尖瓣狭窄诊断",2020,70,"A","","女性，28岁。来院查体，既往有反复扁桃体炎史。查体：T36.2℃，P78次/分，R16次/分，BP120/70mmHg。双侧扁桃体Ⅱ度肿大，双肺（－），心尖搏动位于左侧第五肋间锁骨中线上，心律整，心尖部可闻及舒张期隆隆样杂音，左侧卧位时杂音更明显。该患者心脏存在的器质性病变是",[["A","二尖瓣狭窄"],["B","肺动脉瓣狭窄"],["C","三尖瓣狭窄"],["D","主动脉瓣狭窄"]],"A","28岁年轻女性患者（二尖瓣狭窄高发人群），既往有反复扁桃体炎病史（链球菌感染史），查体，T36.2℃，血压120/70mmHg（正常），R16次/分（正常），P78次/分（正常），心律整齐，双侧扁桃体二度肿大，双肺（-），心尖搏动在左侧第五肋间锁骨中线上缘，心尖区可闻及舒张期隆隆样杂音，左侧卧位杂音明显（二尖瓣狭窄典型心脏杂音），根据该患者的病史、临床表现和体征，最可能的诊断是二尖瓣狭窄（A对）。三尖瓣狭窄（C错）最常见的病因为风心病，胸骨左下缘可闻及三尖瓣开瓣音，胸骨左缘4、5肋间或剑突附近有紧随着开瓣音后舒张期隆隆样杂音，杂音时间短且在吸气时增强，伴随着舒张期震颤。肺动脉瓣狭窄典型的心脏杂音为收缩期喷射期杂音（B错），主动脉瓣狭窄典型的心脏杂音为粗糙而响亮的射流性杂音（D错）。","c139","N"],["2020-N71",21,"第三节 二尖瓣狭窄","二尖瓣狭窄临床表现",2020,71,"A","","女性，28岁。来院查体，既往有反复扁桃体炎史。查体：T36.2℃，P78次/分，R16次/分，BP120/70mmHg。双侧扁桃体Ⅱ度肿大，双肺（－），心尖搏动位于左侧第五肋间锁骨中线上，心律整，心尖部可闻及舒张期隆隆样杂音，左侧卧位时杂音更明显。该患者听诊还可能出现的体征是",[["A","心尖部第一心音减弱"],["B","心尖部第一心音增强"],["C","心底部第二心音减弱"],["D","心底部第二心音逆分裂"]],"B","28岁年轻女性患者（二尖瓣狭窄高发人群），既往有反复扁桃体炎病史（链球菌感染史），查体，T36.2℃，血压120/70mmHg（正常），R16次/分（正常），P78次/分（正常），心律整齐，双侧扁桃体二度肿大，双肺（-），心尖搏动在左侧第五肋间锁骨中线上，心尖区可闻及舒张期隆隆样杂音，左侧卧位杂音明显（二尖瓣狭窄典型心脏杂音），根据该患者的病史、临床表现和体征，最可能的诊断是二尖瓣狭窄。二尖瓣狭窄时，因心室充盈减慢和减少，故在心室开始收缩时二尖瓣位置低垂，而心室收缩时，左心室内压上升加速和收缩时间缩短，造成二尖瓣关闭震动幅度增大，故该患者除典型的二尖瓣心脏杂音外，还可能出现的体征为心尖部第一心音增强（B对）。心尖部第一心音减弱（A错）常见于二尖瓣关闭不全。心底部第二心音减弱（C错）常见于低血压、主动脉瓣或肺动脉瓣狭窄。心底部第二心音逆分裂（D错）见于完全性左束支传导阻滞，也可见于主动脉瓣狭窄或重度高血压时。","c139","N"],["2020-N72",21,"第三节 二尖瓣狭窄","房颤",2020,72,"A","","女性，28岁。来院查体，既往有反复扁桃体炎史。查体：T36.2℃，P78次/分，R16次/分，BP120/70mmHg。双侧扁桃体Ⅱ度肿大，双肺（－），心尖搏动位于左侧第五肋间锁骨中线上，心律整，心尖部可闻及舒张期隆隆样杂音，左侧卧位时杂音更明显。患者突发心悸。查体：P85次/分，BP110/70mmHg，双肺（－），心率102次/分，心律不整。此时该患者心尖部杂音听诊结果是",[["A","无变化"],["B","舒张早期增强"],["C","舒张晚期消失"],["D","舒张早期消失"]],"C","28岁年轻女性患者（二尖瓣狭窄高发人群），既往有反复扁桃体炎病史（链球菌感染史），查体，T36.2℃，血压120/70mmHg（正常），R16次/分（正常），P78次/分（正常），心律整齐，双侧扁桃体二度肿大，双肺（-），心尖搏动在左侧第五肋间锁骨中线上缘，心尖区可闻及舒张期隆隆样杂音，左侧卧位杂音明显（二尖瓣狭窄典型心脏杂音），根据该患者的病史、临床表现和体征，最可能的诊断是二尖瓣狭窄，现患者突然心悸，查体P85次/分（脉率小于心率），血压110/70mmHg，心率102次/分（心率加快，脉率小于心率），心律不整，此时该患者应并发房颤，房颤可降低心输出量，诱发或加重心力衰竭，改变心脏杂音的强度，故现在患者杂音可能的改变为典型的舒张晚期杂音减弱或消失（C对）。其机制为二尖瓣狭窄时，在心尖部可听到舒张期隆隆样杂音，并可由收缩期前增强，杂音的位置常较局限，左侧卧位时更容易听到。此杂音的音调为低至中等，在开瓣音之后立即开始，为递增性，根据心室舒张期中左心房与左心室间的压力阶差及血流情况的不同，杂音可占据舒张中、晚期。在舒张晚期，心房收缩，上述压力阶差增大，左心房内剩余的血液较快的排入左心室，可出现一高调的杂音，在第一心音之前达到最高峰，为收缩期前加强或收缩期前杂音（第四心音），心房颤动时，心房无法将剩余血液快速排出，此时收缩期前杂音消失，即舒张晚期杂音减弱或消失。以上可较为简易的理解为：二尖瓣狭窄时的舒张期杂音是心室舒张时血液流经二尖瓣时产生的，当房颤时，舒张晚期（心房收缩期）时，心房无力将血液快速排入心室，故此时杂音减弱或消失。","c139","N"],["2020-N73",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病诊断",2020,73,"A","","男性，68岁。咳嗽、咳痰10年，活动后喘息2年，上3层楼即感气短需要休息，近1年来无急性加重。既往吸烟48年，每日1包。查体：桶状胸，双肺叩诊过清音，呼气相延长。胸片检查可见双肺透亮度增加。肺功能吸入支气管扩张剂后FEV₁/FVC61%，FEV₁%pred52%。 该患者最可能的诊断是",[["A","慢性阻塞性肺疾病"],["B","支气管扩张症"],["C","支气管哮喘"],["D","间质性肺疾病"]],"A","老年男患，有长期吸烟病史，常年咳嗽、咳痰，近2年并发气短、喘息（提示病变加重），查体可见：桶状胸、双肺叩诊过清音（提示肺气肿），呼气相延长（提示阻塞性通气障碍，存在持续气流受限）。胸片可见双肺透亮度增加（提示肺气肿）。肺功能吸入支气管扩张剂后：FEV1/FVC61％，FEV1pred52％（确诊持续气流受限，GOLD2级/中度）。综合该患者的病史、临床表现、辅助检查，该病人最可能诊断的是慢性阻塞性肺疾病（A对）。支气管扩张症（B错）患者典型者表现为反复大量咯脓痰或反复咯血，X线胸部检查常见肺野纹理粗乱或呈卷发状，故考虑支气管扩张症可能性小。支气管哮喘（C错）多为儿童或青少年，合理吸入糖皮质激素等药物常能有效控制病情，所以考虑支气管哮喘可能性小。间质性肺疾病（D错），即ILD，病人FEV1/FVC正常或增加，故考虑间质性肺疾病可能性小。","c140","N"],["2020-N74",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病肺功能检查",2020,74,"A","","男性，68岁。咳嗽、咳痰10年，活动后喘息2年，上3层楼即感气短需要休息，近1年来无急性加重。既往吸烟48年，每日1包。查体：桶状胸，双肺叩诊过清音，呼气相延长。胸片检查可见双肺透亮度增加。肺功能吸入支气管扩张剂后FEV₁/FVC61%，FEV₁%pred52%。该患者肺功能异常是",[["A","限制性通气功能障碍"],["B","阻塞性通气功能障碍，轻度"],["C","阻塞性通气功能障碍，中度"],["D","阻塞性通气功能障碍，重度"]],"C","男，68岁，咳嗽咳痰10年，活动后喘息2年（慢性阻塞性肺疾病典型临床表现），上3层楼即感气短需要停下来休息（COPD症状评估mMRC分级1级，CAT评分＞10分），近1年来无急性发作史（暂无急性加重风险）。吸烟48年，每日1包（COPD危险因素）。查体：桶状胸，叩诊过清音，呼气期延长（COPD典型体征）。X线可见双肺野透亮度增加（COPD影像学表现）。肺功能检查：吸入支气管扩张剂后FEV₁/FVC为61％（确定存在持续气流受限），FEV₁pred 52％（肺功能GOLD2级：中度），根据该患者的临床表现、体征、实验室检查和影像学检查结果，最可能的诊断是慢性阻塞性肺疾病，根据以上情况，该患者的肺功能异常是阻塞性通气功能障碍，GOLD2级：中度（C对）。","c140","N"],["2020-N75",1,"第二节 慢性阻塞性肺疾病","抗胆碱药",2020,75,"A","","男性，68岁。咳嗽、咳痰10年，活动后喘息2年，上3层楼即感气短需要休息，近1年来无急性加重。既往吸烟48年，每日1包。查体：桶状胸，双肺叩诊过清音，呼气相延长。胸片检查可见双肺透亮度增加。肺功能吸入支气管扩张剂后FEV1/FVC61%，FEV1%pred52%。该患者首选的治疗是",[["A","应用LAMA"],["B","出现感染征象时应用抗生素"],["C","应用ICS+LABA"],["D","应用N-乙酰半胱氨酸"]],"A","男，68 岁，咳嗽咳痰10年，活动后喘息2年（慢性阻塞性肺疾病典型临床表现），上3层楼即感气短需要停下来休息（COPD症状评估 mMRC分级2级，CAT评分＞10分），近1年来无急性发作史（暂无急性加重风险）。吸烟48年，每日一包（COPD危险因素）。查体：桶状胸，叩诊过清音，呼气期延长（COPD典型体征）。X线可见双肺野透亮度增加（COPD 影像学表现）。肺功能检查：FEV1/FVC为61％（确定存在持续气流受限），FEV1pred 52％（肺功能GOLD2级），根据该患者的临床表现、体征、实验室检查和影像学检查结果，最可能的诊断是慢性阻塞性肺疾病，根据以上情况，对该例患者做出综合性评估（需要注意的是，CAT评分综合反映临床状况严重度，较mMRC更全面，推荐优先使用），该患者组别更接近B组（mMRC分级2级，CAT评分＞10分），因此稳定期首选的治疗药物为LAMA和（或）LABA（A对）。糖皮质激素用于高风险组的病人（C组和D组）（C错）。出现感染时应用抗生素（B错）是慢阻肺急性加重期的治疗方案（而该患者目前考虑处于稳定期）。N-乙酰半胱氨酸（D错）作为祛痰药用于慢阻肺稳定期痰不易咳出者，只是辅助药物。","c140","N"],["2020-N76",16,"第三节 房性心律失常","心房颤动诊断",2020,76,"A","","女性，60岁。1个月来无诱因感心悸，呈发作性，持续1～2小时可自行缓解，半小时前再次发作来院。近半年来自觉消瘦、乏力、出汗，食欲好，睡眠差，血压增高。查体：T37.2℃，P90次/分，BP140/70mmHg，皮肤出汗，颈部未闻及血管杂音，双肺正常，心界不大，心律不整，手颤（±）。心电图显示：心室率136次/分，P波消失，可见形态不等的f波，QRS波时限0.08\"，间距不等。该患者最可能的诊断是",[["A","阵发性室上性心动过速"],["B","频发房性期前收缩"],["C","阵发性心房颤动"],["D","阵发性心房扑动"]],"C","老年女性患者，1个月来无诱因感心悸，呈发作性，持续1～2小时可自行缓解（甲亢性心脏病可有临床表现），半小时前再次发作来院，近半年来自觉消瘦，乏力，出汗，食欲好，睡眠差，血压升高（甲状腺功能亢进临床表现），查体：T37.2℃（基础体温升高），P90次/分，BP140/70mmHg（血压升高），皮肤出汗，颈部未闻及血管杂音，双肺正常，心界不大，心律不整，手颤（±）（甲状腺功能亢进可有高动力循环体征）。心电图显示：心室率136次/分，P波消失，可见形态不等的f波，QRS波时限0.08\"，间距不等（心房颤动心电图表现），根据患者病史、临床表现和体征及影像学检查结果，最可能的诊断为甲状腺功能亢进症，此时并发的阵发性心房颤动，属于甲状腺毒症心脏病，甲亢患者无论原来是否有心脏病，常可发生心律失常，常以房性期前收缩和房颤多见，呈发作性或持续性。阵发性室上性心动过速（A错）大多数心电图表现为QRS波群形态正常，RR间期规则的快速心率。频发性房性期前收缩（B错）多发生于各种器质性心脏病患者，主要表现为心悸，部分病人有胸闷、乏力症状，有些病人可无任何症状，心电图特征为P波提前发生，形态与窦性P波不同，PR间期＞120毫秒，QRS波型呈室上性，部分可有室内差异性传导，多为不完全代偿间歇。阵发性房扑（D错）多见于器质性心脏病患者，症状与心室率的快慢呈正相关，房扑伴有较快心室率，可诱发心绞痛与充血性心力衰竭，心电图特征为窦性P波消失，出现F波，扑动波之间的等电线消失，频率常为250～350次/分，心室率规则与否取决于房室传导比例是否恒定，QRS波形态正常，出现室内差异传导、原先有束支阻滞或经房室旁路下传时， QRS 波增宽、形态异常。","c141","N"],["2020-N77",16,"第三节 房性心律失常","心房颤动病因",2020,77,"A","","女性，60岁。1个月来无诱因感心悸，呈发作性，持续1～2小时可自行缓解，半小时前再次发作来院。近半年来自觉消瘦、乏力、出汗，食欲好，睡眠差，血压增高。查体：T37.2℃，P90次/分，BP140/70mmHg，皮肤出汗，颈部未闻及血管杂音，双肺正常，心界不大，心律不整，手颤（±）。心电图显示：心室率136次/分，P波消失，可见形态不等的f波，QRS波时限0.08\"，间距不等。该患者最可能的原发病因是",[["A","高血压"],["B","冠心病"],["C","糖尿病"],["D","甲状腺功能亢进症"]],"D","老年女性患者，1个月来无诱因感心悸，呈发作性，持续1～2小时可自行缓解（甲亢性心脏病可有临床表现），半小时前再次发作来院，近半年来自觉消瘦，乏力，出汗，食欲好，睡眠差，血压升高（甲状腺功能亢进临床表现），查体：T37.2℃，P90次/分，BP140/70mmHg，皮肤出汗，颈部未闻及血管杂音，双肺正常，心界不大，心律不整，手颤（±）（甲状腺功能亢进可有体征）。心电图显示：心室率136次/分，P波消失，可见形态不等的f波，QRS波时限0.08\"，间距不等（心房颤动心电图表现），根据患者病史、临床表现和体征及影像学检查结果，此时患者发生阵发性房颤，最可能的原因为其原发病甲状腺功能亢进症（D对）。","c141","N"],["2020-N78",16,"第三节 房性心律失常","治疗原发病",2020,78,"A","","女性，60岁。1个月来无诱因感心悸，呈发作性，持续1～2小时可自行缓解，半小时前再次发作来院。近半年来自觉消瘦、乏力、出汗，食欲好，睡眠差，血压增高。查体：T37.2℃，P90次/分，BP140/70mmHg，皮肤出汗，颈部未闻及血管杂音，双肺正常，心界不大，心律不整，手颤（±）。心电图显示：心室率136次/分，P波消失，可见形态不等的f波，QRS波时限0.08\"，间距不等。该患者正确的治疗措施是",[["A","选用洋地黄类药物减慢心室率"],["B","行射频消融术转复心律"],["C","治疗原发病"],["D","临床观察"]],"C","老年女性患者，1个月来无诱因感心悸，呈发作性，持续1～2小时可自行缓解（甲亢性心脏病可有临床表现），半小时前再次发作来院，近半年来自觉消瘦，乏力，出汗，食欲好，睡眠差，血压升高（甲状腺功能亢进临床表现），查体：T37.2℃（基础体温升高），P90次/分，BP140/70mmHg（血压升高），皮肤出汗，颈部未闻及血管杂音，双肺正常，心界不大，心律不整，手颤(±)（甲状腺功能亢进可有高动力循环体征）。心电图显示：心室率136次/分，P波消失，可见形态不等的f波，QRS波时限0.08\"，间距不等（心房颤动心电图表现），根据患者病史、临床表现和体征及影像学检查结果，最可能的诊断是甲状腺功能亢进症，此时的并发心房颤动，属于甲状腺毒症心脏病，甲亢患者无论原来是否有心脏病，常可发生心律失常，常以房性期前收缩和房颤多见，呈发作性或持续性，其治疗的基本原则是控制增高的甲状腺激素水平和对心脏病的对症处理，甲状腺毒症纠正后，心房颤动可以消失，故该患者正确的治疗措施是治疗原发病（C对D错）。选用洋地黄类药物减慢心室率（A错）和行射频消融术转复心律（B错）均为心房颤动的治疗措施，特别是射频消融术有明确的使用指征，对于症状明显、药物治疗无效的阵发性房颤使用。本例患者更注重治疗甲亢，纠正甲状腺毒症，根据实际情况在治疗原发病的基础上进行综合治疗，值得注意的是甲亢时易引起强心苷中毒，同时禁用或忌用β受体阻滞剂。","c141","N"],["2020-N79",36,"第一节 原发性肝癌","原发性肝癌诊断",2020,79,"A","","男性，45岁。右侧季肋部胀痛伴厌食、腹胀1月余。既往患乙型病毒性肝炎10余年。查体：肝右肋下3cm，质地硬，边缘及表面不规则。目前最可能的诊断是",[["A","慢性重型肝炎"],["B","原发性肝癌"],["C","细菌性肝脓肿"],["D","肝脏血管瘤"]],"B","中年男性患者（肝癌高发人群），右季肋部胀痛（肝区疼痛），伴有厌食，腹胀1月余（肝癌全身性表现），乙肝病史十余年（肝癌常见病因），查体：肝右肋下3cm，质硬，边缘及表面不规则（肝癌常见临床体征），根据该患者病史、临床表现和体征，最可能的诊断是原发性肝癌（B对）。慢性重症肝炎（A错）有明显的肝脏储备功能下降和门静脉高压相关症状。细菌性肝脓肿（C错）典型临床表现为寒战、高热、肝区疼痛和肝大，体温可高达39～40℃，伴有恶心、呕吐、食欲缺乏和周身乏力，体征可表现为右季肋区呈饱满状态，严重时可并发胆道梗阻（出现黄疸）。肝脏血管瘤（D错）多见于女性，较小时多无症状，较大时可伴有腹部不适、肝大、食欲缺乏、消化不良等症状，瘤内可反复形成血栓，造成肿瘤肿胀，牵拉疼痛，肿块软硬不一，有不同程度的可压缩感，少数呈坚硬结节感。","c142","N"],["2020-N80",36,"第一节 原发性肝癌","甲胎蛋白",2020,80,"A","","男性，45岁。右侧季肋部胀痛伴厌食、腹胀1月余。既往患乙型病毒性肝炎10余年。查体：肝右肋下3cm，质地硬，边缘及表面不规则。对上述诊断意义最大的实验室检查结果是",[["A","血ALT和AST升高"],["B","血AFP持续升高＞400ng/ml"],["C","血ALT、AFP和白细胞计数基本正常"],["D","血白细胞计数和中性粒细胞比例升高"]],"B","中年男性患者（肝癌高发人群），右季肋部胀痛（肝区疼痛），伴有厌食，腹胀1月余（肝癌全身性表现），乙肝病史十余年（肝癌常见病因），查体：肝右肋下3cm，质硬，边缘及表面不规则（肝癌常见临床体征），根据该患者病史、临床表现和体征，最可能的诊断是原发性肝癌，具有诊断意义的实验室检查是血AFP持续升高，大于400ng/ml，甲胎蛋白是最具有诊断意义的肝癌标志物，与影像学相结合对肝癌的诊断具有重要意义（B对C错）。血ALT和AST升高（A错）见于急慢性病毒性肝炎、肝硬化、药物性肝炎、脂肪肝、肝癌等，不具有特异性。白细胞计数和中性粒细胞比例升高（D错）提示体内有感染灶，为非特异性指标，对原发性肝癌的诊断意义不大。","c142","N"],["2020-N81",36,"第一节 原发性肝癌","肝穿刺活体组织检查",2020,81,"A","","男性，45岁。右侧季肋部胀痛伴厌食、腹胀1月余。既往患乙型病毒性肝炎10余年。查体：肝右肋下3cm，质地硬，边缘及表面不规则。最有确定诊断价值的辅助检查是",[["A","腹部B超"],["B","腹部CT"],["C","肝穿刺病理学检查"],["D","肝动脉造影"]],"C","中年男性患者（肝癌高发人群），右季肋部胀痛（肝区疼痛），伴有厌食，腹胀1月余（肝癌全身性表现），乙肝病史十余年（肝癌常见病因），查体：肝右肋下3cm，质硬，边缘及表面不规则（肝癌常见临床体征），根据该患者病史、临床表现和体征，最可能的诊断是原发性肝癌，病理学检查是诊断原发性肝癌的金标准，故最有助于确定诊断的检查为肝穿刺病理学检查（C对）。需要注意的是，目前通过病史及影像学检查一般可以作出肝癌的临床诊断，对于可以进行根治治疗的患者，不一定必须进行肝穿刺活检，对于CT或MRI表现不典型的患者，需要进行活检进行确诊。腹部B超（A错）有助于肝癌早期的诊断，广泛用于筛查肝癌。腹部CT（B错）能全面客观反映肝癌的特性，是目前临床诊断肝癌的常规手段。肝动脉造影（D错）为增强CT或MRI对疑似肝癌的小病灶难以诊断时的补充检查手段，对直径1～2cm的小肝癌可作出更精确的诊断。","c142","N"],["2020-N82",40,"第五节 肾病综合征","肾病综合征诊断",2020,82,"A","","男性，15岁。颜面部、双下肢水肿10天。既往体健。查体：T36.5℃，BP120/70mmHg，眼睑水肿，心肺检查未见异常，腹平软，肝脾肋下未触及，下肢凹陷性水肿（++）。化验尿蛋白（++++），沉渣镜检红细胞0～2个/HP，血白蛋白25g/L，血胆固醇8mmol/L，血Cr102μmol/L，血BUN10.5mmol/L。该患者最可能的临床诊断是",[["A","急性肾小球肾炎"],["B","急进性肾小球肾炎"],["C","肾病综合征"],["D","慢性肾小球肾炎急性发作"]],"C","青少年男性患者，颜面、双下肢水肿（肾性水肿），查体：T36.5℃（体温正常），BP120/70mmHg（血压正常），眼睑水肿（肾性水肿），心肺检查未见明显异常，腹平软，肝脾肋下未触及，下肢凹陷性水肿（++），实验室检查：尿蛋白（++++）（大量蛋白尿），沉渣镜检红细胞0～2个/Hp（＜3个/Hp），血清白蛋白25g/L（＜30g/L，低蛋白血症），血胆固醇8mmol/L（＞6.2mmol/L，胆固醇升高），血Cr102μmol/L（男性正常值53～106μmol/L），血BUN10.5mmol/L（成年正常值3.2～7.1mmol/L，升高），根据患者临床表现和实验室检查，符合肾病综合征“三高一低”的诊断标准，最可能的诊断为肾病综合征（C对）。急性肾小球肾炎是一组以急性肾炎综合征（血尿、蛋白尿、水肿和高血压）为主要临床表现的肾脏疾病，可伴有一过性的肾功能损伤，大多数为链球菌感染后肾小球肾炎，发作前常有前驱感染。急进性肾小球肾炎（B错）临床特点为肾功能损害急骤进展，常伴有少尿或无尿的临床特点，病理类型表现为肾小球广泛新月体形成。慢性肾小球肾炎（D错）是一组以血尿、蛋白尿、水肿和高血压为临床表现的肾小球疾病，急性发作时病情会急剧恶化，及时去除诱因肾功能会有所恢复，晚期主要表现为终末期肾衰竭的相应临床表现。","c143","N"],["2020-N83",40,"第五节 肾病综合征","微小病变型肾病",2020,83,"A","","男性，15岁。颜面部、双下肢水肿10天。既往体健。查体：T36.5℃，BP120/70mmHg，眼睑水肿，心肺检查未见异常，腹平软，肝脾肋下未触及，下肢凹陷性水肿（++）。化验尿蛋白（++++），沉渣镜检红细胞0～2个/HP，血白蛋白25g/L，血胆固醇8mmol/L，血Cr102μmol/L，血BUN10.5mmol/L。该患者最可能的病理诊断是",[["A","毛细血管内肾小球肾炎"],["B","新月体性肾小球肾炎"],["C","系膜毛细血管性肾小球肾炎"],["D","微小病变型肾病"]],"D","青少年男性患者，颜面、双下肢水肿（肾性水肿），查体：T36.5℃（体温正常），BP120/70mmHg（血压正常），眼睑水肿（肾性水肿），心肺检查未见明显异常，腹平软，肝脾肋下未触及，下肢凹陷性水肿（++），实验室检查：尿蛋白（++++）（大量蛋白尿），沉渣镜检红细胞0～2个/Hp（＜3个/Hp），血清白蛋白25g/L（＜30g/L，低蛋白血症），血胆固醇8mmol/L（＞6.2mmol/L，胆固醇升高），血Cr102μmol/L（男性正常值44～133μmol/L），血BUN10.5mmol/L（成年正常值3.2～7.1mmol/L，升高），根据患者临床表现和实验室检查，符合肾病综合征“三高一低”的诊断标准，最可能的诊断为肾病综合征，最可能的病理诊断为微小病变型肾病（D对），微小病变型肾病约占10岁以下儿童肾病综合征90%以上，10岁以上未成年人肾病综合征50%～70%，成年人肾病综合征10%～20%，其临床特点为严重的蛋白尿，镜下血尿少见，肉眼血尿罕见。以肾病为临床表现的病理类型主要为微小病变、膜性肾病或局灶节段肾小球硬化；以肾炎为表现的病理类型，系膜增生性或膜增生性肾小球肾炎最为常见；以无症状性血尿、蛋白尿为临床表现，多见于系膜增生和局灶节段增生性肾小球肾炎。毛细血管内增生性肾小球肾炎（A错）即急性弥漫性增生性肾小球肾炎主要表现为急性肾炎综合征。新月体型肾小球肾炎（B错）即急进性肾小球肾炎，表现为肾炎综合征。系膜毛细血管性肾小球肾炎（C错）即膜增生性肾小球肾炎，常伴有血尿，血清补体水平低下，高血压、贫血及肾功能损害常见，病变持续发展，预后较差。","c143","N"],["2020-N84",40,"第五节 肾病综合征","糖皮质激素",2020,84,"A","","男性，15岁。颜面部、双下肢水肿10天。既往体健。查体：T36.5℃，BP120/70mmHg，眼睑水肿，心肺检查未见异常，腹平软，肝脾肋下未触及，下肢凹陷性水肿（++）。化验尿蛋白（++++），沉渣镜检红细胞0～2个/HP，血白蛋白25g/L，血胆固醇8mmol/L，血Cr102μmol/L，血BUN10.5mmol/L。最主要的治疗药物是",[["A","醋酸泼尼松"],["B","环磷酰胺"],["C","醋酸泼尼松联合环磷酰胺"],["D","辛伐他汀"]],"A","青少年男性患者，颜面、双下肢水肿（肾性水肿），查体：T36.5℃（体温正常），BP120/70mmHg（血压正常），眼睑水肿（肾性水肿），心肺检查未见明显异常，腹平软，肝脾肋下未触及，下肢凹陷性水肿（++），实验室检查：尿蛋白（++++）（大量蛋白尿），沉渣镜检红细胞0～2个/Hp（＜3个/Hp），血清白蛋白25g/L（＜30g/L，低蛋白血症），血胆固醇8mmol/L（＞6.2mmol/L，胆固醇升高），血Cr102μmol/L（男性正常值44～133μmol/L），血BUN10.5mmol/L（成年正常值3.2～7.1mmol/L，升高），根据患者临床表现和实验室检查，符合肾病综合征“三高一低”的诊断标准，最可能的诊断为肾病综合征，病理诊断为微小病变型肾病，微小病变型肾病很少能自动缓解，必须积极治疗，大多数患者对糖皮质激素治疗反应较好，儿童缓解率90%，成人缓解率80%，常用药物为泼尼松或泼尼松龙（A对），对激素依赖或大剂量激素治疗不缓解者，应加用细胞毒药物（C错）。若患者有应用激素的相对禁忌症或不耐受足量的激素治疗，可应用环磷酰胺（B错）。辛伐他汀（D错）为调血脂药物，同时有一定的肾保护作用，为辅助治疗。","c143","N"],["2020-N85",47,"第一节 缺铁性贫血","缺铁性贫血诊断",2020,85,"A","","女性，18岁。乏力、面色苍白半年。月经量增多2年余。查体：贫血貌，巩膜无黄染，心肺检查未见异常，腹平软，肝脾肋下未触及。化验血常规：Hb80g/L，MCV65fl，MCH20pg，MCHC300g/L，WBC4.0×10⁹/L，Plt310×10⁹/L。该患者最可能的诊断是",[["A","缺铁性贫血"],["B","地中海贫血"],["C","慢性病性贫血"],["D","巨幼细胞贫血"]],"A","年轻女性患者（育龄期女性），乏力苍白半年（贫血症状），月经增多两年多（机体缺铁症状），实验室检查Hb80g/L（Hb＜115g/L），MCV65fl（MCV＜80fl），MCH20pg（MCH＜27pg），MCHC300g/L（30%，MCHC＜32%），WBC4.0×10⁹/L（成年人正常值3.5～9.5×10⁹/L），Plt310×10⁹/L（成年人正常值125～350×10⁹/L，血小板升高），根据患者的临床表现和实验室检查结果，为小细胞低色素性贫血，且符合缺铁性贫血的诊断标准，该患者最可能的诊断是缺铁性贫血。地中海贫血（B错）即珠蛋白生成障碍性贫血，有家族史、溶血表现，血清铁蛋白、骨髓可染铁、血清铁和铁饱和度不低且常增高。巨幼细胞贫血（D错）为大细胞性贫血，病因为叶酸或维生素B₁₂缺乏，骨髓内出现巨幼红细胞、粒细胞及巨核细胞系列。慢性病贫血（C错）应有相对应原发病的临床表现和体征，现有临床证据不支持该诊断。","c144","N"],["2020-N86",47,"第一节 缺铁性贫血","铁代谢",2020,86,"A","","女性，18岁。乏力、面色苍白半年。月经量增多2年余。查体：贫血貌，巩膜无黄染，心肺检查未见异常，腹平软，肝脾肋下未触及。化验血常规：Hb80g/L，MCV65fl，MCH20pg，MCHC300g/L，WBC4.0×10⁹/L，Plt310×10⁹/L。确诊的最佳实验室检查是",[["A","外周血网织红细胞计数"],["B","血清铁、铁蛋白测定"],["C","血红蛋白电泳"],["D","血清叶酸、维生素B12测定"]],"B","年轻女性患者（育龄期女性），乏力苍白半年（贫血症状），月经增多两年多（机体缺铁症状），实验室检查Hb80g/L（Hb＜115g/L），MCV65fl（MCV＜80fl），MCH20pg（MCH＜27pg），MCHC300g/L（30%，MCHC＜32%），WBC4.0×10⁹/L（成年人正常值3.5～9.5×10⁹/L），Plt310×10⁹/L（成年人正常值125～350×10⁹/L，血小板升高），根据患者的临床表现和实验室检查结果，为小细胞低色素性贫血，且符合缺铁性贫血的诊断标准，该患者最可能的诊断是缺铁性贫血，最有确诊价值的检查为血清铁、铁蛋白检测（B对），血清铁蛋白和体内铁储存量相关性高，可以作为缺铁的敏感指标。网织红细胞计数（A错）表示骨髓红细胞系增生旺盛，对缺铁性贫血的诊断无特异性，增多还可见于溶血性贫血、急性失血、巨幼细胞贫血等。血红蛋白电泳（C错）是诊断地中海贫血的重要依据。叶酸及维生素B₁₂检测用于诊断巨幼细胞贫血。","c144","N"],["2020-N87",47,"第一节 缺铁性贫血","缺铁性贫血病因",2020,87,"A","","女性，18岁。乏力、面色苍白半年。月经量增多2年余。查体：贫血貌，巩膜无黄染，心肺检查未见异常，腹平软，肝脾肋下未触及。化验血常规：Hb80g/L，MCV65fl，MCH20pg，MCHC300g/L，WBC4.0×10⁹/L，Plt310×10⁹/L。下列各项对明确贫血病因最有意义的是",[["A","询问饮食情况及舌检查"],["B","询问既往患病史"],["C","询问详细月经情况及妇科检查"],["D","询问贫血家族史"]],"C","年轻女性患者（育龄期女性），乏力苍白半年（贫血症状），月经增多两年多（机体缺铁症状），实验室检查Hb80g/L（Hb＜115g/L），MCV65fl（MCV＜80fl），MCH20pg（MCH＜27pg），MCHC300g/L（30%，MCHC＜32%），WBC4.0×10⁹/L（成年人正常值3.5～9.5×10⁹/L），Plt310×10⁹/L（成年人正常值125～350×10⁹/L，血小板升高），根据患者的临床表现和实验室检查结果，为小细胞低色素性贫血，且符合缺铁性贫血的诊断标准，该患者最可能的诊断是缺铁性贫血。本例患者为育龄期妇女，月经增多两年，月经期妇女经期失血量为40～60ml/次，约等于丢失铁20～30mg，因此对铁的需求量也较男性大，月经量过多为妇女缺铁的常见原因，为明确缺铁性贫血的病因，详细询问月经情况及妇科检查是必要的，有助于引发缺铁的原发疾病的诊断（C对）。询问饮食情况及舌检查（A错）、询问既往病史（B错）对病因的诊断也有意义，但不作为首选。缺铁性贫血无基因相关性，询问贫血家族史（D错）对缺铁性贫血意义不大。","c144","N"],["2020-N88",59,"第二节 甲状腺功能减退症","甲状腺功能减退症诊断",2020,88,"A","","女性，68岁。1个月来乏力、畏寒、胸闷、气短、记忆力明显减退，食欲差，夜间愿高枕卧位。既往因心律失常服用胺碘酮治疗，有高脂血症、关节痛史。入院查体：T35.9℃，P84次/分，BP100/85mmHg，高枕位，表情淡漠，皮肤干燥，睑结膜稍苍白，颈静脉充盈，甲状腺不大，双肺（－），心浊音界扩大，心律整，S₁遥远，肝脾触诊不满意，双下肢凹陷性水肿（+），跟腱反射迟钝。该患者应首先考虑的疾病诊断是",[["A","甲状腺功能减退症"],["B","扩张型心肌病"],["C","结核性心包炎"],["D","干燥综合征"]],"A","老年女性患者，乏力，畏寒，食欲差（低代谢症群及甲减消化系统症状），记忆力明显减退（甲减神经精神系统症状），胸闷，气短，夜间愿高枕卧位（甲减心血管系统症状），既往因心律失常服用胺碘酮治疗（胺碘类药物可导致甲减），有高脂血症，关节痛病史（药物服用史，甲减可能诱因）。入院查体：T35.9℃（体温低，甲减常有体征），心率84次/分，BP100/85mmHg，高枕位，表情淡漠，皮肤干燥，睑结膜稍苍白，颈静脉充盈，甲状腺不大，双肺（-），心脏浊音界扩大，心律整，S₁低钝（考虑心包积液），肝脾触诊不满意（甲减可有心血管系统体征），双下肢凹陷性水肿（+），跟腱反射减退（甲减典型阳性体征），根据患者病史、临床表现和体征，最可能的诊断是甲状腺功能减退症（A对），简称甲减，是组织甲状腺激素作用不足或者缺如的一种病理状态，为甲状腺激素合成、分泌或生物效应不足所致的一组内分泌疾病，女性多见，随着年龄增长患病率上升。扩张性心肌病（B错）主要表现为左或右心室或双侧心室扩大，并伴有心室收缩功能减退，伴或不伴充血性心力衰竭，结合该病例，患者的低代谢表现、跟腱反射减退无法用扩张性心肌病解释。结核性心包炎（C错）伴有原发结核表现，常无胸痛或仅有轻微胸痛，可有心包摩擦音，常有大量心包积液，穿刺心包积液检查有助于原发病的诊断。干燥综合征（D错）为主要累及外分泌腺体的慢性炎症性自身免疫病。","c145","N"],["2020-N89",59,"第二节 甲状腺功能减退症","血清TPOAb与TgAb",2020,89,"A","","女性，68岁。1个月来乏力、畏寒、胸闷、气短、记忆力明显减退，食欲差，夜间愿高枕卧位。既往因心律失常服用胺碘酮治疗，有高脂血症、关节痛史。入院查体：T35.9℃，P84次/分，BP100/85mmHg，高枕位，表情淡漠，皮肤干燥，睑结膜稍苍白，颈静脉充盈，甲状腺不大，双肺（－），心浊音界扩大，心律整，S₁遥远，肝脾触诊不满意，双下肢凹陷性水肿（+），跟腱反射迟钝。为确诊，最有价值的检查项目是",[["A","NT-proBNP"],["B","T-SPOTTB"],["C","TPOAb"],["D","抗ENA抗体谱"]],"C","老年女性患者，乏力，畏寒，食欲差（低代谢症群及甲减消化系统症状），记忆力明显减退（甲减神经精神系统症状），胸闷，气短，夜间愿高枕卧位（甲减心血管系统症状），既往因心律失常服用胺碘酮治疗（胺碘类药物可导致甲减），有高脂血症，关节痛病史（药物服用史，甲减可能诱因）。入院查体：T35.9℃（体温低，甲减常有体征），心率84次/分，BP100/85mmHg，高枕位，表情淡漠，皮肤干燥，睑结膜稍苍白，颈静脉充盈，甲状腺不大，双肺（-），心脏浊音界扩大，心律整，S₁低钝（考虑心包积液），肝脾触诊不满意（甲减可有心血管系统体征），双下肢凹陷性水肿（+），跟腱反射减退（甲减典型阳性体征），根据患者病史、临床表现和体征，最可能的诊断是甲状腺功能减退症，简称甲减，是组织甲状腺激素作用不足或者缺如的一种病理状态，为甲状腺激素合成、分泌或生物效应不足所致的一组内分泌疾病，女性多见，随着年龄增长患病率上升，甲状腺过氧化物酶抗体（TPOAb）的敏感性和特异性高，对确诊意义最大（C对）。NT-proBNP（A错）用于明确心衰的程度及预后。T-Spot TB试验（B错）即结核感染T细胞实验，用于辅助诊断潜伏性结核感染或活动性结核感染。抗ENA抗体（D错）对结缔组织疾病诊断和鉴别诊断有重要意义。","c145","N"],["2020-N90",59,"第二节 甲状腺功能减退症","甲状腺激素替代治疗",2020,90,"A","","女性，68岁。1个月来乏力、畏寒、胸闷、气短、记忆力明显减退，食欲差，夜间愿高枕卧位。既往因心律失常服用胺碘酮治疗，有高脂血症、关节痛史。入院查体：T35.9℃，P84次/分，BP100/85mmHg，高枕位，表情淡漠，皮肤干燥，睑结膜稍苍白，颈静脉充盈，甲状腺不大，双肺（－），心浊音界扩大，心律整，S₁遥远，肝脾触诊不满意，双下肢凹陷性水肿（+），跟腱反射迟钝。应选择的治疗是",[["A","口服糖皮质激素"],["B","口服左甲状腺素"],["C","口服利尿剂"],["D","抗结核治疗"]],"B","老年女性患者，乏力，畏寒，食欲差（低代谢症群及甲减消化系统症状），记忆力明显减退（甲减神经精神系统症状），胸闷，气短，夜间愿高枕卧位（甲减心血管系统症状），既往因心律失常服用胺碘酮治疗（胺碘类药物可导致甲减），有高脂血症，关节痛病史（药物服用史，甲减可能诱因）。入院查体：T35.9℃（体温低，甲减常有体征），心率84次/分，BP100/85mmHg，高枕位，表情淡漠，皮肤干燥，睑结膜稍苍白，颈静脉充盈，甲状腺不大，双肺（-），心脏浊音界扩大，心律整，S₁低钝（考虑心包积液），肝脾触诊不满意（甲减可有心血管系统体征），双下肢凹陷性水肿（+），跟腱反射减退（甲减典型阳性体征），根据患者病史、临床表现和体征，最可能的诊断是甲状腺功能减退症，简称甲减，是组织甲状腺激素作用不足或者缺如的一种病理状态，为甲状腺激素合成、分泌或生物效应不足所致的一组内分泌疾病，女性多见，随着年龄增长患病率上升，治疗原则为将血清TSH和甲状腺激素水平恢复到正常范围内，需要终身服药，首选左甲状腺素（L-T₄）（B对）。糖皮质激素静脉滴注（A错）用于黏液性水肿昏迷的治疗。利尿剂（C错）、抗结核治疗（D错）均不属于甲减的治疗。","c145","N"],["2020-N91",70,"第一节 干燥综合征","干燥综合征诊断标准",2020,91,"A","","女性，30岁。1个月来无明显原因出现口、眼干燥，半个月来出现四肢关节疼痛，以双侧肘、膝关节明显，一直未诊治。近几天进固体食物时常须用水冲服，无多饮、多尿，大便正常。既往体健。查体：T36.8℃，BP120/80mmHg，舌面干，口腔异味大，心肺腹检查未见异常，双侧肘、膝关节稍肿胀，轻压痛，下肢不肿。化验血常规：Hb94g/L，RBC3.1×10¹²/L，WBC3.5×10⁹/L，Plt126×10⁹/L。该患者最可能的诊断是",[["A","干燥综合征"],["B","系统性红斑狼疮"],["C","类风湿关节炎"],["D","糖尿病"]],"A","青年女性患者，口干、眼干一个月（干燥综合征典型症状），四肢关节疼痛半个月（干燥综合征骨骼肌肉表现），进食固体食物须用水吞服（口干症状加剧），无多饮、多尿，大便正常（暂不考虑糖尿病），舌体干燥，口腔异味大（干燥综合征典型症状），心肺腹检查未见明显异常，双侧肘、膝关节稍肿胀、轻压痛，下肢不肿（干燥综合征骨骼肌肉症状）。血常规：Hb 94g/L（成年女性正常值115～150g/L，贫血），RBC 3.1×10¹²/L（女性正常值3.5～5.0×10¹²/L，贫血），WBC 3.5×10⁹/L（正常值3.5～9.5×10⁹/L，下降），PLT 126×10⁹/L（125～350×10⁹/L），根据2002年干燥综合征国际分类/诊断标准，综合该患者的病史、临床表现和实验室检查，最可能的诊断是干燥综合征（A对）。系统性红斑狼疮（B错）是一种好发于青年女性的累及多脏器的自身免疫性炎症性结缔组织病。典型表现为蝶形红斑、盘状红斑、关节痛等。类风湿性关节炎（C错）是一种病因未明的慢性、以炎性滑膜炎为主的系统性疾病，其特征是手、足小关节的多关节、对称性、侵袭性关节炎症，经常伴有关节外器官受累及血清类风湿因子阳性，可以导致关节畸形及功能丧失。糖尿病（D错）是一组以高血糖为特征的代谢性疾病，长期存在的高血糖，导致各种组织，特别是眼、肾、心脏、血管、神经的慢性损害、功能障碍。","c146","N"],["2020-N92",70,"第一节 干燥综合征","免疫学检查",2020,92,"A","","女性，30岁。1个月来无明显原因出现口、眼干燥，半个月来出现四肢关节疼痛，以双侧肘、膝关节明显，一直未诊治。近几天进固体食物时常须用水冲服，无多饮、多尿，大便正常。既往体健。查体：T36.8℃，BP120/80mmHg，舌面干，口腔异味大，心肺腹检查未见异常，双侧肘、膝关节稍肿胀，轻压痛，下肢不肿。化验血常规：Hb94g/L，RBC3.1×10¹²/L，WBC3.5×10⁹/L，Plt126×10⁹/L。最有诊断价值的实验室检查是",[["A","血清抗Sm抗体"],["B","空腹血糖"],["C","血清RF"],["D","血清抗SSA、抗SSB抗体"]],"D","青年女性患者，口干、眼干一个月（干燥综合征典型症状），四肢关节疼痛半个月（干燥综合征骨骼肌肉表现），进食固体食物须用水吞服（口干症状加剧），无多饮、多尿，大便正常（暂不考虑糖尿病），舌体干燥，口腔异味大（干燥综合征典型症状），心肺腹检查未见明显异常，双侧肘、膝关节稍肿胀、轻压痛，下肢不肿（干燥综合征骨骼肌肉症状）。血常规：Hb 94g/L（成年女性正常值115～150g/L，贫血），RBC 3.1×10¹²/L（女性正常值3.5～5.0×10¹²/L，贫血），WBC 3.5×10⁹/L（正常值3.5～9.5×10⁹/L，下降），PLT 126×10⁹/L（125～350×10⁹/L，下降），根据2002年干燥综合征国际分类/诊断标准，综合该患者的病史、临床表现和实验室检查，最可能的诊断是干燥综合征，其确诊需要风湿免疫科、眼科和口腔科的协作，有赖于口干燥症、干燥性角膜炎的检测，血清抗SSA和（或）SSB抗体阳性、唇腺组织病理学检查有灶性淋巴细胞浸润，SSA抗体可出现于其他疾病，SSB抗体对诊断更具有意义，二者同时阳性，首先考虑干燥综合征的可能（D对）。抗Sm抗体（A错）属于抗核抗体的其中一种，是系统性红斑狼疮的特异性抗体。空腹血糖（B错）为糖尿病最常用的检测指标。类风湿因子（C错）是一种以变性IgG为靶抗原的自身抗体，可见于多种风湿性疾病，也见于感染性疾病，特异性不强。","c146","N"],["2020-N128",22,"第一节 急性心包炎","急性心包炎诊断",2020,128,"B","","男性，52岁。10天前发热、咽痛，1天来突感心前区锐痛，呈持续性，向左肩放射，活动时加重。既往有高血压病6年。查体：T37.5℃，P88次/分，BP160/90mmHg，双肺（－），胸骨左缘3、4肋间可闻及粗糙抓刮样音，收缩期明显，双侧脉搏对称。该患者最可能的诊断是",[["A","急性心包炎"],["B","急性心肌炎"],["C","急性感染性心内膜炎"],["D","心脏压塞"]],"A","中年男性患者，10天前发热，咽痛（前驱感染症状），1天来突感心前区锐痛，呈持续性，向左肩放射，活动时加重（心包炎特征性临床表现），既往有高血压病6年。查体:T37.5℃（体温稍高，低热），P88次/分（心率正常），BP160/90mmHg（2级高血压），双肺（-），胸骨左缘3、4肋间可闻及粗糙抓刮样音，收缩期时明显（心包炎典型心脏体征），双侧脉搏对称，根据该患者的病史、临床表现和体征，最可能的诊断是急性心包炎（A对），超声心动图及心脏磁共振有助于诊断。急性心肌炎（B错）的临床表现与病变的广泛程度与部位有关，严重时可出现心源性休克及猝死，可有心悸、胸痛、呼吸困难、水肿，查体常有心律失常，以房性与室性期前收缩及房室传导阻滞最为多见，听诊可闻及第三、第四心音或奔马律，导致心衰时可有相关症状和体征。急性感染性心内膜炎（C错）为致病微生物经血液循环直接感染心脏瓣膜等伴有赘生物形成，致病菌主要为金黄色葡萄球菌，特征为中毒症状明显，病程进展迅速，杂音多易变化，最具特征的是新出现的病理性杂音或原有杂音改变，可有皮肤及其附属器、眼的表现。心脏压塞（D错）即心包填塞，临床特征为Beck’s三联征：血压低、心音弱、颈静脉怒张，为心包积液迅速积聚或积液量达到一定程度时，造成心脏输出量和回心血量明显下降而产生的相应临床表现。","","N"],["2020-N129",19,"第六节 心肌炎","心肌炎诊断",2020,129,"B","","女性，46岁。10天前有发热、恶心、腹泻，2天来心悸伴心前区闷痛，活动后明显加重，夜间睡眠中有憋气感。既往体健。查体：T37.6℃，P110次/分，BP110/65mmHg，双肺底偶闻及湿啰音，心律整，心尖部可闻及S₃奔马律，肝未及。该患者最可能的诊断是",[["A","急性心包炎"],["B","急性心肌炎"],["C","急性感染性心内膜炎"],["D","心脏压塞"]],"B","中年女性患者，1周多前有发热，恶心，腹泻（考虑典型病毒感染前驱症状），2天来心悸伴心前区闷痛，活动后明显加重，夜间睡眠中有憋气感（心肌炎可有典型临床表现），既往体健，查体：T37.6℃（体温稍高，低热），P110次/分（体温每升高1℃，心率增加约10次/分，此心率增快且与体温不相称），BP110/65mmHg（血压正常），双肺底偶闻及湿啰音，心律整（考虑心衰），心尖部可闻及S₃奔马律（心肌炎可有体征），肝未触及，根据患者病史、临床表现和体征，最可能的诊断是急性病毒性心肌炎（B对），本病的确诊有赖于心肌活检。急性心包炎（A错）特征性症状为胸骨后、心前区疼痛，疼痛可放射至颈部、左肩、左臂，也可达上腹部，疼痛性质尖锐，与呼吸运动相关，咳嗽、深呼吸、变换体位可加重，最具有诊断价值的体征为心包摩擦音，呈抓刮样、粗糙的高频音，典型的摩擦音为三相摩擦音。急性感染性心内膜炎（C错）为致病微生物循血液循环直接感染心脏瓣膜等伴有赘生物形成，致病菌主要为金黄色葡萄球菌，特征为中毒症状明显，病程进展迅速，杂音多易变化，最具特征的是新出现的病理性杂音或原有杂音改变，可有皮肤及其附属器、眼的表现。心脏压塞（D错）即心包填塞，临床特征为Beck’s三联征：血压低、心音弱、颈静脉怒张，为心包积液迅速积聚或积液量达到一定程度时，造成心脏输出量和回心血量明显下降而产生的相应临床表现。","","N"],["2020-N130",75,"第一节 中毒概述","皮肤黏膜表现",2020,130,"B","","硝基苯中毒常引起的临床表现是",[["A","皮肤、黏膜灼伤"],["B","皮肤、巩膜黄染"],["C","皮肤、黏膜发绀"],["D","皮肤、黏膜苍白"]],"C","硝基苯会引起血红蛋白分子中二价铁被三价铁所取代，失去结合氧的能力，血液中高铁血红蛋白≥30g/L时可出现皮肤黏膜发绀（C对），此时给予氧疗发绀不能改善，需静脉注射亚甲蓝或大量维生素C。皮肤黏膜灼伤（A错）主要见于强酸、强碱、甲醛、苯酚、甲酚皂溶液（来苏儿）、百草枯等腐蚀性毒物中毒。皮肤黏膜黄染（B错）见于毒蕈、鱼胆或四氯化碳等中毒引起的肝损害。皮肤黏膜苍白（D错）常见于贫血。","","N"],["2020-N131",75,"第一节 中毒概述","皮肤黏膜表现",2020,131,"B","","毒蕈中毒常引起的临床表现是",[["A","皮肤、黏膜灼伤"],["B","皮肤、巩膜黄染"],["C","皮肤、黏膜发绀"],["D","皮肤、黏膜苍白"]],"B","毒蕈中毒分为6型，以肝脏损害型和呼吸循环衰竭型最为严重，各类型临床表现可有交叉，可出现皮肤黏膜黄染（肝损害）、黄疸加深、血红蛋白尿（严重溶血）等症状（B对）。皮肤黏膜灼伤（A错）主要见于强酸、强碱、甲醛、苯酚、甲酚皂溶液（来苏儿）、百草枯等腐蚀性毒物中毒。皮肤黏膜发绀（C错）见于亚硝酸盐、苯胺或硝基苯等中毒。皮肤黏膜苍白（D错）常见于贫血。","","N"],["2020-N154",11,"第一节 胸腔积液","恶性胸腔积液",2020,154,"X","","胸水中葡萄糖含量可降低的疾病有",[["A","脓胸"],["B","恶性胸腔积液"],["C","类风湿关节炎"],["D","系统性红斑狼疮"]],"ABCD","正常胸腔积液中葡萄糖含量与血糖相近。漏出液内葡萄糖含量正常（＞3.35mmol/L）。大部分恶性肿瘤导致的胸腔积液葡萄糖也多正常，少数恶性胸腔积液（B对）葡萄糖含量降低。其他胸腔积液葡萄糖含量降低见于类风湿性关节炎并发胸腔积液（C对）、脓胸（A对）、系统性红斑狼疮并发胸腔积液（D对）、结核性胸腔积液。","","N"],["2020-N155",14,"心血管疾病的诊断","心脏超声检查",2020,155,"X","","男性，65岁。6年前患心肌梗死，为评估患者目前的心脏功能，可选用的检查手段有",[["A","动态心电图"],["B","超声心动图"],["C","放射性核素心脏检查"],["D","冠状动脉造影"]],"BC","心脏的主要功能是泵血，临床对心脏泵血功能的评价即心功能评价，可分为心脏射血功能评价和心脏舒张功能评价。超声心动图（B对）检查是诊断心血管疾病的常用方法之一，可计算出左心室舒张末期内径（LVDd）、左心室收缩末内径（LVDs）、左心室舒张末期容积（EDV）、左心室收缩末期容积（ESV）、左心室射血分数（LVEF） 、左心室缩短分数（LVFs） ，其中左心室射血分数是评价大多数患者左心室收缩功能的首选指标，通过计算射血期心室容积的变化速率和心室直径的变化速率可反映心室收缩能力的变化，同时也是目前无创评价左心室舒张功能最为常用和最为重要的方法。超声心动图能直观反映心脏和大血管的结构形态，实时显示其生理活动情况，动态评价心功能，并具有无创性、可重复性、价格优势、床旁检测等优点。核素心肌灌注显像（C对）无论在缺血性心脏病或心肌病等非缺血性心脏病中都有非常广泛的应用，能无创直接显示心肌病变部位、范围以及损伤程度，方便简便、安全有效，其最重要的临床应用价值在于与负荷试验结合评估缺血性心脏病，可反映冠状动脉狭窄的血流动力学和功能性改变，可提供重要的预后信息，其原理是通过正常心肌细胞或有功能的心肌细胞摄取经冠状动脉注入的显像剂而显示心肌影像，病变心肌影像稀疏或缺损。动态心电图（A错）在心律失常检测中用于定性和定量，而且广泛用于检测心肌缺血，筛选高危患者心肌梗死后可能发生的心律失常，为临床诊断和治疗提供可靠的依据，心电图直接反映的是心脏兴奋的产生、传导和恢复过程中的生物电变化，间接地可以反映心脏解剖、代谢、离子和血流动力学等方面的改变，是诊断心律失常的金标准，也是诊断其他心脏疾病的关键或重要指标，同时也是治疗疗效的重要观察指标。冠状动脉造影（D错）是诊断冠状动脉疾病的传统的“金标准”，目前仍是最普遍地被用于确立有无冠状动脉疾病并据此指定治疗方案的影像学检查方法，但只能反映血管本身，并不能反映心肌局部的血流灌注及其心肌细胞的活性。","","N"],["2020-N156",27,"第二节 慢性胃炎","自身免疫",2020,156,"X","","自身免疫性慢性胃炎患者产生巨幼细胞贫血的机制有",[["A","胃壁细胞分泌内因子减少"],["B","内因子抗体致其功能异常"],["C","胃吸收维生素B₁₂减少"],["D","回肠吸收维生素B₁₂减少"]],"ABD","人体不能自身合成维生素B₁₂，必须由食物获取。维生素B₁₂在胃内酸性环境中与壁细胞分泌的内因子形成复合物，在回肠末端，该复合物与肠黏膜细胞表面的受体结合，以胞饮方式进入细胞。当自身免疫性慢性萎缩性胃炎时，患者体内存在抗壁细胞抗体或抗内因子抗体，内因子分泌减少（A对），无法形成维生素B₁₂-内因子复合物（B对），继而导致回肠吸收维生素B₁₂减少（D对C错）。体内维生素B₁₂缺乏时，导致DNA合成障碍，发生巨幼细胞贫血。","","N"],["2020-N157",44,"第一节 急性肾损伤","肾脏替代治疗",2020,157,"X","","急性肾损伤患者，下列情况需要紧急透析治疗的有",[["A","血钾7.0mmol/L"],["B","动脉血pH7.25"],["C","严重肾损伤性脑病"],["D","利尿治疗无效的严重肺水肿"]],"ACD","急性肾损伤的紧急透析指征：①严重高血钾（K⁺＞6.5mmol/L或出现严重心律失常等）（A对）；②急性肺水肿，对利尿剂无良好反应（D对）；③严重代谢性酸中毒，动脉血pH＜7.2（B错）；④还包括严重尿毒症症状如脑病、心包炎、癫痫发作等（C对）。","","N"],["2020-N158",51,"第一节 骨髓增生异常性肿瘤","难治性贫血伴原始细胞增多转变型",2020,158,"X","","根据MDS的FAB分型标准，下列符合难治性贫血伴原始细胞增多转变型的有",[["A","外周血原始细胞≥5%"],["B","骨髓原始细胞＞20%而<30%"],["C","幼粒细胞胞浆中出现Auer小体"],["D","环形铁粒幼细胞≥15%"]],"ABC","根据MDS的FAB分型，难治性贫血伴原始细胞增多转变型（RAEB-t）的FAB分型标准为原始细胞≥5%（A对），骨髓原始细胞＞20%而＜30%（B对）和幼粒细胞胞浆内出现Auer小体（C对）。环形铁粒幼≥15%（D错）属于MDS伴环形铁粒幼细胞（MDS-RS）分型标准之一，该标准为WHO提出的新MDS分型标准。","","N"],["2020-N159",60,"第一节 库欣综合征","皮肤表现",2020,159,"X","","Cushing综合征可出现的临床表现有",[["A","贫血"],["B","皮肤色素沉着"],["C","病理性骨折"],["D","精神异常"]],"BCD","库欣综合征是一组因下丘脑－垂体－肾上腺轴调控失常，肾上腺皮质分泌过多糖皮质激素而导致的临床综合征。临床表现主要是因糖皮质激素长期过多分泌所致蛋白质、脂肪、糖、电解质代谢严重紊乱并伴有多种其他激素分泌异常。包括向心性肥胖、满月脸、多血质外貌、紫纹、高血压、继发性糖尿病、骨质疏松、造血系统改变和电解质及酸碱平衡紊乱等症状。皮肤色素沉着（B对）、病理性骨折（C对）、精神异常（D对）均为库欣综合征可表现的临床症状。库欣综合征患者因皮质醇刺激骨髓造血，红细胞计数和血红蛋白含量均升高，糖皮质激素可破坏淋巴细胞和嗜酸性粒细胞，并使中性粒细胞释放增多，故血中中性粒细胞增多而淋巴细胞和嗜酸性粒细胞减少（A错）。","","N"],["2021-N41",35,"第一节 肝硬化","肝功能减退",2021,41,"A","","符合肝细胞性黄疸检验特点的是",[["A","尿胆原降低"],["B","尿胆红素阳性"],["C","血非结合性胆红素显著下降"],["D","血结合性胆红素显著下降"]],"B","肝细胞性黄疸产生原因为损伤的肝细胞对胆红素的摄取、转化和排泄清除能力降低，此时血中的非结合胆红素（C错）增加，同时因毛细胆管受损，胆栓形成，胆汁排泄受阻而反流入血液循环，故血结合性胆红素（D错）也增加，结合胆红素为水溶性可通过肾小球滤过从尿液中排出，故尿胆红素阳性（B对）。尿胆原是结合胆红素随胆汁进入肠腔后在肠道细菌的作用下形成的，大部分排出体外，小部分参与肠肝循环，可因肝功能障碍而增高或正常（A错）。","","N"],["2021-N42",1,"第二节 慢性阻塞性肺疾病","肺功能评估",2021,42,"A","","诊断慢性阻塞性肺疾病的肺功能标准是",[["A","吸入支气管扩张剂后，FEV₁＜80%预计值"],["B","吸入支气管扩张剂后，FEV₁＜70%预计值"],["C","吸入支气管扩张剂后，FEV₁/FVC＜80%"],["D","吸入支气管扩张剂后，FEV₁/FVC＜70%"]],"D","诊断慢性阻塞性肺疾病的肺功能标准是吸入支气管扩张剂后，FEV₁/FVC＜70%（D对），该项检查结果是临床确定患者存在持续气流受限且不能完全逆转的主要依据，慢阻肺最突出的特征是具有进行性发展的不完全可逆的气流受限。慢阻肺患者吸入支气管扩张剂后FEV₁/FVC＜70%，再依据患者肺功能FEV₁占预计值的百分比（FEV₁%pred）对患者进行气流受限严重程度的分级（GOLD分级），作为患者肺功能评估。","","N"],["2021-N43",2,"第一节 支气管哮喘","重度至危重度(1)",2021,43,"A","","男性，23岁。接触花粉后突发喘憋半小时，家人送至急诊。既往体健。查体：意识模糊，双肺呼吸音明显减低，心率135次/分，律齐。鼻导管吸氧5L/min的情况下查动脉血气分析示pH 7.10，PaCO₂92mmHg，PaO₂65mmHg，下一步治疗措施错误的是",[["A","雾化吸入支气管扩张剂"],["B","静脉应用糖皮质激素"],["C","气管插管机械通气"],["D","静脉应用大剂量利尿剂"]],"D","青年男性患者，接触花粉（变应原）后出现憋喘，查体：P135次/分（心率加快），意识模糊，双肺呼吸音明显减弱（哮喘重度至危重度表现），吸氧后实验室PaCO₂95mmHg（正常值：35mmHg～45mmHg），PaO₂65mmHg（正常值：95mmHg～100mmHg），病人既往体健，可暂排除其他引起呼吸困难的疾病，根据患者的临床表现、体征和实验室检查，最可能的诊断为支气管哮喘，属于急性发作期的重度至危重度。治疗方法为持续雾化吸入SABA（A对），联合雾化吸入短效抗胆碱药、激素混悬液以及静脉给予茶碱类药物；吸氧；尽早静脉应用激素（B对），待病情得到控制和缓解后改为口服给药，经过上述治疗，临床症状和肺功能无改善甚至继续恶化，应及时给予机械通气治疗，指征主要包括：呼吸肌疲劳、PaCO₂≥45mmHg、意识改变（需进行有创机械通气）（C对），同时对重度哮喘发作的治疗，需重视补液，纠正酸中毒及电解质紊乱，积极处理并发症，静脉使用大量利尿剂（D错，为本题正确答案）会诱发或加重酸碱失衡和电解质紊乱。","","N"],["2021-N44",5,"第一节 肺脓肿","血源性肺脓肿",2021,44,"A","","血源性肺脓肿的最常见致病菌是",[["A","金黄色葡萄球菌"],["B","厌氧菌"],["C","铜绿假单胞菌"],["D","军团菌"]],"A","肺脓肿是由一种或多种病原体引起的肺组织化脓性感染，厌氧菌（B错）是最常见的病原体，除厌氧菌外，需氧菌和兼性厌氧菌主要包括金黄色葡萄球菌、化脓性链球菌、B型流感嗜血杆菌、军团菌属（D错）和肺炎克雷伯杆菌、大肠埃希菌、铜绿假单胞菌（C错）等。院内感染中需氧菌比例通常较高。其中血源性肺脓肿的最常见致病菌是金黄色葡萄球菌（A对），以及表皮葡萄球菌、链球菌。","","N"],["2021-N45",18,"第一节 原发性高血压","血管紧张素转换酶抑制剂",2021,45,"A","","男，60岁，高血压20余年，血压最高190/100mmHg，无自觉不适，未规律治疗。今来院健康体检，查体：P62次/分，BP180/90mmHg，心肺（-），化验：尿蛋白（+），血TC6.4mmol/L，HDL-C0.98mmol/L，LDL-C4.96mmol/L，空腹Glu8.6mmol/L，Cr122μmol/L，UA365μmol/L，首选的降压药",[["A","培哚普利"],["B","氨氯地平"],["C","吲达帕胺"],["D","比索洛尔"]],"A","60岁男性患者，高血压20余年，查体：P62次/分（心率正常），BP180/90mmHg（高血压3级），尿蛋白（+）（蛋白尿，提示肾功能不全），血TC6.4mmol/L（总胆固醇TC正常值3～5.2mmol/L，升高，提示高血脂），HDL-C0.98mmol/L（高密度脂蛋白HDL-C正常值＞1.0mmol/L），LDL-C4.96mmol/L（低密度脂蛋白LDL-C正常值＜3.12mmol/L），空腹Glu8.6mmol/L（≥7，提示糖尿病）。结合病史和实验室检查，该患者的诊断为3级高血压、肾功能不全、高血脂、糖尿病，首选的降压药培哚普利（A对），该药物属于ACEI，为一线降压药物，对高血压患者有良好的靶器官保护和心血管终点事件预防作用，具有改善胰岛素抵抗和减少尿蛋白作用，对肥胖、糖尿病和心脏、肾脏靶器官受损的高血压患者具有相对较好的疗效。氨氯地平（B错）属于钙通道阻滞剂，尤其适用于老年高血压、单纯收缩期高血压、左心室肥厚、稳定型冠心病、冠状动脉或颈动脉粥样硬化、脑血管病及周围血管病，本例患者舒张压≥90mmHg，且合并血糖及血脂异常表现，CCB不作为首选降压药物（B错）。吲达帕胺（C错）属于噻嗪类利尿剂，其不良反应为低钾血症、高钙血症，同时会升高空腹血糖、影响血脂、血尿酸代谢，不适用于本例患者（十版内科学P268）。比索洛尔（D错）属于β受体拮抗剂，会增加胰岛素抵抗，还可能掩盖糖尿病患者的低血糖症状，同时会导致血脂升高和血钾轻度升高，不适用于本例患者（十版内科学P268）。","","N"],["2021-N46",17,"第四节 急性冠状综合征","血清心肌坏死标志物",2021,46,"A","","男性，69岁。因两小时前（凌晨5点）在睡眠中突发心前区疼痛伴大汗，自服速效救心丸无效，凌晨7点急送来院，心电图显示Ⅱ、Ⅲ、aVF导联ST段弓背向上抬高0.2～0.4mv，做血液检查，下列最有可能出现异常的是",[["A","肌钙蛋白T"],["B","肌酸激酶同工酶"],["C","谷草转氨酶"],["D","肌红蛋白"]],"D","老年男性患者，凌晨5点在睡眠中突发心前区疼痛伴大汗，自服速效救心丸无效（心梗临床表现），凌晨7点来院就诊（发病2小时），心电图显示Ⅱ、Ⅲ、aVF导联ST段弓背向上抬高0.2～0.4mv（ST段抬高性急性下壁心肌梗死），综合患者的临床表现和辅助检查结果，考虑患者最有可能的诊断为ST段抬高性急性下壁心肌梗死。肌红蛋白增高最早，恢复也较快，但特异性较差，本例患者发病2小时，此时最有可能出现异常的是为肌红蛋白（D对）升高，肌钙蛋白T（A错）于心梗后3～4小时后升高，肌酸激酶同工酶（B错）CK-MB在心梗后4小时内增高，考虑到本例患者发病时间，此时该两项检查可能无异常。需要注意的是，肌钙蛋白是心肌独有的，诊断心肌坏死最特异和敏感的首选标志物，需根据发病时间进行鉴别选择。门冬氨酸氨基转移酶（谷草转氨酶，AST）分布于全身许多器官，对心肌梗死诊断的特异性较差，目前临床已经不推介应用。","","N"],["2021-N47",19,"第六节 心肌炎","心肌炎临床表现",2021,47,"A","","一般不会出现在急性心肌炎病人的临床表现是",[["A","心脏压塞"],["B","猝死"],["C","急性肺水肿"],["D","酷似急性心肌梗死"]],"A","各种病因心包炎均可能伴有心包积液，心脏压塞（A错，为本题正确答案）是短期内出现大量心包积液所导致的，表现为临床特征为Beck's三联征：血压低、心音弱、颈静脉怒张。急性心肌炎的临床表现取决于病变的广泛程度与部位，轻者几乎无症状，重者可导致猝死（B对），多数患者发病前可有发热、全身酸痛、咽痛、腹泻等症状，常诉胸闷、心前区疼痛、心悸、乏力、恶心、头晕等（酷似急性心肌梗死）（D对），疾病发展迅速的患者会出现心力衰竭、急性肺水肿（C对）或心源性休克。","","N"],["2021-N48",21,"第二节 主动脉瓣反流","主动脉瓣反流诊断",2021,48,"A","","女性，46岁。因活动后出现心前区疼痛2个月，每次自含硝酸甘油无效来诊。既往有高血压病、关节炎史。查体：P 80次/分，BP 150/65mmHg，BMI 35kg/m²，甲状腺无肿大，双肺（‒），心界向左扩大，心律整，心尖部S1减弱，可闻及舒张早中期隆隆样杂音，胸骨左缘第3肋间可闻及舒张期叹气样杂音，双下肢水肿（±）。导致该患者心前区疼痛的最主要病因是",[["A","冠心病，高血压"],["B","肥厚型梗阻性心肌病"],["C","二尖瓣狭窄"],["D","主动脉瓣关闭不全"]],"D","中年女性患者，活动后心前区疼痛2个月，自含硝酸甘油无效（暂排除心绞痛）既往有高血压病、关节炎史（主动脉瓣关闭不全可能病因），来院查体：P80/分（正常值：60～100次/分钟），BP150/65mmHg（正常值：90mmHg＜收缩压＜140mmHg、60mmHg＜舒张压＜90mmHg；脉收缩压增高，舒张压降低，脉压增大），BMI：35（BMI标准值：18.5～23.9，肥胖，心脏负荷大），甲状腺无肿大，双肺（-），心律齐，心界向左扩大（主动脉瓣关闭不全体征），听诊S₁减弱（第一心音减弱，为舒张期左心室充盈过度、二尖瓣位置高所致），心尖区闻及舒张早中期隆隆样杂音，胸骨左缘第三肋间舒张期叹气样杂音（主动脉瓣关闭不全特征性杂音），双下肢水肿（+-），根据患者的病史、临床表现和查体结果，最可能的诊断是主动脉瓣关闭不全，该患者心前区疼痛的主要由于左心室射血时引起升主动脉过分牵张或心脏明显增大所致（D对）。冠心病（A错）即冠状动脉粥样硬化性心脏病，可以分为慢性心肌缺血综合征和急性冠状动脉综合征，可发生阵发性的前胸压榨性疼痛、休息或用硝酸酯制剂后疼痛消失（十版内科学P232）；高血压常见症状有头晕、头痛、颈项板紧、疲劳、心悸等，也可出现视物模糊、鼻出血等较重症状，典型的高血压头痛在血压下降后即可消失，高血压一般听诊可听到第二心音亢进、收缩期杂音或收缩早期喀喇音（十版内科学P263）。肥厚型梗阻性心肌病（B错）是肥厚性心肌病的一种，在肥厚型梗阻性心肌病人，左心室收缩时快速血流通过狭窄的流出道产生负压，引起二尖瓣前叶前向运动，加重梗阻；可于胸骨左缘第3～4肋间闻及较粗糙的喷射性收缩期杂音（十版内科学P278）。二尖瓣狭窄（MS）（C错）的主要病因是风湿热，多见于急性风湿热后，二尖瓣狭窄可见呼吸困难、咳嗽、咯血等症状，可在心尖区多可闻及亢进的第一心音，可呈“二尖瓣面容”，右心室扩大时剑突下可触及收缩期抬举样搏动，二尖瓣狭窄特征性的杂音为心尖区舒张中晚期低调的隆隆样杂音，呈递增型，局限，左侧卧位明显，运动或用力呼气可使其增强（十版内科学P306）。","","N"],["2021-N49",26,"第一节 胃食管反流病","胃食管反流病并发症",2021,49,"A","","下列不属于胃食管反流病并发症的是",[["A","食管狭窄"],["B","食管憩室"],["C","上消化道出血"],["D","Barrett食管"]],"B","胃食管反流病并发症包括上消化道出血（C对）、食管狭窄（A对）及Barrett食管（D对）。食管憩室（B错，为本题正确答案）是食管壁的一层或全层局限性膨出，形成与食管腔相通的囊袋，按部位分为咽食管憩室、食管中段憩室和膈上憩室，咽食管憩室和膈上憩室为内压性憩室，与食管功能紊乱有关，食管中段憩室多为牵引性憩室，常为炎症后瘢痕牵拉食管而形成。","","N"],["2021-N50",28,"第一节 消化性溃疡","消化性溃疡诊断",2021,50,"A","","男性，25岁，2年来反复上腹疼痛，一般发生于进餐后1小时，近1天呕出咖啡渣样胃内容物伴黑便1次，既往无肝炎病史。查体：BP100/60mmHg，P 92次/分，心律整，上腹轻度压痛，肝脾肋下未触及。最可能的诊断是",[["A","胃溃疡出血"],["B","十二指肠溃疡出血"],["C","胃癌出血"],["D","肝硬化食管胃底静脉曲张破裂出血"]],"A","青年男性患者，2年来反复上腹疼痛（慢性病程），规律为餐后痛（胃溃疡腹痛症状），近1天呕出咖啡渣样胃内容物伴黑便（考虑溃疡出血），既往无肝炎病史，其他阳性体征（暂排除肝脏疾病），根据患者的病史、临床表现和体征，最可能的诊断是胃溃疡并发出血（A对）。十二指肠溃疡出血（B错）也可表现为慢性上腹痛，并发出血时会出现呕血、黑便等症状，但疼痛一般为饥饿痛或夜间痛、进餐后可缓解，故不作首选诊断；溃疡型胃癌出血（C错）时疼痛无规律，可引起呕血或黑便，继之发生并发症或转移后可出现吞咽困难、恶心呕吐、贫血等特殊症状（十版内科学P379）；食管胃底静脉曲张出血（D错）是肝硬化门脉高压所致，临床表现为突发大量呕鲜血或柏油样便，严重者致出血性休克，本例患者既往无肝炎病史且肝脾肋下未触及，临床表现不符（十版内科学P419）。","","N"],["2021-N51",29,"第二节 结核性腹膜炎","腹腔积液检查",2021,51,"A","","女性，41岁，腹胀、低热3个月。既往有右侧附件结核病史2年。查体T37.8℃，心肺未见异常，腹壁柔韧感，轻压痛，肝脾触诊不满意，移动性浊音阳性。对确诊最有价值的检查是",[["A","腹部B超"],["B","腹部CT"],["C","腹腔穿刺抽液检查"],["D","妇科检查"]],"C","中年女性患者（结核性腹膜炎多见人群），既往有右侧附件结核病史2年（结核性腹膜炎病因），腹胀、低热3个月（结核感染症状），查体T37.8℃（低热），心肺未见异常，腹壁柔韧感，轻压痛，肝脾触诊不满意，移动性浊音阳性（腹腔积液），根据患者病史、临床表现和体征，最可能的诊断为结核性腹膜炎，是结核分枝杆菌感染引起的弥漫性腹膜炎症，对确诊最有价值的检查是腹腔穿刺抽液检查（C对），对鉴别腹水有重要诊断价值，腹水ADA检查的特异性和敏感性均较高（80%～90%），细菌培养结果为阴性，同时可做细胞学检查，排除癌性腹水。腹部B超（A错）可提示穿刺抽取腹水的准确意义，同时可发现少量腹水，对腹部包块性质鉴别有一定帮助，腹部CT（B错）可发现肠粘连、肠结核、肠外肿块等征象，对本病也有辅助诊断价值。本例患者无生殖系统阳性临床表现和体征，妇科检查（D错）对本病确诊无意义。","","N"],["2021-N52",40,"第一节 肾小球疾病概述","水肿",2021,52,"A","","男性，21岁。2周前咽痛、发热，体温最高为38.5℃，按“上感”治疗后好转，2天来眼睑水肿，尿少。查体：BP 150/90mmHg，双眼睑水肿，心肺腹检查未见异常，双下肢凹陷性水肿（++）。尿常规：蛋白（++），沉渣镜检红细胞20～25个/HP，白细胞0～3个/HP。该患者水肿的主要机制是",[["A","醛固酮分泌增多"],["B","血浆胶体渗透压降低"],["C","肾小球滤过率下降"],["D","抗利尿激素分泌增加"]],"C","青年男性患者（急性肾炎高发人群），2周前咽痛，发热，体温最高达38.5℃，按照“上感”治疗（前驱感染史），2天来出现颜面部水肿（考虑肾炎性水肿），少尿。查体：BP150/90mmHg（血压升高），双眼睑水肿，尿常规：蛋白（++）（蛋白尿），沉渣镜检红细胞20～25个/HP（＞3个/HP，镜下血尿），根据该患者病史、临床表现和体征及实验室检查，最可能的诊断是急性肾小球肾炎（急性肾炎），肾小球病变导致肾小球滤过面积明显减少，肾小球滤过率下降（C对），同时肾小管重吸收功能基本正常，造成“球－管失衡”和肾小球滤过分数下降，水、钠排泄减少，血容量增多，血压升高，机体水肿；以及因血容量增多导致RAAS系统被抑制，醛固酮分泌减少（A错），抗利尿激素分泌减少（D错），此外，毛细血管通透性增高可进一步加重水肿，此类水肿属于肾炎性水肿，多从颜面部开始。另一类水肿为肾病性水肿，原因是大量血浆蛋白从尿液丢失，导致血浆胶体渗透压下降（B错），促使液体从血管内进入组织间隙，此时的水肿多从下肢开始。","","N"],["2021-N53",47,"第一节 缺铁性贫血","补铁治疗",2021,53,"A","","女性，26岁。乏力，头晕2个月。既往月经过多2年。化验血：Hb65g/L，RBC2.8x10⁹/L，MCV69fl，MCHC28%，Ret1.2%，WBC4.5x10⁹/L，Plt350×10⁹/L。采用铁剂治疗，最早升高的化验项目是",[["A","Hb"],["B","RBC"],["C","MCV"],["D","Ret"]],"D","青年女性患者，乏力，头晕2个月（贫血的临床表现），既往月经过多2年（女性月经过多是造成缺铁贫的病因），化验血：Hb65g/L，RBC2.8×10⁹/L，MCV69fl，MCHC28%，Ret1.2%，WBC4.5×10⁹/L，Plt350×10⁹/L（正常成年女性Hb＜115g/L称为贫血，MCV＜80fl及MCHC＜32%可诊断为小细胞低色素性贫血），依据患者病史、临床表现及辅助检查可以诊断为缺铁性贫血，缺铁贫的首要治疗方法为根除病因，补足贮铁，该患者除妇科就诊调理月经之外，采用铁剂治疗（口服首选），有效者首先表现为外周血网织红细胞增多（D对），服药后5～10天出现高峰，2周后血红蛋白浓度上升（A错），一般2个月左右恢复正常，同时铁剂治疗应在血红蛋白恢复正常后至少持续4～6个月，待铁蛋白正常后停药。MCV（C错）即平均红细胞容积，属于红细胞参数，反映红细胞大小及Hb改变，用于进行贫血的形态学分类（BC错）。","","N"],["2021-N54",60,"第一节 库欣综合征","肾上腺皮质腺瘤",2021,54,"A","","Cushing综合征单侧肾上腺皮质瘤行患侧肾上腺切除术，术后糖皮质激素替代治疗一般维持的时间是",[["A","1周左右"],["B","1月左右"],["C","2月左右"],["D","6个月至一年以上"]],"D","Cushing综合征单侧肾上腺皮质瘤的手术治疗是主要治疗方法，由于肿瘤自主分泌大量皮质醇，反馈抑制了垂体分泌ACTH，使对侧肾上腺皮质功能减退，故术前、术中及术后应补充适量的皮质激素，以防肾上腺危象发生。单侧肾上腺皮质瘤切除术后糖皮质激素替代治疗一般维持的时间是6个月至1年或更久（D对ABC错）。采用双侧肾上腺全切除术，术后需终生补充肾上腺皮质激素。","","N"],["2021-N55",71,"第六节 贝赫切特病","贝赫切特病针刺反应",2021,55,"A","","贝赫切特病的特异性临床表现是",[["A","颊部蝶形红斑"],["B","腮腺肿大"],["C","针刺反应"],["D","腹部血管杂音"]],"C","贝赫切特病的特异性临床表现是针刺反应（C对），属于贝赫切特病的诊断标准之一。在风湿性疾病范畴内，蝶形红斑（A错）是系统性红斑狼疮的关节外的系统性症状。腮腺肿大（B错）是干燥综合征的临床表现之一。腹部血管杂音（D错）见于大动脉炎。","","N"],["2021-N56",71,"第一节 系统性血管炎概论","系统性血管炎命名与分类",2021,56,"A","","下列属于ANCA相关血管炎的疾病是",[["A","显微镜下多血管炎"],["B","IgA相关血管炎"],["C","系统性红斑狼疮相关血管炎"],["D","类风湿关节炎相关血管炎"]],"A","血管炎是指在病理上以血管壁炎症为特征的一组炎性自身免疫性疾病，分为原发性和继发性。ANCA相关血管炎包括显微镜下多血管炎（A对）、肉芽肿性多血管炎、嗜酸性肉芽肿性多血管炎。IgA相关血管炎（B错）属于免疫复合物性小血管炎；系统性红斑狼疮相关血管炎（C错）及类风湿关节炎相关血管炎（D错）属于与系统性疾病相关的血管炎。","","N"],["2021-N68",28,"第一节 消化性溃疡","消化性溃疡体征",2021,68,"A","","男性，28岁，半小时前在山区修建公路时突发上腹痛，持续加重，近一年患者经常空腹发作上腹痛。此时工地医生给患者做体格检查时，下列对患者病情诊断最有价值的体征是",[["A","心率加快至106次/分"],["B","上腹部压痛"],["C","肠鸣音减弱"],["D","肝浊音界消失"]],"D","青年男性患者，近一年患者经常空腹发作上腹痛（考虑十二指肠溃疡），半小时前在山区修建公路时突发上腹痛（溃疡穿孔诱发因素），持续加重（急性穿孔起病急，变化快，病情重），根据患者病史、临床表现及体征，最可能的诊断是十二指肠溃疡穿孔，此时对患者病情诊断最有价值的体征是肝浊音界消失（因胃肠穿孔导致肝脏表面覆有气体）（D对）。心率加快至106次/分，即心率加快（A错）、上腹部压痛（B错）、肠鸣音减弱或消失（C错）均为急腹症可出现的体征，对本例患者特异性不强，作为支持诊断的其他证据。","c153","N"],["2021-N69",28,"第一节 消化性溃疡","穿孔",2021,69,"A","","男性，28岁，半小时前在山区修建公路时突发上腹痛，持续加重，近一年患者经常空腹发作上腹痛。根据上述体征，该患者最可能的疾病是",[["A","急性心肌梗死"],["B","消化道穿孔"],["C","急性肠梗阻"],["D","急性胰腺炎"]],"B","青年男性患者，近一年患者经常空腹发作上腹痛（考虑十二指肠溃疡），半小时前在山区修建公路时突发上腹痛（溃疡穿孔诱发因素），持续加重（急性穿孔起病急，变化快，病情重），根据患者病史、临床表现及体征，最可能的诊断是十二指肠溃疡穿孔（B对）。急性心肌梗死（A错）有突然胸痛、胸闷、甚至呼吸困难、休克等临床表现，但常有高血压、动脉粥样硬化、冠状动脉粥样硬化性心脏病史，心电图、X线检查、血清酶学检查有助于诊断（十版内科学P135）。肠梗阻（C错）的临床表现一般为腹痛、呕吐、腹胀及停止自肛门排气排便。急性胰腺炎（D错）多有胆道疾病史或发病前饮酒，腹痛剧烈且持续，多位于中左上腹部甚至全腹并向背部放射，血清、尿液和腹腔穿刺液淀粉酶明显升高，X线检查膈下无游离气体，CT、超声检查提示胰腺肿胀，周围渗出。","c153","N"],["2021-N70",47,"第一节 缺铁性贫血","缺铁性贫血诊断",2021,70,"A","","女性，35岁，近2个月渐进性乏力、心悸、头晕来诊，食欲较差，近5个月出现月经不调，每20天来一次，每次持续7～8天，量多。查体：T37.2℃，P102次/分，BP108/68mmHg，皮肤干燥，睑结膜苍白，双肺（-），心律整，心尖部闻及3/6收缩期吹风样杂音，肝脾肋下未及，下肢不肿。根据上述病史及特征，最可能的诊断是",[["A","急性风湿热"],["B","结核病"],["C","缺铁性贫血"],["D","甲状腺功能减退"]],"C","中年女性患者，近2个月渐进性乏力、心悸、头晕来诊，食欲较差（贫血的常见症状），近5个月出现月经不调，每20天来一次，每次持续7～8天，量多（月经不调，月经过多为缺铁性原发病的表现）。体查：T37.2℃，P102次/分（正常值：一般为60～100次/分，心率增快），BP108/68mmHg（收缩压：90～139mmHg，舒张压：60～89mmHg），皮肤干燥，睑结膜苍白（为贫血的基本表现），双肺（-），心律整，心尖部闻及3/6收缩期吹风样杂音（贫血可有心血管系统表现），肝脾肋下未及，下肢不肿，根据患者临床表下、查体结果和既往史，最可能的诊断是缺铁性贫血（C对）。急性风湿热（A错）发病前多有链球菌前驱感染史，急性起病，多表现为中等程度不规则发热，伴食欲减退、多汗、疲倦、面色苍白等毒血症表现（十版内科学P313）。结核病（B错）是结核杆菌感染引起的慢性传染病，结核杆菌可能侵入人体全身各种器官，但主要侵犯肺脏，结核菌感染全身症状多表现为典型的午后潮热，倦怠乏力、盗汗、食欲减退和体重减轻等（十版内科学P73）。甲状腺功能减退症（D错）是由各种原因导致的低甲状腺激素血症或甲状腺激素抵抗而引起的全身性低代谢综合征，典型表现为粘液性水肿，常有畏寒、乏力、手足肿胀感；脉率缓慢；也有女性月经紊乱，或者月经过多、不孕（十版内科学P695）。","c154","N"],["2021-N71",47,"第一节 缺铁性贫血","组织缺铁表现",2021,71,"A","","女性，35岁，近2个月渐进性乏力、心悸、头晕来诊，食欲较差，近5个月出现月经不调，每20天来一次，每次持续7～8天，量多。查体：T37.2°C，P102次/分，BP108/68mmHg，皮肤干燥，睑结膜苍白，双肺（-），心律整，心尖部闻及3/6收缩期吹风样杂音，肝脾肋下未及，下肢不肿。该患者还可能出现的体征是",[["A","杵状指"],["B","爪形手"],["C","匙状甲"],["D","手指末端指节肿大"]],"C","中年女性患者，近2个月渐进性乏力、心悸、头晕来诊，食欲较差（贫血的常见症状），近5个月出现月经不调，每20天来一次，每次持续7～8天，量多（月经不调，月经过多为缺铁性原发病的表现）。体查：T37.2℃，P102次/分（正常值：一般为60～100次/分，心率增快），BP108/68mmHg（收缩压：90～139mmHg，舒张压：60～89mmHg），皮肤干燥，睑结膜苍白（为贫血的基本表现），双肺（-），心律整，心尖部闻及3/6收缩期吹风样杂音（贫血可有心血管系统表现），肝脾肋下未及，下肢不肿，根据患者临床表下、查体结果和既往史，最可能的诊断是缺铁性贫血，故该患者还可能出现的体征是匙状甲（C对），又称为反甲，表现为指甲中央凹陷，边缘翘起，指甲变薄，表面粗糙有条纹，多见于缺铁性贫血和高原疾病，偶见于风湿热及甲癣。杵状指（A错）亦称鼓棰指，表现为手指或足趾末端增生、肥厚、呈杵状膨大；其发生机制可能与肢体末端慢性缺氧、代谢障碍及中毒性损害有关，常可见于法洛四联症、高原红细胞增多症、肺部肿瘤和慢性脓毒性疾病、肝硬化等（九版诊断学P206）。爪形手（B错）为手指呈鸟爪样，典型表现为手指的精细动作消失，原因为尺神经损伤时，大部分手内收肌麻痹，造成握力减弱，持物不稳，动作不灵活等表现（九版诊断学P205）。手指末端指节肿大（D错）见于类风湿性关节炎，表现为病变关节周围囊性感或“面团样”感觉（三版八年制内科学P1160）。","c154","N"],["2021-N72",47,"第一节 缺铁性贫血","血象",2021,72,"A","","女性，35岁，近2个月渐进性乏力、心悸、头晕来诊，食欲较差，近5个月出现月经不调，每20天来一次，每次持续7～8天，量多。查体：T37.2°C，P102次/分，BP108/68mmHg，皮肤干燥，睑结膜苍白，双肺（-），心律整，心尖部闻及3/6收缩期吹风样杂音，肝脾肋下未及，下肢不肿。以下检查项不支持诊断的是",[["A","外周血红细胞大小不等"],["B","血小板增多"],["C","白细胞可正常"],["D","血涂片见镰刀状红细胞"]],"D","中年女性患者，近2个月渐进性乏力、心悸、头晕来诊，食欲较差（贫血的常见症状），近5个月出现月经不调，每20天来一次，每次持续7～8天，量多（月经不调，月经过多为缺铁性原发病的表现）。体查：T37.2℃，P102次/分（正常值：一般为60～100次/分，心率增快），BP108/68mmHg（收缩压：90～139mmHg，舒张压：60～89mmHg），皮肤干燥，睑结膜苍白（为贫血的基本表现），双肺（-），心律整，心尖部闻及3/6收缩期吹风样杂音（贫血可有心血管系统表现），肝脾肋下未及，下肢不肿，根据患者临床表现、查体结果和既往史，最可能的诊断是缺铁性贫血，缺铁性贫血血象呈小细胞低色素性贫血，MCV＜80fl，MCH＜27pg，MCHC＜320g/L，可见外周血红细胞大小不一（A对），其中体积小者多见，其中心淡染区扩大，网织红细胞计数多正常或轻度增高，白细胞和血小板计数大多正常，若因慢性失血导致的缺铁性贫血，可见血小板计数增高（BC对）。血涂片见镰刀状红细胞（D错，为本题正确答案）是镰状细胞贫血的典型特征，该病以常染色体显性方式遗传。","c154","N"],["2021-N73",11,"","",2021,73,"A","","女性，56岁。劳累后发热1周，体温最高39.5℃，伴多汗、纳差，体重下降2公斤，同时出现右侧季肋部疼痛，疼痛较剧烈，夜间无法安睡，于外院输注哌拉西林/他唑巴坦3天无效收入院。既往史：类风湿关节炎20年，平素每日服用来氟米特及强的松治疗，病情稳定。入院时胸片显示右侧胸腔积液。胸腔穿刺化验结果：胸水比重1.038，白细胞16800×10⁶/L，多核细胞80%，单核细胞20%，LDH 3367U/L，ADA 116U/L。该胸腔积液性质最有可能是",[["A","结核性胸腔积液"],["B","恶性胸腔积液"],["C","脓胸"],["D","类风湿相关性胸腔积液"]],"C","中老年女性患者，劳累后发热一周，最高体温39.5℃（急性感染症状），伴多汗，纳差体重减轻2kg，伴右季肋区疼痛，疼痛较剧烈（急性胸痛），夜间无法安睡，在外院输注哌拉西林/他唑巴坦三天后无效入院（β-内酰胺类抗生素使用无效），既往类风湿关节炎20年，长期服用糖皮质激素病情稳定（长期使用糖皮质激素易发生感染），X线提示右侧胸腔积液，胸腔穿刺结果示：比重1.036（为渗出液），白细胞16800×10⁶/L（正常值：（3.5～9.5）×10⁹/L，脓胸患者白细胞可高达10×10⁹/L以上），单核细胞20％，多核细胞80％（中性粒细胞为主，提示急性感染），ADA：116U/L（胸腔积液ADA升高），LDH：3367U/L（正常值血清100～300U/L，升高提示炎症），根据患者既往病史、临床表现、影像学检查和实验室检查结果，最可能的诊断是类肺炎性胸腔积液，该胸腔积液性质最有可能是脓胸（C对）。本例需于结核性胸膜炎相鉴别，结核性胸膜炎胸腔积液ADA虽也会升高，但胸腔积液以淋巴细胞为主，患者同时有干咳、潮热、盗汗、消瘦等结核中毒症状，且多见于青壮年（十版内科学P131）。恶性胸腔积液（B错）病人一般无发热且LDH＞500U/L，以45岁以上中老年人多见，有胸部钝痛、咳血丝痰和消瘦等症状，胸腔积液多呈血性、量大、增长迅速，同时CEA或其他肿瘤标志物升高（十版内科学P131）；类风湿相关性胸腔积液（D错）常见于疾病活动期，胸腔积液为小至中等量，常为渗出液，RF常阳性，补体水平低下，白细胞、蛋白质、胆固醇和LDH均可增高，但糖含量明显下降，糖皮质激素应用可使疾病好转（十五版实用内科学P2612）。","c155","N"],["2021-N74",11,"第一节 胸腔积液","胸腔积液病原学检测",2021,74,"A","","女性，56岁。劳累后发热1周，体温最高39.5℃，伴多汗、纳差，体重下降2公斤，同时出现右侧季肋部疼痛，疼痛较剧烈，夜间无法安睡，于外院输注哌拉西林/他唑巴坦3天无效收入院。既往史：类风湿关节炎20年，平素每日服用来氟米特及强的松治疗，病情稳定。入院时胸片显示右侧胸腔积液。胸腔穿刺化验结果：胸水比重1.038，白细胞16800×10⁶/L，多核细胞80%，单核细胞20%，LDH 3367U/L，ADA 116U/L。为明确诊断首先要做的检查",[["A","胸水中找肿瘤细胞"],["B","胸水进行细菌培养和药敏试验"],["C","胸水进行结核菌培养"],["D","胸水中找类风湿因子"]],"B","中老年女性患者，劳累后发热一周，最高体温39.5℃（急性感染症状），伴多汗，纳差体重减轻2kg，伴右季肋区疼痛，疼痛较剧烈（急性胸痛），夜间无法安睡，在外院输注哌拉西林/他唑巴坦三天后无效入院（β-内酰胺类抗生素使用无效），既往类风湿关节炎20年，长期服用糖皮质激素病情稳定（长期使用糖皮质激素易发生感染），X线提示右侧胸腔积液，胸腔穿刺结果示：比重1.036（为渗出液），白细胞16800×10⁶/L（正常值：（3.5～9.5）×10⁹/L，脓胸患者白细胞可高达10×10⁹/L以上），单核细胞20％，多核细胞80％（中性粒细胞为主，提示急性感染），ADA：116U/L（胸腔积液ADA升高），LDH：3367U/L（正常值血清100～300U/L，升高提示炎症），根据患者既往病史、临床表现、影像学检查和实验室检查结果，最可能的诊断是类肺炎性胸腔积液，即脓胸，为明确诊断和治疗，首先要做的检查胸水进行细菌培养和药敏试验（B对），急性脓胸经过有效抗生素的治疗并及时排除脓液，炎症可逐渐消退。胸水中找肿瘤细胞（A错）可明确诊断为恶性胸腔积液，因其常由恶性肿瘤侵犯胸膜引起，恶性胸腔积液中约有40％～90％可查到恶性肿瘤细胞。胸水进行结核菌培养（C错）可明确结核性胸膜炎，沉渣找结核杆菌或培养可阳性，但阳性率仅约20％，老年病人可无发热，结核菌素试验亦常阴性，应予注意。胸水中找类风湿因子（D错）可明确诊断类风湿相关性胸腔积液，类风湿相关性胸腔积液中类风湿因子＞1:320。","c155","N"],["2021-N75",11,"第一节 胸腔积液","肺炎旁胸腔积液",2021,75,"A","","女性，56岁。劳累后发热1周，体温最高39.5℃，伴多汗、纳差，体重下降2公斤，同时出现右侧季肋部疼痛，疼痛较剧烈，夜间无法安睡，于外院输注哌拉西林/他唑巴坦3天无效收入院。既往史：类风湿关节炎20年，平素每日服用来氟米特及强的松治疗，病情稳定。入院时胸片显示右侧胸腔积液。胸腔穿刺化验结果：胸水比重1.038，白细胞16800×10⁶/L，多核细胞80%，单核细胞20%，LDH 3367U/L，ADA 116U/L。该患者最重要的治疗是",[["A","全身化疗"],["B","胸腔穿刺引流"],["C","四联抗结核药物治疗"],["D","增加强的松用量并加用免疫抑制剂"]],"B","中老年女性患者，劳累后发热一周，最高体温39.5℃（急性感染症状），伴多汗，纳差体重减轻2kg，伴右季肋区疼痛，疼痛较剧烈（急性胸痛），夜间无法安睡，在外院输注哌拉西林/他唑巴坦三天后无效入院（β-内酰胺类抗生素使用无效），既往类风湿关节炎20年，长期服用糖皮质激素病情稳定（长期使用糖皮质激素易发生感染），X线提示右侧胸腔积液，胸腔穿刺结果示：比重1.036（为渗出液），白细胞16800×10⁶/L（正常值：（3.5～9.5）×10⁹/L，脓胸患者白细胞可高达10×10⁹/L以上），单核细胞20％，多核细胞80％（中性粒细胞为主，提示急性感染），ADA：116U/L（胸腔积液ADA升高），LDH：3367U/L（正常值血清100～300U/L，升高提示炎症），根据患者既往病史、临床表现、影像学检查和实验室检查结果，最可能的诊断是类肺炎性胸腔积液，即脓胸，该患者胸痛明显、剧烈，夜间无法安睡，说明胸腔积液量较多，此时最重要的措施是胸腔穿刺引流（B对），每次穿刺均尽可能将脓液抽尽，之后再注入等量生理盐水或2%碳酸氢钠溶液反复冲洗，直到抽出液变为清亮为止。急性脓胸的治疗原则为：控制感染、引流脓液、全身支持治疗。全身化疗（A错）是恶性胸腔积液最重要的治疗方式，胸腔内注入博来霉素、丝裂霉素等抗肿瘤药物，可减缓胸腔积液的产生。四联抗结核药物治疗（C错）是结核性胸膜炎最重要的治疗。考虑本例患者的病史，增加强的松用量并加用免疫抑制剂（D错）疗效不肯定。","c155","N"],["2021-N76",19,"第二节 扩张型心肌病","扩张型心肌病诊断",2021,76,"A","","男性，66岁。半年来劳累后心悸、气短，1周来发热、咳嗽、心悸，气短症状明显加重，夜间不能平卧，尿少，下肢水肿。既往有高血压、心脏扩大病史。查体：T 38.1℃，P 88次/分，R 18次/分，BP 110/70mmHg。半卧位，颈静脉充盈，双肺均可闻及湿啰音，心界向左扩大，心率118次/分，心律绝对不整，心尖部可闻及3/6级收缩期吹风样杂音，双下肢凹陷性水肿（++）。超声心动图显示左房、左室扩大，左室壁弥漫性运动障碍，LVEF 40%。该患者目前最主要的诊断是",[["A","瓣膜性心脏病"],["B","原发性高血压病"],["C","扩张型心肌病"],["D","冠心病"]],"C","老年男性患者，半年来劳累后心悸、气短（活动耐量下降），1周来发热、咳嗽，心悸气短，症状加重（感染诱发加重），夜间不能平卧（左心功能不全症状），尿少，下肢水肿（为右心功能不全症状）。既往有高血压病，心脏扩大病史（慢性起病）。查体：T38.1℃（正常值：36.1℃～37℃，体温升高），P88次/分，R18次/分，BP110/70mmHg（正常值：收缩压：90～139mmHg，舒张压：60～89mmHg），半卧位颈静脉充盈（右心衰体征），双肺均可闻及湿啰音（左心衰体征），心界向左扩大（心脏扩大），心率118次/分（心率正常值：一般为60～100次/分，心率加快），心律绝对不齐（伴有心律失常），心尖部可闻及3/6级收缩期吹风样杂音（扩心病的常见症状），双下肢凹陷性水肿(++)（右心衰体征），超声心动图显示左房、左室扩大，左室壁运动弥漫性运动障碍（DCM超声心动典型表现），LVEF40％（左心室射血分数正常值：大于60%，显著降低），根据患者的病史、临床表现和体征，该患者目前最主要的诊断是扩张型心肌病（C对）。瓣膜性心脏病（A错）是由多种原因引起的心脏瓣膜狭窄或（和）关闭不全所致的心脏疾病，以风湿性心脏病最为常见，超声心动图检查有助于明确病变部位并评价病变严重程度（十版内科学P299）。原发性高血压（B错）临床诊断标准为在未使用降压药物的情况下诊室收缩压≥140mmHg和（或）舒张压≥90mmHg（十版内科学P263）。冠心病（CHD）（D错）即冠状动脉粥样硬化性心脏病，当冠脉血流量不能满足心肌代谢的需要时引起心肌缺血缺氧，临床表现有明显心绞痛，严重时可导致心肌梗死（十版内科学P232）。","c156","N"],["2021-N77",19,"第二节 扩张型心肌病","利尿剂",2021,77,"A","","男性，66岁。半年来劳累后心悸、气短，1周来发热、咳嗽、心悸，气短症状明显加重，夜间不能平卧，尿少，下肢水肿。既往有高血压、心脏扩大病史。查体：T 38.1℃，P 88次/分，R 18次/分，BP 110/70mmHg。半卧位，颈静脉充盈，双肺均可闻及湿啰音，心界向左扩大，心率118次/分，心律绝对不整，心尖部可闻及3/6级收缩期吹风样杂音，双下肢凹陷性水肿（++）。超声心动图显示左房、左室扩大，左室壁弥漫性运动障碍，LVEF 40%。该患者即刻选用的治疗药物，不正确的是",[["A","利尿剂"],["B","β受体拮抗剂"],["C","抗凝药"],["D","血管紧张素转换酶抑制剂"]],"B","老年男性患者，半年来劳累后心悸、气短（活动耐量下降），1周来发热、咳嗽，心悸气短，症状加重（感染诱发加重），夜间不能平卧（左心功能不全症状），尿少，下肢水肿（为右心功能不全症状）。既往有高血压病，心脏扩大病史（慢性起病）。查体：T38.1℃（正常值：36.1℃～37℃，体温升高），P88次/分，R18次/分，BP110/70mmHg（正常值：收缩压：90～139mmHg，舒张压：60～89mmHg），半卧位颈静脉充盈（右心衰体征），双肺均可闻及湿啰音（左心衰体征），心界向左扩大（心脏扩大），心率118次/分（心率正常值：一般为60～100次/分，心率加快），心律绝对不齐（伴有心律失常），心尖部可闻及3/6级收缩期吹风样杂音（扩心病的常见症状），双下肢凹陷性水肿(++)（右心衰体征），超声心动图显示左房、左室扩大，左室壁运动弥漫性运动障碍（DCM超声心动典型表现），LVEF40％（左心室射血分数正常值：大于60%，显著降低），根据患者的病史、临床表现和体征，该患者目前最主要的诊断是扩张型心肌病，所有左心室射血分数＜40%的患者若无禁忌都应使用β受体拮抗剂，但根据患者临床表现，本例患者NYHA心功能分级为Ⅳ级，且属于心力衰竭急性发作期，超声心动图示左心室功能不全，为β受体拮抗剂的禁忌症（B错，为本题正确答案）。对心腔明显扩大伴有射血分数降低、NYHA心功能Ⅳ级、长期卧床、有血管栓塞史或深静脉有血栓形成者应使用华法林抗凝（C对）。利尿剂（A对）的应用能有效改善胸闷、气短和水肿等症状，通常从小剂量开始。血管紧张素转换酶抑制剂（D对）能减缓心室重构及心肌进一步损伤，延缓病变发展。","c156","N"],["2021-N78",19,"第二节 扩张型心肌病","β受体拮抗剂",2021,78,"A","","男性，66岁。半年来劳累后心悸、气短，1周来发热、咳嗽、心悸，气短症状明显加重，夜间不能平卧，尿少，下肢水肿。既往有高血压、心脏扩大病史。查体：T 38.1℃，P 88次/分，R 18次/分，BP 110/70mmHg。半卧位，颈静脉充盈，双肺均可闻及湿啰音，心界向左扩大，心率118次/分，心律绝对不整，心尖部可闻及3/6级收缩期吹风样杂音，双下肢凹陷性水肿（++）。超声心动图显示左房、左室扩大，左室壁弥漫性运动障碍，LVEF 40%。该患者经治疗1周后，体温正常，心悸气短症状缓解，夜间可平卧，下肢水肿消失。查体：P 68次/分，BP 125/70mmHg，左下肺偶闻及湿啰音，心率92次/分，心律绝对不整，杂音同前。对该患者在制定长期治疗心功能不全的方案中，不正确的是",[["A","坚持使用ACEI或ARB类药物"],["B","应用β受体拮抗剂"],["C","应用醛固酮受体拮抗剂"],["D","应用钙通道阻滞剂"]],"D","扩张型心肌病患者，治疗一周后，体温正常，心悸气短症状缓解，夜间可平卧，下肢水肿消失，脉搏68次/分，BP125/70mmHg，心率92次/分，心律绝对不齐，说明患者治疗后急性心衰症状有所缓解，伴心律失常，扩心病针对心功能不全的治疗原则是减轻心室重构及心肌进一步损伤，延缓病变发展，按照慢性心力衰竭治疗指南进行治疗，ACEI或ARB类药物（A对），醛固酮受体拮抗剂（C对）可阻断心力衰竭发生发展的中心环节之一——肾素-血管紧张素-醛固酮系统，可以延缓心室重构，降低死亡率；β受体拮抗剂（B对）可抑制交感神经激活对心力衰竭代偿的不利作用，原则上所有病情稳定并无禁忌证的心功能不全病人一经诊断均应立即以小剂量起始应用β受体拮抗剂，逐渐增加达最大耐受剂量并长期维持，可延缓疾病进展，减少猝死。钙通道阻滞剂（D错，为本题正确答案）的临床应用主要是防治心血管系统疾病，能松弛血管平滑肌，降低外周血管阻力，降低血压，广泛用于高血压、心绞痛、心律失常等，但其扩血管作用引起水钠潴留会加重心衰，且有心肌抑制作用，不宜在心力衰竭、严重房室传导阻滞、心源性休克等情况使用。","c156","N"],["2021-N79",35,"","",2021,79,"A","","男性，55岁，发热，呕吐，腹泻1天，烦躁不安，意识障碍1小时急诊入院，查体：T37.8℃，P90次/分，BP110/70mmHg，神志不清，颈部及胸前区可见蜘蛛痣，巩膜轻度黄染，心肺未见异常，腹部柔软，肝肋下未触及，脾肋下2厘米，血常规Hb112g/L，WBC3.4×10⁹/L，Plt98×10⁹/L尿常规:蛋白质（±），尿糖（+），尿沉渣镜检（-）。最可能的诊断是",[["A","肝性脑病"],["B","糖尿病酮症酸中毒"],["C","脑血管病"],["D","尿毒症"]],"A","中年男性患者，发热，呕吐，腹泻1天（肝性脑病诱因），烦躁不安，意识障碍1小时（精神症状）急诊入院，查体：T37.8℃（正常体温36～37℃，发热），P90次/分（正常脉搏60～100次/min），BP110/70mmHg（血压正常值为90～139mmHg/60～89mmHg，血压正常），神志不清，颈部及胸前区可见蜘蛛痣（是肝病典型体征），巩膜轻度黄染（有黄疸，提示肝病），心肺未见异常，腹部柔软，肝肋下未触及，脾肋下2厘米（脾大，提示有门静脉高压），血常规Hb112g/L（正常Hb130～175g/L，降低），WBC3.4×10⁹/L（正常WBC3.5～9.5×10⁹/L，降低），Plt98×10⁹/L（正常Plt125～350×10⁹/L，降低），尿常规:蛋白质（±），尿糖（+）（提示肾功能异常），尿沉渣镜检（-），根据患者的病史、查体结果、实验室检查，最可能的诊断是肝性脑病（A对），为肝功能衰竭或门体分流引起的中枢神经系统神经精神综合征。糖尿病酮症酸中毒（B错）是高血糖危象之一，由于胰岛素不足或作用明显减弱和升糖激素不适当升高引起的糖、脂肪和蛋白代谢严重紊乱综合征，临床以高血糖、高血酮和代谢性酸中毒为主要表现，疾病发展至失代偿阶段会出现疲乏、食欲减退、恶心呕吐，多尿、口干、头痛、嗜睡，呼吸深快，呼气中有烂苹果味（丙酮）等。脑血管病（C错）是脑血管病变导致脑功能障碍的一类疾病的总称。它包括血管腔闭塞或狭窄、血管破裂、血管畸形、血管壁损伤或通透性发生改变等各种脑血管病变引发的局限性或弥漫性脑功能障碍，但不包括血流动力学异常等因素导致的全脑缺血或缺氧所引发的弥漫性脑功能障碍。尿毒症（D错）是慢性肾衰竭晚期，即终末期肾病，临床表现为水、电解质、酸碱平衡紊乱，糖、脂肪、蛋白质和氨基酸代谢障碍及各系统功能障碍，神经系统累及表现为脑卒中、中枢认知功能障碍、周围神经病变和睡眠障碍。","c157","N"],["2021-N80",35,"","",2021,80,"A","","男性，55岁，发热，呕吐，腹泻1天，烦躁不安，意识障碍1小时急诊入院，查体：T37.8℃，P90次/分，BP110/70mmHg，神志不清，颈部及胸前区可见蜘蛛痣，巩膜轻度黄染，心肺未见异常，腹部柔软，肝肋下未触及，脾肋下2厘米，血常规Hb112g/L，WBC3.4×10⁹/L，Plt98×10⁹/L尿常规:蛋白质（±），尿糖（+），尿沉渣镜检（-）。对确诊最有价值的检查是",[["A","血氨"],["B","血糖"],["C","头颅CT"],["D","血肌酐"]],"A","中年男性患者，发热，呕吐，腹泻1天（肝性脑病诱因），烦躁不安，意识障碍1小时（精神症状）急诊入院，查体：T37.8℃（正常体温36～37℃，发热），P90次/分（正常脉搏60～100次/min），BP110/70mmHg（血压140/90mmHg，降低），神志不清，颈部及胸前区可见蜘蛛痣（是肝病典型体征），巩膜轻度黄染（有黄疸，提示肝病），心肺未见异常，腹部柔软，肝肋下未触及，脾肋下2厘米（脾大，提示有门静脉高压），血常规Hb112g/L（正常Hb130～175g/L，降低），WBC3.4×10⁹/L（正常WBC3.5～9.5×10⁹/L，降低），Plt98×10⁹/L（正常Plt125～350×10⁹/L，降低），尿常规:蛋白质（±），尿糖（+）（提示肾功能异常），尿沉渣镜检（-），根据患者的病史、查体结果、实验室检查，最可能的诊断是肝性脑病，对该患者诊断最有意义的检查是血氨（A对）检查，氨中毒学说是目前肝性脑病发病机制中占最主要地位的学说，血氨升高对疾病的确诊有重要的参考价值。血糖（B错）测定常用于反映胰腺内分泌功能，多用于糖尿病及相关并发症的诊断。头部CT（C错）主要用于排除脑血管意外及颅内肿瘤等疾病。血清肌酐（D错）浓度检测是临床评估肾小球滤过功能的常用方法。","c157","N"],["2021-N81",35,"第一节 肝硬化","及早识别及去除HE发作的诱因",2021,81,"A","","男性，55岁，发热，呕吐，腹泻1天，烦躁不安，意识障碍1小时急诊入院，查体：T37.8℃，P90次/分，BP110/70mmHg，神志不清，颈部及胸前区可见蜘蛛痣，巩膜轻度黄染，心肺未见异常，腹部柔软，肝肋下未触及，脾肋下2厘米，血常规Hb112g/L，WBC3.4×10⁹/L，Plt98×10⁹/L尿常规:蛋白质（±），尿糖（+），尿沉渣镜检（-）。为缓解患者躁动首选药物是",[["A","苯巴比妥"],["B","地西泮"],["C","水合氯醛"],["D","异丙嗪"]],"D","中年男性患者，发热，呕吐，腹泻1天（肝性脑病诱因），烦躁不安，意识障碍1小时（精神症状）急诊入院，查体：T37.8℃（正常体温36～37℃，发热），P90次/分（正常脉搏60～100次/min），BP110/70mmHg（血压140/90mmHg，降低），神志不清，颈部及胸前区可见蜘蛛痣（是肝病典型体征），巩膜轻度黄染（有黄疸，提示肝病），心肺未见异常，腹部柔软，肝肋下未触及，脾肋下2厘米（脾大，提示有门静脉高压），血常规Hb112g/L（正常Hb130～175g/L，降低），WBC3.4×10⁹/L（正常WBC3.5～9.5×10⁹/L，降低），Plt98×10⁹/L（正常Plt125～350×10⁹/L，降低），尿常规:蛋白质（±），尿糖（+）（提示肾功能异常），尿沉渣镜检（-），根据患者的病史、查体结果、实验室检查，最可能的诊断是肝性脑病，当患者狂躁不安时禁用阿片类、巴比妥类（A错）、苯二氮䓬类镇静剂（B错），为缓解该患者躁动首选药物是异丙嗪（D对）。水合氯醛（C错）对心、肝、肾实质性脏器有损害，对严重心、肝、肾疾病患者禁用。","c157","N"],["2021-N82",41,"第一节 尿路感染","定位诊断",2021,82,"A","","女性，24岁。2天来突然出现发热伴尿频，尿急，尿痛来诊。既往体健。查体：T38℃，左肾区有叩击痛。以下最可能的诊断是",[["A","急性膀胱炎"],["B","急性肾盂肾炎"],["C","尿道综合征"],["D","肾结核"]],"B","育龄期青年女性患者（急性肾盂肾炎的高发人群），2天来突然出现（起病急）发热伴尿频，尿急，尿痛来诊（尿路刺激征），既往体健。查体：T38℃（正常体温36～37℃，发热），左肾区有叩击痛（急性肾盂肾炎常见症状），根据患者的病史、查体结果、实验室检查，最可能的诊断是急性肾盂肾炎（B对）。急性膀胱炎（A错）以尿路刺激征为突出表现，一般少有发热、腰痛等，可有耻骨上方疼痛或压痛，部分患者可有排尿困难，尿液常浑浊，可出现血尿（十版内科学P500）。尿道综合征（C错）常见于女性，病人有尿频、尿急、尿痛及排尿不适等尿路剌激症状，但多次检查均无真性细菌尿（十版内科学P502）。肾结核（D错）患者膀胱刺激症状更为明显，一般抗生素治疗无效，尿沉渣可找到抗酸杆菌，尿培养结核分枝杆菌阳性，如经抗生素治疗后，仍残留尿路感染症状或尿沉渣异常者，应高度注意肾结核（十版内科学P502）。","c158","N"],["2021-N83",41,"第一节 尿路感染","尿常规检查",2021,83,"A","","女性，24岁。2天来突然出现发热伴尿频，尿急，尿痛来诊。既往体健。查体：T38℃，左肾区有叩击痛。下列尿检查结果最能支持诊断的是",[["A","尿蛋白（+-）"],["B","沉渣镜检红细胞20～25个/HP"],["C","沉渣镜检白细胞10～15个/HP"],["D","沉渣镜检见白细胞管型"]],"D","育龄期青年女性患者（急性肾盂肾炎的高发人群），2天来突然出现（起病急）发热伴尿频，尿急，尿痛来诊（尿路刺激征），既往体健。查体：T38℃（正常体温36～37℃，发热），左肾区有叩击痛（急性肾盂肾炎常见症状），根据患者的病史、查体结果、实验室检查，最可能的诊断是急性肾盂肾炎，最能支持诊断结果的尿液检查的是沉渣镜检见白细胞管型（D对）。尿蛋白（+—）（微量蛋白尿）、沉渣镜检红细胞20～25个/HP（＞3～5个/HP，血尿），沉渣镜检白细胞10～15个/HP（＞5/HP，白细胞尿）为尿路感染时可出现的尿液检查结果，对感染定位无特异性，仅能作为尿路感染的诊断依据（BC错）。","c158","N"],["2021-N84",41,"第一节 尿路感染","肾盂肾炎",2021,84,"A","","女性，24岁。2天来突然出现发热伴尿频，尿急，尿痛来诊。既往体健。查体：T38℃，左肾区有叩击痛。最有效的治疗方案是",[["A","3天疗程SMZ-TMP疗法"],["B","10～14天疗程喹诺酮类疗法"],["C","规律抗结核治疗"],["D","降温处理"]],"B","育龄期青年女性患者（急性肾盂肾炎的高发人群），2天来突然出现（起病急）发热伴尿频，尿急，尿痛来诊（尿路刺激征），既往体健。查体：T38℃（正常体温36～37℃，发热），左肾区有叩击痛（急性肾盂肾炎常见症状），根据患者的病史、查体结果、实验室检查，最可能的诊断是急性肾盂肾炎，针对该患者最有效的治疗方案是10～14天疗程喹诺酮类疗法（B对）。3天疗程SMZ-TMP疗法（A错）主要用于急性膀胱炎（P495）。该患者不存在结核感染，因此不需要抗结核治疗（C错）。患者发热主要以病因治疗为主，降温处理（D错）用于高热患者的对症处理。","c158","N"],["2021-N85",52,"第三节 慢性髓系白血病","慢性髓系白血病诊断",2021,85,"A","","女性，25岁。乏力、腹胀、消瘦1个半月。查体：心肺未见异常，腹软，肝肋下1cm，脾肋下7cm。化验血：Hb 125g/L，WBC 91.5×10⁹/L，分类：中幼粒细胞6%，晚幼粒细胞11%，杆状核粒细胞23%，分叶中性粒细胞33%，嗜酸性粒细胞9%，嗜碱性粒细胞4%，淋巴细胞14%，Plt 412×10⁹/L，NAP阴性。最可能的诊断是",[["A","原发性骨髓纤维化"],["B","慢性淋巴细胞性白血病"],["C","慢性髓系白血病"],["D","急性髓系白血病"]],"C","青年女性患者，乏力、腹胀，消瘦1个半月（代谢亢进症状）。查体：心肺未见异常，腹软，肝肋下1cm（肝大），脾肋下7cm（脾大）。化验：Hb125g/L（正常Hb115～160g/L），WBC91.5×10⁹/L（正常WBC3.5～9.5×10⁹/L，明显升高，白血病的典型症状），分类：中幼粒细胞6%，晚幼粒细胞11%（正常外周血中几乎不会出现未成熟的白细胞），杆状核粒细胞23%（正常1%～5%，升高），分叶多核细胞33%（正常50%～70%，降低），嗜酸性粒细胞9%（正常0.5%～5%，升高），嗜碱性粒细胞4%（正常0～1%，升高），淋巴细胞14%（淋巴细胞相对计数一般是20～40%，降低），Plt412×10⁹/L（正常值125～350×10⁹/L，升高），NAP呈阴性，根据患者临床表现和体征、实验室检查结果，最可能的诊断是慢性髓系白血病（C对），该病起病缓慢，多表现为外周血粒细胞显著增多伴成熟障碍，嗜碱性粒细胞增多，伴有明显脾肿大，甚至巨脾。原发性骨髓纤维化（A错）脾大显著，血象中白细胞增多，并出现幼粒细胞等，但骨髓纤维化外周血白细胞数一般比CML少，多不超过30×10⁹/L，NAP阳性（十版内科学P586）。慢性淋巴细胞白血病（CLL）（B错）以外周血、骨髓、脾和淋巴结等淋巴组织中出现大量克隆性B淋巴细胞为特征（十版内科学P588）。急性髓系白血病（D错）可有肝脾轻、中度肿大，巨脾罕见。","c159","N"],["2021-N86",52,"第三节 慢性髓系白血病","慢性髓系白血病诊断",2021,86,"A","","女性，25岁。乏力、腹胀、消瘦1个半月。查体：心肺未见异常，腹软，肝肋下1cm，脾肋下7cm。化验血：Hb 125g/L，WBC 91.5×10⁹/L，分类：中幼粒细胞6%，晚幼粒细胞11%，杆状核粒细胞23%，分叶中性粒细胞33%，嗜酸性粒细胞9%，嗜碱性粒细胞4%，淋巴细胞14%，Plt 412×10⁹/L，NAP阴性。为明确诊断，首选的检查是",[["A","网织红细胞计数"],["B","腹部B超检查"],["C","食管钡餐造影"],["D","骨髓细胞学检查"]],"D","青年女性患者，乏力、腹胀，消瘦1个半月（代谢亢进症状）。查体：心肺未见异常，腹软，肝肋下1cm（肝大），脾肋下7cm（脾大）。化验：Hb125g/L（正常Hb115～160g/L），WBC91.5×10⁹/L（正常WBC3.5～9.5×10⁹/L，明显升高，白血病的典型症状），分类：中幼粒细胞6%，晚幼粒细胞11%（正常外周血中几乎不会出现未成熟的白细胞），杆状核粒细胞23%（正常1%～5%，升高），分叶多核细胞33%（正常50%～70%，降低），嗜酸性粒细胞9%（正常0.5%～5%，升高），嗜碱性粒细胞4%（正常0～1%，升高），淋巴细胞14%（淋巴细胞相对计数一般是20～40%，降低），Plt412×10⁹/L（正常值125～350×10⁹/L，升高），NAP呈阴性，根据患者临床表现和体征、实验室检查结果，最可能的诊断是慢性髓系白血病。为明确诊断，首选的检查是骨髓细胞学检查（D对），骨髓检查对白血病具有重要的确诊价值。网织红细胞计数（A错）主要用于骨髓造血功能的评价，增多常见于溶血性贫血、急性失血、缺铁性贫血等，减少常见于再生障碍性贫血等。腹部B超（B错）主要用于腹腔内实质性脏器的检查、腹腔积液的判断等。食管钡餐造影（C错）用于食管病变的检查，如肿瘤、静脉曲张等。","c159","N"],["2021-N87",52,"第三节 慢性髓系白血病","细胞遗传学及分子生物学检查",2021,87,"A","","女性，25岁。乏力、腹胀、消瘦1个半月。查体：心肺未见异常，腹软，肝肋下1cm，脾肋下7cm。化验血：Hb 125g/L，WBC 91.5×10⁹/L，分类：中幼粒细胞6%，晚幼粒细胞11%，杆状核粒细胞23%，分叶中性粒细胞33%，嗜酸性粒细胞9%，嗜碱性粒细胞4%，淋巴细胞14%，Plt 412×10⁹/L，NAP阴性。以下有利于进一步诊断和治疗的是",[["A","BCR-ABL融合基因"],["B","JAK2V617F基因突变"],["C","IgHV基因突变"],["D","PML-RARA融合基因"]],"A","青年女性患者，乏力、腹胀，消瘦1个半月（代谢亢进症状）。查体：心肺未见异常，腹软，肝肋下1cm（肝大），脾肋下7cm（脾大）。化验：Hb125g/L（正常Hb115～160g/L），WBC91.5×10⁹/L（正常WBC3.5～9.5×10⁹/L，明显升高，白血病的典型症状），分类：中幼粒细胞6%，晚幼粒细胞11%（正常外周血中几乎不会出现未成熟的白细胞），杆状核粒细胞23%（正常1%～5%，升高），分叶多核细胞33%（正常50%～70%，降低），嗜酸性粒细胞9%（正常0.5%～5%，升高），嗜碱性粒细胞4%（正常0～1%，升高），淋巴细胞14%（淋巴细胞相对计数一般是20～40%，降低），Plt412×10⁹/L（正常值125～350×10⁹/L，升高），NAP呈阴性，根据患者临床表现和体征、实验室检查结果，最可能的诊断是慢性髓系白血病，因此利于进一步诊断和治疗的是检测BCR-ABL融合基因（A对），CML患者骨髓及有核血细胞中存在的Ph染色体，其实质为9号染色体上C-ABL原癌基因移位至22号染色体，与22号染色体断端的断裂点簇集区（BCR）连接，形成了BCR-ABL融合基因，90%以上的患者可发现BCR-ABL融合基因。JAK2V617F基因突变（B错）主要见于真性红细胞增多症（十版内科学P605）。IgHV基因突变（C错）主要见于慢性淋巴细胞白血病（十版内科学P588）。PML-RARA融合基因（D错）主要见于急性早幼粒白血病（十版内科学P580）。","c159","N"],["2021-N88",59,"第一节 甲状腺功能亢进症","甲状腺毒症和甲亢的诊断",2021,88,"A","","女性，30岁。多食、易饥、多汗伴大便次数增多3个月，体重下降7kg。查体：皮肤湿润，弥漫性甲状腺Ⅱ度肿大。心率120次/分，律不齐，早搏3～4次/分。实验室检查：TgAb（-），TPOAb（-），TRAb（+），肝功能和血常规无异常。该患者最可能的诊断是",[["A","Graves病"],["B","结节性毒性甲状腺肿"],["C","桥本甲状腺炎"],["D","亚急性甲状腺炎"]],"A","青年女性患者，多食、易饥、多汗伴大便次数增多，体重下降（高代谢症群），查体：皮肤湿润，弥漫性甲状腺Ⅱ度肿大（Graves病的重要体征）。心率120次/分（正常心率60～100次/分，增快），律不齐，早搏3～4次/分（心律失常，Graves病的心脏体征）。实验室检查：TgAb（-），TPOAb（-），TRAb（+）（Graves确诊条件），肝功能和血常规无异常，综合患者的病史、查体结果、实验室检查，最可能的诊断是Graves病（A对），该病以甲亢、弥漫性甲状腺肿为特征。结节性甲状腺肿伴甲亢（B错），一般无GO（甲状腺相关性眼病），呈结节状肿大，甲状腺B超可以发现结节，甲状腺扫描为“热”结节，结节外甲状腺组织的摄碘功能受抑制。桥本甲状腺炎（C错）是自身免疫性甲状腺炎的经典类型，表现为甲状腺显著肿大，半数病人伴临床甲减（十版内科学P697）。亚急性甲状腺炎（D错）有前驱感染，是一种与病毒感染有关的自限性甲状腺炎，甲状腺区发生明显疼痛，可放射至耳部，吞咽时疼痛加重，可有全身不适、食欲减退、肌肉疼痛、发热、心动过速、多汗等，甲状腺毒症表现多数不明显（十版内科学P697）。","c160","N"],["2021-N89",59,"第一节 甲状腺功能亢进症","TRAb",2021,89,"A","","女性，30岁。多食、易饥、多汗伴大便次数增多3个月，体重下降7kg。查体：皮肤湿润，弥漫性甲状腺Ⅱ度肿大。心率120次/分，律不齐，早搏3～4次/分。实验室检查：TgAb（-），TPOAb（-），TRAb（+），肝功能和血常规无异常。对确诊最有价值的检查指标是",[["A","TSBAb（＋）"],["B","TgAb（-）"],["C","TPOAb（-）"],["D","TRAb（＋）"]],"D","青年女性患者，多食、易饥、多汗伴大便次数增多，体重下降（高代谢）。查体：皮肤湿润，弥漫性甲状腺Ⅱ度肿大（Graves病的重要体征）。心率120次/分（正常心率60～100次/分，增快），律不齐，早搏3~4次/分（心律失常，Graves病的心脏体征）。实验室检查：TgAb（-），TPOAb（-），TRAb（+）（Graves确诊条件），肝功能和血常规无异常。综合患者的病史、查体结果、实验室检查，最可能的诊断是Graves病，对确诊最有价值的检查指标是TRAb（＋）（D对），TRAb（TSH受体抗体）已经成为诊断GD的第一线指标，未治疗的GD患者的阳性率达到98%。TRAb包括：①甲状腺刺激性抗体（TSAb），阳性反映TRAb是刺激性的；②甲状腺刺激阻断性抗体（TSBAb），TSBAb反映TRAb是阻断性的。TRAb阳性只能证明有针对TSH受体抗体存在，不能反映其功能，而反映功能的TSAb和TSBAb因测定条件复杂，难以在临床常规应用。甲状腺过氧化物酶抗体（TPOAb）（C错）、甲状腺球蛋白抗体（TgAb）（B错）是确定原发性甲减病因和诊断自身免疫性甲状腺炎（包括桥本甲状腺炎、萎缩性甲状腺炎）的主要指标。","c160","N"],["2021-N90",59,"第一节 甲状腺功能亢进症","抗甲状腺药物",2021,90,"A","","女性，30岁。多食、易饥、多汗伴大便次数增多3个月，体重下降7kg。查体：皮肤湿润，弥漫性甲状腺Ⅱ度肿大。心率120次/分，律不齐，早搏3～4次/分。实验室检查：TgAb（-），TPOAb（-），TRAb（+），肝功能和血常规无异常。如果患者希望在一年内妊娠生育，正确的治疗方法是",[["A","对症治疗，选用美托洛尔"],["B","首选I¹³¹治疗"],["C","首选丙硫氧嘧啶治疗"],["D","首选左甲状腺素治疗"]],"C","青年女性患者，多食、易饥、多汗伴大便次数增多，体重下降（高代谢症群），查体：皮肤湿润，弥漫性甲状腺Ⅱ度肿大（Graves病的重要体征）。心率120次/分（正常心率60～100次/分，增快），律不齐，早搏3～4次/分（心律失常，Graves病的心脏体征）。实验室检查：TgAb（-），TPOAb（-），TRAb（+）（Graves确诊条件），肝功能和血常规无异常，综合患者的病史、查体结果、实验室检查，最可能的诊断是Graves病，治疗首选抗甲状腺药物，虽然ATD都可以穿过通过胎盘，但丙硫氧嘧啶有更好的水溶性，较少进入胎儿体内，故PTU致畸的危险小于MMI，如果患者希望在一年内妊娠生育，首选丙硫氧嘧啶PTU治疗（C对）。关于Graves首选ATD的选择，因有丙硫氧嘧啶的肝细胞损害原因致肝移植的报道，除了妊娠前3个月、甲状腺危象、对甲巯咪唑治疗反应小且拒绝放射碘或手术治疗的患者应考虑使用丙硫氧嘧啶外，对Graves病患者的药物治疗应选用甲巯咪唑（MMI）。同时ATD治疗期间不主张应用左甲状腺素（D错）。I¹³¹治疗（B错）的原理是破坏了部分的甲状腺，在部分国家作为Graves病的首选治疗，但因其放射性，妊娠和哺乳期妇女属于治疗禁忌症。美托洛尔（A错）属于β受体阻滞剂，在Graves病的治疗中，β受体阻滞剂可迅速阻断儿茶酚胺的作用，改善甲亢患者心悸、烦躁、多汗、手抖等交感系统兴奋症状，临床常用药物为普萘洛尔，作为辅助治疗或应用于术前准备，尤其是在较严重的甲亢或心悸等症状较严重的患者中。","c160","N"],["2021-N91",70,"第一节 干燥综合征","干燥综合征诊断标准",2021,91,"A","","女性，50岁，口干、乏力1年。加重伴夜尿增多1个月。既往体健。体查：舌面干燥，口腔颊黏膜多发小溃疡，多发龋齿，多处残留黑色牙根。血ESR84mm/h，ANA1：160阳性，抗SSA抗体阳性。最可能的诊断是",[["A","系统性红斑狼疮"],["B","多发性骨髓瘤"],["C","干燥综合征"],["D","贝赫切特病"]],"C","中年女性患者（干燥综合征高发人群），口干（口腔干燥症）、乏力1年（干燥综合征可有全身症状），症状加重伴夜尿增多1个月（累及泌尿系统），既往体健。体查：舌面干燥（口腔干燥症），口腔颊粘膜多发小溃疡（干燥综合征黏膜可出现溃疡或继发感染），多发龋齿，多处残留黑色牙根（猖獗性龋齿，特征性表现），实验室检查血ESR84mm/h（女性正常值0～20mm/h，血沉加快），ANA1：160阳性，抗SSA抗体阳性（自身抗体阳性支持干燥综合征诊断），根据患者病史、临床表现和体征及实验室检查结果，最可能的诊断是干燥综合征（C对），干燥综合征是一种以侵犯外分泌腺体为主要特征的多系统受累的弥漫性结缔组织病。系统性红斑狼疮（A错）临床表现会出现典型的蝶形红斑，抗核抗体（ANA）、抗双链脱氧核糖核酸（dsDNA）抗体、抗可溶性抗原（ENA）抗体阳性，其中抗dsDNA）抗体是诊断SLE的特异性抗体，具体诊断需参照SLE分类标准（十版内科学P823）。多发性骨髓瘤（MM）（B错）是浆细胞恶性增殖性疾病，常见临床表现为骨痛、贫血、肾功能损害、血钙增高和感染等（十版内科学P600）。贝赫切特病（BD）（D错）也称白塞病，是一种病因未明、以反复发作性口腔溃疡、外阴溃疡、眼炎及皮肤损害为临床特征的自身免疫性疾病，可累及黏膜、皮肤、关节、眼、心血管、肺、神经、肌肉等多个系统（十版内科学P842）。","c161","N"],["2021-N92",70,"第一节 干燥综合征","肾脏",2021,92,"A","","女性，50岁。口干、乏力1年。加重伴夜尿增多1个月。既往体健。体查：舌面干燥，口腔颊黏膜多发小溃疡，多发龋齿，多处残留黑色牙根。血ESR84mm/h，ANA1：160阳性，抗SSA抗体阳性。下列病变中，该病最常出现的是",[["A","肾小球病变"],["B","肾小管酸中毒"],["C","消化性多发溃疡伴出血"],["D","病理性骨折"]],"B","中年女性患者（干燥综合征高发人群），口干（口腔干燥症）、乏力1年（干燥综合征可有全身症状），症状加重伴夜尿增多1个月（累及泌尿系统），既往体健。体查：舌面干燥（口腔干燥症），口腔颊粘膜多发小溃疡（干燥综合征黏膜可出现溃疡或继发感染），多发龋齿，多处残留黑色牙根（猖獗性龋齿，特征性表现），实验室检查血ESR84mm/h（女性正常值0～20mm/h，血沉加快），ANA1：160阳性，抗SSA抗体阳性（自身抗体阳性支持干燥综合征诊断），根据患者病史、临床表现和体征及实验室检查结果，最可能的诊断是干燥综合征，该病主要累及远端肾小管，病理改变多为慢性间质性肾炎，最常出现的是肾小管酸中毒（B对），患者会因此出现低血钾性肌肉麻痹，小部分患者会出现较为明显的肾小球损害（A错）。消化性多发溃疡伴出血（C错）常见于贝赫切特病（十版内科学P843）。病理性骨折（D错）常见于多发性骨髓瘤（十版内科学P600）。","c161","N"],["2021-N128",7,"第一节 肺癌","NSCLC",2021,128,"B","","亚洲人群中容易出现EGFR基因突变，可使用口服靶向药治疗的肺癌是",[["A","肺腺癌"],["B","肺鳞状细胞癌"],["C","小细胞肺癌"],["D","大细胞肺癌"]],"A","亚洲人群中容易出现EGFR基因突变，可使用口服靶向药治疗的肺癌是肺腺癌（A对）。临床将肺癌主要分为非小细胞肺癌（NSCLC）和小细胞肺癌（SCLC）。NSCLC存在EGFR突变，不吸烟、女性、腺癌患者中比较多见，其突变率约在50%左右（BD错），而靶向药主要针对恶性肿瘤病理生理发生、发展的关键靶点进行治疗干预，一些分子靶向药物在相应的肿瘤治疗中已经表现出较佳疗效，对于EGFR突变者，可选用EGFR-酪氨酸激酶抑制剂（EGFR-TKI），治疗关键是选择特异性的标靶人群，可明显增加生存率。小细胞肺癌药物治疗中，化疗是治疗的基本方案，小细胞肺癌对化疗非常敏感（C错）。","","N"],["2021-N129",7,"第一节 肺癌","异位ACTH综合征",2021,129,"B","","容易导致Cushing综合征的最常见的肺癌是",[["A","肺腺癌"],["B","肺鳞状细胞癌"],["C","小细胞肺癌"],["D","大细胞肺癌"]],"C","在肺癌的胸外表现是指肺癌非转移性的胸外表现，即有些肺癌患者可出现一些少见的症状或体征，这些症状体征表现于胸外脏器，不是肿瘤直接作用或转移引起的，其中Cushing综合征（库欣综合征）属于内分泌综合征（异位ACTH综合征），常见于小细胞肺癌（C对）或支气管类癌，且多数为不典型的库欣综合征表现，大剂量地塞米松抑制试验阳性。肺鳞状细胞癌（B错）易导致高血钙症；大细胞肺癌（D错）易导致异位分泌促性腺激素（十版内科学P90）。有关肺腺癌（A错）的胸外表现易发类型教材未明确说明。","","N"],["2021-N130",75,"第一节 中毒概述","高铁血红蛋白血症解毒药",2021,130,"B","","亚硝酸盐中毒引起高铁血红蛋白血症的有效解毒药是",[["A","氟马西尼"],["B","亚硝酸异戊酯"],["C","二巯丙磺钠"],["D","亚甲蓝"]],"D","亚硝酸盐中毒引起高铁血红蛋白血症的有效解毒药是亚甲蓝（D对），亚甲蓝是亚硝酸盐中毒的特效解毒药。氟马西尼（A错）是苯二氮䓬类中毒的解毒药，也可用于乙醇中毒之解救。亚硝酸异戊酯（B错）是氰化物中毒解毒药。二巯丙磺钠（C错）（DMPS）用于治疗汞、砷、铜或锑等金属中毒。","","N"],["2021-N131",75,"第一节 中毒概述","中枢神经抑制剂解毒药",2021,131,"B","","苯二氮䓬类中毒的有效解毒药是",[["A","氟马西尼"],["B","亚硝酸异戊酯"],["C","二巯丙磺钠"],["D","亚甲蓝"]],"A","苯二氮䓬类中毒的有效解毒药是氟马西尼（A对），也可用于乙醇中毒之解救；氟马西尼是苯二氮䓬类拮抗剂，能通过竞争抑制苯二氮䓬类受体而阻断苯二氮䓬类药物的中枢神经系统作用。亚硝酸异戊酯（B错）是氰化物中毒解毒药。二巯丙磺钠（C错）（DMPS）用于治疗汞、砷、铜或锑等金属中毒。亚甲蓝（D错）即美蓝，是亚硝酸盐中毒的特效解毒药。","","N"],["2021-N154",3,"第一节 支气管扩张症","控制感染",2021,154,"X","","男性，30岁，反复咳黄绿色脓痰，咯血20余年，曾多次住院治疗，此次再发5天来诊。查体:双侧中下肺可闻及较多湿啰音。肺CT示右中叶、左舌叶及双下叶可见支气管壁增厚，部分呈囊腔样改变，其内可见气液平面。可以选择的经验性抗菌药物有",[["A","头孢他啶"],["B","头孢吡肟"],["C","厄他培南"],["D","环丙沙星"]],"ABD","青年男性患者，反复咳黄绿色脓痰（考虑铜绿假单胞菌感染），咯血20余年，曾多次住院治疗（多次住院史），此次再发5天来诊，体检可闻及湿啰音和干啰音（支扩常见体征），肺CT示右中叶、左舌叶及双下叶可见支气管壁增厚，部分呈囊腔样改变，其内可见气液平面（支气管扩张症典型影像学表现），根据患者病史、临床表现和体征、影像学检查结果，最可能的诊断是支气管扩张症，考虑铜绿假单胞菌感染，故可以选择的经验性抗菌药物有β-内酰胺类抗生素（如头孢他啶（A对）、头孢吡肟（B对）、哌拉西林/他唑巴坦、头孢哌酮/舒巴坦），碳青霉烯类（如亚胺培南、美罗培南），氨基糖苷类，喹诺酮类（环丙沙星（D对）或左氧氟沙星），可单独应用或联合应用。厄他培南（C错）属于广谱的碳青霉烯类抗生素，但铜绿假单胞菌、不动杆菌属等细菌对本品耐药。对于频繁急性加重或铜绿假单胞菌长期定植的患者，可试用经气道吸入妥布霉素或庆大霉素进行治疗。","","N"],["2021-N155",16,"第四节 房室交界性心律失常","心室预激",2021,155,"X","","符合房室旁路典型预激综合征的心电图特点有",[["A","P-R间期＜0.12s"],["B","QRS波群起始部分粗钝"],["C","Q-T间期延长"],["D","T波与QRS主波方向相反"]],"ABD","典型预激综合征属于显性房室旁路，解剖学基础为房室环存在直接连接心房与心室的一束纤维(Kent束），窦房结激动或心房激动可经传导很快的旁路纤维下传预先激动部分心室肌，同时经正常房室结途径下传激动其他部分心室肌，形成特殊的心电图特征，具体表现为：①PR间期缩短＜0.12秒（A对）；②QRS波增宽≥O.12秒；③QRS波群起始部分粗钝，出现预激波(δ波）（B对）；④P-J间期一般正常；⑤出现继发性ST-T改变，与QRS波群主波方向相反（D对），同时需要注意，δ波的大小、QRS波的宽度及ST-T改变的程度与预激成分的多少有关，而Q-T间期取决于QRS波的变化（δ波）与ST-T继发改变是否成比例，若是成比例的改变，则Q-T间期可正常，若是不成比例，Q-T间期则可能延长（C），临床上确存在Q-T延长的情况，但不能作为典型预激综合征的心电图特点。","","N"],["2021-N156",38,"第一节 消化道出血","上消化道出血",2021,156,"X","","引起上消化道出血的病因有",[["A","食管憩室炎"],["B","消化性溃疡"],["C","胃癌"],["D","慢性萎缩性胃炎"]],"ABC","上消化道出血在临床上最常见的病因为消化性溃疡（B对）、食管胃底静脉曲张破裂、急性糜烂性出血性胃炎和胃癌（C对），这些病因占消化道出血的80%～90%，食管憩室炎（A对）严重时会导致食管憩室内出血，发生呕血和黑便。慢性萎缩性胃炎（D错）属于胃癌前状态，镜下偶有出血及糜烂，但最新版内科学并未将其纳入上消化道出血的病因。","","N"],["2021-N157",40,"第五节 肾病综合征","肾病综合征并发症",2021,157,"X","","肾病综合征的并发症有",[["A","急性肾损伤"],["B","慢性肾衰竭"],["C","肾静脉血栓"],["D","蛋白质及脂肪代谢紊乱"]],"ACD","肾病综合征（NS）的主要临床表现及其并发症的根本原因是由于肾小球基底膜通透性的增加所致，其中感染最常见的并发症是与尿中免疫球蛋白的大量丢失、免疫功能紊乱、营养不良、激素和细胞毒药物的使用有关，同时也是疾病复发、激素抵抗的重要原因；血栓和栓塞是因多种因素如尿中丢失大量抗凝物质、高脂血症、血液浓缩等导致血液黏滞度升高，以肾静脉血栓（C对）最为常见；急性肾损伤（A对）是肾病综合征最严重的并发症，尤其是重度水肿的NS患者给予强力利尿治疗时更易发生；多种原因可导致NS患者低血浆白蛋白血症，蛋白代谢呈负平衡，致蛋白质及脂肪代谢紊乱（D对）。慢性肾衰竭（B）是多种慢性肾脏病进行性进展引起肾单位和肾功能不可逆的丧失，导致以代谢产物和毒物潴留、水电解质和酸碱平衡紊乱以及内分泌失调为特征，全身多系统、多器官受累的临床综合征，属于各种慢性肾脏病（CKD）持续进展至后期的共同结局。教材中未将慢性肾衰竭列入肾病综合征并发症的范畴，故此选项暂为争议项。","","N"],["2021-N158",50,"第一节 溶血性贫血概述","溶血性贫血实验室检查",2021,158,"X","","血管内溶血特异性的检查结果有",[["A","血浆游离血红蛋白增多"],["B","尿血红蛋白阳性"],["C","Rous试验阳性"],["D","血清非结合胆红素增多"]],"ABC","溶血可分为血管内溶血（红细胞破坏发生在血液循环中）和血管外溶血（红细胞破坏发生在单核-巨噬细胞系统中），其中血管内溶血的典型特征是血红蛋白血症（A对）和血红蛋白尿（B对），慢性血管内溶血因肾小管上皮重吸收血红蛋白代谢产物可出现含铁血黄素尿，即含铁血黄素尿试验（Rous试验）阳性（C对）。胆红素是血液循环中衰老红细胞在肝、脾及骨髓的单核－巨噬细胞系统中分解和破坏的产物，血清非结合胆红素增多（D错）只能说明红细胞破坏增多，但无法判断是红细胞被破坏的场所，故不属于血管内溶血特异性检查。","","N"],["2021-N159",60,"第二节 原发性醛固酮增多症","原发性醛固酮增多症临床表现",2021,159,"X","","能引起高血压以及低血钾的肾上腺疾病有",[["A","原发性醛固酮增多症"],["B","Addison病"],["C","Liddle综合征"],["D","嗜铬细胞瘤"]],"AD","醛固酮是肾上腺皮质球状带分泌的能够起保钠排钾作用的盐皮质激素，原发性醛固酮增多症（A对）因多种原因分泌过多醛固酮，致水钠潴留，体液容量扩增伴血压升高及肾素－血管紧张素系统受抑制，临床表现主要为高血压和低血钾等。嗜铬细胞瘤（D对）的临床表现主要是由于肿瘤阵发性或持续性释放大量儿茶酚胺于血，作用于肾上腺能受体，出现以心血管症状为主的症状和体征，其中高血压为主要的和特征性的表现，少数病例可因大量儿茶酚胺促使血钾进入细胞内及肾素和醛固酮分泌增加，排钾过多而出现低钾血症。Addison病（B错），全称原发性慢性肾上腺皮质功能减退，因肾上腺本身的病变导致的肾上腺皮质激素分泌不足和反馈性血浆ACTH水平增高，慢性可表现为血压偏低及体位性低血压、低血糖及低血钠。Liddle综合征（C错）为先天性肾小管病变（常染色体显性遗传），远曲肾小管钠重吸收显著增加，造成容量扩张而抑制肾素和醛固酮的产生，表现为低血钾、高血压及碱中毒，双侧肾上腺切除后症状无改善。官方答案选择ACD。","","N"],["2022-N41",69,"第一节 系统性红斑狼疮","系统性红斑狼疮诊断",2022,41,"A","","女性，35岁。一个月来持续发热，体温波动在37.5～38℃之间，自觉关节痛、乏力、头痛。查体：双侧面颊部可见红斑，其他无特殊阳性体征。化验：血Hb 86g/L，WBC 3.1×10⁹/L，尿蛋白（++），肝功能：ALT 92u/L，AST 104u/L，胸部X线片（-），该患者最可能的诊断是",[["A","成人Still病"],["B","结核病"],["C","系统性红斑狼疮"],["D","感染性心内膜炎"]],"C","中年育龄期女性患者（SLE高发人群），持续发热（37.5～38℃之间）一个月（中、低热度发热，SLE全身表现），有关节痛、乏力、头痛（SLE全身表现及肌肉关节表现），查体见双颊部红斑（SLE特征性皮肤黏膜表现），实验室检查血Hb86g/L（成年女性正常值115～150g/L，血红蛋白下降，SLE血液系统表现），白细胞3.1×10⁹/L（成年人正常值3.5～9.5×10⁹/L，白细胞下降，SLE血液系统表现），尿蛋白（++）（蛋白尿，SLE肾脏受累表现），肝功能：ALT92U/L（正常值5～50U/L），AST104U/L（正常值5～50U/L），提示肝功能损伤，根据患者临床表现、体征和实验室检查，该患者最可能的诊断是系统性红斑狼疮（C对），是一种病因尚未阐明的可累及全身多个系统的慢性弥漫性结缔组织病，患者血清中存在以抗核抗体为代表的多种自身抗体。该患者胸部X线片（-），暂不考虑结核病（B错）。成人Still病（A错）是一组病因不明的临床综合征，主要以高热（多为弛张热，体温高达39～40℃）、一过性皮疹、关节炎、关节痛、咽痛和白细胞计数升高为临床表现，常伴有肝、脾、淋巴结肿大（十版内科学P865）。感染性心内膜炎（D错）是由病原微生物循血行途径引起的心内膜、心瓣膜或邻近大动脉内膜的感染，并伴赘生物的形成，常见病原体为链球菌，本病主要临床表现有：全身感染（发热最常见）、心脏受累、血管损害，以及免疫反应，皮肤及其附属器和眼的五大表现为：皮肤瘀点、Osler小结、Janeway斑、Roth斑、甲下线状出血。","","N"],["2022-N42",0,"","",2022,42,"A","","下列疾病中，最常出现叹气样呼吸的是",[["A","巴比妥类中毒"],["B","脑膜脑炎"],["C","胸腔积液"],["D","神经官能症"]],"D","叹气样呼吸表现在一段正常呼吸节律中插入一次深大呼吸，并常伴有叹息声，多为功能性改变，见于神经衰弱、精神紧张或抑郁症，神经官能症（D对）的症状复杂多样，多有胸闷，呼吸不畅，患者常做深呼吸或叹息样呼吸来缓解症状。巴比妥类中毒（A错）会导致呼吸中枢的兴奋性减低，周期性呼吸节律变化，表现为潮式呼吸或间停呼吸。脑膜脑炎（B错）时呼吸中枢受到增高的颅内压和供血减少的刺激，呼吸会变得慢而深，常伴有呼吸节律的改变，如双吸气（抽泣样呼吸）、呼吸遏制（吸气突然停止）等。胸腔积液（C错）严重时可导致混合性呼吸困难，表现为吸气期及呼气期均感呼吸费力、呼吸频率增快、深度变浅，可伴有呼吸音异常或病理性呼吸音。","","N"],["2022-N43",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病肺功能检查",2022,43,"A","","肺功能检查确定持续性阻塞性通气功能障碍的标准是",[["A","吸入组胺激发后FEV₁/FVC＜0.7"],["B","吸入支气管扩张剂后FEV₁/FVC＜0.7"],["C","无需气道内用药在静息状态下测得的FEV₁/FVC＜0.7"],["D","残气量/肺总量＞35％"]],"B","肺功能检查是判断气道阻塞和气流受限的主要客观指标，对慢阻肺诊断、严重程度评价、疾病进展状况、预后及治疗反应判断等都有重要意义。FEV₁/FVC是慢阻肺的一项敏感指标，可检出轻度气流受限。吸入支气管舒张剂后FEV₁/FVC＜70%者，可确定为不能完全可逆的气道阻塞和持续气流受限（B对AC错）。残气量/肺总量在正常情况下小于或等于35%，超过40%提示肺气肿（D错）。","","N"],["2022-N44",7,"第一节 肺癌","肺癌临床分期",2022,44,"A","","对明确NSCLC分期意义不大的检查是",[["A","肿瘤标志物"],["B","胸部CT"],["C","腹部B超"],["D","胸水细胞学检查"]],"A","肺癌的组织病理学分为非小细胞肺癌和小细胞肺癌两大类，其中非小细胞肺癌（NSCLC）最为常见，约占肺癌总发病率的85%。肿瘤的分期需要考虑：原发肿瘤的大小，浸润深度，浸润范围，邻近器官受累情况，局部和远处淋巴结转移情况，远处转移等，国际上广泛采用的TNM分期中，T表示肿瘤原发灶、N代表淋巴结受累情况、M代表远处转移情况。故对明确NSCLC分期有意义的检查是胸部CT（B对）、腹部B超（C对）、胸水细胞学检查（D对），以上对原发病灶、淋巴结受累情况、远处转移情况具有重要的诊断意义。肿瘤标志物检测（A错）大多没有绝对的特异性，通常需要使用一组标记，而且同时需要有良好的阳性对照和阴性对照，才有助于组织学诊断，否则容易导致不恰当的结论，对非小细胞肺癌（NSCLC）而言，迄今尚无诊断敏感性和特异性高的肿瘤标志物。","","N"],["2022-N45",11,"第一节 胸腔积液","结核性胸膜炎",2022,45,"A","","男性，38岁，胸痛、发热3天。既往糖尿病病史5年。查体：T37.6℃，右下肺叩浊，呼吸音减低。胸片提示右侧胸腔积液。胸腔穿刺抽液化验显示胸水WBC650×10⁶/L，其中淋巴细胞90%，葡萄糖3.2mmol/L。该患者最可能的诊断是",[["A","结核性胸膜炎"],["B","恶性胸腔积液"],["C","脓胸"],["D","类肺炎性胸腔积液"]],"A","中年男性患者（结核病高发年龄），有胸痛、发热症状（结核杆菌感染常见全身症状），既往糖尿病病史5年（糖尿病患者合并肺结核的发生率显著增高），查体：T37.6℃（＞37.3℃，低热），右下肺叩浊，呼吸音减低（提示胸腔积液量较多），胸片显示右侧胸腔积液，右侧胸水穿刺提示WBC650×10⁶/L，其中淋巴细胞90%（渗出液，提示结核性胸腔积液），葡萄糖3.2mmol/L（＜3.3mmol/L，提示结核性胸腔积液），根据患者病史、临床表现、体征、影像学检查、实验室检查结果，最可能的诊断为结核性胸膜炎，是由于少量结核分枝杆菌通过淋巴、血行或胸膜下肺部结核病灶直接蔓延至胸膜，产生胸腔积液（A对）。恶性胸腔积液（B错）是由恶性肿瘤侵犯胸膜引起，胸腔积液多呈血性、量大、增长迅速，胸腔积液内葡萄糖多正常，少数也降低，结合病史、胸水脱落细胞检查、胸膜活检、纤维支气管镜检及胸腔镜直视下胸膜活检，常可做出明确诊断。脓胸（C错）时胸水WBC多达10000×10⁶/L，以中性粒细胞为主，临床常表现为高热、胸痛。类肺炎性胸腔积液（D错）是指肺炎、肺脓肿和支气管扩张等感染引起的胸腔积液，常有原发病相关临床症状，一般情况下胸腔积液量不多，胸水呈草黄色或脓性，血白细胞升高、中性粒细胞增多，伴有核左移。","","N"],["2022-N46",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎支原体肺炎治疗",2022,46,"A","","女性，28岁。乏力、咽痛、头痛、咳嗽、发热2周。查体：T37.8℃，P96次/分，R20次/分，双肺呼吸音清，未闻及干湿啰音。胸部X线检查显示双下肺多发小片状浸润影，血清支原体IgM抗体1：64阳性。阿奇霉素治疗1周后症状无好转，复查胸部X线片无变化。此时，患者应换用的抗菌药物是",[["A","青霉素"],["B","红霉素"],["C","头孢呋辛"],["D","左氧氟沙星"]],"D","青年女性患者，出现乏力，咽痛，头痛，咳嗽，发热（上呼吸道感染症状）两周，查体T37.8℃，P96次/分，R20次/分，双肺呼吸音清，未闻及干湿啰音，胸部X线显示双下肺多发小片状浸润影（肺炎常见影像学表现），血清支原体IgM抗体1：64阳性（血清支原体IgM抗体≥1：64，支原体感染诊断依据），阿奇霉素治疗一周后症状无好转（大环内酯类抗生素使用效果不佳），复查胸部X线无变化，根据患者临床表现、体征、影像学检查结果和实验室检查结果，最可能的诊断是支原体肺炎，肺炎支原体属于胞内菌，缺乏细胞壁对β-内酰胺类不敏感（AC错），对大环内酯类、四环素或喹诺酮类药物治疗有效，但近年来肺炎支原体对大环内酯类药物敏感性下降（B错），故本例患者使用阿奇霉素治疗一周后症状无好转，应更换抗菌药物，可使用喹诺酮类药物，如左氧氟沙星（D对）、莫西沙星等。","","N"],["2022-N47",19,"第二节 扩张型心肌病","扩张型心肌病超声心动图",2022,47,"A","","下列不符合扩张型心肌病并发心力衰竭的超声心动图表现是",[["A","LVEF≤40%"],["B","二尖瓣反流"],["C","左室壁节段运动减弱"],["D","左心室舒张末内径增大"]],"C","扩张型心肌病的主要病理生理学改变是心脏泵血功能的障碍，早期可通过加快心率以维持足够的心排血量，后期随着左心室排空受限，心室舒张和收缩末期容量增多、射血分数减少、心脏逐渐增大，产生相对性二尖瓣与三尖瓣关闭不全，导致充血性心力衰竭，此时，心室舒张末期压在增高，左心室尤其明显，B超可见左心室舒张末期内径扩大（D对），心室壁运动普遍受抑（C错，为本题正确答案），二尖瓣和（或）三尖瓣反流（B对），由于心肌收缩功能普遍减弱，射血分数显著降低，左心室射血分数基本上减至50%以下（十五版实用内科学 P1096）（A对），可能有少量心包积液。","","N"],["2022-N48",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞诊断",2022,48,"A","","男性，20岁。渐进性心悸、乏力、消瘦6个月，腹胀、下肢水肿2个月。查体T 37.2℃，P 106次/分，BP 90/75 mmHg，半卧位，颈静脉怒张，双肺（-），心界向两侧扩大，心律整，心音遥远，心尖部可闻及2/6级收缩期吹风样杂音，脉搏减弱，肝颈静脉回流征阳性，双下肢凹陷性水肿（+），该患者最可能的诊断是",[["A","心包积液"],["B","风湿性心瓣膜病"],["C","扩张型心肌病"],["D","病毒性心肌炎"]],"A","青年男性患者，渐进性心悸、乏力、消瘦6个月，腹胀、下肢水肿2个月（提示体循环障碍），查体T：37.2℃，P：106次/分（成年人正常心率60～100次/分，心动过速），BP：90/75mmHg（＜90/60mmHg，血压降低），半卧位，颈静脉怒张，双肺（-），心界向两侧扩大，心律整，心音遥远，心尖部可闻及2/6级收缩期吹风样杂音（可能与心脏舒张功能受限导致的乳头肌缺血有关），脉搏减弱，肝颈静脉回流征（+），双下肢凹陷性水肿（体循环淤血典型表现），本例患者有典型的低血压（BP：90/75mmHg）、心音低弱、颈静脉怒张的临床表现，即出现Beck三联征，而凡是患者出现呼吸困难、心动过速、心影增大及静脉淤血现象而未能找到通常引起心力衰竭的心脏疾病时，应考虑心包积液的可能性，因此该患者最可能的诊断是心包积液（A对），心包积液的临床表现主要取决于积液对心脏及局部组织的压迫程度，重者会出现严重的循环衰竭。除典型的呼吸困难等症状外，尚可有心前区闷胀不适、乏力、腹胀、恶心等症状。风湿性心瓣膜病（B错）在典型症状出现之前1～6周，多有咽喉炎或扁桃体炎等前驱链球菌感染表现，如发热、咽痛、颌下淋巴结肿大和咳嗽等症状，多呈急性起病，亦可为隐匿性进程。扩张型心肌病（C错）是一类以左心室或双心室扩大伴收缩功能障碍为特征的心肌病，临床表现为心脏扩大、心力衰竭、心律失常、血栓栓塞及猝死，超声检查有心腔扩大和心脏收缩功能减低的应考虑扩张型心肌病诊断。病毒性心肌炎（D错）有典型的前驱感染史，同时有心力衰竭和/或心律失常的相应症状及体征，心电图、心肌酶学检查改变，超声心动图、心脏MRI显示的心肌损伤证据，确诊有赖于心肌活检。","","N"],["2022-N49",15,"第二节 慢性心力衰竭","脑钠肽",2022,49,"A","","男性，57岁。2天前因突发胸痛，诊断急性前壁心肌梗死，行急诊PCI术，血管再通成功。为评估此时患者的心脏功能，下列最有价值的血液生化检查是",[["A","肌钙蛋白"],["B","肌酸激酶同工酶"],["C","脑钠肽"],["D","乳酸脱氢酶"]],"C","脑钠肽（BNP）主要储存于心室肌，压力负荷增加和牵拉机制激活引起利钠肽的分泌，其生理作用是扩张血管、增加排Na⁺、对抗肾上腺素、RAAS系统的水钠潴留效应，BNP是反映心脏功能的一个重要标志物（九版生理学P138），心力衰竭时循环中BNP水平升高，其增高程度与心力衰竭的严重程度呈正相关，可以作为评定心力衰竭进程和预后的指标。故行PCI术后评价患者心脏功能最有价值的血液生化指标是脑钠肽BNP（C对）。肌钙蛋白（A错）的出现和增高是反映心肌梗死时急性坏死的指标，其动态变化过程与心肌梗死时间、梗死范围大小、溶栓治疗及再灌注情况有密切关系。肌酸激酶同工酶（B错）也属于临床诊断心肌梗死的血清酶学指标。乳酸脱氢酶（D错）在心肌梗死时也升高，但乳酸脱氢酶分布于全身许多器官，对心肌梗死诊断的特异性及敏感性较差，目前临床已经不推荐应用。","","N"],["2022-N50",26,"第一节 胃食管反流病","胃食管反流病并发症",2022,50,"A","","下列属于胃食管反流病并发症的是",[["A","食管癌"],["B","Barrett食管"],["C","食管憩室炎"],["D","Mallory-Weiss综合征"]],"B","胃食管反流病的并发症：上消化道出血、食管狭窄、Barrett食管（B对）。食管癌（A错）的发生主要与亚硝胺类化合物和真菌毒素、慢性理化刺激及炎症、营养因素、遗传因素有关。食管憩室炎（C错）是食管壁的一层或全层局限性膨出，形成与食管腔相通的囊袋，按发病机制可分为内压性憩室和牵引性憩室，按部位可分为咽食管憩室、食管中段憩室和膈上憩室。Mallory-Weiss综合征（D错）即食管贲门黏膜撕裂综合征是指因各种原因导致食管内压力突然增高如剧烈频繁恶心、呕吐等，导致食管下端和胃贲门部的黏膜纵行撕裂，进而引起以上消化道出血为主的综合征。","","N"],["2022-N51",27,"第二节 慢性胃炎","Hp感染",2022,51,"A","","慢性胃窦胃炎最常见的病因是",[["A","幽门螺旋杆菌感染"],["B","十二指肠-胃反流"],["C","自身免疫"],["D","胃黏膜营养因子缺乏"]],"A","慢性胃炎基于胃炎分布可分为胃窦为主胃炎、胃体为主胃炎和全胃炎。因幽门螺杆菌在胃内分布不均匀，一般胃窦密度比胃体高，依靠其鞭毛穿过黏液层，定居于黏液层与胃窦黏膜上皮细胞表面，一般不侵入胃腺和固有层内。根据悉尼胃炎新分类系统，慢性胃窦胃炎的最常见病因为幽门螺旋杆菌感染（A对）。自身免疫（C错）为胃体萎缩为主的慢性胃炎的主要病因，该类型胃炎又称自身免疫性胃炎或A型胃炎。十二指肠-胃反流（B错）会使胆汁、胰液和肠液大量反流入胃，削弱胃黏膜的屏障功能，导致胃黏膜损伤，产生炎症、糜烂、出血和黏膜上皮化生等变化。胃黏膜营养因子缺乏（D错）或损伤可各自或与幽门螺杆菌感染协同作用损伤胃黏膜导致胃炎。","","N"],["2022-N52",35,"","",2022,52,"A","","男性，42岁。患肝硬化5年，腹痛、腹胀、发热3天，表情淡漠、嗜睡1天。对该患者意识障碍病因诊断最有意义的体征是",[["A","腹壁反射消失"],["B","膝反射亢进"],["C","扑翼样震颤"],["D","Babinski征阳性"]],"C","中年男性患者，肝硬化5年（肝性脑病发病基础），腹痛、腹胀、发热3天，表情淡漠，嗜睡1天（肝性脑病临床表现），根据患者病史及临床表现，最可能的诊断是肝性脑病2期，对该患者意识障碍病因诊断最有意义的体征是扑翼样震颤（C对），临床上患者出现扑翼样震颤的原因多为中毒性或代谢性脑病，肝硬化患者发生扑翼样震颤提示肝性脑病的发生。肝性脑病（HE）是肝功能衰竭或门体分流引起的中枢神经系统神经精神综合征，主要诊断依据为：①严重肝病和（或）广泛门体侧支循环；②精神紊乱、昏睡或昏迷；③有肝性脑病的诱因；④明显肝功能损害或血氨增高，扑翼样震颤和典型的脑电图改变有重要参考价值。腹壁反射消失（A错）、膝反射亢进（B错）、Babinski征阳性（D错）对肝性脑病患者的诊断无特异性。","","N"],["2022-N53",40,"第三节 急进性肾小球肾炎","急进性肾小球肾炎诊断",2022,53,"A","","男性，25岁。半个月前咽痛，咳嗽，1周来水肿、尿少。既往体健。血常规：Hb 98g/L，WBC 5.6×10⁹/L，Plt 150×10⁹/L。尿蛋白（++），沉渣镜检红细胞15～20个/HP，血肌酐442μmol/L，血尿素氮18mmol/L。腹部B超示双肾增大。最可能的诊断是",[["A","急性肾小球肾炎"],["B","急进性肾小球肾炎"],["C","肾病综合征"],["D","慢性肾小球肾炎"]],"B","青年男性患者，半个月前咽痛，咳嗽（前驱感染症状），水肿尿少一周（肾功能损伤表现），血Hb98g/L（血红蛋白成年男性正常值为男性130～175g/L，提示贫血），白细胞：5.6×10⁹/L（白细胞成年人正常值3.5～9.5×10⁹/L），血小板：150×10⁹/L（成年人正常值125～350×10⁹/L），尿蛋白（++），沉渣镜检红细胞15～20个/hp（＞3个/hp，镜下血尿），血肌酐442μmol/L（成年男性正常值约53～106μmol/L，提示肾损伤），血尿素氮：18mmol/L（成年人正常值3.2～7.1mmol/L，提示器质性肾功能损伤），腹部B超示双肾增大（急进性肾小球肾炎病理表现），本例患者有明确的上呼吸道感染前驱症状，随后短时间内出现快速进展型肾炎综合征，出现血尿、蛋白尿、水肿，并伴随少尿，同时实验室检查提示短时间内肾功能急剧恶化，结合影像学表现，最可能的诊断是急进性肾小球肾炎（B对），本病临床表现及发病过程与急性肾小球肾炎相似，但临床症状常常较重，早期出现少尿或无尿，肾功能持续进行性下降，需及时行肾活检明确诊断。急性肾小球肾炎（A错）临床特点为急性起病，表现为血尿、蛋白尿、水肿和高血压，可伴有一过性肾功能不全。慢性肾小球肾炎（D错）临床表现尿检异常（蛋白尿、血尿）、伴或不伴水肿及高血压病史达3个月以上，起病方式各有不同，病情迁延并呈缓慢进展，可有不同程度的肾功能损害。肾病综合征（C错）是以①大量蛋白尿（＞3.5g/d）；②低血清白蛋白血症（血清白蛋白＜30g/L)；③水肿；④高脂血症为基本特征的临床综合征，其中前两项为诊断的必备条件。","","N"],["2022-N54",56,"第二节 原发免疫性血小板减少症","原发免疫性血小板减少症诊断要点",2022,54,"A","","女性，35岁。反复皮肤紫癜1年。半年来月经量较前明显增多。查体：四肢可见出血点、紫癜，心肺检查未见异常，肝脾肋下未触及。血常规：Hb100g/L，WBC7.6×10⁹/L，Plt24×10⁹/L。骨髓检查在2cm×1.5cm片膜中见巨核细胞45个，未见产板型巨核细胞。该患者最可能的诊断是",[["A","再生障碍性贫血"],["B","原发免疫性血小板减少症"],["C","过敏性紫癜"],["D","骨髓增生异常综合征"]],"B","育龄期女性患者（ITP易发人群），反复皮肤紫癜1年（ITP常见症状体征），月经增多半年（出血倾向），查体四肢可见出血点、紫癜（出血症状和体征），血常规：Hb100g/L（成年人女性正常值115～150g/L，贫血表现），WBC7.6×10⁹/L（成人正常值3.5～9.5×10⁹/L），血小板24×10⁹/L（成年人正常值125～350×10⁹/L，明显减少），骨髓检查在2cm×1.5cm片膜上见巨核细胞45个，未见产板型巨核细胞（提示ITP），根据患者临床表现和体征、实验室检查结果最可能的诊断是原发免疫性血小板减少症（B对），是临床上最常见的出血性疾病，本病的发生是由于患者对自身血小板抗原的免疫失耐受，产生免疫介导的血小板过度破坏和血小板生成不足，导致血小板减少，该病的诊断要点为：①至少两次血小板计数减少，血细胞形态无异常；②体检脾脏一般不增大；③骨髓检查巨核细胞正常或增加，有成熟障碍；④排除其他继发性血小板减少症。再生障碍性贫血（A错）主要表现为骨髓有核细胞增生低下、全血细胞减少及所致的贫血、出血和感染。过敏性紫癜（C错）以非血小板减少性皮肤紫癜、腹痛、关节炎、肾炎为临床特征，本病缺乏特异性实验室检查。骨髓增生异常综合征（D错）多发生于中老年，临床特点是髓系细胞发育异常，表现为无效造血、难治性血细胞减少和高风险向急性髓系白血病(AML)转化，血象持续一系或多系血细胞减少，骨髓多增生活跃或明显活跃，少部分增生减低。","","N"],["2022-N55",60,"第一节 库欣综合征","库欣综合征病因诊断",2022,55,"A","","女性，32岁。发现肥胖、出现面部痤疮1年。查体可见满月脸，前臂瘀斑，腹部紫纹。实验室检查：血皮质醇和ACTH显著升高。下列对病因诊断最有价值的检查是",[["A","24小时尿游离皮质醇"],["B","血皮质醇节律变化"],["C","小剂量地塞米松抑制试验"],["D","大剂量地塞米松抑制试验"]],"D","青年女性患者，肥胖、出现面部痤疮1年（糖皮质激素长期分泌过多表现），查体可见满月脸（库欣综合征特征性表现），前臂瘀斑，腹部紫纹（蛋白质代谢障碍表现），实验室检查：血皮质醇、ACTH显著升高（库欣综合征实验室检查表现），根据患者临床表现、体征和实验室检查结果，最可能的诊断是库欣综合征，即皮质醇增多症，是一组因下丘脑－垂体－肾上腺轴调控失常，肾上腺皮质分泌过多糖皮质激素而导致的临床综合征，对病因诊断最有价值的是大剂量地塞米松抑制试验（HDDST）（D对），若该试验后皮质醇能被抑制50%以上，则可诊为垂体性库欣病，而肾上腺肿瘤、皮质癌或异位ACTH分泌综合征则多不能达到满意的抑制。小剂量地塞米松抑制试验（LDDST）（C错）为库欣综合征的定性诊断试验，目前主要用于24h皮质醇分泌均衡的患者，尤其用于鉴别假性库欣综合征，如可抑制，则为假性库欣综合征。小剂量地塞米松抑制试验（LDDST），该试验为库欣综合征的定性诊断试验，24小时尿游离皮质醇（A错）、血皮质醇节律变化（B错）、不能被小剂量地塞米松试验抑制（C错）均为库欣综合征的特征，无法明确病因。","","N"],["2022-N56",69,"第一节 系统性红斑狼疮","系统性红斑狼疮抗磷脂综合征",2022,56,"A","","不属于抗磷脂综合征的临床特征是",[["A","动脉和（或）静脉血栓形成"],["B","习惯性自发性流产"],["C","面颊部红斑"],["D","血小板减少"]],"C","抗磷脂综合征（APS）是一种伴有抗磷脂抗体中度或高度阳性的非炎症性自身免疫性疾病，其临床特征是：①血栓形成：可发生于所有大、中、小动脉和静脉；②病态妊娠：包括习惯性流产和宫内死胎，可发生于妊娠的任何阶段；③血液系统主要表现包括血小板减少、微血管性溶血，极少部分患者表现为出血，其中，血小板减少是最常见的临床表现。面颊部红斑（C错，为本题正确答案）多见于系统性红斑狼疮。","","N"],["2022-N68",18,"第一节 原发性高血压","原发性高血压诊断",2022,68,"A","","女性，25岁。宫内孕38周，1周来感心悸，平卧位明显气促，双下肢水肿来院。既往有心肌炎病史。查体：P120次/分，R18次/分，BP140/90mmHg，高枕卧位，双肺叩清，呼吸音正常，心尖搏动点位于第四肋间左锁骨中线外1.0cm，心律整，可闻及第三心音，未闻及杂音，肝脾触诊不满意，宫底位于剑突下4cm，下肢凹陷性水肿（++）。该孕妇的体检诊断，不正确的是",[["A","心动过速"],["B","高血压"],["C","心脏扩大"],["D","正常第三心音"]],"C","25岁孕晚期女性，既往有心肌炎病史，1周来感心悸，平卧位明显气促（端坐呼吸，提示左心功能不全），查体：双下肢凹陷性水肿，肝脾脏触诊不满意（考虑可能为孕晚期体征，右心功能不全待排），结合患者P120次/分（＞100次/分，提示心动过速）（A对），R18次/分（正常），BP140/90mmHg（收缩压≥140mmHg，提示高血压）。妊娠晚期孕妇血压可轻度升高，结合患者临床表现和体征，考虑诊断为高血压（B对），心功能不全。本例患者体检心尖搏动点位于第四肋间左锁骨中线外1.0cm，患者宫内孕38周，因妊娠后期增大的子宫上推膈肌，心脏向左、向上、向前移位，更贴近胸壁，心浊音界稍扩大，到妊娠末心脏容量增加约10%，不属于心脏扩大（C错，为本题正确答案），这种由于心脏位置变动引起的心脏轮廓的改变，有时难以于真正的心脏肥大鉴别，临床诊断需谨慎。同时，因心脏移位导致大血管轻度扭曲，加之血流量增加及血流速度加快，多数孕妇可闻及心尖区Ⅰ～Ⅱ级柔和吹风样收缩期杂音，80%以上孕妇有第一心音分裂及第三心音（D对）。","c168","N"],["2022-N69",18,"第一节 原发性高血压","原发性高血压诊断",2022,69,"A","","女性，25岁。宫内孕38周，1周来感心悸，平卧位明显气促，双下肢水肿来院。既往有心肌炎病史。查体：P120次/分，R18次/分，BP140/90mmHg，高枕卧位，双肺叩清，呼吸音正常，心尖搏动点位于第四肋间左锁骨中线外1.0cm，心律整，可闻及第三心音，未闻及杂音，肝脾触诊不满意，宫底位于剑突下4cm，下肢凹陷性水肿（++）。该孕妇出现第三心音最可能的原因是",[["A","心室舒张期负荷过重"],["B","心率过快"],["C","心脏扩大"],["D","心力衰竭"]],"A","第三心音产生的原因是心室急速充盈之末，心室肌纤维伸展延长，使房室瓣、腱索和乳头肌突然紧张，血流减速以及心室与胸壁接触而导致振动（B错）。正常人尤其青少年、儿童期，心尖部可有第三心音，并随呼吸而变化，坐位时消失，在运动、发热、心率增快和两腿上抬等使心室舒张期充盈加快的情况下较为明显，此种情况可无病理意义。与此同时高心排量的情况也可出现第三心音，舒张早期血液极快地充盈到扩大的心室因而引起心室壁的振动，并撞击周围组织和胸壁，或可能振动房室瓣所产生声响。因此本例患者出现第三心音的原因是因妊娠导致的心室舒张负荷重（A对）。","c168","N"],["2022-N70",11,"第二节 气胸","气胸诊断",2022,70,"A","","男性，46岁。1小时前在练习举重举起杠铃时感左侧胸痛，不敢深呼吸，随即感气短、呼吸不畅，吸气时胸痛加重，心悸，不能活动，速来院检查。既往体健。查体：R22次/分，BP130/70mmHg，一般状况好，无发绀，左肺叩诊鼓音，呼吸音减低，心律整，心音减弱。根据患者目前检查结果，最可能的诊断是",[["A","肺栓塞"],["B","气胸"],["C","急性心肌梗死"],["D","胸腔积液"]],"B","中年男性患者练习举重举起杠铃时（诱因）感左侧胸痛（气胸典型临床表现），不敢呼吸，随即感气短，呼吸不畅，吸气时胸痛加重（明显的先胸痛后呼吸困难症状），查体R22次/分（＞20次/分，呼吸增快），BP130/70mmHg（正常），左肺叩诊鼓音，呼吸音减低（气胸典型体征），根据患者临床表现及体征，最可能的诊断是气胸（B对），胸部X线检查可确诊。肺栓塞（A错）最常见的症状为呼吸困难及气促，常于活动后出现或加重，静息时可缓解或消失，胸痛可见于大多数患者，多为胸膜炎样胸痛，也可见心绞痛样胸痛，常见体征为呼吸急促，同时有发绀，肺部有时可闻及哮鸣音和（或）细湿啰音，肺野偶可闻及血管杂音。急性心肌梗死（C错）有突然胸痛、胸闷、甚至呼吸困难、休克等临床表现，但常有高血压、动脉粥样硬化、冠状动脉粥样硬化性心脏病史，体征、心电图、X线检查、血清酶学检查有助于诊断。胸腔积液（D错）的症状和体征与积液量有关，主要表现为胸痛、呼吸困难和干咳，严重可致呼吸衰竭，少量积液可无明显体征或仅因胸痛所致患侧胸部运动受限，胸式呼吸减弱，患侧可闻及胸膜摩擦音及呼吸音减弱；中等量以上胸腔积液时，患侧叩诊浊音呼吸音减弱、触觉语颤减弱；大量胸腔积液尚可伴有气管向健侧移位。","c169","N"],["2022-N71",11,"第二节 气胸","气胸体征",2022,71,"A","","男性，46岁。1小时前在练习举重举起杠铃时感左侧胸痛，不敢深呼吸，随即感气短、呼吸不畅，吸气时胸痛加重，心悸，不能活动，速来院检查。既往体健。查体：R22次/分，BP130/70mmHg，一般状况好，无发绀，左肺叩诊鼓音，呼吸音减低，心律整，心音减弱。该患者还可能出现的体征是",[["A","气管向左偏移"],["B","左胸可闻及胸膜摩擦音"],["C","左肺可闻及湿啰音"],["D","左胸语音震颤消失"]],"D","中年男性患者练习举重举起杠铃时（诱因）感左侧胸痛（气胸典型临床表现），不敢呼吸，随即感气短，呼吸不畅，吸气时胸痛加重（明显的先胸痛后呼吸困难症状），查体P22次/分（＞20次/分，呼吸增快），BP130/70mmHg（正常），左肺叩诊鼓音，呼吸音减低（气胸典型体征），根据患者临床表现及体征，最可能的诊断是左侧气胸，左侧积气影响声波传导，故可出现左侧语音共振渐弱或消失（D对），胸腔压力应将气管推向右侧（A错）。胸膜摩擦音（B错）常为胸膜炎症、纤维素渗出导致，为胸腔积液典型体征。湿啰音（C错）系由于吸气时气体通过呼吸道内的分泌物如渗出液、痰液、血液、黏液和脓液等，形成的水泡破裂所产生的声音，常出现在肺部炎症、支气管炎、肺淤血、急性肺水肿等。","c169","N"],["2022-N72",11,"第二节 气胸","气胸体征",2022,72,"A","","男性，46岁。1小时前在练习举重举起杠铃时感左侧胸痛，不敢深呼吸，随即感气短、呼吸不畅，吸气时胸痛加重，心悸，不能活动，速来院检查。既往体健。查体：R22次/分，BP130/70mmHg，一般状况好，无发绀，左肺叩诊鼓音，呼吸音减低，心律整，心音减弱。该患者不可能出现的体征是",[["A","心尖搏动消失"],["B","肺动脉瓣区第二心音增强"],["C","心界叩诊向左扩大"],["D","窦性心动过速"]],"C","中年男性患者练习举重举起杠铃时（诱因）感左侧胸痛（气胸典型临床表现），不敢呼吸，随即感气短，呼吸不畅，吸气时胸痛加重（明显的先胸痛后呼吸困难症状），查体P22次/分（＞20次/分，呼吸增快），BP130/70mmHg（正常），左肺叩诊鼓音，呼吸音减低（气胸典型体征），根据患者临床表现及体征，最可能的诊断是左侧气胸，气胸患者典型的体征为肋间隙膨隆，呼吸运动减弱，患侧（本例为左侧）叩诊鼓音，心或肝脏浊音区消失，语音震颤及呼吸音均减弱或消失，气管和纵隔向健侧移位（本例为右侧），心界叩诊向健侧扩大（C错，为本题正确答案）。同时可伴发心率增快（D对）、呼吸增快、血压下降和发绀。当左侧胸腔大量积气或积液、肺气肿时，心尖搏动减弱或消失（A对）。气胸后，胸腔压力增高，肺循环阻力增加，肺动脉压力增高，第二心音的肺动脉成分亢进，肺动脉瓣区第二心音增强（B对）。","c169","N"],["2022-N73",12,"第一节 急性呼吸窘迫综合征","急性呼吸窘迫综合征诊断",2022,73,"A","","男性，55岁。急性胰腺炎3天后出现进行性加重的呼吸困难。既往体健，吸烟史30年。查体：T37.5℃，P110次/分，R32次/分，BP130/80mmHg，口唇发绀，双肺可闻及少许湿啰音。胸片检查显示双肺多发斑片状影。该患者最可能的诊断是",[["A","医院获得性肺炎"],["B","肺不张"],["C","急性呼吸窘迫综合症"],["D","心力衰竭"]],"C","急性胰腺炎患者（胰腺炎为ARDS的常见危险因素）3天后出现进行性加重的呼吸困难（ARDS的病程特点），T37.5℃（正常体温36～37℃，低热），P110次/分（成年人正常心率60～100次/分，心率加快），R32次/分（＞20次/分，呼吸频率加快），BP130/80mmHg（血压正常），口唇发绀（低氧血症表现），双肺少许湿啰音（ARDS可见体征），胸片显示双肺多发斑片阴影（ARDS影像学表现），根据患者病史、病程特点、临床表现和体征、影像学表现，最可能的诊断是呼吸窘迫综合征（ARDS），根据ARDS的柏林定义，诊断标准为：①明确诱因下1周内出现的急性或进展性的呼吸困难；②双肺弥漫浸润；③排除心脏原因；④低氧血症。医院获得性肺炎（A错）指病人住院期间没有接受有创机械通气，未处于病原感染的潜伏期，且入院≥48小时后在医院内新发生的肺炎，胸部X线或CT显示新出现或进展性的浸润影、实变影、磨玻璃影，加上下列三个临床症状中的两个或以上，可建立临床诊断：①发热，体温＞38℃；②脓性气道分泌物；③外周血白细胞计数＞10×10⁹/L或＜4×10⁹/L。肺不张（B错）的原因包括肿瘤、炎症和结核以及某些特殊病因如血块、异物、外伤和胸腹手术后等，急性肺不张可表现为胸闷、气急、呼吸困难、干咳等，合并感染时，可引起胸痛，发绀、咳嗽、咯血、脓痰、发热、心动过速、体温升高、血压下降，有时出现休克。心力衰竭（D错）是由于各种原因的初始心肌损害（如心肌梗死、心肌炎、心肌病、血流动力负荷过重等）引起心室充盈和射血能力受损，导致心室泵血功能降低，患者主要表现为呼吸困难、疲乏和液体潴留。","c170","N"],["2022-N74",12,"第一节 急性呼吸窘迫综合征","动脉血气分析",2022,74,"A","","男性，55岁。急性胰腺炎3天后出现进行性加重的呼吸困难。既往体健，吸烟史30年。查体：T37.5℃，P110次/分，R32次/分，BP130/80mmHg，口唇发绀，双肺可闻及少许湿啰音。胸片检查显示双肺多发斑片状影。对该患者疾病诊断意义最大的检查是",[["A","痰培养"],["B","胸部CT"],["C","动脉血气分析"],["D","心脏超声"]],"C","急性胰腺炎患者（胰腺炎为ARDS的常见危险因素）3天后出现进行性加重的呼吸困难（ARDS的病程特点），T37.5℃（正常体温36～37℃，低热），P110次/分（成年人正常心率60～100次/分，心率加快），R32次/分（＞20次/分，呼吸频率加快），BP130/80mmHg（血压正常），口唇发绀（低氧血症表现），双肺少许湿啰音（ARDS可见体征），胸片显示双肺多发斑片阴影（ARDS影像学表现），根据患者病史、病程特点、临床表现和体征、影像学表现最可能的诊断是呼吸窘迫综合征（ARDS），根据ARDS的柏林定义，诊断标准为：①明确诱因下1周内出现的急性或进展性的呼吸困难；②双肺弥漫浸润；③排除心脏原因；④低氧血症，因此对该患者疾病诊断意义最大的检查为动脉血气分析（C对），根据PaO₂/FiO₂确立ARDS诊断，并将其按严重程度分为轻度、中度和重度3种（十版内科学P145）。心脏超声（D错）有助于明确心脏情况和指导治疗。痰培养（A错）在肺部感染时可用于明确感染病原体，进行痰菌培养并进行药物敏感试验，对判定病因和指导用药很有价值。肺部CT（B错）是肺部疾病的常见检查，对于发现肺内微小病变，纵隔、胸膜以及心脏后部等隐蔽区域的病变优于常规X线。","c170","N"],["2022-N75",12,"第一节 急性呼吸窘迫综合征","机械通气",2022,75,"A","","男性，55岁。急性胰腺炎3天后出现进行性加重的呼吸困难。既往体健，吸烟史30年。查体：T37.5℃，P110次/分，R32次/分，BP130/80mmHg，口唇发绀，双肺可闻及少许湿啰音。胸片检查显示双肺多发斑片状影。确诊后该患者首选的治疗是",[["A","氧疗，机械通气"],["B","强心，利尿"],["C","抗感染治疗"],["D","气管镜吸痰"]],"A","急性胰腺炎患者（胰腺炎为ARDS的常见危险因素）3天后出现进行性加重的呼吸困难（ARDS的病程特点），T37.5℃（正常体温36～37℃，低热），P110次/分（成年人正常心率60～100次/分，心率加快），R32次/分（＞20次/分，呼吸频率加快），BP130/80mmHg（血压正常），口唇发绀（低氧血症表现），双肺少许湿啰音（ARDS可见体征），胸片显示双肺多发斑片阴影（ARDS影像学表现），根据患者病史、病程特点、临床表现和体征、影像学表现最可能的诊断是呼吸窘迫综合征（ARDS），ARDS的主要治疗措施包括：积极氧疗、机械通气、治疗原发病和调节液体平衡等，确诊后首选的治疗是改善气体交换，包括吸氧、机械通气（A对），机械通气是ARDS治疗的重要措施，机械通气的关键在于可复张萎陷的肺泡并使其维持开放状态，以增加肺容积和改善氧合，同时避免肺泡过度扩张和反复开闭所造成的损伤，目前推荐采用肺保护性通气策略，主要措施包括合适水平的PEEP和小潮气量。ARDS易并发感染，也是ARDS的常见原因，因此抗感染治疗（C错）是ARDS的常规疗法，治疗上宜选用广谱抗生素。气管镜吸痰（D错）可预防呼吸机相关肺炎。为减轻肺水肿，应合理限制液体入量，以可允许的较低循环容量来维持有效循环，保持肺脏处于相对“干”的状态，在血压稳定和保证脏器组织灌注前提下，液体出入量宜轻度负平衡，可使用利尿药促进水肿的消退；强心药物如β受体激动剂在ARDS的治疗价值中尚不明确（B错）。","c170","N"],["2022-N76",17,"第四节 急性冠状综合征","不稳定型心绞痛和非ST段抬高型心肌梗死诊断",2022,76,"A","","男性，65岁。1年来快跑时感心前区闷痛，持续3～5分钟，休息即可缓解。近一个月来快步行走或上二层楼后即出现胸痛，疼痛较前加重，可持续10分钟左右，伴出汗。1天前再次发作，口含硝酸甘油可缓解，胸痛发作时可见心电图有ST-T改变，诊断为冠心病。该患者冠心病的分型是",[["A","稳定型心绞痛"],["B","不稳定型心绞痛"],["C","非ST段抬高型心肌梗死"],["D","急性ST段抬高型心肌梗死"]],"B","老年男性患者，一年来快跑时心前区闷痛，持续3～5分钟，休息后可缓解，根据临床表现最可能的诊断为稳定型心绞痛；近1个月来，胸痛的诱因阈值降低、持续时间延长，发作时伴有出汗，且一天前再次发作，口服硝酸甘油后可缓解，胸痛发作时心电图可见ST-T改变，即在相对稳定的劳力性心绞痛基础上心绞痛逐渐增强，疼痛更剧烈、时间更长或更频繁，根据患者的病史、临床表现和心电图检查结果，该患者冠心病的分型是不稳定型心绞痛（UA）（B对A错），类别为恶化型心绞痛。UA和NSTEMI的临床表现一般具有以下3个特征之一：①静息时或夜间发生心绞痛，常持续20分钟以上；②新近发生的心绞痛（病程在2个月内）且程度严重；③近期心绞痛逐渐加重（包括发作的频度、持续时间、严重程度）和疼痛放射到新的部位。发作时可有出汗、恶心、呕吐、心悸或呼吸困难等表现；而原来可以缓解心绞痛的措施此时变得无效或不完全有效。老年、女性、糖尿病患者症状可不典型。非ST段抬高型心肌梗死（C错）时心电图多数导联有持续性的ST段压低（即无ST段抬高）或伴对称性T波倒置及相应导联的R波进行性压低，且心电图改变持续12小时以上时提示该诊断。急性ST段抬高型心肌梗死（D错）临床表现为更剧烈的压榨性或窒息性的胸痛，不常有发作诱因，发作时长更久，数小时至1～2天，硝酸甘油疗效较差或无效，心电图有明显的特征性和动态性的变化，血清心肌坏死标志物有助于鉴别。","c171","N"],["2022-N77",17,"第四节 急性冠状综合征","不稳定型心绞痛和非ST段抬高型心肌梗死分级和危险分层",2022,77,"A","","男性，65岁。1年来快跑时感心前区闷痛，持续3～5分钟，休息即可缓解。近一个月来快步行走或上二层楼后即出现胸痛，疼痛较前加重，可持续10分钟左右，伴出汗。1天前再次发作，口含硝酸甘油可缓解，胸痛发作时可见心电图有ST-T改变，诊断为冠心病。根据加拿大心血管病学会（CCS）分级，该患者疾病严重度为",[["A","Ⅰ级"],["B","Ⅱ级"],["C","Ⅲ级"],["D","Ⅳ级"]],"B","老年男性患者，一年来快跑时心前区闷痛，持续3～5分钟，休息后可缓解，此时心绞痛分级为CCS分级Ⅰ级（A错），近1个月来，快步走或上二层楼后即感胸痛，疼痛较前加重，可持续10分钟，伴出汗，此时心绞痛分级为CCS分级Ⅱ级（B对），即一般体力活动轻度受限。快步、饭后、寒冷或刮风中、精神应激或醒后数小时内发作心绞痛。一般情况下平地步行200m以上或登楼一层以上受限。","c171","N"],["2022-N78",17,"第四节 急性冠状综合征","经皮冠状动脉介入术",2022,78,"A","","男性，65岁。1年来快跑时感心前区闷痛，持续3～5分钟，休息即可缓解。近一个月来快步行走或上二层楼后即出现胸痛，疼痛较前加重，可持续10分钟左右，伴出汗。1天前再次发作，口含硝酸甘油可缓解，胸痛发作时可见心电图有ST-T改变，诊断为冠心病。该患者最佳的治疗选择是",[["A","溶栓治疗"],["B","长效硝酸甘油口服"],["C","PCI术"],["D","加用β受体拮抗剂"]],"C","老年男性患者，一年来快跑时心前区闷痛，持续3～5分钟，休息后可缓解，根据临床表现最可能的诊断为稳定型心绞痛；近1个月来，胸痛的诱因阈值降低、持续时间延长，发作时伴有出汗，且一天前再次发作，口服硝酸甘油后可缓解，胸痛发作时心电图可见ST-T改变，即在相对稳定的劳力性心绞痛基础上心绞痛逐渐增强，疼痛更剧烈、时间更长或更频繁，根据患者的病史、临床表现和心电图检查结果，该患者冠心病的分型是不稳定型心绞痛（UA），类别为恶化型心绞痛。针对该患者最佳的治疗措施是血运重建治疗，即介入治疗（PCI），根据该患者的临床表现及心电图检查结果，推荐早期行介入治疗（十五版实用内科学P981），PCI创伤小、风险低、见效快，与内科药物保守疗法相比，能使患者的生活质量明显提高（活动耐量增加），随着新技术的出现，PCI不仅可以改善生活质量，而且对存在大面积心肌缺血的高危患者可明显降低其MI的发生率和死亡率。溶栓治疗（A错）为急性ST段抬高型心肌梗死的重要治疗手段，预计直接PCI大于120分钟时，首选溶栓治疗，力争10分钟之内给予病人溶栓药物。β受体拮抗剂（D错）、长效硝酸甘油口服（B错）属于改善心肌缺血、减轻症状的药物治疗，为冠心病的药物治疗。","c171","N"],["2022-N79",37,"第一节 急性胰腺炎","急性胰腺炎诊断",2022,79,"A","","男性，55岁。1天多来出现上腹痛，向腰背部放射，进行性加重，曾呕吐1次，为胃内容物，吐后腹痛未减轻，大便2次，稍稀，无脓血和里急后重感。既往有胆囊结石病史5年。查体：体温37.4℃，BP120/80mmHg，巩膜无黄染，心肺检查未见异常，腹平软，上腹轻压痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音4次/分。该患者最可能的诊断是",[["A","急性胃炎"],["B","胃溃疡"],["C","急性胰腺炎"],["D","急性心肌梗死"]],"C","中年男性患者，有胆囊结石病史（胰腺炎病因），1天来出现上腹痛，向腰背部放射（急性胰腺炎的腹痛典型表现），进行性加重，曾呕吐1次，为胃内容物，呕吐后腹痛未减轻（急性胰腺炎呕吐特点），大便2次，稍稀，无脓血和里急后重，查体，体温37.4℃（＞37.3℃，低热），血压120/80mmHg（正常），巩膜无黄染，心肺未见异常，肝脾未及，腹平软，上腹轻压痛（胰腺炎可有体征），移动性浊音阴性（暂排除腹水），肠鸣音4次/分（正常肠鸣音4～5次），根据患者病史、临床表现和体征，最可能的诊断是急性胰腺炎（C对），确诊有赖于血清淀粉酶和脂肪酶结果。急性胃炎（A错）的病因多为急性应激、化学性损伤和乙醇，临床表现主要为轻微上腹不适或隐痛，最突出的表现是上消化道出血，可以呕血和（或）黑便为首发症状，急诊胃镜检查可确诊。胃溃疡（B错）多为慢性病程，主要病因是幽门螺杆菌感染和口服非甾体抗炎药，胃溃疡多在餐后一小时内出现疼痛，1～2小时可逐渐缓解，直至下餐进食，也可伴随其他消化道症状，如反酸、嗳气、恶心、呕吐、食欲减退等，确诊主要依靠内镜检查。急性心肌梗死（D错）典型表现胸骨后压榨性疼痛，持续数小时，有心电图ST-T改变，胃肠道症状可伴有频繁的恶心、呕吐和上腹胀痛，多见于下壁心肌梗死。","c172","N"],["2022-N80",37,"第一节 急性胰腺炎","淀粉酶",2022,80,"A","","男性，55岁。1天多来出现上腹痛，向腰背部放射，进行性加重，曾呕吐1次，为胃内容物，吐后腹痛未减轻，大便2次，稍稀，无脓血和里急后重感。既往有胆囊结石病史5年。查体：体温37.4℃，BP120/80mmHg，巩膜无黄染，心肺检查未见异常，腹平软，上腹轻压痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音4次/分。对该患者确诊最有意义的检查是",[["A","血、尿淀粉酶"],["B","胃镜"],["C","腹部B超"],["D","心电图"]],"A","中年男性患者，有胆囊结石病史（胰腺炎病因），1天来出现上腹痛，向腰背部放射（急性胰腺炎的腹痛典型表现），进行性加重，曾呕吐1次，为胃内容物，呕吐后腹痛未减轻（急性胰腺炎呕吐特点），大便2次，稍稀，无脓血和里急后重，查体，体温37.4℃（＞37.3℃，低热），血压120/80mmHg（正常），巩膜无黄染，心肺未见异常，肝脾未及，腹平软，上腹轻压痛（胰腺炎可有体征），移动性浊音阴性（暂排除腹水），肠鸣音4次/分（正常肠鸣音4～5次），根据患者病史、临床表现和体征，最可能的诊断是急性胰腺炎，此时对确诊最有意义的检查是血尿淀粉酶（A对），血淀粉酶或脂肪酶＞正常值上限3倍可确诊，监测血淀粉酶准确性高，影响因素少，建议以血清淀粉酶为主，尿淀粉酶仅作为参考，需要注意的是淀粉酶水平高低与病情不呈正相关。腹部B超（C错）可用于急性胰腺炎的常规初筛，但因受肠胀气影响较大，诊断价值有限，影像学检查中CT是急性胰腺炎诊断和鉴别诊断、病情严重程度评估的重要检查。胃镜（B错）主要用于消化道炎症、溃疡等疾病的检查。心电图（D错）是心血管系统疾病检查的重要检查手段。","c172","N"],["2022-N81",37,"第一节 急性胰腺炎","禁食",2022,81,"A","","男性，55岁。1天多来出现上腹痛，向腰背部放射，进行性加重，曾呕吐1次，为胃内容物，吐后腹痛未减轻，大便2次，稍稀，无脓血和里急后重感。既往有胆囊结石病史5年。查体：体温37.4℃，BP120/80mmHg，巩膜无黄染，心肺检查未见异常，腹平软，上腹轻压痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音4次/分。对该患者的最基本治疗是",[["A","镇痛"],["B","禁食，补液"],["C","心电监护和扩冠脉治疗"],["D","抑酸药物治疗"]],"B","中年男性患者，有胆囊结石病史（胰腺炎病因），1天来出现上腹痛，向腰背部放射（急性胰腺炎的腹痛典型表现），进行性加重，曾呕吐1次，为胃内容物，呕吐后腹痛未减轻（急性胰腺炎呕吐特点），大便2次，稍稀，无脓血和里急后重，查体，体温37.4℃（＞37.3℃，低热），血压120/80mmHg（正常），巩膜无黄染，心肺未见异常，肝脾未及，腹平软，上腹轻压痛（胰腺炎可有体征），移动性浊音阴性（暂排除腹水），肠鸣音4次/分（正常肠鸣音4～5次），根据患者病史、临床表现和体征，最可能的诊断是急性胰腺炎，患者应尽快入院监护，最基本的治疗措施是禁食和补液（B对），禁食的目的是让胰腺休息，是治疗急性胰腺炎的理论基础，补液以晶体液为首选，同时要补充适量的胶体、维生素及微量元素，补充低分子右旋糖酐可预防胰腺坏死。镇痛（A错）可用于腹痛剧烈患者，药物可选择哌替啶，不推荐使用吗啡或胆碱能受体拮抗剂。抑酸药物（Ｄ错）如Ｈ₂受体拮抗剂和质子泵抑制剂主要用于消化道溃疡的治疗，在急性胰腺炎的治疗中可预防应激性溃疡的发生，多主张在重症急性胰腺炎时使用。心电监护和扩冠脉治疗（Ｃ错）主要用于急性冠脉综合征的治疗。","c172","N"],["2022-N82",41,"第一节 尿路感染","定位诊断",2022,82,"A","","女性，32岁。发热、尿频、尿急、尿痛伴腰痛3天。既往无类似病史。查体：T 38℃，BP 120/80mmHg，心肺检查未见异常，腹软，肝脾肋下未触及，双肾区有叩击痛。血常规：Hb 132g/L，WBC 11.6×10⁹/L，分类见中性粒细胞80%，Plt 130×10⁹/L。尿蛋白（+），沉渣镜检红细胞2～5个/HP，白细胞30～40个/HP，可见白细胞管型。该患者最可能的诊断是",[["A","急性尿道炎"],["B","尿道综合征"],["C","急性膀胱炎"],["D","急性肾盂肾炎"]],"D","育龄期女性患者，尿频尿急尿痛伴腰痛3天（尿道刺激征，提示泌尿系统感染，急性病程），既往无类似病史，查体：T：38℃（＞37.3℃，发热），血压：120/80mmHg（血压正常），心肺查体未见明显异常，肝脾肋下未触及，双肾区可见叩击痛（提示肾盂肾炎）。血常规：Hb：132g/L（女性正常值115～150g/L），白细胞：11.6×10⁹/L（＞9.5×10⁹/L，白细胞计数升高），中性粒细胞80%，尿蛋白（+），镜下尿沉渣镜检红细胞2～5个/HP（＞3个/HP，镜下血尿），白细胞30～40个/HP（＞5个/HP，白细胞尿），可见白细胞管型（提示肾盂肾炎），根据患者的病程、临床表现和体征、实验室检查结果，最可能的诊断是急性肾盂肾炎（D对）。急性膀胱炎（C错）除尿道刺激征外有下腹痛症状，可有耻骨上方疼痛或压痛，部分可出现排尿困难，只有少数患者出现腰痛、发热，体温一般不高于38℃，尿液常浑浊，有异味。急性尿道炎（A错）表现为发作性尿痛、脓尿，临床表现与膀胱炎相似，尿道炎常因尿道口或尿道内梗阻所致，或因邻近器官的炎症蔓延到尿道，有时可因机械或化学性刺激引起，如器械检查和留置导尿管等。尿道综合征（B错），有尿频、尿急、尿痛及排尿不适等尿路刺激症状，但多次检查均无真性菌尿。","c173","N"],["2022-N83",41,"第一节 尿路感染","肾盂肾炎",2022,83,"A","","女性，32岁。发热、尿频、尿急、尿痛伴腰痛3天。既往无类似病史。查体：T 38℃，BP 120/80mmHg，心肺检查未见异常，腹软，肝脾肋下未触及，双肾区有叩击痛。血常规：Hb 132g/L，WBC 11.6×10⁹/L，分类见中性粒细胞80%，Plt 130×10⁹/L。尿蛋白（+），沉渣镜检红细胞2～5个/HP，白细胞30～40个/HP，可见白细胞管型。不作为常用治疗的药物是",[["A","环丙沙星"],["B","阿莫西林"],["C","罗红霉素"],["D","头孢呋辛"]],"C","育龄期女性患者，尿频尿急尿痛伴腰痛3天（尿道刺激征，提示泌尿系统感染，急性病程），既往无类似病史，查体：T：38℃（＞37.3℃，发热），血压：120/80mmHg（血压正常），心肺查体未见明显异常，肝脾肋下未触及，双肾区可见叩击痛（提示肾盂肾炎）。血常规：Hb：132g/L（女性正常值115～150g/L），白细胞：11.6×10⁹/L（＞9.5×10⁹/L，白细胞计数升高），中性粒细胞80%，尿蛋白（+），镜下尿沉渣镜检红细胞2～5个/HP（＞3个/HP，镜下血尿），白细胞30～40个/HP（＞5个/HP，白细胞尿），可见白细胞管型（提示肾盂肾炎），根据患者的病程、临床表现和体征、实验室检查结果，最可能的诊断是急性肾盂肾炎，急性肾盂肾炎的致病菌80%为大肠埃希菌，因此首选药物应选择对革兰阴性杆菌有效的药物，常用药物有喹诺酮类（如氧氟沙星、环丙沙星）（A对）、半合成青霉素类（如阿莫西林）（B对）、头孢菌素类（如头孢呋辛）（D对）等。用药72小时疗效显著者继续用药，否则应按照药敏结果更改抗生素。罗红霉素（C错）为大环内酯类抗生素，大环内酯类抗菌谱较窄，第一代药物主要对大多数革兰阳性菌、厌氧球菌和包括奈瑟菌和嗜血杆菌在内的部分革兰阴性菌有强大抗菌活性，因此不作为急性肾盂肾炎的常用药物。","c173","N"],["2022-N84",41,"第一节 尿路感染","肾盂肾炎",2022,84,"A","","女性，32岁。发热、尿频、尿急、尿痛伴腰痛3天。既往无类似病史。查体：T 38℃，BP 120/80mmHg，心肺检查未见异常，腹软，肝脾肋下未触及，双肾区有叩击痛。血常规：Hb 132g/L，WBC 11.6×10⁹/L，分类见中性粒细胞80%，Plt 130×10⁹/L。尿蛋白（+），沉渣镜检红细胞2～5个/HP，白细胞30～40个/HP，可见白细胞管型。一般用药的疗程是",[["A","3～5天"],["B","6～9天"],["C","10～14天"],["D","15～19天"]],"C","育龄期女性患者，尿频尿急尿痛伴腰痛3天（尿道刺激征，提示泌尿系统感染，急性病程），既往无类似病史，查体：T：38℃（＞37.3℃，发热），血压：120/80mmHg（血压正常），心肺查体未见明显异常，肝脾肋下未触及，双肾区可见叩击痛（提示肾盂肾炎）。血常规：Hb：132g/L（女性正常值115～150g/L），白细胞：11.6×10⁹/L（＞9.5×10⁹/L，白细胞计数升高），中性粒细胞80%，尿蛋白（+），镜下尿沉渣镜检红细胞2～5个/HP（＞3个/HP，镜下血尿），白细胞30～40个/HP（＞5个/HP，白细胞尿），可见白细胞管型（提示肾盂肾炎），根据患者的病程、临床表现和体征、实验室检查结果，最可能的诊断是急性肾盂肾炎，急性肾盂肾炎的致病菌80%为大肠埃希菌，因此首选药物应选择对革兰阴性杆菌有效的药物，一般治疗的疗程为10～14天（C对）。","c173","N"],["2022-N85",52,"第二节 急性白血病","急性白血病诊断",2022,85,"A","","男性，25岁。发热、咽痛一周，皮肤出血2天。既往体健。查体：T38.1℃，双下肢和胸部可见出血点和数处瘀斑，双颈部各触及两个肿大淋巴结，最大者为3cm×1cm，均质软、无压痛，咽充血，扁桃体Ⅱ度肿大。血常规：Hb80g/L，WBC15.6×10⁹/L，分类见原始细胞30%，Plt30×10⁹/L。该患者最可能的诊断是",[["A","再生障碍性贫血"],["B","急性白血病"],["C","Evans综合征"],["D","霍奇金淋巴瘤"]],"B","青年男性患者，发热，咽痛一周，皮肤出血2天（急性白血病常见早期症状）。既往体健。查体体温38.1℃（＞37.3℃，发热），双下肢和胸部可见多处出血和数处瘀斑（骨髓造血抑制导致的出血症状），可触及2个肿大淋巴结，最大3cm×1cm，均质软，无压痛（提示非感染性），咽部充血，扁桃体Ⅱ度肿大，血常规，血红蛋白80g/L（正常男性血红蛋白130～175g/L，贫血），白细胞15.6×10⁹/L（＞9.5×10⁹/L，白细胞增高），分类见原始细胞30%（提示骨髓造血异常），血小板30×10⁹/L（＜125×10⁹/L，血小板减低），综合该患者病史、体查、实验室检查，最可能的诊断是急性白血病（AL）（B对），AL是一组起源于造血干细胞的恶性克隆性疾病，不成熟的造血细胞大批增殖并蓄积于骨髓和外周血，导致正常造血受抑，同时可浸润肝、脾、淋巴结等组织器官，临床表现为一系列浸润征象，确诊有赖于骨髓涂片检查。再生障碍性贫血（A错）为一类骨髓衰竭性疾病，以外周血血细胞减少及其相关临床表现为特征，白细胞计数＜9.5×10⁹/L。Evans综合征（C错）是自身免疫性溶血性贫血（AIHA）及免疫性血小板减少同时发生或先后发生的一种疾病，可全血细胞减少并骨髓增生减低，外周血网织红或中性粒细胞比例往往不低甚或偏高。霍奇金淋巴瘤（D错）的特点是淋巴结进行性肿大，首发症状常为无痛性颈部或锁骨上淋巴结进行性肿大，常伴有发热、盗汗、瘙痒、消瘦等全身症状。","c174","N"],["2022-N86",52,"第二节 急性白血病","骨骼和关节",2022,86,"A","","男性，25岁。发热、咽痛一周，皮肤出血2天。既往体健。查体：T38.1℃，双下肢和胸部可见出血点和数处瘀斑，双颈部各触及两个肿大淋巴结，最大者为3cm×1cm，均质软、无压痛，咽充血，扁桃体Ⅱ度肿大。血常规：Hb80g/L，WBC15.6×10⁹/L，分类见原始细胞30%，Plt30×10⁹/L。查体中应特别注意的体征是",[["A","睑结膜苍白"],["B","巩膜黄染"],["C","胸骨压痛"],["D","心脏杂音"]],"C","青年男性患者，发热，咽痛一周，皮肤出血2天（急性白血病常见早期症状）。既往体健。查体体温38.1℃（＞37.3℃，发热），双下肢和胸部可见多处出血和数处瘀斑（骨髓造血抑制导致的出血症状），可触及2个肿大淋巴结，最大3cm×1cm，均质软，无压痛（提示非感染性），咽部充血，扁桃体Ⅱ度肿大，血常规，血红蛋白80g/L（正常男性血红蛋白130～175g/L，贫血），白细胞15.6×10⁹/L（＞9.5×10⁹/L，白细胞增高），分类见原始细胞30%（提示骨髓造血异常），血小板30×10⁹/L（＜125×10⁹/L，血小板减低），综合该患者病史、体查、实验室检查，最可能的诊断是急性白血病（AL），查体时应特别注意骨骼和关节症状，AL常有胸骨下段的局部压痛（C对），提示白血病细胞浸润至骨膜、骨和关节，发生骨髓破坏时，可引起骨骼剧痛。白血病的眼部症状为眼球突出、复视或失明，因粒细胞肉瘤累及眼眶部位所致，睑结膜苍白（A错）可由于重度贫血导致，对白血病的诊断无特异性。眼球黄染（B错）是黄疸的体征，各种引起血清胆红素升高的疾病都可以引发黄疸，对白血病的诊断无特异性。心脏杂音（D错）是指除心音与额外心音外，在心脏收缩或舒张期发现的异常声音，杂音性质的判断对于心脏病的诊断具有重要的参考价值，对白血病的诊断无特异性。","c174","N"],["2022-N87",52,"第二节 急性白血病","急性白血病骨髓象",2022,87,"A","","男性，25岁。发热、咽痛一周，皮肤出血2天。既往体健。查体：T38.1℃，双下肢和胸部可见出血点和数处瘀斑，双颈部各触及两个肿大淋巴结，最大者为3cm×1cm，均质软、无压痛，咽充血，扁桃体Ⅱ度肿大。血常规：Hb80g/L，WBC15.6×10⁹/L，分类见原始细胞30%，Plt30×10⁹/L。对诊断最有意义的检查是",[["A","骨髓细胞学检查"],["B","骨髓活检"],["C","淋巴结活检"],["D","Coombs试验"]],"A","青年男性患者，发热，咽痛一周，皮肤出血2天（急性白血病常见早期症状）。既往体健。查体体温38.1℃（＞37.3℃，发热），双下肢和胸部可见多处出血和数处瘀斑（骨髓造血抑制导致的出血症状），可触及2个肿大淋巴结，最大3cm×1cm，均质软，无压痛（提示非感染性），咽部充血，扁桃体Ⅱ度肿大，血常规，血红蛋白80g/L（正常男性血红蛋白130～175g/L，贫血），白细胞15.6×10⁹/L（＞9.5×10⁹/L，白细胞增高），分类见原始细胞30%（提示骨髓造血异常），血小板30×10⁹/L（＜125×10⁹/L，血小板减低），综合该患者病史、体查、实验室检查，最可能的诊断是急性白血病（AL），对诊断最有意义的检查是骨髓细胞学检查（A对），采取骨髓穿刺术，涂片中原始细胞占全部骨髓有核细胞≥30%(FAB分型标准）或≥20%(WHO分型标准）定义为AL的诊断标准。与骨髓穿刺相比，骨髓活检（B错）在有效造血面积评估异常细胞浸润和分布以及纤维化诊断上更有优势，是在骨髓穿刺无法准确鉴别疾病所选择的检测。淋巴结活检（C错）用于确诊淋巴瘤，是淋巴瘤病理类型分类的主要依据。抗人球蛋白试验（Coombs试验）（D错）是温抗体型自身免疫性溶血性贫血最具诊断意义的实验室检查。","c174","N"],["2022-N88",59,"第一节 甲状腺功能亢进症","TRAb",2022,88,"A","","女性，25岁。易饥、多食、心悸、多汗伴大便次数增多3个月，体重下降7Kg。查体：皮肤湿润，甲状腺Ⅱ度肿大。心率120次/分，心律不整，早搏3～4次/分，双手震颤（＋）。实验室检查：血FT₃、FT₄升高，TSH降低，肝功能和血常规均正常。对患者确诊最有价值的检查结果是",[["A","TPOAb阳性"],["B","TgAb阳性"],["C","TPOAb和TgAb均阳性"],["D","TRAb阳性"]],"D","青年女性患者，食欲亢进，心悸，多汗，大便次数增多，体重下降（甲状腺功能亢进常见临床表现）。查体可见皮肤湿润，甲状腺二度肿大（Graves病常见体征）。心率120次/分（＞100次/分，心率增快），心律不整，早搏3～4次（提示心律失常，甲亢心血管系统表现），双手震颤（＋）（甲状腺功能亢进特征体征）。实验室检查：血T₃，T₄增高，TSH下降（提示甲状腺功能亢进），结合患者临床表现和体征、实验室检查结果，可诊断为Graves病，Graves病（GD）属于甲状腺激素分泌增多的自身免疫性甲状腺病，TSAb为其特征性免疫标志物，为诊断GD的第一线指标，因此对该患者诊断最有价值的检查结果是TRAb阳性（D对）。TPOAb和TgAb为非特异性指标，可提示自身免疫病因（ABC错）。","c175","N"],["2022-N89",59,"第一节 甲状腺功能亢进症","ATD副作用",2022,89,"A","","女性，25岁。易饥、多食、心悸、多汗伴大便次数增多3个月，体重下降7Kg。查体：皮肤湿润，甲状腺Ⅱ度肿大。心率120次/分，心律不整，早搏3～4次/分，双手震颤（＋）。实验室检查：血FT₃、FT₄升高，TSH降低，肝功能和血常规均正常。给予患者甲巯咪唑10mg，每日二次治疗。2周后门诊复查：近3天来感咽痛，T38.2℃，咽部稍充血，查肝功正常。外周血WBC2.1×10⁹/L，中性粒细胞0.8×10⁹/L，考虑粒细胞减少的最可能原因是",[["A","疾病本身所致粒细胞减少"],["B","急性病毒感染"],["C","甲巯咪唑引起的粒细胞减少"],["D","假性粒细胞减少"]],"C","青年女性患者，食欲亢进，心悸，多汗，大便次数增多，体重下降（甲状腺功能亢进常见临床表现）。查体可见皮肤湿润，甲状腺二度肿大（Graves病常见体征）。心率120次/分（＞100次/分，心率增快），心律不整，早搏3～4次（提示心律失常，甲亢心血管系统表现），双手震颤（＋）（甲状腺功能亢进特征体征）。实验室检查：血T₃，T₄增高，TSH下降（提示甲状腺功能亢进），结合患者临床表现和体征、实验室检查结果，可诊断为Graves病，给予患者甲巯咪唑2周后，实验室检查患者粒细胞下降，抗甲状腺药导致的粒细胞减少症多发生于用药后2～3个月内，但甲亢本身也可以引起白细胞减少，为区分是甲亢所致，还是ATD所致，必须在治疗前和治疗后定期检查白细胞总数和分数，本例患者用药前血常规正常，因此考虑患者粒细胞下降最可能的原因是甲巯咪唑引起粒细胞减少（C对AD错）。本例未给出支持病毒感染诊断的依据（B错）。","c175","N"],["2022-N90",59,"第一节 甲状腺功能亢进症","ATD副作用",2022,90,"A","","女性，25岁。易饥、多食、心悸、多汗伴大便次数增多3个月，体重下降7Kg。查体：皮肤湿润，甲状腺Ⅱ度肿大。心率120次/分，心律不整，早搏3～4次/分，双手震颤（＋）。实验室检查：血FT₃、FT₄升高，TSH降低，肝功能和血常规均正常。给予患者甲巯咪唑10mg，每日二次治疗。2周后门诊复查：近3天来感咽痛，T38.2℃，咽部稍充血，查肝功正常，外周血WBC2.1×10⁹/L，中性粒细胞0.8×10⁹/L，针对患者粒细胞减少，不合适的处理是",[["A","换用丙基硫氧嘧啶100mg，每日3次"],["B","停用甲巯咪唑"],["C","给予升白细胞药物"],["D","严密监测粒细胞变化"]],"A","青年女性患者，食欲亢进，心悸，多汗，大便次数增多，体重下降（甲状腺功能亢进常见临床表现）。查体可见皮肤湿润，甲状腺二度肿大（Graves病常见体征）。心率120次/分（＞100次/分，心率增快），心律不整，早搏3～4次（提示心律失常，甲亢心血管系统表现），双手震颤（＋）（甲状腺功能亢进特征体征）。实验室检查：血T₃，T₄增高，TSH下降（提示甲状腺功能亢进），结合患者临床表现和体征、实验室检查结果，可诊断为Graves病，给予患者甲巯咪唑2周后，实验室检查患者粒细胞下降，患者粒细胞下降最可能的原因是甲巯咪唑引起粒细胞减少，如外周血白细胞低于3×10⁹/L或中性粒细胞低于1.5×10⁹/L，应考虑停药（B对），不应换另一种抗甲状腺药，因为药物之间存在交叉反应（A错，为本题正确答案），并且使用升白细胞药物（C对），如维生素B₄、鲨肝醇、利血生等，必要时给予糖皮质激素口服，同时因甲亢本身也可以引起白细胞减少，必须在治疗前和治疗后定期检查白细胞总数和分数（D对）。","c175","N"],["2022-N91",68,"第一节 类风湿关节炎","类风湿关节炎诊断",2022,91,"A","","女性，45岁。2个月来无诱因出现双上肢关节疼痛伴晨僵，每于早晨起床后两手指关节僵硬感，持续约1个多小时后逐渐缓解，未诊治，3天来加重来诊，病后进食好，大小便正常。既往体健。查体：双侧前臂伸面对称部位各触及两个皮下结节，直径约5mm，活动，质硬，无压痛，心肺腹检查未见异常，双上肢近端指间关节、掌指关节和腕关节肿胀，有压痛，下肢不肿。该患者最可能的诊断是",[["A","类风湿关节炎"],["B","风湿热"],["C","强直性脊柱炎"],["D","系统性红斑狼疮"]],"A","中年女性患者（类风湿关节炎高发人群），2个月来无诱因出现双上肢关节疼痛伴晨僵，持续约一个多小时后逐渐缓解（类风湿关节炎典型临床表现），查体：双侧前臂伸面对称部位各触及两个皮下结节，直径约5mm，活动，质硬，无压痛（皮肤类风湿结节，为类风湿关节炎较常见的关节外表现），双上肢近端指间关节，掌指关节和腕关节肿胀，有压痛（类风湿关节炎可见关节痛与压痛，好发于腕、掌指、近端指间关节）。根据患者临床表现和体征，最可能的诊断为类风湿关节炎（A对），其临床诊断主要基于慢性关节炎的症状和体征、实验室及影像学检查，目前诊断普遍采用美国风湿病学会（ACR）1987年修订的分类标准（P810表8-3-1ACR1987年修订的RA分类标准），符合7项条目中至少4项可诊断。风湿热（B错）是一种由于咽喉部感染A组乙型溶血性链球菌后反复发作的急性或慢性全身结缔组织炎症，主要侵犯心脏和关节，其他器官如脑、皮肤浆膜、血管等均可受累，临床表现以心脏损害最为严重且多见，典型症状前多有咽喉炎或扁桃体炎感染史，关节炎特点为多发性和游走性，一般在数周内消失。强直性脊柱炎（C错）是一类原因未明，以中轴脊柱受累为主，可伴发关节外表现，严重者可发生脊柱畸形和关节强直的一种慢性炎症性疾病，多见于青壮年男性，炎性下腰背痛是强直性脊柱炎腰背痛特征。系统性红斑狼疮（D错）是一种常见的弥漫性结缔组织病，多有全身非特异炎性症状，尤以低、中度热为常见，伴有疲倦、乏力、食欲缺乏、体重下降等，有鼻梁和双颧蝶形红斑的特异性皮疹，关节痛多为对称性外周多关节肿痛、晨僵，以指、腕、膝关节最多见。","c176","N"],["2022-N92",68,"第一节 类风湿关节炎","抗瓜氨酸化蛋白抗体",2022,92,"A","","女性，45岁。2个月来无诱因出现双上肢关节疼痛伴晨僵，每于早晨起床后两手指关节僵硬感，持续约1个多小时后逐渐缓解，未诊治，3天来加重来诊，病后进食好，大小便正常。既往体健。查体：双侧前臂伸面对称部位各触及两个皮下结节，直径约5mm，活动，质硬，无压痛，心肺腹检查未见异常，双上肢近端指间关节、掌指关节和腕关节肿胀，有压痛，下肢不肿。最有诊断价值的实验室检查是",[["A","血清抗Sm抗体"],["B","红细胞沉降率"],["C","HLA-B27"],["D","血清抗CCP抗体"]],"D","中年女性患者（类风湿关节炎高发人群），2个月来无诱因出现双上肢关节疼痛伴晨僵，持续约一个多小时后逐渐缓解（类风湿关节炎典型临床表现），查体：双侧前臂伸面对称部位各触及两个皮下结节，直径约5mm，活动，质硬，无压痛（皮肤类风湿结节，为类风湿关节炎较常见的关节外表现），双上肢近端指间关节，掌指关节和腕关节肿胀，有压痛（类风湿关节炎可见关节痛与压痛，好发于腕、掌指、近端指间关节）。根据患者临床表现和体征，最可能的诊断为类风湿关节炎，最有价值的实验室检查是抗环状瓜氨酸（CCP）抗体（D对），该抗体属于抗瓜氨酸化蛋白抗体（ACPA），对RA诊断的敏感性和特异性较好，与RA关节影像学改变密切相关。红细胞沉降率（B错）是最常用的监测炎症或病情活动指标。本身无特异性，受多种因素影响，在临床上应综合分析。血清抗Sm抗体（A错）是系统性红斑狼疮的标记性抗体，其特异性99%,但敏感性仅25%。HLA-B27（C错）基因是强直性脊柱炎的易感基因，强直性脊柱炎的群体发病率与人群中HLA-B27的阳性率有关。","c176","N"],["2022-N128",17,"第四节 急性冠状综合征","P₂Y₁₂受体拮抗剂",2022,128,"B","","冠心病患者冠脉内药物支架植入后，若存在氯吡格雷抵抗，可选用的药物是",[["A","替格瑞洛"],["B","伊伐布雷定"],["C","左西孟旦"],["D","比伐卢定"]],"A","冠状动脉内药物支架植入术，即经皮冠状动脉介入治疗（PCI）的一种，术后建议终身服用小剂量阿司匹林，并联合服用血小板P₂Y₁₂受体拮抗剂，主要药物包括氯吡格雷、普拉格雷、替格瑞洛，氯吡格雷的抗血小板作用受到肝脏代谢影响，个体差异较大，药物相互作用多，因此若存在氯吡格雷抵抗，可选用替格瑞洛（A对），该药物属于新型P₂Y₁₂受体拮抗剂，疗效确切，个体差异小，临床应用日益增多，在欧美等国家已作为优先于氯吡格雷的推荐药物。比伐卢定（D错）主要用于UA/NSTEMI病人PCI术中的抗凝（十版内科学P246）。伊伐布雷定（B错）用于心力衰竭的治疗，能减慢窦性心率，对于不耐受β受体阻滞剂的患者，窦性心律且心率≥75次/分钟时可使用。左西孟旦（C错）是钙增敏药，作用于收缩蛋白，增强心肌收缩力，适用于无显著低血压或低血压倾向的急性左心衰病人（十版内科学P188）。","","N"],["2022-N129",15,"第三节 急性心力衰竭","左西孟旦",2022,129,"B","","冠心病患者并发急性左心衰竭，血压正常，可选用的药物是",[["A","替格瑞洛"],["B","伊伐布雷定"],["C","左西孟旦"],["D","比伐卢定"]],"C","左西孟旦（C对）属于钙增敏剂，是近年应用的新一代用于心力衰竭的药物，通过结合于心肌细胞上的肌钙蛋白C促进心肌收缩，还通过介导ATP敏感的钾通道而发挥血管舒张作用和轻度抑制磷酸二酯酶的效应，它的正性肌力作用独立于β肾上腺素能刺激，可用于正接受β受体阻断药治疗的患者，适用于无显著低血压或低血压倾向的急性左心衰病人。替格瑞洛（A错）用于PCI术后抗血小板治疗（十版内科学P240），比伐卢定（D错）主要用于UA/NSTEMI病人PCI术中的抗凝（P233）。伊伐布雷定（B错）用于心力衰竭的治疗，能减慢窦性心率，对于不耐受β受体阻滞剂的患者，窦性心律且心率≥75次/分钟时可使用。","","N"],["2022-N130",75,"第二节 农药中毒","轻度中毒",2022,130,"B","","轻度有机磷中毒不出现的临床表现是",[["A","出汗、流涎"],["B","腹痛、腹泻"],["C","咳嗽、气促"],["D","肌纤维颤动"]],"D","轻度有机磷中毒不会出现的临床表现是肌纤维震颤（D错，为本题正确答案），该症状出现的原因是在横纹肌神经-肌肉接头处ACh蓄积过多，属于烟碱样症状（N样症状），是中度、重度有机磷中毒会出现的临床表现。轻度有机磷中毒时仅有毒蕈碱样症状（M样症状），产生的原因主要是副交感神经末梢过度兴奋，腺体分泌增加，表现为流泪、出汗、流涎（A对）；平滑肌痉挛表现为瞳孔缩小、腹痛、腹泻（B对）；括约肌松弛表现大小便失禁；气道分泌物增多表现为咳嗽、气促（C对）、呼吸困难、双肺干性或湿性啰音，严重者发生肺水肿。","","N"],["2022-N131",75,"第二节 农药中毒","中度中毒",2022,131,"B","","中度有机磷中毒出现的烟碱样症状是",[["A","出汗、流涎"],["B","腹痛、腹泻"],["C","咳嗽、气促"],["D","肌纤维颤动"]],"D","烟碱样症状（N样症状），因横纹肌神经-肌肉接头处ACh蓄积所致，表现为面、眼、舌、四肢或全身肌纤维颤动或强直性痉挛、呼吸肌瘫痪致呼吸衰竭，心率增快、血压升高或降低，而中度有机磷中毒时，M样症状会加重，出现N样症状，表现为神清或模糊、肌纤维震颤（D对）、瞳孔缩小、流涎、腹痛、腹泻、呼吸困难等，其中出汗、流涎（A错）；腹痛、腹泻（B错）；咳嗽、气促（C错）均为有机磷中毒时出现的毒蕈碱样症状（M样症状）。","","N"],["2022-N154",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病肺功能检查",2022,154,"X","","肺功能检查可以表现为阻塞性通气功能障碍的疾病有",[["A","慢性阻塞性肺疾病"],["B","闭塞性细支气管炎"],["C","弥漫性泛细支气管炎"],["D","支气管扩张症"]],"ABCD","阻塞性通气功能障碍是由于气道阻塞所致的通气功能障碍，表现为与最大肺容积（通常为VC或FVC）相比，最大呼气流速不成比例地显著下降。FEV₁和FEV₁/FVC比值明显下降，MVV、MMEF、FEF50%也明显下降，但FVC可在正常范围或轻度下降。常见的引起阻塞性通气功能障碍的肺部疾病包括COPD（A对）、支气管哮喘、闭塞性细支气管炎（B对）、囊性纤维化、弥漫性泛细支气管炎（DPB）（C对）和上气道梗阻疾病等。","","N"],["2022-N155",19,"第一节 肥厚型心肌病","猝死预防",2022,155,"X","","下列属于肥厚型心肌病猝死风险评估的因素有",[["A","不明原因晕厥"],["B","运动时出现高血压"],["C","反复非持续性室性心动过速"],["D","左心室壁肥厚≥30mm"]],"ACD","肥厚性心肌病是青少年和运动员心源性猝死最常见的重要原因，预测高危风险的因素包括：曾经发生过心脏骤停、一级亲属中有1个或多个HCM猝死发生、左心室严重肥厚（≥30mm）（D对）、左室流出道高压力阶差、Holter检查发现反复非持续性心动过速（C对）、运动时出现低血压而不是高血压（B错）、不明原因晕厥（尤其是发生在运动时）（A对）。未植入ICD（埋藏式心律转复除颤器）的患者每1～2年需要进行风险评估。","","N"],["2022-N156",35,"第一节 肝硬化","EGVB的治疗及预防",2022,156,"X","","食管胃底静脉曲张破裂出血的一级预防措施包括",[["A","对因治疗"],["B","应用生长抑素和垂体加压素"],["C","应用非选择性β受体拮抗剂"],["D","内镜结扎治疗可用于中度食管静脉曲张"]],"ACD","食管胃底静脉曲张破裂出血患者的一级预防的主要针对已有食管胃底静脉曲张，但尚未出血者，目的为预防首次出血，曲张的食管静脉径＞5mm、范围＞1/3管腔、曲张静脉表面有红色征、ChildC级患者是出血的高危人群，一级预防包括：①对因治疗；②首选非选择性β受体拮抗剂（普萘洛尔或卡地洛尔）预防首次出血；③无效或有禁忌证者可用内镜下套扎（EVL）作为替代疗法。生长抑素、奥曲肽、特利加压素或垂体加压素等（B错）是收缩内脏血管药物，属于控制急性出血的止血措施。","","N"],["2022-N157",45,"第一节 慢性肾衰竭","营养治疗",2022,157,"X","","慢性肾衰竭患者的饮食治疗原则有",[["A","高蛋白饮食"],["B","注意补充维生素"],["C","尽可能低磷饮食"],["D","足量热量"]],"BCD","慢性肾衰竭患者的饮食治疗原则有：①低蛋白饮食是营养治疗的核心（A错）；②保证足够的热量摄入（D对）；③注意补充其他营养素，如水溶性维生素、叶酸以及钙、铁、锌等（B对）；④控制钾、磷的摄入（C对），除非禁忌症存在，推荐减少钠盐的摄入。","","N"],["2022-N158",47,"第一节 缺铁性贫血","铁代谢",2022,158,"X","","缺铁性贫血患者的铁代谢指标正确的有",[["A","血清铁降低"],["B","血清铁蛋白降低"],["C","血清总铁结合力降低"],["D","血清转铁蛋白饱和度降低"]],"ABD","缺铁性贫血时，铁代谢指标发生异常：贮铁指标（铁蛋白、含铁血黄素）减低（B对）、血清铁和转铁蛋白饱和度减低（AD对）、总铁结合力和未结合铁的转铁蛋白升高（C错）、组织缺铁、红细胞内缺铁。缺铁性贫血时，患者体内内外铁均下降，所以总铁结合能力升高。","","N"],["2022-N159",61,"第二节 糖尿病酮症酸中毒","补液",2022,159,"X","","对糖尿病酮症酸中毒患者正确的治疗措施有",[["A","早期迅速补液是治疗的关键"],["B","应用大剂量胰岛素使血糖迅速降至正常水平"],["C","早期即使血钾正常，尿量＞40mL/h，也应该补钾"],["D","严重酸中毒时应适量给予补碱治疗"]],"ACD","糖尿病酮症酸中毒（DKA）是高血糖危象之一，也是糖尿病的急性并发症之一，所引起的病理生理改变，经过及时治疗是可以逆转的，发病的最主要原因是胰岛素的严重缺乏，因此合理使用胰岛素是治疗的关键，一般采用小剂量胰岛素治疗方案，既能有效抑制酮体生成，又可以避免血糖、血钾和血浆渗透压下降过快带来的各种风险（B错）。同时，补液治疗对DKA患者十分关键，不仅能纠正失水，恢复肾灌注，还有助于降低血糖和清除酮体，补液速度应先快后慢，若无心力衰竭症状，前期应较快补充血容量，改善周围循环和肾功能（A对）。在治疗中通过补液，低钠、低氯血症一般可以纠正，但DKA患者机体失K⁺严重，血清K⁺浓度却高低不一，经过胰岛素和补液治疗后可加重缺K⁺，因此在开始胰岛素及补液治疗后，在心电监护和血钾监护下，就要开始补K⁺，补钾原则为：治疗前血钾低于正常，立刻开始补钾；血钾正常、尿量＞40ml/h，也立即开始补钾（C对）；血钾正常，尿量＜30ml/h，暂缓补钾，尿量增加后再开始补；血钾高于正常，暂缓补钾。轻至中度DKA患者经上述治疗后，酸中毒随着代谢紊乱的纠正可以得到恢复，但重度酸中毒时，需要适当的补碱治疗，补碱指征为：血pH＜7.1，HCO₃⁻＜5mmol/L。酮症酸中毒的其他治疗包括：休克、心力衰竭和心律失常的治疗、脑水肿的治疗、急性肾损伤的治疗及其他合并症和并发症的治疗。","","N"],["2023-N41",75,"第二节 农药中毒","中枢神经系统症状",2023,41,"A","","下列疾病中，最可能先出现意识障碍后发热的是",[["A","流行性乙型脑炎"],["B","中暑"],["C","有机磷农药中毒"],["D","中毒性痢疾"]],"C","一般情况下，先出现发热再出现意识障碍多见于重症感染性疾病，如于流行性乙型脑炎（A错）、斑疹伤寒、流行性脑脊髓膜炎、中毒性菌痢（D错）等。中暑（B错）根据临床表现可按顺序分为热痉挛（无明显体温升高，无神志障碍）、热衰竭（中心体温升高，无神志障碍）和热射病（高热伴神志障碍），因此也为先发热后出现意识障碍。有机磷农药可以与胆碱脂酶结合，抑制其活性，使胆碱酯酶失去分解乙酰胆碱的能力，造成乙酰胆碱在生理效应部位大量蓄积，产生胆碱能神经过度兴奋的表现，产生一系列中枢神经系统症状、毒蕈碱样（M样）和烟碱样（N样）症状，特别是中枢神经系统几乎所有功能都有胆碱能系统参与，当发生有机磷农药中毒时，中枢神经系统功能障碍，继而影响体温调节中枢导致机体发热，因此最可能性先出现意识障碍后发热的有机磷农药中毒（C对），类似的脑出血、巴比妥类药物中毒也是先发生意识障碍后发热。","","N"],["2023-N42",2,"第一节 支气管哮喘","支气管哮喘临床表现",2023,42,"A","","下列提示支气管哮喘重度急性发作的是",[["A","呼吸频率＞30次/分"],["B","日间哮喘症状＞4次/周"],["C","双肺散在呼气相哮鸣音"],["D","PEF占预计值65%"]],"A","哮喘可分为急性发作期和非急性发作期，其中急性发作期根据发作时的严重程度分为轻度、中度、重度和危重4级。支气管哮喘重度急性发作时，患者在休息时即感气短，讲话方式只能发单字表达，常有焦虑、烦躁，伴有大汗淋漓，呼吸频率＞30次/分（A对），常有三凹征，听诊可闻及肺部响亮、弥漫的哮鸣音（C错），心率增快常＞120次/分，有奇脉，使用支气管舒张剂后PEF占预计值＜60%（D错）或绝对值＜100L/min或作用时间＜2小时，PaO₂（吸空气时）＜60mmHg，PaCO₂＞45mmHg，SaO₂（吸空气时）≤90%，pH可降低。日间哮喘症状＞4次/周（B错）属于哮喘控制评估中的哮喘部分控制或未控制水平。","","N"],["2023-N43",6,"第一节 肺结核","痰涂片检查",2023,43,"A","","女性，40岁。低热、间断咯血2个月，每次3～4口，鲜红色。既往体健。查体：T37.8℃，双肺叩诊清音，呼吸音清，未闻及干湿啰音。肺CT示双上肺多发结节，内有空洞。最有助于确诊的检查结果是",[["A","PPD试验皮肤可见水疱"],["B","肺穿刺活检可见肉芽肿病变"],["C","痰涂片抗酸染色阳性"],["D","γ-干扰素释放试验阳性"]],"C","中年女性患者，低热、间断咯血2个月（肺结核常见症状），每次3～4口，鲜红色，既往体健（结核杆菌感染症状，提示肺结核），查体：T37.8℃（正常体温36℃～37℃，低热），双肺叩诊清音，呼吸音清，未闻及干湿啰音（肺结核病变范围较小时可无任何体征）。肺CT示：双上肺多发结节，内有空洞（结合症状考虑结核空洞），根据患者病史、临床表现和体征及影像学检查结果，目前最可能的诊断考虑为肺结核，此时最有助于确诊的检查结果是痰涂片抗酸染色阳性（C对），痰结核分枝杆菌检查是确诊肺结核最特异性的方法，涂片抗酸染色镜检快速简便，且在我国非结核分枝杆菌尚属少数，抗酸杆菌阳性肺结核诊断即基本成立（九版感染病学P214）。PPD试验（A错）与卡介苗存在交叉反应，即接种卡介苗的人群虽无结核感染亦可出现PPD（+）。γ-干扰素释放试验阳性（D错）对结核感染的特异性在95%以上，敏感性为70%左右，操作过程较少受到干扰，但因成本较高等原因，尚未广泛推行，多用于研究评价工作。肺穿刺活检（B错）不作为肺结核的常规确诊手段（各版本内科学及感染病学均未提及肺结核的确诊必须依赖于肺穿刺活检），纤维支气管镜活检对支气管结核的诊断和鉴别诊断具有重要价值，只有当通过痰涂片及影像学检查等检查仍无法确诊者（参考肺结核的诊断标准），可使用经支气管镜肺活检、经皮或胸腔镜活检等手段以协助诊断及鉴别诊断。","","N"],["2023-N44",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎支原体肺炎治疗",2023,44,"A","","不适于肺炎支原体肺炎治疗的抗生素是",[["A","大环内酯类"],["B","喹诺酮类"],["C","四环素类"],["D","β内酰胺类"]],"D","支原体无细胞壁，有些支原体可有多聚糖组成的生物被膜，故β内酰胺类（D错，为本题正确答案）抗生素，如青霉素、头孢菌素等作用靶点为细胞壁的抗生素对支原体不适用。目前临床对肺炎支原体感染多采用罗红霉素、克拉霉素、阿奇霉素等大环内酯类（A对）或氧氟沙星、司帕沙星、莫西沙星等喹诺酮类抗生素（B对）治疗，四环素类也用于肺炎支原体的治疗（C对），但近年来肺炎支原体对大环内酯类抗生素敏感性下降，耐药株产生需引起临床工作的重视。","","N"],["2023-N45",16,"第三节 房性心律失常","转复并维持窦性心律",2023,45,"A","","男性，72岁，高血压及心动过缓25年，三个月来阵发心悸，当地医院诊断心房颤动。服用华法林治疗，一周来出现多次黑矇，持续数秒可恢复。查体：P：42次/分，BP：135/80mmHg，心界不大，心率48次／分，心律不齐。动态心电图可见频发RR间期大于2.5秒。在继续使用华法林的基础上，应选择正确的治疗",[["A","服用胺碘酮转复心律"],["B","植入DDD型起搏器"],["C","射频消融+β受体阻滞剂"],["D","射频消融加起搏器"]],"D","老年男性患者，发生房颤三个月，服用华法林治疗后，一周来出现多次黑矇，持续数秒可恢复（提示持续性房颤），查体：P42次/分（正常心率：60～100次/分，心动过缓，提示传导阻滞），BP135/80mmHg（血压正常值为90～139mmHg/60～89mmHg，血压正常），心界不大，心律不齐，动态心电图可见频发RR间期大于2.5秒（提示Ⅲ度传导阻滞），根据患者的病史、临床表现和体征、心电图检查结果，目前患者的情况为：1.持续性房颤；2.完全性房室传导阻滞，此时在继续使用华法林的基础上，应选择的正确治疗为射频消融加起搏器治疗（D对），即治疗措施需要涵盖完全性房室传导阻滞（心动过缓）及房颤治疗。其中起搏器用于传导阻滞的治疗，DDD型起搏器是目前最常用的心脏起搏器，适用于病态窦房结综合征（SSS）和房室传导阻滞，但禁用于持续性房颤患者（B错）；射频消融为房颤的解决措施，随着临床试验的进行及导管消融经验的累积，射频消融术在持续性房颤的治疗作用值得肯定，部分医疗中心常规将导管消融用于长程持续性房颤的消融，并取得一定成功率。严重的心动过缓、Ⅱ～Ⅲ度房室传导阻滞、病态窦房结综合征为β受体阻滞剂的禁忌症（C错）。胺碘酮用于各种室上性与室性快速型心律失常，特别是有器质心脏病的患者，但会有心动过缓的不良反应，本例患者不适用（A错）。","","N"],["2023-N46",17,"第四节 急性冠状综合征","右心室心肌梗死的处理",2023,46,"A","","男性，65岁。4小时前突发胸痛，持续不缓解，外院确诊为“急性下壁、右室心肌梗死”即转入院。查体：BP82/55mmHg，神清，双肺（-），心率54次/分，心律齐，心音低钝，四肢末梢皮温正常。此时应首先采取的治疗措施是",[["A","即刻静点硝酸甘油"],["B","静脉快速输液"],["C","静点多巴胺升血压"],["D","即刻置入临时起搏器"]],"B","老年男性患者，诊断为急性下壁、右室心肌梗死，查体BP82/55mmHg（血压正常值为90～139mmHg/60～89mmHg，血压过低，提示血流动力学异常，心源性休克），神清，双肺（-）（暂无左心衰、肺水肿），心率54次/min（正常心率：60～100次/分，心动过缓），心律齐，心音低顿，四肢末梢皮温正常（提示休克），患者目前的诊断为右心梗死并发右心衰，此时应首先采取的措施为在血流动力学检测下，静脉快速输液（B对），以增高心排量和动脉压，当低血压得到纠正或PCWP（肺楔压）达15mmHg时，即可停止，如输液1～2L低血压仍未得到纠正，可以使用正性肌力药物，优选多巴胺类药物（C错）。严禁使用硝酸酯类药物和利尿剂（A错），会降低心脏前负荷，进一步加重低血压。Ⅱ～Ⅲ度房室传导阻滞伴有血流动力学障碍者，宜置入临时起搏器治疗，可在传导阻滞症状消除后撤出，本例暂不支持传导阻滞的诊断（D错）。","","N"],["2023-N47",19,"第六节 心肌炎","心肌炎鉴别诊断",2023,47,"A","","可作为鉴别急性心肌炎与扩张型心肌病的检查是",[["A","胸部X线片"],["B","血清心肌损伤标志物"],["C","血BNP"],["D","超声心动图"]],"B","急性心肌炎的X线表现可见心影扩大，心包积液时可有“烧瓶心”，扩张型心肌病的X线检查也有心影增大等相似表现（A错）。急性心肌炎时心肌损伤标志物可有心肌肌酸激酶（CK-MB）和肌钙蛋白（cTnT或cTnI增高），扩心病患者也可出现cTnI轻度升高，故不能作为鉴别检查（B）。血BNP（脑钠肽）在心衰时增高程度与疾病的严重程度正相关，是评定心衰进程和预后的指标，在扩心病时升高有助于鉴别呼吸困难的原因，急性心肌炎导致心衰时也会升高，故不能作为鉴别检查（C错）。扩张型心肌病在临床上主要以超声心动图作为诊断依据，有明确的特征性改变，对于有慢性心力衰竭的患者，超声心动图显示有心腔扩大与心脏收缩功能减低，即应考虑为扩张型心肌病，而急性心肌炎的超声心动图检查表现可正常，也可有左心室增大，室壁运动减低，左心室收缩功能减低，附壁血栓形成等表现，但不具有特异性，不能作为诊断标准。二者区别明显，故可作为鉴别急性心肌炎与扩张型心肌病的检查是超声心动图（D对），本题存在争议，参考答案为B。","","N"],["2023-N48",18,"第一节 原发性高血压","推荐项目",2023,48,"A","","24小时动态血压检查诊断高血压的标准值（白天与夜间的平均血压）是",[["A","白天≥140/90mmHg和（或）夜间≥130/90mmHg"],["B","白天≥140/80mmHg和（或）夜间≥130/80mmHg"],["C","白天≥135/85mmHg和（或）夜间≥120/70mmHg"],["D","白天≥130/80mmHg和（或）夜间≥120/80mmHg"]],"C","24小时动态血压检查诊断高血压的标准值（白天与夜间的平均血压）是白天≥135/85mmHg和（或）夜间≥120/70mmHg（C对）。相应的，目前认为动态血压的正常参考范围为：24小时平均血压＜130/80mmHg，白天血压均值＜135/85mmHg，夜间血压均值＜120/70mmHg。","","N"],["2023-N49",26,"第一节 胃食管反流病","PPI",2023,49,"A","","女性，38岁。反复反酸、烧心5年，平卧位时更明显，1个月来加重，影响睡眠。首选的治疗药物是",[["A","硫糖铝"],["B","奥美拉唑"],["C","法莫替丁"],["D","多潘立酮"]],"B","中年女性患者，反复反酸烧心5年，平卧位时更明显，一个月来加重，影响睡眠（胃食管反流病典型表现），根据患者病史及临床表现，最可能的诊断为胃食管反流病，抑酸为治疗要点，首选药物为PPI，如奥美拉唑（B对）等，PPI为强力抑酸药，可产生显著持久的抑酸效果，缓解症状快。法莫替丁（C错）属于H₂受体拮抗剂，对夜间胃酸分泌抑制明显，但抑酸效果较PPI弱，且长期服用会产生药物耐受，增加剂量的同时也会增加不良反应，不作为首选。多潘立酮（D错）属于促动力药物，一般不作为单独使用，效果较差，当PPI疗效不佳时，可联合促动力药物。硫糖铝（A错）为胃黏膜保护剂，属于胃溃疡或急性胃炎的治疗药物，不用于胃食管反流病的治疗。","","N"],["2023-N50",35,"第一节 肝硬化","EGVB及门静脉高压性胃肠病",2023,50,"A","","对诊断门脉高压性腹水最有价值的检查是",[["A","腹水ADA"],["B","腹水LDH"],["C","腹水白细胞"],["D","血清腹腔积液清蛋白梯度"]],"D","对门脉高压型腹水最有价值的诊断是血清腹腔积液清蛋白梯度（SAAG）（D对），当SAAG≥11g/L时，提示腹水为肝硬化门脉高压所致。当SAAG＜11g/L时，与门静脉高压无关，可与腹膜转移癌、无肝硬化的结核性腹膜炎有关。腹水ADA（A错）主要用于结核性积液与其他积液的鉴别，以及观察结核治疗的效果（抗结核治疗有效时，ADA活性降低）。腹水LDH（B错）在漏出液中时活性与正常血清相似，在渗出液中时活性常明显增高，增高程度依次为化脓性感染积液＞癌性积液＞结核性积液。腹水白细胞（C错）数量的升高对腹腔积液的性质有一定的辅助诊断意义，淋巴细胞升高多见于结核性、恶性腹腔积液，中性粒细胞升高多见于化脓性腹腔积液。","","N"],["2023-N51",37,"第一节 急性胰腺炎","淀粉酶",2023,51,"A","","女性，64岁。饱餐后上腹痛伴恶心、呕吐4小时，吐后腹痛持续不缓解并向腰背部放射。既往高血压病史。下列检查对诊断最有价值的是",[["A","血常规"],["B","心电图"],["C","血清淀粉酶"],["D","急诊胃镜"]],"C","老年女性患者，餐后上腹痛伴有恶心、呕吐，呕吐后症状不缓解并向腰背部放射（急性胰腺炎典型临床表现），根据患者临床表现和体征，最可能的诊断是急性胰腺炎，对诊断最有意义的检查是血清淀粉酶（C对），淀粉酶是诊断急性胰腺炎最常用的指标，血淀粉酶准确性高，影响因素少，临床诊断胰腺炎建议以血淀粉酶为主，血清淀粉酶于起病后2～12小时开始升高，48小时开始下降，持续3～5天。血常规（A错）白细胞增加，中性粒细胞核左移，血清钙下降，与临床严重程度平行。心电图（B错）多用于心律失常及心肌梗死的诊断。胃镜对胃溃疡、出血、炎症、肿瘤等的各种病变有诊断意义，急诊胃镜（D错）对急性上消化道出血原因及部位的诊断起确诊作用。","","N"],["2023-N52",41,"第一节 尿路感染","感染途径",2023,52,"A","","急性肾盂肾炎最常见的感染途径是",[["A","上行性"],["B","血行性"],["C","淋巴道"],["D","直接感染"]],"A","急性肾盂肾炎最常见的感染途径是上行性（A对）感染，约占尿路感染的95%；血行性（B错）感染较少见，占尿路感染的不足2%；尿路感染偶可见直接感染（D错），由病原菌直接侵入泌尿系统；淋巴道（C错）感染罕见。","","N"],["2023-N53",52,"第二节 急性白血病","口腔和皮肤",2023,53,"A","","男性，25岁。发热伴皮肤瘀斑1周。查体：T38.5℃，贫血貌，皮肤可见数处瘀斑，胸骨压痛（+）。血常规：Hb75g/L，WBC16.2×10⁹/L，Plt25×10⁹/L；骨髓细胞学检查见原始细胞87%，原始细胞的MPO弱阳性，NSE阳性，NaF可抑制。该患者最可能有的特异性临床表现是",[["A","浅表淋巴结肿大"],["B","脾大"],["C","睾丸无痛性肿大"],["D","牙龈增生、肿胀"]],"D","青年男性患者，发热伴皮肤瘀斑1周（急性白血病常见表现），查体T：38.5℃（正常体温：36.0～37.0℃，发热），贫血貌，皮肤可见数处瘀斑，胸骨压痛（+）（急性白血病骨骼常见表现）。血常规：Hb75g/L（成年男性正常值130～175g/L，中度贫血），WBC16.2×10⁹/L（成人正常值3.5～9.5×10⁹/L，白细胞增多），Plt25×10⁹/L（正常值125～350×10⁹/L血小板减少），骨髓细胞学检查见原始细胞87%（＞30%，提示急性白血病），原始细胞的MPO弱阳性，NSE阳性，NaF可抑制（提示急性单核细胞白血病），根据患者临床表现和体征，实验室检查结果，最可能的诊断是急性单核细胞白血病（M₅），此时最可能的临床表现是牙龈增生肿胀（D对），是白细胞浸润牙龈导致的，多见于M₄和M₅。浅表淋巴结肿大（A错）以急性淋巴细胞白血病多见（ALL）；各种类型白血病均可表现为脾大（B错），多为轻至中度，慢性髓系白血病可表现为巨脾；睾丸无痛性肿大（C错）多见于ALL化疗缓解后的幼儿和青年，是除中枢神经系统白血病外又一重要的髓外复发的部位。","","N"],["2023-N54",60,"第一节 库欣综合征","库欣综合征病因诊断",2023,54,"A","","对于Cushing综合征的病因诊断，除测定血ACTH外，最有提示价值的检查项目是",[["A","24小时尿游离皮质醇"],["B","血皮质醇节律变化"],["C","大剂量地塞米松抑制试验"],["D","小剂量地塞米松抑制试验"]],"C","Cushing综合征/库欣综合征，即皮质醇增多症，诊断应在病史和临床表现的基础上进行相应的实验室检查，其中24小时尿游离皮质醇（A错）、血皮质醇节律变化（B错）均有助于库欣综合征的诊断，小剂量地塞米松抑制试验（LDDST）（D错）是库欣综合征的定性诊断试验，大剂量地塞米松抑制试验（HDDST）为库欣综合征的病因诊断试验，试验结果解读如下：如皮质醇多数能被抑制、少数不能被抑制，则为垂体性库欣病；不能被抑制为肾上腺肿瘤、皮质癌；不能被抑制、少数可被抑制为异位ACTH综合征，故对于Cushing综合征的病因诊断，除测定ACTH外，最有提示价值的检查项目是大剂量地塞米松抑制试验（C对）。","","N"],["2023-N55",67,"第一节 风湿系统疾病总论","风湿性疾病范畴和分类",2023,55,"A","","下列风湿性疾病中，分类属于脊柱关节炎的是",[["A","银屑病关节炎"],["B","骨关节炎"],["C","风湿性关节炎"],["D","类风湿关节炎"]],"A","风湿性疾病中脊柱关节炎包括强直性脊柱炎、反应性关节炎、肠病性关节炎、银屑病关节炎（A对）、未分化脊柱关节病等。骨关节炎（B错）属于退行性变；风湿性关节炎（C错）即风湿热的关节表现，属于感染相关风湿病。类风湿关节炎（D错）属于弥漫性结缔组织病。","","N"],["2023-N56",73,"","",2023,56,"A","","女性，26岁。左下肢肿胀、疼痛1个月。曾多次流产。血常规：Hb115g/L，WBC7.2×10⁹/L，Plt45×10⁹/L。为明确诊断，最重要的检查是",[["A","血抗核抗体"],["B","血抗磷脂抗体"],["C","血类风湿因子"],["D","骨髓细胞学检查"]],"B","育龄期女性患者（抗磷脂综合征好发人群），左下肢肿胀，疼痛1个月（提示下肢血栓形成），曾多次流产（符合抗磷脂综合征典型表现），血常规：Hb115g/L（女性正常值：115～150g/L），WBC7.2×10⁹/L（成人正常值：3.5～9.5×10⁹/L），Plt45×10⁹/L（血小板计数正常值125～350×10⁹/L，血小板减少），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是抗磷脂综合征，抗磷脂综合征（APS）是一种以反复血管性血栓事件、自发性流产、血小板减少等为主要临床表现，伴有抗磷脂抗体中度或高度阳性的非炎症性自身免疫性疾病，本例为明确诊断，最重要的检查是血抗磷脂抗体（B对），抗磷脂抗体是APS发生的决定性因素，也是抗磷脂综合征诊断的实验室标准之一。血抗核抗体（A错）主要用于系统性红斑狼疮的诊断。血类风湿因子（C错）无特异性，不仅见于类风湿关节炎，还可见于干燥综合征、系统性红斑狼疮、混合性结缔组织病、系统性硬化症等多种风湿免疫性疾病，也可见于部分慢性感染。骨髓细胞学检查（D错）是诊断造血系统疾病最常用的基本方法，如各种类型白血病、多发性骨髓瘤、巨幼细胞贫血等疾病。","","N"],["2023-N68",11,"第一节 胸腔积液","结核性胸膜炎",2023,68,"A","","男性，32岁。因发热、盗汗、咳嗽伴右胸痛2周，气短不能平卧3天来诊。既往有肺结核病史。查体：T37.8℃，P96次/分，R20次/分，BP110/70mmHg。气管向左偏斜，右中下肺叩诊浊音，呼吸音消失，双肺未闻及干湿啰音，心律齐，心音正常，肝脾肋下未触及，双下肢无水肿。最可能的诊断是",[["A","右下肺炎"],["B","右侧胸膜肥厚"],["C","肺栓塞"],["D","右侧胸腔积液"]],"D","青年男性患者，既往有结核病病史，发热、盗汗、咳嗽，伴右胸痛2周，气促不能平卧3天（提示结核性胸腔积液），查体：T37.8℃（正常值：36.0～37.0℃，发热），P96次/分（正常值：60～100次/分），R20次（正常值：12～20次/分钟，呼吸平稳），BP110/70mmHg（血压正常值为90～139mmHg/60～89mmHg，血压正常），气管向左偏斜，右中下肺叩诊浊音，呼吸音消失（提示胸腔积液，暂不考虑肺炎），双肺未闻及干湿啰音（暂不考虑肺炎），心律齐，心音正常，肝脾肋下未触及，双下肢无水肿，根据患者的病史、临床表现和体征，最可能的诊断是右侧胸腔积液（D对），积液性质为结核性。胸膜肥厚（B错）叩诊呈浊音，听诊呼吸音减弱，往往伴有胸廓扁平或塌陷，肋间隙变窄，气管向患侧移位，语音传导减弱等体征，多见于慢性脓胸。肺炎（A错）在临床上通常以发热、寒战、胸痛、咳嗽和咳脓痰为其特征，不同病原体导致的肺炎在临床上具有一定的特点。肺栓塞（C错）临床表现为突发起病，呼吸困难，胸痛，烦躁不安，惊恐甚或濒死感，可有咯血、低热和晕厥，多有下肢或盆腔血栓性静脉炎、骨折、手术后、脑卒中、心房颤动等病史，或发生于长期卧床的老年病人。","c182","N"],["2023-N69",11,"第一节 胸腔积液","胸腔积液超声检查",2023,69,"A","","男性，32岁。因发热、盗汗、咳嗽伴右胸痛2周，气短不能平卧3天来诊。既往有肺结核病史。查体：T37.8℃，P96次/分，R20次/分，BP110/70mmHg。气管向左偏斜，右中下肺叩诊浊音，呼吸音消失，双肺未闻及干湿啰音，心律齐，心音正常，肝脾肋下未触及，双下肢无水肿。为尽快缓解该患者症状，制定下一步诊治方案，应首选的检查是",[["A","胸部B超"],["B","心电图"],["C","胸部CT"],["D","CTPA"]],"A","青年男性患者，既往有结核病病史，发热、盗汗、咳嗽，伴右胸痛2周，气促不能平卧3天（提示结核性胸腔积液），查体：T37.8℃（正常值：36.0～37.0℃，发热），P96次/分（正常值：60～100次/分），R20次（正常值：12～20次/分钟，呼吸平稳），BP110/70mmHg（血压正常值为90～139mmHg/60～89mmHg，血压正常），气管向左偏斜，右中下肺叩诊浊音，呼吸音消失（提示胸腔积液，暂不考虑肺炎），双肺未闻及干湿啰音（暂不考虑肺炎），心律齐，心音正常，肝脾肋下未触及，双下肢无水肿，根据患者的病史、临床表现和体征，最可能的诊断是右侧胸腔积液，积液性质为结核性，为尽快缓解患者症状，制定下一步诊治方案，应首选的检查是胸部B超（A对），对确定有无胸腔积液以及积液量、部位、胸腔穿刺的定位均有重要价值，超声引导下胸腔穿刺可用于局限性胸腔积液或粘连分隔胸腔积液。胸部CT（C错）对胸腔积液诊断的重要意义在于鉴别支气管肺癌的胸膜侵犯或广泛转移，良性或恶性胸膜增厚，对恶性胸腔积液的病因诊断、肺癌分期与选择治疗方案至关重要，本例患者为结核性胸腔积液，故不作为诊疗方案的首选检查。CT肺动脉造影/CTPA（D错）是肺动脉栓塞的一线确诊手段。心电图（B错）主要用于心律失常和心肌缺血、损伤的诊断。","c182","N"],["2023-N70",35,"","",2023,70,"A","","男性，45岁。因4个月来乏力、食欲下降伴腹胀、尿少，1个月来低热、活动后气短、腹胀明显加重来诊。既往有肝炎病史。查体：T37.5℃，P98次/分，R18次/分，BP104/72mmHg。半卧位，上胸部可见蜘蛛痣，巩膜轻度黄染，心肺（-），全腹有压痛及反跳痛，肝脾触诊不满意，移动性浊音（+），双下肢可凹性水肿（+）。化验：血Hb106g/L，WBC7.4×10⁹/L，N0.88，Plt70×10⁹/L，尿胆红素（+），血ALT110U/L，AST130U/L，T-Bil98μmol/L，D-Bil65μmol/L。应首先考虑的诊断是",[["A","肝硬化并发自发性细菌性腹膜炎"],["B","肝硬化并发门静脉血栓"],["C","肝硬化并发结核性腹膜炎"],["D","肝硬化并发肝癌"]],"A","中年男性患者（肝硬化高发人群），乏力，食欲下降伴腹胀，尿少4个月（肝硬化可有临床表现），低热，活动后气短，腹胀明显加重1个月（提示慢性自发性细菌性腹膜炎）。既往有肝炎病史（肝硬化病因）。查体：T：37.5℃（正常值：36.0～37.0℃，发热），P：98次/分（正常值：60～100次/分），R：18次/分（正常值：12～20次/分钟），BP：104/72mmHg（血压正常值为90～139mmHg/60～89mmHg，血压正常），半卧位，上胸部可见蜘蛛痣，巩膜轻度黄染（提示肝硬化），心肺（-），全腹有压痛和反跳痛（腹膜刺激征，提示腹膜炎），肝脾触诊不满意，移动性浊音（+），双下肢可凹性水肿（+）（提示腹水），化验：血Hb106g/L（成年男性Hb＜130g/L，贫血），WBC7.4×10⁹/L（正常值3.5～9.5×10⁹/L），N0.88，Plt70×10⁹/L（正常值125～350×10⁹/L，下降），尿胆红素（+），血ALT110U/L（正常值：5～40U/L，升高），AST130U/L（正常值：8～40U/L，升高）（提示肝损伤），T-Bil 98μmol/L（正常值：3.4～17.1μmol/L，升高），D-Bil 65μmol/L（正常值：0～6.8μmol/L），根据患者的病史、临床表现和体征及实验室检查结果，最可能的诊断是肝硬化并发自发性细菌性腹膜炎（A对），自发性细菌性腹膜炎在住院的腹水患者发生率为10～30%，临床特点为短期内腹水迅速增加，对利尿剂无反应，伴腹泻、腹痛、腹胀、发热，腹壁压痛和反跳痛，少数患者可伴血压下降、肝功能恶化或门体分流性脑病加重。肝硬化并发门静脉血栓（B错）表现为门脉高压症状的显著加重，出现食管静脉或门脉高压性胃病出血，或剧烈腹痛或小肠梗死等。肝硬化并发结核性腹膜炎（C错）腹部触诊有柔韧感/“揉面感”，是结核性腹膜炎的典型特征，压痛一般较为轻微，多继发于肺结核或体内其他部位结核。肝硬化并发肝癌（D错）全身表现为进行性乏力、消瘦、发热、营养不良和恶病质，肝癌致腹水多是在肝硬化的基础上合并门静脉或肝静脉癌栓所致。","c183","N"],["2023-N71",35,"第一节 肝硬化","自发性细菌性腹膜炎",2023,71,"A","","男性，45岁。因4个月来乏力、食欲下降伴腹胀、尿少，1个月来低热、活动后气短、腹胀明显加重来诊。既往有肝炎病史。查体：T37.5℃，P98次/分，R18次/分，BP104/72mmHg。半卧位，上胸部可见蜘蛛痣，巩膜轻度黄染，心肺（-），全腹有压痛及反跳痛，肝脾触诊不满意，移动性浊音（+），双下肢可凹性水肿（+）。化验：血Hb106g/L，WBC7.4×10⁹/L，N0.88，Plt70×10⁹/L，尿胆红素（+），血ALT110U/L，AST130U/L，T-Bil98μmol/L，D-Bil65μmol/L。对该患者进行腹腔穿刺做腹水检查的最主要适应证是",[["A","T37.5℃，巩膜黄染，肝功能异常"],["B","T37.5℃，全腹有压痛及反跳痛，移动性浊音（+）"],["C","巩膜黄染，肝脾触诊不满意"],["D","肝炎病史，可见蜘蛛痣，巩膜黄染"]],"B","中年男性患者（肝硬化高发人群），乏力，食欲下降伴腹胀，尿少4个月（肝硬化可有临床表现），低热，活动后气短，腹胀明显加重1个月（提示慢性自发性细菌性腹膜炎）。既往有肝炎病史（肝硬化病因）。查体：T：37.5℃（正常值：36.0～37.0℃，发热），P：98次/分（正常值：60～100次/分），R：18次/分（正常值：12～20次/分钟），BP：104/72mmHg（血压正常值为90～139mmHg/60～89mmHg，血压正常），半卧位，上胸部可见蜘蛛痣，巩膜轻度黄染（提示肝硬化），心肺（-），全腹有压痛和反跳痛（腹膜刺激征，提示腹膜炎），肝脾触诊不满意，移动性浊音（+），双下肢可凹性水肿（+）（提示腹水），化验：血Hb106g/L（成年男性Hb＜130g/L，贫血），WBC7.4×10⁹/L（正常值3.5～9.5×10⁹/L），N0.88，Plt70×10⁹/L（正常值125～350×10⁹/L，下降），尿胆红素（+），血ALT110U/L（正常值：5～40U/L，升高），AST130U/L（正常值：8～40U/L，升高）（提示肝损伤），T-Bil 98μmol/L（正常值：3.4～17.1μmol/L，升高），D-Bil 65μmol/L（正常值：0～6.8μmol/L），根据患者的病史、临床表现和体征及实验室检查结果，最可能的诊断是肝硬化并发自发性细菌性腹膜炎，此时该患者行腹腔穿刺检查腹腔积液的最佳适应症是“T37.5℃，全腹压痛及反跳痛，移动性浊音（+）”（B对），即患者出现腹腔积液和腹膜炎体征时，需要进行腹腔穿刺，明确腹水病因及导致腹水增加的原因，同时可根据临床情况适当抽放腹腔积液以缓解症状。","c183","N"],["2023-N72",35,"第一节 肝硬化","自发性细菌性腹膜炎",2023,72,"A","","男性，45岁。因4个月来乏力、食欲下降伴腹胀、尿少，1个月来低热、活动后气短、腹胀明显加重来诊。既往有肝炎病史。查体：T37.5℃，P98次/分，R18次/分，BP104/72mmHg。半卧位，上胸部可见蜘蛛痣，巩膜轻度黄染，心肺（-），全腹有压痛及反跳痛，肝脾触诊不满意，移动性浊音（+），双下肢可凹性水肿（+）。化验：血Hb106g/L，WBC7.4×10⁹/L，N0.88，Plt70×10⁹/L，尿胆红素（+），血ALT110U/L，AST130U/L，T-Bil98μmol/L，D-Bil65μmol/L。下列支持该患者诊断的腹水检查结果是",[["A","外观透明浅黄，比重1.012，蛋白定量15g/L"],["B","外观微混，白细胞数600×10⁶/L，单核98%，蛋白定量35g/L"],["C","外观混浊，白细胞数900×10⁶/L，多核60%，蛋白定量45g/L"],["D","外观浑浊，比重1.015，蛋白定量25g/L，LDH158U/L"]],"C","中年男性患者（肝硬化高发人群），乏力，食欲下降伴腹胀，尿少4个月（肝硬化可有临床表现），低热，活动后气短，腹胀明显加重1个月（提示慢性自发性细菌性腹膜炎）。既往有肝炎病史（肝硬化病因）。查体：T：37.5℃（正常值：36.0～37.0℃，发热），P：98次/分（正常值：60～100次/分），R：18次/分（正常值：12～20次/分钟），BP：104/72mmHg（血压正常值为90～139mmHg/60～89mmHg，血压正常），半卧位，上胸部可见蜘蛛痣，巩膜轻度黄染（提示肝硬化），心肺（-），全腹有压痛和反跳痛（腹膜刺激征，提示腹膜炎），肝脾触诊不满意，移动性浊音（+），双下肢可凹性水肿（+）（提示腹水），化验：血Hb106g/L（成年男性Hb＜130g/L，贫血），WBC7.4×10⁹/L（正常值3.5～9.5×10⁹/L），N0.88，Plt70×10⁹/L（正常值125～350×10⁹/L，下降），尿胆红素（+），血ALT110U/L（正常值：5～40U/L，升高），AST130U/L（正常值：8～40U/L，升高）（提示肝损伤），T-Bil 98μmol/L（正常值：3.4～17.1μmol/L，升高），D-Bil 65μmol/L（正常值：0～6.8μmol/L），根据患者的病史、临床表现和体征及实验室检查结果，最可能的诊断是肝硬化并发自发性细菌性腹膜炎，腹水的性质应为渗出液，故符合患者诊断的腹水检查结果的是“外观混浊，白细胞数900×10⁶/L，多核60%，蛋白定量45g/L”（C对）。“外观微混，白细胞数600×10⁶/L，单核98%，蛋白定量35g/L”（B错）提示结核性腹腔积液。“外观透明浅黄，比重1.012，蛋白定量15g/L”（A错）提示腹腔积液为漏出液。“外观浑浊，比重1.015，蛋白定量25g/L，LDH158U/L”（D错）提示腹腔积液可能为肿瘤性。","c183","N"],["2023-N73",13,"第一节 呼吸衰竭概述","高碳酸血症性呼吸衰竭的发生机制",2023,73,"A","","男性，61岁。反复咳嗽、咳痰10余年，活动后气短1年，1周前受凉后出现气短加重，咳黄痰，伴发热，体温最高39℃，夜间可平卧。既往吸烟30年。查体：T38.2℃，P96次/分，R23次/分，BP150/80mmHg，神志清楚，球结膜水肿，口唇发绀，桶状胸，听诊双肺呼吸音低，可闻及散在湿啰音。未吸氧时动脉血气分析示pH7.31，PaCO₂78mmHg，PaO₂52mmHg。该患者出现PaCO₂升高的原因不包括",[["A","肺泡通气量下降"],["B","无效腔通气增加"],["C","内源性PEEP"],["D","弥散功能障碍"]],"D","老年男性患者，反复咳嗽咳痰10余年，活动后气短1年（咳痰喘多年，提示慢阻肺），1周前受凉后出现气短加重，咳黄痰，伴发热，体温最高39℃（提示感染，急性加重期），夜间可平卧，既往吸烟30年（COPD病因），查体：T38.2℃（正常值：36.0～37.0℃，发热），P96次/分（正常值：60～100次/分），R23次/分（正常值：12～20次/分钟），BP150/80mmHg（血压正常值为90～139mmHg/60～89mmHg，血压偏高），神志清楚，球结膜水肿，口唇发绀（缺氧表现），桶状胸（肺气肿体征）。听诊双肺呼吸音低，可闻及散在湿啰音（提示肺部炎症），未吸氧时动脉血气分析示pH7.31（正常值7.35～7.45，酸中毒），PaCO₂：78mmHg（正常：35～45mmHg，＞50mmHg，有CO₂潴留），PaO₂：52mmHg（正常：90～100mmHg，＜60mmHg，提示呼衰），根据患者的病史、临床表现和体征、实验室检查结果，最可能的诊断是1.慢性阻塞性肺疾病，急性加重期；2.Ⅱ型呼吸衰竭。此时机体呼吸衰竭的机制既包括肺通气功能障碍，也包括肺换气功能障碍。慢阻肺时肺泡通气量下降（A对）导致肺泡PO₂下降和肺泡PCO₂升高，流经肺泡的毛细血管血液不能被充分氧合，致机体缺氧和CO₂潴留。慢阻肺时也因大量肺泡壁的断裂导致肺泡毛细血管破坏，剩余的毛细血管受肺泡膨胀的挤压而退化，导致肺毛细血管大量减少，即此时肺区虽然有通气，但肺泡壁无血流灌注，导致无效腔通气增加（B对），此时可导致PaO₂降低，严重时可出现PaCO₂升高，CO₂潴留。内源性PEEP（PEEPi）（C对）即内源性呼气末正压是指因各种原因导致患者呼吸不畅或没有足够的呼气时间，呼气不完全，呼气末时肺泡内残留的气体相对过多，肺泡内压力高于大气压，呈正压状态，慢阻肺患者肺弹性纤维破坏，气道塌陷，易产生PEEPi，虽然在一定程度上PEEPi可以防止肺泡进一步塌陷，但会明显增加呼吸做功与耗氧量，导致呼吸肌疲劳，引发呼吸窘迫，患者必须克服PEEPi后才能产生肺泡内负压开始吸气，故内源性PEEP（PEEPi）会导致机体缺氧和CO₂潴留。慢阻肺时肺泡壁膨胀破裂，肺泡面积减少，严重时导致肺泡弥散面积下降，但因CO₂的弥散能力为O₂的20倍，故弥散功能障碍（D错，为本题正确答案）会导致明显的低氧血症，一般不会导致CO₂分压升高。","c184","N"],["2023-N74",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病发病机制",2023,74,"A","","男性，61岁。反复咳嗽、咳痰10余年，活动后气短1年，1周前受凉后出现气短加重，咳黄痰，伴发热，体温最高39℃，夜间可平卧。既往吸烟30年。查体：T38.2℃，P96次/分，R23次/分，BP150/80mmHg，神志清楚，球结膜水肿，口唇发绀，桶状胸，听诊双肺呼吸音低，可闻及散在湿啰音。未吸氧时动脉血气分析示pH7.31，PaCO₂78mmHg，PaO₂52mmHg。引起该患者病情加重最不可能的病原体是",[["A","流感嗜血杆菌"],["B","肺炎链球菌"],["C","肺炎支原体"],["D","铜绿假单胞菌"]],"C","老年男性患者，反复咳嗽咳痰10余年，活动后气短1年（咳痰喘多年，提示慢阻肺），1周前受凉后出现气短加重，咳黄痰，伴发热，体温最高39℃（提示感染，急性加重期），夜间可平卧，既往吸烟30年（COPD病因），查体：T38.2℃（正常值：36.0～37.0℃，发热），P96次/分（正常值：60～100次/分），R23次/分（正常值：12～20次/分钟），BP150/80mmHg（血压正常值为90～139mmHg/60～89mmHg，血压偏高），神志清楚，球结膜水肿，口唇发绀（缺氧表现），桶状胸（肺气肿体征）。听诊双肺呼吸音低，可闻及散在湿啰音（提示肺部炎症），未吸氧时动脉血气分析示pH7.31（正常值7.35～7.45，酸中毒），PaCO₂：78mmHg（正常：35～45mmHg，＞50mmHg，有CO₂潴留），PaO₂：52mmHg（正常：90～100mmHg，＜60mmHg，提示呼衰），根据患者的病史、临床表现和体征、实验室检查结果，最可能的诊断是1.慢性阻塞性肺疾病，急性加重期；2.Ⅱ型呼吸衰竭。慢性阻塞性肺疾病加重的原因多数为细菌感染诱发，常见的病原菌有肺炎链球菌（B对）、流感嗜血杆菌（A对）、铜绿假单胞菌（D对）、卡他莫拉菌和肺炎克雷伯菌等革兰氏阴性杆菌，特别是考虑到本例患者的临床表现和体征，引起该患者病情加重最不可能的病原体是肺炎支原体（C错，为本题正确答案）。","c184","N"],["2023-N75",13,"第三节 慢性呼吸衰竭","正压机械通气",2023,75,"A","","男性，61岁。反复咳嗽、咳痰10余年，活动后气短1年，1周前受凉后出现气短加重，咳黄痰，伴发热，体温最高39℃，夜间可平卧。既往吸烟30年。查体：T38.2℃，P96次/分，R23次/分，BP150/80mmHg，神志清楚，球结膜水肿，口唇发绀，桶状胸，听诊双肺呼吸音低，可闻及散在湿啰音。未吸氧时动脉血气分析示pH7.31，PaCO₂78mmHg，PaO₂52mmHg。该患者经治疗后出现嗜睡，意识模糊。复查动脉血气分析（吸氧2L/min）：pH7.24，PaCO₂85mmHg，PaO₂62mmHg，首选的治疗措施是",[["A","气管插管有创机械通气"],["B","无创机械通气"],["C","经鼻高流量氧疗"],["D","上调吸氧流量至5L/min"]],"A","老年男性患者，反复咳嗽咳痰10余年，活动后气短1年（咳痰喘多年，提示慢阻肺），1周前受凉后出现气短加重，咳黄痰，伴发热，体温最高39℃（提示感染，急性加重期），夜间可平卧，既往吸烟30年（COPD病因），查体：T38.2℃（正常值：36.0～37.0℃，发热），P96次/分（正常值：60～100次/分），R23次/分（正常值：12～20次/分钟），BP150/80mmHg（血压正常值为90～139mmHg/60～89mmHg，血压偏高），神志清楚，球结膜水肿，口唇发绀（缺氧表现），桶状胸（肺气肿体征）。听诊双肺呼吸音低，可闻及散在湿啰音（提示肺部炎症），未吸氧时动脉血气分析示pH7.31（正常值7.35～7.45，酸中毒），PaCO₂：78mmHg（正常：35～45mmHg，＞50mmHg，有CO₂潴留），PaO₂：52mmHg（正常：90～100mmHg，＜60mmHg，提示呼衰），根据患者的病史、临床表现和体征、实验室检查结果，最可能的诊断是1.慢性阻塞性肺疾病，急性加重期；2.Ⅱ型呼吸衰竭。患者在经治疗后出现嗜睡意识模糊（出现神志改变），复查动脉血气分析（吸氧2L/min，吸氧浓度为29%），pH7.24（酸中毒加重），PaCO₂：85mmHg（CO₂潴留加重），PaO₂：62mmHg（氧合不理想），以上情况说明患者经治疗后，呼吸衰竭情况恶化，出现更严重的酸碱平衡紊乱、低氧血症和神志改变，为改善患者情况，此时宜进行气管插管有创机械通气（A对BC错）。慢阻肺急性加重期行有创机械通气的适应症包括：1.严重呼吸困难，辅助呼吸肌参与呼吸，并出现胸腹矛盾；2.呼吸频率＞35次/min；3.危及生命的低氧血症，PaO₂＜40mmHg或PaO₂/FiO₂＜200mmHg；4.严重的呼吸性酸中毒（pH＜7.25）及高碳酸血症；5.呼吸抑制或停止；6.嗜睡，神志障碍；7.严重心血管系统并发症（低血压、休克、心力衰竭）；8.其他并发症（代谢紊乱、脓毒血症、肺炎、肺血栓栓塞症、气压伤、大量胸腔积液）；9.NPPV失败或存在NPPV的禁忌证（十六版实用内科学P1090）。上调吸氧流量至5L/min（D错）即吸入氧浓度为41%（低流量吸氧浓度为28%～30%），会导致吸入氧浓度过高引起CO₂潴留。","c184","N"],["2023-N76",23,"第一节 感染性心内膜炎","感染性心内膜炎诊断",2023,76,"A","","女性，36岁。发热2周，体温波动在37.5～38.5℃，伴乏力、出汗、食欲不振。既往有甲亢、二尖瓣脱垂史。查体：T38.1℃，P106次/分，BP110/75mmHg，BMI18kg/m²，左眼睑结膜可见瘀点，咽充血，甲状腺无肿大，心界稍大，心律齐，心尖部内侧可闻及4/6级收缩期吹风样杂音，肝未及，脾肋下1cm。化验：血Hb98g/L，WBC11.2×10⁹/L，ESR85mm/h，尿常规：蛋白（±），沉渣镜检RBC10～15个/HP。该患者最可能的诊断是",[["A","甲状腺功能亢进症"],["B","亚急性感染性心内膜炎"],["C","风湿热活动期"],["D","急性肾小球肾炎"]],"B","青年女性患者，发热两周，体温波动于37.5～38.5℃，乏力、出汗、食欲不振（感染全身症状），既往有甲亢、二尖瓣脱垂史（提示病因），查体：T38.1℃（正常值：36.0～37.0℃，发热），P106次/分（正常值：60～100次/分，心率加快），BP110/75mmHg（血压正常值为90～139mmHg/60～89mmHg），BMI18kg/m²（BMI正常值18.5～23.9kg/m²，偏瘦），左眼睑结膜可见淤点，咽充血（亚急性感染性心内膜炎常见周围体征），甲状腺无肿大，心界稍大，心律齐，心尖部内侧可闻及4/6级收缩期吹风样杂音（亚急性感染性心内膜炎心脏杂音常见），肝未及，脾肋下1cm（脾大），化验：Hb98g/L（女性正常值：115～150g/L，提示贫血），WBC11.2×10⁹/L（成人正常值：3.5～9.5×10⁹/L，提示感染），ESR85mm/h（女性正常值0～20mm/h，增快），尿蛋白（±）（轻度蛋白尿），沉渣镜检RBC10～15/HP（正常值＜3个/HP，镜下血尿），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是亚急性感染性心内膜炎（B对），感染性心内膜炎是由病原微生物循血行途径引起的心内膜、心瓣膜或邻近大动脉内膜的感染，并伴赘生物的形成，诊断主要依靠超声心动图和血培养，目前的诊断标准主要参考Duke标准。风湿热（RF）（C错）的致病菌为A组乙型溶血性链球菌，主要侵犯心脏和关节，临床表现以心脏损害最为严重和多见，以二尖瓣受累最为常见，好发年龄为5～15岁，典型表现为游走性及多发性关节炎，可出现环形红斑、皮下结节，风湿热活动期表现为白细胞总数和中性粒细胞增高，核左移，贫血，血沉增快，CRP升高，α₂球蛋白及黏蛋白增高。甲状腺功能亢进症（A错）是甲状腺产生过多甲状腺素导致的甲状腺毒症，Graves 病是导致甲亢的最常见原因，临床上以高代谢症群、甲状腺弥漫性肿、Graves眼病和胫前黏液性水肿为特点。急性肾小球肾炎（D错）多为链球菌感染后肾小球肾炎，多见于儿童，是一组以急性肾炎综合征（血尿、蛋白尿、水肿和高血压）为主要临床表现的肾脏疾病，可伴一过性肾功能损害。","c185","N"],["2023-N77",23,"第一节 感染性心内膜炎","周围体征",2023,77,"A","","女性，36岁。发热2周，体温波动在37.5～38.5℃，伴乏力、出汗、食欲不振。既往有甲亢、二尖瓣脱垂史。查体：T38.1℃，P106次/分，BP110/75mmHg，BMI18kg/m²，左眼睑结膜可见瘀点，咽充血，甲状腺无肿大，心界稍大，心律齐，心尖部内侧可闻及4/6级收缩期吹风样杂音，肝未及，脾肋下1cm。化验：血Hb98g/L，WBC11.2×10⁹/L，ESR85mm/h，尿常规：蛋白（±），沉渣镜检RBC10～15个/HP。该患者还有可能出现的体征是",[["A","Osler结节"],["B","环形红斑"],["C","Janeway损害"],["D","Graefe征"]],"A","青年女性患者，发热两周，体温波动于37.5～38.5℃，乏力、出汗、食欲不振（感染全身症状），既往有甲亢、二尖瓣脱垂史（提示病因），查体：T38.1℃（正常值：36.0～37.0℃，发热），P106次/分（正常值：60～100次/分，心率加快），BP110/75mmHg（血压正常值为90～139mmHg/60～89mmHg），BMI18kg/m²（BMI正常值18.5～23.9kg/m²，偏瘦），左眼睑结膜可见淤点，咽充血（亚急性感染性心内膜炎常见周围体征），甲状腺无肿大，心界稍大，心律齐，心尖部内侧可闻及4/6级收缩期吹风样杂音（亚急性感染性心内膜炎心脏杂音常见），肝未及，脾肋下1cm（脾大），化验：Hb98g/L（女性正常值：115～150g/L，提示贫血），WBC11.2×10⁹/L（成人正常值：3.5～9.5×10⁹/L，提示感染），ESR85mm/h（女性正常值0～20mm/h，增快），尿蛋白（±）（轻度蛋白尿），沉渣镜检RBC10～15/HP（正常值＜3个/HP，镜下血尿），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是亚急性感染性心内膜炎，感染性心内膜炎是由病原微生物循血行途径引起的心内膜、心瓣膜或邻近大动脉内膜的感染，并伴赘生物的形成，诊断主要依靠超声心动图和血培养，目前的诊断标准主要参考Duck标准。该患者还可能出现的体征有Osler结节（A对），结节呈紫或红色，稍高于皮面，直径小约1～2mm，大者可5～15mm，多发生于手指或足趾末端的掌面，大小鱼际肌或足底，可有压痛，4～5天消退，需要注意的是，Osler结节非亚急性感染性心内膜炎特有，在系统性红斑狼疮、伤寒、淋巴瘤中也可出现。Janeway损害（C错）多见于急性患者。环形红斑（B错）提示风湿热，也见于系统性红斑狼疮。Graefe征（D错）即上眼睑移动滞缓，为Graves病眼部表现-非浸润性眼突的眼征之一，表现为眼睛向下看时上眼睑不能及时随眼球向下移动，看到白色巩膜。","c185","N"],["2023-N78",23,"第一节 感染性心内膜炎","UCG",2023,78,"A","","女性，36岁。发热2周，体温波动在37.5～38.5℃，伴乏力、出汗、食欲不振。既往有甲亢、二尖瓣脱垂史。查体：T38.1℃，P106次/分，BP110/75mmHg，BMI18kg/m²，左眼睑结膜可见瘀点，咽充血，甲状腺无肿大，心界稍大，心律齐，心尖部内侧可闻及4/6级收缩期吹风样杂音，肝未及，脾肋下1cm。化验：血Hb98g/L，WBC11.2×10⁹/L，ESR85mm/h，尿常规：蛋白（±），沉渣镜检RBC10～15个/HP。下列检查中，最有可能为明确诊断提供重要依据的是",[["A","血C反应蛋白"],["B","胸部CT检查"],["C","甲状腺B超检查"],["D","超声心动图检查"]],"D","青年女性患者，发热两周，体温波动于37.5～38.5℃，乏力、出汗、食欲不振（感染全身症状），既往有甲亢、二尖瓣脱垂史（提示病因），查体：T38.1℃（正常值：36.0～37.0℃，发热），P106次/分（正常值：60～100次/分，心率加快），BP110/75mmHg（血压正常值为90～139mmHg/60～89mmHg），BMI18kg/m²（BMI正常值18.5～23.9kg/m²，偏瘦），左眼睑结膜可见淤点，咽充血（亚急性感染性心内膜炎常见周围体征），甲状腺无肿大，心界稍大，心律齐，心尖部内侧可闻及4/6级收缩期吹风样杂音（亚急性感染性心内膜炎心脏杂音常见），肝未及，脾肋下1cm（脾大），化验：Hb98g/L（女性正常值：115～150g/L，提示贫血），WBC11.2×10⁹/L（成人正常值：3.5～9.5×10⁹/L，提示感染），ESR85mm/h（女性正常值0～20mm/h，增快），尿蛋白（±）（轻度蛋白尿），沉渣镜检WBC10～15/HP（正常值＜3个/HP，镜下血尿），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是亚急性感染性心内膜炎，感染性心内膜炎是由病原微生物循血行途径引起的心内膜、心瓣膜或邻近大动脉内膜的感染，并伴赘生物的形成，诊断主要依靠超声心动图和血培养，约75%～85%的患者血培养阳性，血培养阳性是诊断感染性心内膜炎/IE的最直接证据，而超声心动图能探测到赘生物所在的部位、大小和形态，对血培养阴性的患者很有诊断价值，因此能为明确诊断提供重要依据的是超声心动图检查（D对），目前的诊断标准主要参考Duck标准。胸部CT（B错）有助于IE时怀疑肺栓塞、脑梗死、脓肿和出血的诊断。血C反应蛋白（A错）是感染时急性时相反应极灵敏的指标，但不具有特异性，见于多种化脓性感染、恶性肿瘤、组织坏死和结缔组织病等，可用于鉴别细菌性感染和非细菌性感染，也可以用于鉴别风湿热的活动期和稳定期，一般情况下器质性病变CRP升高，功能性病变不升高，需要注意的是孕妇体内CRP含量较高。甲状腺B超检查（C错）用于甲状腺疾病的辅助诊断。","c185","N"],["2023-N79",29,"第一节 肠结核","肠结核诊断",2023,79,"A","","男性，31岁。3个月来低热、右下腹痛，加重半个月，常有便秘，有时腹泻伴糊样便。既往有肺结核病史。查体：T37.6℃，浅表淋巴结无肿大，心肺未见异常，腹软，右下腹可触及一4cm×3cm大小肿块，质中，中度压痛，肝脾肋下未触及，移动性浊音（-）。化验：血Hb135g/L，ESR65mm/h。最可能的诊断是",[["A","右侧结肠癌"],["B","肠结核"],["C","克罗恩病"],["D","肠淋巴瘤"]],"B","青年男性患者，3个月来低热（结核毒血症状），右下腹痛，加重半个月，常有便秘，有时腹泻伴糊样便（大便习惯改变），既往有肺结核病变（提示病因），查体：T37.6℃（正常值：36.0～37.0℃，低热），浅表淋巴结无肿大，心肺未见异常，腹软，右下腹可触及一4cm×3cm大小肿块，质中，中度压痛（肠结核腹部肿块特点），肝脾肋下未触及，移动性浊音（﹣），化验：血Hb135g/L（成年男性正常值130～175g/L），ESR65mm/L（男性正常值0～15mm/h，增快），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是肠结核（B对），是结核分枝杆菌引起的肠道慢性特异性感染，多继发于其他部位结核。本病需特别注意与克罗恩病相鉴别，克罗恩病（C错）多有家族史，一般无肠外结核，病程较长，缓解与复发交替，可见肛周病变、腹腔脓肿，抗结核治疗无效。右侧结肠癌（A错）发病年龄较大，一般无发热、盗汗等结核毒血症表现，结肠镜及活检有助于确诊和鉴别。肠淋巴瘤（D错）多有慢性腹痛或便血、贫血、发热、体重下降等表现，严重者可有肠梗阻，肠镜下结肠病灶或淋巴结活检可确诊。","c186","N"],["2023-N80",29,"第一节 肠结核","肠结核结肠镜",2023,80,"A","","男性，31岁。3个月来低热、右下腹痛，加重半个月，常有便秘，有时腹泻伴糊样便。既往有肺结核病史。查体：T37.6℃，浅表淋巴结无肿大，心肺未见异常，腹软，右下腹可触及一4cm×3cm大小肿块，质中，中度压痛，肝脾肋下未触及，移动性浊音（-）。化验：血Hb135g/L，ESR65mm/h。为明确诊断，最有意义的检查是",[["A","粪常规+隐血"],["B","腹部B超"],["C","结肠镜"],["D","X线钡剂灌肠"]],"C","青年男性患者，3个月来低热（结核毒血症状），右下腹痛，加重半个月，常有便秘，有时腹泻伴糊样便（大便习惯改变），既往有肺结核病变（提示病因），查体：T37.6℃（正常值：36.0～37.0℃，低热），浅表淋巴结无肿大，心肺未见异常，腹软，右下腹可触及一4cm×3cm大小肿块，质中，中度压痛（肠结核腹部肿块特点），肝脾肋下未触及，移动性浊音（﹣），化验：血Hb135g/L（成年男性正常值130～175g/L），ESR65mm/L（男性正常值0～15mm/h，增快），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是肠结核，是结核分枝杆菌引起的肠道慢性特异性感染，多继发于其他部位结核，为明确诊断，最有意义的辅助检查是结肠镜（C对），肠结核以回盲部多见，内镜检查至末端回肠同时行活检可确诊。X线钡剂灌肠（D错）对肠结核的诊断有一定的价值，溃疡型肠结核时钡剂在病变肠段可见激惹征象，在病变上下肠段充盈良好，即为X线钡剂跳跃征象；增生型肠结核可见肠黏膜呈结节状改变，肠腔变窄、肠段缩短变形、回肠盲肠正常角度消失。粪常规+隐血（A错）可作为常规辅助检查，但无确诊意义。腹部B超（B错）对空腔脏器的诊断意义有限，主要用于消化系统实质性脏器、胆道及腹腔内的病变。","c186","N"],["2023-N81",29,"第一节 肠结核","肠结核抗结核化学药物治疗",2023,81,"A","","男性，31岁。3个月来低热、右下腹痛，加重半个月，常有便秘，有时腹泻伴糊样便。既往有肺结核病史。查体：T37.6℃，浅表淋巴结无肿大，心肺未见异常，腹软，右下腹可触及一4cm×3cm大小肿块，质中，中度压痛，肝脾肋下未触及，移动性浊音（-）。化验：血Hb135g/L，ESR65mm/h。首选的治疗是",[["A","抗结核治疗"],["B","手术治疗"],["C","全身肿瘤联合化疗"],["D","应用柳氮磺吡啶"]],"A","青年男性患者，3个月来低热（结核毒血症状），右下腹痛，加重半个月，常有便秘，有时腹泻伴糊样便（大便习惯改变），既往有肺结核病变（提示病因），查体：T37.6℃（正常值：36.0～37.0℃，低热），浅表淋巴结无肿大，心肺未见异常，腹软，右下腹可触及一4cm×3cm大小肿块，质中，中度压痛（肠结核腹部肿块特点），肝脾肋下未触及，移动性浊音（﹣），化验：血Hb135g/L（成年男性正常值130～175g/L），ESR65mm/L（男性正常值0～15mm/h，增快），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是肠结核，是结核分枝杆菌引起的肠道慢性特异性感染，多继发于其他部位结核，首选的治疗为抗结核治疗（A对），标准抗结核治疗有很高的治愈率。本例患者不符合肠结核手术治疗的手术指证（B错）。全身肿瘤联合化疗（C错）为部分肿瘤的治疗方式。柳氮磺吡啶（D错）为氨基水杨酸制剂，多用于溃疡型结肠炎和克罗恩病（病变局限于结肠）的治疗。","c186","N"],["2023-N82",40,"第二节 急性肾小球肾炎","急性肾小球肾炎实验室检查",2023,82,"A","","男性，22岁。2周前发热伴咽痛，2天来双眼睑水肿和双下肢中度可凹性水肿。血压150/95mmHg。化验尿蛋白（++），沉渣镜检RBC30～50个/HP，血肌酐96μmol/L，血尿素氮7mmol/L。下一步首选的辅助检查是",[["A","心电图"],["B","血常规"],["C","尿本周蛋白"],["D","尿相差显微镜检查"]],"D","男性，22岁，2周前发热伴咽痛（前驱感染），2天来双眼睑水肿和双下肢中度可凹性水肿（急性肾炎综合征表现），血压150/95mmHg（血压正常值为90～139mmHg/60～89mmHg，血压升高），化验尿蛋白（++）（蛋白尿），沉渣镜检RBC30～50个/HP（正常值0～3个/HP），血肌酐96μmol/L（成年男性正常值54～106μmol/L），血尿素氮7mmol/L（成人正常值3.2～7.1mmol/L），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是急性肾小球肾炎，此时下一步首选的辅助检查是尿相差显微镜检查（D对），可判断尿中红细胞的来源，多数急性肾小球肾炎患者有肾小球源性血尿，近半数患者为肉眼血尿。需要注意的是，急性肾小球肾炎起病初期血清C3及总补体下降，8周内逐渐恢复正常，该变化对本病具有诊断意义，血清抗链球菌溶血素“O”滴度升高，提示近期有链球菌感染。急性肾小球肾炎时血常规（B错）可有轻度贫血，与水钠潴留，血液稀释有关，白细胞计数可正常或升高。尿本周蛋白（C错）提示多发性骨髓瘤，肾盂肾炎、慢性肾炎、肾癌、肾病综合征等患者尿液中偶可检出。心电图（A错）主要用于心律失常和心肌缺血、损伤的诊断。","c187","N"],["2023-N83",40,"第二节 急性肾小球肾炎","急性肾小球肾炎病理表现",2023,83,"A","","男性，22岁。2周前发热伴咽痛，2天来双眼睑水肿和双下肢中度可凹性水肿。血压150/95mmHg。化验尿蛋白（++），沉渣镜检RBC30～50个/HP，血肌酐96μmol/L，血尿素氮7mmol/L。该患者肾脏病理检查最可能的病变类型是",[["A","系膜毛细血管性肾小球肾炎"],["B","系膜增生性肾小球肾炎"],["C","毛细血管内增生性肾小球肾炎"],["D","新月体肾小球肾炎"]],"C","男性，22岁，2周前发热伴咽痛（前驱感染），2天来双眼睑水肿和双下肢中度可凹性水肿（急性肾炎综合征表现），血压150/95mmHg（血压正常值为90～139mmHg/60～89mmHg，血压升高），化验尿蛋白（++）（蛋白尿），沉渣镜检RBC30～50个/HP（正常值0～3个/HP），血肌酐96μmol/L（成年男性正常值54～106μmol/L），血尿素氮7mmol/L（成人正常值3.2～7.1mmol/L），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是急性肾小球肾炎，该患者肾脏病理检查最可能的病理类型是毛细血管内增生性肾小球肾炎（C对），肾小球体积增大，内皮细胞和系膜细胞增生，可见中性粒细胞和单核细胞浸润，毛细血管腔狭窄或闭塞。新月体肾小球肾炎（D错）是急进型肾小球肾炎的病理类型。系膜毛细血管性肾小球肾炎（A错）、系膜增生性肾小球肾炎（B错）是肾病综合征的常见病理类型。","c187","N"],["2023-N84",40,"第二节 急性肾小球肾炎","急性肾小球肾炎临床表现",2023,84,"A","","男性，22岁。2周前发热伴咽痛，2天来双眼睑水肿和双下肢中度可凹性水肿。血压150/95mmHg。化验尿蛋白（++），沉渣镜检RBC30～50个/HP，血肌酐96μmol/L，血尿素氮7mmol/L。该患者血压增高最可能的原因是",[["A","原发性高血压"],["B","水、钠潴留"],["C","肾动脉狭窄"],["D","血醛固酮增高"]],"B","男性，22岁，2周前发热伴咽痛（前驱感染），2天来双眼睑水肿和双下肢中度可凹性水肿（急性肾炎综合征表现），血压150/95mmHg（血压正常值为90～139mmHg/60～89mmHg，血压升高），化验尿蛋白（++）（蛋白尿），沉渣镜检RBC30～50个/HP（正常值0～3个/HP），血肌酐96μmol/L（成年男性正常值54～106μmol/L），血尿素氮7mmol/L（成人正常值3.2～7.1mmol/L），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是急性肾小球肾炎/急性肾炎。肾炎导致的高血压属于肾实质性高血压，主要原因为肾单位大量流失，导致水、钠潴留和细胞外液容量增加（B对），以及肾脏RAS系统的抑制与排钠减少；同时高血压又进一步升高肾小球内囊压力，形成恶性循环，加重肾脏病变。原发性高血压（A错）很少出现明显的蛋白尿，血尿也不明显，肾小管滤过功能可长期保持正常或增强。肾动脉狭窄（C错）是肾血管性高血压的原因。血醛固酮增高（D错）是原发性醛固酮增多症致高血压的原因，原醛在临床上以长期高血压伴低血钾为特征，少数患者血钾正常，可有肌无力、周期性瘫痪、烦渴、多尿等症状。","c187","N"],["2023-N85",50,"第一节 溶血性贫血概述","溶血性贫血诊断",2023,85,"A","","男性，29岁。1个月来头晕、乏力，加重3天。既往体健。查体：贫血貌，巩膜轻度黄染，肺（-），心率96次/分，心律齐，腹软，肝肋下未触及，脾肋下1cm。血常规：Hb75g/L，RBC2.5×10¹²/L，WBC7.4×10⁹/L，Plt185×10⁹/L。最可能的贫血诊断是",[["A","缺铁性贫血"],["B","巨幼细胞贫血"],["C","再生障碍性贫血"],["D","溶血性贫血"]],"D","青年男性患者，一个月来头晕乏力，加重3天（贫血全身表现），既往体健，查体，贫血貌，巩膜轻黄染（提示溶血），肺（-），心率96次/分（正常值60～100次/分），心律齐，腹软，肝肋下未触及，脾肋下1cm（脾大），血常规：Hb75g/L（成年男性正常值130～175g/L，中度贫血），RBC2.5×10¹²/L（男性正常值4～5.5×10¹²/L，红细胞计数减少），WBC7.4×10⁹/L（成人正常值3.5～9.5×10⁹/L），Plt185×10⁹/L（正常值125～350×10⁹/L），根据患者病史、临床表现和体征、实验室检查结果，患者最可能的贫血诊断是慢性溶血性贫血（D对），慢性溶血多为血管外溶血，发病缓慢，表现贫血、黄疸和脾肿大三大特征。缺铁性贫血（A错）一般有导致机体缺铁的原发病表现，妇女月经过多，消化性溃疡，肿瘤等，临床表现除乏力、头晕、气短等一般贫血表现之外，还有明显的组织细胞缺铁表现，相关黏膜损害较常见，出现易出现口角炎、舌炎、舌乳头萎缩、慢性萎缩性胃炎等，吞咽困难或吞咽时有梗阻感是铁缺乏的特殊表现之一，还可见反甲或匙状甲，部分患者可出现异食癖。巨幼细胞贫血（B错）一种主要由叶酸和（或）维生素B₁₂缺乏所致的大细胞性贫血，可有较为特异的消化系统症状，如口腔黏膜、舌乳头萎缩，舌面呈“牛肉样舌”，可伴舌痛，胃肠道黏膜萎缩可导致食欲减退、恶心、腹胀、腹泻或便秘，同时缺乏叶酸和（或）维生素B₁₂也会有相应的神经精神表现。再生障碍性贫血（C错）属于骨髓衰竭性疾病，以外周全血血细胞减少及其相关临床表现为特征。","c188","N"],["2023-N86",50,"第一节 溶血性贫血概述","溶血性贫血实验室检查",2023,86,"A","","男性，29岁。1个月来头晕、乏力，加重3天。既往体健。查体：贫血貌，巩膜轻度黄染，肺（-），心率96次/分，心律齐，腹软，肝肋下未触及，脾肋下1cm。血常规：Hb75g/L，RBC2.5×10¹²/L，WBC7.4×10⁹/L，Plt185×10⁹/L。首选最有意义的检查是",[["A","红细胞沉降率"],["B","血白细胞分类"],["C","血网织红细胞计数"],["D","粪常规+隐血"]],"C","青年男性患者，一个月来头晕乏力，加重3天（贫血全身表现），既往体健，查体，贫血貌，巩膜轻黄染（提示溶血），肺（-），心率96次/分（正常值60～100次/分），心律齐，腹软，肝肋下未触及，脾肋下1cm（脾大），血常规：Hg75g/L（成年男性正常值130～175g/L，中度贫血），RBC2.5×10¹²/L（男性正常值4～5.5×10¹²/L，红细胞计数减少），WBC7.4×10⁹/L（成人正常值3.5～9.5×10⁹/L），Plt185×10⁹/L（正常值125～350×10⁹/L），根据患者病史、临床表现和体征、实验室检查结果，患者最可能的贫血诊断是慢性溶血性贫血，慢性溶血多为血管外溶血，发病缓慢，表现贫血、黄疸和脾肿大三大特征。此时最有意义的检查是血网织红细胞计数（C对），该检查属于红细胞代偿性增生的检查，为溶血性贫血的筛查试验。对溶血性贫血检查的原则是首先进行筛查，确定溶血后，再在初步判断病因的基础上有针对性的选用其他相关检查。红细胞沉降率（A错）、血白细胞分类（B错）、粪常规+隐血（D错）对溶血性贫血无筛查和诊断意义。","c188","N"],["2023-N87",50,"第一节 溶血性贫血概述","溶血性贫血实验室检查",2023,87,"A","","男性，29岁。1个月来头晕、乏力，加重3天。既往体健。查体：贫血貌，巩膜轻度黄染，肺（-），心率96次/分，心律齐，腹软，肝肋下未触及，脾肋下1cm。血常规：Hb75g/L，RBC2.5×10¹²/L，WBC7.4×10⁹/L，Plt185×10⁹/L。骨髓细胞学检查中，幼红细胞最可能出现的异常是",[["A","巨幼样变"],["B","“核老浆幼”现象"],["C","增生减低"],["D","明显增生"]],"D","青年男性患者，一个月来头晕乏力，加重3天（贫血全身表现），既往体健，查体，贫血貌，巩膜轻黄染（提示溶血），肺（-），心率96次/分（正常值60～100次/分），心律齐，腹软，肝肋下未触及，脾肋下1cm（脾大），血常规：Hb75g/L（成年男性正常值130～175g/L，中度贫血），RBC2.5×10¹²/L（男性正常值4～5.5×10¹²/L，红细胞计数减少），WBC7.4×10⁹/L（成人正常值3.5～9.5×10⁹/L），Plt185×10⁹/L（正常值125～350×10⁹/L），根据患者病史、临床表现和体征、实验室检查结果，患者最可能的贫血诊断是慢性溶血性贫血，慢性溶血多为血管外溶血，发病缓慢，表现贫血、黄疸和脾肿大三大特征。骨髓细胞学检查中，幼红细胞最有可能出现的异常是明显增生（D对），提示溶血后骨髓红系代偿性增生。幼红细胞显著降低（C错）提示骨髓增生不良，见于再生障碍性贫血。巨幼样变（A错）是巨幼细胞贫血的骨髓细胞学检查表现。“核老浆幼”现象（B错）是缺铁性贫血的骨髓细胞学检查表现。","c188","N"],["2023-N88",61,"第一节 糖尿病","糖尿病性视网膜病变",2023,88,"A","","女性，63岁。2型糖尿病25年，现用预混胰岛素每日2次注射治疗。2年前眼底检查发现视网膜有新生血管形成。半年来反复出现尿频、尿急，抗生素治疗有效。近2个月咳嗽时常有尿液不自主流出。来院检查发现：BP160/100mmHg，尿糖（++），尿酮体（-），尿沉渣镜检白细胞5～10个/HP，空腹血糖9.6mmol/L，HbA1c8.6%，血Cr203μmol/L。B超检查提示膀胱残余尿量增加。该患者糖尿病微血管并发症的诊断是",[["A","糖尿病视网膜改变3期，糖尿病自主神经病变"],["B","糖尿病视网膜改变3期，糖尿病周围神经病变"],["C","糖尿病视网膜改变4期，糖尿病自主神经病变"],["D","糖尿病视网膜改变4期，糖尿病周围神经病变"]],"C","老年2型糖尿病患者，两年前眼底检查发现视网膜有新生血管形成（糖尿病视网膜病变4期改变），半年来反复出现尿频，尿急，抗生素治疗有效（糖尿病易并发感染）。近两个月咳嗽时常有尿液不自主流出（提示尿失禁，自主神经病变）。来院检查发现；BP160/100mmHg（血压正常值为90～139mmHg/60～89mmHg，血压升高），尿糖（++）（正常为阴性），尿酮体（-），尿沉渣镜检白细胞5～10个/HP（正常值＜5个/HP，提示尿路感染），空腹血糖9.6mmol/L（≥7.0mmol/L，糖尿病），HbA₁c8.6%（正常值4%～6%，≥6.5%为糖尿病诊断的参考），血Cr203μmol/L（女性正常值44～97μmol/L，提示肾损伤），B超检查提示膀胱残余尿量增加（提示尿潴留，自主神经病变），根据患者病史、临床表现和体征、实验室检查、影像学检查结果，目前该患者糖尿病微血管并发症诊断是糖尿病视网膜改变4期，糖尿病自主神经病变（C对）。","c189","N"],["2023-N89",61,"第一节 糖尿病","糖尿病慢性并发症的防治原则",2023,89,"A","","女性，63岁。2型糖尿病25年，现用预混胰岛素每日2次注射治疗。2年前眼底检查发现视网膜有新生血管形成。半年来反复出现尿频、尿急，抗生素治疗有效。近2个月咳嗽时常有尿液不自主流出。来院检查发现：BP160/100mmHg，尿糖（++），尿酮体（-），尿沉渣镜检白细胞5～10个/HP，空腹血糖9.6mmol/L，HbA1c8.6%，血Cr203μmol/L。B超检查提示膀胱残余尿量增加。该患者首选的降压药物是",[["A","利尿剂"],["B","钙通道阻滞剂"],["C","β受体拮抗剂"],["D","血管紧张素转换酶抑制剂"]],"D","老年2型糖尿病患者，两年前眼底检查发现视网膜有新生血管形成（糖尿病视网膜病变4期改变），半年来反复出现尿频，尿急，抗生素治疗有效（糖尿病易并发感染）。近两个月咳嗽时常有尿液不自主流出（提示尿失禁，自主神经病变）。来院检查发现；BP160/100mmHg（血压正常值为90～139mmHg/60～89mmHg，血压升高），尿糖（++）（正常为阴性），尿酮体（-），尿沉渣镜检白细胞5～10个/HP（正常值＜5个/HP，提示尿路感染），空腹血糖9.6mmol/L（≥7.0mmol/L，糖尿病），HbA₁c8.6%（正常值4%～6%，≥6.5%为糖尿病诊断的参考），血Cr203μmol/L（女性正常值44～97μmol/L，提示肾损伤），B超检查提示膀胱残余尿量增加（提示尿潴留，自主神经病变），根据患者病史、临床表现和体征、实验室检查、影像学检查结果，目前该患者诊断为1.2型糖尿病；2.糖尿病视网膜病变；3.糖尿病自主神经病变；4.肾功能损伤；5.2级高血压，很高危，目前该患者首选的降压药应为血管紧张素转换酶抑制剂/ACEI（D对），ACEI可改善胰岛素抵抗并减少蛋白尿，对肥胖、糖尿病和心脏、肾脏靶器官受损的高血压都有较好的疗效。利尿剂（A错）的主要不良反应是低血钾症和影响血脂、血糖、血尿酸代谢，因此不作为本例患者降压首选。钙通道阻滞剂（B错）尤其适用于老年高血压，老年单纯收缩期高血压，伴稳定型心绞痛、冠状动脉或颈动脉粥样硬化及周围血管病患者。β受体拮抗剂（C错）可能会增加胰岛素抵抗，并可能掩盖和延长降糖治疗过程中的低血糖症状，特别是使用胰岛素的糖尿病患者应更加注意。","c189","N"],["2023-N90",61,"第一节 糖尿病","胰岛素",2023,90,"A","","女性，63岁。2型糖尿病25年，现用预混胰岛素每日2次注射治疗。2年前眼底检查发现视网膜有新生血管形成。半年来反复出现尿频、尿急，抗生素治疗有效。近2个月咳嗽时常有尿液不自主流出。来院检查发现：BP160/100mmHg，尿糖（++），尿酮体（-），尿沉渣镜检白细胞5～10个/HP，空腹血糖9.6mmol/L，HbA1c8.6%，血Cr203μmol/L。B超检查提示膀胱残余尿量增加。为改善血糖控制，最合适的治疗方案是",[["A","在原胰岛素治疗方案基础上，加用二甲双胍0.5g，每日3次"],["B","改用每日1次中长效基础胰岛素联合3次餐时胰岛素"],["C","改用每日1次中长效基础胰岛素联合3种口服降糖药"],["D","单用基础胰岛素"]],"B","老年女性患者，2型糖尿病25年，现用预混胰岛素每日两次注射治疗，空腹血糖控制不理想，糖化血红蛋白高，同时有糖尿病视网膜病变和自主神经病变、肾功能损伤，故为改善血糖控制，最合适的治疗方案是改用每日1次中长效基础胰岛素联合3次餐时胰岛素（B对D错），该方案为目前临床常用方案，符合大部分替代治疗，可使三餐血糖及空腹血糖均能控制满意，剂量调整易行，使用得当不易发生低血糖。二甲双胍（A错）禁用于肝肾功能不全、严重高血压、明显视网膜病变者。通常情况下，胰岛素治疗是在生活方式干预和较大剂量多种口服降糖药联合治疗后血糖控制不佳后的治疗选择，故在预混胰岛素每日两次注射治疗后欲改善血糖控制效果，加用多种口服降糖药不会得到更好的治疗效果（C错）。","c189","N"],["2023-N91",71,"第六节 贝赫切特病","贝赫切特病诊断",2023,91,"A","","男性，42岁。间断口腔溃疡5年，偶有阴囊溃疡，反复左侧眼炎3年，近1周自觉左眼视物不清。最可能的诊断是",[["A","系统性红斑狼疮"],["B","赖特（Reiter’s）综合征"],["C","克罗恩病"],["D","贝赫切特（Behcet）病"]],"D","中年男性患者，间断性口腔溃疡5年（贝赫切特病诊断标准1），偶有阴囊溃疡（贝赫切特病诊断标准2），反复左侧眼炎3年（贝赫切特病诊断标准3），近1周自觉左眼视物不清，根据患者的病史和临床表现，最可能的诊断为贝赫切特（Behcet）病（D对），又称白塞病，是一种病因未明、以口腔溃疡、外阴溃疡、眼炎及皮肤损害为临床特征的自身免疫性疾病，以往曾称呼为“眼、口、生殖器综合征”，因其可以表现为多器官多系统受累，故有时会造成鉴别诊断上的困难。系统性红斑狼疮（A错）多见于育龄期女性，有遗传易感性，皮疹以鼻梁和双颧部蝶形红斑最具特征性，对诊断具有重要意义。赖特（Reiter’s）综合征（B错）属于反应性关节炎，是指继发于身体其他部位感染的急性非化脓性关节炎，一般在前驱感染1～2周后发病，典型表现为非对称性少关节炎。克罗恩病（C错）是病因不明的胃肠道慢性非特异、肉芽肿性疾病，临床表现为腹痛、腹泻、腹块及肠梗阻，并伴有关节、皮肤等肠外表现，好发部位为回肠末端和盲肠，但从口腔至肛门各段消化道均可受累，呈节段性或跳跃式分布。","","N"],["2023-N92",71,"第六节 贝赫切特病","皮肤病变",2023,92,"A","","男性，42岁。间断口腔溃疡5年，偶有阴囊溃疡，反复左侧眼炎3年，近1周自觉左眼视物不清。该病较常见的其他临床表现是",[["A","尿道烧灼感"],["B","盘状红斑"],["C","结节性红斑"],["D","心脏扩大"]],"C","中年男性患者，间断性口腔溃疡5年（贝赫切特病诊断标准1），偶有阴囊溃疡（贝赫切特病诊断标准2），反复左侧眼炎3年（贝赫切特病诊断标准3），近1周自觉左眼视物不清，根据患者的病史和临床表现，最可能的诊断为贝赫切特（Behcet）病，又称白塞病，是一种病因未明、以口腔溃疡、外阴溃疡、眼炎及皮肤损害为临床特征的自身免疫性疾病，以往曾称呼为“眼、口、生殖器综合征”，该病较常见的其他临床表现是结节性红斑（C对），双侧下肢小腿伸侧面的结节性红斑最常见，具有特异性，可见于70%的患者。贝赫切特病的心血管受累主要为大、中血管病变，心脏受累不多见，少数出现心脏瓣膜损害和心包炎（D错）。盘状红斑（B错）多见于系统性红斑狼疮。尿道烧灼感（A错）常见于泌尿系统和生殖系统感染。","","N"],["2023-N128",10,"第四节 急性肺源性心脏病","急性肺源性心脏病病因",2023,128,"B","","上述疾病中，急性肺源性心脏病最常见的病因是",[["A","慢性阻塞性肺疾病"],["B","特发性肺纤维化"],["C","急性肺血栓栓塞症"],["D","重症肺炎"]],"C","急性肺源性心脏病的病因为肺动脉压的急剧升高，右心室扩张失代偿但不伴有右心室肥厚，最主要的病因是急性肺血栓栓塞症（C对）及重度急性呼吸窘迫综合征（ARDS）。慢性阻塞性肺疾病（A错）为慢性肺源性心脏病的主要病因，其次为支气管哮喘、肺结核、支气管扩张、间质性肺疾病（B错）等。重症肺炎（D错）为急性呼吸窘迫综合征（ARDS）的常见危险因素。","","N"],["2023-N129",10,"第三节 慢性肺源性心脏病","支气管、肺疾病",2023,129,"B","","上述疾病中，慢性肺源性心脏病最常见的病因是",[["A","慢性阻塞性肺疾病"],["B","特发性肺纤维化"],["C","急性肺血栓栓塞症"],["D","重症肺炎"]],"A","慢性肺源性心脏病最常见的病因是慢性阻塞性肺疾病（A对），其次为支气管哮喘、肺结核、支气管扩张、间质性肺疾病（B错）等。急性肺血栓栓塞症（C错）为急性肺源性心脏病的常见原因。重症肺炎（D错）为急性呼吸窘迫综合征（ARDS）的常见危险因素。","","N"],["2023-N130",35,"第一节 肝硬化","内分泌失调",2023,130,"B","","肝硬化导致性激素代谢失调引起的临床表现是",[["A","黄疸"],["B","蜘蛛痣"],["C","腹水"],["D","牙龈出血"]],"B","肝硬化导致性激素代谢失调的临床表现为性激素紊乱，患者可出现肝掌、蜘蛛痣（B对）及男性乳房发育等表现。腹水（C错）为肝硬化导致肝门静脉高压的最突出的临床表现。黄疸（A错）和牙龈出血（D错）为肝硬化肝功能减退失代偿期表现，前者原因为肝细胞广泛坏死，后者系肝脏凝血因子合成减少、脾功能亢进及毛细血管脆性增加导致。","","N"],["2023-N131",35,"","",2023,131,"B","","门脉高压症的常见临床表现是",[["A","黄疸"],["B","蜘蛛痣"],["C","腹水"],["D","牙龈出血"]],"C","门静脉高压症最典型的临床表现为：①脾大、脾功能亢进；②交通支扩张，最有临床意义的是食管-胃底静脉曲张，易破裂发生急性大出血；③腹水/腹腔积液，是门静脉高压最突出的表现（C对）。黄疸（A错）和牙龈出血（D错）为肝硬化肝功能减退失代偿期表现，前者原因为肝细胞广泛坏死，后者系肝脏凝血因子合成减少、脾功能亢进及毛细血管脆性增加导致。蜘蛛痣（B错）为肝硬化致内分泌失调，雌激素过多导致。","","N"],["2023-N154",1,"第二节 慢性阻塞性肺疾病","自发性气胸",2023,154,"X","","男性，76岁。慢性咳嗽、咳痰30余年，活动后气短5年，加重伴发热3天入院。入院后经抗感染对症治疗后症状减轻，今晨突感左胸疼痛，呼吸困难，查体发现左肺呼吸音明显减低。正确的处理措施有",[["A","胸片及心电图检查"],["B","吸氧"],["C","使用镇静药物治疗"],["D","无创呼吸机辅助通气"]],"AB","老年男性患者，咳痰喘多年，活动后加重3天（提示慢性阻塞性肺疾病急性加重期），入院进行抗感染对症治疗后症状好转（COPD急性加重期抗感染治疗有效），今早左胸突发胸痛，呼吸困难，听诊左肺呼吸音消失（气胸临床表现及体征），根据患者病史、临床表现和体征，最可能的诊断是慢性阻塞性肺疾病（COPD）并发自发性气胸，此时需要尽快解除胸腔积气对呼吸、循环造成的不良影响，尽早复张肺和恢复其功能，也要注重并发症和原发病的治疗。本例患者应卧床休息和吸氧（B对），尽量减少活动，有利于气体吸收和肺复张，可酌情给与镇静、镇痛药物（C对），考虑到患者年龄偏大、合并肺部基础疾病，除保守治疗外，需采取排气疗法，采取胸腔闭式引流，如保守治疗无效，胸膜腔内持续出血，需要在抗休克治疗的同时准备外科手术止血。胸片为诊断气胸的重要辅助检查，心电图可以作为是否合并循环系统并发症的辅助检查手段（A对）。本例患者不符合无创呼吸机辅助通气（D错）的指征。本题正确答案为ABC，但标准答案为AB。","","N"],["2023-N155",15,"第三节 急性心力衰竭","洋地黄类药物",2023,155,"X","","急性左心衰竭（急性肺水肿）可选用的治疗药物有",[["A","毛花苷C"],["B","伊伐布雷定"],["C","奈西立肽"],["D","左西孟旦"]],"ACD","伊伐布雷定（B错）为窦房结If电流选择特异性抑制剂，可减慢心率，延长舒张期，改善左心室功能及生活质量，但对心肌收缩力和心脏传导无明显影响，主要用于NYHAⅡ～Ⅳ级稳定的慢性收缩性心衰患者，血流动力学不稳定、急性心衰、严重肝功能不全，病态窦房结综合征、窦性停搏、完全性房室传导阻滞等情况禁用。毛花苷C（洋地黄类药物）（A对）的最佳适应症为有快速心室率的心房颤动并心室扩大伴左心室收缩功能不全者，可减轻低灌注导致的各种症状，保证重要脏器的血供，但急性心梗（特别是发病＜24h），急性心肌炎、低钾血症、≥Ⅱ度房室传导阻滞、甲状腺功能低下者禁用。左西孟旦（D对）属于钙增敏剂，正性肌力作用独立于心脏β₁受体激动作用，也可扩张冠脉和外周血管，减轻心肌缺血和纠正血流动力学紊乱，适用于无显著低血压或低血压倾向的急性左心衰病人。奈西立肽（重组人脑钠肽）（C对）有利钠利尿、降低心脏前后负荷，适度抑制RAAS和内皮素等血管收缩神经激素的作用，可扩张血管，对于纠正急性心衰时的血流动力学异常有较好作用，各国指南均推荐用于急性心衰的治疗。","","N"],["2023-N156",75,"第二节 农药中毒","迅速清除毒物",2023,156,"X","","下列有机磷杀虫药口服中毒时，可用2%碳酸氢钠溶液反复洗胃的有",[["A","对硫磷"],["B","敌百虫"],["C","敌敌畏"],["D","乐果"]],"ACD","口服有机磷农药中毒者，可用清水、2%碳酸氢钠溶液洗胃，留置胃管间断洗胃效果更佳，间隔3～4小时重复洗胃，直至胃液清亮为止，可再用甘露醇或硫酸镁导泻。但因敌百虫（美曲膦酯）在碱性条件下可转化为毒性更强的敌敌畏，故敌百虫中毒时禁用2%碳酸氢钠溶液洗胃（B错）。同时应注意对硫磷中毒禁用高锰酸钾溶液洗胃。","","N"],["2023-N157",41,"","",2023,157,"X","","属于尿路刺激征的有",[["A","尿潴留"],["B","尿急"],["C","尿痛"],["D","排尿困难"]],"BC","尿频、尿急、尿痛和排尿困难（D错）等属于尿路刺激症状，其中尿频、尿急（B对）、尿痛（C对）三者常同时出现，合称为膀胱刺激征/尿路刺激征/尿道刺激征。尿潴留（A错）为排尿困难进一步加重，发展为尿液不能排出在膀胱内滞留的状态。","","N"],["2023-N158",55,"","",2023,158,"X","","可引起APTT延长而TT正常的原因有",[["A","Ⅴ因子缺乏"],["B","Ⅶ因子缺乏"],["C","Ⅸ因子缺乏"],["D","纤维蛋白原减少"]],"AC","凝血因子检测异常总结：①BT（出血时间）异常，提示血管壁或血小板异常，后者为主要因素；②CT（凝血时间）异常、③APTT（活化部分凝血活酶时间）异常，提示内源性凝血因子/凝血途径异常；④PT（凝血酶原时间）异常，提示外源性凝血因子/凝血途径异常；⑤TT（凝血酶时间）异常，提示纤维蛋白原/凝血因子Ⅰ异常。因此，APTT延长，而TT正常说明内源性凝血系统异常，而纤维蛋白原活化为纤维蛋白过程正常（D错），即Ⅷ、Ⅸ（C对）、Ⅺ、Ⅻ因子（内源性凝血因子）+Ⅱ、Ⅴ（A对）、Ⅹ因子（共同途径因子）异常，Ⅲ、Ⅶ因子（B错）为外源性凝血因子，异常时体现为PT延长。","","N"],["2023-N159",61,"第二节 糖尿病酮症酸中毒","胰岛素治疗",2023,159,"X","","关于糖尿病酮症酸中毒的治疗，正确的措施有",[["A","前4小时内输入0.9%氯化钠2000ml"],["B","血糖降至16.7mmol/L时，补液需改用5%葡萄糖生理盐水"],["C","首次胰岛素静注负荷量10～20U，后静脉滴注每小时0.1U/kg"],["D","血pH＜7.1，HCO₃⁻＜5mmol/L时需要补碱治疗"]],"CD","补液是DKA治疗的关键环节，原则为先快后慢，先盐后糖，首选等渗生理盐水（注意不是平衡盐溶液），开始1～2小时内输入1000～2000ml（A错），在第3～6小时输入1000～2000ml，前4小时输入所计算失水量1/3的液体，一般第1个24小时的输液总量为4000～5000ml，严重失水者可达6000～8000ml。胰岛素治疗需要与补液同时进行（应另建输液途径），通常开始以每小时0.1U/kg胰岛素加入生理盐水静脉滴注，加用首次负荷量为静脉注射短效胰岛素10～20U（C对），每1～2小时复查血糖和血酮体，根据血糖和血酮体的情况调整胰岛素用量。第二阶段，当血糖降至13.9mmol/L时，根据血钠情况，补液需改用5%葡萄糖液或葡萄糖生理盐水（B错），同时按比例加入胰岛素，每4～6小时复查血糖，调节胰岛素的用量和比例，并每4～6小时皮下注射短效胰岛素4～6U，使血糖平稳。DKA的酸中毒主要由酮体中酸性物质引起（乙酰乙酸、丙酮等），在进行补液及胰岛素治疗后，酸中毒可随代谢紊乱的纠正而恢复，一般不需要补碱，只有血pH＜7.1，HCO₃⁻＜5mmol/L时，需要补碱治疗（D对），注意过多过快的补碱会产生碱中毒、脑脊液pH反而降低、低钾血症等多种不良反应，补碱药物为NaHCO₃。DKA也会有不同程度的低钾，补钾量需要根据血钾和尿量综合判断。","","N"],["2024-N41",21,"第三节 二尖瓣狭窄","二尖瓣狭窄临床表现",2024,41,"A","","关于典型二尖瓣狭窄心尖部舒张期杂音的听诊特点，正确的是",[["A","多为递增递减型"],["B","为舒张早中期杂音"],["C","向剑突方向传导"],["D","左侧卧位更明显"]],"D","典型的二尖瓣狭窄的特征性的杂音为心尖区舒张中晚期（B错）低调的隆隆样杂音，呈递增性，系舒张晚期心房收缩促使血液流速加快通过狭窄的瓣叶导致，杂音增强（A错），故房颤时，该杂音会减弱或消失；同时杂音局限不传导（C错），左侧卧位时明显（D对）。有关二尖瓣狭窄的其他杂音包括：①Graham-Sleell杂音，为二尖瓣狭窄导致肺动脉高压时，由于肺动脉扩张致相对性肺动脉瓣关闭不全时，在胸骨左缘第2～4肋间可闻及递减型吹风样的舒张早期杂音（属于功能性心脏杂音）；②相对性三尖瓣关闭不全杂音：左心压力升高致右心室扩大时，可发生相对性三尖瓣关闭不全，可闻及收缩期吹风样杂音，吸气时增强。关于心脏瓣膜病典型杂音的归纳口诀为：“二狭隆隆渐增强（舒张），二闭吹风都一样（收缩），主狭喷射增又减（收缩），主闭叹息渐衰亡（舒张）”。","","N"],["2024-N43",2,"第一节 支气管哮喘","气道免疫-炎症机制",2024,43,"A","","关于支气管哮喘疾病本质的叙述，正确的是",[["A","气道不可逆性功能下降"],["B","气道平滑肌β₂受体功能低下"],["C","肥大细胞M胆碱能受体功能亢进"],["D","慢性气道炎症性疾病"]],"D","支气管哮喘疾病本质的是慢性气道炎症（D对）的发生，有嗜酸性粒细胞、肥大细胞、T淋巴细胞、中性粒细胞、平滑肌细胞、呼吸道上皮细胞等细胞及细胞组分参与，表现为反复发作的喘息、气急、胸闷或咳嗽，同时伴有可逆的气流受限（A错）和气道高反应性，随着病程延长可导致气道重塑。支气管哮喘的发生与β肾上腺素能受体功能低下和迷走神经张力亢进密切相关（BC错），二者属于哮喘发生的神经机制，但不属于哮喘的本质特点。","","N"],["2024-N44",4,"第二节细菌性肺炎","肺炎链球菌肺炎诊断",2024,44,"A","","男性，21岁。受凉后高热、寒战伴咳嗽、咳痰2天。查体：T39.8℃，右上肺语颤增强，可闻及湿啰音。血WBC18.3×10⁹/L，N93%。最可能的诊断是",[["A","急性支气管炎"],["B","急性肺脓肿"],["C","肺炎链球菌肺炎"],["D","肺结核"]],"C","青年男性患者，受凉（发病诱因）后出现高热寒战伴咳嗽、咳痰（肺部感染常见表现），查体：T39.8℃（39.1～41℃，高热），右上肺语颤增强，可闻及湿啰音（大叶性肺炎常见体征），血WBC18.3×10⁹/L（＞9.5×10⁹/L），N93%（提示细菌急性感染），根据患者发病诱因、临床表现和体征及实验室检查结果，最可能的诊断是肺炎链球菌肺炎（C对），合格痰标本见典型的成对G⁺球菌。大叶性肺炎的诊断要点是：青壮年患者＋受凉淋雨等诱因＋寒战高热＋铁锈色痰＋口角/鼻周单纯疱疹＋胸片（多为肺实变+支气管充气征等）+支气管呼吸音等体征，目前考试对肺炎链球菌肺炎的治疗首选青霉素。考虑到本例具体临床情况，应与吸入性肺脓肿（非血源性、继发性肺脓肿）鉴别，吸入性肺脓肿（B错）多有误吸史，如脑血管意外、过量饮酒等意识不清情况、拔牙等，咳大量脓臭痰（静置分三层）是重要表现及鉴别点，影像学胸片可见圆形透亮区及气液平，其四周被浓密炎症浸润所环绕，同时当肺炎使用抗生素治疗后高热不退、咳嗽咳痰加剧且咳大量脓臭痰应考虑肺脓肿可能性。急性支气管炎（A错）常发生于寒冷季节或气温突然变冷时，常常先有上呼吸道感染症状，如发热、头痛、鼻塞、流涕、咽痛、声音嘶哑等，常起病较急，全身症状较轻，可有发热（一般为低到中度发热），咳嗽是最主要的症状，一般持续至少5天，大多数患者可持续1～3周，初为干咳或少量黏痰，随后痰量增多，咳嗽加剧，偶伴痰中带血，X线胸片大多为肺纹理增强。此处补充一个相关知识点：欧洲呼吸病学会下呼吸道感染指南认为，急性咳嗽患者，同时伴有新出现的局限性实变体征，加上发热＞4天或呼吸困难／呼吸急促，而没有其他原因可以解释时需要怀疑肺炎。肺结核（D错）发热类型多为长期午后低热，可伴有倦怠、乏力、夜间盗汗等结核杆菌感染全身表现，可有咯血和胸痛，体征取决于病变性质、部位、范围或程度，痰涂片找到抗酸杆菌绝大多数为结核杆菌，可以提示诊断。","","N"],["2024-N45",6,"第一节 肺结核","肺结核诊断",2024,45,"A","","男性，56岁。低热、盗汗伴咳嗽、咳痰2月余。既往吸烟30年，20支/日。查体：体型消瘦，浅表淋巴结无肿大，双肺听诊无异常。血WBC8.0×10⁹/L，N59%，肺部X线片示“左上肺密度不均匀片状影”。最可能的诊断是",[["A","肺结核"],["B","肺炎"],["C","肺脓肿"],["D","肺癌"]],"A","中年男性患者，低热、盗汗伴咳嗽、咳痰2月余（迁延不愈咳嗽咳痰、长期低热，提示结核杆菌感染），吸烟30年，20支/日（吸烟易诱发气道炎症，降低呼吸系统免疫力），查体：体型消瘦（结核病全身表现），浅表淋巴结无肿大，肺部听诊无异常（暂时排除肺部其他感染性疾病），WBC8.0×10⁹/L，N59%（暂排除其他急性感染），肺部X线示“左上肺密度不均匀片状影”（肺结核可有影像学表现），根据患者病史、临床表现和体征及影像学检查结果，最可能的诊断是肺结核（A对）。肺结核的诊断依赖病原学检查，但病史和临床表现仍然是诊断的基础，凡遇下列情况者应高度警惕结核病的可能性：①反复发作或迁延不愈的咳嗽咳痰或呼吸道感染经抗生素治疗3～4周仍无改善；②痰中带血或咯血；③长期低热或所谓“发热待查”；④体检肩胛间区有湿啰音或局限性哮鸣音；⑤有结核病诱因或好发因素，尤其是糖尿病、免疫抑制性疾病和接受激素或免疫抑制剂治疗者；⑥有关节疼痛和皮肤结节性红斑、滤泡性结膜角膜炎等过敏反应性表现；⑦有渗出性胸膜炎、肛瘘、长期淋巴结肿大既往史以及婴幼儿和儿童有家庭开放性肺结核密切接触史者。肺炎（B错）与肺结核的鉴别的关键证据是病原学检测，临床表现方面如细菌性肺炎一般起病较急，高热寒战，伴有胸痛，血白细胞总数及中性粒细胞增多，抗菌药物治疗有效，可资鉴别。肺脓肿（C错）影像学可见空洞，多见于肺下叶（结核空洞多为上叶，主要与厌氧菌和结核杆菌对氧气的需求有关），脓肿周围的炎症浸润较严重，空洞内常有液平面，肺脓肿起病较急、高热、脓臭痰，但痰中无结核菌，血白细胞总数及中性粒细胞增多，抗生素治疗有效。肺癌（D错）多表现为刺激性咳嗽、胸痛和进行性消瘦，中央型肺癌可有痰中带血，影像学肺癌病灶边缘常见切迹、毛刺，胸部CT有助于二者鉴别，结合痰结核菌、脱落细胞检查及纤维支气管镜检查和活检等能及时鉴别，需要注意的是肺癌和肺结核可有并存。","","N"],["2024-N46",15,"第三节 急性心力衰竭","机械辅助循环支持装置",2024,46,"A","","男性，78岁。6小时前在睡眠中突发胸痛，有明显压迫感，自含硝酸甘油2片，症状稍有缓解。2小时前胸痛再次加重，持续不缓解伴呼吸困难而来院。既往有高血压病20年，糖尿病18年。查体：R20次/分，BP88/50mmHg，口唇发绀，双肺满布湿啰音，心率106次/分，心律齐，心音低钝，四肢末梢皮肤湿凉。心电图示V₂₋₆、Ⅰ、aVL导ST段水平下移0.2～0.4mV，T波倒置，cTnT 1.58μg/L。对该患者应采取的治疗措施是",[["A","即刻静脉补液扩容，提升血压"],["B","在使用升压药的同时，即刻溶栓治疗"],["C","即刻在置入IABP同时行冠脉介入治疗"],["D","即刻给予血管扩张剂及利尿剂，控制心衰"]],"C","老年男性患者，6小时前在睡眠中突发胸痛，有明显压迫感（静息型心绞痛表现），自含硝酸甘油2片，症状稍有缓解（提示静息型心绞痛），2小时前胸痛再次加重（2小时提示血运重建治疗时间窗），持续不缓解伴呼吸困难而来院（提示急性心肌梗死），既往有高血压病20年，糖尿病18年（发病诱因）。查体：R20次/分，BP88/50mmHg（＜90/60mmHg，提示休克），口唇发绀，双肺布满湿啰音（急性左心衰表现），心率106次/分（＞100次/分，提示心功能受损），心律齐，心音低钝，四肢末梢皮肤湿冷（心源性休克表现，提示NSTEMI高危）。心电图示V₂₋₆、Ⅰ、aVL导联ST段水平下移0.2～0.4mV，T波倒置（心电图提示NSTEMI高危型），cTnT 1.58μg/L（心肌肌钙蛋白＞0.5μg/L，诊断AMI），根据患者病史，临床表现和体征，实验室检查和临床表现，最可能的诊断是：1.NSTEMI，高度危险性；2.急性左心衰，Killip分级Ⅳ级。目前针对该患者应即刻采取的治疗措施是采取血运重建术，对其心源性休克（低血压）情况，应在主动脉内球囊反搏（IABP）辅助下施行PCI（C对），改善心肌灌注，降低心肌耗氧，增加心输出量的同时血运重建。该患者此时不宜即刻静脉补液扩容，易导致急性左心衰加重（A错）。本例患者NSTEMI并发心源性休克，禁扩血管及利尿，会导致血压进一步下降（D错）。NSTEMI时影响冠脉堵塞的主要因素是白色血栓，其主要成分是血小板，故不能进行溶栓治疗（B错），溶栓后不但无法使血管再通，还会继发性地激活凝血，导致病情加重。对NSTEMI的治疗总结：低危首选“双抗治疗”（抗血小板+抗凝），低危不建议常规介入治疗，但中、高危首选PCI，有心源性休克（血压低）等血流动力学不稳定情况首选主动脉内球囊反搏（IABP），NSTEMI禁用溶栓治疗。","","N"],["2024-N47",17,"第一节 动脉粥样硬化","动脉粥样硬化心电图",2024,47,"A","","最能反映存在急性心肌缺血的辅助检查结果是",[["A","冠状动脉造影显示血管狭窄＞70%"],["B","心电图出现ST-T动态改变"],["C","超声心动图出现弥漫性室壁运动减弱"],["D","监测血压出现收缩压波动超过40mmHg"]],"B","心肌缺血和心肌的需氧（供血）是辩证统一的两个方面，正常情况下，二者在神经和体液的调节下保持动态平衡，维持机体的正常运转。当冠脉狭窄＜50%时，心肌的血供不受到影响，患者没有症状，各种心脏负荷试验也无心肌缺血的表现；当冠状动脉管腔狭窄＞50%～75%时，机体安静时尚能代偿，但因运动、心动过速、情绪激动造成心肌需氧量增加时，则会导致短暂的心肌供氧和需氧间的不平衡，称为“需氧增加性心肌缺血”——大多数慢性稳定型心绞痛发作的机制，因此在未明确心肌需氧的前提下，“冠状动脉造影显示血管狭窄＞70%”这一单方面的表述不能反映存在心肌缺血（A错），只能直接反映冠脉的狭窄程度。超声心动图可以直观反映心脏和大血管的结构形态，实时显示其生理活动情况，动态评估心功能，是评价心脏收缩、舒张功能以及左心室充盈血流动力学的主要定量手段，但“超声心动图出现弥漫性室壁运动减弱”（C错）可能是心肌缺血的结果，但心肌病也是引起弥漫性室壁运动减弱的重要原因。一般情况下，收缩压的高低主要反映心脏每搏量的多少，监测血压出现收缩压波动超过40mmHg（D错），提示心脏泵功能的病变，但影响心脏泵功能的因素包括各种神经、体液因素，心肌病变，血管病变等。心肌缺血会导致缺血区心肌的复极延迟，从而引起缺血区相关导联的ST-T异常改变。动态心电图是一种日常生活中研究心肌缺血非常有价值的诊断工具，对于无症状心肌缺血尤其有意义。然而，需要注意的是，仅凭动态心电图上的ST段压低来诊断心肌缺血似乎不太妥当，因此，在评估动态心电图上ST段缺血型改变的临床意义之前，应在进行动态心电图监测之前先进行一份常规心电图，以便做出比较。综上所述，最能反映存在心肌缺血的辅助检查结果是心电图出现ST-T动态改变（B对）。但心电图不能直接反映心脏的收缩功能。","","N"],["2024-N48",16,"第六节 心脏传导阻滞","房室传导阻滞治疗",2024,48,"A","","女性，78岁。1年来明显乏力，活动时曾多次出现短暂黑朦。2小时前突发头晕，随即出现短暂意识不清10余秒钟。神志恢复后感胸闷、乏力，急送来院。查体：P40次/分，BP110/60mmHg，平卧位，口唇无发绀，双肺（-），心界不大，心率42次/分，心律不齐，第一心音强弱不等，各瓣膜听诊未闻及杂音，腹部（-），心电图如下。该患者最佳的治疗措施是",[["A","静脉给予地塞米松"],["B","静脉推注阿托品"],["C","置入临时心脏起搏器"],["D","植入永久心脏起搏器"]],"D","老年女性患者，发生无明显诱因的乏力和活动时的短暂黑朦一年，2个小时前再次出现头晕伴短暂意识障碍（结合题干考虑为心源性脑供血不足），查体：P40次/分（正常脉率：60～100次/分），BP110/60mmHg（血压正常值为90～139mmHg/60～89mmHg，血压正常），心率42次/分（心率＞脉率，脉搏短绌），心律不齐，第一心音强弱不等（房颤的主要临床体征），根据患者的病史、临床表现和体征、心电图检查结果，目前患者的情况为：1.房颤；2.三度房室传导阻滞，应选择的最佳治疗方法为植入永久心脏起搏器（D对）。起搏治疗主要用于纠正心率和心律的异常，永久心脏起搏器适用于长期缓慢心率的患者，如病态窦房结综合征、高度房室传导阻滞等，需要长期工作以维持正常心率，该患者此前出现多次黑朦，本次发病出现10余秒钟的意识不清，植入的永久心脏起搏器不仅能够纠正本次的低心室率，也能在患者日常生活中感知到心脏自身的电活动、调整起搏频率以适应患者的需求。临时起搏器（C错）通常不具有调节心率的功能，只是简单地提供固定的起搏频率，主要适用于临时性支持治疗，如心脏骤停、严重心动过缓、急性心肌梗死合并房室传导阻滞等，可以在短时间内维持心率的稳定，当患者病情稳定后，临时起搏器需要尽快取出。静脉给予地塞米松（A错）主要有抗炎、抗毒、抗过敏、抗休克等作用，通常不用于治疗房颤和房室传导阻滞。静脉推注阿托品（B错）可提高房室阻滞的心率，仅适用于无心脏起搏条件的应急情况。","","N"],["2024-N49",15,"第二节 慢性心力衰竭","β受体拮抗剂",2024,49,"A","","慢性心力衰竭应用β受体拮抗剂的最主要目的是",[["A","延缓疾病进展"],["B","控制心室率"],["C","控制心律失常"],["D","减少体液潴留"]],"A","心力衰竭是一种进展性疾病，表现为渐进性心室重构，当心脏排血不足、心腔内压力升高时，机体全面启动神经-体液-免疫机制进行代偿，三大系统之间发生相互作用，促使心肌重构渐进性进展，因此在治疗中，针对体液潴留应用利尿剂（D错），针对血流动力学异常应用强心药和扩血管药物，以上治疗为改善心衰患者的症状；针对神经-内分泌系统异常激活（主要是交感神经系统和RAS系统）应用相应的激素拮抗剂，改善患者预后，延缓病情进展。对炎症免疫异常激活，采取免疫调节治疗。临床试验证明神经-体液拮抗剂能够降低心衰患者的死亡率，这些药物不仅抑制神经-体液因子的活性，还能够调节细胞因子和氧化应激活性，改善衰竭心脏的生物学功能，从而延缓心室重构，此类药物包括β受体阻滞剂、RAS系统拮抗剂（ACEI/ARB、醛固酮受体拮抗剂），故慢性心力衰竭应用β受体阻滞剂的主要目的是延缓疾病进展（A对），减缓心室重塑的病理过程。β受体阻滞剂可以阻断心脏β₁受体，对部分心律失常有缓解作用，但不是其在慢性心衰治疗中应用的主要目的。","","N"],["2024-N50",30,"第一节 溃疡性结肠炎","溃疡性结肠炎实验室和其他检查",2024,50,"A","","下列不属于判断溃疡性结肠炎病情严重程度的指标是",[["A","每日大便次数"],["B","体温高低"],["C","外周血血红蛋白浓度"],["D","外周血白细胞计数"]],"D","溃疡性结肠炎病情严重程度的指标包括：每日大便次数（A对）、体温高低（是否发热）（B对）、外周血血红蛋白浓度（是否贫血）（C对）、脉搏、是否血便、血沉。目前临床评价溃疡性结肠炎疾病活动度使用改良的Truelove和Witts严重程度分型标准（包括以上六种指标）。临床科研常用Mayo评分或部分Mayo评分以定量评价疾病活动度（包括排便次数、便血、内镜发现和医师总体评价指标）。外周血白细胞计数（D错，为本题正确答案）在溃疡性结肠炎活动期可有升高，但不作为病情严重程度的指标。","","N"],["2024-N51",29,"第一节 肠结核","肠结核诊断",2024,51,"A","","男性，58岁。右下腹痛、腹泻伴关节酸痛、低热半年。查体：T37.5℃，心肺检查未见异常，腹软，右下腹触及可疑肿块。钡剂灌肠检查提示回盲部跳跃征。最可能的诊断是",[["A","肠结核"],["B","克罗恩病"],["C","阿米巴肠炎"],["D","肠淋巴瘤"]],"A","中老年男性患者，右下腹痛、腹泻（肠结核常见表现）伴关节酸痛、低热半年（疑结核毒血症状）。查体：T37.5℃（37.3～38℃，低热），心肺检查未见异常，腹软，右下腹触及可疑性肿块（肠结核常见体征）。钡剂灌肠检查提示回盲部跳跃征（肠结核典型X线钡剂灌肠表现），根据患者病史、临床表现和体征及影像学检查结果，最可能的诊断是肠结核（A对），对肠结核的诊断，出现以下几个方面时应予以考虑：①中青年病人有肠外结核，主要是肺结核；②有腹痛、腹泻、便秘等消化道症状；右下腹压痛、腹块或原因不明的肠梗阻，伴有发热、盗汗等结核毒血症状；③X线钡剂检查发现跳跃征、溃疡、肠管变形和肠腔狭窄等征象；④结肠镜检查发现主要位于回盲部的炎症、溃疡、炎性息肉或肠腔狭窄；⑤结核菌素试验强阳性或γ-干扰素释放试验阳性。如肠黏膜病理活检发现干酪性肉芽肿，具有确诊意义；活检组织中找到抗酸杆菌有助于诊断。克罗恩病（B错）的临床表现、肠道造影和内镜与肠结核非常相似，克罗恩病多有家族史，可有肛门直肠周围病变如肛周脓肿、肛瘘、肠穿孔等并发症，或伴有口腔溃疡、结节性红斑、虹膜睫状体炎等，鉴别困难者可先行诊断性抗结核治疗2～3周，密切观察临床症状和炎症指标，有助于判明诊断，但需注意耐药菌株和抗结核药物不良反应。阿米巴肠炎（C错）既往有相应感染史，常见脓血便，粪便常规或孵化检查可发现有关病原体，结肠镜检查有助鉴别，同时相应特效治疗有效。肠淋巴瘤（D错）多有慢性腹痛或便血、贫血、发热、体重下降，甚至肠梗阻、肠穿孔，CT多表现为局部肿块膨胀型生长，常伴有肠系膜和腹膜淋巴结肿大，肠镜下结肠病灶或淋巴结活检多可确诊。","","N"],["2024-N52",35,"第一节 肝硬化","肝硬化代偿期",2024,52,"A","","肝硬化代偿期可见到的临床表现是",[["A","男性乳房发育"],["B","皮肤巩膜黄染"],["C","贫血和出血"],["D","脾大"]],"D","临床上将肝硬化大致分为肝功能代偿期和失代偿期，肝硬化代偿期大部分无明显症状或症状较轻，如腹部不适、乏力、食欲减退、消化不良和腹泻等症状，多呈间歇性，一般情况下早期肝脏可轻度肿大，晚期肝脏可缩小，脾脏因门静脉高压常有轻、中度肿大（D对），肝功能可正常或轻度异常。男性乳房发育（A错）、皮肤巩膜黄染（B错）、贫血和出血（C错）属于肝硬化失代偿期肝功能减退的表现，肝硬化失代偿期还包括门静脉高压的表现（门腔侧支循环形成、脾功能亢进及脾大、腹腔积液）。故脾大既属于肝硬化代偿期的表现，也是肝硬化失代偿期门静脉高压的表现。","","N"],["2024-N53",41,"第一节 尿路感染","尿液检查",2024,53,"A","","女性，36岁。尿频、尿急、尿痛2天，不伴畏寒、发热。既往体健。查体：T36.9℃，双肾区叩击痛阴性。该患者尿化验检查最不可能出现的结果是",[["A","蛋白微量"],["B","沉渣镜检可见WBC20～30个/HP"],["C","沉渣镜检可见白细胞管型"],["D","培养可有大肠埃希菌"]],"C","中青年女性患者，尿频、尿急、尿痛2天（尿路刺激征，提示尿路感染），不伴畏寒、发热（提示下尿路感染），查体：T36.9℃（未发热），双肾区叩击痛阴性（暂排除上尿路感染），根据患者临床表现和体征，最可能的诊断是尿路感染，急性膀胱炎，暂排除是急性肾盂肾炎（上尿路感染），因此该患者尿化验检查最不可能出现的结果是尿沉渣镜检可见白细胞管型（C错，为本题正确答案）。尿沉渣镜检可见WBC20～30个/HP（WBC＞5/HP为白细胞尿）（B对）、尿培养可有大肠埃希菌（D对）均提示尿路感染，但无助于定位诊断。尿路感染时，尿蛋白阴性或有微量尿蛋白（A对），无诊断特异性。","","N"],["2024-N54",50,"第六节 阵发性睡眠性血红蛋白尿症","阵发性睡眠性血红蛋白尿症诊断",2024,54,"A","","男性，47岁。2个月来乏力、头晕、间断尿色加深，1周来加重入院。既往2年前曾患再生障碍性贫血，经治疗血常规恢复正常。入院时血常规：Hb65g/L，Ret12%，WBC3.4×10⁹/L，Plt60×10⁹/L；尿沉渣镜检RBC阴性，隐血试验阳性；血清铁5.25μmol/L，血清铁蛋白8ug/L。该患者目前最可能的诊断是",[["A","巨幼细胞性贫血"],["B","缺铁性贫血"],["C","自身免疫性溶血性贫血"],["D","阵发性睡眠性血红蛋白尿症"]],"D","中年男性患者（PNH高发人群），乏力，头晕2个月（贫血可有临床表现），间断尿色加深（提示溶血），1周来加重入院。既往2年前曾患再生障碍性贫血（提示骨髓造血异常，可能诱因），经治疗血常规恢复正常。入院时血常规：Hb65g/L（男性Hb正常值130～175g/L，本例属中度贫血），Ret12%（正常值0.5%～1.5%，本例提示骨髓红系增生旺盛），WBC3.4×10⁹/L（正常值3.5～9.5×10⁹/L，减少），Plt60×10⁹/L（正常值125～350×10⁹/L，减少）；尿沉渣镜检RBC阴性，隐血试验阳性（提示尿液中有血红蛋白，提示血管内溶血）；血清铁5.25μmol/L（男性正常值10.6～36.7μmol/L，减少），血清铁蛋白8ug/L（男性正常值15～200μg/L，减少），本例患者病程不长，短期内出现尿色加深等血红蛋白尿表现，无明显黄疸表现，并有再生性障碍性贫血病史，血象提示三系减少，骨髓红系增生活跃，故该患者目前最可能的诊断是阵发性睡眠性血红蛋白尿/PNH（D对），Ham试验（+），PNH诊断的金标准为血细胞表型分析CD55和CD59试验，需要注意的是，PNH与再生障碍性贫血关系密切如本例所示，可互相转化，称为再障-PNH综合征或PNH-再障综合征；同时因PNH长期血管内溶血、尿液丢失血红蛋白（Fe）增加，可导致机体缺铁，故本例中血清铁和血清铁蛋白均下降，需与缺铁性贫血（B错）鉴别，后者多发生于儿童和育龄期女性，白细胞和血小板计数大多在正常范围，成人因慢性失血导致缺铁性贫血，可见血小板计数增高，且无溶血性贫血表现如尿色加深、黄疸等。巨幼细胞性贫血（A错）一种主要由叶酸和（或）维生素B₁₂缺乏所致的大细胞性贫血，属于骨髓内溶血（血管外），故部分患者可有轻度黄疸，可有“牛肉舌”等表现，骨髓检查可见“核幼浆老”，叶酸和维生素B₁₂水平测定可帮助诊断。自身免疫性溶血性贫血（C错）多为血管外溶血，女性多见，以贫血、黄疸和脾大为特征，白细胞及血小板多正常，临床表现从无明显溶血至致命性溶血不等。","","N"],["2024-N55",60,"第二节 原发性醛固酮增多症","原发性醛固酮增多症诊断与病因诊断",2024,55,"A","","对确诊原发性醛固酮增多症最有价值的实验室检查结果是",[["A","尿PH偏碱性，比重在1.010～1.018"],["B","血浆醛固酮/血浆肾素活性比值＞50"],["C","尿钾＞25mmol/24小时"],["D","血pH和CO₂结合力高于正常"]],"B","原发性醛固酮增多症的诊断包括三大步骤（2008年美国内分泌学原醛症诊治指南），即检出（或称筛查）试验、确诊试验和分型试验。检出试验主要为血浆醛固酮／肾素比值，＞50具有诊断意义（B对）；确诊试验主要包括钠负荷试验、生理盐水负荷试验、氟氢化可的松抑制试验和卡托普利激发试验，分型试验方法主要包括肾上腺B超、CT或MRI影像学检查结合肾上腺静脉插管采血及地塞米松抑制试验等。尿pH偏碱性，比重在1.010～1.018（A错）、尿钾＞25mmol/24h（C错）、血pH和CO₂结合力高于正常（D错）均为原醛症会出现的实验室检查结果，但不具有确诊意义。","","N"],["2024-N56",72,"","",2024,56,"A","","痛风性关节炎最常见的首发病变部位是",[["A","第一跖趾关节"],["B","远端指间关节"],["C","近端指间关节"],["D","掌指关节"]],"A","痛风是嘌呤代谢紊乱和（或）尿酸排泄障碍所致的一组异质性疾病，其临床特征为血清尿酸升高、反复发作性急性关节炎、痛风石及关节畸形、尿酸性肾脏病变等。痛风性关节炎最常见的首发病变部位是第一跖趾关节（A对）。远端指间关节（B错）累及常见于骨关节炎，近端指间关节（C错）、掌指关节（D错）累及常见于类风湿关节炎。","","N"],["2024-N68",10,"第三节 慢性肺源性心脏病","呼吸衰竭",2024,68,"A","","男性，75岁。患慢性阻塞性肺疾病30年，多次因肺部感染住院治疗。3天来发热，咳喘加重，意识模糊，腹胀明显伴尿少，双下肢水肿。既往否认高血压病、糖尿病病史；吸烟55年，20支/日。查体：T38.5℃，P96次/分，R24次/分，BP115/68mmHg，半卧位，嗜睡状态，口唇发绀，颈静脉充盈，双肺叩诊过清音，双肺底位于肩胛线第11肋间，双肺可闻及散在干湿啰音。该患者胸部还可能出现的体征是",[["A","双肺语颤减弱"],["B","双侧胸部呼吸运动不对称"],["C","双肺可闻及管状呼吸音"],["D","双肺肺泡呼吸音增强"]],"A","老年男性患者，30年慢阻肺病史，有过多次AECOPD病史（肺心病原发病因），发热，咳喘加重（感染加重表现），意识模糊（提示病情严重），腹胀明显伴尿少（腹腔积液＋少尿，提示右心衰竭严重），双下肢水肿3天（提示右心衰竭），查体：T38.5℃（＞37℃，中度发热），P96次/分（脉搏加快），R24次/分（成人正常呼吸频率12～20次/分），BP115/68mmHg（＜120/80mmHg，血压降低），半卧位，嗜睡状态（疑肺性脑病），口唇发绀（缺氧，提示呼吸衰竭），颈静脉充盈（右心衰竭体征），双肺叩诊过清音（COPD体征），双肺底位于肩胛线第11肋间（肺下界下移，COPD体征），双肺可闻及散在干湿啰音（提示肺部感染），根据患者病史、临床表现和体征，该患者拟诊断为：1.AECOPD，2.右心衰竭。语音震颤的强弱与气道是否通畅以及胸壁传导性有关，能反映胸内病变的性质。本例患者多年COPD，且处于急性加重期，有肺部感染情况存在，会影响肺部语音传导，导致双肺语颤减弱（A对）。双侧胸部呼吸运动不对称（B错）多见于一侧胸廓多根肋骨骨折，吸气时健侧胸廓扩大，患侧胸廓反而内陷，呼气时健侧回缩，患侧外突。管状呼吸音（C错）即异常支气管呼吸音，为气流通过声门、气管和支气管的湍流声，当气流通过实变的肺组织、发生压迫性肺不张等情况时，又或者肺内出现大空腔如肺脓肿、空洞型肺结核等，可在肺泡呼吸音的部位听到管状呼吸音。肺泡呼吸音（D错）在病理情况下多见于发热、代谢亢进、贫血、酸中毒等情况，原因为呼吸运动增加，肺泡通气增加或流速增快，本例患者虽有呼吸增加，但因其原发病，肺泡通气量不足，肺泡呼吸音减弱，系通气阻力增加所致。","c196","N"],["2024-N69",10,"第三节 慢性肺源性心脏病","慢性肺源性心脏病心电图检查",2024,69,"A","","男性，75岁。患慢性阻塞性肺疾病30年，多次因肺部感染住院治疗。3天来发热，咳喘加重，意识模糊，腹胀明显伴尿少，双下肢水肿。既往否认高血压病、糖尿病病史；吸烟55年，20支/日。查体：T38.5℃，P96次/分，R24次/分，BP115/68mmHg，半卧位，嗜睡状态，口唇发绀，颈静脉充盈，双肺叩诊过清音，双肺底位于肩胛线第11肋间，双肺可闻及散在干湿啰音。该患者最可能的心电图改变是",[["A","窦性心律，左心房增大，不完全性右束支传导阻滞"],["B","窦性心律，右心房增大，完全性左束支传导阻滞"],["C","窦性心律，右心房增大，右心室肥厚"],["D","窦性心律，左心房增大，左心室肥厚"]],"C","老年男性患者，30年慢阻肺病史，有过多次AECOPD病史（肺心病原发病因），发热，咳喘加重（感染加重表现），意识模糊（提示病情严重），腹胀明显伴尿少（腹腔积液＋少尿，提示右心衰竭严重），双下肢水肿3天（提示右心衰竭），查体：T38.5℃（＞37℃，中度发热），P96次/分（脉搏加快），R24次/分（成人正常呼吸频率12～20次/分），BP115/68mmHg（＜120/80mmHg，血压降低），半卧位，嗜睡状态（疑肺性脑病），口唇发绀（缺氧，提示呼吸衰竭），颈静脉充盈（右心衰竭体征），双肺叩诊过清音（COPD体征），双肺底位于肩胛线第11肋间（肺下界下移，COPD体征），双肺可闻及散在干湿啰音（提示肺部感染），根据患者病史、临床表现和体征，该患者拟诊断为：1.AECOPD，2.右心衰竭。该患者的基本病理过程为长期缺氧致肺动脉高压，再导致右心室肥厚、增大（以右心室病变为主），压力继续传导至右心房肥厚、增大，故此时患者最可能的心电图改变是肺心病心电图改变，即窦性心律，右心房增大，右心室肥厚（C对）。肺心病较少累及左心（AD错）。需要注意的是，不完全性或完全性右束支传导阻滞（B错）属于肺心病心电图诊断标准的次要条件（3版8年制内科学P132）。","c196","N"],["2024-N70",10,"第三节 慢性肺源性心脏病","慢性肺源性心脏病血气分析",2024,70,"A","","男性，75岁。患慢性阻塞性肺疾病30年，多次因肺部感染住院治疗。3天来发热，咳喘加重，意识模糊，腹胀明显伴尿少，双下肢水肿。既往否认高血压病、糖尿病病史；吸烟55年，20支/日。查体：T38.5℃，P96次/分，R24次/分，BP115/68mmHg，半卧位，嗜睡状态，口唇发绀，颈静脉充盈，双肺叩诊过清音，双肺底位于肩胛线第11肋间，双肺可闻及散在干湿啰音。该患者最可能的动脉血气分析结果（未吸氧条件下）是",[["A","PaO₂降低，PaCO₂降低，pH下降"],["B","PaO₂正常，PaCO₂降低，pH升高"],["C","PaO₂正常，PaCO₂增高，pH升高"],["D","PaO₂降低，PaCO₂增高，pH下降"]],"D","老年男性患者，30年慢阻肺病史，有过多次AECOPD病史（肺心病原发病因），发热，咳喘加重（感染加重表现），意识模糊（提示病情严重），腹胀明显伴尿少（腹腔积液＋少尿，提示右心衰竭严重），双下肢水肿3天（提示右心衰竭），查体：T38.5℃（＞37℃，中度发热），P96次/分（脉搏加快），R24次/分（成人正常呼吸频率12～20次/分），BP115/68mmHg（＜120/80mmHg，血压降低），半卧位，嗜睡状态（疑肺性脑病），口唇发绀（缺氧，提示呼吸衰竭），颈静脉充盈（右心衰竭体征），双肺叩诊过清音（COPD体征），双肺底位于肩胛线第11肋间（肺下界下移，COPD体征），双肺可闻及散在干湿啰音（提示肺部感染），根据患者病史、临床表现和体征，该患者拟诊断为：1.AECOPD，2.右心衰竭。慢阻肺最重要的病理生理改变是气道阻塞和气流受限，即引起阻塞性通气功能障碍，随着疾病进展，大量肺泡壁断裂导致肺泡毛细血管破坏或挤压，导致该区域有通气但无血流，生理无效腔增大；也有部分肺区域因通气障碍，不能参与气体交换，产生肺内分流，以上均会导致通气/血流比例失调，肺内气体交换效率明显下降；而此时肺泡和毛细血管的大量破坏也使肺弥散面积大大减少，进一步导致换气功能障碍。这些病理生理改变最终引起肺通气和换气障碍，导致缺氧和二氧化碳潴留，发生不同程度的低氧血症和高碳酸血症，最终发生呼吸衰竭，继发慢性肺源性心脏病。因此，本例患者血气分析（未吸氧条件下）最可能的结果是PaO₂降低，PaCO₂增高，pH下降（D对）。","c196","N"],["2024-N71",40,"","",2024,71,"A","","女性，18岁。3周前出现颜面水肿，晨起明显，伴头晕、乏力，尿量明显减少。2周来水肿明显加重并延伸至双下肢，心悸，食欲差伴恶心。既往半年来反复上感、咽痛，月经周期不规律。查体：T37.1℃，P110次/分，BP160/90mmHg，营养稍差，巩膜无黄染，双眼睑及颜面部明显水肿，咽红，扁桃体Ⅱ度肿大，双肺（-），心律齐，心音正常，肝脾肋下未触及，双下肢可凹性水肿（++）。该患者水肿最可能的类型是",[["A","心源性水肿"],["B","肾源性水肿"],["C","肝源性水肿"],["D","营养不良性水肿"]],"B","青年女性患者，出现颜面部水肿3周，晨起明显，加重并延伸至下肢2周（提示肾性水肿），尿量明显减少（提示肾功能损伤），有头晕、乏力、心悸、纳差、恶心等全身症状及消化道症状，半年来反复上感、咽痛（提示发病诱因），查体T37.1℃（大于37℃，体温稍高），P110次/分（＞100次/分，脉搏加快），BP160/90mmHg（收缩压＞140mmHg，高血压），营养稍差，巩膜无黄染（暂排除肝源性病理原因），双眼睑及眼面部明显水肿，咽红，扁桃体Ⅱ度肿大（提示感染诱因），双肺（-），心律齐，心音正常，肝脾肋下未触及（暂排除心源性病理原因），双下肢可凹性水肿（++）（肾源性水肿为凹陷性水肿），根据患者病史、临床表现和体征，该患者最可能的诊断是急性肾小球肾炎，其水肿类型为肾源性水肿（B对），基本发生机制是水钠潴留。心源性水肿（A错）的特点是从足部开始，向上延及全身，且发展较为缓慢，水肿性质比较坚实，移动性较小，同时可伴有心脏增大、心脏杂音、肝大、静脉压升高等表现。肝源性水肿（C错）最常见的原因是肝硬化，主要表现为腹腔积液，也可首先出现踝部水肿，逐渐向上蔓延，而头、面部及上肢常无水肿。营养不良性水肿（D错）特点是水肿发生前常有体重减轻表现，皮下脂肪减少可致组织松弛，组织压降低，加重水肿液的潴留，水肿常从足部开始逐渐蔓延至全身。","c197","N"],["2024-N72",40,"第一节 肾小球疾病概述","水肿",2024,72,"A","","女性，18岁。3周前出现颜面水肿，晨起明显，伴头晕、乏力，尿量明显减少。2周来水肿明显加重并延伸至双下肢，心悸，食欲差伴恶心。既往半年来反复上感、咽痛，月经周期不规律。查体：T37.1℃，P110次/分，BP160/90mmHg，营养稍差，巩膜无黄染，双眼睑及颜面部明显水肿，咽红，扁桃体Ⅱ度肿大，双肺（-），心律齐，心音正常，肝脾肋下未触及，双下肢可凹性水肿（++）。导致该患者水肿最主要的机制是",[["A","血浆胶体渗透压降低"],["B","营养障碍"],["C","淋巴回流障碍"],["D","钠、水潴留"]],"D","青年女性患者，出现颜面部水肿3周，晨起明显，加重并延伸至下肢2周（提示肾性水肿），尿量明显减少（提示肾功能损伤），有头晕、乏力、心悸、纳差、恶心等全身症状及消化道症状，半年来反复上感、咽痛（提示发病诱因），查体T37.1℃（大于37℃，体温稍高），P110次/分（＞100次/分，脉搏加快），BP160/90mmHg（收缩压＞140mmHg，高血压），营养稍差，巩膜无黄染（暂排除肝源性病理原因），双眼睑及颜面部明显水肿，咽红，扁桃体Ⅱ度肿大（提示感染诱因），双肺（-），心律齐，心音正常，肝脾肋下未触及（暂排除心源性病理原因），双下肢可凹性水肿（++）（肾源性水肿为凹陷性水肿），根据患者病史、临床表现和体征，该患者最可能的诊断是急性肾小球肾炎，其水肿类型为肾源性水肿，基本发生机制是水钠潴留（D对），发生肾小球肾炎时，肾小球滤过率下降，但肾小管重吸收功能基本正常，故造成“球-管失衡”和肾小球滤过分数（肾小球滤过率/肾血浆流量）下降，导致水钠潴留，此时血容量常增加，血压升高，肾素－血管紧张素－醛固酮系统活性抑制、抗利尿激素分泌减少，毛细血管通透性增加等因素可使肾性水肿持续和加重。血浆胶体渗透压降低（A错）一般为血浆蛋白减少导致，是营养不良或某些肝肾疾病水肿的主要原因。淋巴回流障碍（C错）多产生局部性水肿。营养障碍（B错）是营养不良性水肿的主要原因。","c197","N"],["2024-N73",9,"第一节 肺血栓栓塞症","V_Q显像",2024,73,"A","","女性，68岁。股骨颈骨折术后第7天，突发呼吸困难1小时。查体：P90次/分，R24次/分，BP120/80mmHg，神清，右肺呼吸音低，偶闻及湿啰音。临床疑诊为肺血栓栓塞症。血生化检查Cr366μmol/L。目前情况下，对确诊最适合的辅助检查是",[["A","胸部X线片"],["B","超声心动图"],["C","放射性核素肺通气/血流灌注显像"],["D","CTPA"]],"C","老年女性患者，股骨颈骨折术后7天（静脉血栓栓塞的危险因素），突发呼吸困难1小时（提示肺动脉栓塞），临床疑诊为肺血栓栓塞症，血生化检查Cr366μmol/L（女性正常值41～81μmol/L，提示肾功能损伤），故此时确诊该疾病诊断最适合的检查是放射性核素肺通气/血流灌注显像（C对）。对肺血栓栓塞症，CT肺动脉造影（CTPA）（D错）能够准确发现段以上肺动脉内的血栓，诊断质量较高，还有无创伤、迅速、简便等许多优点，是PTE的一线确诊手段，已逐步取代肺动脉造影而成为PTE诊断的“金标准”，但其局限性在于对造影剂过敏者和肾功能不全应慎用。故选择PTE的确诊检查手段时应考虑到患者肾功能情况。超声心动图（B错）不属于PTE的确诊检查，对提示PTE和除外其他心血管疾患，以及急性PTE 危险分层方面有重要价值。胸部X线片（A错）对PTE的检查不具有特异性，约80%的患者可见异常表现，以上两类检查属于PTE的疑诊检查。","c198","N"],["2024-N74",9,"第一节 肺血栓栓塞症","肺血栓栓塞症心电图",2024,74,"A","","女性，68岁。股骨颈骨折术后第7天，突发呼吸困难1小时。查体：P90次/分，R24次/分，BP120/80mmHg，神清，右肺呼吸音低，偶闻及湿啰音。临床疑诊为肺血栓栓塞症。血生化检查Cr366μmol/L。该患者行心电图检查，可能出现的改变是",[["A","电轴左偏"],["B","SⅠQⅢTⅢ"],["C","完全左束支传导阻滞"],["D","逆钟向转位"]],"B","肺血栓栓塞症的心电图常见特点（大多为非特异性改变）：最常见的改变为窦性心动过速，可出现V₁-V₂甚或V₄的T波倒置和ST段异常，典型改变为SⅠQⅢTⅢ征（即Ⅰ导S波加深，Ⅲ导出现Q/q波及T波倒置）（B对），以及可出现完全或不完全性右束支传导阻滞（C错）、肺型P波、电轴右偏（A错）及顺钟向转位（D错）等。随病程的演变，呈动态变化。","c198","N"],["2024-N75",9,"第一节 肺血栓栓塞症","抗凝药物",2024,75,"A","","女性，68岁。股骨颈骨折术后第7天，突发呼吸困难1小时。查体：P90次/分，R24次/分，BP120/80mmHg，神清，右肺呼吸音低，偶闻及湿啰音。临床疑诊为肺血栓栓塞症。血生化检查Cr366μmol/L。目前首选的治疗是",[["A","即刻给予rt-PA100mg，持续2小时静脉滴注"],["B","低分子量肝素抗凝治疗"],["C","华法林抗凝治疗"],["D","抗血小板治疗"]],"B","肺血栓栓塞症的基础治疗方案是抗凝治疗，也是标准治疗方案，能够改善症状、降低复发率、预防血栓形成，并可使血栓逐步吸收，目前临床指南推介的最常使用的药物主要是低分子肝素、华法林、Ⅹa因子拮抗剂等，普通肝素较少应用（出血风险高）。抗凝治疗的适应证为：①血压正常且无右心室功能不全的低危（非大面积）PTE患者，应给予抗凝治疗；②有血压下降和右心室功能不全的高危（大面积）PTE患者，应先行溶栓治疗，随后使用抗凝治疗；③对血压正常而右心室功能不全的中危（次大面积）PTE患者，无论是否溶栓，都应该进行抗凝治疗。本例患者查体：P90次/分，R24次/分，BP120/80mmHg（＞90/60mmHg，提示血流动力较为稳定），神清，右肺呼吸音减弱，偶闻及湿啰音，属于低危PTE，应给予低分子量肝素抗凝治疗（B对）。血压（即血流动力学变化/右心室功能）对首选治疗方法的选择有重要意义，需要重点注意题干中相关信息。","c198","N"],["2024-N76",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞诊断",2024,76,"A","","男性，60岁。3个月来乏力，1个月来出现渐进性呼吸困难、腹胀、食欲下降、尿少、便秘、下肢水肿。无胸痛、无发热。既往有慢性支气管炎30年，饮酒史20年。查体：T36.5℃，P102次/分，BP90/80mmHg，表情淡漠，轻度贫血貌，颈静脉怒张，双肺（-），心界明显向两侧扩大、心音低，肝肋下3cm，双下肢可凹性水肿（++），深吸气时脉搏消失。导致目前临床表现最可能的原因是",[["A","全心衰竭"],["B","呼吸衰竭"],["C","心脏压塞"],["D","肝衰竭"]],"C","老年男性患者，乏力3个月，渐进性呼吸困难（心包积液最突出的症状）、腹胀、食欲下降、尿少、便秘、下肢水肿1个月（心包积液常见症状），无胸痛、无发热（暂排除感染性病因），既往有慢性支气管炎病史30年，饮酒史20年。查体：T36.5℃，P102次/分（＞100次/分，脉率加快），BP90/80mmHg（血压下降，＜90/60mmHg为低血压，Beck三联征之一），表情淡漠，轻度贫血貌，颈静脉怒张（体循环淤血表现，Beck三联征之一），双肺（-），心界向两侧明显扩大（心包积液心脏体征）、心音低（Beck三联征之一），肝肋下3cm（体循环淤血表现），双下肢可凹性水肿（++）（体循环淤血表现），深吸气时脉搏消失（出现奇脉），根据患者病史、临床表现和体征，最可能的诊断是心包积液，导致相关症状最可能的原因是心脏压塞（心包填塞）（C对），其临床特征为Beck三联征：血压低、心音弱、颈静脉怒张。当题干信息中出现渐进性呼吸困难＋Beck三联征＋奇脉＋体循环淤血相关表现，需考虑到心包积液/心脏压塞的可能性。心包积液多需与全心衰竭（A错）鉴别，超声心动图有助于鉴别和明确诊断，主要根据患者原有的基础心脏疾病如冠心病、高血压、瓣膜病、先天性心脏病或心肌病等病史，查体闻及肺部湿啰音，并根据心音、心脏杂音和有无心包摩擦音进行判断。呼吸衰竭（B错）是指各种原因引起的肺通气和（或）换气功能严重障碍，动脉血气分析有低氧血症伴（或不伴）高碳酸血症，本例无血气分析相关依据。肝衰竭（D错）是多种因素引起的严重肝脏损害，导致其合成、解毒、排泄和生物转化等功能发生严重障碍或失代偿，出现以凝血功能障碍、黄疸、肝性脑病、腹水等为主要表现的一组临床症候群，本例表现暂不符合肝衰竭表现。","c199","N"],["2024-N77",22,"第一节 急性心包炎","急性心包炎诊断",2024,77,"A","","男性，60岁。3个月来乏力，1个月来出现渐进性呼吸困难、腹胀、食欲下降、尿少、便秘、下肢水肿。无胸痛、无发热。既往有慢性支气管炎30年，饮酒史20年。查体：T36.5℃，P102次/分，BP90/80mmHg，表情淡漠，轻度贫血貌，颈静脉怒张，双肺（-），心界明显向两侧扩大、心音低，肝肋下3cm，双下肢可凹性水肿（++），深吸气时脉搏消失。最可能的诊断是",[["A","慢性阻塞性肺疾病"],["B","渗出性心包炎"],["C","扩张型心肌病"],["D","酒精性心肌病"]],"B","老年男性患者，乏力3个月，渐进性呼吸困难（心包积液最突出的症状）、腹胀、食欲下降、尿少、便秘、下肢水肿1个月（心包积液常见症状），无胸痛、无发热（暂排除感染性病因），既往有慢性支气管炎病史30年，饮酒史20年。查体：T36.5℃，P102次/分（＞100次/分，脉率加快），BP90/80mmHg（血压下降，＜90/60mmHg为低血压，Beck三联征之一），表情淡漠，轻度贫血貌，颈静脉怒张（体循环淤血表现，Beck三联征之一），双肺（-），心界向两侧明显扩大（心包积液心脏体征）、心音低（Beck三联征之一），肝肋下3cm（体循环淤血表现），双下肢可凹性水肿（++）（体循环淤血表现），深吸气时脉搏消失（出现奇脉），根据患者病史、临床表现和体征，最可能的诊断是渗出性心包炎（B对），大量渗出的心包积液导致心脏压塞。慢性阻塞性肺疾病（A错）进展至肺心病也会导致右心衰竭，体循环障碍等，但查体可见心浊音界缩小。扩张型心肌病（C错）查体体征不出现奇脉/吸停脉。酒精性心肌病（D错）是长期过量饮酒导致的以心脏扩大、心律失常和心功能不全为主要表现的继发性心肌病，戒酒后病情可自行缓解或痊愈，主要临床表现为心脏扩大和心功能不全，部分患者以心房颤动和冠状动脉痉挛为首发表现。","c199","N"],["2024-N78",22,"第二节 心包积液及心脏压塞","心包积液及心脏压塞超声心动图",2024,78,"A","","男性，60岁。3个月来乏力，1个月来出现渐进性呼吸困难、腹胀、食欲下降、尿少、便秘、下肢水肿。无胸痛、无发热。既往有慢性支气管炎30年，饮酒史20年。查体：T36.5℃，P102次/分，BP90/80mmHg，表情淡漠，轻度贫血貌，颈静脉怒张，双肺（-），心界明显向两侧扩大、心音低，肝肋下3cm，双下肢可凹性水肿（++），深吸气时脉搏消失。为明确诊断，首选的检查是",[["A","超声心动图"],["B","动脉血气分析"],["C","胸部X线片"],["D","胸部CT检查"]],"A","老年男性患者，乏力3个月，渐进性呼吸困难（心包积液最突出的症状）、腹胀、食欲下降、尿少、便秘、下肢水肿1个月（心包积液常见症状），无胸痛、无发热（暂排除感染性病因），既往有慢性支气管炎病史30年，饮酒史20年。查体：T36.5℃，P102次/分（＞100次/分，脉率加快），BP90/80mmHg（血压下降，＜90/60mmHg为低血压，Beck三联征之一），表情淡漠，轻度贫血貌，颈静脉怒张（体循环淤血表现，Beck三联征之一），双肺（-），心界向两侧明显扩大（心包积液心脏体征）、心音低（Beck三联征之一），肝肋下3cm（体循环淤血表现），双下肢可凹性水肿（++）（体循环淤血表现），深吸气时脉搏消失（出现奇脉），根据患者病史、临床表现和体征，最可能的诊断是渗出性心包炎，大量渗出的心包积液导致心脏压塞，此时首选的检查是超声心动图（A对），超声检查对积液检查十分可靠，当心包积液≥50ml液体时，超声心动图可见液性暗区，可确定为心包积液，而舒张末期右房塌陷和舒张期右室游离壁塌陷是诊断心脏压塞最敏感而特异的征象。对心包积液/心脏压塞来说，超声心动不但是检查手段，也是治疗手段之一，可用于引导心包穿刺引流，缓解心包压塞，超声心动图可行床旁检查，是一种简便、安全、灵敏和快捷的无创诊断方法。胸部X线（C错）对超过250ml以上心包积液进行检查时，可见心影增大，呈烧瓶状，有助于鉴别心力衰竭，对无并发症的急性心包炎诊断价值不大，不作为首选检查。动脉血气分析（B错）直接测定动脉血氧分压、动脉二氧化碳分压、动脉氢离子浓度，从而判断肺换气功能及酸碱平衡的状况。胸部CT（D错）显示心包厚度＞5mm可以诊断心包积液，但不作为其常规诊断方式。","c199","N"],["2024-N79",36,"第一节 原发性肝癌","原发性肝癌诊断",2024,79,"A","","男性，64岁。右季肋部胀痛、低热伴消瘦2个月，尿黄1周。既往有乙肝病史20年，饮酒20年。查体：T37.5℃，前胸皮肤可见蜘蛛痣，巩膜黄染，肝肋下3.5cm，质硬，轻压痛，脾肋下1cm。腹部B超见肝内直径5cm低回声区。最可能的诊断是",[["A","酒精性肝病"],["B","原发性肝癌"],["C","肝脓肿"],["D","肝囊肿"]],"B","老年男性患者（肿瘤高发人群），右季肋区胀痛，低热伴消瘦2个月（肝癌常见局部症状和全身症状），尿黄1周（提示肝功能受损）。既往乙肝病史20年，饮酒20年（提示病因）。查体：T37.5℃（＞37℃，发热），前胸皮肤蜘蛛痣（肝硬化表现），巩膜黄染（黄疸），肝肋下3.5cm（肝大），质硬，轻压痛，脾肋下1cm（脾大，肝硬化表现）。腹部B超示肝内直径5cm低回声区（提示肝部占位性病变），根据患者病史、临床表现和体征，最可能的诊断是原发性肝癌（B对），原发性肝癌多发生在肝硬化基础上，当存在原发性肝癌的易患因素和临床特征，影像学检查显示有＞2cm的肝癌特征性占位性病变时，提示诊断。酒精性肝病（A错）是由于长期大量饮酒导致的中毒性肝损伤，初期表现为肝细胞脂肪变性，进而发展为酒精性肝炎，最终导致肝纤维化、肝硬化，影像学检查可见肝脏增大，肝内管道结构显示不清，酒精性肝病导致的肝硬化为小结节性肝硬化，肝表面波纹状，可有门静脉高压症（16版实用内科学P1433）。肝脓肿（C错）临床表现为明显发热、肝区疼痛、压痛明显，血象白细胞计数和中性粒细胞升高，超声检查可发现脓肿的液性暗区，超声引导下穿刺或药物实验性治疗可明确诊断和鉴别诊断。肝囊肿（D错）为较常见的良性肝疾病，一般为囊肿较大时因压迫邻近脏器出现食后饱胀、恶心、呕吐、右上腹隐痛，胃部不适等症状；体格检查可触及右上腹肿块或肝大，一般无明显压痛，可随呼吸上下移动。","c200","N"],["2024-N80",36,"第一节 原发性肝癌","增强CT_MRI",2024,80,"A","","男性，64岁。右季肋部胀痛、低热伴消瘦2个月，尿黄1周。既往有乙肝病史20年，饮酒20年。查体：T37.5℃，前胸皮肤可见蜘蛛痣，巩膜黄染，肝肋下3.5cm，质硬，轻压痛，脾肋下1cm。腹部B超见肝内直径5cm低回声区。为明确诊断，首选的影像学检查是",[["A","腹部增强CT"],["B","PET-CT"],["C","腹部X线平片"],["D","放射性核素肝扫描"]],"A","老年男性患者（肿瘤高发人群），右季肋区胀痛，低热伴消瘦2个月（肝癌常见局部症状和全身症状），尿黄1周（提示肝功能受损）。既往乙肝病史20年，饮酒20年（提示病因）。查体：T37.5℃（＞37℃，发热），前胸皮肤蜘蛛痣（肝硬化表现），巩膜黄染（黄疸），肝肋下3.5cm（肝大），质硬，轻压痛，脾肋下1cm（脾大，肝硬化表现）。腹部B超示肝内直径5cm低回声区（提示肝部占位性病变），根据患者病史、临床表现和体征，最可能的诊断是原发性肝癌，原发性肝癌多发生在肝硬化基础上，当存在原发性肝癌的易患因素和临床特征，影像学检查显示有＞2cm的肝癌特征性占位性病变时，提示诊断。为明确诊断，首选的影像学检查是腹部增强CT（A对），其分辨率高于超声，图像清晰稳定，能全面客观地反映肝癌的特性，目前是肝癌诊断的常规手段，增强扫描可清楚地显示肝癌的大小、数目、形态、部位、边界、肿瘤血供丰富程度以及与肝内管道的关系，对判断肝内和临近组织器官是否存在转移具有重要价值，以及可判断是否合并肝硬化及其严重程度，CT动态增强扫描可以显著提高小肝癌的检出率，是诊断小肝癌和微小肝癌的最佳方法。PET-CT（B错）即正电子发射计算机断层扫描，其通过功能显像反映肝脏占位的生化代谢信息，又可通过CT形态显像进行病灶的精确解剖定位，可提高诊断和评判疾病进展的准确性，对肿瘤分期、治疗方案的选择、预后估计、治疗后随访有较大优势（但临床使用价格昂贵）。腹部X线平片（C错）对肝癌诊断的参考价值十分有限，肝右叶的肿瘤可发现右膈肌抬高、运动受限或局部隆起，肝左外叶或右肝下部巨大肝癌在行胃肠钡餐检查可见胃或结肠肝曲被推压现象，但不作为肝癌诊断首选检查。放射线核素肝扫描（D错）可用于肝细胞癌的定性诊断，因正常肝细胞和病灶肝癌细胞对显像剂的摄取和排泄过程不同，可有“水落石出”效应，该延迟显像是肝肿瘤阳性显像的一种方法，可用于小肝癌的定性和定位诊断，但检出率不高，而核素肝胆动态显像具有方法简便、安全和无创的特点，且辐射剂量低，对新生儿也适用，是临床诊断肝胆疾病的常用方法之一，但不作为成人肝癌诊断的首选检查（3版8年制核医学308）。","c200","N"],["2024-N81",36,"第一节 原发性肝癌","甲胎蛋白",2024,81,"A","","男性，64岁。右季肋部胀痛、低热伴消瘦2个月，尿黄1周。既往有乙肝病史20年，饮酒20年。查体：T37.5℃，前胸皮肤可见蜘蛛痣，巩膜黄染，肝肋下3.5cm，质硬，轻压痛，脾肋下1cm。腹部B超见肝内直径5cm低回声区。对诊断最有意义的实验室检查是",[["A","外周血白细胞计数和分类"],["B","血清AFP"],["C","血清ALT、AST"],["D","血清胆红素"]],"B","老年男性患者（肿瘤高发人群），右季肋区胀痛，低热伴消瘦2个月（肝癌常见局部症状和全身症状），尿黄1周（提示肝功能受损）。既往乙肝病史20年，饮酒20年（提示病因）。查体：T37.5℃（＞37℃，发热），前胸皮肤蜘蛛痣（肝硬化表现），巩膜黄染（黄疸），肝肋下3.5cm（肝大），质硬，轻压痛，脾肋下1cm（脾大，肝硬化表现）。腹部B超示肝内直径5cm低回声区（提示肝部占位性病变），根据患者病史、临床表现和体征，最可能的诊断是原发性肝癌，原发性肝癌多发生在肝硬化基础上，当存在原发性肝癌的易患因素和临床特征，影像学检查显示有＞2cm的肝癌特征性占位性病变时，提示诊断。此时对诊断最有意义的实验室检查是甲胎蛋白（AFP），AFP是最具有诊断价值的肝癌标志物，单独应用时并不具有肝癌诊断的特异性和敏感性，但AFP与影像学检查相结合时对肝癌具有重要诊断意义。AFP的诊断意义：①当AFP＞400μg/ml的患者，在排除继发性肝癌、生殖腺肿瘤或活动性肝病情况下；②当AFP逐渐升高不降低，＞200μg/ml持续8周＋肝癌影像学表现时，满足至少1项高度支持肝癌的诊断。故AFP（B对）是肝癌筛查首选检查，同时肝癌根治术后定期复查AFP亦是判断肝癌治疗效果及监测是否复发的重要指标之一。外周血白细胞计数和分类（A错）对肝癌的诊断无特异性。血清ALT、AST（C错）和血清胆红素（D错）均为肝功能检查，对肝癌的诊断无特异性，需要注意的是，血清ALT和AFP的关系可以用于肝癌和活动性肝炎的鉴别诊断，当二者出现平行升高或同步升高时，活动性肝炎可能性大，但二者出现“分离现象”即AFP↑但ALT升高不明显或不升高时，肝癌可能性大。","c200","N"],["2024-N82",40,"第五节 肾病综合征","肾病综合征诊断",2024,82,"A","","男性，20岁。1个月以来全身水肿、尿少。既往体健。查体：BP120/80mmHg，双眼睑水肿，双下肢明显可凹性水肿。尿常规：蛋白（+++），沉渣镜检RBC4～6个/HP，有透明管型，尿蛋白定量4.6g/d。最可能的诊断是",[["A","急性肾小球肾炎"],["B","急进性肾小球肾炎"],["C","慢性肾小球肾炎急性发作"],["D","肾病综合征"]],"D","青年男性患者，全身水肿（肾病综合征诊断条件之一），尿少一个月（提示肾功能损伤），BP120/80mmHg，双眼睑水肿，双下肢明显凹陷性水肿（肾病综合征体征，提示血浆白蛋白↓，血浆胶体渗透压↓）。尿常规：蛋白（+++）（明显蛋白尿），尿沉渣镜检：RBC4～6个/HP（＞3个/HP，镜下血尿），可见透明管型（提示肾实质病变），尿蛋白定量4.6g/d（＞3.5g/d，肾病综合征诊断必要条件之一），根据患者的临床表现和体征及实验室检查结果，最可能的诊断是肾病综合征（D对），为明确诊断，需完善血白蛋白检查。急性肾小球肾炎（A错），是一组以急性肾炎综合征（血尿、蛋白尿、水肿和高血压）为主要临床表现的肾脏疾病，可伴一过性肾功能损害，发病前多有前驱感染，潜伏期为1～2周。急进性肾小球肾炎（B错）是一组以急进性肾炎综合征为临床表现，肾功能损害急骤进展，常伴有少尿或无尿的临床综合征，发病前多有前驱感染，肾活检病理表现为肾小球广泛新月体形成，故又称新月体性肾小球肾炎。慢性肾小球肾炎（C错）的临床特点为病程长，病情迁延，病变缓慢持续进展，最终至慢性肾衰竭，以血尿、蛋白尿、高血压和水肿为基本症状，急性发作时病情会急骤恶化，经及时去除诱因和适当治疗后病情可一定程度缓解，但也可能由此而进入不可逆的慢性肾衰竭。","c201","N"],["2024-N83",40,"第五节 肾病综合征","肾病综合征诊断",2024,83,"A","","男性，20岁。1个月以来全身水肿、尿少。既往体健。查体：BP120/80mmHg，双眼睑水肿，双下肢明显可凹性水肿。尿常规：蛋白（+++），沉渣镜检RBC4～6个/HP，有透明管型，尿蛋白定量4.6g/d。有助于该患者诊断的检查是",[["A","血清白蛋白"],["B","血肌酐"],["C","外周血血红蛋白"],["D","腹部B超"]],"A","青年男性患者，全身水肿（肾病综合征诊断条件之一），尿少一个月（提示肾功能损伤），BP120/80mmHg，双眼睑水肿，双下肢明显凹陷性水肿（肾病综合征体征，提示血浆白蛋白↓，血浆胶体渗透压↓）。尿常规：蛋白（+++）（明显蛋白尿），尿沉渣镜检：RBC4～6个/HP（＞3个/HP，镜下血尿），可见透明管型（提示肾实质病变），尿蛋白定量4.6g/d（＞3.5g/d，肾病综合征诊断必要条件之一），根据患者的临床表现和体征及实验室检查结果，最可能的诊断是肾病综合征，为明确诊断，需完善血白蛋白检查（A对），低白蛋白血症（血清白蛋白＜30g/L）是诊断肾病综合征的必备条件之一。血肌酐（B错）用于肾功能的检查。外周血血红蛋白（C错）用于判断是否贫血。腹部B超（D错）属于肾脏的影像学检查，对肾病综合征无诊断意义。","c201","N"],["2024-N84",40,"第五节 肾病综合征","肾病综合征诊断",2024,84,"A","","男性，20岁。1个月以来全身水肿、尿少。既往体健。查体：BP120/80mmHg，双眼睑水肿，双下肢明显可凹性水肿。尿常规：蛋白（+++），沉渣镜检RBC4～6个/HP，有透明管型，尿蛋白定量4.6g/d。对下一步治疗最有意义的检查是",[["A","肾活检"],["B","静脉肾盂造影"],["C","腹部CT"],["D","肾图"]],"A","青年男性患者，全身水肿（肾病综合征诊断条件之一），尿少一个月（提示肾功能损伤），BP120/80mmHg，双眼睑水肿，双下肢明显凹陷性水肿（肾病综合征体征，提示血浆白蛋白↓，血浆胶体渗透压↓）。尿常规：蛋白（+++）（明显蛋白尿），尿沉渣镜检：RBC4～6个/HP（＞3个/HP，镜下血尿），可见透明管型（提示肾实质病变），尿蛋白定量4.6g/d（＞3.5g/d，肾病综合征诊断必要条件之一），根据患者的临床表现和体征及实验室检查结果，最可能的诊断是肾病综合征，肾病综合征不是一个独立性的疾病，为继续治疗，需要明确病因，不同类型的治疗方法不一，故下一步治疗需要明确病理类型，最有意义的检查是肾活检（A对）。静脉肾盂造影（B错）、腹部CT（C错）、肾图（D错）等影像学检查无法对病理类型进行明确诊断。","c201","N"],["2024-N85",54,"第一节 多发性骨髓瘤","多发性骨髓瘤分型",2024,85,"A","","男性，60岁。乏力、腰痛1个月。既往体健。血常规：Hb80g/L，WBC6.8×10⁹/L，Plt176×10⁹/L；血清总蛋白105g/L，白蛋白30g/L，血清蛋白电泳可见一染色浓而密集、单峰突起的M蛋白，血Cr 134μmol/L。初步诊断为多发性骨髓瘤。根据目前的临床资料，该患者最可能的类型是",[["A","IgG型"],["B","IgE型"],["C","IgD型"],["D","轻链型"]],"A","老年男性患者，乏力腰痛1个月（多发性骨髓瘤骨骼损害导致骨痛），既往体健，血常规：Hb80g/L（男性Hb正常值130～175g/L，提示中度贫血），WBC6.8×10⁹/L（成人白细胞正常值3.5～9.5×10⁹/L），Plt176×10⁹/L（成人血小板正常值125～350×10⁹/L）。血清总蛋白105g/L（正常成人血清总蛋白60～80g/L，升高），白蛋白30g/L（成年人白蛋白正常值40～55g/L，减少），血清蛋白电泳可见一染色浓而密集、单峰突起的M蛋白（多发性骨髓瘤突出表现），血Cr 134μmol/L（男性血肌酐正常值53～106μmol/L，提示肾功能损伤），初步诊断为多发性骨髓瘤（MM病），以IgG型最常见，其次为IgA型，IgD型和IgE型罕见，也有IgM型的报道，故该患者的分型最可能是IgG型（A对）。","c202","N"],["2024-N86",54,"第一节 多发性骨髓瘤","多发性骨髓瘤分期",2024,86,"A","","男性，60岁。乏力、腰痛1个月。既往体健。血常规：Hb80g/L，WBC6.8×10⁹/L，Plt176×10⁹/L；血清总蛋白105g/L，白蛋白30g/L，血清蛋白电泳可见一染色浓而密集、单峰突起的M蛋白，血Cr 134μmol/L。初步诊断为多发性骨髓瘤。根据Durie-Salmon分期，该患者的分期和亚型是",[["A","Ⅱ期A亚型"],["B","Ⅱ期B亚型"],["C","Ⅲ期A亚型"],["D","Ⅲ期B亚型"]],"C","多发性骨髓瘤的DS分期需要参考的标准主要为血红蛋白、血钙、骨骼X线片（溶骨情况）。分组/亚型参考的标准主要为肾功能情况，血肌酐＜177μmol/L为A组，血肌酐≥177μmol/L为B组。本例患者Hb80g/L（＜85g/L，属于Ⅲ期标准），血肌酐134μmol/L（＜177μmol/L，为A组标准），故该患者的分期和亚型为Ⅲ期A亚型（C对）。","c202","N"],["2024-N87",54,"第一节 多发性骨髓瘤","多发性骨髓瘤治疗",2024,87,"A","","男性，60岁。乏力、腰痛1个月。既往体健。血常规：Hb80g/L，WBC6.8×10⁹/L，Plt176×10⁹/L；血清总蛋白105g/L，白蛋白30g/L，血清蛋白电泳可见一染色浓而密集、单峰突起的M蛋白，血Cr 134μmol/L。初步诊断为多发性骨髓瘤。该患者宜选用自体造血干细胞移植，目前诱导治疗不宜选用的药物是",[["A","硼替佐米"],["B","美法仑"],["C","来那度胺"],["D","地塞米松"]],"B","本例患者诊断为多发性骨髓瘤，宜选用自体造血干细胞移植，目前诱导治疗化疗药物多为硼替佐米（A对）、地塞米松（D对）、来那度胺（C对）、多柔比星等。但美法仑会影响干细胞动员，故不宜选用美法仑（B错，为本题正确答案）。","c202","N"],["2024-N88",61,"第一节 糖尿病","糖尿病诊断标准",2024,88,"A","","女性，24岁。口干、多饮半年余，食欲好，活动正常，体重无变化。其父亲和祖母均患糖尿病。查体：身高156cm，体重68kg。实验室检查：尿糖（+），尿酮体（-）；空腹血糖9.2mmol/L，HbA1c8.1％，GADA抗体（-）；甲状腺功能正常。最符合上述临床特点的诊断是",[["A","免疫介导性1型糖尿病"],["B","特发性1型糖尿病"],["C","2型糖尿病"],["D","糖尿病前期"]],"C","青年女性患者，口干，多饮半年余，食欲好（多饮多食症状，提示糖尿病），活动正常，体重无变化（无多尿与体重减轻，“三多一少”症状不典型），其父亲和祖母均患有糖尿病（有家族史），查体：身高156cm，体重68kg（BMI=27.9，超重），实验室检查：尿糖（+）（提示糖尿病），尿酮体（-）（未并发糖尿病酮症）；空腹血糖9.2mmol/L（≥7.0mmol/L，符合糖尿病诊断标准），HbA1c8.1％（正常值4%～6%，升高，提示血糖控制不佳），GADA抗体（-）（无自身免疫）；甲状腺功能正常，根据患者临床表现、体征和实验室检查结果，最符合以上临床特点的诊断是2型糖尿病（T2DM）（C对）。1型糖尿病（T1DM）（十版内科学P728）患者大多起病较急，“三多一少”症状较为典型，免疫介导性1型糖尿病（A错）患者大多自身抗体阳性，特发性1型糖尿病（B错）患者临床表现为糖尿病酮症甚至酸中毒，故排除。患者口干、多饮、多食，空腹血糖≥7.0mmol/L，考虑为糖尿病，故排除糖尿病前期（D错）。","c203","N"],["2024-N89",61,"第一节 糖尿病","口服降糖药物",2024,89,"A","","女性，24岁。口干、多饮半年余，食欲好，活动正常，体重无变化。其父亲和祖母均患糖尿病。查体：身高156cm，体重68kg。实验室检查：尿糖（+），尿酮体（-）；空腹血糖9.2mmol/L，HbA1c8.1％，GADA抗体（-）；甲状腺功能正常。对该患者的治疗原则，不适当的是",[["A","需进行生活方式干预"],["B","可给予磺脲类口服降糖药"],["C","可给予双胍类口服降糖药"],["D","首选胰岛素治疗"]],"D","青年女性患者，口干，多饮半年余，食欲好（多饮多食症状，提示糖尿病），活动正常，体重无变化（无多尿与体重减轻，“三多一少”症状不典型），其父亲和祖母均患有糖尿病（有家族史），查体：身高156cm，体重68kg（BMI=27.9，超重），实验室检查：尿糖（+）（提示糖尿病），尿酮体（-）（未并发糖尿病酮症）；空腹血糖9.2mmol/L（≥7.0mmol/L，符合糖尿病诊断标准），HbA1c8.1％（正常值4%～6%，升高，提示血糖控制不佳），GADA抗体（-）（无自身免疫）；甲状腺功能正常，根据患者临床表现、体征和实验室检查结果，最符合以上临床特点的诊断是2型糖尿病。生活方式干预（A对）对各类糖尿病的病情控制均有积极作用（十版内科学P735）。为使血糖控制达标，磺脲类（B对）、双胍类等口服降糖药（C对）均可用于2型糖尿病治疗（十版内科学P736）。胰岛素常用于治疗经生活方式干预和较大剂量多种口服降糖药联合治疗、血糖仍未达控制目标的晚期患者，本病例为首次确诊的早期患者，且症状不显著（HbA1c＜9%、空腹血糖＜11.1mmol/L），无急性并发症，不宜首选胰岛素治疗（D错，为本题正确答案）。","c203","N"],["2024-N90",61,"第一节 糖尿病","某些特殊类型糖尿病的临床特点",2024,90,"A","","女性，24岁。口干、多饮半年余，食欲好，活动正常，体重无变化。其父亲和祖母均患糖尿病。查体：身高156cm，体重68kg。实验室检查：尿糖（+），尿酮体（-）；空腹血糖9.2mmol/L，HbA1c8.1％，GADA抗体（-）；甲状腺功能正常。该患者最可能的糖尿病类型是",[["A","LADA"],["B","MODY"],["C","线粒体基因突变糖尿病"],["D","脂肪萎缩型糖尿病"]],"B","青年女性患者，口干，多饮半年余，食欲好（多饮多食症状，提示糖尿病），活动正常，体重无变化（无多尿与体重减轻，“三多一少”症状不典型），其父亲和祖母均患有糖尿病（有家族史），查体：身高156cm，体重68kg（BMI=27.9，超重），实验室检查：尿糖（+）（提示糖尿病），尿酮体（-）（未并发糖尿病酮症）；空腹血糖9.2mmol/L（≥7.0mmol/L，符合糖尿病诊断标准），HbA1c8.1％（正常值4%～6%，升高，提示血糖控制不佳），GADA抗体（-）（无自身免疫）；甲状腺功能正常，根据患者临床表现、体征和实验室检查结果，最符合以上临床特点的诊断是2型糖尿病。若进行基因诊断，根据患者家族史、发病年龄及无酮症，最可能的糖尿病类型是MODY，属于β细胞功能缺陷型特殊类型糖尿病，该类型与T1DM、T2DM不易鉴别。对MODY的治疗，原则上为2年内不需要外源性胰岛素控制血糖，但MODY各分型治疗原则不同，如MODY5对磺脲类反应差，应尽早开始胰岛素治疗，而MODY1和MODY3则在发病早期可使用磺脲类药物进行降糖，不需要胰岛素治疗。LADA（A错）属于自身免疫性T1DM的一种，常见临床特征为发病年龄一般＞30岁，发病后体重迅速下降，BMI≤25kg/m²，有自身免疫性疾病家族史或个人史，和T2DM相比，较少代谢综合征表现，GADA抗体阳性是其敏感指标。线粒体基因突变型糖尿病（C错）属于胰岛β细胞功能基因突变所致的糖尿病（特殊类型糖尿病），其基因突变一般为母系遗传，大多数线粒体糖尿病表现类似T2DM，也可呈类似T1DM表现，或在妊娠时发病。一般起病较早，体重低，发病初期单纯饮食控制或使用磺脲类药物有效，但之后常出现磺脲类药物继发失效。脂肪萎缩型糖尿病（D错）属于胰岛素受体基因突变所致的糖尿病（特殊类型糖尿病），本病为常染色体隐性遗传，临床特点为有明显家族史，多为女性发病，严重胰岛素抵抗伴皮下、腹腔和肾周脂肪萎缩，一般不伴酮症酸中毒，有肝大、脾大、肝硬化或肝衰竭，可有皮肤黄色瘤和高甘油三酯血症，女孩常有多毛、阴蒂肥大等男性化表现。","c203","N"],["2024-N91",69,"第一节 系统性红斑狼疮","系统性红斑狼疮诊断",2024,91,"A","","女性，26岁。反复口腔黏膜溃疡半年，发热、双手及足关节痛1周。既往体健。查体：T38.8℃，上肢皮肤可见出血点，口腔左侧颊黏膜可见一处溃疡，关节无红肿。血常规：Hb118g/L，WBC4.2×10⁹/L，Plt25×10⁹/L。血RF阳性，ANA滴度增高，抗Sm抗体阳性。最可能的诊断是",[["A","类风湿性关节炎"],["B","贝赫切特（Behcet）病"],["C","原发免疫性血小板减少症"],["D","系统性红斑狼疮"]],"D","育龄期女性患者（SLE高发人群），反复口腔黏膜溃疡半年（SLE常见黏膜症状），发热，双手及足关节痛1周（SLE常见肌肉关节表现），查体：T38.8℃（38.1℃～39℃，属于中等热度，SLE全身表现），上肢皮肤可见出血点（SLE可有皮肤表现），口腔左侧颊黏膜可见一处溃疡（SLE可有黏膜表现），关节无红肿（SLE关节表现）。血常规：Hb118g/L（成年女性正常值115～150g/L），WBC4.2×10⁹/L（成人正常值3.5～9.5×10⁹/L），Plt25×10⁹/L（成人正常值125～350×10⁹/L，Plt减少），血RF阳性（提示风湿性疾病），ANA滴度增高，抗Sm抗体阳性（提示SLE），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是系统性红斑狼疮（SLE）（D对），是一种常见的弥漫性结缔组织病，其特点是大量产生以抗核抗体为代表的多种自身抗体，引起多系统受累的复杂临床表现，通常情况下，育龄期女性＋发热＋多关节肿痛+黏膜病变（如口腔溃疡等）多考虑系统性红斑狼疮。SLE的标记性抗体为：抗ds-DNA抗体、抗Sm抗体、抗rRNA抗体，活动性抗体为：抗ds-DNA抗体、抗rRNA抗体。类风湿性关节炎（A错）主要表现为手、腕、膝、踝和足等小关节受累为主的对称性、持续性、进展性多关节炎，可导致关节畸形和功能丧失，典型的关节畸形包括纽扣花畸形和天鹅颈畸形，血清中可出现类风湿因子（RF）及抗环瓜氨酸肽抗体（抗CCP）等多种自身抗体，后者对本病的诊断有重要意义。贝赫切特（Behcet）病（B错）又称为白塞病，临床表现以反复发作性口腔溃疡、外阴溃疡、眼炎及皮肤损害等为特征，消化系统、神经系统、心血管系统等受累亦常见，针刺反应阳性有助于诊断，本病无特异性的血清学检查指标。原发性免疫性血小板减少症（C错）既往称为特发性血小板减少性紫癜（ITP），主要的发病机制是免疫介导的血小板破坏过多以及血小板生成不足，导致血小板计数减少，临床表现以皮肤黏膜出血为主，严重者可有内脏出血，甚至颅内出血，出血风险随年龄的增长而增加，其出血多表现为紫癜，骨髓检查有助于确诊，血清学检查部分ITP患者的血小板表面或血浆中可检测出血小板膜GP特异性自身抗体。","c204","N"],["2024-N92",69,"第一节 系统性红斑狼疮","糖皮质激素",2024,92,"A","","女性，26岁。反复口腔黏膜溃疡半年，发热，双手及足关节痛1周。既往体健。查体：T38.8℃，上肢皮肤可见出血点，口腔左侧颊黏膜可见一处溃疡，关节无红肿。血常规：Hb118g/L，WBC4.2×10⁹/L，Plt25×10⁹/L。血RF阳性，ANA滴度增高，抗Sm抗体阳性。对该患者应首选的治疗是",[["A","对症治疗"],["B","应用糖皮质激素"],["C","应用丙种球蛋白"],["D","应用非甾体抗炎药"]],"B","育龄期女性患者（SLE高发人群），反复口腔黏膜溃疡半年（SLE常见黏膜症状），发热，双手及足关节痛1周（SLE常见肌肉关节表现），查体：T38.8℃（38.1℃～39℃，属于中等热度，SLE全身表现），上肢皮肤可见出血点（SLE可有皮肤表现），口腔左侧颊黏膜可见一处溃疡（SLE可有黏膜表现），关节无红肿（SLE关节表现）。血常规：Hb118g/L（成年女性正常值115～150g/L），WBC4.2×10⁹/L（成人正常值3.5～9.5×10⁹/L），Plt25×10⁹/L（成人正常值125～350×10⁹/L，Plt减少），血RF阳性（提示风湿性疾病），ANA滴度增高，抗Sm抗体阳性（提示SLE），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是系统性红斑狼疮（SLE），是一种常见的弥漫性结缔组织病，其特点是大量产生以抗核抗体为代表的多种自身抗体，引起多系统受累的复杂临床表现，通常情况下，育龄期女性＋发热＋多关节肿痛+黏膜病变（如口腔溃疡等）多考虑系统性红斑狼疮，SLE的治疗一般首选联合应用糖皮质激素（B对）和免疫抑制剂（首选环磷酰胺/CTX或吗替麦考酚酯/MMF），以尽快控制病情活动，减少器官损伤，并维持病情长期缓解，对糖皮质激素的使用要求起始足量、缓慢减量、长期维持。对症治疗（A错）属于SLE缓解症状的辅助治疗，对发热和关节肿痛等一般可采取非甾体抗炎药（D错），用于短期控制关节炎；对有高血压、血脂异常、糖尿病、骨质疏松等患者应予相应的治疗。丙种球蛋白（C错）用于病情危重或治疗困难的病例，可根据临床实际情况进行选择。","c204","N"],["2024-N128",8,"第三节 结节病","纤维支气管镜与支气管肺泡灌洗",2024,128,"B","","结节病患者支气管肺泡灌洗液的特点是",[["A","中性粒细胞比例增加"],["B","淋巴细胞比例增加"],["C","肺泡巨噬细胞比例增加"],["D","嗜碱性粒细胞比例增加"]],"B","结节病患者支气管肺泡灌洗液（BALF）的特点是T淋巴细胞比例增加（B对），CD4明显增加，CD4/CD8的比值增加（＞3.5），当淋巴细胞分数大于28%时，提示病变活动。与之相对的是过敏性肺炎，BALF检查也表现为T淋巴细胞增加，但CD8升高为主，CD4/CD8常＜1。中性粒细胞比例增加（A错）和（或）嗜酸性粒细胞增加提示特发性肺纤维化。肺泡巨噬细胞比例增高（C错）见于特发性肺含铁血黄素沉着症，可见灌洗液内肺泡巨噬细胞中的铁颗粒，也可见于铍中毒，CD4/CD8＞4。BALF结果较少涉及嗜碱性粒细胞比例增加（D错）。","","N"],["2024-N129",8,"第二节 特发性肺纤维化","BALF_TBLB",2024,129,"B","","特发性肺纤维化患者支气管肺泡灌洗液的特点是",[["A","中性粒细胞比例增加"],["B","淋巴细胞比例增加"],["C","肺泡巨噬细胞比例增加"],["D","嗜碱性粒细胞比例增加"]],"A","特发性肺纤维化患者的支气管肺泡灌洗液的特点是中性粒细胞比例增加（A对）和（或）嗜酸性粒细胞增加。淋巴细胞比例增加（B错）常见于结节病。肺泡巨噬细胞比例增高（C错）可见于特发性肺含铁血黄素沉着症、铍中毒。BALF结果较少涉及嗜碱性粒细胞比例增加（D错）。","","N"],["2024-N130",75,"第一节 中毒概述","皮肤黏膜表现",2024,130,"B","","亚硝酸盐中毒引起的皮肤改变是",[["A","发绀"],["B","发红"],["C","苍白"],["D","黄疸"]],"A","亚硝酸盐中毒引起的皮肤症状是发绀（A对），机制为其引起血红蛋白分子中二价铁被三价铁所取代，使其失去与氧结合的能力，导致血液中高铁血红蛋白含量增多（＞30g/L，可出现发绀）。中毒导致的发绀还常见于苯胺、硝基苯、伯氨喹、磺胺类等中毒。皮肤发红（B错）常见于一氧化碳中毒。黄疸（D错）常见于毒蕈、鱼胆或四氯化碳中毒导致的肝脏损伤。皮肤苍白（C错）可见于发热、剧烈疼痛、休克等多种病理情况。","","N"],["2024-N131",75,"第一节 中毒概述","皮肤黏膜表现",2024,131,"B","","四氯化碳中毒引起的皮肤改变是",[["A","发绀"],["B","发红"],["C","苍白"],["D","黄疸"]],"D","四氯化碳中毒引起的皮肤症状为黄疸（D对），机制为导致肝细胞损伤，属于肝细胞性黄疸，其他导致皮肤黄疸的毒物有毒蕈、鱼胆等。发绀（A错）见于苯胺、亚硝酸盐、硝基苯、伯氨喹、磺胺类等中毒。皮肤发红（B错）常见于一氧化碳中毒。皮肤苍白（C错）可见于发热、剧烈疼痛、休克等多种病理情况。","","N"],["2024-N154",12,"第一节 急性呼吸窘迫综合征","急性呼吸窘迫综合征病因",2024,154,"X","","急性呼吸窘迫综合征的常见危险因素有",[["A","重症急性胰腺炎"],["B","脓毒症"],["C","误吸"],["D","大量补液"]],"ABC","急性呼吸窘迫综合征（ARDS）是指由各种肺内和肺外致病因素所导致的急性弥漫性肺损伤和进而发展的急性呼吸衰竭，其常见危险因素有：肺炎、非肺源性感染脓毒症（B对）、胃内容物吸入（C对）、大面积创伤、肺挫伤、胰腺炎（A对）、吸入性肺损伤、重度烧伤、非心源性休克、药物过量、输血相关急性肺损伤、肺血管炎、溺水。大量补液（D错）属于ARDS治疗时的禁忌证，ARDS应重视液体管理，限制补液（保证入＜出），避免加重肺水肿。","","N"],["2024-N155",18,"第一节 原发性高血压","高血压急症和亚急症诊断",2024,155,"X","","鉴别高血压急症与亚急症的标准有",[["A","血压是否大于180/120mmHg"],["B","是否伴有急性心力衰竭"],["C","是否伴有高血压脑病"],["D","是否伴有明显发病诱因"]],"BC","由高血压急症和高血压亚急症的定义可知，高血压急症和高血压亚急症均表现为血压明显升高（一般超过180/120mmHg）（A错），鉴别高血压急症与亚急症的唯一标准为是否有严重临床症状及进行性心（B对）、脑（C对）、肾等重要靶器官损害，不涉及是否有发病诱因（D错）。","","N"],["2024-N156",37,"第一节 急性胰腺炎","诊断AP的重要血清学标志物",2024,156,"X","","支持重症急性胰腺炎的实验室检查结果有",[["A","血浆C反应蛋白降低"],["B","空腹血糖降低"],["C","血清淀粉酶正常或降低"],["D","血钙降低"]],"CD","急性胰腺炎起病2～12小时开始升高，48小时开始下降，持续3～5天，测定值越高，诊断急性胰腺炎的价值越大，但血清淀粉酶高低与病情严重程度无相关性，当有明确急性胰腺炎诊断依据，但血清淀粉酶正常或降低时，提示急性重症胰腺炎。血钙值的明显下降提示胰腺有广泛脂肪坏死和组织内钙皂形成，血钙＜1.75mmol/L（7mg/dL），也有教材数值为血钙＜1.8mmol/L（8mg/dL），提示胰腺炎预后不良。故支持重症胰腺炎的实验室检查结果有血清淀粉酶正常或降低（C对）、血钙降低（D对）。发病72h后血浆C-反应蛋白＞150mg/L提示胰腺组织坏死（A错）。","","N"],["2024-N157",40,"第五节 肾病综合征","肾病综合征病因",2024,157,"X","","可表现为肾病综合征的肾小球疾病有",[["A","微小病变型肾病"],["B","膜性肾病"],["C","狼疮肾炎"],["D","链球菌感染后急性肾小球肾炎"]],"ABC","微小病变型肾病（A对）是儿童原发性肾病综合征的常见原因。膜性肾病（B对）是中老年原发性肾病综合征的常见原因。狼疮肾炎（C对）是儿童和青少年继发性肾病综合征的常见原因。链球菌感染后急性肾小球肾炎（D错）表现为急性肾炎综合征，即以肾小球源性血尿为主要特征，常伴有蛋白尿，可有水肿、高血压和（或）肾功能损害。","","N"],["2024-N158",55,"第一节 出血性疾病概述","血管异常",2024,158,"X","","提示因血管异常而引起出血的血液实验室检查项目有",[["A","vWF测定"],["B","FDP测定"],["C","t-PA测定"],["D","TM测定"]],"AD","血管内皮细胞可以合成和释放血管性血友病因子（vWF）、前列环素（PGI2）和血栓调节蛋白（TM）等多种促凝血和抗血栓生物分子，故提示因血管异常而引起出血的血液实验室检查项目有vWF测定（A对）、TM测定（D对）。","","N"],["2024-N159",59,"第一节 甲状腺功能亢进症","妊娠期甲亢的治疗",2024,159,"X","","女性，31岁。3年前患Graves病，服用抗甲状腺药物2年后停药，1个月以来出现心悸、多汗、手颤、消瘦，甲功检查显示FT₃和FT₄明显升高，TSH显著降低，TRAb（+），肝功能和血常规结果正常。目前正值哺乳期。查体：甲状腺Ⅲ度肿大，突眼度为21mm。对该患者治疗方法不恰当的有",[["A","推荐选用MMI治疗"],["B","¹³¹I治疗"],["C","急诊甲状腺切除术"],["D","碘剂治疗"]],"BCD","育龄期女性患者，3年前患Graves病史，服用抗甲状腺药物2年后停药，产后出现心悸、多汗、手颤、消瘦（甲亢表现），甲功检查显示FT₃和FT₄明显升高，TSH显著下降，TRAb（+）（典型甲亢实验室见检查结果），查体：甲状腺Ⅲ度肿大，突眼度为21mm（提示Graves病复发+Graves眼病），根据患者病史、临床表现和体征、实验室检查结果，最可能的诊断是，产后Graves病复发。此时患者的情况不属于手术禁忌证，可进行择期手术治疗（C错，为本题正确答案）。同时哺乳期妇女可使用ATD控制病情，对产后哺乳期GD时的ATD选择，九版教材（内科学＋妇产科学）观点是首选MMI（A对），3版八年制内科学观点是选用PTU，十版内科学观点是PTU或MMI均可，考试中心所给答案以九版教材为观点。哺乳期妇女禁用放射性治疗（B错，为本题正确答案）。碘剂治疗（D错，为本题正确答案）仅用于术前准备和甲状腺危象。本题选项应单独判断，不能结合判断，否则碘剂治疗本身可以用于术前准备，且本例患者可以进行择期手术；其次MMI和PTU的选择各个版本教材也有不同说法。因此本题答案略有争议。","","N"],["2025-N41",21,"第二节 主动脉瓣反流","主动脉瓣反流临床表现",2025,41,"A","","关于主动脉瓣关闭不全听诊的特点，错误的是",[["A","常伴有心尖部第一心音亢进"],["B","杂音为舒张早期递减型"],["C","杂音在前倾位听诊明显"],["D","心尖部可闻及舒张期杂音"]],"A","主动脉瓣关闭不全的听诊特点主要包括：杂音为舒张早期递减型（B对），即杂音开始较强，逐渐减弱，这是因为在舒张早期，主动脉内的血液反流回左心室产生杂音，而随着心室充盈，反流减少，杂音也随之减弱；杂音在前倾位时可能会更明显（C对），这是由于体位的改变影响了心脏与听诊器之间的声波传导；同时，由于血液从主动脉反流回左心室，可能会在心尖部听到柔和的舒张期杂音（D对），这是反流的血液冲击二尖瓣产生的声音。心尖部第一心音亢进（A错，为本题正确答案）常见于二尖瓣狭窄且瓣叶柔顺有弹性时，呈拍击样，并可闻及开瓣音，而不会出现在主动脉瓣关闭不全。","","N"],["2025-N42",41,"第一节 尿路感染","尿路感染的诊断",2025,42,"A","","女性，23岁。因腰痛1周行尿常规沉渣镜检，发现红细胞20～40个/HP，98%形态多样、大小不一。首先可排除的疾病是",[["A","肾盂肾炎"],["B","肾小球肾炎"],["C","肾结石"],["D","肾结核"]],"C","青年女性患者，腰痛一周，行尿沉渣镜检，结果显示：镜下发现红细胞20～30个/HP（提示显微镜下血尿），且98%的红细胞形态多样，大小不一（提示非均一性红细胞）。综合患者临床表现及辅助检查，最可能排除的疾病是肾结石（C错，为本题正确答案），肾结石在移动或嵌顿时会损伤尿路黏膜引发血尿，但为均一性红细胞。肾盂肾炎（A对）为细菌感染肾盂导致的炎症，通常表现为发热、腰痛和尿路刺激症状，尿沉渣检查中会出现白细胞增多，可见白细胞管型，当肾盂肾炎进展累及肾小球时会出现异形红细胞。肾小球肾炎（B对）病变通常累及双侧肾小球，症状包括蛋白尿、血尿、水肿、高血压，因为肾小球基底膜损伤，红细胞通过时易变形，导致尿中出现大量异形红细胞，故不能排除。肾结核（D对）由结核分枝杆菌感染肾脏引发，可导致肾组织破坏和血尿，红细胞通过受损组织时可能发生变形，出现异形红细胞，因此不能排除。","","N"],["2025-N43",7,"第一节 肺癌","鳞癌",2025,43,"A","","下列不符合肺鳞癌临床特点的是",[["A","与吸烟关系密切"],["B","多表现为中央型肺癌"],["C","对化疗不敏感"],["D","EGFR突变检出率较高"]],"D","肺鳞癌为肺癌中最常见的类型之一，与吸烟密切相关（A对），因为烟草中的有害物质能损伤肺组织，增加细胞突变的几率，提升患肺鳞癌的风险。肺鳞癌多起源于段或亚段的支气管黏膜，因此多为中央型肺癌（B对）。肺鳞癌对化疗的敏感性较低（C对），多以手术治疗为主，对于晚期和复发的肺鳞癌病人可采用化疗缓解症状及提高生活质量。EGFR（表皮生长因子受体）突变主要发生在第18号外显子至21号外显子，在肺腺癌中较为常见，但肺鳞癌的EGFR突变检出率却相对较低（D错，为本题正确答案）。","","N"],["2025-N44",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病肺功能检查",2025,44,"A","","慢性阻塞性肺疾病患者，可确定存在不完全可逆气流受限的肺功能检查结果是",[["A","吸入组胺激发后FEV₁/FVC＜0.7"],["B","吸入支气管扩张剂后FEV₁/FVC＜0.7"],["C","静息状态下测得FEV₁/FVC＜0.7"],["D","残气量/肺总量＞35%"]],"B","慢性阻塞性肺疾病的特征是持续存在的呼吸系统症状和气流受限，可确定患者存在不完全可逆性气流受限的肺功能检查结果是吸入支气管扩张剂后FEV₁/FVC＜0.7（B对）。吸入组胺为支气管激发试验，用于测定气道反应性，当FEV₁下降判≥20%，判断结果为阳性，提示存在气道高反应性，可诊断支气管哮喘（A错）。静息状态下FEV₁/FVC＜0.7（C错）虽能表明存在气流受限，但无法证明这种受限是否可逆，所以不能单凭此项指标来诊断慢性阻塞性肺疾病。残气量/肺总量＞35%（D错）能够反映出患者肺部的过度充气状态，但并不能说明存在不完全可逆性气流受限，不能用于诊断慢性阻塞性肺疾病。","","N"],["2025-N45",7,"第一节 肺癌","肺癌的介入治疗",2025,45,"A","","男性，78岁。诊为肺癌2个月，突发咯血1小时，咯血量约200ml。既往有高血压病30年。监测血氧饱和度下降。在保持呼吸道通畅的情况下，最佳的治疗措施是",[["A","静脉给予垂体后叶素"],["B","给予可待因止咳"],["C","支气管镜下止血"],["D","介入栓塞治疗"]],"D","老年男性肺癌患者，既往有高血压病史，突发咯血，咯血量约200ml，监测血氧饱和度下降，在保持呼吸道通畅情况下的最佳治疗措施为介入栓塞治疗（D对），介入栓塞治疗目前广泛应用于咯血的治疗，治疗效果好，不会加重气道阻力。静脉给予垂体后叶素（A错）对大咯血有一定的止血效果，其作用机制是收缩小动脉以减少肺循环血量，同时可以升高血压，由于该患者既往有高血压病史，所以需慎用。给予可待因止咳（B错）主要用于缓解咳嗽，并不能直接解决咯血问题，且可能增加呼吸道阻塞风险，所以该患者不适用。支气管镜下止血（C对）虽然可以清除积血，防治窒息，但同时也有加重咯血的风险，所以一般是在咯血暂时缓解期进行，而该患者咯血1小时，监测血氧饱和度下降，可能存在活动性出血，而且该患者高血压病史30年，可能存在心功能不全，支气管镜下止血风险较高，所以支气管镜下止血需谨慎选择。","","N"],["2025-N46",17,"第一节 动脉粥样硬化","动脉粥样硬化冠状动脉造影",2025,46,"A","","男性，58岁。3天前劳累后感胸部憋闷，咽部发紧，持续数分钟缓解，无胸痛，平日活动不受限。既往有高血压病5年，服药控制，无糖尿病病史，吸烟30年，20支/天。查体：BP142/88mmHg，心肺（-）。静态心电图及超声心动图正常；血脂正常；冠状动脉CT示右冠状动脉中段60%狭窄。为决定该患者下一步治疗方案，首选的检查是",[["A","运动负荷心电图"],["B","动态心电图"],["C","动态血压"],["D","冠状动脉造影"]],"A","中老年男性患者，既往有高血压病和长期吸烟史（心血管疾病的高危因素）。劳累后出现胸部憋闷、咽部发紧的症状，并在数分钟后缓解（提示可能存在心肌缺血），查体：BP142/88mmHg（正常参考值：90～139/60～89mmHg），辅助检查：冠状动脉CT显示右冠状动脉中段存在60%的狭窄。综合患者临床表现及辅助检查，该患者考虑诊断为冠心病，为了决定下一步治疗方案首选的检查是运动负荷心电图（A对），运动负荷心电图为无创检查，是通过运动增加心脏负荷而诱发心肌缺血，从而观察是否出现缺血性ST-T改变的检测方法。动态心电图（B错）主要用于捕捉一过性的心律失常或心肌缺血，适用于那些在日常生活中可能出现短暂心脏事件的患者，对冠心病诊断价值有限。动态血压（C错）主要用于评估高血压，而该患者的主要问题在于可能存在心肌缺血，因此该患者不适用。冠状动脉造影（D错）虽然是冠心病诊断的“金标准”可发现狭窄性病变的位置并估计其程度，但为有创检查，一般需要在无创检查不能确诊时才采用。","","N"],["2025-N47",15,"第三节 急性心力衰竭","血管扩张剂",2025,47,"A","","男性，50岁。1小时前因情绪激动突感胸闷、呼吸困难、咳嗽、咳泡沫样痰，急送来院。既往有高血压病15年，陈旧心肌梗死4年。查体：BP196/108mmHg，半卧位，双肺可闻及湿啰音，心率112次/分，心律齐。应选择的最佳治疗药物是",[["A","尼卡地平"],["B","硝酸甘油"],["C","硝普钠"],["D","多巴酚丁胺"]],"C","中年男性患者，既往有高血压和陈旧性心肌梗死病史。因情绪激动突发胸闷、呼吸困难、咳粉红泡沫痰（提示左心衰竭肺淤血），查体：血压196/108mmHg（正常参考值：90～139/60～89mmHg，提示3级高血压），半卧位，双肺湿啰音（提示左心衰竭肺淤血），心率112次/分（正常参考值：60～100次/分），综合患者既往病史、临床表现，该患者考虑诊断为急性左心衰竭。该患者目前的治疗目标是扩张血管，减轻心脏后负荷，减轻肺水肿，所以首选硝普钠（C对），硝普钠可扩张动脉与静脉，起效快速，在急性左心衰竭的治疗中能迅速降低血压、减轻心脏负担并改善心功能。尼卡地平（A错）为钙通道阻滞剂，适用于高血压合并冠心病的患者，但对急性左心衰竭的迅速降压和改善心功能效果并不理想，且有头痛、潮红和心动过速等不良反应，该患者目前心率较快，所以不适用。硝酸甘油（B错）主要通过扩张静脉来减轻心脏前负荷，对降低动脉血压的作用较弱，因此不是最佳选择。多巴酚丁胺（D错）为非洋地黄类正性肌力药的静脉制剂，是多巴胺的衍生物，主要作用是增强心肌收缩力，而该患者目前需要降低血压，减轻心脏负荷，所以不适用。","","N"],["2025-N48",23,"第一节 感染性心内膜炎","择期手术",2025,48,"A","","自体瓣膜感染性心内膜炎需行外科手术治疗的适应证是",[["A","并发肾动脉栓塞"],["B","真菌性心内膜炎"],["C","主动脉瓣可见赘生物"],["D","出现Janeway损害"]],"B","自体瓣膜感染性心内膜炎主要是由链球菌和葡萄球菌引起，自体瓣膜感染性心内膜炎的治疗包括抗微生物药物治疗和外科手术治疗。外科手术治疗的适应症分为紧急手术（＜24 小时）和外科手术（＜7 天），外科手术的适应症包括：主动脉瓣或二尖瓣伴有急性重度反流、阻塞引起伴有症状的心衰或超声心动提示血流动力学异常；未能控制的局灶性感染灶；真菌或多重耐药菌造成的感染（B对）；规范抗感染、控制脓毒血症转移灶治疗措施情况下仍存在血培养阳性；二尖瓣或主动脉瓣的感染性心内膜炎在正确抗感染治疗下出现过≥1次栓塞事件，且赘生物＞10mm；二尖瓣或主动脉瓣的赘生物＞10mm，严重瓣膜狭窄或反流；二尖瓣或主动脉瓣的感染性心内膜炎伴有单个巨大赘生物（＞30mm）；二尖瓣或主动脉瓣的感染性心内膜炎伴有单个巨大赘生物（＞15mm），可以考虑手术治疗。并发肾动脉栓塞（A错）并不属于自体瓣膜感染性心内膜炎外科手术治疗的适应症。主动脉瓣出现赘生物（C错）手术治疗时需要考虑赘生物的大小以及是否存在瓣膜狭窄及反流等情况。Janeway损害（D错）为感染性心内膜炎的一种皮肤表现，是手掌和足底处直径1～4mm的无痛性出血红斑，不是外科手术治疗的适应症。","","N"],["2025-N49",24,"第一节 心脏骤停与心脏性猝死","初级心肺复苏",2025,49,"A","","关于心脏骤停的初级心肺复苏，不正确的是",[["A","首选心内注射给药"],["B","人工胸外按压"],["C","开通气道"],["D","人工呼吸"]],"A","心脏骤停指心脏射血功能突然终止，造成全身血液循环中断、呼吸停止和意识丧失。心脏骤停的生存率很低，抢救成功的关键是尽早进行心肺复苏和尽早进行复律治疗。心肺复苏分初级心肺复苏和高级心肺复苏，其中初级心肺复苏包括人工胸外按压（B对）、开放气道（C对）和人工呼吸（D对）。心内注射药物（A错，为本题正确答案）需要专业设备和专业人员，操作复杂且风险较高，通常不推荐使用。","","N"],["2025-N50",26,"第一节 胃食管反流病","PPI",2025,50,"A","","女性，42岁。反复反酸、烧心10余年，平卧位时明显，近2个月来加重并影响睡眠，最适宜的治疗药物是",[["A","促胃肠动力剂"],["B","抗酸剂"],["C","质子泵抑制剂"],["D","组胺H₂受体拮抗剂"]],"C","中年女性患者，长期反酸、烧心（胃食管反流病的典型症状），平卧时明显，近期症状加重并影响睡眠，综合患者临床表现，该患者考虑诊断为胃食管反流病。胃食管反流病的目的在于控制症状、治愈食管炎、减少复发和防治并发症，治疗首选质子泵抑制剂（C对），其抑酸作用强，疗效确切，通常疗程4～8周。促胃肠动力药（A错）通过增加食管下括约肌压力、改善食管蠕动功能、促进胃排空缓解部分症状，适用于轻症病人，或与抑酸药联用使用。抗酸剂（B错）能快速中和胃酸，缓解症状，但效果短暂，仅用于症状轻、间歇发作的病人。组胺H₂受体拮抗剂（D错）虽然也能抑制胃酸分泌，但效果相对于质子泵抑制剂较弱，不作为首选。","","N"],["2025-N51",29,"第一节 肠结核","肠结核病理",2025,51,"A","","肠结核最常见的病变部位是",[["A","乙状结肠"],["B","降结肠"],["C","升结肠及横结肠"],["D","回肠及盲肠"]],"D","肠结核是由结核分枝杆菌引起的肠道慢性特异性感染，其好发部位主要位于回肠和盲肠（D对），这是因为该区域淋巴组织丰富，含结核分枝杆菌的肠内容物在回盲部停留较久，增加了局部黏膜的感染机会。虽然肠结核可发生在结肠和直肠的任何部位，由于淋巴组织少且肠内容物通过较快，所以乙状结肠（A错）、降结肠（B错）、升结肠和横结肠（C错）均不是肠结核的好发部位。","","N"],["2025-N52",30,"第一节 溃疡性结肠炎","结肠镜",2025,52,"A","","男性，43岁。间断黏液脓血便1年余，抗菌药物治疗效果不佳，近1周加重。查体：腹平软，左下腹轻压痛，未触及包块。肛诊未发现肛周病变。对明确诊断最有意义的检查是",[["A","粪常规"],["B","粪细菌培养"],["C","钡剂灌肠"],["D","结肠镜"]],"D","中年男性患者，长期间断出现黏液脓血便（溃疡性结肠炎的主要症状），抗菌药物治疗效果不佳（提示非细菌性肠道炎症），近期病情加重，查体：左下腹轻压痛。综合患者临床表现，该患者考虑诊断为溃疡性结肠炎。为明确诊断，最有意义的检查方法为结肠镜（D对），其可直接观察肠道黏膜病变，并可取活检进行组织学检查，是诊断溃疡性结肠炎的金标准。粪常规（A错）虽然可以检测粪便中的红细胞、白细胞等以评估消化道情况，但无法直接观察肠道黏膜病变，对溃疡性结肠炎的诊断意义有限。粪细菌培养（B错）主要用于检测病原菌，对细菌性肠炎有重要意义，但溃疡性结肠炎并非由细菌感染直接引起，因此对其诊断价值不大。钡剂灌肠（C错）可显示肠道形态和结构改变，但对肠道黏膜细微病变显示不佳，且不能取活检，诊断准确性不如结肠镜。","","N"],["2025-N53",39,"第一节 总论","尿相差显微镜检查",2025,53,"A","","男性，35岁。体检尿常规沉渣镜检RBC5～8个/HP，余未见异常。次日复查结果相同。测血压120/80mmHg。B超示双肾未见明显异常。首选的进一步检查是",[["A","血肌酐"],["B","相差显微镜查尿红细胞形态"],["C","肾脏CT检查"],["D","肾穿刺活检"]],"B","青年男性患者，尿常规沉渣镜检发现红细胞5～8个/HP（提示显微镜下血尿），次日复查结果同前，血压正常，B超检查未见双肾明显结构性问题，为明确血尿来源是肾小球性还是非肾小球性，下一步首选的检查是相差显微镜查尿红细胞形态（B对）。血肌酐（A错）主要用于评估肾功能，并不能直接明确尿红细胞的来源。肾脏CT检查（C错）通常用于评估肾脏结构性异常，目前B超已经排除了该患者肾脏结构性问题，而且肾脏CT检查也不能明确尿红细胞的来源。肾穿刺活检（D错）虽然是诊断肾脏疾病的金标准，但其属于侵入性检查，通常需要在无创检查无法明确诊断时才考虑，所以不作为首选。","","N"],["2025-N54",49,"第一节 再生障碍性贫血","AA骨髓象",2025,54,"A","","男性，26岁。乏力、头晕2个月，加重伴牙龈出血1周。既往体健。查体：皮肤可见散在出血点，浅表淋巴结未触及，巩膜无黄染，肝脾肋下未触及。血常规：Hb72g/L，RBC2.4×10¹²/L，Ret0.1%，WBC2.9×10⁹/L，Plt30×10⁹/L；髂后骨髓细胞学检查示增生低下。为明确诊断，最有价值的进一步检查是",[["A","外周血白细胞分类计数"],["B","血清铁和铁蛋白测定"],["C","血清叶酸和维生素B₁₂测定"],["D","胸骨骨髓细胞学检查"]],"D","青年男性患者，出现头晕乏力和牙龈出血的症状，查体：皮肤散在出血点，辅助检查：血常规：Hb72g/L（正常参考值：成年男性130～175g/L，提示该患者为中度贫血），RBC2.4×10¹²/L（正常参考值：成年男性4.3～5.8×10¹²/L），Ret0.1%（网织红细胞，成人正常参考值：0.5%～1.5%），WBC2.9×10⁹/L（正常参考值：3.5～9.5×10⁹/L，提示白细胞减少），PLT30×10⁹/L（正常参考值：125～350×10⁹/L，提示血小板减少），髂后骨髓细胞学检查呈现增生低下，综合患者临床表现及辅助检查，该患者考虑诊断为再生障碍性贫血。为了明确诊断，最有价值的进一步检查是胸骨骨髓细胞学检查（D对），髂后骨髓细胞学检查后再行胸骨穿刺，是明确再生障碍性贫血多部位增生异常的诊断流程，再生障碍性贫血表现为全血细胞减少，骨髓多部位增生减低，如果胸骨骨髓细胞学检查结果呈现增生低下对明确诊断有很大意义。外周血白细胞分类计数（A错）可用于鉴别感染原因及血液系统恶性肿瘤的分类，但对再生障碍性贫血的诊断帮助不大。血清铁和铁蛋白测定（B错）主要诊断由铁缺乏或利用障碍导致的贫血，对再生障碍性贫血的诊断作用不大。血清叶酸和VitB₁₂测定（C错）用于诊断巨幼细胞贫血，对再生障碍性贫血的诊断意义不大。","","N"],["2025-N55",60,"第五节 嗜铬细胞瘤","嗜铬细胞瘤心血管系统表现",2025,55,"A","","关于嗜铬细胞瘤临床特点的叙述，错误的是",[["A","本病瘤体80%～90%位于肾上腺"],["B","多数位于肾上腺外的瘤体主要分泌肾上腺素"],["C","阵发性高血压、血压骤升是其特征性表现"],["D","儿童或青年出现直立性低血压不能排除本病"]],"B","嗜铬细胞瘤起源于肾上腺髓质、交感神经节或其他部位的嗜铬组织，位于肾上腺者占80%～90%（A对），大多为一侧性，肾上腺髓质的嗜铬细胞瘤可产生去甲肾上腺素和肾上腺素，以前者为主，而位于肾上腺外的瘤体（除主动脉旁嗜铬体外），只产生去甲肾上腺素，不能合成肾上腺素（B错，为本题正确答案）。嗜铬细胞瘤能持续或间断地释放大量儿茶酚胺，阵发性高血压、血压骤升是其特征性表现（C对）。虽然嗜铬细胞瘤多见于成年人，但儿童或青少年也可能出现，如果出现直立性低血压，伴多汗、心动过速、烦躁等症状，不能排除嗜铬细胞瘤（D对）。","","N"],["2025-N56",67,"第一节 风湿系统疾病总论","抗磷脂抗体",2025,56,"A","","下列属于抗磷脂抗体的是",[["A","抗β₂GPI抗体"],["B","抗dsDNA抗体"],["C","抗Sm抗体"],["D","抗SSA抗体"]],"A","抗磷脂抗体包括抗β₂GPI（β₂-糖蛋白1）抗体（A对）、抗心磷脂抗体、狼疮抗凝物，抗β₂GPI抗体与血栓形成有较强的相关性，其次是血小板减少、APTT 延长、深静脉血栓形成和流产等。抗dsDNA抗体（B错）是针对双链DNA的抗体，常被作为SLE活动的指标，可用于监测SLE病情变化、SLE疾病活动性判断、药物治疗效果观察等。抗Sm抗体（C错）属于抗非组蛋白抗体，是目前公认的SLE的血清标记抗体。抗SSA抗体（D错）属于抗非组蛋白抗体，主要见于原发性干燥综合征，也可见于SLE和类风湿关节炎等。","","N"],["2025-N68",29,"第二节 结核性腹膜炎","结核性腹膜炎诊断",2025,68,"A","","女性，34岁。1个月来乏力、午后低热，2周来出现腹胀，脐周及下腹部持续性隐痛，食欲下降，大便2～3次/天，不成形。月经稀少、不规律，结婚8年未孕。查体：T37.5℃，消瘦体型，心肺（-），腹部膨隆，全腹有轻压痛及反跳痛，移动性浊音（+）。腹部X线平片示盆腔可见散在钙化影。最可能的诊断是",[["A","化脓性腹膜炎"],["B","结核性腹膜炎"],["C","自发性细菌性腹膜炎"],["D","腹腔恶性肿瘤"]],"B","青年女性患者。1个月来乏力、午后低热（结核毒血症状），2周来出现腹胀，脐周及下腹部持续性隐痛，食欲下降，大便2～3次/天，不成型，月经稀少不规律，结婚8年未孕（提示可能存在生殖系统结核），查体：T37.5℃（正常参考值：36～37℃，提示该患者低热），消瘦，腹部膨隆，全腹有轻压痛及反跳痛，移动性浊音（+）（提示腹腔积液），辅助检查：腹部X线平片示盆腔可见散在钙化影（结核性腹膜炎的常见影像学表现）。综合患者的临床表现及影像学检查，该患者最可能的诊断是结核性腹膜炎（B对）。化脓性腹膜炎（A错）通常由腹腔空腔脏器穿孔引起，病情急骤，突发剧烈腹痛，持续而加剧，有腹壁板样僵直，压痛、反跳痛，肝浊音界消失等体征。自发性细菌性腹膜炎（C错）多与肝硬化腹水相关，患者有肝硬化的相关临床表现，同时可出现低热、腹胀或腹腔积液持续不减，病情进展快者可出现明显腹痛、腹腔积液增长迅速，甚至诱发肝性脑病。腹腔恶性肿瘤（D错）可表现为腹痛、腹胀、腹水、肠梗阻、恶心、呕吐等症状，腹部X线平片可见腹腔占位。","c211","N"],["2025-N69",29,"第二节 结核性腹膜炎","结核性腹膜炎临床表现",2025,69,"A","","女性，34岁。1个月来乏力、午后低热，2周来出现腹胀，脐周及下腹部持续性隐痛，食欲下降，大便2～3次/天，不成形。月经稀少、不规律，结婚8年未孕。查体：T37.5℃，消瘦体型，心肺（-），腹部膨隆，全腹有轻压痛及反跳痛，移动性浊音（+）。腹部X线平片示盆腔可见散在钙化影。该患者疾病可能出现的特征性体征是",[["A","腹部触诊柔韧感"],["B","可触及痉挛的降结肠"],["C","肝浊音界消失"],["D","可见腹壁静脉曲张"]],"A","青年女性患者。1个月来乏力、午后低热（结核毒血症状），2周来出现腹胀，脐周及下腹部持续性隐痛，食欲下降，大便2～3次/天，不成型，月经稀少不规律，结婚8年未孕（提示可能存在生殖系统结核），查体：T37.5℃（正常参考值：36～37℃，提示该患者低热），消瘦，腹部膨隆，全腹有轻压痛及反跳痛，移动性浊音（+）（提示腹腔积液），辅助检查：腹部X线平片示盆腔可见散在钙化影（结核性腹膜炎的常见影像学表现）。综合患者的临床表现及影像学检查，该患者最可能的诊断是结核性腹膜炎。该患者可能出现的特征性体征是腹部触诊柔韧感（A对），主要是因为腹膜受刺激或因慢性炎症而增厚、腹壁肌张力增高、腹壁与腹内脏器粘连所引起。可触及痉挛的降结肠（B错）是溃疡性结肠炎的体征。肝浊音界消失（C错）主要见于消化道穿孔所致的急性腹膜炎。腹壁静脉曲张（D错）提示门静脉高压导致侧支循环开放，主要见于肝硬化失代偿期。","c211","N"],["2025-N70",29,"第二节 结核性腹膜炎","腹腔积液检查",2025,70,"A","","女性，34岁。1个月来乏力、午后低热，2周来出现腹胀，脐周及下腹部持续性隐痛，食欲下降，大便2～3次/天，不成形。月经稀少、不规律，结婚8年未孕。查体：T37.5℃，消瘦体型，心肺（-），腹部膨隆，全腹有轻压痛及反跳痛，移动性浊音（+）。腹部X线平片示盆腔可见散在钙化影。该患者行腹腔穿刺积液检查，对确诊最有价值的检验结果是",[["A","比重1.020"],["B","Rivalta试验阳性"],["C","有核细胞计数大于500×10⁶/L"],["D","腺苷脱氨酶升高"]],"D","青年女性患者。1个月来乏力、午后低热（结核毒血症状），2周来出现腹胀，脐周及下腹部持续性隐痛，食欲下降，大便2～3次/天，不成型，月经稀少不规律，结婚8年未孕（提示可能存在生殖系统结核），查体：T37.5℃（正常参考值：36～37℃，提示该患者低热），消瘦，腹部膨隆，全腹有轻压痛及反跳痛，移动性浊音（+）（提示腹腔积液），辅助检查：腹部X线平片示盆腔可见散在钙化影（结核性腹膜炎的常见影像学表现）。综合患者的临床表现及影像学检查，该患者最可能的诊断是结核性腹膜炎。行腹腔穿刺抽液检查对于确诊结核性腹膜炎具有重要意义，腹腔积液多为草黄色渗出液，Rivalta试验（+），静置后可自然凝固，比重一般超过 1.018，蛋白质定性试验阳性，定量在 30g/L以上，白细胞计数超过500×10⁶/L，以淋巴细胞或单核细胞为主，腺苷脱氨酶（ADA）活性增高，ADA同工酶ADA2升高对确诊有一定特异性（D对）。而比重1.020（A错）和Rivalta试验（+）（B错）主要提示腹腔积液为渗出液，对于诊断结核性腹膜炎不具有特异性，如果有核细胞计数＞500×10⁶/L（C错），同时以淋巴细胞或单核细胞升高为主则对结核性腹膜炎有一定的提示作用。","c211","N"],["2025-N71",61,"第二节 糖尿病酮症酸中毒","糖尿病酮症酸中毒诊断",2025,71,"A","","路遇一中年患者，意识不清，大声呼唤不醒，可闻到烂苹果味。查体：P102次/分，皮肤干燥，口唇无发绀，肢体无抽搐，四肢末梢皮肤发凉，无自主活动。该患者意识障碍最可能的原因是",[["A","急性脑卒中"],["B","感染性休克"],["C","糖尿病酮症酸中毒"],["D","急性有机磷农药中毒"]],"C","路遇一中年患者，出现意识障碍，大声呼喊无反应，其呼出气带有烂苹果味（丙酮，提示糖尿病酮症酸中毒），查体：P102/分（正常参考值：60～100次/分），皮肤干燥，四肢末梢皮肤发凉（提示严重失水），无自主活动。综合患者临床表现，该患者意识障碍最可能的原因为糖尿病酮症酸中毒（C对）。急性脑卒中（A错）包括缺血性脑卒中和出血性脑卒中，患者多具有高龄、高血压、心脏病、高脂血症、糖尿病和吸烟等危险因素，临床表现为一侧肢体无力或麻木，一侧面部麻木或口角歪斜，伴言语困难和意识障碍等。感染性休克（B错）由严重脓毒症或毒血症发展而来，患者表现为烦躁不安、面色苍白、口唇发绀、皮肤花斑、四肢厥冷、脉搏细速、尿量减少及血压下降。急性有机磷农药中毒（D错）患者表现为毒蕈碱样症状（瞳孔缩小、腹痛、腹泻、大小便失禁、大汗、流泪、流涎和呼吸困难等）、烟碱样症状（肌纤维颤动、全身肌强直性痉挛、血压增高和心律失常等）、中枢神经系统症状（头晕、头痛、烦躁不安和昏迷等）和局部皮肤损害，且呼出气体为大蒜味。","c212","N"],["2025-N72",61,"第二节 糖尿病酮症酸中毒","糖尿病酮症酸中毒临床表现",2025,72,"A","","路遇一中年患者，意识不清，大声呼唤不醒，可闻到烂苹果味。查体：P102次/分，皮肤干燥，口唇无发绀，肢体无抽搐，四肢末梢皮肤发凉，无自主活动。该患者最可能出现的呼吸类型是",[["A","库斯莫尔呼吸"],["B","潮式呼吸"],["C","间停呼吸"],["D","抑制性呼吸"]],"A","路遇一中年患者，出现意识障碍，大声呼喊无反应，其呼出气带有烂苹果味（丙酮，提示糖尿病酮症酸中毒），查体：P102/分（正常参考值：60～100次/分），皮肤干燥，四肢末梢皮肤发凉（提示严重失水），无自主活动。综合患者临床表现，该患者意识障碍最可能的原因为糖尿病酮症酸中毒。该患者最有可能的呼吸类型为库斯莫尔呼吸（A对），因为该患者出现了严重代谢性酸中毒，需要通过深而快的呼吸，通过肺脏排出CO₂进行代偿，以调节细胞外酸碱平衡。潮式呼吸（B错）是一种由浅慢逐渐变为深快，然后再由深快转为浅慢，随之出现一段呼吸暂停后，又开始如上变化的周期性呼吸，可见于吗啡类、巴比妥类等中枢抑制药物中毒，虽然也可发生于糖尿病酮症酸中毒，但相对少见。间停呼吸（C错）表现为有规律呼吸几次后，突然停止一段时间，又开始呼吸，间停呼吸较潮式呼吸更为严重，常在临终前发生。抑制性呼吸（D错）为胸部发生剧烈疼痛所致的吸气相突然中断，呼吸运动短暂地突然受到抑制，常见于急性胸膜炎、肋骨骨折及胸部严重外伤等。","c212","N"],["2025-N73",8,"第二节 特发性肺纤维化","特发性肺纤维化诊断",2025,73,"A","","男性，65岁。干咳伴活动耐力下降半年。查体：双下肺可闻及湿啰音，可见杵状指。胸部CT显示双下肺、胸膜下分布的网格影及蜂窝影，伴牵拉性支气管扩张。最可能的诊断是",[["A","慢性阻塞性肺疾病"],["B","支气管扩张症"],["C","特发性肺纤维化"],["D","结节病"]],"C","老年男性患者，出现干咳、活动耐力下降的症状（特发性肺纤维化的常见临床表现），查体：双下肺可闻及湿啰音，杵状指，辅助检查：胸部CT显示双下肺及胸膜下的网格影和蜂窝影（特发性肺纤维化的常见影像学表现），伴有牵拉性支气管扩张。综合患者的临床表现及辅助检查，该患者最可能的诊断是特发性肺纤维化（C对）。慢性阻塞性肺病（A错）患者具有长期吸烟史，临床表现为慢性咳嗽咳痰、气短、呼吸困难，查体可见桶状胸，肺部听诊呈过清音，肺部CT可见小气道病变及肺气肿的影像学表现。支气管扩张症（B错）临床表现主要为慢性咳嗽、咯大量脓痰和（或）反复咯血，胸部高分辨率CT可见支气管呈柱状及囊状改变，气道壁增厚、黏液阻塞、树芽征等。结节病（D错）是一种原因不明的多系统累及的肉芽肿性疾病，主要侵犯肺和淋巴系统，临床过程表现多样，急性结节病可表现为双肺门淋巴结肿大，关节炎和结节性红斑，肺部高分辨率CT的典型表现为沿着肺上叶支气管血管束分布的微小结节，可融合成球。","c213","N"],["2025-N74",8,"第二节 特发性肺纤维化","肺功能",2025,74,"A","","男性，65岁。干咳伴活动耐力下降半年。查体：双下肺可闻及湿啰音，可见杵状指。胸部CT显示双下肺、胸膜下分布的网格影及蜂窝影，伴牵拉性支气管扩张。肺功能检查最可能的结果是",[["A","阻塞性通气功能障碍、弥散功能减低"],["B","阻塞性通气功能障碍、弥散功能正常"],["C","限制性通气功能障碍、弥散功能减低"],["D","混合性通气功能障碍、弥散功能减低"]],"C","老年男性患者，出现干咳、活动耐力下降的症状（特发性肺纤维化的常见临床表现），查体：双下肺可闻及湿啰音，杵状指，辅助检查：胸部CT显示双下肺及胸膜下的网格影和蜂窝影（特发性肺纤维化的常见影像学表现），伴有牵拉性支气管扩张。综合患者的临床表现及辅助检查，该患者最可能的诊断是特发性肺纤维化。由于该患者出现了肺纤维化，肺的顺应性降低，使肺泡扩张的弹性阻力增大而导致限制性通气不足，同时肺纤维化导致肺泡膜厚度增加，弥散距离增宽，使弥散速度减慢，弥散指数下降（C对）。阻塞性呼吸困难，弥散指数下降（A错）可见于肺气肿、慢性阻塞性肺疾病等。阻塞性呼吸困难，弥散指数正常（B错）可见于支气管哮喘。混合型呼吸困难，弥散指数下降（D错）可见于肺气肿伴轻度充血性心力衰竭等。","c213","N"],["2025-N75",8,"第二节 特发性肺纤维化","抗纤维化药物治疗",2025,75,"A","","男性，65岁。干咳伴活动耐力下降半年。查体：双下肺可闻及湿啰音，可见杵状指。胸部CT显示双下肺、胸膜下分布的网格影及蜂窝影，伴牵拉性支气管扩张。首选的治疗药物是",[["A","糖皮质激素"],["B","环磷酰胺"],["C","甲氨蝶呤"],["D","吡非尼酮"]],"D","老年男性患者，出现干咳、活动耐力下降的症状（特发性肺纤维化的常见临床表现），查体：双下肺可闻及湿啰音，杵状指，辅助检查：胸部CT显示双下肺及胸膜下的网格影和蜂窝影（特发性肺纤维化的常见影像学表现），伴有牵拉性支气管扩张。综合患者的临床表现及辅助检查，该患者最可能的诊断是特发性肺纤维化。特发性肺纤维化的治疗包括抗纤维化药物治疗、非药物治疗、合并症治疗、姑息治疗、疾病的监测、病人教育和自我管理，首选的药物治疗为吡非尼酮（D对），吡非尼酮是一种多效性的吡啶化合物，具有抗炎、抗纤维化和抗氧化特性，由于特发性肺纤维化对激素或细胞毒制剂反应差，所以糖皮质激素（A错）、环磷酰胺（B错）和甲氨蝶呤（C错）不作为首选治疗药物。","c213","N"],["2025-N76",16,"第五节 室性心律失常","室性期前收缩诊断",2025,76,"A","","男性，55岁。扩张型心肌病15年，慢性心力衰竭3年，长期服用呋塞米治疗。5天前上感，发热，乏力。半小时前突发心悸，伴意识丧失半分钟，急来院诊治。查体：T37.8℃，P82次/分，BP90/60mmHg，神清，颈静脉充盈，双肺可闻及湿啰音，心界向左扩大，心率98次/分，心律不齐，心尖部第一心音低钝，肝肋下1cm，肠鸣音弱，下肢无水肿，膝反射减弱，病理反射未引出。心电监测示频发多源性室性早搏。该患者突发意识丧失最可能的病因是",[["A","全心衰竭"],["B","感染中毒性脑病"],["C","低血压"],["D","恶性心律失常"]],"D","中年男性患者，扩张型心肌病15年（易并发各种心律失常），慢性心力衰竭3年，长期服用呋塞米治疗（易出现电解质紊乱）。5天前上感，发热，乏力。半小时前突发心悸，伴意识丧失半分钟（提示出现心律失常）。查体：T37.8℃（正常参考值：36～37℃），P82次/分，BP90/60mmHg（正常参考值：90～139/60～89mmHg），神清，颈静脉充盈（提示右心功能不全），双肺可闻及湿啰音，心界向左扩大（提示左心室增大），心率98次/分，心律不齐（提示房颤），心尖部第一心音低顿，肝肋下1cm（肝大，提示右心衰竭），肠鸣音弱，膝反射减弱。心电监测示频发多源室性早搏。综合患者病史、临床表现及心电图检查，该患者突发意识丧失最可能的病因是恶性心律失常（D对）。该患者有长期扩张型心肌病病史，且由左心衰竭继发右心衰竭而形成全心衰竭，但全心衰竭通常不会直接导致意识丧失（A错）。感染中毒性脑病（B错）可以引起意识丧失，但存在感染原发灶的相关临床表现，同时伴严重头痛、呕吐、高热等症状。低血压（C错）也可以引起意识丧失，但有直接导致血压降低的相关病因，如大量失血、严重体液丢失或严重脓毒血症等，而该患者无相关病史，所以可排除。","c214","N"],["2025-N77",19,"第二节 扩张型心肌病","扩张型心肌病发病机制",2025,77,"A","","男性，55岁。扩张型心肌病15年，慢性心力衰竭3年，长期服用呋塞米治疗。5天前上感，发热，乏力。半小时前突发心悸，伴意识丧失半分钟，急来院诊治。查体：T37.8℃，P82次/分，BP90/60mmHg，神清，颈静脉充盈，双肺可闻及湿啰音，心界向左扩大，心率98次/分，心律不齐，心尖部第一心音低钝，肝肋下1cm，肠鸣音弱，下肢无水肿，膝反射减弱，病理反射未引出。心电监测示频发多源性室性早搏。导致出现上述病因最可能的机制是",[["A","电解质紊乱"],["B","脑水肿"],["C","循环血容量不足"],["D","脑供血不全"]],"A","中年男性患者，扩张型心肌病15年（易并发各种心律失常），慢性心力衰竭3年，长期服用呋塞米治疗（易出现电解质紊乱）。5天前上感，发热，乏力。半小时前突发心悸，伴意识丧失半分钟（提示出现心律失常）。查体：T37.8℃（正常参考值：36～37℃），P82次/分，BP90/60mmHg（正常参考值：90～139/60～89mmHg），神清，颈静脉充盈（提示右心功能不全），双肺可闻及湿啰音，心界向左扩大（提示左心室增大），心率98次/分，心律不齐（提示房颤），心尖部第一心音低顿，肝肋下1cm（肝大，提示右心衰竭），肠鸣音弱，膝反射减弱（常见于低钾血症）。心电监测示频发多源室性早搏。综合患者病史、临床表现及心电图检查，该患者突发意识丧失最可能的病因是恶性心律失常。该患者出现恶性心律失常的主要原因是电解质紊乱（A对），该患者因扩张型心肌病、慢性心力衰竭而服用呋塞米治疗，长期可导致低钾血症，严重者可引起室上性或室性心动过速、房颤等心律失常。脑水肿（B错）主要表现为颅内压增高，典型症状为头痛、呕吐和视神经乳头水肿，不会引起恶性心律失常。循环容量不足（C错）会导致休克，表现为脸色苍白，四肢湿冷，脉搏加快，尿量减少、烦躁不安等，不会引起恶性心律失常。脑供血不全（D错）可出现头昏、晕倒和意识丧失等症状，脑供血不足可由严重心律失常引起，但脑供血不足不会引起恶性心律失常。","c214","N"],["2025-N78",19,"第二节 扩张型心肌病","扩张型心肌病实验室检查",2025,78,"A","","男性，55岁。扩张型心肌病15年，慢性心力衰竭3年，长期服用呋塞米治疗。5天前上感，发热，乏力。半小时前突发心悸，伴意识丧失半分钟，急来院诊治。查体：T37.8℃，P82次/分，BP90/60mmHg，神清，颈静脉充盈，双肺可闻及湿啰音，心界向左扩大，心率98次/分，心律不齐，心尖部第一心音低钝，肝肋下1cm，肠鸣音弱，下肢无水肿，膝反射减弱，病理反射未引出。心电监测示频发多源性室性早搏。对该患者即刻选择最重要的辅助检查是",[["A","超声心动图"],["B","血生化及电解质"],["C","头颅MRI"],["D","心肌损伤标志物"]],"B","中年男性患者，扩张型心肌病15年（易并发各种心律失常），慢性心力衰竭3年，长期服用呋塞米治疗（易出现电解质紊乱）。5天前上感，发热，乏力。半小时前突发心悸，伴意识丧失半分钟（提示出现心律失常）。查体：T37.8℃（正常参考值：36～37℃），P82次/分，BP90/60mmHg（正常参考值：90～139/60～89mmHg），神清，颈静脉充盈（提示右心功能不全），双肺可闻及湿啰音，心界向左扩大（提示左心室增大），心率98次/分，心律不齐（提示房颤），心尖部第一心音低顿，肝肋下1cm（肝大，提示右心衰竭），肠鸣音弱，膝反射减弱（常见于低钾血症）。心电监测示频发多源室性早搏。综合患者病史、临床表现及心电图检查，该患者突发意识丧失最可能的病因是恶性心律失常，出现恶性心律失常的病因是电解质紊乱，所以该患者需即刻进行的紧急辅助检查是血生化及电解质（B对）。超声心动图（A错）是评估扩张型心肌病和心力衰竭的重要检查手段，但在此紧急情况下并非首选。头颅MRI（C错）对于诊断脑血管疾病有重要意义，对该患者不适用。心肌损伤标志物（D错）主要用于诊断心肌梗死，对该患者目前的诊断及病情评估作用不大。","c214","N"],["2025-N79",28,"第一节 消化性溃疡","消化性溃疡诊断",2025,79,"A","","男性，45岁。2年来间断上腹痛伴反酸、嗳气，腹痛一般多发生于进餐后1小时左右。2天来出现黑便。查体：BP105/80mmHg，心率85次/分，心律齐，上腹部轻压痛，肝脾肋下未触及。血常规：Hb116g/L，WBC10.6×10⁹/L，Plt255×10⁹/L；粪镜检阴性，隐血试验阳性。引起该患者黑便最可能的疾病是",[["A","胃癌"],["B","胃溃疡"],["C","慢性胃炎"],["D","十二指肠溃疡"]],"B","患者中年男性，2年来间歇性上腹痛（消化性溃疡典型症状），伴反酸，嗳气，腹痛常在饭后1小时发生（餐后痛，胃溃疡的典型症状），2天来出现黑便（提示消化道出血）。查体：BP105/80mmHg（正常参考值：90～139/60～89mmHg），心率85次/分（正常参考值：60～100次/分），上腹轻压痛，辅助检查：血常规：Hb116g/L（正常参考值：成年男性130～175g/L），WBC10.6×10⁹/L（正常参考值：3.5～9.5×10⁹/L），PLT255×10⁹/L（正常参考值：125～350×10⁹/L）；粪镜检阴性，隐血试验阳性（正常为阴性，提示消化道出血，出血量大于5ml，小于50ml）。根据患者的症状、体征及辅助检查，该患者出现黑便的原因为胃溃疡（B对）。胃癌（A错）多发生在55～70岁年龄段，早期可无明显症状，进展期胃癌最常见的症状为体重减轻和上腹痛，且腹痛不具有规律性。慢性胃炎（C错）症状多为非特异性，表现为中上腹不适、饱胀、钝痛、烧灼痛等，不会出现节律性、反复发作的上腹痛和黑便。十二指肠溃疡（D错）表现为规律性上腹痛，多为饥饿痛或夜间痛，进餐后缓解。","c215","N"],["2025-N80",28,"第一节 消化性溃疡","上消化道内镜检查及活检",2025,80,"A","","男性，45岁。2年来间断上腹痛伴反酸、嗳气，腹痛一般多发生于进餐后1小时左右。2天来出现黑便。查体：BP105/80mmHg，心率85次/分，心律齐，上腹部轻压痛，肝脾肋下未触及。血常规：Hb116g/L，WBC10.6×10⁹/L，Plt255×10⁹/L；粪镜检阴性，隐血试验阳性。最具有诊断意义的检查是",[["A","胃镜"],["B","上消化道造影"],["C","¹³C-尿素呼气试验"],["D","血清CEA"]],"A","患者中年男性，2年来间歇性上腹痛（消化性溃疡典型症状），伴反酸，嗳气，腹痛常在饭后1小时发生（餐后痛，胃溃疡的典型症状），2天来出现黑便（提示消化道出血）。查体：BP105/80mmHg（正常参考值：90～139/60～89mmHg），心率85次/分（正常参考值：60～100次/分），上腹轻压痛，辅助检查：血常规：Hb116g/L（正常参考值：成年男性130～175g/L），WBC10.6×10⁹/L（正常参考值：3.5～9.5×10⁹/L），PLT255×10⁹/L（正常参考值：125～350×10⁹/L）；粪镜检阴性，隐血试验阳性（正常为阴性，提示消化道出血，出血量大于5ml，小于50ml）。根据患者的症状、体征及辅助检查，该患者考虑诊断为胃溃疡。最有诊断价值的检查为胃镜（A对），胃镜可以直接观察胃黏膜病变，且能够直接取活检组织进行病理学检查，为诊断胃部疾病的金标准。上消化道造影（B错）虽然能观察胃黏膜形态，但其诊断敏感性不如胃镜，且无法直接活检。¹³C-尿素呼气试验（C错）主要用于幽门螺杆菌感染的检测，对于具体胃部疾病类型的诊断价值有限。血清CEA（癌胚抗原）（D错）是一种广谱性肿瘤标志物，可在胰腺癌、结肠癌、直肠癌、胃癌等表达增高，脏器特异性低，在临床上主要用于辅助恶性肿瘤的诊断、判断预后、监测疗效和肿瘤复发等。","c215","N"],["2025-N81",28,"第一节 消化性溃疡","PPI",2025,81,"A","","男性，45岁。2年来间断上腹痛伴反酸、嗳气，腹痛一般多发生于进餐后1小时左右。2天来出现黑便。查体：BP105/80mmHg，心率85次/分，心律齐，上腹部轻压痛，肝脾肋下未触及。血常规：Hb116g/L，WBC10.6×10⁹/L，Plt255×10⁹/L；粪镜检阴性，隐血试验阳性。目前最主要的治疗是",[["A","抗Hp治疗"],["B","止血药物治疗"],["C","应用质子泵抑制剂"],["D","手术治疗"]],"C","患者中年男性，2年来间歇性上腹痛（消化性溃疡典型症状），伴反酸，嗳气，腹痛常在饭后1小时发生（餐后痛，胃溃疡的典型症状），2天来出现黑便（提示消化道出血）。查体：BP105/80mmHg（正常参考值：90～139/60～89mmHg），心率85次/分（正常参考值：60～100次/分），上腹轻压痛，辅助检查：血常规：Hb116g/L（正常参考值：成年男性130～175g/L），WBC10.6×10⁹/L（正常参考值：3.5～9.5×10⁹/L），PLT255×10⁹/L（正常参考值：125～350×10⁹/L）；粪镜检阴性，隐血试验阳性（正常为阴性，提示消化道出血，出血量大于5ml，小于50ml）。根据患者的症状、体征及辅助检查，该患者考虑诊断为胃溃疡，伴少量溃疡出血，目前最适合的治疗方式是质子泵抑制剂（C对），质子泵抑制剂可以明显抑制胃酸分泌，止血效果显著，并在2～3天内可控制溃疡症状。HP（幽门螺杆菌）是消化性溃疡的重要致病因素，但题干未明确提及患者是否感染HP，而且患者目前的主要问题是胃溃疡出血，所以目前不需要进行抗HP治疗（A错）。当患者胃溃疡并大量出血时，可以使用去甲肾上腺素反复灌洗胃腔局部止血，但该患者目前出血量少，暂时不需要进行止血药物治疗（B错）。手术治疗（D错）的适应证有消化性溃疡并发消化道大出血经药物、胃镜及血管介入治疗无效或急性穿孔、慢性穿透溃疡等，该患者目前出血量较少，无需手术治疗。","c215","N"],["2025-N82",40,"第七节 慢性肾小球肾炎","慢性肾小球肾炎实验室检查",2025,82,"A","","男性，45岁。3年多来乏力、间断性下肢水肿，未诊治。1个多月来加重，伴食欲减退。无高血压病家族史。查体：BP160/95mmHg，轻度贫血貌，双下肢轻度可凹性水肿。尿常规：蛋白（++），沉渣镜检RBC10～15个/HP；血Cr176μmol/L。对明确诊断和指导治疗最有价值的检查是",[["A","24小时尿蛋白定量"],["B","双肾B超"],["C","肾活检病理检查"],["D","肾动脉造影"]],"C","患者中年男性，乏力、间断性下肢水肿3年（病程大于3个月，提示慢性病程），病情加重1月，伴食欲减退，查体：BP：160/95mmHg（正常参考值：90～139/60～89mmHg，提示2级高血压），轻度贫血貌，双下肢轻度可凹性水肿，辅助检查：尿常规：蛋白（++）（正常尿蛋白定性：阴性，提示蛋白尿），沉渣镜检RBC10～15个/HP（正常为阴性，提示显微镜下血尿），血Cr176μmol/L（正常参考值：成年男性57～97μmol/L，提示肾功能受损）。根据患者临床表现及辅助检查，该患者最可能的诊断为慢性肾小球肾炎，最有诊断意义和治疗价值的检查是肾穿刺活检（C对）。24小时尿蛋白检测（A错）有助于评估肾脏损害的程度，但无法直接确诊慢性肾小球肾炎的具体病理类型。B超（B错）虽然能检测肾脏的形态、大小和结构，但对明确诊断和指导后续的治疗的价值不如肾穿刺活检。肾动脉造影（D错）主要用于肾血管病变的检查，对慢性肾小球肾炎的诊断价值有限。","c216","N"],["2025-N83",40,"第七节 慢性肾小球肾炎","积极控制高血压和减少尿蛋白",2025,83,"A","","男性，45岁。3年多来乏力、间断性下肢水肿，未诊治。1个多月来加重，伴食欲减退。无高血压病家族史。查体：BP160/95mmHg，轻度贫血貌，双下肢轻度可凹性水肿。尿常规：蛋白（++），沉渣镜检RBC10～15个/HP；血Cr176μmol/L。该患者尿蛋白定量1.5g/d，理想的血压控制目标是",[["A","＜140/90mmHg"],["B","＜140/85mmHg"],["C","＜130/80mmHg"],["D","＜125/75mmHg"]],"D","患者中年男性，乏力、间断性下肢水肿3年（病程大于3个月，提示慢性病程），病情加重1月，伴食欲减退，查体：BP：160/95mmHg（正常参考值：90～139/60～89mmHg，提示2级高血压），轻度贫血貌，双下肢轻度可凹性水肿，辅助检查：尿常规：蛋白（++）（正常尿蛋白定性：阴性，提示蛋白尿），沉渣镜检RBC10～15个/HP（正常为阴性，提示显微镜下血尿），血Cr176μmol/L（正常参考值：成年男性57～97μmol/L，提示肾功能受损）。根据患者临床表现及辅助检查，该患者最可能的诊断为慢性肾小球肾炎。高血压和蛋白尿是加速肾小球硬化、促进肾功能恶化的重要因素，所以需要积极控制高血压和减少蛋白尿，由于该患者尿蛋白定量1.5g/d（＞1.0g/d），所以该患者血压控制为125/75mmHg（D对ABC错）。最新十版内科学已删除不同尿蛋白量人群的血压控制目标，修改为大多数成年病人目标收缩压应＜120mmHg，所以根据十版内科学，此题无正确答案。","c216","N"],["2025-N84",40,"第七节 慢性肾小球肾炎","慢性肾小球肾炎治疗",2025,84,"A","","男性，45岁。3年多来乏力、间断性下肢水肿，未诊治。1个多月来加重，伴食欲减退。无高血压病家族史。查体：BP160/95mmHg，轻度贫血貌，双下肢轻度可凹性水肿。尿常规：蛋白（++），沉渣镜检RBC10～15个/HP；血Cr176μmol/L。该患者治疗的最终目标是",[["A","防止或延缓病变进展"],["B","消除水肿"],["C","消除尿蛋白"],["D","消除血尿"]],"A","患者中年男性，乏力、间断性下肢水肿3年（病程大于3个月，提示慢性病程），病情加重1月，伴食欲减退，查体：BP：160/95mmHg（正常参考值：90～139/60～89mmHg，提示2级高血压），轻度贫血貌，双下肢轻度可凹性水肿，辅助检查：尿常规：蛋白（++）（正常尿蛋白定性：阴性，提示蛋白尿），沉渣镜检RBC10～15个/HP（正常为阴性，提示显微镜下血尿），血Cr176μmol/L（正常参考值：成年男性57～97μmol/L，提示肾功能受损）。根据患者临床表现及辅助检查，该患者最可能的诊断为慢性肾小球肾炎。慢性肾小球肾炎的主要目的是防止或延缓肾功能进行性恶化、改善或缓解临床症状及防治心脑血管并发症（A对），所以水肿、蛋白尿和血尿只能积极控制和减轻，并不能消除（BCD错）。","c216","N"],["2025-N85",52,"第二节 急性白血病","急性白血病诊断",2025,85,"A","","男性，19岁。6天来鼻出血及牙龈渗血、皮肤瘀斑。血常规：Hb88g/L，WBC12.5×10⁹/L，Plt25×10⁹/L；骨髓细胞增生明显活跃，原始细胞占80%，组化染色示MPO（-）～（+）不等，PAS呈弥漫性淡红色，NSE（+），可被NaF抑制。该患者最可能的诊断是",[["A","急性早幼粒细胞白血病"],["B","急性淋巴细胞白血病"],["C","急性粒-单核细胞白血病"],["D","急性单核细胞白血病"]],"D","青少年男性，鼻出血及牙龈渗血、皮肤瘀斑6天，辅助检查：血常规：Hb88g/L（正常参考值：成年男性130～175g/L，提示中度贫血），WBC12.5×10⁹/L（正常参考值：3.5～9.5×10⁹/L），PLT25×10⁹/L（正常参考值：125～350×10⁹/L），骨髓细胞增生明显活跃，原始细胞占80%，组化染色：MPO（-）～（+）不等，PAS弥漫性淡红色，NSE（+），可被NaF抑制（急性单核细胞白血病的典型细胞化学检查结果）。根据患者的症状、体征及辅助检查，该患者最可能的诊断为急性单核细胞白血病（D对）。急性早幼粒细胞白血病（A错）患者骨髓细胞质颗粒增多的早幼粒细胞占有核细胞 20%以上，细胞质内常见柴束样 Auer 小体，细胞化学染色POX强阳性，分子生物学分析可发现 𝘗𝘔𝘓-𝘙𝘈𝘙𝘈 融合基因。急性淋巴细胞白血病（B错）的细胞化学检查结果为MPO（-），NSE（-），PSA（+）成块或粗颗粒状。急性粒-单核细胞白血病（C错）患者常见到肝脾淋巴结肿大、牙龈肿胀和呈蓝灰色斑丘疹的皮下结节型的浸润灶，骨髓中原始细胞＞30%NEC（指不包括浆细胞、淋巴细胞、组织嗜碱细胞、巨细胞及所有红系有核细胞的骨髓有核细胞计数），各阶段粒细胞≥20%，各阶段单核细胞≥20%。","c217","N"],["2025-N86",52,"第二节 急性白血病","口腔和皮肤",2025,86,"A","","男性，19岁。6天来鼻出血及牙龈渗血、皮肤瘀斑。血常规：Hb88g/L，WBC12.5×10⁹/L，Plt25×10⁹/L；骨髓细胞增生明显活跃，原始细胞占80%，组化染色示MPO（-）～（+）不等，PAS呈弥漫性淡红色，NSE（+），可被NaF抑制。该患者临床最常出现的异常是",[["A","牙龈肿胀"],["B","弥散性血管内凝血"],["C","睾丸肿大"],["D","中枢神经系统受侵犯"]],"A","青少年男性，鼻出血及牙龈渗血、皮肤瘀斑6天，辅助检查：血常规：Hb88g/L（正常参考值：成年男性130～175g/L，提示中度贫血），WBC12.5×10⁹/L（正常参考值：3.5～9.5×10⁹/L），PLT25×10⁹/L（正常参考值：125～350×10⁹/L），骨髓细胞增生明显活跃，原始细胞占80%，组化染色：MPO（-）～（+）不等，PAS弥漫性淡红色，NSE（+），可被NaF抑制（急性单核细胞白血病的典型细胞化学检查结果）。根据患者的症状、体征及辅助检查，该患者最可能的诊断为急性单核细胞白血病，该病最常见的症状表现是牙龈肿胀（A对）。弥漫性血管内凝血（B错）多见于急性早幼粒细胞白血病，是由细胞内的Auer小体等细胞组分在细胞破裂后引发。睾丸肿胀（C错）多见于急性淋巴细胞白血病化疗缓解后。中枢神经系统损伤（D错）多见于急性淋巴细胞白血病治疗后缓解期。","c217","N"],["2025-N87",52,"第二节 急性白血病","AML诱导缓解治疗",2025,87,"A","","男性，19岁。6天来鼻出血及牙龈渗血、皮肤瘀斑。血常规：Hb88g/L，WBC12.5×10⁹/L，Plt25×10⁹/L；骨髓细胞增生明显活跃，原始细胞占80%，组化染色示MPO（-）～（+）不等，PAS呈弥漫性淡红色，NSE（+），可被NaF抑制。该患者目前的首选治疗是",[["A","DA方案化疗"],["B","口服全反式维A酸"],["C","DVLP方案化疗"],["D","骨髓移植"]],"A","青少年男性，鼻出血及牙龈渗血、皮肤瘀斑6天，辅助检查：血常规：Hb88g/L（正常参考值：成年男性130～175g/L，提示中度贫血），WBC12.5×10⁹/L（正常参考值：3.5～9.5×10⁹/L），PLT25×10⁹/L（正常参考值：125～350×10⁹/L），骨髓细胞增生明显活跃，原始细胞占80%，组化染色：MPO（-）～（+）不等，PAS弥漫性淡红色，NSE（+），可被NaF抑制（急性单核细胞白血病的典型细胞化学检查结果）。根据患者的症状、体征及辅助检查，该患者最可能的诊断为急性单核细胞白血病，该患者目前首选的治疗方案是DA方案（A对）。口服全反式维A酸（B错）用于治疗急性早幼粒细胞白血病。DVLP方案（C错）用于治疗急性淋巴细胞白血病。骨髓移植（D错）一般应用于复发难治的急性白血病患者，且多在缓解期进行。","c217","N"],["2025-N88",59,"第一节 甲状腺功能亢进症","甲状腺毒症和甲亢的诊断",2025,88,"A","","女性，35岁。多食、易饥、多汗伴腹泻1个月，体重下降3kg。查体：皮肤湿润，甲状腺Ⅱ度肿大，质软。心率120次/分，心律齐，双手震颤（+）。实验室检查：血清FT₃、FT₄显著升高，TSH降低，TgAb（-），TPOAb（-），尿糖可疑阳性，肝功能和血常规均正常。目前该患者最可能的诊断是",[["A","桥本甲状腺毒症"],["B","Graves病"],["C","亚急性甲状腺炎"],["D","多结节性毒性甲状腺肿"]],"B","青年女性，多食、易饥、多汗、腹泻，伴体重下降（高代谢表现，提示甲状腺毒症），查体：皮肤湿润，甲状腺二度肿大，质软（提示弥漫性毒性甲状腺肿），心率120次/分（正常参考值：60～100次/分），律齐，双手震颤（+），实验室检查：血清FT₃、FT₄显著增高，TSH降低（甲状腺功能亢进症的典型实验室检查结果），TgAb（-），TPOAb（-），尿糖可疑阳性，肝功能和血常规均正常。根据患者的症状、体征及辅助检查，该患者最可能的诊断为Graves病（弥漫性毒性甲状腺肿）（B对）。桥本甲状腺炎（A错）也称为慢性淋巴细胞性甲状腺炎，属于自身免疫性甲状腺炎，早期没有明显临床症状，病程晚期出现甲状腺功能减退的表现，查体可见甲状腺坚硬，肿大，血清TPOAb和TgAb显著增高。亚急性甲状腺炎（C错）是一种与病毒感染有关的自限性甲状腺炎，起病前有咽炎、腮腺炎、麻疹等病毒感染史，甲状腺区明显疼痛，伴有全身不适、发热等症状，查体可见甲状腺轻至中度肿大，质地较硬，显著触痛，整个病程可分为甲状腺毒症期、甲减期和恢复期。多发性结节状毒性甲状腺肿（D错）属于甲状腺功能亢进症的一种，也可有高代谢的相关症状，查体可见甲状腺的肿大，质地较硬，可以触及多个结节，结节的大小不一。","c218","N"],["2025-N89",59,"第一节 甲状腺功能亢进症","TRAb",2025,89,"A","","女性，35岁。多食、易饥、多汗伴腹泻1个月，体重下降3kg。查体：皮肤湿润，甲状腺Ⅱ度肿大，质软。心率120次/分，心律齐，双手震颤（+）。实验室检查：血清FT₃、FT₄显著升高，TSH降低，TgAb（-），TPOAb（-），尿糖可疑阳性，肝功能和血常规均正常。为明确诊断，最有价值的检查是",[["A","甲状腺B超"],["B","TRAb"],["C","OGTT"],["D","HbA1c"]],"B","青年女性，多食、易饥、多汗、腹泻，伴体重下降（高代谢表现，提示甲状腺毒症），查体：皮肤湿润，甲状腺二度肿大，质软（提示弥漫性毒性甲状腺肿），心率120次/分（正常参考值：60～100次/分），律齐，双手震颤（+），实验室检查：血清FT₃、FT₄显著增高，TSH降低（甲状腺功能亢进症的典型实验室检查结果），TgAb（-），TPOAb（-），尿糖可疑阳性，肝功能和血常规均正常。根据患者的症状、体征及辅助检查，该患者最可能的诊断为Graves病（弥漫性毒性甲状腺肿）。为明确诊断，最有价值的检查是TRAb（B对），其为诊断Graves病的第一线指标，未治疗的病人阳性率达到98%。甲状腺B超（A错）可用于评估甲状腺的大小和形态，协助甲亢的诊断，但不能用于确诊。OGTT（C错），即口服葡萄糖耐量试验，虽然患者尿糖可疑阳性，但考虑是甲状腺激素的升血糖作用，而且该患者没有糖尿病典型的“三多一少”症状，所以OGTT的价值不大。HbA1c（D错），即糖化血红蛋白，主要是用于监测糖尿病患者的血糖控制情况，该患者目前不考虑诊断为糖尿病，所以该检查意义不大。","c218","N"],["2025-N90",59,"第一节 甲状腺功能亢进症","抗甲状腺药物",2025,90,"A","","女性，35岁。多食、易饥、多汗伴腹泻1个月，体重下降3kg。查体：皮肤湿润，甲状腺Ⅱ度肿大，质软。心率120次/分，心律齐，双手震颤（+）。实验室检查：血清FT₃、FT₄显著升高，TSH降低，TgAb（-），TPOAb（-），尿糖可疑阳性，肝功能和血常规均正常。对该患者的治疗选择，不适当的是",[["A","对症治疗，如口服普萘洛尔"],["B","如无妊娠计划、可选¹³¹I治疗"],["C","如有妊娠计划、首选甲巯咪唑治疗"],["D","ATD治疗无效可外科手术治疗"]],"C","青年女性，多食、易饥、多汗、腹泻，伴体重下降（高代谢表现，提示甲状腺毒症），查体：皮肤湿润，甲状腺二度肿大，质软（提示弥漫性毒性甲状腺肿），心率120次/分（正常参考值：60～100次/分），律齐，双手震颤（+），实验室检查：血清FT₃、FT₄显著增高，TSH降低（甲状腺功能亢进症的典型实验室检查结果），TgAb（-），TPOAb（-），尿糖可疑阳性，肝功能和血常规均正常。根据患者的症状、体征及辅助检查，该患者最可能的诊断为Graves病（弥漫性毒性甲状腺肿）。目前Graves病治疗可采用的方式有抗甲状腺药物（ATD）、放射碘和手术，首先可以对症治疗，如口服普萘洛尔（A对），不仅可以控制心率，还可以阻断外周组织T₄向T₃的转化，若无妊娠要求，可用¹³¹I治疗（B对），若打算妊娠，优先选择丙硫氧嘧啶（C错，为本题正确答案），因为丙硫氧嘧啶的致畸作用小于甲巯咪唑，若ATD无效手术治疗（D对）。","c218","N"],["2025-N91",68,"第一节 类风湿关节炎","类风湿关节炎诊断",2025,91,"A","","男性，57岁。反复多关节肿痛伴晨僵1年余，主要表现为双手指关节和双腕关节肿痛。查体见双手近端指间关节梭形肿胀，双腕关节肿胀。最可能的诊断是",[["A","风湿性关节炎"],["B","系统性红斑狼疮"],["C","类风湿关节炎"],["D","银屑病关节炎"]],"C","患者中年男性，多发双手关节肿痛伴晨僵1年余，表现为双手指间关节、双腕关节肿痛（对称性多关节肿痛，类风湿关节炎的典型表现），查体：双手近段指间关节梭形肿胀，双腕关节肿胀（类风湿关节炎的典型体征）。根据患者的症状及体征，该患者最可能的诊断是类风湿性关节炎（C对）。风湿性关节炎（A错）是链球菌感染后所致风湿热在关节的表现，通常在链球菌感染后1个月内发作，典型表现是游走性多关节炎，常对称累及膝、踝、肩、腕、肘、髋等大关节，也可以呈现局部红、肿，热、痛等，症状2～6周内消失，关节功能完全恢，不遗留关节强直和畸形。系统性红斑狼疮（B错）以20～40岁的育龄期女性多见，临床症状多样，特征性表现为鼻梁和双颧颊部呈蝶形分布的红斑，可出现指、腕、膝关节疼痛，但关节红肿少见，肾脏受累可出现血尿、蛋白尿和水肿等。银屑病关节炎（D错）多于银屑病若干年后发生，部分病人表现为对称性多关节炎，以累及远端指关节处为主，表现为该关节的附着端炎和手指炎，同时可有骶髂关节炎和脊柱炎。","c219","N"],["2025-N92",68,"第一节 类风湿关节炎","类风湿关节炎X线检查",2025,92,"A","","男性，57岁。反复多关节肿痛伴晨僵1年余，主要表现为双手指关节和双腕关节肿痛。查体见双手近端指间关节梭形肿胀，双腕关节肿胀。最有助于确定诊断的辅助检查是",[["A","血清抗核抗体"],["B","血清抗链“O”"],["C","血清HLA-B27"],["D","双手、腕关节X线片"]],"D","患者中年男性，多发双手关节肿痛伴晨僵1年余，表现为双手指间关节、双腕关节肿痛（对称性多关节肿痛，类风湿关节炎的典型表现），查体：双手近段指间关节梭形肿胀，双腕关节肿胀（类风湿关节炎的典型体征）。根据患者的症状及体征，该患者最可能的诊断是类风湿性关节炎，对诊断最有价值的检查是双手、腕关节X线（D对），可见关节周围软组织肿胀影、关节附近骨质疏松等表现，是类风湿性关节炎的重要诊断标准。血清抗核抗体（A错）包括抗 DNA、抗组蛋白、抗非组蛋白、抗核仁抗体及抗其他细胞成分抗体五大类，主要用于诊断系统性红斑狼疮、干燥综合征，类风湿性关节炎阳性率不高，诊断价值不大。血清抗链“O”（B错）主要用于诊断链球菌感染所致的风湿热，与类风湿性关节炎无关。血清HLA-B27（C错）主要用于协助诊断强直性脊柱炎，与类风湿性关节炎无关。","c219","N"],["2025-N128",4,"第二节细菌性肺炎","肺炎链球菌肺炎发病机制",2025,128,"B","","病变以肺叶或肺段分布为主，一般不形成空洞的肺炎是",[["A","肺炎链球菌肺炎"],["B","肺炎支原体肺炎"],["C","金黄色葡萄球菌肺炎"],["D","病毒性肺炎"]],"A","肺炎链球菌肺炎（A对）的典型表现为大叶性肺炎，侵犯肺段或肺叶，致病菌为肺炎链球菌，因为肺炎链球菌不产生毒素，所以不引起组织坏死或形成空洞。支原体肺炎（B错）由肺炎支原体感染引起，肺部病变为支气管肺炎、间质性肺炎和细支气管炎，以持久的阵发性剧咳为较典型的表现。金黄色葡萄球菌肺炎（C错）由金黄色葡萄球菌感染引起，致病力强，可产生毒素和酶，可早期形成空洞。病毒性肺炎（D错）常由甲、乙型流感病毒、腺病毒等感染引起，引起肺间质及实质性炎症，以发热、头痛、全身酸痛等全身症状为主。","","N"],["2025-N129",4,"第四节 肺炎支原体肺炎、衣原体肺炎与肺军团病","肺炎支原体肺炎临床表现",2025,129,"B","","以持久的阵发性剧咳为特点的肺炎是",[["A","肺炎链球菌肺炎"],["B","肺炎支原体肺炎"],["C","金黄色葡萄球菌肺炎"],["D","病毒性肺炎"]],"B","支原体肺炎（B对）由肺炎支原体感染引起，肺部病变为支气管肺炎、间质性肺炎和细支气管炎，以持久的阵发性剧咳为较典型的表现。炎链球菌肺炎（A错）的典型表现为大叶性肺炎，侵犯肺段或肺叶，致病菌为肺炎链球菌，因为肺炎链球菌不产生毒素，所以不引起组织坏死或形成空洞。金黄色葡萄球菌肺炎（C错）由金黄色葡萄球菌感染引起，致病力强，可产生毒素和酶，可早期形成空洞。病毒性肺炎（D错）常由甲、乙型流感病毒、腺病毒等感染引起，引起肺间质及实质性炎症，以发热、头痛、全身酸痛等全身症状为主。","","N"],["2025-N130",30,"第一节 溃疡性结肠炎","消化系统表现",2025,130,"B","","溃疡性结肠炎的临床特点是",[["A","腹痛-黏液脓血便-缓解"],["B","腹痛-黏液便-缓解"],["C","腹痛-果酱样便-缓解"],["D","腹痛-黏液脓血便-加重"]],"A","溃疡性结肠炎是一种慢性非特异性肠道炎症性疾病，病变主要限于大肠黏膜与黏膜下层，以反复发作的腹泻、黏液脓血便及腹痛为主要症状，伴里急后重，便后腹痛缓解（A对C错）。急性阿米巴痢疾表现为腹痛、腹胀，腹泻每天数次，大便呈暗红色果酱样，有腥臭（B错）。肠易激综合征是一种以腹痛伴排便习惯改变为特征，而无器质性症变的功能性肠病，临床表现为不同程度的腹痛，排便或排气后缓解，解糊状或稀水样便，可带有黏液但无脓血（D错）。","","N"],["2025-N131",32,"第二节 肠易激综合征","肠易激综合征临床表现",2025,131,"B","","肠易激综合征的临床特点是",[["A","腹痛-黏液脓血便-缓解"],["B","腹痛-黏液便-缓解"],["C","腹痛-果酱样便-缓解"],["D","腹痛-黏液脓血便-加重"]],"B","肠易激综合征是一种以腹痛伴排便习惯改变为特征，而无器质性症变的功能性肠病，临床表现为不同程度的腹痛，排便或排气后缓解，解糊状或稀水样便，可带有黏液但无脓血（B对）。溃疡性结肠炎是一种慢性非特异性肠道炎症性疾病，病变主要限于大肠黏膜与黏膜下层，以反复发作的腹泻、黏液脓血便及腹痛为主要症状，伴里急后重，便后腹痛缓解（AC错）。急性阿米巴痢疾表现为腹痛、腹胀，腹泻每天数次，大便呈暗红色果酱样，有腥臭（D错）。","","N"],["2025-N154",11,"第一节 胸腔积液","区别漏出液和渗出液",2025,154,"X","","根据Light标准，确定渗出性胸腔积液的标准有",[["A","胸腔积液有核细胞数＜500×10⁶/L"],["B","胸腔积液蛋白/血清蛋白＞0.5"],["C","胸腔积液LDH/血清LDH＞0.6"],["D","胸腔积液LDH大于血清LDH正常值高限的2/3"]],"BCD","Light标准用于区别胸腔积液为漏出液或渗出液，需要测定胸腔积液中的蛋白质含量和乳酸脱氢酶（LDH），Light标准包括：渗出液通常含有较高的蛋白质含量，胸腔积液蛋白与血清蛋白的比例大于0.5（B对）；渗出液中LDH有较高活性，胸腔积液LDH与血清LDH的比例大于0.6（C对），胸腔积液LDH大于血清LDH正常值高限的2/3（D对）。胸腔积液有核细胞数不属于Light标准，但是当有核细胞数＞500×10⁶/L时多提示胸腔积液为渗出液（A错）。","","N"],["2025-N155",16,"第四节 房室交界性心律失常","房室结折返性心动过速心电图特征",2025,155,"X","","符合阵发性室上性心动过速心电图特点的有",[["A","心室率可达160～250次/分"],["B","R-R间期相差不大于0.12秒"],["C","QRS波群形态可不正常"],["D","常难以见到逆行P波"]],"ACD","阵发性室上性心动过速包括房室结折返性心动过速和房室折返性心动过速，通常心率范围在160～250次/分（A对），这是由于折返机制引起的快速性心律失常。在心电图中，R-R间期差距体现的是心律的规则性，发生阵发性室上性心动过速时，当房室传导比例不固定时，R-R间期可以不相等，R-R间期相差不大于0.12秒描述不准确（B错）。QRS波群形态与时限均正常，但发生室内差异性传导或束支传导阻滞时，QRS波群形态可能会出现异常（C对），如增宽或变形。阵发性室上性心动过速时，逆行P波可能隐藏在QRS波群内或位于其终末部分，常难以发现（D对），这是由于心房和心室的激动几乎同时发生，导致心房的电活动在心电图上不易被观察到。","","N"],["2025-N156",75,"第二节 农药中毒","胆碱受体拮抗药",2025,156,"X","","应用阿托品治疗有机磷中毒时，可以改善的临床表现有",[["A","腹痛、腹泻"],["B","大汗、流涎"],["C","大小便失禁"],["D","双肺湿啰音"]],"ABCD","有机磷进入体内后可抑制乙酰胆碱酯酶，引起体内生理效应部位乙酰胆碱大量蓄积，出现毒蕈碱样、烟碱样和中枢神经系统等中毒症状和体征，而阿托品作为M胆碱受体阻断药，通过阻断胃肠道平滑肌的M受体，能有效松弛胃肠道平滑肌，从而显著缓解腹痛、腹泻（A对）；通过阻断汗腺和唾液腺上的M受体，进而减少腺体分泌，有效改善大汗和流涎症状（B对）；通过阻断膀胱和肛门括约肌上的M受体，增强括约肌张力，可以改善大小便失禁（C对）的症状；同时还可以阻断支气管平滑肌和黏膜腺体上的M受体，有效缓解支气管收缩并减少腺体分泌，治疗由有机磷中毒引发的双肺湿啰音（D对）。","","N"],["2025-N157",45,"第一节 慢性肾衰竭","内分泌功能紊乱",2025,157,"X","","慢性肾衰竭患者内分泌功能紊乱的主要表现有",[["A","1，25-（OH）₂D₃不足"],["B","EPO缺乏"],["C","PTH不足"],["D","糖耐量异常"]],"ABD","慢性肾衰竭是各种慢性肾脏病持续进展至后期的共同结局，以代谢产物潴留，水、电解质及酸碱平衡失调和全身各系统症状为表现的一种临床综合征，其中内分泌紊乱的主要临床表现包括：肾脏本身内分泌功能紊乱，由于肾脏1α-羟化酶活性降低，导致1，25-（OH）₂D₃合成不足，进而引发钙磷代谢紊乱，同时，慢性肾衰竭可导致EPO（促红细胞生成素）缺乏（B对），使红细胞生成减少，从而导致贫血；外周内分泌腺功能紊乱，慢性肾衰竭时，由于血磷上升和血钙下降，会刺激甲状旁腺分泌更多的PTH（甲状旁腺激素）（C错）；糖耐量异常（D对）和胰岛素抵抗，与骨骼肌及外周器官摄取糖能力下降、酸中毒、肾脏降解小分子物质能力下降有关；下丘脑-垂体内分泌功能紊乱，催乳素、促黑色素激素、促肾上腺皮质激素等水平增高。","","N"],["2025-N158",55,"第一节 出血性疾病概述","抗凝异常",2025,158,"X","","提示抗凝异常的实验室检查项目有",[["A","凝血酶-抗凝血酶复合物测定"],["B","D-二聚体测定"],["C","FⅧ：C抗体测定"],["D","凝血酶原时间测定"]],"AC","提示抗凝功能异常的确诊实验室检查项目包括：凝血酶-抗凝血酶复合检查（A对），凝血酶和抗凝血酶在正常凝血过程中相互作用，凝血酶会被抗凝血酶抑制，以维持凝血与抗凝的平衡，复合物水平异常可能提示抗凝功能异常；针对FⅧ：C的抗体可能干扰凝血因子Ⅷ的正常功能，导致抗凝异常，所以FⅧ：C抗体测定（C对）可以用于确诊抗凝功能异常。D-二聚体检测（B错）是纤溶功能异常的确诊试验，并不直接反映抗凝功能的异常。凝血酶原时间（D错）是外源凝血系统较为灵敏和最为常用的筛选试验，其异常也可提示抗凝物质增多，D选项存在争议。","","N"],["2025-N159",61,"第一节 糖尿病","促胰岛素分泌剂",2025,159,"X","","可刺激胰腺分泌胰岛素的药物有",[["A","磺脲类降糖药"],["B","双胍类降糖药"],["C","α-葡萄糖苷酶抑制剂"],["D","GLP-1受体激动剂"]],"AD","刺激胰腺分泌胰岛素的药物主要有磺脲类降糖药（A对）和GLP-1受体激动剂（D对），磺脲类降糖药通过刺激胰岛β细胞释放胰岛素而发挥降血糖作用，而GLP-1受体激动剂则是通过激动GLP-1受体，以葡萄糖浓度依赖的方式增强胰岛素分泌，同时抑制胰高血糖素分泌，并能延缓胃排空，通过中枢性的食欲抑制来减少进食量，进而达到降血糖的效果。双胍类降糖药（B错）的作用机制是：①通过激活腺苷酸活化蛋白激酶（AMPK）信号系统，减少肝脏葡萄糖输出，抑制脂肪酸和胆固醇的生成；②增加外周肌肉组织对葡萄糖的摄取；③增强胰岛素信号转导，明显降低肥胖或胰岛素抵抗的T2DM患者的血糖。目前，也有观点认为二甲双胍可提高GLP-1水平，间接刺激胰岛素的分泌，因此，该选项存在争议。α-葡萄糖苷酶抑制剂（C错）竞争性抑制小肠黏膜刷状缘α- 葡萄糖苷酶，抑制寡糖分解为单糖，减少小肠中淀粉、糊精和双糖的吸收，降低餐后血糖和糖化血红蛋白，不增加体重。","","N"],["2026-N41",22,"第二节 心包积液及心脏压塞","心脏压塞",2026,41,"A","","典型心脏压塞的Beck三联征是",[["A","低血压、呼吸困难、心力衰竭"],["B","低血压、心音低弱、颈静脉怒张"],["C","心音低弱、心前区疼痛、心力衰竭"],["D","心前区疼痛、低血压、颈静脉怒张"]],"B","心脏压塞是心包积液迅速或积液量达到一定程度时，心包压增加，可造成心排血量和回心血量明显下降而产生的临床症状，典型Beck三联征表现为低血压、心音弱、颈静脉怒张（B对）。呼吸困难（A错）是心包积液最突出的症状，但不属于Beck三联征。心前区疼痛（CD错）常见于急性心包炎、冠心病等。","","N"],["2026-N42",16,"第四节 房室交界性心律失常","房室结折返性心动过速心电图特征",2026,42,"A","","下列心电图最可能的诊断是",[["A","陈旧性下壁心肌梗死"],["B","预激综合征"],["C","左心室增大"],["D","心肌缺血"]],"B","图中的心电图可见：QRS波群起始部分可见δ波（V₃、V₄、V₅导联），多个导联T波倒置，在Ⅰ导联上可大致看出PR间期缩短（大致为一个大方格的1/2-2/3），所以综合上述心电图特点，考虑预激综合征的可能性最大（B对）。陈旧性下壁心肌梗死在心电图上通常表现为Ⅱ、Ⅲ、aVF导联出现病理性Q波（A错）。左心室增大的心电图可出现QRS波振幅增高电轴往左上象限偏移（+0°～-30°），严重左心室肥厚可超过-30°，V₁、V₂导联可出现QS波（C错）。心肌缺血在心电图上可表现为ST段压低（水平型或下斜型压低≥0.05mV）、T波低平、双向或倒置等改变（D错）。","","N"],["2026-N43",1,"第二节 慢性阻塞性肺疾病","慢性阻塞性肺疾病发病机制",2026,43,"A","","下列不属于慢性阻塞性肺疾病发病机制的是",[["A","气道炎症"],["B","蛋白酶-抗蛋白酶失衡"],["C","氧化应激增加"],["D","变态反应"]],"D","变态反应（D错，为本题正确答案）主要由IgE介导的过敏反应，以嗜酸性粒细胞浸润为特征，是支气管哮喘的核心发病机制。慢性阻塞性肺疾病的主要发病机制涉及慢性炎症过程，其发病机制包括：气道炎症（A对）是COPD的核心机制，长期炎症导致气道壁增厚和气流受限；蛋白酶-抗蛋白酶失衡（B对）指蛋白酶（如中性粒细胞弹性蛋白酶）过度活跃而抗蛋白酶（如α1-抗胰蛋白酶）不足，造成肺实质破坏；氧化应激增加（C对）指氧化物质积累，加剧炎症和组织损伤，许多研究表明慢阻肺病病人的氧化应激增加。","","N"],["2026-N44",7,"第一节 肺癌","肺癌临床分期",2026,44,"A","","男性，60岁，确诊右肺腺癌1周，肺部原发肿瘤最大直径为2cm，伴纵膈、右肺门和右锁骨上淋巴结转移，未见远处转移。该患者TNM分期是",[["A","T₁N₁M₀"],["B","T₁N₂M₀"],["C","T₁N₃M₀"],["D","T₂N₃M₀"]],"C","老年男性患者，确诊右肺腺癌1周，肺部原发肿瘤最大直径为2cm（T₁），伴纵膈、右肺门和右锁骨上淋巴结转移（N₃），未见远处转移（M₀）。根据患者的病史，临床表现和影像学检查，该患者TNM分期是T₁N₃M₀（C对）。T₁：肿瘤最大径≤3cm，周围包绕肺组织及脏胸膜，支气管镜见肿瘤侵及叶支气管，未侵及主支气管。T₂： 肿瘤最大径＞3～5cm；侵犯主支气管（不常见的表浅扩散型肿瘤，不论体积大小，侵犯限于支气管壁时，虽可能侵犯主支气管，仍为 T₁），但未侵及隆突；侵及脏胸膜；有阻塞性肺炎或者部分或全肺不张。符合以上任何一个条件即归为T₂（D错）。N₁（A错）：同侧支气管周围及（或）同侧肺门淋巴结以及肺内淋巴结转移，包括原发肿瘤直接侵及的肺内淋巴结。N₂（B错）：同侧纵隔内及（或）隆突下淋巴结转移。N₃：对侧纵隔、对侧肺门、同侧或对侧前斜角肌及锁骨上淋巴结转移。M₀：无远处转移。","","N"],["2026-N45",2,"第一节 支气管哮喘","重度至危重度(1)",2026,45,"A","","男性，25岁，接触宠物后突发喘息半小时，急诊入院。查体：P120次/分，意识模糊，颜面水肿，口唇轻度发绀，双肺呼吸音明显降低。动脉血气分析示：pH 7.10，PaCO₂ 95mmHg，PaO₂ 60mmHg。下列处理措施错误的是",[["A","雾化吸入支气管扩张剂"],["B","静脉注射糖皮质激素"],["C","机械通气"],["D","应用IgE单克隆抗体"]],"D","年轻男性患者，接触宠物后突发喘息半小时（支气管哮喘典型诱因），急诊入院。查体：P120次/分（正常范围为60～100次/分，提示心动过快），意识模糊，颜面水肿，口唇轻度发绀，双肺呼吸音明显降低（危重度支气管哮喘典型表现）。动脉血气分析示：pH7.10（提示pH降低），PaCO₂95mmHg，PaO₂60mmHg（提示Ⅱ型呼吸衰竭）。根据患者的接触史、临床表现和动脉血气分析，可初步诊断为支气管哮喘急性危重度发作。急性发作的治疗目标是尽快缓解气道痉挛，纠正低氧血症，恢复肺功能，预防进一步恶化和防治并发症。持续雾化吸入支气管扩张剂（A对）是哮喘急性发作的一线急救措施，可快速舒张气道、缓解痉挛，改善通气功能。危重度哮喘发作时气道炎症反应剧烈，需尽早静脉注射糖皮质激素（B对），抑制炎症介质释放、减轻气道水肿。该患者pH＜7.20且PaCO₂≥45mmHg、意识模糊，需要进行有创机械通气（C对）纠正呼吸衰竭，挽救生命。IgE单克隆抗体（D错，为本题正确答案）属于生物靶向药物，目前主要用于常规治疗不能控制的重度哮喘。","","N"],["2026-N46",16,"第三节 房性心律失常","心房颤动诊断",2026,46,"A","","男性，68岁，高血压20余年，间断服药，偶有短阵发作性心悸，休息可缓解。3h前突感心悸、气短、胸闷，伴出汗，来院就诊，查体：P106次/分，BP110/64mmHg，平卧位，双肺（-），心率140次/分，心律不齐，心音强弱不等，无杂音，双下肢无水肿。该患者最可能的诊断是",[["A","急性心肌梗死伴心脏衰竭"],["B","阵发性室上性心动过速"],["C","快速心室率心房颤动"],["D","阵发性室性心动过速"]],"C","老年男性患者，高血压20余年（房颤高危因素），偶有短阵发作性心悸。3h前心悸、气短、胸闷。查体：P106次/分（正常范围为60～100次/分，提示心动过速），BP110/64mmHg（正常范围为90～139/60～89mmHg），心率140次/分（脉率＜心率，房颤典型表现），心律不齐，心音强弱不等。根据患者的病史、临床表现，最可能的诊断是快速心室率心房颤动（C对）。急性心肌梗死（A错）表现为突发持续性胸骨后或心前区压榨性憋闷感或疼痛，甚至呼吸困难、休克等临床表现，多合并高血压、动脉粥样硬化、冠状动脉粥样硬化性心脏病病史。阵发性室上性心动过速（B错）多无器质性心脏病，常见于年轻人，症状包括突发的心悸、胸闷、焦虑不安、头晕等，心动过速发作时听诊心尖区第一心音强度恒定，心律绝对规则。阵发性室性心动过速（D错）最常见于冠心病患者，可无明显症状，持续性室速可表现为低血压、头晕、气促、心绞痛和晕厥等，听诊心律可轻度不规则，第一、二心音分裂。","","N"],["2026-N47",21,"第一节 主动脉瓣狭窄","主动脉瓣狭窄诊断",2026,47,"A","","男性，64岁，活动时胸骨后闷痛、心悸、气短1年余。2个月来加重。查体：P90次/分，BP90/60mmHg，双肺（-），心律齐，心尖可闻及S₄，A₂减弱，胸骨右缘第2肋间可闻及4/6级收缩期喷射性杂音，向颈部传导。最有可能的诊断是",[["A","主动脉瓣狭窄"],["B","主动脉瓣反流"],["C","二尖瓣反流"],["D","室间隔缺损"]],"A","患者老年男性，活动时出现胸骨后闷痛、心悸、气短等症状（提示心肌缺血和心力衰竭可能），加重2个月。查体：心率90次/分（正常60～100次/分），血压90/60mmHg（正常值90～139/60～89mmHg），心尖部闻及S₄（第四心音，提示心房收缩增强，常见于左心室顺应性下降），A₂减弱（主动脉瓣第二心音减弱，提示主动脉瓣狭窄）；胸骨右缘第2肋间可闻及4/6级收缩期喷射性杂音并向颈部传导（主动脉瓣狭窄的典型体征）。综合患者症状和查体，考虑可能诊断为为主动脉瓣狭窄（A对）。主动脉瓣反流（B错）分为慢性和急性，慢性者一般长时间无明显症状，心脏杂音通常表现为舒张期杂音而非收缩期，同时伴周围血管征。二尖瓣反流（C错）分为慢性和急性，轻度慢性者可无明显症状，重者出现心力衰竭的相关症状，典型的二尖瓣反流杂音为心尖部全收缩期吹风样杂音，并向腋下传导。室间隔缺损（D错）轻者无明显症状，重者主要表现为劳力性呼吸困难，听诊除在胸骨左缘可闻及全收缩期杂音伴震颤外，并可在心尖区闻及舒张中期反流性杂音。","","N"],["2026-N48",22,"第一节 急性心包炎","急性心包炎诊断",2026,48,"A","","男性，52岁。两天前感心前区锐痛，向颈部及左肩部放射，呼吸及运动可明显加剧。1天来疼痛稍有缓解，感胸闷气短，明显乏力。既往曾有肺结核病史，三个月前有胸部外伤史，2周前有上感史。查体：T37.8℃，BP128/75mmHg，P82次/分，双肺（-），心界不大，心音正常，心前区及胸骨左缘3-4肋间收缩期可闻及粗糙高频抓刮样音。血WBC9.8×10⁹/L。该患者可能诊断是",[["A","非特异性心包炎"],["B","感染性心内膜炎"],["C","心脏损伤后综合征"],["D","不稳定型心绞痛"]],"A","患者中年男性。两天前感心前区锐痛，向颈部及左肩部放射，呼吸及运动可明显加剧（急性心包炎的特征性疼痛表现）。1天来疼痛稍有缓解，感胸闷气短（提示病程进展）。既往曾有肺结核病史，三个月前有胸部外伤史，2周前有上感史（非特异性心包炎最常见的诱因）。查体：T37.8℃（正常值36～37℃），BP128/75mmHg（正常值90～139/60～89mmHg），P82次/分（正常值60～100次/分），心前区及胸骨左缘3-4肋间收缩期可闻及粗糙高频抓刮样音（提示心包摩擦音）。血WBC9.8×10⁹/L（正常值3.5～9.5×10⁹/L）。综合患者病史、症状和查体，考虑可能诊断是急性非特异性心包炎（A对）。感染性心内膜炎（B错）患者多有心脏瓣膜疾病史，临床表现多有发热、心脏瓣膜杂音、栓塞或皮肤黏膜瘀点、Osler结节等周围体征，无特征性心包摩擦音。心脏损伤后综合征（C错）患者有手术、心肌梗死等心脏损伤史，少有心包摩擦音，虽可能由胸部外伤引发，但多在损伤后数周内发病，本例外伤史已3个月，诊断证据不足。不稳定型心绞痛（D错）疼痛多为压榨性，与呼吸无关，休息或含服硝酸甘油可缓解，无发热及心包摩擦音，与本例患者疼痛特点及体征不符。","","N"],["2026-N49",26,"第一节 胃食管反流病","胃食管反流病治疗",2026,49,"A","","下列关于胃食管反流病的处理，不恰当的是",[["A","抑酸药为基础治疗药物"],["B","临时缓解症状可用抗酸药"],["C","睡前4小时禁食"],["D","嘱患者禁酒戒烟"]],"C","胃食管反流病（GERD）的核心处理策略包括生活方式干预和药物治疗，生活方式干预包括：进食后不宜立即卧床。为减少卧位及夜间反流，睡前2小时不宜进食（C错，为本题正确答案），睡时可抬高床头；戒烟及禁酒（D对）等。药物治疗包括：抑酸药（如质子泵抑制剂）为基础治疗药物（A对），通过抑制胃酸分泌直接缓解反流症状并促进食管黏膜愈合；促胃肠动力药适用于轻症病人，或作为抑酸药的辅助用药；抗酸药仅用于症状轻、间歇发作的病人临时缓解症状（B对）。","","N"],["2026-N50",30,"第二节 克罗恩病","克罗恩病内镜检查",2026,50,"A","","男性，28岁，一年来反复右下腹痛，腹泻便秘交替，偶有粘液脓血便，腹痛发作时常有低热。查体: T37.5℃，左侧颊部黏膜处有溃疡，右下腹触及一边界不清的肿物，可移动，压痛。为明确诊断，最重要的检查是",[["A","腹部B超"],["B","腹部CT"],["C","钡剂灌肠"],["D","结肠镜"]],"D","患者青年男性，一年来反复右下腹痛，腹泻便秘交替，偶有粘液脓血便（提示肠道炎症或溃疡），腹痛发作时常有低热。查体：T37.5℃（正常值36～37℃），左侧颊部黏膜处有溃疡，右下腹触及一边界不清的肿物，可移动，压痛（高度提示克罗恩病）。为明确诊断，最重要的检查是结肠镜（D对）。结肠镜可直接观察全结肠黏膜病变、取活检明确病理诊断，是炎症性肠病的确诊金标准。腹部B超（A错）对肠道病变分辨率低，仅能评估包块性质。腹部CT（B错）可显示肠壁增厚及并发症（如脓肿），但无法替代内镜确诊。钡剂灌肠（C错）可能加重肠穿孔风险（尤其疑诊活动性炎症时），且不能获取组织标本。","","N"],["2026-N51",36,"第一节 原发性肝癌","甲胎蛋白",2026,51,"A","","女性，60岁，三个月来肝区疼痛，纳差、消瘦，加重一周，乙肝表面抗原阳性10年。查体：肝肋下4cm，质硬，边缘不整齐。对诊断最有意义的血清标志物是",[["A","CEA"],["B","AFP"],["C","CA125"],["D","GPC3"]],"B","患者老年女性（肝癌的高发人群），三个月来肝区疼痛，纳差，消瘦（肝癌的典型症状），加重一周，乙肝表面抗原阳性10年（提示慢性乙型肝炎感染）。查体：肝肋下4cm，质硬，边缘不整齐（肝癌的体征特点）。综合患者的病史及临床表现，考虑诊断为肝癌，对诊断最有意义的血清标志物是AFP（B对）。甲胎蛋白（AFP）作为原发性肝癌的主要筛查和诊断标志物，其血清水平升高与该病直接相关。癌胚抗原（CEA）（A错）主要用于结直肠癌的诊断。CA125（C错）主要用于卵巢癌的监测。Glypican-3（GPC3）（D错）虽在肝癌中表达，但作为血清标志物不如AFP常用。","","N"],["2026-N52",40,"第二节 急性肾小球肾炎","急性肾小球肾炎临床表现",2026,52,"A","","男性，21岁，自述感冒2周后尿液呈浑浊红棕色，伴眼睑及颜面水肿2天就诊。查体：BP150/90mmHg，双眼睑水肿，心肺腹检查无异常，双下肢中度可凹陷性水肿。该患者的尿最可能是",[["A","肌红蛋白尿"],["B","血红蛋白尿"],["C","肉眼血尿"],["D","卟啉尿"]],"C","患者青年男性（急性肾小球肾炎的常见发病人群），感冒2周后（上呼吸道感染前驱史）尿液呈浑浊红棕色（提示尿液中存在红细胞及蛋白质等成分），伴眼睑及颜面水肿2天（急性肾小球肾炎的首发表现）。查体：BP150/90mmHg（正常值90～139/60～89mmHg，高血压），双眼睑水肿，双下肢中度可凹陷性水肿。综合患者病史、症状和查体，高度怀疑急性肾小球肾炎，该患者的尿最可能是肉眼血尿（C对）。急性肾小球肾炎的典型尿液改变为尿液含大量红细胞，可呈洗肉水样或红棕色，若合并蛋白尿则尿液浑浊。肌红蛋白尿（A错）通常由肌肉损伤如横纹肌溶解引起，尿液呈粉红色或暗红色。血红蛋白尿（B错）源于血管内溶血，见于蚕豆病、阵发性睡眠性血红蛋白尿症等，该患者无黄疸或贫血表现。卟啉尿（D错）与卟啉病相关，罕见且伴神经或腹痛症状，与患者表现不符。","","N"],["2026-N53",54,"第一节 多发性骨髓瘤","多发性骨髓瘤诊断标准",2026,53,"A","","女性，76岁，腰痛6周，加重尿少1月，既往体健，尿蛋白（++），尿沉渣镜检（-），血常规79g/L，白细胞4.7×10⁹/L，血小板138×10⁹g/L，血Cr182μmol/L，血清蛋白电泳：单峰突起的单克隆M蛋白。X线见第3、4腰椎压缩性骨折。该患者最可能的诊断为",[["A","慢性肾小球肾炎"],["B","腰椎结核"],["C","骨转移瘤"],["D","多发性骨髓瘤"]],"D","老年女性患者，腰痛6周，加重尿少1月，既往体健，尿蛋白（++）（提示蛋白尿），尿沉渣镜检（-），血常规79g/L（正常范围为115～150g/L，提示贫血），白细胞4.7×10⁹/L（正常范围为3.5～9.5×10⁹/L），血小板138×10⁹g/L（正常范围为125～350×10⁹/L），血Cr182μmol/L（正常范围为41～81μmol/L，提示肾功能不全），血清蛋白电泳：单峰突起的单克隆M蛋白（多发性骨髓瘤的突出特点）。X线见第3、4腰椎压缩性骨折（病理性骨折）。该患者最可能的诊断为多发性骨髓瘤（D对）（MM）。多发性骨髓瘤的主要症状为以腰、骶部，胸骨，肋骨疼痛最为常见，由于骨髓瘤细胞浸润抑制造血以及肾功能不全，易引起正常细胞性贫血，白细胞计数、血小板计数多数正常；血清蛋白电泳可见染色浓而密集、单峰突起的M蛋白，正常免疫球蛋白减少。慢性肾小球肾炎（A错）以蛋白尿、血尿、高血压和水肿为基本临床表现，多数起病缓慢、隐匿，肾功能可正常或有不同程度的损害。腰椎结核（B错）可引起脊椎压缩骨折和腰痛，但常有低热、盗汗、体重减轻等结核中毒症状，X线常提示椎旁脓肿等。骨转移瘤（D错）可导致病理性骨折，但多有原发病表现和体征。","","N"],["2026-N54",60,"第二节 原发性醛固酮增多症","原发性醛固酮增多症临床表现",2026,54,"A","","下列疾病中，常引起低钾血症的是",[["A","原发性醛固酮增多症"],["B","Cushing病"],["C","甲状腺功能减退症"],["D","甲状腺功能亢进症"]],"A","原发性醛固酮增多症（A对）时，肾上腺皮质肿瘤或增生导致醛固酮分泌过量，导致潴钠排钾、体液容量扩增、肾素-血管紧张素系统受抑制，表现为高血压和低血钾。Cushing病（B错）虽可因糖皮质激素增多导致低钾，但Cushing病的主要表现以皮质醇增多引起的各种临床症状为主，低钾血症发生率低于原发性醛固酮增多症。甲状腺功能减退症（C错）多表现为黏液性水肿，低钾血症非典型表现。甲状腺功能亢进症（D错）可出现甲状腺毒症周期性瘫痪，伴低钾血症，但非常规表现。","","N"],["2026-N55",68,"第一节 类风湿关节炎","类风湿关节炎MRI",2026,55,"A","","对早期诊断类风湿关节炎最有价值的检查是",[["A","关节X线"],["B","关节超声"],["C","关节MRI"],["D","关节镜"]],"C","对早期诊断类风湿关节炎（RA）最有价值的检查是关节MRI（C对），可以显示关节软组织病变和/或滑膜炎症、水肿与增生、关节积液，以及骨髓水肿等，较X线更敏感。关节X线（A错）对RA诊断、关节病变分期、病变演变的监测均很重要。关节超声（B错）虽能评估滑膜增厚和血流信号，但整体敏感性和特异性不及MRI。关节镜（D错）是侵入性手术操作，常用于治疗或活检，而非常规诊断检查，存在并发症风险且不适合早期筛查。","","N"],["2026-N56",70,"第一节 干燥综合征","干燥综合征口腔科检查",2026,56,"A","","男性，50岁。口干、眼干1年，加重伴双膝关节疼痛1周，哭时无泪。查体：牙齿多片脱落，有的只残留牙根，双膝关节无红肿。确定诊断特异性最强的是",[["A","Schirmer试验"],["B","泪膜破裂时间"],["C","唾液流率"],["D","唇腺病理学检查"]],"D","中年男性患者，口干、眼干1年，加重伴双膝关节疼痛1周（干燥综合征典型表现），哭时无泪（提示泪液减少）。查体：牙齿多片脱落，有的只残留牙根（口腔干燥症特征性表现），双膝关节无红肿。根据患者的临床表现和查体，最可能的诊断为干燥综合征，其诊断特异性最强的是唇腺病理学检查（D对），是诊断该疾病的金标准，特征性病理改变是灶性淋巴细胞性唾液腺炎。Schirmer试验（泪液分泌试验）（A错）主要反映泪液分泌功能，≤5mm为pSS诊断标准之一，但非特异性最强。泪膜破裂时间（B错）反映的是泪膜稳定性，≤10秒为阳性，提示泪膜稳定性下降。唾液流率（C错）是诊断口干燥症的敏感指标，但非特异性最强。","","N"],["2026-N68",16,"第二节 窦性心律失常","病态窦房结综合征",2026,68,"A","","女性，44岁，在长时间排队购物时突感心悸、胸闷，面色苍白，坚持站立1分钟左右突感黑矇，随即倒地，呼之不应。无口吐白沫、出汗、肢体抽搐，半分钟后清醒，自诉发力，仍感心悸、胸闷，自行起立后缓慢行走。既往有心动过速发作病史。患者首先可排除的晕厥病因是",[["A","低血糖晕厥"],["B","单纯性晕厥"],["C","脑源性晕厥"],["D","心源性晕厥"]],"A","中年女性患者，既往有心动过速发作病史（提示可能诱发心源性晕厥）。在长时间排队购物时突感心悸、胸闷，面色苍白（晕厥的先兆症状），站立时（晕厥通常在站立时发生）突感黑矇，随即倒地，呼之不应，无口吐白沫、出汗（可排除低血糖晕厥），半分钟后清醒。该患者晕厥的病因可为单纯性晕厥（B对）、脑源性昏厥（C对）或心源性晕厥（D对）。单纯性晕厥由自主神经功能暂时紊乱引发，表现为短暂意识丧失，通常无严重器质性疾病，可自行恢复，常因特定诱因（如久站、情绪刺激等）触发；心源性晕厥是因心脏或心血管功能异常导致心输出量骤降，引发急性脑缺血而出现的突发性意识丧失，严重时可致猝死，发作时多伴呼吸困难、心律失常及心电图异常；脑源性昏厥是因脑部血管或主要供应脑部的血管发生循环障碍，导致短暂性、广泛性脑供血不足引发的突发意识丧失。低血糖晕厥（A错，为本题正确答案）可出现的临床表现有震颤、心悸和焦虑，以及出汗、饥饿感等，与该患者临床表现不符。","c226","N"],["2026-N69",16,"第一节 心律失常概述","运动心电图",2026,69,"A","","女性，44岁，在长时间排队购物时突感心悸、胸闷，面色苍白，坚持站立1分钟左右突感黑矇，随即倒地，呼之不应。无口吐白沫、出汗、肢体抽搐，半分钟后清醒，自诉发力，仍感心悸、胸闷，自行起立后缓慢行走。既往有心动过速发作病史。为了明确病因，首选检查是什么",[["A","快速血糖检测"],["B","动态心电图"],["C","头颅核磁"],["D","冠状动脉CTA"]],"B","中年女性患者，既往有心动过速发作病史（提示可能诱发心源性晕厥）。在长时间排队购物时突感心悸、胸闷，面色苍白（晕厥的先兆症状），站立时（晕厥通常在站立时发生）突感黑矇，随即倒地，呼之不应，无口吐白沫、出汗（可排除低血糖晕厥），半分钟后清醒。患者既往有心动过速发作病史，考虑心源性因素可能性较大，且优先考虑心律失常（如阵发性室上性心动过速）导致的脑灌注不足。首选检查为动态心电图（B对），可以了解心悸与晕厥等症状的发生是否与心律失常有关。快速血糖检测（A错）用于监测血糖的情况，该患者目前已排除低血糖晕厥，快速血糖监测作用不大。头颅核磁（C错）主要用于排查脑结构性病变（如脑梗死、出血、肿瘤等），目前首先考虑心源性晕厥，头颅核磁不作为首选。冠状动脉CTA（D错）可以显示冠状动脉主要分支病变情况、冠状动脉解剖异常和桥血管情况，是筛查和诊断冠心病的重要手段。","c226","N"],["2026-N70",28,"第一节 消化性溃疡","幽门梗阻",2026,70,"A","","男性，52岁，10余年来餐后出现上腹部持续性钝痛，自服“胃药”可缓解，近3月因劳累，自感上腹钝痛加剧，伴恶心，呕吐后可缓解，呕吐物含宿食，自觉乏力，食欲差，体重下降3kg。该患者最可能的诊断是",[["A","慢性胃炎"],["B","反流性食管炎"],["C","幽门梗阻"],["D","慢性胰腺炎"]],"C","52岁男性患者，10余年来餐后出现上腹部持续性钝痛（提示存在慢性消化道疾病），自服“胃药”可缓解，近3月上腹钝痛加剧，伴恶心，呕吐后可缓解，呕吐物含隔夜宿食（胃内容物潴留的典型表现，提示胃出口梗阻），体重下降3kg，综合患者临床表现，考虑诊断为幽门梗阻（C对）。慢性胃炎（A错）多为非特异性消化不良症状，一般不引起频繁呕吐宿食及明显体重下降。反流性食管炎（B错）的典型症状为烧心和反流，烧心和反流常发生于餐后1小时，卧位、弯腰或腹内压增高时可加重，部分病人也可发生于夜间睡眠时。慢性胰腺炎（D错）是由于各种原因导致的胰腺局部或弥漫性的慢性进展性炎症，伴随胰腺内外分泌功能的不可逆损害，临床上表现为反复发作性或持续性腹痛、腹泻或脂肪泻、消瘦、黄疸、腹部包块和糖尿病。","c227","N"],["2026-N71",28,"第一节 消化性溃疡","幽门梗阻",2026,71,"A","","男性，52岁，10余年来餐后出现上腹部持续性钝痛，自服“胃药”可缓解，近3月因劳累，自感上腹钝痛加剧，伴恶心，呕吐后可缓解，呕吐物含宿食，自觉乏力，食欲差，体重下降3kg。该患者可能出现的体征是",[["A","压痛、反跳痛（+）"],["B","振水音（+）"],["C","液波震颤（+）"],["D","移动性浊音（+）"]],"B","52岁男性患者，10余年来餐后出现上腹部持续性钝痛（提示存在慢性消化道疾病），自服“胃药”可缓解，近3月上腹钝痛加剧，伴恶心，呕吐后可缓解，呕吐物含隔夜宿食（胃内容物潴留的典型表现，提示胃出口梗阻），体重下降3kg，综合患者临床表现，考虑诊断为幽门梗阻。幽门梗阻时胃内积液积气，冲击患者上腹部可闻及气过水声即振水音阳性（B对）。腹肌紧张、压痛与反跳痛（A错）合称腹膜刺激征，常见于腹膜炎患者。液波震颤（C错）用于检查腹腔积液，需有3000ml以上液体量才能查出。移动性浊音（D错）是发现有无腹腔积液的重要检查方法，当腹腔内游离腹腔积液在1000ml以上时，移动性浊音阳性。","c227","N"],["2026-N72",28,"","",2026,72,"A","","男性，52岁，10余年来餐后出现上腹部持续性钝痛，自服“胃药”可缓解，近3月因劳累，自感上腹钝痛加剧，伴恶心，呕吐后可缓解，呕吐物含宿食，自觉乏力，食欲差，体重下降3kg。该患者呕吐频繁，最可能出现的电解质紊乱是",[["A","低钾血症"],["B","高氯血症"],["C","高钠血症"],["D","低钙血症"]],"A","52岁男性患者，10余年来餐后出现上腹部持续性钝痛（提示存在慢性消化道疾病），自服“胃药”可缓解，近3月上腹钝痛加剧，伴恶心，呕吐后可缓解，呕吐物含隔夜宿食（胃内容物潴留的典型表现，提示胃出口梗阻），体重下降3kg，综合患者临床表现，考虑诊断为幽门梗阻。由于患者呕吐频繁，导致胃酸（H⁺、K⁺、Cl⁻）丢失，容易导致代谢性碱中毒和低钾血症（A对）。幽门梗阻患者呕吐胃酸会导致氯离子丢失，通常表现为低氯血症（B错）。高钠血症（C错）通常由水分丢失多于钠丢失或钠摄入过多引起。低钙血症（D错）常见于甲状旁腺功能减退、维生素D缺乏或肾功能不全，与呕吐无直接关联。","c227","N"],["2026-N73",11,"第一节 胸腔积液","肺炎旁胸腔积液",2026,73,"A","","女性，56岁，发热1周，最高体温39.5℃，伴咳嗽、黄痰，右季肋区疼痛，深呼吸时明显，类风湿性关节炎20年，长期服用糖皮质激素，2型糖尿病5年，血糖控制不满意。查体：体温38.5℃，右下肺呼吸音减弱，可闻及湿啰音，血WBC15.6×10⁹/L。胸部CT：右下肺实变，右侧有胸腔积液。胸腔积液检查：白细胞6800×10⁶/L，多核细胞80%，蛋白质55g/L，LDH 836IU/L，ADA 28IU/L。以下哪项最符合积液的性质",[["A","肿瘤性积液"],["B","结核性积液"],["C","肺炎旁胸腔积液"],["D","类风湿相关性积液"]],"C","中老年女性患者，既往类风湿关节炎，长期服用糖皮质激素，且糖尿病血糖控制差（免疫功能抑制，易感染）。发热1周，最高39.5℃（正常体温36～37℃，高热），伴咳嗽、咳黄痰（呼吸道感染症状），右季肋区疼痛，深呼吸时加重（提示急性感染性胸膜炎）。查体：右下肺呼吸音减低、湿啰音（右下肺感染征象）。辅助检查：血白细胞15.6×10⁹/L（正常3.5～9.5×10⁹/L，显著升高），CT显示右下肺实变伴胸腔积液。胸腔积液检查白细胞增多、多核细胞占80%（中性粒细胞为主，提示急性细菌感染的可能性大），蛋白55g/L（＞30g/L，提示渗出液），LDH 836IU/L（＞200IU/L，提示渗出液），ADA 28U/L（结核性通常＞45U/L，结核性胸腔积液可能性不大）。综合患者急性感染的临床表现及胸腔积液的检查结果，该患者最可能为肺炎旁胸腔积液（C对）。肿瘤性胸腔积液（A错）以中老年人多见，主要临床表现包括呼吸困难、胸部钝痛、咳血丝痰和消瘦等症状，胸腔积液多呈血性、量大、增长迅速，CEA或其他肿瘤标志物升高，胸部影像学检查可发现肺部占位。结核性胸腔积液（B错）常与肺结核或身体其他部位结核同时存在，表现为胸痛、气短，可伴有潮热、盗汗、消瘦等结核中毒症状，ADA常＞45U/L。类风湿相关性胸腔积液（D错）见于类风湿关节炎患者，多为慢性低热，为单侧或双侧少量胸腔积液，为渗出液，葡萄糖含量降低。","c228","N"],["2026-N74",11,"","",2026,74,"A","","女性，56岁，发热1周，最高体温39.5℃，伴咳嗽、黄痰，右季肋区疼痛，深呼吸时明显，类风湿性关节炎20年，长期服用糖皮质激素，2型糖尿病5年，血糖控制不满意。查体：体温38.5℃，右下肺呼吸音减弱，可闻及湿啰音，血WBC15.6×10⁹/L。胸部CT：右下肺实变，右侧有胸腔积液。胸腔积液检查：白细胞6800×10⁶/L，多核细胞80%，蛋白质55g/L，LDH 836IU/L，ADA 28IU/L。为明确诊断，首选的胸腔积液检查是",[["A","涂片查结核杆菌"],["B","查肿瘤细胞"],["C","细菌培养+药敏"],["D","类风湿因子"]],"C","中老年女性患者，既往类风湿关节炎，长期服用糖皮质激素，且糖尿病血糖控制差（免疫功能抑制，易感染）。发热1周，最高39.5℃（正常体温36～37℃，高热），伴咳嗽、咳黄痰（呼吸道感染症状），右季肋区疼痛，深呼吸时加重（提示急性感染性胸膜炎）。查体：右下肺呼吸音减低、湿啰音（右下肺感染征象）。辅助检查：血白细胞15.6×10⁹/L（正常3.5～9.5×10⁹/L，显著升高），CT显示右下肺实变伴胸腔积液。胸腔积液检查白细胞增多、多核细胞占80%（中性粒细胞为主，提示急性细菌感染的可能性大），蛋白55g/L（＞30g/L，提示渗出液），LDH 836IU/L（＞200IU/L，提示渗出液），ADA 28U/L（结核性通常＞45U/L，结核性胸腔积液可能性不大）。综合患者急性感染的临床表现及胸腔积液的检查结果，该患者最可能为肺炎旁胸腔积液。为明确诊断，首选胸腔积液检查应为细菌培养+药敏试验（C对），因为临床表现和积液性质高度提示细菌感染，细菌培养+药敏可明确病原体并指导抗生素选择。该患者ADA28U/L，排除结核性胸膜炎，故排除使用涂片查结核杆菌（A错）。查肿瘤细胞（B错）用于筛查恶性胸腔积液，该患者有明确的急性感染灶和感染性积液表现，不考虑恶性胸腔积液。类风湿因子（D错）可用于辅助诊断类风湿性胸膜炎，但诊断特异性不高，且该患者目前不考虑类风湿相关性积液。","c228","N"],["2026-N75",11,"第一节 胸腔积液","肺炎旁胸腔积液",2026,75,"A","","女性，56岁，发热1周，最高体温39.5℃，伴咳嗽、黄痰，右季肋区疼痛，深呼吸时明显，类风湿性关节炎20年，长期服用糖皮质激素，2型糖尿病5年，血糖控制不满意。查体：体温38.5℃，右下肺呼吸音减弱，可闻及湿啰音，血WBC15.6×10⁹/L。胸部CT：右下肺实变，右侧有胸腔积液。胸腔积液检查：白细胞6800×10⁶/L，多核细胞80%，蛋白质55g/L，LDH 836IU/L，ADA 28IU/L。治疗措施是",[["A","四联抗结核杆菌"],["B","全身化疗"],["C","静脉应用抗菌药"],["D","加大剂量用糖皮质激素"]],"C","中老年女性患者，既往类风湿关节炎，长期服用糖皮质激素，且糖尿病血糖控制差（免疫功能抑制，易感染）。发热1周，最高39.5℃（正常体温36～37℃，高热），伴咳嗽、咳黄痰（呼吸道感染症状），右季肋区疼痛，深呼吸时加重（提示急性感染性胸膜炎）。查体：右下肺呼吸音减低、湿啰音（右下肺感染征象）。辅助检查：血白细胞15.6×10⁹/L（正常3.5～9.5×10⁹/L，显著升高），CT显示右下肺实变伴胸腔积液。胸腔积液检查白细胞增多、多核细胞占80%（中性粒细胞为主，提示急性细菌感染的可能性大），蛋白55g/L（＞30g/L，提示渗出液），LDH 836IU/L（＞200IU/L，提示渗出液），ADA 28U/L（结核性通常＞45U/L，结核性胸腔积液可能性不大）。综合患者急性感染的临床表现及胸腔积液的检查结果，该患者最可能为肺炎旁胸腔积液。治疗原则是控制感染、引流胸腔积液、营养支持治疗，故该患者的最佳治疗为静脉应用抗菌药（C对），直接针对细菌感染。该患者不考虑结核性胸膜炎，无使用抗结核药指征（A错）。该患者无任何肿瘤依据，无需全身化疗（B错）。在活动性细菌感染未控制前，增加激素剂量（D错）会进一步抑制免疫，导致感染扩散、恶化，甚至死亡。","c228","N"],["2026-N76",17,"第四节 急性冠状综合征","不稳定型心绞痛和非ST段抬高型心肌梗死诊断",2026,76,"A","","男性，68岁，一周来凌晨睡眠中反复出现胸痛，伴咽颈部紧缩感，出汗，口含硝酸甘油1分钟后可缓解，日间活动正常，无胸痛发作。既往有糖尿病、慢性胃炎病史，吸烟40年。该患者最可能的诊断是",[["A","稳定型心绞痛"],["B","初发型心绞痛"],["C","变异型心绞痛"],["D","非ST段抬高型心肌梗死"]],"C","患者老年男性，既往有糖尿病，吸烟40年（均为冠心病危险因素）。一周来凌晨睡眠中（变异型心绞痛的常见发作时间）反复出现胸痛，伴咽颈部紧缩感（典型心绞痛症状），口含硝酸甘油可缓解（可排除急性心肌梗死），日间活动正常，无胸痛发作（排除劳累性心绞痛）。根据该患者症状、体征及既往病史，最可能的诊断是变异型心绞痛（C对），变异型心绞痛由冠状动脉痉挛引起，常于夜间或凌晨休息时发生，硝酸甘油能快速缓解痉挛。稳定型心绞痛（A错）也称劳力性心绞痛，其特点为阵发性的前胸部压榨性疼痛或憋闷感觉，主要位于胸骨后部，可放射至心前区和左上肢尺侧，常发生于劳力负荷增加时。初发型心绞痛（B错）通常在首发症状1～2个月内、很轻的体力活动可诱发，程度至少达CCS Ⅲ级。非ST段抬高型心肌梗死（D错）表现为突发胸痛、胸闷、憋气持续不缓解，伴有出汗等症状，心电图表现为ST段压低、T波倒置。","c229","N"],["2026-N77",17,"第四节 急性冠状综合征","静息心电图",2026,77,"A","","男性，68岁，一周来凌晨睡眠中反复出现胸痛，伴咽颈部紧缩感，出汗，口含硝酸甘油1分钟后可缓解，日间活动正常，无胸痛发作。既往有糖尿病、慢性胃炎病史，吸烟40年。胸痛发作时心电图的改变是",[["A","病理性Q波"],["B","QRS波增宽"],["C","ST段抬高"],["D","ST段压低"]],"C","患者老年男性，既往有糖尿病，吸烟40年（均为冠心病危险因素）。一周来凌晨睡眠中（变异型心绞痛的常见发作时间）反复出现胸痛，伴咽颈部紧缩感（典型心绞痛症状），口含硝酸甘油可缓解（可排除急性心肌梗死），日间活动正常，无胸痛发作（排除劳累性心绞痛）。根据该患者症状、体征及既往病史，最可能的诊断是变异型心绞痛。发作时最可能的心电图表现为ST段抬高（C对），因为冠脉痉挛引起血管完全或近乎完全闭塞，发作时心电图呈一过性ST段抬高，T波高耸，或T波假性正常化。病理性Q波（A错）是急性心肌梗死的特征性改变，发生于梗死后数小时或数日，可持续到数周。QRS波增宽（B错）多见于室内传导阻滞、预激综合征、室性心律失常等。ST段压低（D错）提示心绞痛发作时短暂的心内膜下缺血，虽然非典型变异型心绞痛患者可出现，但比较少见。","c229","N"],["2026-N78",17,"第四节 急性冠状综合征","钙通道阻滞剂",2026,78,"A","","男性，68岁，一周来凌晨睡眠中反复出现胸痛，伴咽颈部紧缩感，出汗，口含硝酸甘油1分钟后可缓解，日间活动正常，无胸痛发作。既往有糖尿病、慢性胃炎病史，吸烟40年。最佳的治疗药物是",[["A","地尔硫䓬"],["B","单硝酸异山梨酯"],["C","美托洛尔"],["D","尼可地尔"]],"A","患者老年男性，既往有糖尿病，吸烟40年（均为冠心病危险因素）。一周来凌晨睡眠中（变异型心绞痛的常见发作时间）反复出现胸痛，伴咽颈部紧缩感（典型心绞痛症状），口含硝酸甘油可缓解（可排除急性心肌梗死），日间活动正常，无胸痛发作（排除劳累性心绞痛）。根据该患者症状、体征及既往病史，最可能的诊断是变异型心绞痛。最佳的治疗药物是地尔硫䓬（A对），其作为非二氢吡啶类钙通道阻滞剂，能有效解除冠脉痉挛，对于血管痉挛性心绞痛的病人，可作为首选。单硝酸异山梨酯（B错）虽为硝酸酯类，可用于一般心绞痛，但对冠脉痉挛效果不佳。美托洛尔（C错）可能会加重或诱发痉挛，不能单独用于变异型心绞痛病人。尼可地尔（D错）属于三磷酸腺苷（ATP）敏感性钾通道开放剂，与硝酸酯类制剂具有相似药理特性，虽可用于心绞痛，一般作为联用的药物，钙通道阻滞剂更优。","c229","N"],["2026-N79",27,"","",2026,79,"A","","男性，55岁，上腹部不适、食欲减退3年余。加重伴头晕、乏力3个月。查体：轻度贫血貌，上腹部轻压痛，肝脾肋下未触及。血常规：Hb82g/L，RBC2.0×10¹²/L，WBC3.5×10⁹/L，Plt98×10⁹/L。胃镜检查见胃黏膜色泽变淡，胃体皱襞变细而平坦，黏液分泌减少，黏膜血管透见。最有可能诊断的是",[["A","慢性浅表性胃炎"],["B","慢性萎缩性胃炎"],["C","胃癌"],["D","胃溃疡"]],"B","中年男性患者，上腹部不适、食欲减退3年余，加重伴头晕、乏力3个月（提示慢性消耗性疾病）。查体：轻度贫血貌，上腹部轻压痛。血常规：Hb82g/L（正常值130～175g/L，降低），RBC2.0×10¹²/L（正常值4.3～5.8×10¹²/L，降低），WBC3.5×10⁹/L（正常值3.5～9.5×10⁹/L），Plt98×10⁹/L（正常值125～350×10⁹/L，降低）。胃镜检查见胃黏膜色泽变淡，胃体皱襞变细而平坦，黏液分泌减少，黏膜血管透见（典型慢性萎缩性胃炎表现）。根据患者的临床表现、实验室检查及胃镜结果，最有可能的诊断是慢性萎缩性胃炎（B对）。慢性浅表性胃炎（A错）胃镜下多表现为黏膜充血、水肿，皱襞通常正常或增粗，且慢性浅表性胃炎极少引起贫血或全血细胞减少。胃癌（C错）患者常有体重下降、恶病质、上腹部包块等表现，胃镜下可见占位性病变（如溃疡、肿块或黏膜粗糙不平）。胃溃疡（D错）典型表现为周期性、节律性上腹痛（餐后痛或夜间痛），胃镜下可见圆形或椭圆形溃疡灶，周围黏膜皱襞集中。","c230","N"],["2026-N80",27,"第二节 慢性胃炎","慢性胃炎诊断",2026,80,"A","","男性，55岁，上腹部不适、食欲减退3年余。加重伴头晕、乏力3个月。查体：轻度贫血貌，上腹部轻压痛，肝脾肋下未触及。血常规：Hb82g/L，RBC2.0×10¹²/L，WBC3.5×10⁹/L，Plt98×10⁹/L。胃镜检查见胃黏膜色泽变淡，胃体皱襞变细而平坦，黏液分泌减少，黏膜血管透见。对诊断最有意义的检查是",[["A","粪隐血实验"],["B","血清抗壁细胞抗体"],["C","血清癌胚抗原"],["D","¹³C-尿素呼气实验"]],"B","中年男性患者，上腹部不适、食欲减退3年余，加重伴头晕、乏力3个月（提示慢性消耗性疾病）。查体：轻度贫血貌，上腹部轻压痛。血常规：Hb82g/L（正常值130～175g/L，降低），RBC2.0×10¹²/L（正常值4.3～5.8×10¹²/L，降低），WBC3.5×10⁹/L（正常值3.5～9.5×10⁹/L），Plt98×10⁹/L（正常值125～350×10⁹/L，降低）。胃镜检查见胃黏膜色泽变淡，胃体皱襞变细而平坦，黏液分泌减少，黏膜血管透见（典型慢性萎缩性胃炎表现）。根据患者的临床表现、实验室检查及胃镜结果，最有可能的诊断是慢性萎缩性胃炎。病因上，黏膜血管透见和贫血高度提示自身免疫性胃炎（A型胃炎），因此对诊断最有意义的检查是血清抗壁细胞抗体（B对）。粪隐血试验（A错）用于检测消化道出血，该患者无黑便、呕血等表现，且贫血原因更可能与维生素B₁₂缺乏相关，而非慢性失血。血清癌胚抗原（C错）主要用于肿瘤监测，该患者无体重下降、恶病质等恶性肿瘤典型表现，且胃镜未提示占位性病变。¹³C-尿素呼气试验（D错）用于检测幽门螺杆菌（Hp）感染，该患者胃镜表现为胃体萎缩，Hp感染更常见于胃窦为主的萎缩性胃炎（B型胃炎），自身免疫性胃炎与Hp感染无直接关联。","c230","N"],["2026-N81",27,"第二节 慢性胃炎","慢性胃炎治疗",2026,81,"A","","男性，55岁，上腹部不适、食欲减退3年余。加重伴头晕、乏力3个月。查体：轻度贫血貌，上腹部轻压痛，肝脾肋下未触及。血常规：Hb82g/L，RBC2.0×10¹²/L，WBC3.5×10⁹/L，Plt98×10⁹/L。胃镜检查见胃黏膜色泽变淡，胃体皱襞变细而平坦，黏液分泌减少，黏膜血管透见。首选的治疗方法是",[["A","抗幽门螺旋杆菌治疗"],["B","补充铁剂"],["C","补充叶酸和维生素B₁₂治疗"],["D","手术治疗"]],"C","中年男性患者，上腹部不适、食欲减退3年余，加重伴头晕、乏力3个月（提示慢性消耗性疾病）。查体：轻度贫血貌，上腹部轻压痛。血常规：Hb82g/L（正常值130～175g/L，降低），RBC2.0×10¹²/L（正常值4.3～5.8×10¹²/L，降低），WBC3.5×10⁹/L（正常值3.5～9.5×10⁹/L），Plt98×10⁹/L（正常值125～350×10⁹/L，降低）。胃镜检查见胃黏膜色泽变淡，胃体皱襞变细而平坦，黏液分泌减少，黏膜血管透见（典型慢性萎缩性胃炎表现）。根据患者的临床表现、实验室检查及胃镜结果，最有可能的诊断是慢性萎缩性胃炎。该患者考虑A型胃炎，因为内因子分泌减少，影响维生素B₁₂吸收，进而引起巨幼细胞性贫血，因此，首选治疗方法为补充叶酸和维生素B₁₂治疗（C对），以纠正贫血和改善黏膜萎缩。抗幽门螺旋杆菌治疗（A错）不适用，该患者不考虑B型胃炎，且题干未提供幽门螺旋杆菌感染证据。补充铁剂（B错）适用于缺铁性贫血，本例无小细胞低色素等缺铁特征。手术治疗（D错）非常规选择，萎缩性胃炎一般无需手术干预。","c230","N"],["2026-N82",41,"第一节 尿路感染","慢性肾盂肾炎",2026,82,"A","","女性，35岁。尿频、尿急、尿痛伴腰痛，发热3天，体温最高38.5℃。既往有反复类似症状发作2年，曾用多种抗生素治疗，病情时轻时重，无结核病病史，尿常规：尿蛋白（+），尿沉渣镜检显示：RBC0-4个/HPF，WBC20-30个/HPF。对该病的诊断，最可能的是",[["A","慢性膀胱炎急性发作"],["B","急性肾盂肾炎"],["C","慢性肾盂肾炎急性发作"],["D","肾结核"]],"C","青年女性患者，尿频、尿急、尿痛（尿路刺激征）伴腰痛（腰痛为肾盂肾炎常见症状），发热3天，体温最高38.5℃（属于全身感染症状，提示急性发作）。既往有反复类似症状发作2年（提示慢性感染或反复急性感染未彻底治愈，符合慢性肾盂肾炎的特点）。尿常规：尿蛋白（+），尿沉渣镜检显示：RBC0-4个/HPF（正常或轻度升高），WBC20-30个/HPF（显著升高，提示尿路感染）。根据患者的临床表现、病史及实验室检查结果，最可能的诊断是慢性肾盂肾炎急性发作（C对）。慢性膀胱炎急性发作（A错）通常表现为尿频、尿急、尿痛，但无腰痛和发热，除非合并上尿路感染。尿常规中蛋白尿不常见，且白细胞升高程度通常低于肾盂肾炎。急性肾盂肾炎（B错）可表现为腰痛、发热及尿路刺激征，但患者有反复发作史，提示慢性病程，单纯急性肾盂肾炎无法解释既往病史。肾结核（D错）的典型表现为膀胱刺激征伴终末血尿，尿常规以红细胞增多为主，而本例红细胞正常或轻度升高。肾结核患者常有低热、盗汗等结核中毒症状，且影像学检查（如IVU）可显示肾实质破坏或空洞，本例未提及。","c231","N"],["2026-N83",41,"第一节 尿路感染","慢性肾盂肾炎的诊断",2026,83,"A","","女性，35岁。尿频、尿急、尿痛伴腰痛，发热3天，体温最高38.5℃。既往有反复类似症状发作2年，曾用多种抗生素治疗，病情时轻时重，无结核病病史，尿常规：尿蛋白（+），尿沉渣镜检显示：RBC0-4个/HPF，WBC20-30个/HPF。下列检查结果最支持诊断的是",[["A","尿沉渣镜检见颗粒管型"],["B","血白细胞计数和中性粒细胞比例增高"],["C","γ-干扰素释放试验阳性"],["D","持续性肾小管功能损害"]],"D","青年女性患者，尿频、尿急、尿痛（尿路刺激征）伴腰痛（腰痛为肾盂肾炎常见症状），发热3天，体温最高38.5℃（属于全身感染症状，提示急性发作）。既往有反复类似症状发作2年（提示慢性感染或反复急性感染未彻底治愈，符合慢性肾盂肾炎的特点）。尿常规：尿蛋白（+），尿沉渣镜检显示：RBC0-4个/HPF（正常或轻度升高），WBC20-30个/HPF（显著升高，提示尿路感染）。根据患者的临床表现、病史及实验室检查结果，最可能的诊断是慢性肾盂肾炎急性发作。最支持诊断的是持续性肾小管功能损害（D对），表现为夜尿增多、低比重尿等，是诊断慢性肾盂肾炎的重要依据。尿沉渣镜检见颗粒管型（A错）多见于肾小球疾病（如慢性肾炎），肾盂肾炎少见，非特异性指标。血白细胞计数和中性粒细胞比例增高（B错）仅提示急性感染，无法区分急性或慢性肾盂肾炎，缺乏特异性。γ-干扰素释放试验阳性（C错）用于诊断结核病，患者无结核病史，该结果与病情无关。","c231","N"],["2026-N84",41,"第一节 尿路感染","尿路感染致病菌",2026,84,"A","","女性，35岁。尿频、尿急、尿痛伴腰痛，发热3天，体温最高38.5℃。既往有反复类似症状发作2年，曾用多种抗生素治疗，病情时轻时重，无结核病病史，尿常规：尿蛋白（+），尿沉渣镜检显示：RBC0-4个/HPF，WBC20-30个/HPF。清洁后中段尿培养，最常见的细菌是",[["A","金黄色葡萄球菌"],["B","大肠埃希菌"],["C","结核分枝杆菌"],["D","厌氧菌"]],"B","青年女性患者，尿频、尿急、尿痛（尿路刺激征）伴腰痛（腰痛为肾盂肾炎常见症状），发热3天，体温最高38.5℃（属于全身感染症状，提示急性发作）。既往有反复类似症状发作2年（提示慢性感染或反复急性感染未彻底治愈，符合慢性肾盂肾炎的特点）。尿常规：尿蛋白（+），尿沉渣镜检显示：RBC0-4个/HPF（正常或轻度升高），WBC20-30个/HPF（显著升高，提示尿路感染）。根据患者的临床表现、病史及实验室检查结果，最可能的诊断是慢性肾盂肾炎急性发作。清洁后中段尿培养，最常见的细菌是大肠埃希菌（B对），因为大肠埃希菌是尿路感染最常见的病原菌。金黄色葡萄球菌（A错）为革兰氏阳性球菌，主要引起皮肤软组织、血液或导管相关感染，尿路感染中较少见。该患者无结核病史，且症状以急性尿路感染为主，无低热、盗汗等结核中毒症状，尿常规中无大量红细胞或脓细胞聚集，故结核分枝杆菌（C错）可能性低。厌氧菌（D错）尿路感染多见于复杂性尿路感染（如尿路梗阻、结石或留置导尿管），该患者无相关危险因素，且常规中段尿培养难以检出厌氧菌。","c231","N"],["2026-N85",49,"第一节 再生障碍性贫血","AA诊断标准",2026,85,"A","","男性，65岁。乏力、面色苍白3个月，加重伴间断心前区疼痛2天，既往冠心病病史3年。查体：明显贫血貌，四肢皮肤可见散在出血点，浅表淋巴结未触及肿大，巩膜无黄染，心率112次/分，心律齐，肝脾肋下未触及。实验室检查：血红蛋白54g/L，红细胞1.8×10¹²/L，网织红蛋白0.1%，白细胞2.1×10⁹/L，淋巴细胞85%，血小板38×10⁹/L。最可能的诊断是",[["A","急性白血病"],["B","巨幼细胞性贫血"],["C","再生障碍性贫血"],["D","PNH"]],"C","老年男性患者。乏力、面色苍白3个月（贫血表现），加重伴间断心前区疼痛2天（可能与严重贫血导致心肌缺血有关），既往冠心病病史3年。查体：明显贫血貌，四肢皮肤可见散在出血点（提示血小板减少引起出血倾向），浅表淋巴结未触及肿大，巩膜无黄染（可排除溶血性疾病），心率112次/分（正常为60～100次/分），心律齐，肝脾肋下未触及。实验室检查：血红蛋白54g/L（正常值130～175g/L，重度贫血），红细胞1.8×10¹²/L（正常值4.3～5.8×10¹²/L，降低），网织红蛋白0.1%（0.5%～1.5%，明显降低），白细胞2.1×10⁹/L（正常值3.5～9.5×10⁹/L，降低），淋巴细胞85%（正常值20%～40%，升高），血小板38×10⁹/L（正常值125～350×10⁹/L，明显降低）。根据患者的临床表现和实验室检查结果，最可能的诊断是再生障碍性贫血（C对），其特征为全血细胞减少、网织红细胞显著减低、无肝脾肿大及溶血表现。急性白血病（A错）起病急，常表现为贫血、发热、出血等，通常有白细胞异常增多或原始细胞浸润表现，伴有肝、脾、淋巴结肿大。巨幼细胞性贫血（B错）表现为大细胞性贫血、网织红细胞正常或升高，且有叶酸和维生素B₁₂缺乏的依据。PNH（阵发性睡眠性血红蛋白尿）（D错）典型患者有特征性间歇发作的睡眠后血红蛋白尿，部分患者有黄疸，出血和感染较少见，网织红细胞增高，Ham试验及蛇毒因子溶血试验呈阳性反应。","c232","N"],["2026-N86",49,"第一节 再生障碍性贫血","AA骨髓象",2026,86,"A","","男性，65岁。乏力、面色苍白3个月，加重伴间断心前区疼痛2天，既往冠心病病史3年。查体：明显贫血貌，四肢皮肤可见散在出血点，浅表淋巴结未触及肿大，巩膜无黄染，心率112次/分，心律齐，肝脾肋下未触及。实验室检查：血红蛋白54g/L，红细胞1.8×10¹²/L，网织红蛋白0.1%，白细胞2.1×10⁹/L，淋巴细胞85%，血小板38×10⁹/L。为明确诊断，首先检查是",[["A","血清叶酸和维生素B₁₂检测"],["B","流式细胞术测定CD55、CD59阴性率"],["C","血涂片中性粒细胞碱性磷酸酶染色情况"],["D","骨髓细胞学检查"]],"D","老年男性患者。乏力、面色苍白3个月（贫血表现），加重伴间断心前区疼痛2天（可能与严重贫血导致心肌缺血有关），既往冠心病病史3年。查体：明显贫血貌，四肢皮肤可见散在出血点（提示血小板减少引起出血倾向），浅表淋巴结未触及肿大，巩膜无黄染（可排除溶血性疾病），心率112次/分（正常为60～100次/分），心律齐，肝脾肋下未触及。实验室检查：血红蛋白54g/L（正常值130～175g/L，重度贫血），红细胞1.8×10¹²/L（正常值4.3～5.8×10¹²/L，降低），网织红蛋白0.1%（0.5%～1.5%，明显降低），白细胞2.1×10⁹/L（正常值3.5～9.5×10⁹/L，降低），淋巴细胞85%（正常值20%～40%，升高），血小板38×10⁹/L（正常值125～350×10⁹/L，明显降低）。根据患者的临床表现和实验室检查结果，最可能的诊断是再生障碍性贫血。为明确诊断，首先检查是骨髓细胞学检查（D对），因其可直接评估骨髓造血细胞数量和形态，是诊断骨髓疾病的金标准。血清叶酸和维生素B₁₂检测（A错）常用于巨幼细胞贫血的诊断，但该患者网织红细胞极低且无大细胞贫血表现，不支持巨幼细胞贫血的诊断。流式细胞术测定CD55、CD59阴性率（B错）用于阵发性睡眠性血红蛋白尿，但该患者无黄疸或溶血证据，不支持阵发性睡眠性血红蛋白尿的诊断。虽然血涂片中性粒细胞碱性磷酸酶染色（C错）在再生障碍性贫血中可出现阳性反应，但其主要还是用于慢性粒细胞白血病等骨髓增殖性疾病的诊断，而骨髓细胞学检查对再生障碍性贫血的诊断价值更大，所以不首选血涂片中性粒细胞碱性磷酸酶染色。","c232","N"],["2026-N87",49,"第一节 再生障碍性贫血","对症治疗",2026,87,"A","","男性，65岁。乏力、面色苍白3个月，加重伴间断心前区疼痛2天，既往冠心病病史3年。查体：明显贫血貌，四肢皮肤可见散在出血点，浅表淋巴结未触及肿大，巩膜无黄染，心率112次/分，心律齐，肝脾肋下未触及。实验室检查：血红蛋白54g/L，红细胞1.8×10¹²/L，网织红蛋白0.1%，白细胞2.1×10⁹/L，淋巴细胞85%，血小板38×10⁹/L。该患者目前的应急处理是",[["A","输注悬浮红细胞"],["B","血小板成分输注"],["C","补充叶酸和维生素B₁₂"],["D","全身紧急化疗"]],"A","老年男性患者。乏力、面色苍白3个月（贫血表现），加重伴间断心前区疼痛2天（可能与严重贫血导致心肌缺血有关），既往冠心病病史3年。查体：明显贫血貌，四肢皮肤可见散在出血点（提示血小板减少引起出血倾向），浅表淋巴结未触及肿大，巩膜无黄染（可排除溶血性疾病），心率112次/分（正常为60～100次/分），心律齐，肝脾肋下未触及。实验室检查：血红蛋白54g/L（正常值130～175g/L，重度贫血），红细胞1.8×10¹²/L（正常值4.3～5.8×10¹²/L，降低），网织红蛋白0.1%（0.5%～1.5%，明显降低），白细胞2.1×10⁹/L（正常值3.5～9.5×10⁹/L，降低），淋巴细胞85%（正常值20%～40%，升高），血小板38×10⁹/L（正常值125～350×10⁹/L，明显降低）。根据患者的临床表现和实验室检查结果，最可能的诊断是再生障碍性贫血。该患者属于重度贫血，符合输血指征（血红蛋白＜60g/L），且伴明显贫血症状及心前区疼痛（提示心肌缺血），随时可能因氧输送不足诱发急性冠脉事件，故应急处理首选输注悬浮红细胞（A对），以迅速提高携氧能力、缓解心肌缺氧。该患者血小板虽低于正常，但尚无活动性出血表现，不符合输血小板指征（血小板＜20×10⁹/L），可暂不输血小板（B错）。叶酸、B₁₂补充（C错）及化疗（D错）分别用于治疗巨细胞贫血和白血病，且均非应急措施。","c232","N"],["2026-N88",60,"第一节 库欣综合征","库欣综合征诊断与鉴别诊断",2026,88,"A","","女性，27岁。2年来体重增加20Kg，半年来月经仅来潮两次就诊。一个月前体检发现空腹血糖6.5mmol/L。查体：身高158cm，体重75Kg，BP145/90mmHg，水牛背，后颈部皮肤可见色素沉着，双大腿内外侧可见少量紫纹。该患者最可能的诊断是",[["A","高血压病"],["B","Cushing综合征"],["C","糖耐量异常"],["D","肥胖症"]],"B","青年女性患者，2年体重增加20kg（肥胖），半年月经仅两次（月经失调），空腹血糖6.5mmol/L（正常值3.9～6.1mmol/L，提示糖耐量异常），查体显示血压145/90mmHg（正常值90～139/60～89mmHg，提示高血压），查体：身高158cm，体重75Kg（BMI30，提示肥胖），水牛背、后颈部色素沉着、双大腿内外侧紫纹（Cushing综合征临床表现）。根据患者病史、临床表现、查体、实验室检查等，该患者最可能的诊断是Cushing综合征（B对）。高血压病（A错）无月经失调、糖耐量异常、水牛背、色素沉着、紫纹等表现。糖耐量异常（C错）为该患者的其中一种表现，仅此无法解释水牛背、色素沉着、紫纹等表现。肥胖症（D错）患者可有高血压、糖耐量减低、月经少或闭经，腹部可有条纹，但条纹大多数为白色，有时可为淡红色，基本不表现为水牛背、色素沉着，可根据血皮质醇水平及节律测定鉴别。","c233","N"],["2026-N89",60,"第一节 库欣综合征","库欣综合征诊断依据",2026,89,"A","","女性，27岁。2年来体重增加20Kg，半年来月经仅来潮两次就诊。一个月前体检发现空腹血糖6.5mmol/L。查体：身高158cm，体重75Kg，BP145/90mmHg，水牛背，后颈部皮肤可见色素沉着，双大腿内外侧可见少量紫纹。为明确诊断最具有价值的检查的是",[["A","口服葡萄糖耐量试验"],["B","性激素水平测定"],["C","24小时动态血压监测"],["D","血皮质醇水平及节律测定"]],"D","青年女性患者，2年体重增加20kg（肥胖），半年月经仅两次（月经失调），空腹血糖6.5mmol/L（正常值3.9～6.1mmol/L，提示糖耐量异常），查体显示血压145/90mmHg（正常值90～139/60～89mmHg，提示高血压），查体：身高158cm，体重75Kg（BMI30，提示肥胖），水牛背、后颈部色素沉着、双大腿内外侧紫纹（Cushing综合征临床表现）。根据患者病史、临床表现、查体、实验室检查等，该患者最可能的诊断是Cushing综合征。为明确诊断最具有价值的检查是血皮质醇水平及节律测定（D对），Cushing综合征表现为皮质醇分泌增多，失去昼夜分泌节律，且不能被小剂量地塞米松抑制。口服葡萄糖耐量试验（A错）无法直接诊断库欣综合征，仅为辅助诊断。性激素水平测定（B错）可用于月经失调的鉴别诊断。24小时动态血压监测（C错）可诊断高血压病分级，但无法直接诊断库欣综合征。","c233","N"],["2026-N90",60,"第一节 库欣综合征","库欣综合征病因诊断",2026,90,"A","","女性，27岁。2年来体重增加20Kg，半年来月经仅来潮两次就诊。一个月前体检发现空腹血糖6.5mmol/L。查体：身高158cm，体重75Kg，BP145/90mmHg，水牛背，后颈部皮肤可见色素沉着，双大腿内外侧可见少量紫纹。为明确诊断首选的影像学检查是",[["A","胰腺CT"],["B","超声心动图"],["C","肾上腺CT"],["D","双肾及肾血管B超"]],"C","青年女性患者，2年体重增加20kg（肥胖），半年月经仅两次（月经失调），空腹血糖6.5mmol/L（正常值3.9～6.1mmol/L，提示糖耐量异常），查体显示血压145/90mmHg（正常值90～139/60～89mmHg，提示高血压），查体：身高158cm，体重75Kg（BMI30，提示肥胖），水牛背、后颈部色素沉着、双大腿内外侧紫纹（Cushing综合征临床表现）。根据患者病史、临床表现、查体、实验室检查等，该患者最可能的诊断是Cushing综合征。为明确诊断首选的影像学检查是垂体MRI、肾上腺CT（C对），可以鉴别不同病因的库欣综合征，通过明确病变部位决定后续治疗方案。胰腺CT（A错）适用于诊断胰腺疾病。超声心动图（B错）适用于心脏结构评估。双肾及肾血管B超（D错）适用于肾脏或肾脏血管性疾病筛查。","c233","N"],["2026-N91",71,"第五节 ANCA相关血管炎","ANCA相关血管炎诊断与鉴别诊断",2026,91,"A","","男性，50岁。不规则发热、疲乏、关节肌肉疼痛1个月，伴咳嗽1周。体检：T37.9℃，双下肺可闻及少量细湿啰音，关节无红肿。尿检：蛋白（++），沉渣镜检RBC40～50个/HPF，可见红细胞管型。血pANCA（+），胸部CT可见肺间质改变。该患者最可能的诊断是",[["A","肉芽肿性多血管炎"],["B","系统性红斑狼疮"],["C","显微镜下多血管炎"],["D","类风湿关节炎"]],"C","中年男性患者，不规则发热、疲乏、关节肌肉疼痛1个月，双下肺闻及少量细湿啰音，胸部CT示肺间质改变（符合显微镜下多血管炎临床表现），尿蛋白（++）（提示蛋白尿），尿沉渣镜检RBC40～50个/HPF（正常0～3个/HPF），可见红细胞管型（符合显微镜下多血管炎实验室检查），血pANCA阳性（抗中性粒细胞胞质抗体阳性）。根据患者病史、临床表现、实验室检查等，该患者最可能的诊断是显微镜下多血管炎（MPA）（C对）。肉芽肿性多血管炎（GPA）（A错）表现为C-ANCA阳性及肉芽肿病变。系统性红斑狼疮（B错）多表现为抗核抗体阳性、皮疹或关节症状，ANCA为阴性。类风湿关节炎（D错）以对称性关节炎、类风湿因子阳性为主。","c234","N"],["2026-N92",71,"第一节 系统性血管炎概论","病理",2026,92,"A","","男性，50岁。不规则发热、疲乏、关节肌肉疼痛1个月，伴咳嗽1周。体检：T37.9℃，双下肺可闻及少量细湿啰音，关节无红肿。尿检：蛋白（++），沉渣镜检RBC40～50个/HPF，可见红细胞管型。血pANCA（+），胸部CT可见肺间质改变。对确诊最有意义的检查是",[["A","血类风湿因子"],["B","肾活检"],["C","肾血管造影"],["D","血抗核抗体"]],"B","中年男性患者，不规则发热、乏力、关节肌肉疼痛1个月，双下肺闻及少量细湿啰音，胸部CT示肺间质改变（符合显微镜下多血管炎临床表现），尿蛋白（++）（提示蛋白尿），尿沉渣镜检RBC40～50个/HPF（正常0～3个/HPF），可见红细胞管型（符合显微镜下多血管炎实验室检查），血pANCA阳性（抗中性粒细胞胞质抗体阳性）。根据患者病史、临床表现、实验室检查等，该患者最可能的诊断是显微镜下多血管炎（MPA）。对确诊最有意义的检查是肾活检（B对），活检是确诊血管炎的金标准，还可协助分型、指导治疗。血类风湿因子（A错）可用于类风湿关节炎诊断。肾血管造影（C错）是诊断大、中血管炎的重要依据，也是了解病变范围最确切、可靠的方法，但MPA主要累及小血管，诊断金标准为活检。血抗核抗体（D错）可用于诊断系统性红斑狼疮等结缔组织病。","c234","N"],["2026-N128",7,"第一节 肺癌","肺癌的药物治疗",2026,128,"B","","以EGFR突变阳性为靶点，进行靶向治疗的最常见的肺癌类型是",[["A","肺腺癌"],["B","肺鳞状细胞癌"],["C","小细胞肺癌"],["D","肺大细胞癌"]],"A","以EGFR（表皮生长因子受体）突变阳性为靶点，进行靶向治疗的最常见的肺癌类型是肺腺癌（A对），EGFR突变在非小细胞肺癌中常见（C错），而在肺腺癌中突变的频率更高（BC错）。","","N"],["2026-N129",7,"第一节 肺癌","小细胞肺癌",2026,129,"B","","可导致类癌综合征的最常见肺癌类型是",[["A","肺腺癌"],["B","肺鳞状细胞癌"],["C","小细胞肺癌"],["D","肺大细胞癌"]],"C","类癌综合征指由类癌细胞分泌多种血管活性物质，如5-羟色胺等，表现为喘息、皮肤潮红、水样腹泻、阵发性心动过速等。最新内科学教材中提到：类癌综合征多见于SCLC（小细胞肺癌）和腺癌。小细胞肺癌包括：典型类癌、不典型类癌、小细胞癌和大细胞神经内分泌癌，小细胞癌起源于支气管黏膜的Kulchitsky细胞（神经内分泌细胞）；而肺腺癌主要起源于支气管黏膜上皮细胞和肺泡上皮细胞，这些细胞在正常情况下负责分泌黏液、气体交换等功能，仅少数病例因异常分化获得分泌功能，所以可导致类癌综合征的最常见肺癌类型是小细胞癌（C对），而不是肺腺癌（A错）。肺鳞状细胞癌（B错）和肺大细胞癌（D错）均属于非小细胞肺癌，缺乏神经内分泌分化特征。","","N"],["2026-N130",37,"第一节 急性胰腺炎","急性胰腺炎诊断",2026,130,"B","","器官衰竭后48小时恢复和（或）有无菌性胰腺坏死的急性胰腺炎",[["A","轻症急性胰腺炎"],["B","中度重症急性胰腺炎"],["C","重症急性胰腺炎"],["D","危重急性胰腺炎"]],"B","器官衰竭后48小时恢复和（或）有无菌性胰腺坏死的急性胰腺炎属于中度重症急性胰腺炎（B对）。轻症急性胰腺炎（A错）无器官衰竭和胰腺坏死；重症急性胰腺炎（C错）表现为器官衰竭＞48小时或有感染性胰腺坏死；危重急性胰腺炎（D错）表现为器官衰竭＞48小时和伴有感染性胰腺坏死。","","N"],["2026-N131",37,"第一节 急性胰腺炎","急性胰腺炎诊断",2026,131,"B","","器官衰竭后48小时不恢复和感染性胰腺坏死的急性胰腺炎",[["A","轻症急性胰腺炎"],["B","中度重症急性胰腺炎"],["C","重症急性胰腺炎"],["D","危重急性胰腺炎"]],"D","器官衰竭后48小时不恢复和感染性胰腺坏死的急性胰腺炎属于危重急性胰腺炎（D对）。轻症急性胰腺炎（A错）无器官衰竭和胰腺坏死；中度重症急性胰腺炎（B错）表现为器官衰竭后≤48小时内恢复和（或）有无菌性胰腺坏死的急性胰腺炎；重症急性胰腺炎（C错）表现为器官衰竭＞48小时或有感染性胰腺坏死。","","N"],["2026-N154",3,"第一节 支气管扩张症","控制感染",2026,154,"X","","男性，72岁，反复咳黄绿色浓痰、咯血30余年。近2年来加重，每年需住院4次。再发伴发热5天来诊。查体：T 38℃，双侧中下肺可闻及湿啰音，胸部CT示：双下肺囊样支气管扩张，其内可见气液平。建议使用的抗菌药物有",[["A","头孢他啶"],["B","哌拉西林/他唑巴坦"],["C","头孢曲松"],["D","头孢哌酮/舒巴坦"]],"ABD","老年男性患者，反复咳黄绿色浓痰、咯血30余年（支气管扩张症的典型表现）。近2年来加重，每年需住院4次（铜绿假单胞菌感染高危因素）。再发伴发热5天来诊。查体：T38℃（正常值36～37℃，发热），双侧中下肺可闻及湿啰音，胸部CT示：双下肺囊样支气管扩张，其内可见气液平（支气管扩张症的CT表现）。综合该患者的病史、体查及影像学检查，该患者考虑诊断为支气管扩张症伴急性感染。对于存在铜绿假单胞菌感染高危因素的病人，可选择具有抗假单胞菌活性的β-内酰胺类抗生素，如头孢他啶（A对）、头孢吡肟、哌拉西林/他唑巴坦（B对）、头孢哌酮/舒巴坦（D对），或者碳青霉烯类（如亚胺培南、美罗培南）、氨基糖苷类、喹诺酮类（环丙沙星或左氧氟沙星），可单独应用或联合应用。头孢曲松（C错）适用于无铜绿假单胞菌感染高危因素的病人。","","N"],["2026-N155",15,"第二节 慢性心力衰竭","慢性心力衰竭药物治疗",2026,155,"X","","可改善慢性心力衰竭患者生存预后的治疗药物有",[["A","正性肌力药"],["B","β受体拮抗剂"],["C","血管紧张素转换酶抑制剂"],["D","袢利尿剂"]],"BC","可改善慢性心力衰竭患者生存预后的治疗药物有β受体拮抗剂和血管紧张素转换酶抑制剂。长期应用β受体拮抗剂（B对）治疗能改善HFrEF和HFmrEF病人左心室功能，降低死亡率和住院率，显著降低猝死率。所有病人除非存在禁忌，均推荐使用。ACEI（C对）对于HFrEF病人，早期足量应用可缓解症状，延缓心衰进展，降低死亡率。所有HFrEF病人除非存在禁忌，均推荐使用。正性肌力药（A错）可短期应用于急性心衰病人，升压、维持重要脏器功能，但对生存率无明显改变。袢利尿剂（D错）主要用于减轻水肿症状，但对生存预后无直接影响。","","N"],["2026-N156",75,"第二节 农药中毒","急性有机磷杀虫药中毒临床表现",2026,156,"X","","下列符合有机磷中毒特点的有",[["A","呕吐物有蒜味"],["B","大小便失禁"],["C","四肢肌纤维颤动"],["D","胆碱酯酶活力升高"]],"ABC","急性有机磷杀虫药中毒是指OPI进入体内抑制乙酰胆碱酯酶活性，引起体内生理效应部位Ach大量蓄积，出现毒蕈碱样、烟碱样和中枢神经系统等中毒症状和体征。全血ChE（胆碱酯酶）活性会出现不同程度降低（D错）。OPI属于有机磷酸酯或硫化磷酸酯类化合物，稍有挥发性，有大蒜臭味，故患者呕吐物有蒜味（A对）。有机磷中毒时可引起毒蕈碱样症状，此时副交感神经末梢过度兴奋，括约肌松弛，表现为大小便失禁（B对）。有机磷中毒时还可引起烟碱样症状，由于Ach在横纹肌神经肌肉接头处蓄积过多，出现肌颤、全身肌强直性痉挛等表现（C对）。","","N"],["2026-N157",40,"第五节 肾病综合征","肾病综合征诊断",2026,157,"X","","下列符合肾病综合征诊断标准的有",[["A","尿蛋白大于3.5g/d"],["B","血清白蛋白低于30g/L"],["C","水肿"],["D","高血压"]],"ABC","肾病综合征是一组以大量蛋白尿（＞3.5g/d）（A对）、低白蛋白血症（血清白蛋白＜30g/L）（B对）、水肿（C对）、高脂血症为基本特征的临床综合征。高血压（D错）可见于肾炎综合征，但不属于肾病综合征的诊断标准。","","N"],["2026-N158",57,"第一节 血友病","血友病实验室检查",2026,158,"X","","APTT延长而PT、TT正常时，缺乏的凝血因子有",[["A","纤维蛋白原"],["B","凝血因子Ⅷ"],["C","凝血因子Ⅸ"],["D","凝血因子Ⅹ"]],"BC","活化部分凝血活酶时间（APTT）是内源凝血系统较为灵敏和最为常用的筛选试验。其延长见于因子Ⅻ、Ⅺ、Ⅸ、Ⅷ、Ⅹ、Ⅴ、Ⅱ、PK（激肽释放酶原）、HMWK（高分子量激肽原）和纤维蛋白原缺乏，尤其多见于因子Ⅷ（B对）、Ⅸ（C对）、Ⅺ缺乏以及它们的抗凝物质增多的情况。PT（凝血酶原时间）正常表明外源性途径正常，凝血因子Ⅹ（D错）正常。凝血酶时间（TT）是指在受检血浆中加入“标准化”凝血酶溶液到开始出现纤维蛋白丝所需的时间，TT正常说明纤维蛋白原功能正常（A错）。","","N"],["2026-N159",61,"第一节 糖尿病","口服降糖药物",2026,159,"X","","下列不使体重增加的降糖药有",[["A","二肽基肽酶-4抑制剂"],["B","噻唑烷二酮类"],["C","二甲双胍类"],["D","磺酰脲类"]],"AC","二肽基肽酶-4（DPP-4）抑制剂（A对）可以增强葡萄糖依赖性胰岛素分泌、减少餐后胰高血糖素分泌，可使HbA1c（糖化血红蛋白）降低0.5%～1.0%，不增加体重。二甲双胍（C对）是T2DM的基础用药，可使HbA1c下降1%～2%，不增加体重。噻唑烷二酮类（B错）的常见副作用有体重增加和水肿，与胰岛素合用会更明显。磺酰脲类（D错）可刺激胰岛β细胞分泌胰岛素，体重增加是其不良反应。","","N"]];
